  AvgDialog_118699_Content_70 = {
    Text = "守密人%sirormadam%，我相信善良的人，都會有好運的庇佑，您這樣的人，一定會有幸福的結局的。"
  },
  AvgDialog_118699_Content_71 = {
    Text = "大%brotherorsister1%，莉莉已經可以讀很多故事書了，等你回來，我們可以拍一個關於大%brotherorsister1%和莉莉的電影嗎？"
  },
  AvgDialog_118699_Content_72 = {
    Text = "凱旋的戰士，理應回到{Male=他的,Female=她的}故鄉。"
