  AvgDialog_118699_Content_74 = {
    Text = "你曾經問過我，我的願望是什麼……現在我終於有了自己的願望，那就是希望你能夠平安回來。"
  },
  AvgDialog_118699_Content_75 = {
    Text = "不講信用的小樹苗，答應過我的新世界裡，可不能沒有你呀……"
  },
  AvgDialog_118699_Content_76 = {
    Text = "我們的族群，不會拋下任何落單的成員。"
