  },
  AvgDialog_118699_Content_78 = {
    Text = "所有喚醒體默念著那個熟悉的名字，一道道精神力螢火般匯入懸浮的銀鑰匙中，銀鑰中央漸漸變得如星辰一樣閃耀。"
  },
  AvgDialog_118699_Content_79 = {
    Text = "波呂克斯與卡斯托爾對視一眼，相對點了點頭，卡斯托爾的身軀刹那間化作一道流光，融入了波呂克斯的胸口。"
  },
  AvgDialog_118699_Content_8 = {
    Text = "但，拉蒙娜小姐最後一瞬那強烈的願望，讓「聖心」對<Yellow:%player%>的感受更加清晰了。"
  },
  AvgDialog_118699_Content_80 = {
    Text = "青綠的光暈流轉在聖心之中，波呂克斯背後，一雙瑰麗的青黑羽翼倏然展開，他伸出手指一點，聖心便與銀鑰的光芒呼應閃爍起來。"
  },
  AvgDialog_118699_Content_82 = {
    Text = "迎著波呂克斯肅穆的目光，拉蒙娜握緊了手中開始發光的玫瑰，那是她與守密人一同約定的信號。"
  },
  AvgDialog_118699_Content_83 = {
    Text = "演練過千百次的精神力循著熟悉的指引漸漸凝聚，她抬起頭凝望著那把銀鑰匙，將心聲與所有人一同投入鑰匙的中央。"
  },
  AvgDialog_118699_Content_84 = {
    Text = "（<Yellow:%player%>，等著我，我這就來接你回家。）"
  },
  AvgDialog_118699_Content_9 = {
    Text = "如果彙集更多強烈指向<Yellow:%player%>的精神力，或許就能更精准地感應到%player%的位置。"
  },
  AvgDialog_118700_Content_1 = {
    Text = "一刹相擁"
  },
  AvgDialog_118700_Content_10 = {
    Text = "周圍的嘈雜消失。在腦海深處，拉蒙娜凝望著那個遙遠的自己。"
  },
  AvgDialog_118700_Content_11 = {
    Text = "你的力量比我強大……或許，這次的任務應該由你去，才會更加穩妥……"
  },
  AvgDialog_118700_Content_12 = {
    Text = "感受到拉蒙娜內心所想，環行·拉蒙娜搖了搖頭，抬起被遮罩的雙眼靜靜望向那道深淵。"
  },
  AvgDialog_118700_Content_13 = {
    Text = "我只是來送行的，在這樣遙遠的維度旅途中，我與你並沒有什麼分別，更何況……"
  },
  AvgDialog_118700_Content_14 = {
    Text = "你才是{Male=他的,Female=她的}搭檔，這是屬於你們的命運，不屬於我。"
  },
  AvgDialog_118700_Content_15 = {
    Text = "去吧，去帶回{Male=他,Female=她}，「拉蒙娜」。"
  },
  AvgDialog_118700_Content_16 = {
    Text = "拉蒙娜握住玫瑰的手猛地攥緊，半晌，她鄭重地點了點頭，在另一個自己的目送下坐進了精神分離儀中。"
  },
  AvgDialog_118700_Content_17 = {
    Text = "肉體的雙目緊閉，另一雙眼緩緩睜開，一道凝實的靈魂脫離了身體，被波呂克斯「聖心」的光輝鍍上一層朦朧如紗的白光。"
  },
  AvgDialog_118700_Content_18 = {
    Text = "在數十道目光的注視下，拉蒙娜回過頭，與戰友們一一對視，背負上了那些沉重的希望。"
  },
  AvgDialog_118700_Content_19 = {
    Text = "在那些思念的指引下，她轉過身，縱身躍入了巨大的漩渦之中。地獄之門一般的入口，轉瞬吞沒了單薄的靈魂。"
  },
  AvgDialog_118700_Content_2 = {
    Text = "高懸的天使降下聖光，等待著將迷途的靈魂送往神的身旁。"
  },
  AvgDialog_118700_Content_3 = {
    Text = "朵爾與拉蒙娜對視一眼，啟動了幾乎覆蓋大半黑池的巨型儀器。池水猛烈的震盪中，巨大的渦旋轟然塌陷，形成一道彷彿要吞噬一切的深淵。"
  },
  AvgDialog_118700_Content_5 = {
    Text = "磅礴的池水彷彿向下流淌進了另一個世界，深不見底的漩渦內，世界的存在開始變得模糊。"
  },
  AvgDialog_118700_Content_6 = {
    Text = "這個世界的邊緣，通往維度空間的入口。"
  },
  AvgDialog_118700_Content_7 = {
    Text = "深淵的背後，{Male=他,Female=她}在等你。"
  },
  AvgDialog_118700_Content_8 = {
    Text = "拉蒙娜點點頭。在將要踏入深淵之前，她忽然停下腳步，望向人群。"
  },
  AvgDialog_118700_Content_9 = {
    Text = "一道虛無的身影，默默站立在祈禱的人群之後。那是深藏於她意識之中、只有她能夠看見的身影。"
  },
  AvgDialog_118701_Content_10 = {
    Text = "霧氣凝聚又消散，一位彌薩格的常客出現在黑池的入口，靜靜站在了人偶身旁，一同遙望「門」前枯坐的身影。"
  },
  AvgDialog_118701_Content_11 = {
    Text = "長期接觸池水，對身體可不太好，你不攔著她一些嗎？"
  },
  AvgDialog_118701_Content_12 = {
    Text = "我給了她基礎的防護裝置，何況身體的損傷我還有辦法治療，心理的損傷就沒那麼容易治療了。"
  },
  AvgDialog_118701_Content_13 = {
    Text = "理性的教授歎了口氣，探究地回過了頭。"
  },
  AvgDialog_118701_Content_14 = {
    Text = "你很少願意來這裡，這次你帶來了什麼？"
  },
  AvgDialog_118701_Content_15 = {
    Text = "啊，一個恰好可以治癒她心靈的好消息。"
  },
  AvgDialog_118701_Content_16 = {
    Text = "搭檔，多虧你的壯舉，最近世界範圍內的融蝕裂隙都少了非常多。"
  },
  AvgDialog_118701_Content_17 = {
    Text = "學校的調查員們都變得清閒了起來，大家每天只用上課考試，彌薩格越來越像一所普通的大學了。"
  },
  AvgDialog_118701_Content_18 = {
    Text = "有人提議要為你建一座雕像，就放在華德校長的旁邊，目前校方還在考慮。"
  },
  AvgDialog_118701_Content_19 = {
    Text = "我遞交了不支持的建議，你明明還在這裡，為什麼要和校長一樣做成雕像。"
  },
  AvgDialog_118701_Content_2 = {
    Text = "卡達斯世界\n守密人葬禮之前"
  },
  AvgDialog_118701_Content_20 = {
    Text = "再說，等你回來的時候，看到巨大的自己站在校長旁邊，一定會尷尬得說不出話。"
  },
  AvgDialog_118701_Content_21 = {
    Text = "你的表情明明這樣安寧，我不相信……你一定是在其他世界迷了路，忘記了怎麼回來……"
  },
  AvgDialog_118701_Content_22 = {
    Text = "你說得沒錯，{Male=他,Female=她}的確進入了其他的維度，一個很遙遠的維度。"
  },
  AvgDialog_118701_Content_23 = {
    Text = "聽到身後突然出現的達芙黛爾的聲音，拉蒙娜近乎失態地站了起來，險些沒剋制住去抓握店主的胳膊。"
  },
  AvgDialog_118701_Content_24 = {
    Text = "您說什麼？您找到{Male=他,Female=她}了？維度……我記得您能夠穿梭維度！"
  },
  AvgDialog_118701_Content_25 = {
    Text = "怎樣才能將{Male=他,Female=她}帶回來？我可以付出任何代價！"
  },
  AvgDialog_118701_Content_26 = {
    Text = "難掩激動地懇求後，拉蒙娜才注意到一旁朵爾並無笑意的面龐。"
  },
  AvgDialog_118701_Content_27 = {
    Text = "……怎麼？"
  },
  AvgDialog_118701_Content_28 = {
    Text = "雖然你的決心很令人感動，但很遺憾，那是一個並未與這個世界相連的維度，況且，我也沒有辦法帶守密人跨越未知的維度空間。"
  },
  AvgDialog_118701_Content_29 = {
    Text = "如果無法找到確定的航線，隨意在維度亂流中穿梭，只有迷失一種結局。"
  },
  AvgDialog_118701_Content_3 = {
    Text = "隨著一聲檢測完畢的嗡鳴，眾多儀器上又一次顯示了毫無反應的結果，朵爾沉默著揮了揮手，研究員們互相對視一眼，默契地開始拆卸儀器。"
  },
  AvgDialog_118701_Content_30 = {
    Text = "以彌薩格現有的技術，也無法做到這一點。"
  },
  AvgDialog_118701_Content_31 = {
    Text = "什麼意思……我們嘗試了這麼久，終於有了{Male=他,Female=她}的消息，難道就要讓{Male=他,Female=她}一個人流落在外嗎？！"
  },
  AvgDialog_118701_Content_32 = {
    Text = "穿梭維度的技巧，我或許還可以與朵爾教授一同商討，就當是免費贈予老顧客的。"
  },
  AvgDialog_118701_Content_33 = {
    Text = "但想要接回<Yellow:%player%>，最難的是如何找到通往那一個世界的路，即使是我的收藏裡，也沒有這樣超脫宇宙的寶物。"
  },
  AvgDialog_118701_Content_34 = {
    Text = "我會讓科研部即日起，全力投入維度方面的研究。"
  },
  AvgDialog_118701_Content_35 = {
    Text = "維度與維度之間，有時永遠也不會出現交集，並非通過窮舉就能找到。"
  },
  AvgDialog_118701_Content_36 = {
    Text = "你們要面臨的，可能是漫長到看不見希望的嘗試。"
  },
  AvgDialog_118701_Content_37 = {
    Text = "我們不會放棄的。"
  },
  AvgDialog_118701_Content_39 = {
    Text = "我知道了，無論多久，我都會等著{Male=他,Female=她}。"
  },
  AvgDialog_118701_Content_4 = {
    Text = "為什麼要收起儀器？再試一次，一定還有沒想到的測試方法……"
  },
  AvgDialog_118701_Content_40 = {
    Text = "卡達斯世界\n守密人葬禮後十個月\n黑池"
  },
  AvgDialog_118701_Content_41 = {
    Text = "空曠的腳步聲穿過層層封鎖的大門，踏入了黏稠的水波，寂靜的黑色池水迎來了今天第二個訪客。"
  },
  AvgDialog_118701_Content_42 = {
    Text = "我就知道你又在這裡。"
  },
  AvgDialog_118701_Content_43 = {
    Text = "教授對話的對象並沒有答覆，一動不動的背影始終朝向著「門」前那個懸浮的身影，像是一座遙望的雕塑。"
  },
  AvgDialog_118701_Content_44 = {
    Text = "今天又有人的建議信投遞到我這裡了，這是你第7次拒絕分配任務搭檔，堅持獨自執行雙人調查任務了吧。"
  },
  AvgDialog_118701_Content_46 = {
    Text = "沒關係，我不是來批評或者命令你的，更不是來勸告你的，雖然茜爾維婭說你的心理評估的確出了一點問題。"
  },
  AvgDialog_118701_Content_47 = {
    Text = "不過這所大學裡的人，又有幾個是完全沒問題的呢？"
  },
  AvgDialog_118701_Content_48 = {
    Text = "粉色的螯足站定在雕塑的身邊，與她一起望向那個始終沉睡的人影。"
  },
  AvgDialog_118701_Content_49 = {
    Text = "有什麼特殊任務需要我執行嗎？"
  },
  AvgDialog_118701_Content_5 = {
    Text = "檢測次數與頻段已經足夠多了，你的銀芯儀器使用課程是滿分，不要再自欺欺人了，拉蒙娜。"
  },
  AvgDialog_118701_Content_50 = {
    Text = "失去反應的雕塑終於開口，語調平靜得像是機器。"
  },
  AvgDialog_118701_Content_52 = {
    Text = "任務要求？"
  },
  AvgDialog_118701_Content_53 = {
    Text = "需要你去一個很危險的地方，接引你的搭檔。"
  },
  AvgDialog_118701_Content_56 = {
    Text = "拉蒙娜猛地轉過頭來，死死盯住人偶無機的雙眼。"
  },
  AvgDialog_118701_Content_57 = {
    Text = "這次的任務是一場賭博，也是前所未有的危險等級，恐怕校內的外援無法與你同行……"
  },
  AvgDialog_118701_Content_58 = {
    Text = "科研部有結果了？什麼時候？"
  },
  AvgDialog_118701_Content_59 = {
    Text = "朵爾笑了笑，將手中新鮮出爐的研究報告遞向對方。"
  },
  AvgDialog_118701_Content_6 = {
    Text = "{Male=他,Female=她}留在這裡的只是一具軀殼，沒有任何生命波動，守密人的意識……可能已經消散了。"
  },
  AvgDialog_118701_Content_60 = {
    Text = "自從達芙黛爾告訴我們守密人的消息，科研部已經將目前所有的技術手段嘗試了一遍，沒想到最後的突破口在喚醒體身上。"
  },
  AvgDialog_118701_Content_61 = {
    Text = "我們發現了波呂克斯的「聖心」可以對那個存在產生吸引，原本提燈教會製造「聖心」就是為了製造純淨的靈魂，傳播神血。"
  },
  AvgDialog_118701_Content_62 = {
    Text = "最終獻祭聖子，召喚所謂的淨土。"
  },
  AvgDialog_118701_Content_63 = {
    Text = "實際上其原理就是通過吸引那一位的注意，從而擴散融蝕。經過定向處理，「聖心」極有可能可以針對性地為我們指引守密人的位置。"
  },
  AvgDialog_118701_Content_64 = {
    Text = "校方計劃將一個精神力優秀的意識送往維度空間，跟隨「聖心」的指引跨越維度、建立連接兩個世界的隧道。"
  },
  AvgDialog_118701_Content_65 = {
    Text = "如果一切測試資料推進順利，不出一個月，就可以開始嘗試了。"
  },
  AvgDialog_118701_Content_66 = {
    Text = "接下來你的任務會增加關於精神力鍛煉的部分，希望你……不要過於勤奮，以免損傷大腦。"
  },
  AvgDialog_118701_Content_67 = {
    Text = "卡達斯世界\n守密人葬禮後一年\n黑池"
  },
  AvgDialog_118701_Content_68 = {
    Text = "極速運轉的精神分離儀發出不堪重負的紅色警報，一旁密切觀察的人偶立刻拍下了終止按鈕。"
  },
  AvgDialog_118701_Content_69 = {
    Text = "裝有使用者的艙門瞬間彈開，已經虛脫的拉蒙娜動了一下手指，被兩邊的研究員快速攙扶了出來。"
  },
  AvgDialog_118701_Content_7 = {
    Text = "殘忍的宣判終於從人偶口中落下，看著拉蒙娜怔愣的眼中流下的淚水，見慣犧牲的教授也不忍地閉上了眼。"
  },
  AvgDialog_118701_Content_70 = {
    Text = "扶著她，快速進入精神冷卻液中！"
  },
  AvgDialog_118701_Content_71 = {
    Text = "淡綠色的池水浸沒胸口，拉蒙娜身上高燒一樣的溫度終於降了下來，那雙曾經理性，現在則顯得偏執的眼睛緩緩睜開。"
  },
  AvgDialog_118701_Content_72 = {
    Text = "即便後天就是第一次正式嘗試的日期，你也不能這樣用身體冒險。"
  },
  AvgDialog_118701_Content_73 = {
    Text = "沒關係，我能承受……"
  },
  AvgDialog_118701_Content_74 = {
    Text = "從一旁的儀器中走出的波呂克斯此時也靜靜來到兩人旁邊，打斷了朵爾更多的叮囑。"
  },
  AvgDialog_118701_Content_75 = {
    Text = "我能理解那種失去重要的人的痛苦，那種對無能為力的自己的痛恨……放心吧，拉蒙娜小姐。"
  },
  AvgDialog_118701_Content_76 = {
    Text = "現在「聖心」已經能感受到那盞明燈的召喚，我跟卡斯托爾會全力以赴，和你一起找回恩人的。"
  },
  AvgDialog_118701_Content_8 = {
    Text = "準備為<Yellow:%player%>舉行葬禮吧，那封遺書……就由你來為{Male=他,Female=她}讀吧。"
  },
  AvgDialog_118701_Content_9 = {
    Text = "卡達斯世界\n守密人葬禮後三個月"
  },
  AvgDialog_118702_Content_1 = {
    Text = "遠方的傳訊"
  },
  AvgDialog_118702_Content_10 = {
    Text = "你像目盲的人一樣揮舞著雙手，拼命邁開步伐，如同涉水而上的旅人，在黏稠的黑暗裡向前跋涉、找尋。"
  },
  AvgDialog_118702_Content_100 = {
    Text = "這裡沒有滾燙的溫度，只有無盡的黏稠的黑暗。向前穿梭的時候，前進與後退都開始模糊，就像存在也變成了虛無。"
  },
  AvgDialog_118702_Content_101 = {
    Text = "繼續向前，不要回頭。"
  },
  AvgDialog_118702_Content_102 = {
    Text = "你信任著那個聲音，努力放空精神，不斷前進著，直到一陣迷幻的色彩使你陷入猛烈的眩暈。"
  },
  AvgDialog_118702_Content_103 = {
    Text = "……這是！"
  },
  AvgDialog_118702_Content_104 = {
    Text = "除了在達芙黛爾的原質之海中，你第一次站在宇宙之外看向世界。"
  },
  AvgDialog_118702_Content_105 = {
    Text = "像是進入了顯微鏡中的微觀世界，膠質般的空間質、無數蠕動的線條、形狀詭異的精神體、極遙遠處閃爍光芒的星系……"
  },
  AvgDialog_118702_Content_106 = {
    Text = "以及沒有盡頭的世界邊界。"
  },
  AvgDialog_118702_Content_107 = {
    Text = "如果沒有足夠的精神錨點，在這樣混亂而無垠的空間中很快就會迷失，但你的心中並沒有多少畏懼。"
  },
  AvgDialog_118702_Content_108 = {
    Text = "準備好了嗎，你開始連結之後，我會盡可能製造些動靜吸引祂，剩下的，就是你的戰鬥了。"
  },
  AvgDialog_118702_Content_109 = {
    Text = "你握緊了胸前的銀鑰匙，鄭重而眷戀地將精神的觸角伸向手中那朵盛放的玫瑰。"
  },
  AvgDialog_118702_Content_11 = {
    Text = "終於……找到你了！我們@3……通過@2隧道……"
  },
  AvgDialog_118702_Content_110 = {
    Text = "開始吧。"
  },
  AvgDialog_118702_Content_111 = {
    Text = "盛大的精神力波動在維度空間內轟然炸響，在你的精神觸角感知的極限中，一道突兀出現的裂口割開了空間。"
  },
  AvgDialog_118702_Content_112 = {
