  },
  AvgDialog_121744_Content_3 = {
    Text = "一道閃電劃破了漆黑的夜空，嗜血的巨刃伴隨著迅疾的紫黑電光，狠狠斬向蒼白纖弱的帷幕之肢。"
  },
  AvgDialog_121744_Content_4 = {
    Text = "……彌利亞姆？戈利亞？你們為什麼會出現在這裡？"
  },
  AvgDialog_121744_Content_5 = {
    Text = "神母決意已定，我等自當代神母斬斷這重無妄的「帷幕」。"
  },
  AvgDialog_121744_Content_6 = {
    Text = "彌利亞姆……"
  },
  AvgDialog_121744_Content_7 = {
    Text = "安心吧，神母大人。無論您今後作何打算，蹈海者都是您身後最穩固堅牢的基石。"
  },
  AvgDialog_121744_Content_8 = {
    Text = "別囉嗦了，難道我們要眼睜睜看著你們兩個小不點對抗這傢伙？"
  },
  AvgDialog_121744_Content_9 = {
    Text = "熟悉的聲音突然出現，打斷了墨菲的話。是戈利亞和凱刻斯。"
  },
  AvgDialog_121745_Content_1 = {
    Text = "聳立的怪物高昂地抬起頭，自黯淡的帷幕之後，「凝視」你們所有人。"
  },
  AvgDialog_121745_Content_10 = {
    Text = "請你和那個我一樣……永遠葬身於無垠的深海中吧！"
  },
  AvgDialog_121745_Content_3 = {
    Text = "某種無形的連結真實地貫穿在她和祂之間，不可迴避，令少女看到了祂的創傷，祂的啜泣，乃至祂的疑惑……"
  },
  AvgDialog_121745_Content_4 = {
    Text = "就像一個被傷害的嬰孩，質問著母親的「背叛」。"
  },
  AvgDialog_121745_Content_5 = {
    Text = "別看我，別審問我……我已經下定決心。這是我的最後一次「背叛」。"
  },
  AvgDialog_121745_Content_6 = {
    Text = "曾經的我，向「樂園」許下願望，一場我幼年時渴求的「幻夢」。"
  },
  AvgDialog_121745_Content_7 = {
    Text = "我以為「權柄」能為我換來「幸福」，但這終究只是虛妄的幻夢……"
  },
  AvgDialog_121745_Content_8 = {
    Text = "墨菲笑著擦乾眼角落下的淚。她慢慢地、細緻地擦著，直到最後一抹淚痕也消失殆盡，她仰起頭，注視著那個龐大的「自己」。"
  },
  AvgDialog_121745_Content_9 = {
    Text = "我不需要樂園，不需要欺騙自己的美夢。不再需要了。"
  },
  AvgDialog_121858_Content_1 = {
    Text = "自祂的腳下溢出萬千怪物，而你們將之一一斬殺。\n踏著萬千屍骸，你們抵達了巨大輪廓的腳下。"
  },
  AvgDialog_121858_Content_10 = {
    Text = "這一次，我不會容許再用任何人的生命換取勝利。"
  },
  AvgDialog_121858_Content_11 = {
    Text = "準備迎戰吧，終將凋零的「帷幕」！"
  },
  AvgDialog_121858_Content_2 = {
    Text = "這就是我的意志，「樂園」的意志……"
  },
  AvgDialog_121858_Content_3 = {
    Text = "「孩子」向來不從屬於「母親」，誕生之後的祂，也產生了自身的「願望」。"
  },
  AvgDialog_121858_Content_4 = {
    Text = "<Red:夢……必須……延續……>"
  },
  AvgDialog_121858_Content_5 = {
    Text = "你曾經說過，只要殺死夢的掌控者，將權柄移交給你……"
  },
  AvgDialog_121858_Content_6 = {
    Text = "是的。你已經做出覺悟了嗎？"
  },
  AvgDialog_121858_Content_7 = {
    Text = "不，她不必做這樣的犧牲。"
  },
  AvgDialog_121858_Content_9 = {
    Text = "密境的「核」，顯現的「災厄」，這種規模的，我已經不記得自己迎戰過多少次了。"
  },
  AvgDialog_121859_Content_1 = {
    Text = "祂施加在帷幕內的力量……在變化……"
  },
  AvgDialog_121859_Content_2 = {
    Text = "被割捨，被遺棄……祂在不甘，在憤怒，在哀歎……"
  },
  AvgDialog_121859_Content_3 = {
    Text = "祂的怨憤，將傾瀉於爾等之身……！"
  },
  AvgDialog_121864_Content_1 = {
    Text = "很意外嗎？因為神諭在呼喚我，在帷幕之外……"
  },
  AvgDialog_121865_Content_1 = {
    Text = "我的血脈正在鼓動，海淵正齊唱著向我發出邀請！"
  },
  AvgDialog_121866_Content_1 = {
    Text = "遠方的神明啊，您虔誠的侍者，將為您獻上一份綿薄之力……"
  },
  AvgDialog_121867_Content_1 = {
    Text = "幸運的傢伙，這就讓你見識一下非利士人的力量！"
  },
  AvgDialog_122640_Content_1 = {
    Text = "<Shake:轟！——>"
  },
  AvgDialog_122640_Content_2 = {
    Text = "瘋狂的目光讓整個維度開始顫抖，拉蒙娜與你的連結被融蝕遮蔽，不見蹤影。"
  },
  AvgDialog_122640_Content_3 = {
    Text = "你深吸一口氣，強行壓下心中那股因瘋狂而產生的狂躁。"
  },
  AvgDialog_122640_Content_4 = {
    Text = "把這些瘋狂留給自己吧……<Big:我不會讓你的這些瘋狂，再傷害到任何人！>"
  },
  AvgDialog_122641_Content_2 = {
    Text = "熟悉的威壓。熟悉的目光。熟悉的幾乎將你大腦撕裂的疼痛。"
  },
  AvgDialog_122641_Content_3 = {
    Text = "呵……又見面了，託乎瓦波，至高的神明……雖然你無法聽見，但是我得感謝你。"
  },
  AvgDialog_122641_Content_4 = {
    Text = "你曾讓我死過一次，在這次死亡裡，我領悟到了一個至理……"
  },
  AvgDialog_122641_Content_5 = {
    Text = "你緊握銀鑰，直視著祂的意志投下的目光。甚至連你自己都沒有發現，你的嘴角帶著一抹微笑。"
  },
  AvgDialog_122641_Content_6 = {
    Text = "你讓我知道，在你這個宏偉的夢境裡，沒有任何事情不可改變，沒有任何事物不可戰勝。"
  },
  AvgDialog_122641_Content_7 = {
    Text = "為了再次相見，我們已經等待了許久……即便是你，也休想擋住我們的路！"
  },
  AvgDialog_122642_Content_2 = {
    Text = "強烈的衝擊讓整個維度開始破碎。你睜開發紅的眼，望向那個越來越接近實體的眼瞳。"
  },
  AvgDialog_122642_Content_3 = {
    Text = "你的意識也已經到極限了，託乎瓦波……現在，繼續安睡吧！"
  },
  AvgDialog_122642_Content_4 = {
    Text = "你振奮起幾乎枯竭的精神，將最後的精神力量灌入銀鑰。"
  },
  AvgDialog_122642_Content_5 = {
    Text = "你手握銀光如同利刃，向身前的神明刺去——"
  },
  AvgDialog_122643_Content_2 = {
    Text = "熟悉的身影被目光帶來的融蝕吞沒，古老、邪惡的咒文在這道目光中若隱若現。"
  },
  AvgDialog_122643_Content_3 = {
    Text = "這些吟誦到此為止了……！"
  },
  AvgDialog_122644_Content_1 = {
    Text = "世界在你面前崩塌、重建，至親在你面前死去、復生。那道迷亂的目光，將宇宙一切的混亂帶到你的精神之中。"
  },
  AvgDialog_122644_Content_2 = {
    Text = "無序，迷亂，困惑……你的權柄帶來的，依然是這些東西。"
  },
  AvgDialog_122644_Content_3 = {
    Text = "你的目光從未迷惑我，託乎瓦波。曾經如此，現今亦然。"
  },
  AvgDialog_122644_Content_4 = {
    Text = "銀光閃耀。在那些無盡的幻象之中，你找到了那條與它對決的道路——"
  },
  AvgDialog_122645_Content_1 = {
    Text = "遙遠的維度中，一顆光點正在微微閃爍。"
  },
  AvgDialog_122645_Content_2 = {
    Text = "那是……波呂克斯的「聖心」？"
  },
  AvgDialog_122645_Content_3 = {
    Text = "他們的尋找也已經開始了……他們現在，一定也處在危險之中。"
  },
  AvgDialog_122645_Content_4 = {
    Text = "我還記得第一次面對你時的恐懼，託乎瓦波。這一次，我不會讓他們久等的！"
  },
  AvgDialog_122646_Content_1 = {
    Text = "強烈的刺痛襲向你的每一根骨頭、每一寸血肉。你忍受著這鑽心的痛苦，艱難地笑起來。"
  },
  AvgDialog_122646_Content_2 = {
    Text = "癡愚的神明，你不知道，在你的夢境裡，有許多痛苦遠遠超越了肉體……"
  },
  AvgDialog_122646_Content_3 = {
    Text = "那樣的痛苦，我不會讓它再出現的！"
  },
  AvgDialog_122694_Content_1 = {
    Text = "走廊中段的房門已經蒙上了白霜，甚至有向外擴散的趨勢。"
  },
  AvgDialog_122694_Content_10 = {
    Text = "求求你，守密人，抱抱我吧，一點點，只要一點點溫暖就好～仙女會永遠記得你的恩情。"
  },
  AvgDialog_122694_Content_11 = {
    Text = "這是你第一次看見眼前的小騙子露出這種表情，但殘存的警惕心還是讓你呵著白氣站在原地活動身體。"
  },
  AvgDialog_122694_Content_12 = {
    Text = "我已經通知了校務處，他們很快就會來幫忙，你且站在這裡不要走動，什麼都不要做。"
  },
  AvgDialog_122694_Content_13 = {
    Text = "可是我現在好難受，那條河的力量把我帶回了那個蒼白……寒冷的……可怕的地方……"
  },
  AvgDialog_122694_Content_14 = {
    Text = "毫無徵兆地，卡拉布的眼淚直直墜落了下來，彷彿真的目睹到了什麼可怕的事情。"
  },
  AvgDialog_122694_Content_15 = {
    Text = "我可能等不到幫助了，守密人，抱歉之前總是對你撒謊……"
  },
  AvgDialog_122694_Content_16 = {
    Text = "結晶正在以她為圓心向外蔓延，她看上去無助而易碎，眼眶通紅地看著你、似乎搖搖欲墜地隨時會摔倒。"
  },
  AvgDialog_122694_Content_18 = {
    Text = "在她倒地的前一瞬間，你終究還是撲過去扶住了她，但下一秒，你就後悔了。"
  },
  AvgDialog_122694_Content_19 = {
    Text = "那雙冰涼的胳膊像某種無脊椎生物般，靈活地纏上了你，帶著雪花結晶的吐息隨之撲進你的頸窩與耳廓。"
  },
  AvgDialog_122694_Content_2 = {
    Text = "你硬著頭皮，頂住抖得差點讓你咬舌自盡的寒冷，推開了卡拉布的宿舍門。"
  },
  AvgDialog_122694_Content_20 = {
    Text = "嘻嘻～唉呀，果然，%player%還是這麼心軟。"
  },
  AvgDialog_122694_Content_21 = {
    Text = "在她背後，有什麼更加柔軟又冰冷的東西，緊密而溫吞地將你溺沒進層層深雪。"
  },
  AvgDialog_122694_Content_22 = {
    Text = "你唔唔掙扎著，在徹底失去意識前，聽到了那抹狡猾純白的嬉笑。"
  },
  AvgDialog_122694_Content_23 = {
    Text = "沒事的，本仙女會非常，非常溫柔地對待我最重要的小羊羔哦~"
  },
  AvgDialog_122694_Content_3 = {
    Text = "卡拉布，你又做了什、嘶，這也太冷了。*抖抖"
  },
  AvgDialog_122694_Content_4 = {
    Text = "然而那個古靈精怪的身影，居然沒有一如既往用某種亮閃閃的方式出現，向你炫耀她的惡作劇。"
  },
  AvgDialog_122694_Content_5 = {
    Text = "她的臉上罕見地浮現出一層紅暈，甚至稱得上，呃，楚楚可憐。"
  },
  AvgDialog_122694_Content_6 = {
    Text = "守密人，怎麼辦～卡拉布覺得好奇怪，身體好奇怪，腦子也好奇怪。"
  },
  AvgDialog_122694_Content_7 = {
    Text = "卡拉布好冷，幾乎快要被凍死在這裡了。"
  },
  AvgDialog_122694_Content_8 = {
    Text = "卡拉布又好熱，熱得腿都在發軟，一步都邁不開。"
  },
  AvgDialog_122694_Content_9 = {
    Text = "她咬住下唇，淚眼汪汪地衝你張開雙臂，擺出一個索要擁抱的姿勢。"
  },
  AvgDialog_122696_Content_1 = {
    Text = "空洞的殿堂中，只有你和墨菲的腳步迴響。"
  },
  AvgDialog_122697_Content_1 = {
    Text = "今日的天比平時暗得更快，且陰沉沉的，顯然要下雨。"
  },
  AvgDialog_122697_Content_10 = {
    Text = "茉夏抬起了頭，染著不正常紅暈的臉上，露出一種混雜著困惑和狂熱的笑容。"
  },
  AvgDialog_122697_Content_11 = {
    Text = "和我戰鬥，立刻，馬上！"
  },
  AvgDialog_122697_Content_13 = {
    Text = "未等你回答，茉夏的斧子就已經襲來，輕巧且有分寸地擦過你的臉頰，掀起一陣冰冷的風。"
  },
  AvgDialog_122697_Content_14 = {
    Text = "那風未經允許就擅自闖入你的衣領，再灌入你的胸膛，令你的身體本能地泛起雞皮疙瘩。"
  },
  AvgDialog_122697_Content_15 = {
    Text = "怎麼一言不合就打起來了！？"
  },
  AvgDialog_122697_Content_16 = {
    Text = "你的質問被斧子和斧子的主人忽略了。"
  },
  AvgDialog_122697_Content_19 = {
    Text = "在你的連續追問下，斧子終於停了。它貼著你的肩膀，深深楔入牆壁。"
  },
  AvgDialog_122697_Content_2 = {
    Text = "為了避免淋濕的命運，你急匆匆跑向宿舍，卻被一個人影攔住了去路。"
  },
  AvgDialog_122697_Content_20 = {
    Text = "而斧子的主人，就站在你眼前，面色潮紅，握緊拳頭，用力拽住了你的衣領。"
  },
  AvgDialog_122697_Content_21 = {
    Text = "<Shake:別吵……我現在很難受，只有和你戰鬥才能好受一些……>"
  },
  AvgDialog_122697_Content_22 = {
    Text = "抓住你衣領的手指繼續用力，從肉色變為蒼白，昭示著主人的倔強與不甘。"
  },
  AvgDialog_122697_Content_23 = {
    Text = "我最討厭別人將想法強加在他人身上……"
  },
  AvgDialog_122697_Content_24 = {
    Text = "區區聖河而已，就想影響我？<Shake:未免……太小瞧我了。>"
  },
  AvgDialog_122697_Content_25 = {
    Text = "茉夏說著用力吐氣，以此平復聖河對她的影響，但你能感覺到她體內奔湧的熱度，流竄的渴望，和掙扎的衝突。"
  },
  AvgDialog_122697_Content_26 = {
    Text = "察覺到茉夏的情緒，你不由得嘆了口氣，拉住她的手，引導少女重新握住了斧柄。"
  },
  AvgDialog_122697_Content_27 = {
    Text = "<Shake:你做什麼？>"
  },
  AvgDialog_122697_Content_28 = {
    Text = "不是想要戰鬥嗎？那就戰鬥。"
  },
  AvgDialog_122697_Content_29 = {
    Text = "無論你想要以什麼方式戰鬥，無論你想要戰鬥到什麼時候，我都奉陪到底。"
  },
  AvgDialog_122697_Content_3 = {
    Text = "茉夏？有什麼事嗎？"
  },
  AvgDialog_122697_Content_31 = {
    Text = "少女的眼睛驟然瞪大，意外地看著你。"
  },
  AvgDialog_122697_Content_32 = {
    Text = "這時候，那場預謀已久的雨終於落下，有雨滴落在茉夏的臉上，從她的下巴滑落，再沒入你的衣領，順著你的胸膛流淌而下。"
  },
  AvgDialog_122697_Content_33 = {
    Text = "隨後，是更多的雨滴，狂野地敲擊著地面，拍打著你和少女的臉頰，帶來一些癢意。"
  },
  AvgDialog_122697_Content_34 = {
    Text = "<Shake:哈哈哈哈，我喜歡你的回答。>"
  },
  AvgDialog_122697_Content_35 = {
    Text = "事情開始變得有意思起來了，不是嗎？"
  },
  AvgDialog_122697_Content_36 = {
    Text = "茉夏握住斧柄，將斧頭從牆壁抽回來，但她並沒有再揮動斧頭，而是望向你，直視你。"
  },
  AvgDialog_122697_Content_37 = {
    Text = "通常，我不會和人空手格鬥，但有時候也要嘗試一下新事物，對不對？"
  },
  AvgDialog_122697_Content_38 = {
    Text = "人生這麼長，一些有趣的事情，可要親自、慢慢地體會。"
  },
  AvgDialog_122697_Content_39 = {
    Text = "茉夏說著，慢慢走向你。而那柄斧頭，也靜靜倚在牆壁，接受著世界濕漉漉的洗禮。"
  },
  AvgDialog_122697_Content_4 = {
    Text = "茉夏低著頭，沒有回答，你也只能從她用力握緊斧頭而發白的手指上，察覺到少女並不平靜的心情。"
  },
  AvgDialog_122697_Content_6 = {
    Text = "終於，少女開口了，聲音卻帶著一絲遲疑和不確定。"
  },
  AvgDialog_122697_Content_7 = {
    Text = "%player%，我、我需要你的幫助……"
  },
  AvgDialog_122697_Content_8 = {
    Text = "幫助？沒問題。你需要什麼？"
  },
  AvgDialog_122700_Content_1 = {
    Text = "歡迎來到我的劇院。您到的很準時，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_122700_Content_10 = {
    Text = "繁衍……新生……難道你也？！"
  },
  AvgDialog_122700_Content_11 = {
