  },
  AvgDialog_123119_Content_41 = {
    Text = "睜開眼後，茉夏沒有聽見笛聲，也沒有看見什麼樂手。周遭光怪陸離，只有大片大片的光斑環繞著她，保持著不近不遠的距離。"
  },
  AvgDialog_123119_Content_42 = {
    Text = "很高興見到你，茉夏，「我」的朋友。"
  },
  AvgDialog_123119_Content_43 = {
    Text = "光斑發出了嗡鳴，弔詭的是，她完全能夠理解。\n或者說，她此刻也是光斑。"
  },
  AvgDialog_123119_Content_44 = {
    Text = "我這是陣亡了？原來陣亡是這種感覺啊……"
  },
  AvgDialog_123119_Content_45 = {
    Text = "不，你還活著。你只是被我帶到了這裡。你身上有「我」的氣息。"
  },
  AvgDialog_123119_Content_46 = {
    Text = "若是我不這麼做，你會因失敗的維度跨越遭受@4，因為你已經被@3。"
  },
  AvgDialog_123119_Content_47 = {
    Text = "茉夏沒有聽到光斑最後的話語，因為那混沌的音節響起的刹那，她的頭就劇烈疼痛起來，幾欲裂開。"
  },
  AvgDialog_123119_Content_48 = {
    Text = "<Shake:停！停！說點我能聽的……再這樣下去，我的頭要炸了。>"
  },
  AvgDialog_123119_Content_49 = {
    Text = "她似乎聽到了光斑的歎息，又或許沒有，因為無數奇怪的資訊灌入了茉夏的腦海，吸引了她全部的注意力。"
  },
  AvgDialog_123119_Content_5 = {
    Text = "孩子，你不了解其中的危險性，精神維度的創傷同樣會影響現實世界，你會……"
  },
  AvgDialog_123119_Content_50 = {
    Text = "這是什麼？"
  },
  AvgDialog_123119_Content_51 = {
    Text = "你們此刻需要的。展示給「我」，%heorshe%會明白的。"
  },
  AvgDialog_123119_Content_52 = {
    Text = "什麼我、你的，聽不懂——"
  },
  AvgDialog_123119_Content_54 = {
    Text = "這不可能，我剛剛才看到你活蹦亂跳的，看起來再活100年完全沒問題。"
  },
  AvgDialog_123119_Content_55 = {
    Text = "光斑嗡鳴著，發出一聲輕笑，茉夏不知道這是否能被稱為「笑」，因為它沒有喜悅。準確來說，沒有任何情緒。"
  },
  AvgDialog_123119_Content_56 = {
    Text = "你可以理解為那是另一個維度的「我」，而我，真正的我——"
  },
  AvgDialog_123119_Content_57 = {
    Text = "隨著光斑的話語，又有無數資訊湧入了茉夏的腦海。這些資訊不斷分裂、聚合，形成了不穩定的畫面。"
  },
  AvgDialog_123119_Content_58 = {
    Text = "起初，這些畫面抽象斑駁，模糊不定，但很快——"
  },
  AvgDialog_123119_Content_59 = {
    Text = "那些古怪的光影就凝聚成了一個身影，一個她熟悉的身影。"
  },
  AvgDialog_123119_Content_6 = {
    Text = "這裡只有我合適。我雖然頭腦簡單些，但不傻。"
  },
  AvgDialog_123119_Content_60 = {
    Text = "那熟悉的身影在一片爆炸中醒來，懵懂地注視著這個世界。"
  },
  AvgDialog_123119_Content_61 = {
    Text = "許多年後，人們將這次爆炸，稱為「阿庫特爆炸」。"
  },
  AvgDialog_123119_Content_62 = {
    Text = "隨後，%heorshe%進入了彌薩格，獲得銀鑰匙，成為了「守密人」，開始與稱為「喚醒體」的同伴們出任務，調查這個詭異而恐怖的世界。"
  },
  AvgDialog_123119_Content_63 = {
    Text = "就像她和調查官、霧境調查團那樣。"
  },
  AvgDialog_123119_Content_65 = {
    Text = "回憶到那些熟悉的人和過去，茉夏懷念地歎息。而關於%player%的一生，仍在繼續——"
  },
  AvgDialog_123119_Content_66 = {
    Text = "她看到%player%穿行過冰天雪地的小鎮，在滿是秘密的療養院裡，直面穿越時空的獵犬，見證親情的永恆。"
  },
  AvgDialog_123119_Content_67 = {
    Text = "也追隨%player%遊覽過開滿詩與花的西岱，聆聽烈火的歎息，哀痛於玫瑰的凋零。"
  },
  AvgDialog_123119_Content_68 = {
    Text = "還有飄零在海上的幽靈船。信仰、神明、獻祭，她同%player%一起，認知了這世界的扭曲、殘酷與瘋狂。"
  },
  AvgDialog_123119_Content_69 = {
    Text = "但無論是怎樣危險的地方，都沒有打倒%player%，和%heorshe%的同伴。"
  },
  AvgDialog_123119_Content_7 = {
    Text = "茉夏出聲打斷薩爾瓦多的話，神色認真地看著你們。"
  },
  AvgDialog_123119_Content_70 = {
    Text = "就像在那個世界，霧災、灰骸、古物也打不倒她和調查官，打不倒霧境調查團一樣。"
  },
  AvgDialog_123119_Content_71 = {
    Text = "這還差不多！"
  },
  AvgDialog_123119_Content_72 = {
    Text = "也不知道那些霧裡的小傢伙們現在怎麼樣了？"
  },
  AvgDialog_123119_Content_73 = {
    Text = "唉，真的好想喝杯熱騰騰的榛果卡瓦茶啊！"
  },
  AvgDialog_123119_Content_74 = {
    Text = "茉夏笑起來。\n她以為%player%會和喚醒體們永遠戰鬥下去——"
  },
  AvgDialog_123119_Content_75 = {
    Text = "理所當然是這樣的，因為她從未想過要離開霧境調查團，那些喚醒體，自然也不會想離開守密人。"
  },
  AvgDialog_123119_Content_76 = {
    Text = "他們會戰鬥、戰鬥，直到解決世界的麻煩，或者被世界所解決。\n就像所有故事裡演的那樣。"
  },
  AvgDialog_123119_Content_77 = {
    Text = "但這個世界，遠比茉夏所想像的，遠比茉夏所在的那個世界，更加殘酷。"
  },
  AvgDialog_123119_Content_78 = {
    Text = "<Shake:怎麼會這樣！！>"
  },
  AvgDialog_123119_Content_8 = {
    Text = "薩爾瓦多，你的能力是我們在濃霧中保持安全的基礎，而%player%，很顯然，你還有你的銀鑰匙都很重要。"
  },
  AvgDialog_123119_Content_80 = {
    Text = "你這傢伙，我就不該指望你會放棄拯救這個無聊的世界。"
  },
  AvgDialog_123119_Content_81 = {
    Text = "為了拯救別人犧牲這種事……這種事……"
  },
  AvgDialog_123119_Content_82 = {
    Text = "茉夏無法再說下去了，因為無論是生氣、憤怒，都已經無濟於事。"
  },
  AvgDialog_123119_Content_83 = {
    Text = "%player%固然是她茉夏的朋友，但她茉夏，卻只是這個世界的過客。"
  },
  AvgDialog_123119_Content_84 = {
    Text = "兩人之間相隔的，不僅僅是「維度」，還有兩個全然不同的「世界」。"
  },
  AvgDialog_123119_Content_85 = {
    Text = "其實，我的夢想是和我愛的人，一起圍坐在舒適的火爐旁，浪費我們一文不值的生命。"
  },
  AvgDialog_123119_Content_86 = {
    Text = "窗外的雪慢慢地飄著，年復一年，直到我們壽終正寢。然後，我的墓碑上會寫著：%heorshe%是一個長壽又幸福的廢物。"
  },
  AvgDialog_123119_Content_87 = {
    Text = "直到如今，我的夢想也從未變過。"
  },
  AvgDialog_123119_Content_88 = {
    Text = "那就去實現這個夢想啊，世界毀滅又怎麼樣？這樣無聊的世界，就算毀滅了又怎麼樣！？"
  },
  AvgDialog_123119_Content_89 = {
    Text = "總比留下永恆的遺憾，一個人永遠孤獨地被困在這個鬼地方強吧！"
  },
  AvgDialog_123119_Content_9 = {
    Text = "要是你出了什麼意外，可就沒人能解決那個麻煩了。"
  },
  AvgDialog_123119_Content_90 = {
    Text = "光斑再次一聲輕笑，茉夏卻已經無法分辨這聲音裡有沒有笑意了。\n因為她心中充滿了苦澀。"
  },
  AvgDialog_123119_Content_91 = {
    Text = "我也想實現這個夢想，很想很想，但是……"
  },
  AvgDialog_123119_Content_92 = {
    Text = "這個殘酷的世界下，我們總會做出一些「選擇」，一些可能連自己都無法理解的選擇。"
  },
  AvgDialog_123119_Content_93 = {
    Text = "或許，也不算無法理解。我雖然沒有喝過熱騰騰的榛果卡瓦茶，但我也有自己喜歡的東西。"
  },
  AvgDialog_123119_Content_94 = {
    Text = "墨菲的小蛋糕，莉茲的舞蹈，就連朵爾每次額外佈置的作業，現在想起來也充滿了趣味……"
  },
  AvgDialog_123119_Content_95 = {
    Text = "夠了，別再說了。你這傢伙簡直就是個無藥可救的……"
  },
  AvgDialog_123119_Content_97 = {
    Text = "驟然間，一道聲音乍響在茉夏的腦海。而她，第一時間就認出了對方。"
  },
  AvgDialog_123119_Content_98 = {
    Text = "看過「%heorshe%」為了拯救世界所進行的掙扎和犧牲後，她想，她很難再忘記這個聲音，這個人。"
  },
  AvgDialog_123119_Content_99 = {
    Text = "堅持住，我和薩爾瓦多很快就會將你救出來！我保證過的。"
  },
  AvgDialog_123120_Content_1 = {
    Text = "以自身為獻祭"
  },
  AvgDialog_123120_Content_10 = {
    Text = "薩爾瓦多神父……？"
  },
  AvgDialog_123120_Content_100 = {
    Text = "不知道這鬼東西要擴散到什麼程度，如果真的和我那個世界一樣……"
  },
  AvgDialog_123120_Content_101 = {
    Text = "茉夏沒有再說下去，但你明白她的潛臺詞——"
  },
  AvgDialog_123120_Content_102 = {
    Text = "霧災，是足以影響到一個世界的災難。"
  },
  AvgDialog_123120_Content_103 = {
    Text = "必須不計一切代價，終結這個儀式……<Shake:薩爾瓦多！>"
  },
  AvgDialog_123120_Content_104 = {
    Text = "我在。我必會保證你們的安全……也會讓這些迷途者，獲得真正的救贖……"
  },
  AvgDialog_123120_Content_105 = {
    Text = "隨後，溫暖柔和的光芒乍然出現在薩爾瓦多身上，擴散至你和茉夏身旁，隔絕著霧災的傷害。"
  },
  AvgDialog_123120_Content_106 = {
    Text = "茉夏，為了關閉這個空間裂隙，接下來我需要測量和確定精神維度的振波，戰鬥就拜託你了。"
  },
  AvgDialog_123120_Content_107 = {
    Text = "戰鬥？沒問題。有我在，妥妥地讓你不會掉一根毛！"
  },
  AvgDialog_123120_Content_108 = {
    Text = "憋了這麼久，終於可以發洩一下——"
  },
  AvgDialog_123120_Content_109 = {
    Text = "男女老少都愛看的！\n<Big:閃耀☆龍捲風——！！>"
  },
  AvgDialog_123120_Content_11 = {
    Text = "薩爾瓦多沉默著深吸了一口氣，然後重重吐出。"
  },
  AvgDialog_123120_Content_111 = {
    Text = "一把斧子飛出，劈散一連串的人形霧氣，也為你靠近那不斷吞吐濃霧的未知之門，劈出短暫的安全道路。"
  },
  AvgDialog_123120_Content_112 = {
    Text = "而你，不停操作著測量儀器，嘗試捕捉不同維度的振波。"
  },
  AvgDialog_123120_Content_113 = {
    Text = "一分鐘，悄然過去。\n兩分鐘，悄然過去。"
  },
  AvgDialog_123120_Content_114 = {
    Text = "然後是三分鐘，五分鐘，十分鐘……"
  },
  AvgDialog_123120_Content_115 = {
    Text = "汗水從你的額頭滴落，你從未覺得時間如此漫長。"
  },
  AvgDialog_123120_Content_116 = {
    Text = "還要多久？我總覺得這些怪物似乎變強了，劈好幾下才能打散……"
  },
  AvgDialog_123120_Content_117 = {
    Text = "那是另一個維度在嘗試入侵和吞噬我們世界的表現，對嗎，蒼白的使者？"
  },
  AvgDialog_123120_Content_118 = {
    Text = "又一滴汗水從你的額頭滴落，精神緊繃下，你連點頭都忘了。"
  },
  AvgDialog_123120_Content_119 = {
    Text = "振波……在不停變化……"
  },
  AvgDialog_123120_Content_12 = {
    Text = "不必尋找了，懷特神父……就在此處。"
  },
  AvgDialog_123120_Content_120 = {
    Text = "可能是濃霧自身的原因，也可能是被困在霧中的靈魂干擾……我需要時間去排查。"
  },
  AvgDialog_123120_Content_121 = {
    Text = "你抬頭看了眼天空，此時你再也看不見什麼「群星」了。\n整個世界似乎只剩下濃霧，以及持續不斷噴吐濃霧的維度之門。"
  },
  AvgDialog_123120_Content_122 = {
    Text = "可我們沒有時間了。"
  },
  AvgDialog_123120_Content_123 = {
    Text = "……你說得對。"
  },
  AvgDialog_123120_Content_124 = {
    Text = "你收起測量儀器，抬手握住了銀鑰匙。"
  },
  AvgDialog_123120_Content_125 = {
    Text = "看來，只能賭一把了……"
  },
  AvgDialog_123120_Content_126 = {
    Text = "蒼白的使者，你是想要連接……？"
  },
  AvgDialog_123120_Content_127 = {
    Text = "薩爾瓦多皺著眉，不贊同地看著你。而你，只是沉默。"
  },
  AvgDialog_123120_Content_128 = {
    Text = "喂喂，這裡還有一個「異世界來客」呢，說點我聽得懂的可以嗎？"
  },
  AvgDialog_123120_Content_129 = {
    Text = "%player%的意思是……連接那扇未知的「門」，以確定維度的振波。"
  },
  AvgDialog_123120_Content_13 = {
    Text = "那位祭台上的主祭……正是懷特。"
  },
  AvgDialog_123120_Content_130 = {
    Text = "什麼？那東西古怪得很，誰知道會有什麼結果，你可別做傻事。"
  },
  AvgDialog_123120_Content_131 = {
    Text = "你緊緊握住銀鑰匙，神色沉重地走向那無形的光門。此時此刻，行動勝過語言。"
  },
  AvgDialog_123120_Content_132 = {
    Text = "真是服了你們這些認為這個無聊世界還有拯救價值的人了……"
  },
  AvgDialog_123120_Content_133 = {
    Text = "出人意料地，茉夏伸手攔住了你。她表情複雜地望著你，似乎在看著你，又似乎在透過你，看著另外一個人。"
  },
  AvgDialog_123120_Content_134 = {
    Text = "最終，所有的糾結都化為了臉上的微笑，茉夏努力讓自己的聲音聽起來顯得輕鬆。"
  },
  AvgDialog_123120_Content_135 = {
    Text = "算了，誰讓我是調查團備受矚目的前鋒呢，衝在最前面也是理所當然的——"
  },
  AvgDialog_123120_Content_136 = {
    Text = "所以，讓我去。"
  },
  AvgDialog_123120_Content_137 = {
    Text = "茉夏望著你，神情嚴肅而堅定。"
  },
  AvgDialog_123120_Content_138 = {
    Text = "從囚籠一角開始，這是她第一次露出這樣認真的表情。"
  },
  AvgDialog_123120_Content_14 = {
    Text = "什麼！？"
  },
  AvgDialog_123120_Content_15 = {
    Text = "震驚之下，你不由得轉頭看向懷特，見到從前的生命教廷神父，如今的邪教領袖正在慷慨陳詞。"
  },
  AvgDialog_123120_Content_16 = {
    Text = "此刻，我們以銀與血為代價，做出了選擇，並永遠不會為此而後悔。"
  },
  AvgDialog_123120_Content_17 = {
    Text = "為了前往 「無消散之苦的寧靜國度 」，為了於這燃燒的世界救贖我們自己——"
  },
  AvgDialog_123120_Content_18 = {
    Text = "為了前往 「無消散之苦的寧靜國度 」，為了於這燃燒的世界救贖我們自己——"
  },
  AvgDialog_123120_Content_19 = {
    Text = "十幾個繁星黎明的信徒們異口同聲地宣誓著——"
  },
  AvgDialog_123120_Content_2 = {
    Text = "<Shake:這個世界正在燃燒，這個世界正在崩潰，這個世界註定毀滅。>"
  },
  AvgDialog_123120_Content_20 = {
    Text = "十幾個繁星黎明的信徒們整齊劃一舉起鍍銀匕首——"
  },
  AvgDialog_123120_Content_22 = {
    Text = "在你的呐喊聲中，鍍銀匕首同時刺向人牲的心臟，深深紮入，狠狠攪動。"
  },
  AvgDialog_123120_Content_23 = {
    Text = "刺目的鮮血自人牲的胸口噴湧而出，染紅了祭壇。"
  },
  AvgDialog_123120_Content_24 = {
    Text = "在一片血色中，你們自隱匿的陰影處現身，直視懷特，直面造成這一切悲劇的源頭。"
  },
  AvgDialog_123120_Content_25 = {
    Text = "又有無知之徒來阻止父神的儀式？"
  },
  AvgDialog_123120_Content_26 = {
    Text = "哈，天災降臨時你們無動於衷，當我即將帶領兄弟姐妹們獲得救贖時，你們卻要來阻止我——"
  },
  AvgDialog_123120_Content_27 = {
    Text = "繁星黎明會的首領輕蔑地笑著，看向了你們，而後他的眼瞳猛然瞪大，僵在了原地。"
  },
  AvgDialog_123120_Content_28 = {
    Text = "<Shake:薩、爾瓦多主教！？>"
  },
  AvgDialog_123120_Content_29 = {
    Text = "薩爾瓦多面色籠罩著陰霾，你注意到寬大的教袍之下，他高大瘦削的身軀居然在微微顫抖。"
  },
  AvgDialog_123120_Content_3 = {
