  AvgDialog_123121_Content_72 = {
    Text = "他聽到了你的所求。"
  },
  AvgDialog_123121_Content_73 = {
    Text = "他回應了你的所求。"
  },
  AvgDialog_123121_Content_75 = {
    Text = "在薩爾瓦多的幫助下，你終於從那迷幻的暈眩中回神。你拼命呼吸，大口喘氣，感覺自己恢復了一些理智。"
  },
  AvgDialog_123121_Content_76 = {
    Text = "薩爾瓦多，可以停止賜福了，我已經、好多了。"
  },
  AvgDialog_123121_Content_77 = {
    Text = "薩爾瓦多點點頭，全心投入到與霧中不知名威脅的戰鬥裡。"
  },
  AvgDialog_123121_Content_78 = {
    Text = "這些霧中的怪物不會死亡。就算被打散，也會很快再次出現。"
  },
  AvgDialog_123121_Content_79 = {
    Text = "恐怕只要這些霧氣還存在，這些怪物就會永生。"
  },
  AvgDialog_123121_Content_8 = {
    Text = "茉夏，你是自願被邪教徒抓住的。"
  },
  AvgDialog_123121_Content_80 = {
    Text = "薩爾瓦多神父，請問你覺得，茉夏剛才說的……是真的嗎？"
  },
  AvgDialog_123121_Content_81 = {
    Text = "從相遇開始，茉夏女士的靈魂之火便恆定如一。於我所見，她既沒有說謊的表現，也沒有說謊的動機。"
  },
  AvgDialog_123121_Content_82 = {
    Text = "那麼，我有一些猜想。不過，得先找到茉夏才行。"
