  AvgDialog_126907_Content_29 = {
    Text = "拉蒙娜，你有什麼祈歲節願望嗎？"
  },
  AvgDialog_126907_Content_3 = {
    Text = "你留意到，拉蒙娜獨自站在舞池外的小桌旁，啜飲著不知名的飲品。"
  },
  AvgDialog_126907_Content_30 = {
