  },
  AvgDialog_126911_Content_44 = {
    Text = "怎麼，你害怕我是那個內鬼嗎？"
  },
  AvgDialog_126911_Content_45 = {
    Text = "這倒不會。只是以前，都是我等著菲茵特睡著，然後再去休息……"
  },
  AvgDialog_126911_Content_46 = {
    Text = "那今天，就輪到你好好休息了！去吧去吧。"
  },
  AvgDialog_126911_Content_47 = {
    Text = "在溫柯爾的堅持下，汀克特也拿起一份毛毯，倚著座椅靠背合上了雙眼。"
  },
  AvgDialog_126911_Content_48 = {
    Text = "難怪大家都睡著了，真是安逸的氛圍啊……"
  },
  AvgDialog_126911_Content_5 = {
    Text = "1號和3號車廂都是空置的，所有窗戶和車門都是完全閉鎖的，無論使用物理手段還是銀芯科技都無法打破。"
  },
  AvgDialog_126911_Content_52 = {
    Text = "首先映入眼簾的，是溫柯爾安靜平和的睡臉。"
  },
  AvgDialog_126911_Content_53 = {
    Text = "列車裡不知何時熄了燈，周遭的環境都陷在一片黑暗之中，只有柔和的光從車廂的連接處透出。"
  },
  AvgDialog_126911_Content_54 = {
    Text = "溫柯爾……你怎麼睡著了……？"
  },
  AvgDialog_126911_Content_55 = {
    Text = "溫柯爾輕輕吐出一口氣。"
  },
  AvgDialog_126911_Content_56 = {
    Text = "嗯……？我……睡著了？"
  },
  AvgDialog_126911_Content_57 = {
    Text = "誒誒誒？！！！我睡著了！！！"
  },
  AvgDialog_126911_Content_58 = {
    Text = "溫柯爾的呼號如疾風驟雨，立刻驚醒了所有沉睡的旅客。"
  },
  AvgDialog_126911_Content_59 = {
    Text = "燈光驟然亮起，將整片車廂照亮。"
  },
  AvgDialog_126911_Content_6 = {
    Text = "我就說吧！沒必要折騰的！在車上只剩最後一位贏家之前，大家都出不去的！"
  },
  AvgDialog_126911_Content_60 = {
    Text = "各位乘客，在返鄉特快上休息得還好嗎？"
  },
  AvgDialog_126911_Content_61 = {
    Text = "監測到所有乘客都進入睡眠狀態後，小N特別替你們準備了安靜避光的環境哦！"
  },
  AvgDialog_126911_Content_62 = {
    Text = "抱歉，我平時都是靠飲用大量咖啡保持清醒狀態……"
  },
  AvgDialog_126911_Content_63 = {
    Text = "等等，我們當中是不是少了一個人？"
  },
  AvgDialog_126911_Content_65 = {
    Text = "嗯？小樹苗在看我嗎？我在哦。"
  },
  AvgDialog_126911_Content_66 = {
    Text = "那麼，缺少的人是……"
  },
  AvgDialog_126911_Content_67 = {
    Text = "所有人的目光望向車廂的尾端——"
  },
  AvgDialog_126911_Content_68 = {
    Text = "汀克特的喉嚨處被某種尖銳之物貫穿了一個大洞，血漿從傷口順著她天鵝般優美的脖頸流下，浸透了禮服的前襟。"
  },
  AvgDialog_126911_Content_69 = {
    Text = "滴血的夜鶯，再也不能歌唱了。"
  },
  AvgDialog_126911_Content_7 = {
    Text = "你怎麼又……剛才泰旖絲不是把你……"
  },
  AvgDialog_126911_Content_71 = {
    Text = "溫柯爾發出一聲刺破夜空的尖叫，身體順著牆壁滑坐到角落，雙臂緊緊環抱住自己，止不住地顫抖。"
  },
  AvgDialog_126911_Content_72 = {
    Text = "<Shake:對不起、我不該對自己那麼自信的、我不該一個人守夜、我不該在沒有咖啡的情況下覺得自己不會睡著……>"
  },
  AvgDialog_126911_Content_73 = {
    Text = "溫柯爾焦躁地咬著自己的指甲，慌張的淚水不斷地湧出，滴落在地毯上。"
  },
  AvgDialog_126911_Content_74 = {
    Text = "鋼鋼！善解人意的小N聽見了什麼？<Shake:乘客的需求>！"
  },
  AvgDialog_126911_Content_75 = {
    Text = "現在就給乘客大人送上貼心服務——<Yellow:無限量咖啡機>！"
  },
  AvgDialog_126911_Content_76 = {
    Text = "只要按下這個紅色按鈕，就會有無窮無盡的深烘熱美式從噴頭湧出！"
  },
  AvgDialog_126911_Content_77 = {
    Text = "你無聲地上前，抬手——"
  },
  AvgDialog_126911_Content_78 = {
    Text = "然後狠狠地砸扁了面前這個胡攪蠻纏的小N。"
  },
  AvgDialog_126911_Content_79 = {
    Text = "<Shake:對不起、對不起、對不起……>"
  },
  AvgDialog_126911_Content_8 = {
    Text = "哼哼，要是那麼容易死掉，就不是我小N了呀！"
  },
  AvgDialog_126911_Content_80 = {
    Text = "車廂內迴蕩著溫柯爾的抽泣聲。"
  },
  AvgDialog_126911_Content_81 = {
    Text = "無論你們如何抵抗，以汀克特的死亡為開幕——"
  },
  AvgDialog_126911_Content_82 = {
    Text = "自相殘殺，還是開始了。"
  },
  AvgDialog_126911_Content_9 = {
    Text = "怎麼樣怎麼樣，大家都在心中決定好今晚的擊殺目標了嗎？"
  },
  AvgDialog_126912_Content_1 = {
    Text = "隱藏的殺招"
  },
  AvgDialog_126912_Content_10 = {
    Text = "不知道為什麼，你總覺得那縷微笑之下深藏著某種你尚未知曉的情緒。"
  },
  AvgDialog_126912_Content_11 = {
    Text = "走吧，彌利亞姆。我們去1號車廂。"
  },
  AvgDialog_126912_Content_12 = {
    Text = "連接門即將合攏的瞬間，旺達側身回眸。"
  },
  AvgDialog_126912_Content_13 = {
    Text = "祈歲節快樂，守密人。"
  },
  AvgDialog_126912_Content_15 = {Text = "2號車廂"},
  AvgDialog_126912_Content_16 = {
    Text = "旺達和彌利亞姆離開後，車廂中只剩下了你和泰旖絲兩個人。"
  },
  AvgDialog_126912_Content_17 = {
    Text = "接下來，難得的獨處時間，我們做些什麼好呢，我的小樹苗？"
  },
  AvgDialog_126912_Content_18 = {
    Text = "泰旖絲不懷好意地突然湊近，你被驚得彈跳後撤半步，保持安全距離。"
  },
  AvgDialog_126912_Content_19 = {
    Text = "我可以去趕報告……"
  },
  AvgDialog_126912_Content_2 = {Text = "2號車廂"},
  AvgDialog_126912_Content_20 = {
    Text = "都已經祈歲節了，放鬆一下吧，別總是想著你的報告了。"
  },
  AvgDialog_126912_Content_21 = {
    Text = "她蜜色的手臂輕輕地攏上你的肩膀，曖昧的吐息猶如夜霧般纏繞上了你。"
  },
  AvgDialog_126912_Content_22 = {Text = "這……"},
  AvgDialog_126912_Content_23 = {
    Text = "朵爾嚴肅板起的臉、拉蒙娜的歎息聲、訶勒特的教鞭瞬間浮現在你的眼前。"
  },
  AvgDialog_126912_Content_24 = {
    Text = "還是不了……"
  },
  AvgDialog_126912_Content_25 = {
    Text = "你諂笑著，仿若不經意般躲開了泰旖絲的親昵。"
  },
  AvgDialog_126912_Content_26 = {
    Text = "好吧，那我們安靜地坐下來聊會兒天，怎麼樣？"
  },
  AvgDialog_126912_Content_27 = {
    Text = "告訴我吧，守密人……在你眼神躲閃的那個瞬間，你的腦海中在思念著誰呢？"
  },
  AvgDialog_126912_Content_3 = {
    Text = "列車的隆隆聲中，旺達率先打破了沉默。"
  },
  AvgDialog_126912_Content_30 = {
    Text = "你不記得自己講述了多久，只知道往日種種歷歷在目。"
  },
  AvgDialog_126912_Content_31 = {
    Text = "還有彌薩格的食堂，是個遠比實驗室火爆的地方。"
  },
  AvgDialog_126912_Content_32 = {
    Text = "尤其是小蛋糕上架的時候，孩子們會爭先恐後地奔向櫃檯，完全不顧淑女的優雅和謙讓的美德……"
  },
  AvgDialog_126912_Content_33 = {
    Text = "還有些小壞蛋會作弊，讓自己的動物夥伴叼著餐券提前在出餐口占位，然後把搶到的蛋糕送給自己膽小的朋友。"
  },
  AvgDialog_126912_Content_34 = {
    Text = "<Shake:還有……咦？>"
  },
  AvgDialog_126912_Content_35 = {
    Text = "你發現自己的語氣哽咽了起來，淚水不由自主地自眼眶滑落。"
  },
  AvgDialog_126912_Content_36 = {
    Text = "還有……"
  },
  AvgDialog_126912_Content_37 = {
    Text = "淚水越積越多，視線也越來越模糊。"
  },
  AvgDialog_126912_Content_38 = {
    Text = "<Shake:我好想好想回到彌薩格、回到大家的身邊……>"
  },
  AvgDialog_126912_Content_39 = {
    Text = "真奇怪、明明我<Yellow:三天前>才離開彌薩格去做田野調查、不應該……"
  },
  AvgDialog_126912_Content_4 = {
    Text = "我有一個提議。"
  },
  AvgDialog_126912_Content_40 = {
    Text = "可是思念的苦悶讓你的鼻子酸痛，腦內彷彿有一根緊緊繃著的弦瀕臨斷裂的邊界。"
  },
  AvgDialog_126912_Content_42 = {
    Text = "你沒入一個柔軟的懷抱。母親的懷抱。"
  },
  AvgDialog_126912_Content_43 = {
    Text = "@2答應你、你會回到你思念的地方的。"
  },
  AvgDialog_126912_Content_44 = {
    Text = "泰旖絲的面目變得模糊了。"
  },
  AvgDialog_126912_Content_45 = {
    Text = "朦朧的霧氣攏住了你們二人，你安靜地蜷縮在她的懷抱裡，化作很小很小的一隻。"
  },
  AvgDialog_126912_Content_46 = {
    Text = "你聞見了香氣。<Yellow:白玉蘭的香氣>。"
  },
  AvgDialog_126912_Content_47 = {
    Text = "<Red:大朵大朵白玉蘭的香氣。>"
  },
  AvgDialog_126912_Content_48 = {
    Text = "你就在這馥郁香氣的纏繞中，陷入令人遺忘所有擔憂、所有恐懼的，嬰孩般的睡眠。"
  },
  AvgDialog_126912_Content_49 = {
    Text = "意識消退之前、你記得的、只有母親那<Yellow:黃金色的、令人戀慕的眼睛>。"
  },
  AvgDialog_126912_Content_5 = {
    Text = "我們可以兩兩分組，分別留在1、2兩節車廂，這樣可以互相看顧。"
  },
  AvgDialog_126912_Content_51 = {
    Text = "然後——"
  },
  AvgDialog_126912_Content_52 = {
    Text = "「哐啷」一聲巨響，自1號車廂而來。"
  },
  AvgDialog_126912_Content_53 = {
    Text = "你知道，自相殘殺的遊戲還在繼續，夢該醒了。"
  },
  AvgDialog_126912_Content_54 = {Text = "1號車廂"},
  AvgDialog_126912_Content_55 = {
    Text = "1號車廂內，旺達與彌利亞姆重傷的軀體糾纏在一起，一柄匕首完全沒入了旺達的胸膛，彌利亞姆則被無數尖刺貫穿。"
  },
  AvgDialog_126912_Content_56 = {
    Text = "旺達半睜開失神的眼，斷斷續續地向你們吐露。"
  },
  AvgDialog_126912_Content_57 = {
    Text = "我就知道，彌利亞姆一定會發難，所以，我準備好了「反擊」……"
  },
  AvgDialog_126912_Content_58 = {
    Text = "現在，N絕對沒辦法達成他的勝利了……"
  },
  AvgDialog_126912_Content_59 = {
    Text = "你們一定要……"
  },
  AvgDialog_126912_Content_6 = {
    Text = "被留在兇手身邊的人豈不是很危險？"
  },
  AvgDialog_126912_Content_60 = {
    Text = "旺達的尾音消失不見。她遺言中的祝福也隨之被吞沒於寂靜之中。"
  },
  AvgDialog_126912_Content_61 = {
    Text = "漫長的沉默之後，泰旖絲終於顫抖著開口。"
  },
  AvgDialog_126912_Content_62 = {
    Text = "看來兇手確實是彌利亞姆。她知道二人相互看守的規則下，必須要先殺死旺達，否則她的行動一定會招致剩餘所有人的敵對，所以動手了。"
  },
  AvgDialog_126912_Content_63 = {
    Text = "旺達……正是知道自己擅長「反擊」，所以才主動和內鬼彌利亞姆共處一室。"
  },
  AvgDialog_126912_Content_64 = {
    Text = "她用自己的犧牲，換來了「好人」的勝利。"
  },
  AvgDialog_126912_Content_65 = {
    Text = "泰旖絲的語調、沉重中帶著一絲尊敬。\n如果可以、你多希望這出自真心。"
  },
  AvgDialog_126912_Content_67 = {
    Text = "不……彌利亞姆……不是N安插在我們當中的內鬼。"
  },
  AvgDialog_126912_Content_68 = {
    Text = "<Shake:不是她？那她為什麼？……>"
  },
  AvgDialog_126912_Content_69 = {
    Text = "為了勝利，為了贏，為了N許諾的「利莫里亞」，我所認知的彌利亞姆的確不惜於親自動手。"
  },
  AvgDialog_126912_Content_7 = {
    Text = "但這樣至少可以保證N不會獲得最終的勝利。"
  },
  AvgDialog_126912_Content_70 = {
    Text = "那麼……"
  },
  AvgDialog_126912_Content_71 = {
    Text = "真正的內鬼、是你。泰旖絲、或者說、<Yellow:假扮泰旖絲的某人>。"
  },
  AvgDialog_126912_Content_72 = {
    Text = "或許是你的鋪墊已經足夠，泰旖絲並未流露出太多驚愕，只是淡然地、眼含笑意地凝視著你的眼眸。"
  },
  AvgDialog_126912_Content_73 = {
    Text = "噢？你是什麼時候發現的？妾身倒是想要聽聽。"
  },
  AvgDialog_126912_Content_74 = {
    Text = "溫柯爾……離開後，旺達提出分割兩個車廂之前。"
  },
  AvgDialog_126912_Content_75 = {
    Text = "居然……那麼早嗎？妾身本以為、妾身選用的手法足夠謹慎、沒有留下多少線索。"
  },
  AvgDialog_126912_Content_76 = {
    Text = "汀克特身上的貫穿傷、可以來自泰旖絲的荊棘、旺達的尖刺、或是彌利亞姆隨身的匕首。"
  },
  AvgDialog_126912_Content_77 = {
    Text = "而溫柯爾之死……泰旖絲、旺達、彌利亞姆都具備施加中毒的能力。"
  },
  AvgDialog_126912_Content_78 = {
    Text = "考量到溫柯爾對咖啡的攝取量、只要在咖啡機裡下毒、死亡必將在某個時間點降臨。"
  },
  AvgDialog_126912_Content_79 = {
    Text = "所以、是的、在行兇手法上、你的偽裝非常成功。"
  },
  AvgDialog_126912_Content_8 = {
    Text = "由我來看守彌利亞姆。放心吧，我藏著對方絕對意料不到的殺手鐗。"
  },
  AvgDialog_126912_Content_80 = {
    Text = "那你的推理依據是……？"
  },
  AvgDialog_126912_Content_81 = {
    Text = "你聽過一款名叫「血月之夜」的派對遊戲嗎？每個血月，狼人會睜開雙眼開始狩獵，又在第二個白天潛伏入好人之中。"
  },
  AvgDialog_126912_Content_82 = {
    Text = "要想辨明隱藏的狼人，最關鍵的就是在發言環節推斷每個人的目的。狼人知曉好人的身分，所以他們的指認往往更加篤定。"
  },
  AvgDialog_126912_Content_83 = {
    Text = "而真正的泰旖絲，是在亞蘭蟄伏千年的女王，她的人格底色與表像截然相反，行事慎重，絕對不是輕易將嫌疑扣在他人身上之人。"
  },
  AvgDialog_126912_Content_84 = {
    Text = "所以你投票給了妾身，沒有跟票彌利亞姆。"
  },
  AvgDialog_126912_Content_85 = {
    Text = "我是主動和兇手共處一室的。"
  },
  AvgDialog_126912_Content_86 = {
    Text = "我本準備在你下手時人贓並獲，只可惜，彌利亞姆的行動比你更快……"
  },
  AvgDialog_126912_Content_87 = {
    Text = "在你對我的催眠完成之前，她就對旺達下手了。"
  },
  AvgDialog_126912_Content_88 = {
    Text = "精彩、精彩的推理。令妾身刮目相看了呢。"
  },
  AvgDialog_126912_Content_89 = {
    Text = "不、遠遠不夠……畢竟、我並不打算按照小N的安排、在這個故事中扮演偵探的角色。"
  },
  AvgDialog_126912_Content_9 = {
    Text = "旺達眯起眼睛，露出一個讓人安心的微笑。"
  },
  AvgDialog_126912_Content_90 = {
    Text = "我更希望、在案件發生之前、阻止你們的陰謀。但已經太遲了。"
  },
  AvgDialog_126912_Content_91 = {
    Text = "現如今，我也只能請你告訴我……你的真實面貌，究竟是誰？"
  },
  AvgDialog_126912_Content_92 = {
    Text = "銀光自你胸口的銀鑰匙爆發，似乎要照穿一切虛無與偽裝。"
  },
  AvgDialog_126912_Content_94 = {
    Text = "你的攻擊好像落到了空氣上。"
  },
  AvgDialog_126912_Content_95 = {
    Text = "她化作了一縷煙，一縷霧，一縷不可捉摸、不可名狀的存在。"
  },
  AvgDialog_126912_Content_96 = {
    Text = "來吧，跟妾身來。"
  },
  AvgDialog_126912_Content_97 = {
    Text = "霧氣咯咯地笑著，向你發出曖昧莫名的邀約。"
  },
  AvgDialog_128696_Content_1 = {
    Text = "砰！咚！砰！咚"
  },
  AvgDialog_128696_Content_10 = {
    Text = "諾締拉！"
