  AvgDialog_13049_Content_14 = {
    Text = "這是——？！"
  },
  AvgDialog_13049_Content_15 = {Text = "敵襲！"},
  AvgDialog_13049_Content_2 = {
    Text = "你找不到寬慰他的藉口，曾經仔細讀過的喚醒體檔案上的那些字，躍然眼前——"
  },
  AvgDialog_13049_Content_3 = {
    Text = "喚醒體自述：奧吉爾·丹斯克，@2公國騎士\n犧牲於衛國之夜……"
  },
  AvgDialog_13049_Content_4 = {
    Text = "侍官閣下，您也先去城郊避難吧，這裡…有我們就行了。"
  },
  AvgDialog_13049_Content_5 = {
