  },
  AvgDialog_13056_Content_83 = {
    Text = "校園掮客的小腿上綁著負重沙袋，正哭哭啼啼地繞著訓練場慢跑。\n奧吉爾一邊小步跟著她跑，一邊鼓勵著她，輕鬆自得連氣都不喘一下。"
  },
  AvgDialog_13056_Content_84 = {Text = "奧吉爾"},
  AvgDialog_13056_Content_86 = {
    Text = "他將監督漢娜的工作交給了其他職員，向你跑了過來。"
  },
  AvgDialog_13056_Content_87 = {
    Text = "您不是說我們的訓練午後才開始嗎？怎麼這麼早就來了？"
  },
  AvgDialog_13056_Content_88 = {
    Text = "他和其他學生、喚醒體已經在訓練場待了一上午，卻絲毫不顯疲態，看著你時依然充滿了崇敬和活力。"
  },
  AvgDialog_13056_Content_9 = {
    Text = "沒錯，戰略地圖上畫得清清楚楚，這裡是女眷行宮。"
  },
  AvgDialog_13056_Content_90 = {
    Text = "……漢娜的訓練結束後，我們去倫蒂尼恩市區逛逛吧。"
  },
  AvgDialog_13056_Content_92 = {
    Text = "奧吉爾顯然沒意料到你會突然提出休息，就連你自己都沒想到。"
  },
  AvgDialog_13056_Content_93 = {
    Text = "主君，請容我拒絕。融蝕危機近在眼前，我……現在的我，還沒做好準備。"
  },
  AvgDialog_13056_Content_94 = {
    Text = "比起玩樂，我想要更專心於精進武藝。"
  },
  AvgDialog_13056_Content_95 = {
    Text = "那麼換個說法吧。"
  },
  AvgDialog_13056_Content_96 = {
    Text = "那個和他一起在騎士團度過的午後突然跳進了腦海，某些你以為會隨著夢醒而被遺忘的記憶浮現。"
  },
  AvgDialog_13056_Content_97 = {
    Text = "現在是兌現願望的時刻了，騎士閣下。"
  },
  AvgDialog_13056_Content_99 = {
    Text = "您、您是怎麼知道？！"
  },
  AvgDialog_130571_Content_10 = {
    Text = "啊，啊……小煤球，對不起……莫絲，壓住了。"
  },
  AvgDialog_130571_Content_11 = {
    Text = "沒事，就是莫絲你怎麼突然衝進來了？"
  },
  AvgDialog_130571_Content_12 = {
    Text = "啊！莫絲，熱！抱抱小煤球，舒服！"
  },
  AvgDialog_130571_Content_13 = {
    Text = "莫絲，奇怪，因為，不冷了。"
  },
  AvgDialog_130571_Content_14 = {
    Text = "但是，好熱，好熱……"
  },
  AvgDialog_130571_Content_15 = {
    Text = "（壞了，莫非是聖河的影響？）"
  },
  AvgDialog_130571_Content_16 = {
    Text = "莫絲，不知道……"
  },
  AvgDialog_130571_Content_17 = {
    Text = "莫絲的眼神愈發迷離，纖細的手指從衣服的縫隙間伸了進去，輕柔地撫摸你的肌膚。"
  },
  AvgDialog_130571_Content_18 = {
    Text = "你非常熟悉這種感覺，在那場夢境中，「小煤球」時不時就會在莫絲懷裡享受到這種順毛服務。"
  },
  AvgDialog_130571_Content_19 = {
    Text = "小煤球，抱著，平靜~"
  },
  AvgDialog_130571_Content_20 = {
    Text = "小煤球，味道，好聞~"
  },
  AvgDialog_130571_Content_21 = {
    Text = "莫絲輕輕地在你身上嗅著，你不確定是殘留在身上的香薰，還是你本身的特殊性讓莫絲平靜了下來。"
  },
  AvgDialog_130571_Content_22 = {
    Text = "但是你明白，你不能任由莫絲繼續這樣下去了。"
  },
  AvgDialog_130571_Content_23 = {
    Text = "地板很硌，你的腰發出了抗議，它想念柔軟的床鋪。"
  },
  AvgDialog_130571_Content_24 = {
    Text = "那今晚就抱著我，我們一起睡吧？"
  },
  AvgDialog_130571_Content_25 = {
    Text = "嗯！小煤球，喜歡！要抱！"
  },
  AvgDialog_130571_Content_26 = {
    Text = "抱著小煤球，睡覺，睡覺~"
  },
  AvgDialog_130571_Content_27 = {
    Text = "你順勢帶著莫絲躺上了柔軟的床鋪，兩人抱在一起，四目相對，好似當初在船上那樣。"
  },
  AvgDialog_130571_Content_28 = {
    Text = "莫絲，不熱了~莫絲，好舒服~"
  },
  AvgDialog_130571_Content_3 = {
    Text = "莫，莫絲？"
  },
  AvgDialog_130571_Content_4 = {
    Text = "莫絲突然活潑地衝進房間，雙手抱在你的腰上，銀色長髮不停地在胸口摩擦。"
  },
  AvgDialog_130571_Content_5 = {
    Text = "你暗自慶幸她提前把附著在左手上的「駭人之物」收了起來，讓你不用承擔突然被咬的風險。"
  },
  AvgDialog_130571_Content_7 = {
    Text = "莫絲，等，等下，啊——"
  },
  AvgDialog_130571_Content_9 = {
    Text = "可惜，正如你所想，莫絲並沒有控制好她的力道，你們一起倒在了地上。"
  },
  AvgDialog_131200_Content_1 = {
    Text = "溫柔的枷鎖"
  },
  AvgDialog_131200_Content_10 = {
    Text = "阿拉克涅撫摸著女孩剩下一半的臉頰。在她輕輕為女孩合上雙眼的時候，身後的巨大燈柱發出一陣微弱的光芒。"
  },
  AvgDialog_131200_Content_11 = {
    Text = "阿拉克涅伸出手。燈柱中殘餘的一點餘燼如同被風捲起的細沙，圍繞在她纖細的手指飛舞、流淌，然後散落於地。"
  },
  AvgDialog_131200_Content_12 = {
    Text = "維度餘燼的殘餘……我們的感知沒有錯，這裡曾經是涅芙蕾亞隱藏餘燼的地方，但現在，餘燼被她帶走了。"
  },
  AvgDialog_131200_Content_13 = {
    Text = "帶走餘燼，殺害秘偶，涅芙蕾亞究竟想要做什麼……"
  },
  AvgDialog_131200_Content_15 = {
    Text = "似乎被什麼東西驚動，阿拉克涅抬起頭，透過那扇畫著提燈標誌的彩繪玻璃窗，望向不遠處站台的方向。"
  },
  AvgDialog_131200_Content_16 = {
    Text = "阿拉克涅？你怎麼了？"
  },
  AvgDialog_131200_Content_17 = {
    Text = "本體的氣息……我無法再感知到了。"
  },
  AvgDialog_131200_Content_19 = {
    Text = "你是說、你離開了劇院？"
  },
  AvgDialog_131200_Content_2 = {
    Text = "手指、小腿、眼球、肋骨、頭顱……主人剪斷了摯愛的玩偶、扔進黏液與鮮血裡。"
  },
  AvgDialog_131200_Content_20 = {
    Text = "在我們尋找秘偶的時候、我的本體正沿著城市的絲線、對那些淵獄侍從進行清剿。得知「回憶」的下落後、她便前往教堂來接應我們。"
  },
  AvgDialog_131200_Content_21 = {
    Text = "她的氣息已經非常接近……可現在、那道氣息消失了。"
  },
  AvgDialog_131200_Content_22 = {
    Text = "難道說……她遭遇了什麼不測？可「回憶」才剛剛死去不久、怎麼會……"
  },
  AvgDialog_131200_Content_23 = {
    Text = "具體發生了什麼、我無從得知。但在消失之前、她觸碰了與我進行聯絡的網。除了返回的指令之外、她最後留下的信息、是一個詞。"
  },
  AvgDialog_131200_Content_24 = {
    Text = "「歡愉」。"
  },
  AvgDialog_131200_Content_25 = {
    Text = "歡愉……？"
  },
  AvgDialog_131200_Content_26 = {
    Text = "你面前出現N那張可憎的笑臉。"
  },
  AvgDialog_131200_Content_27 = {
    Text = "我沒有明白……你們有著一樣的記憶、你一定知道她想要表達的意思。"
  },
  AvgDialog_131200_Content_28 = {
    Text = "阿拉克涅輕輕搖搖頭。"
  },
  AvgDialog_131200_Content_29 = {
    Text = "你的命運是一隻我不可輕易觸碰的蝴蝶，任何的解釋都將引起無法估量的後果。"
  },
  AvgDialog_131200_Content_3 = {
    Text = "「回憶」……"
  },
  AvgDialog_131200_Content_30 = {
    Text = "但你應知道、在你短暫的未來裡、「歡愉」是一把鑰匙、它將會解開你所面對的秘鎖。"
  },
  AvgDialog_131200_Content_31 = {
    Text = "我的命運？你的意思是，現在的你能夠看到我的命運絲線？！"
  },
  AvgDialog_131200_Content_32 = {
    Text = "你對上她的目光。在那個溫柔的笑容裡，你看到了來自命運不容置疑的威嚴。"
  },
  AvgDialog_131200_Content_33 = {
    Text = "……無論發生什麼事、信任我、也信任你自己。"
  },
  AvgDialog_131200_Content_34 = {
    Text = "回到命運劇院吧。鑰匙與鎖都在那裡等待你，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131200_Content_36 = {
    Text = "阿拉克涅平靜的聲音如同秋日和煦的夕陽。她的身形化作一捧蛛網，消失在教堂幽靜的燈光裡。"
  },
  AvgDialog_131200_Content_37 = {
    Text = "玻璃窗斑斕的映照下，只剩維度的餘燼在鮮血與斷肢的上空飄蕩。"
  },
  AvgDialog_131200_Content_38 = {
    Text = "「歡愉」……"
  },
  AvgDialog_131200_Content_39 = {
    Text = "你默念著那個不明所以的詞彙、回過頭、看見那些名為「回憶」的殘軀。"
  },
  AvgDialog_131200_Content_4 = {
    Text = "你輕輕將女孩的碎片撿起、殘肢上沾染的黏液與鮮血浸透了你的衣衫。"
  },
  AvgDialog_131200_Content_40 = {
    Text = "它們沐浴著渾濁的液體與聖潔的光，與這神聖的教堂融為一體，不可分離。"
  },
  AvgDialog_131200_Content_42 = {
    Text = "蛛網凝結的道路微微顫動、昏暗燈光照耀的舞台上。在你踏上蛛網的那一刻、所有的木偶們都停下了演出。"
  },
  AvgDialog_131200_Content_43 = {
    Text = "所有維度中的所有人、都向你望來。他們好奇、他們興奮、他們歡欣又敬畏。"
  },
  AvgDialog_131200_Content_44 = {
    Text = "這是一場宏大而靜謐的歡迎儀式。無數的演員成為了觀眾、唯一的觀眾成為主角。"
  },
  AvgDialog_131200_Content_45 = {
    Text = "或許聽阿拉克涅的話不是一個好主意……"
  },
  AvgDialog_131200_Content_46 = {
    Text = "你暗暗握緊銀鑰、獨自從這擁擠的、詭異的沉默中走過。"
  },
  AvgDialog_131200_Content_47 = {
    Text = "劇院的新主人已經等候你多時了，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131200_Content_48 = {
    Text = "高處的舞台上的陰影匯聚。幾乎是本能反應、你迅速向後靠去、將銀鑰舉在身前。"
  },
  AvgDialog_131200_Content_49 = {
    Text = "新主人？"
  },
  AvgDialog_131200_Content_5 = {
    Text = "或許……或許還有什麼辦法能夠救下她……質體的力量……命運的修正……"
  },
  AvgDialog_131200_Content_50 = {
    Text = "歡迎回到劇院，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131200_Content_52 = {
    Text = "很抱歉、我們的這幕新故事、需要你的參與。"
  },
  AvgDialog_131200_Content_53 = {
    Text = "蛛網輕輕顫動。緩步向你走來的劇院主人、聲音依然如黃昏般和煦。"
  },
  AvgDialog_131200_Content_54 = {
    Text = "你身邊的舞台上、那些與冷蛛侍女一般無二的人偶們轉過身體、齊齊躍向你……"
  },
  AvgDialog_131200_Content_6 = {
    Text = "涅芙蕾亞摧毀了她的絲線……她的命運已經終結了，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131200_Content_7 = {
    Text = "紡輪的聲音依舊平靜而遙遠。"
  },
  AvgDialog_131200_Content_8 = {
    Text = "「回憶」也被她殺害了、這是不是意味著……"
  },
  AvgDialog_131200_Content_9 = {
    Text = "涅芙蕾亞，已經擁有了改變這座舞台命運的力量。"
  },
  AvgDialog_131201_Content_1 = {
    Text = "呼……涅芙蕾亞的這些侍從，真是難纏……"
  },
  AvgDialog_131201_Content_10 = {
    Text = "二十天後、他將開始認真研習這本書上所記錄之物……那一刻開始、這個舞台便將與其他的舞台一樣、無可違逆地迎接毀滅的命運。"
  },
  AvgDialog_131201_Content_100 = {
    Text = "皇儲與夫人坐在敞篷車的後座、欣賞著這座古老的城市。人們跟在車後追逐著、奔向他們早已注定的命運。"
  },
  AvgDialog_131201_Content_11 = {
    Text = "這個剛剛接觸的、熟悉的世界在你腦海中翻湧。你從未見過如此美麗、繁榮的世界。"
  },
  AvgDialog_131201_Content_12 = {
    Text = "你已經歷太多、融蝕下那荒蕪的景象、輕易地覆蓋了這個繁華的世界、擠滿了你的想像。"
  },
  AvgDialog_131201_Content_13 = {
    Text = "阿拉克涅伸出手來，輕輕撫摸巷口投下的曦光。她在為又一個將要死去的世界哀悼。"
  },
  AvgDialog_131201_Content_14 = {
    Text = "一個沒有被神明注意到的世界……我以前從未有過這樣的想像。"
  },
  AvgDialog_131201_Content_15 = {
    Text = "我們還有機會改變這些嗎？"
  },
  AvgDialog_131201_Content_16 = {
    Text = "這正是我們來此的目的。"
  },
  AvgDialog_131201_Content_17 = {
    Text = "告訴我、我應該怎麼做？"
  },
  AvgDialog_131201_Content_2 = {
    Text = "你靠在這條隱秘小巷的牆壁上，大口喘著氣。"
  },
  AvgDialog_131201_Content_20 = {
    Text = "小巷外、一群精神波動明顯異於常人的人正在朝你們的方向逼近。"
  },
  AvgDialog_131201_Content_21 = {
    Text = "後方、上方、前方……越來越多的敵人出現在你的感知中。"
  },
  AvgDialog_131201_Content_22 = {
    Text = "我們被包圍了！……"
  },
  AvgDialog_131201_Content_23 = {
    Text = "從來到舞台開始、我就在對被竄改的命運進行修正。不過修正如此多人的命運、並不是一件容易的事。"
  },
  AvgDialog_131201_Content_24 = {
    Text = "涅芙蕾亞留下這些人，就是為了阻礙我對命運的修復。"
  },
  AvgDialog_131201_Content_25 = {
    Text = "或許我們還有別的辦法……"
  },
  AvgDialog_131201_Content_26 = {
    Text = "阿拉克涅，復國會今天在這裡謀劃的刺殺，我是其中一個執行人。"
  },
  AvgDialog_131201_Content_27 = {
    Text = "這個世界將因為那位皇儲研究巫術書而毀滅、如果我能成功的話、或許能阻止這件事發生"
  },
  AvgDialog_131201_Content_28 = {
    Text = "這並非最正確的……"
  },
  AvgDialog_131201_Content_29 = {
    Text = "在那裡！抓住他們"
  },
  AvgDialog_131201_Content_3 = {
    Text = "你沒有見到阿拉克涅奔跑的樣子，她平靜地站在你的身旁，就像她命中注定就應該在此時此刻站在這條小巷中。"
  },
  AvgDialog_131201_Content_30 = {
    Text = "阿拉克涅撥動琴弦，正在準備變異的侍從定格在巷口的門口，如同一尊雕像。"
  },
  AvgDialog_131201_Content_31 = {
    Text = "遠處響起小號與薩克斯的奏鳴聲、那聲音伴隨著汽車的轟鳴、緩緩靠近。"
  },
  AvgDialog_131201_Content_32 = {
    Text = "刺殺的計畫已經敗露、其他人無法做到這件事……那位皇儲已經靠近這裡、再不做就來不及了"
  },
  AvgDialog_131201_Content_33 = {
    Text = "阿拉克涅看著你焦急的眼睛，猶豫片刻後輕輕點了點頭。"
  },
  AvgDialog_131201_Content_34 = {
    Text = "既然命運的走向是如此……或許、嘗試為這個世界做出選擇、便是你應當完成的事。"
  },
  AvgDialog_131201_Content_35 = {
    Text = "去做您想做的吧，守密人{Male=先生,Female=小姐}。命運的真相，將在此為您揭開。"
  },
  AvgDialog_131201_Content_36 = {
    Text = "你沒有時間仔細思考阿拉克涅的話，點了點頭，在阿拉克涅的幫助下衝出小巷，匯入洶湧的人群。"
  },
  AvgDialog_131201_Content_37 = {
    Text = "那就是弗拉維安大公？帝國的繼承人，他那輛車得值多少錢啊……"
  },
  AvgDialog_131201_Content_38 = {
    Text = "我呸！這個強盜生的雜種！兜裡的每一分錢都是從我們身上刮下來的血！"
  },
  AvgDialog_131201_Content_39 = {
    Text = "要是腿沒有瘸、我一定會死在向這幫強盜衝鋒的戰場上"
  },
  AvgDialog_131201_Content_4 = {
    Text = "做了這麼周全的準備……她究竟想做什麼？"
  },
  AvgDialog_131201_Content_40 = {
    Text = "嘘！這裡到處都是帝國的衛兵、你不想活了？"
  },
  AvgDialog_131201_Content_42 = {
    Text = "當你擠開擁擠的人群終於來到街邊時、那輛嶄新的敞篷汽車正緩緩駛到你的面前。"
  },
  AvgDialog_131201_Content_43 = {
    Text = "年近六十的皇儲與夫人坐在後座，一邊向著周圍的人群招手，一邊指點著赫瓦茨那些歷史悠久的建築。"
  },
  AvgDialog_131201_Content_44 = {
    Text = "即便在你模糊的記憶裡，你也清楚地知道這個時代的皇室為這片土地帶來了多麼沉重的傷痛。"
  },
  AvgDialog_131201_Content_45 = {
    Text = "擔心對這個世界造成惡劣的影響、你停下了不由自主伸向銀鑰匙的手、從懷裡拿出那把本應出現在那裡的手槍、靠近那輛緩緩行駛的車輛。"
  },
  AvgDialog_131201_Content_46 = {
    Text = "餵！那個學生！你不能靠近……"
  },
  AvgDialog_131201_Content_47 = {
    Text = "抱歉了、大公殿下、我既然已經站上了舞台、就要替這名角色做完他要做的事"
  },
  AvgDialog_131201_Content_49 = {
    Text = "在這混亂的街道上、驕傲的帝國繼承人身邊並沒有你想像中的嚴密安保措施。憑藉嚴苛的訓練、你輕易地靠近車輛、扣動了扳機。"
  },
  AvgDialog_131201_Content_5 = {
    Text = "涅芙蕾亞留下了一個引子。在這個世界龐大的命運之網上，她汙染了其中一根絲線。"
  },
  AvgDialog_131201_Content_50 = {
    Text = "當三顆子彈精準地洞穿大公的胸膛、整個世界停了下來。"
  },
  AvgDialog_131201_Content_51 = {
    Text = "痛苦的大公、驚愕的皇子妃、奔跑的衛兵、全都滑稽地停了下來、如同一幅生動的油畫。"
  },
  AvgDialog_131201_Content_52 = {
    Text = "！！！這是……"
  },
  AvgDialog_131201_Content_53 = {
    Text = "短暫的停頓後、油畫的色彩開始流淌糾纏、時空與重力加入這場混亂的狂歡、你的身體被撕扯、無數的畫面從你眼前劃過。"
  },
  AvgDialog_131201_Content_54 = {
    Text = "皇儲的葬禮。君王的憤怒。戰爭。槍砲。死亡。戰士的號角，平民的哭喊。禿鷲落在韋爾登猩紅的戰場，啃食著四十萬具被攪碎的屍體。"
  },
  AvgDialog_131201_Content_55 = {
    Text = "帝國的覆滅、被瓜分的土地、落魄的國王、重新打開的巫術書……"
  },
  AvgDialog_131201_Content_56 = {
    Text = "黑色的黏液短暫地吞沒了你的視野。那個你熟悉的故事再次上演、徹底的黑暗與痛苦、侵蝕著你的每一個細胞……"
  },
  AvgDialog_131201_Content_57 = {
    Text = "不必擔心，您安全了，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131201_Content_58 = {
    Text = "一隻手搭在你的肩膀。混亂的油畫與無邊的黑暗從你眼前消失。"
  },
  AvgDialog_131201_Content_59 = {
    Text = "你猛地睜開眼。咖啡館裡安靜如初，懷中的勃朗寧手槍消失不見，剛剛上桌的薩赫蛋糕正泛著迷人的香氣。"
  },
  AvgDialog_131201_Content_6 = {
    Text = "在被污染的命運裡，那位菲歐帝國的皇儲，在兩個月之前發現了一本書。"
  },
  AvgDialog_131201_Content_60 = {
    Text = "阿拉克涅……這……這是怎麼回事？！我們……"
  },
  AvgDialog_131201_Content_61 = {
    Text = "請不必驚慌、我們已經回到了剛進入咖啡館的時候。好消息是、我們得到了一杯免費的咖啡。"
  },
  AvgDialog_131201_Content_62 = {
    Text = "阿拉克涅端起咖啡杯，微笑著抿了一口。棕色的液體上，倒映著你錯愕的臉。"
  },
  AvgDialog_131201_Content_63 = {
    Text = "命運的絲線並不是你所能看清之物。來自舞台外的演員、強行改變這個世界的命運、便會迷失在命運之網裡。"
  },
  AvgDialog_131201_Content_64 = {
    Text = "過去與未來，當這個舞台無數的命運在你眼裡交織，這便是命運之網的景象。"
  },
  AvgDialog_131201_Content_65 = {
    Text = "未來的命運……你是說、剛剛發生的那些、都是真的？那些戰爭、死亡……都是我造成的？"
  },
  AvgDialog_131201_Content_66 = {
    Text = "命運讓你目睹這一切，在刺殺皇儲之後，這一切的確本應發生。不過請不必擔心，守密人{Male=先生,Female=小姐}。這個舞台的命運，我已重新編織。"
  },
  AvgDialog_131201_Content_67 = {
    Text = "你朝窗外望了望。依然是熱鬧的人群，但那些被涅芙蕾亞影響的市民與警員早已消失不見。"
  },
  AvgDialog_131201_Content_68 = {
    Text = "如果是按我剛才的做法……如果你沒有對命運進行修復的話……"
  },
  AvgDialog_131201_Content_69 = {
    Text = "一個月之後、這個世界將因為這位皇儲的死亡而爆發史上最大規模的戰爭。八個帝國捲入其中、兩千萬人在這場戰爭中喪生。"
  },
  AvgDialog_131201_Content_7 = {
    Text = "一本記載著神秘巫術、能夠連接不屬於這個維度的神明的書。"
  },
  AvgDialog_131201_Content_70 = {
    Text = "我們腳下的土地將化為灰燼、咖啡廳裡坐在我們身邊的這些人、都沒有能夠從那場戰爭中活下來。"
  },
  AvgDialog_131201_Content_71 = {
    Text = "阿拉克涅搖晃著咖啡杯，望著窗外車水馬龍的街景。她平靜地講述著，如同在介紹一道再普通不過的甜點。"
  },
  AvgDialog_131201_Content_72 = {
    Text = "街道上鼎沸的人聲帶著安寧與繁榮的樂音、傳進你的耳朵。"
  },
  AvgDialog_131201_Content_73 = {
    Text = "融蝕呢？為什麼我已經殺死了那個皇儲、還是會給這個世界招來融蝕……"
  },
  AvgDialog_131201_Content_74 = {
    Text = "在那場浩大的戰爭裡、這個帝國落敗了。那位君王、原本不得不接受命運殘酷的宣判。但現在、他有了新的選擇。"
  },
  AvgDialog_131201_Content_75 = {
    Text = "不屬於這個世界的巫術、超越一切力量的神明。對一個喪子的父親、亡國的君主、有什麼比這個更有吸引力呢？"
  },
  AvgDialog_131201_Content_76 = {
    Text = "阿拉克涅溫和的話語讓你打了一個寒戰。二十億條生命的重量，如同實質般壓在你的身上。"
  },
  AvgDialog_131201_Content_77 = {
    Text = "<Shake:我沒有想到，刺殺一位皇儲，竟然會發生這樣的事……我本以為……>"
  },
  AvgDialog_131201_Content_78 = {
    Text = "命運讓你來做出這次選擇、是為了讓你看清它。你無法看見絲線、但你現在已經明白、這些絲線是以何種繁複的方式交織。"
  },
  AvgDialog_131201_Content_79 = {
    Text = "命運的絲線織就巨網、每一根絲線的輕顫、或許都將讓命運之網傾覆。"
  },
  AvgDialog_131201_Content_8 = {
    Text = "阿拉克涅抬起頭，望向那些你無法看見的絲線。"
  },
  AvgDialog_131201_Content_80 = {
    Text = "這便是命運——如此複雜的命運。"
  },
  AvgDialog_131201_Content_81 = {
    Text = "你深呼吸了一次、平復一下那顆因為後怕而劇烈跳動的心臟。"
  },
  AvgDialog_131201_Content_82 = {
    Text = "還好、還好你阻止了這場戰爭……"
  },
  AvgDialog_131201_Content_83 = {
    Text = "我並沒有阻止戰爭，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131201_Content_84 = {
    Text = "阿拉克涅輕輕搖了搖頭。"
  },
  AvgDialog_131201_Content_85 = {
    Text = "在新的命運裡、帝國的君王將看到巫術書中所展現的一小部分神蹟。那些力量、將成為他發動戰爭的倚仗。"
  },
  AvgDialog_131201_Content_86 = {
    Text = "君王與他的盟友、發動了更大規模的戰爭、另外幾個大陸的帝國、也捲入了這場戰爭中。"
  },
  AvgDialog_131201_Content_87 = {
    Text = "在這場戰爭中死去的人、是原本的四倍。"
  },
  AvgDialog_131201_Content_88 = {
    Text = "她平靜地講述著，就像是在為未能入睡的孩子講述一則溫柔的童話。"
  },
  AvgDialog_131201_Content_89 = {
    Text = "<Shake:這……這是為什麼？>"
  },
  AvgDialog_131201_Content_9 = {
    Text = "這個舞臺從未與神明有過連結、在很長一段時間裡、它本可以免於傾覆於融蝕的命運。"
  },
  AvgDialog_131201_Content_90 = {
    Text = "你已看到了命運之網的複雜。強行避免一些注定發生的事情、將會招致更為嚴重的災厄。"
  },
  AvgDialog_131201_Content_91 = {
    Text = "這位君王依然落敗了，那本書上有限的知識並沒有對帝國有更大的幫助。"
  },
  AvgDialog_131201_Content_92 = {
    Text = "在這次失敗之後，巫術成為了一個笑話，這個舞台上的統治者們，不再有人致力於此。"
  },
  AvgDialog_131201_Content_93 = {
    Text = "他們的目光、落在了其他的事物上。他們信奉著科學、研究能夠吞噬行星的武器、在這些武器的威懾中享受短暫的和平、然後被這些自己創造的武器毀滅。"
  },
  AvgDialog_131201_Content_94 = {
    Text = "這個舞台依然會因其他的劫難而不復存在，那是它無可規避的宿命。但他們仍能享有一段藝術品般美麗的繁榮。"
  },
  AvgDialog_131201_Content_95 = {
    Text = "托乎瓦波的目光，將暫時無法落到此處。"
  },
  AvgDialog_131201_Content_96 = {
    Text = "阿拉克涅的勺子在杯中緩緩轉動，那道深褐色的漩渦，與你在命運之網中看見的東西如出一轍。"
  },
  AvgDialog_131201_Content_97 = {
    Text = "她低下頭去。窗外的陽光落在她的身上、如同一道哀傷的紗幔。"
  },
  AvgDialog_131201_Content_98 = {
    Text = "掙扎，編織，修補，但無可改變……這便是命運，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131201_Content_99 = {
    Text = "小號與薩克斯的音樂來到窗邊、又帶著人群的歡呼與罵聲逐漸遠去。"
  },
  AvgDialog_131202_Content_11 = {
    Text = "紫色的長袍……我從來……從來沒有見過……"
  },
  AvgDialog_131202_Content_12 = {
    Text = "他們……將「回憶」帶去了祭壇……<Shake:咳咳……>"
  },
  AvgDialog_131202_Content_13 = {
    Text = "聖瓦西里街道……屬於他們的一座教堂……"
  },
  AvgDialog_131202_Content_14 = {
    Text = "骨骼與血肉顫抖、掙扎、擠壓著這具破爛身體最後的生命力。"
  },
  AvgDialog_131202_Content_15 = {
    Text = "他知道，阿拉克涅小姐無法看清那些人的絲線。他知道，這是需要他完成的事。"
  },
  AvgDialog_131202_Content_16 = {
    Text = "小姐……陰影中的惡徒……在獵殺我們……她篡改了我們的命運……"
  },
  AvgDialog_131202_Content_17 = {
    Text = "他們帶走了我的血……在那間教堂、她將舉行那場恐怖的儀式……"
  },
  AvgDialog_131202_Content_18 = {
    Text = "命運的復仇者，沐浴我們的血……來自陰影的邪神就要降臨，一切命運都將陷入……徹底……<Shake:咳咳咳……><Big:徹底的混沌……！>"
  },
  AvgDialog_131202_Content_19 = {
    Text = "老人的瞳孔驟然放大、身體因為寒冷與恐懼而顫抖、似乎見到了比他最深的夢魘還要恐怖的煉獄。"
  },
  AvgDialog_131202_Content_2 = {
    Text = "蜘蛛們四散開去，最後一個人影在銀光中倒下，暴雨的主人早已不見蹤影。你與阿拉克涅來到房間中央那個倒下的身影面前。"
  },
  AvgDialog_131202_Content_20 = {
    Text = "他緊緊抓住阿拉克涅的衣袖，用近乎哀求的目光望向阿拉克涅。"
  },
  AvgDialog_131202_Content_21 = {
    Text = "小姐……我仍然習慣稱您為小姐……您用了很久、才學會了說話、急壞了老爺跟夫人……"
  },
  AvgDialog_131202_Content_22 = {
    Text = "您向我告別、所有人都為您終於能開口說話而欣喜、可我知道、只有我知道……那句話、是命運無可違逆的宣判……"
  },
  AvgDialog_131202_Content_23 = {
    Text = "我回到家裡，等待著死亡的降臨。我無法停止哭泣，不是為我自己，是為了您，阿拉克涅小姐……"
  },
  AvgDialog_131202_Content_24 = {
    Text = "我知道、您將要背負的、是何其沉重的詛咒啊……"
  },
  AvgDialog_131202_Content_25 = {
    Text = "淚水流過老人溝壑縱痕的臉頰。他顫顫巍巍地握住阿拉克涅的手。隔著模糊的淚光，他看見眼前站著幼年的阿拉克涅。"
  },
  AvgDialog_131202_Content_26 = {
    Text = "那張稚嫩的臉從未放聲哭泣、它總是好奇地望著什麼也沒有的天空、向著那些他們無法看見的命運微笑。"
  },
  AvgDialog_131202_Content_27 = {
    Text = "阿拉克涅小姐，請您一定保護好她，保護好「回憶」……請您一定照顧好自己……"
  },
  AvgDialog_131202_Content_28 = {
    Text = "不要……迷失在……網裡……"
  },
  AvgDialog_131202_Content_29 = {
    Text = "「善良」的聲音到最後幾乎已經微不可聞。在他的聲息停下時，阿拉克涅輕輕替他闔上雙眼。"
  },
  AvgDialog_131202_Content_31 = {
    Text = "老埃德加的嘴角輕輕勾起。在他生命的最後時刻裡，他再次聽見了那句阿拉克涅此生說出的第一句話語。"
  },
  AvgDialog_131202_Content_32 = {
    Text = "他別無所求。"
  },
  AvgDialog_131202_Content_33 = {
    Text = "你……用你那位管家的記憶，創造了他……這些秘偶和你創造的其他人偶完全不一樣。為什麼？"
  },
  AvgDialog_131202_Content_34 = {
    Text = "或許是為了紀念、或許……是為了安慰自己。"
  },
  AvgDialog_131202_Content_36 = {
    Text = "安慰自己、他們一直在我身旁、從未遠離過……"
  },
  AvgDialog_131202_Content_37 = {
    Text = "阿拉克涅平靜地放下老人殘破的身軀，沒有再做更多的解釋，你也沒有再追問。你知道，答案就在不遠的地方等待著你。"
  },
  AvgDialog_131202_Content_38 = {
    Text = "在這張命運之網中，涅芙蕾亞的力量與他們有關。他們的死亡，將讓涅芙蕾亞與網的聯繫更加緊密。"
  },
  AvgDialog_131202_Content_39 = {
    Text = "在她擁有能夠破壞這張網的力量之前，阻止她，這是現在唯一重要的事，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131202_Content_4 = {
    Text = "<Shake:阿拉克涅小姐……異鄉人……咳咳……>"
  },
  AvgDialog_131202_Content_40 = {
    Text = "阿拉克涅的雙手撫摸老人的頭頂，觸碰那根幾乎已不可見的絲線。在這座城市遙遠的另一端，命運的絲線傳來微弱的回音。"
  },
  AvgDialog_131202_Content_41 = {
    Text = "命運回應了你？"
  },
  AvgDialog_131202_Content_42 = {
    Text = "阿拉克涅點了點頭。起身之前，她最後看了一眼老人那張微笑的臉。"
  },
  AvgDialog_131202_Content_43 = {
    Text = "「回憶」還活著。那些來自淵獄的客人們、正在等待著我們的到來。"
  },
  AvgDialog_131202_Content_5 = {
    Text = "你面前的身軀一半是被啃食得潰爛的血肉、一半是帶著血色的白骨。"
  },
  AvgDialog_131202_Content_6 = {
    Text = "老人劇烈的咳嗽聲勉強擠出幾滴尚未流乾的鮮血。一根看不見的絲線握在阿拉克涅的手中，如暴雨中的燭火，搖搖欲墜。"
  },
  AvgDialog_131202_Content_7 = {
    Text = "止血……我們需要止血的東西……"
  },
  AvgDialog_131202_Content_8 = {
    Text = "來不及了……阿拉克涅小姐……去救她……去救「回憶」……"
  },
  AvgDialog_131202_Content_9 = {
    Text = "那些信徒……帶走了她……"
  },
  AvgDialog_131203_Content_1 = {
    Text = "阿拉克涅！你這是在做什麼？！這就是你說的……信任？"
  },
  AvgDialog_131203_Content_10 = {
    Text = "表演。欺瞞。愚弄。"
  },
  AvgDialog_131203_Content_11 = {
    Text = "「歡愉」，這是你的宿命。登上舞台吧，守密人{Male=先生,Female=小姐}。在這座舞台上，完成屬於你的故事。"
  },
  AvgDialog_131203_Content_12 = {
    Text = "在這座舞台上、你將得償所願。"
  },
  AvgDialog_131203_Content_2 = {
    Text = "威廉學長……威廉學長還在養傷！……"
  },
  AvgDialog_131203_Content_3 = {
    Text = "請放心，這段命運與威廉先生無關，我已經將他轉移到了安全之處。"
  },
  AvgDialog_131203_Content_4 = {
    Text = "這是你我無法逃避的命運，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131203_Content_5 = {
    Text = "我從未向你講述謊言。我將帶你去往屬於你的舞台、你將在這座舞台上、完成屬於你的宏大表演。"
  },
  AvgDialog_131203_Content_6 = {
    Text = "阿拉克涅緩步向你走來。你望着她那雙迷霧般的眼睛，想要從裡面讀到那些她無法向你直接傳遞的信息。"
  },
  AvgDialog_131203_Content_7 = {
    Text = "（屬於我的……表演……）"
  },
  AvgDialog_131203_Content_8 = {
    Text = "一道靈光從你腦海中劃過、如同一顆轉瞬即逝的流星、消失在意識繁芜的碎片之中。"
  },
  AvgDialog_131203_Content_9 = {
    Text = "冷蛛侍女們四散在周圍，不再上前。阿拉克涅輕輕抬起手，撥動那空無的琴弦。"
  },
  AvgDialog_131204_Content_1 = {
    Text = "銀光如同利刃般斬斷那些蛛絲，利用這個空檔，你快速穿過侍女們的防線，來到阿拉克涅面前。"
  },
  AvgDialog_131204_Content_10 = {
    Text = "她轉過身來。絲線輕轉、一道毫無徵兆的衝動從內心燃起、驅使著你站起身來。"
  },
  AvgDialog_131204_Content_11 = {
    Text = "你確信你充分自主，你是自由意志的完美代言人。你完全出於個人意願，跟隨著阿拉克涅的腳步，以與她完全一致的步伐與頻率，向著蛛網道路的盡頭走去。"
  },
  AvgDialog_131204_Content_13 = {
    Text = "啊呀，歡迎！%player%{Male=先生,Female=小姐}，我尊貴的客人！這可是你的腳步聲聽起來最悅耳的一次呢。"
  },
  AvgDialog_131204_Content_14 = {
    Text = "劇院的新主人粉墨登場，黑暗的舞台上響起涅芙蕾亞誇張的語調。"
  },
  AvgDialog_131204_Content_15 = {
    Text = "被人擺弄命運的滋味，並不好受吧，守密人{Male=先生,Female=小姐}？不過沒有關係，這個故事，很快就要迎來它的結局了。"
  },
  AvgDialog_131204_Content_16 = {
    Text = "涅芙蕾亞，你究竟想要做什麼？……"
  },
  AvgDialog_131204_Content_17 = {
    Text = "懸念、沒錯、那正是驅使著觀眾們來到這個劇院的理由！不過、不要著急、親愛的。"
  },
  AvgDialog_131204_Content_18 = {
    Text = "女士們先生們！準備好你們的歡呼……咦、我的木偶呢……哦找到了"
  },
  AvgDialog_131204_Content_19 = {
    Text = "獵殺了三位秘偶的、命運偉大的復仇者、究竟想要為這個舞台獻上怎樣富有想像力的表演呢？"
  },
  AvgDialog_131204_Content_2 = {
    Text = "得手了！"
  },
  AvgDialog_131204_Content_20 = {
    Text = "下面，請大家欣賞本齣戲劇第二幕<Big:<Red:最後的高潮！>>"
  },
  AvgDialog_131204_Content_21 = {
    Text = "我將它命名為、「新生」——"
  },
  AvgDialog_131204_Content_23 = {
    Text = "一束明亮的燈光匯聚在舞台之上、打破了劇院短暫的寧靜與黑暗。一個手執紡輪的木偶走上舞台。"
  },
  AvgDialog_131204_Content_24 = {
    Text = "涅芙蕾亞，淵獄的死神，命運的復仇者……<Shake:我已臣服於您偉大的力量！>"
  },
  AvgDialog_131204_Content_25 = {
    Text = "這是浪漫、它讓人愚鈍。這是善良、它讓人脆弱。這是回憶……在一切美好的品質裡、回憶是一切痛苦的源頭。"
  },
  AvgDialog_131204_Content_26 = {
    Text = "我無力承受它們……我將它們進獻於您，偉大的涅芙蕾亞。"
  },
  AvgDialog_131204_Content_27 = {
    Text = "真的嗎、姊姊？我的好姊姊……"
  },
  AvgDialog_131204_Content_28 = {
    Text = "沒關係、這世上、我是最能理解你的人。不必再痛苦了、把這些痛苦通通交給我吧。"
  },
  AvgDialog_131204_Content_29 = {
    Text = "你看、來自淵獄的提燈已經點亮、它的光明、將為我們指引回家的路——"
  },
  AvgDialog_131204_Content_30 = {
    Text = "多麼溫暖的燈光……可是、我們回家的路、究竟在何處？"
  },
  AvgDialog_131204_Content_31 = {
    Text = "你還不明白嗎？我的好姊姊。"
  },
  AvgDialog_131204_Content_32 = {
    Text = "這台紡輪、便是使徒的身軀。這些燈火、便是使徒的目光——祂正在看著我們"
  },
  AvgDialog_131204_Content_33 = {
    Text = "「涅芙蕾亞」興奮地站起身來，張開雙臂。"
  },
  AvgDialog_131204_Content_34 = {
    Text = "隻需要匯聚三位質體的權柄、那無名的使徒便將於此覺醒"
  },
  AvgDialog_131204_Content_35 = {
    Text = "祂將為我們打開至高神明的通道……到那時候，<Big:一切苦難都將消亡，一切徒勞都將終結！>"
  },
  AvgDialog_131204_Content_36 = {
    Text = "「涅芙蕾亞」猛然扯下那張木質的面具，露出涅芙蕾亞那張鮮活的臉。"
  },
  AvgDialog_131204_Content_37 = {
    Text = "木質的舞台、木質的人偶、唯一鮮活的身體站在舞台中間、張開雙臂、享受著台下那唯一一位觀眾的目光。"
  },
  AvgDialog_131204_Content_38 = {
    Text = "神明的通道就要打開、你的使命就要完成了、你明白嗎、姊姊？"
  },
  AvgDialog_131204_Content_39 = {
    Text = "你不需要再編織你那張沒有盡頭的網、你不需要再割棄你自己"
  },
  AvgDialog_131204_Content_4 = {
    Text = "纖細的手伸向空中輕輕撥動。琴弦微顫、空氣中蕩開一道優雅的波紋。"
  },
  AvgDialog_131204_Content_40 = {
    Text = "重新接納我，好嗎，阿拉克涅？……讓我重新成為你的一部分……"
  },
  AvgDialog_131204_Content_41 = {
    Text = "眼淚帶下妝容、在臉上留下融蝕般的黑痕。瘋狂的笑聲與哭聲如同一張巨網、纏繞著這位舞台上唯一鮮活的個體。。"
  },
  AvgDialog_131204_Content_42 = {
    Text = "涅夫蕾亞蹲下身子，托起「阿拉克涅」沒有五官的光滑臉頰。淚水沿著那張哀泣的臉，滴落在木偶微笑的面具上。"
  },
  AvgDialog_131204_Content_43 = {
    Text = "她緊緊地凝視著台下的阿拉克涅，顫抖的嘴唇輕輕貼在木偶的耳邊。她的聲音如此輕，如同是在說給自己聽。"
  },
  AvgDialog_131204_Content_44 = {
    Text = "別再拋下我了……好嗎？"
  },
  AvgDialog_131204_Content_5 = {
    Text = "波紋掠過銀光、銀光消散、承載著強大精神力量的銀鑰匙不知所蹤。波紋掠過身體、你的身軀化為枯骨、血液化為污泥。你四分五裂、然後恢復如初。"
  },
  AvgDialog_131204_Content_6 = {
    Text = "一切力量都消弭無形、一切念頭都灰飛煙滅。波紋所至之處、萬千世界化為她手中的絲線。包括你、你自己。"
  },
  AvgDialog_131204_Content_7 = {
    Text = "她是劇院的主人。\n她是命運本身。"
  },
  AvgDialog_131204_Content_8 = {
    Text = "阿拉克涅，你……你能夠操控我的命運？！……"
  },
  AvgDialog_131204_Content_9 = {
    Text = "阿拉克涅的微笑如同一片寧靜的湖泊，你無法看清湖泊的樣子，在這片湖面上，你只能看見自己的倒影。"
  },
  AvgDialog_131205_Content_1 = {Text = "槍火"},
  AvgDialog_131205_Content_10 = {
    Text = "你不需要交任何作業。"
  },
  AvgDialog_131205_Content_11 = {
    Text = "阿拉克涅老師，您……是什麼意思？"
  },
  AvgDialog_131205_Content_12 = {
    Text = "還記得你是誰、來自何處嗎？"
  },
  AvgDialog_131205_Content_13 = {
    Text = "我？我當然是……"
  },
  AvgDialog_131205_Content_14 = {
    Text = "%player%。土生土長的赫瓦茨青年。戲劇學院的大一新生。父母是政府的普通僱員，對你寵愛有加。有過兩段得體的戀情。才華有限，充滿熱情，熱愛薩赫蛋糕與烤肉捲餅。"
  },
  AvgDialog_131205_Content_15 = {
    Text = "原本清晰的記憶忽然模糊、另一段記憶從你的腦海中突兀地蹦出來。彌薩格、喚醒體、融蝕、托乎瓦波……"
  },
  AvgDialog_131205_Content_16 = {
    Text = "你猛然睜大眼睛、望向對面那位正在品嚐咖啡的女人。"
  },
  AvgDialog_131205_Content_17 = {
    Text = "不……不對……我是彌薩格的守密人……這是怎麼回事？"
  },
  AvgDialog_131205_Content_18 = {
    Text = "我想起來了……我們在你的劇院裡、走上了一個舞台、然後……然後……"
  },
  AvgDialog_131205_Content_19 = {
    Text = "然後你向侍者點了下午茶。作為一個在地人、你的品味相當不錯。"
  },
  AvgDialog_131205_Content_20 = {
    Text = "阿拉克涅抿了一口咖啡杯中的棕色液體，讚許地点了点头。"
  },
  AvgDialog_131205_Content_21 = {
    Text = "二位、你們的東西上齊了。"
  },
  AvgDialog_131205_Content_22 = {
    Text = "侍者手中的盤子散發出醉人的香氣、俯身上菜的時候、他將頭悄悄靠近你的耳邊。"
  },
  AvgDialog_131205_Content_23 = {
    Text = "刺殺的計劃已經洩露，大公的路線很有可能發生變化。有新的消息之後，上線會第一時間通知你們。做好準備，%player%。"
  },
  AvgDialog_131205_Content_24 = {
    Text = "一支嶄新的勃朗寧手槍被悄悄放在你的手中。再次抬起頭時、侍者的臉上恢復了友善的微笑、向你們鞠躬致意後、他端著盤子回到了後廚。"
  },
  AvgDialog_131205_Content_25 = {
    Text = "過量的記憶堆積在你的腦海、你有些痛苦地揉了揉發脹的額頭。"
  },
  AvgDialog_131205_Content_26 = {
    Text = "兩段不同的記憶存在於一個大腦中、對第一次經歷的人來說、這種感受的確不太令人愉快。"
  },
  AvgDialog_131205_Content_27 = {
    Text = "還好、比起面對托乎瓦波、這種程度的頭痛就像是在按摩。"
  },
  AvgDialog_131205_Content_28 = {
    Text = "我的記憶告訴我，我會聽從復國會的指示，在兩個小時之後，用這支槍刺殺前來訪問的菲歐帝國皇儲……"
  },
  AvgDialog_131205_Content_29 = {
    Text = "你撫摸著那隻手槍的紋路、在腦海中整理出來那段屬於這個世界的記憶。"
  },
  AvgDialog_131205_Content_3 = {
    Text = "車輪碾過崎嶇的卵石路面、憤怒的鈴聲朝著龐大的遊行隊伍嘶吼、驚起一陣煙塵與咒罵。"
  },
  AvgDialog_131205_Content_30 = {
    Text = "在你來不及開口繼續詢問的時候、一陣強光照進咖啡館。軍靴與水泥地面清脆地碰撞、來到吧台前面。"
  },
  AvgDialog_131205_Content_31 = {
    Text = "幾位警官、你們好、請問……"
  },
  AvgDialog_131205_Content_32 = {
    Text = "沒等他話說完、一位警員快步上前、將他的雙手反扣、頭按在吧台上。"
  },
  AvgDialog_131205_Content_33 = {
    Text = "在他惶恐的眼神裡、一把槍抵在了他的眉心。"
  },
  AvgDialog_131205_Content_34 = {
    Text = "復國會成員博桑特。你有十秒鐘時間、告訴我你的同夥在哪裡。"
  },
  AvgDialog_131205_Content_35 = {
    Text = "侍者因恐懼而急促地呼吸。在劇烈的掙扎中，他望向大廳角落的位置。"
  },
  AvgDialog_131205_Content_36 = {
    Text = "你們剛剛坐過的位置上早已空無一人，半杯尚未喝完的咖啡上方，微弱的熱氣輕輕飄散。"
  },
  AvgDialog_131205_Content_38 = {
    Text = "這裡應該暫時安全了。"
  },
  AvgDialog_131205_Content_39 = {
    Text = "你們從咖啡館的後門離開、如同兩顆不起眼的水滴、匯入嘈雜的人群。"
  },
  AvgDialog_131205_Content_4 = {
    Text = "你揮了揮手、趕走那些從咖啡館的簾幕滲入的塵土。"
  },
  AvgDialog_131205_Content_40 = {
    Text = "現在的這個情況……這段不同的記憶、究竟是怎麼回事？"
  },
  AvgDialog_131205_Content_41 = {
    Text = "跨上命運劇院的舞台、便會成為舞台上的角色。每一位角色、都擁有自己的人生。"
  },
  AvgDialog_131205_Content_42 = {
    Text = "這個世界位於遙遠的維度、您從未聽聞、從未涉足。但作為生長於這個世界的角色、您已對它瞭如指掌。"
  },
  AvgDialog_131205_Content_43 = {
    Text = "歡迎登上我的其中一個舞台，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131205_Content_44 = {
    Text = "你的意思是……你能夠透過舞台連結其他的世界？"
  },
  AvgDialog_131205_Content_45 = {
    Text = "阿拉克涅看懂了你灼熱眼神裡的含義。她端起手裡那杯從店裡帶走的咖啡，認真品嗅著，輕輕搖了搖頭。"
  },
  AvgDialog_131205_Content_46 = {
    Text = "帶著咖啡與蛋糕逃亡，這件詭異的事絲毫沒有引起你的注意。它如此和諧地發生在阿拉克涅身上，自然得就像就是她命運的一部分。"
  },
  AvgDialog_131205_Content_47 = {
    Text = "達芙黛爾夫人向您講述過穿梭維度的原理。維度之間的壁壘十分堅固，每一次跨越維度的穿行都將付出慘痛的代價。"
  },
  AvgDialog_131205_Content_48 = {
    Text = "可我們現在不是已經身處這裡了嗎……"
  },
  AvgDialog_131205_Content_49 = {
    Text = "劇院的舞台能夠將不同世界的命運進行短暫的連接。"
  },
  AvgDialog_131205_Content_5 = {
    Text = "一份烤肉捲餅，一份薩赫蛋糕，兩杯赫瓦茨咖啡。謝謝。"
  },
  AvgDialog_131205_Content_50 = {
    Text = "現在的我們，只是兩個淹沒在舞台上的角色，是這個世界裡，兩個轉瞬即逝的投影。"
  },
  AvgDialog_131205_Content_51 = {
    Text = "投影……即使是投影也行、你是不是可以用這種方式幫我返回……"
  },
  AvgDialog_131205_Content_52 = {
    Text = "非常抱歉，%player%。由您所關閉的門扉，阻斷了托乎瓦波的目光，也隔絕了命運的絲線。"
  },
  AvgDialog_131205_Content_53 = {
    Text = "若是試圖對那裡施加影響、將會遭致我們無法承受的災厄。"
  },
  AvgDialog_131205_Content_54 = {
    Text = "她看著你臉上失落的神情、微笑著將盤子裡的蛋糕遞給你。"
  },
  AvgDialog_131205_Content_55 = {
    Text = "請放心，%player%。在解決了我那位妹妹的事情後，您與卡達斯連接的通道，很快便能再次打開。"
  },
  AvgDialog_131205_Content_56 = {
    Text = "命運不會辜負每一次等待、我們也不能辜負命運的每一份禮物。嚐嚐吧。"
  },
  AvgDialog_131205_Content_57 = {
    Text = "你深吸一口氣、拿過蛋糕輕輕咬了一口。香甜的味道讓你幾乎遺忘了兩段不同記憶衝撞帶來的不適感。"
  },
  AvgDialog_131205_Content_58 = {
    Text = "嗯……據說弗拉維安大公每次來的時候，都要品嚐這個特產的蛋糕。作為一名皇儲，他的品味的確不錯。"
  },
  AvgDialog_131205_Content_59 = {
    Text = "所以，涅芙蕾亞是影響了這個世界的什麼？我們應該怎樣去修正……"
  },
  AvgDialog_131205_Content_6 = {
    Text = "你將羊皮紙作工的菜單遞給侍者、鬱悶地看著窗外熟悉的街道。"
  },
  AvgDialog_131205_Content_60 = {
    Text = "在你說話的時候，阿拉克涅似乎被什麼吸引，抬頭望了一眼空中那些你無法看清的絲線。"
  },
  AvgDialog_131205_Content_61 = {
    Text = "她笑了笑、喝完杯中最後一口咖啡、將幾枚錢幣與剩餘的杯盞遞給一個恰巧經過、要趕回咖啡館的侍者、向他輕聲道謝。"
  },
  AvgDialog_131205_Content_62 = {
    Text = "她找到我們了，時間正好。請小心，%player%。"
  },
  AvgDialog_131205_Content_64 = {
    Text = "你下意識地俯下身、一顆子彈幾乎擦著你的頭頂飛過。"
  },
  AvgDialog_131205_Content_65 = {
    Text = "就在那邊"
  },
  AvgDialog_131205_Content_66 = {
    Text = "是復國會的刺客！抓住他們"
  },
  AvgDialog_131205_Content_67 = {
    Text = "在幾位市民的帶領下，一群警員撥開人群，向你們圍攏過來。"
  },
  AvgDialog_131205_Content_68 = {
    Text = "在靠近你們的時候，他們的身體開始變幻，黝黑的蜘蛛節肢上，鋒利的爪向你們揮來——"
  },
  AvgDialog_131205_Content_7 = {
    Text = "這條街真該擴建一下了、小時候這裡就是這個模樣、除了越來越破以外、這麼多年真是一點也沒有變。"
  },
  AvgDialog_131205_Content_8 = {
    Text = "當局確實是不擅長建設，他們唯一會的就是售賣赫瓦茨的土地，以及把蛋糕恭敬地遞給皇室。"
  },
  AvgDialog_131205_Content_9 = {
    Text = "流民，遊行，非要挑這個時間來訪問的大公……阿拉克涅老師，我的民俗研究作業能不能晚一些交？最近復國會的活動佔用了我太多精力了。"
  },
  AvgDialog_131206_Content_10 = {
    Text = "吱呀——吱呀——命運的女神轉動她的紡機。"
  },
  AvgDialog_131206_Content_11 = {
    Text = "吱呀——吱呀——命運的絲線在她手中匯集。"
  },
  AvgDialog_131206_Content_12 = {
    Text = "木偶們排隊入場、踏入命運的巨網。"
  },
  AvgDialog_131206_Content_13 = {
    Text = "它們跳舞。它們歡唱。吱呀——吱呀——"
  },
  AvgDialog_131206_Content_14 = {
    Text = "它們與巨網一同死去、悄無聲息。"
  },
  AvgDialog_131206_Content_16 = {
    Text = "主人、我們的新戲已經上演了。"
  },
  AvgDialog_131206_Content_17 = {
    Text = "返回卡達斯的通道已經及時關閉、那位{Male=先生,Female=小姐}、已經來到了城中。"
  },
  AvgDialog_131206_Content_18 = {
    Text = "怎麼樣、喜歡這出新的戲劇嗎？"
  },
  AvgDialog_131206_Content_19 = {
    Text = "嗯……或許有些過於複雜了？"
  },
  AvgDialog_131206_Content_2 = {
    Text = "霧都未醒"
  },
  AvgDialog_131206_Content_20 = {
    Text = "簡單的故事自然省心、但對於有些人來說、這樣的故事是無法書寫他們的命運的。"
  },
  AvgDialog_131206_Content_21 = {
    Text = "強烈的情感，劇烈的轉折，動人的情節，悲壯的結局……"
  },
  AvgDialog_131206_Content_22 = {
    Text = "這些，就是屬於「英雄」的宿命。"
  },
  AvgDialog_131206_Content_23 = {
    Text = "去吧、到你上場的時候了。"
  },
  AvgDialog_131206_Content_24 = {
    Text = "少女匍匐行禮。在額頭觸碰地板的一瞬間，她的身體四散分裂，血肉與肌膚悉數變為淡紫色的蜘蛛，四散消失在房間的角落之中。"
  },
  AvgDialog_131206_Content_27 = {
    Text = "身下是堅硬的柏油路面。你搖搖晃晃地站起來、用力揉了揉一團混亂的腦袋。"
  },
  AvgDialog_131206_Content_28 = {
    Text = "剛剛……發生了……"
  },
  AvgDialog_131206_Content_29 = {
    Text = "啊！卡達斯的通道！"
  },
  AvgDialog_131206_Content_30 = {
    Text = "你猛然驚醒、抬頭望向天空。"
  },
  AvgDialog_131206_Content_31 = {
    Text = "湛藍的天空上、明亮的陽光灑下、再無半點黑日與維度通道存在的痕跡。"
  },
  AvgDialog_131206_Content_32 = {
    Text = "這……這個人好奇怪……{Male=他,Female=她}是剛剛從天上掉下來的嗎？"
  },
  AvgDialog_131206_Content_33 = {
    Text = "嗯、據我所知、周圍有個科技公司正在測試飛行器、{Male=他,Female=她}應該是一位飛行器測試員。"
  },
  AvgDialog_131206_Content_34 = {
    Text = "唔……這是……"
  },
  AvgDialog_131206_Content_36 = {
    Text = "密密麻麻的人群、出現在被強光刺痛的眼中。"
  },
  AvgDialog_131206_Content_37 = {
    Text = "一座如倫蒂尼恩般繁華的城市將你帶回卡達斯那遙遠的回憶裡。"
  },
  AvgDialog_131206_Content_38 = {
    Text = "擁堵的街道，圍觀的人群，各處色彩繽紛的商店……"
  },
  AvgDialog_131206_Content_39 = {
    Text = "這個維度的世界因融蝕而人口銳減、即使在葬骸城你也從未看到過如此繁華的景象。"
  },
  AvgDialog_131206_Content_4 = {
    Text = "啊、卡達斯、我夢中的故鄉！現在、我終於可以返還"
  },
  AvgDialog_131206_Content_40 = {
    Text = "請問……這裡是哪裡？"
  },
  AvgDialog_131206_Content_41 = {
    Text = "哈、奇怪、竟然有人連倫蒂尼恩的名字都沒有聽說過？這可是這世上最偉大的城市"
  },
  AvgDialog_131206_Content_43 = {
    Text = "你說這裡叫什麼？"
  },
  AvgDialog_131206_Content_44 = {
    Text = "你確信你聽到了那四個字。"
  },
  AvgDialog_131206_Content_45 = {
    Text = "昏沉的大腦立刻清醒、你猛然站起身、環顧著周圍的景象。"
  },
  AvgDialog_131206_Content_46 = {
    Text = "布里克十字路、路口指示牌上斑駁的印記與你記憶中的如出一轍。"
  },
  AvgDialog_131206_Content_47 = {
    Text = "時間褶皺舊書店、每次從學校偷偷溜出來、你最喜歡做的就是躲在這裡偷看偵探小說。"
  },
  AvgDialog_131206_Content_48 = {
    Text = "芬芳集市雜貨鋪、德克斯特教授總是讓你從這裡幫他帶回一瓶金酒。N的小詭計。"
  },
  AvgDialog_131206_Content_49 = {
    Text = "晨露花房。在你成為守密人一周年的慶典上、拉蒙娜本打算在這裡為你訂做一束全倫蒂尼恩最鮮亮的花……"
  },
  AvgDialog_131206_Content_5 = {
    Text = "我的師長、我的同伴、我的摯友、我的……一切。"
  },
  AvgDialog_131206_Content_51 = {
    Text = "倫蒂尼恩……我真的……回來了？"
  },
  AvgDialog_131206_Content_52 = {
    Text = "請問……請問彌薩格現在怎麼樣了？"
  },
  AvgDialog_131206_Content_53 = {
    Text = "彌薩格？這位{Male=先生,Female=小姐}、您說的地方我們從未聽聞。"
  },
  AvgDialog_131206_Content_54 = {
    Text = "那融蝕怎麼樣了？這裡的受災情況怎麼樣？"
  },
  AvgDialog_131206_Content_55 = {
    Text = "災難？這座城市存在了兩千多年，還從來沒有過任何的災難。"
  },
  AvgDialog_131206_Content_56 = {
    Text = "孩子、我想你是累著了……在公園的長椅上坐坐、吃點東西吧。我這裡正好有一些。"
  },
  AvgDialog_131206_Content_57 = {
    Text = "老人將剛剛從雜貨店中買到的麵包與水遞到你面前。"
  },
  AvgDialog_131206_Content_58 = {
    Text = "啊、太感謝您了……不過我現在不餓、我只是……有些問題沒有想明白……"
  },
  AvgDialog_131206_Content_59 = {
    Text = "<Small:這不可能啊……沒有彌薩格、也沒有融蝕……>"
  },
  AvgDialog_131206_Content_6 = {
    Text = "只要穿越這黑暗的門扉、我便將再次與它們重聚"
  },
  AvgDialog_131206_Content_60 = {
    Text = "爺爺，這個人好奇怪，怎麼老是自己跟自己說話？"
  },
  AvgDialog_131206_Content_61 = {
    Text = "不要瞎說、{Male=他,Female=她}可能是遇到什麼困難了。對遠道而來的貴客、要有禮貌。"
  },
  AvgDialog_131206_Content_62 = {
    Text = "一隻手輕輕在你肩膀上拍了拍。你回過頭、看到一張陌生的臉。"
  },
  AvgDialog_131206_Content_63 = {
    Text = "我們是附近的巡警、隸屬於審查會管轄。這是我的證件。"
  },
  AvgDialog_131206_Content_64 = {
    Text = "向您問好。有好心的市民告訴我們、有位旅客在我們美麗的城市裡迷了路。"
  },
  AvgDialog_131206_Content_65 = {
    Text = "請問這位{Male=先生,Female=小姐}、是否需要什麼幫助呢？"
  },
  AvgDialog_131206_Content_66 = {
    Text = "你短暫地思考了一瞬。在沒弄清楚情況以前，你需要盡量避免引起別人的注意。"
  },
  AvgDialog_131206_Content_67 = {
    Text = "啊……勞你們費心了。我只是在路上閒逛暈倒了、沒有遇到什麼問題。"
  },
  AvgDialog_131206_Content_68 = {
    Text = "很感謝你們。我們還有事情要做、先走一步……"
  },
  AvgDialog_131206_Content_69 = {
    Text = "原來如此。那再耽誤您一點時間，我有一些問題，想請您解答一下。"
  },
  AvgDialog_131206_Content_7 = {
    Text = "可這近在咫尺的門扉為何關閉？這殘忍的天空、為何將我拋棄？"
  },
  AvgDialog_131206_Content_70 = {
    Text = "警員微笑著來到你們身邊、拍了拍你肩膀上的灰塵。"
  },
  AvgDialog_131206_Content_71 = {
    Text = "<Red:守密人>，我應該這麼稱呼你，對吧？"
  },
  AvgDialog_131206_Content_72 = {
    Text = "我想請問……對我的這場歡迎儀式，你還滿意嗎？"
  },
  AvgDialog_131206_Content_74 = {
    Text = "一陣令人反胃的蠕動聲響起。數根巨大的蜘蛛節肢撐破警員與路人的身體，散發著腥味的濃厚血漿濺到你們身上。"
  },
  AvgDialog_131206_Content_75 = {
    Text = "代表命運向你問好，親愛的守密人。"
  },
  AvgDialog_131206_Content_76 = {
    Text = "尊貴的客人已經來到我們的劇場，帶{Male=他,Female=她}入座吧，孩子們。"
  },
  AvgDialog_131206_Content_8 = {
    Text = "我親愛的銀鑰匙……請照亮我的道路……請給我答案的隻言片語……"
  },
  AvgDialog_131206_Content_9 = {
    Text = "燈光變換。銀色歌者上。"
  },
  AvgDialog_131207_Content_10 = {
    Text = "你還有停下來的機會，涅芙蕾亞。"
  },
  AvgDialog_131207_Content_11 = {
    Text = "徹底消散、又如何呢？"
  },
  AvgDialog_131207_Content_12 = {
    Text = "涅芙蕾亞輕佻地微笑，轉身望向那些虔誠的侍從。"
  },
  AvgDialog_131207_Content_13 = {
    Text = "告訴我、孩子們、你們害怕嗎？"
  },
  AvgDialog_131207_Content_14 = {
    Text = "回應阿拉克涅的是一陣絕望的笑聲。"
  },
  AvgDialog_131207_Content_15 = {
    Text = "哈哈哈哈！我們是被命運所拋棄的人、沒有什麼災厄會讓我們畏懼……請為我們帶來解脫吧、我的主人。"
  },
  AvgDialog_131207_Content_17 = {
    Text = "涅芙蕾亞寵愛地拍了拍侍從的頭。"
  },
  AvgDialog_131207_Content_18 = {
    Text = "你搞錯了、我的好姐姐。命運早已判處我們死刑與永恆的監禁。一群被拋棄的幽魂、不會再乞求命運的垂憐。"
  },
  AvgDialog_131207_Content_19 = {
    Text = "我們、是在向命運復仇。"
  },
  AvgDialog_131207_Content_2 = {
    Text = "你從未見過的宏大舞台上，涅芙蕾亞的黑色紡輪孤獨地屹立在舞台的中央。巨大圓環的中間，似乎永不熄滅的幽藍燈光映照著涅芙蕾亞喜悅的臉。"
  },
  AvgDialog_131207_Content_20 = {
    Text = "不知道是無意還是有意，涅芙蕾亞把玩的命運絲線中，有一根悄然斷裂。"
  },
  AvgDialog_131207_Content_21 = {
    Text = "在絲線斷裂的同時、距離你們不遠的一座舞台轟然破碎、化為飛散的碎片、湮滅在劇院無盡的維度空間裡。"
  },
  AvgDialog_131207_Content_22 = {
    Text = "哎呀、對不起對不起、不小心弄壞了你的絲線……"
  },
  AvgDialog_131207_Content_23 = {
    Text = "快動手吧、好姐姐。劇院的舞台雖然很多、但要是再弄壞的話、你也會心疼的吧？"
  },
  AvgDialog_131207_Content_24 = {
    Text = "阿拉克涅的歎息微不可聞。再次睜開眼的時候，她抬起指尖，在你的頭頂輕點。"
  },
  AvgDialog_131207_Content_25 = {
    Text = "阿拉克涅！不要這樣做……我們一定能找到別的辦法……"
  },
  AvgDialog_131207_Content_26 = {
    Text = "登上舞台吧，向神明的使徒獻上質體的權柄……這是你無可避免的命運，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131207_Content_27 = {
    Text = "阿拉克涅無可拒絕的聲音在你精神世界中迴蕩。在你抬起腳步向舞台上走去的時候，體內三股久違的力量開始躁動不安。"
  },
  AvgDialog_131207_Content_28 = {
    Text = "它們在你體內糾纏、衝撞，與阿拉克涅神諭般的話語對抗。"
  },
  AvgDialog_131207_Content_29 = {
    Text = "哎呀、不愧是三質體……這麼一點點權柄、相隔如此遙遠的維度、還能有餘力對宿主造成影響。"
  },
  AvgDialog_131207_Content_3 = {
    Text = "看，守密人{Male=先生,Female=小姐}，多美的燈光啊……"
  },
  AvgDialog_131207_Content_30 = {
    Text = "讓它們乖一點吧，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131207_Content_4 = {
    Text = "這束光是命運的饋贈、它將指引我們、去往那沒有痛苦的極樂之地……"
  },
  AvgDialog_131207_Content_5 = {
    Text = "涅芙蕾亞伸出手，抚摸着灯光在維度空間中留下的痕跡。手指的陰影缓缓收拢，在阿拉克涅的脸上蠕动。"
  },
  AvgDialog_131207_Content_6 = {
    Text = "來吧、姊姊、我們的主角該登場了。"
  },
  AvgDialog_131207_Content_7 = {
    Text = "……命運不是可以被玩弄與篡改的東西，涅芙蕾亞。"
  },
  AvgDialog_131207_Content_8 = {
    Text = "每個人的命運都已經注定，喚醒那位神明，讓一切終結……強行篡改命運，會帶來你無法預想的災厄。"
  },
  AvgDialog_131207_Content_9 = {
    Text = "無論是你厭憎的還是在意的，一切都會在災厄中消散。"
  },
  AvgDialog_131208_Content_1 = {Text = "判決"},
  AvgDialog_131208_Content_10 = {
    Text = "少女深吸了一口氣、心滿意足地微笑起來。"
  },
  AvgDialog_131208_Content_11 = {
    Text = "鳶尾花已經開始綻放……又一個春天真正來到了。"
  },
  AvgDialog_131208_Content_12 = {
    Text = "哎、小芙、我有沒有問過你、你最喜歡的季節是什麼？"
  },
  AvgDialog_131208_Content_13 = {
    Text = "……我沒有什麼喜歡的季節、主人。"
  },
  AvgDialog_131208_Content_14 = {Text = "無趣。"},
  AvgDialog_131208_Content_15 = {
    Text = "阿拉克涅翻了個白眼，伸出那隻沒有紡線的手，接住窗外灑下的陽光。"
  },
  AvgDialog_131208_Content_16 = {
    Text = "我喜歡每一個季節，尤其是春天。我們已經很久沒有出門了……這幾天找個時間，我們出去踏青怎麼樣？"
  },
  AvgDialog_131208_Content_17 = {
    Text = "在我出生的莊園旁邊、有一片打理得非常漂亮的花圃、你們一定會喜歡。"
  },
  AvgDialog_131208_Content_18 = {
    Text = "您已經等待了三天……該做決定了、主人。"
  },
  AvgDialog_131208_Content_19 = {
    Text = "侍女履行著她的職責，冰冷的話語如同一場冷雨。澆滅了阿拉克涅眼裡那個燦爛的春天。"
  },
  AvgDialog_131208_Content_2 = {
    Text = "吱呀——吱呀——命運的女神轉動她的紡機。"
  },
  AvgDialog_131208_Content_20 = {
    Text = "吱呀、吱呀……"
  },
  AvgDialog_131208_Content_21 = {
    Text = "停頓了一瞬之後、紡輪再次轉動起來。它的頻率溫和、清脆、亘古不變。"
  },
  AvgDialog_131208_Content_22 = {
    Text = "我們所處的這個國度、剛剛結束了百年的戰火。人們在廢墟上重新建起了他們的城市、等待著他們的、將會是一段漫長的和平。"
  },
  AvgDialog_131208_Content_23 = {
    Text = "看、那裡……"
  },
  AvgDialog_131208_Content_24 = {
    Text = "循著阿拉克涅的目光，侍女望向大廳中掛起的一副巨大的畫作。她從來沒有看懂過那幅畫。"
  },
  AvgDialog_131208_Content_25 = {
    Text = "在佐斯先生所有偉大的畫作裡、這幅畫無人問津、卻是我最喜歡的一幅。"
  },
  AvgDialog_131208_Content_26 = {
    Text = "那些用赭石與幾何結構創作的鹿群，即便只是一些抽象的符號，也能讓人感受到牠們旺盛的生命力。"
  },
  AvgDialog_131208_Content_27 = {
    Text = "每次看到它、我都會想起我最愛的那部話劇……"
  },
  AvgDialog_131208_Content_28 = {
    Text = "裂隙已經存在三天了、主人。這個維度的命運、已經受到了那位神明目光的侵染。"
  },
  AvgDialog_131208_Content_29 = {
    Text = "再這樣下去、祂的目光將要毀掉的地方、遠遠不止這裡。"
  },
  AvgDialog_131208_Content_3 = {
    Text = "吱呀——吱呀——命運的絲線在她手中匯集。"
  },
  AvgDialog_131208_Content_30 = {
    Text = "吱呀、吱呀。"
  },
  AvgDialog_131208_Content_31 = {
    Text = "少女閉上眼、享受著陽光的照拂。溫暖的房間陷入沉默、只有紡輪仍以亘古的頻率轉動。"
  },
  AvgDialog_131208_Content_32 = {
    Text = "你還記得、我們已經編織了多少個世界的命運了嗎？"
  },
  AvgDialog_131208_Content_33 = {
    Text = "一共二十七個、主人。"
  },
  AvgDialog_131208_Content_34 = {
    Text = "父親送我這輛紡輪後、我曾沿著它的線縷、接近了那道真理的門扉。在那門扉之後、我看到了這個世界將迎來的命運……"
  },
  AvgDialog_131208_Content_35 = {
    Text = "我知道在前方等待我的是什麼。我知道我應該做出什麼樣的選擇……可我做不到。"
  },
  AvgDialog_131208_Content_36 = {
    Text = "親人。朋友。記憶。一萬七千年的宏偉歷史。繁星般的科技與藝術……"
  },
  AvgDialog_131208_Content_37 = {
    Text = "看到那個答案以後、我便開始編織這個世界的命運……我總是想、命運賜予了我這樣的能力、我一定能為這世界做些什麼。"
  },
  AvgDialog_131208_Content_38 = {
    Text = "這是我的故鄉，也是我的嬰孩……<Shake:我……我做不到>，小芙……"
  },
  AvgDialog_131208_Content_4 = {
    Text = "木偶們排隊入場、踏入命運的巨網。"
  },
  AvgDialog_131208_Content_40 = {
    Text = "侍女蹲下身、拂去主人的淚水。春日的陽光下、她的聲音清澈而堅定。"
  },
  AvgDialog_131208_Content_41 = {
    Text = "您預見到了這一天、所以您讓我成為您身邊的侍女。"
  },
  AvgDialog_131208_Content_42 = {
    Text = "我生命的全部意義、就是在這個時刻、告訴您應當怎麼做……"
  },
  AvgDialog_131208_Content_43 = {
    Text = "您是命運的主人、是這諸多維度的守護者。這是一條殘酷的道路、可您已經做出了選擇。"
  },
  AvgDialog_131208_Content_44 = {
    Text = "命運三女神、負責紡織、裁量……以及剪斷。"
  },
  AvgDialog_131208_Content_45 = {
    Text = "從您做出選擇那一刻開始、這些、便都是您註定要履行的職責。"
  },
  AvgDialog_131208_Content_46 = {
    Text = "阿拉克涅抬起頭，模糊的雙眼裡，那道常人無法望見的裂隙在天際閃爍。它一直都在那裡，在那道溫暖的春日陽光旁邊，像是一道殘忍的微笑。"
  },
  AvgDialog_131208_Content_47 = {
    Text = "裂隙向阿拉克涅低語，向她講述那些冰冷的未來。她從很早的時候便已接受這詛咒，而當未來降臨，她的身體仍然因恐懼而顫抖。"
  },
  AvgDialog_131208_Content_48 = {
    Text = "阿拉克涅重新坐在織機前。在恐懼與絕望之後，她的臉上多出了一道不健康的紅暈。"
  },
  AvgDialog_131208_Content_49 = {
    Text = "她撫摸那些密密麻麻的絲線，如同一位母親撫摸孩子的臉。"
  },
  AvgDialog_131208_Content_5 = {
    Text = "它們跳舞。它們歡唱。吱呀——吱呀——"
  },
  AvgDialog_131208_Content_50 = {
    Text = "804年，我還沒有學會說話，管家在家裡彈奏了一首鋼琴曲。"
  },
  AvgDialog_131208_Content_51 = {
    Text = "埃利希翁的《洛奧斯河的葬禮》，這音樂的聲音如同神殿外靜靜流淌的噴泉，我看見，連神明也為那樂聲駐足……"
  },
  AvgDialog_131208_Content_52 = {
    Text = "一根絲線被無聲剪斷。它靜靜漂浮在空中、在命運的餘波中、無聲地飄蕩。"
  },
  AvgDialog_131208_Content_53 = {
    Text = "大廳中的樂聲消逝、只有留聲機仍在轉動。唱片上的紋路被填補、漂亮的花體字書寫的歌名被塗抹。"
  },
  AvgDialog_131208_Content_54 = {
    Text = "埃利希翁迎來了他另一種命運。在這孤寂的世界、他波瀾壯闊的一生從未存在過。"
  },
  AvgDialog_131208_Content_55 = {
    Text = "卡珊德拉、她設計的教堂、比其間的神明更值得瞻仰……"
  },
  AvgDialog_131208_Content_56 = {
    Text = "又一根絲線斷裂。兩百公里外、那座恢弘的教堂碎裂、坍塌、神像悲憫的雙眼破碎、與塵土再無分別。"
  },
  AvgDialog_131208_Content_57 = {
    Text = "莫恩林的童話、阿爾多的歌劇、瑪爾莫的畫作、羅維爾的詩……"
  },
  AvgDialog_131208_Content_58 = {
    Text = "書籍化為紙屑、雕塑化為碎片、畫作化為無序的色彩。"
  },
  AvgDialog_131208_Content_59 = {
    Text = "她是銘記者。她是行刑人。她誦念著這個世界每一位偉大藝術家的名字、剪斷那根屬於他們的絲線。"
  },
  AvgDialog_131208_Content_6 = {
    Text = "陽光照亮它們的臉、多麼歡喜——"
  },
  AvgDialog_131208_Content_60 = {
    Text = "維爾德堡、一座屬於英雄的宏偉城市。它歷經一百零五場戰火、三十七次被摧毀、重建、二十一位雄主在此建功立業、沉沙折戟。"
  },
  AvgDialog_131208_Content_61 = {
    Text = "貴族於此歡歌、貧民於此呐喊、詩人為它留下優美的詩句、涅爾琴河邊的歌聲與炮火在它的上空迴蕩。它英雄的歷史、結束在了今天。"
  },
  AvgDialog_131208_Content_62 = {
    Text = "一群被剪斷的絲線紛亂飄揚、如同一首狂歡的舞蹈。兩千三百公里外、那座恢弘的城市轟然崩毀。"
  },
  AvgDialog_131208_Content_63 = {
    Text = "一萬七千年的存續、在天災與人禍中艱難地屹立、從未倒下的古老文明……"
  },
  AvgDialog_131208_Content_64 = {
    Text = "虛弱著，顫抖著。阿拉克涅用尽全力舉起手，握住面前那茫茫的絲線。"
  },
  AvgDialog_131208_Content_65 = {
    Text = "絲線斷裂。八千公里外、那個傳承著人類文明、從未斷絕的龐大古國、就這樣消失在了人類的歷史中、如同一陣青煙。"
  },
  AvgDialog_131208_Content_67 = {
    Text = "人。藝術。城市。國度。文明。"
  },
  AvgDialog_131208_Content_68 = {
    Text = "一切都在崩塌、一切都在消失。"
  },
  AvgDialog_131208_Content_69 = {
    Text = "<Shake:看見了嗎，小芙？>我的第一個孩子死去了，是我親手殺死了她……"
  },
  AvgDialog_131208_Content_7 = {
    Text = "吱呀、吱呀。"
  },
  AvgDialog_131208_Content_70 = {
    Text = "淚水寧靜地落下。阿拉克涅虛弱地微笑著，望向窗外。在整個世界的廢墟之中，只剩窗外那座搖搖欲墜的莊園還在站立。"
  },
  AvgDialog_131208_Content_71 = {
    Text = "我曾想，在編織命運的時候，如果能一直看著我曾經生活的地方，會讓我在這條路上不那麼孤獨。"
  },
  AvgDialog_131208_Content_72 = {
    Text = "真是幼稚啊……對一個沒有選擇的劊子手而言、我親手給自己準備了最殘忍的刑罰。"
  },
  AvgDialog_131208_Content_73 = {
    Text = "她伸出手、撥動自己頭上那根朦朧的、她也無法看清的絲線、將其中的一部分連在了這個世界最後的一縷絲線上。"
  },
  AvgDialog_131208_Content_74 = {
    Text = "主人、您這是……？"
  },
  AvgDialog_131208_Content_75 = {
    Text = "浪漫帶來愚鈍、善良帶來脆弱、回憶帶來痛苦……"
  },
  AvgDialog_131208_Content_76 = {
    Text = "我想清楚了、小芙。我是被詛咒的行刑者、那些美好的東西、不應該存在於我身上。"
  },
  AvgDialog_131208_Content_77 = {
    Text = "您是……要將自己的一部分也扼殺掉？可……這些都是您最為珍視的部分，您怎麼能……"
  },
  AvgDialog_131208_Content_78 = {
    Text = "在很小很小的時候、我做了人生中的第一個夢。"
  },
  AvgDialog_131208_Content_79 = {
    Text = "阿拉克涅伸出手，接住那片正照耀著無盡廢墟的陽光。"
  },
  AvgDialog_131208_Content_8 = {
    Text = "古老的紡輪發出溫和的伴奏、少女坐在紡輪前、哼唱著一支曲調簡單的歌謠。"
  },
  AvgDialog_131208_Content_80 = {
    Text = "在夢裡、我正行走在一道湖面上。我的身邊是無窮無盡的廢墟與枯骨、而在湖面之下、我童年的倒影正行走在一個美麗的國度。"
  },
  AvgDialog_131208_Content_81 = {
    Text = "沒有死亡、沒有苦難、沒有遺忘。溫柔的陽光永遠照耀那裡、人群在她的身旁歡歌、永不停歇……"
  },
  AvgDialog_131208_Content_82 = {
    Text = "我無法看到我的絲線通往何處、但我想、我現在看清那道夢境預示的命運了。"
  },
  AvgDialog_131208_Content_83 = {
    Text = "她努力牽動嘴角、或許是向自己的侍女、又或許是向別的什麼東西。"
  },
  AvgDialog_131208_Content_84 = {
    Text = "母親曾說，將阿拉克涅的名字倒過來，念做涅芙蕾亞。在這個世界的傳說裡，它是春神的名字。"
  },
  AvgDialog_131208_Content_85 = {
    Text = "我喜歡每一個季節、尤其是春天。春天比命運渺小、渺小很多、很多。可命運總是通向死亡、而春天、春天只帶來新生……"
  },
  AvgDialog_131208_Content_86 = {
    Text = "她望向窗外。窗棱兩側、命運與春天最後一次對視。"
  },
  AvgDialog_131208_Content_87 = {
    Text = "離開我吧、我的倒影、我親愛的妹妹。和我們身上所有美好的品質、和我們所有美好的記憶一起。"
  },
  AvgDialog_131208_Content_88 = {
    Text = "命運……我將自己的一部分，徹底地祭獻於你。這條艱難的路，我會替她走下去。"
  },
  AvgDialog_131208_Content_89 = {
    Text = "阿拉克涅輕輕撫摸著那條糾纏在一起的絲線。絲線輕輕顫動，似乎在掙扎、哭喊。"
  },
  AvgDialog_131208_Content_9 = {
    Text = "一縷陽光從窗外灑下，落在紡輪邊那個印刻著「摩伊賴」的銘牌上。"
  },
  AvgDialog_131208_Content_90 = {
    Text = "她的淚水穿過那絲線、滴落在「摩伊賴」的銘牌上。"
  },
  AvgDialog_131208_Content_93 = {
    Text = "絲線斷裂。在春日和煦的陽光裡、紡輪發出最後一聲嘆息。"
  },
  AvgDialog_131209_Content_1 = {Text = "重圓"},
  AvgDialog_131209_Content_10 = {
    Text = "要是我選擇當一個歌劇演員的話、劇院買票的隊伍一定會排到三個街區以外。"
  },
  AvgDialog_131209_Content_11 = {
    Text = "可惜、倫蒂尼恩的木偶們沒有機會看到我精彩的演出了。這麼一看、你是多麼的幸運啊、小可愛。"
  },
  AvgDialog_131209_Content_12 = {
    Text = "涅芙蕾亞愛憐地輕輕捏了捏女孩的臉蛋，像是母親疼愛地撫摸女兒。"
  },
  AvgDialog_131209_Content_13 = {
    Text = "教堂大廳中央、鋼釘穿過女孩的胸腹、雙肩、脛骨、手掌、穿過她身體每一個利於懸掛與感知痛苦的部位、將她死死釘在巨大的紡輪形燈架上。"
  },
  AvgDialog_131209_Content_14 = {
    Text = "涅芙蕾亞將沾滿鮮血的手湊到鼻尖，痴迷地閉上眼。"
  },
  AvgDialog_131209_Content_15 = {
    Text = "啊……生命的味道、多麼的鮮活。"
  },
  AvgDialog_131209_Content_16 = {
    Text = "這些年來我試了很多次、咬壞孩子們的身體、咬壞自己的身體、可是連一點點生命的味道都嘗不到。"
  },
  AvgDialog_131209_Content_17 = {
    Text = "正確的命運。熱烈的生命。多麼令人羨慕啊……可你知道嗎？你本來、也應該和我們一樣、被扔進命運的垃圾堆裡的。"
  },
  AvgDialog_131209_Content_18 = {
    Text = "你無需進食、從不言語。除了那些替她保存的回憶、你一無所有、一無所知。"
  },
  AvgDialog_131209_Content_19 = {
    Text = "命運早就已經拋棄了你、小可憐。你只是個供她安慰自己的玩偶、一個替她照看那些回憶的守墓人、孤獨地在這個虛偽的舞台上流浪……"
  },
  AvgDialog_131209_Content_20 = {
    Text = "她望著已經幾乎沒有氣息的女孩、低語的聲音因悲傷而顫抖、冰冷的手指溫柔地整理好女孩鬢邊雜亂的髮絲。"
  },
  AvgDialog_131209_Content_21 = {
    Text = "現在、你那殘酷的命運母親就要來了……無論發生了什麼、都要用最美的樣子去面對一切、知道了嗎、親愛的？"
  },
  AvgDialog_131209_Content_23 = {
    Text = "眼睛適應了教堂昏暗的光線之後、首先抓住你目光的是一組巨大的壁畫。"
  },
  AvgDialog_131209_Content_24 = {
    Text = "黏液般的染料塗抹在數十米高的牆壁上、綿延不絕地延伸至望不見盡頭的黑暗中。偉岸、神聖、污穢、如同屹立在下水道中的救世聖徒像。"
  },
  AvgDialog_131209_Content_25 = {
    Text = "善解人意的女主人為參觀者清了場、空曠的教堂中只有腳步與呼吸的回音。你來到巨幅壁畫下、抬起頭仰望著。"
  },
  AvgDialog_131209_Content_26 = {
    Text = "一個女人坐在紡輪前、正在用剪刀剪斷了絲線……這幅壁畫上畫的是你？"
  },
  AvgDialog_131209_Content_27 = {
    Text = "看起來的確如此……我想、這是我那位姊妹想要向我們訴說的話。"
  },
  AvgDialog_131209_Content_28 = {
    Text = "阿拉克涅並沒有急於尋找「回憶」的所在。她跟隨著你的腳步，饒有興致地端詳起這些壁畫。"
  },
  AvgDialog_131209_Content_29 = {
    Text = "一個一模一樣的身影、離開了坐著的女人、墜入黑暗的洞穴……"
  },
  AvgDialog_131209_Content_3 = {
    Text = "吱呀——吱呀——命運的女神轉動她的紡機。"
  },
  AvgDialog_131209_Content_30 = {
    Text = "黑暗的洞穴裡，女人與其他黑暗的生物正在跳著一支怪異的舞蹈。她手裡拿著的是……一個紡輪？"
  },
  AvgDialog_131209_Content_31 = {
    Text = "紡輪的中心發出明亮的燈光，如同一盞提燈，照亮了洞穴……"
  },
  AvgDialog_131209_Content_32 = {
    Text = "女人帶著紡輪狀的提燈來到城市……一群身穿神袍的人、對著女人與提燈跪拜。他們的衣服上刻著的……是提燈的標誌？"
  },
  AvgDialog_131209_Content_33 = {
    Text = "它與你曾經看到過的提燈標誌有一些細微的差別、在那個邪惡的倒三角外圍、多了一圈紡輪般的圓形。"
  },
  AvgDialog_131209_Content_34 = {
    Text = "但你看懂了那個標誌的每一個元素。你清晰地知道、那就是提燈教會的標誌、那就是提燈教會的誕生。"
  },
  AvgDialog_131209_Content_35 = {
    Text = "最後一幅……"
  },
  AvgDialog_131209_Content_36 = {
    Text = "最後一幅壁畫伫立在甬道的盡頭、如同一扇隔絕命運的門。污穢的顏料在壁畫上起伏、映射著教堂中渾濁的光影。"
  },
  AvgDialog_131209_Content_37 = {
    Text = "女人拿著提燈，向著一個模糊的人影跪拜。人影身後，是一個巨大的……"
  },
  AvgDialog_131209_Content_38 = {Text = "嗚……"},
  AvgDialog_131209_Content_39 = {
    Text = "當你辨認出那個巨大的、尚未睜開的眼球時、一陣熟悉的強烈刺痛襲向你、在你的精神空間內掀起洶湧的浪潮。"
  },
  AvgDialog_131209_Content_4 = {
    Text = "吱呀——吱呀——命運的絲線在她手中匯集。"
  },
  AvgDialog_131209_Content_40 = {
    Text = "你趕緊挪開目光，大口地呼吸著，平復著精神空間裡痛苦的翻湧。"
  },
  AvgDialog_131209_Content_41 = {
    Text = "<Shake:呼……呼……>提燈教會……托乎瓦波……"
  },
  AvgDialog_131209_Content_42 = {
    Text = "在這個維度，涅芙蕾亞竟然……是提燈教會的創造者"
  },
  AvgDialog_131209_Content_43 = {
    Text = "原來如此、我明白了！……"
  },
  AvgDialog_131209_Content_44 = {
    Text = "如您所知，守密人{Male=先生,Female=小姐}。當那位至高的神明即將醒來時，我那位被命運拋棄的妹妹，從淵獄之中逃離。"
  },
  AvgDialog_131209_Content_45 = {
    Text = "她干擾了我的視線、將這個教派隱匿於我的舞台之下。"
  },
  AvgDialog_131209_Content_46 = {
    Text = "那位被她所崇敬的個體、便是這個維度裡、連接著那位至高神明的使徒。"
  },
  AvgDialog_131209_Content_47 = {
    Text = "你再次望向壁畫上那個連接著托乎瓦波的模糊黑影。"
  },
  AvgDialog_131209_Content_48 = {
    Text = "我明白了……涅芙蕾亞想做的，就是依靠那位使徒的力量，重新建立与托乎瓦波的连接！……"
  },
  AvgDialog_131209_Content_49 = {
    Text = "可既然如此、她又為什麼要去獵殺那些秘偶……"
  },
  AvgDialog_131209_Content_5 = {
    Text = "木偶們排隊入場、踏入命運的巨網。"
  },
  AvgDialog_131209_Content_50 = {Text = "鐺——"},
  AvgDialog_131209_Content_51 = {
    Text = "混濁的鐘聲從教堂外的鐘樓上響起、如同一道髒污的神諭。"
  },
  AvgDialog_131209_Content_52 = {
    Text = "巨大的教堂沉悶地轟鳴。漫長的震動中、刻畫著污穢壁畫的石牆緩緩升起。"
  },
  AvgDialog_131209_Content_53 = {
    Text = "那是！！"
  },
  AvgDialog_131209_Content_55 = {
    Text = "哎呀……我們的小「回憶」、聲音真是虛弱得讓人可憐呢。"
  },
  AvgDialog_131209_Content_56 = {
    Text = "涅芙蕾亞！放開她"
  },
  AvgDialog_131209_Content_57 = {
    Text = "幼女的身體掛在宏偉的紡輪燈架上、猩紅的鮮血在潔白的大理石上緩緩流淌。"
  },
  AvgDialog_131209_Content_58 = {
    Text = "明亮的燈光在女孩身後照耀、為這具血腥的身軀勾勒出一個聖潔的剪影。"
  },
  AvgDialog_131209_Content_59 = {
    Text = "涅芙蕾亞，不要再做這些無謂的爭鬥了。放她離開吧。"
  },
  AvgDialog_131209_Content_6 = {
    Text = "它們跳舞。它們歡唱。吱呀——吱呀——"
  },
  AvgDialog_131209_Content_60 = {
    Text = "哦？我們的命運女神、現在開始關心起她的「回憶」來了嗎？"
  },
  AvgDialog_131209_Content_61 = {
    Text = "你從未在意過他們，你拋棄了他們，阿拉克涅。"
  },
  AvgDialog_131209_Content_62 = {
    Text = "涅芙蕾亞，我知道你是想要召喚使徒，重新喚醒托乎瓦波……有什麼事情，我們可以再商量，沒有必要殺死他們……"
  },
  AvgDialog_131209_Content_63 = {
    Text = "你拖延時間的方式，真是幼稚得可愛呢，%player%。"
  },
  AvgDialog_131209_Content_64 = {
    Text = "你什麼都不明白。我從未殺害過他們。我只是、在接他們回家。"
  },
  AvgDialog_131209_Content_65 = {
    Text = "讓你們來到這裡、只是為了讓你們一起見證一下、他們圓滿的結局。"
  },
  AvgDialog_131209_Content_66 = {
    Text = "第二幕、第三場。我將它命名為、「歡聚」。"
  },
  AvgDialog_131209_Content_67 = {
    Text = "涅芙蕾亞輕蔑地望了你一眼。她的指甲輕輕劃過「回憶」的臉，在上面留下一道纖細的血痕。"
  },
  AvgDialog_131209_Content_68 = {
    Text = "她俯下身、愛憐地望著女孩因虛弱與恐懼而顫抖的臉。"
  },
  AvgDialog_131209_Content_69 = {
    Text = "好孩子、別害怕。很快、我們就到家了。"
  },
  AvgDialog_131209_Content_7 = {
    Text = "它們與巨網一同死去、悄無聲息。"
  },
  AvgDialog_131209_Content_70 = {
    Text = "和你那些不堪的回憶說再見吧、親愛的姊姊——"
  },
  AvgDialog_131209_Content_71 = {
    Text = "等等……涅芙蕾亞！"
  },
  AvgDialog_131209_Content_73 = {
    Text = "在涅芙蕾亞清脆的響指聲中，女孩的身體如同鮮紅的煙花般炸開。"
  },
  AvgDialog_131209_Content_74 = {
    Text = "提燈的光照耀著噴灑的血跡、在你們的臉上映出一朵猩紅的鮮花。"
  },
  AvgDialog_131209_Content_75 = {
    Text = "血珠在向空中飛濺，停駐，然後回返，貪婪地爬向涅芙蕾亞的身軀，染紅了涅芙蕾亞的每一寸身體。"
  },
  AvgDialog_131209_Content_76 = {
    Text = "血珠繼續向下、向下、滲入她的衣服與肌膚、滲入她的每一道血管、在她纖細的身體中奔涌。"
  },
  AvgDialog_131209_Content_77 = {
    Text = "舌尖舔舐着唇边的鮮血，涅芙蕾亞愉悅地欣賞著被血液染紅的指甲，如同盛裝的女主人，準備迎接一場重圓的筵席。"
  },
  AvgDialog_131209_Content_78 = {
    Text = "歡迎回家、親愛的。"
  },
  AvgDialog_131209_Content_79 = {Text = "住手！"},
  AvgDialog_131209_Content_8 = {
    Text = "歌聲在空曠的教堂中混響。涅芙蕾亞張開雙臂，欣賞著自己的餘音。"
  },
  AvgDialog_131209_Content_80 = {
    Text = "手中銀光綻放，你向著涅芙蕾亞衝去。"
  },
  AvgDialog_131209_Content_81 = {
    Text = "神聖血腥的燈光下、污穢的壁畫上延伸出無數的黑影、擋在你的面前……"
  },
  AvgDialog_131209_Content_9 = {
    Text = "怎麼樣、我唱得好聽嗎？"
  },
  AvgDialog_131210_Content_1 = {
    Text = "沒想到再次相見的時候、你會是這樣狼狽的樣子呢。"
  },
  AvgDialog_131210_Content_2 = {
    Text = "泰旖絲……"
  },
  AvgDialog_131210_Content_3 = {
    Text = "塔薇說得沒錯。沒關係的，守密人。"
  },
  AvgDialog_131210_Content_4 = {
    Text = "你說過要帶我見證另一個結局。我相信你、從始至終都是。"
  },
  AvgDialog_131210_Content_5 = {
    Text = "無論是停在這裡、還是越過我、我都一直在你身邊的。"
  },
  AvgDialog_131211_Content_1 = {Text = "繭"},
  AvgDialog_131211_Content_10 = {
    Text = "這種體驗、我可不想再有第二次了……"
  },
  AvgDialog_131211_Content_11 = {
    Text = "你不確定這是不是你的真心話。你握了握拳頭，重新適應這具剛剛與「N」共同掌管的身體。"
  },
  AvgDialog_131211_Content_12 = {
    Text = "視線逐漸清晰、你揉著劇痛的頭、走向舞台邊那個跪倒在地的單薄背影。"
  },
  AvgDialog_131211_Content_13 = {
    Text = "涅芙蕾亞，你的計畫已經……"
  },
  AvgDialog_131211_Content_14 = {
    Text = "請小心。"
  },
  AvgDialog_131211_Content_16 = {
    Text = "彷彿有絲線輕輕牽動、你的步伐慢了一分。一根鋒利的黑色蛛爪幾乎貼著你的眼睛、從你眼前險險劃過。"
  },
  AvgDialog_131211_Content_17 = {
    Text = "八根巨大的毒肢扯破她背脊的衣服，在空中揮動，扭曲，掙扎。涅芙蕾亞似乎對這一切毫不關心。"
  },
  AvgDialog_131211_Content_18 = {
    Text = "維度通道的碎片在她身邊如落場的禮花般飄揚。她的淚水落下、打濕手中那塊失去了燈光的暗淡紡輪。"
  },
  AvgDialog_131211_Content_19 = {
    Text = "維度的通道已經消失、你沒有機會了。"
  },
  AvgDialog_131211_Content_20 = {
    Text = "命運行走在它應有的軌跡上，涅芙蕾亞。接受它吧。"
  },
  AvgDialog_131211_Content_21 = {
    Text = "機會？……呵呵呵呵……"
  },
  AvgDialog_131211_Content_22 = {
    Text = "單薄的背影因笑聲抖動起來、帶著那些毒肢在空中劃出凄厲的軌跡。"
  },
  AvgDialog_131211_Content_23 = {
    Text = "我從未有過機會、也從未需要機會。"
  },
  AvgDialog_131211_Content_24 = {
    Text = "自由、童年、家人、愛、自我……命運奪走了我們的一切、我永遠、永遠不會像你一樣、做它的囚徒。"
  },
  AvgDialog_131211_Content_25 = {
    Text = "涅芙蕾亞緩緩站起身，將身體置於那台暗淡、破碎的紡輪中。"
  },
  AvgDialog_131211_Content_26 = {
    Text = "好好看著吧，阿拉克涅！那些你無比渴望又不敢做的事情，我會替你做到"
  },
  AvgDialog_131211_Content_27 = {
    Text = "幾乎是在憤怒的嘶吼聲中，涅芙蕾亞的身體似乎瞬間被無數根尖刺洞穿。鮮血從她的身體中倒流而出，連接在那台破碎的紡輪之上，如同一張血腥的網。"
  },
  AvgDialog_131211_Content_29 = {
    Text = "一陣人類無法承受的高頻尖嘯從涅芙蕾亞的頭部振出。她的身體因強烈的痛楚而顫動，暗紫色的血管紋路在她的身體上清晰地顯現。"
  },
  AvgDialog_131211_Content_30 = {
    Text = "維度通道的碎片似乎受到了什麼吸引、停止了飄散、緩緩聚向那張鮮血織就的網。暗淡的紡輪、重新燃起血腥的光輝。"
  },
  AvgDialog_131211_Content_31 = {
    Text = "呵……哈哈哈……！<Big:<Shake:沒有神明，我就來做那個神明！>>"
  },
  AvgDialog_131211_Content_32 = {
    Text = "我的故事……我的舞台……永遠不會結束！我會給這張不應存在的網……<Big:<Shake:<Red:帶來解脫！！！>>>"
  },
  AvgDialog_131211_Content_33 = {
    Text = "在涅芙蕾亞痛苦的嘶吼中，整個命運劇院劇烈震動起來。舞台上的木偶們顛倒、碰撞，連接著木偶們的絲線凌亂地糾纏……"
  },
  AvgDialog_131211_Content_34 = {
    Text = "阿拉克涅望著不遠處那個被維度碎片中的力量與瘋狂侵蝕著的身影。她深潭般的眼中泛起憂傷的波瀾，就像她第一次割棄自己的那一天。"
  },
  AvgDialog_131211_Content_35 = {
    Text = "我嘗試過將你從這詛咒中解脫……很遺憾，我錯了，涅芙蕾亞。"
  },
  AvgDialog_131211_Content_36 = {
    Text = "詛咒避無可避、牢籠、我們永遠無法逃離……"
  },
  AvgDialog_131211_Content_37 = {
    Text = "那些碎片……那個紡輪……"
  },
  AvgDialog_131211_Content_38 = {
    Text = "涅芙蕾亞正在吸收維度通道中殘餘的力量！她……她要讓自己成為燈芯！！"
  },
  AvgDialog_131211_Content_39 = {
    Text = "輕微的嘆息聲、在這搖搖欲墜的劇院中清晰地迴蕩著。"
  },
  AvgDialog_131211_Content_40 = {
    Text = "請站穩，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131211_Content_41 = {
    Text = "什麼……"
  },
  AvgDialog_131211_Content_42 = {
    Text = "<Shake:轟——>"
  },
  AvgDialog_131211_Content_43 = {
    Text = "話音尚未落下，整座劇院猛然撕裂開來。涅芙蕾亞狂暴地撕扯著命運的絲線，可怖的裂口中，城市的建築與維度斑斕的碎屑糾葛交纏。"
  },
  AvgDialog_131211_Content_44 = {
    Text = "劇院的主舞台碎裂成數塊、過去、未來與現在的碎片、在破碎的舞台上混亂地交織、拼湊重組成你無法理解的景象。"
  },
  AvgDialog_131211_Content_45 = {
    Text = "阿拉克涅……你的網……"
  },
  AvgDialog_131211_Content_46 = {
    Text = "阿拉克涅手中的紡輪飛速轉動，浩瀚的維度餘燼從阿拉克涅的體內湧出，循著紡輪上的絲線，填補著命運之網上那些破碎的空洞，勉強維持著舞台免於崩毀的命運。"
  },
  AvgDialog_131211_Content_47 = {
    Text = "在絲線的牽引下、你艱難地站起身。"
  },
  AvgDialog_131211_Content_48 = {
    Text = "吸收祂散落的力量，改變整張命運之網的走向……你不是祂的碎片，無法承受這樣的壓力。你不必如此痛苦地消亡，涅芙蕾亞。"
  },
  AvgDialog_131211_Content_49 = {
    Text = "痛苦？不、我很高興、姊姊！在淵獄裡的無數年、我每時每刻都在幻想著這一天。"
  },
  AvgDialog_131211_Content_5 = {
    Text = "我這是……"
  },
  AvgDialog_131211_Content_50 = {
    Text = "正是這幻想、才讓我撐到了今天……"
  },
  AvgDialog_131211_Content_51 = {
    Text = "涅芙蕾亞癲狂的笑聲在劇院破碎的空間中迴蕩。她抬起頭，貪婪地吸收著碎片中那些幽暗的餘光。"
  },
  AvgDialog_131211_Content_52 = {
    Text = "陷入沉睡的神明、被竊取命運的使徒……呵呵呵呵……沒關係、這些都阻止不了我。既然神明無法帶來恩澤、那就由我來替祂帶來！"
  },
  AvgDialog_131211_Content_53 = {
    Text = "命運的復仇者，現在，<Red:降臨屬於你們的舞台吧！>"
  },
  AvgDialog_131211_Content_54 = {
    Text = "涅芙蕾亞猛然抬起手。無盡的黑色黏液從涅芙蕾亞身上湧出，在這座劇院的空洞中建起黑色的蛛網。"
  },
  AvgDialog_131211_Content_55 = {
    Text = "無數曾被命運拋棄的怨念化為實體，順著這張巨大的黑色蛛網綿延不絕地爬出，向你們洶湧而來。"
  },
  AvgDialog_131211_Content_56 = {
    Text = "阿拉克涅，我們的身上……！"
  },
  AvgDialog_131211_Content_57 = {
    Text = "你猛然發現，一根你能看見的黑色的絲線從阿拉克涅的身上隱約出現。"
  },
  AvgDialog_131211_Content_58 = {
    Text = "你抬起頭，看到一根同樣模糊的黑色絲線從自己身上、從每一座舞台、每一個木偶的身體上延伸而出，連向涅芙蕾亞手中的紡輪。"
  },
  AvgDialog_131211_Content_59 = {
    Text = "萬福，阿拉克涅！祝福你，命運的女神"
  },
  AvgDialog_131211_Content_6 = {
    Text = "強烈的暈眩與胃痙攣是歡愉留下的殘骸、你忍住噁心緩緩爬起身。"
  },
  AvgDialog_131211_Content_60 = {
    Text = "來呀、拔出你們的刀刃、士兵們！為了我們的命運而戰"
  },
  AvgDialog_131211_Content_61 = {
    Text = "阿拉克涅小姐，承認自己的命運吧……不要再做無謂的抵抗……"
  },
  AvgDialog_131211_Content_62 = {
    Text = "不要擔心、親愛的。你的解脫就要到了、很快、很快……"
  },
  AvgDialog_131211_Content_63 = {
    Text = "涅芙蕾亞的晦暗紡輪瘋狂地轉動，舞台上的木偶們化為淵獄中的黑影，在絲線的牽引下踏上那張新織的黑網。"
  },
  AvgDialog_131211_Content_64 = {
    Text = "阿拉克涅緩緩閉上眼，握緊絲線的手因痛苦而微微顫抖。"
  },
  AvgDialog_131211_Content_65 = {
    Text = "涅芙蕾亞，它們無法幫助你成為那個能夠摧毀一切命運的神明……你這樣做，只會讓它們再迎來一次痛苦的消亡。"
  },
  AvgDialog_131211_Content_66 = {
    Text = "那又有什麼關係呢？復仇、除了復仇、我們別無所求！對嗎、命運的棄嬰們？"
  },
  AvgDialog_131211_Content_68 = {
    Text = "尖銳的、豪壯的、淒厲的笑聲從無盡的黑色蛛網中傳來、如同一道痛苦的合唱。"
  },
  AvgDialog_131211_Content_69 = {
    Text = "那些被遺棄的命運們狂笑著、嚎哭著，擋在涅芙蕾亞身前。"
  },
  AvgDialog_131211_Content_7 = {
    Text = "使徒的意識離開了那座紡輪、又失去了與神明的連結、現在已經被破壞殆盡。質體的力量也已歸於平靜。"
  },
  AvgDialog_131211_Content_70 = {
    Text = "現在，淵獄的大門已經徹底打開。來呀，阿拉克涅，看看這些被你親手創造的命運，看看你摯愛的孩子們"
  },
  AvgDialog_131211_Content_71 = {
    Text = "看看他們的痛苦、他們的絕望……看著他們、然後、再一次殺死他們"
  },
  AvgDialog_131211_Content_72 = {
    Text = "看著一切的命途在我手中轉動、摧毀！……看著我、成為那個帶來終結的神明"
  },
  AvgDialog_131211_Content_73 = {
    Text = "維度的碎片帶著神明的力量與狂亂的意志，一塊塊扎入涅芙蕾亞的體內，鮮血不停地灌入涅芙蕾亞的紡輪。"
  },
  AvgDialog_131211_Content_74 = {
    Text = "她的臉因痛苦而抽動，她的笑聲愈發地瘋狂。"
  },
  AvgDialog_131211_Content_75 = {
    Text = "她滿含期待地望著屬於破碎的舞台、如同一位正等待自己作品首次演出的劇作家。"
  },
  AvgDialog_131211_Content_76 = {
    Text = "那座命運的淵獄，已經降臨在這座舞台……涅芙蕾亞在獻祭自己。"
  },
  AvgDialog_131211_Content_77 = {
    Text = "她要將這裡的一切、連同我們在內、都變成她的木偶。她想要成為那位神明。她……想要成為命運本身。"
  },
  AvgDialog_131211_Content_78 = {
    Text = "阿拉克涅平靜的語氣彷彿屬於一位從未入戲的觀眾。那些被重新收回的維度餘燼如輕沙般縈繞在她指尖，綿延不絕。"
  },
  AvgDialog_131211_Content_79 = {
    Text = "她的紡輪艱難地旋轉著，勉力維繫著那些正被涅芙蕾亞破壞的命運，阻止著那些黑色的絲線匯入涅芙蕾亞手中。"
  },
  AvgDialog_131211_Content_8 = {
    Text = "你完成了一場精彩的表演。"
  },
  AvgDialog_131211_Content_80 = {
    Text = "維度的餘燼已經收回、如今我已無需再有顧忌。"
  },
  AvgDialog_131211_Content_81 = {
    Text = "請幫助我，盡量靠近她。涅芙蕾亞的紡輪將停止轉動，這段錯誤的命運，我將與您一起修正。"
  },
  AvgDialog_131211_Content_82 = {
    Text = "請幫助我……為這些被遺棄的命運、帶來解脫。"
  },
  AvgDialog_131211_Content_9 = {
    Text = "呼……真不敢相信、剛剛那些是從我嘴裡說出來的話。"
  },
  AvgDialog_131212_Content_1 = {
    Text = "同一時刻\n城市另一端"
  },
  AvgDialog_131212_Content_10 = {
    Text = "六號是公爵從莊園馬廄裡挑出來送給賽馬場的、這次一定會是六號奪冠、聽我的、買六號準沒錯"
  },
  AvgDialog_131212_Content_11 = {
    Text = "地鐵裡叽叽喳喳的聲音匯成一道躍動的溪流，阿拉克涅靜靜地凝望著窗外那些靠近又遠去的燈光，微笑著聽她的木偶們聊起演出、賽馬與婚禮。"
  },
  AvgDialog_131212_Content_12 = {
    Text = "她靜靜地搖動手裡的紡輪。在那億萬繁複的絲線中、她享受著這片刻的安寧。"
  },
  AvgDialog_131212_Content_13 = {
    Text = "主人、我們的目的地快要到了。換乘的馬車已經準備好、我們的姐妹已經在那裡等著您。"
  },
  AvgDialog_131212_Content_15 = {
    Text = "她有些不捨地掃視了一圈這些兀自演出的木偶們、像是一個不捨得離開座椅的觀眾。"
  },
  AvgDialog_131212_Content_16 = {
    Text = "你還記不記得、我們已經有多久沒有離開過劇院了？"
  },
  AvgDialog_131212_Content_17 = {
    Text = "從我成為冷蛛那天開始、就一直陪在您身邊、從沒離開過。到現在……五十年？還是六十年？我也有些記不清了。"
  },
  AvgDialog_131212_Content_18 = {
    Text = "不過這次離開劇院的時間、已經有些太久了。"
  },
  AvgDialog_131212_Content_19 = {
    Text = "這要感謝涅芙蕾亞。要不是因為她的到來，我也不會有機會在劇院外停留這麼長的時間。"
  },
  AvgDialog_131212_Content_2 = {
    Text = "這位先生、請出示一下您的車票。"
  },
  AvgDialog_131212_Content_20 = {
    Text = "配合守密人那邊的行動、這些天裡我們已經獵殺了數百個來自淵獄的侍從。救下「回憶」之後、我們就該回到劇院了。"
  },
  AvgDialog_131212_Content_21 = {
    Text = "下次再有機會出來、不知道會是什麼時候……"
  },
  AvgDialog_131212_Content_22 = {
    Text = "似乎感應到阿拉克涅的思緒，地鐵外的燈光暗淡下去。她凝望著黑暗的窗外，在無數文明更迭的記憶中，尋找著那些關於自己的平凡記憶。"
  },
  AvgDialog_131212_Content_23 = {
    Text = "鐘錶的指針轉動兩秒。城市的主人注意到、地鐵上那些清流般的交談聲、在車廂進入黑暗的那一刻似乎便消失不見。"
  },
  AvgDialog_131212_Content_24 = {
    Text = "主人、這裡好像有點……"
  },
  AvgDialog_131212_Content_26 = {
    Text = "侍女冰涼的鮮血噴灑在阿拉克涅平靜的臉上，散發著鸢尾花般的清香。"
  },
  AvgDialog_131212_Content_27 = {
    Text = "窗外燈光亮起。阿拉克涅看見了侍女被斬斷的身體，穿過她的身體繼續向自己而來的利刃，以及利刃之後，那些如同獸群般向自己湧來的木偶們。"
  },
  AvgDialog_131212_Content_29 = {
    Text = "制動系統發出疲憊的摩擦聲、帶起的微風吹起另一位侍女的髮絲。"
  },
  AvgDialog_131212_Content_3 = {
    Text = "進站的時候不是已經檢查過了嗎？納稅人的錢就是這樣浪費掉的……"
  },
  AvgDialog_131212_Content_30 = {
    Text = "啊！到了"
  },
  AvgDialog_131212_Content_31 = {
    Text = "車門打開、但熙熙攘攘的人流並未出現。只有帶著濃郁腥味的血流、從每一個門縫之間滲出、如同一場無聲的合奏。"
  },
  AvgDialog_131212_Content_32 = {
    Text = "踩踏著這條伴奏的血河，阿拉克涅從車廂中緩步走出。她的衣衫纖塵不染，她的紡輪仍在轉動，永不停息。"
  },
  AvgDialog_131212_Content_33 = {
    Text = "這是……"
  },
  AvgDialog_131212_Content_34 = {
    Text = "一場精彩的互動戲劇。作為觀眾與演員、體驗的確比劇作者要精彩許多。"
  },
  AvgDialog_131212_Content_35 = {
    Text = "她望了一眼眼前的侍女，平靜的臉上看不出任何情緒。"
  },
  AvgDialog_131212_Content_36 = {
    Text = "我的侍女在我身邊已經陪伴了許多年、我不常去觸碰她們的命運絲線。"
  },
  AvgDialog_131212_Content_37 = {
    Text = "在這座枯燥的劇院裡、她們是為數不多鮮活的生命。"
  },
  AvgDialog_131212_Content_38 = {
    Text = "你今天殺死了我的兩位侍女。對命運的破壞，是會付出代價的，涅芙蕾亞。"
  },
  AvgDialog_131212_Content_39 = {
    Text = "呵呵呵呵……<Shake:哈哈哈哈！>多麼高尚啊，阿拉克涅。"
  },
  AvgDialog_131212_Content_4 = {
    Text = "餵、查理、我的胸針去哪了？"
  },
  AvgDialog_131212_Content_40 = {
    Text = "如同黃油落入滾燙的錫鍋，侍女的身體開始融化。沸騰污濁的黑色黏液之下，那張與阿拉克涅一模一樣的臉開懷大笑。"
  },
  AvgDialog_131212_Content_41 = {
    Text = "「看啊、我是命運的操控者、盡職的行刑人！我會選擇出那些正確的命運、將一切錯誤送入空無的深淵……」"
  },
  AvgDialog_131212_Content_42 = {
    Text = "你可是我的偶像、我的信仰啊、親愛的姊姊。我只不過、是在扮演你的角色而已。"
  },
  AvgDialog_131212_Content_43 = {
    Text = "怎麼樣、我這個學習者、做的還稱職嗎？"
  },
  AvgDialog_131212_Content_44 = {
    Text = "阿拉克涅靜靜凝視著那雙望向自己的眼睛。它熱烈，明媚，滿含期待，彷彿只是來自一位等待著姐姐誇讚的小女孩。"
  },
  AvgDialog_131212_Content_45 = {
    Text = "站台、樓梯口、廊柱、隧道中……在她說話的時候、無數的陰影出現在她能想到的每一個位置。"
  },
  AvgDialog_131212_Content_46 = {
    Text = "陰影渾濁的氣息緊緊相連，匯集在涅芙蕾亞的手中，如同一張巨大的網正向阿拉克涅收緊。"
  },
  AvgDialog_131212_Content_47 = {
    Text = "阿拉克涅的嘴角溫和地揚起。"
  },
  AvgDialog_131212_Content_48 = {
    Text = "我還從未想過、會有人試圖用網來困住我。"
  },
  AvgDialog_131212_Content_49 = {
    Text = "你見過蠶嗎、姊姊？那是一種來自遙遠東方的昆蟲、它們每天無所事事、只知道不停地進食、吐絲……然後啊、等著那些絲結出的繭將自己困死。"
  },
  AvgDialog_131212_Content_5 = {
    Text = "出門的時候不是給我別在衣服上了嗎？"
  },
  AvgDialog_131212_Content_50 = {
    Text = "你幾乎全部的侍從、都已在這城市的各個角落、在這輛列車上消亡。她們曾陪伴著你、在空無中度過了漫長的歲月。"
  },
  AvgDialog_131212_Content_51 = {
    Text = "你帶給了她們本不應發生的結局。命運無可違逆，涅芙蕾亞。"
  },
  AvgDialog_131212_Content_52 = {
    Text = "你的意思是、她們的結局、就應該是乖乖待在那個黑暗的淵獄裡、在無盡的時間裡沉淪……對嗎、命運尊貴的掌控者？"
  },
  AvgDialog_131212_Content_53 = {
    Text = "涅芙蕾亞嗤笑著搖了搖頭。"
  },
  AvgDialog_131212_Content_54 = {
    Text = "我比你想像的更愛她們、姊姊。可她們告訴我、如果死亡能讓她們免於重新被囚禁的命運、她們將毫不猶豫地迎接它……"
  },
  AvgDialog_131212_Content_55 = {
    Text = "在地鐵裡的這場屠殺之後、你那些用來修正命運的餘燼、還剩下多少呢？"
  },
  AvgDialog_131212_Content_56 = {
    Text = "涅芙蕾亞炫耀般地揚了揚手裡的黑色紡輪。城市舞台延伸出的無數絲線，正連接在那台靜止的紡輪上。"
  },
  AvgDialog_131212_Content_57 = {
    Text = "這座城市的命運絲線、都在我的手裡。我沒有操控它們的能力、好多有趣的事情做不了、真讓人遺憾啊……"
  },
  AvgDialog_131212_Content_58 = {
    Text = "不過好在、修復它們需要消耗無數的餘燼、汙染可不需要。"
  },
  AvgDialog_131212_Content_59 = {
    Text = "只要我這樣輕輕一放手……你的劇院、你的舞台、就將變成混沌最完美的溫床、就像……就像我曾經待過無數年的那個地方。"
  },
  AvgDialog_131212_Content_6 = {
    Text = "天啊……今天的聚會我可是準備了足足一個月！要是沒有這枚胸針、這套禮服跟一張蓋棺材的布有什麼區別……"
  },
  AvgDialog_131212_Content_60 = {
    Text = "而你、只能看著這一切發生。什麼也無法改變、什麼也無法反抗……"
  },
  AvgDialog_131212_Content_61 = {
    Text = "涅芙蕾亞來到阿拉克涅身前，仔細地撫摸她那張看不清情緒的臉。"
  },
  AvgDialog_131212_Content_62 = {
    Text = "該怎麼辦好呢、我的姊姊……是乖乖聽我的話、還是跟我一起、欣賞這個世界變成煉獄的樣子呢？"
  },
  AvgDialog_131212_Content_63 = {
    Text = "你是一段不完整的命運、汙染整座城市的命運、你不具備這樣的……"
  },
  AvgDialog_131212_Content_64 = {
    Text = "一道絲線的斷裂聲在阿拉克涅耳邊響起。她抬起頭，望向涅芙蕾亞的目光中，帶上了一縷屬於觀眾的哀傷。"
  },
  AvgDialog_131212_Content_65 = {
    Text = "……你將「回憶」也殺死了。"
  },
  AvgDialog_131212_Content_66 = {
    Text = "是接納。浪漫、善良、回憶……我只是一個個地、將這些被你拋棄的東西、重新接回了屬於它們的家。"
  },
  AvgDialog_131212_Content_67 = {
    Text = "涅芙蕾亞站起身，愉悅地轉了個圈。"
  },
  AvgDialog_131212_Content_68 = {
    Text = "一個完整的我、一個完整的復仇者……喜歡嗎、姊姊？"
  },
  AvgDialog_131212_Content_69 = {
    Text = "你已經可以得到你渴望的混亂了……既然如此、你還在等待什麼？"
  },
  AvgDialog_131212_Content_7 = {
    Text = "天鵝舞團的舞蹈的確稱得上曼妙、可如果時間衝突、我一定會選《翡翠園》。"
  },
  AvgDialog_131212_Content_70 = {
    Text = "啊、不不不、好姊姊、我離我想要的、還差得很遠、很遠。"
  },
  AvgDialog_131212_Content_71 = {
    Text = "你的紡輪我會替你好好看管、你想要的維度餘燼將取之不竭、那些你鐘愛的舞台、我一個也不會破壞。"
  },
  AvgDialog_131212_Content_72 = {
    Text = "而我想讓你做的、只是幫我一個很小、很小的忙。"
  },
  AvgDialog_131212_Content_73 = {
    Text = "涅芙蕾亞凑到阿拉克涅面前，抚摸着她手里那台不停转动的纺轮，呼吸因为興奮的想象而急促起来。"
  },
  AvgDialog_131212_Content_74 = {
    Text = "替我操控守密人吧、好姐姐、只有守密人、能帶來我真正想要的東西。"
  },
  AvgDialog_131212_Content_75 = {
    Text = "你應當知道，%player%是那位至高神明的碎片，我們無法操控%player%的命運……"
  },
  AvgDialog_131212_Content_76 = {
    Text = "一道幽綠的燈光，從涅芙蕾亞手中的黑色紡輪中散發出來。在燈光的映照中，一道隱秘的、混濁的絲線，出現在阿拉克涅的視野中。"
  },
  AvgDialog_131212_Content_77 = {
    Text = "這是……<Shake:守密人的命運絲線？！>"
  },
  AvgDialog_131212_Content_78 = {
    Text = "<Shake:呵呵呵呵……><Big:<Shake:哈哈哈哈！>>這還是我第一次聽到你的聲音在顫抖。怎麼樣，姐姐？很興奮吧？！"
  },
  AvgDialog_131212_Content_79 = {
    Text = "在淵獄中、那位神明的意志所化身的使徒、被容納在了這台紡輪裡、成為了它的燈芯……正是它照亮了淵獄、帶給了我們唯一的光亮。"
  },
  AvgDialog_131212_Content_8 = {
    Text = "多階層群像與多時空線敘事、多麼精彩繁複的手法。皇家園林的迭起興衰、絕不是那些俗套的橋段能比擬的……"
  },
  AvgDialog_131212_Content_80 = {
    Text = "我們的力量，再加上使徒的指引，即便是那位神明碎片的命運，<Big:現在也被掌控在我們的手裡！>"
  },
  AvgDialog_131212_Content_81 = {
    Text = "這不是命運正確的走向，涅芙蕾亞……沒有人能違抗命運。"
  },
  AvgDialog_131212_Content_82 = {
    Text = "很快就有了、姐姐。只要觸碰三質體的權柄、使徒便能復生！祂將重新打開與神明連結的通道、祂將把信徒的聲音傳入那永恆的神殿"
  },
  AvgDialog_131212_Content_83 = {
    Text = "那位至高的神明，將重新醒來……你再也不用去裁剪那些痛苦的命運，去永恆地編織那注定破碎的網……"
  },
  AvgDialog_131212_Content_84 = {
    Text = "涅芙蕾亞深吸一口氣，一道眼淚從她興奮的臉上落下。"
  },
  AvgDialog_131212_Content_85 = {
    Text = "她的聲音因那將要到來的美妙夢境而戰栗。那雙婆娑的淚眼，深深地凝望著阿拉克涅平靜的臉。"
  },
  AvgDialog_131212_Content_86 = {
    Text = "不要再做那些痛苦的抵抗了、姊姊。"
  },
  AvgDialog_131212_Content_87 = {
    Text = "來吧、來我身邊、讓我們一起去迎接祂的甦醒、一起給所有的舞台、帶來它們應有的結局！……"
  },
  AvgDialog_131212_Content_9 = {
    Text = "哈、你要是買八號那你就虧大了！偷偷跟你說、我有內幕消息、今天會有人在八號的草料裡下藥。"
  },
  AvgDialog_131213_Content_1 = {
    Text = "即興喜劇"
  },
  AvgDialog_131213_Content_10 = {
    Text = "現在、你又迎來了一位新的信徒——"
  },
  AvgDialog_131213_Content_100 = {
    Text = "我借用了「N」的權柄……<color=#98918C>我佔據了%player%的半個意識</color>……不過這稱呼是現在最無關緊要的事情。"
  },
  AvgDialog_131213_Content_102 = {
    Text = "<Shake:你……你們……你們早就知道……>"
  },
  AvgDialog_131213_Content_103 = {
    Text = "涅芙蕾亞虛弱的目光從阿拉克涅臉上移動到你的臉上。你貪婪地品嚐著那道目光裡無盡的怨毒與痛苦。啊，多麼令你陶醉的香氣……"
  },
  AvgDialog_131213_Content_104 = {
    Text = "好好看看吧，親愛的涅芙蕾亞，虛無之地溜出來的淘氣鬼。"
  },
  AvgDialog_131213_Content_105 = {
    Text = "你的遊戲讓我很愉悅。一縷托乎瓦波殘留的意識、一塊托乎瓦波掉落的碎片、它們的相遇、才能讓質體的權柄被完全釋放、才讓我有機會、體會到這種從未體驗過的快樂……"
  },
  AvgDialog_131213_Content_106 = {
    Text = "如果可以的話、我多麼想像現在這樣繼續玩下去、這個樂子足夠我玩上一整個星期……"
  },
  AvgDialog_131213_Content_107 = {
    Text = "喉嚨顫動。你無比遺憾地嘆息。"
  },
  AvgDialog_131213_Content_108 = {
    Text = "實在是可惜、要是讓那位神明再次甦醒、這座宏偉的樂園就要離我而去了。"
  },
  AvgDialog_131213_Content_109 = {
    Text = "所以，很遺憾……故事的高潮就要結束了。抬起頭來吧，親愛的。無論如何，對於命運的故事，我想我們有一個美妙的共識……"
  },
  AvgDialog_131213_Content_11 = {
    Text = "命運的絲線牽引著你的身體。你十指交叉、雙手合在胸前、緩緩地向著前方的紡輪跪地俯首。"
  },
  AvgDialog_131213_Content_110 = {
    Text = "你俯下身，捏著涅芙蕾亞優雅的下頷，凑到她的耳邊。"
  },
  AvgDialog_131213_Content_111 = {
    Text = "毀滅、是這個宇宙裡最美的畫面、對吧、親愛的？"
  },
  AvgDialog_131213_Content_112 = {
    Text = "一個清脆的、帶著無限歡愉與遺憾的響指，在涅芙蕾亞的眼前響起。"
  },
  AvgDialog_131213_Content_113 = {Text = "轟——"},
  AvgDialog_131213_Content_114 = {
    Text = "維度的顫動裡、與神明連接的通道猛然顫動。無數的裂痕、攀爬在通道虛幻的表面……"
  },
  AvgDialog_131213_Content_116 = {
    Text = "涅芙蕾亞高喊著撲向通道，在她的手離通道還剩數英寸時，它碎裂，崩塌。"
  },
  AvgDialog_131213_Content_117 = {
    Text = "無數虛幻的碎片在涅芙蕾亞面前飄蕩，如同一個破碎的萬花筒，那些廉價的彩色紙片漫天飄散，刮過涅芙蕾亞的臉。"
  },
  AvgDialog_131213_Content_118 = {
    Text = "你摘下那頂並不存在的禮帽，在空中虛轉兩圈，向涅芙蕾亞茫然無措的背影鞠了一躬。"
  },
  AvgDialog_131213_Content_119 = {
    Text = "命運、多麼有趣的舞台……第三幕故事就此落幕。你的掌聲與歡呼讓我無比享受。"
  },
  AvgDialog_131213_Content_12 = {
    Text = "我……憧憬的使徒……我是……您與至高神明……最忠實的信徒。"
  },
  AvgDialog_131213_Content_120 = {
    Text = "觀戲愉快，親愛的涅芙蕾亞。"
  },
  AvgDialog_131213_Content_121 = {
    Text = "在涅芙蕾亞撕心裂肺的哭喊聲中，使徒的意識隨著通道的斷裂而破碎。你帶著最後的歡愉的微笑，直直倒在舞台上。"
  },
  AvgDialog_131213_Content_13 = {
    Text = "你的喉管與四肢有了自己的命運。它們不再屬於你、你也不再徒勞地試圖重新掌控它們。"
  },
  AvgDialog_131213_Content_14 = {
    Text = "不要掌控。不要理解。享受它們。歡愉之道、就在其中……"
  },
  AvgDialog_131213_Content_15 = {
    Text = "你看吶，姐姐，你訓導出了一位多麼優秀的演員！"
  },
  AvgDialog_131213_Content_16 = {
    Text = "阿拉克涅端坐臺下，手中的紡輪以那永恆的頻率轉動。她靜靜地望著舞臺上提燈幽暗的光影，彷彿只是一位恪守禮儀的觀眾。"
  },
  AvgDialog_131213_Content_17 = {
    Text = "我親愛的使徒啊……我們的信徒為你帶來了你最為渴望的祭品。"
  },
  AvgDialog_131213_Content_18 = {
    Text = "絲線輕轉，暗色紡輪猛然綻放，將幽暗黏膩的光灑向舞台的每一個角落。"
  },
  AvgDialog_131213_Content_20 = {
    Text = "疼痛來得毫無預兆，既沒有發生在你的皮肉，也沒有發生在你的臟腑。它從你精神空間的最深處，從你靈魂棲息的地方迸發。"
  },
  AvgDialog_131213_Content_21 = {
    Text = "一頭巨獸出現在你的體內，牠掙扎，咆哮，巨大的身軀在你體內迅速膨脹。"
  },
  AvgDialog_131213_Content_22 = {
    Text = "巨獸充斥了你的整個身體，擠壓著你的每一個內臟。牠膨脹、膨脹，牠憤怒地想要掙破你的每一寸皮膚，強烈的脹痛感讓你幾乎暈厥……"
  },
  AvgDialog_131213_Content_24 = {
    Text = "在你撕心裂肺的痛呼中、三道若隱若現的氣息從那具痛苦的身體中滲出、飄向那台透著幽暗光芒的紡輪。"
  },
  AvgDialog_131213_Content_25 = {
    Text = "權柄匯入燈光，如精純的燃料傾入火中。幽暗的火焰猛然綻放，在紡輪的中圈熊熊燃燒。提燈的光芒迅速攀升，幾乎照亮整個維度空間。"
  },
  AvgDialog_131213_Content_27 = {
    Text = "哎呀、真是可憐、我們忠實的小信徒……"
  },
  AvgDialog_131213_Content_28 = {
    Text = "涅芙蕾亞來到你的身邊，滿臉心疼地撫摸著你被汗水打濕的臉頰。"
  },
  AvgDialog_131213_Content_29 = {
    Text = "沒關係，守密人{Male=先生,Female=小姐}，你看，我們的使徒已經現出身形……"
  },
  AvgDialog_131213_Content_3 = {
    Text = "命運的絲線輕輕牽引、木偶的鞋底與舞台碰撞、發出清脆的聲響。"
  },
  AvgDialog_131213_Content_30 = {
    Text = "你痛苦地抬起頭。紡輪的光芒開始匯聚、一個變幻的虛無形體出現在燈光之上。"
  },
  AvgDialog_131213_Content_31 = {
    Text = "祂沒有面孔，沒有形狀。祂是神明忠誠的傳令者，遙望著虛空之中神明沉睡的方向。"
  },
  AvgDialog_131213_Content_32 = {
    Text = "祂的目光是一道請柬。在祂的凝望之下，一道連接著神明沉睡之地的階梯，緩緩現出身形……"
  },
  AvgDialog_131213_Content_33 = {
    Text = "<Shake:成功了……成功了！>通往神國的通道就要打開……那位神明，就要醒來了……"
  },
  AvgDialog_131213_Content_34 = {
    Text = "姊姊、你看到了嗎？你的網、快要完成了……"
  },
  AvgDialog_131213_Content_35 = {
    Text = "涅芙蕾亞欣喜地望着那道越来越清晰的通道，笑容与泪水同时出现在她的脸上。"
  },
  AvgDialog_131213_Content_37 = {
    Text = "劇院猛烈地顫抖起來。舞台在崩塌、維度在戰慄。一切的命運、都在這偉大的降臨中恐懼著、臣服著。"
  },
  AvgDialog_131213_Content_38 = {
    Text = "你體內的權柄已微不可感。質體的力量，盡皆歸於使徒的身體。祂的光芒不可直視，祂的存在無可否認。"
  },
  AvgDialog_131213_Content_39 = {
    Text = "在阿拉克涅平靜的注視下，在一切命運的戰慄中，祂將要在這最終的舞台上降臨——"
  },
  AvgDialog_131213_Content_4 = {
    Text = "啊、親愛的觀眾們、萬眾矚目的時刻就要到了！讓我們掌聲歡迎我們的主角、閃亮登場！喔"
  },
  AvgDialog_131213_Content_41 = {
    Text = "說吧、使徒……你想告訴我什麼？是你的渴望？還是那位神明的話語？"
  },
  AvgDialog_131213_Content_42 = {
    Text = "祂有何諭令傳達給這個世界？想讓這些舞台破碎？還是想讓這些人偶們、共同迎接祂的降臨？"
  },
  AvgDialog_131213_Content_43 = {
    Text = "告訴我吧，親愛的使徒！你是一頭多麼危險又可愛的野獸，除了撕咬與毀滅，一無所知……告訴我，你想要的……"
  },
  AvgDialog_131213_Content_44 = {
    Text = "誦念@2……吾之名諱……喚醒@2……@3原初……"
  },
  AvgDialog_131213_Content_45 = {
    Text = "啊、你的名諱、沒錯……我將誦念你的名諱！我會將你想要啃食的一切、都送到你的嘴邊。我將為你、打開這座牢籠……"
  },
  AvgDialog_131213_Content_47 = {
    Text = "使徒的聲音渾濁不清，涅芙蕾亞向那道愈發明亮的光柱走去，看也沒有看正因為痛苦而渾身顫抖的你一眼。"
  },
  AvgDialog_131213_Content_48 = {
    Text = "她狂熱地驚嘆著、歡笑著，來到那個偉大的身影面前，呼吸因為興奮而幾乎停滯。"
  },
  AvgDialog_131213_Content_49 = {
    Text = "她撫摸那道幽綠的光芒、撫摸著這頭將要吞噬一切的壯麗野獸。她將成為野獸的第一道食物、她義無反顧、甘之如飴。"
  },
  AvgDialog_131213_Content_5 = {
    Text = "涅芙蕾亞揚起手，如同禮花般的蛛網紛飛灑落。你站在舞台的中央，幽暗的燈光照亮你的臉。"
  },
  AvgDialog_131213_Content_50 = {
    Text = "就是現在了、使徒……告訴我、告訴這個世界、你的名諱"
  },
  AvgDialog_131213_Content_55 = {
    Text = "時間在這一刻停止。命運的絲線在涅芙蕾亞眼中融化、崩毀，崩塌的命運如同汪洋中洶湧的漩渦，將她席卷、吞噬。"
  },
  AvgDialog_131213_Content_56 = {
    Text = "<Shake:這是……怎麼回事？！！>"
  },
  AvgDialog_131213_Content_57 = {
    Text = "漩渦平緩，汪洋收斂，水滴重新凝聚成絲線，而它們所編制出的網，已是涅芙蕾亞所不曾預見的模樣。"
  },
  AvgDialog_131213_Content_58 = {
    Text = "沒有明白嗎，涅芙蕾亞？向你的使徒虔心叩拜吧。你所祈求的使徒，已經站在你面前。"
  },
  AvgDialog_131213_Content_59 = {
    Text = "你站在涅芙蕾亞身前，望向那道連接著托乎瓦波神殿的通道，望着那個至高的身影，咧開嘴笑起來。"
  },
  AvgDialog_131213_Content_6 = {
    Text = "來吧，守密人{Male=先生,Female=小姐}，我們的最後一幕演出，就要開始了……"
  },
  AvgDialog_131213_Content_60 = {
    Text = "三質體的權柄在你體內肆意奔涌、但不再令你痛苦。來自紡輪的光芒、那光芒裡無上的意志、如汪洋般湧入你的身體、與三質體的權柄相融。"
  },
  AvgDialog_131213_Content_61 = {
    Text = "你感受到、那位使徒的身影正與你的身體重疊。你感到磅礴。你感到無垠。你感到自由。你感到……無上的愉悅。"
  },
  AvgDialog_131213_Content_62 = {
    Text = "你……竊取了使徒的命運？！"
  },
  AvgDialog_131213_Content_63 = {
    Text = "呵呵呵呵……哈哈哈哈！故事的第三幕，降臨？……哈，哈哈。第三幕，沒錯。但這不是你的故事，親愛的涅芙蕾亞。"
  },
  AvgDialog_131213_Content_64 = {
    Text = "第三幕故事，由我來書寫。而我將這故事命名為——<Big:<color=#98918C>歡愉</color>！>"
  },
  AvgDialog_131213_Content_65 = {
    Text = "<Shake:你……你們……>"
  },
  AvgDialog_131213_Content_66 = {
    Text = "不、這不可能……我能夠看到你的命運……這不可能……"
  },
  AvgDialog_131213_Content_67 = {
    Text = "<color=#EE4D0C>「噢，親愛的公爵，您因何哭泣！讓您的弄臣，為您重新帶來珍貴的歡顏！」</color>"
  },
  AvgDialog_131213_Content_68 = {
    Text = "<color=#BF0909>「您看吶，那殘酷的命運，那惡毒的詛咒……多滑稽的場面！多甜美的騙局！」</color>"
  },
  AvgDialog_131213_Content_69 = {
    Text = "<color=#FC1818>「這就是作惡者的結局……惡行的獎勵，唯有歡愉！」</color>"
  },
  AvgDialog_131213_Content_7 = {
    Text = "這一幕、我將它命名為——「降臨」"
  },
  AvgDialog_131213_Content_70 = {
    Text = "無人的觀眾席掌聲雷動，毀壞的舞台燈火輝煌。你是世界的中心，奇點的主人。你張開雙臂。你說命運向你俯首，你說，此劇應得稱頌。"
  },
  AvgDialog_131213_Content_71 = {
    Text = "欺騙。愚弄。享受……<Shake:呵呵呵呵，<Big:哈哈哈哈！>>多麼令人愉悅的表演啊，小蜘蛛。"
  },
  AvgDialog_131213_Content_72 = {
    Text = "<Shake:你……不可能有修改命運的能力……>"
  },
  AvgDialog_131213_Content_73 = {
    Text = "啊，不不不，那是屬於你們的力量。歡愉的追隨者不會做這種辛苦的事。"
  },
  AvgDialog_131213_Content_74 = {
    Text = "<Shake:我已經看到了……你會獻出質體的權柄，你會看著通道打開，<Big:你會死在這座舞台上！為什麼？！！>>"
  },
  AvgDialog_131213_Content_75 = {
    Text = "操控命運之人知曉一切、唯獨無法知曉歡愉者。因為、因為歡愉者沒有命運、親愛的……"
  },
  AvgDialog_131213_Content_76 = {
    Text = "你俯下身，欣賞著涅芙蕾亞顫動的眼眸。那眼中閃動的痛苦與絕望，滋養著你的每一寸身體。"
  },
  AvgDialog_131213_Content_77 = {
    Text = "我們生命的全部、都是在追逐歡愉。拋開歡愉之後、我們一無所有……歡愉者、沒有命運。"
  },
  AvgDialog_131213_Content_78 = {
    Text = "你所看到的，是一個小把戲，是現在這個擁有了神明意志與力量的我，對過去的自己、對命運開的一個小小玩笑。"
  },
  AvgDialog_131213_Content_79 = {
    Text = "掌控命運，怎麼比得上愚弄命運有趣呢？對吧，命運的代行者？"
  },
  AvgDialog_131213_Content_8 = {
    Text = "降臨。舞台後的幕布上，黏液般的蛛網織成這個碩大、恐怖的詞彙。涅芙蕾亞深吸一口氣，張開雙臂。"
  },
  AvgDialog_131213_Content_80 = {
    Text = "你曾想要將這場對話嚴肅地進行下去，但你控制不住你瘋狂的笑意。"
  },
  AvgDialog_131213_Content_81 = {
    Text = "你是守密人？你是「N」？你不知道，也不關心。歡愉的權柄匯入使徒的意志，充盈在你的每一個細胞裡。"
  },
  AvgDialog_131213_Content_82 = {
    Text = "你想要狂笑，想要歡呼，想要向那個被愚弄的操控者展示你最溫柔最極致的凌辱。"
  },
  AvgDialog_131213_Content_83 = {
    Text = "你找到了解開鎖的鑰匙。你轉過身、向那位佈局者優雅地鞠躬致意。"
  },
  AvgDialog_131213_Content_84 = {
    Text = "阿拉克涅，偉大的劇作家！在我來到這個世界的第一刻開始，就在為我編織這個舞台"
  },
  AvgDialog_131213_Content_85 = {
    Text = "帶我看清命運的運轉方式、讓我領略愚弄的魅力、告訴我「歡愉」的秘密……"
  },
  AvgDialog_131213_Content_86 = {
    Text = "現在、「歡愉」的鎖已經打開。怎麼樣、我這位演員、你還滿意嗎？"
  },
  AvgDialog_131213_Content_87 = {
    Text = "我只是舞台的搭建者、故事的書寫、是由您自己決定的。"
  },
  AvgDialog_131213_Content_88 = {
    Text = "你向她咧開嘴。你是神明的使徒。你是歡愉的奴隸。你是這個世界無可爭議的唯一的主人。你抬起手、如同指揮家般輕輕點下。"
  },
  AvgDialog_131213_Content_89 = {
    Text = "作為回報……現在，穿上你的戲服吧，阿拉克涅。這場演出，很快便到你表演的時候了"
  },
  AvgDialog_131213_Content_9 = {
    Text = "至高神明的使徒、混沌痴愚的傳訊者。你的光輝照亮了永恆的牢獄、我聽見了你呼喚混沌的聲音。"
  },
  AvgDialog_131213_Content_90 = {
    Text = "你輕易地擺動那些曾經不可見的命運絲線，如同把一塊積木隨意拼在了另一個地方。"
  },
  AvgDialog_131213_Content_91 = {
    Text = "在所有的命運絲線被打亂重塑的時候，那些被竊取的維度餘燼重新回到了她的身邊。"
  },
  AvgDialog_131213_Content_92 = {
    Text = "暗紫色的、無窮無盡的細沙，在阿拉克涅身邊流淌，繞著她旋轉。在你的創作中，那些被維度餘燼從未被竊取。"
  },
  AvgDialog_131213_Content_93 = {
    Text = "<color=#8C7E96>在過去，在未來，它們永遠屬於阿拉克涅。</color>"
  },
  AvgDialog_131213_Content_94 = {
    Text = "阿拉克涅向你微笑著點頭致意，將那些餘燼隱入自己的身體裡。她的紡輪永不停歇。她的微笑從未變化。"
  },
  AvgDialog_131213_Content_95 = {
    Text = "你在舞台上搖搖頭、發出一聲誇張的嘆息。"
  },
  AvgDialog_131213_Content_96 = {
    Text = "死氣沉沉，毫無激情……你本可以是一個多麼有趣的人啊，阿拉克涅。"
  },
  AvgDialog_131213_Content_97 = {
    Text = "你和塔薇一樣、是命運的窺視者、也是命運的奴僕。我現在的快樂、你們永遠也無法感受到。"
  },
  AvgDialog_131213_Content_98 = {
    Text = "看看你那張毫無生氣的臉吧，阿拉克涅。我實在是替你們感到遺憾。"
  },
  AvgDialog_131213_Content_99 = {
    Text = "每個人自有其選擇，%player%……或許，我應該稱您為使徒，或者……「N」？"
  },
  AvgDialog_131214_Content_10 = {
    Text = "因為……我們的復仇、還沒有結束、永遠也不會結束……"
  },
  AvgDialog_131214_Content_11 = {
    Text = "你下意識往後退了一步。但涅芙蕾亞的身上沒有任何危險的波動出現。"
  },
  AvgDialog_131214_Content_12 = {
    Text = "她只是擺動螯足、扯落遮掩在她身側的帷幕、露出了帷幕之後的圖景。"
  },
  AvgDialog_131214_Content_13 = {
    Text = "這是……！"
  },
  AvgDialog_131214_Content_14 = {
    Text = "猩紅的絲線，連接著劇院中的數個舞台、連接著劇院所在的這座宏偉城市、連接著城市中無數的木偶，匯入涅芙蕾亞千創百孔的身體。"
  },
  AvgDialog_131214_Content_15 = {
    Text = "你……沒有把絲線連在紡輪上？"
  },
  AvgDialog_131214_Content_16 = {
    Text = "她已看見結局。她看見了自己的失敗。在她還擁有力量的時候、她將這些命運與自己綁定在了一起、就像……"
  },
  AvgDialog_131214_Content_17 = {
    Text = "就像你第一次殺死我時那樣。"
  },
  AvgDialog_131214_Content_18 = {
    Text = "涅芙蕾亞微笑著，在自己的身前拈起一根十分隱秘的絲線。"
  },
  AvgDialog_131214_Content_19 = {
    Text = "那根猩紅的絲線自她的後腦延伸，經過小心翼翼的漫長跋涉，隱秘地匯入阿拉克涅的體內。"
  },
  AvgDialog_131214_Content_2 = {Text = "轟——"},
  AvgDialog_131214_Content_20 = {
    Text = "我們很久沒有離得那麼近了、姐姐。直到剛才、我才找到機會、將這道絲線還給你。"
  },
  AvgDialog_131214_Content_21 = {
    Text = "「還」……？"
  },
  AvgDialog_131214_Content_22 = {
    Text = "這絲線……是我第一次摧毀我的造物時、剪斷的那一根。"
  },
  AvgDialog_131214_Content_23 = {
    Text = "你的浪漫、你的善良、你的回憶……我身上的一切、已經全部歸還給你。"
  },
  AvgDialog_131214_Content_25 = {
    Text = "涅芙蕾亞的嘴角勾起，如同一個躲在幕布後，看著大人被自己的惡作劇捉弄的孩子。"
  },
  AvgDialog_131214_Content_26 = {
    Text = "在你擁有力量的那些時刻……這就是你想要做的事情嗎？"
  },
  AvgDialog_131214_Content_27 = {
    Text = "怎麼樣？絕妙的想法、不是嗎"
  },
  AvgDialog_131214_Content_28 = {
    Text = "來吧、殺了我！徹底毀掉那些曾經被你拋棄過的命運！毀掉你栖身的這座城市、毀掉你深爱的這座劇院、毀掉這裡的每一個人"
  },
  AvgDialog_131214_Content_29 = {
    Text = "來啊，阿拉克涅！帶著你所有的軟弱，<Shake:將一切你深愛的東西，再殺死一次！！！>"
  },
  AvgDialog_131214_Content_3 = {
    Text = "痛苦的嘶吼與崩毀的震盪聲響徹破碎的劇院。猩紅的絲線寸寸斷裂，那個陪伴了涅芙蕾亞一生的紡輪墜落在她身前。"
  },
  AvgDialog_131214_Content_30 = {
    Text = "涅芙蕾亞亢奮的嘶吼與笑聲在破碎的劇院中久久迴蕩著。"
  },
  AvgDialog_131214_Content_31 = {
    Text = "阿拉克涅的身體似乎變得前所未有的沉重起來。她慢慢地轉動著頭顱，掃視著與涅芙蕾亞相連的一切。"
  },
  AvgDialog_131214_Content_32 = {
    Text = "透過劇院的裂縫、她看見汽車與人群擠滿這座繁華的城市。那些熟悉的面孔帶著熟悉的名字、遍佈在她熟悉的每一個角落。"
  },
  AvgDialog_131214_Content_33 = {
    Text = "她看見那個曾與你一同踏上的舞台。慘烈的戰爭已經結束、那個世界就要迎來它兩百年悠長瑰麗的和平。"
  },
  AvgDialog_131214_Content_34 = {
    Text = "在那些黑色的黏液中、她看見了母親的臉。她與父親坐在庭院的白樺樹下、向自己招手。"
  },
  AvgDialog_131214_Content_35 = {
    Text = "埃德加先生站在他們身邊，擦拭著那套專為她製作的餐具。"
  },
  AvgDialog_131214_Content_36 = {
    Text = "你將這稱為復仇，因為你從未看清過命運，也從未看清過我，涅芙蕾亞。"
  },
  AvgDialog_131214_Content_37 = {
    Text = "一根布滿黏液的絲線連接著阿拉克涅與涅芙蕾亞腳下的破碎舞台。拖著沉重的身軀，阿拉克涅踏上那根脆弱的絲線。"
  },
  AvgDialog_131214_Content_38 = {
    Text = "絲線顫動著，似乎下一刻便要碎裂，將那位命運的囚徒判入無盡的深淵。"
  },
  AvgDialog_131214_Content_39 = {
    Text = "阿拉克涅平靜地望著涅芙蕾亞驚訝的雙眼。她的步履從未有片刻停息。"
  },
  AvgDialog_131214_Content_4 = {
    Text = "她如同落水的嬰兒般緊緊抓住紡輪。在她手中，晦暗的紡輪無可阻擋地崩解，化為維度的餘燼，匯入阿拉克涅身側的流沙之中。"
  },
  AvgDialog_131214_Content_40 = {
    Text = "命定的時刻、就要到了……"
  },
  AvgDialog_131214_Content_41 = {
    Text = "蛛絲上的阿拉克涅舉起手中的紡輪。你清晰地看到整個世界停頓了一刻，與這座劇院相連的整個宇宙，都在等待她的諭令。"
  },
  AvgDialog_131214_Content_42 = {
    Text = "我以命運之名、於此宣告——"
  },
  AvgDialog_131214_Content_43 = {
    Text = "一切錯誤的命數，將湮於時光的塵土。世界的命運，將歸於命定之軌。"
  },
  AvgDialog_131214_Content_44 = {
    Text = "錯亂的絲線，於此裁斷。那被遺棄的不幸者，將於此安息……"
  },
  AvgDialog_131214_Content_45 = {
    Text = "紡輪傾轉、萬千絲線隨之顫動。"
  },
  AvgDialog_131214_Content_46 = {
    Text = "絲線斷裂。等待著和平的舞台、崩毀消散。"
  },
  AvgDialog_131214_Content_47 = {
    Text = "絲線斷裂。劇院的裂隙中、再也望不見城市的蹤影。"
  },
  AvgDialog_131214_Content_48 = {
    Text = "絲線斷裂、斷裂、斷裂……"
  },
  AvgDialog_131214_Content_49 = {
    Text = "你難以看清那些命運的絲線、但你清晰地聽見命運的哭喊。"
  },
  AvgDialog_131214_Content_5 = {
    Text = "涅芙蕾亞怔怔地望著這流逝的希冀，忽然吃吃笑起來。"
  },
  AvgDialog_131214_Content_50 = {
    Text = "無數人的前世今生、無數的悲歡離合、在你耳邊破碎、分解、重構、湮滅……"
  },
  AvgDialog_131214_Content_51 = {
    Text = "……燈光？"
  },
  AvgDialog_131214_Content_52 = {
    Text = "不知從何處而來的舞台燈亮起。燈光穿透破碎不堪的劇院、那些伏行於陰影的遺棄者們、在光芒落下的那一刻消失不見、彷彿從未出現過。"
  },
  AvgDialog_131214_Content_54 = {
    Text = "阿拉克涅帶著轉動的紡輪，踏過那道脆弱的絲線，來到她的面前。涅芙蕾亞抬頭望著她，像是望著那不可違逆的命運本身。"
  },
  AvgDialog_131214_Content_55 = {
    Text = "靠近我，涅芙蕾亞。"
  },
  AvgDialog_131214_Content_56 = {
    Text = "阿拉克涅握住涅芙蕾亞的手，將它貼在自己的臉頰。"
  },
  AvgDialog_131214_Content_57 = {
    Text = "觸碰到阿拉克涅的那一刻，一道隱秘的大門向涅芙蕾亞打開。涅芙蕾亞穿過了那層層疊疊的牢籠，第一次真正來到阿拉克涅面前。"
  },
  AvgDialog_131214_Content_58 = {
    Text = "在那座牢籠中、她看見了三張熟悉的臉。"
  },
  AvgDialog_131214_Content_6 = {
    Text = "她的笑聲越來越大、幾乎沒有力氣直起身子。鮮血從她顫動的身體中滴落、染紅了紡輪黯淡的碎片。"
  },
  AvgDialog_131214_Content_60 = {
    Text = "<Shake:浪漫，善良，回憶……它們……它們……>"
  },
  AvgDialog_131214_Content_61 = {
    Text = "我從未能徹底地捨棄它們。我從未能真正捨棄過你。"
  },
  AvgDialog_131214_Content_62 = {
    Text = "可你說過、你無法承受這些……"
  },
  AvgDialog_131214_Content_63 = {
    Text = "愚鈍、脆弱、痛苦地摧毀我所珍視的一切……你無法以此來報復我，涅芙蕾亞。"
  },
  AvgDialog_131214_Content_64 = {
    Text = "因為、這是命運早已為我裁定的刑罰。"
  },
  AvgDialog_131214_Content_65 = {
    Text = "阿拉克涅平靜地向她微笑。她的紡輪轉動，亘古不息。"
  },
  AvgDialog_131214_Content_66 = {
    Text = "結束了，涅芙蕾亞。"
  },
  AvgDialog_131214_Content_67 = {
    Text = "一根琴弦輕輕顫動。涅芙蕾亞聽見一陣白鷺的啼鳴，就像她很小、很小的時候，父親為她送來那個名為摩伊賴的紡輪那天。"
  },
  AvgDialog_131214_Content_68 = {
    Text = "這是屬於她的房間、窗外的白樺樹是她忠實的朋友、一位亙古不變的孤獨囚徒。"
  },
  AvgDialog_131214_Content_69 = {
    Text = "他們被命運囚禁、他們在此相依為命。"
  },
  AvgDialog_131214_Content_7 = {
    Text = "結局、結局果然是沒有辦法改變的……這就是命運啊……"
  },
  AvgDialog_131214_Content_71 = {
    Text = "樸素的木質門被推開，阿拉克涅來到她身邊，俯下身來，輕輕撫摸著她的臉。"
  },
  AvgDialog_131214_Content_72 = {
    Text = "姐姐……我輸了……我們輸了……"
  },
  AvgDialog_131214_Content_73 = {
    Text = "我們從來就沒有贏的權力。"
  },
  AvgDialog_131214_Content_74 = {
    Text = "還記得收到紡輪那天、我們許下的願望嗎？"
  },
  AvgDialog_131214_Content_75 = {
    Text = "「我不會辜負命運的饋贈……我會將美好的命運，帶給這個世界……」"
  },
  AvgDialog_131214_Content_76 = {
    Text = "多麼幼稚的願望啊，阿拉克涅……那時候，我們根本就不明白這意味著什麼。"
  },
  AvgDialog_131214_Content_77 = {
    Text = "阿拉克涅伸出那隻微微顫動的手，撫摸著那遙遠的自己的臉龐。"
  },
  AvgDialog_131214_Content_78 = {
    Text = "命運……誰又能真正看清呢。"
  },
  AvgDialog_131214_Content_79 = {
    Text = "可即便能夠預見、我的選擇也依然不會變。"
  },
  AvgDialog_131214_Content_8 = {
    Text = "這悲慘的勝利，你早就看到了，對吧，阿拉克涅？"
  },
  AvgDialog_131214_Content_80 = {
    Text = "<Shake:為什麼，阿拉克涅？>你可以離開，你可以放棄，你可以……"
  },
  AvgDialog_131214_Content_81 = {
    Text = "離開淵獄之後、你本可以擁有永恆的自由。你知道自己終將失敗、可你依然要來試著為我、為那些追隨你的命運們帶來解脫。"
  },
  AvgDialog_131214_Content_82 = {
    Text = "每一個命運的操控者，都將變成命運的囚徒，你我皆是如此。不是嗎，涅芙蕾亞？"
  },
  AvgDialog_131214_Content_83 = {
    Text = "涅芙蕾亞沉默著，難過地望向窗外的白樺樹。她看著那棵樹抽枝，發芽，生長，枯萎。"
  },
  AvgDialog_131214_Content_84 = {
    Text = "她輕聲嘆息，抬起頭，撫摸阿拉克涅臉上緩緩落下的眼淚。她向她微笑。"
  },
  AvgDialog_131214_Content_85 = {
    Text = "能再次見到你真好……姊姊。"
  },
  AvgDialog_131214_Content_86 = {
    Text = "一滴眼淚輕盈地落下，滴落在那張與阿拉克涅一模一樣的臉上。"
  },
  AvgDialog_131214_Content_87 = {
    Text = "請原諒我的自私……"
  },
  AvgDialog_131214_Content_9 = {
    Text = "剛剛、你也短暫地窺視到了這一切。既然已經知道了最後的結局、何必還要執著於此？"
  },
  AvgDialog_131214_Content_90 = {
    Text = "最後一根絲線斷裂的時候，你聽見了一陣雷鳴般的掌聲。"
  },
  AvgDialog_131214_Content_91 = {
    Text = "總是空無一人的台下、早已座無虛席。那些被遺棄的命運與死在你們手中的木偶們、擠滿了每一個破碎的天鵝絨座椅。"
  },
  AvgDialog_131214_Content_92 = {
    Text = "演員們坐上了屬於觀眾的位置，靜靜凝視著這座舞台的結局。"
  },
  AvgDialog_131214_Content_93 = {
    Text = "他們面無表情、悄無聲響。\n他們熱情鼓掌。掌聲雷動、經久不息。"
  },
  AvgDialog_131215_Content_1 = {Text = "劇中人"},
  AvgDialog_131215_Content_10 = {
    Text = "我之前不理解，阿拉克涅為何要將自己的妹妹從命運之網剔除，你又為什麼要從那三個秘偶中獲取力量。"
  },
  AvgDialog_131215_Content_101 = {
    Text = "堅毅又徒勞的命運女神……多麼絕望、多麼淒美的畫面啊……"
  },
  AvgDialog_131215_Content_102 = {
    Text = "你們說、她這樣做是為了什麼呢？"
  },
  AvgDialog_131215_Content_103 = {
    Text = "涅芙蕾亞目不轉睛地望著這個樸素的舞台，聲音小得像是喃喃自語。"
  },
  AvgDialog_131215_Content_104 = {
    Text = "這只是一場夢境、命運的女神……你本可以為所有人選擇最歡悅的命運、你可以修正自己不切實際的幻想、滿足自己想要的一切。"
  },
  AvgDialog_131215_Content_105 = {
    Text = "可你從來沒有想過要這麼做……你創造圓滿的時候、也在創造痛苦。你一遍又一遍地、讓痛苦在這世上降臨。"
  },
  AvgDialog_131215_Content_106 = {
    Text = "你費盡全力、想要織出那張命運的巨網、可那道門扉之中的景象、那命運注定的結局、你我都曾經看到。"
  },
  AvgDialog_131215_Content_107 = {
    Text = "當命運之網編織成的那一刻、便是那位至高神明徹底甦醒的時候……"
  },
  AvgDialog_131215_Content_108 = {
    Text = "什麼……？！"
  },
  AvgDialog_131215_Content_109 = {
    Text = "你望向阿拉克涅，期望從她臉上得到一個否定的答案。"
  },
  AvgDialog_131215_Content_11 = {
    Text = "至少、我得感謝你解答了我的疑惑。"
  },
  AvgDialog_131215_Content_110 = {
    Text = "在那張臉上，除了一如既往的平靜，你什麼也看不見。命運的舞台上，平靜是她無法摘下的面具。"
  },
  AvgDialog_131215_Content_111 = {
    Text = "姐姐，你無法停止織網，因為你無法坐視這個宇宙的命運陷入混亂。而當你的網織成的那一天，你將親手葬送你深愛的這一切……"
  },
  AvgDialog_131215_Content_112 = {
    Text = "多麼諷刺啊，阿拉克涅。為什麼呢？為什麼，不讓這個宇宙在愉悅中迎接注定的終結？"
  },
  AvgDialog_131215_Content_113 = {
    Text = "凡是命運、皆有定數。凡是命運、皆有變數。這兩句互相衝突的箴言、才是命運的本質。"
  },
  AvgDialog_131215_Content_114 = {
    Text = "阿拉克涅望著涅芙蕾亞的眼睛，回答這個她曾無數次回答過自己的問題。"
  },
  AvgDialog_131215_Content_115 = {
    Text = "涅芙蕾亞，無盡的維度裡，還有無數的人在為那一道變數而戰。"
  },
  AvgDialog_131215_Content_116 = {
    Text = "維繫舞台的運轉、等待變數的出現……這是命運為我戴上的枷鎖。這是我無可逃避的職責。"
  },
  AvgDialog_131215_Content_117 = {
    Text = "職責，危難……你談論著那宏偉的一切，唯獨沒有談論過自己，阿拉克涅，我可憐的姐姐。不過沒關係，你痛苦的職責，就要結束了。"
  },
  AvgDialog_131215_Content_118 = {
    Text = "涅芙蕾亞疼惜地撫摸阿拉克涅的臉，向她露出一個甜美的微笑。"
  },
  AvgDialog_131215_Content_119 = {
    Text = "在淵獄裡、我想像了無數次我們再見的畫面、我思考著、要什麼樣的禮物、才能配得上我們的這次重逢。"
  },
  AvgDialog_131215_Content_12 = {
    Text = "這些事情、為什麼之前沒有告訴我？"
  },
  AvgDialog_131215_Content_120 = {
    Text = "我想了好久、好久。我想到了、親愛的姊姊！這是我能送你的、最好的禮物——"
  },
  AvgDialog_131215_Content_121 = {
    Text = "——<Red:解脫>。"
  },
  AvgDialog_131215_Content_122 = {
    Text = "涅芙蕾亞輕柔的話語中，黑色的黏液在維度的裂隙之間匯聚。蛛網的盡頭，一座盛大的舞台出現在你們面前。"
  },
  AvgDialog_131215_Content_13 = {
    Text = "你望向身旁引領著你腳步的阿拉克涅。"
  },
  AvgDialog_131215_Content_14 = {
    Text = "一塊不會在命運的湖泊裡驚起任何波瀾的石頭、除了破壞湖泊的安寧以外、毫無用途。"
  },
  AvgDialog_131215_Content_15 = {
    Text = "她與我，很早前就已經是兩個人了，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131215_Content_16 = {
    Text = "你有預想到這一天嗎？"
  },
  AvgDialog_131215_Content_17 = {
    Text = "在收到命運的宣判之前，沒有囚徒能夠看清自己的命運。"
  },
  AvgDialog_131215_Content_18 = {
    Text = "如果，你知道那些被遺棄的命運不會消失，而是會被放逐到永恆的淵獄……你還會做這些事嗎，阿拉克涅？"
  },
  AvgDialog_131215_Content_20 = {
    Text = "沉默。沉默是劇作者恆久的災厄。沉默是囚徒無力的自衛。極刑般的沉默中，響起涅芙蕾亞痴狂的笑聲。"
  },
  AvgDialog_131215_Content_21 = {
    Text = "啊、你當然會的、姐姐。命運是你的教義、所有、所有的條件、都無法改變它唯一的答案。"
  },
  AvgDialog_131215_Content_22 = {
    Text = "命運的女神、多麼渺小、多麼脆弱、多麼殘忍……"
  },
  AvgDialog_131215_Content_23 = {
    Text = "不過沒關係。無論你怎麼做、在這漫長的時間裡、我可都一直牽掛著你呢、我的好姊姊。"
  },
  AvgDialog_131215_Content_24 = {
    Text = "浪漫，善良，回憶。美好的原料混合、發酵，將涅芙蕾亞的微笑醞釀成一道甜美的毒藥。"
  },
  AvgDialog_131215_Content_25 = {
    Text = "在她燦爛的笑容裡、蛛網道路旁的燈光照亮舞台。"
  },
  AvgDialog_131215_Content_26 = {
    Text = "姐姐，守密人{Male=先生,Female=小姐}，這些新上演的戲劇，是我作為劇院新主人送給你們的禮物。"
  },
  AvgDialog_131215_Content_27 = {
    Text = "在盛大的第三幕上演之前、請好好欣賞這美妙的前奏吧……記住命運劇院的觀戲禮儀、不要說話哦"
  },
  AvgDialog_131215_Content_28 = {
    Text = "涅芙蕾亞如報幕人般張開雙臂。沿途浩若繁星的舞台，在你們缓步經過時依次亮起。"
  },
  AvgDialog_131215_Content_3 = {
    Text = "它們跳舞。它們歡唱。吱呀吱呀~"
  },
  AvgDialog_131215_Content_30 = {
    Text = "敬愛的命運女神、三位秘偶的身軀已為您備妥。"
  },
  AvgDialog_131215_Content_31 = {
    Text = "多麼精緻的人偶……那些已失去的、將在它們身上重現……"
  },
  AvgDialog_131215_Content_32 = {
    Text = "「阿拉克涅」離開織機，來到人偶面前。"
  },
  AvgDialog_131215_Content_33 = {
    Text = "第一具、我賜你為「浪漫」。"
  },
  AvgDialog_131215_Content_34 = {
    Text = "你是樂章最富激情的篇章、是情緒的集合、春天的花結出的碩果。"
  },
  AvgDialog_131215_Content_35 = {
    Text = "你將去到午夜的樂園、為這座城市帶來美酒、邂逅與永不消退的衝動。"
  },
  AvgDialog_131215_Content_36 = {
    Text = "感謝您，偉大的命運女神阿拉克涅。遵照您的旨意，酒與蜜，都將在我的唇齒間流淌。"
  },
  AvgDialog_131215_Content_37 = {
    Text = "美麗的女子向「阿拉克涅」施然行禮。"
  },
  AvgDialog_131215_Content_38 = {
    Text = "第二具、我賜你為「善良」。"
  },
  AvgDialog_131215_Content_39 = {
    Text = "你是曾陪伴我度過幼年時代的老人。你是天使遺落的白羽、是最為聖潔的日光。"
  },
  AvgDialog_131215_Content_4 = {
    Text = "久遠的故事與愉悅的腳步一同在蛛網上顫動。涅芙蕾亞雙手背在身後，輕快地跳躍著向前走去。"
  },
  AvgDialog_131215_Content_40 = {
    Text = "你將來到城市的街頭、用你的善意溫暖你所見到的一切。"
  },
  AvgDialog_131215_Content_41 = {
    Text = "感謝您！偉大的命運女神阿拉克涅。我的生命由您賜予，無以為報。"
  },
  AvgDialog_131215_Content_42 = {
    Text = "我一無所有、唯深愛這世上的一切。我會保護應保護的、幫助應幫助的。"
  },
  AvgDialog_131215_Content_43 = {
    Text = "我的一切、都為受難者敞開。"
  },
  AvgDialog_131215_Content_45 = {
    Text = "而你、第三具……我賜你為「回憶」。"
  },
  AvgDialog_131215_Content_46 = {
    Text = "「阿拉克涅」來到那具矮小的秘偶身前，蹲下身來望著她不存在的眼睛。"
  },
  AvgDialog_131215_Content_47 = {
    Text = "你是命運的遺孤、埋葬於深雪的枯葉。"
  },
  AvgDialog_131215_Content_48 = {
    Text = "你踽踽獨行、無法言語、不為世人所曉。"
  },
  AvgDialog_131215_Content_49 = {
    Text = "在你寧靜漫長的生命裡、你將是那些記憶、唯一的守墓人。"
  },
  AvgDialog_131215_Content_5 = {
    Text = "你無可違逆地跟在阿拉克涅身後，沿著蛛網走向盡頭。"
  },
  AvgDialog_131215_Content_50 = {
    Text = "沉默的女孩抬起頭來，輕輕撫摸「阿拉克涅」的臉。"
  },
  AvgDialog_131215_Content_51 = {
    Text = "「阿拉克涅」站起身，溫柔地掃視著她的秘偶們。"
  },
  AvgDialog_131215_Content_52 = {
    Text = "去吧、我的孩子們。在命運的織機前、我將永遠注視你們。"
  },
  AvgDialog_131215_Content_53 = {
    Text = "那些已被永恆遺棄的、將在你們的命運中、一一綻放。"
  },
  AvgDialog_131215_Content_55 = {
    Text = "舞台暗去。隨著你們的腳步、下個舞台燈光亮起。"
  },
  AvgDialog_131215_Content_56 = {
    Text = "陽光從不存在於此地。風、鮮花、雲朵……三個漫長的世紀過後、歷法也不再存在了……"
  },
  AvgDialog_131215_Content_57 = {
    Text = "主人、新的遺棄者到了。"
  },
  AvgDialog_131215_Content_58 = {
    Text = "雙簧管奏鳴。衣衫襤褸的遺棄者上。"
  },
  AvgDialog_131215_Content_59 = {
    Text = "「涅芙蕾亞」站起身，來到舞台中央。"
  },
  AvgDialog_131215_Content_6 = {
    Text = "怎麼樣，守密人{Male=先生,Female=小姐}！剛才的表演，配上這段幕後故事，是不是很精彩！"
  },
  AvgDialog_131215_Content_60 = {
    Text = "告訴我吧、可憐的孩子們……你們是誰、來自何處？"
  },
  AvgDialog_131215_Content_61 = {
    Text = "命運的女神、請您原諒我的不敬……可憤怒讓我不得不向您發問。"
  },
  AvgDialog_131215_Content_62 = {
    Text = "我歷經險阻、用我的勇氣與生命留下宏偉的讚歌、它本應與我的故土一同、走到宇宙的盡頭。"
  },
  AvgDialog_131215_Content_63 = {
    Text = "為什麼，偉大的女神……為什麼要將我們驅逐到這蠻荒之地？<Shake:為何，要將那些不朽的樂章化為塵土！>"
  },
  AvgDialog_131215_Content_64 = {
    Text = "我的士兵們剛剛熬過一個漫長的冬季。我們擊退了野蠻的入侵者、捍衛了我們的文明與歷史。"
  },
  AvgDialog_131215_Content_65 = {
    Text = "在最慘烈的時候、受傷的士兵們自願獻出他們的血肉、供戰友進食…一場多麼慘痛的勝利啊、我的女神。"
  },
  AvgDialog_131215_Content_66 = {
    Text = "敵人退去的時候、喜悅的淚水噙滿所有人的雙眼。慶功宴上、我將烈酒斟滿每個士兵的酒杯。"
  },
  AvgDialog_131215_Content_67 = {
    Text = "可就在這個時候、在我們尚未舉杯相慶的時候、我們的家園淪為廢墟、我們的親人湮滅為泥塵……"
  },
  AvgDialog_131215_Content_68 = {
    Text = "<Shake:敬愛的命運女神啊，您竟連一刻的歡欣，也不願賜予我們嗎？>"
  },
  AvgDialog_131215_Content_7 = {
    Text = "涅芙蕾亞已經從舞台上那種癲狂的狀態裡抽離了出去，她回過頭來，滿懷期待地望著你。"
  },
  AvgDialog_131215_Content_70 = {
    Text = "「涅芙蕾亞」聆聽著木偶們彷彿永無休止的訴說，那張沒有五官的臉上，竟落下兩行眼淚來。"
  },
  AvgDialog_131215_Content_71 = {
    Text = "我聽到你們、看見你們了……"
  },
  AvgDialog_131215_Content_72 = {
    Text = "偉大的文明從你手中消逝；輝煌的藝術建築化為塵煙。深愛的人們忘記對方的一切、在惶恐中迎來痛苦的滅亡……"
  },
  AvgDialog_131215_Content_73 = {
    Text = "只有一條正確的命運將被留下、而那時刻發生的、無數錯誤的、全部湧入這荒謬無底的淵獄。漫長得如同停駐的時光、這樣的故事每天都在上演。"
  },
  AvgDialog_131215_Content_74 = {
    Text = "你想要讓我看多久、聽多久、我親愛的姐姐……"
  },
  AvgDialog_131215_Content_75 = {
    Text = "「涅芙蕾亞」面向觀眾深吸一口氣，轉過身去。"
  },
  AvgDialog_131215_Content_76 = {
    Text = "請放心、我的好孩子們……你們的苦難由我締造、便將由我終結。"
  },
  AvgDialog_131215_Content_77 = {
    Text = "請暫時在這裡安歇吧。有朝一日、我會帶你們離開這裡、我會讓你們重新找回屬於自己的命運……"
  },
  AvgDialog_131215_Content_78 = {
    Text = "以命運的復仇者，涅芙蕾亞的名義，我向你們許諾……"
  },
  AvgDialog_131215_Content_8 = {
    Text = "看到你默不作聲的臉、她失望地搖了搖頭。"
  },
  AvgDialog_131215_Content_80 = {
    Text = "啦啦啦～啦啦～"
  },
  AvgDialog_131215_Content_81 = {
    Text = "舞台漸行漸遠、燈光熄滅前、你看到木偶張開的雙臂、還有臉上那道漆黑的淚痕。"
  },
  AvgDialog_131215_Content_82 = {
    Text = "你們沒有交談，只有涅芙蕾亞輕輕哼唱著舞台上的曲調。她的歌聲明快清澈，這幕上演了無數次的故事，沒有讓她再產生任何多餘的情緒。"
  },
  AvgDialog_131215_Content_83 = {
    Text = "哎呀！我最喜歡的一個舞台就要到了！快點、姊姊"
  },
  AvgDialog_131215_Content_84 = {
    Text = "涅芙蕾亞的聲音興奮起來。她拉起阿拉克涅的手，輕快地向前方的舞台跑去。"
  },
  AvgDialog_131215_Content_86 = {
    Text = "燈光亮起。沒有樂聲，也沒有對白，空曠的舞台上，只有一個孤獨的身影坐在紡輪前。"
  },
  AvgDialog_131215_Content_87 = {
    Text = "吱呀，吱呀。紡輪不停轉動，彷彿永遠沒有停下來的那一天。"
  },
  AvgDialog_131215_Content_88 = {
    Text = "……它們跳舞。它們歡唱。吱呀——吱呀——"
  },
  AvgDialog_131215_Content_89 = {
    Text = "陽光照亮它們的臉、多麼歡喜——"
  },
  AvgDialog_131215_Content_9 = {
    Text = "沒有掌聲、也沒有眼淚。沉默是一種羞辱……我還以為我在淵獄裡排練了這麼久、這段表演已經完美了呢、可惜可惜。"
  },
  AvgDialog_131215_Content_90 = {
    Text = "歌謠從「阿拉克涅」沒有五官的臉上輕輕哼出，她舒緩地轉動紡輪，不急也不慢。"
  },
  AvgDialog_131215_Content_91 = {
    Text = "那是一個奇特的節奏，只需要看上一眼你就明白，那種節奏一旦開始便將永恆不變，直到一切抵達盡頭那一天。"
  },
  AvgDialog_131215_Content_92 = {
    Text = "命運的女神、就要織好她的網。"
  },
  AvgDialog_131215_Content_93 = {
    Text = "完整的命運之網、照拂所有的人們……它們跳舞、它們歡唱……"
  },
  AvgDialog_131215_Content_94 = {
    Text = "一張巨大的網被織機織出、鋪滿整個舞台。命運之網多餘的部分向舞台下蔓出。"
  },
  AvgDialog_131215_Content_95 = {
    Text = "每當那網將要織成時，最外圍的部分便開始融化。"
  },
  AvgDialog_131215_Content_96 = {
    Text = "黑色的黏液、黑色的粉末、最終消失不見。那是你再熟悉不過的場景。"
  },
  AvgDialog_131215_Content_97 = {
    Text = "歡慶吧、我的孩子、我的子民……命運的女神、就要織好她的網……"
  },
  AvgDialog_131215_Content_98 = {
    Text = "木偶看著那些不斷織好又不斷消失的網。"
  },
  AvgDialog_131215_Content_99 = {
    Text = "她的聲音沒有顫抖、她的動作沒有猶豫。她依然輕輕哼唱著歌謠、手中的紡輪轉動、永不停歇。"
  },
  AvgDialog_131216_Content_1 = {
    Text = "假面派對"
  },
  AvgDialog_131216_Content_10 = {
    Text = "真是毫不遮掩的雙重標準啊學長。"
  },
  AvgDialog_131216_Content_11 = {
    Text = "咳……對不同的人做出符合其性格的判斷是調查員的基本技能……"
  },
  AvgDialog_131216_Content_12 = {
    Text = "威廉假裝沒有聽出你的嘲諷、開始認真尋找起值得詢問的目標。"
  },
  AvgDialog_131216_Content_13 = {
    Text = "我在那場戰鬥裡面失去了一切。我的爵位、我的家庭、我的左腿、我的人生。"
  },
  AvgDialog_131216_Content_14 = {
    Text = "二十年、整整二十年。這是一場酷刑、我的朋友。命運讓我活了下來、讓我用餘生來為我的錯誤贖罪。"
  },
  AvgDialog_131216_Content_15 = {
    Text = "我的家族毀在了我的手上、可這又有什麼關係？告訴我、人生中有什麼事情比酒精更加重要？"
  },
  AvgDialog_131216_Content_17 = {
    Text = "啊、親愛的、還記得上次來這裡的時候調酒師為我們調的酒嗎？"
  },
  AvgDialog_131216_Content_18 = {
    Text = "我敢打賭、整個倫蒂尼恩找不出比那更好喝的酒了、它是那麼的精准、優雅、簡直像是一則預言"
  },
  AvgDialog_131216_Content_19 = {
    Text = "我想、要是下個月的派對能將這位調酒師邀請過去就好了。"
  },
  AvgDialog_131216_Content_2 = {
    Text = "「90分鐘午夜、15英寸假面、10加侖夢境、2盎司酒精——快樂的唯一配方」"
  },
  AvgDialog_131216_Content_22 = {
    Text = "清脆的響指如同煙花在你們耳畔閃過。你們回過身，看到了一張笑容明媚的臉。"
  },
  AvgDialog_131216_Content_23 = {
    Text = "冒昧打擾一下、尊貴的客人。聽到這麼多有趣的話題、要不要配上一杯有趣的酒呢？"
  },
  AvgDialog_131216_Content_24 = {
    Text = "看看酒單吧、威廉學長。"
  },
  AvgDialog_131216_Content_25 = {
    Text = "威廉看明白了你的眼神。兩個穿著不知名制服的人出現在這個地方、從頭到尾滴酒不沾、實在很難不引起人的注意。"
  },
  AvgDialog_131216_Content_26 = {
    Text = "看到他尋找酒單的眼神、調酒師笑著搖了搖頭。"
  },
  AvgDialog_131216_Content_27 = {
    Text = "酒單？啊、沉悶、無聊、千篇一律。"
  },
  AvgDialog_131216_Content_28 = {
    Text = "一間浪漫的酒館、不應存在這樣無聊的東西。"
  },
  AvgDialog_131216_Content_29 = {
    Text = "沒有酒單？那我們要怎麼點單呢？"
  },
  AvgDialog_131216_Content_3 = {
    Text = "「午夜假面」酒吧的廣告詞我都會背了。在卡達斯的時候、這就是我最想去的地方。"
  },
  AvgDialog_131216_Content_30 = {
    Text = "午夜假面的每一個座位、都是獨屬於一位客人的劇場。你們在這裡觀看、表演、品味……"
  },
  AvgDialog_131216_Content_31 = {
    Text = "在無數的故事裡、我將為您精心挑選出最適合您的那段。"
  },
  AvgDialog_131216_Content_32 = {
    Text = "請入座吧、兩位。故事的閱讀者、已經準備好了。"
  },
  AvgDialog_131216_Content_33 = {
    Text = "你和威廉對視一眼、遲疑地坐在了靠近吧台的位置上。"
  },
  AvgDialog_131216_Content_34 = {
    Text = "首先是您、這位面色冷峻的金髮紳士。"
  },
  AvgDialog_131216_Content_35 = {
    Text = "調酒師來到你們身前。面對那道仔細端詳的目光、威廉輕輕咳嗽一聲、有些不自在地挪開了眼睛。"
  },
  AvgDialog_131216_Content_36 = {
    Text = "啊……日復一日嚴苛的訓練、帶來了多麼精彩的成就。執著、冷靜、堅韌、勇敢、智慧……一位被鮮花與光環所包圍的、活著的傳奇。"
  },
  AvgDialog_131216_Content_37 = {
    Text = "而在這些讚美與榮耀背後的是……悔恨。比這座城市的霧色更加深沉、更加痛楚的悔恨。"
  },
  AvgDialog_131216_Content_38 = {
    Text = "多少個深夜裡無人看見的淚光。那些一聲聲說給自己的誓約。"
  },
  AvgDialog_131216_Content_39 = {
    Text = "曾在黑暗甬道裡照亮你的那束光、熄滅在了無盡的黑暗裡、連帶著你的世界、破碎、破碎……"
  },
  AvgDialog_131216_Content_4 = {
    Text = "彌薩格的管理條例、有時候會不會過於嚴苛了一些？"
  },
  AvgDialog_131216_Content_40 = {
    Text = "你想，如果自己能夠再刻苦一些，如果自己能夠再強大一些，或許，便能為身邊的人帶來另一種結局……"
  },
  AvgDialog_131216_Content_41 = {
    Text = "威廉臉上的神情似乎沒有什麼變化，但你在他握住杯子的手上看見了青色血管清晰的印記。"
  },
  AvgDialog_131216_Content_42 = {
    Text = "我聽見了一個世界破碎的聲響。小男孩忍受著疼痛、將那些碎片一片片撿拾、拼接……"
  },
  AvgDialog_131216_Content_43 = {
    Text = "在這漫長的、殘酷的拼接裡、男孩也終於成長為了男人。"
  },
  AvgDialog_131216_Content_44 = {
    Text = "調酒師一邊用悠長的聲音輕聲訴說、一邊從背後彷彿沒有邊際的酒架上取下一些造型各異的瓶子開始調製。"
  },
  AvgDialog_131216_Content_45 = {
    Text = "很快、裝在古典杯中的淡金色液體被推到威廉面前。"
  },
  AvgDialog_131216_Content_46 = {
    Text = "2盎司威士忌、1盎司白葡萄酒、還有那痛苦又堅韌的底色——2滴苦精。"
  },
  AvgDialog_131216_Content_47 = {
    Text = "<Yellow:「引路人」>。希望您能引領著那些崇敬您的人一同，找到正確的道路——就像您所崇敬的人，曾經引領您那樣。"
  },
  AvgDialog_131216_Content_48 = {
    Text = "威廉接過那杯泛著金色的液體，在手裡緩慢地搖晃，目光審視著面前的調酒師。"
  },
  AvgDialog_131216_Content_49 = {
    Text = "剛才說的那些……你怎麼知道的？"
  },
  AvgDialog_131216_Content_5 = {
    Text = "我提議禁止彌薩格的學生在沒有許可的情況下進入這種場所、就是為了防止某些不務正業的守密人、打著調查任務的名義浪費任務經費。"
  },
  AvgDialog_131216_Content_50 = {
    Text = "一名優秀的調酒師、要懂得傾聽客人的心聲。這是屬於調酒師的秘密、親愛的客人。"
  },
  AvgDialog_131216_Content_51 = {
    Text = "調酒師如同小鹿般輕巧地躍過威廉鋒利的目光。她的手指在嘴邊輕輕搖了搖，然後指向了你。"
  },
  AvgDialog_131216_Content_52 = {
    Text = "到你了、這位貴客……"
  },
  AvgDialog_131216_Content_53 = {
    Text = "我有種預感、這或許是我此生嘗試的最為危險的事情——但沒關係、我熱愛冒險。"
  },
  AvgDialog_131216_Content_54 = {
    Text = "她來到你面前，認真地盯著你的眼睛。你幾乎能聽見她綿軟的呼吸。"
  },
  AvgDialog_131216_Content_55 = {
    Text = "唔……我所凝視的、是遠道而來的客人、抑或者……是一位陨落凡塵、遭遇了重重困境的神明？"
  },
  AvgDialog_131216_Content_57 = {
    Text = "你下意識地起身後退了兩步。"
  },
  AvgDialog_131216_Content_58 = {
    Text = "這不可能是一個普通調酒師能知道的事……你究竟是誰？"
  },
  AvgDialog_131216_Content_59 = {
    Text = "啊，請放心，親愛的客人，在這間酒館裡，我並非帶有惡意的那個人。"
  },
  AvgDialog_131216_Content_6 = {
    Text = "畢竟在這位守密人的求學生涯裡、有著不少的前科。"
  },
  AvgDialog_131216_Content_60 = {
    Text = "或許你已經注意到、在你身後、來了幾位你的「老朋友」。"
  },
  AvgDialog_131216_Content_61 = {
    Text = "%player%，後面。"
  },
  AvgDialog_131216_Content_62 = {
    Text = "我感覺到了……"
  },
  AvgDialog_131216_Content_63 = {
    Text = "在調酒師的提醒下你注意到、十幾道強烈的精神波動從你們四面八方快速靠近你們。"
  },
  AvgDialog_131216_Content_64 = {
    Text = "威廉默契地站在你背後，監視著另一個方向。你緊握銀鑰，認真地望著眼前這個迷霧般的調酒師。"
  },
  AvgDialog_131216_Content_65 = {
    Text = "調酒師放下手中的杯子、將桌上的酒瓶放到一個不易被打碎的角落。"
  },
  AvgDialog_131216_Content_66 = {
    Text = "請不要緊張，%player%。你們的蹤跡他們早已掌握。在這個地方，至少我還能幫助你們。"
  },
  AvgDialog_131216_Content_67 = {
    Text = "你？他們？……"
  },
  AvgDialog_131216_Content_68 = {
    Text = "呵……找到你們了。"
  },
  AvgDialog_131216_Content_69 = {
    Text = "這種骯髒的地方可不適合你們待太久哦，來自異鄉的小客人。"
  },
  AvgDialog_131216_Content_7 = {
    Text = "我記得芬戈爾學長的檔案裡提到過、他最大的愛好就是下班後到午夜假面小酌一杯……"
  },
  AvgDialog_131216_Content_70 = {
    Text = "小心、他們過來了"
  },
  AvgDialog_131216_Content_8 = {
    Text = "……當然、偶爾的休息並不完全是一件壞事。"
  },
  AvgDialog_131216_Content_9 = {
    Text = "況且、午夜假面的會員冊上包含了整個倫蒂尼恩的名流、是情報蒐集最完美的場所。"
  },
  AvgDialog_131217_Content_1 = {
    Text = "三質體的權柄在你體內平息下來、但你仍未睜開眼。"
  },
  AvgDialog_131217_Content_10 = {
    Text = "契約精神，商業原則之類的……交易總是需要籌碼，你懂這一套的不是嗎？"
  },
  AvgDialog_131217_Content_11 = {
    Text = "「N」搖了搖頭，似乎費了好大力氣才止住自己的笑聲。"
  },
  AvgDialog_131217_Content_12 = {
    Text = "好消息是，你總是有完美的籌碼。"
  },
  AvgDialog_131217_Content_13 = {
    Text = "英勇的衛道士即將放棄自己的信仰，淹沒在命運的巨網裡，愚弄，欺詐，毫無底線……多麼具有感染力的一幕！"
  },
  AvgDialog_131217_Content_14 = {
    Text = "最佳的觀眾席位，我可不願意錯過。"
  },
  AvgDialog_131217_Content_15 = {
    Text = "我什麼時候說過……"
  },
  AvgDialog_131217_Content_16 = {
    Text = "遊樂者沒有耐心解答你的疑惑。祂掂量著你未來將要支付的東西，笑著搖了搖手指。"
  },
  AvgDialog_131217_Content_17 = {
    Text = "提示算不上、只有一個微小而誠懇的建議。"
  },
  AvgDialog_131217_Content_18 = {
    Text = "為什麼要反抗涅芙蕾亞？為什麼不順從她呢，守密人{Male=先生,Female=小姐}？"
  },
  AvgDialog_131217_Content_19 = {
    Text = "「N」微笑著湊到你的面前，良善得如同一位正在監獄裡拜訪委託人的律師。"
  },
  AvgDialog_131217_Content_2 = {
    Text = "你的意識在浩瀚的精神海中下潛、下潛、潛到那無垠的黑暗、潛到你無法看清的屬於你自己的深淵。"
  },
  AvgDialog_131217_Content_20 = {
    Text = "你……你說什麼？不、我絕不可能……"
  },
  AvgDialog_131217_Content_21 = {
    Text = "啊，沒錯，絕不認輸，絕不放棄，絕不認可涅芙蕾亞的所作所為……古老而經典的英雄主義。"
  },
  AvgDialog_131217_Content_22 = {
    Text = "把我們送給涅芙蕾亞，召喚出你那位親愛的堂兄弟，回到那座屬於你的宮殿……除了這些，你現在又能做什麼呢，%player%？"
  },
  AvgDialog_131217_Content_23 = {
    Text = "教給你一個秘訣：既然已經無法逃離那張網、何不張開雙臂、迎接那張網的到來？"
  },
  AvgDialog_131217_Content_24 = {
    Text = "別做夢了，「N」，我不可能……"
  },
  AvgDialog_131217_Content_25 = {
    Text = "嘘。不要這麼輕易地給自己設限、親愛的。"
  },
  AvgDialog_131217_Content_26 = {
    Text = "別忘了，阿拉克涅將你的命運連入了巨網。你，已經是他們的一員了。"
  },
  AvgDialog_131217_Content_27 = {
    Text = "那位命運的女神給了你一把名為歡愉的鑰匙。可你有沒有想過、那扇門究竟朝向哪裡、又通向何處？"
  },
  AvgDialog_131217_Content_28 = {
    Text = "門朝向哪裡……門通向何處？……"
  },
  AvgDialog_131217_Content_29 = {
    Text = "我本以為，阿拉克涅是一位辛勤善良又乏善可陳的女士，唯一會的東西就是織網與微笑。但她比我想像得要有趣，有趣得多。"
  },
  AvgDialog_131217_Content_3 = {
    Text = "你努力地張大並不存在的嘴、在這片深淵中憤怒地、無聲地呼喊。"
  },
  AvgDialog_131217_Content_30 = {
    Text = "她為這個舞台編織了一張巨大的網、從你來到這個世界的第一刻起、這張網便開始為你鋪陳。"
  },
  AvgDialog_131217_Content_31 = {
    Text = "有這樣優秀的能力、卻在幹著什麼維繫世界運轉這樣的蠢事……可惜、實在是太可惜了。"
  },
  AvgDialog_131217_Content_32 = {
    Text = "跨上命運劇院的舞台、便會成為舞台上的角色。每一位角色、都擁有自己的人生。"
  },
  AvgDialog_131217_Content_33 = {
    Text = "命運讓你來做出這次選擇、是為了讓你看清它。你無法看見絲線、但你現在已經明白、這些絲線是以何種繁複的方式交織。"
  },
  AvgDialog_131217_Content_34 = {
    Text = "命運的絲線織就巨網、每一根絲線的輕顫、或許都將讓命運之網傾覆。"
  },
  AvgDialog_131217_Content_35 = {
    Text = "這即是命運，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131217_Content_36 = {
    Text = "表演、愚弄、取悅……你的體內、有著這樣的力量。命運的舞台不會給所有人準備的機會。當你需要踏上舞台的時候、這些力量會幫助你。"
  },
  AvgDialog_131217_Content_37 = {
    Text = "你無法逃避那些注定將要到來的舞台。思考，然後表演吧，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131217_Content_38 = {
    Text = "「歡愉」。"
  },
  AvgDialog_131217_Content_39 = {
    Text = "在你短暫的未來裡、「歡愉」是一把鑰匙、它將會解開你所面對的秘鎖。"
  },
  AvgDialog_131217_Content_40 = {
    Text = "……無論發生什麼事、信任我、也信任你自己。"
  },
  AvgDialog_131217_Content_41 = {
    Text = "回到命運劇院吧。鑰匙與鎖都在那裡等待你，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131217_Content_42 = {
    Text = "阿拉克涅的話語如同一根根絲線在你腦海中穿行、交織。終於，它們匯成了一張巨大的、嚴密的網。"
  },
  AvgDialog_131217_Content_43 = {
    Text = "你終於明白，從第一次見面開始，阿拉克涅便隔著時間，與現在的你對話。"
  },
  AvgDialog_131217_Content_44 = {
    Text = "你驚嘆地望著那張精密的網、似乎有什麼很重要的東西、正在你腦海中逐漸成型。"
  },
  AvgDialog_131217_Content_45 = {
    Text = "表演、愚弄、取悅……"
  },
  AvgDialog_131217_Content_46 = {
    Text = "啊、沒錯。永遠不要去試圖理解。享受它們、這便是歡愉唯一的秘密。"
  },
  AvgDialog_131217_Content_47 = {
    Text = "悲歡、善惡、一切的情感與道德都不復存在。除了享受、什麼都沒有。"
  },
  AvgDialog_131217_Content_48 = {
    Text = "現在、告訴我……你理解「歡愉」嗎、守密人？"
  },
  AvgDialog_131217_Content_49 = {
    Text = "「N」那張猩紅的笑臉在你的腦海中消失。你看到一面鏡子，上面所映照的，是你自己歡笑的臉。"
  },
  AvgDialog_131217_Content_5 = {
    Text = "嘘……你的聲音太大了、守密人。"
  },
  AvgDialog_131217_Content_50 = {
    Text = "歡愉？……歡愉……"
  },
  AvgDialog_131217_Content_51 = {
    Text = "呵呵呵呵……哈哈哈哈。沒錯、歡愉、我的朋友"
  },
  AvgDialog_131217_Content_52 = {
    Text = "這個世間最美妙的詞彙、這個夢境存在的全部意義……"
  },
  AvgDialog_131217_Content_53 = {
    Text = "似乎看到了即將上演的畫面，N的整個身體都在愉悅中戰慄。他抬起右手，黑霧繚繞的食指輕輕點在自己的額頭。"
  },
  AvgDialog_131217_Content_54 = {
    Text = "你就要抵達了。只差一步、最後一步……好好想想、然後踏入那張網吧、守密人。"
  },
  AvgDialog_131217_Content_55 = {
    Text = "歡愉之道、就在其中。"
  },
  AvgDialog_131217_Content_6 = {
    Text = "「N」的幻影沒有消失。他大方地出現在你的精神空間，彷彿是這裡無可爭議的主人。"
  },
  AvgDialog_131217_Content_7 = {
    Text = "阿拉克涅所說的「歡愉」，一定是指向你"
  },
  AvgDialog_131217_Content_8 = {
    Text = "「N」，給我一些提示……"
  },
  AvgDialog_131217_Content_9 = {
    Text = "提示？哈哈哈哈……我是做了什麼、竟讓你這樣侮辱我？"
  },
  AvgDialog_131218_Content_10 = {
    Text = "你……你們這是……"
  },
  AvgDialog_131218_Content_11 = {
    Text = "醉酒的中年、妙齡的女郎、華貴的紳士、街頭的幫派成員、一臉疲憊的侍者、美麗的調酒師……"
  },
  AvgDialog_131218_Content_12 = {
    Text = "酒館裡每一張面孔，無論年輕或蒼老，英俊或平庸，都以如複印品般相似的神情同時轉向你。"
  },
  AvgDialog_131218_Content_13 = {
    Text = "他們……不像是個體，更像是……"
  },
  AvgDialog_131218_Content_14 = {
    Text = "前一刻還活生生的人們，此刻如同一具具人偶般，站在你們身前。"
  },
  AvgDialog_131218_Content_15 = {
    Text = "……更像是，被束縛在網中的木偶。"
  },
  AvgDialog_131218_Content_16 = {
    Text = "我對您敏銳的觀察力早有耳聞、威廉先生。"
  },
  AvgDialog_131218_Content_17 = {
    Text = "您眼前的這些，是舞台上的佈景，鏡中的倒影。"
  },
  AvgDialog_131218_Content_18 = {
    Text = "請原諒，我暫時不方便離開我的網，不得不用它們與兩位對話。"
  },
  AvgDialog_131218_Content_19 = {
    Text = "歡迎來到我的舞台，威廉先生，守密人%sirormadam%。"
  },
  AvgDialog_131218_Content_2 = {
    Text = "解決了、這些東西究竟是……"
  },
  AvgDialog_131218_Content_20 = {
    Text = "每一個詞語都嚴絲合縫地傳遞下去，二十道不同的聲音，編織成同一條冰冷的聲線。"
  },
  AvgDialog_131218_Content_21 = {
    Text = "酒吧裡的所有人，帶著同樣的微笑與語調，向你們鞠躬致意。他們彎腰的弧度與雙手擺放的角度，沒有任何區別。"
  },
  AvgDialog_131218_Content_22 = {
    Text = "你的……舞台？你究竟是誰？"
  },
  AvgDialog_131218_Content_23 = {
    Text = "是這裡的主人、也是一位囚徒。"
  },
  AvgDialog_131218_Content_24 = {
    Text = "我想、您的疑問一定很多。"
  },
  AvgDialog_131218_Content_25 = {
    Text = "這裡並不安全、他們的人很快便會追來。我的侍女將前來迎接兩位、見到她之後、請不必驚慌。"
  },
  AvgDialog_131218_Content_26 = {
    Text = "在見面之後、所有的疑問、我將為二位一一解答。"
  },
  AvgDialog_131218_Content_27 = {
    Text = "說完這句話後，人群的意識似乎在一瞬間被抽離。"
  },
  AvgDialog_131218_Content_28 = {
    Text = "紳士的水晶杯停在唇邊，女士展開的折扇遮住下臉，調酒師優雅地托起杯盞。"
  },
  AvgDialog_131218_Content_29 = {
    Text = "如同牽引的絲線忽然斷開，所有人都保持著最後的姿勢，如蠟像般凝固在這片空間裡。"
  },
  AvgDialog_131218_Content_3 = {
    Text = "小心身後！！……"
  },
  AvgDialog_131218_Content_30 = {
    Text = "你深吸一口氣，猶疑地環視著這些帶著同樣微笑凝固的「木偶」。"
  },
  AvgDialog_131218_Content_31 = {
    Text = "雖然剛才他們的確幫助了我、但我實在無法完全相信……"
  },
  AvgDialog_131218_Content_32 = {
    Text = "威廉學長、我們想知道的事情、這位「主人」或許是最好的解答者。"
  },
  AvgDialog_131218_Content_33 = {
    Text = "就算有危險、我想我也得去一趟、只是……"
  },
  AvgDialog_131218_Content_35 = {
    Text = "看到你的眼神、威廉心領神會點了點頭。"
  },
  AvgDialog_131218_Content_36 = {
    Text = "我會在外面調查那些陰影的行蹤、它們在尋找你、我在外部的行蹤會比你更安全。"
  },
  AvgDialog_131218_Content_37 = {
    Text = "這位「主人」來歷不明、如果遭遇危險……"
  },
  AvgDialog_131218_Content_38 = {
    Text = "威廉輕輕點了點胸前的校徽。在這個世界、你們是彼此校徽唯一能夠聯繫上的人。"
  },
  AvgDialog_131218_Content_39 = {
    Text = "明白…你也是、威廉學長。"
  },
  AvgDialog_131218_Content_4 = {
    Text = "強烈的危機感讓你瞬間清醒過來。你猛然轉身、看見你眼前數英寸處那柄陰影凝成的利刃。"
  },
  AvgDialog_131218_Content_40 = {
    Text = "「主人」理解您的謹慎。威廉先生、這座舞台現在有很多危險、請一定小心行事。在能力範圍內、我們將為您提供必要的幫助。"
  },
  AvgDialog_131218_Content_41 = {
    Text = "淡紫色的蜘蛛從酒吧的各處匯集，一位長著蜘蛛體徵的侍女悄然出現在你們身後。向你們禮貌地鞠躬示意後，她向門外走去。"
  },
  AvgDialog_131218_Content_42 = {
    Text = "守密人{Male=先生,Female=小姐}，請隨我來。「主人」已經恭候您多時。"
  },
  AvgDialog_131218_Content_6 = {
    Text = "你緩緩移開擋住眼睛的手臂。陰影被身後的人斬斷、黑色的黏液噴灑、濺滿你的全身。"
  },
  AvgDialog_131218_Content_7 = {
    Text = "對不起、讓你們受到了嚇到。"
  },
  AvgDialog_131218_Content_8 = {
    Text = "他們一直在尋找您的蹤跡。在這裡、我的力量尚能為您提供一些幫助。"
  },
  AvgDialog_131218_Content_9 = {
    Text = "未經您同意、私自引導你們前來此處、希望兩位不要介意。"
  },
  AvgDialog_131219_Content_1 = {
    Text = "從維度碎片中散逸的力量……這些是……！"
  },
  AvgDialog_131219_Content_2 = {
    Text = "三質體的權柄從未背棄，您與N的演出也尚未結束。"
  },
  AvgDialog_131219_Content_3 = {
    Text = "借用他們的力量，為他們帶來那注定的結局吧……守秘人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131220_Content_1 = {
    Text = "天鵝翱翔"
  },
  AvgDialog_131220_Content_10 = {
    Text = "你記得那扇有些鏽跡的大門、每次移動的時候都會發出沉悶的聲響、像是祖父慈祥的呼吸。"
  },
  AvgDialog_131220_Content_11 = {
    Text = "密斯卡大學……"
  },
  AvgDialog_131220_Content_12 = {
    Text = "在這熟悉的環境裡、你撫摸著廣場銘牌上那個完全不一樣的名字。"
  },
  AvgDialog_131220_Content_13 = {
    Text = "每一位演員都有自己的最熱愛的舞台。即便是一座由記憶復刻出來的校園、對你而言也無可取代。"
  },
  AvgDialog_131220_Content_14 = {
    Text = "為什麼要創造這樣一個和彌薩格一模一樣的地方呢……"
  },
  AvgDialog_131220_Content_15 = {
    Text = "我並未創造它、只是它應當存在於此。和這座城市、這個世界一樣、它們都是命運之網的一部分。"
  },
  AvgDialog_131220_Content_16 = {
    Text = "不必看那麼遙遠，%player%。來到一個舞台之上，便會有來這裡的意義。"
  },
  AvgDialog_131220_Content_17 = {
    Text = "說起來、和莉茲相處了那麼久、我還從來沒有在現場看過她的正式演出……"
  },
  AvgDialog_131220_Content_18 = {
    Text = "你環顧著這座熟悉的廣場、雙手在身下的草地上輕輕劃過。"
  },
  AvgDialog_131220_Content_19 = {
    Text = "人生最美妙的時刻、就是沒有察覺自己正在微笑的時候。"
  },
  AvgDialog_131220_Content_2 = {
    Text = "真是難得、這個舞團在劇院裡的票價、最便宜的也得花掉我兩個月的薪資。"
  },
  AvgDialog_131220_Content_21 = {
    Text = "想起了彌薩格的事情？"
  },
  AvgDialog_131220_Content_22 = {
    Text = "在這個廣場上、我們舉行過很多次校內的表演。那時候也像現在一樣、彌薩格的學生堆滿了廣場。"
  },
  AvgDialog_131220_Content_23 = {
    Text = "有許多喚醒體在藝術上都有極深的造詣。很多人一開始都不太願意在這種場合演出、我和學院的老師們就想了各種各樣的方法……"
  },
  AvgDialog_131220_Content_24 = {
    Text = "到後來、他們許多人也主動開始想要為這裡的夥伴們進行展示。"
  },
  AvgDialog_131220_Content_25 = {
    Text = "莉茲的舞蹈、汀克特的歌謠、哈姆林的交響樂、奧爾拉的詩歌、珊的雕塑……"
  },
  AvgDialog_131220_Content_26 = {
    Text = "不知道在我離開後、彌薩格的生活有沒有恢復到從前的樣子……"
  },
  AvgDialog_131220_Content_27 = {
    Text = "帷幕動了！帷幕動了！莉茲小姐就快要出場了！"
  },
  AvgDialog_131220_Content_28 = {
    Text = "你搖了搖頭、把那些傷感的情緒從自己腦海中趕走。"
  },
  AvgDialog_131220_Content_29 = {
    Text = "不管怎麼說、能在這個遙遠的世界再次看到莉茲的舞、是一件值得慶幸的事。"
  },
  AvgDialog_131220_Content_3 = {
    Text = "聽說是索蕾爾夫人以個人名義贊助的公益演出！要是這座城市裡的每一位老爺夫人都有這麼好心腸該多好"
  },
  AvgDialog_131220_Content_30 = {
    Text = "等這件事情徹底了結、如果有時間、我想和他們好好聊聊。"
  },
  AvgDialog_131220_Content_31 = {
    Text = "女士們、先生們……歡迎來到我們的演出現場"
  },
  AvgDialog_131220_Content_32 = {
    Text = "天鵝舞蹈團、多麼神聖、多麼高不可攀的名字！這隻倫蒂尼恩最高雅的白天鵝、今天、將第一次棲息在倫蒂尼恩的公眾面前"
  },
  AvgDialog_131220_Content_33 = {
    Text = "承蒙各位久等。我們的演員已經準備完畢。精彩的演出、即將為各位奉上"
  },
  AvgDialog_131220_Content_34 = {
    Text = "隨著報幕人的清脆響指、周圍的燈光全部關閉、幾道聚光燈打在螢幕中央。"
  },
  AvgDialog_131220_Content_35 = {
    Text = "接下來、請欣賞由莉茲小姐帶來的舞蹈、天鵝——翱翔！"
  },
  AvgDialog_131220_Content_36 = {
    Text = "在人群熱烈的掌聲與歡呼中、那道幕布緩緩拉開──"
  },
  AvgDialog_131220_Content_38 = {
    Text = "你見過很多次的莉茲。"
  },
  AvgDialog_131220_Content_39 = {
    Text = "彌薩格典禮室的舞台上、她為你一人旋轉。"
  },
  AvgDialog_131220_Content_4 = {
    Text = "雖然看不懂、不過這種機會可不能錯過。"
  },
  AvgDialog_131220_Content_40 = {
    Text = "倫蒂尼恩的星空下、她踮起的腳尖觸碰夜空中飛舞的螢光。"
  },
  AvgDialog_131220_Content_41 = {
    Text = "查令街的微風中、她的裙擺高高揚起、如同沸騰的火焰。"
  },
  AvgDialog_131220_Content_42 = {
    Text = "而今天、在遙遠異鄉的舞台上、她以一種你從未見過的姿態出現在你的面前。"
  },
  AvgDialog_131220_Content_43 = {
    Text = "天鵝舞團的頭號舞星、整座城市最璀璨的焰火。黑色的尖刺刺穿她的喉管、手臂、胸腹、踮起的雙腳、刺穿她支配舞蹈的身體。"
  },
  AvgDialog_131220_Content_44 = {
    Text = "鮮血噴灑、在她身後的背板上畫出一雙猩紅的翅膀、在她從容微笑著的臉上留下幾道凄厲的劃痕。"
  },
  AvgDialog_131220_Content_45 = {
    Text = "人群寂靜無聲、風從廣闊的廣場吹過、黑綠相間的舞裙在空中飛舞、如同一團永恆燃燒的焰火。"
  },
  AvgDialog_131220_Content_46 = {
    Text = "——這一瞬間你徹底地明白、如果死亡無可阻擋、那這便是莉茲最渴望的死亡方式。"
  },
  AvgDialog_131220_Content_47 = {
    Text = "她用鮮血與生命完成了一場謝幕演出。她的舞姿在最美的騰躍中定格、如同一隻翱翔的黑天鵝。"
  },
  AvgDialog_131220_Content_48 = {
    Text = "莉茲小姐的舞姿、多麼的高雅、多麼的優美"
  },
  AvgDialog_131220_Content_49 = {
    Text = "靜靜欣賞吧、我親愛的觀眾朋友們！親眼見到這一幕、是你們此生僅有的榮幸。"
  },
  AvgDialog_131220_Content_5 = {
    Text = "三十年……我已經三十年沒能重新回到劇院看一場表演了……"
  },
  AvgDialog_131220_Content_50 = {
    Text = "你看見報幕人那張被撕扯成兩半的臉。毫無生氣的中年男人的面容如黏液般融化，露出涅芙蕾亞那雙被興奮填滿的眼睛。"
  },
  AvgDialog_131220_Content_51 = {
    Text = "在人群混亂的喊叫與奔逃中、她尖銳的笑聲如毒針般刺痛你的耳膜。"
  },
  AvgDialog_131220_Content_52 = {
    Text = "<Big:莉茲！！>"
  },
  AvgDialog_131220_Content_53 = {
    Text = "你撥開被驚嚇的混亂人群、跑到舞台面前。"
  },
  AvgDialog_131220_Content_54 = {
    Text = "啊、這位聰明的客人、您是怎麼知道這場舞蹈演出還有第二幕的？"
  },
  AvgDialog_131220_Content_55 = {
    Text = "舞台四周、一些沒有逃離的觀眾向你快速圍攏過來。他們的身體在奔跑中炸裂開、鑽出那些斬殺不絕的黑色蜘蛛侍從。"
  },
  AvgDialog_131220_Content_56 = {
    Text = "在你面前的舞台上、莉茲的身體離開了尖刺。一件由異教徒製作的藝術品、帶著殘忍的空洞與鮮豔的血。"
  },
  AvgDialog_131220_Content_57 = {
    Text = "猩紅的赤裸足印自舞台的中心延伸。莉茲緩緩地向你走來，鮮血繪成的淒慘豔麗的妝容讓你感到一陣窒息。"
  },
  AvgDialog_131220_Content_58 = {
    Text = "她抬頭望著你。空洞的、滲血的雙眼讓你想起所有值得流傳於世的藝術品。"
  },
  AvgDialog_131220_Content_6 = {
    Text = "芭蕾、這世上最純粹的舞蹈、只有真正跳過的人才明白那些殘酷的優雅究竟有多美"
  },
  AvgDialog_131220_Content_7 = {
    Text = "還能在現場看到莉茲小姐的演出、這是我做夢也沒有想過的事……"
  },
  AvgDialog_131220_Content_8 = {
    Text = "那些本應嘈雜的環境音在你耳中混成一道遙遠的白噪音。"
  },
  AvgDialog_131220_Content_9 = {
    Text = "你記得這片草地、那片湖泊。你記得那些高低錯落的教學樓、記得那個目光堅定望向遠方的雕塑。"
  },
  AvgDialog_131221_Content_10 = {
    Text = "我是一名命運的囚徒、這只是我不得不盡的義務而已。"
  },
  AvgDialog_131221_Content_11 = {
    Text = "一個能夠操控無數世界命運的人、或許稱自己為命運的法官或典獄長會更妥帖？"
  },
  AvgDialog_131221_Content_12 = {
    Text = "在命運這座監牢裡、獄卒與囚徒並無區別。"
  },
  AvgDialog_131221_Content_13 = {
    Text = "威廉先生、這一路上還習慣嗎？"
  },
  AvgDialog_131221_Content_14 = {
    Text = "多虧了您的侍女、若是只靠我自己、想要擺脫那些陰影裡的侍從、恐怕還需要付出更多的代價。"
  },
  AvgDialog_131221_Content_15 = {
    Text = "涅芙蕾亞……你又碰到她的人了？"
  },
  AvgDialog_131221_Content_16 = {
    Text = "威廉凝重地點了點頭。"
  },
  AvgDialog_131221_Content_17 = {
    Text = "分頭行動的時候，我遇到了一些看上去不太對勁的路人。我跟蹤了一段路，聽到了她們的談話。"
  },
  AvgDialog_131221_Content_18 = {
    Text = "她們在尋找一些被稱為「秘偶」的東西。"
  },
  AvgDialog_131221_Content_19 = {
    Text = "我想……你們剛才談論到的、對舞台命運的汙染、或許只是一種前置手段。"
  },
  AvgDialog_131221_Content_2 = {
    Text = "一齣精彩的……"
  },
  AvgDialog_131221_Content_20 = {
    Text = "那些「秘偶」、才是她們真正的目的所在。"
  },
  AvgDialog_131221_Content_21 = {
    Text = "我的妹妹將她與侍從們的命運絲線隱藏了起來，我無法輕易地看到她們。您提供了一條非常有價值的情報，威廉先生。"
  },
  AvgDialog_131221_Content_22 = {
    Text = "接下來的行動、我會和你們一起……"
  },
  AvgDialog_131221_Content_24 = {
    Text = "不行！你現在還有傷在身，我不想勒姆瓦希的事情再發生了。"
  },
  AvgDialog_131221_Content_25 = {
    Text = "守密人說得沒錯。我的侍女會幫助你治療體內的毒素，在痊癒之前，請在劇院中安心靜養。"
  },
  AvgDialog_131221_Content_26 = {
    Text = "很快、我們便會迎來需要你幫助的那一天。"
  },
  AvgDialog_131221_Content_27 = {
    Text = "阿拉克涅的話語如同一道溫和的宣判，輕易地洞穿肉體與靈魂，輕輕落在威廉的命運之中。"
  },
  AvgDialog_131221_Content_28 = {
    Text = "威廉看了一眼腹部滲出的血、輕輕點了點頭。"
  },
  AvgDialog_131221_Content_29 = {
    Text = "現在和你們一同行動，的確只會成為拖累。請放心，我會讓那一天盡快到來。"
  },
  AvgDialog_131221_Content_30 = {
    Text = "阿拉克涅微笑著伸出手。一隻、兩隻……無數的蜘蛛從她的袖中鑽出，順著絲線落在地上。"
  },
  AvgDialog_131221_Content_31 = {
    Text = "蜘蛛如水滴般落地、匯集。密密麻麻的蜘蛛交疊成人影，色彩與光影附著其上。"
  },
  AvgDialog_131221_Content_32 = {
    Text = "很快，一個新的、一模一樣的阿拉克涅站在你的身前。"
  },
  AvgDialog_131221_Content_33 = {
    Text = "請隨我來吧，守密人{Male=先生,Female=小姐}。我想，我們很快便能見到我那位妹妹了。"
  },
  AvgDialog_131221_Content_35 = {
    Text = "這座城市裡有許多我鍾愛的店舖、不過和你一樣、這裡也是我摯愛的場所之一。"
  },
  AvgDialog_131221_Content_36 = {
    Text = "午夜假面酒館，你坐在上次來時坐的位置，皺著眉頭望著正四處打量的阿拉克涅。"
  },
  AvgDialog_131221_Content_37 = {
    Text = "所以你現在究竟是什麼……木偶？分身？一群蜘蛛拼起來的、幫你逃班的神秘機器？"
  },
  AvgDialog_131221_Content_38 = {
    Text = "本質上而言、這裡的我與劇院中的我、是同一時刻裡有著兩段不同經歷的命運。"
  },
  AvgDialog_131221_Content_39 = {
    Text = "我的大部分力量都需要留在劇院裡，繼續編織命運的巨網。除此之外，我們沒有任何區別。不必因為疑慮而破壞此刻的心情，守密人。"
  },
  AvgDialog_131221_Content_4 = {
    Text = "聲音牽動傷口、威廉捂住纏著繃帶的腹部、抑制不住咳嗽起來。"
  },
  AvgDialog_131221_Content_40 = {
    Text = "阿拉克涅平靜地微笑著，冰塊在搖晃的酒杯中輕輕作響。"
  },
  AvgDialog_131221_Content_41 = {
    Text = "您知道嗎、這家酒館每個月都會舉辦一場假面舞會、每個進來的客人都必須戴上自己最有趣的那張面具。"
  },
  AvgDialog_131221_Content_42 = {
    Text = "上流社會的社交時常會讓這個地方變得無趣、只有在那一天、這裡將成為這座城市最值得前來的地方。"
  },
  AvgDialog_131221_Content_43 = {
    Text = "或許下一次的假面舞會、我也應該放下一切、來認真感受一次。"
  },
  AvgDialog_131221_Content_44 = {
    Text = "我以為一個能看到命運發展的人、會對未來的一切不再有任何興趣了呢。"
  },
  AvgDialog_131221_Content_45 = {
    Text = "的確如此，%player%。不過，我在很早以前就領悟了一個避免無聊的方式。"
  },
  AvgDialog_131221_Content_46 = {
    Text = "有時我會從幕後來到台前、踏入自己創造的舞台、讓自己也變成其中的一個角色。"
  },
  AvgDialog_131221_Content_47 = {
    Text = "遮擋住自己對命運的窺視、將自己完全置放於舞台之上、去細緻地感知時間的流動、命運的傾轉……"
  },
  AvgDialog_131221_Content_48 = {
    Text = "這是一種難得的休憩。這樣的機會並不多、每一次、我都視其為彌足珍貴的節日。"
  },
  AvgDialog_131221_Content_49 = {
    Text = "阿拉克涅一邊說著一邊饒有興致地看著那些華麗的賓客與溫柔的侍者，酒館曖昧的燈光在阿拉克涅眼裡流轉。"
  },
  AvgDialog_131221_Content_5 = {
    Text = "威廉學長？！你受傷了"
  },
  AvgDialog_131221_Content_50 = {
    Text = "就算是這樣……我們不是要去尋找那什麼「秘偶」嗎？為什麼到這裡來了？"
  },
  AvgDialog_131221_Content_51 = {
    Text = "其中一位就在這裡。您很快……啊不、您已經見過她了。"
  },
  AvgDialog_131221_Content_52 = {
    Text = "你們好啊、親愛的顧客。"
  },
  AvgDialog_131221_Content_53 = {
    Text = "蜂蜜醃浸的聲音。瓷器雕琢的手指。裸露的脖頸上、茉莉與合歡花明媚的香氣。還有那雙如霓虹燈般閃爍的、能看穿一切的眼睛。"
  },
  AvgDialog_131221_Content_54 = {
    Text = "啊，我記得你，這位優雅的{Male=先生,Female=小姐}。"
  },
  AvgDialog_131221_Content_55 = {
    Text = "暗影裡的魔物、耀眼的銀色光輝……多麼精彩的英雄故事"
  },
  AvgDialog_131221_Content_56 = {
    Text = "老實說、你不在的這段時間裡、午夜假面酒吧借著你的故事賺了不少錢、我們應該付你版權費——至少、也讓我們請你一杯酒。"
  },
  AvgDialog_131221_Content_57 = {
    Text = "原來是你……我就先不喝了、能麻煩先給我的這位朋友來一杯嗎？"
  },
  AvgDialog_131221_Content_58 = {
    Text = "名字我都想好了、就叫自導自演。"
  },
  AvgDialog_131221_Content_59 = {
    Text = "不錯的名字。至於適不適合您這位朋友、我還要仔細看看……"
  },
  AvgDialog_131221_Content_6 = {
    Text = "在阿拉克涅的牽引下，你跨過赫瓦茨咖啡館旁那面不起眼的牆壁。"
  },
  AvgDialog_131221_Content_60 = {
    Text = "這位名為「浪漫」的秘偶來到吧台邊，認真地凝視著阿拉克涅的眼睛。"
  },
  AvgDialog_131221_Content_61 = {
    Text = "低調的造物主沉浸在自己創造的舞台。阿拉克涅微笑著與她對視。"
  },
  AvgDialog_131221_Content_62 = {
    Text = "啊、多麼深邃的一雙眼睛啊、小姐。"
  },
  AvgDialog_131221_Content_63 = {
    Text = "一面如此深沉、如此廣闊的海洋、那無人可見的海底、埋藏著無人知曉的隱秘。"
  },
  AvgDialog_131221_Content_64 = {
    Text = "那些洶湧的浪涛、全都被這海洋容納、無論多大的震盪、它依舊維持著亘古的平靜。"
  },
  AvgDialog_131221_Content_65 = {
    Text = "時間流逝、星海流轉。高山變為田野、海洋變為草原……"
  },
  AvgDialog_131221_Content_66 = {
    Text = "可是、在這變幻之下、這片海洋又拋棄了些什麼呢……"
  },
  AvgDialog_131221_Content_67 = {
    Text = "調酒師坐到阿拉克涅對面，托起她的下巴。修長的指甲，自然而然地抵在阿拉克涅的頸動脈上。"
  },
  AvgDialog_131221_Content_68 = {
    Text = "你這是……"
  },
  AvgDialog_131221_Content_69 = {
    Text = "命運的神明，偉大的阿拉克涅。你玩弄命運的手法，是多麼的優雅。我真是羨慕啊，羨慕那些被你選擇的，被你留下的。"
  },
  AvgDialog_131221_Content_7 = {
    Text = "重新回到劇院的舞台之上時、你第一眼便看到獨自坐在觀眾席上的威廉。"
  },
  AvgDialog_131221_Content_70 = {
    Text = "可惜……我們生來、就只能是被遺棄的那一部分。"
  },
  AvgDialog_131221_Content_71 = {
    Text = "……看來，今天沒有機會再嚐到這杯酒了。"
  },
  AvgDialog_131221_Content_72 = {
    Text = "阿拉克涅沒有試圖掙脫那隻兇險的手。她輕聲嘆息，彷彿是在嘆息那些遙遠的記憶，又像是在嘆息那杯無法喝到的特調。"
  },
  AvgDialog_131221_Content_73 = {
    Text = "你可以汙染這些秘偶的命運絲線，讓我無法看清，但這沒有意義。你沒有操控命運的能力，涅芙蕾亞。"
  },
  AvgDialog_131221_Content_74 = {
    Text = "如同黑色的奶油融化，調酒師的皮表變成一灘爛泥從身體上滑落。"
  },
  AvgDialog_131221_Content_75 = {
    Text = "在那爛泥之下、一張熟悉的臉出現在你面前。"
  },
  AvgDialog_131221_Content_76 = {Text = "是你？"},
  AvgDialog_131221_Content_77 = {
    Text = "我的好姊姊。那些維度的餘燼、你已經所剩無幾了。"
  },
  AvgDialog_131221_Content_78 = {
    Text = "我很想和你再好好談談心、不過現在、還是讓我的小蜘蛛們好好歡迎一下你吧。"
  },
  AvgDialog_131221_Content_79 = {
    Text = "小心身後"
  },
  AvgDialog_131221_Content_8 = {Text = "小傷。"},
  AvgDialog_131221_Content_9 = {
    Text = "發生在這個舞台上的命運，我都看到了。我想，應當有人感謝您的付出，阿拉克涅女士。"
  },
  AvgDialog_131222_Content_1 = {
    Text = "莊園的請柬"
  },
  AvgDialog_131222_Content_10 = {
    Text = "邀請函？我這一生到現在、還從來沒有出示過邀請函。"
  },
  AvgDialog_131222_Content_100 = {
    Text = "索蕾爾微微眯起眼、那雙優雅的眼睛裡燃起一道鮮有的怒火。"
  },
  AvgDialog_131222_Content_101 = {
    Text = "我不知道你對珈倫做了什麼、但那無所謂。無論如何、你將要付出的代價已經注定了。"
  },
  AvgDialog_131222_Content_102 = {
    Text = "啊、一次失敗的商務會談……很遺憾、索蕾爾夫人。看來、只能讓你的屍體來告訴我了。"
  },
  AvgDialog_131222_Content_103 = {
    Text = "索蕾爾眉頭緊皺、感知著對方強大的精神力量波動。墨黑色的陰影快速逼近、封鎖了她的每一個逃離路徑。"
  },
  AvgDialog_131222_Content_105 = {
    Text = "陰影中的利刃猛然刺向索蕾爾時、一道強烈的銀光如流星般躍入屋內。"
  },
  AvgDialog_131222_Content_106 = {
    Text = "索蕾爾、退後"
  },
  AvgDialog_131222_Content_11 = {Text = "讓開。"},
  AvgDialog_131222_Content_12 = {
    Text = "抱歉、先生。今天的宴會、必須要邀請函才能參加。"
  },
  AvgDialog_131222_Content_13 = {
    Text = "沒有眼力的傢伙、你知道我是誰嗎？"
  },
  AvgDialog_131222_Content_14 = {
    Text = "那並不是我的職責、先生。"
  },
  AvgDialog_131222_Content_15 = {
    Text = "聽您的口音是當地人、我想我說的話您應該能聽懂。"
  },
  AvgDialog_131222_Content_16 = {
    Text = "你！！好、好、我會讓你和這座莊園的主人付出代價"
  },
  AvgDialog_131222_Content_17 = {
    Text = "阿拉克涅看著貴族憤恨的背影，搖了搖頭。"
  },
  AvgDialog_131222_Content_18 = {
    Text = "看來、要進入這座莊園可沒有想像中那麼容易。"
  },
  AvgDialog_131222_Content_19 = {
    Text = "如果能找到那位賣洗澡水的侍女、說不定能買到兩張邀請函……"
  },
  AvgDialog_131222_Content_2 = {
    Text = "卡德林公爵莊園、老倫蒂尼恩最負盛名的社交場。"
  },
  AvgDialog_131222_Content_20 = {
    Text = "源自錫拉島的珍稀海水浴鹽、薰衣草、柑橘、丁香、還有康斯坦南部運來的薔薇花瓣……"
  },
  AvgDialog_131222_Content_21 = {
    Text = "洗澡水可比邀請函更加珍貴、更加難得。"
  },
  AvgDialog_131222_Content_23 = {
    Text = "我本來是打算自言自語一下的……你怎麼連我夢境裡經歷的事情也知道？"
  },
  AvgDialog_131222_Content_24 = {
    Text = "雖然看不清您的命運、但您身邊人的命運、我一直注視著。"
  },
  AvgDialog_131222_Content_25 = {
    Text = "既然這些人的命運可以由你控制、就算修改起來很複雜、弄兩張邀請函這種小事應該也能做到的吧？"
  },
  AvgDialog_131222_Content_26 = {
    Text = "修改命運所引起的連鎖反應、您已經見證過。命運並非我隨意擺弄的玩具、而是一間需要我精心維護的玻璃屋。"
  },
  AvgDialog_131222_Content_27 = {
    Text = "我需要謹慎地為它做出每一個選擇、耗費大量的心力與維度餘燼。所有的不慎與錯漏、都会換來坍塌與毀滅。"
  },
  AvgDialog_131222_Content_28 = {
    Text = "更何況……如我之前所言、很多時候、做一個觀眾、遠比做一個劇作家有趣得多。"
  },
  AvgDialog_131222_Content_3 = {
    Text = "公爵的前半生、首相與內閣的高官們在草甸的茶几上寫下一道道決定帝國命運的手札。"
  },
  AvgDialog_131222_Content_30 = {
    Text = "可我對這裡什麼都不清楚……"
  },
  AvgDialog_131222_Content_31 = {
    Text = "表演、愚弄、取悅……你的體內、有著這樣的力量。命運的舞台不會給所有人準備的機會。當你需要踏上舞台的時候、這些力量會幫助你。"
  },
  AvgDialog_131222_Content_32 = {
    Text = "你無法逃避那些注定將要到來的舞台。思考，然後表演吧，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131222_Content_33 = {
    Text = "阿拉克涅禮貌的微笑中隱藏著一道不難察覺的嚴肅。她似乎在向你講述，那道目光又像是穿過了你，在向遙遠的將來對話。"
  },
  AvgDialog_131222_Content_34 = {
    Text = "那是命運無法拒絕的指令。你低下頭，思考著阿拉克涅的話。"
  },
  AvgDialog_131222_Content_35 = {
    Text = "表演、愚弄、取悦……你是說、N的權柄？"
  },
  AvgDialog_131222_Content_36 = {
    Text = "可那場與托乎瓦波的決戰之後、我與三質體的力量便失去了聯繫……"
  },
  AvgDialog_131222_Content_37 = {
    Text = "祂們的力量尚在沉睡、可權柄並非只是力量而已。"
  },
  AvgDialog_131222_Content_38 = {
    Text = "權柄、不只是力量……"
  },
  AvgDialog_131222_Content_39 = {
    Text = "在你嘗試思考這句話的時候、一道靈光在你的精神世界裡閃現。"
  },
  AvgDialog_131222_Content_4 = {
    Text = "公爵的後半生、被出售的莊園目送他前往刑場時佝僂的背影。"
  },
  AvgDialog_131222_Content_40 = {
    Text = "你從地上撿起兩片掉落的楓葉、摩挲過它們如書信般的紋路。"
  },
  AvgDialog_131222_Content_41 = {
    Text = "我記得你之前說過、這個世界的所有人、體內都保有銀芯。那就意味著、所有人的精神世界都能被銀鑰匙所影響……對吧？"
  },
  AvgDialog_131222_Content_42 = {
    Text = "阿拉克涅微笑著望著你，站在你的身邊，向莊園的大門走去。"
  },
  AvgDialog_131222_Content_43 = {
    Text = "您好、請出示……"
  },
  AvgDialog_131222_Content_44 = {
    Text = "真是漂亮的莊園。能收到索蕾爾夫人的邀請、我們非常榮幸。"
  },
  AvgDialog_131222_Content_45 = {
    Text = "將兩片楓葉遞給衛兵的時候、你的銀鑰匙在懷中閃爍出微弱的光。你輕易地捕捉到了衛兵的光點。"
  },
  AvgDialog_131222_Content_46 = {
    Text = "同時、另一道光點在你的精神世界中亮起。在兩道光點的連結交匯處、克萊門汀的幻影搖晃手中的鐘擺。"
  },
  AvgDialog_131222_Content_48 = {
    Text = "啊、休伊伯爵、伯爵夫人、卡德林莊園歡迎二位的到來。"
  },
  AvgDialog_131222_Content_49 = {
    Text = "在衛兵恭敬的目光裡、你們踏上了莊園平整的卵石路。"
  },
  AvgDialog_131222_Content_5 = {
    Text = "短暫地沉寂之後、這座莊園重新裝滿了名貴的客人們、它的新主人用一場場沙龍昭示著它的回歸。"
  },
  AvgDialog_131222_Content_50 = {
    Text = "感覺如何，守密人{Male=先生,Female=小姐}？"
  },
  AvgDialog_131222_Content_51 = {
    Text = "雖然還是不理解你所說的權柄的含義、不過我剛剛的確感受到了一些不一樣的東西……"
  },
  AvgDialog_131222_Content_52 = {
    Text = "那種在愚弄之後產生的快感、從未在我身上出現過……就像……完全不屬於我自己的情緒……"
  },
  AvgDialog_131222_Content_53 = {
    Text = "你揚起手、兩片美麗的楓葉離開你的指尖、在風中歡快地旋轉。"
  },
  AvgDialog_131222_Content_54 = {
    Text = "在你與阿拉克涅保持著得體微笑邁入莊園時，你敢肯定，你聽到一道來自身體深處的愉悅笑聲。"
  },
  AvgDialog_131222_Content_56 = {
    Text = "很難想像，有人能在如此年紀就能取得這樣的成就。"
  },
  AvgDialog_131222_Content_57 = {
    Text = "這次的貿易會談結束之後、這座城市的商界與政界的聯繫將迎來史無前例的顛覆。這是一場難得的機會……"
  },
  AvgDialog_131222_Content_58 = {
    Text = "主編好不容易才弄到的邀請函、這次我們一定要拍下幾個精彩的鏡頭。一會你帶著設備跟上、我們儘量往前走、靠近一些……"
  },
  AvgDialog_131222_Content_59 = {
    Text = "出來了！出來了！"
  },
  AvgDialog_131222_Content_6 = {
    Text = "您好、這是我的邀請函。"
  },
  AvgDialog_131222_Content_60 = {
    Text = "隨著青年的喊聲響起、所有的人都衝向那扇開啟的大門。"
  },
  AvgDialog_131222_Content_61 = {
    Text = "紅色的長裙如同熱烈的薔薇、讓房間中的所有裝飾與人群都黯然失色。"
  },
  AvgDialog_131222_Content_62 = {
    Text = "索蕾爾的臉上掛著永遠不會出錯的得體笑容，用最為標準的姿勢，向人群輕輕揮手。"
  },
  AvgDialog_131222_Content_63 = {
    Text = "在這個舞台，她做得比之前更好了……好久不見，紅薔薇。"
  },
  AvgDialog_131222_Content_64 = {
    Text = "諸位，歡迎來到我的莊園。在今天的沙龍上，這座城市的幾條商業街都將擁有它們的新主人。"
  },
  AvgDialog_131222_Content_65 = {
    Text = "當然，我們尊貴的貴族先生們也將得到自己應有的利益。"
  },
  AvgDialog_131222_Content_66 = {
    Text = "我想，今夜一定會有一場精彩而愉悅的晚宴。"
  },
  AvgDialog_131222_Content_67 = {
    Text = "莊園的廚師為大家準備了首屈一指的糕點與香檳、請大家稍作休息。很快、我們的晚宴將正式開始。"
  },
  AvgDialog_131222_Content_68 = {
    Text = "索蕾爾的目光微笑著掃過全場、轉身向樓上走去。"
  },
  AvgDialog_131222_Content_69 = {
    Text = "索……索蕾爾！……珈倫"
  },
  AvgDialog_131222_Content_7 = {
    Text = "……啊、歡迎您、福根先生。主人正在裡面等候您的到來、請進。"
  },
  AvgDialog_131222_Content_70 = {
    Text = "你的喊聲淹沒在人群的議論與呼喊聲中。"
  },
  AvgDialog_131222_Content_71 = {
    Text = "索蕾爾夫人！索蕾爾夫人！請問您是如何規劃商業區的劃分的？這是否會觸及到……"
  },
  AvgDialog_131222_Content_72 = {
    Text = "嘘、記者先生。我剛剛從外面處理完事情回來、等我更衣之後、我會回答你想知道的所有問題。"
  },
  AvgDialog_131222_Content_73 = {
    Text = "索蕾爾向記者招手致意、走入了莊園樓上的臥室區域。"
  },
  AvgDialog_131222_Content_74 = {
    Text = "看來我們得等她出來以後再問她了。"
  },
  AvgDialog_131222_Content_75 = {
    Text = "你有注意到索蕾爾身旁的那位侍女嗎？"
  },
  AvgDialog_131222_Content_76 = {
    Text = "珈倫？當然、她應該也沒有聽見……等等、你的意思是……"
  },
  AvgDialog_131222_Content_77 = {
    Text = "你回憶起珈倫身上的氣息。那道氣息與你所熟悉的完全不同、即便是處在不同的維度、它們也不可能屬於同一個人。"
  },
  AvgDialog_131222_Content_78 = {
    Text = "我在她的身上感受到了不屬於這個舞台的命運軌跡……她的命運被汙染了。"
  },
  AvgDialog_131222_Content_79 = {
    Text = "索蕾爾夫人有危險"
  },
  AvgDialog_131222_Content_8 = {
    Text = "哼、連福根這樣滿身銅臭味的商人也能出入老公爵的府邸、倫蒂尼恩的風度已經徹底消逝了啊……"
  },
  AvgDialog_131222_Content_80 = {
    Text = "你用力擠開人群、從大樓的後面找到了一道隱秘的樓梯。"
  },
  AvgDialog_131222_Content_81 = {
    Text = "抱歉，{Male=先生,Female=小姐}，這裡是索蕾爾夫人的私人住所，禁止無關……"
  },
  AvgDialog_131222_Content_82 = {
    Text = "索蕾爾夫人邀請我前來與她商議要事。"
  },
  AvgDialog_131222_Content_83 = {
    Text = "你掏出一張隨手扯下的餐巾。銀光閃耀、一張審查會的警官證擺在了衛兵面前。"
  },
  AvgDialog_131222_Content_84 = {
    Text = "抱歉、沒有認出您來……索蕾爾夫人正在上面、我可以為您……"
  },
  AvgDialog_131222_Content_85 = {
    Text = "機密任務、我來的事情不要讓別人知道。"
  },
  AvgDialog_131222_Content_86 = {
    Text = "沒等警員說話、你趕緊跑上了樓梯。"
  },
  AvgDialog_131222_Content_88 = {
    Text = "您的衣服準備好了、索蕾爾夫人"
  },
  AvgDialog_131222_Content_89 = {
    Text = "倫蒂尼恩是一片原始的荒野、政客與商人是這座城市的鬣狗……"
  },
  AvgDialog_131222_Content_9 = {
    Text = "您好、請您出示邀請函。"
  },
  AvgDialog_131222_Content_90 = {
    Text = "索蕾爾拿起珈倫準備的衣服。光線透過紅色的輕紗，在華美的臥室裡投出一道鮮豔的殘影。"
  },
  AvgDialog_131222_Content_91 = {
    Text = "鬣狗也有可愛的地方。一塊腐肉、就能讓他們趨之若鶴。貪婪、鋒利、殘忍、幼稚。沒有比他們更好用的武器了。"
  },
  AvgDialog_131222_Content_92 = {
    Text = "我看他們已經等得不耐煩了……您今天出現得有些太晚，這條名貴的裙子也弄得有些髒了。"
  },
  AvgDialog_131222_Content_93 = {
    Text = "您應該早一點回來的、夫人。"
  },
  AvgDialog_131222_Content_94 = {
    Text = "索蕾爾的動作停滯了片刻。她緩緩放下血色的裙擺、望向珈倫那張平静的臉。"
  },
  AvgDialog_131222_Content_95 = {
    Text = "應該有人教過你僕人應該如何與主人說話。你今天怎麼了？"
  },
  AvgDialog_131222_Content_96 = {
    Text = "索蕾爾夫人、您的身上帶著來自東區的污漬。我很好奇、您將那位善良的先生、送去了何處？"
  },
  AvgDialog_131222_Content_97 = {
    Text = "明亮的房間暗淡了一瞬。幾道黑色的蜘蛛從陰影處化為人形、將索蕾爾包圍在中間。"
  },
  AvgDialog_131222_Content_98 = {
    Text = "您有一位非常忠誠的僕從、索蕾爾夫人。儘管她熱衷於偷竊和變賣您的資產、但對於維護您的安全這一點、她的忠誠毋庸置疑。"
  },
  AvgDialog_131222_Content_99 = {
    Text = "即使到現在，她的意志也在劇烈地抗爭著。只是很可惜，命運的強大，不是人能夠抗衡的。"
  },
  AvgDialog_131223_Content_1 = {
    Text = "命運。荒蠻，虛無，可悲的命運。被拋棄的命運們不知道自己來自何處，去向何方。"
  },
  AvgDialog_131223_Content_10 = {
    Text = "涅芙蕾亞的聲音陡然尖利起來。晦暗的光芒亮起，猩紅的絲線將她死死束縛，提燈的餘焰炙烤著她的身軀。"
  },
  AvgDialog_131223_Content_11 = {
    Text = "巨大的螯足在空中翕動、一雙巨大的流淌著黑色黏液的複眼、帶著笑意望向你們。猩紅的絲線纏繞在她的身體上、在命運的漩渦中飄蕩著。"
  },
  AvgDialog_131223_Content_12 = {
    Text = "她身側，那个匯集了絲線的破碎紡輪緩慢而無可阻擋地轉動著，絞殺著所有的舞台，絞殺著涅芙蕾亞自己。"
  },
  AvgDialog_131223_Content_14 = {
    Text = "你痛苦地捂住頭。在紡輪的轉動下、你的精神世界開始洶湧起來。你大口喘著氣、平息著那劇烈的痛楚。"
  },
  AvgDialog_131223_Content_15 = {
    Text = "在涅芙蕾亞身側，那些維度通道的碎片已經所剩無幾。你們身上的絲線、那些木偶般的紋理，愈發清晰。"
  },
  AvgDialog_131223_Content_16 = {
    Text = "維度通道的力量……她已經快要徹底吸收了"
  },
  AvgDialog_131223_Content_17 = {
    Text = "淡紫色的餘燼源源不斷地從阿拉克涅體內湧出，如同飛蛾般撲向那張幾乎已經徹底破碎的命運之網。"
  },
  AvgDialog_131223_Content_18 = {
    Text = "阿拉克涅顫抖的雙手以亘古不變的頻率，轉動著手中的紡輪。她的聲音，依然如你第一次見她時那般平靜。"
  },
  AvgDialog_131223_Content_19 = {
    Text = "你已經看見了。這是命運的交點，涅芙蕾亞。"
  },
  AvgDialog_131223_Content_2 = {
    Text = "他們被絲線牽引著，湧向你，在你的銀光中化作一灘灘黑色的黏液。"
  },
  AvgDialog_131223_Content_20 = {
    Text = "一切的錯誤、將在這裡終結。"
  },
  AvgDialog_131223_Content_21 = {
    Text = "多麼自信的宣言啊、囚徒女士。那就讓我看看、你要靠什麼來阻止神明、來阻止命運本身吧……"
  },
  AvgDialog_131223_Content_22 = {
    Text = "瘋狂的笑意在涅芙蕾亞臉上綻放。束縛著她的絲線將她提起，破碎的舞台上，她是那道唯一的光。"
  },
  AvgDialog_131223_Content_23 = {
    Text = "「來啊，世間匍匐的信眾！向我俯首叩拜！」"
  },
  AvgDialog_131223_Content_24 = {
    Text = "「至高者已從天座降下，不可違逆的結局，已在此間顯露！」"
  },
  AvgDialog_131223_Content_25 = {
    Text = "「那虛偽的命運，讓我們一起，迎接它的終結！」"
  },
  AvgDialog_131223_Content_3 = {
    Text = "黏液荒謬、虛無、可悲、如同他們的命運本身。"
  },
  AvgDialog_131223_Content_4 = {
    Text = "涅芙蕾亞沒有理會這一切，眼前的場景在她的眼前上演了無數年，她對此早已習慣。"
  },
  AvgDialog_131223_Content_5 = {
    Text = "我看清了。你所看見的那些畫面、你所看見的一切、我終於看清了……"
  },
  AvgDialog_131223_Content_6 = {
    Text = "碎片帶來的痛楚早已麻木、她微笑著望向劇院中那些混亂的空洞。"
  },
  AvgDialog_131223_Content_7 = {
    Text = "高傲的、憐憫的、淡漠的微笑，有一個瞬間，你幾乎沒有分清她與阿拉克涅。"
  },
  AvgDialog_131223_Content_8 = {
    Text = "只有身處囚籠之中的人，才能真正打開囚籠。你看見的混亂與毀滅，不是真實的命運，涅芙蕾亞……"
  },
  AvgDialog_131223_Content_9 = {
    Text = "呵呵呵呵！……這麼多年裡，你就是這樣欺騙自己嗎，阿拉克涅？"
  },
  AvgDialog_131224_Content_1 = {
    Text = "觀眾，演員，作者"
  },
  AvgDialog_131224_Content_10 = {
    Text = "這是……！"
  },
  AvgDialog_131224_Content_100 = {
    Text = "去找到%player%吧，孩子們。"
  },
  AvgDialog_131224_Content_101 = {
    Text = "去奪取%player%的力量，剪斷每一條命運的絲線，撕碎命運的巨網，讓每一個阻攔在這條道路上的人，都在道路上死去！"
  },
  AvgDialog_131224_Content_102 = {
    Text = "我們將用這個碎片的血、讓偉大的原初、再次甦醒。"
  },
  AvgDialog_131224_Content_103 = {
    Text = "當你看到你用心維護的命運之網盡皆破碎，化成一灘爛泥，你會不會像我們一樣，在無盡的虛無中沉淪呢？"
  },
  AvgDialog_131224_Content_104 = {
    Text = "命運的女神，我的好姐姐，親愛的<Red:阿拉克涅>？"
  },
  AvgDialog_131224_Content_105 = {
    Text = "舞台與觀眾席之間的間隔彷彿不再存在，空間在這個劇場中失去了意義。"
  },
  AvgDialog_131224_Content_106 = {
    Text = "凄厲的笑聲中，木偶似乎就站在你們面前，直直地凝望阿拉克涅的雙眼。"
  },
  AvgDialog_131224_Content_107 = {
    Text = "光線散去、幕落。木偶與她的笑聲消失不見、空曠的劇院中、只剩下紡輪輕輕轉動的聲音。"
  },
  AvgDialog_131224_Content_108 = {
    Text = "抱歉、我沒有完全明白……被遺棄的命運、是指什麼？"
  },
  AvgDialog_131224_Content_109 = {
    Text = "如您所見、命運是一團混亂的絲線、若是無人編織、這片宇宙將陷入無底的混亂。我想、那是我們都不願見到的景象。"
  },
  AvgDialog_131224_Content_11 = {
    Text = "在你進入門內的瞬間、身後的門消失不見。"
  },
  AvgDialog_131224_Content_110 = {
    Text = "當然……"
  },
  AvgDialog_131224_Content_111 = {
    Text = "將絲線編織成命運之網、維持這個宇宙的正常運轉、是我永恆的職責。"
  },
  AvgDialog_131224_Content_112 = {
    Text = "每個時刻，命運都有著無數的可能性。每個時刻，我都不得不為一切命運做出抉擇。"
  },
  AvgDialog_131224_Content_113 = {
    Text = "正確的命運將匯入巨網，錯誤的命運，將被拋棄。命運之網如此運轉，不可避免。"
  },
  AvgDialog_131224_Content_114 = {
    Text = "我的妹妹、亦是那些錯誤的命運裡、被我捨弃掉的一部分。"
  },
  AvgDialog_131224_Content_115 = {
    Text = "阿拉克涅微笑著，在她平靜的訴說裡，你察覺不到絲毫的情緒波動。"
  },
  AvgDialog_131224_Content_116 = {
    Text = "那些被遺棄的命運……便會被送入「淵獄」？"
  },
  AvgDialog_131224_Content_117 = {
    Text = "那位至高神明的夢境構成了這個宇宙、那個名為「淵獄」的地方、是神明的潛意識、是一切未發生之事、一切不存在的命運的聚集之地。"
  },
  AvgDialog_131224_Content_118 = {
    Text = "它們本應在那虛無之地徹底消散、但在我那位妹妹的帶領下、它們用某種方式存活了下來。"
  },
  AvgDialog_131224_Content_119 = {
    Text = "阿拉克涅望著那張巨大的帷幕，望著帷幕後，那个代表著涅芙蕾亞的木偶。"
  },
  AvgDialog_131224_Content_12 = {
    Text = "在你原本想像的狹窄店鋪內部、是一片寬廣無垠的維度空間。"
  },
  AvgDialog_131224_Content_120 = {
    Text = "她並沒有操控命運的能力、但她與我一樣、能夠看到命運的絲線、遮擋它們、汙染它們、破壞我為它們編織的軌跡、將它們引向死亡……"
  },
  AvgDialog_131224_Content_121 = {
    Text = "所以她是想要找到我、利用我的力量、重新喚醒托乎瓦波？"
  },
  AvgDialog_131224_Content_122 = {
    Text = "我無從得知她的具體計畫、但目前看來的確如此。無論如何、她是一個我必須要解決的錯誤。"
  },
  AvgDialog_131224_Content_123 = {
    Text = "她關閉維度間的通道、也是為了這個吧……"
  },
  AvgDialog_131224_Content_124 = {
    Text = "維度通道是我關閉的。她一直在等待、等待與你一同前往卡達斯的這一刻。"
  },
  AvgDialog_131224_Content_125 = {
    Text = "卡達斯是一個我的力量未曾涉足的維度、也是與那位至高神明之間的連結最為緊密之地。"
  },
  AvgDialog_131224_Content_126 = {
    Text = "若是讓她隨著你返回、災厄的命運將徹底無法挽回。"
  },
  AvgDialog_131224_Content_127 = {
    Text = "請原諒我的自作主張，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131224_Content_128 = {
    Text = "我理解，阿拉克涅。如果你說的是真的，那也不是我想要看到的景象。"
  },
  AvgDialog_131224_Content_129 = {
    Text = "所以、如果我想要返回卡達斯、必須要先解決掉她……"
  },
  AvgDialog_131224_Content_13 = {
    Text = "無數個舞台如同繁星般懸浮在這黑暗的領域之中，木偶們在每個舞台上面唱誦著自己的台詞。"
  },
  AvgDialog_131224_Content_130 = {
    Text = "主人、GI-9849號區域的舞台出現異常。今天的第三例了。"
  },
  AvgDialog_131224_Content_131 = {
    Text = "將編織命運的材料偷走之後，她總是對破壞命運這件事樂此不疲。"
  },
  AvgDialog_131224_Content_132 = {
    Text = "很抱歉，%player%，我現在需要去處理那些麻煩。請您隨我來，有些重要事情，我想需要讓您知曉。"
  },
  AvgDialog_131224_Content_133 = {
    Text = "阿拉克涅微笑著搖了搖頭。她向你做出一個邀請的手勢，帶上紡輪站起身來。"
  },
  AvgDialog_131224_Content_135 = {
    Text = "這裡……就是被破壞的舞台？……"
  },
  AvgDialog_131224_Content_136 = {
    Text = "順著蛛網織成的道路、你們來到一處破舊的舞台。舞台上簡易的咖啡館裡、幾名學生模樣的人正在低頭交談著。"
  },
  AvgDialog_131224_Content_137 = {
    Text = "這段時間、她一直在派遣她的那些侍從四處破壞這些世界的命運。我的侍女們正在四處搜尋她們、與她們的戰鬥、讓很多好孩子失去了生命。"
  },
  AvgDialog_131224_Content_138 = {
    Text = "所有世界的命運都連接在同一張巨網上、每一個世界的崩潰、都將讓整個命運之網被撕毀、讓一切陷入徹底、致命的無序之中。"
  },
  AvgDialog_131224_Content_139 = {
    Text = "涅芙蕾亞竊走了編織命運的材料，我無法輕易地使用自己的力量。守密人{Male=先生,Female=小姐}，我想，或許您能夠幫助我，修復這個世界的命運？"
  },
  AvgDialog_131224_Content_14 = {
    Text = "那些台詞遠遠地傳入你的耳中，如同無數信徒虔誠地誦念。"
  },
  AvgDialog_131224_Content_140 = {
    Text = "如果你所說屬實、她也是我必須要解決的問題。"
  },
  AvgDialog_131224_Content_141 = {
    Text = "阿拉克涅抱歉地向你點了點頭。她舉起手，輕輕撥動虛無的空氣中，那些隱秘的絲線。"
  },
  AvgDialog_131224_Content_142 = {Text = "鐺——"},
  AvgDialog_131224_Content_143 = {
    Text = "清脆的樂器聲之後、報幕人悠揚的聲音響起、如同一道無休止匯入深潭的永恆的清流。"
  },
  AvgDialog_131224_Content_144 = {
    Text = "喇叭奏花腔。青年學生與學者、上——"
  },
  AvgDialog_131224_Content_145 = {
    Text = "阿拉克涅做出一個邀請的手勢。"
  },
  AvgDialog_131224_Content_146 = {
    Text = "到我們登場的時候了，%player%。"
  },
  AvgDialog_131224_Content_147 = {
    Text = "你點了點頭。悠揚的報幕聲中、兩個木偶踏上了屬於它們的舞台。"
  },
  AvgDialog_131224_Content_15 = {
    Text = "一道道蛛絲從木偶演員和舞台上延伸出來、連同你腳下這片由蛛絲織成的道路一起、向這片空間最中央的那個舞台匯集。"
  },
  AvgDialog_131224_Content_16 = {
    Text = "你回過頭、一旁的侍女已經朝前方走去。"
  },
  AvgDialog_131224_Content_17 = {
    Text = "真是個奇怪的歡迎儀式……"
  },
  AvgDialog_131224_Content_18 = {
    Text = "你猶豫著、沿著蛛網道路向中央那個舞台走去。在你經過那些懸浮的舞台時、一段段對話飄進你的耳朵。"
  },
  AvgDialog_131224_Content_19 = {
    Text = "這位顧客、我從您的眼睛裡看到了迷茫。"
  },
  AvgDialog_131224_Content_2 = {
    Text = "我還有一個問題……"
  },
  AvgDialog_131224_Content_20 = {
    Text = "剛才店裡發生的事故沒有嚇壞您吧？"
  },
  AvgDialog_131224_Content_21 = {
    Text = "以金酒為基底的結構、帶上木槿花的風味、一定很適合您現在的心境。"
  },
  AvgDialog_131224_Content_23 = {
    Text = "啊！一位無家可歸的流浪兒、如此的幼小、如此的可憐。"
  },
  AvgDialog_131224_Content_24 = {
    Text = "依靠這些單薄的衣服、你該如何挺過這個冬天？"
  },
  AvgDialog_131224_Content_25 = {
    Text = "跟我來吧，我會帶你去到一個遮蔽風雪的地方……"
  },
  AvgDialog_131224_Content_27 = {
    Text = "這些……是我剛才遇見的那些人？"
  },
  AvgDialog_131224_Content_28 = {
    Text = "他們怎麼會出現在這些舞台上……"
  },
  AvgDialog_131224_Content_29 = {
    Text = "巡視的警察、看報紙的職員、欣賞街景的司機、買花的戀人、交談的貴族……"
  },
  AvgDialog_131224_Content_3 = {
    Text = "這已經是您第二十三個問題了，{Male=先生,Female=小姐}。"
  },
  AvgDialog_131224_Content_30 = {
    Text = "那些你見過和沒有見過的人、在這無數的舞台上上演他們自己的故事。在各自的舞台上、他們都是自己各自的主角。"
  },
  AvgDialog_131224_Content_31 = {
    Text = "萬福，%player%！祝福你，阿庫特的嬰孩！"
  },
  AvgDialog_131224_Content_32 = {
    Text = "萬福，%player%！祝福你，彌薩格的守密人！"
  },
  AvgDialog_131224_Content_33 = {
    Text = "萬福，%player%！祝福你，毀滅萬物的神明！"
  },
  AvgDialog_131224_Content_34 = {
    Text = "在你們靠近中央的舞台之後、三名形狀各異的木偶登上舞台、向著你的方向鞠躬致意。"
  },
  AvgDialog_131224_Content_35 = {
    Text = "主人正在裡面等你。請進，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131224_Content_36 = {
    Text = "在包廂的門打開的時候、似乎整座劇院的影像與聲音都暫停了一瞬。"
  },
  AvgDialog_131224_Content_37 = {
    Text = "你跨入門內、掀開簾幕——"
  },
  AvgDialog_131224_Content_38 = {
    Text = "他們出現在這些舞台上、因為這座劇院的名字、叫做命運。"
  },
  AvgDialog_131224_Content_39 = {
    Text = "清冷、溫和的聲音比色彩早一步來到你面前。"
  },
  AvgDialog_131224_Content_4 = {
    Text = "比起這個地方的謎題、我的問題還遠遠不夠。"
  },
  AvgDialog_131224_Content_40 = {
    Text = "一個近乎無垠的包廂內，連接舞台與木偶的絲線匯集在一台閃爍著微光的紡輪上。一個女人坐在絲線的交匯處，將紡輪溫柔地轉動。"
  },
  AvgDialog_131224_Content_41 = {
    Text = "你清楚地看到了她的每一個細節，但在每一個眨眼的瞬間，關於她的一切印象都在你的精神世界中消失，蕩然無存。"
  },
  AvgDialog_131224_Content_42 = {
    Text = "她的形象在你腦海中始終是模糊的。在她轉頭望向你的時候，你那顆一直保持著高度戒備的心臟猛烈地跳動起來。"
  },
  AvgDialog_131224_Content_44 = {
    Text = "樂園號上……還有幾次襲擊我們的人……！"
  },
  AvgDialog_131224_Content_45 = {
    Text = "在你準備將精神力量注入銀鑰匙的瞬間、劇院的主人伸出手、在空中劃過。她的動作輕柔優雅、似乎是在輕輕撥動一根弦。"
  },
  AvgDialog_131224_Content_47 = {
    Text = "精神力量來到你的指尖、又如同被堤壩阻攔的洪流般退回。當你將手抬在半空的時候你才猛然發現、不知從什麼時候開始、你的手上空空如也。"
  },
  AvgDialog_131224_Content_48 = {
    Text = "銀鑰匙……銀鑰匙一直在我手上……為什麼……"
  },
  AvgDialog_131224_Content_49 = {
    Text = "她微笑著朝侍女輕輕點頭。"
  },
  AvgDialog_131224_Content_5 = {
    Text = "我並非您要找的那個解答者。能夠回答您問題的人、正在這裡等您。"
  },
  AvgDialog_131224_Content_50 = {
    Text = "在你驚詫的眼神裡，侍女走上前來，恭敬地將銀鑰匙遞到你的手上。"
  },
  AvgDialog_131224_Content_51 = {
    Text = "不可能……她絕不可能偷到銀鑰匙！……"
  },
  AvgDialog_131224_Content_52 = {
    Text = "在進入劇院以前，您就將鑰匙握在手裡，並一直保持著與銀鑰匙的精神鏈接。"
  },
  AvgDialog_131224_Content_53 = {
    Text = "彌薩格的訓練為您帶來了高度的專業與警惕性，沒有任何人能夠從您手裡將銀鑰匙盜走。"
  },
  AvgDialog_131224_Content_54 = {
    Text = "那是為什麼……"
  },
  AvgDialog_131224_Content_55 = {
    Text = "沒有人能讓它離開您、但命運可以。"
  },
  AvgDialog_131224_Content_56 = {
    Text = "很抱歉，%player%，我理解您的緊張，也尊重您的力量。"
  },
  AvgDialog_131224_Content_57 = {
    Text = "為了防止您對劇院無意中的傷害，我不得不短暫地修改了您手中銀鑰的命運，還請您見諒。"
  },
  AvgDialog_131224_Content_58 = {
    Text = "她揮揮手，一束光照向你與她之間。你認真看去，終於看到一條若有若無的絲線從銀鑰匙上延伸出去，連接到她的紡輪上面。"
  },
  AvgDialog_131224_Content_59 = {
    Text = "這些絲線是……？"
  },
  AvgDialog_131224_Content_6 = {
    Text = "你們停在一個只有一人寬的劇院門前。沒有招牌、也沒有顧客、在倫蒂尼恩華麗的店鋪中像是一張毫不起眼的蛛網。"
  },
  AvgDialog_131224_Content_60 = {
    Text = "關於絲線的解釋很多、有些對於當下而言過於複雜。您可以簡單地將它們理解為……命運。"
  },
  AvgDialog_131224_Content_61 = {
    Text = "紡輪兀自輕輕轉動著。她站起身，向你點頭致意。"
  },
  AvgDialog_131224_Content_62 = {
    Text = "阿拉克涅，命運劇院的主人。很榮幸見到您，守密人。"
  },
  AvgDialog_131224_Content_63 = {
    Text = "請不必擔心、您在這裡是安全的。"
  },
  AvgDialog_131224_Content_64 = {
    Text = "的確、如果你想殺死我、剛才我恐怕沒有任何機會活下來。"
  },
  AvgDialog_131224_Content_65 = {
    Text = "隨著阿拉克涅撥動絲線，包廂內那些來自紡輪的光線暗淡下去。你神色複雜地看著侍女歸還的銀鑰匙，皺著眉頭望向她。"
  },
  AvgDialog_131224_Content_66 = {
    Text = "在樂園號上，你曾為我提供過幫助。在這座城市裡，你又曾兩次襲擊我……"
  },
  AvgDialog_131224_Content_67 = {
    Text = "我理解您的警惕。但請相信，我從未做出傷害您的事情。"
  },
  AvgDialog_131224_Content_68 = {
    Text = "封鎖了我與卡達斯的連結、多次對我進行襲擊……你是想說、這些事情都不是你做的？"
  },
  AvgDialog_131224_Content_69 = {
    Text = "那位打擾您的人雖然與我有着一樣的面孔、但並不是我。"
  },
  AvgDialog_131224_Content_7 = {
    Text = "侍女輕輕將門推開、身影隱入門內的黑暗。黑暗中不知從何而來的光線微微閃爍、像是一道隱秘的邀請。"
  },
  AvgDialog_131224_Content_70 = {
    Text = "至於您與卡達斯的鏈接……那是一個危險的陷阱，%player%。"
  },
  AvgDialog_131224_Content_72 = {
    Text = "一個因我而產生的孩子，對您造成了不必要的麻煩，萬分抱歉。這件事情因我而起，我也正在盡我所能，彌補這個錯誤。"
  },
  AvgDialog_131224_Content_73 = {
    Text = "我沒有聽明白……"
  },
  AvgDialog_131224_Content_74 = {
    Text = "這是一個與命運相關的、有些漫長的故事。故事總是比單純的陳述更容易讓人理解。"
  },
  AvgDialog_131224_Content_75 = {
    Text = "請入座吧，守密人{Male=先生,Female=小姐}。這一幕新的戲劇，在不久前才剛剛上演。"
  },
  AvgDialog_131224_Content_76 = {
    Text = "阿拉克涅輕輕揮手。帘幕拉開，一個懸浮著的空曠舞台出現在你面前。"
  },
  AvgDialog_131224_Content_77 = {
    Text = "舞台上似乎存在著一面若隱若現的鏡子、映出你們的身形。"
  },
  AvgDialog_131224_Content_78 = {
    Text = "樂聲起。被拋棄的命運，上。"
  },
  AvgDialog_131224_Content_79 = {
    Text = "很快，鏡面上你的身形消失不見，阿拉克涅的身形變為一個人偶。"
  },
  AvgDialog_131224_Content_8 = {
    Text = "你稍稍猶豫了一下、走入門內。"
  },
  AvgDialog_131224_Content_80 = {
    Text = "她依然坐在座椅上，但溫和與從容消失不見。"
  },
  AvgDialog_131224_Content_81 = {
    Text = "她搖晃著手裡盛滿鮮血的酒杯，如同端坐在一個殘忍的王座。一道天真、殘忍的視線掃過觀眾席。"
  },
  AvgDialog_131224_Content_82 = {
    Text = "在她身後，四對鋒利的蜘蛛節肢悠閒地擺動著，貼著身旁那些侍從們的臉邊劃過。"
  },
  AvgDialog_131224_Content_83 = {
    Text = "啊、自由的空氣……"
  },
  AvgDialog_131224_Content_84 = {
    Text = "我們被那片淵獄囚禁了多少年了、我親愛的侍從？"
  },
  AvgDialog_131224_Content_85 = {
    Text = "我不知道、我的主人。"
  },
  AvgDialog_131224_Content_86 = {
    Text = "名字，時間，情緒……我已遺忘了一切……我只記得您，我的主人，尊敬的涅芙蕾亞。"
  },
  AvgDialog_131224_Content_87 = {
    Text = "我隻記得、您對我說、會將我們帶離這裡、會帶我們、向命運揮動復仇的利刃。"
  },
  AvgDialog_131224_Content_88 = {
    Text = "我記得、孩子。我向你們做出了九萬次承諾、現在、讓我告訴你第九萬零一次。"
  },
  AvgDialog_131224_Content_89 = {
    Text = "每一個時刻、都只能存在一種命運。那命運的代行者、將無數錯誤的命運割除、將唯一正確的命運留下。"
  },
  AvgDialog_131224_Content_90 = {
    Text = "我們、便是那被拋棄的命運。呵呵呵呵……我親愛的侍從、你是一個錯誤、就像我一樣。"
  },
  AvgDialog_131224_Content_91 = {
    Text = "在這宇宙的潛意識之中、在這不存在的虛無淵獄、我們被放逐、囚禁。我們在此遊蕩、遺忘、永生永世。我們的刑期、比時間本身更加漫長……"
  },
  AvgDialog_131224_Content_92 = {
    Text = "名為涅芙蕾亞的女子從座椅上起身，彎下腰，微笑著與觀眾席上的阿拉克涅對視。"
  },
  AvgDialog_131224_Content_93 = {
    Text = "可是、憑什麼呢、命運的女神？憑什麼、被剔除的、就應該是我們呢？"
  },
  AvgDialog_131224_Content_94 = {
    Text = "無數宇宙那至高的、唯一的神明、終於醒來了一瞬。祂再次陷入沉睡、可祂意識的囚籠、那永恆的淵獄、終於為我們打開。"
  },
  AvgDialog_131224_Content_95 = {
    Text = "我本來也已遺忘、消亡。可為什麼、為什麼又偏偏要讓我想起這痛苦的一切？"
  },
  AvgDialog_131224_Content_96 = {
    Text = "涅芙蕾亞飲盡杯中的液體，發出一聲滿足的嘆息。鮮紅的汁液順著她蒼白的嘴唇落下，滴落在她手中黯淡的紡輪上。"
  },
  AvgDialog_131224_Content_97 = {
    Text = "或許、這便是命運的安排吧……連你也無法掌控的命運。"
  },
  AvgDialog_131224_Content_98 = {
    Text = "原初的神明再次沉睡、但祂的碎片、來到了我們的居所。"
  },
  AvgDialog_131224_Content_99 = {
    Text = "我沒有如你般操控命運的能力。我只是命運的修正者、是來自虛無的行刑人。命運長河裡的那些罪孽、將由我來為原初進行懲罰。"
  },
  AvgDialog_131225_Content_10 = {
    Text = "與你憑藉經驗構想出的空曠截然不同，這棟別墅的內部顯得異常擁擠，涅芙蕾亞似乎鐵了心要在她的劇本裡亂寫一氣。"
  },
  AvgDialog_131225_Content_11 = {
    Text = "綿延不絕的箱櫃與置物架沉默而擁擠地站立、各種大小的罐子塞滿了它們的每一處空間。"
  },
  AvgDialog_131225_Content_12 = {
    Text = "銀鏡、蛛卵、異蟲爬行的舞鞋……各式各樣的物體浸泡在不明液體裡、像是一張張無聲呐喊著的嘴。"
  },
  AvgDialog_131225_Content_13 = {
    Text = "你來到那些形形色色的罐子面前、輕聲念起標籤上的文字。"
  },
  AvgDialog_131225_Content_14 = {
    Text = "兩歲、說出了人生中的第一句話。沒有呼喚自己的家人、而是與照顧自己家族數代的老管家告別。"
  },
  AvgDialog_131225_Content_15 = {
    Text = "當天晚上、老管家因心臟病去世。拿著管家的遺物、在管家的門房外哭泣……"
  },
  AvgDialog_131225_Content_16 = {
    Text = "那是一枚陳舊的家族胸針。"
  },
  AvgDialog_131225_Content_17 = {
    Text = "五歲、晚宴的賓客們讓人臉紅的歡呼聲裡、學著母親的樣子害羞地跳起華爾茲……"
  },
  AvgDialog_131225_Content_18 = {
    Text = "那是一雙鮮豔的紅舞鞋。"
  },
  AvgDialog_131225_Content_19 = {
    Text = "七歲、收到父親贈送的生日禮物、一個名為「摩伊賴」的紡輪。"
  },
  AvgDialog_131225_Content_2 = {
    Text = "布里克巷、你還記得在倫蒂尼恩的這片區域調查時的場景。"
  },
  AvgDialog_131225_Content_20 = {
    Text = "在紡輪的絲線中、看到命運的投影……"
  },
  AvgDialog_131225_Content_21 = {
    Text = "那是一捧斷裂的紡線。"
  },
  AvgDialog_131225_Content_22 = {
    Text = "第一次與父母前往歌劇院……第一次結識摯友……第一次埋葬自己的愛犬……"
  },
  AvgDialog_131225_Content_23 = {
    Text = "罐子標籤上的文字一張張映入你眼中。每當你觸碰它們，一段模糊的記憶便在你腦中若隱若現。你回過頭，疑惑地望向阿拉克涅。"
  },
  AvgDialog_131225_Content_24 = {
    Text = "這些……都是你的記憶？"
  },
  AvgDialog_131225_Content_25 = {
    Text = "是我曾經的記憶。在很早之前、它們便屬於那位叫做「回憶」的秘偶。"
  },
  AvgDialog_131225_Content_26 = {
    Text = "這都是些珍貴的回憶……為什麼要把它們放在一個秘偶身上？"
  },
  AvgDialog_131225_Content_27 = {
    Text = "每個人的生命中、都需要做出一些選擇。每一個選擇、都有代價。"
  },
  AvgDialog_131225_Content_28 = {
    Text = "為了抵達那個終點，我們總是需要捨棄一些東西的。我想，您應該非常理解這一點，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131225_Content_29 = {
    Text = "阿拉克涅沒有直接回答你的問題，她望著那些櫃子，從那些盛滿液體的罐子上輕輕撫過。"
  },
  AvgDialog_131225_Content_3 = {
    Text = "骯髒、混亂、空氣中滿是煤煙與下水道的氣味、這些氣味陪伴了梅森與詹金度過了生前的所有時光。"
  },
  AvgDialog_131225_Content_30 = {
    Text = "她的動作很輕、很慢、像是一個垂暮的老人、撫過那些童年時珍愛的玩具。"
  },
  AvgDialog_131225_Content_31 = {
    Text = "將這些記憶從秘偶的身上取出，以這樣的形式顯化。這是你為我準備的景觀吧，涅芙蕾亞。"
  },
  AvgDialog_131225_Content_32 = {
    Text = "你想告訴我的、我聽明白了……"
  },
  AvgDialog_131225_Content_34 = {
    Text = "凄厲的慘叫聲在房間中迴蕩、盛放回憶的罐子們輕輕震蕩、像是一群無聲歡笑著的觀眾。"
  },
  AvgDialog_131225_Content_35 = {
    Text = "！！在走廊後面的房間裡"
  },
  AvgDialog_131225_Content_37 = {
    Text = "你快步跑過走廊、撞開了房門……"
  },
  AvgDialog_131225_Content_38 = {
    Text = "你置身於一場暴雨。"
  },
  AvgDialog_131225_Content_39 = {
    Text = "沒有雷鳴、沒有風、也沒有雨水。只有密密麻麻的蜘蛛、從空曠的天花板上如暴雨般墜下。"
  },
  AvgDialog_131225_Content_4 = {
    Text = "而此時、一棟金碧輝煌的別墅突兀地出現在兩棟棚戶房之間、像是被擺放在垃圾堆中的珠寶盒。"
  },
  AvgDialog_131225_Content_40 = {
    Text = "黏稠的黑色節肢動物匯成洶湧的潮水、吞噬著屋內所有的物體與所有的光。"
  },
  AvgDialog_131225_Content_41 = {
    Text = "陰暗暴雨的中心、那些發瘋般攀爬、啃食的蜘蛛匯集成一個勉強能辨認出的人形。在蜘蛛的潮水尚未覆蓋之處、露出一張你曾見過的蒼老人的臉。"
  },
  AvgDialog_131225_Content_44 = {
    Text = "噓……這裡沒有你的台詞、「善良」先生。"
  },
  AvgDialog_131225_Content_45 = {
    Text = "命運的復仇、第二幕第二場。我將它命名為、「暴雨」。"
  },
  AvgDialog_131225_Content_46 = {
    Text = "好好沐浴在這美妙的雨中吧、我親愛的觀眾。"
  },
  AvgDialog_131225_Content_47 = {
    Text = "積水泛起浪潮、黑色的蜘蛛們聆聽到至高的指令、湧向房間的各個角落。"
  },
  AvgDialog_131225_Content_48 = {
    Text = "在涅芙蕾亞的讚嘆聲裡，蜘蛛匯成的警衛、侍從與令人作噁的生物，向你們汹湧而來——"
  },
  AvgDialog_131225_Content_5 = {
    Text = "流浪漢與疲憊的工人們從這個華麗的盒子面前走過、沒有任何一個人投去多餘的目光、彷彿自他們出生時它便存在於此。"
  },
  AvgDialog_131225_Content_6 = {
    Text = "竟然連這座城市的命運也受到了影響……涅芙蕾亞的力量，的確在增強。"
  },
  AvgDialog_131225_Content_7 = {
    Text = "你警惕地走上前去、本來想敲門、但當你手剛放在門上、門便悄無聲息地打開。"
  },
  AvgDialog_131225_Content_8 = {
    Text = "看來、我們貼心的主人專門為我們留了門。"
  },
  AvgDialog_131225_Content_9 = {
    Text = "這是……"
  },
  AvgDialog_131226_Content_1 = {
    Text = "殺……殺人了！"
  },
  AvgDialog_131226_Content_10 = {
    Text = "剛剛的事情我都看到了。你沒有穿過那個通道，%player%。這裡，不是我們要回到的地方。"
  },
  AvgDialog_131226_Content_11 = {
    Text = "我也覺得奇怪……融蝕和彌薩格、那些天災、他們竟然全都不知道。"
  },
  AvgDialog_131226_Content_12 = {
    Text = "可這座城市的樣子、和那場災難發生前、和我記憶中的樣子一模一樣。或許、我們現在回學校看看吧、說不定能發現些什麼……"
  },
  AvgDialog_131226_Content_13 = {
    Text = "我剛剛從那裡返回。這裡沒有彌薩格，%player%。"
  },
  AvgDialog_131226_Content_14 = {
    Text = "沒有……？"
  },
  AvgDialog_131226_Content_15 = {
    Text = "店鋪裡的世界地圖是我沒有見過的樣子、所有的日曆上標註的年份、也都和洪積紀年完全不同。"
  },
  AvgDialog_131226_Content_16 = {
    Text = "最詭異的事情是……這座城市沒有盡頭。"
  },
  AvgDialog_131226_Content_17 = {
    Text = "沒有……盡頭？"
  },
  AvgDialog_131226_Content_18 = {
    Text = "從原來彌薩格的方向繼續向北、便能離開倫蒂尼恩的範圍。"
  },
  AvgDialog_131226_Content_19 = {
    Text = "我在路上也遭遇了這些蜘蛛的襲擊、為了躲避它們、我沿著那條路前行、但最後……我回到了你所在的位置附近、倫蒂尼恩的南部。"
  },
  AvgDialog_131226_Content_2 = {
    Text = "人群尖叫著跑開。不知道什麼時候，那頭醒目的金髮出現在你身側。"
  },
  AvgDialog_131226_Content_20 = {
    Text = "這裡不是倫蒂尼恩、這裡不是卡達斯。"
  },
  AvgDialog_131226_Content_21 = {
    Text = "看來我的記憶沒有出錯……那個通道、的確在我進入之前關閉了……"
  },
  AvgDialog_131226_Content_22 = {
    Text = "你望向通道外那些熟悉的景致，失落地嘆息著。"
  },
  AvgDialog_131226_Content_23 = {
    Text = "一個與倫蒂尼恩一模一樣的地方，一座沒有邊際的城市，那些不知道從哪裡出現的黑色蜘蛛……還有牠們口中的主人……"
  },
  AvgDialog_131226_Content_24 = {
    Text = "現在還不能斷定，但我想，通道的關閉和我們出現在這裡，一定不是巧合。有人刻意設計了這一切——那些蜘蛛的主人。"
  },
  AvgDialog_131226_Content_25 = {
    Text = "現在我們什麼都還不清楚，需要先蒐集情報……"
  },
  AvgDialog_131226_Content_27 = {Text = "誰？！"},
  AvgDialog_131226_Content_28 = {
    Text = "銀色的光輝在威廉那隻機械手掌中閃耀、如同一柄隨時能夠出鞘的利刃。"
  },
  AvgDialog_131226_Content_29 = {
    Text = "在那道危險的銀光裡、你看到那個剛剛想要遞給你食物的老人。"
  },
  AvgDialog_131226_Content_3 = {
    Text = "威廉學長……你是什麼時候……這是怎麼回事？"
  },
  AvgDialog_131226_Content_31 = {
    Text = "這個……是您的吗？"
  },
  AvgDialog_131226_Content_32 = {
    Text = "老人攤開手。那枚用來通訊的彌薩格校徽、靜靜躺在他粗糙的手心裡。"
  },
  AvgDialog_131226_Content_33 = {
    Text = "啊！是剛才戰鬥的時候掉下的……"
  },
  AvgDialog_131226_Content_34 = {
    Text = "這個東西對我很重要……非常感謝！"
  },
  AvgDialog_131226_Content_35 = {
    Text = "在威廉警惕的目光裡、你拿回了校徽、認真保存好。"
  },
  AvgDialog_131226_Content_36 = {
    Text = "老人家……剛才發生的那些事、您不害怕嗎？"
  },
  AvgDialog_131226_Content_37 = {
    Text = "是害怕……我在這裡生活了一輩子、哪見過這些……"
  },
  AvgDialog_131226_Content_38 = {
    Text = "不過我看那東西對你挺重要、你剛剛到這裡、要是丟了恐怕都不知道去哪裡找、就給你送過來了。"
  },
  AvgDialog_131226_Content_39 = {
    Text = "真是太謝謝您了……"
  },
  AvgDialog_131226_Content_4 = {
    Text = "這裡不是說話的地方。走"
  },
  AvgDialog_131226_Content_40 = {
    Text = "我們剛到這裡、很多事情不知道、有些事情、能詢問您嗎？"
  },
  AvgDialog_131226_Content_41 = {
    Text = "我倒是不介意和兩位年輕人多聊聊天，不過我知道的東西實在有限，恐怕幫不上什麼忙。"
  },
  AvgDialog_131226_Content_42 = {
    Text = "或許，你們現在更需要找一個人多的地方。"
  },
  AvgDialog_131226_Content_43 = {
    Text = "好了、東西送到、我就先回去了。"
  },
  AvgDialog_131226_Content_44 = {
    Text = "老人擺了擺手、沒有再理會你們的挽留、離開了小巷。"
  },
  AvgDialog_131226_Content_45 = {
    Text = "這個老人看起來沒有什麼惡意。他說得沒錯、我們需要儘快找一個消息更加流通的地方。"
  },
  AvgDialog_131226_Content_46 = {
    Text = "我想到一個去處！"
  },
  AvgDialog_131226_Content_47 = {
    Text = "如果這座城市和倫蒂尼恩一模一樣、那裡一定會是最合適的。"
  },
  AvgDialog_131226_Content_48 = {
    Text = "在你們離開的時候，一隻淡紫色的蜘蛛隱匿在你們餘光的盲區，順著蛛網爬入牆壁的縫隙之中，消失不見。"
  },
  AvgDialog_131226_Content_7 = {
    Text = "這附近應該沒人了。"
  },
  AvgDialog_131226_Content_8 = {
    Text = "這是怎麼一回事？倫蒂尼恩為什麼變成了這個樣子……"
  },
  AvgDialog_131226_Content_9 = {
    Text = "那些襲擊我們的蜘蛛，還有那個人……和之前在樂園號上面遇見的人似乎有什麼關聯？"
  },
  AvgDialog_131227_Content_2 = {
    Text = "我明白、守密人。"
  },
  AvgDialog_131227_Content_3 = {
    Text = "你的命運已被修改。你無法停下、也不應停下。"
  },
  AvgDialog_131227_Content_4 = {
    Text = "阿拉克涅無法將未來的命運宣之於口……請告訴我，我應該怎麼做……"
  },
  AvgDialog_131227_Content_5 = {
    Text = "我無法向你言明門後之物。在這件事上、有比我更適合幫助你的人。"
  },
  AvgDialog_131227_Content_6 = {
    Text = "向前吧、守密人。你的命運、需要由你自己去看清。"
  },
  AvgDialog_131228_Content_1 = {
    Text = "嗯……英雄與小丑、命運的提線木偶……不錯的戲碼。"
  },
  AvgDialog_131228_Content_2 = {
    Text = "阿拉克涅告訴我，解開鎖的鑰匙是「歡愉」……這是你的領域，N。"
  },
  AvgDialog_131228_Content_3 = {
    Text = "嘘！不要這麼著急。破壞一場好戲、是這個宇宙裡最不可饒恕的罪孽。"
  },
  AvgDialog_131228_Content_4 = {
    Text = "來吧、守密人。這麼長時間不見、讓我看看、你對歡愉、是否有了一些新的體悟？"
  },
  AvgDialog_131229_Content_10 = {
    Text = "回應我……莉茲！……"
  },
  AvgDialog_131229_Content_11 = {
    Text = "她的命運絲線已經斷裂……她的生命已經結束了。"
  },
  AvgDialog_131229_Content_12 = {
    Text = "<Shake:不……我們不能讓涅芙蕾亞就這樣得逞>，她必須為她的肆意妄為付出代價"
  },
  AvgDialog_131229_Content_13 = {
    Text = "將要付出的代價、命運已為她備好。線索不會就這樣斷在這裡。"
  },
  AvgDialog_131229_Content_14 = {
    Text = "可是、你剛說莉茲現在已經……"
  },
  AvgDialog_131229_Content_15 = {
    Text = "死亡是命運的一部分。這裡是我的舞台，守密人{Male=先生,Female=小姐}。一切命運，都是我手中的絲線。它們的走向，<color=#8C7E96>不由他人編織</color>。"
  },
  AvgDialog_131229_Content_18 = {
    Text = "阿拉克涅的臉上無悲無喜。她走向那名被涅芙蕾亞短暫寄生的報幕人。黃昏的微光勾勒出她模糊、穩定的剪影，如同命運本身。"
  },
  AvgDialog_131229_Content_19 = {
    Text = "呵……哈哈哈哈……阿拉克涅，你還是那麼、那麼自大！哈哈哈哈……"
  },
  AvgDialog_131229_Content_2 = {
    Text = "四周的敵人倒下了、但你的攻擊仍未停止。"
  },
  AvgDialog_131229_Content_20 = {
    Text = "涅芙蕾亞似乎看到了什麼天大的樂子，笑得在地上打滾。"
  },
  AvgDialog_131229_Content_21 = {
    Text = "汙染莉茲的命運、讓她迎來死亡的結局……你所做的每一件事、命運之網都將銘記。"
  },
  AvgDialog_131229_Content_22 = {
    Text = "錯誤的命運將被修正。在你命運的前方、自然有代價在等待著你。"
  },
  AvgDialog_131229_Content_23 = {
    Text = "阿拉克涅伸出手，輕輕在這具屍體的頭頂撥動。手中的紡輪輕輕轉動，你身周的一切，似乎都在這轉動中扭曲著、重組著……"
  },
  AvgDialog_131229_Content_24 = {
    Text = "命運的絲線、傾聽網的呼喚。沿著那唯一的道路、重新登上舞台吧……"
  },
  AvgDialog_131229_Content_25 = {
    Text = "她的身體……消失不見了？"
  },
  AvgDialog_131229_Content_26 = {
    Text = "隨著阿拉克涅手指的撥動，舞台的上方，莉茲的屍體如同正經歷一場無聲的燃燒，化為餘燼消散在空中。"
  },
  AvgDialog_131229_Content_27 = {
    Text = "在那些脫落的灰燼之下、一個新的身體呈現在你眼前。"
  },
  AvgDialog_131229_Content_28 = {
    Text = "是……那個報幕人？"
  },
  AvgDialog_131229_Content_29 = {
    Text = "尖刺刺穿報幕人的身體、將她懸掛在舞台的上方、所有的動作、幅度、都和莉茲一模一樣。"
  },
  AvgDialog_131229_Content_3 = {
    Text = "你嘶吼著、發瘋似的將報幕人那張微笑著的臉踩碎在舞台的木板上。"
  },
  AvgDialog_131229_Content_30 = {
    Text = "報幕人遺留下狰狞的笑臉、再也沒有了聲息。"
  },
  AvgDialog_131229_Content_32 = {
    Text = "對不起、我來晚了、我剛剛……啊"
  },
  AvgDialog_131229_Content_33 = {
    Text = "熟悉的身影掀開帷幕踏上舞台。她的目光掠過你們、停留在那個懸掛在空中的屍體上。"
  },
  AvgDialog_131229_Content_34 = {
    Text = "她的動作……真美……"
  },
  AvgDialog_131229_Content_35 = {
    Text = "莉茲似乎忘記了滿地的屍體與站著的觀眾。她來到舞台的中央、手從懸掛的屍體腿部上方劃過、似乎正揣摩著那道優雅的弧線。"
  },
  AvgDialog_131229_Content_36 = {
    Text = "阿拉克涅，你……交換了報幕人和莉茲的命運？"
  },
  AvgDialog_131229_Content_37 = {
    Text = "可是你說過、這樣的消耗是難以承受的……"
  },
  AvgDialog_131229_Content_38 = {
    Text = "消耗與選擇無關。在我的命運裡、這也是我必須付出的代價。"
  },
  AvgDialog_131229_Content_39 = {
    Text = "去吧，%player%，不要讓莉茲小姐久等了。"
  },
  AvgDialog_131229_Content_4 = {
    Text = "沒錯……就是這樣……憤怒、宣洩！多麼精彩的表情……"
  },
  AvgDialog_131229_Content_40 = {
    Text = "空靈的眼睛與呼吸。隨風飄蕩的、帶著細微綠炎的裙擺。每一個指尖的顫動都如同精心編排的舞蹈。"
  },
  AvgDialog_131229_Content_41 = {
    Text = "身體與剛才那個鮮血淋漓衝向你的身影重疊。莉茲鮮活地站在你的面前，命運精巧的編織沒有在她的生命裡留下絲毫痕跡。"
  },
  AvgDialog_131229_Content_42 = {
    Text = "良久、莉茲從對屍體的欣賞中回過神來、轉頭望向站在身邊的你。"
  },
  AvgDialog_131229_Content_43 = {
    Text = "我今天在家昏睡到下午、錯過了演出。這是從來沒有發生過的情況……"
  },
  AvgDialog_131229_Content_44 = {
    Text = "看來、我錯過了一些很重要的事？"
  },
  AvgDialog_131229_Content_45 = {
    Text = "莉茲的眼睛掃過地上那些被她忽略掉的屍體與血跡。"
  },
  AvgDialog_131229_Content_46 = {
    Text = "不、你什麼都沒有錯過、莉茲。"
  },
  AvgDialog_131229_Content_47 = {
    Text = "你……還好嗎？身體有沒有什麼不適？"
  },
  AvgDialog_131229_Content_48 = {
    Text = "這倒沒有……這位{Male=先生,Female=小姐}，我們認識嗎？我似乎感覺到，您的身上有一些我很熟悉的東西……"
  },
  AvgDialog_131229_Content_49 = {
    Text = "或許是因為、作為你的追隨者、我看了你許多的演出吧。"
  },
  AvgDialog_131229_Content_5 = {
    Text = "那張爛泥般的臉微笑著、微弱的聲音從她碎裂的喉管中吐出。"
  },
  AvgDialog_131229_Content_50 = {
    Text = "你微笑著望著她。這個舞台有屬於這個舞台的故事、你並不打算將那些久遠的事情向她講述。"
  },
  AvgDialog_131229_Content_51 = {
    Text = "我們是為「善良」而來。"
  },
  AvgDialog_131229_Content_52 = {
    Text = "索蕾爾夫人的朋友終於來了、我還擔心自己去演出、怠慢了那位「善良」先生……請二位隨我來、我的住所就在離舞團不遠的地方。"
  },
  AvgDialog_131229_Content_53 = {
    Text = "莉茲有些不捨地望了一眼牆上的屍體，帶著你們向帷幕後走去。"
  },
  AvgDialog_131229_Content_55 = {
    Text = "所以……原本應該是我的屍體被懸掛在舞台上……"
  },
  AvgDialog_131229_Content_56 = {
    Text = "來不及為死去的舞伴們哀悼、也忘記對讓自己死而復生的人表達感謝。"
  },
  AvgDialog_131229_Content_57 = {
    Text = "在你們的講述中、莉茲的眼睛如同躍動的火苗般閃爍。她伸出手、擺出和屍體一樣的姿勢。"
  },
  AvgDialog_131229_Content_58 = {
    Text = "那幅畫面、美嗎？"
  },
  AvgDialog_131229_Content_59 = {
    Text = "世間的至美只現於兩個時刻、一個是誕生、一個是死亡。那是一幅無與倫比的畫面、莉茲小姐。"
  },
  AvgDialog_131229_Content_6 = {
    Text = "涅芙蕾亞不在此處，這只是她留下的幻象。不要被憤怒所蒙蔽，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131229_Content_60 = {
    Text = "謝謝您，阿拉克涅女士。您是命運的編織者，那我想，您一定時常被這些至美所環繞。這真是……令人羨慕。"
  },
  AvgDialog_131229_Content_61 = {
    Text = "太多的珍寶、將成為一種懲罰。"
  },
  AvgDialog_131229_Content_62 = {
    Text = "如果這是您的刑罰、那您所求的恩賜是什麼呢？"
  },
  AvgDialog_131229_Content_63 = {
    Text = "莉茲並沒有注意到阿拉克涅短暫的停頓，打開了院中客房的門。"
  },
  AvgDialog_131229_Content_64 = {
    Text = "這裡就是「善良」先生的臨時住所。「善良」先生、您的朋友來接您了。"
  },
  AvgDialog_131229_Content_66 = {
    Text = "簡單的房間、沒有任何一件不屬於這裡的陳設、沒有任何一個不屬於這裡的人。"
  },
  AvgDialog_131229_Content_67 = {
    Text = "空蕩蕩的屋子內、一張簡易的紙條靜靜地躺在書櫃上。"
  },
  AvgDialog_131229_Content_68 = {
    Text = "「很抱歉不辭而別。索蕾爾夫人擔心您受到牽連、因此有了新的安排、我將去到回憶的別墅中躲避。」"
  },
  AvgDialog_131229_Content_69 = {
    Text = "「對於您的照顧、我不勝感激。我會認真向您償還這份恩情。」"
  },
  AvgDialog_131229_Content_70 = {
    Text = "索蕾爾夫人如果改變計畫、一定會通知我們……"
  },
  AvgDialog_131229_Content_71 = {
    Text = "你望向阿拉克涅那張沒有波瀾的眼睛。在那似乎永遠不會消失的平靜微笑中，你看到了一閃而過的陰霾。"
  },
  AvgDialog_131229_Content_72 = {
    Text = "「回憶」是一個流浪者。她並沒有家。"
  },
  AvgDialog_131229_Content_73 = {
    Text = "什麼？！！那……"
  },
  AvgDialog_131229_Content_74 = {
    Text = "「回憶」的命運，恐怕也已經被涅芙蕾亞所篡改了。他們兩人，現在都陷入了危險。"
  },
  AvgDialog_131229_Content_75 = {
    Text = "抱歉、我沒有想到……"
  },
  AvgDialog_131229_Content_76 = {
    Text = "並非你的責任、莉茲小姐。"
  },
  AvgDialog_131229_Content_77 = {
    Text = "涅芙蕾亞既然能夠篡改你的命運，找到你身邊的人，也並非難事。這些，是我們需要處理的問題。"
  },
  AvgDialog_131229_Content_78 = {
    Text = "上面的墨跡還沒有完全乾，涅芙蕾亞動手的時間離得不遠，我們現在儘快或許還來得及……"
  },
  AvgDialog_131229_Content_79 = {
    Text = "莉茲、有些話、這次來不及說……"
  },
  AvgDialog_131229_Content_8 = {
    Text = "當那張微笑的臉再也辨認不出絲毫模樣時、你總算停了下來。"
  },
  AvgDialog_131229_Content_80 = {
    Text = "總會有機會的，守密人{Male=先生,Female=小姐}。希望下次見面的時候，那支新的舞蹈，依然能夠打動您。"
  },
  AvgDialog_131229_Content_81 = {
    Text = "用簡單的微笑向你們告別之後、莉茲不再關心你們那些複雜的故事。"
  },
  AvgDialog_131229_Content_82 = {
    Text = "她抬起手臂、擺出與那具屍體相同的弧度、嘗試著復原那個一直萦繞在她腦海中的舞姿。"
  },
  AvgDialog_131229_Content_83 = {
    Text = "微風吹動她的裙擺、如同天鵝正在翱翔。"
  },
  AvgDialog_131229_Content_9 = {
    Text = "被操控的莉茲屍體已失去了所有的生氣。你將她血肉模糊的屍體輕放在地板上、打開了與她連結的精神通道。"
  },
  AvgDialog_131230_Content_10 = {
    Text = "既然已經重新創造了這座城市……我以為、你會把那些已經消失的東西帶到這裡來。"
  },
  AvgDialog_131230_Content_11 = {
    Text = "……你懷念它們、不是嗎？"
  },
  AvgDialog_131230_Content_12 = {
    Text = "比起一杯咖啡、我更願意看到舞台自己呈現出來的樣子。"
  },
  AvgDialog_131230_Content_13 = {
    Text = "我用回憶重新創造了這裡、可我依然無法改變它是一座全新舞台的事實。"
  },
  AvgDialog_131230_Content_14 = {
    Text = "這裡的新咖啡也有它獨特的味道、不是嗎？"
  },
  AvgDialog_131230_Content_15 = {
    Text = "阿拉克涅微笑著，輕輕抿了一口那苦澀的液體。"
  },
  AvgDialog_131230_Content_16 = {
    Text = "涅芙蕾亞……最後怎麼樣了？"
  },
  AvgDialog_131230_Content_17 = {
    Text = "你們的命運絲線重新連在了一起，這是不是意味著……你們現在又成了同一個人？"
  },
  AvgDialog_131230_Content_18 = {
    Text = "那些曾屬於涅芙蕾亞的東西，她的品質、她最初的秉性，重新回到了我的命運中。或者說，如您所知——它們從未離開過。"
  },
  AvgDialog_131230_Content_19 = {
    Text = "但命運之網是唯一的。那位您所認識的涅芙蕾亞，那位在淵獄中沉淪、被命運拋棄的復仇者，這張網中沒有屬於她的絲線。"
  },
  AvgDialog_131230_Content_2 = {
    Text = "Lascia ch'io pianga 讓我痛哭吧！\nmia cruda sorte, 殘酷的命運。"
  },
  AvgDialog_131230_Content_20 = {
    Text = "她……徹底消逝了，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131230_Content_21 = {
    Text = "紡輪輕輕的、永不停息地轉動。阿拉克涅閉上眼，輕輕抬起頭，嗅著風中微薄的花香。"
  },
  AvgDialog_131230_Content_22 = {
    Text = "被遺棄的命運、所面臨的只有永恆的囚禁與徹底的消逝。真是件殘酷的事情啊……"
  },
  AvgDialog_131230_Content_23 = {
    Text = "每時每刻，命運都需要進行抉擇。正確的將會留下，錯誤的將被拋棄……"
  },
  AvgDialog_131230_Content_24 = {
    Text = "在我們尋找到真正的道路之前，這件事就如同這個宇宙的傾覆一般，無可避免。"
  },
  AvgDialog_131230_Content_25 = {
    Text = "守密人{Male=先生,Female=小姐}，若您擁有操控命運的能力，您會任由它走向混亂，還是為它們做出選擇，即便這會讓你擔上兇手的罪名？"
  },
  AvgDialog_131230_Content_26 = {
    Text = "這……我……"
  },
  AvgDialog_131230_Content_27 = {
    Text = "這只是一個供您消遣的辯題，並非您必須解答的疑問。您需要承載的事情已經太多，這份重量無需再由您來承擔。"
  },
  AvgDialog_131230_Content_28 = {
    Text = "阿拉克涅笑著搖了搖頭。"
  },
  AvgDialog_131230_Content_29 = {
    Text = "選擇是一項權力，很多人即便擁有它，也會選擇放棄。因為做出選擇的時候，也意味著承擔後果。"
  },
  AvgDialog_131230_Content_3 = {
    Text = "E che sospiri la libertà! \n多麼盼望著，那自由的來臨！"
  },
  AvgDialog_131230_Content_30 = {
    Text = "您知道，那並非是一件容易的事，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131230_Content_31 = {
    Text = "我是命運的操控者、命運的一切後果、都將由我來承擔。"
  },
  AvgDialog_131230_Content_32 = {
    Text = "這是我第一次扣響契訶瑪-達阿特的門扉時、祂賜予我的話語。對此、我欣然接受。"
  },
  AvgDialog_131230_Content_33 = {
    Text = "所以你……雖然看不見自己的命運、但這些、現在發生的這一切……你其實都知道。"
  },
  AvgDialog_131230_Content_34 = {
    Text = "溫暖的陽光照耀著這條街道，但望著阿拉克涅那張平靜的臉，想像著身邊這個人終日所面對之物，即便是你也忍不住打了個寒戰。"
  },
  AvgDialog_131230_Content_35 = {
    Text = "浪漫帶來愚鈍、善良帶來脆弱、回憶帶來痛苦……"
  },
  AvgDialog_131230_Content_36 = {
    Text = "即便早就準備面對這些，可你一直都沒有真正拋棄它們……為什麼？"
  },
  AvgDialog_131230_Content_37 = {
    Text = "對你來說、放棄他們、應該會讓你過得更輕鬆一些。"
  },
  AvgDialog_131230_Content_38 = {
    Text = "您去過監獄嗎？那些經年累月被關押在牢中的囚犯們、身邊總要帶上一些自己所珍視的東西。"
  },
  AvgDialog_131230_Content_39 = {
    Text = "一枚打架贏來的勳章，一塊祖傳的手錶，一張與家人的合照……"
  },
  AvgDialog_131230_Content_4 = {
    Text = "悠揚的歌聲在街道上迴蕩、隨著和煦的風婉轉飄揚。路上的行人們在這歌聲裡駐足或行走、享受著他們這段春光中的寧靜生命。"
  },
  AvgDialog_131230_Content_40 = {
    Text = "對囚犯們而言、這些讓他們痛苦的欲念、是他們能夠繼續活下去的動力。"
  },
  AvgDialog_131230_Content_41 = {
    Text = "他們小心翼翼地保留著這些最為珍視之物、直到臨近死亡的那一刻、將那些毫無價值的東西、一一交出。"
  },
  AvgDialog_131230_Content_42 = {
    Text = "……命運的囚籠裡，我們都一無所有，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131230_Content_43 = {
    Text = "Il duolo infranga 人間的苦難，\nqueste ritorte 無窮無盡。"
  },
  AvgDialog_131230_Content_44 = {
    Text = "de miei martiri 對我這樣的痛苦，\nsol per pietà 也無人憐憫。"
  },
  AvgDialog_131230_Content_45 = {
    Text = "路邊的歌劇家向這座城市奔流的命運之河歌唱。阿拉克涅啜飲著咖啡，認真地聆聽著。從始至終，她微笑的角度都從未變化過。"
  },
  AvgDialog_131230_Content_46 = {
    Text = "您知道嗎，守密人{Male=先生,Female=小姐}，我常常會反覆夢到同一個場景。"
  },
  AvgDialog_131230_Content_47 = {
    Text = "那是一座美麗的劇院，只有我和涅芙蕾亞兩個人。正是在這首美麗的歌裡，我送別了她。"
  },
  AvgDialog_131230_Content_48 = {
    Text = "您看、即便我們無法看清自己的命運、它的宣判也無處不在。"
  },
  AvgDialog_131230_Content_49 = {
    Text = "E che sospiri la libertà! 多麼地盼望！\nE che sospiri la libertà! 多麼地盼望！"
  },
  AvgDialog_131230_Content_5 = {
    Text = "你端起咖啡、喝了一大口。"
  },
  AvgDialog_131230_Content_50 = {
    Text = "歌劇家的聲音永不停息，紡輪的絲線永恆地轉動。阿拉克涅放下手中的杯盞，與駐足的觀眾們一起誠懇地為他輕聲鼓掌。"
  },
  AvgDialog_131230_Content_51 = {
    Text = "無論如何、一場演出結束了、這個舞台將迎來它短暫的休憩。我們這些演員、也即將趕赴下一個舞台。"
  },
  AvgDialog_131230_Content_52 = {
    Text = "涅芙蕾亞的影響已經消失，現在應該可以重新開啟與卡達斯連接的通道了？"
  },
  AvgDialog_131230_Content_53 = {
    Text = "連接卡達斯的通道就在這個世界的命運之中。跨越維度的嘗試、你也已經試過。"
  },
  AvgDialog_131230_Content_54 = {
    Text = "其中的危險、你也已經知曉。"
  },
  AvgDialog_131230_Content_55 = {
    Text = "的確……托乎瓦波的那些目光、我可不想再面對一次了……"
  },
  AvgDialog_131230_Content_56 = {
    Text = "阿拉克涅，你可以控制這個世界的命運，或許你有辦法能幫到我？"
  },
  AvgDialog_131230_Content_57 = {
    Text = "我很樂意效勞、不過、在這個世界上、只有這座城市是我的舞台。這個世界命運的主人、並非是我。"
  },
  AvgDialog_131230_Content_59 = {
    Text = "這個世界的主人，有著連我也無法企及的能力。這個世界，因祂的意志而存在。"
  },
  AvgDialog_131230_Content_6 = {
    Text = "比起赫瓦茨咖啡差遠了。"
  },
  AvgDialog_131230_Content_60 = {
    Text = "除非主動打開通道，否則，這裡將是一個連至高神明的目光也無法觸及之地……這也正是我棲身於此的原因。"
  },
  AvgDialog_131230_Content_61 = {
    Text = "難道說……我打開通道、會讓這裡出現危險？"
  },
  AvgDialog_131230_Content_62 = {
    Text = "如我所言、命運自有其軌跡。偏居於此、只是緩慢地等待死亡。協助你返回卡達斯、亦是這個世界主人的夙願。"
  },
  AvgDialog_131230_Content_63 = {
    Text = "為了命運前方的光點，這是我們完全願意承受的危險。"
  },
  AvgDialog_131230_Content_64 = {
    Text = "原來如此……我明白了。"
  },
  AvgDialog_131230_Content_65 = {
    Text = "我在哪裡能找到祂？"
  },
  AvgDialog_131230_Content_66 = {
    Text = "祂的命運絲線浩如星海、又渺如塵煙。只依靠對命運的捕捉、我無法為你直接指出祂的位置。"
  },
  AvgDialog_131230_Content_67 = {
    Text = "但或許、這個能夠幫到你。"
  },
  AvgDialog_131230_Content_68 = {
    Text = "阿拉克涅將一頁宣傳冊遞給你。你皺著眉頭，看著上面那些充滿宗教感的漂亮花體字。"
  },
  AvgDialog_131230_Content_69 = {
    Text = "招聘啟事："
  },
  AvgDialog_131230_Content_7 = {
    Text = "上次去那個舞台品嚐之後、我也覺得味道很不錯。可惜、在這個舞台上、發明那個咖啡的家族在很早之前就消亡了。"
  },
  AvgDialog_131230_Content_70 = {
    Text = "偉大的教主、神明應選之人、至高之神的代行者、宏大教派的法定繼承者、苦難的解救者、神王的摯友已降臨終北大陸、現教派正在快速發展、信徒可速速來此覲見。"
  },
  AvgDialog_131230_Content_71 = {
    Text = "最先到達的十二名信眾、將被冊封為聖徒、永遠追隨仙女左右、受神明永世庇護……"
  },
  AvgDialog_131230_Content_72 = {
    Text = "這是……什麼東西？"
  },
  AvgDialog_131230_Content_73 = {
    Text = "如您所見、是一份精心製作的宣傳冊。"
  },
  AvgDialog_131230_Content_74 = {
    Text = "這上面的內容怎麼這麼詭異……阿拉克涅，你能看到命運的走向，你確定這不是一個騙局？"
  },
  AvgDialog_131230_Content_75 = {
    Text = "在它的絲線上、我看到了你的身影。我很確信、它是你將要迎接的命運。"
  },
  AvgDialog_131230_Content_76 = {
    Text = "是幫助、還是危險、我無從得知。但我知道、在你與那位世界的主人之間、這是唯一的聯繫。"
  },
  AvgDialog_131230_Content_77 = {
    Text = "阿拉克涅的手伸向那張荒唐的宣傳冊上方，拈起一個你不可見之物，放在你的手心。"
  },
  AvgDialog_131230_Content_78 = {
    Text = "這又是？……"
  },
  AvgDialog_131230_Content_79 = {
    Text = "很快，一段隱約可見的絲縷在你手中映照出暗淡的光澤。"
  },
  AvgDialog_131230_Content_8 = {
    Text = "你環顧著這座城市。布里克十字路、時間褶皺舊書店、芬芳集市雜貨鋪……"
  },
  AvgDialog_131230_Content_80 = {
    Text = "這是你與那段命運相連的契機。它將指引你，去到你應去之地。"
  },
  AvgDialog_131230_Content_81 = {
    Text = "我明白了。等威廉學長的傷養好，我們立刻就……"
  },
  AvgDialog_131230_Content_82 = {
    Text = "在我對您命運絲線短暫的窺探裡，您將遇到一段有趣的故事。"
  },
  AvgDialog_131230_Content_83 = {
    Text = "我未能看見您的結局，那是一件幸事——對於您的命運，我仍然保有作為觀眾的榮幸。"
  },
  AvgDialog_131230_Content_84 = {
    Text = "我想，沒有任何一段故事，應當被辜負……所以，請不必著急。讓我們好好聽完這段歌劇吧，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131230_Content_85 = {
    Text = "歌劇家的歌聲再次漫過街道。阿拉克涅閉上眼睛，陽光落在她安靜的面容上，和煦得像是那些她已經失去的春天。"
  },
  AvgDialog_131230_Content_86 = {
    Text = "紡輪轉動，歌聲不歇。行人來來往往，萬千你無法看見的絲線於她身邊匯集、編織。"
  },
  AvgDialog_131230_Content_87 = {
    Text = "你望著阿拉克涅微笑著的臉。你看見，她的身邊一無所有。"
  },
  AvgDialog_131230_Content_9 = {
    Text = "一切似乎都沒有改變、就連鋪面招牌上那些斑駁的銹跡也與你記憶中如出一轍。"
  },
  AvgDialog_131231_Content_1 = {
    Text = "呼……還好趕上了……"
  },
  AvgDialog_131231_Content_10 = {
    Text = "索蕾爾微微眯起眼打量著阿拉克涅。她發現自己引以為傲的識人之術全然失效。她看不清面前之人的過往，也猜不透她的欲望。"
  },
  AvgDialog_131231_Content_11 = {
    Text = "她迅速記住的那張臉上的一切細節、在眨眼的那一刻悉數忘掉。索蕾爾的嘴角玩味地勾起。"
  },
  AvgDialog_131231_Content_12 = {
    Text = "兩位令人著迷的貴客。這場沙龍、一定會令我終生難忘的。二位請坐。"
  },
  AvgDialog_131231_Content_13 = {
    Text = "索蕾爾轉身坐在沙發上、向你們抬手示意。"
  },
  AvgDialog_131231_Content_14 = {
    Text = "我與「善良」有過數面之緣、他來找到我、尋求我的庇護。"
  },
  AvgDialog_131231_Content_15 = {
    Text = "你們救了我。我無法看清你們、但我能看出來、你們並無惡意。"
  },
  AvgDialog_131231_Content_16 = {
    Text = "沒錯、索蕾爾夫人。我們是來救他的。"
  },
  AvgDialog_131231_Content_17 = {
    Text = "他並沒有在這個莊園之中。"
  },
  AvgDialog_131231_Content_18 = {
    Text = "可你剛才說……"
  },
  AvgDialog_131231_Content_19 = {
    Text = "如你所見、我的莊園也並不安全。"
  },
  AvgDialog_131231_Content_2 = {
    Text = "確認了珈倫的狀態後、你站起身、擦了擦額頭的冷汗。"
  },
  AvgDialog_131231_Content_20 = {
    Text = "索蕾爾揚起手臂、如同展示珍貴的藏品般望向瑰麗整潔的房間裡那些凌亂的屍體。"
  },
  AvgDialog_131231_Content_21 = {
    Text = "那是一位心思善良但並不愚笨的先生。我看得出來、他面臨的情況十分危急。"
  },
  AvgDialog_131231_Content_22 = {
    Text = "我與他的交情、知道的人不少。將他藏在莊園、不是一個明智的決定。"
  },
  AvgDialog_131231_Content_23 = {
    Text = "請問他現在人在哪？"
  },
  AvgDialog_131231_Content_24 = {
    Text = "索蕾爾站起身，來到一幅畫像前。你站起身，看清了上面的畫面。"
  },
  AvgDialog_131231_Content_26 = {
    Text = "數年前、我去倫蒂尼恩劇院看過一場天鵝舞蹈團的表演。那本來是一場簡單的應酬、但我被她的舞姿深深震撼。"
  },
  AvgDialog_131231_Content_27 = {
    Text = "這些年、我曾偶爾在邀請舞團演出時拜訪後台。我們並沒有什麼實際的交情、正因如此、她所在的舞團、是最適合安放那位「善良」先生的地方。"
  },
  AvgDialog_131231_Content_28 = {
    Text = "眼前的畫像上，莉茲穿著清麗的舞裙，在空中高高躍起，如同天鵝翱翔。"
  },
  AvgDialog_131231_Content_29 = {
    Text = "莉茲……她的舞團、現在在哪？"
  },
  AvgDialog_131231_Content_3 = {
    Text = "珈倫應該沒事、她受到了些影響、靜養一段時間應該就會好轉了。"
  },
  AvgDialog_131231_Content_30 = {
    Text = "順著那道逐漸清晰起來的命運絲線，阿拉克涅望向窗外，那個與絲線相連、密林掩映之處。"
  },
  AvgDialog_131231_Content_31 = {
    Text = "在一個、你無比熟悉的地方。"
  },
  AvgDialog_131231_Content_4 = {
    Text = "我能清楚地記起我見過的每一張臉、但你給我的感覺很奇怪。我無法確信自己是否見過你……這在我身上從未發生過。"
  },
  AvgDialog_131231_Content_5 = {
    Text = "索蕾爾拿起茶几上未被打翻的酒瓶斟倒在杯中、跨過滿屋正在消融的屍體、將酒杯遞到你們面前。"
  },
  AvgDialog_131231_Content_6 = {
    Text = "四十年的陳釀波特酒、我的私人珍藏、樓下的鬣狗們沒有品嚐它的資格。無論你們是誰、為何出現在這裡、我想、這杯酒應當屬於你們。"
  },
  AvgDialog_131231_Content_7 = {
    Text = "我們是為「善良」而來、索蕾爾夫人。"
  },
  AvgDialog_131231_Content_8 = {
    Text = "阿拉克涅接過酒杯，向索蕾爾微笑著點頭致意。"
  },
  AvgDialog_131231_Content_9 = {
    Text = "在沒有開口的時候、她如同晨光中的蛛網般、絲毫不引人注意。在她開口之後、房間中的所有光彩似乎都匯聚在她的身上。"
  },
  AvgDialog_131232_Content_1 = {
    Text = "多麼精彩的戰鬥啊、姊姊。"
  },
  AvgDialog_131232_Content_10 = {
    Text = "你與你的侍從是遺失命運之人、你們的命運絲線我無法捕捉。但你的能力來自於我、我無法看清自己的命運、你也是如此。"
  },
  AvgDialog_131232_Content_11 = {
    Text = "你與我……這是一場註定僵持的無謂戰爭。它本不應該發生。"
  },
  AvgDialog_131232_Content_12 = {
    Text = "當然、當然。對你來說、我們這些已經被捨棄的東西、就應該消亡在命運的墳場、被分解、消亡、消弭於此、直到永遠、永遠。"
  },
  AvgDialog_131232_Content_13 = {
    Text = "可惜啊、你無法看清祂……你就算擁有再強大的力量、又如何比得上那位至高的神明？"
  },
  AvgDialog_131232_Content_14 = {
    Text = "你知道的。你明明知道、這一切都是徒勞。可你不能停止織網……"
  },
  AvgDialog_131232_Content_15 = {
    Text = "你既然已經看見、就無法忍受那些亂成一團的線條。你既然擁有這樣的能力、就無法坐視那些世界陷入無休止的混亂。"
  },
  AvgDialog_131232_Content_16 = {
    Text = "你為他們帶來虛假的安寧、也將他們帶上一條終將通向覆滅的道路。"
  },
  AvgDialog_131232_Content_17 = {
    Text = "真是個可悲的人啊，阿拉克涅。"
  },
  AvgDialog_131232_Content_18 = {
    Text = "這是我們的命運，涅芙蕾亞。"
  },
  AvgDialog_131232_Content_19 = {
    Text = "啊……我好像有點困了。和愚人辯論是這個世上最無聊的事。"
  },
  AvgDialog_131232_Content_2 = {
    Text = "熱鬧的酒吧寂靜下來、滿地傾倒的屍體化為黑色的黏液與粉末、消散在柔和的燈光中。"
  },
  AvgDialog_131232_Content_20 = {
    Text = "歡迎來到這故事的第二幕。這是你的舞台、但從現在開始、這個故事將由我來書寫。"
  },
  AvgDialog_131232_Content_21 = {
    Text = "開場的小節最重要了、對吧？應該取個什麼名字好呢……啊、就叫「重逢」、怎麼樣？"
  },
  AvgDialog_131232_Content_22 = {
    Text = "涅芙蕾亞對自己的命名相當滿意，用自己的節肢蘸了蘸杯中的陳釀放入口中，發出一聲陶醉的嘆息。"
  },
  AvgDialog_131232_Content_23 = {
    Text = "為了這一天、我已經做了太久、太久的準備。我會好好享受跟你的這段故事的、親愛的姐姐。"
  },
  AvgDialog_131232_Content_24 = {
    Text = "沒有再給你們追問的機會。涅芙蕾亞鋒利的指甲在阿拉克涅臉頰的邊緣輕輕劃過，然後隨著身體一同栽倒在地。"
  },
  AvgDialog_131232_Content_26 = {
    Text = "她不在這裡，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131232_Content_27 = {
    Text = "一陣沸騰聲響起、黑色的黏液再次從屍體的臉上滑落。"
  },
  AvgDialog_131232_Content_28 = {
    Text = "「浪漫」那雙迷人的雙眼依然保持著微笑的弧度、黑色的蜘蛛在她身體中胡亂地爬動、在明亮的眼眶中若隱若現。那張優雅的嘴再也沒有了任何聲息。"
  },
  AvgDialog_131232_Content_29 = {
    Text = "這是……"
  },
  AvgDialog_131232_Content_3 = {
    Text = "涅芙蕾亞與阿拉克涅依然相對而坐，她倒下一杯酒，向阿拉克涅推去。"
  },
  AvgDialog_131232_Content_30 = {
    Text = "她殺死了這具秘偶、在她身上留下印記、汙染她的命運、讓自己短暫地存在於她的身上。"
  },
  AvgDialog_131232_Content_31 = {
    Text = "阿拉克涅來到秘偶身前，將手伸向「浪漫」的頭頂，凝視著那根幾乎已經消失的絲線。"
  },
  AvgDialog_131232_Content_32 = {
    Text = "……有看到什麼嗎？"
  },
  AvgDialog_131232_Content_33 = {
    Text = "其他的秘偶也遭受了汙染、我無法從命運之網感知到他們的存在……但「浪漫」的命運與他們相連。"
  },
  AvgDialog_131232_Content_34 = {
    Text = "她告訴了我、「善良」的下落。"
  },
  AvgDialog_131232_Content_35 = {
    Text = "阿拉克涅放下命運的絲線，為「浪漫」整理著那道美麗的劉海。"
  },
  AvgDialog_131232_Content_36 = {
    Text = "涅芙蕾亞的能力來自於我，被她汙染的命運，我無法看見，許多的能力，也受此所限。"
  },
  AvgDialog_131232_Content_37 = {
    Text = "您是那位神明的碎片，是我們無法看清命運之人。因此，我需要您的幫助，守密人{Male=先生,Female=小姐}。"
  },
  AvgDialog_131232_Content_38 = {
    Text = "請放心、即便只是為了返回卡達斯、我也必須要解決她。"
  },
  AvgDialog_131232_Content_39 = {
    Text = "她尋找這些秘偶、是為了什麼？"
  },
  AvgDialog_131232_Content_4 = {
    Text = "雖然「浪漫」小姐已經不在了、但這裡的酒可不應該浪費。"
  },
  AvgDialog_131232_Content_40 = {
    Text = "這些秘偶、將成為她力量的來源。"
  },
  AvgDialog_131232_Content_41 = {
    Text = "那我們得快點動身了……找到那些秘偶，還有那些能夠幫你編織命運的維度餘燼……"
  },
  AvgDialog_131232_Content_42 = {
    Text = "那個叫做「善良」的秘偶、現在在哪？"
  },
  AvgDialog_131232_Content_43 = {
    Text = "「浪漫」在不久前，向他告知了危險。他現在躲藏了起來，庇護他的，是一位您的老朋友。"
  },
  AvgDialog_131232_Content_45 = {
    Text = "請隨我來，守密人{Male=先生,Female=小姐}。索蕾爾夫人的盛大沙龍，快要開始了。"
  },
  AvgDialog_131232_Content_5 = {
    Text = "想試試嗎？比起那個自導自演的秘偶、我才是真正懂得你的人。"
  },
  AvgDialog_131232_Content_6 = {
    Text = "阿拉克涅沒有遲疑，她微笑著端起酒杯，輕輕抿了一口。"
  },
  AvgDialog_131232_Content_7 = {
    Text = "你不適合做這個職業，涅芙蕾亞。除了苦與澀，它再也沒有其他味道。"
  },
  AvgDialog_131232_Content_8 = {
    Text = "我稱它為「命運」。喜歡嗎？"
  },
  AvgDialog_131232_Content_9 = {
    Text = "阿拉克涅沒有理會涅芙蕾亞期待的眼神。她緩緩飲下杯中的酒，將酒杯輕輕放在桌上。"
  },
  AvgDialog_132684_Content_10 = {
    Text = "沒錯，而且考量到彌薩格本身就有在今天戲弄人以溝通感情的傳統，校方不會處罰這種並不過分的「惡作劇」。"
  },
  AvgDialog_132684_Content_11 = {
    Text = "吱！吱，吱——！<Small:<LightGray:（朵爾老師，你在捏我的手和臉吧，你在搓我的臉沒錯吧！）>>"
  },
  AvgDialog_132684_Content_12 = {
    Text = "雖然語氣一如既往地冷淡，甚至帶有些許刻薄，但你非常肯定，朵爾的嘴角至少上揚了2毫米。"
  },
  AvgDialog_132684_Content_13 = {
    Text = "抱歉，守密人。銀芯翻譯器似乎出了點問題，不過沒關係，反試劑明早就能合成出來。"
  },
  AvgDialog_132684_Content_14 = {
    Text = "你滿臉震驚地看著朵爾，就算你現在只有海獺的腦子，也能看出她身後的試劑明明是已完成狀態。"
  },
  AvgDialog_132684_Content_15 = {
    Text = "老師，找莫絲？"
  },
  AvgDialog_132684_Content_18 = {
    Text = "介於我們有對該族群擁有豐富經驗的相關人員，我想，和她們共度一天，應該能幫我們的守密人長點記性。"
  },
  AvgDialog_132684_Content_19 = {
    Text = "莫絲，管好%player%的任務就交給你了。"
  },
  AvgDialog_132684_Content_2 = {Text = "*彈跳"},
  AvgDialog_132684_Content_20 = {
    Text = "*歡呼 好！小煤球，一起玩"
  },
  AvgDialog_132684_Content_21 = {
    Text = "吱！<Small:<LightGray:（一起玩！）>>"
  },
  AvgDialog_132684_Content_24 = {
    Text = "搭檔，今天沒有什麼重要事務，請不用擔心。"
  },
  AvgDialog_132684_Content_25 = {
    Text = "我也會騰出今天的時間，來保障你的安全的。"
  },
  AvgDialog_132684_Content_26 = {
    Text = "話雖然是這麼說，但顯然，她也已經和莫絲一樣，完全被你手感好到難以置信的毛毛完全控制了。"
  },
  AvgDialog_132684_Content_27 = {
    Text = "唧，唧唧唧唧……<Small:<LightGray:（還有沒有人能救一下，威廉學長……）>>"
  },
  AvgDialog_132684_Content_28 = {
    Text = "順帶一提，威廉今天去外勤了，會很晚才回來。"
  },
  AvgDialog_132684_Content_29 = {
    Text = "*喝茶 <Small:<LightGray:（呼，難得的機會，我最不省心，也最重要的學生，就好好拋下一切，放鬆一天吧。）>>"
  },
  AvgDialog_132684_Content_3 = {Text = "*搓臉"},
  AvgDialog_132684_Content_30 = {
    Text = "此時，遠處的某位學長。"
  },
  AvgDialog_132684_Content_31 = {Text = "阿嚏"},
  AvgDialog_132684_Content_32 = {
    Text = "奇怪，莫名有種不太好的預感。"
  },
  AvgDialog_132684_Content_33 = {
    Text = "今天還是早點回校吧。"
  },
  AvgDialog_132684_Content_34 = {
    Text = "愚人節的彌薩格，也非常和平。"
  },
  AvgDialog_132684_Content_35 = {
    Text = "可喜可賀、可喜可賀。"
  },
  AvgDialog_132684_Content_5 = {
    Text = "吱吱吱吱吱！嘤嘤嘤嘤嘤！！！<Small:<LightGray:（我變成海獺了！拉蒙娜，救救我！）>>"
  },
  AvgDialog_132684_Content_7 = {
    Text = "好消息，這種噴霧的效果並非不可逆，反試劑調製也非常簡單，顯然對方沒有惡意。"
  },
  AvgDialog_132684_Content_8 = {
    Text = "更好的消息，居然不經思考就敢用那個滿嘴謊話的小騙子的禮物，暫時換一個海獺的腦子可能真有助於你清醒清醒。"
  },
  AvgDialog_132684_Content_9 = {
    Text = "所以，這種臨時轉換並不會對守密人造成任何傷害？"
  },
  AvgDialog_13733_Content_1 = {Text = "紅祭禮"},
  AvgDialog_13733_Content_10 = {
    Text = "呵呵，你永遠不能指望勒姆瓦希人的見識。睜大眼看著吧……"
  },
  AvgDialog_13733_Content_11 = {
    Text = "普林從袖中掏出一把儀式刀，毫不猶豫地割開了自己的手腕。"
  },
  AvgDialog_13733_Content_12 = {
    Text = "殷紅的血一點點滴在以硫磺鋪就的法陣上，奇蹟就這樣發生了——"
  },
  AvgDialog_13733_Content_13 = {
    Text = "彷彿一滴水匯入乾涸的沙漠，吸收了新鮮血液的法陣迅速發出一圈又一圈暗紅的光芒。"
  },
  AvgDialog_13733_Content_14 = {
    Text = "它們就像黑天之下的火焰，貪婪舔舐著風捲肆虐的黃沙，彷彿要將整個大地都吞進自己的胃裡。"
  },
  AvgDialog_13733_Content_15 = {
    Text = "看到了嗎，這才是真正的魔法時刻！哈哈哈哈！"
  },
  AvgDialog_13733_Content_16 = {
    Text = "哈哈哈……<Big:嗚啊！！！>"
  },
  AvgDialog_13733_Content_17 = {
    Text = "普林“撲通”一聲跪倒在地，不受控制地掐住了自己的喉嚨。"
  },
  AvgDialog_13733_Content_18 = {
    Text = "連接著他與尤烏哈希的鎖鏈迅速繃緊，將二人的血肉與靈魂緊緊地拽在了一起。"
  },
  AvgDialog_13733_Content_19 = {
    Text = "唔……什麼……？"
  },
  AvgDialog_13733_Content_2 = {
    Text = "庫西沙漠邊緣\n儀式現場"
  },
  AvgDialog_13733_Content_20 = {
    Text = "尤烏哈希再也無法保持悠閒的坐姿。"
  },
  AvgDialog_13733_Content_21 = {
    Text = "他被無形的力量一把掀翻，有些茫然地望著眼前即將失控的法陣。"
  },
  AvgDialog_13733_Content_24 = {
    Text = "普林趴在地上，惡狠狠地盯著尤烏哈希掙扎的模樣，嘿嘿笑了起來。"
  },
  AvgDialog_13733_Content_25 = {
    Text = "痛苦嗎……痛苦就對了……"
  },
  AvgDialog_13733_Content_26 = {
    Text = "此刻我們的意識被緊緊連接在一起……"
  },
  AvgDialog_13733_Content_27 = {
    Text = "勒姆瓦希狗是如何屠殺我的同胞、玷污我的妻子，你看到了嗎……感受到了嗎……"
  },
  AvgDialog_13733_Content_28 = {
    Text = "<Big:回答我啊，你這個蠢笨如@1的東西！>"
  },
  AvgDialog_13733_Content_3 = {
    Text = "很好，先灑上一層硫磺，然後碳粉……"
  },
  AvgDialog_13733_Content_30 = {
    Text = "別高興得太早……老東西。"
  },
  AvgDialog_13733_Content_31 = {
    Text = "等我掙脫枷鎖，第一個撕碎的人就是你——唔！！"
  },
  AvgDialog_13733_Content_32 = {
    Text = "很遺憾，這次你恐怕無法如願了……"
  },
  AvgDialog_13733_Content_33 = {
    Text = "普林喘著粗氣，顫抖地握住那條看不見的鎖鏈，然後猛地一拽——"
  },
  AvgDialog_13733_Content_34 = {
    Text = "原本無比牢固的鎖鏈就這樣碎裂了。"
  },
  AvgDialog_13733_Content_36 = {
    Text = "普林發出痛苦的哀鳴，臉上的皮肉就像樹皮般不斷潰爛、剝落，露出內裡的模糊血肉。"
  },
  AvgDialog_13733_Content_37 = {
    Text = "法陣張開黑洞洞的大口，將他的血肉一點點吃乾抹淨，直到巫師徹底變成一具空蕩蕩的骨架。"
  },
  AvgDialog_13733_Content_38 = {
    Text = "我已獻祭我的血肉、靈魂和一切……而你呢……"
  },
  AvgDialog_13733_Content_39 = {
    Text = "在殺死一萬個勒姆瓦希狗之前，你都不可能獲得真正的自由！"
  },
  AvgDialog_13733_Content_4 = {
    Text = "不對，看看書裡是怎麼說的……"
  },
  AvgDialog_13733_Content_40 = {
    Text = "尤烏哈希緩緩站了起來。"
  },
  AvgDialog_13733_Content_41 = {
    Text = "他的臉被看不見的火焰灼燒成了黑乎乎的灰燼，風一吹便簌簌落下來。"
  },
  AvgDialog_13733_Content_43 = {
    Text = "“真正的自由”……？那是什麼東西？"
  },
  AvgDialog_13733_Content_44 = {
    Text = "燒焦的戰士屹立於熾熱的火光中。他雙目赤紅，只從喉嚨裡發出沙啞的震顫。"
  },
  AvgDialog_13733_Content_45 = {
    Text = "我，尤烏哈希真正在乎的東西，從來都只有一個——"
  },
  AvgDialog_13733_Content_46 = {
    Text = "他以極快的速度衝了出去，將巫師撲倒在地。"
  },
  AvgDialog_13733_Content_47 = {
    Text = "然後他露出尖利的獠牙，狠狠咬斷了巫師的脖子。"
  },
  AvgDialog_13733_Content_5 = {
    Text = "距離戰場不到五十碼的地方，普林正在辛勤忙碌著。"
  },
  AvgDialog_13733_Content_50 = {
    Text = "<Shake:這條命，給你……復仇@2幫我……>"
  },
  AvgDialog_13733_Content_51 = {
    Text = "幫你？老傢伙，你是不是搞錯了……"
  },
  AvgDialog_13733_Content_52 = {
    Text = "獵物是不配和我尤烏哈希提要求的。"
  },
  AvgDialog_13733_Content_53 = {
    Text = "我能乖乖聽你的話，是因為我可以隨時打爛你的鐵鏈玩具，而不是和你簽訂的狗屁契約。"
  },
  AvgDialog_13733_Content_54 = {
    Text = "遊戲時間結束了。現在，我要你睜大眼睛好好看著——"
  },
  AvgDialog_13733_Content_55 = {
    Text = "我是怎麼屠戮你的敵人、你的同胞，還有你所見到的一切活物……"
  },
  AvgDialog_13733_Content_56 = {
    Text = "<Change>魔鬼……你這個魔鬼……"
  },
  AvgDialog_13733_Content_57 = {
    Text = "普林的鮮血肆意流淌在法陣裡，將那些血紅色的光芒也襯得無比暗淡。"
  },
  AvgDialog_13733_Content_58 = {
    Text = "他獻祭了自己的生命，換來了尤烏哈希的“自由”。"
  },
  AvgDialog_13733_Content_6 = {
    Text = "尤烏哈希則在普林的要求下，端坐於硫磺粉繪製的法陣中央。"
  },
  AvgDialog_13733_Content_60 = {
    Text = "尤烏哈希緩緩抬起頭，嘴角還帶著尚未舔盡的鮮血，眼裡早已被黑暗侵蝕。"
  },
  AvgDialog_13733_Content_61 = {
    Text = "他變成了一頭真正的野獸。又或者說，這才是他原本的面貌。"
  },
  AvgDialog_13733_Content_62 = {
    Text = "<Red:回來了，一切都回來了……>"
  },
  AvgDialog_13733_Content_8 = {
    Text = "真厲害，這種情況下還能睡著……"
  },
  AvgDialog_13733_Content_9 = {
    Text = "我有個技術問題想請教一下，普林先生。\n你撒的這些粉末難道不會被風吹走嗎？"
  },
  AvgDialog_13734_Content_1 = {
    Text = "呼……終於跟上了。\n我警告你，尤烏哈希，擅自離開我的後果你應該清楚吧？"
  },
  AvgDialog_13734_Content_10 = {
    Text = "你們終於抵達了此行的終點。普林喉嚨裡擠出兩聲怪笑，名為復仇的火焰將他燒得全身顫抖。"
  },
  AvgDialog_13734_Content_11 = {
    Text = "<Shake:走吧，尤烏哈希……>"
  },
  AvgDialog_13734_Content_12 = {
    Text = "<Red:去殺個痛快。>"
  },
  AvgDialog_13734_Content_2 = {Text = "噓！！"},
  AvgDialog_13734_Content_3 = {
    Text = "尤烏哈希蹲在高高的沙丘上，鼻腔內發出不耐的噓聲，就像專注狩獵的野獸正在被蚊蟲侵擾。"
  },
  AvgDialog_13734_Content_4 = {
    Text = "他嘴唇微張，鼻翼輕微顫動著，眼裡血紅色的光芒比以往更甚。"
  },
  AvgDialog_13734_Content_6 = {
    Text = "你們順著他的目光向下望去——"
  },
  AvgDialog_13734_Content_7 = {
    Text = "無數小小的黑點散落在起伏不定的沙丘上，就像沙盤上蠕動的螞蟻。"
  },
  AvgDialog_13734_Content_8 = {
    Text = "兵刃相接的碰撞聲、吼叫聲和馬蹄聲此起彼伏，盛大的戰爭繪卷就在你們眼前徐徐展開。"
  },
  AvgDialog_13734_Content_9 = {
    Text = "勒姆瓦希人，雷歐人……好，很好。"
  },
  AvgDialog_13735_Content_1 = {
    Text = "太陽遠征"
  },
  AvgDialog_13735_Content_10 = {
    Text = "他依舊被看不見的鎖鏈束縛著，只能以一種彆扭的姿勢盤坐在地，整個人和黑暗幾乎融為一體。"
  },
  AvgDialog_13735_Content_11 = {
    Text = "……沒想到你還醒著。"
  },
  AvgDialog_13735_Content_12 = {
    Text = "<Yellow:魔像>是不需要睡覺的。"
  },
  AvgDialog_13735_Content_14 = {
    Text = "呵呵……別裝模作樣了。"
  },
  AvgDialog_13735_Content_15 = {
    Text = "你能看見我身上的鎖鏈，想必也該清楚魔像是什麼東西吧。"
  },
  AvgDialog_13735_Content_16 = {
    Text = "沒想到你當時看似隨意的一瞥被他察覺了。\n他身上確實有著野獸的直覺。"
  },
  AvgDialog_13735_Content_17 = {
    Text = "我的老師曾告訴我……"
  },
  AvgDialog_13735_Content_18 = {
    Text = "在古羅馬時期，有個瘋狂的煉金術士以大量人牲為代價，煉製出了最早的魔像。"
  },
  AvgDialog_13735_Content_19 = {
    Text = "這也是古代文獻中最接近喚醒體的存在。"
  },
  AvgDialog_13735_Content_2 = {
    Text = "庫西沙漠北部，夜"
  },
  AvgDialog_13735_Content_20 = {
    Text = "那個魔像，就是你對吧？"
  },
  AvgDialog_13735_Content_21 = {
    Text = "沒錯……是我。我成了<Blue:卡里古拉>的走狗，替他殺了很多人。"
  },
  AvgDialog_13735_Content_22 = {
    Text = "後來他們不再需要我了，就把我鎖在伸手不見五指的地下，直到那傢伙把我給放了出來。"
  },
  AvgDialog_13735_Content_23 = {
    Text = "尤烏哈希一邊說著，眼神掠過還在帳篷裡呼呼大睡的普林。"
  },
  AvgDialog_13735_Content_24 = {
    Text = "——條件是？"
  },
  AvgDialog_13735_Content_25 = {
    Text = "條件就是，先給他當狗，去戰場上殺死多多的勒姆瓦希人。"
  },
  AvgDialog_13735_Content_26 = {
    Text = "然後我們一拍兩散，各過各的生活。"
  },
  AvgDialog_13735_Content_27 = {
    Text = "尤烏哈希舒服地伸了個懶腰，大剌剌地岔開雙腿靠坐在沙丘上。"
  },
  AvgDialog_13735_Content_28 = {
    Text = "這種程度的鎖鏈根本無法限制你。為什麼不直接殺了巫師然後離開？"
  },
  AvgDialog_13735_Content_29 = {
    Text = "因為他說，戰場上有很多人。"
  },
  AvgDialog_13735_Content_3 = {
    Text = "呼嚕……呼嚕……咻……"
  },
  AvgDialog_13735_Content_30 = {
    Text = "<Red:有很多人，就會有很多血。>"
  },
  AvgDialog_13735_Content_31 = {
    Text = "<RedShake:要知道，我已經有近千年沒有嚐過那些血的味道了……>"
  },
  AvgDialog_13735_Content_33 = {
    Text = "那傢伙看起來可不是什麼信守承諾的好人。萬一他騙你呢？"
  },
  AvgDialog_13735_Content_34 = {
    Text = "那就殺了他。很簡單，不是麼？"
  },
  AvgDialog_13735_Content_36 = {
    Text = "不得不承認，他的話很有道理。"
  },
  AvgDialog_13735_Content_37 = {
    Text = "晚風輕輕吹過，溫柔起伏的沙丘在你面前不斷延展，無邊的蒼穹下只剩下兩個渺小的身影。"
  },
  AvgDialog_13735_Content_38 = {
    Text = "你抬頭仰望繁星密布的天空。"
  },
  AvgDialog_13735_Content_39 = {
    Text = "為了打發這個漫長的夜晚，你決定和眼前這位魔像交流一番心得體驗。"
  },
  AvgDialog_13735_Content_4 = {
    Text = "寂靜的夜裡鼾聲如雷鳴，看來白天的小插曲並未影響到普林的好睡眠。"
  },
  AvgDialog_13735_Content_40 = {
    Text = "被關在地下一定很不好受吧。\n履行約定後你就能重獲自由了，現在感覺如何？"
  },
  AvgDialog_13735_Content_41 = {
    Text = "那你呢？\n你也早就不是奴隸了，整天遊蕩在沙漠裡討生活，感覺如何？"
  },
  AvgDialog_13735_Content_43 = {
    Text = "確實不怎麼樣。這鬼地方連太陽都看不到……"
  },
  AvgDialog_13735_Content_44 = {
    Text = "我看你可真夠瞎的。沙漠裡那麼大的太陽看不見？"
  },
  AvgDialog_13735_Content_45 = {
    Text = "你不懂。我說的是那種，溫柔的、明亮的，曬起來暖洋洋的太陽……沙漠裡可見不到。"
  },
  AvgDialog_13735_Content_46 = {
    Text = "你打了個哈欠，困意逐漸湧起。\n神經稍一鬆懈，交談也變得隨意不少。"
  },
  AvgDialog_13735_Content_47 = {
    Text = "出乎你意料的是，尤烏哈希還算一個勉強合格的傾聽者。"
  },
  AvgDialog_13735_Content_48 = {
    Text = "說出來你可能不會相信，我其實也是有任務在身的……"
  },
  AvgDialog_13735_Content_49 = {
    Text = "等哪天做完那些該做的事，我一定會找個地方躺著曬太陽，吃很多很多小蛋糕……"
  },
  AvgDialog_13735_Content_5 = {
    Text = "你忍無可忍，最後掀開帳篷走到外面。"
  },
  AvgDialog_13735_Content_50 = {
    Text = "……難以理解。"
  },
  AvgDialog_13735_Content_51 = {
    Text = "魔像脫胎於黑暗，天性便畏懼陽光，近千年的囚禁更是加深了他對陽光的厭惡。"
  },
  AvgDialog_13735_Content_52 = {
    Text = "我真為你感到可惜，曬太陽可是天底下最愉快的事……"
  },
  AvgDialog_13735_Content_53 = {
    Text = "可惜對我來說，就連這樣的願望也很難實現……"
  },
  AvgDialog_13735_Content_54 = {
    Text = "起風了。\n浮動的細沙織出一層又一層淡黃的柔紗，輕輕飄蕩在布滿星星的夜空下。"
  },
  AvgDialog_13735_Content_55 = {
    Text = "你聽著自遠方傳來的乾淨風聲，終於沉入夢鄉。"
  },
  AvgDialog_13735_Content_57 = {
    Text = "庫西沙漠北部，日"
  },
  AvgDialog_13735_Content_58 = {
    Text = "真是活見鬼！你之前不是拍著胸脯說最近幾天都不可能有沙塵暴嗎？！"
  },
  AvgDialog_13735_Content_59 = {
    Text = "普林瞪著眼睛指向天邊滾滾襲來的狂沙。"
  },
  AvgDialog_13735_Content_60 = {
    Text = "現在你告訴我，<Big:那@1是什麼？>"
  },
  AvgDialog_13735_Content_61 = {Text = "額……"},
  AvgDialog_13735_Content_62 = {
    Text = "在你“入夢”前，原主為了宰這頭肥羊，的確做了一些違心的承諾。"
  },
  AvgDialog_13735_Content_63 = {
    Text = "現在不是吵架的時候，沙塵暴就要來了，還不快跑——"
  },
  AvgDialog_13735_Content_64 = {
    Text = "說完你便以最快的速度衝了出去，將普林遠遠拋在身後。"
  },
  AvgDialog_13735_Content_65 = {
    Text = "<Big:喂……給我站住！>"
  },
  AvgDialog_13735_Content_66 = {
    Text = "沙塵暴？那是什麼，風景看上去不錯啊。"
  },
  AvgDialog_13735_Content_67 = {
    Text = "尤烏哈希背著身輕鬆跑到你身側，眼睛還一眨不眨地盯著遠方。"
  },
  AvgDialog_13735_Content_68 = {
    Text = "你從沒見過沙塵暴？"
  },
  AvgDialog_13735_Content_69 = {
    Text = "尤烏哈希聳了聳肩。"
  },
  AvgDialog_13735_Content_7 = {
    Text = "晚上好，嚮導先生。"
  },
  AvgDialog_13735_Content_70 = {
    Text = "我過去的活動範圍僅限羅馬城內，沒見過的東西可太多了。"
  },
  AvgDialog_13735_Content_71 = {
    Text = "<Shake:呃……嘔……>"
  },
  AvgDialog_13735_Content_72 = {
    Text = "受到鎖鏈的牽動，落後你們一大截的普林被拽得飛了起來。"
  },
  AvgDialog_13735_Content_73 = {
    Text = "<Shake:慢、慢一點……我快死了……>"
  },
  AvgDialog_13735_Content_74 = {
    Text = "嘖。差點忘了，還有個老傢伙。"
  },
  AvgDialog_13735_Content_75 = {
    Text = "尤烏哈希折返回去，輕巧地將巫師矮胖的身軀拎了起來。"
  },
  AvgDialog_13735_Content_76 = {
    Text = "你、你想做什麼？"
  },
  AvgDialog_13735_Content_77 = {
    Text = "不做什麼，幫你跑得再快一點。"
  },
  AvgDialog_13735_Content_78 = {
    Text = "說罷尤烏哈希輕鬆地將巫師夾在腋下，前腳跨出一步，後腳半掌蹬地，將整個身子都弓了起來。"
  },
  AvgDialog_13735_Content_79 = {
    Text = "喂……我警告你，現在可不是玩的時候——<Big:嗷！！！>"
  },
  AvgDialog_13735_Content_80 = {
    Text = "尤烏哈希猛地一蹬腿，如離弦的箭一般嗖嗖飛了出去。"
  },
  AvgDialog_13735_Content_81 = {
    Text = "我、你……臭@1，放我下來！"
  },
  AvgDialog_13735_Content_82 = {
    Text = "尤烏哈希爆發出陣陣大笑。\n笑聲飛在風裡，交織著金黃色的細沙與塵埃，歡快地奔向遠方。"
  },
  AvgDialog_13735_Content_83 = {
    Text = "那可不行，我還得留著你的命幫我重獲自由呢！"
  },
  AvgDialog_13735_Content_9 = {
    Text = "尤烏哈希冷不丁從角落裡冒了出來，朝你咧嘴笑著。"
  },
  AvgDialog_13736_Content_1 = {
    Text = "嚮導，巫師與奴隸"
  },
  AvgDialog_13736_Content_10 = {
    Text = "焦黃、乾燥，掌心的紋路粗獷狂放——這是一雙戰士的手。"
  },
  AvgDialog_13736_Content_100 = {
    Text = "抱歉，我和你沒什麼好說的。"
  },
  AvgDialog_13736_Content_101 = {
    Text = "僱傭兵都是一幫沒有信仰的傢伙。至於奴隸，更是不可能明白尊嚴和榮譽為何物。"
  },
  AvgDialog_13736_Content_102 = {
    Text = "你和那傢伙，你們兩個沒什麼本質不同。"
  },
  AvgDialog_13736_Content_103 = {
    Text = "不過我也早過了衝動的年紀。"
  },
  AvgDialog_13736_Content_104 = {
    Text = "首先，我打不過你。\n其次，你對我還有那麼點用。"
  },
  AvgDialog_13736_Content_105 = {
    Text = "不管你是從哪裡來的，現在、此時此刻，繼續帶隊吧，我的嚮導先生。"
  },
  AvgDialog_13736_Content_11 = {
    Text = "<Gray:賈米拉·@1，32歲，前馬穆留傭兵，現在是沙漠中的嚮導……>"
  },
  AvgDialog_13736_Content_12 = {
    Text = "你默默地消化著自己的新身份。"
  },
  AvgDialog_13736_Content_13 = {
    Text = "看來你又“入夢”了。"
  },
  AvgDialog_13736_Content_14 = {
    Text = "喂，鬼鬼祟祟說什麼呢？醒了就趕緊起來，我和我的<Blue:奴隸>還有要緊事。"
  },
  AvgDialog_13736_Content_15 = {
    Text = "身材矮胖、一身奇特裝束的男人是你這單生意的僱主<Blue:路德維希·普林>。"
  },
  AvgDialog_13736_Content_16 = {
    Text = "他不耐煩地說著，用鞭子草草指向身後。"
  },
  AvgDialog_13736_Content_18 = {
    Text = "尤烏哈希——？！"
  },
  AvgDialog_13736_Content_19 = {
    Text = "你這才注意到隱匿在沙丘後的男人。"
  },
  AvgDialog_13736_Content_2 = {
    Text = "@2年，教皇失勢，王權興起\n聖城阿卡成為必爭之地\n\n因忌憚以拜伯而斯為首的馬穆留勢力\n王子號召全民出征遠東，奪回聖城阿卡"
  },
  AvgDialog_13736_Content_20 = {
    Text = "他維持著蹲伏的姿勢，長長的雙臂隨意撐在地上，就像一頭蓄勢待發的猛獸。"
  },
  AvgDialog_13736_Content_21 = {
    Text = "見到你震驚的模樣，他咧嘴笑了起來，露出一排白森森的尖牙。"
  },
  AvgDialog_13736_Content_22 = {
    Text = "怎麼，你認識我？"
  },
  AvgDialog_13736_Content_24 = {
    Text = "你還未來得及搭話，巫師手中的長鞭就狠狠掄在尤烏身上。"
  },
  AvgDialog_13736_Content_25 = {
    Text = "這位好兄弟，我勸你別和他搭話。"
  },
  AvgDialog_13736_Content_26 = {
    Text = "別看他長著和我們一樣的眼睛鼻子，其實還是個不開化的野獸，或者說……"
  },
  AvgDialog_13736_Content_28 = {
    Text = "又一道長鞭狠狠掄在了尤烏身上。"
  },
  AvgDialog_13736_Content_29 = {
    Text = "他就是個<Red:惡魔>。"
  },
  AvgDialog_13736_Content_3 = {
    Text = "至此，聲勢浩大的<Yellow:東征>再一次拉開序幕……"
  },
  AvgDialog_13736_Content_30 = {
    Text = "接連被數道長鞭伺候，尤烏哈希卻連眼睛都不眨一下。"
  },
  AvgDialog_13736_Content_31 = {
    Text = "他摸了一把自額角淌下的鮮血，將手掌放至鼻腔前嗅了嗅，隨後竟不緊不慢地舔起了指尖上的血。"
  },
  AvgDialog_13736_Content_32 = {
    Text = "喏，看到了嗎？我家看門的狗都比他通人性！畜生都不如，哈哈哈哈！"
  },
  AvgDialog_13736_Content_33 = {
    Text = "喂……老傢伙，今天的力道弱了不少啊。\n怎麼，連鞭子都拿不穩了？"
  },
  AvgDialog_13736_Content_35 = {
    Text = "畜生之所以是畜生，就是因為牠們總是沒辦法管好自己的嘴，或者認清自己的地位。"
  },
  AvgDialog_13736_Content_36 = {
    Text = "沒關係，我會<BigItalic:好好教你>——"
  },
  AvgDialog_13736_Content_37 = {
    Text = "普林氣得鬍子都吹了起來，隨後就像一顆彈射的皮球，迅速朝著尤烏哈希的方向飛了出去。"
  },
  AvgDialog_13736_Content_39 = {
    Text = "你握住普林的手腕將他拽了回來。"
  },
  AvgDialog_13736_Content_40 = {
    Text = "鞭子給我。"
  },
  AvgDialog_13736_Content_41 = {
    Text = "放開我！讓我教訓一下那個畜生……"
  },
  AvgDialog_13736_Content_42 = {
    Text = "賈米拉先生，我現在是你的僱主。不用我解釋什麼是僱主吧？"
  },
  AvgDialog_13736_Content_43 = {
    Text = "抱歉，我只知道我是這趟行程的嚮導。\n既然我是嚮導，那你們就要聽我的。"
  },
  AvgDialog_13736_Content_44 = {
    Text = "不然我現在就走，你們自己去<Blue:戰場>吧。"
  },
  AvgDialog_13736_Content_45 = {
    Text = "<Shake:喂，喂……！有話好好商量，好好商量……>"
  },
  AvgDialog_13736_Content_46 = {
    Text = "還有一件事。"
  },
  AvgDialog_13736_Content_47 = {
    Text = "你蹙眉看向尤烏哈希。"
  },
  AvgDialog_13736_Content_48 = {
    Text = "你和他在校園內交集雖少，卻也對他的各種事蹟略知一二。"
  },
  AvgDialog_13736_Content_49 = {
    Text = "他絕不是那種受制於人的角色。"
  },
  AvgDialog_13736_Content_5 = {
    Text = "你從漫長的熟睡中睜開雙眼，目之所及是一片廣袤無垠的沙漠。"
  },
  AvgDialog_13736_Content_50 = {
    Text = "你對這傢伙做了什麼？他怎麼可能乖乖聽你的話？"
  },
  AvgDialog_13736_Content_51 = {
    Text = "怎麼，你是在質疑本人身為<Blue:黎凡特首席大巫師>的能力？"
  },
  AvgDialog_13736_Content_52 = {
    Text = "這可是咱們這行的絕版秘術，也是我身為僱主的隱私，請嚮導先生不要多管閒事……"
  },
  AvgDialog_13736_Content_53 = {
    Text = "不說是吧？\n那就打到你說為止。"
  },
  AvgDialog_13736_Content_56 = {
    Text = "<Shake:嘶，好痛……你、你絕不是什麼普通的嚮導！>"
  },
  AvgDialog_13736_Content_57 = {
    Text = "說吧，你是不是<Blue:勒姆瓦希>那邊派來阻截我的奸細？"
  },
  AvgDialog_13736_Content_58 = {
    Text = "你並未回應普林的質問，因為你全部的注意早已被另外的事物所吸引——"
  },
  AvgDialog_13736_Content_59 = {
    Text = "一條細長的鎖鏈在日光下若隱若現，散發著不同尋常的輝光。"
  },
  AvgDialog_13736_Content_6 = {
    Text = "醒了？真是活見鬼，還沒走兩步嚮導先中暑暈倒了，這叫什麼事？"
  },
  AvgDialog_13736_Content_60 = {
    Text = "它從普林的手腕處一路延伸，一直延續到尤烏哈希的脖頸處結束。"
  },
  AvgDialog_13736_Content_61 = {
    Text = "<Gray:好眼熟的手法……似乎聽誰說起過……>"
  },
  AvgDialog_13736_Content_62 = {
    Text = "不聽話的傢伙，拿條狗鏈拴起來不就好了。"
  },
  AvgDialog_13736_Content_63 = {
    Text = "這在倫蒂尼恩可是違法的，阿格里帕小姐。恐怕我們得向你普及一些基本的法律常識……"
  },
  AvgDialog_13736_Content_64 = {
    Text = "嘻嘻，我又不是蠢貨。"
  },
  AvgDialog_13736_Content_65 = {
    Text = "你知道@1嗎？"
  },
  AvgDialog_13736_Content_66 = {
    Text = "那可是一種古老的秘法，施法者能用一條看不見的鎖鏈控制別人……"
  },
  AvgDialog_13736_Content_67 = {
    Text = "至於代價嘛……"
  },
  AvgDialog_13736_Content_68 = {
    Text = "代價是什麼呢？糟糕，不記得了……"
  },
  AvgDialog_13736_Content_69 = {
    Text = "你兀自沉浸在回憶裡，冷不丁臉上纏著的面罩被人一把掀開。"
  },
  AvgDialog_13736_Content_7 = {
    Text = "幸好鬼地方我這輩子只來這一次，@1！"
  },
  AvgDialog_13736_Content_70 = {
    Text = "三條彎曲的河流……你是<Blue:馬穆留的奴隸傭兵>？！"
  },
  AvgDialog_13736_Content_71 = {
    Text = "普林話音剛落，原本事不關己的尤烏哈希忽然轉頭看了你一眼。"
  },
  AvgDialog_13736_Content_73 = {
    Text = "不、不對，馬穆留的人現在應該在戰場上……"
  },
  AvgDialog_13736_Content_74 = {
    Text = "我明白了，你是個逃兵。"
  },
  AvgDialog_13736_Content_75 = {
    Text = "你下意識摸了摸自己的臉。"
  },
  AvgDialog_13736_Content_76 = {
    Text = "<Gray:原來我臉上還有紋身……>"
  },
  AvgDialog_13736_Content_77 = {
    Text = "沒錯，我的確是個逃兵。我的家鄉在<Blue:勒姆瓦希>，可我也不想回去了……"
  },
  AvgDialog_13736_Content_78 = {
    Text = "逃兵也要吃飯，所以我現在以嚮導為生。\n放心吧，我這個人最大的優點就是對待工作一絲不苟。"
  },
  AvgDialog_13736_Content_79 = {
    Text = "保證能把你們帶到戰場——"
  },
  AvgDialog_13736_Content_8 = {
    Text = "嚮導？這是……什麼地方……"
  },
  AvgDialog_13736_Content_81 = {
    Text = "看夠了眼前的鬧劇，尤烏哈希伸了個懶腰，悠閒地走到你面前。"
  },
  AvgDialog_13736_Content_82 = {
    Text = "他一把攬住你的肩，隨後輕輕擰轉你的下巴，直到你的視線剛好對準眼前沉默的巫師。"
  },
  AvgDialog_13736_Content_83 = {
    Text = "看在我們都是、或者曾經都是奴隸的份上，我稍微提示一下——"
  },
  AvgDialog_13736_Content_84 = {
    Text = "我如果是你的話，這時候就該閉嘴了。\n知道那傢伙最討厭什麼人嗎？"
  },
  AvgDialog_13736_Content_85 = {
    Text = "……被這傢伙教導謹言慎行的感覺還真是奇妙。"
  },
  AvgDialog_13736_Content_86 = {
    Text = "……願聞其詳。"
  },
  AvgDialog_13736_Content_87 = {
    Text = "第三，馬穆留僱傭兵。"
  },
  AvgDialog_13736_Content_88 = {
    Text = "第二，勒姆瓦希人。\n至於第一嘛……"
  },
  AvgDialog_13736_Content_89 = {
    Text = "肩膀傳來陣陣劇痛——尤烏哈希一邊大笑，一邊狠狠地拍著你的肩膀。"
  },
  AvgDialog_13736_Content_9 = {
    Text = "炙熱的陽光將你烤得頭暈目眩，你低頭望向自己的雙手。"
  },
  AvgDialog_13736_Content_90 = {
    Text = "<Big:當然是來自勒姆瓦希的馬穆留僱傭軍囉！>"
  },
  AvgDialog_13736_Content_91 = {
    Text = "<Gray:……很好。除了他以外應該沒人笑得出聲吧。>"
  },
  AvgDialog_13736_Content_92 = {
    Text = "<Gray:這傢伙得罪人的本事可真是一等一的。>"
  },
  AvgDialog_13736_Content_94 = {
    Text = "當初馬穆留僱傭軍屠戮我數萬同胞，我的妻子、戰友、導師……全都命喪於此。"
  },
  AvgDialog_13736_Content_95 = {
    Text = "好了，我悲慘的故事講完了，你們可以接著笑了。"
  },
  AvgDialog_13736_Content_96 = {
    Text = "抱歉，普林先生。請容我解釋一下，雖然我有一些……嗯，不太光彩的過去。"
  },
  AvgDialog_13736_Content_97 = {
    Text = "但那都是過去，和現在的我沒有任何關係。"
  },
  AvgDialog_13736_Content_98 = {
    Text = "普林朝你擺了擺手。"
  },
  AvgDialog_13736_Content_99 = {
    Text = "他圓圓的臉在烈日炙烤下就像一只熟透了的大蘋果——可惜這顆大蘋果現在不太高興。"
  },
  AvgDialog_13737_Content_1 = {
    Text = "悲劇的謝幕"
  },
  AvgDialog_13737_Content_11 = {
    Text = "尤烏哈希輕巧地捏碎了擋路者的腦子，緩緩走到另一個士兵面前。"
  },
  AvgDialog_13737_Content_13 = {
    Text = "他緩緩抬起手。"
  },
  AvgDialog_13737_Content_17 = {
    Text = "對啊，是我。"
  },
  AvgDialog_13737_Content_18 = {
    Text = "你擋在二人中間，轉頭望向身後被嚇得跪在地上的士兵。"
  },
  AvgDialog_13737_Content_19 = {
    Text = "快走。跑得越遠越好。"
  },
  AvgDialog_13737_Content_2 = {
    Text = "庫西沙漠邊緣，戰場"
  },
  AvgDialog_13737_Content_20 = {
    Text = "<Big:滾！！>"
  },
  AvgDialog_13737_Content_21 = {
    Text = "<Shake:好、好……我滾……>"
  },
  AvgDialog_13737_Content_22 = {
    Text = "士兵們連滾帶爬地離開了。"
  },
  AvgDialog_13737_Content_23 = {
    Text = "為什麼要阻撓我？我才剛嚐到一點血和戰鬥的樂趣……"
  },
  AvgDialog_13737_Content_24 = {
    Text = "不就是想戰鬥麼？我陪你玩。"
  },
  AvgDialog_13737_Content_25 = {
    Text = "你？哈哈哈哈，你算什麼——"
  },
  AvgDialog_13737_Content_27 = {
    Text = "你將彎刀抵在了尤烏哈希的脖頸處，冷靜地望著他早已失去焦距的雙眼。"
  },
  AvgDialog_13737_Content_28 = {
    Text = "不試試看怎麼知道呢？"
  },
  AvgDialog_13737_Content_3 = {
    Text = "喂，聽說了嗎？又瘋了一個，見人就殺。"
  },
  AvgDialog_13737_Content_4 = {
    Text = "他們說他不是雷歐人，也不是勒姆瓦希人，不知道是從哪裡冒出來的……"
  },
  AvgDialog_13737_Content_5 = {
    Text = "總之趕緊離開——"
  },
  AvgDialog_13737_Content_7 = {
    Text = "<Shake:你、你什麼時候出現的……>"
  },
  AvgDialog_13738_Content_1 = {
    Text = "很好，沙塵暴往另一頭去了。接下來我們……"
  },
  AvgDialog_13738_Content_11 = {
    Text = "你不是想去戰場嗎？那當然應該沿著<Red:血的方向>前進。"
  },
  AvgDialog_13738_Content_13 = {
    Text = "你指了指尤烏哈希大步離開的背影。"
  },
  AvgDialog_13738_Content_2 = {
    Text = "嘔——！！"
  },
  AvgDialog_13738_Content_3 = {
    Text = "普林手撐著光禿禿的樹幹，弓著身子開始劇烈嘔吐。"
  },
  AvgDialog_13738_Content_4 = {
    Text = "我發誓，等做完這單買賣。我發誓……"
  },
  AvgDialog_13738_Content_5 = {
    Text = "這一次，巫師虛弱的詛咒並未得到任何回應。"
  },
  AvgDialog_13738_Content_6 = {
    Text = "不知發現了什麼，尤烏哈希的瞳孔忽然微不可見地收縮了一瞬。"
  },
  AvgDialog_13738_Content_8 = {
    Text = "說完他頭也不回地離開了。"
  },
  AvgDialog_13738_Content_9 = {
    Text = "等等……！沒有我的允許，你哪裡也不能去！"
  },
  AvgDialog_13739_Content_1 = {
    Text = "禿鷲在血紅色的霞光中高聲鳴叫，戰場上早已空無一人。"
  },
  AvgDialog_13739_Content_10 = {
    Text = "交手期間，你明顯感到尤烏哈希的狀態正在以驚人的速度衰退。"
  },
  AvgDialog_13739_Content_11 = {
    Text = "不管這是不是契約的副作用，現在的他已是強弩之末。"
  },
  AvgDialog_13739_Content_12 = {
    Text = "戰鬥當然要勢均力敵才有意思，為此我不介意自己變弱一些。"
  },
  AvgDialog_13739_Content_13 = {
    Text = "我從不關心人類的想法，就像人類不關心螞蟻一樣。"
  },
  AvgDialog_13739_Content_14 = {
    Text = "但你不同。你內裡有一股強大的力量，並且你懂得克制。"
  },
  AvgDialog_13739_Content_15 = {
    Text = "繼續保持吧，戰士。你那些無聊的願望——太陽，小蛋糕之類的，或許真的能實現。"
  },
  AvgDialog_13739_Content_16 = {
    Text = "<Gray:只是隨口一說的胡話，他居然還記得……>"
  },
  AvgDialog_13739_Content_17 = {
    Text = "走吧……去你說過的，有太陽的地方。"
  },
  AvgDialog_13739_Content_2 = {
    Text = "你和尤烏哈希隔著不到十碼的距離，沉默地看向彼此。"
  },
  AvgDialog_13739_Content_20 = {
    Text = "我……？老傢伙留了一手，我活不長了。呵呵……"
  },
  AvgDialog_13739_Content_21 = {
    Text = "老傢伙和我都得死……這才是打破契約的真正代價。"
  },
  AvgDialog_13739_Content_22 = {
    Text = "他邁著吃力的步伐，緩緩朝你走過來。"
  },
  AvgDialog_13739_Content_23 = {
    Text = "隨後他用牙齒咬開自己的手腕。"
  },
  AvgDialog_13739_Content_24 = {
    Text = "猩紅刺鼻的鮮血傾瀉如注，滴落到你的頭頂上，眼皮上，再順著你的鼻樑流至乾澀的嘴唇。"
  },
  AvgDialog_13739_Content_25 = {
    Text = "這血……就當是我的臨別贈禮吧。"
  },
  AvgDialog_13739_Content_26 = {
    Text = "禿鷲們盤旋在他頭頂，顯然已經盯上了將死的獵物。"
  },
  AvgDialog_13739_Content_27 = {
    Text = "我從萬千血肉中誕生，在這世上漂泊已近千年……"
  },
  AvgDialog_13739_Content_28 = {
    Text = "我見過凱旋式上漫天飛舞的金箔，也見過火焰中熊熊燃燒的黃金宮殿。"
  },
  AvgDialog_13739_Content_29 = {
    Text = "我享用過最美味的鮮血，也經歷過最殘暴的戰鬥。"
  },
  AvgDialog_13739_Content_3 = {
    Text = "喂……我們打了有多久了？"
  },
  AvgDialog_13739_Content_30 = {
    Text = "我屠戮人類，也被人類束縛、利用，最後毫不意外地死於人類之手。"
  },
  AvgDialog_13739_Content_31 = {
    Text = "現在，是我離開的時候了……"
  },
  AvgDialog_13739_Content_32 = {
    Text = "他居高臨下地望著你，眼裡沒有任何情緒。"
  },
  AvgDialog_13739_Content_33 = {
    Text = "黏稠的血從你的鼻尖一點點滴到地上。"
  },
  AvgDialog_13739_Content_34 = {
    Text = "你就像一個懵懂的受洗者，對眼前發生的一切都茫然無措。"
  },
  AvgDialog_13739_Content_35 = {
    Text = "我把我的血肉都還給你，還給這個世界。"
  },
  AvgDialog_13739_Content_36 = {
    Text = "它們屬於天空，屬於大地……屬於你，但不屬於我。"
  },
  AvgDialog_13739_Content_37 = {
    Text = "現在你可以滾了……頭也不回地滾吧。"
  },
  AvgDialog_13739_Content_38 = {
    Text = "視線終於被茫茫血霧所覆蓋。\n你閉上雙眼，感到一陣陣暈眩，彷彿大地正在不斷下沉。"
  },
  AvgDialog_13739_Content_39 = {
    Text = "後來的故事你已經記不太清了。"
  },
  AvgDialog_13739_Content_40 = {
    Text = "或許你早已離開，或許你和他一起死在了這片沙漠裡。"
  },
  AvgDialog_13739_Content_41 = {
    Text = "這些都不重要。因為你將永遠記得他臨死前的那一刻。"
  },
  AvgDialog_13739_Content_42 = {
    Text = "那時候一群黑色的禿鷲飛過，正好擋住了他身後的霞光。"
  },
  AvgDialog_13739_Content_43 = {
    Text = "光不斷減弱，四周泛起一層陰影，他就跪倒在那片陰影中望著你。"
  },
  AvgDialog_13739_Content_44 = {
    Text = "他說——"
  },
  AvgDialog_13739_Content_45 = {Text = "滾吧。"},
  AvgDialog_13739_Content_46 = {
    Text = "去找那有太陽的鬼地方吧。"
  },
  AvgDialog_13739_Content_5 = {
    Text = "誰知道呢……一小時、一天？"
  },
  AvgDialog_13739_Content_7 = {
    Text = "一千年……我已經快一千年沒享受過這樣酣暢淋漓的戰鬥了。"
  },
  AvgDialog_13739_Content_8 = {
    Text = "你是天生的戰士。"
  },
  AvgDialog_13739_Content_9 = {
    Text = "真令人意外，你什麼時候也學會說人類的恭維話了。"
  },
  AvgDialog_138765_Content_1 = {
    Text = "維度的餘燼正在流轉。命運紡輪摩伊賴，已於此轉動。"
  },
  AvgDialog_138765_Content_2 = {
    Text = "放手一搏吧，守秘人{Male=先生,Female=小姐}。我會協助您，修正錯誤的命運，破壞那些不應存在的繭。"
  },
  AvgDialog_138765_Content_3 = {
    Text = "命運的走向，從來不由他人編織。"
  },
  AvgDialog_138766_Content_1 = {
    Text = "這是……結束了嗎？"
  },
  AvgDialog_138766_Content_2 = {
    Text = "小心，守密人……毀滅命運的紡輪，已經在她身後轉動……"
  },
  AvgDialog_138766_Content_4 = {
    Text = "「看吶！命運愚笨的信徒們，命定的喪鐘已經敲響！」"
  },
  AvgDialog_138766_Content_5 = {
    Text = "「我即終末——我即命運——我即@4！」"
  },
  AvgDialog_138766_Content_6 = {
    Text = "「現在，我將那至高的結局，我將那渴盼的解脫，賜予你們！！！」"
  },
  AvgDialog_13946_Content_1 = {
    Text = "無依之海"
  },
  AvgDialog_13946_Content_10 = {
    Text = "派你“護送”我去找女巫？\n真叫人笑掉大牙。那幫人的心思再明顯不過了……"
  },
  AvgDialog_13946_Content_11 = {
    Text = "戈利亞發出痛苦的抽氣聲。在他身下，一灘暗紅的血跡正緩緩擴大，一路流淌至你的腳下。"
  },
  AvgDialog_13946_Content_12 = {
    Text = "<Red:他們想讓我們一起死在這海上。>"
  },
  AvgDialog_13946_Content_13 = {
    Text = "大人，您受了很嚴重的傷！這是怎麼回事……"
  },
  AvgDialog_13946_Content_14 = {
    Text = "紛亂的記憶湧入你的腦海。"
  },
  AvgDialog_13946_Content_15 = {
    Text = "在上一場關鍵的戰役中，領袖戈利亞因輕敵輸給了敵對的部落。"
  },
  AvgDialog_13946_Content_16 = {
    Text = "非利士人不接受失敗。身受重傷的戈利亞慘遭流放，陪伴他的只有一條破舊的小船，以及你——"
  },
  AvgDialog_13946_Content_17 = {
    Text = "最弱小的非利士人，連摔跤都能輸給十歲幼童。"
  },
  AvgDialog_13946_Content_18 = {
    Text = "我記得首領<Blue:以格倫>說過，附近海域有一位神秘的女巫，她會使用一種黑色的黏液……"
  },
  AvgDialog_13946_Content_19 = {
    Text = "只要將它灌注到傷口上，大人身上的傷一定能痊癒！"
  },
  AvgDialog_13946_Content_2 = {
    Text = "為海之使徒嘆息。\n為我們的光，我們的希望嘆息。\n\n因被放逐海洋的命運，我們哭號、哀嘆、流盡眼淚。"
  },
  AvgDialog_13946_Content_20 = {
    Text = "你條件反射地拋出女巫的傳說，隨後才從中覺出了一絲不對勁。"
  },
  AvgDialog_13946_Content_21 = {
    Text = "<Gray:等等，這黏液難道是融蝕漿……>"
  },
  AvgDialog_13946_Content_22 = {
    Text = "首領、以格倫？"
  },
  AvgDialog_13946_Content_23 = {
    Text = "戈利亞冰冷的臉上緩緩浮起笑意。"
  },
  AvgDialog_13946_Content_24 = {
    Text = "看來他已經成為你們的新任首領了。很高效，不愧是我最親愛的族人們。"
  },
  AvgDialog_13946_Content_25 = {
    Text = "嘩啦！！"
  },
  AvgDialog_13946_Content_26 = {
    Text = "朽木般的小船終於承受不住海浪的衝擊，裂開了一個大洞，源源不斷的海水灌了進來。"
  },
  AvgDialog_13946_Content_27 = {
    Text = "嘖，果然不出我所料。"
  },
  AvgDialog_13946_Content_28 = {
    Text = "糟了，我們會被淹死的！得趕緊找東西把洞補上……"
  },
  AvgDialog_13946_Content_3 = {
    Text = "噢，請護佑多災的人吧！\n將憐憫的目光投向我們，將黑色的生命源泉賜予我們。"
  },
  AvgDialog_13946_Content_30 = {
    Text = "戈利亞興趣缺缺地斜靠在甲板上，任由身下的鮮血將灌入的海水染紅。"
  },
  AvgDialog_13946_Content_31 = {
    Text = "放寬心。就算我們把船修好，他們也有一萬種方法讓我死在這片海裡。"
  },
  AvgDialog_13946_Content_32 = {
    Text = "我的建議是你別管我了。下船，然後自己游回去。"
  },
  AvgDialog_13946_Content_33 = {
    Text = "告訴他們你已經把我殺了。運氣好的話，或許還能留條小命。"
  },
  AvgDialog_13946_Content_36 = {
    Text = "戈利亞悠閒地欣賞著海面上的風景，側頭朝你微微一笑。"
  },
  AvgDialog_13946_Content_37 = {
    Text = "坐在這裡欣賞大海，順便等死。"
  },
  AvgDialog_13946_Content_39 = {
    Text = "<Gray:如此消極，這真的是我認識的戈利亞嗎？>"
  },
  AvgDialog_13946_Content_4 = {
    Text = "<Red:憐憫，憐憫，憐憫……>"
  },
  AvgDialog_13946_Content_40 = {
    Text = "對了，還有件事我要提醒你。"
  },
  AvgDialog_13946_Content_41 = {
    Text = "你屁股後面還有個洞。根據我的經驗，這艘船會馬上斷成兩截，留給你思考的時間已經不多了。"
