  AvgDialog_13946_Content_63 = {
    Text = "戈利亞聲音逐漸低弱下來，既像是問你，也像是在問他自己。"
  },
  AvgDialog_13946_Content_64 = {
    Text = "被族人驅逐、身負重傷，此刻他的前路就像眼前霧影幢幢的大海，只剩無盡的渺茫。"
  },
  AvgDialog_13946_Content_66 = {
    Text = "大人您嘴上說著要等死，可是當海浪真正襲來時，大人您不僅找到這塊木板爬了上來，還救了我。"
