  },
  AvgDialog_139657_Content_38 = {
    Text = "沙耶低著頭，微微喘著氣，你看不清她的表情。"
  },
  AvgDialog_139657_Content_39 = {
    Text = "這裡……就是我們出發的小屋，你看那邊。"
  },
  AvgDialog_139657_Content_4 = {
    Text = "你驀然驚醒。"
  },
  AvgDialog_139657_Content_40 = {
    Text = "你指向房間角落，早上被你從沙耶手腕扯下並拋擲在一旁的肉塊。"
  },
  AvgDialog_139657_Content_41 = {
    Text = "我們……繞回來了。"
  },
  AvgDialog_139657_Content_42 = {
    Text = "密境之中除了荒蕪，一無所有。"
  },
  AvgDialog_139657_Content_43 = {
    Text = "也算是恰好吧，可以……休息一會兒了。"
  },
  AvgDialog_139657_Content_44 = {
    Text = "沙耶若無其事地微笑，尾音中卻帶著一絲無法抑制的顫抖。"
  },
  AvgDialog_139657_Content_45 = {
    Text = "沙耶，你的身體……"
  },
  AvgDialog_139657_Content_46 = {
    Text = "我有點累呢……"
  },
  AvgDialog_139657_Content_47 = {
    Text = "就在你的面前，沙耶的身體像被抽去了所有支撐，直直地墜倒下去。"
  },
  AvgDialog_139657_Content_49 = {
    Text = "深夜，沙耶高燒不止。在她的指揮下，你用看不出是什麼的東西生起了火堆。"
  },
  AvgDialog_139657_Content_50 = {
    Text = "如果我知道你病得這麼重，就不會讓你跟著我走一天路……"
  },
  AvgDialog_139657_Content_51 = {
    Text = "沒關係，我覺得生病應該不是因為這種原因……\n比起這個……聊聊天好嗎？"
  },
  AvgDialog_139657_Content_52 = {
    Text = "沒問題，你想聊些什麼？"
  },
  AvgDialog_139657_Content_53 = {
    Text = "你早上的時候說，你和彌薩格想要對抗融蝕，守護其他人，也守護我。"
  },
  AvgDialog_139657_Content_54 = {
    Text = "這是真的嗎？"
  },
  AvgDialog_139657_Content_55 = {
    Text = "當然。在正式被授予銀鑰的那天，我就宣誓過了。"
  },
  AvgDialog_139657_Content_56 = {
    Text = "你的聲音比自己預想的更篤定。話說出口的瞬間，授鑰儀式的畫面在腦海中倏然浮現——"
  },
  AvgDialog_139657_Content_57 = {
    Text = "銀鑰沉甸甸地落入掌心時的涼意，眾人肅穆的注視，以及自己握緊鑰匙時心底湧起的那股滾燙的決意。"
  },
  AvgDialog_139657_Content_58 = {
    Text = "沙耶似乎沉默了一小會兒。火光將她小小的側影鍍上一層暖融融的橘色。"
  },
  AvgDialog_139657_Content_59 = {
    Text = "那麼，如果有一天，你失去了作為守密人的力量，成為了一個普通人。"
  },
  AvgDialog_139657_Content_6 = {
    Text = "沙耶倚著小屋的門扉，發出輕微的咳嗽聲。"
  },
  AvgDialog_139657_Content_60 = {
    Text = "如果無法再完成對抗融蝕的使命了……你會怎麼做？"
  },
  AvgDialog_139657_Content_61 = {
    Text = "那個啊，我已經想好了。"
  },
  AvgDialog_139657_Content_62 = {
    Text = "你往後仰了仰身子，雙手撐在身後的草地上，仰頭望向頭頂無垠的星空。"
  },
  AvgDialog_139657_Content_63 = {
    Text = "我會和我的愛人、我的朋友們一起，平平穩穩地過完普通的一生。"
  },
  AvgDialog_139657_Content_64 = {
    Text = "等到老了，頭髮白了，跑不動了，我們就一起圍坐在爐火邊，翻來覆去地懷念年輕時候幹過的那些糗事。"
  },
  AvgDialog_139657_Content_65 = {
    Text = "拉蒙娜肯定還是會糾正德克斯特勳爵念錯的每一位女士的名字；威廉還是那副不苟言笑的樣子，端著書假裝在看，其實耳朵早就豎起來了……"
  },
  AvgDialog_139657_Content_66 = {
    Text = "訶勒特老師照舊抱著她的伏特加，喝到盡興處非要拉著所有人唱歌。"
  },
  AvgDialog_139657_Content_67 = {
    Text = "你轉過頭，發現沙耶正安安靜靜地看著你。火光映在她的眼底，明明滅滅，像是盛了兩簇小小的星子。"
  },
  AvgDialog_139657_Content_70 = {
    Text = "沙耶的聲音啞了啞，她收回目光，黯淡的眼瞳凝視著陰暗角落的虛空。"
  },
  AvgDialog_139657_Content_71 = {
    Text = "如果你和他們分散了，你的身邊空無一人，那你要怎麼辦？"
  },
  AvgDialog_139657_Content_72 = {
    Text = "他們是離開了，還是一開始就不存在？"
  },
  AvgDialog_139657_Content_73 = {
    Text = "如果……是記憶中確實殘留著相遇、共處的時光……"
  },
  AvgDialog_139657_Content_74 = {
    Text = "但時間過去太久，記憶支離破碎，你也不知是真是假……"
  },
  AvgDialog_139657_Content_75 = {
    Text = "只要我還能記得，我就一定會去找他們。"
  },
  AvgDialog_139657_Content_76 = {
    Text = "無論天涯海角，無論有多少艱難險阻，我一定會找到他們。"
  },
  AvgDialog_139657_Content_77 = {
    Text = "你望向沙耶的眼神沒有一絲猶疑。"
  },
  AvgDialog_139657_Content_78 = {
    Text = "假如……我是說假如——找不到呢？"
  },
  AvgDialog_139657_Content_79 = {
    Text = "我也會一直尋找，走過每一條路，翻過每一座山，渡過每一片海。"
  },
  AvgDialog_139657_Content_8 = {
    Text = "湧動著黑泥的肉塊從門的縫隙中侵入小屋，纏上了沙耶的手腕。"
  },
  AvgDialog_139657_Content_80 = {
    Text = "直到在不斷尋找的旅程中，消耗完我這漫長的一生。"
  },
  AvgDialog_139657_Content_81 = {
    Text = "即使在合上眼的那個瞬間，我也依然是飽滿而充實的。"
  },
  AvgDialog_139657_Content_82 = {
    Text = "因為我這一生既有珍貴的記憶，也有無論如何都要前往的地方。"
  },
  AvgDialog_139657_Content_83 = {
    Text = "尋找本身，就已經是意義了。"
  },
  AvgDialog_139657_Content_84 = {
    Text = "話音落下，四周忽然安靜得只剩下蒲公英在微風中搖曳的沙沙聲。"
  },
  AvgDialog_139657_Content_86 = {
    Text = "沙耶合上了眼，她的面色蒼白如薄紙。你的心狠狠地揪緊了。"
  },
  AvgDialog_139657_Content_88 = {
    Text = "你焦急地湊近，卻發現沙耶的鼻息輕柔而平穩，胸口隨著呼吸緩緩起伏，像湖面上最細微的漣漪。"
  },
  AvgDialog_139657_Content_89 = {
    Text = "只是睡著了啊……"
  },
  AvgDialog_139657_Content_9 = {
    Text = "這些表象上的變化……反而沒那麼關鍵。"
  },
  AvgDialog_139657_Content_90 = {
    Text = "我也，有點，困了呢……"
  },
  AvgDialog_139657_Content_91 = {
    Text = "突如其來的安心感下，奔忙一天的疲憊和滿眼肉塊的視覺壓力終於佔據了你。"
  },
  AvgDialog_139657_Content_92 = {
    Text = "在終結到來之前，這一夜也靜悄悄地流逝了。"
  },
  AvgDialog_139658_Content_1 = {Text = "雨霽時"},
  AvgDialog_139658_Content_10 = {
    Text = "真好啊，能感覺到太陽。"
  },
  AvgDialog_139658_Content_11 = {
    Text = "沙耶笑著，伸出手觸摸陽光落進來的方向，像一株植物迎向光。"
  },
  AvgDialog_139658_Content_12 = {
    Text = "能扶我出去看看嗎？"
  },
  AvgDialog_139658_Content_13 = {
    Text = "你攙扶著沙耶在小屋旁倚著牆坐下。即使只是這一小段路，沙耶也難以掩飾地喘著氣。"
  },
  AvgDialog_139658_Content_14 = {
    Text = "沙耶，你的身體……"
  },
  AvgDialog_139658_Content_15 = {
    Text = "不必在意，我想是時間快到了。"
  },
  AvgDialog_139658_Content_16 = {
    Text = "你也能感覺到吧？阻礙我們鏈接的那堵壁障……正在消退。"
  },
  AvgDialog_139658_Content_17 = {
    Text = "再過一會兒，一定會完全崩塌。\n到那時……應該就能建立你所說的「鏈接」了吧。"
  },
  AvgDialog_139658_Content_19 = {
    Text = "鏈接之後，沙耶或許就會消失。那堵壁障是她保護自己的圍牆，才會因為她的虛弱而變得脆弱。"
  },
  AvgDialog_139658_Content_2 = {
    Text = "當你醒來的時候，光線已經變了。"
  },
  AvgDialog_139658_Content_20 = {
    Text = "請不必有所顧慮。這個時刻，能有你在身邊陪伴、交流，我非常高興哦。"
  },
  AvgDialog_139658_Content_21 = {
    Text = "沙耶瞇起眼睛，露出真誠而虛弱的笑意。你不忍直視，但還是努力將她的笑容印刻在記憶裡。"
  },
  AvgDialog_139658_Content_22 = {
    Text = "我會一直陪著你的。"
  },
  AvgDialog_139658_Content_23 = {
    Text = "好啦，別露出那副憂鬱的表情。讓我們繼續昨天的話題吧。"
  },
  AvgDialog_139658_Content_24 = {
    Text = "你說，即使無法對抗融蝕、即便身邊空無一人，你也還要繼續前進。"
  },
  AvgDialog_139658_Content_25 = {
    Text = "我很好奇，這是為什麼呢？"
  },
  AvgDialog_139658_Content_26 = {
    Text = "為什麼呢？雨後的陽光有些刺眼，讓你忍不住想要流淚。"
  },
  AvgDialog_139658_Content_27 = {
    Text = "你深吸一口氣。"
  },
  AvgDialog_139658_Content_28 = {
    Text = "因為我愛著拉蒙娜，愛著彌薩格大學的所有同伴。\n同時，我確信他們也愛著我。"
  },
  AvgDialog_139658_Content_29 = {
    Text = "可是你們相隔很遠很遠，不能觸碰彼此，不能確認彼此的心意。"
  },
  AvgDialog_139658_Content_3 = {
    Text = "潮濕的空氣裡有了一種洗過之後的乾淨氣味，門縫裡擠進來的不是風，而是一束安靜的光。"
  },
  AvgDialog_139658_Content_30 = {
    Text = "何況你的世界存在名為「融蝕」的異常，你怎麼能確定你思念的人沒有遺忘你的存在呢？"
  },
  AvgDialog_139658_Content_31 = {
    Text = "她的聲音帶著一股近乎夢囈的輕柔。"
  },
  AvgDialog_139658_Content_32 = {
    Text = "融蝕或許會抹去存在，但銀芯在潛意識的海洋中鏈接了我和拉蒙娜。"
  },
  AvgDialog_139658_Content_33 = {
    Text = "你望向遠方。雨後的天際線清晰得不可思議，雲層被風撕開了一道口子，金色的光柱從縫隙中傾瀉而下，落在遠處的山脊上。"
  },
  AvgDialog_139658_Content_34 = {
    Text = "我能感覺到她的存在，即使現在這一時刻也是一樣，即使我們被迫分散在不同世界也是一樣。"
  },
  AvgDialog_139658_Content_35 = {
    Text = "何況……"
  },
  AvgDialog_139658_Content_37 = {
    Text = "她微微偏過頭來。"
  },
  AvgDialog_139658_Content_38 = {
    Text = "真正的愛人不需要在身邊也能感知到彼此，也能確認彼此的愛。"
  },
  AvgDialog_139658_Content_39 = {
    Text = "哪怕世界末日輪迴不止，我也一定能找到拉蒙娜。她也一定會做出同樣的選擇。"
  },
  AvgDialog_139658_Content_4 = {
    Text = "……外面好安靜。"
  },
  AvgDialog_139658_Content_40 = {
    Text = "我有這種預感。我們在精神之海中相連的思念，永遠不會斷絕。"
  },
  AvgDialog_139658_Content_41 = {
    Text = "沙耶沉默了很久，雨後的風穿過小屋，拂過她幾乎沒有血色的面頰。"
  },
  AvgDialog_139658_Content_42 = {
    Text = "然後，她笑了。"
  },
  AvgDialog_139658_Content_43 = {
    Text = "真是，強烈而堅定的信任，真是，偉大的愛啊……"
  },
  AvgDialog_139658_Content_44 = {
    Text = "她說「愛」這個字的時候，聲音裡沒有羨慕，沒有哀傷，沒有遺憾。"
  },
  AvgDialog_139658_Content_45 = {
    Text = "只有溫柔。"
  },
  AvgDialog_139658_Content_46 = {
    Text = "像是一個在漫長冬夜裡獨自趕路的旅人，終於在地平線的盡頭望見了第一縷晨曦——她不一定能走到那裡，光只要存在，就已經足夠。"
  },
  AvgDialog_139658_Content_47 = {
    Text = "沙耶痴痴地笑著。"
  },
  AvgDialog_139658_Content_48 = {
    Text = "然後，她朝你伸出手來。"
  },
  AvgDialog_139658_Content_5 = {
    Text = "雨……停了嗎？"
  },
  AvgDialog_139658_Content_50 = {
    Text = "那隻手蒼白、纖細、微微顫抖著，她看不見你，可她的手卻準確無誤地伸向了你所在的方向——"
  },
  AvgDialog_139658_Content_51 = {
    Text = "像是某種比視覺更古老、比語言更深沉的東西，在引導著她。"
  },
  AvgDialog_139658_Content_53 = {
    Text = "就在你們的掌心相觸的那個瞬間——"
  },
  AvgDialog_139658_Content_54 = {
    Text = "眼眶一陣劇痛。"
  },
  AvgDialog_139658_Content_55 = {
    Text = "某種遠比那更尖銳、更灼烈的東西，像一道閃電劈開了你的顱骨，直直地貫穿了你意識的最深處。"
  },
  AvgDialog_139658_Content_56 = {
    Text = "視野劇烈地搖晃起來。"
  },
  AvgDialog_139658_Content_57 = {
    Text = "你看見了陽光下濕漉漉的蒲公英、沙耶蒼白而安詳的側臉、她乾裂的唇角彎起的那抹笑——"
  },
  AvgDialog_139658_Content_58 = {
    Text = "然後一切驟變成血肉的宇宙，天空是血紅的，大地是血紅的，就連眼前的沙耶也——"
  },
  AvgDialog_139658_Content_6 = {
    Text = "沙耶的眼睛是望向窗戶的，可是那目光沒有落點。"
  },
  AvgDialog_139658_Content_60 = {
    Text = "兩種光景在你的視野中交替閃現、重疊、融合，兩條本該平行的河流在某個不可能的交匯點猛然撞在了一起。"
  },
  AvgDialog_139658_Content_61 = {
    Text = "你和沙耶的鏈接，完成了。"
  },
  AvgDialog_139658_Content_7 = {
    Text = "陽光投進她的眼底，就像一顆石子投進水裡，卻沒有盪開任何漣漪。"
  },
  AvgDialog_139658_Content_9 = {
    Text = "你語調艱澀。"
  },
  AvgDialog_139659_Content_1 = {Text = "「愛」"},
  AvgDialog_139659_Content_11 = {
    Text = "經歷雨水的沖刷，無數蒲公英種子落在紅黑色的大地上，有些竟然已經開始抽芽生長。"
  },
  AvgDialog_139659_Content_12 = {
    Text = "一夜而生，一夜而誕……"
  },
  AvgDialog_139659_Content_13 = {
    Text = "看你的神情，是想起什麼了嗎？"
  },
  AvgDialog_139659_Content_14 = {
    Text = "嗯，我曾經在亞蘭的沙漠中，見過類似的景象。"
  },
  AvgDialog_139659_Content_15 = {
    Text = "那裡的土地受到「豐穰母樹」的祝福，種群的後裔落地而生，迎風而長。"
  },
  AvgDialog_139659_Content_16 = {
    Text = "那不是挺好的嗎？"
  },
  AvgDialog_139659_Content_17 = {
    Text = "……但是，聽上去，你好像覺得那並不太好。"
  },
  AvgDialog_139659_Content_18 = {
    Text = "作為置身事外之人，我不好發表評價。"
  },
  AvgDialog_139659_Content_19 = {
    Text = "只是，對很多人來說，生命的每個階段都是很重要的吧。"
  },
  AvgDialog_139659_Content_2 = {
    Text = "你和沙耶各自蜷縮在小屋的一角，一夜無話。"
  },
  AvgDialog_139659_Content_20 = {
    Text = "比如那個叫涅弗魯瑞的孩子……他從來沒有經歷過真正的童年，沒有享受過來自父母的關愛，就匆忙踏上了迎擊風暴之壁的戰場……"
  },
  AvgDialog_139659_Content_21 = {
    Text = "沙耶似懂非懂地點了點頭。"
  },
  AvgDialog_139659_Content_22 = {
    Text = "你的意思是，對人類來說，生命的長度也是很關鍵的，對吧？"
  },
  AvgDialog_139659_Content_23 = {
    Text = "不僅如此，生命中經歷的每一件事，遇見的每一個人，都會化為未來的記憶中的一部分。"
  },
  AvgDialog_139659_Content_24 = {
    Text = "這些記憶的積澱，構成了每個人自身。"
  },
  AvgDialog_139659_Content_25 = {
    Text = "甚至可以說，人類是記憶的載體。\n即使肉身消亡，記憶也會傳承下去，直到被所有人遺忘。"
  },
  AvgDialog_139659_Content_26 = {
    Text = "這樣啊……我明白了。"
  },
  AvgDialog_139659_Content_27 = {
    Text = "那麼，如果有一天我死去了，今天我和你在這裡的回憶，也會構成你的一部分嗎？"
  },
  AvgDialog_139659_Content_28 = {Text = "會的。"},
  AvgDialog_139659_Content_29 = {
    Text = "在沙耶虛弱的笑容裡，你堅定地點了點頭。"
  },
  AvgDialog_139659_Content_3 = {
    Text = "不知何時，你在疲憊的驅使下沉沉地睡去了。"
  },
  AvgDialog_139659_Content_30 = {
    Text = "這一天，又在對邊界的探索和徘徊中過去。"
  },
  AvgDialog_139659_Content_31 = {
    Text = "然而在蒲公英花田之外，只有一幅又一幅相似的荒蕪風景，被血肉覆蓋的看不出原型的大地。"
  },
  AvgDialog_139659_Content_32 = {
    Text = "儘管你強行壓抑，不安感還是逐漸從心底萌芽，一點一點攀上你的意識。"
  },
  AvgDialog_139659_Content_33 = {
    Text = "（如果什麼都找不到，那麼這處密境的核只能是……）"
  },
  AvgDialog_139659_Content_35 = {
    Text = "好好休息吧，我覺得有點累呢。"
  },
  AvgDialog_139659_Content_36 = {
    Text = "正好，我也想早點休息，這樣的話，明天才能去更遠的地方探索。"
  },
  AvgDialog_139659_Content_37 = {
    Text = "伴隨著這樣的交談，你們陷入了安睡。"
  },
  AvgDialog_139659_Content_39 = {
    Text = "你被什麼聲音喚醒了，只覺得渾身燥熱，彷彿置身於沙漠之中。"
  },
  AvgDialog_139659_Content_4 = {
    Text = "（好冷……希望明天能睡在溫暖的床鋪上……）"
  },
  AvgDialog_139659_Content_41 = {
    Text = "你感覺自己的頭昏昏沉沉的，不知道是因為眼前詭異的景象，還是飄散在空中迷離的煙霧。"
  },
  AvgDialog_139659_Content_42 = {
    Text = "或者是母樹聖河的影響。"
  },
  AvgDialog_139659_Content_43 = {
    Text = "真可惜啊，你在期待的人不是我嗎？"
  },
  AvgDialog_139659_Content_44 = {
    Text = "亞蘭的女王——泰旖絲掀簾而入，她毫無顧忌地湊近，薄若無物的輕紗緊貼你的小臂，發出直白的邀請。"
  },
  AvgDialog_139659_Content_45 = {
    Text = "來吧，接受亞蘭的血脈，成為我們的一員吧。"
  },
  AvgDialog_139659_Content_46 = {
    Text = "靠近我，擁抱我……給我你的血，你的種……"
  },
  AvgDialog_139659_Content_47 = {
    Text = "火光在她狂熱的瞳孔中躍動，暈紅的臉頰流露出病態的渴求。"
  },
  AvgDialog_139659_Content_48 = {
    Text = "只要一滴就好，只要我們的骨血交融，祂便會賜予我們渴望的未來……"
  },
  AvgDialog_139659_Content_49 = {
    Text = "讓我們……為族群誕下子嗣，同享永恆的……"
  },
  AvgDialog_139659_Content_5 = {
    Text = "朦朧中，你感覺有什麼東西攏住了你。"
  },
  AvgDialog_139659_Content_50 = {
    Text = "你竭力調用理智抵抗泰旖絲的蠱惑，當年喚醒你的鐘聲卻遲遲不來。"
  },
  AvgDialog_139659_Content_51 = {
    Text = "僵持之下，你突然聽見新的聲音鑽入你的耳朵。"
  },
  AvgDialog_139659_Content_52 = {
    Text = "為什麼，為什麼要拒絕呢？"
  },
  AvgDialog_139659_Content_53 = {
    Text = "少女不知何時，從營帳的一角鑽出。"
  },
  AvgDialog_139659_Content_54 = {
    Text = "與平時輕快的語調不同，似乎蘊含著某種特別的情感。"
  },
  AvgDialog_139659_Content_55 = {
    Text = "「繁衍」這件事，我覺得是好事，也是所有生命的目的……"
  },
  AvgDialog_139659_Content_56 = {
    Text = "那為什麼不接受呢？"
  },
  AvgDialog_139659_Content_57 = {
    Text = "為什麼，為什麼要拒絕呢？"
  },
  AvgDialog_139659_Content_58 = {
    Text = "因為這無關愛，這只是誘惑。"
  },
  AvgDialog_139659_Content_59 = {
    Text = "誘惑不是愛，使命不是愛，慾望也不是愛。"
  },
  AvgDialog_139659_Content_60 = {
    Text = "愛是——"
  },
  AvgDialog_139659_Content_61 = {
    Text = "愛是——"
  },
  AvgDialog_139659_Content_62 = {
    Text = "你昏迷了過去。"
  },
  AvgDialog_139659_Content_63 = {
    Text = "一切沉入漫長的黑暗之中。"
  },
  AvgDialog_139659_Content_7 = {
    Text = "你身上蓋著一層薄薄的毯子。"
  },
  AvgDialog_139659_Content_8 = {
    Text = "天已經晴了。"
  },
  AvgDialog_139660_Content_1 = {
    Text = "「記憶」"
  },
  AvgDialog_139660_Content_10 = {
    Text = "我確實不算普通人，我是來自彌薩格大學的調查員。"
  },
  AvgDialog_139660_Content_11 = {
    Text = "沙耶的眼神中寫滿了疑惑，顯然這些名詞對她而言都太過陌生。"
  },
  AvgDialog_139660_Content_12 = {
    Text = "如果展開來講的話，就太過漫長了。我現在有更重要的事情需要解決。"
  },
  AvgDialog_139660_Content_13 = {
    Text = "我的搭檔，拉蒙娜，我看到她被什麼東西吞噬了，她變成了……"
  },
  AvgDialog_139660_Content_14 = {
    Text = "你沒有說完。你沒辦法說完。"
  },
  AvgDialog_139660_Content_15 = {
    Text = "言語不過是乾癟的符號，無法傳達你在那個瞬間感受到的、從脊椎底部蔓延上來的恐懼。"
  },
  AvgDialog_139660_Content_16 = {
    Text = "對於永遠失去拉蒙娜的可能性的恐懼。"
  },
  AvgDialog_139660_Content_17 = {
    Text = "她是我無可替代的人。"
  },
  AvgDialog_139660_Content_18 = {
    Text = "沙耶的目光短暫地失焦了。"
  },
  AvgDialog_139660_Content_19 = {
    Text = "無可替代的人……原來如此。"
  },
  AvgDialog_139660_Content_2 = {
    Text = "還沒等你整理好滿腹的疑惑，少女率先開口了。"
  },
  AvgDialog_139660_Content_20 = {
    Text = "我好像也有過……這樣的人。"
  },
  AvgDialog_139660_Content_21 = {
    Text = "她低下頭，皺著眉喃喃自語。"
  },
  AvgDialog_139660_Content_22 = {
    Text = "有一個人。非常重要的人。那個人的臉……我應該記得。我一定記得。可是現在我去想他的時候，能看到的只有——"
  },
  AvgDialog_139660_Content_23 = {
    Text = "——只有輪廓。像隔著一層毛玻璃。知道他在那裡，知道他很重要，但所有細節都被……塗抹掉了。"
  },
  AvgDialog_139660_Content_24 = {
    Text = "不只是他。其他的事情也一樣。我知道我有必須去做的事——很重要的事。"
  },
  AvgDialog_139660_Content_25 = {
    Text = "但是每一段記憶都在打架。這一段說他很溫柔，下一段又說我在很黑的地方待了很久。"
  },
  AvgDialog_139660_Content_26 = {
    Text = "這一段說我在等什麼人來接我，下一段又說我需要做一件……會讓人害怕的事。"
  },
  AvgDialog_139660_Content_27 = {
    Text = "每一段都感覺是真的。可它們放在一起就互相矛盾。"
  },
  AvgDialog_139660_Content_28 = {
    Text = "你見過這種狀態。"
  },
  AvgDialog_139660_Content_29 = {
    Text = "這是融蝕現象報告書中記載的症狀，並非只發生在她身上。\n意識混濁、記憶碎片化、自我認知崩潰。"
  },
  AvgDialog_139660_Content_3 = {
    Text = "我是……嗯，叫我「沙耶」吧。\n話說回來，你知道這裡是哪裡嗎？"
  },
  AvgDialog_139660_Content_30 = {
    Text = "我不知道哪一段才是真正發生過的，我不知道哪些是屬於我自己的真實的記憶……"
  },
  AvgDialog_139660_Content_31 = {
    Text = "沙耶的手指蜷縮著，似乎想要握住什麼已經不存在的東西。"
  },
  AvgDialog_139660_Content_32 = {
    Text = "隨著她的動搖，你感覺周圍的環境開始變化。"
  },
  AvgDialog_139660_Content_34 = {
    Text = "你看向蒲公英田外圍。黑液覆蓋的肉膜正一寸寸碾過來，蒲公英花田的邊界顯得越來越脆弱。"
  },
  AvgDialog_139660_Content_4 = {
    Text = "為什麼會在這種地方呢……\n嗯——總覺得好多事情都想不起來。"
  },
  AvgDialog_139660_Content_5 = {
    Text = "……你，好像不是普通人？\n擁有什麼特別的力量……？"
  },
  AvgDialog_139660_Content_6 = {
    Text = "你沒有立刻回答。名為沙耶的少女鬆開手，退後半步，瞇起眼睛打量著你。"
  },
  AvgDialog_139660_Content_7 = {
    Text = "看到我，你沒有任何感覺嗎？為什麼要來這裡？"
  },
  AvgDialog_139660_Content_8 = {
    Text = "慢點，一個一個問題來。"
  },
  AvgDialog_139660_Content_9 = {
    Text = "根據我的經驗，這裡大概率是一座密境吧。"
  },
  AvgDialog_139661_Content_1 = {
    Text = "心象風景"
  },
  AvgDialog_139661_Content_10 = {
    Text = "一名美麗的少女，和一個青年。"
  },
  AvgDialog_139661_Content_11 = {
    Text = "他們手牽手，親暱地行走在風沙呼嘯的荒原上。"
  },
  AvgDialog_139661_Content_13 = {
    Text = "她嬉笑著，張開手擁抱風。"
  },
  AvgDialog_139661_Content_14 = {
    Text = "一旁的青年也隨之側身，聆聽她的每一句巧笑。"
  },
  AvgDialog_139661_Content_15 = {
    Text = "天空晴朗，卻帶著一絲憂傷。"
  },
  AvgDialog_139661_Content_16 = {
    Text = "但從兩個人相伴的身影中，你體味出一絲油然而生的幸福感。"
  },
  AvgDialog_139661_Content_17 = {
    Text = "即便周遭空無一人，即便得不到任何人的體諒與祝福，那份愛也——"
  },
  AvgDialog_139661_Content_18 = {
    Text = "然後夢境戛然而止，風沙捲走了一切。"
  },
  AvgDialog_139661_Content_19 = {
    Text = "世界落入虛空的黑暗。"
  },
  AvgDialog_139661_Content_2 = {
    Text = "天地是由沙構成的。"
  },
  AvgDialog_139661_Content_20 = {
    Text = "——那時，有一位歌姬，正在星辰之間穿行。"
  },
  AvgDialog_139661_Content_21 = {
    Text = "在一片荒蕪的宇宙中，她拾起了一枚銀芯。"
  },
  AvgDialog_139661_Content_22 = {
    Text = "在她觸碰到它的瞬間，「我」便甦醒了過來。"
  },
  AvgDialog_139661_Content_23 = {
    Text = "「我」失去了記憶，只知道必須要去尋找那個「無可替代的人」。"
  },
  AvgDialog_139661_Content_24 = {
    Text = "「我」詢問了那位歌姬，能不能一起同行，但是，這個請求被拒絕了。"
  },
  AvgDialog_139661_Content_25 = {
    Text = "我要去尋找我深愛的人——我的姐姐。"
  },
  AvgDialog_139661_Content_26 = {
    Text = "歌姬這麼說了。"
  },
  AvgDialog_139661_Content_27 = {
    Text = "希望沙耶你也能找回所愛。我衷心期盼著你能擁有那樣的結局。"
  },
  AvgDialog_139661_Content_28 = {
    Text = "留下這樣一句話，歌姬離開了。"
  },
  AvgDialog_139661_Content_29 = {
    Text = "從那之後，失去了過去記憶，也失去了那位歌姬的我。"
  },
  AvgDialog_139661_Content_3 = {
    Text = "在永世連綿吹過沙漠的風中，你迷茫地俯瞰。"
  },
  AvgDialog_139661_Content_30 = {
    Text = "懷揣著她的祝願，獨自一人在這個世界中不斷行走著。"
  },
  AvgDialog_139661_Content_31 = {
    Text = "為了找到曾經無可替代之人，為了找回過去的記憶……"
  },
  AvgDialog_139661_Content_32 = {
    Text = "一直相信著，所追尋之物，一定就在前方。"
  },
  AvgDialog_139661_Content_33 = {
    Text = "……然後，遇見了你。"
  },
  AvgDialog_139661_Content_4 = {
    Text = "這裡是……"
  },
  AvgDialog_139661_Content_5 = {
    Text = "沒有融蝕的淤泥，沒有遍野的肉塊。"
  },
  AvgDialog_139661_Content_6 = {
    Text = "這裡的風景孤獨、純淨而美麗。"
  },
  AvgDialog_139661_Content_7 = {
    Text = "這裡是我的心象風景哦。"
  },
  AvgDialog_139661_Content_8 = {
    Text = "是沙耶的、不應遺忘、無可替代的存在。"
  },
  AvgDialog_139661_Content_9 = {
    Text = "風沙滾滾而去，在沙漠的角落，現出兩個身影。"
  },
  AvgDialog_139662_Content_10 = {
    Text = "我將作為你的助手，陪你抵達這條道路的終點……<Yellow:願銀鑰指引前路。>"
  },
  AvgDialog_139662_Content_11 = {
    Text = "還好嗎，%player%？\n從剛才開始，你的臉色就不太對勁。需要我送你去醫務室嗎？"
  },
  AvgDialog_139662_Content_13 = {
    Text = "你的呢喃聲彷彿卡在了喉嚨裡，你無法呼喚她的名字，你熟悉的名字。"
  },
  AvgDialog_139662_Content_14 = {
    Text = "<Shake:<Red:唔ｦ,ﾋ保5險ｸk起Q見...ﾃ還爨是ｨ和A我ﾑ鑷鏈9ｴ接吧ﾅ。>>"
  },
  AvgDialog_139662_Content_15 = {
    Text = "<Shake:<Red:稍ｷ微z(提ﾉ前ｲ了驫ｲ一8點ﾃP點ｬ,不ﾗ過ｸ沒ﾎ関靇係ﾑ,不w是ｦ嗎J?>>"
  },
  AvgDialog_139662_Content_16 = {
    Text = "<Red:不對不對不對不對。哪裡都不對。>"
  },
  AvgDialog_139662_Content_17 = {
    Text = "<Shake:<Red:ﾒ從ｩﾇ龥年ｯ前7開ﾘ始L,ﾝ我就Q在ｱ齉其月ﾏ待r今ｮ天了麤。>>"
  },
  AvgDialog_139662_Content_18 = {
    Text = "<Shake:不，那不是拉蒙娜，拉蒙娜不會是醜惡扭曲的肉塊，不會發出這樣令人作嘔的低鳴，不會渾身湧出漆黑的融蝕漿……>"
  },
  AvgDialog_139662_Content_19 = {
    Text = "<Red:不會用那雙漆黑空洞的眼睛，死死地盯著我——>"
  },
  AvgDialog_139662_Content_21 = {
    Text = "我這是……做了一個夢？"
  },
  AvgDialog_139662_Content_22 = {
    Text = "你一身冷汗地驚醒。"
  },
  AvgDialog_139662_Content_23 = {
    Text = "好奇怪的夢。夢醒了以後還殘留在視野裡。"
  },
  AvgDialog_139662_Content_24 = {
    Text = "視野裡的東西……是……"
  },
  AvgDialog_139662_Content_26 = {
    Text = "<Shake:<Red:肉塊，大塊大塊堆疊覆蓋的肉塊。>>"
  },
  AvgDialog_139662_Content_27 = {
    Text = "<Red:深紅色的蠕動臟器鋪滿牆壁，纏滿梁柱，爬滿窗戶。\n而在肉塊與肉塊的縫隙之間——>"
  },
  AvgDialog_139662_Content_28 = {
    Text = "黑色的液體正在滲出來。"
  },
  AvgDialog_139662_Content_29 = {Text = "融蝕。"},
  AvgDialog_139662_Content_3 = {
    Text = "疼痛，劇烈的疼痛。暗紅色扎入你的視網膜。"
  },
  AvgDialog_139662_Content_30 = {
    Text = "你見過太多融蝕。但沒有這樣的。兩種完全不同的疾病同時發作在一具軀體上。"
  },
  AvgDialog_139662_Content_32 = {
    Text = "畫面再次閃回。漆黑空洞的眼眶。扭曲膨脹的輪廓。她的手指在你掌心裡變成<Shake:不規則的肉芽>——"
  },
  AvgDialog_139662_Content_34 = {
    Text = "她還在——她一定還在某個地方——"
  },
  AvgDialog_139662_Content_35 = {
    Text = "腦內響起一聲極輕的震顫。"
  },
  AvgDialog_139662_Content_36 = {
    Text = "你下意識地去辨認來源——不是拉蒙娜。拉蒙娜的波紋你閉著眼都能認出來，她的精神紋路像一片舒緩的湖面。"
  },
  AvgDialog_139662_Content_37 = {
    Text = "向東走……"
  },
  AvgDialog_139662_Content_38 = {Text = "誰？"},
  AvgDialog_139662_Content_39 = {
    Text = "沒有回應。"
  },
  AvgDialog_139662_Content_4 = {
    Text = "頭好痛——"
  },
  AvgDialog_139662_Content_40 = {
    Text = "在任何其他線索出現之前，你只能依循著這個聲音前進。"
  },
  AvgDialog_139662_Content_41 = {
    Text = "跨過發出鐵鏽味和腐敗味的小河，跨過暗紅色筋絡寄生的肉膜般的大地。"
  },
  AvgDialog_139662_Content_42 = {
    Text = "你的呼吸變得困難，神經也因為詭異色彩的侵蝕而突突跳動。"
  },
  AvgDialog_139662_Content_43 = {
    Text = "有誰能，帶我離開這個夢……"
  },
  AvgDialog_139662_Content_44 = {
    Text = "沒錯，這一定是夢，即使夢中的觸感是如此真實，但你必須堅信這是一場夢境……"
  },
  AvgDialog_139662_Content_45 = {
    Text = "一朵柔軟的白色絨絮飄上了你的鼻尖。"
  },
  AvgDialog_139662_Content_47 = {
    Text = "你踏上了一條邊界，一條清晰可見的、分割兩個世界的邊界。"
  },
  AvgDialog_139662_Content_48 = {
    Text = "邊界之外，是令人作嘔的血肉和湧動的融蝕漿。"
  },
  AvgDialog_139662_Content_49 = {
    Text = "邊界之內，是一片小小的蒲公英花田。花田中央，坐落著木製的小屋。"
  },
  AvgDialog_139662_Content_5 = {
    Text = "暗光閃爍，嗡鳴聲在耳膜迴盪，世界是不足以相信的，眼前所見的一切都只是虛像。"
  },
  AvgDialog_139662_Content_50 = {
    Text = "蒲公英叢裡有什麼動了一下。"
  },
  AvgDialog_139662_Content_51 = {
    Text = "你的目光循著那個動靜看過去。白色的絨球被輕輕撥開，露出一小片素白色的衣角。"
  },
  AvgDialog_139662_Content_52 = {
    Text = "然後她站了起來。"
  },
  AvgDialog_139662_Content_53 = {
    Text = "一位像蒲公英一樣的少女。"
  },
  AvgDialog_139662_Content_54 = {
    Text = "她偏了偏頭，似乎在觀察你的表情。"
  },
  AvgDialog_139662_Content_55 = {
    Text = "我的樣子，不可怕嗎？"
  },
  AvgDialog_139662_Content_56 = {
    Text = "真可笑。這一路走來，她是你見到的唯一正常的人類，唯一不可怕的存在。"
  },
  AvgDialog_139662_Content_57 = {
    Text = "那麼，要來握一下手嗎？"
  },
  AvgDialog_139662_Content_58 = {
    Text = "誒，為什麼？"
  },
  AvgDialog_139662_Content_59 = {
    Text = "唔……總覺得現在就應該這麼做。"
  },
  AvgDialog_139662_Content_6 = {
    Text = "醒來，快點醒來……"
  },
  AvgDialog_139662_Content_60 = {
    Text = "至於為什麼，有點想不起來了。"
  },
  AvgDialog_139662_Content_62 = {
    Text = "少女側側頭，仿佛饒有興趣一樣微笑了起來。"
  },
  AvgDialog_139662_Content_63 = {
    Text = "你好像也很想碰碰我的樣子。"
  },
  AvgDialog_139662_Content_64 = {
    Text = "你想啊，你當然想。"
  },
  AvgDialog_139662_Content_65 = {
    Text = "這一路而來的漆黑、腥臭、惹人生厭的感官衝擊之後，你怎麼會不想觸碰你接觸到的第一個活生生的人呢？"
  },
  AvgDialog_139662_Content_66 = {
    Text = "你伸出手去，觸碰到她那纖細柔軟的手指。"
  },
  AvgDialog_139662_Content_67 = {
    Text = "不可思議的感覺……"
  },
  AvgDialog_139662_Content_68 = {
    Text = "是的，你也感受到了，隨著觸碰傳來的，除了人類的體溫，還有一絲微弱的電流接通般的感覺。"
  },
  AvgDialog_139662_Content_69 = {
    Text = "那是銀芯的共振。"
  },
  AvgDialog_139662_Content_7 = {
    Text = "歡迎你加入彌薩格大學，%player%。"
  },
  AvgDialog_139662_Content_8 = {
    Text = "或者說……歡迎你，正式跨入世界的裡側。"
  },
  AvgDialog_139662_Content_9 = {
    Text = "（我這是……回來了？）"
  },
  AvgDialog_139663_Content_1 = {
    Text = "這些怪物是……"
  },
  AvgDialog_139663_Content_10 = {
    Text = "這真是一個有點難回答的問題。儘管同為彌薩格的調查員，但拉蒙娜不具備你身為守秘人的特殊性。"
  },
  AvgDialog_139663_Content_11 = {
    Text = "既然身為喚醒體，或許我可以和你建立鏈接。通過夢的共鳴，你可以知曉拉蒙娜的模樣。"
  },
  AvgDialog_139663_Content_12 = {
    Text = "以她為引線，或許也能挖掘出你的記憶。"
  },
  AvgDialog_139663_Content_13 = {
    Text = "你再次握住沙耶的手，嘗試著在腦海中回憶拉蒙娜的音容笑貌，希望那微不可察的鏈接能夠傳遞至沙耶的腦海。"
  },
  AvgDialog_139663_Content_14 = {
    Text = "啪嚓一聲，鏈接中斷了。"
  },
  AvgDialog_139663_Content_15 = {
    Text = "好像有什麼無形的牆壁阻攔了我們的鏈接……"
  },
  AvgDialog_139663_Content_16 = {
    Text = "或許和我要做的事情有關。有一種預感在提醒我，那是一種不能告訴所有人的禁忌之事。"
  },
  AvgDialog_139663_Content_17 = {
    Text = "轟隆一聲，驚雷在天際炸響。"
  },
  AvgDialog_139663_Content_18 = {
    Text = "要下暴雨了。我們先去小屋內休息吧。"
  },
  AvgDialog_139663_Content_19 = {
    Text = "小屋木板的縫隙中，不時有黑色的黏液逆著重力懸浮而起。"
  },
  AvgDialog_139663_Content_2 = {
    Text = "我也不知道。不過，我有一種預感，答案就藏在我的記憶之中。"
  },
  AvgDialog_139663_Content_20 = {
    Text = "沙耶蜷縮在小屋的一角，下半臉埋在手臂裡，低聲詢問你。"
  },
  AvgDialog_139663_Content_21 = {
    Text = "這就是你說的“融蝕”，對嗎？"
  },
  AvgDialog_139663_Content_22 = {
    Text = "你點點頭以示肯定。"
  },
  AvgDialog_139663_Content_23 = {
    Text = "就是它讓我失去了記憶嗎？"
  },
  AvgDialog_139663_Content_24 = {
    Text = "不光是你，許許多多人都因為融蝕失去了重要的記憶。"
  },
  AvgDialog_139663_Content_25 = {
    Text = "有些人遺忘了自己親人的容貌，一直苦苦地尋找，甚至因此傷害了她思念的人。"
  },
  AvgDialog_139663_Content_26 = {
    Text = "有些人連自己誕生的城市都遺忘了，孤獨地徘徊在大洋之上，尋找著永無歸途的過去。"
  },
  AvgDialog_139663_Content_27 = {
    Text = "……失去重要的回憶，一定很痛苦吧。"
  },
  AvgDialog_139663_Content_28 = {
    Text = "沙耶望向小屋外連綿的雨絲，彷彿雨水能夠洗去黑色的泥濘與污濁。"
  },
  AvgDialog_139663_Content_29 = {
    Text = "不知道我的記憶裡，又有什麼重要的存在呢？"
  },
  AvgDialog_139663_Content_3 = {
    Text = "我會想辦法帶你離開密境，找尋你的記憶。"
  },
  AvgDialog_139663_Content_30 = {
    Text = "沙耶臉上流露出哀傷的神色。"
  },
  AvgDialog_139663_Content_31 = {
    Text = "你沒有接話。"
  },
  AvgDialog_139663_Content_32 = {
    Text = "窗外的雨，仍在淅淅瀝瀝地落下。"
  },
  AvgDialog_139663_Content_5 = {
    Text = "你想先找到那個叫拉蒙娜的人，對吧？"
  },
  AvgDialog_139663_Content_6 = {
    Text = "說實話，我隱約記得，我曾經碰見過某個人，然後……"
  },
  AvgDialog_139663_Content_7 = {
    Text = "沙耶眼神飄忽，話的後半截被嚥了回去。"
  },
  AvgDialog_139663_Content_8 = {
    Text = "總之，你說的那個拉蒙娜，她和你一樣特殊嗎？"
  },
  AvgDialog_139663_Content_9 = {
    Text = "如果她是普通人的話，恐怕無法和我交流。"
  },
  AvgDialog_141373_Content_1 = {
    Text = "這不是你第一次來到厄波揚斯，但沒有哪一次，這些無面的生靈和今天一樣躁動。"
  },
  AvgDialog_141373_Content_10 = {
    Text = "等等，你是……為什麼會在這裡來著？"
  },
  AvgDialog_141373_Content_11 = {
    Text = "尖銳的白噪音吞沒意識，古老且無形的潮汐迫使你昏沉地抬起頭，看向唯一能辨識的東西。"
  },
  AvgDialog_141373_Content_12 = {
    Text = "沒錯，那些都不重要，你是誰、你要做什麼、你來到這裡的原因。"
  },
  AvgDialog_141373_Content_13 = {
    Text = "低沉的嗓音將海水聲驅散，年長者居高臨下地將圍獵圈縮窄。"
  },
  AvgDialog_141373_Content_14 = {
    Text = "你很安全，歡迎回來。"
  },
  AvgDialog_141373_Content_15 = {
    Text = "哦……對，厄波揚斯，我回到了厄波揚斯。"
  },
  AvgDialog_141373_Content_16 = {
    Text = "你喃喃地複述著，不知不覺嘴角上揚，一切接下來的動作都顯得理所當然。"
  },
  AvgDialog_141373_Content_17 = {
    Text = "好吧，我承認這有些違規，但不用擔心，我會讓你回到彌薩格的。"
  },
  AvgDialog_141373_Content_18 = {
    Text = "深淵已然把你包裹其中，你脆弱的智識在一次次的顛沛中完全無法理解對方所陳述的一切。"
  },
  AvgDialog_141373_Content_19 = {Text = "什麼？"},
  AvgDialog_141373_Content_2 = {
    Text = "餵、餵！停下，我不是敵……"
  },
  AvgDialog_141373_Content_20 = {
    Text = "沙啞的、短促的笑聲。"
  },
  AvgDialog_141373_Content_21 = {
    Text = "只是不是現在。"
  },
  AvgDialog_141373_Content_22 = {
    Text = "濡濕，混亂，擁擠，它們把你充盈地填滿，繼而又連綿起伏地讓你深陷，你失去了所有支配權。"
  },
  AvgDialog_141373_Content_23 = {
    Text = "耳邊只剩下夾雜著喘息的私語。"
  },
  AvgDialog_141373_Content_24 = {
    Text = "現在，你屬於這裡，屬於我，屬於厄波揚斯。"
  },
  AvgDialog_141373_Content_25 = {
    Text = "你聽不明白，你只是在快樂裡繼續順應那古老的海水。"
  },
  AvgDialog_141373_Content_26 = {
    Text = "祂沒有要停歇的跡象。"
  },
  AvgDialog_141373_Content_3 = {Text = "*獵哨聲"},
  AvgDialog_141373_Content_4 = {
    Text = "攻擊停止了，然而，黑暗也突如其來地將你席捲。幾乎是一瞬間，靜滯的沉悶把你拋入了某種難言的淵流。"
  },
  AvgDialog_141373_Content_7 = {
    Text = "彷彿要確認什麼，無視你因為瞬間的應激而炸出的寒慄，這名此地的領主用不容置疑的姿態撫過你的眉骨、眼尾、直到脖側。"
  },
  AvgDialog_141373_Content_8 = {
    Text = "在這種時候造訪厄波揚斯可不是個好主意，%player%。"
  },
  AvgDialog_142850_Content_1 = {Text = "螻蟻"},
  AvgDialog_142850_Content_10 = {
    Text = "瓦羅……你、你放棄吧！我們有這麼多的人，你不可能活著離開這座森林！"
  },
  AvgDialog_142850_Content_100 = {
    Text = "那是他無法反抗的速度與力量。瓦羅抬起疑惑的雙眼，不解地望向蘿坦。"
  },
  AvgDialog_142850_Content_101 = {
    Text = "你……答應過……"
  },
  AvgDialog_142850_Content_102 = {
    Text = "我答應過讓你加入我的隊伍。可我沒說，你會活著。"
  },
  AvgDialog_142850_Content_103 = {
    Text = "弱小不是你的錯。但你不夠純粹，戰士。"
  },
  AvgDialog_142850_Content_104 = {
    Text = "蘿坦從瓦羅的手上拿走那兩塊骨印，隨意將那個迷茫的屍體推倒，和那十二名騎士的屍體堆在一起，如同一堆無人問津的垃圾。"
  },
  AvgDialog_142850_Content_105 = {
    Text = "她瞟了一眼灌木叢，拿起巨劍，準備劈向多出來的那塊骨印……"
  },
  AvgDialog_142850_Content_107 = {
    Text = "蘿坦的劍停在半空，漠然地看著從灌木叢裡爬出來的你。"
  },
  AvgDialog_142850_Content_108 = {
    Text = "我對太弱的對手沒有興趣。"
  },
  AvgDialog_142850_Content_109 = {
    Text = "騎士團的小侍從，如果我是你，我會在對方沒有改變主意以前逃走，越快越好。"
  },
  AvgDialog_142850_Content_11 = {
    Text = "把你的骨印交出來，我們保證、保證你可以安全地離開！"
  },
  AvgDialog_142850_Content_110 = {
    Text = "埃利安老爺讓騎士團為他帶回王冠，要是……要是他發現我逃走，我全家都活不了……"
  },
  AvgDialog_142850_Content_111 = {
    Text = "你鼓起所有的勇氣，向蘿坦的方向邁了一步。"
  },
  AvgDialog_142850_Content_112 = {
    Text = "您還有一張骨印……求您，讓我也去星天之鯨的鬥獸場，好嗎？只需要到那裡，我的任務就完成了……您這麼強，我不會對您有任何威脅……"
  },
  AvgDialog_142850_Content_114 = {
    Text = "蘿坦挑了挑眉毛，嘲諷地望向你。"
  },
  AvgDialog_142850_Content_115 = {
    Text = "你的力量甚至比不上那些被瓦羅殺死的廢物。走進那座鬥獸場的第一秒，你會像一隻蟲子一樣死掉。"
  },
  AvgDialog_142850_Content_116 = {
    Text = "現在離開，你還有機會活。"
  },
  AvgDialog_142850_Content_117 = {
    Text = "你望著滿地的屍體，望著面前這個讓你從內心深處感到恐懼的身影，艱難地嚥了口唾沫。"
  },
  AvgDialog_142850_Content_118 = {
    Text = "你知道，勝利從一開始就與你無關。你很想離開眼前這個魔鬼，離得越遠越好。"
  },
  AvgDialog_142850_Content_119 = {
    Text = "你很想忘掉被活活獻祭給星天之鯨的母親，忘掉那些被關在馬圈裡的兄弟姐妹，好好活下去。"
  },
  AvgDialog_142850_Content_12 = {
    Text = "他說的沒錯，瓦羅！就算你是六國裡最強大的傭兵，陷入我們十三個人的合圍，也討不到什麼便宜。"
  },
  AvgDialog_142850_Content_120 = {
    Text = "可沒有辦法，你忘不掉。就像參與這場注定會成為炮灰的角逐一樣，你從來就沒有選擇的權利。"
  },
  AvgDialog_142850_Content_121 = {
    Text = "我是隊裡的向導，知道去鬥獸場的路。我做侍從很多很多年了，我懂得怎樣服侍一位戰士！我很有用，您會需要我的……"
  },
  AvgDialog_142850_Content_122 = {
    Text = "你深吸一口氣，上前撿起那塊骨印，用破布為蘿坦擦拭鎧甲上的污痕，就像你曾經為騎士們做的那樣。"
  },
  AvgDialog_142850_Content_123 = {
    Text = "請走這邊，這位……這位……呃？"
  },
  AvgDialog_142850_Content_124 = {
    Text = "你躬身站在她的面前，她平靜的呼吸壓得你不敢抬起頭，只能緊緊盯著她腳下的地面。你感覺到，她利刃般的目光在你身上停留了數秒。"
  },
  AvgDialog_142850_Content_125 = {
    Text = "遇到危險，不要指望我會幫你。"
  },
  AvgDialog_142850_Content_126 = {
    Text = "不用後綴。你可以叫我蘿坦。"
  },
  AvgDialog_142850_Content_127 = {
    Text = "蘿坦收起巨劍，朝著你指向的方向走去。"
  },
  AvgDialog_142850_Content_128 = {
    Text = "血已經完全滲入了地面。暗紅色的天穹深處，一個巨大的、緩慢移動的陰影若隱若現。"
  },
  AvgDialog_142850_Content_129 = {
    Text = "你打了個寒顫，趕緊追上了蘿坦的腳步。"
  },
  AvgDialog_142850_Content_13 = {
    Text = "我們可以合作，不是嗎？"
  },
  AvgDialog_142850_Content_130 = {
    Text = "是……蘿坦大人！"
  },
  AvgDialog_142850_Content_15 = {
    Text = "星天之鯨只會選出一個人成為它的代行者，這件事靠一個人是做不到的！"
  },
  AvgDialog_142850_Content_16 = {
    Text = "只需要放下骨印，我們保證你安全地離開這裡，並且得到你能得到的一切……"
  },
  AvgDialog_142850_Content_17 = {Text = "是嗎？"},
  AvgDialog_142850_Content_18 = {
    Text = "我知道，瓦羅，你從荒島的獸群中存活下來，在鏡子面前殺死了自己最深愛的人，可能是你的父母、孩子、或者別的什麼東西。"
  },
  AvgDialog_142850_Content_19 = {
    Text = "你在這座原始森林裡活了半個月。你肯定不願意就這樣回去……"
  },
  AvgDialog_142850_Content_2 = {
    Text = "樹葉從枝頭飄落，劃過暗紅色的天空，落入地上的血泊，驚起一道微弱的漣漪。"
  },
  AvgDialog_142850_Content_20 = {
    Text = "可你想想，想想前面等待著你的是什麼！"
  },
  AvgDialog_142850_Content_21 = {
    Text = "你要衝出我們的包圍，躲避一路上的危險，找到星天之鯨的鬥獸場，在那裡和這個世界上最危險的人死鬥。"
  },
  AvgDialog_142850_Content_22 = {
    Text = "就算那個骨印能把你帶到鬥獸場，你能確定，你會成為最後活下來的那個人嗎？"
  },
  AvgDialog_142850_Content_23 = {
    Text = "只要你放棄，埃利安老爺上位之後，你就能成為開國的功臣……好好想想，瓦羅！"
  },
  AvgDialog_142850_Content_24 = {
    Text = "你的提議很動人。不過可惜，只有廢物才需要抱團取暖。你根本不明白什麼叫強者。"
  },
  AvgDialog_142850_Content_25 = {
    Text = "不用廢話了，一起上吧，騎士團的渣滓們。"
  },
  AvgDialog_142850_Content_27 = {
    Text = "瓦羅！你會為你的不尊重付出代價！"
  },
  AvgDialog_142850_Content_28 = {
    Text = "騎士團！衝鋒！！！"
  },
  AvgDialog_142850_Content_3 = {
    Text = "古老的森林瀰漫著一股揮之不去的腥甜味，用鮮血滋養土地的身體們躺在殷紅的地衣上，瞪著不甘的雙眼，早已沒了聲息。"
  },
  AvgDialog_142850_Content_30 = {
    Text = "鎧甲的洪流山呼海嘯般湧向中央孤立的身影。十餘人的衝鋒踩碎了苔蘚與枯骨，腳下的大地為之顫動。"
  },
  AvgDialog_142850_Content_31 = {
    Text = "猛烈的金屬撞擊聲在密林中炸響，驚起黑壓壓的鳥群，如同一片從樹冠上剝落的黑色碎片。"
  },
  AvgDialog_142850_Content_32 = {
    Text = "藏身處的枝葉顫動。你蜷縮在灌木叢後，透過藤蔓間的縫隙，屏住呼吸注視著這場屠殺。"
  },
  AvgDialog_142850_Content_34 = {
    Text = "彎刀斬碎刀劍，擊穿鎧甲下脆弱的血肉，從甲片的縫隙間斬斷四肢與頭顱。每一刀都精準、兇殘，不帶一絲多餘的動作。"
  },
  AvgDialog_142850_Content_35 = {
    Text = "力量、速度、技巧……在這位戰士面前，精銳的騎士團如同待宰的羔羊般一一倒下。"
  },
  AvgDialog_142850_Content_37 = {
    Text = "這……這個人……"
  },
  AvgDialog_142850_Content_38 = {
    Text = "衝鋒與喊殺聲很快平息。瓦羅在死去騎士的身上扯下一塊乾淨的布，擦去了彎刀上的血跡。"
  },
  AvgDialog_142850_Content_39 = {
    Text = "他審視著一塵不染的刀身，滿意地點了點頭。隨後，他從為首的騎士屍體上翻出了那塊通往鬥獸場的骨印。"
  },
  AvgDialog_142850_Content_4 = {
    Text = "呼……冷靜……應該沒有人發現我……"
  },
  AvgDialog_142850_Content_42 = {
    Text = "他四處張望，沒有再找到第十三具屍體。"
  },
  AvgDialog_142850_Content_43 = {
    Text = "不好！他發現我了……我得趁早……"
  },
  AvgDialog_142850_Content_45 = {
    Text = "一截枯木不合時宜地出現在你後退的路線上。瓦羅猛地轉過身，望向你藏身的灌木叢。"
  },
  AvgDialog_142850_Content_47 = {
    Text = "我說怎麼感覺少宰一個，原來還有一個躲在這裡。"
  },
  AvgDialog_142850_Content_48 = {
    Text = "出來吧，朋友，我會給你一個痛快的。"
  },
  AvgDialog_142850_Content_49 = {
    Text = "瓦羅欣賞著彎刀上映出的自己的面容，不緊不慢地向你走來。"
  },
  AvgDialog_142850_Content_5 = {
    Text = "一場激烈的夢境。你躲在灌木叢中，平復著自己急促的呼吸，透過樹叢的縫隙向外望去。"
  },
  AvgDialog_142850_Content_50 = {
    Text = "你望了望四周，焦急地尋找著一條合適的逃離路線。"
  },
  AvgDialog_142850_Content_51 = {
    Text = "不行……全是密林……我這副小孩的身體，根本跑不過他……"
  },
  AvgDialog_142850_Content_52 = {
    Text = "怎麼辦……"
  },
  AvgDialog_142850_Content_53 = {
    Text = "你閉上眼，努力壓下心中翻湧的恐懼，腦中一片空白……"
  },
  AvgDialog_142850_Content_56 = {
    Text = "腳步聲踩著落葉與地衣，從另一個方向走來。"
  },
  AvgDialog_142850_Content_57 = {
    Text = "它平靜，穩定，如同午後的閒步。"
  },
  AvgDialog_142850_Content_58 = {
    Text = "騎士團的幫手嗎……不選擇逃跑，很有勇氣，也很蠢。"
  },
  AvgDialog_142850_Content_59 = {
    Text = "腳步聲停下的時候，風聲與鳥鳴盡皆消失，連你身後那些屍體滲出的血似乎都停止了流淌，整個森林陷入一片詭異的死寂。"
  },
  AvgDialog_142850_Content_6 = {
    Text = "一柄彎刀從他的胸膛乾脆利落地抽出，發出令人牙酸的摩擦聲。戰士拍了拍鎧甲上沾染的灰塵，抬頭望向周圍。"
  },
  AvgDialog_142850_Content_60 = {
    Text = "一個女人出現在你的視野裡。裝飾般的黑色輕鎧覆在她身上，兩柄與體型不成比例的粗獷巨劍被她隨意提在手裡。"
  },
  AvgDialog_142850_Content_61 = {
    Text = "她的眼睛掃視滿地的屍體，目光在他們的傷口上一閃而過。"
  },
  AvgDialog_142850_Content_62 = {
    Text = "每個人都是五刀以內斃命，專門挑選了鎧甲連接處，角度和力度準確……這些人，是你殺的？"
  },
  AvgDialog_142850_Content_63 = {
    Text = "呵呵呵……沒錯。可惜，我還沒有玩夠，他們就已經倒下了。"
  },
  AvgDialog_142850_Content_64 = {
    Text = "十二個人，你沒有受傷。不錯。"
  },
  AvgDialog_142850_Content_65 = {
    Text = "黑甲女子滿意地點了點頭，平穩的腳步繼續向他走來。"
  },
  AvgDialog_142850_Content_66 = {
    Text = "瓦羅等待著。他在這個女人的眼睛裡尋找恐懼，但看到的只有令人煩躁的平靜。"
  },
  AvgDialog_142850_Content_67 = {
    Text = "不管你是誰，我可以給你三分鐘時間逃跑。三分鐘之後，能不能活著就看……"
  },
  AvgDialog_142850_Content_68 = {
    Text = "我說，你是聾了嗎，聽不見我的話？"
  },
  AvgDialog_142850_Content_69 = {
    Text = "黑甲女子沒有回答，腳步依然平緩得像在散步。憤怒瞬間點燃了瓦羅，他的手扣上了刀柄，拔出了那把鋒利的彎刀。"
  },
  AvgDialog_142850_Content_7 = {
    Text = "下一個，輪到誰了？"
  },
  AvgDialog_142850_Content_70 = {
    Text = "本來想饒你一命，既然你這麼想找死，那我就不客……"
  },
  AvgDialog_142850_Content_71 = {Text = "錚——"},
  AvgDialog_142850_Content_72 = {
    Text = "一聲瓦羅此生聽過的最清脆的金屬碰撞聲，在他耳畔轉瞬即逝。"
  },
  AvgDialog_142850_Content_73 = {
    Text = "本應在瓦羅身前的女子，不知何時出現在他的身後。一柄巨劍被她單手握著，劍刃隨意地擱在他的頸側。"
  },
  AvgDialog_142850_Content_74 = {
    Text = "瓦羅低下頭。那把由六國最精湛的鐵匠打造的、斬殺了無數敵人的彎刀，懸在出鞘數英寸的地方，被齊根斬斷。"
  },
  AvgDialog_142850_Content_75 = {
    Text = "那讓他引以為傲的華麗刀身，旋轉著倒插在被鮮血浸潤的土地，像是一塊冰冷的墓碑。"
  },
  AvgDialog_142850_Content_76 = {
    Text = "這……你……"
  },
  AvgDialog_142850_Content_77 = {
    Text = "能滅掉整支騎士團的人，我以為至少能讓我提起些興趣。"
  },
  AvgDialog_142850_Content_78 = {
    Text = "黑甲女子語氣裡帶著毫不掩飾的失望。"
  },
  AvgDialog_142850_Content_79 = {
    Text = "骨印，你有嗎？"
  },
  AvgDialog_142850_Content_8 = {
    Text = "他舔舐著彎刀上的鮮血，環顧著四周那十幾個包圍著他的人，饒有興致地詢問著。"
  },
  AvgDialog_142850_Content_81 = {
    Text = "瓦羅見過了許多的人或事，他知道在什麼時候應該做什麼。他雙腿一軟，跪倒在她面前。"
  },
  AvgDialog_142850_Content_82 = {
    Text = "閣下、閣下請聽我說……星天之鯨只會選出一個人成為它的代行者，這件事靠一個人是做不到的！"
  },
  AvgDialog_142850_Content_83 = {
    Text = "王冠，那頂王冠！那是每個人都夢想得到的東西……您也一樣，不是麼？！"
  },
  AvgDialog_142850_Content_84 = {
    Text = "您有這樣強大的力量，要是我們組一個隊伍，一定能獲取最終的勝利！"
  },
  AvgDialog_142850_Content_85 = {
    Text = "我將會是您最忠實的僕從，永遠效忠於您，幫您拿到星天之鯨的力量！……"
  },
  AvgDialog_142850_Content_86 = {
    Text = "閣下……請閣下考慮一下……"
  },
  AvgDialog_142850_Content_87 = {
    Text = "不錯的提議。我答應你。"
  },
  AvgDialog_142850_Content_89 = {
    Text = "瓦羅本已準備好一大段說辭，發現完全用不上。"
  },
  AvgDialog_142850_Content_9 = {
    Text = "在他舉起彎刀的時候，所有人不約而同地向後退了一步。"
  },
  AvgDialog_142850_Content_90 = {
    Text = "放心。我從不食言。"
  },
  AvgDialog_142850_Content_92 = {
    Text = "瓦羅如同從深淵邊緣被撈起，手忙腳亂地在身上翻找，終於顫抖著將骨印雙手捧到蘿坦面前。"
  },
  AvgDialog_142850_Content_93 = {
    Text = "這裡！就是這個！"
  },
  AvgDialog_142850_Content_94 = {
    Text = "這個騎士團搶到了兩塊骨印，只要拿著這個，我們就能一起去到星天之鯨的鬥獸場！"
  },
  AvgDialog_142850_Content_95 = {
    Text = "到時候，無論是誰都無法戰勝……"
  },
  AvgDialog_142850_Content_98 = {
    Text = "巨劍的刃口輕鬆劃過鎧甲，一道幾乎貫穿身體的巨大創口從瓦羅的右腰延伸至左肩。"
  },
  AvgDialog_142850_Content_99 = {
    Text = "溫熱的鮮血噴灑在你面前的灌木上，在葉面上凝成暗紅色的露珠。"
  },
  AvgDialog_142851_Content_1 = {
    Text = "契約精神"
  },
  AvgDialog_142851_Content_10 = {
    Text = "在那些斷裂石柱的中央，一道通往另一個空間的裂隙撕裂了現實，如同一隻緩緩睜開的、豎直的瞳孔。"
  },
  AvgDialog_142851_Content_100 = {
    Text = "腳下的肉壁劇烈痙攣，一股濃烈的鐵鏽味湧入鼻腔。這個空間本身正變得興奮起來。"
  },
  AvgDialog_142851_Content_102 = {
    Text = "一萬兩千年，蘿坦……我在這片虛空中等待，等待一個能讓我覺得，存在並非是一場折磨的人。"
  },
  AvgDialog_142851_Content_103 = {
    Text = "國王、聖人、勇士、魔物……他們來到我面前，帶著他們自以為宏大的欲望，下跪，乞求。"
  },
  AvgDialog_142851_Content_104 = {
    Text = "然後，他們被我賜予的力量一點點腐蝕，變成深淵中又一張漂浮的面孔。"
  },
  AvgDialog_142851_Content_105 = {
    Text = "我以為這就是永恆的全部內容。"
  },
  AvgDialog_142851_Content_106 = {
    Text = "直到你站在這裡，用這雙什麼也不渴求的眼睛看著我，告訴我，你要……呵呵呵呵……你要殺了我？！！"
  },
  AvgDialog_142851_Content_107 = {
    Text = "純粹、濃稠、有重量的暗紅色從心臟的裂口湧出，吞沒了所有的光脈與深淵中的面孔。"
  },
  AvgDialog_142851_Content_108 = {
    Text = "在那腐壞的暗紅之中，星天之鯨巨大的身軀的輪廓於天際顯現。"
  },
  AvgDialog_142851_Content_109 = {
    Text = "比這個世界更加巨大的身軀彎折了虛空本身的形狀，你腳下的平面開始像紙一樣彎曲，遠處的黑暗開始向內坍縮。"
  },
  AvgDialog_142851_Content_11 = {
    Text = "原來不需要殺死對方就能讓門打開……你運氣不錯。"
  },
  AvgDialog_142851_Content_110 = {
    Text = "這座星球在它的身體上生長，六國的人類因為它而存在。它是吞噬星球力量的神明，是這顆星球無可爭議的主人。它是這個空間本身。"
  },
  AvgDialog_142851_Content_111 = {
    Text = "幻影徹底消失，利維坦猛然睜開它宏偉的雙眼。"
  },
  AvgDialog_142851_Content_112 = {
    Text = "一股毀天滅地的力量從星天之鯨的身上噴湧而出。整個維度空間開始坍塌，無形的力量將你掀飛出去，重重地摔在平面的邊緣。"
  },
  AvgDialog_142851_Content_113 = {
    Text = "你的手指扣住裂縫，拼命不讓自己滑入深淵。"
  },
  AvgDialog_142851_Content_114 = {
    Text = "你讓我非常、非常高興，蘿坦！"
  },
  AvgDialog_142851_Content_115 = {
    Text = "在你死後，我會讓這個世界的所有奴僕，為你刻下最宏偉的雕塑！"
  },
  AvgDialog_142851_Content_116 = {
    Text = "在那片吞沒一切的黑暗中央，在那個不可名狀的龐然存在面前，蘿坦雙手緊握巨劍，向著那雙可怖的巨瞳走去。"
  },
  AvgDialog_142851_Content_117 = {
    Text = "她的步伐越來越快、越來越快，最終，變成一往無前的風暴。她的臉上，帶著你從未見過的、狂熱的笑意。"
  },
  AvgDialog_142851_Content_118 = {
    Text = "來啊！利維坦！！！"
  },
  AvgDialog_142851_Content_119 = {
    Text = "海潮般快意的咆哮聲響起，震碎了你最後殘存的知覺。你抓住石頭的手再也沒有力氣，在那咆哮的狂風中，你從那道裂隙重新回到了鬥獸場。"
  },
  AvgDialog_142851_Content_12 = {
    Text = "蘿坦收回目光，她對你從來就沒有任何的興趣。那纖細的身影提著巨劍，向那道裂隙走去。"
  },
  AvgDialog_142851_Content_120 = {
    Text = "在你最後的餘光中，你看見蘿坦握著那兩柄巨劍，躍向那比星辰更加宏偉的神祇。"
  },
  AvgDialog_142851_Content_121 = {
    Text = "風暴粉身碎骨。\n風暴永不回頭。"
  },
  AvgDialog_142851_Content_13 = {
    Text = "直到她的身影徹底消失於裂隙，你才終於坐起身來，大口喘著氣。"
  },
  AvgDialog_142851_Content_14 = {
    Text = "呼……嚇死人了……"
  },
  AvgDialog_142851_Content_15 = {
    Text = "那裡……就是星天之鯨的居所嗎……"
  },
  AvgDialog_142851_Content_16 = {
    Text = "你本想逃離這裡，但一種無法抗拒的吸引力從那道裂隙中湧出，如同一根無形的絲線，繫在你的骨骼之上，輕輕地、持續不斷地拉扯著你。"
  },
  AvgDialog_142851_Content_17 = {
    Text = "你的腳不由自主地向裂隙邁去。裂隙微微顫動著，如同一隻溫柔的眼睛正注視著你。"
  },
  AvgDialog_142851_Content_18 = {
    Text = "看一眼，就看一眼。看看那吞噬星辰的巨主，究竟是什麼模樣……你躡手躡腳地靠近裂隙，向裡跟去……"
  },
  AvgDialog_142851_Content_2 = {
    Text = "蘿、蘿坦大人！……"
  },
  AvgDialog_142851_Content_20 = {
    Text = "沒有光，沒有聲音，甚至連你自己的心跳都聽不到。你不確定自己是否還擁有一副軀體，還是已經變成了某種漂浮在虛無中的意識碎片。"
  },
  AvgDialog_142851_Content_21 = {
    Text = "觸覺重新回歸了身體，你的腳下感到一陣柔軟、溫熱、有節律的蠕動。它在你的腳底輕輕收縮，像是一條巨大的舌頭在舔舐著你。"
  },
  AvgDialog_142851_Content_22 = {
    Text = "這是？！！……"
  },
  AvgDialog_142851_Content_23 = {
    Text = "晦暗的星辰在星空中流轉，一團不斷變換著顏色的脈動照耀著你所在的這片空間。"
  },
  AvgDialog_142851_Content_24 = {
    Text = "綿延不絕的血肉團塊在你腳下起伏，像是一個巨大的舌頭或是胃袋。"
  },
  AvgDialog_142851_Content_25 = {
    Text = "你深吸一口氣，和遠處那團閃爍的、眼珠般的脈動對視。短短一秒，強烈的暈眩襲向你，一道溫熱的鮮血從你鼻腔裡湧出。你趕緊挪開目光。"
  },
  AvgDialog_142851_Content_26 = {
    Text = "在你最後的餘光裡，你看見那團變幻的脈動凝結成型，一個虛無的幻影出現在蘿坦面前。在祂開口之時，遼闊的鯨歌在這片空間中響起。"
  },
  AvgDialog_142851_Content_27 = {
    Text = "歡迎，第四千名來到我身前的挑戰者！歡迎來到我的居所。"
  },
  AvgDialog_142851_Content_29 = {
    Text = "如此精彩的角逐，如果不能親臨現場觀看，還有什麼樂趣可言。"
  },
  AvgDialog_142851_Content_3 = {
    Text = "我……我沒有……沒有想過要和您搶王冠……"
  },
  AvgDialog_142851_Content_30 = {
    Text = "我看過你的每一場戰鬥，持巨劍的孩子。"
  },
  AvgDialog_142851_Content_31 = {
    Text = "格拉古，沃恩姐妹，桑吉，埃利安，阿利什……在這座恢弘的鬥獸場，你戰勝了這個星球上所有最為強大的生靈。"
  },
  AvgDialog_142851_Content_32 = {
    Text = "你的劍沒有多餘的動作。你的靈魂沒有多餘的累贅。你的勝利當之無愧，蘿坦。"
  },
  AvgDialog_142851_Content_33 = {
    Text = "那團幻影滿意地點了點頭。"
  },
  AvgDialog_142851_Content_34 = {
    Text = "來到這裡的生靈，理由無非三種：智識，權力，生命。"
  },
  AvgDialog_142851_Content_35 = {
    Text = "貪婪的國王想要不朽的王座，絕望的母親想要復活死去的孩子，瘋狂的術士想要窺探禁忌的知識……他們想要的都很多、很多。"
  },
  AvgDialog_142851_Content_36 = {
    Text = "所以，他們傷害，殺戮，犧牲一切。他們跪在我面前，用我聽了成千上萬年的措辭懇求我。"
  },
  AvgDialog_142851_Content_37 = {
    Text = "但一切都是值得的……最終，每個人都獲得了他們苦苦追尋的東西。"
  },
  AvgDialog_142851_Content_38 = {
    Text = "那麼，勇猛的戰士……你想要的，又是什麼呢？"
  },
  AvgDialog_142851_Content_40 = {
    Text = "力量只是一個工具、一道階梯，在階梯之上，還有東西在等待著你。"
  },
  AvgDialog_142851_Content_41 = {
    Text = "告訴我，你真正想要的，究竟是什麼？"
  },
  AvgDialog_142851_Content_42 = {
    Text = "我已經說過了……我想要的，就只是力量。永遠沒有止境的、更加強大的力量。"
  },
  AvgDialog_142851_Content_43 = {
    Text = "除了力量之外的東西，我不感興趣。"
  },
  AvgDialog_142851_Content_44 = {
    Text = "星天之鯨玩味地看著蘿坦，一道轟鳴般的笑聲在這片空間中響起。"
  },
  AvgDialog_142851_Content_46 = {
    Text = "這樣的話，我曾聽過許多次。每一個說這句話的人，最終都會迷失在力量帶來的慾望裡。"
  },
  AvgDialog_142851_Content_47 = {
    Text = "他們獲得了我的力量，卻無法承受它的重量。它在骨髓裡生長，將靈魂蠶食，殺戮與征服的渴望將他們的意識一一吞沒……"
  },
  AvgDialog_142851_Content_48 = {
    Text = "這樣的故事，我看過四千場，永遠也看不膩。"
  },
  AvgDialog_142851_Content_49 = {
    Text = "隨著一聲鯨歌響起，一顆巨大的鯨魚心臟出現在這片空間之中。一道血柱從心臟流出，在蘿坦面前匯集成密密麻麻的符文。"
  },
  AvgDialog_142851_Content_5 = {
    Text = "你早已忘了肩膀上的傷口，沒有勇氣直視那雙平靜的眼睛。"
  },
  AvgDialog_142851_Content_50 = {
    Text = "它們排列成一個無法被理解的圖形，每當蘿坦試圖看清它的全貌，它就會變成另一個完全不同的形狀。"
  },
  AvgDialog_142851_Content_51 = {
    Text = "僅僅是餘光掃過，你便感到一股灼熱的血流在身體中奔騰，衝擊著你的每一個器官，驅使著你拿起劍刺入面前人的心臟……你趕緊挪開雙眼。"
  },
  AvgDialog_142851_Content_52 = {
    Text = "簽下它。你便將獲得你夢寐以求的……屬於我的力量。"
  },
  AvgDialog_142851_Content_53 = {
    Text = "代價是？"
  },
  AvgDialog_142851_Content_54 = {
    Text = "沒有代價，只有一個承諾。"
  },
  AvgDialog_142851_Content_55 = {
    Text = "我的力量將與你共通，我的命運將與你綁定。從簽訂契約的那一刻起，你便是這顆星球的掌控者，是我意志的代行人。"
  },
  AvgDialog_142851_Content_56 = {
    Text = "你將擁有六國的一切，直到——直到三年後，一場新的角逐開始，一位新的王誕生。"
  },
  AvgDialog_142851_Content_57 = {
    Text = "你將陪著我，看著那些有趣的靈魂、看著你自己，一步步走向深淵。就像你之前的那些王一樣。"
  },
  AvgDialog_142851_Content_58 = {
    Text = "但我知道，即便你知道後果，也不會抗拒。"
  },
  AvgDialog_142851_Content_59 = {
    Text = "你在想，你和前面那四千個挑戰者不同。你擁有能夠克服一切的意志，你永遠不會在力量與慾望的深淵中墮落……"
  },
  AvgDialog_142851_Content_6 = {
    Text = "蘿坦沒有言語，只是提著刀向你走來，不緊不慢。你的額頭緊緊貼在地面，身體在那個靠近的身影前顫抖。"
  },
  AvgDialog_142851_Content_60 = {
    Text = "這個契約，要怎麼簽？"
  },
  AvgDialog_142851_Content_61 = {
    Text = "星天之鯨的微笑帶著古老的倦怠。祂已見過太多次同樣的故事了。這一次，也沒有什麼不同。"
  },
  AvgDialog_142851_Content_62 = {
    Text = "……貪婪。果斷。你並不在意禮儀，但至少，你身上有著令我感到愉快的品質。"
  },
  AvgDialog_142851_Content_63 = {
    Text = "伸出你的手，將它放在契約上吧。"
  },
  AvgDialog_142851_Content_64 = {
    Text = "沒有遲疑，蘿坦伸出手，按在那個鮮血匯成的圖形之上。"
  },
  AvgDialog_142851_Content_65 = {
    Text = "某種液態的、有生命的字符從血池中爬鑽出。它沿著蘿坦的手臂攀爬、滲透，鑽入她的皮膚之下。"
  },
  AvgDialog_142851_Content_66 = {
    Text = "在那些字符經過的地方，蘿坦的血肉迅速地腐化、裂解，只剩下森然的白骨與殷紅的血。"
  },
  AvgDialog_142851_Content_67 = {
    Text = "蘿坦的身體因痛苦而顫抖，但她自始至終也沒有發出任何的聲音。她睜大那雙已經碎裂一半的眼睛，認真地見證著這一切。"
  },
  AvgDialog_142851_Content_68 = {
    Text = "字符沿著血管網絡向心臟蔓延，最終抵達她的雙眼。一瞬間，蘿坦的瞳孔變成了與星天之鯨相同的漩渦。"
  },
  AvgDialog_142851_Content_69 = {
    Text = "然後，漩渦消失了，星天之鯨的瞳色永遠停留在了她的眼中，白骨般的鎧甲覆蓋在她新生的身軀之上。"
  },
  AvgDialog_142851_Content_7 = {
    Text = "一位挑戰者選擇了臣服，一位挑戰者選擇了逃離，十五位挑戰者選擇了死亡……看來，我們最後的優勝者已經產生。"
  },
  AvgDialog_142851_Content_70 = {
    Text = "整個虛空發出一聲低沉的共鳴，那些懸浮在深淵中的、死在鬥獸場中的面孔同時張開了嘴，發出了無聲的哀嚎。"
  },
  AvgDialog_142851_Content_71 = {
    Text = "他們迎接著自己的新王。"
  },
  AvgDialog_142851_Content_72 = {
    Text = "這個……就是星天之鯨的力量……"
  },
  AvgDialog_142851_Content_73 = {
    Text = "蘿坦握住拳頭，感受著自己體內洶湧奔騰的來自古老神明的力量，感受著自己與這個世界的連結。"
  },
  AvgDialog_142851_Content_74 = {
    Text = "被星天之鯨吞噬的世界在她的感知中脈動，所有被星天之鯨創造與奴役的生命如同細微的燭火，只需一個念頭，就能將它們全部熄滅。"
  },
  AvgDialog_142851_Content_75 = {
    Text = "那道血池匯集成猩紅的皇冠，在她的面前熠熠生輝。"
  },
  AvgDialog_142851_Content_76 = {
    Text = "契約已成。你我命運合一，不可逆轉。我存在了多少紀元，你便繼承了多少紀元的重量。"
  },
  AvgDialog_142851_Content_77 = {
    Text = "好好享受吧，蘿坦。我見過太多與你相似的靈魂。純粹，熾熱，不可一世。"
  },
  AvgDialog_142851_Content_78 = {
    Text = "我會期待的……期待，你墜入深淵的那一天。我將陷入一場新的長眠……現在，你可以去做一切你想做的事了。"
  },
  AvgDialog_142851_Content_79 = {
    Text = "星天之鯨的幻影留下無聊的告別，重新打開了裂隙。"
  },
  AvgDialog_142851_Content_8 = {
    Text = "聲音從四面八方湧來，帶著令人不適的愉悅。看台上的無數幻影同時站起身，不斷變幻的面孔上浮現出一模一樣的笑容。"
  },
  AvgDialog_142851_Content_80 = {
    Text = "你的話說完了？"
  },
  AvgDialog_142851_Content_81 = {
    Text = "星天之鯨的居所陷入短暫的沉默。祂沒有等到自己期望的誦念與臣服，祂等到的是一雙燃燒著難耐欲火的戰士的眼睛。"
  },
  AvgDialog_142851_Content_82 = {
    Text = "那麼現在……到你出手的時候了。"
  },
  AvgDialog_142851_Content_83 = {
    Text = "你從未想過，你會在一位神明的眼中看到困惑。"
  },
  AvgDialog_142851_Content_84 = {
    Text = "你……說什麼？"
  },
  AvgDialog_142851_Content_85 = {
    Text = "你說，我可以做我一切想做的事……我想做的事情只有一件。殺死你，或者被你殺死。"
  },
  AvgDialog_142851_Content_86 = {
    Text = "我的習慣是讓對手先出手。所以，到你出手的時候了，利維坦。"
  },
  AvgDialog_142851_Content_87 = {
    Text = "你剛剛簽訂了契約……"
  },
  AvgDialog_142851_Content_88 = {
    Text = "我承諾過，要成為這個星球的守護者、你意志的執行人。"
  },
  AvgDialog_142851_Content_89 = {
    Text = "你是這個星球的奴隸主，我替他們討伐你，也算是履行我的職責。"
  },
  AvgDialog_142851_Content_9 = {
    Text = "一陣沉悶的聲響。鬥獸場的石柱在你身後崩毀，碎石飛向天空，消失在那片沼澤般暗紅色的天空深處。"
  },
  AvgDialog_142851_Content_90 = {
    Text = "你是吞星者，殺戮與戰爭的代名詞。戰鬥，便是你的意志。"
  },
  AvgDialog_142851_Content_91 = {
    Text = "很不錯的玩笑，蘿坦。現在離開，你依然能獲得所有人都想擁有的一切。留在這裡，你什麼也得不到。"
  },
  AvgDialog_142851_Content_92 = {
    Text = "我的話已經說得很清楚。"
  },
  AvgDialog_142851_Content_93 = {
    Text = "契約已將你的命運與我綁在一起。我的死亡就是你的死亡。"
  },
  AvgDialog_142851_Content_95 = {
    Text = "你的力量，連我的一半都不到。你剛剛獲得它，你根本不理解你所要駕馭的力量……你根本沒有這個能力來挑戰我，蘿坦。"
  },
  AvgDialog_142851_Content_96 = {
    Text = "我想試試。"
  },
  AvgDialog_142851_Content_98 = {
    Text = "星天之鯨狂笑著。祂已有上萬年的時間沒有如此快意地笑過。"
  },
  AvgDialog_142851_Content_99 = {
    Text = "笑聲從虛空的最深處湧上來，震動著每一條光脈、每一片鱗甲、每一張漂浮在深淵中的面孔。"
  },
  AvgDialog_142852_Content_10 = {
    Text = "你轉過身去，正好看到兩個快速奔襲而來的陰影——"
  },
  AvgDialog_142852_Content_100 = {
    Text = "阿利什震撼地看著眼前這個年輕的女人。晦暗的血紅色光芒映照著她的剪影。在他人生的最後時刻，他看到了他的信仰本身。"
  },
  AvgDialog_142852_Content_102 = {
    Text = "我想象過許多次自己的死亡……沒有任何一個，比今天發生的更令我滿意。"
  },
  AvgDialog_142852_Content_103 = {
    Text = "感謝你，蘿坦女士。"
  },
  AvgDialog_142852_Content_104 = {
    Text = "阿利什將軍張開雙臂，沐浴著血色的日光。"
  },
  AvgDialog_142852_Content_106 = {
    Text = "一道乾脆利落的刀光亮起，老阿利什的頭顱滾落在死去的戰馬與折斷的旗幟旁邊。"
  },
  AvgDialog_142852_Content_107 = {
    Text = "飽經滄桑的頭顱上掛著滿足的微笑。對於自己的結局，老阿利什別無所求。"
  },
  AvgDialog_142852_Content_108 = {
    Text = "替他闔上雙眼，蘿坦轉過身，看見那個穿著宰相服飾的貴族，還有他顫抖的刀下那個孩童。"
  },
  AvgDialog_142852_Content_109 = {
    Text = "蘿……蘿坦大人……"
  },
  AvgDialog_142852_Content_111 = {
    Text = "循著埃利安的聲音，蘿坦回過頭望了一眼身後那個隱匿在黑暗中的身影。"
  },
  AvgDialog_142852_Content_112 = {
    Text = "短暫地掙扎了數秒之後，宰相官邸的毒士收起了自己顫抖的手，轉頭向鬥獸場外跑去。在死亡面前，大多數人都知道作何選擇。"
  },
  AvgDialog_142852_Content_113 = {
    Text = "看來，你對身邊人的掌控實在有限。"
  },
  AvgDialog_142852_Content_114 = {
    Text = "蘿坦女士，我們是盟友！還記得嗎？"
  },
  AvgDialog_142852_Content_115 = {
    Text = "讓我活著，讓我去見星天之鯨……我會給你一切你想要的東西！"
  },
  AvgDialog_142852_Content_116 = {
    Text = "還有{Male=他,Female=她}……你不想讓{Male=他,Female=她}死，沒錯吧？我看得出來……那麼激烈的戰鬥，你都想要保住{Male=他,Female=她}的性命……"
  },
  AvgDialog_142852_Content_117 = {
    Text = "死亡的腳步持續不斷地向埃利安逼近。他的聲音開始顫抖起來。"
  },
  AvgDialog_142852_Content_119 = {
    Text = "鋒利的匕首狠狠插入你的肩膀，鬥獸場內響起你痛苦的呼喊。"
  },
  AvgDialog_142852_Content_120 = {
    Text = "蘿坦！你再過來，這個人就會因為你死掉！"
  },
  AvgDialog_142852_Content_121 = {
    Text = "你從不濫殺無辜……你從不希望無辜的人因為你而死！沒錯，沒錯！！我不會看錯人的！！"
  },
  AvgDialog_142852_Content_122 = {
    Text = "伴隨著持續不斷的哀嚎，匕首在你體內轉動。"
  },
  AvgDialog_142852_Content_123 = {
    Text = "蘿坦平靜得似乎什麼也聽不見，她提著巨劍走向埃利安，步履平穩得如同午後的散步。"
  },
  AvgDialog_142852_Content_124 = {
    Text = "我欣賞純粹的人。純粹的殺意，純粹的力量，純粹的榮耀，純粹的智慧與狡詐。"
  },
  AvgDialog_142852_Content_126 = {
    Text = "蘿坦輕蔑地搖了搖頭。"
  },
  AvgDialog_142852_Content_127 = {
    Text = "你連我在意的東西是什麼都沒有弄清楚。"
  },
  AvgDialog_142852_Content_128 = {
    Text = "你，什麼也不是。"
  },
  AvgDialog_142852_Content_13 = {
    Text = "兩股風從你身邊颳過，溫熱的液體噴濺在你的身上。"
  },
  AvgDialog_142852_Content_130 = {
    Text = "乾淨俐落的刀一閃而過。這位縱橫六國的政客，帶著驚訝的、無力的眼睛，迎來自己的終局。"
  },
  AvgDialog_142852_Content_131 = {
    Text = "整座鬥獸場只剩下兩個還能呼吸的生物。蘿坦手中的巨劍鮮血淋漓，那道沒有任何溫度的目光，望向了你。"
  },
  AvgDialog_142852_Content_14 = {
    Text = "沒有感覺到疼痛，死亡似乎也尚未降臨。你挪開捂住雙眼的手，看到兩顆新鮮的頭顱，正睜著不甘的雙眼望向你。"
  },
  AvgDialog_142852_Content_16 = {
    Text = "你趕緊後退兩步，差點被格拉古的半截屍體絆倒。"
  },
  AvgDialog_142852_Content_17 = {
    Text = "哈，沃恩姐妹，兩位多麼著名的賞金獵人。六國的國王們曾想過無數種方法，都沒能招募她們。"
  },
  AvgDialog_142852_Content_18 = {
    Text = "現在，她們迎來了自己唯一一次失敗的狩獵。"
  },
  AvgDialog_142852_Content_19 = {
    Text = "幻影觀眾們山呼海嘯的歡呼聲中，埃利安滿意地跨過屍體。"
  },
  AvgDialog_142852_Content_2 = {
    Text = "鬥獸場環形石壁高聳，看台上擠滿了聚精會神的幻影。"
  },
  AvgDialog_142852_Content_20 = {
    Text = "和我預想的順序不同，但沒關係。我們的敵人，已經所剩無幾。現在，我想你需要休息……"
  },
  AvgDialog_142852_Content_21 = {
    Text = "一道猛烈的馬蹄聲帶著呼嘯的狂風打斷了埃利安的話，猛然出現在埃利安和你身後。"
  },
  AvgDialog_142852_Content_22 = {
    Text = "在你還沒有反應過來的時候，蘿坦將你提起來扔到了一邊。"
  },
  AvgDialog_142852_Content_23 = {
    Text = "<RedBigShake:死——！>"
  },
  AvgDialog_142852_Content_24 = {
    Text = "戰馬嘹亮的嘶鳴響徹鬥獸場。煙塵之中，一位穿著老舊鎧甲的將軍拉住奔騰的戰馬，將手中軍旗的尖刺送入一名避閃不及的騎士的胸膛。"
  },
  AvgDialog_142852_Content_25 = {
    Text = "緩慢散去的煙塵勾勒出一個並不魁梧的身影。他輕拉韁繩，帶著戰馬轉過身，那雙見慣了屍山血海的眼睛平靜地望向你們。"
  },
  AvgDialog_142852_Content_26 = {
    Text = "你不小心與那雙眼睛對視了一眼。一股強大的壓迫感讓你雙腿一軟，幾乎無法站立。"
  },
  AvgDialog_142852_Content_27 = {
    Text = "煙塵散去。你看到那個傳說中留有七十道裂口的舊鎧甲，還有那匹曾經踏破六國土地、高傲地噴著熱氣的披甲戰馬。"
  },
  AvgDialog_142852_Content_28 = {
    Text = "四顆滴著鮮血的人頭掛在戰馬的身側，那是老人從小便養成的習慣。"
  },
  AvgDialog_142852_Content_29 = {
    Text = "阿利什將軍。"
  },
  AvgDialog_142852_Content_3 = {
    Text = "如同泥沼般暗紅色天空深處，巨大的鯨魚般的陰影在緩慢地游動。"
  },
  AvgDialog_142852_Content_30 = {
    Text = "你注意到蘿坦的語氣第一次有了明顯的變化。她的聲音沙啞而興奮，如同一頭嗅到獵物氣味的獅子。"
  },
  AvgDialog_142852_Content_31 = {
    Text = "告訴我，我的對手叫什麼名字。"
  },
  AvgDialog_142852_Content_32 = {
    Text = "你可以叫我蘿坦。"
  },
  AvgDialog_142852_Content_33 = {
    Text = "蘿坦……這世上大部分值得交手的人我都聽過，但我不記得這個名號。"
  },
  AvgDialog_142852_Content_34 = {
    Text = "或許是因為聽過這名字的人大部分都已經死了。這不重要。五分鐘之後，你會記住我的名字。"
  },
  AvgDialog_142852_Content_35 = {
    Text = "哈……這個世界常常出現讓我難以適應的變化，或許，現在的年輕人有著讓我忌憚的資本。"
  },
  AvgDialog_142852_Content_36 = {
    Text = "離開賽已經過去半小時。能活到現在，你一定有著與你的狂妄相匹配的實力。"
  },
  AvgDialog_142852_Content_37 = {
    Text = "您誤會了，阿利什將軍，我們並非您的敵人。"
  },
  AvgDialog_142852_Content_38 = {
    Text = "讓開，埃利安。"
  },
  AvgDialog_142852_Content_39 = {
    Text = "（小聲）蘿坦女士，請不要忘記我們之前所制定的計劃。現在我們應該先清除掉其他的敵人。阿利什年老體衰，等他體力不濟的時候……"
  },
  AvgDialog_142852_Content_4 = {
    Text = "祂一直都這麼喜歡看熱鬧嗎？"
  },
  AvgDialog_142852_Content_40 = {
    Text = "我說，讓開。"
  },
  AvgDialog_142852_Content_41 = {
    Text = "埃利安見過許多危險人物，蘿坦的聲音和他們相比絲毫不激烈，但那冷淡的話語讓埃利安感到前所未有的強烈恐懼。"
  },
  AvgDialog_142852_Content_42 = {
    Text = "他沒有思考太久，臉色如常地讓開了道路。"
  },
  AvgDialog_142852_Content_43 = {
    Text = "這座鬥獸場裡剩下的人不多。值得我挑戰的對手，只有一個。"
  },
  AvgDialog_142852_Content_44 = {
    Text = "蘿坦的手放在巨劍的握把上，向阿利什的方向走去。"
  },
  AvgDialog_142852_Content_45 = {
    Text = "那些看台上的幻影全部安靜下來，他們模糊的面孔齊刷刷地跟著蘿坦的腳步轉動。"
  },
  AvgDialog_142852_Content_46 = {
    Text = "空氣中的低頻嗡鳴變得更加清晰，如同某種古老的、貪婪的期待。"
  },
  AvgDialog_142852_Content_47 = {
    Text = "我看到過你的出手，年輕人。在我七十年的征戰生涯裡，我從沒有見過像你一樣強的對手。"
  },
  AvgDialog_142852_Content_48 = {
    Text = "這座鬥獸場裡有著世界上最為強大的敵人，每個人都想要先出手，但你沒有。你永遠會等你的對手先拔劍……"
  },
  AvgDialog_142852_Content_49 = {
    Text = "能告訴我，為什麼嗎？"
  },
  AvgDialog_142852_Content_5 = {
    Text = "蘿坦搖搖頭，將巨劍從腳下的屍體身上拔了出來。"
  },
  AvgDialog_142852_Content_50 = {
    Text = "因為……拔出劍的敵人，會更強一些。"
  },
  AvgDialog_142852_Content_51 = {
    Text = "更……強一些？"
  },
  AvgDialog_142852_Content_52 = {
    Text = "我只對更強的東西感興趣。舉起你的軍旗吧，阿利什。"
  },
  AvgDialog_142852_Content_53 = {
    Text = "蘿坦的話語沒有絲毫挑釁的意味。她的手放在巨劍之上，眼睛緊盯著那位垂垂老矣的將軍，腳步莊重得如同一位朝聖者。"
  },
  AvgDialog_142852_Content_55 = {
    Text = "老將軍仰頭笑起來。他的戰馬紋絲不動，一人一馬獨自站立在鬥獸場中央，血紅的旗幟在風中凌亂飛舞。"
  },
  AvgDialog_142852_Content_56 = {
    Text = "很像。真的很像……如果再年輕一些，我們或許就能在這個世界上看到另一個自己。"
  },
  AvgDialog_142852_Content_57 = {
    Text = "無論如何……希望我們都不會令彼此失望！"
  },
  AvgDialog_142852_Content_58 = {
    Text = "阿利什的聲音陡然升高，雙腿嫻熟一拍，那匹隨他征戰多年的戰馬猛然啟動，一聲嘹亮的嘶鳴在廣闊的戰場上迴蕩——"
  },
  AvgDialog_142852_Content_59 = {
    Text = "旗幟飛揚，如同紅色的閃電撕破鬥獸場中央的塵土，向蘿坦奔襲而去。"
  },
  AvgDialog_142852_Content_6 = {
    Text = "被洞穿的骨骼與劍身摩擦出令人牙酸的聲響，魁梧的身體被撕扯成兩截，那雙不甘的眼睛隨著半截身子滾入淌血的陰溝裡。"
  },
  AvgDialog_142852_Content_60 = {
    Text = "你看到，蘿坦的嘴角抑制不住地上揚。這是你第一次看到蘿坦的笑容。"
  },
  AvgDialog_142852_Content_61 = {
    Text = "她拔出巨劍，猛然向著那道紅色的閃電迎頭撞去——"
  },
  AvgDialog_142852_Content_63 = {
    Text = "轟！！！——"
  },
  AvgDialog_142852_Content_64 = {
    Text = "白色的巨劍與紅色的軍旗相撞，高頻、尖銳的聲音震動著每一個人的耳膜。"
  },
  AvgDialog_142852_Content_65 = {
    Text = "戰馬的鐵蹄踏起煙塵，蘿坦與阿利什的身影在晦暗的戰場中交錯。"
  },
  AvgDialog_142852_Content_66 = {
    Text = "每一次碰撞，天空中那道巨鯨的陰影便猛烈地顫動一下，彷彿在品嚐著一道難得的珍饈。"
  },
  AvgDialog_142852_Content_68 = {
    Text = "阿利什將軍……蘿坦女士……"
  },
  AvgDialog_142852_Content_69 = {
    Text = "真是場驚人的戰鬥……"
  },
  AvgDialog_142852_Content_7 = {
    Text = "他剛才說，他叫什麼來著？"
  },
  AvgDialog_142852_Content_70 = {
    Text = "你努力用眼睛捕捉著兩人的身影，但那讓你十分難以辨認。"
  },
  AvgDialog_142852_Content_71 = {
    Text = "維拉，動手吧。"
  },
  AvgDialog_142852_Content_72 = {
    Text = "是，埃利安老爺。"
  },
  AvgDialog_142852_Content_74 = {
    Text = "那是……宰相官邸那個製毒的術士？！蘿坦女士！小心……"
  },
  AvgDialog_142852_Content_75 = {
    Text = "你的話沒有說完，一陣冰涼的觸感貼上你的皮膚。"
  },
  AvgDialog_142852_Content_76 = {
    Text = "噓……小麻雀。你對我一直忠心耿耿，現在，你想因為一個素不相識的人，背叛我嗎？"
  },
  AvgDialog_142852_Content_78 = {
    Text = "我說過，等我拿到星天之鯨的王冠，成為六國的至高王，你的家人和你自己，都會收到應有的恩賞。"
  },
  AvgDialog_142852_Content_79 = {
    Text = "但現在，給我好好閉上你的嘴。"
  },
  AvgDialog_142852_Content_8 = {
    Text = "格拉古……整個北方最出名的角鬥士，在六國的鬥獸場裡從來沒有敗績……"
  },
  AvgDialog_142852_Content_80 = {
    Text = "喉嚨滾動著。只有身為奴隸之人，才知道埃利安的這句話有著多麼強烈的誘惑力。"
  },
  AvgDialog_142852_Content_81 = {
    Text = "你看著那個毒士隱藏著自己的身形混入煙塵之中，不再作聲。"
  },
  AvgDialog_142852_Content_83 = {
    Text = "正在縱馬疾馳的將軍瞟見了一個隱入煙塵的身形，眉頭緊緊皺起。這讓他的反應慢了半分。"
  },
  AvgDialog_142852_Content_84 = {
    Text = "當那柄兇猛的巨劍再度向他揮來時，他只能提起軍旗勉強擋住。"
  },
  AvgDialog_142852_Content_86 = {
    Text = "一陣巨力碰撞，戰馬打了個趔趄，猛然墜地。鮮紅的軍旗斷成兩截，一柄巨大的劍橫在他的脖頸。"
  },
  AvgDialog_142852_Content_87 = {
    Text = "你的動作慢了，阿利什。"
  },
  AvgDialog_142852_Content_89 = {
    Text = "這件事很重要嗎？"
  },
  AvgDialog_142852_Content_9 = {
    Text = "你見過不少死人，但眼前的景象仍讓你胃裡一陣翻騰。"
  },
  AvgDialog_142852_Content_90 = {
    Text = "你說……什麼？"
  },
  AvgDialog_142852_Content_91 = {
    Text = "蘿坦輕輕嘆了口氣，輕微的嘆息裡滿是遺憾。"
  },
  AvgDialog_142852_Content_92 = {
    Text = "你很接近了，阿利什，但還不夠。在力量與戰鬥之上，你還有著其他的渴求——榮譽。"
  },
  AvgDialog_142852_Content_93 = {
    Text = "你太在意那些無聊的東西。你還不夠純粹。"
  },
  AvgDialog_142852_Content_94 = {
    Text = "蘿坦睜開眼，搖了搖頭，全然不顧那個躲在她身後的陰影。"
  },
  AvgDialog_142852_Content_95 = {
    Text = "你認為，有埃利安的幫助，你們幾個一起對付我，勝之不武。"
  },
  AvgDialog_142852_Content_96 = {
    Text = "難道不應該是這樣？兩個能力與思想接近的人，一場公正的決鬥……"
  },
  AvgDialog_142852_Content_97 = {
    Text = "瞧瞧你用了多少詞。榮譽、公正、尊嚴……都是弱者給自己編造的鎖鏈。"
  },
  AvgDialog_142852_Content_98 = {
    Text = "戰士生來就是隻為戰鬥而存在。戰鬥……就只是戰鬥罷了。與其他的任何東西都無關。"
  },
  AvgDialog_142852_Content_99 = {
    Text = "天空中的陰影停駐下來，發出一陣愉悅的轟鳴。"
  },
  AvgDialog_142853_Content_1 = {
    Text = "唯一的規則"
  },
  AvgDialog_142853_Content_10 = {
    Text = "我說……蘿坦大人……您能不能稍微走慢一些……"
  },
  AvgDialog_142853_Content_100 = {
    Text = "蘿坦大人……不要信他的話！他是個騙子……我在他身邊，看到他犯過無數的罪……"
  },
  AvgDialog_142853_Content_101 = {
    Text = "我相信，您不會和他那樣的人合作的……"
  },
  AvgDialog_142853_Content_102 = {
    Text = "你向蘿坦連連擺手。你想提醒她，埃利安是一個多麼狡詐的人。"
  },
  AvgDialog_142853_Content_103 = {
    Text = "從奴隸到商人，從商人到貴族，從貴族到宰相，埃利安艱難的一路留下了無數的腳印，每一個腳印裡都灌滿了謊言與鮮血。"
  },
  AvgDialog_142853_Content_104 = {
    Text = "但蘿坦並沒有看你。她偏過頭，望向暗紅色的天穹。那個巨大的、鯨魚狀的陰影仍在緩緩移動，布滿骨刺的輪廓若隱若現。"
  },
  AvgDialog_142853_Content_105 = {Text = "讓開。"},
  AvgDialog_142853_Content_106 = {
    Text = "你麻木地挪開身子。蘿坦從你身側走過，低頭俯視著面前的宰相。暗紅色的光線在她身後勾出一道鋒利的剪影。"
  },
  AvgDialog_142853_Content_107 = {
    Text = "你比你的騎士團有趣得多，埃利安。我不在意你是個什麼樣的人，也不關心你會在什麼時候背叛。你能幫到我，這就足夠了。"
  },
  AvgDialog_142853_Content_108 = {
    Text = "我同意你的請求。不要打擾我的戰鬥，這是我唯一的要求。"
  },
  AvgDialog_142853_Content_109 = {
    Text = "蘿坦大人……您……"
  },
  AvgDialog_142853_Content_11 = {
    Text = "一路上您都不怎麼說話，只顧著殺人和趕路，也不怎麼歇息……"
  },
  AvgDialog_142853_Content_110 = {
    Text = "空氣裡流淌的權欲如同潮汐般沖刷著你，苦笑攀上你的臉。來到這座鬥獸場的人都一樣，你本不應該有什麼期待的。"
  },
  AvgDialog_142853_Content_111 = {
    Text = "埃利安咧開嘴，他的神態中沒有一丁點超脫於意外的喜悅，彷彿這是一場必定勝利的談判。"
  },
  AvgDialog_142853_Content_112 = {
    Text = "他轉過身，向鬥獸場邊的看台走去。"
  },
  AvgDialog_142853_Content_113 = {
    Text = "所有人的信息，他們將組成的隊伍、他們將破裂的時機，還有最能令你愉悅的挑戰順序，我已經為你想好了。"
  },
  AvgDialog_142853_Content_114 = {
    Text = "享受這場戰鬥吧，蘿坦女士。"
  },
  AvgDialog_142853_Content_12 = {
    Text = "你是想自己閉嘴，還是想讓我把劍塞進你的嘴裡？"
  },
  AvgDialog_142853_Content_14 = {
    Text = "你緊緊捂住嘴。蘿坦的目光沒有在你身上停留。她觀察著周圍的環境，手撫過一截斷裂的石柱。"
  },
  AvgDialog_142853_Content_15 = {
    Text = "石柱的截面上布滿了黑色的、如同血管般的紋路，像是某種活物的組織在生長。"
  },
  AvgDialog_142853_Content_16 = {
    Text = "這是……"
  },
  AvgDialog_142853_Content_17 = {
    Text = "你把耳朵貼在石柱上，隱約聽見了一種極其低沉的律動，像某種巨大的生物在石頭深處緩慢地呼吸。"
  },
  AvgDialog_142853_Content_18 = {
    Text = "一股無端的噁心與殺戮的衝動湧入你的身體，你趕緊退開。"
  },
  AvgDialog_142853_Content_19 = {
    Text = "這個東西……是活的？！"
  },
  AvgDialog_142853_Content_2 = {
    Text = "這就是你帶的路？"
  },
  AvgDialog_142853_Content_20 = {
    Text = "傳說裡，星天之鯨用祂的身體創造了這個世界，六國的子民，都存在於祂的軀體之上。"
  },
  AvgDialog_142853_Content_21 = {
    Text = "看來，我們離它已經很近了。"
  },
  AvgDialog_142853_Content_22 = {
    Text = "蘿坦走向廣場中央的一個石桌。那塊用青金石製成的石桌，精緻的做工與昂貴的材料與這個荒涼的地方格格不入。"
  },
  AvgDialog_142853_Content_23 = {
    Text = "石桌的表面覆蓋著一層細密的、濕潤的鱗片，在微弱的光線下緩緩開合，頻率就像你剛剛聽到的呼吸聲。"
  },
  AvgDialog_142853_Content_24 = {
    Text = "蘿坦將兩塊骨印放了上去。骨印接觸鱗片的瞬間，那些鱗片驟然收緊，像無數隻手指攥住了獵物，將那兩塊骨製的陳舊印章吞噬殆盡。"
  },
  AvgDialog_142853_Content_25 = {
    Text = "我們的骨印！！！"
  },
  AvgDialog_142853_Content_26 = {
    Text = "啊！兩位新的挑戰者！"
  },
  AvgDialog_142853_Content_27 = {
    Text = "在你衝向石桌的時候，一個人形的輪廓從石桌的中央緩緩浮起。"
  },
  AvgDialog_142853_Content_28 = {
    Text = "它的面孔在不停地變換，時而是國王，時而是騎士，時而是某種你無法辨認的東西。"
  },
  AvgDialog_142853_Content_29 = {
    Text = "它的聲音像是從血泊之下傳來，每個音節都帶著奇異的共鳴。"
  },
  AvgDialog_142853_Content_3 = {
    Text = "我們要找的是鬥獸場，不是廢墟。這裡看起來已經荒廢很多年了。"
  },
  AvgDialog_142853_Content_30 = {
    Text = "我是星天之鯨的幻影，祂最忠實的僕從，也是此座鬥獸場的管理者與觀眾。"
  },
  AvgDialog_142853_Content_31 = {
    Text = "你們經歷了重重艱險，終於依靠自己的力量與智慧來到此地。你們是六國的驕傲，最為強大與堅韌的……"
  },
  AvgDialog_142853_Content_32 = {
    Text = "廢話可以少一些。"
  },
  AvgDialog_142853_Content_33 = {
    Text = "……你相當無禮，挑戰者。幸運的是，星天之鯨從不在意這些。"
  },
  AvgDialog_142853_Content_34 = {
    Text = "祂在意的只有一件事：力量。純粹的、不摻一絲雜念的力量。"
  },
  AvgDialog_142853_Content_35 = {
    Text = "歡迎，歡迎來到星天之鯨的鬥獸場，歡迎來到純粹力量的舞台——"
  },
  AvgDialog_142853_Content_36 = {
    Text = "幻影高舉雙臂，一道如鯨歌般低頻、遼遠的聲音從他的體內發出，穿透你的骨骼，在你的顱腔內共鳴。"
  },
  AvgDialog_142853_Content_37 = {
    Text = "！！！這是……"
  },
  AvgDialog_142853_Content_38 = {
    Text = "歌聲如漣漪盪開，波紋所到之處，天空被抹上低沉的紅色，斷壁殘垣被不明的黏液附著連接，廢墟般的建築化作一座宏偉的古鬥獸場。"
  },
  AvgDialog_142853_Content_39 = {
    Text = "四周的巨大神祇雕塑擺著不同的手勢，用悲憫或憤怒的雙眼望向腳下螻蟻般的生靈。"
  },
  AvgDialog_142853_Content_4 = {
    Text = "地圖我記得很熟，應該就是這個地方沒錯啊……可為什麼這裡和記載的不一樣？"
  },
  AvgDialog_142853_Content_40 = {
    Text = "十幾名挑戰者三三兩兩地分散在主台的周圍，暗自打量著你們。"
  },
  AvgDialog_142853_Content_42 = {
    Text = "骨印一共有二十塊，後面應該還會有兩個人……"
  },
  AvgDialog_142853_Content_43 = {
    Text = "沒有了，挑戰者。那兩塊骨印，已經在上一輪的角逐中被摧毀。"
  },
  AvgDialog_142853_Content_44 = {
    Text = "恭喜二位。作為最後到達的人，你們將擁有被全部人注目的榮幸——"
  },
  AvgDialog_142853_Content_45 = {
    Text = "幻影輕快的笑聲裡，十六道不懷好意的目光向你們投來。"
  },
  AvgDialog_142853_Content_46 = {
    Text = "那個人好熟悉……好像在哪個角鬥場的宣傳圖上見到過？"
  },
  AvgDialog_142853_Content_47 = {
    Text = "那身衣服……好像是屬於那個叫做小指的殺手組織！沒想到能在這裡見到他們的人……"
  },
  AvgDialog_142853_Content_48 = {
    Text = "你知道得還不少。"
  },
  AvgDialog_142853_Content_49 = {
    Text = "騎士團的會議我不能講話，但也旁聽過很多次。埃利安老爺和我們講過許多……"
  },
  AvgDialog_142853_Content_5 = {
    Text = "你看著周圍被風化了多年的斷壁殘垣，撓了撓頭。"
  },
  AvgDialog_142853_Content_50 = {
    Text = "啊！你看那邊！！那個穿著舊鎧甲的人！"
  },
  AvgDialog_142853_Content_51 = {
    Text = "那是六國最勇武的將軍！他曾經單槍匹馬在戰場上斬殺過敵國的國王，我從小就聽著他的故事長大！"
  },
  AvgDialog_142853_Content_52 = {
    Text = "一位活著的傳奇！沒想到……沒想到能在這裡見過他！"
  },
  AvgDialog_142853_Content_53 = {
    Text = "蘿坦沒有理會你抑制不住的興奮叫喊。她掃了眼參賽者，靠在石柱上閉上了眼睛。"
  },
  AvgDialog_142853_Content_54 = {
    Text = "騎士團參與這場角逐之前，我和夫人打賭誰會是進入到星天之鯨宮殿的人。"
  },
  AvgDialog_142853_Content_55 = {
    Text = "你做得很好，小麻雀。在這場令人厭倦的遊戲結束以後，夫人得給我賠上一大筆錢了。"
  },
  AvgDialog_142853_Content_57 = {
    Text = "埃……埃利安老爺……"
  },
  AvgDialog_142853_Content_58 = {
    Text = "溫和的聲音，穩定的腳步，用名貴織料製成的寬袍，身上杜松子香水的香氣……即便化為灰燼，你也能認出他。"
  },
  AvgDialog_142853_Content_59 = {
    Text = "您……您怎麼親自……我是說……"
  },
  AvgDialog_142853_Content_6 = {
    Text = "國王在自己的日記裡說，這裡的牆壁是用黃金製成，這裡的天空中有六翼的神使翱翔，這裡的河流裡流淌著蜜與酒……"
  },
  AvgDialog_142853_Content_60 = {
    Text = "您讓騎士團幫您爭奪王冠，我以為……"
  },
  AvgDialog_142853_Content_61 = {
    Text = "你以為我會把全部的希望寄予一個連僱傭兵都打不過的騎士團？我教過你的，小麻雀，雞蛋永遠不要放在同一個籃子。"
  },
  AvgDialog_142853_Content_62 = {
    Text = "請對善良的埃利安有些信心，偉大的星天之鯨總是會眷顧好人的。"
  },
  AvgDialog_142853_Content_63 = {
    Text = "貴族優雅地微笑。他的目光從未離開蘿坦。"
  },
  AvgDialog_142853_Content_64 = {
    Text = "這位是……你的朋友？"
  },
  AvgDialog_142853_Content_65 = {
    Text = "呃，或許不太算……"
  },
  AvgDialog_142853_Content_66 = {
    Text = "蘿坦。一名戰士。"
  },
  AvgDialog_142853_Content_67 = {
    Text = "很高興見到你，蘿坦女士。希望我的家僕沒有為你添麻煩。"
  },
  AvgDialog_142853_Content_69 = {
    Text = "蘿坦的目光掃過他服飾與腰間佩劍的紋飾。即便是再不關心六國的政治，宰相的印記也依然十分容易分辨。"
  },
  AvgDialog_142853_Content_7 = {
    Text = "現在這個廢墟一樣的廣場是怎麼回事……也看不到檢查骨印的人。"
  },
  AvgDialog_142853_Content_70 = {
    Text = "一個虛職罷了，唯一的作用是節省下自我介紹的時間。"
  },
  AvgDialog_142853_Content_71 = {
    Text = "埃利安微笑著，坐到了蘿坦身前的石柱上。"
  },
  AvgDialog_142853_Content_72 = {
    Text = "你帶著我的奴僕來到這裡，我的騎士團卻消失不見。我想，我大概已經明白路上發生了些什麼了。"
  },
  AvgDialog_142853_Content_73 = {
    Text = "你的騎士團死得很無聊。十二個人，連一個下三濫戰士的盔甲都沒有碰到。"
  },
  AvgDialog_142853_Content_74 = {
    Text = "而你，很輕易地成為了那場戰鬥的贏家。"
  },
  AvgDialog_142853_Content_75 = {
    Text = "你對他們的死好像一點也沒有興趣。"
  },
  AvgDialog_142853_Content_76 = {
    Text = "啊，不不不，您誤會我了，蘿坦女士……"
  },
  AvgDialog_142853_Content_77 = {
    Text = "埃利安哈哈大笑，搖了搖頭。"
  },
  AvgDialog_142853_Content_78 = {
    Text = "我的騎士都是好孩子，忠誠，刻苦……但這是星天之鯨的鬥獸場。弱者迎來了屬於弱者的結局，我對此並不在意。"
  },
  AvgDialog_142853_Content_79 = {
    Text = "我在意的是你，蘿坦女士。一個強大的戰士，熱愛刀劍、殺戮與鮮血，為了那頂鮮血鑄就的王冠，甘願獻出一切……"
  },
  AvgDialog_142853_Content_8 = {
    Text = "餵！等等我……"
  },
  AvgDialog_142853_Content_80 = {
    Text = "埃利安的語速越來越快。空氣中飄蕩著的殺戮與權欲浸潤著他，讓他那顆飽經風霜的心也難以自抑地躍動起來。"
  },
  AvgDialog_142853_Content_81 = {
    Text = "似乎是察覺到了自己的失態，他深吸一口氣，向後退了半步。"
  },
  AvgDialog_142853_Content_82 = {
    Text = "我想，我們可以合作。"
  },
  AvgDialog_142853_Content_83 = {
    Text = "你覺得，我是一個喜歡合作的人？"
  },
  AvgDialog_142853_Content_84 = {
    Text = "弱者們總是習慣抱團，你當然不是那樣的人。但，每個人都會有合作的需求，你也不例外。"
  },
  AvgDialog_142853_Content_85 = {
    Text = "蘿坦尚未回話，無數個一模一樣的幻影出現在鬥獸場的座位上，占滿了密密麻麻的觀眾席，鯨歌般的聲音再次傳遍這座空曠的鬥獸場。"
  },
  AvgDialog_142853_Content_86 = {
    Text = "好了，挑戰者們，我們已經等不及了。最後的試煉，即將在這座輝煌的鬥獸場展開！"
  },
  AvgDialog_142853_Content_87 = {
    Text = "當最後的優勝者脫穎而出，一扇通往星天之鯨宮殿的門將為他打開！"
  },
  AvgDialog_142853_Content_88 = {
    Text = "那扇門後，是無盡的榮耀、財富、權力——一切！"
  },
  AvgDialog_142853_Content_89 = {
    Text = "選出優勝者……規則是什麼？"
  },
  AvgDialog_142853_Content_9 = {
    Text = "在你對著古老的石座自言自語的時候，蘿坦向巨大廣場的中心走了過去。"
  },
  AvgDialog_142853_Content_90 = {
    Text = "規則？呵呵呵……哈哈哈哈！規則？！……"
  },
  AvgDialog_142853_Content_91 = {
    Text = "幻影們誇張的笑聲震痛了鬥獸場內所有人的耳膜。癲狂的笑聲裡，他們不再言語，期待地望向空曠的鬥獸場中央。"
  },
  AvgDialog_142853_Content_92 = {
    Text = "可是……他還沒有說規則是什麼呢……"
  },
  AvgDialog_142853_Content_93 = {
    Text = "他已經說了。「最後的優勝者」，只有一位。這就是唯一的規則，小麻雀。"
  },
  AvgDialog_142853_Content_94 = {
    Text = "殺戮，挑戰，結盟，背叛……十八名參賽者，只有一個站著的人，可以通過那扇大門。"
  },
  AvgDialog_142853_Content_95 = {
    Text = "埃利安臉上重新掛起那個你熟悉的微笑。"
  },
  AvgDialog_142853_Content_96 = {
    Text = "你要面對的，將是這個世界上最強大的一批人。"
  },
  AvgDialog_142853_Content_97 = {
    Text = "請不要誤會，我絲毫不質疑你的力量，蘿坦女士。"
  },
  AvgDialog_142853_Content_98 = {
    Text = "但我想，你也並不想在享受那些愉悅的殺戮時，被無聊的人打擾了興致吧？"
  },
  AvgDialog_142853_Content_99 = {
    Text = "蘿坦第一次認真抬起頭。她看見一張溫和微笑的臉，以及臉上那雙彷彿能洞察一切的眼睛。"
  },
  AvgDialog_142854_Content_1 = {
    Text = "王冠之輕"
  },
  AvgDialog_142854_Content_10 = {
    Text = "蘿……蘿坦大人？"
  },
  AvgDialog_142854_Content_11 = {
    Text = "你無法辨認眼前這個渾身是血的人是不是蘿坦。"
  },
  AvgDialog_142854_Content_12 = {
    Text = "骯髒的、腐壞的血覆滿她的身體，不知道是來自於她自己還是別的什麼。"
  },
  AvgDialog_142854_Content_13 = {
    Text = "在那骯髒的血與破碎的盔甲之下，她的半個身子都只剩下森森白骨。"
  },
  AvgDialog_142854_Content_14 = {
    Text = "只剩半邊身體的戰士走出那片腥氣瀰漫的裂隙。她的步伐緩慢、疲憊，斷裂的巨劍拖在地上，在血泊中劃出一道淺淺的溝痕。"
  },
  AvgDialog_142854_Content_15 = {
    Text = "在她的另一隻手上，那個由鮮血凝成的皇冠，正滴落著骯髒的血。"
  },
  AvgDialog_142854_Content_17 = {
    Text = "蘿……蘿坦大人……星天之鯨……祂……"
  },
  AvgDialog_142854_Content_18 = {
    Text = "祂輸了。"
  },
  AvgDialog_142854_Content_19 = {
    Text = "蘿坦的聲音沒有任何的顫動，彷彿只是在訴說一件必定發生的事。"
  },
  AvgDialog_142854_Content_20 = {
    Text = "您與祂簽訂了契約……如果祂受到傷害，您也……"
  },
  AvgDialog_142854_Content_21 = {
    Text = "你不需要再問下去。蘿坦身上的傷已經說明了一切。"
  },
  AvgDialog_142854_Content_22 = {
    Text = "蘿坦大人，您戰勝了所有的挑戰者，甚至……甚至是星天之鯨！"
  },
  AvgDialog_142854_Content_23 = {
    Text = "現在，您是這個星球毋庸置疑的王……現在，是您人生最輝煌的時刻！現在……"
  },
  AvgDialog_142854_Content_24 = {
    Text = "現在，也是她最脆弱的時刻。"
  },
  AvgDialog_142854_Content_25 = {
    Text = "從裂隙中滲出的血腥味包裹著你，鯨歌般的低語在你的耳邊越來越清晰。"
  },
  AvgDialog_142854_Content_26 = {
    Text = "看呐，鮮血凝成的王冠……"
  },
  AvgDialog_142854_Content_27 = {
    Text = "六國的王座，千萬人的臣服，永不枯竭的財富與榮耀……那頂王冠能給予它的主人一切。"
  },
  AvgDialog_142854_Content_28 = {
    Text = "鬥獸場裡每一個人都在渴望它。那些天天打罵你的騎士，格拉古，沃恩姐妹，阿利什將軍，無所不能的埃利安老爺……"
  },
  AvgDialog_142854_Content_29 = {
    Text = "還有你，小麻雀。你也在渴望它……"
  },
  AvgDialog_142854_Content_3 = {
    Text = "這是……"
  },
  AvgDialog_142854_Content_30 = {
    Text = "你望著蘿坦手中的那頂猩紅的王冠。每一滴鮮血滴落，星天之鯨的低語都更加地清晰。"
  },
  AvgDialog_142854_Content_31 = {
    Text = "你永遠不用再作為奴隸活著了，小麻雀。"
  },
  AvgDialog_142854_Content_32 = {
    Text = "你會為你的母親修建一座宏偉的陵墓。你會把你的兄弟從馬圈裡接出來，與他們一同住進輝煌的宮殿。"
  },
  AvgDialog_142854_Content_33 = {
    Text = "曾經欺辱你們的那些人，會跪在你的面前，親吻你的腳背。"
  },
  AvgDialog_142854_Content_34 = {
    Text = "權力。無上的權力。"
  },
  AvgDialog_142854_Content_35 = {
    Text = "那些流淌在傳說裡的名字，都為之而死……而現在，它就在你的眼前，近在咫尺。"
  },
  AvgDialog_142854_Content_36 = {
    Text = "去吧，小麻雀。在你這一生裡，這是你唯一的機會！"
  },
  AvgDialog_142854_Content_37 = {
    Text = "耳語變成了轟鳴，一股強烈的衝動在你的腦海中湧動。發乾的喉嚨滾動，你顫抖的手舉起了那把埃利安留下的、綴著珠寶的匕首。匕首的刀身上，還沾著你自己的血。"
  },
  AvgDialog_142854_Content_38 = {
    Text = "乾澀的喉嚨滾動，你顫抖的手舉起了那把埃利安留下的、綴著珠寶的匕首。匕首的刀身上，還沾著你自己的血。"
  },
  AvgDialog_142854_Content_39 = {
    Text = "你已經抵達了這裡，為什麼不能再向前一步？那是屬於你的……王冠本就是屬於你的……"
  },
  AvgDialog_142854_Content_4 = {
    Text = "你從滿地的塵土中爬起來，抖落身上的砂礫，花了幾秒鐘時間回憶起了自己現在身在何處。"
  },
  AvgDialog_142854_Content_40 = {
    Text = "<Red:殺了她？……殺了她……殺了她……殺了她！！！>"
  },
  AvgDialog_142854_Content_41 = {
    Text = "三步。你距離那無上的榮耀，距離只有三步……"
  },
  AvgDialog_142854_Content_42 = {
    Text = "<ShakeRed:（我要……殺了她……！）>"
  },
  AvgDialog_142854_Content_43 = {
    Text = "在你鼓足勇氣打算邁出第一步的時候，蘿坦回過頭來。那雙疲倦的眼睛，平靜地望向你。"
  },
  AvgDialog_142854_Content_44 = {
    Text = "在被那目光注視的一瞬間，所有支撐著你的耳語同時消失，你沸騰的血液瞬間冷了下來。"
  },
  AvgDialog_142854_Content_45 = {
    Text = "<Shake:蘿……蘿坦大人……抱歉……>"
  },
  AvgDialog_142854_Content_47 = {
    Text = "蘿坦的眼睛裡沒有絲毫的殺意。看著那雙眼睛，你忽然明白，如果不是為了見到星天之鯨，這裡沒有任何一個人值得她動手。"
  },
  AvgDialog_142854_Content_48 = {
    Text = "那是一個正在俯視螻蟻們為了一個糖塊而爭鬥的人的眼神。除此之外，再也沒有多餘的情緒。"
  },
  AvgDialog_142854_Content_49 = {
    Text = "螻蟻們的故事，從未變化過。她揚起那隻已成白骨的手，隨意地將手裡的東西放在你的頭上。"
  },
  AvgDialog_142854_Content_5 = {
    Text = "鬥獸場的石壁像紙一樣碎裂開來，巨大的石塊從看台上砸落，那些幻影觀眾最後的殘影早已消失不見。"
  },
  AvgDialog_142854_Content_50 = {
    Text = "！！！這是……"
  },
  AvgDialog_142854_Content_51 = {
    Text = "溫熱的、骯髒的血跡從你的頭頂滴落。你伸出手，在自己的頭上，摸到了那頂鮮血匯成的、冰涼黏膩的王冠。"
  },
  AvgDialog_142854_Content_52 = {
    Text = "無數英雄為之殺戮，無數的人性為之墮落。六國的權力與財富，無上的尊貴與榮耀，此刻就輕飄飄地戴在你的頭頂。"
  },
  AvgDialog_142854_Content_53 = {
    Text = "最終的勝利者將它隨手扔給了你，如同將一塊糖塞進孩子貪婪的嘴——現在，你擁有一切了。"
  },
  AvgDialog_142854_Content_54 = {
    Text = "蘿坦大人……您……您……"
  },
  AvgDialog_142854_Content_55 = {
    Text = "幫我一個忙。"
  },
  AvgDialog_142854_Content_56 = {
    Text = "我要去找新的對手了。在那之前，我需要一對新的劍。"
  },
  AvgDialog_142854_Content_57 = {
    Text = "蘿坦望著自己手中那對陪伴自己多年的巨劍，將它們殘破的屍體收進劍鞘。"
  },
  AvgDialog_142854_Content_58 = {
    Text = "她轉過身，拖著殘破的身軀，疲憊、緩慢地向前走去，走向下一個你無法理解的終點。"
  },
  AvgDialog_142854_Content_59 = {
    Text = "在你身後的裂隙中，古老的符文逐一熄滅，那個正在崩解腐化的神祇，露出你從未見過的欣慰笑容。"
  },
  AvgDialog_142854_Content_6 = {
    Text = "你趴在滿是碎石的地面上，耳朵裡嗡鳴不止。那道維度裂隙懸在鬥獸場中央，邊緣正在劇烈地抽搐，像是一道猙獰的傷口。"
  },
  AvgDialog_142854_Content_60 = {
    Text = "替我……記住她的名字。"
  },
  AvgDialog_142854_Content_61 = {
    Text = "鮮血順著你的頭顱與臉龐滴落，身下的血泊映照著你茫然無措的眼。"
  },
  AvgDialog_142854_Content_62 = {
    Text = "頭頂的王冠很重、很重。一萬兩千年欲望的重量讓你跪在血泊中，望著那個漸行漸遠的身影，久久無法起身。"
  },
  AvgDialog_142854_Content_63 = {
    Text = "頭頂的王冠很輕、很輕，輕得似乎從未存在過。"
  },
  AvgDialog_142854_Content_7 = {
    Text = "一聲低沉、綿長的悲鳴從傷口中傳來，穿透你的顱骨直抵腦海的深處，沉重得如同一座星球的嘆息。"
  },
  AvgDialog_142854_Content_8 = {
    Text = "那聲音……是星天之鯨？！"
  },
  AvgDialog_142854_Content_9 = {
    Text = "裂隙中散發出強烈的、令人作嘔的血腥味。在你準備向它緩緩靠近時，一隻只剩白骨的腳從裂隙中邁了出來。"
  },
  AvgDialog_142888_Content_1 = {Text = "謊"},
  AvgDialog_142888_Content_10 = {
    Text = "你沒有辦法回答，你的記憶現在亂得像一隻在泥地裡打了三圈滾的長毛狗。"
  },
  AvgDialog_142888_Content_100 = {
    Text = "漫過胸口、漫過耳廓、漫過……"
  },
  AvgDialog_142888_Content_102 = {
    Text = "你猛然回過神，遠處，結束訓練的奧吉爾、蘿坦、拉蒙娜向你走來，朵爾的分身人偶正在分析他們的訓練數據。"
  },
  AvgDialog_142888_Content_103 = {
    Text = "身旁的人十分遺憾地嘆了口氣。"
  },
  AvgDialog_142888_Content_104 = {
    Text = "別擔心，我會一直替你保留這個選擇。"
  },
  AvgDialog_142888_Content_105 = {
    Text = "身邊已然空無一人，夕陽將垂的天際線折射出少許迷幻的柔和珠光。"
  },
  AvgDialog_142888_Content_107 = {
    Text = "你還有很多話想說。關於那場沒有任何針對性，只是N出於玩心蠱惑教徒引發的災難。"
  },
  AvgDialog_142888_Content_108 = {
    Text = "關於提燈教會在其中的推波助瀾，關於龐托斯後來百十年間各種瘋狂的報復行動。"
  },
  AvgDialog_142888_Content_109 = {
    Text = "關於……他是否有一個瞬間，也為另一個可能性動搖過，所以讓歲月在他身上留下了記號。"
  },
  AvgDialog_142888_Content_11 = {
    Text = "同樣因為之前的戰鬥幾乎力竭的蕾莎，努力撐起身，擋在了你和龐托斯之間。"
  },
  AvgDialog_142888_Content_110 = {
    Text = "關於雅格和蕾莎，現在是不是仍舊在厄波揚斯狂歡。"
  },
  AvgDialog_142888_Content_111 = {
    Text = "……最終你只想祈禱他不要在學校裡跟德克斯特教授發生點什麼。"
  },
  AvgDialog_142888_Content_112 = {
    Text = "你搖搖頭，毫不猶豫地向朋友們的身旁走去。"
  },
  AvgDialog_142888_Content_12 = {
    Text = "龐托斯，結束了。"
  },
  AvgDialog_142888_Content_13 = {
    Text = "還活著的人，如果留在厄波揚斯，要以遺忘厄波揚斯外的記憶為代價。"
  },
  AvgDialog_142888_Content_14 = {
    Text = "而像我這種已經死去，被重塑為魇的人，最後所有的記憶都會被緩慢侵蝕。"
  },
  AvgDialog_142888_Content_15 = {
    Text = "雅格已經做出了他的選擇，我也做出了我的……\n讓我們離開吧。"
  },
  AvgDialog_142888_Content_16 = {
    Text = "龐托斯的嘴唇抿成一條冷漠的線，腮幫繃緊。"
  },
  AvgDialog_142888_Content_17 = {
    Text = "你應該還記得，你依托厄波揚斯而存在。離開厄波揚斯，你會死。"
  },
  AvgDialog_142888_Content_18 = {
    Text = "對，但我過去的記憶也會回來。我會作為一個人類死去，這是唯一的辦法。"
  },
  AvgDialog_142888_Content_19 = {
    Text = "我已經……不記得你和雅格小時候的樣子了，至少，在我完全忘記你們之前。"
  },
  AvgDialog_142888_Content_2 = {
    Text = "令人窒息的威壓如潮水般褪去，你的大腦傳來劇烈刺痛，眼前一陣陣發白。"
  },
  AvgDialog_142888_Content_20 = {
    Text = "龐托斯僵在了原地，第一次，你看到他臉上出現了如此悲傷的表情。"
  },
  AvgDialog_142888_Content_21 = {
    Text = "……我真希望我能說那股力量還在控制著我。"
  },
  AvgDialog_142888_Content_22 = {
    Text = "他閉上眼，彷彿想要從他不想面對的事情裡躲開。最後，他露出了一個自嘲且頹然的笑。"
  },
  AvgDialog_142888_Content_23 = {
    Text = "那樣我就可以理直氣壯地違背你們的意願，對你們行惡。"
  },
  AvgDialog_142888_Content_25 = {
    Text = "龐托斯在沉默裡妥協了，那輛載著他向敵人復仇的戰車，如今也為蕾莎送行。"
  },
  AvgDialog_142888_Content_26 = {
    Text = "散發著無可名狀珠光的車體滑入厄波揚斯以外天空的瞬間，蕾莎臉上出現了釋然的笑容，她回頭看向你們——"
  },
  AvgDialog_142888_Content_27 = {
    Text = "然後，徹底消失在了夜晚的海風中。"
  },
  AvgDialog_142888_Content_28 = {
    Text = "你們都沒有開口，只是長久地凝望著那片虛無，直到龐托斯打破了這種沉默。"
  },
  AvgDialog_142888_Content_29 = {
    Text = "你離開厄波揚斯之後的生活，「你」的生活，是什麼樣？"
  },
  AvgDialog_142888_Content_30 = {
    Text = "你沒有想到他的第一句話會是這個，愣了愣，才開始整理那些紛雜的回憶。"
  },
  AvgDialog_142888_Content_31 = {
    Text = "這次密境好像出了些問題，不論是雅格還是%player%的記憶，都不太完全。"
  },
  AvgDialog_142888_Content_32 = {
    Text = "……我記不清了，我的腦子裡現在既有作為雅格的記憶，也有作為遙遠的地方、另外一個人的記憶，所有的記憶都很混亂。"
  },
  AvgDialog_142888_Content_33 = {
    Text = "你下意識將手伸進口袋，去撫摸那隻草蜢。"
  },
  AvgDialog_142888_Content_34 = {
    Text = "不過，雖然很平凡、很普通、忙忙碌碌，日復一日，但也很幸福。"
  },
  AvgDialog_142888_Content_35 = {
    Text = "幸福到足夠讓我成為我，足夠讓我無論如何都想回去。"
  },
  AvgDialog_142888_Content_36 = {
    Text = "他靜靜地凝視著你的眼睛，彷彿、就像……蕾莎看著你的時候那樣。"
  },
  AvgDialog_142888_Content_37 = {
    Text = "<Red:他不止是在看著雅格。>"
  },
  AvgDialog_142888_Content_38 = {
    Text = "你們想錯了，雅格……<Red:%player%>。"
  },
  AvgDialog_142888_Content_39 = {
    Text = "！！！？"
  },
  AvgDialog_142888_Content_4 = {
    Text = "孑然一身的龐托斯站在原地，你看不清他的表情。"
  },
  AvgDialog_142888_Content_40 = {
    Text = "什麼？！"
  },
  AvgDialog_142888_Content_41 = {
    Text = "你悚然一驚，為什麼龐托斯會知道<Red:「你」>的名字，這不只是一個密境嗎？"
  },
  AvgDialog_142888_Content_42 = {
    Text = "他又回到了那種冷淡的、矜貴的姿態，好像什麼都沒有脫離掌控，平靜地露出笑容。"
  },
  AvgDialog_142888_Content_43 = {
    Text = "我知道<Red:「你」>一直在這裡，我知道<Red:「你」>就是「他」，從<Red:「你」>小時候，我就知道<Red:「你」>與眾不同。"
  },
  AvgDialog_142888_Content_44 = {
    Text = "沉悶的、屬於海水的噪音再次沒過你的耳畔。"
  },
  AvgDialog_142888_Content_45 = {
    Text = "你們還太小，太蒙昧，誤以為那種庸常就叫作幸福。"
  },
  AvgDialog_142888_Content_46 = {
    Text = "這次，我不會再犯把選擇權交給你們自己的<Red:「錯誤」>了。"
  },
  AvgDialog_142888_Content_47 = {
    Text = "你們弄錯了，他沒有妥協，他不會，也絕不準備放手，他只是放下了一個餌。"
  },
  AvgDialog_142888_Content_48 = {
    Text = "他早就發現了另一部分的「你」，他要找到「你」，他不容許再有任何意外。"
  },
  AvgDialog_142888_Content_49 = {
    Text = "太輕易了，那場戰鬥，那場勝利。\n那是一個要釣出<Red:「你」>的陷阱。"
  },
  AvgDialog_142888_Content_5 = {
    Text = "但顯然，有些東西已經從他身上離開了。"
  },
  AvgDialog_142888_Content_50 = {
    Text = "無論要付出怎樣的代價，無論要向怎樣的存在宣誓效忠……"
  },
  AvgDialog_142888_Content_51 = {
    Text = "我都會讓厄波揚斯的狂歡永遠持續下去。"
  },
  AvgDialog_142888_Content_52 = {
    Text = "沒有人知道，為什麼他突然允許衰老在自己身上發生。"
  },
  AvgDialog_142888_Content_53 = {
    Text = "整個厄波揚斯都在和他一同搖晃，四周的所有介質與他胸口湧動出的海水，不分彼此地相互交融。"
  },
  AvgDialog_142888_Content_54 = {
    Text = "或許有朋友，或許有敵人，無數隻黑色的胳膊從他的胸膛探出，撕扯撫摸著他的皮膚。"
  },
  AvgDialog_142888_Content_55 = {
    Text = "像是想逃離，又像是要永遠和他相聚。"
  },
  AvgDialog_142888_Content_56 = {
    Text = "我在一條早就沒有辦法回頭的道路上，我也不需要回頭。"
  },
  AvgDialog_142888_Content_57 = {
    Text = "那些未曾經歷的時光根本無關緊要，在厄波揚斯，它們可控，溫順，不會帶來傷害。"
  },
  AvgDialog_142888_Content_58 = {
    Text = "真遺憾，我暫時還沒有辦法把你留下，我們的時間已經到了，<Red:%player%>。"
  },
  AvgDialog_142888_Content_6 = {
    Text = "給我一個理由。"
  },
  AvgDialog_142888_Content_60 = {
    Text = "失重感拽著你從被撕裂的空間中，高拋而起。\n遮天蔽日的魘展開膜翅，撲簌向你湧來。"
  },
  AvgDialog_142888_Content_61 = {
    Text = "放心，我們很快就會再見的。"
  },
  AvgDialog_142888_Content_62 = {
    Text = "我和厄波揚斯，會永遠等待著你的歸來。"
  },
  AvgDialog_142888_Content_63 = {
    Text = "歲月的痕跡如風化般漫過了龐托斯的身體。"
  },
  AvgDialog_142888_Content_64 = {
    Text = "他大笑著，在迅速離你遠去的厄波揚斯向你舉杯。"
  },
  AvgDialog_142888_Content_65 = {
    Text = "沒入黑暗前的最後一瞥，你看見了站在他身旁的兩個身影。"
  },
  AvgDialog_142888_Content_66 = {
    Text = "他沒有放過任何人，他留住了所有人。"
  },
  AvgDialog_142888_Content_67 = {
    Text = "<Red:那是蕾莎，和年輕時的雅格。>"
  },
  AvgDialog_142888_Content_69 = {
    Text = "誒？！後來呢，後來呢？守密人不會摔死了吧！"
  },
  AvgDialog_142888_Content_7 = {
    Text = "他聲音嘶啞，身體卻依然緊繃著，像某種窮途末路的獸類。"
  },
  AvgDialog_142888_Content_70 = {
    Text = "龐托斯叔叔好壞啊！不可以這樣！"
  },
  AvgDialog_142888_Content_71 = {
    Text = "就是，怎麼這麼壞啊龐托斯！"
  },
  AvgDialog_142888_Content_72 = {
    Text = "你正氣勢洶洶地跟奧瑞塔嘀嘀咕咕在夢境中的經歷，一扭頭……"
  },
  AvgDialog_142888_Content_73 = {
    Text = "就被同樣興致勃勃插著兜在門邊不知道聽了多久的某人嚇了一跳。"
  },
  AvgDialog_142888_Content_74 = {
    Text = "故事的後來，小雅格順利地離開了，從夢裡睜開眼。"
  },
  AvgDialog_142888_Content_75 = {
    Text = "他發現自己正躺在家中的床上，他愛著的人們圍繞在他身邊。"
  },
  AvgDialog_142888_Content_76 = {
    Text = "故事的另一個主人公靠在奧瑞塔臥室的牆邊，聲音低沉和緩地補上了故事的結尾。"
  },
  AvgDialog_142888_Content_77 = {
    Text = "他想起了一生所有的記憶，安詳地閉上了雙眼，去了一個幸福的地方。"
  },
  AvgDialog_142888_Content_78 = {
    Text = "奧瑞塔心滿意足地發出小小的鼻息聲，逐漸迷迷糊糊睡了過去，就和你記憶裡的薇拉一樣。"
  },
  AvgDialog_142888_Content_79 = {
    Text = "龐托斯向門外，做了一個象徵邀請的手勢。"
  },
  AvgDialog_142888_Content_8 = {
    Text = "為什麼，為什麼連你也要離開，為什麼寧願投向死亡，而不是——"
  },
  AvgDialog_142888_Content_80 = {
    Text = "我想，你應該會想和我談談？"
  },
  AvgDialog_142888_Content_82 = {
    Text = "久別重逢，真是個不錯的詞。"
  },
  AvgDialog_142888_Content_83 = {
    Text = "你沒有告訴奧瑞塔真正的結尾，你說謊了，對吧？"
  },
  AvgDialog_142888_Content_84 = {
    Text = "你放走蕾莎是個謊言，從厄波揚斯離開的，也只有我，沒有雅格。"
  },
  AvgDialog_142888_Content_85 = {
    Text = "被直截了當地打斷，龐托斯並不氣惱，咧開嘴挑了挑眉弓。"
  },
  AvgDialog_142888_Content_86 = {
    Text = "當然，顯然。有些故事，是不適合說給孩子們聽的，不是嗎？"
  },
  AvgDialog_142888_Content_87 = {
    Text = "你現在……這幅容貌，也只是為了告訴所有人，你錯過的衰老沒什麼了不起的。"
  },
  AvgDialog_142888_Content_88 = {
    Text = "因為你可以掌控所有事，包括時間、包括衰老、包括其他人的人生，對吧？"
  },
  AvgDialog_142888_Content_89 = {
    Text = "大概是你話語中的火藥味太過明顯，龐托斯沒有正面回答，只是笑得讓你非常火大。"
  },
  AvgDialog_142888_Content_90 = {
    Text = "誰知道呢，說不定我只是想嘗試一些新事物。"
  },
  AvgDialog_142888_Content_91 = {
    Text = "總之，很高興你想起來了，從我第一次來到彌薩格，我就一直在期待這一天。"
  },
  AvgDialog_142888_Content_92 = {
    Text = "厄波揚斯的一切都還等待著你，%player%。"
  },
  AvgDialog_142888_Content_93 = {
    Text = "……如果你需要提醒的話，彌薩格有一套完整的安保系統。"
  },
  AvgDialog_142888_Content_94 = {
    Text = "不用這麼緊張。"
  },
  AvgDialog_142888_Content_95 = {
    Text = "說起來，我很好奇。不再是雅格的，彌薩格的小朋友，你有答案了嗎？"
  },
  AvgDialog_142888_Content_96 = {
    Text = "龐托斯略微側過頭，你看向他深藍色的眼睛。"
  },
  AvgDialog_142888_Content_97 = {
    Text = "如果我再給你一次選擇的機會，你會選擇永葆青春的永生，還是一生所創造的記憶？"
  },
  AvgDialog_142888_Content_98 = {
    Text = "海水聲、翅膀的翕動聲。"
  },
  AvgDialog_142888_Content_99 = {
    Text = "熟悉而遙遠的白噪音再一次緩慢地浸潤過身軀。"
  },
  AvgDialog_142889_Content_10 = {
    Text = "你長大就會知道了，我們總會再見面的，當我們分開時，我會一直想念你。"
  },
  AvgDialog_142889_Content_100 = {
    Text = "他嘆了口氣，露出了理所當然的笑容，和另一個聲音一起說出了後半句話。"
  },
  AvgDialog_142889_Content_101 = {
    Text = "你在說什麼呢，這裡是厄波揚斯，這裡沒有衰老，我們會永遠狂歡，永遠年輕。"
  },
  AvgDialog_142889_Content_102 = {
    Text = "從奧爾尼身後走出的身影，嗓音低啞，如同一位最為寬厚而威嚴的長者。"
  },
  AvgDialog_142889_Content_103 = {
    Text = "那不是龐托斯的聲音。"
  },
  AvgDialog_142889_Content_104 = {
    Text = "祂古老到讓那些曾經的熟悉感一掃而空，只剩下海洋<Red:最深處>，海水的迴響將你的意識再次滌蕩。"
  },
  AvgDialog_142889_Content_105 = {
    Text = "是的，是的，這裡是厄波揚斯，我已經回到了厄波揚斯。"
  },
  AvgDialog_142889_Content_106 = {
    Text = "<Shake:<Red:我們會永遠狂歡。>>"
  },
  AvgDialog_142889_Content_107 = {
    Text = "<Red:我們會永遠年輕。>"
  },
  AvgDialog_142889_Content_108 = {
    Text = "你是這麼的快樂，這麼的輕鬆，你在厄波揚斯。"
  },
  AvgDialog_142889_Content_110 = {
    Text = "不過，不知道為什麼，你沒有讓任何人看到那隻你忘記了名字的草蜢。"
  },
  AvgDialog_142889_Content_12 = {
    Text = "在羅盤剛剛離開你的那個瞬間，窗外傳來了一陣密集的輕響。"
  },
  AvgDialog_142889_Content_13 = {
    Text = "緊接著，是一聲輕笑。"
  },
  AvgDialog_142889_Content_14 = {
    Text = "讓我看看這個漂亮小伙子是誰——"
