  AvgDialog_142890_Content_52 = {
    Text = "我想，<Red:「我」>已經做出了選擇。"
  },
  AvgDialog_142890_Content_53 = {
    Text = "從識海深處，一道靈性掙扎而出。"
  },
  AvgDialog_142890_Content_54 = {
    Text = "從阿庫特大爆炸中存活，作為<Red:「彌薩格守密人」>的「你」，接管了這具軀體。"
  },
  AvgDialog_142890_Content_55 = {
    Text = "銀色的光輝於你掌中閃爍。"
  },
  AvgDialog_142890_Content_56 = {
    Text = "屬於雅格的，雜亂的記憶被一點點撿回。"
  },
  AvgDialog_142890_Content_57 = {
    Text = "你知道嗎，龐托斯舅舅，我第一件想起的，居然是一件很無關緊要的事。"
  },
  AvgDialog_142890_Content_59 = {
    Text = "「龐托斯」沒有開口，他沉默地打量著你。"
  },
  AvgDialog_142890_Content_6 = {
    Text = "是有意義的，那些記憶。"
  },
  AvgDialog_142890_Content_60 = {
    Text = "十八歲那一年，奧爾尼和「我」偷溜上最近的輪船底艙，死皮賴臉地替水手幫工，坐了一次免費的遊輪。"
  },
  AvgDialog_142890_Content_61 = {
    Text = "第二天清早，我們看到了當時所見過的，最美的一輪日出。奧爾尼說，希望太陽永不落下，但我不是這麼想的。"
  },
  AvgDialog_142890_Content_62 = {
    Text = "因為太陽會落山，一天會結束，所以我們每天經歷的事情才格外珍貴。"
  },
  AvgDialog_142890_Content_63 = {
    Text = "不要再說傻話了，在厄波揚斯，只要你想，我可以讓太陽隨你的意願升起或落下。"
  },
  AvgDialog_142890_Content_64 = {
    Text = "他厭倦地閉起眼睛，終於失去了耐心，你堅定地搖了搖頭。"
  },
  AvgDialog_142890_Content_65 = {
    Text = "重要的是我們所經歷的時間，而不是永遠高懸的太陽。"
  },
  AvgDialog_142890_Content_66 = {
    Text = "抱歉，龐托斯。"
  },
  AvgDialog_142890_Content_67 = {
    Text = "他抬了抬手，魘牆再度向你壓來。"
  },
  AvgDialog_142890_Content_68 = {
    Text = "去吧，僕從們。"
  },
  AvgDialog_142890_Content_7 = {
    Text = "不是對別人，而是對我自己。"
  },
  AvgDialog_142890_Content_8 = {
    Text = "我想知道我度過了怎樣的一生，失去記憶後，為什麼怎樣的快樂都讓我覺得若有所失。"
  },
  AvgDialog_142890_Content_9 = {
    Text = "那隻草蜢的刺輕扎著你的指尖，你莫名想起了那個在床邊哭泣的孩子的身影。"
  },
  AvgDialog_142891_Content_10 = {
    Text = "它叫——唔，它叫薇拉，因為薇拉是爺爺取的，是最好的名字。"
  },
  AvgDialog_142891_Content_100 = {
    Text = "祂的怒火會燒毀你們，唯有歡愉能……@1！"
  },
  AvgDialog_142891_Content_102 = {
    Text = "鮮血濺出，你目瞪口呆地看著遠處的蕾莎和幾位旅館的常客，驅使著與你們身下相同的生物作戰。"
  },
  AvgDialog_142891_Content_103 = {
    Text = "這些該詛咒的東西到底為什麼會跑到這來……\n算了，這應該是最後一隻了。"
  },
  AvgDialog_142891_Content_104 = {
    Text = "希望牠們只是路過……"
  },
  AvgDialog_142891_Content_105 = {
    Text = "蕾莎和同伴們離開了，你和龐托斯站在暗處，他緊托著你的後肩，你才沒有直接栽倒在地上。"
  },
  AvgDialog_142891_Content_106 = {
    Text = "你緊攥住他的衣角，他的聲音平和而輕緩，似乎在極力不給你增添驚嚇。"
  },
  AvgDialog_142891_Content_107 = {
    Text = "雅格，就和你看到的一樣……這種生靈叫作魇，我們驅使牠們為我們作戰。"
  },
  AvgDialog_142891_Content_108 = {
    Text = "他停頓了一下，手放在「魇」的身側，把指節捏得啪啪作響，彷彿在猶豫怎麼解釋，"
  },
  AvgDialog_142891_Content_109 = {
    Text = "我們是勇者冒險故事裡的主角，我是說，就像那些馭龍——只是我們馭的是魇的那種家族。"
  },
  AvgDialog_142891_Content_11 = {
    Text = "薇拉……爺爺需要休息，來爸爸這兒。"
  },
  AvgDialog_142891_Content_110 = {
    Text = "什……？！你在說什麼呢，龐托斯舅舅？！我們家明明只是開著一家旅店而已。"
  },
  AvgDialog_142891_Content_111 = {
    Text = "在……一場事故以後，這個族群只剩下了一小部分人，蕾莎為族群做了很多，大家也都很依賴她。"
  },
  AvgDialog_142891_Content_112 = {
    Text = "但她不想讓我們，尤其是你，接觸到這些，現在寂寂無名的日子就是她想讓我們過上的生活。"
  },
  AvgDialog_142891_Content_113 = {
    Text = "然而這個世界上還有許多邪惡的、醜陋的東西存在著，就和今天你看到的一樣，我不明白……"
  },
  AvgDialog_142891_Content_114 = {
    Text = "龐托斯難得地露出了有些煩躁的表情，順手將額前垂落的金髮理到腦後。"
  },
  AvgDialog_142891_Content_115 = {
    Text = "最近，「魇」找到了我，而且我能感受到祂們身後那種更強大的力量，祂選中了我，在呼喚我。"
  },
  AvgDialog_142891_Content_116 = {
    Text = "我可以做得更多，但蕾莎覺得只要躲好，那些怪物就和我們沒關係，一切就是安全的。"
  },
  AvgDialog_142891_Content_117 = {
    Text = "巨大的信息量讓你只能愣愣地眨巴著眼睛，你頭一次有這種每個單詞都明白，連在一起完全聽不懂的感覺。"
  },
  AvgDialog_142891_Content_118 = {
    Text = "龐托斯似乎也反應過來，回過神衝你笑了笑。"
  },
  AvgDialog_142891_Content_119 = {
    Text = "抱歉，雅格，我是不是一下說得太多了？"
  },
  AvgDialog_142891_Content_12 = {
    Text = "兒子有些擔心你的身體，想把孫女抱開，她癟了癟嘴，幾乎要哭出聲。"
  },
  AvgDialog_142891_Content_120 = {
    Text = "在蕾莎發現我們偷溜出來之前，先回去吧，我們還有很長時間來聊這個。"
  },
  AvgDialog_142891_Content_121 = {
    Text = "遠處，蕾莎似乎察覺到什麼動靜，往這邊看了一眼，龐托斯再次衝你比了個噤聲的手勢。"
  },
  AvgDialog_142891_Content_123 = {
    Text = "窗扉靜悄悄地打開，又靜悄悄地再次關上。"
  },
  AvgDialog_142891_Content_124 = {
    Text = "彷彿只是風曾吹開過窗戶，窗外，海浪拍打又退去，你聽到蕾莎從樓下走上來的聲音。"
  },
  AvgDialog_142891_Content_125 = {
    Text = "你們呼吸平穩地埋進枕頭，裝作這仍然是個普通的夜晚。"
  },
  AvgDialog_142891_Content_13 = {
    Text = "你笑著咳嗽了幾聲，努力支起這副脆弱的骨骼，靠在床頭。"
  },
  AvgDialog_142891_Content_14 = {
    Text = "薇拉，不要哭。外面的月色這麼美，把燈調暗一些吧。"
  },
  AvgDialog_142891_Content_15 = {
    Text = "爺爺還有時間再給你講個故事，讓我想想……"
  },
  AvgDialog_142891_Content_16 = {
    Text = "你的視線落在從未離身的那隻黃銅羅盤上，它並沒有被時光侵蝕，被月亮鍍上了一層毛絨絨的銀邊。"
  },
  AvgDialog_142891_Content_17 = {
    Text = "帶著懷念緩慢摩挲過它的表面，你聲音沙啞地陷入回憶。"
  },
  AvgDialog_142891_Content_18 = {
    Text = "那是……六十多年前，我還是個孩子的時候。"
  },
  AvgDialog_142891_Content_19 = {
    Text = "蕾莎，船馬上就要離港了，他還沒回來嗎？"
  },
  AvgDialog_142891_Content_20 = {
    Text = "看來實在無法當面道別了，請至少把這枚胸針……"
  },
  AvgDialog_142891_Content_21 = {
    Text = "港口的汽笛聲拉響，飾品的主人們叮呤咣啷留下了一大堆貼身首飾，滿臉遺憾地回到船隻上。"
  },
  AvgDialog_142891_Content_22 = {
    Text = "天啊，看在@3的份上，親愛的，你舅舅到底什麼時候能稍微學會不要有這麼多「朋友」？"
  },
  AvgDialog_142891_Content_23 = {
    Text = "你的媽媽蕾莎滿臉又是好笑，又是無奈地看著你，嘆了口氣把首飾塞進那個船隻下次靠岸時，會還給船長代為轉交的小盒子。"
  },
  AvgDialog_142891_Content_24 = {
    Text = "你家在海邊的小鎮上經營著一間再普通不過的小旅館，只有一件事稍微有些特殊……"
  },
  AvgDialog_142891_Content_25 = {
    Text = "讓我看看這個漂亮小伙子是誰——"
  },
  AvgDialog_142891_Content_26 = {
    Text = "大門帶著鹹味的風再次敞開，那件「特殊的事」大笑著把你攔腰兜住在空中甩了一圈。"
  },
  AvgDialog_142891_Content_27 = {
    Text = "龐托斯！說過多少次了，你會拽壞他的胳膊的！"
  },
  AvgDialog_142891_Content_28 = {
    Text = "龐托斯舅舅！"
  },
  AvgDialog_142891_Content_29 = {
    Text = "嗨，小雅格，看我給你帶了什麼好東西回來？"
  },
  AvgDialog_142891_Content_3 = {
    Text = "一輪你所見過的，最明亮的圓月掛在天上。你的四肢衰弱無力，思維也有些遲滯。"
  },
  AvgDialog_142891_Content_30 = {
    Text = "他打了個響指，五指在虛空中一張，一枚沉甸甸的鍍銅羅盤落在了你掌心。"
  },
  AvgDialog_142891_Content_31 = {
    Text = "這最好是從正當渠道弄來的，這個屋子裡已經裝不下更多「定情信物」和「破碎的心」了。"
  },
  AvgDialog_142891_Content_32 = {
    Text = "蕾莎揶揄地把那盒首飾扔給他，抬抬下巴，示意外面裝著另一半「破碎的心」的船剛離港。"
  },
  AvgDialog_142891_Content_33 = {
    Text = "唉呀……你知道的，我實在是不怎麼擅長拒絕別人。"
  },
  AvgDialog_142891_Content_34 = {
    Text = "龐托斯笑嘻嘻地側頭躲過了蕾莎的一記重擊，把你放到地上。"
  },
  AvgDialog_142891_Content_35 = {
    Text = "說起來，我認識了一些新朋友，我們可能得聊聊，蕾莎。"
  },
  AvgDialog_142891_Content_36 = {
    Text = "關於你不願意談的那些事。"
  },
  AvgDialog_142891_Content_37 = {
    Text = "你忙著研究手裡的新寶貝，錯過了蕾莎臉上有些難看的表情，龐托斯揉了揉你的腦袋。"
  },
  AvgDialog_142891_Content_38 = {
    Text = "我和媽媽有些事要談，如果我最喜歡的男子漢願意上樓玩一會兒的話，我會告訴他一些很棒的旅行見聞，成交？"
  },
  AvgDialog_142891_Content_39 = {
    Text = "他伸出五指，你看在羅盤的份上回應了他，那是一個專屬於你們的「成交握手」儀式。"
  },
  AvgDialog_142891_Content_4 = {
    Text = "抬起手，代表蒼老的紋路已然爬遍了你的皮膚。"
  },
  AvgDialog_142891_Content_41 = {
    Text = "你趴在樓上臥室的地板上，翻出了地圖，專心致志地嘗試用羅盤找那些航海故事裡的方向。"
  },
  AvgDialog_142891_Content_42 = {
    Text = "然而這幢房子太老了，海洋和風又一直在消磨它，依然會有幾句零星碎語從地板縫隙傳上來。"
  },
  AvgDialog_142891_Content_43 = {
    Text = "……們都已經……告訴……總不能……躲不是辦法。"
  },
  AvgDialog_142891_Content_44 = {
    Text = "……祂們……我可以……我的天賦……"
  },
  AvgDialog_142891_Content_45 = {
    Text = "龐托斯舅舅的語氣越來越急，你剛要好奇地把耳朵貼過去——"
  },
  AvgDialog_142891_Content_46 = {
    Text = "轟！咚！"
  },
  AvgDialog_142891_Content_47 = {
    Text = "門砰地一聲被推開，龐托斯被拽著領子扔了進來，蕾莎板起臉擺出一個意味著「沒得商量」的表情。"
  },
  AvgDialog_142891_Content_48 = {
    Text = "我不同意，龐托斯。我唯一的願望就是你們都平平安安活著……離你那些新朋友遠一點。"
  },
  AvgDialog_142891_Content_49 = {
    Text = "如果事情真的控制不住，我會帶你們離開這的。"
  },
  AvgDialog_142891_Content_5 = {
    Text = "啊，原來我已經到了這個年齡……今天或許就是最後一晚了。"
  },
  AvgDialog_142891_Content_50 = {
    Text = "嘿，蕾莎，我早就不是小孩子了！我們總不能一直逃跑下去。"
  },
  AvgDialog_142891_Content_51 = {
    Text = "先學著幫我處理生意，別成天在外面亂晃再說這個。"
  },
  AvgDialog_142891_Content_52 = {
    Text = "你很少聽到蕾莎用這麼嚴厲的聲音說話，她吸了口氣，勉強向你扯出一個笑容。"
  },
  AvgDialog_142891_Content_53 = {
    Text = "雅格，幫媽媽一個忙。看好你舅舅，至少今晚別再讓他出去亂轉了。"
  },
  AvgDialog_142891_Content_54 = {
    Text = "她扔下這些話，就匆匆忙忙地下樓去翻那些永遠翻不完的賬本了，似乎想要盡快結束這個話題。"
  },
  AvgDialog_142891_Content_55 = {
    Text = "龐托斯挑起眉毛，衝你聳了聳肩。"
  },
  AvgDialog_142891_Content_56 = {
    Text = "好吧，雅格，看來我們可以把故事時間稍微提前那麼一點。"
  },
  AvgDialog_142891_Content_58 = {
    Text = "或許是那些從船艙裡同貨物一起滾落出來的故事太過跌宕離奇，直到半夜，你睡得也並不沉。"
  },
  AvgDialog_142891_Content_59 = {
    Text = "窗外的月色在你的眼簾外鍍了一層銀，什麼東西遮住了它。"
  },
  AvgDialog_142891_Content_6 = {
    Text = "記憶逐漸回籠，但很奇怪，你的內心並沒有任何對於死亡的恐懼，而是因為發自內心的安寧而微笑了起來。"
  },
  AvgDialog_142891_Content_60 = {
    Text = "喀拉、是窗栓的聲響，你睜開眼，窗扇已經被完全拉開了。"
  },
  AvgDialog_142891_Content_62 = {
    Text = "龐托斯舅舅，你不能翻窗戶出去，媽媽會生氣的！"
  },
  AvgDialog_142891_Content_63 = {
    Text = "大半個龐托斯已經邁出了窗沿，你不假思索地要衝過去抱住他，甚至忘記了考慮為什麼他看上去像是……懸在空中。"
  },
  AvgDialog_142891_Content_65 = {
    Text = "失重感傳來，接著——"
  },
  AvgDialog_142891_Content_7 = {
    Text = "親人們簇擁在你身旁，最小的孫女薇拉還什麼都不知道，只是依戀地趴在你手邊。"
  },
  AvgDialog_142891_Content_70 = {
    Text = "你被提著後腰布料猛地拉起，奇怪的光滑皮毛觸感從你臉上拂過。"
  },
  AvgDialog_142891_Content_71 = {
    Text = "你睜開眼，如墜冰窟的戰慄猛然從脊椎竄向頭頂。"
  },
  AvgDialog_142891_Content_72 = {Text = "龐——"},
  AvgDialog_142891_Content_73 = {
    Text = "一頭完全沒有五官，無可名狀的詭異生靈的尾巴鉤在你的背後，尾梢密密麻麻地爬滿了醜惡的倒刺。"
  },
  AvgDialog_142891_Content_74 = {
    Text = "你顧不上顯然剛才是這個恐怖的東西救了你，不受控制地要從喉嚨擠出滯澀尖叫。"
  },
  AvgDialog_142891_Content_75 = {Text = "噓！"},
  AvgDialog_142891_Content_76 = {
    Text = "趴伏在這頭無面生靈身上的龐托斯一把將你抱了上去，死死捂住了你的嘴，生靈展開蝙蝠般的巨大翅膀，無聲地滑進夜幕。"
  },
  AvgDialog_142891_Content_77 = {
    Text = "別怕，祂們不會傷害你。"
  },
  AvgDialog_142891_Content_78 = {
    Text = "時間來不及了，雅格，別出聲，我之後再和你解釋。"
  },
  AvgDialog_142891_Content_79 = {
    Text = "龐托斯安撫似地環住你的肩膀，把你攏在生靈和自己之間，身形壓低，目光緊緊盯著海港偏僻處的礁石灘。"
  },
  AvgDialog_142891_Content_8 = {
    Text = "爺爺，你什麼時候能再陪我玩呀，你看，你上次教我的，我已經學會了。"
  },
  AvgDialog_142891_Content_80 = {
    Text = "你什麼都沒來得及問，從海中，不祥的聲音如同蠕蟲般爬了出來。"
  },
  AvgDialog_142891_Content_83 = {
    Text = "！……嘔……"
  },
  AvgDialog_142891_Content_84 = {
    Text = "先是佈滿鱗片的趾爪，接著是手臂，抑或柔軟扭曲的節肢，佈滿藤壺的軀體和褻神般可憎的黏液……"
  },
  AvgDialog_142891_Content_85 = {
    Text = "你從未想過帶來豐沛海貨的汪洋裡還生活著如此可詛咒的族群，他們凸起的恐怖瞳仁中滿是惡意，緊盯著鎮上的建築。"
  },
  AvgDialog_142891_Content_86 = {
    Text = "<Change>@4提普……所行之處……"
  },
  AvgDialog_142891_Content_87 = {
    Text = "<Change>……必經此地……餵飼融蝕、投身融蝕！肉、肉！！"
  },
  AvgDialog_142891_Content_89 = {
    Text = "下一秒，你們身下無面的有翼生物梭行向下，龐托斯展開骨節分明的手指，晦澀的光線撲向那兩隻可鄙的怪物。"
  },
  AvgDialog_142891_Content_9 = {
    Text = "她捧著一隻歪歪扭扭的草蜢，把它放在被子上。"
  },
  AvgDialog_142891_Content_91 = {
    Text = "祂們呆滯地滑脫在地上，彷彿兩尊斷開的石像。"
  },
  AvgDialog_142891_Content_92 = {
    Text = "啪，輕觸聲。"
  },
  AvgDialog_142891_Content_93 = {
    Text = "然後那兩半身軀撲向地面，化為捲入海風中的灰色齏粉。"
  },
  AvgDialog_142891_Content_94 = {
    Text = "呼，我就知道總有一兩個漏網之魚，蕾莎他們還是太粗心了。"
  },
  AvgDialog_142891_Content_95 = {
    Text = "<Shake:媽媽他們？龐托斯舅舅，這到底是怎麼回事？！>"
  },
  AvgDialog_142891_Content_96 = {
    Text = "你幾乎被嚇得雙腿發軟，快要從光滑的背上掉下去。"
  },
  AvgDialog_142891_Content_97 = {
    Text = "再等一等，我得先去確認祂們是不是順利。"
  },
  AvgDialog_142891_Content_98 = {
    Text = "龐托斯只是撫了撫你的肩膀，驅使那頭生物帶著你們向小鎮另一側的海岸線飛去。"
  },
  AvgDialog_142892_Content_1 = {
    Text = "當你不在"
  },
  AvgDialog_142892_Content_10 = {Text = "黃沙。"},
  AvgDialog_142892_Content_13 = {
    Text = "然後又回到夜晚。"
  },
  AvgDialog_142892_Content_14 = {
    Text = "這不是人類所能理解的旅途和軌跡，時間和空間都變得毫無意義，你們只是不斷穿行、巡梭，你體會一切再被一切摧毀。"
  },
  AvgDialog_142892_Content_15 = {
    Text = "祂們既然敢闖入，那就從現世把祂們驅逐，讓祂們畏懼我們，讓祂們記住我的名字！"
  },
  AvgDialog_142892_Content_16 = {
    Text = "龐托斯肆無忌憚地揮霍著他所取得的力量，那些獲得了他的存在如今也在撕裂他的敵人。"
  },
  AvgDialog_142892_Content_17 = {
    Text = "無數扭曲可憎的怪物，被他帶領著魘和馭魘者追獵，刺穿。"
  },
  AvgDialog_142892_Content_18 = {
    Text = "最終成為狂歡的一部分，引來無數歡慶的哨聲與大笑。"
  },
  AvgDialog_142892_Content_2 = {
    Text = "奇怪的光滑皮毛觸感，尾巴上鋒利的倒鉤，巨大的膜翅悄無聲息地劃開夜空。"
  },
  AvgDialog_142892_Content_20 = {
    Text = "你親眼看見龐托斯放出的光束讓這名狂信者成為齏粉，但緊接著，祂的軀體又再次重組，從口中發出恐懼的嚎啕。"
  },
  AvgDialog_142892_Content_21 = {
    Text = "祂是這一群狂信者中最虔誠的那一個，然而現在，祂已經經歷了不知多少次痛苦的死亡和重組。"
  },
  AvgDialog_142892_Content_22 = {
    Text = "龐托斯舅舅，祂是……在重生？"
  },
  AvgDialog_142892_Content_23 = {
    Text = "不，祂只是一次次在死而復生裡體會應許的痛苦。"
  },
  AvgDialog_142892_Content_24 = {
    Text = "偶爾，我也會放祂們去死，只要祂們放棄信奉那些褻瀆污穢的神。"
  },
  AvgDialog_142892_Content_25 = {
    Text = "但要是祂們的信仰太過堅定，就算是死亡也沒辦法幫祂們從痛苦裡解脫。"
  },
  AvgDialog_142892_Content_26 = {
    Text = "輕描淡寫得像只是在說一件小事，龐托斯手掌上抬，無形的力量讓狂信者雙臂展開，上身彎折，跪伏在龐托斯面前。"
  },
  AvgDialog_142892_Content_27 = {
    Text = "來，再告訴我一次，你依然信奉你那骯髒的神嗎？"
  },
  AvgDialog_142892_Content_28 = {
    Text = "<LightGray:*嗚咽>不……不，求求你，求求您，讓我死，只要您讓我死！"
  },
  AvgDialog_142892_Content_29 = {
    Text = "<Shake:哈哈哈，哈哈哈哈哈哈，沒有救主，根本就沒有救主，只有AB@2S，只有@2@3！！>"
  },
  AvgDialog_142892_Content_3 = {
    Text = "龐托斯帶著你加入了厄波揚斯每晚狂歡前的巡獵。"
  },
  AvgDialog_142892_Content_30 = {
    Text = "很好，獵物，抬起頭，露出你的喉嚨。"
  },
  AvgDialog_142892_Content_31 = {
    Text = "狂信者神智崩潰地發出扭曲的抽泣聲與狂笑聲，膝行向前，以詭異的姿態高抬起脖子。"
  },
  AvgDialog_142892_Content_32 = {
    Text = "我會把死亡施捨給你。"
  },
  AvgDialog_142892_Content_33 = {
    Text = "光像熱刀切開奶油一樣把祂的咽喉全然融化，祂的軀體驀地坍塌成灰土，被風捲入海洋。"
  },
  AvgDialog_142892_Content_34 = {
    Text = "這次，這個可悲的信徒沒有重生。"
  },
  AvgDialog_142892_Content_35 = {
    Text = "那些其他的，被抓住的狂信者會到哪裡去？"
  },
  AvgDialog_142892_Content_36 = {
    Text = "祂們也在厄波揚斯。"
  },
  AvgDialog_142892_Content_37 = {
    Text = "一個同樣永恆，但不那麼快樂的厄波揚斯。"
  },
  AvgDialog_142892_Content_38 = {
    Text = "在那裡，什麼都沒有，連痛苦都能算作獎勵。"
  },
  AvgDialog_142892_Content_39 = {
    Text = "你似懂非懂，月色披被在你們身上，魘護衛著你們，這場奇妙的旅途走向尾聲。"
  },
  AvgDialog_142892_Content_4 = {
    Text = "在無數難以辨明的介質中，厄波揚斯的人們追捕著無數維度中的「獵物」。"
  },
  AvgDialog_142892_Content_40 = {
    Text = "閉上眼睛，雅格。"
  },
  AvgDialog_142892_Content_41 = {
    Text = "濕潤的、熟悉的、緊密的黑暗擁抱了你，吞沒掉你。"
  },
  AvgDialog_142892_Content_42 = {
    Text = "你們回到了高屋，龐托斯從戰車上邁下，揭開又一輪狂歡的序幕。"
  },
  AvgDialog_142892_Content_43 = {
    Text = "這個孩子看上去很喜歡你。"
  },
  AvgDialog_142892_Content_44 = {
    Text = "靠近露台的窗沿，龐托斯撇開熱鬧的人群，向窗外那隻盤旋不去的魘伸出手。"
  },
  AvgDialog_142892_Content_45 = {
    Text = "雖然很多事不知道為什麼都記不清了，不過，龐托斯舅舅，你已經不是人類，這裡也不是我所理解的那個世界了，對吧？"
  },
  AvgDialog_142892_Content_46 = {
    Text = "我是已經死了嗎？"
  },
  AvgDialog_142892_Content_47 = {
    Text = "似乎沒有想到你會如此直接地問出這些話，龐托斯有些驚訝地挑起眉，然後——笑了出來。"
  },
  AvgDialog_142892_Content_48 = {
    Text = "我親愛的小朋友，當然不。"
  },
  AvgDialog_142892_Content_49 = {
    Text = "留在厄波揚斯，你會過上你小時候看故事書所嚮往的，偉大而不凡的一生，你再也不會被消磨。"
  },
  AvgDialog_142892_Content_5 = {
    Text = "高屋的玻璃裡依然跳動著奇異光暈，一隻隻魘在空中盤旋。"
  },
  AvgDialog_142892_Content_50 = {
    Text = "我們會去探險，會從俗世裡逃走，那些給我們的生活帶來劇變和災難的敵人，終將會被我們打擊得永遠不敢露頭。"
  },
  AvgDialog_142892_Content_51 = {
    Text = "你深吸了一口氣。你又摸到了那隻草蜢，拙劣、粗糙、有些扎手。"
  },
  AvgDialog_142892_Content_53 = {
    Text = "但我要付出的代價是什麼，龐托斯舅舅？"
  },
  AvgDialog_142892_Content_54 = {
    Text = "他的眉頭極緩慢地蹙起，帶著一種令你陌生的，矜貴的傲慢。"
  },
  AvgDialog_142892_Content_55 = {
    Text = "代價只是……一些根本不重要的東西，一些你不需要，也不會記住的東西。<Red:把它給我>，雅格。"
  },
  AvgDialog_142892_Content_56 = {
    Text = "話音剛落，魘帶著倒鉤的尾巴從窗外向你的口袋垂去。"
  },
  AvgDialog_142892_Content_57 = {
    Text = "伸向你口袋裡的草蜢。"
  },
  AvgDialog_142892_Content_59 = {
    Text = "你下意識地猛地後退，但這個舉動似乎激怒了龐托斯，他一把抓住了你的胳膊。"
  },
  AvgDialog_142892_Content_6 = {
    Text = "直到與你一同站在散發著無可名狀的珠光車體裡的龐托斯發出一聲嘯叫。"
  },
  AvgDialog_142892_Content_60 = {
    Text = "你根本就不明白，小朋友，我花了那麼多心思去找你……"
  },
  AvgDialog_142892_Content_62 = {
    Text = "你僵在了原地，貼在你皮膚上的不止是龐托斯的手指，無名的恐懼令你抬起頭，龐托斯深藍色的瞳孔沉沉地落在你身上。"
  },
  AvgDialog_142892_Content_63 = {
    Text = "既然你想看，就看一看吧，我到底從怎樣的東西裡把你救了出來。"
  },
  AvgDialog_142892_Content_64 = {
    Text = "你再次被<Red:吞沒>了。"
  },
  AvgDialog_142892_Content_66 = {
    Text = "喂，喂，老夥計，你聽到我說話了嗎，你怎麼又走神了？當心！"
  },
  AvgDialog_142892_Content_67 = {
    Text = "嗤！泥水濺在臉上，你猛然回神，愣怔地打量著身邊的人。蒼老、佝僂、絮絮叨叨，但你認出來了，那無疑是年老的奧爾尼。"
  },
  AvgDialog_142892_Content_68 = {
    Text = "這些該死的水手，簡直無法無天，要我說，那些航行把他們的心都弄野了，根本沒有心思在實事上！"
  },
  AvgDialog_142892_Content_69 = {
    Text = "奧爾尼？……你小時候最大的夢想不就是成為一名水手，去探索每片大陸嗎？"
  },
  AvgDialog_142892_Content_7 = {
    Text = "抓住祂們，讓祂們永遠不能再離開，讓祂們永遠在此處受苦！"
  },
  AvgDialog_142892_Content_70 = {
    Text = "我還說過這種話？別開玩笑了，到我們這把年紀，就應該知道，平穩才是最好的。"
  },
  AvgDialog_142892_Content_71 = {
    Text = "你忘了嗎，老夥計，大學二年級開始我們就不討論這個了。我們聊那些報紙新聞，一張張該死的報表，退休金，兩週一次的家庭聚餐。"
  },
  AvgDialog_142892_Content_72 = {
    Text = "他拍了拍你的肩膀，顫顫巍巍地從藥房窗口拿出兩個紙袋。"
  },
  AvgDialog_142892_Content_73 = {
    Text = "你不是跟我一樣嗎，大學畢業回到這裡以後，謝天謝地，我們連長途旅行都懶得去了。"
  },
  AvgDialog_142892_Content_74 = {
    Text = "這天殺的關節炎，幸好，除了你和這些止痛藥，根本也沒什麼東西需要我外出。"
  },
  AvgDialog_142892_Content_75 = {
    Text = "孤獨，哈！我們年輕的時候還以為它和大腳怪一樣不可能存在呢！"
  },
  AvgDialog_142892_Content_76 = {
    Text = "奧爾尼繼續念叨著些什麼，你盯著他一開一合的嘴唇，突如其來的眩暈把你從瑣碎的日常裡拽了出去。"
  },
  AvgDialog_142892_Content_78 = {
    Text = "看見了嗎，那些庸常的日子把奧爾尼變成了什麼樣。再去看看吧，你換來的是什麼。"
  },
  AvgDialog_142892_Content_79 = {
    Text = "你看見了，躺在床上、形容枯朽的，你。"
  },
  AvgDialog_142892_Content_8 = {Text = "雲層。"},
  AvgDialog_142892_Content_80 = {
    Text = "當然，他們一開始會傷心，為你掉幾滴眼淚。"
