  },
  AvgDialog_15613_Content_19 = {
    Text = "光球已經很暗淡了，幾乎要融入周遭的黑暗之中。"
  },
  AvgDialog_15613_Content_2 = {Text = "左腳。"},
  AvgDialog_15613_Content_20 = {
    Text = "就算你挽救了她的血肉軀體，那又如何？\n死亡總會到來，到時候她是會感謝你，還是怨恨你剝奪了她永生的機會？\n\n放手吧，艾瑞卡，讓我接管這個身體。\n我會讓她<Red:「蛻變」>，讓她擁有更好的未來。"
  },
  AvgDialog_15613_Content_21 = {
    Text = "我……一直覺得……自己會死在爆炸中……\n很抱歉……要……拉著你一起了……"
  },
  AvgDialog_15613_Content_22 = {
    Text = "……你要幹什麼？"
  },
  AvgDialog_15613_Content_23 = {
    Text = "閉嘴……惡魔……我沒有……在和你說話……"
  },
  AvgDialog_15613_Content_24 = {
    Text = "光球中出現的畫面，是一隻已經滿是焦痕的，還在不斷流出電漿的機械手。"
  },
  AvgDialog_15613_Content_25 = {
    Text = "手裡不知何時握了幾根線，上面沾滿了黑色的黏液。"
  },
  AvgDialog_15613_Content_26 = {
    Text = "對不起，嘀嗒人……到最後……反而……要親手毀掉你……"
  },
  AvgDialog_15613_Content_27 = {
    Text = "沉默降臨在你們之間。\n你仍不確定自己在這場夢中的身份，而她，似乎也沒有在等一個回應。"
  },
  AvgDialog_15613_Content_3 = {Text = "右腳。"},
  AvgDialog_15613_Content_32 = {
    Text = "你猛地坐起身，發現自己回到了熟悉的房間。"
  },
  AvgDialog_15613_Content_33 = {
    Text = "有人正在敲響你的房門。"
  },
  AvgDialog_15613_Content_34 = {Text = "請進。"},
  AvgDialog_15613_Content_35 = {
    Text = "下午好，守密人。你有一則來自朵爾，的留言，請問是否接收？"
  },
  AvgDialog_15613_Content_36 = {
    Text = "朵爾這是又給你搞了什麼新功能……接收。"
  },
  AvgDialog_15613_Content_37 = {
    Text = "哔——你還記得今天是什麼日子嗎，%player%？提醒你兩個字：測試。"
  },
  AvgDialog_15613_Content_39 = {
    Text = "我勸你在五分鐘之內出現在教室裡，不然我很難保證接下來30天你的訓練生活會是怎樣的，或許體能方面的特訓會加倍呢？"
  },
  AvgDialog_15613_Content_4 = {
    Text = "每一步都有火花飛濺，每一步都能聽到機械彼此傾軋摩擦的刺耳聲響。"
  },
  AvgDialog_15613_Content_40 = {
    Text = "哔——留言結束。請問是否需要回覆？"
  },
  AvgDialog_15613_Content_41 = {
    Text = "回覆個什麼啊，趕緊出門了！！"
  },
  AvgDialog_15613_Content_42 = {
    Text = "守密人的身影消失在樓道盡頭，艾瑞卡轉過身，看向桌上散落的文件。"
  },
  AvgDialog_15613_Content_43 = {
    Text = "洪積298年@1月@2日，彌薩格大學喚醒系，@3\n據設計圖紙T-38完成自動人偶E的軀幹復原，編號EA301881。\n這是我們第10次嘗試進行復原了。我不得不佩服最初完成這個設計，並將它製作出來的人——這個自動人偶非常精細複雜，同時也非常優雅，成百上千個齒輪與軸承相互連接，共同演奏著名為機械結構的華麗樂章。即使現在它靜止不動，我都能感到一種獨特的生命力。\n可惜，我們至今沒能找到電機設計圖紙的關鍵——一個直徑5公分，長十公分的圓筒。它理應是整個人偶的能源核心，可這樣大小、又能為這樣複雜的器械供能的東西，我還從未見過……\n希望朵爾教授能想到些什麼，我已經等不及看到它真正運轉起來的模樣了。"
  },
  AvgDialog_15613_Content_44 = {
    Text = "洪積298年@1月@2日，彌薩格大學喚醒系，@3\n完成電機復原，編號MF311028。\n雖然中途經歷了不少波折（父神在上，我們進行了整整28次嘗試，28次！），朵爾教授的最終設想被證明是正確的——電機的供能核心是銀芯。\n在嘗試了多個銀芯後，唯有E-1929號銀芯使電機正常運轉。我很難不想像這是設計者的某種遺留的意志的影響，儘管我們至今不知道這個人的去向。"
  },
  AvgDialog_15613_Content_45 = {
    Text = "洪積300年@2月@1日，彌薩格大學喚醒系，朵爾\n自動人偶艾瑞卡喚醒成功。\n喚醒體具有極強的攻擊性與破壞慾，即使有調查員維持精神，依舊具有明顯的攻擊傾向，且會不受控地放出電流，對周邊事物進行無差別攻擊。\n阿利斯泰爾判斷E-1929內含有兩個精神，一個癲狂強大，另一個雖然微弱，但更具理性。應嘗試將二者分離，或將癲狂壓制在可控範圍內。\n……\n洪積300年@2月@2日，彌薩格大學喚醒系，朵爾\n無法分離精神，積極考慮第二方案。\n精神壓抑裝置是個好主意。\n……\n洪積303年@1月@2日，彌薩格大學喚醒系，朵爾\n壓抑裝置製造完成，安裝成功。\n喚醒體的癲狂得到抑制，整體狀態趨向穩定，但仍有抑制短暫失效的情況出現。\n喚醒體性格、愛好等方面完全喪失，表現得更貼近人偶，而非人。\n起碼她不會每時每刻都處在爆炸的邊緣了。\n……"
  },
  AvgDialog_15613_Content_46 = {
    Text = "艾瑞卡歪歪頭，將文件收拾整齊，離開了房間。"
  },
  AvgDialog_15613_Content_5 = {
    Text = "不遠處的路燈下，一個公用電話亭靜靜地佇立。"
  },
  AvgDialog_15613_Content_6 = {Text = "左腳。"},
  AvgDialog_15613_Content_7 = {Text = "右腳。"},
  AvgDialog_15613_Content_8 = {
    Text = "似乎注意到你們的決心，癱軟在地上的黏液仍然在向著艾瑞卡的意識進攻，連你身上都被染得漆黑。"
  },
  AvgDialog_15613_Content_9 = {Text = "左腳。"},
  AvgDialog_18708_Content_10 = {
    Text = "伴隨痛苦的呻吟，獵顱者的五官被扭曲到不可思議的程度，皮下的膿包快速蠕動著，亟待破繭而出。"
  },
  AvgDialog_18708_Content_11 = {
    Text = "這是……？"
  },
  AvgDialog_18708_Content_13 = {
    Text = "頭顱被無情斬下，黑色的融蝕漿自脖頸噴湧而出，幾乎就要濺到你的臉上。"
  },
  AvgDialog_18708_Content_14 = {
    Text = "好奇心太重可不是什麼好習慣哦，守密人。"
  },
  AvgDialog_18708_Content_15 = {
    Text = "他的顱腔裡全是淤積的融蝕漿，建議你們最好離遠一些。"
  },
  AvgDialog_18708_Content_16 = {
    Text = "達芙黛爾夫人！"
  },
  AvgDialog_18708_Content_18 = {
    Text = "怎麼又是你……？"
  },
  AvgDialog_18708_Content_19 = {
    Text = "我循著獵顱者的蹤跡追來這裡，順便收回我的花。"
  },
  AvgDialog_18708_Content_2 = {
    Text = "獵顱者重重倒在地上，嘴裡發出微弱的呻吟。"
  },
  AvgDialog_18708_Content_20 = {
    Text = "達芙黛爾自如地行走在被血跡與融蝕漿浸染的地板上，將床頭的水仙摘出，拿到鼻尖輕輕嗅著。"
  },
  AvgDialog_18708_Content_21 = {
    Text = "這可是我精心培育了三年的褐盞水仙，有鎮靜安神的作用哦。"
  },
  AvgDialog_18708_Content_22 = {
    Text = "要來聞一聞嗎？"
  },
  AvgDialog_18708_Content_23 = {
    Text = "<LightGray:難怪我剛才睡得那麼沉……>"
  },
  AvgDialog_18708_Content_24 = {
    Text = "你有些煩躁地撇開她手中含露盛放的水仙。"
  },
  AvgDialog_18708_Content_25 = {
    Text = "你好像很了解獵顱者"
  },
  AvgDialog_18708_Content_26 = {
    Text = "你怎麼知道他的腦子裡會湧出融蝕漿？"
  },
  AvgDialog_18708_Content_27 = {
    Text = "如果你活的時間和我一樣長，見過足夠數量的融蝕患者，自然也會懂得多一些。"
  },
  AvgDialog_18708_Content_28 = {
    Text = "獵顱者的蹤跡？"
  },
  AvgDialog_18708_Content_29 = {
    Text = "“循著獵顱者的蹤跡”——你能感知他的方位？"
  },
  AvgDialog_18708_Content_3 = {
    Text = "樓梯間傳來“噔噔噔”的腳步聲，你身後的木門被一把拉開。"
  },
  AvgDialog_18708_Content_30 = {
    Text = "我有我的方法。不過……為了避免嚇壞小朋友，還是不便透露了。"
  },
  AvgDialog_18708_Content_32 = {
    Text = "現在請你暫時離開，達芙黛爾夫人。不要干擾守密人查案。"
  },
  AvgDialog_18708_Content_33 = {
    Text = "咦，現在不懷疑我了嗎？"
  },
  AvgDialog_18708_Content_34 = {
    Text = "還不能完全排除你的嫌疑。不過直覺告訴我……"
  },
  AvgDialog_18708_Content_35 = {
    Text = "如果你是“獵顱者”，應該會做得更加乾淨俐落，不會留下那些過於拙劣的把柄。"
  },
  AvgDialog_18708_Content_36 = {
    Text = "啊呀，這是對我的誇獎嗎？\n準確來講，這是事實而非直覺。"
  },
  AvgDialog_18708_Content_37 = {
    Text = "……別轉移話題。"
  },
  AvgDialog_18708_Content_38 = {
    Text = "既然你今天才到鎮上，那我昨晚看到的人是誰？"
  },
  AvgDialog_18708_Content_39 = {
    Text = "難道你還有個雙胞胎姐妹？"
  },
  AvgDialog_18708_Content_4 = {
    Text = "%player%%sirormadam%，我剛才聽到聲音，發生什麼事了？"
  },
  AvgDialog_18708_Content_41 = {
    Text = "達芙黛爾狀似苦惱地思考著，忽然朝你伸出手來。"
  },
  AvgDialog_18708_Content_42 = {
    Text = "柔軟的指尖在你的臉上摩挲片刻，隨後又劃到你的脖頸處停住，感受著來自血管深處的跳動。"
  },
  AvgDialog_18708_Content_44 = {
    Text = "我一直以為，人是一種善於偽裝的生物。"
  },
  AvgDialog_18708_Content_45 = {
    Text = "你們將自己包裹進相似的血肉裡，說著差不多的話，有著差不多的脈搏和心跳……"
  },
  AvgDialog_18708_Content_46 = {
    Text = "很長一段時間，我都分不清你們，正如你們也無法分清我。"
  },
  AvgDialog_18708_Content_47 = {
    Text = "你的意思是……你們並非雙胞胎，而是某種更加特殊的關係？"
  },
  AvgDialog_18708_Content_48 = {
    Text = "有可能哦。給你三次機會，要不要來猜猜看？"
  },
  AvgDialog_18708_Content_49 = {
    Text = "……我拒絕。"
  },
  AvgDialog_18708_Content_5 = {
    Text = "這，這是……？！"
  },
  AvgDialog_18708_Content_50 = {
    Text = "即使我猜對了，你也不會告訴我真實答案。我說得對嗎？"
  },
  AvgDialog_18708_Content_51 = {
    Text = "達芙黛爾漫不經心地用指尖描摹著你頸部血管的脈絡，眼中笑意更甚。"
  },
  AvgDialog_18708_Content_52 = {
    Text = "你真是越來越了解我了，守密人%sirormadam%。"
  },
  AvgDialog_18708_Content_53 = {
    Text = "你退開半步離開達芙黛爾的掌心，朝她投去一個警告的眼神。"
  },
  AvgDialog_18708_Content_54 = {
    Text = "在你們眼裡，長得一模一樣就算是雙胞胎嗎？"
  },
  AvgDialog_18708_Content_55 = {
    Text = "常規而言，這恐怕是唯一的可能性。"
  },
  AvgDialog_18708_Content_56 = {
    Text = "但你我都知道，我們所處的世界並不“常規”。"
  },
  AvgDialog_18708_Content_57 = {
    Text = "是啊。這個世界最遺憾的地方莫過於它的“不常規”。"
  },
  AvgDialog_18708_Content_58 = {
    Text = "做一對無憂無慮的雙胞胎姐妹，似乎也不錯。"
  },
  AvgDialog_18708_Content_6 = {
    Text = "你上前一把掀開獵顱者黑色的兜帽，露出下面的臉來。"
  },
  AvgDialog_18708_Content_7 = {
    Text = "高顴骨、鷹鉤鼻、消瘦的面頰——一張完全陌生的臉。"
  },
  AvgDialog_18708_Content_8 = {
    Text = "可真會挑對象，竟然追到這裡了。你究竟是誰？"
  },
  AvgDialog_18709_Content_10 = {
    Text = "你撐起來靠在床頭，先前發生的一幕幕從你眼前掠過，還有許多問題亟待解決。"
  },
  AvgDialog_18709_Content_11 = {
    Text = "先問問奧爾拉小姐都知道些什麼吧。"
  },
  AvgDialog_18709_Content_12 = {
    Text = "詢問老弗里曼"
  },
  AvgDialog_18709_Content_13 = {
    Text = "老弗里曼？原來他還活著……"
  },
  AvgDialog_18709_Content_14 = {
    Text = "聽鄉民說，他年輕的時候是個樂觀開朗的人，大家都很喜歡他。"
  },
  AvgDialog_18709_Content_15 = {
    Text = "那場<Yellow:瘟疫>後，他離開瑞尼鎮，回來卻完全變了個人。"
  },
  AvgDialog_18709_Content_17 = {
    Text = "三年前，瑞尼鎮北部發生了一場融蝕災難，當地人都管它叫瘟疫。"
  },
  AvgDialog_18709_Content_18 = {
    Text = "現在那裡已經徹底成為了一片死地。"
  },
  AvgDialog_18709_Content_19 = {
    Text = "詢問達芙黛爾"
  },
  AvgDialog_18709_Content_20 = {
    Text = "奧爾拉小姐，剛才你說起達芙黛爾的語氣……你們之前認識？"
  },
  AvgDialog_18709_Content_21 = {
    Text = "達芙黛爾夫人……"
  },
  AvgDialog_18709_Content_22 = {
    Text = "奧爾拉望著手中的書頁，臉上泛起淡淡的微笑。"
  },
  AvgDialog_18709_Content_23 = {
    Text = "達芙黛爾夫人，她……幫過我。"
  },
  AvgDialog_18709_Content_24 = {
    Text = "15@1年，聖佩德羅"
  },
  AvgDialog_18709_Content_25 = {
    Text = "這本龍薩的詩集可是孤品，一定要好好珍藏哦。"
  },
  AvgDialog_18709_Content_26 = {
    Text = "萬分感謝，達芙黛爾夫人。想不到您竟然真的找到了……"
  },
  AvgDialog_18709_Content_27 = {
    Text = "“願你永葆燦若玫瑰之美，直到永遠。”"
  },
  AvgDialog_18709_Content_28 = {
    Text = "很美的詩句，你的眼光不錯。"
  },
  AvgDialog_18709_Content_29 = {
    Text = "是的，不過我更喜歡“我用牛奶和鮮花在此刻祭奠……”"
  },
  AvgDialog_18709_Content_3 = {
    Text = "你終於醒了，守密人%sirormadam%。"
  },
  AvgDialog_18709_Content_30 = {
    Text = "啊……對不起，我又跑題了。"
  },
  AvgDialog_18709_Content_31 = {
    Text = "我知道“交換商店”的規矩。那麼，您想從我身上獲得什麼呢？"
  },
  AvgDialog_18709_Content_32 = {
    Text = "唔……那我可要好好觀察觀察你了，我的小玫瑰。"
  },
  AvgDialog_18709_Content_33 = {
    Text = "目光不帶感情地掃過奧爾拉全身。少女不由自主挺直了背脊。"
  },
  AvgDialog_18709_Content_34 = {
    Text = "能給我一段你的回憶嗎？\n痛苦的，悲傷的……任何不開心的回憶都可以。"
  },
  AvgDialog_18709_Content_35 = {
    Text = "不開心的回憶？那、那可不是什麼好東西。您打算用它做什麼……？"
  },
  AvgDialog_18709_Content_36 = {
    Text = "我打算用它來做一個小實驗，到時候你會知道的。"
  },
  AvgDialog_18709_Content_37 = {
    Text = "連日忙碌的疲倦不斷侵蝕著神經，你在奧爾拉輕柔的話語中再次沉入夢鄉。"
  },
  AvgDialog_18709_Content_39 = {
    Text = "不知過了多久，窗外淅淅瀝瀝下起了小雨。"
  },
  AvgDialog_18709_Content_4 = {
    Text = "我記得我似乎暈倒了，然後……"
  },
  AvgDialog_18709_Content_40 = {
    Text = "有人踩著泥濘的路面，在雨中緩慢地、永無止境地踱步。"
  },
  AvgDialog_18709_Content_41 = {
    Text = "他們只在下著雨的黑夜出現，腳步聲藏在雨裡，只需要輕輕繞到你的身後……"
  },
  AvgDialog_18709_Content_42 = {
    Text = "獵顱者既不是一個人，也不是兩個人。獵顱者是一個組織。"
  },
  AvgDialog_18709_Content_43 = {
    Text = "下著雨的黑夜，獨自一人……<Red:不就是你現在的處境嗎？>"
  },
  AvgDialog_18709_Content_44 = {
    Text = "<Red:滋……哢哢……>"
  },
  AvgDialog_18709_Content_47 = {
    Text = "慘白的閃電劃破夜的沉寂，你在黑暗中倏然睜眼。"
  },
  AvgDialog_18709_Content_48 = {
    Text = "有人正站在你的床邊。"
  },
  AvgDialog_18709_Content_49 = {
    Text = "沉甸甸的視線就像濕冷的鐮刀，描摹著你的四肢、背部，以及……"
  },
  AvgDialog_18709_Content_5 = {
    Text = "是達芙黛爾夫人把你抱回來的，她還囑託我一定要好好照顧你。"
  },
  AvgDialog_18709_Content_50 = {
    Text = "毫不設防的脖頸。"
  },
  AvgDialog_18709_Content_51 = {
    Text = "頭@1頭顱@4"
  },
  AvgDialog_18709_Content_55 = {
    Text = "你猝不及防滾落床底，下意識伸手捂住脖子。"
  },
  AvgDialog_18709_Content_56 = {
    Text = "手持鐮刀的黑影站在床前，幾乎與身後暗沉沉的夜色融為一體。"
  },
  AvgDialog_18709_Content_57 = {
    Text = "空氣裡充斥著雨和鐵鏽的味道。暗紅的血自冷白的鋒刃淌出，再一路滴落在地板上。"
  },
  AvgDialog_18709_Content_58 = {
    Text = "——是獵顱者。"
  },
  AvgDialog_18709_Content_6 = {
    Text = "達芙黛爾……？"
  },
  AvgDialog_18709_Content_8 = {
    Text = "床頭不知何時擺上了一個細頸花瓶，潔白的水仙正迎著陽光伸展花蕊。"
  },
  AvgDialog_18710_Content_1 = {
    Text = "野獸王國"
  },
  AvgDialog_18710_Content_10 = {
    Text = "那是個晴朗的夏夜，我像往常一樣辛勤地搬運著我的“戰利品”。"
  },
  AvgDialog_18710_Content_11 = {
    Text = "<Shake:頭……更多的頭……>"
  },
  AvgDialog_18710_Content_13 = {
    Text = "輕盈的腳步聲悄然而至，頭頂傳來一個溫柔的聲音。"
  },
  AvgDialog_18710_Content_14 = {
    Text = "呵……瞧瞧我都找到了什麼？一頭走失的小野獸。"
  },
  AvgDialog_18710_Content_15 = {
    Text = "那天晚上，一個女人來到我身邊。"
  },
  AvgDialog_18710_Content_16 = {
    Text = "當她靠近我時，我聞到一股很好聞的香氣。\n是花與霧的氣味。"
  },
  AvgDialog_18710_Content_17 = {
    Text = "這是來自另一個世界的氣味，它和我的王國就像白天與黑夜一樣涇渭分明，本不該有任何交集。"
  },
  AvgDialog_18710_Content_18 = {
    Text = "但她還是腳踩惡臭泥濘的泔水，穿過城市的陰影，向我伸出手。"
  },
  AvgDialog_18710_Content_19 = {
    Text = "她說……"
  },
  AvgDialog_18710_Content_2 = {
    Text = "我是一頭野獸……我是一個病人。\n\n我是一個無可救藥之人。"
  },
  AvgDialog_18710_Content_20 = {
    Text = "願意跟我走嗎，小野獸？"
  },
  AvgDialog_18710_Content_21 = {
    Text = "5：00，瑞尼鎮北部"
  },
  AvgDialog_18710_Content_22 = {
    Text = "這裡還真是……一片荒蕪。"
  },
  AvgDialog_18710_Content_23 = {
    Text = "三年前，這裡生出了一個<Yellow:S級融蝕裂隙>。水源、植被……所有的生態都遭到了嚴重破壞。"
  },
  AvgDialog_18710_Content_24 = {
    Text = "萬幸人員傷亡較少，居民都在審查會的安排下離開了。"
  },
  AvgDialog_18710_Content_25 = {
    Text = "你看向眼前蕭瑟的牆垣與慘白的枯樹。"
  },
  AvgDialog_18710_Content_26 = {
    Text = "若是沒有融蝕，這裡本該是丁香花盛開的綠色原野。風吹過的時候，草浪便會上下翻飛，就像一片綠色的海洋。"
  },
  AvgDialog_18710_Content_27 = {
    Text = "你確定獵顱者在這裡嗎，達芙黛爾夫人？"
  },
  AvgDialog_18710_Content_28 = {
    Text = "回應你的只有烏鴉沙啞的鳴叫聲。"
  },
  AvgDialog_18710_Content_29 = {
    Text = "咦，達芙黛爾夫人不見了？"
  },
  AvgDialog_18710_Content_3 = {
    Text = "白天，我躲在城市的陰影裡，挺著肚皮四腳朝天，呼呼大睡。"
  },
  AvgDialog_18710_Content_30 = {
    Text = "嘖，輕信他人的後果。"
  },
  AvgDialog_18710_Content_31 = {
    Text = "咳咳。她總是這樣行蹤不定，我早就習慣了。"
  },
  AvgDialog_18710_Content_32 = {
    Text = "沒關係，我自己也能調查。這裡一定能找出點什麼……"
  },
  AvgDialog_18710_Content_33 = {
    Text = "<Big:轟隆隆——！！>"
  },
  AvgDialog_18710_Content_34 = {
    Text = "低垂的雲暮裡響起沉悶的雷聲，枯葉在秋風吹拂下沙沙作響。"
  },
  AvgDialog_18710_Content_35 = {
    Text = "這是下雨的前兆。"
  },
  AvgDialog_18710_Content_36 = {
    Text = "為什麼只在下雨天出現呢？"
  },
  AvgDialog_18710_Content_37 = {
    Text = "因為在下雨的時候，血和雨就能混到一起，流到下水道裡。"
  },
  AvgDialog_18710_Content_38 = {
    Text = "是的，流到下水道裡，棺材裡，還有你身邊的小水溝裡……"
  },
  AvgDialog_18710_Content_39 = {
    Text = "<Red:滋……哢哢……>"
  },
  AvgDialog_18710_Content_4 = {
    Text = "夜晚，我像鬼魅一般彷徨街頭，尋找一個又一個頭顱。"
  },
  AvgDialog_18710_Content_40 = {
    Text = "下著雨的黑夜……不對，怎麼又開始胡思亂想了。"
  },
  AvgDialog_18710_Content_41 = {
    Text = "你使勁搖了搖頭，試圖將腦海裡紛亂的驅逐乾淨。"
  },
  AvgDialog_18710_Content_42 = {
    Text = "留給你的時間不多了，必須趕緊行動。"
  },
  AvgDialog_18710_Content_5 = {
    Text = "<Red:頭顱。頭顱。頭顱。>"
  },
  AvgDialog_18710_Content_6 = {
    Text = "<RedBig:頭顱。\n        頭顱。\n                頭顱。\n                        頭顱。\n                                頭顱。\n                                        頭顱……>"
  },
  AvgDialog_18710_Content_7 = {
    Text = "我的腦子再也無法思考生存、愛與尊嚴。\n\n它早已被那些飢渴的狂想塞得滿滿當當。"
  },
  AvgDialog_18710_Content_8 = {
    Text = "我是一個無可救藥之人。"
  },
  AvgDialog_18710_Content_9 = {
    Text = "15@1年，聖佩德羅市"
  },
  AvgDialog_18711_Content_10 = {
    Text = "她不顧滿地髒污的黏液和血跡，蹲下來望著眼前不斷掙扎的困獸。"
  },
  AvgDialog_18711_Content_11 = {
    Text = "別找了。它們都消失了，再也不會回來了。"
  },
  AvgDialog_18711_Content_12 = {
    Text = "你需要的不是這些東西。"
  },
  AvgDialog_18711_Content_13 = {
    Text = "不需要……？不，頭@1給我……"
  },
  AvgDialog_18711_Content_15 = {
    Text = "你知道嗎？其實……我們是一樣的。\n我知道你的痛苦。"
  },
  AvgDialog_18711_Content_16 = {
    Text = "15@1年，聖佩德羅市"
  },
  AvgDialog_18711_Content_17 = {
    Text = "願意跟我走嗎，小野獸？你需要幫助。"
  },
  AvgDialog_18711_Content_18 = {
    Text = "15@1年的夏天，一個女人向我伸出手。"
  },
  AvgDialog_18711_Content_19 = {
    Text = "或許是她身上的氣味太好聞了，或許是她看起來很溫和。"
  },
  AvgDialog_18711_Content_2 = {
    Text = "浮浪般的肉團轟然坍塌，融蝕漿與灰質黏液如潮水般傾瀉而出，直到褪出哈莉特孱弱的身軀。"
  },
  AvgDialog_18711_Content_20 = {
    Text = "總之，我沒有拒絕她。"
  },
  AvgDialog_18711_Content_21 = {
    Text = "我懵懂地抓住她的手，也抓住了我今後的命運。"
  },
  AvgDialog_18711_Content_23 = {
    Text = "你快死了，達芙黛爾。"
  },
  AvgDialog_18711_Content_24 = {
    Text = "傻孩子……教了你那麼多年，還沒學會好好說話。"
  },
  AvgDialog_18711_Content_25 = {
    Text = "別哭……咳咳……"
  },
  AvgDialog_18711_Content_26 = {
    Text = "<Shake:我、我沒有……>"
  },
  AvgDialog_18711_Content_27 = {
    Text = "取下我的頭吧。我把我的身份和容貌，還有這個小店都交給你。"
  },
  AvgDialog_18711_Content_29 = {
    Text = "我知道，咳咳……你一直渴望能像普通人類一樣行走於世。"
  },
  AvgDialog_18711_Content_3 = {
    Text = "灰白色的頭顱紛紛湧出，不過一眨眼的功夫便悄然湮滅了。"
  },
  AvgDialog_18711_Content_30 = {
    Text = "你躲在角落裡觀察我怎麼說話、怎麼走路，趁我不在的時候偷偷地穿我的衣服，還頂替我的身份出去交朋友……"
  },
  AvgDialog_18711_Content_32 = {
    Text = "對不起，達芙黛爾，我不是故意的……"
  },
  AvgDialog_18711_Content_33 = {
    Text = "現在我滿足你的願望，咳咳……但是你要向我保證……"
  },
  AvgDialog_18711_Content_34 = {
    Text = "以後不能隨意取下無辜者的頭顱。若是見到像你一樣的人，你也要幫助他們。"
  },
  AvgDialog_18711_Content_35 = {
    Text = "就像我現在幫助你一樣。"
  },
  AvgDialog_18711_Content_37 = {
    Text = "哈莉特發出困獸般的哀鳴，向達芙黛爾顫抖著伸出手。"
  },
  AvgDialog_18711_Content_39 = {
    Text = "那時候……在墓地見到丈夫的時候，你一定很絕望吧？"
  },
  AvgDialog_18711_Content_4 = {
    Text = "頭@1不……"
  },
  AvgDialog_18711_Content_41 = {
    Text = "我們身負相同的詛咒，我卻比你幸運得多。"
  },
  AvgDialog_18711_Content_42 = {
    Text = "在我還不知善惡為何物的時候，是那位夫人向我伸出手。"
  },
  AvgDialog_18711_Content_43 = {
    Text = "達芙黛爾蹲在哈莉特夫人面前，輕輕握住她傷痕累累、沾滿融蝕漿的手。"
  },
  AvgDialog_18711_Content_44 = {
    Text = "我學著她說話、走路，把自己活成了她的模樣。"
  },
  AvgDialog_18711_Content_45 = {
    Text = "小心，達芙黛爾夫人！哈莉特手上都是融蝕漿——"
  },
  AvgDialog_18711_Content_46 = {
    Text = "噓……我和她還有話要說。"
  },
  AvgDialog_18711_Content_47 = {
    Text = "達芙黛爾繼續望著哈莉特。一種隱秘的聯結流淌在二人中間，將一切紛擾都隔絕在外。"
  },
  AvgDialog_18711_Content_48 = {
    Text = "現在我終於也能像她一樣，向別人伸出手……可我來得太晚了。"
  },
  AvgDialog_18711_Content_49 = {
    Text = "淡紫色的煙霧逐漸升起，在昏暗的室內緩慢浮動。"
  },
  AvgDialog_18711_Content_5 = {
    Text = "失去頭顱的哈莉特不安地扭動身體，頸部的血管急促地顫動著，從中發出模糊的嗡鳴。"
  },
  AvgDialog_18711_Content_50 = {
    Text = "你又聞到了那股熟悉的花香，帶著午夜薄霧的濕氣，沖淡了一室濃郁的血腥。"
  },
  AvgDialog_18711_Content_51 = {
    Text = "達芙黛爾將手輕輕放在哈莉特夫人身邊。"
  },
  AvgDialog_18711_Content_52 = {
    Text = "放心離開吧，哈莉特夫人。你不會感受到任何痛苦。"
  },
  AvgDialog_18711_Content_53 = {
    Text = "自她的掌心處迅速撕開一道裂隙，緩慢地將哈莉特吞入其中……"
  },
  AvgDialog_18711_Content_55 = {
    Text = "我的丈夫@2見到，告訴他別再喝酒了。"
  },
  AvgDialog_18711_Content_56 = {
    Text = "還有……"
  },
  AvgDialog_18711_Content_57 = {
    Text = "哈莉特裸露在外的喉腔輕輕顫抖著，最後卻像蔫掉的樹葉，再也沒有發出一絲聲息。"
  },
  AvgDialog_18711_Content_58 = {
    Text = "她放開達芙黛爾的手，無聲地墜入深不見底的維度裂隙中。"
  },
  AvgDialog_18711_Content_59 = {
    Text = "<Change>再見，再見……"
  },
  AvgDialog_18711_Content_6 = {
    Text = "給我@2把頭給我……"
  },
  AvgDialog_18711_Content_60 = {
    Text = "終於……結束了嗎。你把她帶去什麼地方了，達芙黛爾夫人？"
  },
  AvgDialog_18711_Content_61 = {
    Text = "原質海洋。她將擁有漫長的時間來銘記……或是遺忘發生的一切。"
  },
  AvgDialog_18711_Content_63 = {
    Text = "你還來不及釐清紛亂的思緒，便聽到屋外隱約傳來腳步聲。"
  },
  AvgDialog_18711_Content_64 = {
    Text = "什麼人？跟上去看看。"
  },
  AvgDialog_18711_Content_66 = {
    Text = "好久不見，小偵探！還記得我嗎，守墓人老弗里曼！"
  },
  AvgDialog_18711_Content_67 = {
    Text = "老弗里曼拎著白蘭地，不住地打著酒嗝，嘴角咧開尷尬的微笑。"
  },
  AvgDialog_18711_Content_68 = {
    Text = "老弗里曼？！你在這裡做什麼……你都聽到了？"
  },
  AvgDialog_18711_Content_7 = {
    Text = "她焦急地在地上爬來爬去，骨瘦如柴的雙臂四處揮舞。就像走投無路的野獸，只在喉嚨裡發出一聲聲絕望的哀哞。"
  },
  AvgDialog_18711_Content_70 = {
    Text = "我也不知道怎麼回事，喝完酒後睡了一大覺。"
  },
  AvgDialog_18711_Content_71 = {
    Text = "中間發生什麼也記不清了，總之稀里糊塗就跑到這裡了。"
  },
  AvgDialog_18711_Content_72 = {
    Text = "然後就聽到裡頭有動靜……放心，我可一眼都沒朝裡面看！"
  },
  AvgDialog_18711_Content_73 = {
    Text = "老弗里曼說著，忽然湊了上來，朝你神秘兮兮地眨了眨眼。\n你躲閃不及，聞到一股菸酒的濃烈惡臭。"
  },
  AvgDialog_18711_Content_74 = {
    Text = "你們殺了那個什麼獵顱者，對吧？"
  },
  AvgDialog_18711_Content_75 = {
    Text = "差、差不多吧，以後沒人會來打擾你睡覺了。"
  },
  AvgDialog_18711_Content_76 = {
    Text = "你捏著鼻子退後三步，敷衍地點了點頭。"
  },
  AvgDialog_18711_Content_78 = {
    Text = "老弗里曼揉了揉亂糟糟的頭髮，眼裡閃過一絲茫然。"
  },
  AvgDialog_18711_Content_80 = {
    Text = "弗里曼先生。以後……別再喝酒了。"
  },
  AvgDialog_18711_Content_81 = {
    Text = "戒酒？不不不……還是要了我這條老命更實際一些。"
  },
  AvgDialog_18711_Content_82 = {
    Text = "這是一位朋友託我請求你的。她去了很遠很遠的地方……但她一直都很關心你。"
  },
  AvgDialog_18711_Content_83 = {
    Text = "朋友？呵呵，少騙人了。老弗里曼哪來的朋友……"
  },
  AvgDialog_18711_Content_84 = {
    Text = "他敷衍地朝你們擺了擺手，一邊嘟囔著，一邊顫顫巍巍地離開了。"
  },
  AvgDialog_18711_Content_85 = {
    Text = "他看上去很失落。可惜……\n他永遠不會知道自己為何失落。"
  },
  AvgDialog_18711_Content_86 = {
    Text = "就像他不明白自己為什麼會來這裡。"
  },
  AvgDialog_18711_Content_87 = {
    Text = "這也是哈莉特夫人所希望的吧。"
  },
  AvgDialog_18711_Content_88 = {
    Text = "什麼都別告訴他……他還能像現在這樣，喝著酒唱著歌，迷迷糊糊地過完一生。"
  },
  AvgDialog_18711_Content_89 = {
    Text = "某種意義而言，這也是一種幸運。人類的一輩子，是很短暫的……"
  },
  AvgDialog_18711_Content_9 = {
    Text = "達芙黛爾輕嘆一聲，眼底閃爍著難言的哀傷。"
  },
  AvgDialog_18711_Content_90 = {
    Text = "你目送老弗里曼離去。"
  },
  AvgDialog_18711_Content_91 = {
    Text = "佝僂的身影在蕭瑟的風裡打著顫，越來越小、越小越小……"
  },
  AvgDialog_18711_Content_92 = {
    Text = "直到被遠方的地平線徹底吞沒。"
  },
  AvgDialog_18711_Content_93 = {
    Text = "然後你看到一線熹微的晨光破開薄霧，逐漸點亮天際。"
  },
  AvgDialog_18711_Content_94 = {
    Text = "雨停了……達芙黛爾。"
  },
  AvgDialog_18712_Content_1 = {
    Text = "影子頌歌"
  },
  AvgDialog_18712_Content_10 = {
    Text = "給我……<Big:還給我>！"
  },
  AvgDialog_18712_Content_11 = {
    Text = "黑色的觸鬚自脖頸內不斷伸長，貪婪地將那些滾落在地的頭顱一一融進自己體內。"
  },
  AvgDialog_18712_Content_12 = {
    Text = "每吃下一顆頭顱，它的體型便脹大一分。"
  },
  AvgDialog_18712_Content_13 = {
    Text = "最後矗立在你們面前的，是一團層層堆疊的巨型肉塊。"
  },
  AvgDialog_18712_Content_15 = {
    Text = "這些頭……我見過。"
  },
  AvgDialog_18712_Content_16 = {
    Text = "你見過它們之中的一部分，就在警局給你的資料裡，就在那些排成一列的、冷冰冰的受害人照片裡。"
  },
  AvgDialog_18712_Content_17 = {
    Text = "你見過他們。"
  },
  AvgDialog_18712_Content_18 = {
    Text = "這下你明白了吧，從來都沒有什麼獵顱人組織。"
  },
  AvgDialog_18712_Content_19 = {
    Text = "<Yellow:自始至終，獵顱者都是一個人。>"
  },
  AvgDialog_18712_Content_2 = {
    Text = "達芙黛爾夫人……？！"
  },
  AvgDialog_18712_Content_20 = {
    Text = "<RedShake:不夠……>"
  },
  AvgDialog_18712_Content_21 = {
    Text = "<RedShake:不夠……不夠……>"
  },
  AvgDialog_18712_Content_22 = {
    Text = "腫脹的身軀被嵌入無數表情痛苦、哀嚎著的頭顱，它們伴隨柔軟的脂肪一同起伏、呼吸……"
  },
  AvgDialog_18712_Content_23 = {
    Text = "好熟悉的精神波動……是千面幻象？！"
  },
  AvgDialog_18712_Content_25 = {
    Text = "現在它已經徹底失控了，並且還會不斷變大。\n我們必須速戰速決。"
  },
  AvgDialog_18712_Content_27 = {
    Text = "達芙黛爾忽然湊近你，握住你胸前的銀鑰匙。"
  },
  AvgDialog_18712_Content_28 = {
    Text = "願意跟我合作嗎，%player%？"
  },
  AvgDialog_18712_Content_29 = {
    Text = "咦，你願意和我鏈接？"
  },
  AvgDialog_18712_Content_3 = {
    Text = "抱歉……為了引它出來，我故意把你丟在這裡。你一定在心裡怪罪我吧？"
  },
  AvgDialog_18712_Content_30 = {
    Text = "經過這一路的相處與配合，我以為我們之間應該有些默契了。"
  },
  AvgDialog_18712_Content_31 = {
    Text = "還是說……你沒有信心能駕馭我？"
  },
  AvgDialog_18712_Content_32 = {
    Text = "呵……那我們試試看？"
  },
  AvgDialog_18712_Content_33 = {
    Text = "你閉上雙眼，凝神催動胸前的銀鑰匙。"
  },
  AvgDialog_18712_Content_34 = {
    Text = "不一會，銀鑰匙發出持續微弱的振盪，從中逸散的冷白輝光迅速吞沒了整個暗室。"
  },
  AvgDialog_18712_Content_35 = {
    Text = "你彷彿置身一片浩瀚的時間之海。"
  },
  AvgDialog_18712_Content_36 = {
    Text = "陌生的能量在你胸口不斷激盪，那是跨越維度的洶湧浪潮。"
  },
  AvgDialog_18712_Content_37 = {
    Text = "隔著寬廣的時間之海，達芙黛爾靜靜地看著你。\n此時此刻，她的臉上隱約浮現出你從未見過的神色。"
  },
  AvgDialog_18712_Content_38 = {
    Text = "那是歷經數百年的光陰，從無數場對決和交鋒中磨礪出來的一種絕對的、理所當然的自信。"
  },
  AvgDialog_18712_Content_39 = {
    Text = "出發吧，%player%。我已經準備好了。"
  },
  AvgDialog_18712_Content_5 = {
    Text = "等出去咱們再好好算帳。"
  },
  AvgDialog_18712_Content_6 = {
    Text = "<Shake:頭……還給我……>"
  },
  AvgDialog_18712_Content_7 = {
    Text = "“哈莉特”踉蹌著往前走了兩步，伸手在脖子上方徒勞地抓握。"
  },
  AvgDialog_18712_Content_8 = {
    Text = "一下、兩下……"
  },
  AvgDialog_18712_Content_9 = {
    Text = "意識到頭顱早已不復存在後，她發出一聲聲淒厲的尖叫。"
  },
  AvgDialog_18713_Content_10 = {
    Text = "你胡亂抹開臉上的雨水，眨了眨眼，這才確定真的有人在和你說話。"
  },
  AvgDialog_18713_Content_11 = {
    Text = "我以為這裡早就沒人住了。"
  },
  AvgDialog_18713_Content_13 = {
    Text = "那些生病的、上了年紀的人選擇留下，也有一些人去了外面，然後又回來……"
  },
  AvgDialog_18713_Content_14 = {
    Text = "不是所有人都能適應外面的生活。"
  },
  AvgDialog_18713_Content_15 = {
    Text = "原來如此。可我剛才一個人都沒看到。"
  },
  AvgDialog_18713_Content_16 = {
    Text = "……他們討厭和外面的人打交道。"
  },
  AvgDialog_18713_Content_17 = {
    Text = "你環顧四周稀疏破敗的屋舍。"
  },
  AvgDialog_18713_Content_18 = {
    Text = "黑洞洞的窗戶內隱約可見沉默的目光，帶著十足的審慎與敵意。"
  },
  AvgDialog_18713_Content_19 = {
    Text = "您好，夫人。請問您——"
  },
  AvgDialog_18713_Content_2 = {
    Text = "你獨自穿行在雨中，又冷又濕的雨水將你的衣服淋得濕透，緊緊貼在皮膚上。"
  },
  AvgDialog_18713_Content_20 = {
    Text = "見過什麼奇怪的東西嗎？"
  },
  AvgDialog_18713_Content_21 = {
    Text = "奇怪的東西……？"
  },
  AvgDialog_18713_Content_22 = {
    Text = "呃……人，或者野獸，總之移動速度很快。"
  },
  AvgDialog_18713_Content_23 = {
    Text = "婦人搖了搖頭。"
  },
  AvgDialog_18713_Content_24 = {
    Text = "這裡已經很久沒人來過了，連禿鷲都不願靠近。"
  },
  AvgDialog_18713_Content_25 = {
    Text = "見過達芙黛爾嗎？"
  },
  AvgDialog_18713_Content_26 = {
    Text = "請問您見過一位，唔……很美麗，穿著紫色長裙的女士嗎？"
  },
  AvgDialog_18713_Content_27 = {
    Text = "婦人搖了搖頭。"
  },
  AvgDialog_18713_Content_28 = {
    Text = "這裡已經很久沒人來過了，連禿鷲都不願靠近。"
  },
  AvgDialog_18713_Content_29 = {
    Text = "<Big:轟隆隆——>"
  },
  AvgDialog_18713_Content_3 = {
    Text = "你穿過一個又一個廢棄的房屋，路過一個又一個墳塚。"
  },
  AvgDialog_18713_Content_30 = {
    Text = "雨越下越大，天地都變得灰濛濛的。"
  },
  AvgDialog_18713_Content_31 = {
    Text = "婦人的身影開始模糊、失焦，就連聲音也愈發飄渺……"
  },
  AvgDialog_18713_Content_32 = {
    Text = "進來吧，%sirormadam%。這麼大的雨，您會生病的……"
  },
  AvgDialog_18713_Content_34 = {
    Text = "樂意之至。"
  },
  AvgDialog_18713_Content_4 = {
    Text = "所到之處皆是傷痕累累，一片荒蕪。"
  },
  AvgDialog_18713_Content_5 = {
    Text = "只有雨。連綿的、冰冷的雨，和你一路作伴。"
  },
  AvgDialog_18713_Content_7 = {
    Text = "衰老的婦人站在木屋前，朝你招了招手。"
  },
  AvgDialog_18713_Content_8 = {
    Text = "她身著暗淡的連衣裙，面容隱匿在灰濛濛的雨幕裡，和身後破敗的房屋完美地融為一體。"
  },
  AvgDialog_18713_Content_9 = {
    Text = "%sirormadam%，你看起來很冷……需要進來坐坐嗎？"
  },
  AvgDialog_18714_Content_1 = {
    Text = "暴雨將至"
  },
  AvgDialog_18714_Content_10 = {
    Text = "一個人？！"
  },
  AvgDialog_18714_Content_11 = {
    Text = "啊呀，你的臉色看起來很糟糕。需要幫忙嗎？"
  },
  AvgDialog_18714_Content_12 = {
    Text = "你先退後，我有話要問你。"
  },
  AvgDialog_18714_Content_13 = {
    Text = "這話可真叫人傷心。怎麼，難道我身上沾了什麼難聞的氣味？"
  },
  AvgDialog_18714_Content_14 = {
    Text = "我不知道……或許是死人的氣味？"
  },
  AvgDialog_18714_Content_15 = {
    Text = "貝倫·斯托克，德懷特·威廉姆斯……對這些名字有印象嗎？"
  },
  AvgDialog_18714_Content_17 = {
    Text = "原來如此，你懷疑我是獵顱者。"
  },
  AvgDialog_18714_Content_18 = {
    Text = "而你清楚地知道獵顱者受害人的姓名。"
  },
  AvgDialog_18714_Content_2 = {
    Text = "達芙黛爾優雅隨意地向你走來，彷彿是來這裡度假的。"
  },
  AvgDialog_18714_Content_20 = {
    Text = "我還以為，通過在拉伊的相處，我們之間能稍微有點信任感。"
  },
  AvgDialog_18714_Content_21 = {
    Text = "獵顱者從我這裡拿走了一顆<Yellow:珍貴的頭顱>，所以我來做點小小的調查，就是這麼簡單。"
  },
  AvgDialog_18714_Content_22 = {
    Text = "珍貴的頭顱……是誰的？"
  },
  AvgDialog_18714_Content_24 = {
