  },
  AvgDialog_18716_Content_15 = {
    Text = "重獲新生的“哈莉特”咧著嘴角，帶著令人難以置信的速度朝你奔來。"
  },
  AvgDialog_18716_Content_18 = {
    Text = "森冷的刀光無情地劃破黑暗。"
  },
  AvgDialog_18716_Content_19 = {
    Text = "下一秒，“哈莉特”的頭顱輕巧地飛了出去，滾落到寬大的裙襬旁。"
  },
  AvgDialog_18716_Content_2 = {
    Text = "哈莉特倒在地上，從喉嚨深處發出淒厲的哀鳴。"
