  AvgDialog_18719_Content_59 = {
    Text = "事已至此，還是早點搞定這個案子吧，我還想休假呢。"
  },
  AvgDialog_18719_Content_6 = {
    Text = "很好。乾燥、鬆軟，沒有雨水和血的味道。"
  },
  AvgDialog_18719_Content_60 = {
    Text = "咦，這是……"
  },
  AvgDialog_18719_Content_61 = {
    Text = "書頁翻動的聲音戛然而止。"
  },
  AvgDialog_18719_Content_62 = {
    Text = "你凝神望著被定格的那頁，開始醞釀接下來的調查計畫。"
  },
  AvgDialog_18719_Content_63 = {
    Text = "拉蒙娜……在和警探匯合前，我想先去一個地方。"
  },
  AvgDialog_18719_Content_7 = {
    Text = "早上好，%player%%sirormadam%。歡迎蒞臨寒舍……"
  },
  AvgDialog_18719_Content_8 = {
    Text = "奧爾拉小姐？！"
  },
  AvgDialog_18719_Content_9 = {
    Text = "記憶開始一點點復甦。"
  },
  AvgDialog_18720_Content_1 = {
    Text = "11：00，海格特荒塚"
  },
  AvgDialog_18720_Content_10 = {
    Text = "別對偏遠地區警探的專業程度抱有太大的期望。"
  },
  AvgDialog_18720_Content_12 = {
    Text = "你拿出隨身攜帶的放大鏡繼續觀察這具白骨。"
  },
  AvgDialog_18720_Content_13 = {
    Text = "頸骨上有<Red:鋸齒狀割傷>……"
  },
  AvgDialog_18720_Content_14 = {
    Text = "不過很凌亂，還有大量重疊的割痕，和我們之前在照片裡見過的完全不同。"
  },
  AvgDialog_18720_Content_15 = {
    Text = "還挺手生的，初次犯案？"
  },
  AvgDialog_18720_Content_16 = {
    Text = "先以亂葬崗為中心展開調查吧。\n不熟練的新手在初次犯案時，通常不會離家太遠。"
  },
  AvgDialog_18720_Content_17 = {
    Text = "明白。這次我很有信心，兇手一定會很快落網的！"
  },
  AvgDialog_18720_Content_18 = {
    Text = "兇手（murderer）？你怎麼敢假定，嗝，兇手只有一個？"
  },
  AvgDialog_18720_Content_19 = {
    Text = "密林掩映的深處走出來一位滿身酒氣、面頰通紅的老頭子。"
  },
  AvgDialog_18720_Content_2 = {
    Text = "你獨自穿行在空茫的荒塚裡。"
  },
  AvgDialog_18720_Content_20 = {
    Text = "抱歉，無意偷聽你的自言自語。"
  },
  AvgDialog_18720_Content_21 = {
    Text = "我是這裡的守墓人，你可以叫我老……嗝，<Blue:老弗里曼>。"
  },
  AvgDialog_18720_Content_22 = {
    Text = "下午好，弗里曼先生。\n剛才您的意思是，兇手不止一個人？"
  },
  AvgDialog_18720_Content_23 = {
    Text = "老弗里曼拎起酒瓶咚咚往喉嚨裡灌著酒，肥碩的喉結不住地上下滑動。"
  },
  AvgDialog_18720_Content_24 = {
    Text = "嗝！這破林子一天到晚都見不到人。難得你來了，那就聽我好好講講……"
  },
  AvgDialog_18720_Content_25 = {
    Text = "那是大概今年年初的時候……？我也記不清了。"
  },
  AvgDialog_18720_Content_26 = {
    Text = "像往常一樣，我喝完酒，隨便找了塊陰涼地就睡著了。"
  },
  AvgDialog_18720_Content_27 = {
    Text = "然後我聽見了一些奇怪的聲音，就好像……"
  },
  AvgDialog_18720_Content_29 = {
    Text = "奇怪的聲音，然後呢？"
  },
  AvgDialog_18720_Content_3 = {
    Text = "烏鴉掠過愁雲慘淡的天際，蕭索的秋風不斷呼嘯。"
  },
  AvgDialog_18720_Content_30 = {
    Text = "別著急，小偵探。\n我睜開眼睛……嗝，你猜我看到了什麼？"
  },
  AvgDialog_18720_Content_31 = {
    Text = "不會這麼巧，剛好是獵顱者吧？"
  },
  AvgDialog_18720_Content_32 = {
    Text = "是的，是獵顱者！或者，也可以說是個一個女人……"
  },
  AvgDialog_18720_Content_33 = {
    Text = "一個女人正在割皮諾科的頭！"
  },
  AvgDialog_18720_Content_34 = {
    Text = "然後她看到我，嗝，就和見了鬼似的，跑得比誰都快咧！"
  },
  AvgDialog_18720_Content_35 = {
    Text = "我可憐的皮諾科，脖子只剩半截吊在那裡！"
  },
  AvgDialog_18720_Content_37 = {
    Text = "老弗里曼發出一連串無比洪亮的笑聲，連眼淚都笑了出來。"
  },
  AvgDialog_18720_Content_39 = {
    Text = "嗝，嗝！過了一個月吧，我又聽到了那個聲音……"
  },
  AvgDialog_18720_Content_41 = {
    Text = "這回來的不是那個女的，是個很瘦的男人。"
  },
  AvgDialog_18720_Content_42 = {
    Text = "那可是個熟練工咧！一刀下去……"
  },
  AvgDialog_18720_Content_43 = {
    Text = "<RedBig:咻！>皮諾科的頭就沒啦！"
  },
  AvgDialog_18720_Content_44 = {
    Text = "聽起來有兩個獵顱者。後來呢？"
  },
  AvgDialog_18720_Content_45 = {
    Text = "後來？沒有什麼後來。這就是老弗里曼和獵顱者的全部故事，嗝。"
  },
  AvgDialog_18720_Content_46 = {
    Text = "老弗里曼滿足地打了個酒嗝，又瞇縫著混濁的黃色眼睛，將你從上到下打量了一番。"
  },
  AvgDialog_18720_Content_47 = {
    Text = "你好像什麼都不知道，可憐的小偵探。聽過<Red:獵顱者傳說>嗎？"
  },
  AvgDialog_18720_Content_48 = {
    Text = "獵顱者傳說？願聞其詳。"
  },
  AvgDialog_18720_Content_49 = {
    Text = "老弗里曼悠閒地靠在墓碑上，三五口喝完瓶中剩餘的酒，又隨手把它扔在地上。"
  },
  AvgDialog_18720_Content_5 = {
    Text = "你停在一座孤零零的墓前，下面朽爛的棺材蓋早已被掀開。"
  },
  AvgDialog_18720_Content_50 = {
    Text = "液體從碎裂的酒瓶裡淌出，在地上拖出蜿蜒的軌跡。像眼淚，也像是血。"
  },
  AvgDialog_18720_Content_51 = {
    Text = "有人說，獵顱者是那次<Yellow:瘟疫>催生的怪物。"
  },
  AvgDialog_18720_Content_52 = {
    Text = "還有人說，獵顱者既不是一個人，也不是兩個人。"
  },
  AvgDialog_18720_Content_53 = {
    Text = "<Red:獵顱者是一個組織。>"
  },
  AvgDialog_18720_Content_54 = {Text = "組織？"},
  AvgDialog_18720_Content_55 = {
    Text = "是的，一個組織。"
  },
  AvgDialog_18720_Content_56 = {
    Text = "他們只在下著雨的黑夜出現，腳步聲藏在雨裡，只需要悄悄繞到你的背後……"
  },
  AvgDialog_18720_Content_59 = {
    Text = "哈哈哈哈！怎麼，這就被嚇破了膽，我的小偵探？"
  },
  AvgDialog_18720_Content_6 = {
    Text = "一具無頭白骨橫陳棺內，上面早已成為青苔與蟲豸的樂園。"
  },
  AvgDialog_18720_Content_60 = {
    Text = "他晃悠著身子，又朝你走近幾步。渾濁發黃的眼珠咕嚕嚕轉著，幾欲將你灼穿。"
  },
  AvgDialog_18720_Content_61 = {
    Text = "這傢伙不太對勁。趕緊離開這裡。"
  },
  AvgDialog_18720_Content_62 = {
    Text = "抱歉，弗里曼先生。天色不早了，我想我得離開了……"
  },
  AvgDialog_18720_Content_63 = {
    Text = "你輕輕吸了一口氣，頭也不回地轉身離開了。"
  },
  AvgDialog_18720_Content_64 = {
    Text = "背後傳來譏諷的笑聲，但你已顧不上其他。現在你只想離開。"
  },
  AvgDialog_18720_Content_65 = {
    Text = "天色逐漸暗了下來，低垂的烏雲遮住了蒼白的日光，風吹起樹葉如潮水般起伏不定。"
  },
  AvgDialog_18720_Content_66 = {
    Text = "就在墓園的盡頭，你看見了一個熟悉又陌生的身影。"
  },
  AvgDialog_18720_Content_67 = {
    Text = "是達芙黛爾。她大半張臉籠罩在低垂的帽簷下，灰白色的髮絲在風中輕輕飛舞。"
  },
  AvgDialog_18720_Content_68 = {
    Text = "見到你這副狼狽的模樣，達芙黛爾開心地笑了起來。"
  },
  AvgDialog_18720_Content_69 = {
    Text = "好久不見，守密人%sirormadam%。"
  },
  AvgDialog_18720_Content_7 = {
    Text = "筆記上記錄的發現時間是半年前，死亡時間只會更早……"
  },
  AvgDialog_18720_Content_8 = {
    Text = "換言之，這很可能是已知最早的“獵顱者”受害者。可警局的資料中從未提及……"
  },
  AvgDialog_18720_Content_9 = {
    Text = "這裡連個像樣的醫院和殯儀館都沒有，也沒人會把死人太當回事。"
  },
  AvgDialog_18721_Content_1 = {
    Text = "或許可以試著用精神追溯尋找獵顱者？"
  },
  AvgDialog_18721_Content_2 = {
    Text = "這方法對超維界域的生物收效甚微。"
  },
  AvgDialog_18721_Content_3 = {
    Text = "精神追溯也不是萬能的。"
  },
  AvgDialog_18722_Content_1 = {
    Text = "後會有期"
  },
  AvgDialog_18722_Content_10 = {
    Text = "<LightGray:珍貴的頭顱？會是誰的呢……>"
  },
  AvgDialog_18722_Content_12 = {
    Text = "你看起來很苦惱，%player%。看來你真的很想知道答案？"
  },
  AvgDialog_18722_Content_13 = {
    Text = "馬馬虎虎吧"
  },
  AvgDialog_18722_Content_14 = {
    Text = "咳咳，我可不是那種喜歡隨意打探他人隱私的人。"
  },
  AvgDialog_18722_Content_15 = {
    Text = "是嗎？可你的表情已經出賣自己了哦。"
  },
  AvgDialog_18722_Content_16 = {
    Text = "確實想知道"
  },
  AvgDialog_18722_Content_17 = {
    Text = "我只是想更多地了解您，達芙黛爾夫人。"
  },
  AvgDialog_18722_Content_18 = {
    Text = "哦？某人似乎越來越貪心了。"
  },
  AvgDialog_18722_Content_19 = {
    Text = "給個提示吧：<Yellow:是你之前見過的東西。>"
  },
  AvgDialog_18722_Content_2 = {
    Text = "支援部隊和審查會已經在趕來的路上了，你先留在這裡保護現場。"
  },
  AvgDialog_18722_Content_20 = {
    Text = "見過的東西……？"
  },
  AvgDialog_18722_Content_21 = {
    Text = "你苦苦思索，這兩天發生的故事、見過的人走馬燈一般在你眼前飛速掠過。"
  },
  AvgDialog_18722_Content_24 = {
    Text = "難道是諾里奇街上，那個和你一模一樣的……"
  },
  AvgDialog_18722_Content_25 = {
    Text = "真聰明。"
  },
  AvgDialog_18722_Content_26 = {
    Text = "可為什麼……我不明白。"
  },
  AvgDialog_18722_Content_27 = {
    Text = "達芙黛爾眺望著遠方地平線上朦朧的晨光，薄涼的冷風吹起她長長的頭髮。"
  },
  AvgDialog_18722_Content_28 = {
    Text = "那是一個“標本”，它屬於我曾經的主人。"
  },
  AvgDialog_18722_Content_29 = {
    Text = "告訴你一個秘密：我現在的臉正是仿照它做出來的。"
  },
  AvgDialog_18722_Content_3 = {
    Text = "放心吧，這次我一定乖乖等著，絕不到處亂跑了。"
  },
  AvgDialog_18722_Content_31 = {
    Text = "<LightGray:原來這不是達芙黛爾夫人真正的模樣……>"
  },
  AvgDialog_18722_Content_32 = {
    Text = "這次你可幫了我大忙。\n把這麼稚嫩的守密人拿去當誘餌，我到現在都無法原諒自己。"
  },
  AvgDialog_18722_Content_33 = {
    Text = "……沒關係，只要能完成調查，我不介意被利用一次。"
  },
  AvgDialog_18722_Content_34 = {
    Text = "是嗎，可是我很過意不去呢。所以……"
  },
  AvgDialog_18722_Content_35 = {
    Text = "作為賠禮道歉，我可以答應你一個請求。"
  },
  AvgDialog_18722_Content_36 = {
    Text = "免費的哦~"
  },
  AvgDialog_18722_Content_38 = {
    Text = "站在你面前的可是一位以殘酷精明著稱的商人，她所掌握的情報、禁忌知識與珍貴藏品是多少人夢寐以求的東西。"
  },
  AvgDialog_18722_Content_39 = {
    Text = "而現在，她能無償答應你的一個請求。"
  },
  AvgDialog_18722_Content_4 = {
    Text = "想不到能這麼快搞定調查。\n幹得漂亮，%player%。"
  },
  AvgDialog_18722_Content_40 = {
    Text = "<LightGray:不行……朵爾小姐如果知道我在外面隨意和別人做交易，一定會生氣的。>"
  },
  AvgDialog_18722_Content_41 = {
    Text = "腦子裡掠過無數種可能，失傳的黃金造物、最美味的小蛋糕、巨額雷歐坊……"
  },
  AvgDialog_18722_Content_42 = {
    Text = "紛亂的念頭不斷交織、碰撞，最後都如潮水般退去——你決定遵從內心的本能。"
  },
  AvgDialog_18722_Content_43 = {
    Text = "想好你的請求了嗎？可不能太貪心哦。"
  },
  AvgDialog_18722_Content_44 = {
    Text = "想好了，我的要求很簡單。"
  },
  AvgDialog_18722_Content_45 = {
    Text = "讓我看看你真實的樣子吧。"
  },
  AvgDialog_18722_Content_47 = {
    Text = "就這麼簡單？你可要想清楚了，我能給你很多東西，隨便一件都比它更有價值。"
  },
  AvgDialog_18722_Content_48 = {
    Text = "價值究竟幾何，取決於我的判斷。除此之外，我沒有別的要求了。"
  },
  AvgDialog_18722_Content_49 = {
    Text = "不愧是守密人%sirormadam%，總能讓我感到意外。那麼……"
  },
  AvgDialog_18722_Content_5 = {
    Text = "咳咳，這次多虧達芙黛爾夫人。"
  },
  AvgDialog_18722_Content_50 = {
    Text = "達芙黛爾緩步向你走來。風吹起她長長的頭髮，就像上下翻飛的灰色海浪。"
  },
  AvgDialog_18722_Content_51 = {
    Text = "你們隔得很近，你幾乎能從她的眼睛裡看見自己的倒影。"
  },
  AvgDialog_18722_Content_52 = {
    Text = "記得保密哦，%player%。"
  },
  AvgDialog_18722_Content_53 = {
    Text = "話音剛落，她的五官就像入了水的油彩一般，開始暈染、稀釋……"
  },
  AvgDialog_18722_Content_54 = {
    Text = "最後，你終於看清了她的臉。"
  },
  AvgDialog_18722_Content_55 = {
    Text = "那是一張@2的臉，它讓你聯想到了很多東西。"
  },
  AvgDialog_18722_Content_56 = {
    Text = "比如雨後潮濕的薄霧，在角落裡悄悄綻放的水仙，又比如蜷縮在黑暗裡的小動物……"
  },
  AvgDialog_18722_Content_57 = {
    Text = "你還未來得及細看，那張臉就像水滴落入水中，再次消融不見了。"
  },
  AvgDialog_18722_Content_58 = {
    Text = "原來……這才是你真實的模樣啊。"
  },
  AvgDialog_18722_Content_59 = {
    Text = "怎麼樣，是不是覺得很難看？"
  },
  AvgDialog_18722_Content_6 = {
    Text = "舉手之勞罷了，我也找回了原本丟失的東西。"
  },
  AvgDialog_18722_Content_60 = {
    Text = "你搖了搖頭。"
  },
  AvgDialog_18722_Content_61 = {
    Text = "令人意外……卻又很像你的一張臉。"
  },
  AvgDialog_18722_Content_62 = {
    Text = "晨曦的陽光一掃雨水的濕氣，她周身都籠罩在柔軟的光暈裡。"
  },
  AvgDialog_18722_Content_63 = {
    Text = "說實話……剛才我甚至有些害怕，隨後我又驚訝於自己的害怕。"
  },
  AvgDialog_18722_Content_64 = {
    Text = "十年、五十年？我已經不記得自己上一次害怕是在多少年前了。"
  },
  AvgDialog_18722_Content_65 = {
    Text = "害怕……？難道是怕我覺得你很難看？"
  },
  AvgDialog_18722_Content_66 = {
    Text = "達芙黛爾並不回應，只輕輕揉了揉你的頭髮。"
  },
  AvgDialog_18722_Content_67 = {
    Text = "%player%，現在你可是這世上唯一見過“我”的人了。"
  },
  AvgDialog_18722_Content_68 = {
    Text = "呵呵，你有個小把柄握在我手上了。"
  },
  AvgDialog_18722_Content_69 = {
    Text = "趁現在還沒失憶，我要趕緊把你的臉畫到紙上。"
  },
  AvgDialog_18722_Content_7 = {
    Text = "從商人的角度來看，這是一次完美的“交易”。"
  },
  AvgDialog_18722_Content_70 = {
    Text = "達芙黛爾笑了起來，眼睛彎成一個好看的弧度。"
  },
  AvgDialog_18722_Content_71 = {
    Text = "真是個傻孩子。"
  },
  AvgDialog_18722_Content_72 = {
    Text = "好了，你那些審查會和警局的朋友應該都在趕來的路上了吧？"
  },
  AvgDialog_18722_Content_73 = {
    Text = "<Shake:原來你都知道……>"
  },
  AvgDialog_18722_Content_74 = {
    Text = "我可沒心情應付那些無聊的盤查。\n下次找個沒人打擾的地方，請你喝杯咖啡。"
  },
  AvgDialog_18722_Content_75 = {
    Text = "再會，我的守密人%sirormadam%。"
  },
  AvgDialog_18722_Content_76 = {
    Text = "啊？哦……再、再見，達芙黛爾夫人。"
  },
  AvgDialog_18722_Content_77 = {
    Text = "達芙黛爾朝你揮了揮手，轉身離去。"
  },
  AvgDialog_18722_Content_78 = {
    Text = "你遙望著她悠閒的背影，心情也變得輕鬆起來。"
  },
  AvgDialog_18722_Content_79 = {
    Text = "連綿的陰霾徹底褪去，天空終於放晴了。陽光透過慵懶的雲彩，將你全身都烤得暖洋洋的。"
  },
  AvgDialog_18722_Content_8 = {
    Text = "丟失的東西……"
  },
  AvgDialog_18722_Content_80 = {
    Text = "不知為何，你有種預感——"
  },
  AvgDialog_18722_Content_81 = {
    Text = "你們還會不斷相遇的，在不同的時間和空間維度裡。"
  },
  AvgDialog_18722_Content_9 = {
    Text = "獵顱者從我這裡拿走了一顆<Yellow:珍貴的頭顱>，所以我來這裡做點小小的調查。就這麼簡單。"
  },
  AvgDialog_18723_Content_1 = {
    Text = "咳咳，超維界域的喚醒體可真難追……"
  },
  AvgDialog_18723_Content_11 = {
    Text = "牠趁你暫時離開，我和奧爾拉小姐在一旁聊天的時候跑了。"
  },
  AvgDialog_18723_Content_12 = {
    Text = "不過無需擔心，跟我走的話，你很快就能見到牠。"
  },
  AvgDialog_18723_Content_13 = {
    Text = "是在<Blue:瑞尼鎮北部的荒地>裡吧？"
  },
  AvgDialog_18723_Content_14 = {
    Text = "哦？看來我們的小小偵探很敏銳嘛。你怎麼看出來的？"
  },
  AvgDialog_18723_Content_15 = {
    Text = "那傢伙身上有融蝕現象，很可能和三年前的北部發生的瘟疫有關。"
  },
  AvgDialog_18723_Content_16 = {
    Text = "現在牠受了這麼重的傷，又面臨我們和警局的雙重夾擊，能去的地方不多了。"
  },
  AvgDialog_18723_Content_17 = {
    Text = "不管牠最後是不是躲在荒地，那裡都是一個值得調查的突破口。"
  },
  AvgDialog_18723_Content_18 = {
    Text = "不錯，很聰明。不過你知道那片荒地面積有多大嗎？"
  },
  AvgDialog_18723_Content_19 = {
    Text = "接近50平方英里。\n你也不想寶貴的假期都浪費在地質探險和人口普查工作上吧？"
  },
  AvgDialog_18723_Content_2 = {
    Text = "你踉踉蹌蹌跑到一個路口。"
  },
  AvgDialog_18723_Content_20 = {
    Text = "而我呢，恰好能找出牠準確的藏身處。\n要跟我走一趟嗎？"
  },
  AvgDialog_18723_Content_21 = {
    Text = "別答應。她很危險，千萬不要被她迷惑。"
  },
  AvgDialog_18723_Content_22 = {
    Text = "我數三下哦。三、二……"
  },
  AvgDialog_18723_Content_26 = {
    Text = "唔，真是聽話的好孩子。"
  },
  AvgDialog_18723_Content_27 = {
    Text = "達芙黛爾夫人，我可以和你們一同前往嗎？"
  },
  AvgDialog_18723_Content_28 = {
    Text = "瘦弱的女孩從你們身後的樹影中走出，眼裡滿是擔憂。"
  },
  AvgDialog_18723_Content_29 = {
    Text = "我知道你很擔心%player%。"
  },
  AvgDialog_18723_Content_3 = {
    Text = "這裡早已沒有獵顱者的身影，只剩達芙黛爾和她腳下拖長的身影。"
  },
  AvgDialog_18723_Content_30 = {
    Text = "但是很抱歉，我的小玫瑰。這次我只能帶一個人。"
  },
  AvgDialog_18723_Content_31 = {
    Text = "深夜的街上寒風凜冽，奧爾拉不由裹緊了足以禦寒防風的信紙。她揚起蒼白的小臉，嚴肅地看著達芙黛爾。"
  },
  AvgDialog_18723_Content_32 = {
    Text = "為什麼？我雖然不擅長戰鬥，但多一個幫手總是好的，不是麼？"
  },
  AvgDialog_18723_Content_33 = {
    Text = "我只帶一個。抱歉，小玫瑰，我有我的理由。"
  },
  AvgDialog_18723_Content_35 = {
    Text = "達芙黛爾夫人，你一定會護送%player%%sirormadam%平安歸來的，對吧？"
  },
  AvgDialog_18723_Content_36 = {
    Text = "達芙黛爾望著路燈下不斷翻飛的飛蛾，從嘴裡悠然吐出一個圓圓的煙圈。"
  },
  AvgDialog_18723_Content_37 = {
    Text = "那是當然，放心吧。"
  },
  AvgDialog_18723_Content_4 = {
    Text = "不知為何，你覺得她已經這樣站了很久很久。"
  },
  AvgDialog_18723_Content_5 = {
    Text = "好像從亙古的過往伊始，她便獨自守在這裡，沉默地看著遠方，不發一言。"
  },
  AvgDialog_18723_Content_6 = {
    Text = "你來了啊。"
  },
  AvgDialog_18723_Content_7 = {
    Text = "達芙黛爾轉過身，表情依舊是淡淡的。"
  },
  AvgDialog_18723_Content_8 = {
    Text = "獵顱者呢？跟丟了？"
  },
  AvgDialog_18723_Content_9 = {
    Text = "對，跟丟了。不過……我想我已經知道答案了。"
  },
  AvgDialog_18724_Content_1 = {
    Text = "來自遠方"
  },
  AvgDialog_18724_Content_10 = {
    Text = "從屍體狀況及目擊證言來看，二人死亡時間相近，不超過半小時。"
  },
  AvgDialog_18724_Content_11 = {
    Text = "死亡地點呢，離得近嗎？"
  },
  AvgDialog_18724_Content_12 = {
    Text = "拉蒙娜搖了搖頭。"
  },
  AvgDialog_18724_Content_13 = {
    Text = "即便開車也要一個多小時，更何況鎮上有車的人很少很少。"
  },
  AvgDialog_18724_Content_14 = {
    Text = "……或許老弗里曼是對的。"
  },
  AvgDialog_18724_Content_15 = {
    Text = "獵顱人是一個組織。可他們的目的究竟是什麼？"
  },
  AvgDialog_18724_Content_16 = {
    Text = "頭@2更多的頭……"
  },
  AvgDialog_18724_Content_17 = {
    Text = "背後忽然刮起一陣冷風。"
  },
  AvgDialog_18724_Content_18 = {
    Text = "你轉過頭，只見那具已被你斬下頭顱的屍體正以極快的速度撲來。"
  },
  AvgDialog_18724_Content_2 = {
    Text = "00：15，奧爾拉的木屋"
  },
  AvgDialog_18724_Content_20 = {
    Text = "給我頭@3給@1頭@4"
  },
  AvgDialog_18724_Content_21 = {
    Text = "你迅速錯開身體。屍體一舉撞破前方的玻璃，瞬間消失在茫茫夜色中。"
  },
  AvgDialog_18724_Content_22 = {
    Text = "好快的速度……是超維界域的喚醒體？"
  },
  AvgDialog_18724_Content_23 = {
    Text = "正疑惑之際，一股濃郁的水仙氣味便將你層層包裹。"
  },
  AvgDialog_18724_Content_24 = {
    Text = "紫色的裙襬飛似地從你眼前掠過，隨後也消失在你面前。"
  },
  AvgDialog_18724_Content_25 = {
    Text = "達芙黛爾夫人……？"
  },
  AvgDialog_18724_Content_26 = {
    Text = "快追上去，不能讓重要線索跑了。"
  },
  AvgDialog_18724_Content_3 = {
    Text = "你找了個僻靜的角落，將剛才發生的情況向拉蒙娜說明了一番。"
  },
  AvgDialog_18724_Content_4 = {
    Text = "當然，略去你差點被割喉的那部分。"
  },
  AvgDialog_18724_Content_6 = {
    Text = "我從下午到現在已經呼叫了<Red:35>次，你都沒有任何回音。"
  },
  AvgDialog_18724_Content_7 = {
    Text = "抱歉，事發突然……"
  },
  AvgDialog_18724_Content_8 = {
    Text = "……下不為例。"
  },
  AvgDialog_18724_Content_9 = {
    Text = "白天新增的受害者身份調查清楚了。\n木匠戴蒙·門德斯，35歲；閒散青年托馬斯·奎倫，23歲。"
  },
  AvgDialog_18725_Content_1 = {
    Text = "一個倒扣的相框吸引了你的注意。"
  },
  AvgDialog_18725_Content_10 = {
    Text = "<RedItalic:星期天他喝了十瓶酒，丟掉了工作，丟掉了老婆。>"
  },
  AvgDialog_18725_Content_11 = {
    Text = "有人輕輕哼著毫無節律變化的童謠。"
  },
  AvgDialog_18725_Content_12 = {
    Text = "乾澀的旋律如同一隻潮濕無形的手，輕撫著你後頸處早已直立的汗毛。"
  },
  AvgDialog_18725_Content_14 = {
    Text = "伴隨木板嘎吱作響的聲音，哈莉特悄無聲息地站在幽暗的廊道前。"
  },
  AvgDialog_18725_Content_15 = {
    Text = "沒錯，老弗里曼是我的丈夫。"
  },
  AvgDialog_18725_Content_16 = {
    Text = "什麼？！"
  },
  AvgDialog_18725_Content_17 = {
    Text = "那時候，所有人都以為我死了。我的丈夫也一樣。"
  },
  AvgDialog_18725_Content_18 = {
    Text = "後來，不知過了多久，我又活了過來……可是我變得有些不一樣了。"
  },
  AvgDialog_18725_Content_19 = {
    Text = "你默然不語，心中已經猜到了後面的故事。"
  },
  AvgDialog_18725_Content_2 = {
    Text = "廚房裡傳來一陣陣燒水的咕嚕聲，哈莉特夫人還在裡面忙碌著。"
  },
  AvgDialog_18725_Content_20 = {
    Text = "人類感染融蝕後，精神會出現不可逆的損傷，進而引發各式各樣的併發症。"
  },
  AvgDialog_18725_Content_21 = {
    Text = "哈莉特夫人會變成這樣並不奇怪。"
  },
  AvgDialog_18725_Content_22 = {
    Text = "我開始渴望頭顱，很多的頭顱……於是我偷偷地跑去一個亂葬崗。"
  },
  AvgDialog_18725_Content_23 = {
    Text = "我趴在老皮諾科的身上，用生鏽的鐮刀使勁地割他的頭。\n可那時的我太虛弱了，連刀都握不穩……"
  },
  AvgDialog_18725_Content_24 = {
    Text = "然後你猜我遇到了誰？"
  },
  AvgDialog_18725_Content_27 = {
    Text = "他變胖了，也變老了，還成了一個酒鬼。"
  },
  AvgDialog_18725_Content_28 = {
    Text = "呵呵……這個世道總是會變著花樣來折磨我們這些可憐蟲。"
  },
  AvgDialog_18725_Content_29 = {
    Text = "他拎著酒，像看一條野狗一樣看著我。"
  },
  AvgDialog_18725_Content_3 = {
    Text = "你輕輕將相框翻了過來。"
  },
  AvgDialog_18725_Content_30 = {
    Text = "他一直在笑。是的，我知道我那時候的樣子一定既可憐，又可笑。"
  },
  AvgDialog_18725_Content_31 = {
    Text = "可他竟然……完全不認識我了。"
  },
  AvgDialog_18725_Content_32 = {
    Text = "……原來你就是他說的那個獵顱者。"
  },
  AvgDialog_18725_Content_33 = {
    Text = "哈莉特機械地向右歪了歪頭，脖頸處傳來“喀啦喀啦”的聲音。"
  },
  AvgDialog_18725_Content_34 = {
    Text = "是啊。明知道他早就不記得我了，還是會跑去偷偷看他。"
  },
  AvgDialog_18725_Content_35 = {
    Text = "然後你聽到了我們的對話，知道我在調查命案，這才決定跟蹤偷襲？"
  },
  AvgDialog_18725_Content_37 = {
    Text = "你和他們果然不一樣。我說了這麼多，你卻還能保持鎮定。"
  },
  AvgDialog_18725_Content_38 = {
    Text = "你輕嘆一聲，低頭看著身旁緊鎖的房門。"
  },
  AvgDialog_18725_Content_39 = {
    Text = "暗紅的血像黏稠的糖漿從門縫中緩緩溢出，一點點爬到你的腳下。"
  },
  AvgDialog_18725_Content_4 = {
    Text = "這是一張老舊的全家福。妻子和孩子的臉早已模糊不清，只留下站在最左側的丈夫。"
  },
  AvgDialog_18725_Content_40 = {
    Text = "你知道嗎……"
  },
  AvgDialog_18725_Content_41 = {
    Text = "這裡的地上、天花板上、櫃子上……都是血和死人的味道。"
  },
  AvgDialog_18725_Content_42 = {
    Text = "從進來的第一刻起，我就什麼都知道了。"
  },
  AvgDialog_18725_Content_5 = {
    Text = "他身材魁梧，姿態閒適地靠在剛建好的新房前，面對鏡頭露出燦爛無比的笑容。"
  },
  AvgDialog_18725_Content_6 = {
    Text = "你望著他略顯熟悉的眉眼，一個荒謬的念頭忽然閃電般劃過腦海。"
  },
  AvgDialog_18725_Content_8 = {
    Text = "難道他是哈莉特夫人的丈夫？"
  },
  AvgDialog_18725_Content_9 = {
    Text = "<RedItalic:老弗里曼，老弗里曼，又窮又瘋的酒鬼老弗里曼……>"
  },
  AvgDialog_18726_Content_1 = {
    Text = "你向巷道深處走去，雨水早已將你的外套打濕。"
  },
  AvgDialog_18726_Content_11 = {
    Text = "巷道外的街道上傳來不緊不慢的腳步聲，一個模糊的身影出現在路燈下。"
  },
  AvgDialog_18726_Content_12 = {
    Text = "這裡很危險，趕緊離——"
  },
  AvgDialog_18726_Content_13 = {
    Text = "那是一個女人。"
  },
  AvgDialog_18726_Content_14 = {
    Text = "她孤零零地站在路燈下，手裡拎著一顆肥碩的頭顱，尺寸與你身後無頭屍身的脖頸完美適配。"
  },
  AvgDialog_18726_Content_15 = {
    Text = "鮮血從頭顱頸部滴答落下，順著地磚的縫緩慢遊走。"
  },
  AvgDialog_18726_Content_16 = {
    Text = "站在那裡別動。\n你是誰？"
  },
  AvgDialog_18726_Content_17 = {
    Text = "昏黃的路燈不斷明滅，發出令人煩躁的電流聲。"
  },
  AvgDialog_18726_Content_18 = {
    Text = "女人抬起頭，你終於辨清了她的面容。"
  },
  AvgDialog_18726_Content_2 = {
    Text = "暗紅的血從陰影中流出，張開猙獰的觸角，向你發出無聲的邀約。"
  },
  AvgDialog_18726_Content_20 = {
    Text = "<Gray:達芙……黛爾夫人？>"
  },
  AvgDialog_18726_Content_3 = {
    Text = "這裡很安靜，你只聽得見雨聲、腳步聲和呼吸聲。"
  },
  AvgDialog_18726_Content_4 = {
    Text = "它們像紛亂交織的鼓點，越來越快，越來越響，直到你來到巷道的盡頭。"
  },
  AvgDialog_18726_Content_5 = {
    Text = "肥碩的屍體被隨意棄置在垃圾堆上，軟軟地耷拉著。"
  },
  AvgDialog_18726_Content_6 = {
    Text = "脖頸處的切面模糊不堪，從血管裡湧出一股股暗紅的血。"
  },
  AvgDialog_18726_Content_7 = {
    Text = "無需觸碰，你也知道那血一定是溫熱的。"
  },
  AvgDialog_18726_Content_8 = {
    Text = "頭顱缺失，脖頸上有鋸齒形傷痕……"
  },
  AvgDialog_18726_Content_9 = {
    Text = "是“獵顱者”。"
  },
  AvgDialog_18727_Content_10 = {
    Text = "如果她沒有撒謊或者看花眼的話，是的。"
  },
  AvgDialog_18727_Content_11 = {
    Text = "<Blue:先遣隊>已在一週前抵達瑞尼鎮，並在死亡現場檢測到銀芯活躍的跡象。"
  },
  AvgDialog_18727_Content_12 = {
    Text = "算上剛才那三起，這已經是瑞尼鎮發生的第八起<Blue:獵顱者行兇事件>了。"
  },
  AvgDialog_18727_Content_13 = {
    Text = "獵顱者？這裡的人是這麼稱呼兇手的？"
  },
  AvgDialog_18727_Content_14 = {
    Text = "很形象，不是麼？託他的福，這裡已經沒人敢在天黑後上街了。"
  },
  AvgDialog_18727_Content_15 = {
    Text = "你望向眼前淒清的街道。"
  },
  AvgDialog_18727_Content_16 = {
    Text = "不過晚上8點，附近所有的門窗都鎖得死死的。恐懼從黑洞洞的窗戶裡溢出，無言地籠罩四周。"
  },
  AvgDialog_18727_Content_17 = {
    Text = "除了一兩聲拖長的狗吠，這裡寂寥無聲。"
  },
  AvgDialog_18727_Content_18 = {
    Text = "淅瀝瀝……"
  },
  AvgDialog_18727_Content_2 = {
    Text = "貝倫·斯托克，46歲，9月12日死於家中廚房。\n<Red:頭顱缺失>，屍身其餘部分完好，脖頸處有鋸齒形割傷。"
  },
  AvgDialog_18727_Content_20 = {
    Text = "微涼的細雨自夜空中滴落，在你面前蒙上了一層白色的細紗。"
  },
  AvgDialog_18727_Content_21 = {
    Text = "我聽到你那邊有雨聲。帶傘了嗎？"
  },
  AvgDialog_18727_Content_22 = {
    Text = "<Shake:糟糕。你總是帶傘的那一個，所以……>"
  },
  AvgDialog_18727_Content_23 = {
    Text = "看樣子我還需要適應一下沒有你的生活。"
  },
  AvgDialog_18727_Content_25 = {
    Text = "抱歉，這次沒能和你一同前往。"
  },
  AvgDialog_18727_Content_26 = {
    Text = "朵兒小姐堅持要我留下，和她做一些據說“很重要”的融蝕研究……"
  },
  AvgDialog_18727_Content_27 = {
    Text = "<Small:拉蒙娜，幫我遞一下第五排架子上第三層的銀芯樣本，編號SI-3007……>"
  },
  AvgDialog_18727_Content_29 = {
    Text = "好好照顧自己，%player%。至於住宿……<Blue:奧爾拉>小姐會安排好一切。"
  },
  AvgDialog_18727_Content_3 = {
    Text = "德懷特·威廉姆斯，56歲，9月13日死於德曼街口。\n<Red:頭顱缺失>，屍身其餘部分完好，脖頸處有鋸齒形割傷。"
  },
  AvgDialog_18727_Content_30 = {
    Text = "奧爾拉小姐？難怪在學校很少見到她，竟然住在外面？"
  },
  AvgDialog_18727_Content_31 = {
    Text = "彌薩格可不是什麼只進不出的集中營。"
  },
  AvgDialog_18727_Content_32 = {
    Text = "危害性較低的喚醒體可以外出度假、住宿、探親。\n條件很簡單：提前申請，別惹麻煩。"
  },
  AvgDialog_18727_Content_33 = {
