  },
  AvgDialog_18768_Content_2 = {
    Text = "剛才念在昔日的情分上，兄弟們都沒下死手。"
  },
  AvgDialog_18768_Content_20 = {
    Text = "一顆流星自夜空中劃過，現在正是許願的好時機。"
