  AvgDialog_18769_Content_73 = {
    Text = "你可是堂堂迷宮之主，沒有什麼東西能真正傷害到你。"
  },
  AvgDialog_18769_Content_75 = {
    Text = "阿格里帕罕見地陷入沉默，看來她還未從往日的陰影中走出。"
  },
  AvgDialog_18769_Content_76 = {
    Text = "<LightGray:如果真能改變過去就好了……這樣既能幫到她，也能走出眼下的困境。>"
