  AvgDialog_18769_Content_78 = {
    Text = "你竭力在殘缺的記憶中搜尋著可能有用的資訊。"
  },
  AvgDialog_18769_Content_79 = {
    Text = "入夢無法改變過去，但它能影響未來。所以在入夢期間，守密人必須要學會克制。"
  },
  AvgDialog_18769_Content_8 = {
    Text = "呵呵，兄弟們都在為了偉大的事業奮鬥，只有你還願意留下來繼續當狗。"
  },
  AvgDialog_18769_Content_80 = {
    Text = "影響未來？"
