  AvgDialog_18802_Content_18 = {
    Text = "我們會找到他，然後讓他付出代價。\n我向你發誓"
  },
  AvgDialog_18802_Content_19 = {
    Text = "謝謝、謝謝你們……謝謝你們…"
  },
  AvgDialog_18802_Content_2 = {
    Text = "上次我抵抗他，反而……反而……我做不到嗚嗚嗚…"
  },
  AvgDialog_18802_Content_20 = {
    Text = "落日金黃的餘暉穿透鐘樓的巨大透明鐘面，灑落到女孩的身上"
  },
  AvgDialog_18802_Content_21 = {
    Text = "艾繼絲側轉過身，將一隻手貼在玻璃上，眯著眼睛迎向溫暖的陽光"
  },
  AvgDialog_18802_Content_22 = {
    Text = "今天，看得見太陽耶…"
  },
  AvgDialog_18802_Content_24 = {
    Text = "像是被難得的晴天所振奮，她撐起身體，搖搖晃晃地走到一塊較為乾淨的玻璃前。"
  },
  AvgDialog_18802_Content_25 = {
    Text = "模糊的視線終於變得清晰，她注視著那些或熟悉或陌生的街道，恍惚間，耳邊似是響起了誰的低語。"
  },
  AvgDialog_18802_Content_26 = {
    Text = "看，那個聲音說，今晚一定能看到燦爛的星空。"
  },
  AvgDialog_18802_Content_28 = {
    Text = "女孩低下頭，露出懷念的微笑。"
  },
  AvgDialog_18802_Content_29 = {
    Text = "以前，每到能夠看到太陽的日子，提尤格就會在晚上偷偷帶著我上來。"
  },
  AvgDialog_18802_Content_3 = {
    Text = "不要再這樣了，不要再強迫我做這種事情了"
  },
  AvgDialog_18802_Content_30 = {
    Text = "莎拉小姐從來不許我們來這裡，她說這裡太危險了，我們會很容易受傷。但提尤格才不管這些。"
  },
  AvgDialog_18802_Content_32 = {
    Text = "他和詹金一樣，機靈又勇敢，總能知道別人不知道的小路和機關。"
  },
  AvgDialog_18802_Content_33 = {
    Text = "只要有他帶著，我們就不會被莎拉小姐發現。"
  },
  AvgDialog_18802_Content_34 = {
    Text = "只要有他帶著，這裡就永遠是我們的秘密基地。"
  },
  AvgDialog_18802_Content_35 = {
    Text = "他告訴我，我得多和星星接觸，法力才會強大。\n雖然我們在這裡一顆星星也看不著。"
  },
  AvgDialog_18802_Content_36 = {
    Text = "那時他是唯一一個相信我的人。\n相信我能看到那些黑色的東西，告訴我那是魔女的天賦。"
  },
  AvgDialog_18802_Content_37 = {
    Text = "後來他……那之後，醫生們就開始把病人帶出去，不再在濟貧院看診了。我也沒辦法收集證據，沒辦法為提尤格報仇。"
  },
  AvgDialog_18802_Content_38 = {
    Text = "如果我像他一樣聰明，像詹金一樣勇敢，大概早就查清真相了吧。"
  },
  AvgDialog_18802_Content_39 = {
    Text = "但我不是什麼魔女。"
  },
  AvgDialog_18802_Content_4 = {
    Text = "我不想傷害別人，我不想殺人"
  },
  AvgDialog_18802_Content_40 = {
    Text = "我只是一個膽小鬼。"
  },
  AvgDialog_18802_Content_41 = {
    Text = "一個怪物。"
  },
  AvgDialog_18802_Content_42 = {
    Text = "一個……殺人兇手。"
  },
  AvgDialog_18802_Content_43 = {
    Text = "你們知道我是第幾次被人操控嗎？\n你們知道我的手上沾過多少鮮血嗎？"
  },
  AvgDialog_18802_Content_44 = {
    Text = "我害怕極了，怕我自己即將成為的東西。"
  },
  AvgDialog_18802_Content_46 = {
    Text = "曾經我的眼睛很疼，身體也很疼。但現在我卻沒有一點感覺，就像我也是石頭做的一樣。"
  },
  AvgDialog_18802_Content_48 = {
    Text = "該死的，一個兩個到底都跑哪裡去了……"
  },
  AvgDialog_18802_Content_5 = {
    Text = "<Shake:<AvgNormalFont:不！不要！\n不要讓小麥克這樣做，他那麼小，他怎麼能……<Shake:求求你……>>>"
  },
  AvgDialog_18802_Content_50 = {
