  },
  AvgDialog_18802_Content_57 = {
    Text = "紙片上畫著金色的蝴蝶，皺褶的邊緣被人用心壓平疊好，落下的時候，帶有糖果的甜香。"
  },
  AvgDialog_18802_Content_58 = {
    Text = "嗚……艾繼絲…………"
