  AvgDialog_18843_Content_16 = {
    Text = "不……我不要去……我已經去過一次了，我不要……"
  },
  AvgDialog_18843_Content_19 = {
    Text = "……你有哪裡不舒服嗎？"
  },
  AvgDialog_18843_Content_2 = {
    Text = "我真的看見了，真的！那些黑黑的，三角形的。每個去了博士那裡的人，身上都會多出這些東西，好可怕，好可怕。"
  },
  AvgDialog_18843_Content_20 = {
    Text = "我沒有不舒服，能跑能跳，健康著呢！\n但我能看到東西。"
  },
  AvgDialog_18843_Content_21 = {
    Text = "哦？你能看到什麼？"
  },
  AvgDialog_18843_Content_22 = {
    Text = "我和艾繼絲一樣，都會看到黑色的幻覺。\n能不能請你幫幫我呢？"
