  AvgDialog_18847_Content_9 = {
    Text = "不過——在那之前，先解決眼前的傢伙。"
  },
  AvgDialog_18848_Content_1 = {
    Text = "一個又一個異變體在拉蒙娜的劍下消散，艾繼絲的臉色在飄揚的黑色粉塵中顯得愈發蒼白。"
  },
  AvgDialog_18848_Content_2 = {
