  AvgDialog_18852_Content_3 = {
    Text = "好、好的。天啊，這真是……孩子們，孩子們快，到我這裡來。"
  },
  AvgDialog_18852_Content_4 = {
    Text = "動作快，有個棘手的傢伙出來了。"
  },
  AvgDialog_18853_Content_1 = {
    Text = "騷亂結束，人們重新排成了隊伍。\n艾繼絲站在孩子們中間，面色蒼白，微微顫抖。"
