  AvgDialog_18855_Content_21 = {
    Text = "不准開燈，節約用電——**，那個莎拉也太摳門了。還事兒多！就我們這個破地方，哪個小偷高興來……嗯？"
  },
  AvgDialog_18855_Content_22 = {
    Text = "昏黃的光線下，一扇門無聲地敞開。"
