  AvgDialog_18855_Content_3 = {
    Text = "一切沒有開始，沒有結束，你將一直向前，直到生命終結，直到時間——"
  },
  AvgDialog_18855_Content_30 = {
    Text = "悠悠的腳步聲從遠處傳來，在寂靜的走廊中近乎刺耳。"
  },
  AvgDialog_18855_Content_31 = {
    Text = "誰、誰在那裡？\n出來！我、我警告你，我可是有武器的！"
  },
  AvgDialog_18855_Content_32 = {
    Text = "走廊裡沒有一點氣流，燈芯上的火焰卻如被風吹過一般晃動。"
  },
  AvgDialog_18855_Content_33 = {
    Text = "艾繼絲手裡的託盤打著抖，白色的茶杯與茶託 相互敲擊，顫出一串幼鳥臨死前的哀泣。"
  },
  AvgDialog_18855_Content_34 = {
    Text = "腳步聲越來越近，越來越近。布朗的爪子深深陷入詹金肩頭的衣物中，它露出牙齒，發出鼠類特有的尖銳威嚇。"
  },
  AvgDialog_18855_Content_35 = {
