  },
  AvgDialog_18905_Content_26 = {
    Text = "詹金從背包深處摸出兩枚銀色的戒指。"
  },
  AvgDialog_18905_Content_27 = {
    Text = "如果不是你，辦公室右邊抽屜裡的這兩個小玩意，難道還是我憑空變出來的嗎？"
  },
  AvgDialog_18905_Content_28 = {
    Text = "那怎麼在你那裡？還給我，那是其他資助人給我的禮物！"
  },
  AvgDialog_18905_Content_29 = {
    Text = "請相信我，我是把它們當做用來補貼濟貧院的應急品的！我怎麼可能、怎麼可能為了這些東西，傷害這裡的孩子？"
  },
  AvgDialog_18905_Content_3 = {
    Text = "你們怎麼能——"
  },
  AvgDialog_18905_Content_30 = {
    Text = "如果您與這件事毫無瓜葛，那您怎麼解釋這些……孩子呢？"
  },
  AvgDialog_18905_Content_31 = {
    Text = "拉蒙娜指了指地上爬動的怪物。"
  },
  AvgDialog_18905_Content_32 = {
    Text = "……孩子？\n你是說……"
  },
  AvgDialog_18905_Content_33 = {
    Text = "莎拉似乎這才意識到什麼，僵硬地扭過頭去細看那些怪物的形貌。"
  },
  AvgDialog_18905_Content_34 = {
    Text = "這些，是濟貧院失蹤的工人和孩子們吧？"
  },
  AvgDialog_18905_Content_35 = {
    Text = "不，不會的……"
  },
  AvgDialog_18905_Content_36 = {
    Text = "真是吵鬧。"
  },
  AvgDialog_18905_Content_37 = {
    Text = "別去看那些未完成品了。\n匍匐於真正的美吧。"
  },
  AvgDialog_18905_Content_38 = {
    Text = "她將剛剛完工的雕像推到莎拉面前。"
  },
  AvgDialog_18905_Content_39 = {
    Text = "那是一尊孩童的雕像，渾濁的糖殼下，五官栩栩如生。"
  },
  AvgDialog_18905_Content_41 = {
    Text = "雕像的眼球猝然抖動了一下。"
  },
  AvgDialog_18905_Content_43 = {
    Text = "莎拉發出病態的尖叫。"
  },
  AvgDialog_18905_Content_44 = {
    Text = "她蜷起身體，雙手抱住自己的頭，悲切的低語漸漸變得粗啞混亂，難以分辨。"
  },
  AvgDialog_18905_Content_45 = {
    Text = "<Small:我無能，我沒用，我不是一個好院長，我保護不了大家，保護不了孩子們……>"
  },
  AvgDialog_18905_Content_46 = {
    Text = "莎拉小姐，別這樣……我們，大家都明白的，你已經盡力了。"
  },
  AvgDialog_18905_Content_47 = {
    Text = "對不起，小艾繼絲；對不起，小露西；對不起，詹金、亨利、戴安娜……"
  },
  AvgDialog_18905_Content_48 = {
    Text = "莎拉抬起頭，露出完全失控的五官，眼球和唇角像是牽著手舞蹈，扭曲成人類絕對無法呈現的姿態。"
  },
  AvgDialog_18905_Content_5 = {
    Text = "她沒能說完這句話，就看著地面上扭曲的糖人發出恐怖的尖叫。"
  },
  AvgDialog_18905_Content_50 = {
    Text = "周遭宛如沉入水底一般，一瞬間陷入了陰冷的死寂之中。\n無形的壓力突如其來，你猛地喘了一口氣，意識到事情不對。"
  },
  AvgDialog_18905_Content_51 = {
    Text = "糟了，拉蒙娜，快讓其他人離開！"
  },
  AvgDialog_18905_Content_52 = {
    Text = "來不及了。\n年輕的院長頭部如花一般開裂，黑色的黏液噴濺在地上。"
  },
  AvgDialog_18905_Content_54 = {
    Text = "她發出高昂尖銳的嘶鳴，周遭的扭曲肢體回應著她，發出狼嚎般的聲響，迅速裂變成被融蝕侵染的怪物。"
  },
  AvgDialog_18905_Content_6 = {
    Text = "我們怎麼能？這句話該送給你。\n不是你在地下室裡藏的濟貧院幽靈嗎？她都告訴我們了。"
  },
  AvgDialog_18905_Content_7 = {
    Text = "像是被莎拉的尖叫吸引，地面上蠕動的半糖化人形，扭動著向她的方向爬來。"
  },
  AvgDialog_18905_Content_8 = {
    Text = "聽著，莎拉小姐，你的所作所為已經沒法再隱藏下去了。"
  },
  AvgDialog_18905_Content_9 = {
    Text = "請儘快交代濟貧院和雕塑家協會的合作聯繫方式，以及調查員<Blue:肖恩·安德森>的下落。"
  },
  AvgDialog_18906_Content_10 = {
    Text = "那個……"
  },
  AvgDialog_18906_Content_11 = {
    Text = "都說了，今天不開張了，我得去裡面找姐姐。"
  },
  AvgDialog_18906_Content_12 = {
    Text = "孩子懶洋洋的，甚至沒抬眼看他。"
  },
  AvgDialog_18906_Content_13 = {
    Text = "不是的，我是想請教一下……\n請問你知不知道莉莉安濟貧院怎麼走？"
  },
  AvgDialog_18906_Content_15 = {
    Text = "<Small:哪兒來的肥羊……>"
  },
  AvgDialog_18906_Content_17 = {
    Text = "抱歉，我剛剛走神了，沒能聽清。能再說一遍嗎？"
  },
  AvgDialog_18906_Content_18 = {
    Text = "你湊過來點，我指給你看。"
  },
  AvgDialog_18906_Content_19 = {
    Text = "看，就那邊的轉角，近得很。"
  },
  AvgDialog_18906_Content_2 = {
    Text = "你剛剛下車，就被濃重的濕氣和腐朽的臭味壓得透不過氣。"
  },
  AvgDialog_18906_Content_20 = {
    Text = "啊！非常感謝。"
  },
  AvgDialog_18906_Content_21 = {
    Text = "不，我得謝謝你才是。"
  },
  AvgDialog_18906_Content_22 = {
    Text = "謝謝我？"
  },
  AvgDialog_18906_Content_23 = {
    Text = "奧吉爾轉頭看向剛才孩子所在的階梯，那裡空空如也。\n不知何時，兜帽已經溜到了街道的盡頭，手中還抓著奧吉爾的錢包。"
  },
  AvgDialog_18906_Content_24 = {
    Text = "啊，我的錢包——"
  },
  AvgDialog_18906_Content_25 = {
    Text = "倫蒂尼恩常識之二：東區最臭名昭著的歡迎儀式，就是讓你的錢包在不知不覺中消失。"
  },
  AvgDialog_18906_Content_26 = {
    Text = "看來，我們得幫幫奧吉爾了。\n走吧，守密人。"
  },
  AvgDialog_18906_Content_3 = {
    Text = "一股強烈的眩暈感伴隨著劇烈的耳鳴突然向你襲來。\n模糊的畫面在你腦中一閃而過，似乎某個時候，你看過類似的場景。"
  },
  AvgDialog_18906_Content_4 = {
    Text = "是錯覺嗎，還是說，那是你丟失的記憶的一部分？"
  },
  AvgDialog_18906_Content_5 = {
    Text = "這裡既沒有路標，也沒有路牌……和地圖也對不上……"
  },
  AvgDialog_18906_Content_6 = {
    Text = "倫蒂尼恩常識之一：東區讓你迷失的方式，除了不散的濃霧，還有迂回曲折的窄路。"
  },
  AvgDialog_18906_Content_7 = {
    Text = "我去問問路吧。"
  },
  AvgDialog_18906_Content_8 = {
    Text = "路邊慵懶地躺著一個戴破舊兜帽的孩子，斗篷極不合身，襯得身量分外矮小。"
  },
  AvgDialog_18906_Content_9 = {
    Text = "奧吉爾走向那個孩子，輕鞠一躬。"
  },
  AvgDialog_18907_Content_10 = {
    Text = "詹金！你怎麼…不能帶資助人來<Blue:醫護區>的，要被資助人看到了就……"
  },
  AvgDialog_18907_Content_11 = {
    Text = "你向拉蒙娜使了個眼色，拉蒙娜走向艾繼絲，溫柔地詢問。"
  },
  AvgDialog_18907_Content_12 = {
    Text = "艾繼絲，能不能跟我們講講，為什麼資助人不能來醫護區？"
  },
  AvgDialog_18907_Content_13 = {
    Text = "這、這…我…他們……他們很虛弱……"
  },
  AvgDialog_18907_Content_14 = {
    Text = "艾繼絲滿臉猶豫，她看看身後的病人，又看看衣著光鮮的你們，吞吐著不知如何作答。"
  },
  AvgDialog_18907_Content_15 = {
    Text = "借此機會，你和奧吉爾靠近了病床上的老者，仔細觀察。"
  },
  AvgDialog_18907_Content_16 = {
    Text = "老者被粗布條綁住手腳，固定在了床上。他身上有著奇怪的傷痕，乍一看像是扭曲的縫合痕跡，尚未痊癒的皮肉間滿是漆黑的黏液。"
  },
  AvgDialog_18907_Content_17 = {
    Text = "艾繼絲，這次視察會決定我們是否對莉莉安濟貧院提供經濟資助。\n你應該能明白，沒有資助人願意讓自己的錢流入騙子手中。"
  },
  AvgDialog_18907_Content_18 = {
    Text = "他們不會傷害你，不要抗拒他們。"
  },
  AvgDialog_18907_Content_19 = {
    Text = "艾繼絲臉上的掙扎在片刻喘息後消失，她深呼吸了一口氣，如蚊蠅般細聲回復。"
  },
  AvgDialog_18907_Content_2 = {
    Text = "詹金領著你們穿過後院，指向角落的一棟小破屋。"
  },
  AvgDialog_18907_Content_20 = {
    Text = "<Small:莎拉小姐說，資助人如果看到了這些病人，他們就會覺得我們是個無底洞……>"
  },
  AvgDialog_18907_Content_21 = {
    Text = "你就不該聽那個臭女人的話！這幾個資助人會幫我們解決<Yellow:濟貧院幽靈>，她們也是來找人的，肯定也會找到我的姐姐……"
  },
  AvgDialog_18907_Content_22 = {
    Text = "可醫護區太危險了！"
  },
  AvgDialog_18907_Content_23 = {
    Text = "艾繼絲拔高的尾音戛然而止，她不安地偏頭看了眼失去意識的老人，才將詹金拉離了病床邊。"
  },
  AvgDialog_18907_Content_24 = {
    Text = "萬一傳染給你和資助人可怎麼辦……"
  },
  AvgDialog_18907_Content_25 = {
    Text = "艾繼絲緊張又無力地駁斥著詹金，她緊緊抱著小熊玩偶，白色衣袖順著小臂滑落，露出猙獰可怖的黑色縫合痕跡和兩道紅腫勒痕。"
  },
  AvgDialog_18907_Content_26 = {
    Text = "女孩的手臂纖巧伶仃，盤踞其上的黑色裂口形似巨型百足蟲，邊緣還在緩緩溢出黑色的黏液，令人不寒而慄。"
  },
  AvgDialog_18907_Content_27 = {
    Text = "艾繼絲，你胳膊上的傷……"
  },
  AvgDialog_18907_Content_28 = {
    Text = "艾繼絲慌亂地攏起袖子，搖頭躲避拉蒙娜的視線。"
  },
  AvgDialog_18907_Content_29 = {
    Text = "這是上回、上回不小心從樓梯上摔下來時弄的。"
  },
  AvgDialog_18907_Content_3 = {
    Text = "從窗外望去，就能看見艾繼絲的奔忙身影。\n她抱著鐵盆，匆匆忙忙地將滿是髒污的繃帶從病床邊端去髒衣堆。"
  },
  AvgDialog_18907_Content_30 = {
    Text = "這個縫合痕跡可不像普通的摔傷剮蹭。"
  },
  AvgDialog_18907_Content_31 = {
    Text = "看吧，他們能“看見”。\n把一切都告訴他們，他們是最後的轉機。"
  },
  AvgDialog_18907_Content_32 = {
    Text = "<Small:他們會有危險的，不可以……>"
  },
  AvgDialog_18907_Content_33 = {
    Text = "聽我說，艾繼絲。只有告訴我們真相，我們才能真正判斷你們需要什麼樣的幫助。"
  },
  AvgDialog_18907_Content_34 = {
    Text = "在你的身側，老人喉嚨裡發出咯咯的怪響，乾瘦的手臂扯斷了束縛的布條猛地一抬——"
  },
  AvgDialog_18907_Content_4 = {
    Text = "嗯？怎麼了？"
  },
  AvgDialog_18907_Content_5 = {
    Text = "似乎是聽見了某人的呼喚，她放下鐵盆，躬下腰湊在床邊。\n從你們的角度，已經看不見她的小小身影，只有細聲細氣的話語傳來。"
  },
  AvgDialog_18907_Content_6 = {
    Text = "羅伯特爺爺，您別起來，我把水端過來給您。"
  },
  AvgDialog_18907_Content_7 = {
    Text = "別這麼說，您的病一定會好起來的。\n那時候，我們就能去德萊爾公園玩，再一起喂鴿子了。"
  },
  AvgDialog_18907_Content_8 = {
    Text = "“砰”地一下，詹金推開了小屋的門。\n艾繼絲嚇了一跳，慌亂地差點把水灑到病人身上。"
  },
  AvgDialog_18907_Content_9 = {
    Text = "看，這些就是<Yellow:病瘋子>。"
  },
  AvgDialog_18908_Content_1 = {
    Text = "非禮勿言"
  },
  AvgDialog_18908_Content_10 = {
    Text = "見到糖果的瞬間，艾繼絲的臉色白了白，但仍是小心地接過。"
  },
  AvgDialog_18908_Content_11 = {
    Text = "你還記得我們遇見那天的事情嗎？"
  },
  AvgDialog_18908_Content_12 = {
    Text = "嗯，我永遠也不會忘記的。"
  },
  AvgDialog_18908_Content_13 = {
    Text = "10日前，倫蒂尼恩東區\n莉莉安濟貧院"
  },
  AvgDialog_18908_Content_14 = {
    Text = "夜半時分，東區一片晦暗。不論是街燈還是月光，都被彌漫的濃霧吞吃殆盡，只留幾個模糊的虛影在空中晃動。"
  },
  AvgDialog_18908_Content_15 = {
    Text = "白色少女懷抱著罪惡與恐懼，在昏暗空曠的濟貧院前院中奔跑。\n直至撞上陰影中潛藏的陌生之物，才疼痛得驚呼出聲。"
  },
  AvgDialog_18908_Content_16 = {Text = "哎喲！"},
  AvgDialog_18908_Content_18 = {
    Text = "你、你不是小麥克，也不是小露西！你到底是誰……！"
  },
  AvgDialog_18908_Content_19 = {
    Text = "我還要問你是什麼人呢！大半夜的不睡覺在外面晃蕩，嚇了我一跳。"
  },
  AvgDialog_18908_Content_2 = {
    Text = "剛剛在病瘋子那裡，你沒受傷吧？"
  },
  AvgDialog_18908_Content_20 = {
    Text = "對、對不起，我以為遇上了……"
  },
  AvgDialog_18908_Content_21 = {
    Text = "遇上什麼？"
  },
  AvgDialog_18908_Content_22 = {
    Text = "遇上了…幽靈……沒錯，我還以為遇上了<Red:濟貧院幽靈>……"
  },
  AvgDialog_18908_Content_23 = {
    Text = "幽靈？什麼亂七八糟的。我老實和你說了吧，我確實不是這破地方的人。\n我叫詹金，這是布朗。"
  },
  AvgDialog_18908_Content_25 = {
    Text = "我進來是為了找我姐姐的。她叫<Blue:梅森>，兩個星期前在這附近失蹤了。\n你們這兒最近有多出個叫梅森的人嗎？"
  },
  AvgDialog_18908_Content_26 = {
    Text = "濟貧院最近有很多新人，我還沒認全大家的臉……"
  },
  AvgDialog_18908_Content_27 = {
    Text = "你好好想想，她有這麼高，長長的頭髮，<Yellow:綁著漂亮的紅色緞帶>，緞帶末尾連著一個方扣，上面雕刻了字母M。"
  },
  AvgDialog_18908_Content_28 = {
    Text = "她偶爾會來這邊看病，上次來了之後就沒回家，不知道是不是被你們扣下做工了。"
  },
  AvgDialog_18908_Content_29 = {
    Text = "<Shake:病、病人？>\n抱、抱歉…我也沒見過年輕的女病人……"
  },
  AvgDialog_18908_Content_3 = {
    Text = "嗯……我沒關係。"
  },
  AvgDialog_18908_Content_30 = {
    Text = "嘖，不管了，我也沒覺得能幸運到直接撞上知情人。\n不過你差點害我被發現了，這責任得你來負。"
  },
  AvgDialog_18908_Content_31 = {
    Text = "那、那我帶你去我的秘密基地吧！院長小姐從來不進鐘樓，藏在那裡她一定發現不了你。"
  },
  AvgDialog_18908_Content_32 = {
    Text = "說實話，那天撞到的人是艾繼絲你，真是太幸運了。\n不然我肯定得被揪著兜帽丟出去。"
  },
  AvgDialog_18908_Content_33 = {
    Text = "你別這麼說，濟貧院裡的大家都是很好很好的人。只是最近發生了太多壞事，所以大家的情緒有些糟糕……"
  },
  AvgDialog_18908_Content_34 = {
    Text = "艾繼絲。"
  },
  AvgDialog_18908_Content_36 = {
    Text = "我知道濟貧院的大家對你來說很重要…但我一直是把你當朋友的，所以，你有沒有把我當朋友？"
  },
  AvgDialog_18908_Content_37 = {
    Text = "當然了！我非常、非常喜歡和詹金你待在一起，像這樣吃著糖聊著天。"
  },
  AvgDialog_18908_Content_38 = {
    Text = "既然你把我當朋友，那為什麼不肯跟我說出真相呢？\n艾繼絲，不要對我撒謊了。"
  },
  AvgDialog_18908_Content_39 = {
    Text = "我、我不明白你在說什麼……"
  },
  AvgDialog_18908_Content_4 = {
    Text = "……我把那幾個資助人帶了過去，你是不是在生我的氣？"
  },
  AvgDialog_18908_Content_40 = {
    Text = "我在臭女人的辦公室翻到了<Blue:帳本>，還有%player%在找的人的<Blue:學生證>。我知道她在把你們賣給那夥怪醫生做實驗！"
  },
  AvgDialog_18908_Content_41 = {
    Text = "那女人最喜歡你了，甚至信任你去照顧那些病人。艾繼絲，你一定知道什麼的，告訴我好嗎？"
  },
  AvgDialog_18908_Content_43 = {
    Text = "女孩囁嚅著，聲音逐漸減小。\n她面色蒼白，看上去像是經受著莫大的痛苦。"
  },
  AvgDialog_18908_Content_44 = {
    Text = "彌薩格大學最擅長挖掘秘密，他們很快就會知道真相。"
  },
  AvgDialog_18908_Content_45 = {
    Text = "你沒有辦法永遠帶著枷鎖生活。"
  },
  AvgDialog_18908_Content_46 = {
    Text = "詹金，如果失去的一切已經無法再挽回…所謂的真相，真的還那麼重要嗎？"
  },
  AvgDialog_18908_Content_47 = {
    Text = "當然重要！對我來說，沒有什麼比找到姐姐更重要。"
  },
  AvgDialog_18908_Content_48 = {
    Text = "我知道你害怕那個臭女人，但你為什麼一直在袒護她？她不僅把工人賣給了醫生 ，還窩藏著<Yellow:濟貧院幽靈>。"
  },
  AvgDialog_18908_Content_49 = {
    Text = "濟、濟貧院幽靈？"
  },
  AvgDialog_18908_Content_5 = {
    Text = "怎麼會呢！"
  },
  AvgDialog_18908_Content_50 = {
    Text = "是啊，就是你跟我說的的那個傳說。\n<Yellow:起霧的晚上不能到處亂走，會被拿著刀徘徊的幽靈抓走>。"
  },
  AvgDialog_18908_Content_51 = {
    Text = "那、那只是我編出來的……夜裡太危險了，我不想讓你到處跑。"
  },
  AvgDialog_18908_Content_52 = {
    Text = "別替莎拉開脫了！我已經找到<Yellow:藏著幽靈的地下室>了，還聽到了<Yellow:刀的聲音>。\n我的姐姐是不是就在裡面？"
  },
  AvgDialog_18908_Content_53 = {
    Text = "隨著地下室這個詞語從詹金口中蹦出，艾繼絲的臉上最後一絲血色也消退殆盡。"
  },
  AvgDialog_18908_Content_54 = {
    Text = "別害怕，艾繼絲。內心的孔洞會讓祂趁虛而入。"
  },
  AvgDialog_18908_Content_55 = {
    Text = "跟隨銀的引導，光輝會為你指路。"
  },
  AvgDialog_18908_Content_56 = {
    Text = "詹金，對不起，我不能……"
  },
  AvgDialog_18908_Content_57 = {
    Text = "艾繼絲眼中含淚地看了一眼詹金，轉身爬回鐘樓衝下樓梯，動作沒有一絲猶豫。"
  },
  AvgDialog_18908_Content_58 = {
    Text = "艾繼絲！你去哪裡！"
  },
  AvgDialog_18908_Content_59 = {
    Text = "不知何時，濟貧院內起了霧氣。\n這霧氣突如其來，周圍的一切都籠上了一層水氣，顯得影影綽綽的。"
  },
  AvgDialog_18908_Content_6 = {
    Text = "我只是擔心你也…染上……"
  },
  AvgDialog_18908_Content_60 = {
    Text = "艾繼絲！該死，這霧怎麼都飄進室內了！"
  },
  AvgDialog_18908_Content_61 = {
    Text = "遠方的迷霧中，傳來血肉膨脹的聲音，和被水霧浸濕的隱約歌聲。"
  },
  AvgDialog_18908_Content_62 = {
    Text = "<Italic:老查理有一隻他很愛很愛的虎斑貓……>"
  },
  AvgDialog_18908_Content_63 = {
    Text = "詹金擦亮了她的提燈，小小的光輝在濃厚的霧氣中顯得那麼微弱無力。"
  },
  AvgDialog_18908_Content_64 = {
    Text = "悠悠的腳步聲從遠處傳來，在寂靜的走廊中近乎刺耳。"
  },
  AvgDialog_18908_Content_65 = {
    Text = "誰、誰在那裡？\n出來！我、我警告你，我可是有武器的！"
  },
  AvgDialog_18908_Content_66 = {
    Text = "走廊裡沒有一點氣流，燈芯上的火焰卻如被風吹過一般晃動。"
  },
  AvgDialog_18908_Content_67 = {
    Text = "腳步聲越來越近，越來越近。布朗的爪子深深陷入詹金肩頭的衣物中，它露出牙齒，發出鼠類特有的尖銳威嚇。"
  },
  AvgDialog_18908_Content_68 = {
    Text = "像是被布朗的聲音刺激到，腳步聲驟然加快，赫然是朝詹金而來。"
  },
  AvgDialog_18908_Content_69 = {
    Text = "濃重的黑影將微弱的燭火徹底吞沒，女孩閉上眼睛高聲尖叫，卻只感到一陣水汽撲面而來。"
  },
  AvgDialog_18908_Content_70 = {
    Text = "一隻手從黑暗中伸出，準確地落在詹金的肩頭。"
  },
  AvgDialog_18908_Content_71 = {
    Text = "你怎麼了？臉色這、這樣白？"
  },
  AvgDialog_18908_Content_72 = {
    Text = "羅、羅傑斯？你看到艾繼絲了嗎？"
  },
  AvgDialog_18908_Content_73 = {
    Text = "別擔心，艾繼絲很熟悉這家濟貧院，她不會有事。"
  },
  AvgDialog_18908_Content_74 = {
    Text = "我能理解，起霧的夜晚確實容易讓人膽戰心、心驚。"
  },
  AvgDialog_18908_Content_75 = {
    Text = "羅傑斯將門推開，溫暖的光傾瀉而出，驅散了走廊裡深重的陰影。"
  },
  AvgDialog_18908_Content_76 = {
    Text = "他從床上抱來做工精緻的玩偶，對女孩露出微笑。"
  },
  AvgDialog_18908_Content_77 = {
    Text = "作為安慰，要不要摸摸看呢？\n<Blue:喬治>會很高興的。"
  },
  AvgDialog_18908_Content_78 = {
    Text = "玩偶無機質的眼睛反射著燈火的黃光，彷彿在對女孩無聲地祈求：摸我吧，就一下。"
  },
  AvgDialog_18908_Content_79 = {
    Text = "摸摸我，然後——"
  },
  AvgDialog_18908_Content_8 = {
    Text = "詹金魔術般誇張地張開雙手，掌中躺著兩顆小小的糖果。"
  },
  AvgDialog_18908_Content_80 = {
    Text = "<Red:成為我忠實的朋友。>"
  },
  AvgDialog_18908_Content_81 = {
    Text = "“吱”地一聲，布朗的尖叫喚回了失神的詹金。"
  },
  AvgDialog_18908_Content_82 = {
    Text = "不、不必了！我對你們這些上流社會的藝術家不感興趣。"
  },
  AvgDialog_18908_Content_83 = {
    Text = "噢，天真的小老鼠。其實，美和藝術從、從不分貧富、貴賤。\n將苦難凝結於美中，是很、很好的。"
  },
  AvgDialog_18908_Content_84 = {
    Text = "羅傑斯凝視著滿臉警惕的女孩和女孩兜帽中冒頭的灰色老鼠，目光熾熱滾沸，彷彿壓抑著無法抵抗的欲望。"
  },
  AvgDialog_18908_Content_85 = {
    Text = "如果有機會，我也會將你、你們製作成蠟像。\n就叫“布朗與詹金”，如、如何？"
  },
  AvgDialog_18908_Content_9 = {
    Text = "喏，一人一顆。吃了這顆糖，你可得發誓不會生我氣哦。"
  },
  AvgDialog_18909_Content_1 = {
    Text = "地下的幽靈"
  },
  AvgDialog_18909_Content_10 = {
    Text = "拉蒙娜面不改色，語句流暢如背誦過千百遍臺詞的話劇演員。\n奧吉爾在一旁早已漲紅了臉。"
  },
  AvgDialog_18909_Content_11 = {
    Text = "真不愧是艾什勳爵家的少爺，這麼早就能承擔重大的責任。\n濟貧院裡有不少和他差不多大的孩子，能幫忙盛粥擦地就不錯了……"
  },
  AvgDialog_18909_Content_12 = {
    Text = "您、您千萬別這麼說……"
  },
  AvgDialog_18909_Content_13 = {
    Text = "拉蒙娜輕咳一聲，及時轉移了話鋒。"
  },
  AvgDialog_18909_Content_14 = {
    Text = "因此，我們會在東區進行一批實地考察，通過長期資助來掌握當地情況。\n莉莉安濟貧院是我們的第一站，也希望院長能對我們坦誠相待……"
  },
  AvgDialog_18909_Content_15 = {
    Text = "拉蒙娜簡述了濟貧院門口保安異變傷人的始末，當然，略去了融蝕相關的環節。"
  },
  AvgDialog_18909_Content_16 = {
    Text = "請問您對此是否知情？"
  },
  AvgDialog_18909_Content_17 = {
    Text = "居然還有這種事！那個保、保安，肯定不是我們濟貧院的人。\n我們這兒又沒有什麼值得偷啊搶啊的，請保安做什麼呢？"
  },
  AvgDialog_18909_Content_18 = {
    Text = "她表情訕訕，顯然是在說謊。"
  },
  AvgDialog_18909_Content_2 = {
    Text = "你們一行人進入濟貧院，遠遠就看見一個修女打扮的女人領著幾個孩子和工人排成一行等候你們。"
  },
  AvgDialog_18909_Content_20 = {
    Text = "莎拉瞪了身側的女孩一眼，女孩露出慌亂的表情。"
  },
  AvgDialog_18909_Content_21 = {
    Text = "艾繼絲，你還小，照顧好自己最重要。大人的事兒，你別插手。"
  },
  AvgDialog_18909_Content_22 = {
    Text = "女孩抿了抿嘴，眼神垂向手中的玩偶，不再說話。"
  },
  AvgDialog_18909_Content_23 = {
    Text = "……算了，你帶個工人過去。給他罩塊布，別讓老鼠把人啃了。"
  },
  AvgDialog_18909_Content_24 = {
    Text = "說完，她又轉向你們。"
  },
  AvgDialog_18909_Content_25 = {
    Text = "抱歉，醫生來的時候，我會請他們幫忙收殮的。"
  },
  AvgDialog_18909_Content_26 = {Text = "醫生？"},
  AvgDialog_18909_Content_27 = {
    Text = "啊…是、是這樣的。咱們這兒有不少孩子 ，有其他資助人慷慨相助，請了醫生定期來檢查孩子們的情況。"
  },
  AvgDialog_18909_Content_28 = {
    Text = "算算時間，下次身體檢查就在這兩天了。"
  },
  AvgDialog_18909_Content_29 = {
    Text = "不需要通知警局嗎？"
  },
  AvgDialog_18909_Content_3 = {
    Text = "濟貧院事務繁雜，我們有失遠迎了，尊敬的艾什%lordorlady%、瑪麗小姐。\n我是這兒的管理人莎拉。"
  },
  AvgDialog_18909_Content_30 = {
    Text = "唉，這您就有所不知了，東區有東區的法則。"
  },
  AvgDialog_18909_Content_31 = {
    Text = "即使是鬧得人心惶惶的<Red:肢解者事件>，他們也不過是派人收走屍體，再沒下文了。"
  },
  AvgDialog_18909_Content_32 = {
    Text = "對我們這些人來說，吃飽飯已經很不容易了，沒有那麼多餘的精力浪費在這些事情上。"
  },
  AvgDialog_18909_Content_33 = {
    Text = "說罷，莎拉引著你們，朝著濟貧院內走去。\n在你們的身後，工人安靜地排成兩列，似是護衛，又彷彿看守。"
  },
  AvgDialog_18909_Content_34 = {
    Text = "你聽見拉蒙娜輕聲念出的話語。"
  },
  AvgDialog_18909_Content_35 = {
    Text = "倫蒂尼恩常識之三——"
  },
  AvgDialog_18909_Content_36 = {
    Text = "“在東區，人的價格是不可衡量的。因為他們沒有價值。”"
  },
  AvgDialog_18909_Content_37 = {
    Text = "靜悄悄的走廊裡，鑲嵌了金屬銘牌的門緩緩打開。\n一隻老鼠從門縫間溜出來，它左右看看，朝走廊的陰影吱吱叫了兩聲。"
  },
  AvgDialog_18909_Content_39 = {
    Text = "上次你也說沒人！要不是遇到的是艾繼絲，我可就倒大黴了。"
  },
  AvgDialog_18909_Content_4 = {
    Text = "見身邊人沒接上話頭，她眉頭一皺，拍了拍女孩的背。\n女孩似乎在走神，這會兒像是被嚇了一跳，趕緊向你們鞠了一躬。"
  },
  AvgDialog_18909_Content_40 = {
    Text = "詹金從轉角探出頭，確認走廊上空無一人後才溜出了門縫，回身將門關上。"
  },
  AvgDialog_18909_Content_42 = {
    Text = "對啦對啦，你說得都對。我們的布朗最厲害了！"
  },
  AvgDialog_18909_Content_44 = {
    Text = "讓我看看這臭女人都藏了什麼秘密。\n戒指，項鍊……這都是金的吧？"
  },
  AvgDialog_18909_Content_45 = {
    Text = "這個臭女人，連糖果都不肯給艾繼絲買，說什麼“入不服出”，結果自己藏著這麼多好東西！"
  },
  AvgDialog_18909_Content_46 = {
    Text = "鑰匙，好，看來出入其他地方也省事了。\n真得謝謝那什麼<Yellow:“自助人”>，我們可以自助調查濟貧院了。"
  },
  AvgDialog_18909_Content_48 = {
    Text = "別急，布朗，還有時間。"
  },
  AvgDialog_18909_Content_49 = {
    Text = "咦……這是……帳本？\n麥克，男，5歲，10雷歐坊；戴安娜，女，23歲，5雷歐坊……"
  },
  AvgDialog_18909_Content_5 = {
    Text = "歡、歡迎各位，我們在餐廳準備了點心……"
  },
  AvgDialog_18909_Content_50 = {
    Text = "不會吧……難道這濟貧院把人都賣了？！"
  },
  AvgDialog_18909_Content_53 = {
    Text = "布朗突然發出尖銳的提醒，木門吱呀一聲被推開。"
  },
  AvgDialog_18909_Content_54 = {
    Text = "出現在莎拉面前的，是空無一人的辦公室。"
  },
  AvgDialog_18909_Content_55 = {
    Text = "她半拉開抽屜，塞入一個巴掌大小的薄片，然後重重推上了木質抽屜，迅速抽身離去。"
  },
  AvgDialog_18909_Content_57 = {
    Text = "莎拉離開後，布朗率先從角落盆栽的陰影中跑出。"
  },
  AvgDialog_18909_Content_58 = {
    Text = "詹金輕手輕腳地跟上，拉開抽屜。"
  },
  AvgDialog_18909_Content_59 = {
    Text = "學生證？<Blue:肖恩……安德森>……\n這上面的符號，是不是跟早上那個冤大頭金毛皮夾上的一樣？"
  },
  AvgDialog_18909_Content_6 = {
    Text = "咦，這位是……？"
  },
  AvgDialog_18909_Content_61 = {
    Text = "別急，布朗。\n我必須冷靜……冷靜……"
  },
  AvgDialog_18909_Content_62 = {
    Text = "我都看過了，賬簿裡面沒有姐姐的名字。"
  },
  AvgDialog_18909_Content_63 = {
    Text = "不過，我們還有這麼多鑰匙，我可以打開這鬼地方每一扇門！我就不信找不到證據。"
  },
  AvgDialog_18909_Content_67 = {
    Text = "見鬼，這是最後一個房間了。"
  },
  AvgDialog_18909_Content_68 = {
    Text = "黑漆漆的，什麼都沒有。\n我們要無功而返了，布朗。"
  },
  AvgDialog_18909_Content_7 = {
    Text = "莎拉疑惑地看向隊伍中的奧吉爾，又看了看你們。"
  },
  AvgDialog_18909_Content_70 = {
    Text = "什麼？地板的下面？"
  },
  AvgDialog_18909_Content_71 = {
    Text = "詹金猶豫了一下，還是輕輕擦亮了提燈，她將火光撥到最小，湊近了地面。"
  },
  AvgDialog_18909_Content_72 = {
    Text = "那是一排螞蟻，沿著整齊的隊形，延伸入木板的縫隙之中。"
  },
  AvgDialog_18909_Content_73 = {
    Text = "詹金撬開兩枚釘子，掀起木板。\n木板下是一個25英寸見方的鐵質蓋板。"
  },
  AvgDialog_18909_Content_74 = {
    Text = "詹金一一嘗試了所有鑰匙。"
  },
  AvgDialog_18909_Content_75 = {
    Text = "該死，全都打不開。\n這女人還藏了其他鑰匙？"
  },
  AvgDialog_18909_Content_76 = {
    Text = "她將耳朵貼在了鐵板上，試圖聆聽地下室內的聲響。"
  },
  AvgDialog_18909_Content_79 = {
    Text = "這、這難道是……艾繼絲說的、<Yellow:濟貧院的幽靈>……！"
  },
  AvgDialog_18909_Content_8 = {
    Text = "他是我的胞弟奧吉爾，也是艾什家族的未來繼承人之一。"
  },
  AvgDialog_18909_Content_81 = {
    Text = "門外隱約傳來了腳步聲。"
  },
  AvgDialog_18909_Content_82 = {
    Text = "沒辦法了，布朗。\n如果那個臭女人還在濟貧院裡養了幽靈，光憑我們可打不過她。"
  },
  AvgDialog_18909_Content_83 = {
    Text = "我們需要<Yellow:她會害怕的人>……"
  },
  AvgDialog_18909_Content_84 = {
    Text = "詹金躲在陰影中，仗著盆栽的遮擋探出半個腦袋。"
  },
  AvgDialog_18909_Content_85 = {
    Text = "走廊中，莎拉正側著身向參觀的一行人諂媚地介紹著濟貧院的收支狀況。"
  },
  AvgDialog_18909_Content_86 = {
    Text = "……那就是艾繼絲說的，自助人？"
  },
  AvgDialog_18909_Content_87 = {
    Text = "詹金若有所思地點頭，然後趁著一行人不備離開了黑暗的雜物間。"
  },
  AvgDialog_18909_Content_88 = {
    Text = "在她的背後，未完全扣合的地板張開漆黑深邃的裂口，無聲地等候著光臨者的到來。"
  },
  AvgDialog_18909_Content_9 = {
    Text = "勳爵希望奧吉爾小少爺對東區現狀能有深入的認知，有助於在未來接管家族產業後，他能更有針對性地改善東區環境。"
  },
  AvgDialog_18910_Content_1 = {
    Text = "該死，好多怪物湧進來，越來越多了！"
  },
  AvgDialog_18910_Content_2 = {
    Text = "奧吉爾，你去封上地下室大門！拉蒙娜，集中精力壓制莎拉！"
  },
  AvgDialog_18910_Content_3 = {Text = "聽令！"},
  AvgDialog_18911_Content_1 = {
    Text = "都結束了。"
  },
  AvgDialog_18911_Content_10 = {
    Text = "刀具隨著手的運動，拖出一道長長的銀色軌跡。"
  },
  AvgDialog_18911_Content_12 = {
    Text = "刀尖越來越近，越來越近，直到佔據了全部視野。\n然後——"
  },
  AvgDialog_18911_Content_14 = {
    Text = "艾繼絲顫抖著，喉嚨深處發出戰慄而恐懼的尖叫。"
  },
  AvgDialog_18911_Content_15 = {
    Text = "彷彿被那聲尖叫召喚而來，神秘的心理醫生悄然出現在她的身後。"
  },
  AvgDialog_18911_Content_16 = {
    Text = "小艾繼絲遇到新的煩惱了嗎，要不要和克萊門汀醫生說說呢？"
  },
  AvgDialog_18911_Content_17 = {
    Text = "克萊門汀醫生？！"
  },
  AvgDialog_18911_Content_18 = {
    Text = "深夜的濟貧院可不是什麼最佳出診地，你為什麼會在這裡出現？"
  },
  AvgDialog_18911_Content_19 = {
    Text = "別那麼嚴肅嘛。這陣子濟貧院有些不太平，羅傑斯先生擔心工人和孩子們的精神狀態，特地聘請了我來關照大家。"
  },
  AvgDialog_18911_Content_2 = {
    Text = "拉蒙娜轉向驚魂未定的女孩，她連牙齒都在顫抖著，半句話也說不出來。"
  },
  AvgDialog_18911_Content_20 = {
    Text = "有時看診到夜深了，我也會留宿濟貧院，就睡在孩子們附近的房間。"
  },
  AvgDialog_18911_Content_21 = {
    Text = "艾繼絲，你認識她嗎？"
  },
  AvgDialog_18911_Content_22 = {
    Text = "克萊門汀的到來使女孩從回憶中抽身，她點點頭，給出了肯定的答覆。"
  },
  AvgDialog_18911_Content_23 = {
    Text = "從我第一次來到濟貧院開始，她就是我的小小客人。"
  },
  AvgDialog_18911_Content_24 = {
    Text = "訴說煩惱是心理療癒的方法之一，而我恰好是一名很專業的聽眾。"
  },
  AvgDialog_18911_Content_25 = {
    Text = "審視的視線從眾人臉上一一滑過，最後定格在了你身上。"
  },
  AvgDialog_18911_Content_26 = {
    Text = "不必了，我們還有事在身。"
  },
  AvgDialog_18911_Content_27 = {
    Text = "真遺憾。如果改變主意了，隨時歡迎你加入我們尋找內心的旅程。\n走吧，艾繼絲。"
  },
  AvgDialog_18911_Content_28 = {
    Text = "艾繼絲牽著克萊門汀的手，沉默著緩步離開。"
  },
  AvgDialog_18911_Content_29 = {
    Text = "艾繼絲！你們去哪裡！"
  },
  AvgDialog_18911_Content_3 = {
    Text = "她輕輕卷起艾繼絲的袖子，縫合走線觸目驚心，在白皙的手腕上格外刺目。"
  },
  AvgDialog_18911_Content_30 = {
    Text = "<Small:對不起…克萊門汀醫生能幫我……>"
  },
  AvgDialog_18911_Content_31 = {
    Text = "女孩說完，她難得主動地大力扯了扯克萊門汀的衣袖。在無聲的催促下，兩人的身影消失在了濟貧院門內。"
  },
  AvgDialog_18911_Content_32 = {
    Text = "艾繼絲……不知道這個孩子究竟藏著什麼秘密。"
  },
  AvgDialog_18911_Content_33 = {
    Text = "霧快散了，我們也回去休息一會兒吧。後半夜和詹金約好了去探查地下室，我們需要保存一些精力。"
  },
  AvgDialog_18911_Content_4 = {
    Text = "艾繼絲，他們也對你做了一樣的實驗。\n他們把你捆起來，強行進行手術，為你植入了一些……<Yellow:異物>，對嗎？"
  },
  AvgDialog_18911_Content_5 = {
    Text = "我、我，那時候……"
  },
  AvgDialog_18911_Content_6 = {
    Text = "唔……這裡是……"
  },
  AvgDialog_18911_Content_7 = {
    Text = "強烈的燈光讓人不自覺地想要閉上眼睛，艾繼絲試圖控制眼皮，卻發現自己無法做到。"
  },
  AvgDialog_18911_Content_8 = {
    Text = "冰冷的金屬固定住了眼周肌肉，她只能眼睜睜地看著白袍男人手持柳葉刀慢慢靠近自己。"
  },
  AvgDialog_18912_Content_1 = {
    Text = "銀鑰匙劇烈閃爍，女孩猛然撐起身體，依稀聽到什麼東西撕裂的聲音。"
  },
  AvgDialog_18912_Content_10 = {
    Text = "你也無力地跌坐在地上，強忍大腦一陣一陣的脹痛，及緊隨其來的噁心感。"
  },
  AvgDialog_18912_Content_12 = {
    Text = "精神力透支了吧？總是亂來的話，你可見證不到彌薩格的未來。\n坐下休息吧，精神力透支會影響你的感知能力。"
  },
  AvgDialog_18912_Content_13 = {
    Text = "別管我了，快去看看艾繼絲。"
  },
  AvgDialog_18912_Content_14 = {
    Text = "液體蒸發一般的聲音逐漸減弱，不一會兒就徹底消散。\n沾染了黑色黏液的地板上，女孩捂著單眼，靜靜地坐著。"
  },
  AvgDialog_18912_Content_15 = {
    Text = "拉蒙娜小姐……還有……%player%%sirormadam%。\n你們沒事真是太好了。"
  },
  AvgDialog_18912_Content_16 = {
    Text = "艾繼絲……"
  },
  AvgDialog_18912_Content_17 = {
    Text = "跟我們回彌薩格去，我們一定會想辦法治好你的眼睛。"
  },
  AvgDialog_18912_Content_18 = {
    Text = "你向著艾繼絲伸出手去。"
  },
  AvgDialog_18912_Content_19 = {
    Text = "艾繼絲輕輕地、輕輕地搭上了你的手掌。\n她的指尖冰冷如石頭，這個瞬間卻像是鐘樓外金黃的落日般溫暖。"
  },
  AvgDialog_18912_Content_2 = {
    Text = "眼罩緩緩飄落，蠕動的色彩替代了黑暗，一個巨大的蒼白瞳仁出現在她身下，像是已經注視著她很久。"
  },
  AvgDialog_18912_Content_20 = {
    Text = "詹金告訴我，你們在研究的、醫生在我們身上實驗的，是一種叫做“融蝕”的現象，會讓人的存在逐漸消失，連相關的記憶都蕩然無存。"
  },
  AvgDialog_18912_Content_21 = {
    Text = "如果這是真的……我有一個願望。"
  },
  AvgDialog_18912_Content_22 = {
    Text = "艾繼絲停頓了片刻，收住隱約的哭腔。"
  },
  AvgDialog_18912_Content_23 = {
    Text = "希望濟貧院的大家都能忘了我，忘掉我給大家帶來的痛苦。"
  },
  AvgDialog_18912_Content_24 = {
    Text = "她抬起頭，用冰冷的石色瞳孔凝視著你。"
