  AvgDialog_18913_Content_14 = {
    Text = "我還能堅持多久？一年、一個月、一天、一小時？"
  },
  AvgDialog_18913_Content_15 = {
    Text = "難道我要永遠躲在大家身後，等到殘存的一切都無法挽回的時候，再採取行動嗎？"
  },
  AvgDialog_18913_Content_16 = {
    Text = "這一次，我想要像提尤格、像詹金、像你一樣勇敢。"
  },
  AvgDialog_18913_Content_17 = {
    Text = "奧吉爾，你不是騎士嗎？那你應該明白的。\n即使我留下來，也註定是被騎士審判的罪人。"
  },
  AvgDialog_18913_Content_18 = {
    Text = "奧吉爾怔住了。"
  },
  AvgDialog_18913_Content_19 = {
    Text = "奧吉爾，你說過……能否得到救贖，取決於我自己。"
