  AvgDialog_18913_Content_2 = {
    Text = "別這樣，求求你……\n我知道……"
  },
  AvgDialog_18913_Content_20 = {
    Text = "現在…能請你看著我嗎，看著我的靈魂……是否能被救贖。"
  },
  AvgDialog_18913_Content_21 = {
    Text = "奧吉爾注視著艾繼絲那唯一的一隻正常的瞳孔，猶豫片刻後，鄭重地鬆開了手。"
  },
  AvgDialog_18913_Content_22 = {
    Text = "隨著他的動作，艾繼絲脫離了你的連結控制。"
  },
  AvgDialog_18913_Content_23 = {
    Text = "刹那間，女孩的軀體急劇膨脹，皮肉宛如沸騰了一樣鼓起大大小小的圓形鼓包，很快便封住了現在的樓梯口，並頂在高高的天花板上。"
  },
  AvgDialog_18913_Content_24 = {
    Text = "肢體扭曲彎折的可怖聲響中，女孩的聲音僅有一絲殘存。"
  },
  AvgDialog_18913_Content_4 = {
    Text = "滾燙、熾熱的黑暗，像是融化的糖漿，裹纏在你的身上，將你緊緊束縛其中。"
