  },
  AvgDialog_18931_Content_11 = {
    Text = "一定是那個什麼鬼協會的人派你來做臥底！"
  },
  AvgDialog_18931_Content_14 = {
    Text = "啊啊啊——！！為什麼不聽我解釋呢？！"
  },
  AvgDialog_18931_Content_15 = {
    Text = "面對你們的層層質詢，24忽然抱頭尖叫起來。"
  },
  AvgDialog_18931_Content_16 = {
    Text = "聽我解釋，你@2聽我解釋啊啊啊——！！"
  },
  AvgDialog_18931_Content_17 = {
    Text = "<SmallShake:聽、我聽還不行嗎……怎麼又瘋了……>"
  },
  AvgDialog_18931_Content_18 = {
    Text = "24不斷喘息，臉上青筋畢露。"
  },
  AvgDialog_18931_Content_19 = {
    Text = "喂，你臉上的血管……"
  },
  AvgDialog_18931_Content_2 = {
    Text = "請聽我解釋，其實我是被迫的！那時候是我推的你……"
  },
  AvgDialog_18931_Content_20 = {
    Text = "呵呵……沒錯，就是這個眼神。我看到……"
  },
  AvgDialog_18931_Content_21 = {Text = "恐懼。"},
  AvgDialog_18931_Content_22 = {Text = "厭惡。"},
  AvgDialog_18931_Content_23 = {
    Text = "<RedShake:怪物。怪物。像我這樣被遺棄的醜陋怪物……>"
  },
  AvgDialog_18931_Content_24 = {
    Text = "<RedShake:沒有人靠近我，沒有人相信我……>"
  },
  AvgDialog_18931_Content_25 = {
    Text = "暗紅色的手臂再度從24體內生出，狠狠纏住她的脖頸。"
  },
  AvgDialog_18931_Content_27 = {
    Text = "糟了，她又開始不對勁了。快離開這裡！"
  },
  AvgDialog_18931_Content_3 = {
    Text = "竟然是你推的？很好……你倒是很誠實，什麼都招了！"
  },
  AvgDialog_18931_Content_4 = {
    Text = "我知道你們很厲害、所以我後來決定和你們一起行動……"
  },
  AvgDialog_18931_Content_5 = {
    Text = "你只需要回答我一個問題，24小姐。是你放走她的嗎？"
  },
  AvgDialog_18931_Content_7 = {
    Text = "這也是被迫的？"
  },
  AvgDialog_18931_Content_8 = {
    Text = "事實上……"
  },
  AvgDialog_18931_Content_9 = {
    Text = "等等。你以為我們還會信你的鬼話？"
  },
  AvgDialog_18932_Content_2 = {
    Text = "不，請殺了我……"
  },
  AvgDialog_18933_Content_2 = {
    Text = "咦，那傢伙好像摔倒了？"
  },
  AvgDialog_18933_Content_3 = {
    Text = "過去看看。"
  },
  AvgDialog_18934_Content_1 = {
    Text = "你你你們先跑，我斷後……我、我才不怕她！"
  },
  AvgDialog_18934_Content_2 = {
    Text = "……你先別抖。聽話，躲到我後面去。"
  },
  AvgDialog_18935_Content_1 = {Text = "娃娃館"},
  AvgDialog_18935_Content_10 = {
    Text = "媽媽……"
  },
  AvgDialog_18935_Content_11 = {
    Text = "看來你已經越來越習慣和“媽媽”相處了。"
  },
  AvgDialog_18935_Content_12 = {
    Text = "……蠟、蠟像先生。"
  },
  AvgDialog_18935_Content_13 = {
    Text = "是不是很美？這可不是她原本的模樣。"
  },
  AvgDialog_18935_Content_14 = {
    Text = "她生前是個賣唱女，又不幸患上了傳染病，全身都是紅色的瘢痕和腫塊。"
  },
  AvgDialog_18935_Content_15 = {
    Text = "我看著她被人打死，倒在我面前。然後我把她帶了回來，變成現在你看到的模樣。"
  },
  AvgDialog_18935_Content_16 = {
    Text = "完、完全看不出來……這是魔法嗎？"
  },
  AvgDialog_18935_Content_17 = {
    Text = "這不是魔法，我的孩子。這是蠟像藝術。"
  },
  AvgDialog_18935_Content_18 = {
    Text = "蠟像……藝術……"
  },
  AvgDialog_18935_Content_19 = {
    Text = "我看向“媽媽”。昏黃的燭火將她的面龐鍍出玉石般的光澤，又勾勒出她嘴角的笑意。"
  },
  AvgDialog_18935_Content_2 = {
    Text = "洪積295年夏\n斯卡伯勒，北約克郡"
  },
  AvgDialog_18935_Content_20 = {
    Text = "目光一寸寸掃過，試圖在她身上尋找一絲貧窮與苦難的蛛絲馬跡，卻徒勞無功。"
  },
  AvgDialog_18935_Content_21 = {
    Text = "你似乎不太愛說話。放心吧，我暫時不打算把你變成蠟像……在我面前你可以暢所欲言。"
  },
  AvgDialog_18935_Content_22 = {
    Text = "他們說我、我有病，需要接受治療，不能隨便說話。"
  },
  AvgDialog_18935_Content_23 = {
    Text = "是口吃吧。他們是怎麼治療你的？"
  },
  AvgDialog_18935_Content_24 = {
    Text = "用火、火鉗燙、注射@2酊劑……"
  },
  AvgDialog_18935_Content_25 = {
    Text = "@2酊劑？那可不是什麼好東西。"
  },
  AvgDialog_18935_Content_26 = {
    Text = "我不知道。媽媽說它會幫助我喉嚨的肌肉放、放鬆。"
  },
  AvgDialog_18935_Content_27 = {
    Text = "那是一段痛苦的經歷。我的母親沉迷各類“新式”療法，將我當成她的玩具一樣隨意擺弄。"
  },
  AvgDialog_18935_Content_28 = {
    Text = "每天清晨，我都要站在高高的臺階上，嘴裡塞滿尖銳的碎石。"
  },
  AvgDialog_18935_Content_29 = {
    Text = "唱啊。媽媽說，唱啊。"
  },
  AvgDialog_18935_Content_3 = {
    Text = "老查理有一隻他很愛很愛的虎斑貓~"
  },
  AvgDialog_18935_Content_30 = {
    Text = "於是我高聲唱著歡快的字母歌，血從嘴裡不斷湧出，一直流到胸口上。"
  },
  AvgDialog_18935_Content_31 = {
    Text = "別哭了，我的孩子。這裡的蠟像們，每一個背後的故事都很悲傷。"
  },
  AvgDialog_18935_Content_32 = {
    Text = "他們原本應該悄無聲息地生活、死去，最後和那些悲傷的故事一起被雨水衝進下水道。"
  },
  AvgDialog_18935_Content_33 = {
    Text = "就好像那些悲傷從未存在。"
  },
  AvgDialog_18935_Content_34 = {
    Text = "從未……存在……"
  },
  AvgDialog_18935_Content_35 = {
    Text = "很殘酷，不是麼？我想幫助他們，可我只有這把生銹的刻刀。"
  },
  AvgDialog_18935_Content_36 = {
    Text = "於是我成了這些悲傷的記錄者……但很快，我就不再滿足於此了。"
  },
  AvgDialog_18935_Content_37 = {
    Text = "你……改、改變了它們。"
  },
  AvgDialog_18935_Content_38 = {
    Text = "銘記，然後重塑——這就是我的蠟像哲學。"
  },
  AvgDialog_18935_Content_39 = {
    Text = "這是一條艱難的求索之路，我的孩子。但它非常迷人。"
  },
  AvgDialog_18935_Content_4 = {
    Text = "當她無故失蹤的時候他到處找~"
  },
  AvgDialog_18935_Content_40 = {
    Text = "屆時，你就是經書裡的聖人。海水將在你面前分開，為你讓出一片乾地。"
  },
  AvgDialog_18935_Content_41 = {
    Text = "火鉗也好，@2酊劑也罷……它們再也不重要了。"
  },
  AvgDialog_18935_Content_42 = {
    Text = "22：15，羅傑斯蠟像館\n陳列區"
  },
  AvgDialog_18935_Content_43 = {
    Text = "你們行走在古老陳舊的蠟像館之中。"
  },
  AvgDialog_18935_Content_44 = {
    Text = "館外幾乎沒有自然光射入，零星幾盞煤油燈也無法改善陰森的氛圍。"
  },
  AvgDialog_18935_Content_45 = {
    Text = "我有個問題……"
  },
  AvgDialog_18935_Content_46 = {
    Text = "這些蠟像為什麼都笑得這麼奇怪？"
  },
  AvgDialog_18935_Content_47 = {
    Text = "你望向這些無比精緻的蠟像。"
  },
  AvgDialog_18935_Content_48 = {
    Text = "抿著嘴的、打瞌睡的、還有撐著陽傘的……它們唯一的共同點便是臉上燦爛的笑容。"
  },
  AvgDialog_18935_Content_49 = {
    Text = "看著怪滲人的。\n說它們開心吧，眼睛黑洞洞的，一點精神都沒有。"
  },
  AvgDialog_18935_Content_50 = {
    Text = "要我說，這羅傑斯的水準也不怎麼樣，徒有其表。"
  },
  AvgDialog_18935_Content_51 = {
    Text = "從之前的資料來看，“歡笑”似乎是羅傑斯的藝術母題之一。\n我說得對嗎，朵爾？"
  },
  AvgDialog_18935_Content_52 = {Text = "朵爾？"},
  AvgDialog_18935_Content_54 = {
    Text = "你輕叩了數下胸針，卻沒有任何回音，整座蠟像館安靜得如同一座巨大的墳墓。"
  },
  AvgDialog_18935_Content_55 = {
    Text = "通訊器功能好好的，信號卻中斷了……怎麼回事？"
  },
  AvgDialog_18935_Content_56 = {
    Text = "剛進蠟像館的時候，我似乎聽到了電流聲……有什麼東西在干擾通訊？"
  },
  AvgDialog_18935_Content_58 = {
    Text = "我也聽見了。"
  },
  AvgDialog_18935_Content_59 = {
    Text = "現在怎麼辦？按照原計劃，我們得和朵爾小姐配合……"
  },
  AvgDialog_18935_Content_6 = {
    Text = "媽媽，我唱得好聽嗎？"
  },
  AvgDialog_18935_Content_60 = {
    Text = "或許是潘狄婭搞的鬼，先回去看看。"
  },
  AvgDialog_18935_Content_7 = {
    Text = "今天是我和母親“伽拉忒亞”相處的第十五天。"
  },
  AvgDialog_18935_Content_8 = {
    Text = "望著她溫柔的面龐與打磨得恰到好處的儀態，我的內心忽然升起一陣感動。"
  },
  AvgDialog_18935_Content_9 = {
    Text = "我將頭輕輕靠進她的懷裡。"
  },
  AvgDialog_18936_Content_1 = {
    Text = "幹嘛要回去找那傢伙……她看起來就不像什麼好人。"
  },
  AvgDialog_18936_Content_2 = {
    Text = "先去前臺打個電話，看看到底是哪裡出了問題。"
  },
  AvgDialog_18936_Content_3 = {
    Text = "明白！如果是她搞的鬼，那就抓起來先揍一頓。"
  },
  AvgDialog_18937_Content_1 = {
    Text = "嗚嗚嗚，把人家的腸子還來……"
  },
  AvgDialog_18937_Content_2 = {
    Text = "喏，還給你！"
  },
  AvgDialog_18937_Content_3 = {
    Text = "塞不回去了……嗚嗚嗚……"
  },
  AvgDialog_18938_Content_1 = {
    Text = "伽拉忒亞"
  },
  AvgDialog_18938_Content_10 = {
    Text = "我的父母都是體面的有錢人，他們會給你錢的……"
  },
  AvgDialog_18938_Content_12 = {
    Text = "噓……別說話，你吵到她了。"
  },
  AvgDialog_18938_Content_13 = {
    Text = "過來，孩子。"
  },
  AvgDialog_18938_Content_14 = {
    Text = "靠近點，不要害怕。"
  },
  AvgDialog_18938_Content_16 = {
    Text = "即使是最無暇的美玉，也不及它萬分之一。"
  },
  AvgDialog_18938_Content_17 = {
    Text = "<Shake:美……美極了，先生。>"
  },
  AvgDialog_18938_Content_18 = {
    Text = "很遺憾，我從你的眼裡沒有感受到一絲敬意，只有恐懼和厭惡……"
  },
  AvgDialog_18938_Content_19 = {
    Text = "不……不是這樣的，請再給我一次機會！"
  },
  AvgDialog_18938_Content_2 = {
    Text = "洪積295年夏\n斯卡伯勒，北約克郡"
  },
  AvgDialog_18938_Content_20 = {
    Text = "沒關係，我會好好培養你，為你祛除矇昧的面紗。\n先從第一步開始——"
  },
  AvgDialog_18938_Content_22 = {
    Text = "現在我命令你，跪下。"
  },
  AvgDialog_18938_Content_23 = {
    Text = "向伽拉忒亞，向“媽媽”……"
  },
  AvgDialog_18938_Content_24 = {
    Text = "獻上虔誠的吻。"
  },
  AvgDialog_18938_Content_25 = {
    Text = "那是我第一次親吻“媽媽”。"
  },
  AvgDialog_18938_Content_26 = {
    Text = "蒼白的手被細心包裹在粘稠的油蠟中，在斯卡伯勒盛夏的高溫炙烤下，隱約散發出腐臭的氣息。"
  },
  AvgDialog_18938_Content_27 = {
    Text = "死亡的氣息。"
  },
  AvgDialog_18938_Content_28 = {
    Text = "21：00，南華克街"
  },
  AvgDialog_18938_Content_29 = {
    Text = "呼叫編號I-2069通訊器，呼叫編號I-2069通訊器……"
  },
  AvgDialog_18938_Content_3 = {
    Text = "這是我最鍾愛的藝術品——伽拉忒亞。"
  },
  AvgDialog_18938_Content_30 = {
    Text = "第25次通訊嘗試失敗。我們丟失了與調查員威廉·德拉普爾的連接。"
  },
  AvgDialog_18938_Content_31 = {
    Text = "和威廉同行的警探們，能聯繫上嗎？"
  },
  AvgDialog_18938_Content_32 = {
    Text = "很遺憾，不能。\n收工吧，先回彌薩格彙報。在沒搞清楚情況前，先別輕舉妄動。"
  },
  AvgDialog_18938_Content_33 = {
    Text = "收工？可威廉學長現在情況不明，我擔心他……"
  },
  AvgDialog_18938_Content_34 = {
    Text = "真是一幫膽小鬼。"
  },
  AvgDialog_18938_Content_35 = {
    Text = "不好意思，我姐姐可等不起你們這套又臭又長的辦事流程。"
  },
  AvgDialog_18938_Content_36 = {
    Text = "蠟像館我一個人也能去。"
  },
  AvgDialog_18938_Content_38 = {
    Text = "詹金說罷，轉身一頭紮進濃稠的霧中。"
  },
  AvgDialog_18938_Content_39 = {
    Text = "詹金！別亂跑，那邊很危險！"
  },
  AvgDialog_18938_Content_4 = {
    Text = "聽說過<Blue:皮格馬利翁>的故事吧？"
  },
  AvgDialog_18938_Content_5 = {
    Text = "他用象牙雕刻了一座美麗的少女像，像對待妻子那樣愛撫她、裝扮她……"
  },
  AvgDialog_18938_Content_6 = {
    Text = "並將全部的熱情與愛戀都獻給了她。"
  },
  AvgDialog_18938_Content_7 = {
    Text = "“伽拉忒亞”——這就是那個少女的名字。"
  },
  AvgDialog_18938_Content_8 = {
    Text = "抱歉，我不小心說了太多，你一定感到厭煩了。"
  },
  AvgDialog_18938_Content_9 = {
    Text = "沒、沒有的事，先生。求您了，先生……"
  },
  AvgDialog_18939_Content_10 = {
    Text = "喬治，我的名字叫喬治。"
  },
  AvgDialog_18939_Content_11 = {
    Text = "洪積295年6月@1日。"
  },
  AvgDialog_18939_Content_12 = {
    Text = "那是很混亂的一天。直到他們拉開地窖門，讓陽光照進來……"
  },
  AvgDialog_18939_Content_13 = {
    Text = "我才知道我的花園，我的王國原來只是一處狹窄的地下室。"
  },
  AvgDialog_18939_Content_14 = {
    Text = "孩子！我的孩子……終於找到你了！"
  },
  AvgDialog_18939_Content_15 = {
    Text = "快和媽媽一起離開這裡，永遠離開這裡……"
  },
  AvgDialog_18939_Content_16 = {
    Text = "喬治……"
  },
  AvgDialog_18939_Content_17 = {
    Text = "……什麼？"
  },
  AvgDialog_18939_Content_18 = {
    Text = "喬治……我要和喬、喬治一起走。"
  },
  AvgDialog_18939_Content_19 = {
    Text = "“喬治”？你是指這個小蠟像吧。"
  },
  AvgDialog_18939_Content_2 = {
    Text = "洪積295年夏\n斯卡伯勒，北約克郡"
  },
  AvgDialog_18939_Content_20 = {
    Text = "喬治！請、請還給我——"
  },
  AvgDialog_18939_Content_21 = {
    Text = "別著急，小傢伙，先回答我一個問題。"
  },
  AvgDialog_18939_Content_22 = {
    Text = "<Yellow:“蠟像”去哪裡了？>"
  },
  AvgDialog_18939_Content_23 = {
    Text = "“蠟像”……？我、我不知道你在說什麼……"
  },
  AvgDialog_18939_Content_24 = {
    Text = "呵呵。你真不知道？那我再問你一個問題。"
  },
  AvgDialog_18939_Content_25 = {
    Text = "<Yellow:這個蠟像是怎麼來的？>"
  },
  AvgDialog_18939_Content_27 = {
    Text = "<Shake:媽媽，我、我害怕。>"
  },
  AvgDialog_18939_Content_28 = {
    Text = "這位警探，請注意你說話的語氣。"
  },
  AvgDialog_18939_Content_29 = {
    Text = "如果需要配合調查，歡迎隨時聯繫我們的律師弗朗茲·@1。我們就此別過。"
  },
  AvgDialog_18939_Content_3 = {
    Text = "他死了。現在我只有你了。"
  },
  AvgDialog_18939_Content_30 = {
    Text = "衣著華麗的婦人抬起尖尖的下巴，斜斜看了一眼面前的警探，隨後牽起男孩離開了。"
  },
  AvgDialog_18939_Content_32 = {
    Text = "終於找到工作室了！想不到你這傢伙還挺有用的嘛！"
  },
  AvgDialog_18939_Content_33 = {
    Text = "啊？是，是嗎……謝謝……"
  },
  AvgDialog_18939_Content_34 = {
    Text = "你環顧四周，這又是一處昏暗的所在。"
  },
  AvgDialog_18939_Content_35 = {
    Text = "牆角的壁燈閃爍著晦暗的光芒，將透過窗戶的月光也染上了一種灰濛濛的色澤。"
  },
  AvgDialog_18939_Content_36 = {
    Text = "空無一人的室內，隨處可見蠟制的手臂、腿腳、頭顱以及軀幹……"
  },
  AvgDialog_18939_Content_37 = {
    Text = "它們就像柔軟的破襪子，被人隨意堆疊在長凳、工作臺與地板上。"
  },
  AvgDialog_18939_Content_38 = {
    Text = "弗雷曼，小約翰，還有四指盧克……"
