  },
  AvgDialog_18958_Content_38 = {
    Text = "<SmallShake:我可是在他們中間安插了內應，小喬治也會幫忙的，保證萬無一失！>"
  },
  AvgDialog_18958_Content_39 = {
    Text = "你剛才說館長大人回來了？"
  },
  AvgDialog_18958_Content_4 = {
    Text = "一半悲鳴，一半恐怖，宛若來自地獄的迴響。"
  },
  AvgDialog_18958_Content_40 = {
    Text = "我可以認為這才是你的目的嗎？和我們拖延時間，直到羅傑斯回來。"
  },
  AvgDialog_18958_Content_41 = {
    Text = "是的，是的！我罪行累累，不可饒恕……"
  },
  AvgDialog_18958_Content_42 = {
    Text = "<Big:請狠狠地懲罰我吧！>"
  },
  AvgDialog_18958_Content_44 = {
    Text = "私心來說，我希望你不是梅森小姐，這樣我就能毫無顧忌地揍你一頓。"
  },
  AvgDialog_18958_Content_45 = {
    Text = "%player%，地下的怪物，要一起查探一下嗎？"
  },
  AvgDialog_18958_Content_46 = {Text = "當然"},
  AvgDialog_18958_Content_47 = {
    Text = "下面關著的，可能是羅傑斯的受害者，不能置之不理。"
  },
  AvgDialog_18958_Content_48 = {
    Text = "嗯。找找看附近有沒有能通往地下的通道吧。"
  },
  AvgDialog_18958_Content_49 = {Text = "我拒絕"},
  AvgDialog_18958_Content_5 = {
    Text = "不知過了多久，聲音才慢慢止歇。"
  },
  AvgDialog_18958_Content_50 = {
    Text = "直覺告訴我，那聲音有些不對勁，不能貿然前往。"
  },
  AvgDialog_18958_Content_51 = {
    Text = "別忘了，守密人。我們正是來調查這些不對勁的，不是來觀光旅遊。"
  },
  AvgDialog_18958_Content_52 = {
    Text = "不得不承認，拉蒙娜說得有道理。在求生的本能面前，你早已將《調查員守則》忘得一乾二淨。"
  },
  AvgDialog_18958_Content_53 = {
    Text = "<SmallShake:你，你說得沒錯……>"
  },
  AvgDialog_18958_Content_54 = {
    Text = "嗯。找找看附近有沒有能去到地下的通道吧。"
  },
  AvgDialog_18958_Content_55 = {
    Text = "這裡有個活板門，應該能通往地下！"
  },
  AvgDialog_18958_Content_57 = {
    Text = "你們用盡了全部的力氣，卻也只能將它拉開一道窄縫。"
  },
  AvgDialog_18958_Content_58 = {
    Text = "不行，根本打不開。"
  },
  AvgDialog_18958_Content_59 = {
    Text = "這種關鍵時刻，當然要靠我們了。"
  },
  AvgDialog_18958_Content_6 = {
    Text = "那、那是什麼東西……"
  },
  AvgDialog_18958_Content_7 = {
    Text = "哦呀。看來是館長大人回來了。\n地下的<Blue:小寵物們>都很想他呢。"
  },
  AvgDialog_18958_Content_8 = {
    Text = "23：00，菲爾費克斯醫生的診所\n一小時前"
  },
  AvgDialog_18958_Content_9 = {
    Text = "時間到了。感謝您的配合，羅傑斯先生。\n對於剛才造成的一點小誤會，我很抱歉。"
  },
  AvgDialog_18959_Content_1 = {Text = "後記"},
  AvgDialog_18959_Content_10 = {
    Text = "別忘了我哦。"
  },
  AvgDialog_18959_Content_11 = {
    Text = "如果沒有銀芯，死了就真的什麼都沒有了……或許是有人故意把銀芯收走了？"
  },
  AvgDialog_18959_Content_12 = {
    Text = "還是說，有什麼別的細節被我忽略了……"
  },
  AvgDialog_18959_Content_13 = {
    Text = "朵爾說你最近上課缺勤率很高，原來是躲在這裡和老師談心？"
  },
  AvgDialog_18959_Content_14 = {
    Text = "訶勒特院長！"
  },
  AvgDialog_18959_Content_15 = {
    Text = "別擔心，我不是來查考勤的。威廉今天回來了，或許你可以和他聊聊？"
  },
  AvgDialog_18959_Content_16 = {
    Text = "聽說他已經追查到了羅傑斯的行蹤，已經移交給審查會處理了。"
  },
  AvgDialog_18959_Content_18 = {
    Text = "明白……我去問問。"
  },
  AvgDialog_18959_Content_19 = {
    Text = "再見，阿利斯泰爾老師。再見，訶勒特院長。"
  },
  AvgDialog_18959_Content_2 = {
    Text = "一個月後\n彌薩格，限制區域A-001"
  },
  AvgDialog_18959_Content_20 = {
    Text = "腳步聲漸行漸遠，隨後傳來電梯沉重的運轉聲。"
  },
  AvgDialog_18959_Content_21 = {
    Text = "已經一個月了，%heorshe%還是無法接受詹金離開的現實。"
  },
  AvgDialog_18959_Content_22 = {
    Text = "%heorshe%在責怪自己。\n這是每個調查員剛上路時都會經歷的必修課，給%heorshe%一些時間吧。"
  },
  AvgDialog_18959_Content_23 = {
    Text = "好久不見，阿利斯泰爾。最近感覺怎麼樣？"
  },
  AvgDialog_18959_Content_24 = {
    Text = "和我這樣的老傢伙談論“感覺”，似乎有些多餘了。"
  },
  AvgDialog_18959_Content_25 = {
    Text = "從剛才%player%的反應來看，你現在已經是彌薩格的院長了？"
  },
  AvgDialog_18959_Content_26 = {
    Text = "代理院長。以及……你的消息似乎過於滯後了。"
  },
  AvgDialog_18959_Content_27 = {
    Text = "請原諒，大家都不太喜歡和我談論彌薩格。\n不論如何，恭喜職位升遷——這是你應得的。"
  },
  AvgDialog_18959_Content_28 = {
    Text = "呵……這可不是什麼好差事。"
  },
  AvgDialog_18959_Content_29 = {
    Text = "人們開始不記得因融蝕而死的人了。"
  },
  AvgDialog_18959_Content_3 = {
    Text = "聽說你今天又跟著審查會的人去蠟像館了，有什麼收穫嗎？"
  },
  AvgDialog_18959_Content_31 = {
    Text = "我記得那是洪積290年，還是291年？赫伯特在論文裡提出一種假設——"
  },
  AvgDialog_18959_Content_32 = {
    Text = "<Yellow:融蝕現象的盡頭，便是抹去人的存在本身。>"
  },
  AvgDialog_18959_Content_33 = {
    Text = "他曾是學院的驕傲。誰也想不到，他後來竟殺死了自己的導師，還是以如此殘忍的手段……"
  },
  AvgDialog_18959_Content_34 = {
    Text = "這很難預料麼？我早就提醒過他們了。"
  },
  AvgDialog_18959_Content_35 = {
    Text = "自黑夜裡滋生的，只能是那些見不得光的東西。"
  },
  AvgDialog_18959_Content_36 = {
    Text = "存在性消除在過去只有零星個例，沒人把它當回事。\n最近卻有頻發的跡象……"
  },
  AvgDialog_18959_Content_37 = {
    Text = "我已經和審查會取得了聯繫，請他們務必留心相關的症狀。只是……"
  },
  AvgDialog_18959_Content_38 = {
    Text = "從洪積15年第一例有記載的融蝕病症開始，已經過去快三百年了。"
  },
  AvgDialog_18959_Content_39 = {
    Text = "直到今天，我們對融蝕依然不甚了解。"
  },
  AvgDialog_18959_Content_4 = {
    Text = "你搖了搖頭。"
  },
  AvgDialog_18959_Content_40 = {
    Text = "我有種預感……這個新來的守密人，或許能成為祛散迷霧的關鍵。"
  },
  AvgDialog_18959_Content_41 = {
    Text = "%heorshe%能記得因融蝕而死的存在，光憑這點就已經足夠特別了。"
  },
  AvgDialog_18959_Content_42 = {
    Text = "%heorshe%必然比我們走得更遠。"
  },
  AvgDialog_18959_Content_43 = {
    Text = "南華克街44號，蠟像館廢墟"
  },
  AvgDialog_18959_Content_44 = {
    Text = "真是一片廢墟。不出三日，這裡就會變成一灘黑泥，然後徹底湮滅。"
  },
  AvgDialog_18959_Content_45 = {
    Text = "羅傑斯呢？"
  },
  AvgDialog_18959_Content_46 = {
    Text = "他和潘狄婭現在被審查會的瘋狗們逼得四處逃竄。我們上一次見面的時候，是在西岱的一家療養院。"
  },
  AvgDialog_18959_Content_47 = {
    Text = "這兩個傢伙隨心所欲慣了。給他們一點小小的教訓，讓他們知道什麼叫謹言慎行。"
  },
  AvgDialog_18959_Content_48 = {
    Text = "臨走前潘狄婭交給我一個東西，說是給你的賠禮。"
  },
  AvgDialog_18959_Content_49 = {
    Text = "什麼東西……個人檔案？"
  },
  AvgDialog_18959_Content_5 = {
    Text = "那裡被融蝕得乾乾淨淨，一點銀芯的碎屑都沒找到。"
  },
  AvgDialog_18959_Content_50 = {
    Text = "打開看看，裡面有驚喜。"
  },
  AvgDialog_18959_Content_52 = {
    Text = "出生日期不詳……去年才被彌薩格錄入，從未接受過訓練卻能連結多名喚醒體作戰……"
  },
  AvgDialog_18959_Content_53 = {
    Text = "真是個有趣的傢伙，想不到彌薩格還藏了這一手。"
  },
  AvgDialog_18959_Content_54 = {
    Text = "看來當年的“提燈事件”還沒讓他們吃夠苦頭。"
  },
  AvgDialog_18959_Content_55 = {
    Text = "是時候回學院看看了，給我最親愛的導師掃掃墓。"
  },
  AvgDialog_18959_Content_56 = {
    Text = "倫蒂尼恩郊外\n肖爾迪奇墓地"
  },
  AvgDialog_18959_Content_58 = {
    Text = "%player%%sirormadam%！你怎麼來了……"
  },
  AvgDialog_18959_Content_59 = {
    Text = "我來看看詹金。"
  },
  AvgDialog_18959_Content_6 = {
    Text = "只有極少數的人死後會析出銀芯，我以為這個道理你早該明白的。"
  },
  AvgDialog_18959_Content_60 = {
    Text = "你蹲下身，輕輕拂開小小墓碑上浮動的碎屑。墓碑上空空如也，你們還沒准備好在上面篆刻文字。"
  },
  AvgDialog_18959_Content_61 = {
    Text = "就好像……一旦刻上了文字，詹金的離開就會成為現實。"
  },
  AvgDialog_18959_Content_62 = {
    Text = "24小姐，在蠟像館的時候，你為什麼不告訴我們你的真實身分？"
  },
  AvgDialog_18959_Content_64 = {
    Text = "那時候我的腦子很亂，也很害怕……詹金如果見到我這副模樣，一定會傷心的。"
  },
  AvgDialog_18959_Content_66 = {
    Text = "是啊……她一直是我見過最勇敢堅強的孩子。"
  },
  AvgDialog_18959_Content_67 = {
    Text = "學院的事我都聽說了。詹金的銀芯還是沒有任何下落，對麼？"
  },
  AvgDialog_18959_Content_68 = {
    Text = "威廉學長那邊暫時還沒有新情報。放心吧，24小姐。"
  },
  AvgDialog_18959_Content_69 = {
    Text = "等羅傑斯落網的那一天，我會親自審問。"
  },
  AvgDialog_18959_Content_7 = {
    Text = "可詹金她，她不一樣……"
  },
  AvgDialog_18959_Content_70 = {
    Text = "24搖了搖頭。"
  },
  AvgDialog_18959_Content_71 = {
    Text = "我知道你不會放棄的。我只是擔心……我對詹金的記憶已經開始模糊了。"
  },
  AvgDialog_18959_Content_72 = {
    Text = "我怕即使有一天她真的站在我面前，我也認不出她。"
  },
  AvgDialog_18959_Content_73 = {
    Text = "那就等忘記的那一天，我來告訴你吧。"
  },
  AvgDialog_18959_Content_74 = {
    Text = "你們是怎麼相遇的、生活的，她是怎麼救你的，又是如何成為了我們的大英雄……"
  },
  AvgDialog_18959_Content_75 = {
    Text = "聲音逐漸降低，最終被吹散在輕柔的微風裡。"
  },
  AvgDialog_18959_Content_77 = {
    Text = "耳畔忽然傳來細弱的響動，忽高忽低，還帶著一股抑揚頓挫的節奏感。"
  },
  AvgDialog_18959_Content_78 = {
    Text = "怎麼有老鼠……<Big:布朗？！>"
  },
  AvgDialog_18959_Content_8 = {
    Text = "如果你幫我，我就把你的錢包和那什麼證還你，幫你保密。\n如果你不幫我的話……哼哼！"
  },
  AvgDialog_18959_Content_80 = {
    Text = "聽聲音……似乎就在附近。"
  },
  AvgDialog_18959_Content_81 = {
    Text = "你急忙起身轉了一圈，竟然真的在墓碑背後的雜草叢中見到了一隻肥碩的小老鼠。"
  },
  AvgDialog_18959_Content_82 = {
    Text = "呼嚕……呼……"
  },
  AvgDialog_18959_Content_83 = {
    Text = "這體格、還有花色……真的是布朗！！"
  },
  AvgDialog_18959_Content_84 = {
    Text = "你和24一齊驚呼。"
  },
  AvgDialog_18959_Content_85 = {
    Text = "這位自蠟像館事件後便消失至今的小老鼠並未被你們打斷睡眠。"
  },
  AvgDialog_18959_Content_86 = {
    Text = "它似乎剛剛經歷一場驚心動魄的冒險，此刻無比疲憊地睡倒在旅途的終點。"
  },
  AvgDialog_18959_Content_87 = {
    Text = "呼呼……咻……嚕嚕……"
  },
  AvgDialog_18959_Content_88 = {
    Text = "它懷裡似乎抱著什麼東西……"
  },
  AvgDialog_18959_Content_9 = {
    Text = "<Big:《波羅的海之春》！>"
  },
  AvgDialog_18959_Content_90 = {
    Text = "是銀芯。詹金的銀芯。"
  },
  AvgDialog_18959_Content_91 = {
    Text = "小小的爪子緊緊抱著一顆銀芯。它尚且未經打磨，周身散發著渾濁的微光。"
  },
  AvgDialog_18959_Content_92 = {
    Text = "然而在這微光之下，你彷彿聽到了那無比歡快的、活潑的心跳聲。"
  },
  AvgDialog_18959_Content_93 = {
    Text = "好久不見，詹金。"
  },
  AvgDialog_18959_Content_94 = {
    Text = "天空終於放晴了。陽光高懸空中，拋灑著金色光芒以及恰到其分的溫暖。"
  },
  AvgDialog_18959_Content_95 = {
    Text = "風帶著清新的泥土氣息吹來，你和24沐浴在溫暖的陽光下，相視一笑。"
  },
  AvgDialog_18959_Content_97 = {
    Text = "連日的陰雲終於散去，屬於你們的冒險故事才剛剛開始。"
  },
  AvgDialog_18960_Content_1 = {
    Text = "寂靜的坍塌"
  },
  AvgDialog_18960_Content_10 = {
    Text = "可我們現在別無選擇。"
  },
  AvgDialog_18960_Content_11 = {
    Text = "可以試試"
  },
  AvgDialog_18960_Content_12 = {
    Text = "%player%，希望你冷靜一點。"
  },
  AvgDialog_18960_Content_13 = {
    Text = "前面已經被融蝕漿湮沒了，即使是喚醒體，長時間浸泡在裡面也會受影響。"
  },
  AvgDialog_18960_Content_14 = {
    Text = "現在已經無法通過正常路線回去了，得想想其他辦法。"
  },
  AvgDialog_18960_Content_15 = {
    Text = "其他辦法……其他通道……"
  },
  AvgDialog_18960_Content_17 = {
    Text = "看，那裡有個通風口。"
  },
  AvgDialog_18960_Content_18 = {
    Text = "你們順著詹金的目光抬頭，小小的通風口就位於你們頭頂。"
  },
  AvgDialog_18960_Content_19 = {
    Text = "那裡確實有可能通往館長室，融蝕漿也夠不到……"
  },
  AvgDialog_18960_Content_2 = {
    Text = "4：15，羅傑斯蠟像館"
  },
  AvgDialog_18960_Content_20 = {
    Text = "不行，這個通道太小了，我們沒辦法進去。"
  },
  AvgDialog_18960_Content_21 = {
    Text = "我可以鑽進去。"
  },
  AvgDialog_18960_Content_22 = {
    Text = "你們忘了嗎，我可是“老鼠”。"
  },
  AvgDialog_18960_Content_24 = {
    Text = "不行，這樣太冒險了。沒人能保證鑰匙現在還在館長室裡，就連這個通風口到底能不能——"
  },
  AvgDialog_18960_Content_25 = {
    Text = "嘖。囉裡囉嗦的煩死啦，我還以為你是個乾脆的大人，拉蒙娜小姐。"
  },
  AvgDialog_18960_Content_26 = {
    Text = "我來幫你們厘清現實吧：第一，現在好像沒有其他辦法了吧？與其在這裡等死，還不如去撞撞運氣。"
  },
  AvgDialog_18960_Content_27 = {
    Text = "第二，我和布朗一起去，我指揮，它才是負責拿鑰匙的那個。"
  },
  AvgDialog_18960_Content_3 = {
    Text = "你們踉蹌著在廢墟中奔跑，喘息聲此起彼伏。"
  },
  AvgDialog_18960_Content_30 = {
    Text = "這次我給你們添了不少麻煩，姐姐還替我挨了鞭子。"
  },
  AvgDialog_18960_Content_32 = {
    Text = "多少也讓我幫一些忙吧，我可受不了被你們一直照顧。"
  },
  AvgDialog_18960_Content_33 = {
    Text = "說完詹金一躍爬上通風口，就像之前無數次在白教堂區錯落的房屋中來回穿梭那樣，瞬間沒了身影。"
  },
  AvgDialog_18960_Content_34 = {
    Text = "詹金……！她從來都不肯好好聽我的話……"
  },
  AvgDialog_18960_Content_35 = {
    Text = "別擔心，24小姐。詹金比我們都要靈巧，她一定會沒事的。"
  },
  AvgDialog_18960_Content_4 = {
    Text = "終於，你們看到前方那扇沉重的大門。只需要輕輕一推——"
  },
  AvgDialog_18960_Content_5 = {
    Text = "糟糕，門鎖住了。"
  },
  AvgDialog_18960_Content_6 = {
    Text = "前方已化為一片黑色的海洋，危險一步步逼近，沒有任何退路可言。"
  },
  AvgDialog_18960_Content_7 = {
    Text = "似乎是威廉學長提過的那扇門……鑰匙應該在館長室裡。"
  },
  AvgDialog_18960_Content_9 = {
    Text = "這裡到處都是融蝕漿……即使是喚醒體，長時間浸泡在裡面也會立刻死亡。"
  },
  AvgDialog_18961_Content_100 = {
    Text = "下一秒，她輕抖手腕，滾燙的蠟猛然傾注，白皙的手臂綻開猙獰赤紅的花瓣。"
  },
  AvgDialog_18961_Content_102 = {
    Text = "哦呀……好漂亮的紋路。"
  },
  AvgDialog_18961_Content_103 = {
    Text = "喬治討厭吵鬧的豬玀，把蠟全部灌進她嘴裡。"
  },
  AvgDialog_18961_Content_104 = {
    Text = "漂浮的燭臺飛至詹金的面前，蒸騰的熱氣將詹金的臉烤至通紅。"
  },
  AvgDialog_18961_Content_105 = {
    Text = "燭臺內盛滿了滾燙的蠟，即將傾倒而出。"
  },
  AvgDialog_18961_Content_106 = {
    Text = "<Shake:騙子……不是說一點都不痛嗎……>"
  },
  AvgDialog_18961_Content_107 = {
    Text = "真不好意思，人家已經不做人很久了，不知道會這麼難受呢~"
  },
  AvgDialog_18961_Content_108 = {
    Text = "完美。你們兩個上來，撬開她的嘴。"
  },
  AvgDialog_18961_Content_109 = {
    Text = "接下來只需要把蠟灌進去，陰溝裡的臭老鼠就能永遠閉嘴了。"
  },
  AvgDialog_18961_Content_11 = {
    Text = "下次再這麼遲鈍，連你一起裝進棺材裡哦~"
  },
  AvgDialog_18961_Content_110 = {
    Text = "停下……快停下！她和這一切都無關……"
  },
  AvgDialog_18961_Content_112 = {
    Text = "不要……不要，我改變主意了，我不想死了！別過來……！"
  },
  AvgDialog_18961_Content_115 = {
    Text = "混亂中，你忽然聽到一聲輕輕的歎息。"
  },
  AvgDialog_18961_Content_116 = {
    Text = "我說……請等一下。"
  },
  AvgDialog_18961_Content_12 = {
    Text = "抱歉，潘狄婭小姐……"
  },
  AvgDialog_18961_Content_13 = {
    Text = "<Big:潘狄婭大人——！！>"
  },
  AvgDialog_18961_Content_14 = {
    Text = "女子的身影雲一般飄過，長長的裙擺打著旋泛出白光。她匍匐跪倒在潘狄婭面前。"
  },
  AvgDialog_18961_Content_15 = {
    Text = "潘狄婭大人！請不要這樣對待24，要懲罰的話……"
  },
  AvgDialog_18961_Content_16 = {
    Text = "請衝著我來！"
  },
  AvgDialog_18961_Content_18 = {
    Text = "我改變主意了，你們都做得很好，退下吧。"
  },
  AvgDialog_18961_Content_19 = {
    Text = "大人，我明白您不忍心責備我。您一直都是如此溫柔……"
  },
  AvgDialog_18961_Content_2 = {
    Text = "不錯，人都齊了。這下我們可得給彌薩格準備一份大禮。"
  },
  AvgDialog_18961_Content_21 = {
    Text = "我親愛的，我最最親愛的甜心，先放開我的腿，好嗎？"
  },
  AvgDialog_18961_Content_22 = {
    Text = "一切都聽您的，潘狄婭大人。"
  },
  AvgDialog_18961_Content_23 = {
    Text = "真乖。就像現在這樣……然後向後轉，向前走十步，離開這個房間，再也不要回頭。"
  },
  AvgDialog_18961_Content_24 = {
    Text = "明白我的意思嗎？"
  },
  AvgDialog_18961_Content_25 = {
    Text = "明白……我會想念您的，潘狄婭大人……\n不對，我現在已經開始想念您了！"
  },
  AvgDialog_18961_Content_26 = {
    Text = "女子轉過身，臨走前還不忘貼心帶上房門。"
  },
  AvgDialog_18961_Content_27 = {
    Text = "呼……真叫人傷腦筋。"
  },
  AvgDialog_18961_Content_28 = {
    Text = "確認房門緊緊關閉後，潘狄婭深吸一口氣，又恢復了往日的活力。"
  },
  AvgDialog_18961_Content_29 = {
    Text = "好了各位，我們剛才說到哪裡了呀~"
  },
  AvgDialog_18961_Content_3 = {
    Text = "不過呢，這一刻等得還是稍微有一點點——不對，超級久了。"
  },
  AvgDialog_18961_Content_30 = {
    Text = "呼吸……好艱難。"
  },
  AvgDialog_18961_Content_32 = {
