  AvgDialog_18961_Content_38 = {
    Text = "%player%，你終於醒了！"
  },
  AvgDialog_18961_Content_39 = {
    Text = "放開我……唔！"
  },
  AvgDialog_18961_Content_4 = {
    Text = "24，我最親愛的24，快過來呀~"
  },
  AvgDialog_18961_Content_40 = {
    Text = "別亂動哦，人家可是費了好大的勁才把你們固定住呢。"
  },
  AvgDialog_18961_Content_41 = {
    Text = "看到那邊的棺材了嗎？為你們精心準備的哦。\n你們啊，馬上就要獲得新生了~"
  },
  AvgDialog_18961_Content_42 = {
    Text = "不過是以蠟像的形式，嘻嘻。這次做個什麼主題好呢？唔……"
  },
  AvgDialog_18961_Content_43 = {
    Text = "老查理在哪裡都找不到他的虎斑貓~"
  },
  AvgDialog_18961_Content_44 = {
    Text = "虎斑貓，虎斑貓~"
  },
  AvgDialog_18961_Content_45 = {
    Text = "拉蒙娜……拉蒙娜？！見鬼，別唱了……"
  },
  AvgDialog_18961_Content_46 = {
    Text = "那傢伙從我醒來就變成這樣了，只會翻來覆去地唱歌。"
  },
  AvgDialog_18961_Content_47 = {
    Text = "你的夥伴已經被做成蠟像了哦，花了羅傑斯大人一個小時呢。"
  },
  AvgDialog_18961_Content_48 = {
    Text = "虎斑貓！喵！"
  },
  AvgDialog_18961_Content_49 = {
    Text = "怎麼樣，喜歡嗎？是不是超級可愛~"
  },
  AvgDialog_18961_Content_5 = {
    Text = "……是，潘狄婭大人。"
  },
  AvgDialog_18961_Content_50 = {
    Text = "呸，把你的髒手從她身上拿開！"
  },
  AvgDialog_18961_Content_51 = {
    Text = "羅傑斯，在工坊里弄暈我的傢伙就是你吧。"
  },
  AvgDialog_18961_Content_52 = {
    Text = "你害死了艾繼絲，小麥克，就連我姐姐的失蹤也……"
  },
  AvgDialog_18961_Content_53 = {
    Text = "艾繼絲是什麼東西？"
  },
  AvgDialog_18961_Content_54 = {
    Text = "不好意思，喬治從來不記得廢棄素材和垃圾的名字。"
  },
  AvgDialog_18961_Content_55 = {
    Text = "你@2罵誰呢？！@1豬！"
  },
  AvgDialog_18961_Content_56 = {
    Text = "咦，難道不是嗎？你叫詹金，對吧。莎拉和我們說起過小詹金的故事。"
  },
  AvgDialog_18961_Content_57 = {
    Text = "小詹金剛出生不久，她的酒鬼父親就跑了。"
  },
  AvgDialog_18961_Content_58 = {
    Text = "小詹金的媽媽得了融蝕，成了一個瘋女人。"
  },
  AvgDialog_18961_Content_59 = {
    Text = "瘋女人每天都用掃帚、皮帶、還有一切能找到的工具毆打小詹金，還要用最骯髒的話辱罵小詹金……"
  },
  AvgDialog_18961_Content_60 = {
    Text = "你……你胡說……"
  },
  AvgDialog_18961_Content_61 = {
    Text = "哦對了，她身體裡還會流出很多黑色的粘液，家裡床上、地板上，全是黏糊糊、濕噠噠的……噫！"
  },
  AvgDialog_18961_Content_62 = {
    Text = "說到這裡，喬治誇張地打了個寒戰，又咯咯笑了起來。"
  },
  AvgDialog_18961_Content_63 = {
    Text = "然後呢瘋女人自己跑了。小詹金站在家門口等她，等啊，等啊……\n瘋女人去哪裡啦？沒有人知道。"
  },
  AvgDialog_18961_Content_64 = {
    Text = "不，不是這樣的……"
  },
  AvgDialog_18961_Content_65 = {
    Text = "呸呸呸，喬治偏要說！後來呢，小詹金被送去福利院，可那不過是從一個垃圾場去了另一個垃圾場。"
  },
  AvgDialog_18961_Content_66 = {
    Text = "承認吧，你們就是倫蒂尼恩街道上、下水道裡隨處可見的垃圾，一場暴雨就能全部衝光光！"
  },
  AvgDialog_18961_Content_67 = {
    Text = "就連你的姐姐，難道不是因為厭倦了一切，想拋下你才隨便找了個藉口離開的？"
  },
  AvgDialog_18961_Content_68 = {
    Text = "閉嘴……<Big:你給我閉嘴！>"
  },
  AvgDialog_18961_Content_69 = {
    Text = "詹金顫抖著，臉色無比蒼白。她張了張嘴，似乎是想辯解什麼，可到頭來也只是沮喪地低下頭。"
  },
  AvgDialog_18961_Content_7 = {
    Text = "黑色的皮鞭輕輕一晃，24被打翻在地，身上瞬間浮起紅腫的鞭痕。"
  },
  AvgDialog_18961_Content_70 = {
    Text = "是啊，她有什麼資格呢。對陰溝裡的老鼠而言，愛是一種絕對的奢侈，是夢裡才敢伸手觸碰的糖果。"
  },
  AvgDialog_18961_Content_71 = {
    Text = "一雙手輕輕撫上詹金的頭。"
  },
  AvgDialog_18961_Content_72 = {
    Text = "可憐的孩子。我見過很多像、像你一樣悲傷的孩子。他們不被需要，也不被善待。"
  },
  AvgDialog_18961_Content_73 = {
    Text = "所以我想幫、幫助你們離開——以蠟像的形式。"
  },
  AvgDialog_18961_Content_74 = {
    Text = "幫助我們？可是你們對艾繼絲，對小麥克……"
  },
  AvgDialog_18961_Content_75 = {
    Text = "你確定讓他們繼、繼續辛苦地活在世上，是一個好的選擇嗎？"
  },
  AvgDialog_18961_Content_77 = {
    Text = "放心吧，可憐的孩子。\n我會讓你變成最漂亮的蠟像，一點也不會痛的。"
  },
  AvgDialog_18961_Content_78 = {
    Text = "詹金，別聽他們的詭辯！"
  },
  AvgDialog_18961_Content_79 = {
    Text = "羅傑斯，你真是個自欺欺人的小丑。\n變成蠟像就能假裝一切都沒發生過？"
  },
  AvgDialog_18961_Content_80 = {
    Text = "他們真的是自願的嗎？\n你敢保證你從來沒有蠱惑、強迫過你的那些“蠟像素材”？！"
  },
  AvgDialog_18961_Content_81 = {
    Text = "別吵了。"
  },
  AvgDialog_18961_Content_82 = {
    Text = "小不點，我承認你說得不錯。這個世界就是爛透了。"
  },
  AvgDialog_18961_Content_83 = {
    Text = "反正我們現在跑也跑不了……動作快點吧，我還等著去找媽媽呢。"
  },
  AvgDialog_18961_Content_84 = {
    Text = "詹金，我知道你現在很難過。\n但是，請別忘了我們是來找你姐姐的，她還等著我們救她。"
  },
  AvgDialog_18961_Content_86 = {
    Text = "或許，所謂的姐姐，只存在於我的幻想裡……"
  },
  AvgDialog_18961_Content_87 = {
    Text = "不然她怎麼會，到現在都不出來見我呢？"
  },
  AvgDialog_18961_Content_88 = {
    Text = "啊呀，既然小老鼠都發話了，那還等什麼呢。"
  },
  AvgDialog_18961_Content_89 = {
    Text = "24，雷婭，快過來把蠟澆上去。要輕輕地、溫柔地澆上去哦~"
  },
  AvgDialog_18961_Content_9 = {
    Text = "人家等得都快睡著了也沒看見你們，還是喬治出手才把人帶過來。"
  },
  AvgDialog_18961_Content_91 = {
    Text = "潘狄婭大人，您的命令就是我的神諭。"
  },
  AvgDialog_18961_Content_92 = {
    Text = "你們怎麼會一起……我明白了，你們是一夥的。"
  },
  AvgDialog_18961_Content_94 = {
    Text = "女子手持盛滿蠟液的杯盞，走到詹金面前。"
