  AvgDialog_18966_Content_13 = {
    Text = "<Shake:羅傑斯……羅傑斯……>"
  },
  AvgDialog_18966_Content_15 = {
    Text = "約定……？難道是……"
  },
  AvgDialog_18966_Content_16 = {
