  AvgDialog_18980_Content_28 = {
    Text = "咦，你們什麼都不記得了？"
  },
  AvgDialog_18980_Content_29 = {
    Text = "“立體派的傑出捍衛者，波提切利的靈魂轉世正隱居於南華克街角的蠟像館內……”"
  },
  AvgDialog_18980_Content_3 = {
