  AvgDialog_18986_Content_9 = {
    Text = "我理解人類在失去重要血親時的焦慮感，但也該讓她清醒一點面對現實了。"
  },
  AvgDialog_18987_Content_1 = {
    Text = "黑咕隆咚的，什麼也看不清。萬一是個陷阱……"
  },
  AvgDialog_18987_Content_10 = {
    Text = "這是出外勤必備的工具，不是什麼厲害的東西，小朋友。"
  },
  AvgDialog_18987_Content_2 = {
    Text = "試試這個？"
  },
  AvgDialog_18987_Content_3 = {
    Text = "黑暗中，拉蒙娜鎮定地打開一支手電，重新照亮了道路。"
  },
  AvgDialog_18987_Content_4 = {
    Text = "嗚哇，怎麼有光從裡面衝出來了！這是什麼東西？"
  },
  AvgDialog_18987_Content_5 = {
    Text = "學名掌上型電子設備，簡稱手電筒。\n可防止我們撞到牆上、樹上、路燈上。"
  },
  AvgDialog_18987_Content_7 = {
    Text = "有時候我覺得，你的背包就像一個深不見底的兔子洞。"
  },
  AvgDialog_18987_Content_8 = {
    Text = "你會不會哪天從裡面掏出全套的茶話會餐具，就像童話故事裡說的那樣？"
  },
  AvgDialog_18988_Content_1 = {
    Text = "希望這輩子再也不要相見哦，我的小甜心們~"
  },
  AvgDialog_18988_Content_10 = {
    Text = "讓他去吧。羅傑斯是雕塑家協會的重要成員，不能就這樣放他離開。"
  },
  AvgDialog_18988_Content_11 = {
    Text = "明白。那麼接下來……"
  },
  AvgDialog_18988_Content_12 = {
    Text = "你們回望著眼前一地的狼藉。"
  },
  AvgDialog_18988_Content_13 = {
    Text = "不，不要丟下我……"
  },
  AvgDialog_18988_Content_15 = {
    Text = "先是雙腿、軀幹、手臂……"
  },
  AvgDialog_18988_Content_16 = {
    Text = "不……你們這些垃圾，不許靠近喬治……"
  },
  AvgDialog_18988_Content_17 = {
    Text = "然後是嘴、鼻子、眼睛……"
  },
  AvgDialog_18988_Content_18 = {
    Text = "喬治的漂亮的金色腦袋被蠟像們不斷撕扯，直到徹底裂開。"
  },
  AvgDialog_18988_Content_19 = {
    Text = "<Change>謝謝羅傑斯，美味，吃掉，吃掉——！！！"
  },
  AvgDialog_18988_Content_2 = {
    Text = "你們就待在這裡被乖乖融蝕掉吧，永遠別出現在我的回憶裡！"
  },
  AvgDialog_18988_Content_20 = {
    Text = "<Change>給我吃一點，吃一點——！！！"
  },
  AvgDialog_18988_Content_21 = {
    Text = "<Shake:別吃我，你們怎麼敢吃我……不——>"
  },
  AvgDialog_18988_Content_23 = {
    Text = "有了喬治的加入，原本堆積成小山的蠟像和屍塊們再度自發地、緩慢地糅合在了一起。"
  },
  AvgDialog_18988_Content_24 = {
    Text = "黑色的粘液從無數它們的眼睛、嘴唇和耳朵裡滴落下來。"
  },
  AvgDialog_18988_Content_25 = {
    Text = "位於中間的碩大頭顱，正是喬治。"
  },
  AvgDialog_18988_Content_26 = {
    Text = "<Change>嗚嗚嗚……好餓、好餓……"
  },
  AvgDialog_18988_Content_27 = {
    Text = "都怪你們……都怪你們……"
  },
  AvgDialog_18988_Content_28 = {
    Text = "<Change>都是你們的錯！！"
  },
  AvgDialog_18988_Content_4 = {
    Text = "不能讓他跑了……%player%，拉蒙娜，這裡你們能搞定嗎？"
  },
  AvgDialog_18988_Content_5 = {
    Text = "你和拉蒙娜齊刷刷點了點頭。"
  },
  AvgDialog_18988_Content_6 = {
    Text = "威脅最大的裂隙已經被關閉了，剩下的交給我們吧。可學長你一個人……"
  },
  AvgDialog_18988_Content_7 = {
    Text = "好，我相信你們。記得活著回來。"
  },
  AvgDialog_18988_Content_8 = {
    Text = "威廉說罷，收起面前的儀器，帶上手提箱匆忙追了出去。"
  },
  AvgDialog_18988_Content_9 = {
    Text = "學長……"
  },
  AvgDialog_18991_Content_1 = {
    Text = "你好，達芙黛爾夫人"
  },
  AvgDialog_18991_Content_10 = {
    Text = "她的語調柔軟而曖昧，口音中帶有一絲上流社會的優雅。"
  },
  AvgDialog_18991_Content_11 = {
    Text = "雖然說著抱歉，表情卻絲毫不含歉意，反而顯露出絲絲嘲弄。"
  },
  AvgDialog_18991_Content_12 = {
    Text = "這鄉野間最近有“地獄犬”出沒，早些沉入夢鄉或許就能躲開它的視線。"
  },
  AvgDialog_18991_Content_13 = {
    Text = "地獄犬？"
  },
  AvgDialog_18991_Content_14 = {
    Text = "傳說只要被它的目光捕獲三次，就會墮入虛無之中，迎來死亡。\n各位客人們，還是小心點為好呢。"
  },
  AvgDialog_18991_Content_15 = {
    Text = "我以為這只是哄騙不睡覺小孩的話術。"
  },
  AvgDialog_18991_Content_16 = {
    Text = "莫真若假，誰知道呢？鄉野傳說自有其真實之處吧。"
  },
  AvgDialog_18991_Content_17 = {
    Text = "你似乎不那麼認為。"
  },
  AvgDialog_18991_Content_18 = {
    Text = "真假總是成對出現，一個人眼中的真相，可能是另一人眼中的虛妄。"
  },
  AvgDialog_18991_Content_19 = {
    Text = "瞧我，又在說些亂七八糟的話了，還請各位不要放在心上。\n早些歇息吧，親愛的客人們。"
  },
  AvgDialog_18991_Content_2 = {
    Text = "你們在少女的引領下，來到街角一間不起眼的小店內。"
  },
  AvgDialog_18991_Content_20 = {
    Text = "說完，達芙黛爾起身，施施然離去，只留給你們散發幽香的背影。"
  },
  AvgDialog_18991_Content_21 = {
    Text = "……你們在胡說八道些什麼？"
  },
  AvgDialog_18991_Content_22 = {
    Text = "我也沒聽懂。"
  },
  AvgDialog_18991_Content_23 = {
    Text = "我們現在處在一個幻象之中。\n用銀鑰匙看看吧，你會明白我在說什麼的。"
  },
  AvgDialog_18991_Content_26 = {
    Text = "這片區域的融蝕程度遠超常理，達芙黛爾和貨品卻纖塵不染。"
  },
  AvgDialog_18991_Content_27 = {
    Text = "達芙黛爾夫人（Lady Daffodil），水仙夫人，很難相信是真名。"
  },
  AvgDialog_18991_Content_28 = {
    Text = "如果是販賣違禁品的商人，用假名示人也不是說不通。"
  },
  AvgDialog_18991_Content_3 = {
    Text = "紫霧繚繞的小店只有十英尺寬窄，陳設卻頗有品位。\n精緻古樸的小擺件在櫃檯上層層疊疊地堆放著，亂中有序。"
  },
  AvgDialog_18991_Content_30 = {
    Text = "假如你是一名有“經驗”的商人，在這失蹤案頻發的小鎮，會輕易在半夜放三個陌生人進門嗎？"
  },
  AvgDialog_18991_Content_31 = {
    Text = "還有，我總覺得有什麼在盯著我們看。"
  },
  AvgDialog_18991_Content_32 = {
    Text = "你也覺得渾身發毛嗎？"
  },
  AvgDialog_18991_Content_33 = {
    Text = "別把我想得跟你一樣。\n我只是很好奇，到底是哪個膽大包天的傢伙，敢把我當成獵物。"
  },
  AvgDialog_18991_Content_34 = {
    Text = "這裡至少有遮雨的頂棚。\n我們輪崗休息，保持警惕，剩下的事情，明天再說吧。"
  },
  AvgDialog_18991_Content_36 = {
    Text = "對了，艾瑞卡？"
  },
  AvgDialog_18991_Content_37 = {
    Text = "你好，自動人偶艾瑞卡全天候待機，給予你最及時的技術與資訊支援。"
  },
  AvgDialog_18991_Content_38 = {
    Text = "關鍵字：“達芙黛爾夫人”，職業古董商人。"
  },
  AvgDialog_18991_Content_39 = {
    Text = "輸入關鍵字“達芙黛爾”，“古董商人”，正在進行檢索，請稍候。\n檢索結果，無。非常抱歉，請更換關鍵字再進行嘗試……"
  },
  AvgDialog_18991_Content_4 = {
    Text = "嘖，說是達芙黛爾“夫人”的店鋪，原來只是個街頭的零售小店啊。"
  },
  AvgDialog_18991_Content_41 = {
    Text = "夜色漸濃，伴隨著拉蒙娜與艾瑞卡的交談聲，你漸漸沉入夢境……"
  },
  AvgDialog_18991_Content_43 = {
    Text = "……你別和她爭。那件事後，就有人說她瘋了。"
  },
  AvgDialog_18991_Content_44 = {
    Text = "她找到醫生，聲稱自己能看到什麼“<Yellow:人身體上的空洞>”……\n還說什麼，那種空洞害死了她的丈夫和女兒。"
  },
  AvgDialog_18991_Content_45 = {
    Text = "她不是一直單身嗎，哪來的丈夫和女兒？"
  },
  AvgDialog_18991_Content_46 = {
    Text = "是啊，可不是失心瘋了麼？"
  },
  AvgDialog_18991_Content_47 = {
    Text = "既然這樣，我們能不能要求對她進行精神狀態評估？"
  },
  AvgDialog_18991_Content_48 = {
    Text = "還用得著評估？一般人活得好好的，會主動申請去送死嗎？"
  },
  AvgDialog_18991_Content_49 = {
    Text = "還有那群狂熱的探險愛好者，我看他們的腦袋也不太正常。真要做精神檢測，只怕沒有哪個通過得了。"
  },
  AvgDialog_18991_Content_5 = {
    Text = "而且，這些……古董？怪模怪樣的，真是扭曲。"
  },
  AvgDialog_18991_Content_50 = {
    Text = "黑色的濃稠黏液自天際垂落，覆蓋視野。"
  },
  AvgDialog_18991_Content_51 = {
    Text = "覆蓋在<Blue:基金會>的臺階上、基金會的大門上、基金會的櫃檯上。"
  },
  AvgDialog_18991_Content_52 = {
    Text = "直到基金會員工的臉上。"
  },
  AvgDialog_18991_Content_53 = {
    Text = "我警告你們，我保有將你們以誹謗罪告上法庭的權利。"
  },
  AvgDialog_18991_Content_54 = {
    Text = "這些黑色的黏液……雖然你們看不見，但它們是真實存在的。\n就是它們，就是它們，奪走了……"
  },
  AvgDialog_18991_Content_55 = {
    Text = "奪走了……我最親近的人……"
  },
  AvgDialog_18991_Content_56 = {
    Text = "為什麼？為什麼他們都看不見？"
  },
  AvgDialog_18991_Content_57 = {
    Text = "很疼，但是@2 能忍住，媽媽。"
  },
  AvgDialog_18991_Content_58 = {
    Text = "不，不行，不能這樣，你會消失的。\n我已經失去了@3，我不能再失去你了。"
  },
  AvgDialog_18991_Content_59 = {
    Text = "我不會離開媽媽的。"
  },
  AvgDialog_18991_Content_6 = {
    Text = "我倒是很愛惜這些藏品。您不覺得它們身上有一種積澱時光的美嗎？"
  },
  AvgDialog_18991_Content_60 = {
    Text = "為什麼？你不是說不會離開我的嗎？"
  },
  AvgDialog_18991_Content_61 = {
    Text = "對啊，你也看不見。"
  },
  AvgDialog_18991_Content_62 = {
    Text = "可是我看得見、我看得見啊！"
  },
  AvgDialog_18991_Content_63 = {
    Text = "他們不是失蹤，他們生病了，他們在溶解……\n那些黑色的黏液，在溶解他們……"
  },
  AvgDialog_18991_Content_64 = {
    Text = "女人低語著沉沉睡去。周遭的霧氣輕柔彌漫，漸漸將她籠罩。\n濃霧之中，浮現出深紫色的黯影。"
  },
  AvgDialog_18991_Content_65 = {
    Text = "原本想來看看是不是到了收割的時間……沒想到事情會發展得這麼有趣。"
  },
  AvgDialog_18991_Content_66 = {
    Text = "算了，這人頭你就先留著吧。"
  },
  AvgDialog_18991_Content_67 = {
    Text = "等你從那冰封極寒之地回來，可要好好交給我哦？"
  },
  AvgDialog_18991_Content_7 = {
    Text = "幽魅的聲音從迷離暗影中流出，如極沉的低音流入混雜的交響。"
  },
  AvgDialog_18991_Content_8 = {
    Text = "抱歉，請容我自我介紹，我便是這間小店的店主，達芙黛爾。"
  },
  AvgDialog_18991_Content_9 = {
    Text = "我無意打擾客人們的談話。\n只是想提醒各位，夜已深，該休息了。"
  },
  AvgDialog_18992_Content_1 = {
    Text = "人生無友"
  },
  AvgDialog_18992_Content_10 = {
    Text = "希洛喃喃著，微微張合的口中念誦著語調生澀、古老難懂的褻瀆咒文。"
  },
  AvgDialog_18992_Content_12 = {
    Text = "這什麼聲音！可惡，頭好疼……"
  },
  AvgDialog_18992_Content_13 = {
    Text = "你從未聽過這種語言，但不知為何你卻理解了其中的含義。\n無盡的絮語侵入大腦皮層，詭異的語調噩夢般迴響。"
  },
  AvgDialog_18992_Content_14 = {
    Text = "<Change>回歸初源的巢穴吧"
  },
  AvgDialog_18992_Content_15 = {
