  AvgDialog_18992_Content_52 = {
    Text = "不用你提醒，區區頭疼，根本不影響我的實力！"
  },
  AvgDialog_18992_Content_6 = {
    Text = "希洛垂著頭，任憑蘿坦肆意嘲諷，始終一動不動。"
  },
  AvgDialog_18992_Content_8 = {
    Text = "怎麼——"
  },
  AvgDialog_18992_Content_9 = {
    Text = "驟然間，四周湧起未名的黑綠色潮水，某種遠古的、令人毛骨悚然的尖嘯聲在腦海中迴蕩。"
