  AvgDialog_19009_Content_10 = {
    Text = "這樣聽上去更可疑了……"
  },
  AvgDialog_19009_Content_11 = {
    Text = "怎麼會呢，就像是愚蠢的野獸一定會被血的味道吸引，人類幼崽根本抵抗不了糖果的誘惑。"
  },
  AvgDialog_19009_Content_12 = {
    Text = "這比喻真是……\n等等，外面好像有動靜。"
  },
  AvgDialog_19009_Content_13 = {
    Text = "嗯？什麼動靜？"
  },
  AvgDialog_19009_Content_14 = {
    Text = "你也聽到了對吧，那就麻煩你去探查一下吧。"
  },
  AvgDialog_19009_Content_15 = {
    Text = "喂，別以為我不知道你是想把我支開——"
  },
  AvgDialog_19009_Content_16 = {
    Text = "%player%，你肯定不會和她一樣心狠的對吧？"
  },
  AvgDialog_19009_Content_17 = {
    Text = "這裡就交給我和拉蒙娜吧。"
  },
  AvgDialog_19009_Content_18 = {
    Text = "相信我們，我們對和孩子交流非常在行。"
  },
  AvgDialog_19009_Content_19 = {
    Text = "拉蒙娜輕輕歎了口氣。"
  },
  AvgDialog_19009_Content_2 = {
    Text = "店內一切如常，你們三人坐成一排，面對著小小的莉莉。\n這場景似乎有些像是審問……"
  },
  AvgDialog_19009_Content_20 = {
    Text = "哎呀，外面的響動越來越大了。"
  },
  AvgDialog_19009_Content_21 = {
    Text = "你還是出去看看吧，蘿坦，這些雜事交給我和拉蒙娜就好。"
  },
  AvgDialog_19009_Content_22 = {
    Text = "嘁，小氣鬼。"
  },
  AvgDialog_19009_Content_23 = {
    Text = "蘿坦轉身走出房間，莉莉的目光不安地跟隨著她的背影。"
  },
  AvgDialog_19009_Content_24 = {
    Text = "可怕的大姐姐走了。我們可以放鬆一點了，對吧，莉莉？"
  },
  AvgDialog_19009_Content_25 = {
    Text = "女孩眨眨眼，像是確實放鬆下來了，又像是根本不明白現在的情況。"
  },
  AvgDialog_19009_Content_26 = {
    Text = "你知道麗莎的下落，對嗎？"
  },
  AvgDialog_19009_Content_27 = {
    Text = "莉莉點了點頭，又搖了搖頭。"
  },
  AvgDialog_19009_Content_28 = {
    Text = "那你能不能告訴我們呢？\n放心，這裡只有我和%player%，我們會為你保密，並且保護你的。"
  },
  AvgDialog_19009_Content_29 = {
    Text = "不行，因為……<Yellow:眼睛>一直在看著莉莉……"
  },
  AvgDialog_19009_Content_3 = {
    Text = "莉莉坐立難安，不斷抬頭瞟向窗外。"
  },
  AvgDialog_19009_Content_31 = {
    Text = "嗯，很多、很多眼睛，從<Yellow:其他維度>……"
  },
  AvgDialog_19009_Content_32 = {
    Text = "維度？莉莉理解維度是什麼意思嗎？"
  },
  AvgDialog_19009_Content_33 = {
    Text = "莉莉突然緊抿嘴唇，一言不發，不時慌張地望向窗外。"
  },
  AvgDialog_19009_Content_34 = {
    Text = "%player%，外面好像有動靜。"
  },
  AvgDialog_19009_Content_35 = {
    Text = "……你連我也要支走嗎？"
  },
  AvgDialog_19009_Content_38 = {
    Text = "外面真的有情況！"
  },
  AvgDialog_19009_Content_39 = {
    Text = "蘿坦！發生什麼了！"
  },
  AvgDialog_19009_Content_4 = {
    Text = "你剛想說些什麼打破壓抑的氛圍，蘿坦卻率先開口了。"
  },
  AvgDialog_19009_Content_40 = {
    Text = "不必跟來，我能搞定！"
  },
  AvgDialog_19009_Content_5 = {
    Text = "喂，你知道那個叫麗莎的孩子到哪去了吧？"
  },
  AvgDialog_19009_Content_6 = {
    Text = "別擔心，我們都是講理的人。在弄清楚情況前，不會像那個瘋大嬸一樣追著你打。"
  },
  AvgDialog_19009_Content_7 = {
    Text = "如果你乖乖說出那什麼麗莎的下落，那邊的漂亮姐姐會給你糖果獎勵噢？"
  },
  AvgDialog_19009_Content_8 = {
    Text = "蘿坦，你別嚇到她。"
  },
  AvgDialog_19009_Content_9 = {
    Text = "怎麼可能！我可是最溫柔的大姐姐了，對不對？"
  },
  AvgDialog_19013_Content_1 = {
    Text = "船到橋頭自然直"
  },
  AvgDialog_19013_Content_10 = {
    Text = "庫姆，不怕。"
  },
  AvgDialog_19013_Content_11 = {
    Text = "動物是很敏銳的，它們，還有它，一定是感受到了什麼。"
  },
  AvgDialog_19013_Content_12 = {
    Text = "在黑暗中，突兀地傳來嘔啞古怪的嘶叫聲。\n彷彿聲帶早已破裂，膿漿溢滿喉管。"
  },
  AvgDialog_19013_Content_13 = {
    Text = "……為……放棄……"
  },
  AvgDialog_19013_Content_14 = {
    Text = "莉莉抬手，指向了黑暗之中。\n你們隱約能感覺到，那正是怪聲傳來的方向。"
  },
  AvgDialog_19013_Content_2 = {
    Text = "福勒斯鋼橋橫跨午夜的江面，\n鋼管弦桿彷彿豎琴的鋼弦，在幽夜中由風變奏出挽歌。"
  },
  AvgDialog_19013_Content_3 = {
    Text = "夜色如深邃的暗影吞噬萬物，在這裡等待你們已久的庫姆嗚嗚地叫了兩聲，昏暗鐵橋的盡頭，燈火曖昧不明地搖曳。"
  },
  AvgDialog_19013_Content_4 = {
    Text = "……不對勁。"
  },
  AvgDialog_19013_Content_5 = {
    Text = "我也有同感，但又說不上來是哪裡不對。"
  },
  AvgDialog_19013_Content_6 = {
    Text = "這還不明顯嗎？\n你聽見動物的聲音了嗎？"
  },
  AvgDialog_19013_Content_7 = {
    Text = "沒有。\n萬籟俱寂，悄無聲息。"
  },
  AvgDialog_19013_Content_8 = {
    Text = "即使你們全部收聲合眼專注聆聽，也只能感受到沙沙的風聲，和過分遙遠的黑暗中傳來的、已無法判定是否是幻聽的嚎叫聲。"
  },
  AvgDialog_19013_Content_9 = {
    Text = "庫姆不安地打了個鼻息。"
  },
  AvgDialog_19014_Content_1 = {
    Text = "嘁，你們留手了吧？真沒勁。"
  },
  AvgDialog_19014_Content_10 = {
    Text = "通訊莫名地中斷了。"
  },
  AvgDialog_19014_Content_11 = {
    Text = "視線的盡頭，唐突出現一隻…或者說兩隻長耳的無毛貓。\n兩顆頭顱，被密密麻麻地縫作一處，共用著修長健美的軀體。"
  },
  AvgDialog_19014_Content_12 = {
    Text = "它靈巧地一躍，落在了一個一頭亂髮的男人的肩頭。"
  },
  AvgDialog_19014_Content_13 = {
    Text = "這真是命運的巧遇。\n今夜的月色相當美好，不是嗎？"
  },
  AvgDialog_19014_Content_14 = {
    Text = "彌薩格大學的各位。"
  },
  AvgDialog_19014_Content_2 = {
    Text = "融蝕調查不是搏擊運動，蘿坦。如果只有揮灑汗水才能治癒你的注意缺陷，我會建議你去找茜爾維婭進行心理疏導。"
  },
  AvgDialog_19014_Content_3 = {
    Text = "拉蒙娜，同步你剛才觀察的異常情況。"
  },
  AvgDialog_19014_Content_4 = {
    Text = "是。觀測到密境維度的黏液膿皰，直徑約20英寸，刺傷後流出泛綠光的黑色黏液並自然消散。"
  },
  AvgDialog_19014_Content_5 = {
    Text = "“刻耳柏洛斯”相關的記錄中，並無類似膿皰的資訊。"
  },
  AvgDialog_19014_Content_6 = {
    Text = "……是喚醒體。"
  },
  AvgDialog_19014_Content_7 = {
    Text = "守密人，拉蒙娜。\n聽著，你們一定要留心一個機械獨眼的男人。"
  },
  AvgDialog_19014_Content_8 = {
    Text = "你們接二連三與雕塑家協會正面對抗，他一定已經盯上了你們。"
  },
  AvgDialog_19014_Content_9 = {
    Text = "他或許不會和你們發生正面衝突，但……<Shake:@1@2……>"
  },
  AvgDialog_19015_Content_1 = {
    Text = "昨日重現"
  },
  AvgDialog_19015_Content_10 = {
    Text = "或許在知道真相後，她會因“自己是誰”而迷失……\n這種情況，在過去百千年間我見得多了。"
  },
  AvgDialog_19015_Content_11 = {
    Text = "在你的眼中，她算是什麼呢？"
  },
  AvgDialog_19015_Content_12 = {
    Text = "她是人類，是我的同學。"
  },
  AvgDialog_19015_Content_13 = {
    Text = "她和喚醒體一樣能夠協助我戰鬥。"
  },
  AvgDialog_19015_Content_14 = {
    Text = "她是什麼根本不重要。"
  },
  AvgDialog_19015_Content_15 = {
    Text = "你還沒說出口，熟悉的聲音就打斷了你們的對話。"
  },
  AvgDialog_19015_Content_16 = {
    Text = "我回來了，%player%，蘿坦。"
  },
  AvgDialog_19015_Content_17 = {
    Text = "……怎麼了？為什麼一臉古怪地看著我，我臉上有東西嗎？"
  },
  AvgDialog_19015_Content_18 = {
    Text = "不，沒什麼。"
  },
  AvgDialog_19015_Content_19 = {
    Text = "歡迎回來"
  },
  AvgDialog_19015_Content_2 = {
    Text = "爬行，爬行，無休止地爬行。\n失去支配力的雙足在地面蠕動，殘損的視網膜中只映現出模糊的世界。"
  },
  AvgDialog_19015_Content_21 = {
    Text = "我帶回來一個好消息，一個壞消息。"
  },
  AvgDialog_19015_Content_22 = {
    Text = "好消息是，校方同意了我們的策略，讓我們先護送莉莉回母親身邊。"
  },
  AvgDialog_19015_Content_23 = {
    Text = "壞消息是，威廉觀察到一些怪人在對精神療養院虎視眈眈。"
  },
  AvgDialog_19015_Content_24 = {
    Text = "如果我的感覺沒出現偏差……他們現在正潛伏在我們身邊。"
  },
  AvgDialog_19015_Content_3 = {
    Text = "這樣的爬行已經持續了接近20小時。\n失去精神力源泉的軀體逐漸朽壞，她的體力也瀕臨耗竭。"
  },
  AvgDialog_19015_Content_4 = {
    Text = "在永遠沉入黑暗之前，她必須找到那個人——"
  },
  AvgDialog_19015_Content_5 = {
    Text = "你自己要送她走，結果又心神不寧的。\n人類總是這樣，缺乏坦誠。"
  },
  AvgDialog_19015_Content_6 = {
    Text = "我不知道她會聽到怎樣的真相，又會如何做出選擇。"
  },
  AvgDialog_19015_Content_7 = {
    Text = "……我是看著她從蹣跚學步的幼兒之姿成長為如今的模樣的，她絕不是喚醒體，但……也不是人類。"
  },
  AvgDialog_19015_Content_8 = {
    Text = "尋常人類不可能表現出這樣的戰鬥能力。"
  },
  AvgDialog_19015_Content_9 = {
    Text = "德克斯特那幫人把她的身世藏得很好，甚至不惜為此封閉黑池。不僅是為了保護彌薩格，更是為了保護她。"
  },
  AvgDialog_19016_Content_10 = {
    Text = "旋即，她轉過身來，面向你們。"
  },
  AvgDialog_19016_Content_100 = {
    Text = "……只要下這個山坡……"
  },
  AvgDialog_19016_Content_102 = {
    Text = "腳下鬆軟的積雪突然塌陷，你眼前一黑，暈了過去。"
  },
  AvgDialog_19016_Content_11 = {
    Text = "這幾位就是您說的，莉莉的新朋友嗎？"
  },
  AvgDialog_19016_Content_12 = {
    Text = "弗朗西斯自言自語般點了點頭。"
  },
  AvgDialog_19016_Content_13 = {
    Text = "你們好，我是莉莉的母親，叫我弗朗西斯就好。"
  },
  AvgDialog_19016_Content_14 = {
    Text = "這位是我的助手，<Blue:寧菲亞>。"
  },
  AvgDialog_19016_Content_15 = {
    Text = "貴安。我是寧菲亞·波洛涅斯，請稱呼我寧菲亞吧。"
  },
  AvgDialog_19016_Content_16 = {
    Text = "發生的事情，我已經聽達芙黛爾說了。\n我是<Blue:精神療養院>的醫生，莉莉之前也和我住在療養院。"
  },
  AvgDialog_19016_Content_17 = {
    Text = "我不想讓莉莉在那樣的環境中生活太久，才將她送到鎮上暫住，沒想到她還是很難適應外界的生活。"
  },
  AvgDialog_19016_Content_18 = {
    Text = "很抱歉莉莉給你們添了這麼多麻煩。\n作為一個不稱職的母親，我深表歉意。"
  },
  AvgDialog_19016_Content_19 = {
    Text = "如果不是庫姆還在一副如臨大敵的模樣，她就像一個有點嚴厲、卻又有點親切的普通母親。"
  },
  AvgDialog_19016_Content_2 = {
    Text = "門外響起了輕輕的叩擊聲，在安靜的夜晚裡，有節奏的敲擊聲讓人莫名脊骨發冷。"
  },
  AvgDialog_19016_Content_20 = {
    Text = "不必這麼說，莉莉很乖巧的。"
  },
  AvgDialog_19016_Content_22 = {
    Text = "希望之後能有機會答謝二位。"
  },
  AvgDialog_19016_Content_23 = {
    Text = "聽你這話，這就要走了嗎？"
  },
  AvgDialog_19016_Content_24 = {
    Text = "你知道的，只靠寧菲亞，我無法在外停留過夜。"
  },
  AvgDialog_19016_Content_25 = {
    Text = "而且…逃避始終不是辦法，我得去和<Yellow:那個人>談談。"
  },
  AvgDialog_19016_Content_26 = {
    Text = "奧茲伍德院長，或許在這件事上，我能稍許為您分憂？"
  },
  AvgDialog_19016_Content_27 = {
    Text = "不行，寧菲亞，你沒必要摻和進我的這些事裡。\n我做的決定，必須由我來了結。"
  },
  AvgDialog_19016_Content_28 = {
    Text = "那我就更不推薦你把莉莉帶在身邊了，尤其是這幾個夜晚。"
  },
  AvgDialog_19016_Content_29 = {
    Text = "這兒有個兩全其美的提議：你去處理你的事，送莉莉回去的任務，就交給這幾位朋友，如何？"
  },
  AvgDialog_19016_Content_30 = {
    Text = "這不合適吧，莉莉已經給大家添太多麻煩了。"
  },
  AvgDialog_19016_Content_31 = {
    Text = "達芙黛爾向你們使了個眼色。\n看來，這便是你們的“答案”了。"
  },
  AvgDialog_19016_Content_32 = {
    Text = "我們都很樂意和莉莉相處。"
  },
  AvgDialog_19016_Content_33 = {
    Text = "既然如此……那麼就拜託你們了。"
  },
  AvgDialog_19016_Content_34 = {
    Text = "把莉莉送回家，送到拉伊精神療養院。"
  },
  AvgDialog_19016_Content_35 = {
    Text = "23：00，二層臥室"
  },
  AvgDialog_19016_Content_36 = {
    Text = "艾瑞卡，幫我查詢拉伊精神療養院相關的全部資料。"
  },
  AvgDialog_19016_Content_37 = {
    Text = "拉伊精神療養院，位於拉伊小鎮東南角林賽路，距今已有十二年歷史。其主要業務為精神疾病觀察及康復，因而也被稱為瘋人院。"
  },
  AvgDialog_19016_Content_38 = {
    Text = "現任負責人弗朗西斯·奧茲伍德——"
  },
  AvgDialog_19016_Content_39 = {
    Text = "跳過這些明面上的東西。有可查詢的病人資料嗎？以及他們的家屬資訊？"
  },
  AvgDialog_19016_Content_4 = {
    Text = "庫姆突然拱起身，如被包圍的野獸般擺出蓄勢待發的姿勢。"
  },
  AvgDialog_19016_Content_40 = {
    Text = "正在檢索，請稍候……\n涉及資訊量較大，預計檢索完成時間為明日早上8點整。"
  },
  AvgDialog_19016_Content_41 = {
    Text = "……好吧。多謝了，艾瑞卡。\n看來這就是今天能做的全部了。"
  },
  AvgDialog_19016_Content_42 = {
    Text = "我有一種預感，這次的事件，才剛剛開始……"
  },
  AvgDialog_19016_Content_43 = {
    Text = "躺在床上，困意不斷侵襲而來，一種朦朧的印象在你腦海中浮現。"
  },
  AvgDialog_19016_Content_44 = {
    Text = "或許，又要做那個<Yellow:夢>了……"
  },
  AvgDialog_19016_Content_45 = {
    Text = "歡迎來到<Blue:艾爾沃斯探險隊>。\n我是隊伍的負責人，你可以叫我<Blue:伯特蘭>。"
  },
  AvgDialog_19016_Content_46 = {
    Text = "我看過你的申請報告。實話說，我們已經進行了為期三個月的籌備工作，本不該臨時吸納非專業人員。"
  },
  AvgDialog_19016_Content_47 = {
    Text = "但此行兇險，醫護人員不可或缺。所以，即使你只經過了短期培訓，我們仍歡迎你加入隊伍，與我們一同征服<Blue:艾爾沃斯>。"
  },
  AvgDialog_19016_Content_48 = {
    Text = "過程中有任何不適，請及時向我提出。為生命安全起見，我們會發送求助訊號，併為你留下足夠的物資等待救援。"
  },
  AvgDialog_19016_Content_49 = {
    Text = "請注意，這也意味著你可能不能與我們共同完成探險。\n隊伍會銘記你的功勞，但在最終的首次勘探者記錄中不會有你的名字。"
  },
  AvgDialog_19016_Content_5 = {
    Text = "深夜打擾了。"
  },
  AvgDialog_19016_Content_50 = {
    Text = "伯特蘭，別總是那麼冷淡嘛。人家願意辛辛苦苦和我們一起去那樣的冰天雪地，已經很不錯了，不是嗎？"
  },
  AvgDialog_19016_Content_51 = {
    Text = "……同時，在極端氣候下，喪生的機率始終不會為零。\n確認的話，你就是勘探隊的一員了。"
  },
  AvgDialog_19016_Content_52 = {
    Text = "嗯，這些我都知道"
  },
  AvgDialog_19016_Content_53 = {
    Text = "那是你的房間。訓練期間，每天早晨6點需要起床晨練，別遲到。"
  },
  AvgDialog_19016_Content_55 = {
    Text = "啊，好久沒有這麼晴朗的天氣了！你們看，都能看清遠方的山巔！"
  },
  AvgDialog_19016_Content_56 = {
    Text = "氣候比預計要糟糕，前幾天的進度不太理想。\n我們必須把握住難得的晴天，以最快的速度前進。"
  },
  AvgDialog_19016_Content_57 = {
    Text = "還有你，你可是醫生，別自己倒下了，反而要別人照顧。"
  },
  AvgDialog_19016_Content_58 = {
    Text = "伯特蘭，我說你，天氣晴了是好消息，能不能照顧一下大家的情緒？"
  },
  AvgDialog_19016_Content_59 = {
    Text = "……我跟你這種尋求自我挑戰的貴族小姐不一樣，軍人有軍人的義務。\n在抵達那座最高峰之前，我不會回頭。"
  },
  AvgDialog_19016_Content_6 = {
    Text = "庫姆急劇轉身，撓了撓地面，背脊緊繃，發出威脅的低吼。"
  },
  AvgDialog_19016_Content_60 = {
    Text = "塞西莉，我沒事的。\n伯特蘭上校說得對，我們抓緊時間吧。"
  },
  AvgDialog_19016_Content_62 = {
    Text = "你們放棄了一部分輜重，驅使著雪橇犬和矮種馬，以最快的效率前進。"
  },
  AvgDialog_19016_Content_63 = {
    Text = "內心的不安感湧動著，你從層層疊疊的衣服內側掏出懷錶，祈願著。"
  },
  AvgDialog_19016_Content_64 = {
    Text = "你又在看你的懷錶了。它很特別嗎？"
  },
  AvgDialog_19016_Content_65 = {
    Text = "嗯，是我從一個奇特的古董店裡買到的。\n我把我女兒的照片和胎毛放在裡面了，看到的時候就會想起她。"
  },
  AvgDialog_19016_Content_66 = {
