  AvgDialog_19033_Content_30 = {
    Text = "什麼——"
  },
  AvgDialog_19033_Content_32 = {
    Text = "伴隨著鼓動耳膜的劇烈喘息，金黃的豎瞳撕裂了蘿坦背後的空間。\n無神的瞳孔掃視大地，最終聚焦在你們的身上。"
  },
  AvgDialog_19033_Content_33 = {
    Text = "你的內心不由自主地震顫，那目光彷彿從浩瀚星海邊緣而來，於亙古之時就已在凝視——"
  },
  AvgDialog_19033_Content_34 = {
    Text = "別慌，小心應敵！"
  },
  AvgDialog_19033_Content_4 = {
    Text = "話說回來，不知各位有沒有見過一位小姑娘？\n大約這麼高……"
  },
  AvgDialog_19033_Content_5 = {
    Text = "視你們若無物，男人悠然自得地比劃著。"
  },
  AvgDialog_19033_Content_6 = {
    Text = "穿白裙子，身上掛著個小牌子……"
  },
  AvgDialog_19033_Content_7 = {
    Text = "同一時間\n拉伊樹叢"
  },
  AvgDialog_19033_Content_8 = {
    Text = "在哪兒……"
  },
  AvgDialog_19034_Content_1 = {
