  },
  AvgDialog_19081_Content_56 = {
    Text = "可是……我做不到……\n我不想死，可是……如果他們在靠岸前就犧牲了……"
  },
  AvgDialog_19081_Content_57 = {
    Text = "<SmallShake:我…不想……那樣的事……>"
  },
  AvgDialog_19081_Content_59 = {
    Text = "我的意思是……我不能永遠呆在密境裡，如果想要真正脫身，我就需要那兩個學生的幫助。"
  },
  AvgDialog_19081_Content_6 = {
    Text = "墨菲咬著嘴巴，焦急地來回踱步。一會兒踢一腳貨箱，一會兒抓兩下固定貨箱的固定繩。"
  },
  AvgDialog_19081_Content_60 = {
    Text = "我不能直接找上學校，告訴校長，他們的學生為了幫我而犧牲。\n我需要他們活著，我要堂堂正正成為他們的客人。"
  },
  AvgDialog_19081_Content_61 = {
    Text = "余不會分神保護你。"
  },
  AvgDialog_19081_Content_62 = {
    Text = "不用你保護，蹈海者的弱點在哪我清楚得很，我能照顧好自己。"
  },
  AvgDialog_19081_Content_63 = {
    Text = "好，若你執意如此。"
  },
  AvgDialog_19081_Content_64 = {
    Text = "你這是什麼眼神？"
  },
  AvgDialog_19081_Content_65 = {
    Text = "余原本以為，你不值得他們付出如此犧牲。\n如今看來，余先入為主了。"
  },
  AvgDialog_19081_Content_66 = {
    Text = "你在說什麼謎語？快走快走！"
  },
  AvgDialog_19081_Content_67 = {
    Text = "這孩子……罷了，如果這是她的選擇的話。"
  },
  AvgDialog_19081_Content_68 = {
    Text = "希萊斯特，維持全速前進。"
  },
  AvgDialog_19081_Content_7 = {
    Text = "他們不會出什麼事吧……"
  },
  AvgDialog_19081_Content_8 = {
    Text = "她沒法靜下來祈禱，沒法安心坐下。"
  },
  AvgDialog_19082_Content_1 = {
    Text = "你還在等什麼？等我請你嗎？"
  },
  AvgDialog_19082_Content_11 = {
    Text = "不行！你是普通人，我有保護你的義務——<BigShake:啊！>"
  },
  AvgDialog_19082_Content_12 = {
    Text = "少女假裝沒聽見你的嘮叨，她仗著自己身材嬌小，靈活地繞到了你身後。"
  },
  AvgDialog_19082_Content_13 = {
    Text = "——然後，狠狠一腳將你踹進了黝黑的門洞裡。"
  },
  AvgDialog_19082_Content_15 = {
    Text = "少女緊隨其後跳了進來，她大力合上鐵門，熟稔地轉動絞盤，鎖死門鎖。"
  },
  AvgDialog_19082_Content_16 = {
    Text = "呼——應該暫時安全了。"
  },
  AvgDialog_19082_Content_17 = {
    Text = "少女按下了開關，老舊的電燈閃爍幾下後，光線才向四周鋪開，驅散了黑暗。"
  },
  AvgDialog_19082_Content_18 = {
    Text = "貨艙寬敞而空曠，零星的貨物不成規模地被固定在角落。揚塵在昏暗的燈光下飛舞，一派久無人跡的衰敗之相。"
  },
  AvgDialog_19082_Content_19 = {
    Text = "頭頂持續傳來敲擊的悶響，一聲聲震盪著你的顱腔。"
  },
  AvgDialog_19082_Content_2 = {
    Text = "暗門？！"
  },
  AvgDialog_19082_Content_20 = {
    Text = "我的頭……"
  },
  AvgDialog_19082_Content_21 = {
    Text = "太陽穴隨著敲擊的頻率鼓動，劇烈的疼痛撕扯著你的左右半腦，胃酸再次上湧到了咽喉。"
  },
  AvgDialog_19082_Content_22 = {
    Text = "他們一時半會兒應該進不來……誒？！你怎麼了？！"
  },
  AvgDialog_19082_Content_23 = {
    Text = "別、別嚇我啊？別死啊！"
  },
  AvgDialog_19082_Content_24 = {
    Text = "呼，終於甩掉他們了。"
  },
  AvgDialog_19082_Content_25 = {
    Text = "這扇門很牢固，到這裡應該暫時安全了……<BigShake:可惡！>"
  },
  AvgDialog_19082_Content_26 = {
    Text = "可惡可惡可惡！你這傢伙闖大禍了！把本小姐的計劃全打亂了！得想想辦法……"
  },
  AvgDialog_19082_Content_27 = {
    Text = "對了，你最好牢牢記住本小姐的名字——"
  },
  AvgDialog_19082_Content_28 = {
    Text = "少女焦急的面孔和腦中浮現的碎片逐漸重合，兩個相似卻不同的場景也相融成了同一個畫幅。"
  },
  AvgDialog_19082_Content_3 = {
    Text = "什麼暗門？都這種時候了還和本小姐開玩笑？！你瘋了嗎？！"
  },
  AvgDialog_19082_Content_30 = {
    Text = "你、你還好吧？"
  },
  AvgDialog_19082_Content_31 = {
    Text = "摔得有點疼。"
  },
  AvgDialog_19082_Content_32 = {
    Text = "不會吧，哪裡摔傷了嗎？"
  },
  AvgDialog_19082_Content_33 = {
    Text = "借著黯淡的光源，她踮著腳查看起了你的狀況。"
  },
  AvgDialog_19082_Content_35 = {
    Text = "怎麼了？"
  },
  AvgDialog_19082_Content_36 = {
    Text = "<SmallShake:沒、沒什麼……>"
  },
  AvgDialog_19082_Content_37 = {
    Text = "<Small:好像這批貨物裡有能用得上的東西……>"
  },
  AvgDialog_19082_Content_38 = {
    Text = "墨菲模糊不清地念叨著，動作僵硬地挪到貨箱堆積處，翻找起了什麼。"
  },
  AvgDialog_19082_Content_4 = {
    Text = "又不是沒進過船艙，別墨跡了，準備好！"
  },
  AvgDialog_19082_Content_40 = {
    Text = "墨菲拆箱子的動作非常粗暴，填充貨箱的紙條乾草散落一地，這個角落很快就變得一片狼藉。"
  },
  AvgDialog_19082_Content_41 = {
    Text = "不對……這箱是破首飾。"
  },
  AvgDialog_19082_Content_42 = {
    Text = "你看了一眼，貨箱裡是一套宮廷風格的鉑金首飾，鑲嵌的珍珠和鑽石看起來價值連城。"
  },
  AvgDialog_19082_Content_43 = {
    Text = "……什麼嘛，全是儀式用品。"
  },
  AvgDialog_19082_Content_44 = {
    Text = "第二個箱子裡塞滿了形形色色的雜物和草藥，石缽、鼠尾草、末藥……沒有煉金術常識的人，恐怕只會以為這是哪個藥商的貨物。"
  },
  AvgDialog_19082_Content_45 = {
    Text = "找到了！快快，你蹲下來。"
  },
  AvgDialog_19082_Content_46 = {
    Text = "粘稠的膏狀物不由分說地糊在了你的後腦勺，冰涼中帶著一絲辛辣，一定程度上緩解了疼痛。"
  },
  AvgDialog_19082_Content_47 = {
    Text = "這是……"
  },
  AvgDialog_19082_Content_48 = {
    Text = "誒！你別亂摸。"
  },
  AvgDialog_19082_Content_49 = {
    Text = "墨菲遞給你一罐藥膏。"
  },
  AvgDialog_19082_Content_5 = {
    Text = "下面安全嗎？"
  },
  AvgDialog_19082_Content_50 = {
    Text = "標籤上沒有寫配方或藥名，只繪製了一個怪異的圖案，儼然是一瓶自製藥。"
  },
  AvgDialog_19082_Content_51 = {
    Text = "……是既視感嗎？藥膏標籤上的圖案，好像在哪裡見到過。"
  },
  AvgDialog_19082_Content_52 = {
    Text = "喏，就是這個，放心吧毒不死你。"
  },
  AvgDialog_19082_Content_53 = {
    Text = "從小到大只要受了外傷，本小姐都塗的這個藥膏。\n怎麼樣，是不是一塗上就不疼了？"
  },
  AvgDialog_19082_Content_54 = {
    Text = "她對你滾下樓梯磕到頭這件事感到非常緊張，看你的眼神充滿了心虛。"
  },
  AvgDialog_19082_Content_56 = {
    Text = "看吧，我就說了很有效的——"
  },
  AvgDialog_19082_Content_57 = {
    Text = "得到肯定的回答，墨菲終於放鬆了下來，露出了笑容。"
  },
  AvgDialog_19082_Content_58 = {
    Text = "後腦舒適了一些，但太陽穴仍隱隱作痛。\n看著她放鬆的樣子，內心有一個聲音這樣告訴你——"
  },
  AvgDialog_19082_Content_59 = {
    Text = "有些事，可以在與<Blue:你的搭檔>會合後再去深究。"
  },
  AvgDialog_19082_Content_6 = {
    Text = "我哪裡知道。"
  },
  AvgDialog_19082_Content_7 = {
    Text = "總比被這些瘋子抓去喂魚來得強！別墨跡了，做好準備。"
  },
  AvgDialog_19082_Content_8 = {
    Text = "敵人的速度很快，你吃力地拖延著敵人的攻擊，掩護少女拉起了鐵門。"
  },
  AvgDialog_19082_Content_9 = {
    Text = "門洞之下，鐵質階梯延伸向深不可測的暗處。"
  },
  AvgDialog_19083_Content_1 = {
    Text = "扭曲的現實"
  },
  AvgDialog_19083_Content_10 = {
    Text = "借著光，她看見「母親」光滑的表皮之上，大大小小分佈著數不盡的黑色傷口。"
  },
  AvgDialog_19083_Content_11 = {
    Text = "「對不起……」"
  },
  AvgDialog_19083_Content_12 = {
    Text = "黑色黏液翻湧，攪碎了灘底的平靜。"
  },
  AvgDialog_19083_Content_13 = {
    Text = "「母親」發出了一聲尖利的哀鳴，觸肢一陣翻動，將什麼東西送入了雛鳥的胸腔。"
  },
  AvgDialog_19083_Content_14 = {
    Text = "濕滑冰冷的軟體觸肢纏繞著她，黑色的池水不再堵塞她的口鼻，反而如羊水一般，托舉起了她的生命。"
  },
  AvgDialog_19083_Content_15 = {
    Text = "<Change>「對不起……」\n「我還……不想死……」"
  },
  AvgDialog_19083_Content_16 = {
    Text = "水面維持著長久的平靜，就連極地呼嘯的風，都無法讓粘稠的池水泛起漣漪。"
  },
  AvgDialog_19083_Content_17 = {
    Text = "彌利亞姆大人，聖女會不會已經……"
  },
  AvgDialog_19083_Content_18 = {
    Text = "她於上一個星辰正位時刻出生，是“看得見”的孩子。"
  },
  AvgDialog_19083_Content_19 = {
    Text = "世界上，沒有人比她更值得得到神之血脈的承認。"
  },
  AvgDialog_19083_Content_2 = {
    Text = "被折斷翅膀的雛鳥，落入了黑色水潭。"
  },
  AvgDialog_19083_Content_20 = {
    Text = "伴隨著喃喃低語，彷彿地心的能量即將噴湧而出一般，水面陡然沸騰了起來。"
  },
  AvgDialog_19083_Content_21 = {
    Text = "厚重黏稠的黑水溢出池畔，沒過眾人腳背，流淌至女人赤裸的足邊。"
  },
  AvgDialog_19083_Content_22 = {
    Text = "穿過低聲驚呼的年輕教眾，她沉默著走上黑液鋪就的道路，將雙手深深浸入了池水中——"
  },
  AvgDialog_19083_Content_23 = {Text = "——嘩"},
  AvgDialog_19083_Content_24 = {
    Text = "少女攀附於她的雙手，從池水中躍出。\n黑液順著臉部輪廓流下，像極了兩道駭人的淚痕。"
  },
  AvgDialog_19083_Content_25 = {
    Text = "謔，還不錯嘛。看樣子，<Blue:神胎>已經承認了新的<Blue:母親>。"
  },
  AvgDialog_19083_Content_26 = {
    Text = "戈利亞冷不防地出聲，語氣嘲弄，在場卻已無人在意他的譏諷。"
  },
  AvgDialog_19083_Content_27 = {
    Text = "聖女……成功了？我們成功了！"
  },
  AvgDialog_19083_Content_28 = {
    Text = "彌利亞姆雙目輕闔，鬆開與少女緊握的雙手，轉身面向陷入狂熱的教眾。"
  },
  AvgDialog_19083_Content_29 = {
    Text = "她雙臂高舉，黑液順著肌膚紋理滑落，頭紗瞬間被染成濃重的黑色。"
  },
  AvgDialog_19083_Content_3 = {
    Text = "主祭的絮絮禱言飄忽而堅實，狂熱的言辭穿透黑色黏液，化為利刃剖開了雛鳥的胸腔。"
  },
  AvgDialog_19083_Content_30 = {
    Text = "禱言此起彼伏，最終在寒冷的洞窟中調律重合，狂熱，扭曲，震耳欲聾。"
  },
  AvgDialog_19083_Content_32 = {
    Text = "祂將從@1中復甦，使@2降臨！"
  },
  AvgDialog_19083_Content_33 = {
    Text = "祂將從@1中復甦，使@2降臨！"
  },
  AvgDialog_19083_Content_34 = {
    Text = "三個月後"
  },
  AvgDialog_19083_Content_35 = {
    Text = "你可讓那女人越來越頭疼了。前幾個月不是還很乖嗎？怎麼，現在不願意再聽媽媽的話了？"
  },
  AvgDialog_19083_Content_36 = {
    Text = "少女瞥了一眼戈利亞，狠狠將刻刀插進木頭上，連工具帶材料扔到了一邊。"
  },
  AvgDialog_19083_Content_37 = {
    Text = "媽、媽媽？"
  },
  AvgDialog_19083_Content_38 = {
    Text = "你……從何處習得這種說法？"
  },
  AvgDialog_19083_Content_39 = {
    Text = "字典！你看，“照顧幼兒，且有感情連接的女性成人”。"
  },
  AvgDialog_19083_Content_4 = {
    Text = "鮮紅色的液體從胸口上浮，在歸於平靜的黑色水面上妖冶綻放——"
  },
  AvgDialog_19083_Content_40 = {
    Text = "不，我不會是你的媽媽。"
  },
  AvgDialog_19083_Content_41 = {
    Text = "你是教團聖女，是尊貴的命定之人……若你願意，可以直呼我的名字。"
  },
  AvgDialog_19083_Content_42 = {
    Text = "唔……彌利……亞姆？"
  },
  AvgDialog_19083_Content_43 = {
    Text = "是的，聖女。"
  },
  AvgDialog_19083_Content_44 = {
    Text = "我是您忠實的僕人。"
  },
  AvgDialog_19083_Content_45 = {
    Text = "……她不是我媽媽，從來都不是。"
  },
  AvgDialog_19083_Content_46 = {
    Text = "只有提燈教會上面的傢伙知道我的來歷，我也沒有媽媽，我只是他們送給彌利亞姆的禮物。"
  },
  AvgDialog_19083_Content_47 = {
    Text = "哦？她居然連這事都告訴你了？"
  },
  AvgDialog_19083_Content_48 = {
    Text = "對一個死期已經定下的囚犯來說，知道多少秘密都無所謂了，反正所有東西都會被我帶進墳墓裡。"
  },
  AvgDialog_19083_Content_49 = {
    Text = "這也是那女人對你的補償吧。要知道，把神胎移植到你體內的那天，我們的主祭大人可整夜都沒休息。"
  },
  AvgDialog_19083_Content_5 = {
    Text = "她卻在不斷下沉，帶著血跡的根，沉入最深處，沉入一個柔軟而陰冷的懷抱。"
  },
  AvgDialog_19083_Content_50 = {
    Text = "愧疚感可把她折磨得不輕。"
  },
  AvgDialog_19083_Content_51 = {
    Text = "愧疚感？你在開玩笑嗎？她不會有這種情感。"
  },
  AvgDialog_19083_Content_52 = {
    Text = "真絕情啊，小公主。\n女孩子太冷酷，可是會惹媽媽傷心的哦。"
  },
  AvgDialog_19083_Content_53 = {
    Text = "你煩不煩！都說了她不是我媽媽了！"
  },
  AvgDialog_19083_Content_54 = {
    Text = "這可不一定，你想聽故事嗎。"
  },
  AvgDialog_19083_Content_55 = {
    Text = "<BigShake:不想聽，我也不想見到你！>\n如果是特意來譏諷我的，你可以離開了！"
  },
  AvgDialog_19083_Content_56 = {
    Text = "不，你想聽。"
  },
  AvgDialog_19083_Content_57 = {
    Text = "戈利亞的語氣陡然深沉，帶著久經戰場的威儀，墨菲體內的兩顆心臟都險些因此停跳。"
  },
  AvgDialog_19083_Content_58 = {
    Text = "她突然意識到——巨人從來就不是她可以隨意把弄的玩具。\n自己只是仗著身分得寸進尺，而對方也樂於看笑話罷了。"
  },
  AvgDialog_19083_Content_59 = {
    Text = "是……是的，請說吧。"
  },
  AvgDialog_19083_Content_60 = {
    Text = "有一個神秘教會，為了血統的絕對純淨，一切婚嫁都由教首指定。\n那些和外面的人成婚生子的傢伙，最後都會遭到清算。"
  },
  AvgDialog_19083_Content_61 = {
    Text = "在上一次清算中，執行者帶回了一名嬰兒——能夠看見<Yellow:精神存在>的女嬰。"
  },
  AvgDialog_19083_Content_62 = {
    Text = "女嬰……"
  },
  AvgDialog_19083_Content_63 = {
    Text = "她在母親身體下的暗格待了太久，被教徒找到時，她差點被<Red:親生母親的血>嗆死。"
  },
  AvgDialog_19083_Content_64 = {
    Text = "那個碌碌無為的普通女人，這輩子最大的成就，就是生下了一個素質優秀的女兒，並試圖不讓她被教會帶走。"
  },
  AvgDialog_19083_Content_65 = {
    Text = "——多麼美妙的母女情誼啊，我都快要為之落淚了。"
  },
  AvgDialog_19083_Content_66 = {
    Text = "戈利亞……你……"
  },
  AvgDialog_19083_Content_67 = {
    Text = "為什麼……為什麼要告訴我這些？"
  },
  AvgDialog_19083_Content_68 = {
    Text = "鬱鬱寡歡可不是什麼好事，要知道，<Blue:神>的發育可是取決於宿主狀態的。"
  },
  AvgDialog_19083_Content_69 = {
    Text = "做點什麼你喜歡的事吧，搞破壞，對蹈海者抽鞭子，折騰你的女僕……隨便什麼都行。"
  },
  AvgDialog_19083_Content_70 = {
    Text = "戈利亞單方面中止了這場對話，毫無溫情可言地拍了拍她的發頂。"
  },
  AvgDialog_19083_Content_71 = {
    Text = "離開時，他看了一眼被墨菲扔到牆角的木雕。少女的手藝非常差，那木質底座上端坐著的形狀肥大而詭異，讓人只看一眼就心生厭煩。"
  },
  AvgDialog_19083_Content_73 = {
    Text = "戈利亞離開後，空間變得一片寂靜，牢籠中那些待宰的祭品也沒有發出絲毫聲音。"
  },
  AvgDialog_19083_Content_74 = {
    Text = "墨菲在篝火旁坐了很久，直到光芒漸弱，篝火將熄，她才如夢初醒般拍了拍自己的臉頰。"
  },
  AvgDialog_19083_Content_75 = {
    Text = "她對著身邊一個牢籠狠狠踢了一腳，嚇得蜷縮在籠子角落的憔悴女人瑟縮了一下。"
  },
  AvgDialog_19083_Content_76 = {
    Text = "喂，你剛剛都聽到了吧。"
  },
  AvgDialog_19083_Content_78 = {
    Text = "我不是白白幫你的。我要你逃走後，想辦法回來把我也帶走。"
  },
  AvgDialog_19083_Content_79 = {
    Text = "我恐怕沒有那麼大的能力，我只是一個普通的科學家……"
  },
  AvgDialog_19083_Content_8 = {
    Text = "她看到了。\n她向上看去，「母親」垂下三對眼柄，同她對視。"
  },
  AvgDialog_19083_Content_80 = {
    Text = "所以說讓你想辦法啊！科學家的大腦，總不會一個辦法都想不出來吧！"
  },
  AvgDialog_19083_Content_81 = {
    Text = "看著少女強忍著淚水的臉龐，女人回想起記憶中面容已經模糊的女兒，終究動了惻隱之心。"
  },
  AvgDialog_19083_Content_82 = {
    Text = "你別太難過。"
  },
  AvgDialog_19083_Content_83 = {
    Text = "以前遇到研究瓶頸時，我常徹夜睡不著，這時就會偷偷去我女兒的房間，坐在床邊看著她。"
  },
  AvgDialog_19083_Content_84 = {
    Text = "她那麼小，那麼乖……一想到我所做的一切都是為了給她更美好的未來，所有的疲累就都算不上什麼了。"
  },
  AvgDialog_19083_Content_85 = {
    Text = "我也曾是一個母親，我知道……你的親生母親，一定是期待著你的出生的，這個世界上，肯定是有人愛著你的。"
  },
  AvgDialog_19083_Content_87 = {
    Text = "你說夠沒有？少管本小姐的閒事，先保住自己的小命吧！"
  },
  AvgDialog_19083_Content_88 = {
    Text = "「對不起……」\n「我……不想死……」"
  },
  AvgDialog_19083_Content_89 = {
    Text = "我也不想……就這麼結束……"
  },
  AvgDialog_19083_Content_9 = {
    Text = "那是個深紅色的龐然巨物，被血液沾染的地方呈現出了透明的白。「母親」發出微弱螢光，暫且照亮了一方小小天地。"
  },
  AvgDialog_19084_Content_1 = {
    Text = "你們讓司機離開了。"
  },
  AvgDialog_19084_Content_10 = {
    Text = "從最開始它們的襲擊就是帶有目的性的，為了把我們逼到這裡——<Blue:第三碼頭2號泊位>。"
  },
  AvgDialog_19084_Content_11 = {
    Text = "可這裡看起來也沒什麼特別的……"
  },
  AvgDialog_19084_Content_12 = {
    Text = "是的，這個2號泊位沒有任何特別之處。"
  },
  AvgDialog_19084_Content_13 = {
    Text = "真正有問題的，是停在這裡的<Blue:船>。"
  },
  AvgDialog_19084_Content_15 = {
    Text = "拉蒙娜的話語掀起了一陣烈風，瞬間打散了盤踞腦海的濃霧。"
  },
  AvgDialog_19084_Content_17 = {
    Text = "一艘巨輪悄無聲息出現在你們身後，遮天蔽日地擋住了月光，將所有人都籠罩於黑暗中。"
  },
  AvgDialog_19084_Content_18 = {
    Text = "這艘船剛剛在這裡嗎？"
  },
  AvgDialog_19084_Content_19 = {
    Text = "恐怕一直都在，只是出於某些未知的理由，我們一直忽視了它。"
  },
  AvgDialog_19084_Content_2 = {
    Text = "敵人數量太多，退路也被它們圍堵住了。"
  },
  AvgDialog_19084_Content_20 = {
    Text = "外部船殼銹蝕褪色得厲害，已經無法看清巨輪原本的塗裝，白漆刷就的船名也變得難以辨別。"
  },
  AvgDialog_19084_Content_21 = {
    Text = "索納……尼爾？"
  },
  AvgDialog_19084_Content_22 = {
    Text = "<Blue:索納尼爾號>。\n艾瑞卡，彌薩格檔案中有記錄嗎？"
  },
  AvgDialog_19084_Content_23 = {
    Text = "索納尼爾號，曾隸屬<Blue:黑星航運公司>，作為客輪執行跨洋航運任務。公司破產後，索納尼爾號被私人匿名收購，變更航運登記並改造為貨輪。"
  },
  AvgDialog_19084_Content_24 = {
    Text = "威廉前輩！你知道這艘船嗎？"
  },
  AvgDialog_19084_Content_25 = {
    Text = "洪積288年，索納尼爾號在一場風暴中沉沒，數年後，北海沿岸開始陸續出現<Blue:“幽靈船”>目擊記錄。"
  },
  AvgDialog_19084_Content_26 = {
    Text = "曾有彌薩格調查員登上過索納尼爾號，但沒有帶回任何可用情報。"
  },
  AvgDialog_19084_Content_27 = {
    Text = "沒有帶回可用情報……"
  },
  AvgDialog_19084_Content_28 = {
    Text = "但這意味著，那位調查員平安返校了，對嗎？"
  },
  AvgDialog_19084_Content_29 = {
    Text = "是的，儘管喪失了部分記憶，但登船沒有對他的身體帶來其他異常。\n短暫修養後，他就再次回到了調查的最前線。"
  },
  AvgDialog_19084_Content_3 = {
    Text = "被月光照亮的海面仍醞釀著漣漪，在光線無法透入的深海，不知道還藏著多少敵人。"
  },
  AvgDialog_19084_Content_30 = {
    Text = "能讓那位前輩接入通訊嗎？"
  },
  AvgDialog_19084_Content_31 = {
    Text = "很可惜，早在你加入彌薩格之前，他在一次任務中犧牲了。"
  },
  AvgDialog_19084_Content_33 = {
    Text = "拉蒙娜，你不會是想要……"
  },
  AvgDialog_19084_Content_34 = {
    Text = "是的，我不認為它們會讓我們等到救援。"
  },
  AvgDialog_19084_Content_35 = {
    Text = "包圍圈在逐漸縮小，敵人的武器已經抵在了腳邊。"
  },
  AvgDialog_19084_Content_36 = {
    Text = "我們現在登船。"
  },
  AvgDialog_19084_Content_5 = {
    Text = "將包圍圈縮到最小後，魚人怪物沒有繼續進攻，而是與你們僵持在了某個泊位前，口中不斷吐出怪異難辨的絮語。"
  },
  AvgDialog_19084_Content_6 = {
    Text = "攻擊停下了？"
  },
  AvgDialog_19084_Content_8 = {
    Text = "拉蒙娜，怎麼了？"
  },
  AvgDialog_19084_Content_9 = {
    Text = "不管是利用數量把我們往北側趕，還是最後封鎖了出口，敵人始終給我們留了一條去路。"
  },
  AvgDialog_19085_Content_1 = {
    Text = "終於結束了……"
  },
  AvgDialog_19085_Content_10 = {
    Text = "蹈海者的魚類下顎張大到了極致，連接上下頜的肉膜組織被拉伸到半透明。"
  },
  AvgDialog_19085_Content_11 = {
    Text = "被恐懼、希望與信仰驅使，迸發出了難以想像的生命力，它猛地撞開了你，尖嘯著向動力室外衝去。"
  },
  AvgDialog_19085_Content_2 = {
    Text = "墨菲踢了一腳失去意識的蹈海者，類魚的身體軟綿綿地滾遠了一些。"
  },
  AvgDialog_19085_Content_3 = {
    Text = "這回他們應該都沒法繼續戰鬥了……只是一些可憐蟲，別管他們了。"
  },
  AvgDialog_19085_Content_4 = {
    Text = "趕緊離開這裡吧。"
  },
  AvgDialog_19085_Content_5 = {
    Text = "咕……咕嗚……"
  },
  AvgDialog_19085_Content_6 = {
    Text = "癱倒一片的蹈海者中，有一人用折斷的武器支撐身體，顫顫巍巍爬了起來。"
  },
  AvgDialog_19085_Content_7 = {
    Text = "為什麼……為什麼……從@4大人身邊……為什麼？"
  },
  AvgDialog_19085_Content_8 = {
    Text = "神母，神母……咕嗚，咕嗚……！"
  },
  AvgDialog_19086_Content_1 = {
    Text = "灰藍的手從廢墟下衝出，蹼狀手掌抓住了墨菲的靴子。"
  },
  AvgDialog_19086_Content_2 = {
    Text = "咕、咕嗚嗚……"
  },
  AvgDialog_19086_Content_3 = {
    Text = "這傢伙居然還活著！？明明已經被壓在廢墟下面了。"
  },
  AvgDialog_19086_Content_5 = {
    Text = "……別靠近我！"
  },
  AvgDialog_19087_Content_1 = {
    Text = "腐敗的腥臭逐漸飄入鼻腔。"
  },
  AvgDialog_19087_Content_2 = {
    Text = "蹈海者們受到首領的召喚，從四面八方的艙室魚貫而出。"
  },
  AvgDialog_19088_Content_1 = {
    Text = "甲板另一頭傳來了沉重的腳步聲，一個粗獷男聲用聞所未聞的語言說了些什麼，圍堵的敵人便如潮水般退去，"
  },
  AvgDialog_19088_Content_10 = {
    Text = "拉蒙娜回頭，身後卻空無一人，兩人竟在這封閉的敵人包圍圈中失散。"
  },
  AvgDialog_19088_Content_12 = {
    Text = "不遠處堆積的貨箱後，傳來了異樣的窸窣聲。"
  },
  AvgDialog_19088_Content_13 = {
    Text = "別躲了，我知道你在那。現在可不是你耍寶的時候，“艾什少爺”。"
  },
  AvgDialog_19088_Content_14 = {
    Text = "拉蒙娜無奈地搖搖頭，她甩開劍尖的污血，一面將武器收回劍鞘，一面向堆積著貨箱的角落走去。"
  },
  AvgDialog_19088_Content_18 = {
    Text = "猛烈的攻擊擊穿了貨箱，也刺穿了敵人。\n觸肢上沾染的藍黑色污血混著散碎的木屑，散發出了難聞的腥臭味。"
  },
  AvgDialog_19088_Content_19 = {
    Text = "觸肢的主人猛地甩開了掛在其上的異形身體，貨箱隨之轟然崩解。\n——少年身姿顯現在拉蒙娜眼前。"
  },
  AvgDialog_19088_Content_2 = {
    Text = "大人！這是主祭的命令……"
  },
  AvgDialog_19088_Content_21 = {
    Text = "未經外勤行動組組長批准，且未被調查員連結前，喚醒體不被允許離開彌薩格地界，我以為你是清楚這一點的……"
  },
  AvgDialog_19088_Content_22 = {
    Text = "喚醒體圖魯，檔案編號-6291，代號<Blue:“沉睡之主”>。"
  },
  AvgDialog_19088_Content_23 = {
    Text = "余相信你也清楚，你們那些所謂的“戒律”，在余面前形同虛設。"
  },
  AvgDialog_19088_Content_24 = {
    Text = "另，別用那愚蠢的代號指代余。"
  },
  AvgDialog_19088_Content_25 = {Text = "圖魯。"},
  AvgDialog_19088_Content_26 = {
    Text = "我不是審查會那些死腦筋，喚醒體於我而言不是需要銬上腳鐐的野獸，現在也不是追究什麼“離家出走”的時候。"
  },
  AvgDialog_19088_Content_27 = {
    Text = "我擔心的是，你不在外勤任務的人員名單上，未經任何人連結。\n離開彌薩格的<Yellow:核>太久，你會步入失控。"
  },
  AvgDialog_19088_Content_28 = {
    Text = "無礙，余不會被所謂本能掌控。"
  },
  AvgDialog_19088_Content_29 = {
    Text = "喚醒體保持著少年的形態，一言一行卻充滿了上位者的威壓。\n僅是輕飄飄撇來一督，就足以讓人渾身汗毛直立。"
  },
  AvgDialog_19088_Content_31 = {
    Text = "拉蒙娜長籲一口氣，再次與他對視。"
  },
  AvgDialog_19088_Content_32 = {
    Text = "——我只想知道，你為什麼會出現在這裡？\n你常年保持沉睡，就連<Yellow:銀鑰授予儀式>上的突變也沒能讓你醒來。"
  },
  AvgDialog_19088_Content_33 = {
    Text = "可現在，你不惜冒著失去理智的風險出現在這裡……這艘船上發生的事，對你而言一定意義非凡。"
  },
  AvgDialog_19088_Content_34 = {
    Text = "這裡所發生的一切，皆因余而起。\n至於細節，與你無關。"
  },
  AvgDialog_19088_Content_35 = {
    Text = "是嗎？是那些追逐我們的魚人與我無關？還是走失的守密人與我無關？"
  },
  AvgDialog_19088_Content_37 = {
    Text = "當務之急是找到守密人，然後離開這艘船。\n所以，我不會繼續問下去。"
  },
  AvgDialog_19088_Content_38 = {
    Text = "你現在可以保持沉默，但你知道，我會找到答案的。"
  },
  AvgDialog_19088_Content_5 = {
    Text = "別走！你們究竟是什麼人？"
  },
  AvgDialog_19088_Content_6 = {
    Text = "喚醒體少年收起了武器，他轉身看了拉蒙娜一眼，不再戀戰，隨著自己的集群一同消失在了甲板上。"
  },
  AvgDialog_19088_Content_7 = {
    Text = "這究竟是…怎麼回事？"
  },
  AvgDialog_19088_Content_8 = {
    Text = "現在管不了那麼多了，它們的真正目標並不是我們……趁這個機會，趕緊找辦法下船。"
  },
  AvgDialog_19088_Content_9 = {
    Text = "我們小心為上，繞開那些魚人……守密人！"
  },
  AvgDialog_19089_Content_1 = {
    Text = "和墨菲同行的短短半小時，你已經吐了三次。"
  },
  AvgDialog_19089_Content_2 = {
    Text = "強烈的暈眩和反胃感總是一同湧上，反流的胃液將喉嚨灼燒得隱隱作痛。"
  },
  AvgDialog_19089_Content_3 = {
    Text = "頭好痛……"
  },
  AvgDialog_19089_Content_4 = {
    Text = "你不會要死了吧？\n我、我去找人幫你，你等我！"
  },
  AvgDialog_19089_Content_5 = {
    Text = "別，你別一個人行動，太危險了。"
  },
  AvgDialog_19089_Content_6 = {
    Text = "我感覺好多了，真的。\n走吧，我的搭檔還在等我。"
  },
  AvgDialog_19090_Content_1 = {
    Text = "墨菲看向回轉著奇異流光的天空。\n飛鳥在光幕下盤旋，光線扭曲而柔和，隔絕了外部可能的狂風暴雨。"
  },
  AvgDialog_19090_Content_10 = {
    Text = "沒錯。換句話說，於墨菲或於我們，<Blue:希萊斯特小姐>都是關鍵。\n而她現在……恐怕正處於蹈海者的領袖，彌利亞姆的控制之中。"
  },
  AvgDialog_19090_Content_11 = {
    Text = "可惡……那個女人……"
  },
  AvgDialog_19090_Content_12 = {
    Text = "墨菲捂著胸口，表情凝重地看向密境的邊界。"
  },
  AvgDialog_19090_Content_13 = {
    Text = "她在乎的只有神明的重生，除此之外一切都不被她放在眼裡。"
  },
  AvgDialog_19090_Content_14 = {
    Text = "她會殺掉所有人，最後，這個怪物會把我的心臟啃得連渣也不會剩下。"
  },
  AvgDialog_19090_Content_15 = {
    Text = "我不想……就這麼死掉……"
  },
  AvgDialog_19090_Content_16 = {
    Text = "一時間，沉默如死寂般蔓延。"
  },
  AvgDialog_19090_Content_2 = {
    Text = "蹈海者教團的筆記中，反復強調著<Blue:星辰正位>的重要性，降生儀式也必須在特定的時間進行，這就是那女人讓我沉睡的原因。"
  },
  AvgDialog_19090_Content_3 = {
    Text = "船長推測，祂的成長也許與天體運轉的規則有關。\n所以希萊斯特就以船為中心，製造出了這個與世隔絕的密境。"
  },
  AvgDialog_19090_Content_4 = {
    Text = "我們猜對了，自從離開了真正的天空，祂也隨之沉寂了下來。\n只要在密境裡躲過這一次的正位之時，也許祂就會永遠休眠下去。"
  },
  AvgDialog_19090_Content_5 = {
    Text = "等等，希萊斯特？"
  },
  AvgDialog_19090_Content_6 = {
    Text = "有人能先和我解釋一下嗎？“希萊斯特”是何方神聖？"
  },
  AvgDialog_19090_Content_7 = {
    Text = "咦？沒和你解釋過嗎？"
  },
  AvgDialog_19090_Content_8 = {
    Text = "希萊斯特是船長的搭檔，也是一名喚醒體。\n正是她控制著本該沉沒的索納尼爾號航行，並構築出了這個密境。"
  },
  AvgDialog_19090_Content_9 = {
    Text = "我們能否回到陸地也取決於她嗎？"
  },
  AvgDialog_19091_Content_1 = {
    Text = "墨菲的情緒低沉了下來，你不知道該如何安慰她，拉蒙娜卻出神地看著天上的海鳥。"
  },
  AvgDialog_19091_Content_10 = {
    Text = "根據皇家天文臺的計算，月球到達近地點應該在<Blue:聖派翠克節>前後。\n現在的月相，是違反科學規律的。"
  },
  AvgDialog_19091_Content_11 = {
    Text = "你能說英語嗎？"
  },
  AvgDialog_19091_Content_12 = {
    Text = "是的，是個月亮非常大的夜晚。\n月亮非常明亮，其他所有星座都不可見。"
  },
  AvgDialog_19091_Content_13 = {
    Text = "什、什麼？！居然就是今天……"
  },
  AvgDialog_19091_Content_14 = {
    Text = "就算我們能順利從蹈海者手中逃走，心臟裡的這傢伙也會要了我的命。"
  },
  AvgDialog_19091_Content_15 = {
    Text = "如果有其他方法能隔絕天體，說不定就能給你爭取到更多時間。"
  },
  AvgDialog_19091_Content_16 = {
    Text = "<Big:說得輕鬆！>停止時間、製造空間……不管哪個都不是過家家，就連我都知道沒這麼簡單。"
  },
  AvgDialog_19091_Content_18 = {
    Text = "莉莉的房間！"
  },
  AvgDialog_19091_Content_19 = {
    Text = "是的。朵爾和溫柯爾女士正在研究那個房間，希望能製造出不被追獵的空間用於實驗。"
  },
  AvgDialog_19091_Content_2 = {
    Text = "為了遠離船上的危險氣壓，飛鳥盤旋的隊伍四散崩離，海鳥們直直衝向了異色的光——"
  },
  AvgDialog_19091_Content_20 = {
    Text = "研究已經初具雛形，我們這次出發前，溫柯爾女士已經在著手準備動物實驗了。"
  },
  AvgDialog_19091_Content_21 = {
    Text = "不用白費心思了。"
  },
  AvgDialog_19091_Content_22 = {
    Text = "你們的學校……總不能在海上吧。\n從這裡回到陸地，再趕回你們的學校……來不及的。"
  },
  AvgDialog_19091_Content_23 = {
    Text = "更何況希萊斯特還在那個女人手上……這艘船能不能靠岸都還是未知數。"
  },
  AvgDialog_19091_Content_24 = {
    Text = "下意識地，你看向了拉蒙娜。\n她眉頭緊皺，身姿卻挺拔不屈，她仍在思索能保全所有人的萬全之法。"
  },
  AvgDialog_19091_Content_26 = {
    Text = "她盯著你看了一會，最終心領神會地展開笑顏。"
  },
  AvgDialog_19091_Content_27 = {
    Text = "走吧，如果這是你所希望的話。"
  },
  AvgDialog_19091_Content_3 = {
    Text = "一隻，兩隻，三隻……它們列隊撞向天幕，渴望逃離這片空間，卻無一不被密境柔和地擋了回來。"
  },
  AvgDialog_19091_Content_5 = {
    Text = "帷幕在海鳥接二連三的撞擊下，竟變得透明了一瞬。這瞬間轉眼即逝，卻被拉蒙娜精准地捕捉——"
  },
  AvgDialog_19091_Content_6 = {
    Text = "剛才是不是……密境消失了一瞬。"
  },
  AvgDialog_19091_Content_7 = {
    Text = "是的……確實是的，我感受到了祂跳動了一下。"
  },
  AvgDialog_19091_Content_8 = {
    Text = "撐起隔絕天體牽引的密境，希萊斯特小姐恐怕已經竭盡全力了。 \n抵抗蹈海者的攻擊，對她來說負擔太大。"
  },
  AvgDialog_19091_Content_9 = {
    Text = "天體……等等，外面現在是晚上嗎？星星月亮看起來是什麼樣的？"
  },
  AvgDialog_19092_Content_10 = {
    Text = "這裡有地圖。"
  },
  AvgDialog_19092_Content_11 = {
    Text = "這一層有動力室的入口……去看看吧，鞋印的方向是往那邊去的。"
  },
  AvgDialog_19092_Content_12 = {
    Text = "隨意行動很危險，並非明智之選。"
  },
  AvgDialog_19092_Content_13 = {
    Text = "正因為危險，才更要去。\n我不能放任守密人獨自應敵。"
  },
  AvgDialog_19092_Content_14 = {
    Text = "……好，若你堅持如此。"
  },
  AvgDialog_19092_Content_2 = {
    Text = "這裡有些痕跡。"
  },
  AvgDialog_19092_Content_3 = {
    Text = "海水打濕了積灰，在貨艙留下了大片凌亂的痕跡：帶蹼的足印、蛇形移動的拖痕、布料拖拽的痕跡……"
  },
  AvgDialog_19092_Content_5 = {
    Text = "拉蒙娜蹲在樓梯旁端詳片刻，隨後站起身，在鞋印旁輕輕踩了一腳。"
  },
  AvgDialog_19092_Content_6 = {
    Text = "花紋和學生制式鞋是一致的，守密人來過這裡。"
  },
  AvgDialog_19092_Content_7 = {
    Text = "這裡還有另外一種圖樣。"
  },
  AvgDialog_19092_Content_8 = {
    Text = "鞋碼比我的要小，可能是小孩子留下的。"
  },
  AvgDialog_19092_Content_9 = {
    Text = "沒辦法追蹤，鞋印到這裡就消失了……"
  },
  AvgDialog_19093_Content_1 = {
    Text = "他是喚醒體！"
  },
  AvgDialog_19093_Content_10 = {
    Text = "狂笑在密境空間迴蕩，氣氛更加劍拔弩張——"
  },
  AvgDialog_19093_Content_11 = {
    Text = "你們走吧。"
  },
  AvgDialog_19093_Content_12 = {Text = "什麼？"},
  AvgDialog_19093_Content_13 = {
    Text = "別這麼戒備，處理亂跑的小老鼠本來就不歸我管……嘖，<Blue:提燈>那些廢物，連這點小事都做不好。"
  },
  AvgDialog_19093_Content_14 = {
    Text = "不過也多虧了他們，現在這場儀式可變得更精彩了。"
  },
  AvgDialog_19093_Content_15 = {
    Text = "不僅和<Blue:提燈教會>有牽連，而且你口中的<Blue:儀式>……"
  },
  AvgDialog_19093_Content_16 = {
    Text = "戈利亞……你究竟是什麼人？"
  },
  AvgDialog_19093_Content_17 = {
    Text = "我是什麼人？<Big:哈哈哈哈哈！>\n為什麼不問問你身邊那傢伙呢？"
  },
  AvgDialog_19093_Content_18 = {
    Text = "我，還有這些蹈海者從何而來——您不會猜不到吧？畢竟您可是至高無上的……"
  },
  AvgDialog_19093_Content_2 = {
    Text = "好驚人的力量，就算以喚醒體的角度來看，都難有人能夠望其項背。"
  },
  AvgDialog_19093_Content_20 = {
    Text = "真嚇人真嚇人——但可惜，我可不是你那些忠心耿耿的臣子。"
  },
  AvgDialog_19093_Content_21 = {
    Text = "我還得繼續為儀式做準備，沒空和你們繼續糾纏不清。"
  },
  AvgDialog_19093_Content_22 = {
    Text = "儘管夾著觸手東躲西藏吧，但你知道的——那個女人想要的東西，只有你能給。"
  },
  AvgDialog_19093_Content_23 = {
    Text = "——戈利亞，等等！"
  },
  AvgDialog_19093_Content_24 = {
    Text = "哦？小小姐還有什麼貴幹？"
  },
  AvgDialog_19093_Content_25 = {
    Text = "我喜歡有膽量挑戰權威的傢伙，在我不耐煩之前，你還有一個提問的機會。"
  },
  AvgDialog_19093_Content_26 = {
    Text = "有關……"
  },
  AvgDialog_19093_Content_27 = {
    Text = "有關提燈教會……我還有問題要問你。"
  },
  AvgDialog_19093_Content_3 = {
    Text = "這力量……"
  },
  AvgDialog_19093_Content_4 = {
    Text = "圖魯的遲疑甫一顯露，巨人也若有所思地停止了攻擊。"
  },
  AvgDialog_19093_Content_5 = {
    Text = "原來如此……你居然和彌薩格大學的人混在了一塊。"
  },
  AvgDialog_19093_Content_6 = {
    Text = "戈利亞用赤裸而尖銳的目光打量著二人，最後放聲大笑了起來。"
  },
  AvgDialog_19093_Content_8 = {
    Text = "要是叫<Blue:那女人>看到這場面，她又會露出什麼樣的表情呢——不會直接發瘋吧？"
  },
  AvgDialog_19093_Content_9 = {
    Text = "哈哈哈哈，我太期待那個時刻了！"
  },
  AvgDialog_19094_Content_1 = {
    Text = "22：00\n索納尼爾號\n動力室"
  },
  AvgDialog_19094_Content_10 = {
    Text = "船上很危險，我會讓船儘量靠近海岸，但接下來你們只能用救生船漂流回陸地了。"
  },
  AvgDialog_19094_Content_11 = {
    Text = "你們呢？現在船上到處都是敵人，你們留在這裡很危險。"
  },
  AvgDialog_19094_Content_12 = {
    Text = "這是我們的船，船上是<Blue:希萊斯特>的密境，我們不會有事。"
  },
  AvgDialog_19094_Content_13 = {
    Text = "被稱作希萊斯特的喚醒體少女看了眾人一眼，發出了一聲微不可聞的鼻音。"
  },
  AvgDialog_19094_Content_14 = {
    Text = "密境是希萊斯特意志的具現，那些蹈海者是不被她承認的存在，本該被攔在密境之外。"
  },
  AvgDialog_19094_Content_15 = {
    Text = "難道說……！"
  },
  AvgDialog_19094_Content_16 = {
    Text = "我們的登船，讓密境的穩定性出現了失調。\n即使我解下了舷梯，蹈海者還是趁機從其他地方突破了密境……對嗎？"
  },
  AvgDialog_19094_Content_17 = {
    Text = "抱歉，我們……"
  },
  AvgDialog_19094_Content_18 = {
    Text = "這不是你們的錯，讓你上船是我們共同的決定。"
  },
  AvgDialog_19094_Content_19 = {
    Text = "“護佑人類”是一道掛在希萊斯特身上的枷鎖，作為她的同伴，我會盡可能配合她。"
  },
  AvgDialog_19094_Content_2 = {
    Text = "太危險了，不是讓你別靠近了嗎？"
  },
  AvgDialog_19094_Content_22 = {
    Text = "船長劇烈咳嗽起來，喚醒體少女的身體也隨之閃爍了一瞬。"
  },
  AvgDialog_19094_Content_23 = {
    Text = "圖魯突然閃現在希萊斯特身邊，昭示著非人身分的觸肢搭在了她的肩上。"
  },
  AvgDialog_19094_Content_24 = {
    Text = "她的存在非常微弱，余不認為她能繼續維持理智太久。"
  },
  AvgDialog_19094_Content_25 = {
    Text = "希萊斯特不會失去理智，我不會讓她變成失控的怪物。"
  },
  AvgDialog_19094_Content_26 = {
    Text = "憑藉凡人羸弱的生命與縹緲的靈知嗎，你的自信從何而來？"
  },
  AvgDialog_19094_Content_27 = {Text = "圖魯！"},
  AvgDialog_19094_Content_28 = {
    Text = "別急，女學生。\n喚醒體小子說得沒錯。"
  },
  AvgDialog_19094_Content_29 = {
    Text = "維持希萊斯特存在的消耗可不小……不過，總能找到辦法的。"
  },
  AvgDialog_19094_Content_3 = {
    Text = "您剛剛看見了，我有應付這些蹈海者的能力。\n我的名字是拉蒙娜，您就是船長嗎？"
  },
  AvgDialog_19094_Content_30 = {
    Text = "希萊斯特的反應一直十分微弱，她好像一副精美但無生命的油畫，或是舊時代立於帆船船首的船首像，安靜地俯瞰著世界與大海。"
  },
  AvgDialog_19094_Content_31 = {
    Text = "但此時，彷彿是為了回應埃爾頓船長的話，她微微躬身，摸了摸船長的帽檐。"
  },
  AvgDialog_19094_Content_32 = {
    Text = "拉蒙娜才注意到船長的狀況——這個高大的男人呼吸非常微弱，站立時手腳都止不住地發抖。"
  },
  AvgDialog_19094_Content_33 = {
    Text = "您的身體……"
  },
  AvgDialog_19094_Content_34 = {
    Text = "我沒事，老毛病了。"
  },
  AvgDialog_19094_Content_35 = {
    Text = "說起來怎麼只有你一個人？我可明明看見了兩個學生——\n希萊斯特，你能感覺到另一個學生在哪嗎？"
  },
  AvgDialog_19094_Content_36 = {
    Text = "被叫到名字的少女視線停留在自己指間，沒有立刻回應船長的話。\n過了好一會兒，希萊斯特才抬頭看向拉蒙娜。"
  },
  AvgDialog_19094_Content_37 = {
    Text = "……沒有了。\n除了埃爾頓、墨菲和……"
  },
  AvgDialog_19094_Content_38 = {
    Text = "和你……以外，沒有其他人了。"
  },
  AvgDialog_19094_Content_39 = {
    Text = "怎麼可能？！我們分開才不過半個小時。"
  },
  AvgDialog_19094_Content_4 = {
    Text = "埃爾頓，或者直接叫我船長。"
  },
  AvgDialog_19094_Content_40 = {
    Text = "而且我能感受到和守密人之間的聯繫，%heorshe%一定還在船上。"
  },
  AvgDialog_19094_Content_41 = {
    Text = "別急，女學生。船到橋頭自然直。\n如果你那位同學和你一樣優秀的話，%heorshe%會沒事的。"
  },
  AvgDialog_19094_Content_42 = {
    Text = "別忘了鞋印。"
  },
  AvgDialog_19094_Content_44 = {
    Text = "對了！守密人可能在和一個孩子一起行動。"
  },
  AvgDialog_19094_Content_45 = {
    Text = "孩子？我知道了……\n那是<Blue:墨菲>，這艘船唯一的乘客。"
  },
  AvgDialog_19094_Content_5 = {
    Text = "埃爾頓船長從腰包中掏出煙盒，剛撚起最後一撮煙葉，揚起的白紗就抽在了他手上。"
  },
  AvgDialog_19094_Content_6 = {
    Text = "他長歎一口氣，收回了煙盒。"
  },
  AvgDialog_19094_Content_7 = {
    Text = "你是那個彌薩格大學的人吧，我記得這身校服。"
  },
  AvgDialog_19094_Content_8 = {
    Text = "是的，多年前曾有一位本校前輩登上過這艘船。"
  },
  AvgDialog_19094_Content_9 = {
    Text = "可惜了，現在不是個好時機。\n如果換作其他日子，我還能給你倒杯酒好好聊聊。"
  },
  AvgDialog_19095_Content_10 = {
    Text = "不…不……他向我許諾過的……"
  },
  AvgDialog_19095_Content_11 = {
    Text = "消瘦的女人終於有了反應，她怔怔抬起頭，口中念念有詞。"
  },
  AvgDialog_19095_Content_12 = {
    Text = "我全能的神明將行使祂的權能……對這些造出偽造之物的，罪無可赦的異教徒降下審判！"
  },
  AvgDialog_19095_Content_13 = {
    Text = "她拔出腰間匕首，濃霧似的紫黑火焰覆蓋了刀身，散發著森然死氣。"
  },
  AvgDialog_19095_Content_15 = {
    Text = "贗品……去死吧！"
  },
  AvgDialog_19095_Content_16 = {
    Text = "到我身後來！"
  },
  AvgDialog_19095_Content_17 = {
    Text = "——匕首上陰冷詭譎的死之火，點燃了煤塵。"
  },
  AvgDialog_19095_Content_19 = {
    Text = "在火焰與塵埃的連環反應中，空氣急劇膨脹，爆破的嗡鳴巨響包圍了所有人。"
  },
  AvgDialog_19095_Content_2 = {
    Text = "這些建築正在消失。"
  },
  AvgDialog_19095_Content_20 = {
    Text = "面前是極速膨脹的火焰，身後是被爆炸破開大洞的艙壁。"
  },
  AvgDialog_19095_Content_21 = {
    Text = "%player%，把手給我！"
  },
  AvgDialog_19095_Content_22 = {
    Text = "衝擊力破開了船體金屬，在幻光和火焰的交織中，你與少女伸出的手擦肩而過。"
  },
  AvgDialog_19095_Content_23 = {
    Text = "——你向深海墜落。"
  },
  AvgDialog_19095_Content_3 = {
    Text = "這是彌利亞姆所構築的幻境，也許這就是她口中曾經的<Blue:神國>……"
  },
  AvgDialog_19095_Content_4 = {
    Text = "神國再臨……支撐她數千年的執念就這麼被打破了。\n圖魯，你…有什麼寬慰之言嗎？"
  },
  AvgDialog_19095_Content_6 = {
    Text = "敵人從失控中尋回了些許神智，同時褪去了異怪的形體。"
  },
  AvgDialog_19095_Content_7 = {
    Text = "彌利亞姆虛弱地躺在黑色塵埃中，目光渙散而虛無，連圖魯來到她身前都沒有做出任何反應。"
  },
  AvgDialog_19095_Content_8 = {
    Text = "不要執迷不悟了，彌利亞姆。"
  },
  AvgDialog_19095_Content_9 = {
    Text = "屬於我們的時代，我們的<Blue:永恆之國>，它的消失已成定局。"
  },
  AvgDialog_19096_Content_1 = {
    Text = "我們的通訊器，很貴嗎？"
  },
  AvgDialog_19096_Content_2 = {
    Text = "內核所使用的銀芯，在黑市能換到一套倫蒂尼恩中心的房產。"
  },
  AvgDialog_19097_Content_1 = {
    Text = "攻擊衝破了動力室一側牆壁，霧氣一般的蛇影糾纏成群，打破了原本勢均力敵的戰局。"
  },
  AvgDialog_19097_Content_10 = {
    Text = "你們沒必要被捲進來。"
  },
  AvgDialog_19097_Content_11 = {
    Text = "埃爾頓咬咬牙，向前站出了一步，擋在了拉蒙娜和希萊斯特身前。"
  },
  AvgDialog_19097_Content_12 = {
    Text = "主祭大人，我不理解您在說什麼。"
  },
  AvgDialog_19097_Content_13 = {
    Text = "事到如今……你還在執迷不悟嗎？"
  },
  AvgDialog_19097_Content_14 = {
    Text = "女人走到蹈海者群的最前列，拉蒙娜看清了她的模樣。"
  },
  AvgDialog_19097_Content_15 = {
    Text = "這正是他們登船後第一次被圍攻時，出現過的女人。"
  },
  AvgDialog_19097_Content_16 = {
    Text = "不可原諒……不可原諒，不可饒恕！"
