  AvgDialog_19100_Content_6 = {
    Text = "沒錯。如果放任儀式進行，墨菲體內的那個東西不知道會孵化出什麼怪物。"
  },
  AvgDialog_19100_Content_7 = {
    Text = "只憑我們的力量，恐怕無法結束這一切。\n但如果只是救出希萊斯特小姐，好讓墨菲先離開這艘船……"
  },
  AvgDialog_19100_Content_8 = {
    Text = "這是只有我們能做到的事"
  },
  AvgDialog_19101_Content_1 = {
    Text = "女學生！別靠近這裡！"
  },
  AvgDialog_19101_Content_2 = {
