  AvgDialog_19102_Content_12 = {
    Text = "誰勉強自己了？我可沒見著——等等，眼前這不就有一個嗎？"
  },
  AvgDialog_19102_Content_13 = {
    Text = "有人從<Yellow:爆炸>中倖存了下來，但撞壞了腦子，現在還在逞強說自己沒事。"
  },
  AvgDialog_19102_Content_14 = {
    Text = "等、等等？你在說誰？"
