  AvgDialog_19103_Content_8 = {
    Text = "只是暫時的。"
  },
  AvgDialog_19104_Content_1 = {
    Text = "墨菲狠狠跺了跺腳，一臉不情不願地湊近艙壁上的平面圖。"
  },
  AvgDialog_19104_Content_10 = {
    Text = "呼，<Small:我還以為你也看不明白。>"
  },
  AvgDialog_19104_Content_12 = {
    Text = "<BigShake:沒、沒什麼！>\n快好好看看。"
