  AvgDialog_19121_Content_5 = {
    Text = "看來有人的膽子被嚇破了。"
  },
  AvgDialog_19121_Content_6 = {
    Text = "請不要對外勤人員進行不必要的語言干擾。"
  },
  AvgDialog_19121_Content_7 = {
    Text = "好吧，好吧。\n那麼，你們需要幫助嗎？"
  },
  AvgDialog_19121_Content_8 = {
    Text = "我們需要增援！"
  },
  AvgDialog_19121_Content_9 = {
    Text = "我們在<Blue:布里爾珀特鎮>的<Blue:第三碼頭>，與未知敵人發生了遭遇戰。"
  },
  AvgDialog_19122_Content_1 = {
    Text = "那些醜陋的面容，僅是直視就令人感到對進化論的褻瀆。"
  },
  AvgDialog_19122_Content_2 = {
    Text = "它們相互推搡著，手中冷兵敲到在一起發出刺耳的聲響。而一片混亂的正中，它們似乎簇擁著什麼存在……"
  },
  AvgDialog_19123_Content_1 = {
    Text = "無路可逃"
  },
  AvgDialog_19123_Content_10 = {
    Text = "在碼頭髮動襲擊，將你們逼上舷梯的敵人團團圍在舷梯之下，一雙雙無神的魚眼緊盯著你們。"
  },
  AvgDialog_19123_Content_11 = {
    Text = "它們沒有跟上舷梯……"
  },
  AvgDialog_19123_Content_12 = {
    Text = "拉蒙娜壓低了聲音，悄聲說道。"
  },
  AvgDialog_19123_Content_13 = {
    Text = "我們被當作了開路小白鼠，一旦登上甲板，恐怕就會失去對他們的利用價值。"
  },
  AvgDialog_19123_Content_14 = {
    Text = "所以……我有個主意。"
  },
  AvgDialog_19123_Content_15 = {
    Text = "你們踏上了舷梯最後一級臺階。"
  },
  AvgDialog_19123_Content_16 = {
    Text = "拉蒙娜，不太對勁！先等一等！"
  },
  AvgDialog_19123_Content_17 = {
    Text = "舷梯一陣震顫，敵人沒有給你們喘息的機會。它們不再繼續觀望，手腳並用地向上攀爬。"
  },
  AvgDialog_19123_Content_18 = {
    Text = "哐當——！"
  },
  AvgDialog_19123_Content_19 = {
    Text = "拉蒙娜全力的一劍擊碎了固定搭扣，舷梯應聲掉落，卻沒有發出哪怕半分重物落地的聲響。"
  },
  AvgDialog_19123_Content_2 = {
    Text = "21：10\n港口城鎮-布里爾珀特\n第三碼頭"
  },
  AvgDialog_19123_Content_20 = {
    Text = "至少它們沒法從這部舷梯登船了。"
  },
  AvgDialog_19123_Content_21 = {
    Text = "等等，這……"
  },
  AvgDialog_19123_Content_22 = {
    Text = "如同被天空親吻的飛鳥，你們的雙眼被輕柔和煦的風拂過，入目的世界天翻地覆。"
  },
  AvgDialog_19123_Content_23 = {
    Text = "偌大的滿月消失在了天空中，極光般的光暈攪動著包圍船體的空間，投到甲板上的光斑也泛著奇異的色澤。"
  },
  AvgDialog_19123_Content_24 = {
    Text = "異象沖刷著你們的大腦，過了好一會兒你們才找回說話的能力。"
  },
  AvgDialog_19123_Content_26 = {
    Text = "拉蒙娜，你有什麼看法？"
  },
  AvgDialog_19123_Content_27 = {
    Text = "有趣，太有趣了。舷梯掉下去時沒有發出聲音——說明我們可能正身處一個獨立的空間中。"
  },
  AvgDialog_19123_Content_28 = {
    Text = "這是肉眼可見的<Yellow:密境>！"
  },
  AvgDialog_19123_Content_29 = {
    Text = "保護學校的迷霧由<Yellow:銀芯科技>驅動，不知道這艘船會處於哪種力量的控制之下呢？"
  },
  AvgDialog_19123_Content_3 = {
    Text = "鋼鐵銹蝕的腥臭直衝鼻腔，每走一步，舷梯都會發出搖搖欲墜的呻吟。"
  },
  AvgDialog_19123_Content_30 = {
    Text = "會是喚醒體嗎？"
  },
  AvgDialog_19123_Content_31 = {
    Text = "檔案中沒有類似記錄，但從理論上看，喚醒體創造獨立空間是可行的——你想聽聽具體理論嗎？"
  },
  AvgDialog_19123_Content_32 = {
    Text = "放過我吧……"
  },
  AvgDialog_19123_Content_33 = {
    Text = "看看場合吧！"
  },
  AvgDialog_19123_Content_34 = {
    Text = "抱歉，抱歉，原諒我的好奇心吧。"
  },
  AvgDialog_19123_Content_35 = {
    Text = "朵爾，你們聽見了嗎？"
  },
  AvgDialog_19123_Content_36 = {
    Text = "拉蒙娜點點胸針，通訊器表面似有流光劃過。"
  },
  AvgDialog_19123_Content_38 = {
    Text = "拉蒙娜側過身，伸手點了點你的通訊器。\n你試圖像往常一樣集中精神，但毫不奏效。"
  },
  AvgDialog_19123_Content_39 = {
    Text = "精神力就像淚水滴入了大海，歸於寂靜。"
  },
  AvgDialog_19123_Content_4 = {
    Text = "缺少維護修繕，但除了陳舊以外，船體本身相對完整。"
  },
  AvgDialog_19123_Content_40 = {
    Text = "我的通訊器也失去連接了。"
  },
  AvgDialog_19123_Content_41 = {
    Text = "從外觀上看通訊器沒有受損，但無法發信。"
  },
  AvgDialog_19123_Content_42 = {
    Text = "<Small:怎麼有這麼多東西能阻斷通信，上次在蠟像館也是……>"
  },
  AvgDialog_19123_Content_43 = {
    Text = "銀芯催生的科技不是萬能的。再說了，對於銀芯本身，我們的研究也還只是皮毛。"
  },
  AvgDialog_19123_Content_44 = {
    Text = "……不然，我們還是下船吧？"
  },
  AvgDialog_19123_Content_45 = {
    Text = "在甲板上到處看看吧，說不定能找到其他下船的方法。"
  },
  AvgDialog_19123_Content_46 = {
    Text = "小心周圍環境，並祈禱這艘船不會起航吧。"
  },
  AvgDialog_19123_Content_47 = {
    Text = "<Big:嗚————>"
  },
  AvgDialog_19123_Content_48 = {
    Text = "像是百靈鳥回應歌劇演員的花腔一般，綿長的汽笛回應起了拉蒙娜的祈禱。"
  },
  AvgDialog_19123_Content_5 = {
    Text = "海水侵蝕痕跡不明顯，吃水線下也沒有藤壺、牡蠣……"
  },
  AvgDialog_19123_Content_51 = {
    Text = "我知道你想說什麼，但拜託了，不是現在。"
  },
  AvgDialog_19123_Content_52 = {
    Text = "我們不能跟著索納尼爾號出海，這艘船有太多疑點了。"
  },
  AvgDialog_19123_Content_53 = {
    Text = "去甲板另一頭看看，大型船應該都配有救生艇，說不定能放下救生艇從海上撤離。"
  },
  AvgDialog_19123_Content_54 = {
    Text = "等等……好像有什麼聲音。"
  },
  AvgDialog_19123_Content_56 = {
    Text = "類魚面孔出現在了甲板上，將你們趕上船的始作俑者們步步緊逼。"
  },
  AvgDialog_19123_Content_6 = {
    Text = "你有什麼發現？"
  },
  AvgDialog_19123_Content_7 = {
    Text = "索納尼爾號缺少沉沒幽靈船的特徵，不符合它曾在風暴中沉沒的記錄。"
  },
  AvgDialog_19123_Content_8 = {
    Text = "如果有機會，我會想好好調查這艘船的來龍去脈……"
  },
  AvgDialog_19123_Content_9 = {
    Text = "但現在顯然不是個好時機。"
  },
  AvgDialog_19124_Content_1 = {
    Text = "啊啊……為什麼……為什麼！"
  },
  AvgDialog_19124_Content_2 = {
    Text = "彌利亞姆看起來不太對勁。"
  },
  AvgDialog_19124_Content_3 = {
    Text = "那不是正好嗎，趁現在趕緊把<Yellow:%player%>救下來。"
  },
  AvgDialog_19125_Content_1 = {
    Text = "伴隨著彌利亞姆心智的動盪，蹈海者的集群也變得不再穩定，混亂無序悄然蔓延開來。"
  },
  AvgDialog_19125_Content_2 = {
    Text = "蛇尾胡亂地抽打著艙壁，鋼鐵的共振嗡嗡作響。"
  },
  AvgDialog_19125_Content_3 = {
    Text = "堆積已久的煙塵也被揚起，在動力室下起一場簌簌黑雪。"
  },
  AvgDialog_19126_Content_10 = {
    Text = "不管你以為發生了什麼，一切都是我下的決定，我才是這艘船的主人。\n希萊斯特幾乎沒有自我意識，何談改變我？"
  },
  AvgDialog_19126_Content_11 = {Text = "是嗎？"},
  AvgDialog_19126_Content_12 = {
    Text = "我能讓你喚醒她，我也能讓她變回一抔銀沙。"
  },
  AvgDialog_19126_Content_14 = {
    Text = "就是現在！"
  },
  AvgDialog_19126_Content_17 = {
    Text = "攻擊結實地打在了拉蒙娜外放的護盾上，流光只持續了半秒，護盾就轟然碎裂。"
  },
  AvgDialog_19126_Content_18 = {
    Text = "女學生？！"
  },
  AvgDialog_19126_Content_2 = {
    Text = "22：35\n索納尼爾號\n動力室"
  },
  AvgDialog_19126_Content_20 = {
    Text = "我沒事，你別過來！"
  },
  AvgDialog_19126_Content_21 = {
    Text = "要分心保護人的情況下，我不是這個女人的對手。\n我盡力拖延她的攻擊，你先帶著他們離開。"
  },
  AvgDialog_19126_Content_22 = {
    Text = "你會趕來和我會合，對嗎？"
  },
  AvgDialog_19126_Content_23 = {
    Text = "你在擔心什麼？"
  },
  AvgDialog_19126_Content_24 = {
    Text = "拉蒙娜揮劍打散了襲來的蛇影，分神對你微笑了一下。"
  },
  AvgDialog_19126_Content_26 = {
    Text = "船長，快！"
  },
  AvgDialog_19126_Content_27 = {
    Text = "——如被洪水猛獸追趕般，你們玩命似地向艙室外狂奔。"
  },
  AvgDialog_19126_Content_3 = {
    Text = "感懷於你我皆為流蕩失離之人，我將逝者現世之法渡讓於你。"
  },
  AvgDialog_19126_Content_4 = {
    Text = "她的出現，代表你的夙願得償，想必你已得到了足夠的、來自逝去親眷的慰藉……"
  },
  AvgDialog_19126_Content_5 = {
    Text = "而我的願望，偉大神明寄予我的厚望，就是<Blue:那個孩子>。\n將聖女……不，將神母還給我。"
  },
  AvgDialog_19126_Content_6 = {
    Text = "蒙吾神聖恩，當他於聖女腹中重生，神國再臨之時……你亦將步入神國，尋得永恆安樂。"
  },
  AvgDialog_19126_Content_7 = {
    Text = "主祭大人，得知神母失蹤的消息，我也很驚訝。 但我已經說過了，神母不在船上。"
  },
  AvgDialog_19126_Content_8 = {
    Text = "何苦惺惺作態，故作愚人之姿？"
  },
  AvgDialog_19126_Content_9 = {
    Text = "我曾無比欣賞你的聰穎與執著，是什麼改變了你對我的忠誠，是這具<Yellow:魔像>嗎？如此弱小而縹緲……"
  },
  AvgDialog_19127_Content_10 = {
    Text = "我不指望你會出手幫忙。"
  },
  AvgDialog_19127_Content_11 = {
    Text = "但如果真的如你所言，一切“因你而起”，我希望至少不要從罪魁禍首口中聽見風涼話。"
  },
  AvgDialog_19127_Content_13 = {
    Text = "那些生物從甲板南側襲來，守密人不可能直直衝進敵人的包圍中，%heorshe%沒有那麼傻。"
  },
  AvgDialog_19127_Content_14 = {
    Text = "我們那時所在的北側甲板一定存在著沒被注意到的艙門入口。"
  },
  AvgDialog_19127_Content_16 = {
    Text = "怎麼了，有其他發現嗎？"
  },
  AvgDialog_19127_Content_18 = {
    Text = "指間有蹼，尾椎骨以上的部分完全魚化，保有一定智力。"
  },
  AvgDialog_19127_Content_19 = {
    Text = "它們的形體流暢自然，不像雕塑家協會的手筆，那些人總是把他們的實驗品弄得一團糟。"
  },
  AvgDialog_19127_Content_2 = {
    Text = "21：30\n索納尼爾號\n甲板"
  },
  AvgDialog_19127_Content_20 = {
    Text = "我原本以為，它們的外貌是受<Yellow:災厄>影響後變異的結果，但在這幾次戰鬥中，我並沒有發現它們身上存在有明顯的<Yellow:融蝕痕>。"
  },
  AvgDialog_19127_Content_21 = {
    Text = "它們……更像是進化論對人類開的一個愚蠢玩笑。"
  },
  AvgDialog_19127_Content_22 = {
    Text = "“對人類開的一個愚蠢玩笑”，余欣賞你的比喻。"
  },
  AvgDialog_19127_Content_23 = {
    Text = "謝謝，但這並沒有讓我放鬆對你的戒備。\n尤其是在你對我和守密人間的關係隨意置喙後。"
  },
  AvgDialog_19127_Content_24 = {
    Text = "余不會對你們出手。"
  },
  AvgDialog_19127_Content_25 = {
    Text = "是嗎？那為什麼不肯透露你擅自離校的真實目的？就如此難以啟齒嗎？"
  },
  AvgDialog_19127_Content_26 = {
    Text = "余沒有向你們解釋的義務，但如有必要，余將出手相助。"
  },
  AvgDialog_19127_Content_27 = {
    Text = "我和守密人希望調查提燈教會的線索，希望從這艘船上安全脫身。"
  },
  AvgDialog_19127_Content_28 = {
    Text = "我不認為我們之間有利益衝突，不然，我不會有在這兒和你費盡口舌的機會。坦誠相待只會是互利的。"
  },
  AvgDialog_19127_Content_29 = {
    Text = "余的事，與你們無關。"
  },
  AvgDialog_19127_Content_3 = {
    Text = "拉蒙娜攀在船舷上，半個身子探出了船外。"
  },
  AvgDialog_19127_Content_30 = {
    Text = "看，就是這樣的態度，才讓人無法信任你。"
  },
  AvgDialog_19127_Content_31 = {
    Text = "你表現出的憤怒，讓你很像一個人類。"
  },
  AvgDialog_19127_Content_32 = {
    Text = "不如說，你表現出的冷漠，讓人很難相信你曾作為人類生活過。"
  },
  AvgDialog_19127_Content_33 = {
    Text = "鬥嘴於你我二人而言，都是浪費時間。走吧，回北側甲板去。"
  },
  AvgDialog_19127_Content_34 = {
    Text = "拉蒙娜冷靜地結束了這場對話，越過少年喚醒體，轉身向著最開始上船的方向走去。"
  },
  AvgDialog_19127_Content_35 = {
    Text = "小心，敵襲！"
  },
  AvgDialog_19127_Content_36 = {Text = "什麼？"},
  AvgDialog_19127_Content_4 = {
    Text = "伸出的細劍尖端陷入了光幕之中，在看似無物的空中攪動出了小小的異色漩渦。"
  },
  AvgDialog_19127_Content_5 = {
    Text = "半晌後，她才收回細劍，在甲板上站定。"
  },
  AvgDialog_19127_Content_6 = {
    Text = "船已經出發了，但由於光幕的存在，無法通過參照物判斷航向。"
  },
  AvgDialog_19127_Content_7 = {
    Text = "母港、目的地、船主……這些都不重要，當務之急是找到守密人。"
  },
  AvgDialog_19127_Content_8 = {
    Text = "余本以為，以你的能力，是不必對所謂“守密人”言聽計從的。"
  },
  AvgDialog_19127_Content_9 = {
    Text = "你不需要連結也能保持理智，有獨自作戰的能力。"
  },
  AvgDialog_19128_Content_1 = {
    Text = "<Blue:蹈海者>大多身體羸弱，這把巨劍另有主人，小心應對。"
  },
  AvgDialog_19128_Content_2 = {
    Text = "你稱呼這些魚人為什麼？"
  },
  AvgDialog_19128_Content_3 = {
    Text = "他們圍過來了，小心。"
  },
  AvgDialog_19129_Content_10 = {
    Text = "你知道我們？"
  },
  AvgDialog_19129_Content_11 = {
    Text = "如果有什麼東西能讓<Blue:“燈芯”>恨之入骨，你們就是其中之一……不過，對聰明人，我向來抱有憐惜。"
  },
  AvgDialog_19129_Content_12 = {
    Text = "燈芯，提燈……難不成，<Blue:“燈芯”>指代了提燈教會中，某些地位特殊的人？"
  },
  AvgDialog_19129_Content_13 = {
    Text = "蹈海者的外形難以行走世間，而他們想要我們的力量……怪人的相互利用，抱團取暖罷了。"
  },
  AvgDialog_19129_Content_14 = {
    Text = "掌控著蹈海者勢力的你，一定是極受重視的合作者。\n還是說，你也是“燈芯”之一？"
  },
  AvgDialog_19129_Content_15 = {
    Text = "此身雖為<Yellow:搖曳燭光>，但願景與其餘燈芯所求，大相徑庭。\n爾等救世界於<Yellow:黑穢>，與<Blue:神國再臨>並非兩相衝突。"
  },
  AvgDialog_19129_Content_16 = {
    Text = "聰穎之人，不應埋沒於俗世。\n神之國土雖由血脈交織縱橫而起，卻也不吝於接納外來血液。"
  },
  AvgDialog_19129_Content_17 = {
    Text = "為我等效力，加入神國的再臨與復興，極盡榮光……如此，你我皆能行走於極樂之土。"
  },
  AvgDialog_19129_Content_18 = {
    Text = "如果你口中的復興 ，指的是以活人為祭品，以無辜者作為怪物的載體。"
  },
  AvgDialog_19129_Content_19 = {
    Text = "抱歉，我做不到，守密人也不會認同。"
  },
  AvgDialog_19129_Content_2 = {
    Text = "22：55\n索納尼爾號\n動力室"
  },
  AvgDialog_19129_Content_20 = {
    Text = "<Big:無禮之人！>能作為神明重生前的載體，理應感到榮耀。"
  },
  AvgDialog_19129_Content_21 = {
