  AvgDialog_19130_Content_1 = {Text = "船員"},
  AvgDialog_19130_Content_10 = {
    Text = "歌劇院？"
  },
  AvgDialog_19130_Content_11 = {
    Text = "<Yellow:%player%>加入彌薩格後，每次離校都是為了執行任務，我一直想找機會帶他逛逛倫蒂尼恩。"
  },
  AvgDialog_19130_Content_12 = {
    Text = "歌劇院可是家喻戶曉的地標性建築，恰逢新劇碼上演，將歌劇院作為觀光起點，順理成章。"
  },
  AvgDialog_19130_Content_13 = {
    Text = "但，你並不期待成為台下的觀眾。"
  },
  AvgDialog_19130_Content_14 = {
    Text = "……有時候我會覺得你敏銳得可怕，就像童話中能洞察人心的國王。"
  },
  AvgDialog_19130_Content_16 = {
    Text = "我並非無法理解藝術之美。從兒時起，父親就經常帶我出入劇場或畫展，甚至曾為我聘請過藝術鑒賞方面的老師。"
  },
  AvgDialog_19130_Content_17 = {
    Text = "但長大後，越是明白世界暗中發生的一切，我就越無法帶著欣賞的心情去享受藝術。"
  },
  AvgDialog_19130_Content_18 = {
    Text = "我會想，如果我們沒能找到<Yellow:融蝕現象>的起源，這一切美好之物就都會消融於虛無之中。"
  },
  AvgDialog_19130_Content_19 = {
    Text = "友人、親人、愛人逐一消逝，無論最後能有多少人倖存，這個世界都將變成孤寂的死地，無人將識得藝術為何物。"
  },
  AvgDialog_19130_Content_2 = {
    Text = "21：50\n索納尼爾號\n甲板"
  },
  AvgDialog_19130_Content_20 = {
    Text = "世界上本就不存在能夠永存的東西。"
