  AvgDialog_19130_Content_28 = {
    Text = "真正讓我相信他的，是你的態度。"
  },
  AvgDialog_19130_Content_29 = {
    Text = "若你真的順應命運，沒有絲毫反抗或彌補之心的話……就不會出現在這裡了，對嗎？"
  },
  AvgDialog_19130_Content_30 = {
    Text = "拉蒙娜的言語沒有絲毫留情。本不具攻擊性的詞語成為了尖刀，將某人的遮羞布狠狠切碎。"
  },
  AvgDialog_19130_Content_31 = {
    Text = "圖魯眯了眯眼，保持著斜斜撐頭的姿態，視線從拉蒙娜身上滑過，遊移向反射著異色光線的大海。"
  },
  AvgDialog_19130_Content_32 = {
