  AvgDialog_19977_Content_14 = {
    Text = "不，它好像……沒有臉。"
  },
  AvgDialog_19977_Content_15 = {
    Text = "怪物低垂的頭顱中央，隱約能分辨出近似人面的輪廓，但本應分佈五官的位置，如同黑洞一般，將所有光線吸納殆盡。"
  },
  AvgDialog_19977_Content_16 = {
    Text = "控制住它，蘿坦！我左邊，你右邊！"
  },
  AvgDialog_19977_Content_2 = {
    Text = "一行三人蜷身在破損的籬笆後，借深沉的夜色隱蔽身形，不時回頭張望。"
  },
  AvgDialog_19977_Content_3 = {
    Text = "喂，這種埋伏真的有用嗎？就憑這幾隻小雞仔？"
  },
  AvgDialog_19977_Content_4 = {
    Text = "我們靜觀其變。盡力忍耐一下，別按捺不住衝出去。"
  },
  AvgDialog_19977_Content_5 = {
