    Text = "庫姆……"
  },
  AvgDialog_19984_Content_9 = {
    Text = "此刻你才注意到，那黢黑的臉部並非沒有五官，只是閉合的雙眼、扁平的鼻翼和幾不可見的雙唇全部呈現出濃黑色，造成了無面的錯覺。"
  },
  AvgDialog_20082_Content_1 = {
    Text = "呼……怎麼回事……攀爬的難度比之前上升了很多，之前從沒這麼……這麼艱難！"
  },
  AvgDialog_20082_Content_2 = {
    Text = "雪山開始甦醒，地形隨時都在發生變化，抓緊我的手——"
  },
  AvgDialog_20082_Content_3 = {
    Text = "你握住希洛的手，從岩塊裂縫內艱難掙扎著爬起來，卻見莉莉朝你張開了懷抱。"
  },
  AvgDialog_20082_Content_4 = {
    Text = "莉莉，疼……要抱，一會兒就好。"
  },
  AvgDialog_20082_Content_5 = {
    Text = "你依言將她抱了起來。一路上莉莉都表現得很懂事聽話，但現在她的狀態似乎不太對勁……"
  },
  AvgDialog_20082_Content_6 = {
    Text = "莉莉，再撐一會，一會就好……"
  },
  AvgDialog_20082_Content_7 = {
    Text = "地面漆黑的岩塊上還殘留著些許積雪，你跺了跺腳，發現地面變得有些黏稠。"
  },
  AvgDialog_20082_Content_8 = {
    Text = "讓山體軟化，想要拖慢我們的腳步……不會讓它得逞的！"
  },
  AvgDialog_20233_Content_1 = {
    Text = "注意到了麼？他的弱點是身後的「死者」。"
  },
  AvgDialog_20233_Content_2 = {
    Text = "我來給你一點「小禮物」吧。"
  },
  AvgDialog_20475_Content_1 = {
    Text = "終於……見到你了。"
  },
  AvgDialog_20475_Content_10 = {
    Text = "雪山已經開始吞噬你們了……必須盡快打敗怪物，毀掉核心！"
  },
  AvgDialog_20475_Content_11 = {
    Text = "希洛點點頭，拔出黑刺，向怪物衝去——"
  },
  AvgDialog_20475_Content_2 = {
    Text = "你們艱難搏殺著，終於抵達了熒藍色怪物守護的山頂。"
  },
  AvgDialog_20475_Content_3 = {
    Text = "沉入死寂的雪山之巔，搖曳著一團熊熊燃燒的藍色火焰，如同雪山跳動的心臟。"
  },
  AvgDialog_20475_Content_4 = {
    Text = "你擋不住我們的。"
  },
  AvgDialog_20475_Content_5 = {
    Text = "空曠的雪山上迴盪著她的嗓音，漂浮在空中的藍色怪物凝視著她，漂浮在空中的巨獸沒有絲毫回應。"
  },
  AvgDialog_20475_Content_6 = {
    Text = "腿……動不了了……"
  },
  AvgDialog_20475_Content_7 = {
    Text = "你朝莉莉的方向望去。漆黑的岩塊融化成了漿液，莉莉的腿已經被黑泥吞沒了一半。"
  },
  AvgDialog_20475_Content_8 = {
    Text = "你用力拉動，莉莉的雙腿卻仍然被流動的黑漿覆蓋，越陷越深。"
  },
  AvgDialog_20475_Content_9 = {
    Text = "希洛的鞋跟也被黏液拽住，暗紅光線下的山脈閃爍著詭異的光澤，像是要將二人齊齊拉入地獄。"
  },
  AvgDialog_20483_Content_2 = {
    Text = "心智已然被憤怒吞噬，曾名為彌利亞姆的異怪僅停滯了須臾，便又再度發起瘋狂的進攻。"
  },
  AvgDialog_20483_Content_3 = {
    Text = "她已經認定余是冒牌貨了……既然如此，那余也只得用利莫里亞的方式來應對了。"
  },
  AvgDialog_20483_Content_4 = {
    Text = "彌利亞姆……\n希望這來自萬古的一擊…能讓你幡然醒悟。"
  },
  AvgDialog_20503_Content_1 = {
    Text = "不能再放任她繼續被憤怒侵蝕了，完全失控的她，會成為徹頭徹尾的怪物。"
  },
  AvgDialog_20503_Content_2 = {
    Text = "到那個地步，一切就都將無法挽回。\n降服她，或者……殺了她。"
  },
  AvgDialog_20503_Content_3 = {
    Text = "余最忠誠的臣子……\n願你……不再迷惘。"
  },
  AvgDialog_21363_Content_11 = {
    Text = "古老的黑色漩渦將%heorshe%吞沒。\n我只能眼睜睜地看著，黑池的風暴將整個彌薩格席捲殆盡。"
  },
  AvgDialog_21363_Content_12 = {
    Text = "喚醒系小心貯藏的銀芯全部被黑池溶解。"
  },
  AvgDialog_21363_Content_13 = {
    Text = "現存的喚醒體大多陷入失控，尖叫、暈厥、哀泣、恍惚、狂笑……"
  },
  AvgDialog_21363_Content_14 = {
    Text = "訶勒特和威廉組織了最後的撤離工作，並將迷霧屏障徹底封死。"
  },
  AvgDialog_21363_Content_15 = {
    Text = "我獨自一人被封存在黑池之中。"
  },
  AvgDialog_21363_Content_16 = {
    Text = "不知耗費了多久，我總算從塔薇施予我的知識中找到了一個方法。"
  },
  AvgDialog_21363_Content_17 = {
    Text = "一個通道——它可以讓我回到過去，扭轉已發生的悲劇。\n但不論是我還是塔薇，都無法預測這種行為會帶來的後果。"
  },
  AvgDialog_21363_Content_18 = {
    Text = "僅為了自己而做出這種行動，實在太過魯莽了。"
  },
  AvgDialog_21363_Content_19 = {
    Text = "我開始等待。"
  },
  AvgDialog_21363_Content_2 = {
    Text = "通道開啟計數：0"
  },
  AvgDialog_21363_Content_20 = {
    Text = "直到那天。\n阿利斯泰爾先生坐在輪椅上，由肢體破舊的朵爾推回了黑池邊。"
  },
  AvgDialog_21363_Content_21 = {
    Text = "你看，她果然在這裡。"
  },
  AvgDialog_21363_Content_22 = {
    Text = "就算世界末日了我也不會和你打賭的，阿利斯泰爾——哪怕現在確實是末日。"
  },
  AvgDialog_21363_Content_24 = {
    Text = "啊，你還不知道。外面的世界已經終結了，彌薩格……"
  },
  AvgDialog_21363_Content_25 = {
    Text = "讓我這麼說吧，我們是僅剩的所有了。"
  },
  AvgDialog_21363_Content_26 = {
    Text = "一切都消失了嗎？"
  },
  AvgDialog_21363_Content_27 = {
    Text = "乾乾淨淨。"
  },
  AvgDialog_21363_Content_28 = {
    Text = "如果不是連最後一個能當做實驗室的地方也沒了，這星球會是個完美的實驗場。"
  },
  AvgDialog_21363_Content_29 = {
    Text = "……那就……沒什麼好顧慮的了。"
  },
  AvgDialog_21363_Content_3 = {
    Text = "黑池異變那天，塔薇向我撲來，輕輕擁抱了我的靈魂。"
  },
  AvgDialog_21363_Content_31 = {
    Text = "我閉上眼，感受力量在我體內遊走。在漫長等待中，我變得與它熟悉無比。如今，它帶來了一種我已經淡忘的鮮活。"
  },
  AvgDialog_21363_Content_32 = {
    Text = "我會找到的，改變這一切的方法。"
  },
  AvgDialog_21363_Content_33 = {
    Text = "撕裂般的疼痛將我淹沒，我不禁想起那個下午。\n%player%當時也這樣痛苦嗎？還是比這更甚……？"
  },
  AvgDialog_21363_Content_34 = {
    Text = "悲劇不能再度上演。"
  },
  AvgDialog_21363_Content_35 = {
    Text = "通道開啟計數：1"
  },
  AvgDialog_21363_Content_36 = {
    Text = "在塔薇衝向我時，我拉著守密人退了半步。"
  },
  AvgDialog_21363_Content_37 = {
    Text = "為什麼？\n你建立彌薩格，是想要改變未來的吧？"
  },
  AvgDialog_21363_Content_38 = {
    Text = "你為什麼還要這麼做？"
  },
  AvgDialog_21363_Content_39 = {
    Text = "塔薇沒有言語，只是輕輕抬手，喚來與前次相同的風暴。"
  },
  AvgDialog_21363_Content_4 = {
    Text = "然後，黑色的潮水開始翻湧。"
  },
  AvgDialog_21363_Content_40 = {
    Text = "通道開啟計數：2"
  },
  AvgDialog_21363_Content_41 = {
    Text = "在朵爾要求我和守密人逃離時，我們沒有堅持。"
  },
  AvgDialog_21363_Content_42 = {
    Text = "我們沿著墓園外的後門，穿過稀薄的迷霧屏障，穿過晦暗莫名的小樹林。"
  },
  AvgDialog_21363_Content_43 = {
    Text = "眼前的景象豁然開朗——車水馬龍的倫蒂尼恩街道，活在幸福的日常中的普通民眾。"
  },
  AvgDialog_21363_Content_44 = {
    Text = "然而，這幸福沒有持續太久。"
  },
  AvgDialog_21363_Content_45 = {
    Text = "黑色的黏稠陰影從背後追上了我們。"
  },
  AvgDialog_21363_Content_46 = {
    Text = "這一次，在我眼前消失之物百倍千倍於從前。"
  },
  AvgDialog_21363_Content_47 = {
    Text = "行走在街道上歡笑的路人，突然邁不出步伐——被浸泡在黑泥之中，失去“存在”的雙足。"
  },
  AvgDialog_21363_Content_48 = {
    Text = "他們試圖移動，卻摔倒在不可見的污泥之中，最後……"
  },
  AvgDialog_21363_Content_49 = {
    Text = "他們失去了存在本身。"
  },
  AvgDialog_21363_Content_50 = {
    Text = "通道開啟計數：3"
  },
  AvgDialog_21363_Content_51 = {
    Text = "我隱瞞了鐘樓與黑池的存在，費盡口舌勸說守密人獨自離開校園，自己踏上了面對塔薇的道路。"
  },
  AvgDialog_21363_Content_52 = {
    Text = "失去了守密人的指揮和同伴的協助，我甚至沒能抵達黑池。在途中，我就被其他失控的喚醒體所擊潰。"
  },
  AvgDialog_21363_Content_53 = {
    Text = "通道開啟計數：4"
  },
  AvgDialog_21363_Content_54 = {
    Text = "通道開啟計數：5"
  },
  AvgDialog_21363_Content_56 = {
    Text = "通道開啟計數：@3"
  },
  AvgDialog_21363_Content_57 = {
    Text = "這是第幾次了？"
  },
  AvgDialog_21363_Content_58 = {
    Text = "我又要看著世界，看著%player%死去嗎？"
  },
  AvgDialog_21363_Content_59 = {
    Text = "如果無論我做什麼，身為守密人的%heorshe%都一定會死去，那麼，就讓%heorshe%不要成為守密人吧。"
  },
  AvgDialog_21363_Content_6 = {
    Text = "我盡力伸出手。"
  },
  AvgDialog_21363_Content_60 = {
    Text = "我隱瞞了%hisorher%能力，將%heorshe%留在了阿庫特。\n只要%heorshe%能活著，我不在乎自己是不是獨自前進。"
  },
  AvgDialog_21363_Content_61 = {
    Text = "這次，我甚至沒能離開墓園。"
  },
  AvgDialog_21363_Content_62 = {
    Text = "你們坐在黑池邊上，拉蒙娜一邊為你包紮，一邊用平淡的口吻講述了自己的痛苦。"
  },
  AvgDialog_21363_Content_63 = {
    Text = "我試過逃離校園，也試過直面塔薇。"
  },
  AvgDialog_21363_Content_64 = {
    Text = "我試過帶上蘿坦、奧吉爾、朵爾和校園中遇到的其他人，也試過分別不與他們中的任意某個或某些人同行。"
  },
  AvgDialog_21363_Content_65 = {
    Text = "試過溫和交涉，也試過訴諸暴力。"
  },
  AvgDialog_21363_Content_66 = {
    Text = "但，一切都彷彿於事無補。"
  },
  AvgDialog_21363_Content_67 = {
    Text = "後來，我開始磨練自己的戰鬥技巧。"
  },
  AvgDialog_21363_Content_68 = {
    Text = "唯一殘存的可能性，就是在黑池異變那天，在塔薇現出真容的時刻，一擊貫穿她的核心。"
  },
  AvgDialog_21363_Content_69 = {
    Text = "必須足夠快，足夠快。"
  },
  AvgDialog_21363_Content_7 = {
    Text = "就像在阿庫特時那樣，如果我能拉住%heorshe%，%heorshe%就能在風暴中拯救陷入絕境的我們。"
  },
  AvgDialog_21363_Content_70 = {
    Text = "快到能讓蘿坦手足無措，快到能讓朵爾失去聲音，快到能讓塔薇反應不及。"
  },
  AvgDialog_21363_Content_71 = {
    Text = "見到的每個人都成了磨礪劍術的對象，在這條道路上，我不再有名為「夥伴」之物。"
  },
  AvgDialog_21363_Content_72 = {
    Text = "我甚至不再與守密人對話，只是一心一意地磨練著那一記「命定之劍」。"
  },
  AvgDialog_21363_Content_73 = {
    Text = "你成功了嗎？"
  },
  AvgDialog_21363_Content_74 = {
    Text = "我成功了……也失敗了。"
  },
  AvgDialog_21363_Content_75 = {
    Text = "那天，塔薇向我伸出雙臂。"
  },
  AvgDialog_21363_Content_76 = {
    Text = "我憑著千錘百煉出的直覺，朝著塔薇的胸膛隱藏的閃光刺出全力一擊。"
  },
  AvgDialog_21363_Content_78 = {
    Text = "堅硬金屬碰撞的聲音迴盪，震顫著我緊握細劍的手腕。"
  },
  AvgDialog_21363_Content_79 = {
    Text = "塔薇的形體消散，化作銀色的飛灰。"
  },
  AvgDialog_21363_Content_8 = {
    Text = "更何況——"
  },
  AvgDialog_21363_Content_80 = {
    Text = "結束了，終於……"
  },
  AvgDialog_21363_Content_81 = {
    Text = "結束了……！"
  },
  AvgDialog_21363_Content_82 = {
    Text = "%player%，我們成功——"
  },
  AvgDialog_21363_Content_84 = {
    Text = "我身後沒有守密人。"
  },
  AvgDialog_21363_Content_85 = {
    Text = "有的，是一隻正在沉入黑色漩渦的手。"
  },
  AvgDialog_21363_Content_86 = {
    Text = "那一天，我縱身躍入了黑池。"
  },
  AvgDialog_21363_Content_87 = {
    Text = "然後，我短暫地看到了一個不屬於我的未來。"
  },
  AvgDialog_21363_Content_88 = {
    Text = "「塔薇」仍靜立原地，只是姿態已不似之前從容。"
  },
  AvgDialog_21363_Content_89 = {
    Text = "在其他所有人反應過來之前，祂猛然張開銀色的羽翼，向拉蒙娜——向另一個我撲去。"
  },
  AvgDialog_21363_Content_90 = {
    Text = "時間像是凝固了。"
  },
  AvgDialog_21363_Content_92 = {
    Text = "守密人疾步衝刺，擋在了另一個我的面前。"
  },
  AvgDialog_21363_Content_93 = {
    Text = "我這才明白。"
  },
  AvgDialog_21363_Content_94 = {
    Text = "世界的未來並不由我選擇和改變。"
  },
  AvgDialog_21363_Content_96 = {
    Text = "一步，即是命運的天塹。"
  },
  AvgDialog_21364_Content_2 = {
    Text = "等等，拉蒙娜！朵兒和奧吉爾不在這裡，僅憑你一個人的話……"
  },
  AvgDialog_21364_Content_3 = {
    Text = "來不及了，塔薇已經嘯叫著張開了銀色六翼。"
  },
  AvgDialog_21364_Content_4 = {
    Text = "熟悉的溫熱酸澀感燎燒著你的眼眶，這一次比上回更加灼熱刺痛，眼淚止不住地撲簌而下。"
  },
  AvgDialog_21364_Content_5 = {
    Text = "拉蒙娜轉過頭來，壓低了聲音對你低語。"
  },
  AvgDialog_21364_Content_6 = {
    Text = "與我鏈接，最後再對我下達一次指令吧。"
  },
  AvgDialog_21365_Content_2 = {
    Text = "乾淨俐落的一劍瞬間結束了戰鬥，拉蒙娜甩掉劍上的黏液，全程沒有回頭看過你一眼。"
  },
  AvgDialog_21365_Content_3 = {
    Text = "你震驚地看著堪稱冷漠的她的背影，感到一陣陌生。"
  },
  AvgDialog_21365_Content_4 = {
    Text = "這……真的是記憶嗎？"
  },
  AvgDialog_21365_Content_5 = {
    Text = "拉蒙娜跨過還未消散的異變體的屍體，提著劍就朝廣場的方向跑去。"
  },
  AvgDialog_21366_Content_1 = {
    Text = "你匆忙趕上拉蒙娜，在電梯關閉前最後一秒，冒著被夾住雙手的風險拉開了電梯門。"
  },
  AvgDialog_21366_Content_10 = {
    Text = "人工密境會切斷鏈接嗎？\n你看到的這一切，究竟是什麼？"
  },
  AvgDialog_21366_Content_11 = {
    Text = "你不知道。\n你甚至不知道自己什麼時候才能離開。"
  },
  AvgDialog_21366_Content_13 = {
    Text = "拉蒙娜邁出電梯，在身後扔下一句答案："
  },
  AvgDialog_21366_Content_3 = {
    Text = "直到這時，你才終於在進入「人工密境」後，第一次見到了她的臉。"
  },
  AvgDialog_21366_Content_5 = {
    Text = "眼前的拉蒙娜雙眼上蒙了黑色的眼罩，她面露不悅之色，似乎是對你耽誤了她下行的速度而感到不滿。"
  },
  AvgDialog_21366_Content_6 = {
    Text = "你……不是我認識的那個拉蒙娜，對嗎？"
  },
  AvgDialog_21366_Content_7 = {
    Text = "電梯聲隆隆。\n拉蒙娜面朝著你，沒有說話。"
  },
  AvgDialog_21366_Content_8 = {
    Text = "你試探著感應你們之間的鏈接，卻一無所獲。"
  },
  AvgDialog_21366_Content_9 = {
    Text = "沒有鏈接……"
  },
  AvgDialog_21367_Content_1 = {
    Text = "這不是永別"
  },
  AvgDialog_21367_Content_10 = {
    Text = "黑池的景象如褪色一般淺淡下去，「塔薇」原本所在的地方隱約顯露出喚醒儀器的輪廓。"
  },
  AvgDialog_21367_Content_11 = {
