  AvgDialog_21391_Content_8 = {
    Text = "但是，我的媽媽不一樣。"
  },
  AvgDialog_21391_Content_9 = {
    Text = "她以為我是其他人，但她在第一次用手術刀劃開我的時候，對我說對不起了。"
  },
  AvgDialog_21392_Content_10 = {
    Text = "駕駛員急忙拉下手刹，列車劇烈震顫減速。\n不明情況的乘客慌忙躍下地鐵，四散而逃。"
  },
  AvgDialog_21392_Content_11 = {
    Text = "緊急情況，保護群眾！\n朵爾，朵爾，你能聽見嗎？"
  },
  AvgDialog_21392_Content_12 = {
    Text = "檢測到……通訊干擾……銀芯波動……疑似……嗞啦啦……共鳴……"
  },
  AvgDialog_21392_Content_13 = {
    Text = "有句話怎麼說來著？遠水救不了近火。\n看來，是我出手的時候了。"
  },
  AvgDialog_21392_Content_2 = {
    Text = "那、那是什麼東西？！"
  },
  AvgDialog_21392_Content_3 = {
    Text = "在黑暗地道前方的鐵軌上，燈光映亮之處，站著不可能存在的身影。"
  },
  AvgDialog_21392_Content_4 = {
    Text = "女人身姿高挑，眼神淩厲如刀，鎮定地迎接著呼嘯而來的列車。"
  },
  AvgDialog_21392_Content_6 = {
    Text = "只在短短的一刹間，女人的身影消失了——"
  },
  AvgDialog_21392_Content_8 = {
    Text = "不，不是消失，她朝著飛馳的列車奔襲而來！"
  },
