  AvgDialog_21761_Content_8 = {
    Text = "【小雨】測試，2\n結束"
  },
  AvgDialog_21761_Content_9 = {
    Text = "正在進行【老膠片】測試，1"
  },
  AvgDialog_21801_Content_10 = {
    Text = "你怎麼走路歪歪扭扭的，是不是腿受傷了？"
  },
  AvgDialog_21801_Content_11 = {
    Text = "你回頭看向自己所走過的地方：為了繞開滿地流溢的融蝕漿，腳印在泥地上印出了一道詭異的弧線。"
  },
  AvgDialog_21801_Content_12 = {
    Text = "要不然，要不然奧瑞塔背你走吧！"
  },
  AvgDialog_21801_Content_13 = {
    Text = "不，不用了。我只是覺得這樣走更好玩，奧瑞塔不覺得有意思嗎？"
  },
  AvgDialog_21801_Content_15 = {
    Text = "對，像跳房子。"
  },
  AvgDialog_21801_Content_16 = {
    Text = "……奧瑞塔，我們來玩踩影子遊戲吧？"
  },
  AvgDialog_21801_Content_17 = {
    Text = "我走在前面，你踩著我的腳印走……怎麼樣？"
  },
  AvgDialog_21801_Content_18 = {
    Text = "嗯…也不是不可以哦！那朋友先走，奧瑞塔來給你指路。"
  },
  AvgDialog_21801_Content_19 = {
    Text = "奧瑞塔乖乖後退兩步為你讓出了路，蹦跳間險些一腳踩進融蝕漿中。"
  },
  AvgDialog_21801_Content_20 = {
    Text = "你猛地拉了她一把，她渾然不覺地眨眨眼，臉上仍洋溢著遊戲開始的快樂。"
  },
  AvgDialog_21801_Content_21 = {
    Text = "滴滴——小火車出發！中心廣場——往左邊！"
  },
  AvgDialog_21801_Content_3 = {
    Text = "奧瑞塔哼唱著輕快的小調，與你並肩走在被融蝕所消解的街道上。"
  },
  AvgDialog_21801_Content_4 = {
    Text = "無燈的幽暗窗口昭彰著此處早已人去樓空，寂靜的街道兩側，只留下房屋殘破的輪廓。"
  },
  AvgDialog_21801_Content_5 = {
    Text = "那些居民呢？他們是否早在融蝕現象爆發前就離開了家，是否尋找到了新的住地，還是……"
  },
  AvgDialog_21801_Content_6 = {
    Text = "黏稠的黑液在腳邊無聲流淌，你深吸了一口氣，壓下幾乎跳出喉嚨的反胃。"
  },
  AvgDialog_21801_Content_7 = {
    Text = "還是……他們從未離開自己深愛的家園？"
  },
  AvgDialog_21801_Content_9 = {
    Text = "認真思考時發出的哼唧聲把你從愁緒中拉出，奧瑞塔上下打量了你一番，終於不解地開口。"
  },
  AvgDialog_21803_Content_1 = {
    Text = "水裡的宮殿"
  },
  AvgDialog_21803_Content_10 = {
    Text = "真的嗎！謝謝婆婆！"
  },
  AvgDialog_21803_Content_11 = {
    Text = "貝蒂婆婆三言兩語哄好了奧瑞塔，目送著女孩蹦蹦跳跳地跑進了另一邊的廢墟，這才微笑著轉向你。"
  },
  AvgDialog_21803_Content_12 = {
    Text = "您特意支開奧瑞塔，到底是想要和我說什麼？"
  },
  AvgDialog_21803_Content_13 = {
    Text = "別太防備，我只是想要……講一個故事。"
  },
  AvgDialog_21803_Content_14 = {
    Text = "曾經，這裡是個漁港。有理想的年輕人去了城裡，也有人留在家鄉以捕魚為生……平靜得和其他漁村沒什麼不同。"
  },
  AvgDialog_21803_Content_15 = {
    Text = "變化發生得悄無聲息，不知不覺間，這裡只剩下了婦孺。"
  },
  AvgDialog_21803_Content_16 = {
    Text = "一艘艘漁船離開，卻只有一截截破碎的龍骨順著洋流回到海岸。"
  },
  AvgDialog_21803_Content_17 = {
    Text = "黑色的水流漫過堤壩，街道被侵蝕得支離破碎。"
  },
  AvgDialog_21803_Content_18 = {
    Text = "等奧瑞塔反應過來時，她的玩伴、她的家人甚至整個小鎮的居民，都已經消失得無影無蹤……"
  },
  AvgDialog_21803_Content_2 = {
    Text = "自稱貝蒂的老婦人微笑著打量你，似乎在不留痕跡地審視你作為“奧瑞塔朋友”的資格。"
  },
  AvgDialog_21803_Content_20 = {
    Text = "她搖搖頭，示意你看向她的下半身。"
  },
  AvgDialog_21803_Content_21 = {
    Text = "麻布長裙之下流出的，赫然是融蝕漿。\n她的下半身幾乎完全浸泡在湮滅與虛無之中。"
  },
  AvgDialog_21803_Content_23 = {
    Text = "您、您現在身體感覺如何？"
  },
  AvgDialog_21803_Content_24 = {
    Text = "老婦人噗嗤一聲笑了出來，她拍了拍你的肩膀，就像一位真正的長輩。"
  },
  AvgDialog_21803_Content_25 = {
    Text = "別怕，年輕人，別怕。"
  },
  AvgDialog_21803_Content_26 = {
    Text = "「貝蒂婆婆」早就消失了，是那個孩子的執念把我留在了這裡。"
  },
  AvgDialog_21803_Content_27 = {
    Text = "說話間，不知何處而來的風吹來了一張傳單。\n紙面上的圖樣被融蝕漿塗黑了大半，但宣傳語仍依稀可見。"
  },
  AvgDialog_21803_Content_28 = {
    Text = "「貝蒂麵包房，家鄉婆婆的手工麵包」"
  },
  AvgDialog_21803_Content_29 = {
    Text = "哎呀……看來，「貝蒂」也不一定是我真正的名字。"
  },
  AvgDialog_21803_Content_3 = {
    Text = "良久，她才收起眼神，拍了拍奧瑞塔的背。"
  },
  AvgDialog_21803_Content_30 = {
    Text = "……您為什麼要告訴我這些？"
  },
  AvgDialog_21803_Content_31 = {
    Text = "貝蒂婆婆看向了不遠處歪倒的廢樓，奧瑞塔正在那裡“尋寶”，弄得塵灰滿天。"
  },
  AvgDialog_21803_Content_32 = {
    Text = "為了不讓奧瑞塔傷心，我對她撒了很多謊。"
  },
  AvgDialog_21803_Content_34 = {
    Text = "“海裡的家”"
  },
  AvgDialog_21803_Content_35 = {
    Text = "她居然連這個都告訴你了嗎？看來她真的很相信這個說辭……\n但除了編織謊言，她真正的婆婆又能做什麼呢？"
  },
  AvgDialog_21803_Content_36 = {
    Text = "我們能告訴她，她的父母再也不會回來了嗎？\n在這座沒有未來的城鎮，這種話太殘忍了。"
  },
  AvgDialog_21803_Content_37 = {
    Text = "所以，我想求你一件事……請你，請你對她保守秘密。"
  },
  AvgDialog_21803_Content_38 = {
    Text = "不要把現實中正在發生的事告訴她……至少，讓她在快樂中離開。"
  },
  AvgDialog_21803_Content_39 = {
    Text = "這是我的願望，也是……她的願望。"
  },
  AvgDialog_21803_Content_4 = {
    Text = "奧瑞塔，你先自己去玩一會兒，好嗎。\n婆婆和這位新朋友聊會天，馬上就來找你。"
  },
  AvgDialog_21803_Content_40 = {
    Text = "貝蒂婆婆語氣誠懇，聲音中甚至帶上了哀求。"
  },
  AvgDialog_21803_Content_41 = {Text = "離開？"},
  AvgDialog_21803_Content_42 = {
    Text = "明明什——麼都沒有嘛！"
  },
  AvgDialog_21803_Content_43 = {
    Text = "婆婆真的把陶人藏在那邊了嗎？奧瑞塔已經翻得底朝天了！"
  },
  AvgDialog_21803_Content_44 = {
    Text = "奧瑞塔悶悶不樂的聲音讓你下意識看了過去，她站在廢墟上背對著你。\n這一次，你終於看清了她背上一閃而過的黑色污漬。"
  },
  AvgDialog_21803_Content_45 = {
    Text = "小小的身體上赫然盤踞著一個空洞——那分明是一塊巨大的融蝕痕。"
  },
  AvgDialog_21803_Content_46 = {
    Text = "你一愣，回頭看向「貝蒂婆婆」曾站立的地方。\n那裡只剩下一灘黏稠的液體，與污黑的積水融為一體。"
  },
  AvgDialog_21803_Content_47 = {
    Text = "污水中，陶瓷反射著溫潤的光。"
  },
  AvgDialog_21803_Content_48 = {
    Text = "撿起陶偶"
  },
  AvgDialog_21803_Content_49 = {
    Text = "出人意料的，「貝蒂婆婆」消失後，留下的竟不是老婦造型的陶偶。"
  },
  AvgDialog_21803_Content_5 = {
    Text = "奧瑞塔不能一起聊天嗎？"
  },
  AvgDialog_21803_Content_50 = {
    Text = "圓潤飽滿的傘蓋，細而密的觸鬚，在瓷白的底色上點綴著四葉形的藍釉。"
  },
  AvgDialog_21803_Content_51 = {
    Text = "哇啊——是奧瑞塔最喜歡的水母！"
  },
  AvgDialog_21803_Content_52 = {
    Text = "你果然耍賴皮！居然騙奧瑞塔去那邊找，明明就在你手上！"
  },
  AvgDialog_21803_Content_53 = {
    Text = "別、別生氣…你看，這些是什麼？"
  },
  AvgDialog_21803_Content_54 = {
    Text = "你扯出一個勉強的笑，從口袋裡又拿出了「潑尼」和「白雪」，連著「水母」陶偶一起遞給了奧瑞塔。"
  },
  AvgDialog_21803_Content_55 = {
    Text = "都是給奧瑞塔的嗎？！謝謝朋友！"
  },
  AvgDialog_21803_Content_56 = {
    Text = "水缸~奧瑞塔的水族箱~"
  },
  AvgDialog_21803_Content_57 = {
    Text = "宮殿~朋友和水裡的宮殿~"
  },
  AvgDialog_21803_Content_58 = {
    Text = "奧瑞塔哼著歌，沉溺在拿到新玩具的喜悅中。維特、潑尼、白雪和貝蒂婆婆似乎沒能在她心裡留下哪怕一絲痕跡。"
  },
  AvgDialog_21803_Content_59 = {
    Text = "嘿咻…嘿咻……大家這麼站著可以嗎？"
  },
  AvgDialog_21803_Content_6 = {
    Text = "乖孩子，大人之間的話題，只怕你聽著會無聊呢。我們的小奧瑞塔不是最怕無聊了嗎？"
  },
  AvgDialog_21803_Content_60 = {
    Text = "把「潑尼」再往外面擺一擺吧，一匹馬站在室內總感覺有點奇怪。"
  },
  AvgDialog_21803_Content_61 = {
    Text = "好有道理！說起來，「潑尼」是你給牠取的名字嗎？"
  },
  AvgDialog_21803_Content_63 = {
    Text = "奧瑞塔的宮殿佈置好了！"
  },
  AvgDialog_21803_Content_64 = {
    Text = "奧瑞塔以後的家，奧瑞塔水裡的家……"
  },
  AvgDialog_21803_Content_65 = {
    Text = "奧瑞塔要睡在爸爸媽媽的隔壁房間，偶爾也要和他們一起睡！"
  },
  AvgDialog_21803_Content_66 = {
    Text = "小狗要睡在奧瑞塔的床上，小馬要待在客廳——待在花園裡。"
  },
  AvgDialog_21803_Content_67 = {
    Text = "水母可以在任何地方漂游，還有奧瑞塔的朋友們都要在壁爐前喝熱可可……"
  },
  AvgDialog_21803_Content_68 = {
    Text = "嗯…水底……可以點壁爐嗎？"
  },
  AvgDialog_21803_Content_69 = {
    Text = "奧瑞塔的眼睛一眨一眨的，竟顯出幾分困意來。她打了個長長的哈欠，眼神朦朧。"
  },
  AvgDialog_21803_Content_7 = {
    Text = "嗚…嗚嗚……可是我想和婆婆待在一起……"
  },
  AvgDialog_21803_Content_70 = {
    Text = "奧瑞塔困了嗎？"
  },
  AvgDialog_21803_Content_71 = {
    Text = "奧瑞塔…還能……玩……"
  },
  AvgDialog_21803_Content_72 = {
    Text = "放心睡吧，奧瑞塔。"
  },
  AvgDialog_21803_Content_73 = {
    Text = "壁爐會燒得暖暖的。"
  },
  AvgDialog_21803_Content_74 = {
    Text = "端上來的可可會加好多好多糖。"
  },
  AvgDialog_21803_Content_75 = {
    Text = "等你醒來，朋友們都會在。"
  },
  AvgDialog_21803_Content_77 = {
    Text = "不要…丟下奧瑞塔一個人哦……"
  },
  AvgDialog_21803_Content_8 = {
    Text = "婆婆的好孩子，和婆婆做個遊戲吧？"
  },
  AvgDialog_21803_Content_9 = {
    Text = "奧瑞塔不是想要裝飾朋友們的家嗎？婆婆在這兒附近藏了好幾個小陶人……只要奧瑞塔找到了，就都是奧瑞塔的了。"
  },
  AvgDialog_21805_Content_1 = {
    Text = "寂靜的白日"
  },
  AvgDialog_21805_Content_10 = {
    Text = "啊……不可以！那裡面的水不可以喝！你明明已經喝了這麼多了。"
  },
  AvgDialog_21805_Content_11 = {
    Text = "我這是溺水到差點死掉了，不是喝水喝的。"
  },
  AvgDialog_21805_Content_12 = {
    Text = "面對著女孩氣鼓鼓的天真神情，你感受著肺部的刺痛，好幾次深呼吸後，理智才終於又充盈了大腦。"
  },
  AvgDialog_21805_Content_13 = {
    Text = "意志與記憶共振，你終於意識到，再一次地，你進入了喚醒體的回憶——"
  },
  AvgDialog_21805_Content_15 = {
    Text = "奧瑞塔很擅長游泳！只要成為奧瑞塔的朋友，就不會再溺水了！"
  },
  AvgDialog_21805_Content_16 = {
    Text = "奧瑞塔一邊咋咋呼呼地繞著床打轉，一邊艱難地點燃了房間的爐火。"
  },
  AvgDialog_21805_Content_17 = {
    Text = "伴隨著女孩被爐灰嗆到的咳嗽，室內慢慢暖和了起來，濡濕的衣物飄出幾縷水汽，冰封的四肢逐漸回暖。"
  },
  AvgDialog_21805_Content_18 = {
    Text = "奧瑞塔…你是奧瑞塔，那麼這裡就是你的家……"
  },
  AvgDialog_21805_Content_19 = {
    Text = "嗯！這裡是奧瑞塔的家，而你是奧瑞塔從海裡請來的客人！"
  },
  AvgDialog_21805_Content_20 = {
    Text = "身體的記憶碎片浮出水面，你逐漸理解了自己在這場夢中所扮演的角色——"
  },
  AvgDialog_21805_Content_21 = {
    Text = "在風暴中落水的船員，被有好生之德的海浪推上了岸，最終被眼前的女孩連推帶拽撿回了家……"
  },
  AvgDialog_21805_Content_23 = {
    Text = "你多少已經習慣了“入夢”這種超脫現實的體驗。通常而言，只要見證過構築這段夢境的記憶，你就會在合適的時機醒來。"
  },
  AvgDialog_21805_Content_24 = {
    Text = "現在的問題是，你無法確認奧瑞塔的「記憶」。"
  },
  AvgDialog_21805_Content_25 = {
    Text = "奧瑞塔的「記憶」是一個謎團。融蝕吞噬了她被喚醒前的過去，從那孩童般的言語中，也難以找到足夠的細節拼湊全貌。"
  },
  AvgDialog_21805_Content_26 = {
    Text = "現在，也許正是補全奧瑞塔檔案空白的好時機。"
  },
  AvgDialog_21805_Content_27 = {
    Text = "怎麼了？怎麼這麼久不說話？"
  },
  AvgDialog_21805_Content_28 = {
    Text = "如果你不想和奧瑞塔玩的話，送你離開也不是不可以嘛……"
  },
  AvgDialog_21805_Content_29 = {
    Text = "這麼快就要送客了嗎？"
  },
  AvgDialog_21805_Content_3 = {
    Text = "液體在重擊之下被擠出了氣道，海水的腥鹹猝不及防湧上喉管，在舌根跳起了一場熱烈的康康舞。"
  },
  AvgDialog_21805_Content_31 = {
    Text = "你的意思是，你會和奧瑞塔一起玩嗎！"
  },
  AvgDialog_21805_Content_32 = {
    Text = "太好了太好了太好了！\n新的客人，新的朋友，加入奧瑞塔<Yellow:水族箱的新夥伴>！"
  },
  AvgDialog_21805_Content_34 = {
    Text = "水族箱？難不成，你說的是那個玻璃缸？"
  },
  AvgDialog_21805_Content_35 = {
    Text = "那是奧瑞塔為了佈置未來新家做的準備哦！"
  },
  AvgDialog_21805_Content_36 = {
    Text = "女孩興奮地擺著手，你也終於認真端詳起了窗邊裝滿水的玻璃缸——"
  },
  AvgDialog_21805_Content_37 = {
    Text = "它有著精緻的城堡造景，生命循環帶起的波瀾卻無處可尋。\n儼然只是一篇沉沒的童話。"
  },
  AvgDialog_21805_Content_38 = {
    Text = "新夥伴？"
  },
  AvgDialog_21805_Content_39 = {
    Text = "嗯！奧瑞塔的新朋友！等奧瑞塔回到海裡的家，和爸爸媽媽團聚，奧瑞塔的朋友們就都能來做客了。"
  },
  AvgDialog_21805_Content_40 = {
    Text = "分明躺在柔軟的被褥裡，可奧瑞塔的話卻讓你無端感到一陣脊背發涼。"
  },
  AvgDialog_21805_Content_41 = {
    Text = "這時你才意識到——太安靜了。"
  },
  AvgDialog_21805_Content_42 = {
    Text = "蟲鳴、風聲、樹葉相互撞擊的聲音……\n交談、笑鬧、鞋底摩擦路面的聲音……"
  },
  AvgDialog_21805_Content_43 = {
    Text = "世界一片死寂，只有作為夢境主人的奧瑞塔是鮮活的。"
  },
  AvgDialog_21805_Content_44 = {
    Text = "奧瑞塔……是一個人住在這裡嗎？"
  },
  AvgDialog_21805_Content_45 = {
    Text = "一個人？不是哦。維特、白雪、潑尼……奧瑞塔的朋友們都在鎮上呢！\n還有婆婆，奧瑞塔的<Yellow:婆婆>也和奧瑞塔住在一起！"
  },
  AvgDialog_21805_Content_46 = {
    Text = "對了！婆婆！婆婆說過，奧瑞塔如果交到了新朋友，那一定要讓她也認識認識！"
  },
  AvgDialog_21805_Content_47 = {
    Text = "提到「婆婆」，奧瑞塔眼睛一亮，蹦跳回床前想要順勢拉你起身，但想起什麼似地突然僵住了動作。"
  },
  AvgDialog_21805_Content_48 = {
    Text = "你還要喝水嗎？"
  },
  AvgDialog_21805_Content_5 = {
    Text = "海水與血腥味瀰漫在被過度浸泡的鼻腔，隨著你的劇烈咳嗽，甚至有粗糙的砂礫從鼻腔深處噴了出來。"
  },
  AvgDialog_21805_Content_50 = {
    Text = "我也想見見奧瑞塔的家人，奧瑞塔能帶我去找婆婆嗎？"
  },
  AvgDialog_21805_Content_51 = {
    Text = "嗯！婆婆應該就在中心廣場！"
  },
  AvgDialog_21805_Content_52 = {
    Text = "奧瑞塔腳步雀躍地下了樓，你也不再猶豫，拍拍臉頰使自己徹底清醒。"
  },
  AvgDialog_21805_Content_53 = {
    Text = "外面有點下雨了耶——"
  },
  AvgDialog_21805_Content_54 = {
