  AvgDialog_21875_Content_2 = {
    Text = "用這些工具抓住它吧！"
  },
  AvgDialog_22111_Content_10 = {
    Text = "那裡……那裡是……"
  },
  AvgDialog_22111_Content_100 = {
    Text = "我不太明白，一個人們都看不懂的東西，到底有什麼意義呢……"
  },
  AvgDialog_22111_Content_101 = {
    Text = "嗯……我覺得，詩歌並不是一種文字或者畫面，它像是一把鑰匙。"
  },
  AvgDialog_22111_Content_102 = {Text = "鑰匙？"},
  AvgDialog_22111_Content_103 = {
    Text = "對！人的心都像是一個箱子，裡面裝著好多好多的感情。這個箱子被上了鎖，這些感情平時都被鎖在箱子裡，想拿也拿不出來。"
  },
  AvgDialog_22111_Content_104 = {
    Text = "詩呢，就是打開這個箱子的那把鑰匙。"
  },
  AvgDialog_22111_Content_105 = {
    Text = "其實，詩是不需要被讀懂的，甚至連被閱讀都不需要。"
  },
  AvgDialog_22111_Content_106 = {
    Text = "每個人，不論讀不讀詩，不論早還是晚，在他們生命的某個瞬間，都一定會找到這把鑰匙的。"
  },
  AvgDialog_22111_Content_107 = {
    Text = "那你肯定會成為最好的鑰匙匠！"
  },
  AvgDialog_22111_Content_108 = {
    Text = "騙人……你剛剛才說了沒看懂。"
  },
  AvgDialog_22111_Content_109 = {
    Text = "你說的這些我都聽不懂。可是我相信你，奧爾拉。"
  },
  AvgDialog_22111_Content_11 = {
    Text = "你們站在花園邊緣的廣場。肉眼可見的融蝕裂隙從小樓下方往上蔓延，囊括了中間花園的空地。"
  },
  AvgDialog_22111_Content_110 = {
    Text = "這首《玫瑰的棲居》，是你寫的第一首詩。從今天開始，你所有的詩我都會幫你珍藏起來的。"
  },
  AvgDialog_22111_Content_111 = {
    Text = "我會用別針把它們整理到一起，等以後有錢了，就把它們印成一本漂亮的詩集！"
  },
  AvgDialog_22111_Content_112 = {
    Text = "她伸出一直背在身後的手。那雙手佈滿了棘刺留下的傷口，黝黑，粗糙，完全辨認不出是一雙屬於少女的手。"
  },
  AvgDialog_22111_Content_113 = {
    Text = "這……這個是……"
  },
  AvgDialog_22111_Content_114 = {
    Text = "聽那些新貴族們說，西岱是花與詩的城市，一首好詩，可以換到一束玫瑰……"
  },
  AvgDialog_22111_Content_115 = {
    Text = "我種的玫瑰今天開了。開的不是很多，全部都拿去付了房租和地租。"
  },
  AvgDialog_22111_Content_116 = {
    Text = "不過我趁他們不注意，悄悄留下了一朵……"
  },
  AvgDialog_22111_Content_117 = {
    Text = "那隻滿是傷痕的手，將一朵有些殘破、但依然鮮紅的玫瑰，遞到了奧爾拉的面前。"
  },
  AvgDialog_22111_Content_118 = {
    Text = "一首好詩，奧爾拉……以後，我就用我的花，來換你的詩吧！"
  },
  AvgDialog_22111_Content_12 = {
    Text = "那是……我們的花園……不……柯蕾特，不……"
  },
  AvgDialog_22111_Content_13 = {
    Text = "奧爾拉低下頭。柯蕾特走到她身旁，托起她的下巴，讓她的視線看著花園的中央。"
  },
  AvgDialog_22111_Content_14 = {
    Text = "你知道嗎，奧爾拉。很多年前，我就是在這個地方，看著那場大火燒起來的。"
  },
  AvgDialog_22111_Content_15 = {
    Text = "我把這裡改建成了廣場，在這裡樹立了我的雕像……你看，我也是懂象徵的。"
  },
  AvgDialog_22111_Content_16 = {
    Text = "看著。看清楚了。那是我們生活的地方……那是我們的花園。很快，那裡的一切都將消失掉。"
  },
  AvgDialog_22111_Content_17 = {
    Text = "我的生命，是從你死的那一天正式開始的。今天，它會在這裡再次走向輝煌……"
  },
  AvgDialog_22111_Content_18 = {
    Text = "黑色的裂隙快速地擴散著。很快，華麗的別墅被整個吞沒。"
  },
  AvgDialog_22111_Content_19 = {
    Text = "花園，灰燼，簡筆畫，詩歌，記憶，笑聲，誓言……一切的一切，都沉入了望不見盡頭的黑暗中。"
  },
  AvgDialog_22111_Content_2 = {
    Text = "你們的突襲成功擊倒了柯蕾特召喚出的怪物。詩中世界出現一陣動盪，西堤展露出它的一部分真容。"
  },
  AvgDialog_22111_Content_20 = {
    Text = "滴答——"
