  AvgDialog_22111_Content_50 = {
    Text = "那是你們人生中最為珍貴的時刻。"
  },
  AvgDialog_22111_Content_52 = {
    Text = "奧爾拉所經歷的巨大的痛苦，隨著她的鮮血，漣漪般傳向了整個西岱。"
  },
  AvgDialog_22111_Content_53 = {
    Text = "玫瑰的尖刺貫穿了無數顆心臟。鮮紅的花朵，在每個人心中盛開。"
  },
  AvgDialog_22111_Content_54 = {
    Text = "柯蕾特，你已經有了整個西岱，可你還住在這裡。"
  },
  AvgDialog_22111_Content_55 = {
    Text = "住在我們曾經夢想住著的房子，住在我們曾經一起生活的花園……"
  },
  AvgDialog_22111_Content_56 = {
    Text = "你曾經救下過我的命。這首用生命寫的詩，送給你，送給花園。"
  },
  AvgDialog_22111_Content_57 = {
    Text = "這是春天，寫給花園的詩。"
