  AvgDialog_22111_Content_58 = {
    Text = "奧爾拉……你……"
  },
  AvgDialog_22111_Content_59 = {
    Text = "淚水沖刷著她精緻的妝容，她毫不在意，任由它們在臉上留下不得體的凌亂痕跡。"
  },
  AvgDialog_22111_Content_6 = {
    Text = "柯蕾特的憤怒很快消失不見。她重新換上那副貴族般的得體笑臉。"
