  },
  AvgDialog_22111_Content_72 = {
    Text = "無數的怪物們吼叫著，倒在地上，逐漸恢復成人的形態。"
  },
  AvgDialog_22111_Content_73 = {
    Text = "權慾在消退，情感在回歸。構建這個世界的根基蕩然無存。"
  },
  AvgDialog_22111_Content_75 = {
    Text = "她感受到了力量的消失。她感受到了失敗的到來。她喚出利刃般的棘刺，走向奧爾拉。"
  },
  AvgDialog_22111_Content_76 = {
