  },
  AvgDialog_22120_Content_64 = {
    Text = "被融蝕的詩集，竟能產生如此特殊的密境。被融蝕的詩句，竟能干擾到現實的物體……"
  },
  AvgDialog_22120_Content_65 = {
    Text = "就連彌薩格，也找不出幾個這樣有趣的研究。"
  },
  AvgDialog_22120_Content_66 = {
    Text = "如果能一直活在虛假中，那就不存在虛假了。"
  },
  AvgDialog_22120_Content_67 = {
    Text = "您的智慧讓人驚嘆，夫人。"
  },
  AvgDialog_22120_Content_68 = {
    Text = "我們的儀式準備得如何了？"
  },
  AvgDialog_22120_Content_69 = {
    Text = "就快了……按照您的吩咐，儀式將在下個月開始。"
  },
  AvgDialog_22120_Content_7 = {
    Text = "你是怎麼看到奧爾拉的？"
  },
  AvgDialog_22120_Content_70 = {
    Text = "照您的說法，到那時候，詩集的融蝕將會擴散，甚至可能會影響到整個西岱？"
  },
  AvgDialog_22120_Content_71 = {
    Text = "我不記得您是一個關心道德的人。"
  },
  AvgDialog_22120_Content_72 = {
    Text = "當然。但我關心我所擁有的東西……到那時候，我的密境會受到影響嗎？"
  },
  AvgDialog_22120_Content_73 = {
    Text = "呵呵……請您放心，夫人。密境的形成，與融蝕息息相關。融蝕越強，您的密境越穩定。"
  },
  AvgDialog_22120_Content_74 = {
    Text = "密境現在能覆蓋的地方還不大，等到儀式完成，它將會擴散到西岱全境。"
  },
  AvgDialog_22120_Content_75 = {
    Text = "到那個時候，整個西岱的權力與財富，都將是您的。"
  },
  AvgDialog_22120_Content_76 = {
    Text = "“柯蕾特”，勝利……您從來都是贏家。不是嗎？"
  },
  AvgDialog_22120_Content_77 = {
    Text = "花匠走到窗邊，看著她的花園。"
  },
  AvgDialog_22120_Content_78 = {
    Text = "她盡力保持貴族般得體的微笑，但手中的紅酒杯不受控地顫抖。"
  },
  AvgDialog_22120_Content_79 = {
    Text = "貴婦人的臉倒映在搖晃的酒杯上，如同某種潰爛的創口。"
  },
  AvgDialog_22120_Content_8 = {
    Text = "我告訴過你答案了。"
  },
  AvgDialog_22120_Content_80 = {
    Text = "我們都會是贏家，赫伯特先生。"
  },
  AvgDialog_22120_Content_9 = {
    Text = "在新的西岱，一切美好的東西，都應該被看見。"
  },
  AvgDialog_22121_Content_1 = {
    Text = "遲來的葬禮"
  },
  AvgDialog_22121_Content_10 = {
    Text = "或許是受到了那場大火的影響"
  },
  AvgDialog_22121_Content_11 = {
    Text = "不管怎麼樣，這裡都應該是我們要找的地方了。"
  },
  AvgDialog_22121_Content_12 = {
    Text = "奧爾拉，那本詩集是放在哪裡的？"
  },
  AvgDialog_22121_Content_13 = {
    Text = "火燒起來的時候，為了保護那本詩集，我挖了一個小土坑，用一個盒子裝著，把詩集給埋了進去。"
  },
  AvgDialog_22121_Content_14 = {
    Text = "我們住在種植玫瑰的溫室裡，穿過那片花圃就能找到了。"
  },
  AvgDialog_22121_Content_16 = {
    Text = "有危險？！"
  },
  AvgDialog_22121_Content_17 = {
    Text = "啊，不是……守密人%sirormadam%，您看那裡。"
  },
  AvgDialog_22121_Content_18 = {
    Text = "奧爾拉興奮地指向一面牆。牆上用彩色粉筆畫著一幅粗糙的簡筆畫。"
  },
  AvgDialog_22121_Content_19 = {
    Text = "兩個穿著裙子的小女孩，正在扮演著貴婦與侍女。"
  },
  AvgDialog_22121_Content_2 = {
    Text = "我們到了！"
  },
  AvgDialog_22121_Content_20 = {
    Text = "來到這裡以後，我們經常玩這個遊戲，有時候我演貴族，有時候柯蕾特演。"
  },
  AvgDialog_22121_Content_21 = {
    Text = "這幅畫是她畫的，畫得不太好看。不過當時我們沒有更多的粉筆了。"
  },
  AvgDialog_22121_Content_22 = {
    Text = "這個紅裙子，是她用玫瑰的花汁塗抹出來的……現在已經看不太清楚了，好可惜。"
  },
  AvgDialog_22121_Content_23 = {
    Text = "奧爾拉的手指輕輕從那幅簡筆畫上拂過，嘴角輕輕揚起。"
  },
  AvgDialog_22121_Content_24 = {
    Text = "柯蕾特……就是那個燒死你的花匠，是嗎？"
  },
  AvgDialog_22121_Content_26 = {
    Text = "小時候住在花房，雖然也很好，但是有一點點擠。我們就夢想著，有一天能在這上面的小樓裡有一間房子。"
  },
  AvgDialog_22121_Content_27 = {
    Text = "不過，直到最後也沒有住上……"
  },
  AvgDialog_22121_Content_28 = {
    Text = "奧爾拉惋惜地望著眼前華麗的別墅，繼續向前走去。"
  },
  AvgDialog_22121_Content_29 = {
    Text = "守密人%sirormadam%，穿過這片玫瑰園，我們就快到了。"
  },
  AvgDialog_22121_Content_3 = {
    Text = "穿過西堤繁華的美第奇大道，一路向東北方向走，很快便來到了一處美麗的公寓區域。"
  },
  AvgDialog_22121_Content_30 = {
    Text = "玫瑰園？哪裡有玫瑰園……"
  },
  AvgDialog_22121_Content_31 = {
    Text = "這座宅邸的後院，曾經是開滿了玫瑰的。"
  },
  AvgDialog_22121_Content_32 = {
    Text = "是柯蕾特種的？"
  },
  AvgDialog_22121_Content_33 = {
    Text = "嗯！那時候，我們剛剛從以前的莊園被趕出來，沒有地方去……"
  },
  AvgDialog_22121_Content_34 = {
    Text = "等等！柯蕾特……我剛才看到了門牌。這裡，是伯爵夫人的花園？"
  },
  AvgDialog_22121_Content_35 = {
    Text = "你不是說，好久沒有見過花園了嘛。喏，這裡就是這個片區最漂亮的花園了。"
  },
  AvgDialog_22121_Content_36 = {
    Text = "柯蕾特，我們快走吧……要是被人發現，會很麻煩的！"
  },
  AvgDialog_22121_Content_37 = {
    Text = "不會的。你看——"
  },
  AvgDialog_22121_Content_38 = {
    Text = "她摘下一朵玫瑰，塞到了奧爾拉手裡。"
  },
  AvgDialog_22121_Content_39 = {
    Text = "啊啊啊！柯蕾特，我們要在牢裡住了……"
  },
  AvgDialog_22121_Content_4 = {
    Text = "一棟華麗如同宮殿般的別墅矗立在你們面前，分外惹眼。"
  },
  AvgDialog_22121_Content_40 = {
    Text = "沒人會在牢裡住。奧爾拉，你看那邊！"
  },
  AvgDialog_22121_Content_41 = {
    Text = "順著柯蕾特指的方向，奧爾拉看到了一個培育貴重玫瑰的花房。"
  },
  AvgDialog_22121_Content_42 = {
    Text = "花房裡放著兩張床，還有她們為數不多的行李。"
