  AvgDialog_22121_Content_51 = {
    Text = "可是……我能做什麼呢……"
  },
  AvgDialog_22121_Content_52 = {
    Text = "除了寫一些沒有人看的詩，我什麼忙也幫不上……"
  },
  AvgDialog_22121_Content_53 = {
    Text = "老實說，你的那些詩我也看不懂……不過，這也不重要。你就寫你想寫的詩就好了。"
  },
  AvgDialog_22121_Content_54 = {
    Text = "每個人都有自己生來就要做的事。我生來就是要為這個花園、為那間房子努力……"
