  AvgDialog_22121_Content_61 = {
    Text = "我只知道，如果不是因為那些詩，這一切都不會發生……"
  },
  AvgDialog_22121_Content_62 = {
    Text = "奧爾拉……"
  },
  AvgDialog_22121_Content_63 = {
    Text = "奧爾拉腦中的畫面在你眼前展開，她的哀愁似乎有實感般蔓延開，浸染著周圍的一切。"
  },
  AvgDialog_22121_Content_64 = {
    Text = "對不起！守密人%sirormadam%……我又讓你難過了……"
