  AvgDialog_23852_Content_136 = {
    Text = "怎麼樣，是不是一塗上就不疼了？"
  },
  AvgDialog_23852_Content_137 = {
    Text = "她對你滾下樓梯磕到頭這件事感到非常緊張，看你的眼神充滿了心虛。"
  },
  AvgDialog_23852_Content_139 = {
    Text = "太陽穴仍隱隱作痛，但後腦確實舒適了一些。"
  },
  AvgDialog_23852_Content_14 = {
    Text = "浪花相互推搡的聲音輕柔而規律，托著船體舒緩飄蕩，駛向未知的目的地。"
  },
  AvgDialog_23852_Content_140 = {
    Text = "你的視線忍不住移向了那處被你撞毀的“祭壇”，墨菲怕你又吐出來，早就扯了塊布把那裡蓋了起來。"
  },
  AvgDialog_23852_Content_141 = {
    Text = "此時，殷紅、灰綠的液體交融混雜，在麻布上洇出了一個詭異的形狀。像一把奇特的匕首，又像一個即將發出第一聲啼哭的嬰孩。"
