  AvgDialog_23852_Content_6 = {
    Text = "剛剛那是…夢境嗎？"
  },
  AvgDialog_23852_Content_60 = {
    Text = "我和拉蒙娜為執行調查任務離開了學校，至於剩下的……"
  },
  AvgDialog_23852_Content_61 = {
    Text = "你搖了搖頭。你不知道自己是否受到了什麼外力影響，但有一點你非常肯定：你的身體在阻止你去回憶它們。"
