  AvgDialog_23852_Content_64 = {
    Text = "雖然我想不起來到底發生了什麼，但這連結不會騙人，我們理應是站在同一陣營的——圖魯，我需要你告訴我到底發生了什麼。"
  },
  AvgDialog_23852_Content_65 = {
    Text = "圖魯身上流露出些許疲憊，他闔上了眼，似是需要一些時間整理思緒。"
  },
  AvgDialog_23852_Content_66 = {
    Text = "未曾注意到你的異樣，是余的過失。\n以人類之身被捲入如此事件，看來對你不是全無影響。"
  },
  AvgDialog_23852_Content_67 = {
    Text = "但「降神儀式」對於彌薩格守密人來說，實在是太過敏感的關鍵字。\n你正要追問下去，圖魯的觸手卻突然橫在了你身前。"
  },
  AvgDialog_23852_Content_68 = {
    Text = "有人過來了，提高戒備。"
  },
  AvgDialog_23852_Content_7 = {
    Text = "天亮了嗎……"
  },
  AvgDialog_23852_Content_70 = {
    Text = "急促的腳步中混雜了類似腳蹼拍擊地面的怪聲，腳下傳來輕微的震動，一個身影橫衝直撞地從甲板另一頭向你靠近。"
  },
  AvgDialog_23852_Content_71 = {
    Text = "咕…咕嗚……"
  },
  AvgDialog_23852_Content_73 = {
    Text = "幫幫我！！%player%！"
  },
  AvgDialog_23852_Content_74 = {
    Text = "少女衝到了你身邊，說話上氣不接下氣，卻像抓住救命稻草似地扯著你的斗篷下襬。"
  },
  AvgDialog_23852_Content_75 = {
    Text = "還…@2…@1母！@2！"
  },
  AvgDialog_23852_Content_76 = {
    Text = "這些身軀類人，卻有著水生生物特徵的敵人發出了怪異的嗚咽。聲音無序刺耳，你卻莫名領會到了他們的意思。"
  },
  AvgDialog_23852_Content_77 = {
    Text = "他們在說……“還給我們”？"
  },
  AvgDialog_23852_Content_78 = {
    Text = "無序的咆哮在你耳中變得更加清晰。\n只差一點，只差一點你就能聽懂他們想要什麼——"
  },
  AvgDialog_23852_Content_79 = {
    Text = "在你因此而失神的片刻，少女一腳狠狠踩在了你的皮鞋上。"
  },
  AvgDialog_23852_Content_8 = {
    Text = "每一塊骨骼都像被打碎重組，渾身泛著不合時宜的疲憊。\n太陽穴刺痛，眼睛也乾澀得如有針扎。"
  },
  AvgDialog_23852_Content_81 = {
    Text = "你就只是看著嗎！做點什麼啊！"
  },
  AvgDialog_23852_Content_82 = {
    Text = "還有你！別看著我，給本小姐專心一點！小心別被他們抓走了。"
  },
  AvgDialog_23852_Content_83 = {
    Text = "圖魯別過臉去，不再看你和少女。觸肢大力揮舞，將前仆後繼的敵人一一橫掃出船外。"
  },
  AvgDialog_23852_Content_84 = {
    Text = "還有增援，他們是衝著你來的。"
  },
  AvgDialog_23852_Content_85 = {
    Text = "少女抿了抿嘴，片刻後眼睛一亮，露出靈光一閃的神情。"
  },
  AvgDialog_23852_Content_86 = {
    Text = "去船艙裡！能暫時躲開他們。"
  },
  AvgDialog_23852_Content_87 = {
    Text = "少女自顧自往後走了幾步，你趕緊護著她跟了上去。只見她踢開幾塊木板，甲板上赫然露出了一扇地門。"
  },
  AvgDialog_23852_Content_88 = {
    Text = "暗門？！"
  },
  AvgDialog_23852_Content_89 = {
    Text = "什麼暗門？你就非得在這個節骨眼和本小姐開玩笑嗎！"
  },
  AvgDialog_23852_Content_9 = {
    Text = "嗓子感覺像剛吞了一大口伍斯特醬汁，每次呼吸都帶著令人窒息的阻塞與疼痛。"
  },
  AvgDialog_23852_Content_90 = {
    Text = "又不是沒進過船艙，別墨跡了，準備好！"
  },
  AvgDialog_23852_Content_91 = {
    Text = "圖魯沒有反對少女的計劃，在他沉默的掩護下，你和少女一起拉開了鐵門。"
  },
  AvgDialog_23852_Content_92 = {
    Text = "門洞之下，鐵質階梯向下延伸，直進不可視之處。"
  },
  AvgDialog_23852_Content_94 = {
    Text = "你沒有戰鬥能力，我有保護你的義務——啊！"
  },
  AvgDialog_23852_Content_95 = {
    Text = "少女假裝沒聽見你的嘮叨，她仗著自己身材嬌小，靈活地繞到了你身後。"
  },
  AvgDialog_23852_Content_96 = {
    Text = "——然後，狠狠一腳將你踹進了黝黑的門洞裡。"
  },
  AvgDialog_23852_Content_98 = {
    Text = "你好像摔進了一團柔軟的海草中，魚類的腥、海水的鹹一股腦衝進鼻腔，讓你本就鈍痛的腦袋感到又一陣天旋地轉。"
  },
  AvgDialog_23852_Content_99 = {
    Text = "喂！你也別撐了，快下來！"
  },
  AvgDialog_23853_Content_1 = {
    Text = "眨眼的功夫人就不見了……\n這麼找下去不是辦法。不然，還是先去找拉蒙娜……"
  },
  AvgDialog_23853_Content_3 = {
    Text = "咳……余的意思是，她身上或許有解開蹈海者之謎的鑰匙。"
  },
  AvgDialog_23853_Content_4 = {
    Text = "從她對蹈海者的熟悉程度來看，她一定知道這些人的目的。"
  },
  AvgDialog_23853_Content_6 = {
    Text = "好，接下來我會試著用精神追溯去找她。\n這是我第一次用精神追溯定位人類，不能保證奏效。"
  },
  AvgDialog_23854_Content_10 = {
    Text = "老實說，就連你的名字，都是剛剛才想起來的。"
  },
  AvgDialog_23854_Content_11 = {
    Text = "……啊！不會是把你踢下來時磕到腦袋了吧！\n可惡，怎麼會在這個節骨眼出事……"
  },
  AvgDialog_23854_Content_12 = {
    Text = "墨菲煩躁地撓了撓頭，顯然也不知道如何是好。"
  },
  AvgDialog_23854_Content_13 = {
    Text = "前因後果…解釋起來太複雜了。這裡也不是什麼很安全的地方，還是得先和其他人會合。"
  },
  AvgDialog_23854_Content_15 = {
    Text = "這艘索納尼爾號的船長們，還有拉蒙娜。"
  },
  AvgDialog_23854_Content_16 = {
    Text = "對了！你能再試試那個嗎？就是那個去精神世界裡找人的方法。"
  },
  AvgDialog_23854_Content_17 = {
    Text = "精神追溯？你不僅認識拉蒙娜、圖魯，甚至知道我能進行精神追溯……\n之前到底發生了什麼？"
  },
  AvgDialog_23854_Content_18 = {
    Text = "別磨嘰啦！你先找到拉蒙娜的位置，路上我慢慢和你解釋。"
  },
  AvgDialog_23854_Content_19 = {
    Text = "沉入精神世界的過程前所未有的痛苦，精神像從荊棘林間穿過般，處處透著細弱的疼痛。而當你終於見到熟悉的光斑時——"
  },
  AvgDialog_23854_Content_2 = {
    Text = "圖魯那傢伙說讓我們先和其他人會合…哼，他想得倒簡單。"
  },
  AvgDialog_23854_Content_20 = {
    Text = "劈啪——"
  },
  AvgDialog_23854_Content_22 = {
    Text = "神智的觸鬚剛一爬上精神空間的邊緣，就如乾枯的樹藤般根根繃斷。"
  },
  AvgDialog_23854_Content_23 = {
    Text = "劇烈到能撕裂靈魂與肉體的疼痛穿透了太陽穴，讓你倒在了墨菲面前。"
  },
  AvgDialog_23854_Content_24 = {
    Text = "誒、誒？！你別嚇我啊，別死掉啊？！"
  },
  AvgDialog_23854_Content_25 = {
    Text = "我、我沒事……"
  },
  AvgDialog_23854_Content_26 = {
    Text = "精神追溯向來是你的拿手好戲，但此時你的身體似乎在阻止你在精神世界中潛遊。"
  },
  AvgDialog_23854_Content_27 = {
    Text = "你非常肯定：將你從精神世界中驅逐出來的是自己的身體，而不是什麼其他神秘存在。"
  },
  AvgDialog_23854_Content_28 = {
    Text = "@2…咕嗚……"
  },
  AvgDialog_23854_Content_29 = {
    Text = "是蹈海者的聲音，他們找過來了！\n不能再待在這裡了，跟我來。"
  },
  AvgDialog_23854_Content_3 = {
    Text = "墨菲嘟囔著在貨艙裡轉圈圈，神色難掩焦躁。\n你深呼吸一口氣，叫住了她。"
  },
  AvgDialog_23854_Content_30 = {
    Text = "墨菲吃力地扶起你，你的重量讓她雙腿都打著抖。你見狀將重心微微偏向了船艙，這才在她的攙扶下走向船的深處……"
  },
  AvgDialog_23854_Content_31 = {
    Text = "你們停在了一扇厚重的鐵門前，門上有著詭異的凹陷和凸起。從那已經無法完全閉合的門縫中，隱約飄出燃燒的嗆味。"
  },
  AvgDialog_23854_Content_32 = {
    Text = "墨菲，我們要進去嗎？"
  },
  AvgDialog_23854_Content_33 = {
    Text = "噓，讓我聽聽……"
  },
  AvgDialog_23854_Content_34 = {
    Text = "墨菲輕手輕腳地放開了你，將耳朵貼在門上，閉眼聽了好一會兒。"
  },
  AvgDialog_23854_Content_35 = {
    Text = "好像沒有人，我們先躲進去。"
  },
  AvgDialog_23854_Content_36 = {
    Text = "在墨菲推開門前，你看了一眼門上的標籤——「動力室」。"
  },
  AvgDialog_23854_Content_37 = {
    Text = "門後沒有你想像中熱火朝天的景象：沒有肌肉緊實的工人，沒有熊熊燃燒的鍋爐，只有令人無法忽視的火星四處飛濺。"
  },
  AvgDialog_23854_Content_38 = {
    Text = "地上橫七豎八躺著無數冰涼冷硬的身體——是那些一路追趕你們的魚人怪物。"
  },
  AvgDialog_23854_Content_39 = {
    Text = "墨菲和圖魯稱呼他們為“<Yellow:蹈海者>”。"
  },
  AvgDialog_23854_Content_40 = {
    Text = "艙壁開出了巨大的孔洞，寒風爭先恐後吹進船艙。墨菲捏捏自己凍得通紅的耳垂，扶著你跨過火焰，走進了廢墟之中。"
  },
  AvgDialog_23854_Content_41 = {
    Text = "咳、咳咳咳……氣味也太難聞了。"
  },
  AvgDialog_23854_Content_42 = {
    Text = "這裡…經歷過一場惡戰？"
  },
  AvgDialog_23854_Content_43 = {
    Text = "惡戰？你就用這麼輕飄飄的詞來形容那場戰鬥嗎？"
  },
  AvgDialog_23854_Content_44 = {
    Text = "哦……說起來，你還不知道發生了什麼。"
  },
  AvgDialog_23854_Content_45 = {
    Text = "殘垣斷壁間，有什麼東西反射著醒目的光。"
  },
  AvgDialog_23854_Content_46 = {
    Text = "你還沒能看清那是什麼東西，墨菲便臉色微變，似驚恐又似悲傷。"
  },
  AvgDialog_23854_Content_47 = {
    Text = "不知道從什麼時候開始，那女人變成了現在這幅瘋瘋癲癲的樣子……"
  },
  AvgDialog_23854_Content_48 = {
    Text = "她扯了扯嘴角，一面沒章法地向你講述著“過去”，一面向著廢墟中的閃光走去。"
  },
  AvgDialog_23854_Content_49 = {
    Text = "她什麼都聽不進去，不管我怎麼求她，她都執意要舉行這場儀式……"
  },
  AvgDialog_23854_Content_5 = {
    Text = "要不還是找個角落蹲著吧……"
  },
  AvgDialog_23854_Content_50 = {
    Text = "——那閃光是一把形狀奇異的匕首，靜靜躺在火熄餘燼中。儘管匕身落滿塵埃，也能看出其鋒芒之尖銳。"
  },
  AvgDialog_23854_Content_51 = {
    Text = "明明…她曾經對我是那麼好……"
  },
  AvgDialog_23854_Content_52 = {
    Text = "墨菲凝視那把匕首片刻，突然手腳並用爬進了瓦礫堆疊的廢墟，伸手去夠那把匕首。"
  },
  AvgDialog_23854_Content_53 = {
    Text = "咕……咕嗚……"
  },
  AvgDialog_23854_Content_54 = {
    Text = "癱倒一片的蹈海者中，有一人用折斷的武器支撐身體，顫顫巍巍爬了起來，用那大到幾乎脫離眼眶的眼珠死死瞪著高處的墨菲。"
  },
  AvgDialog_23854_Content_55 = {
    Text = "為什麼…為什麼……從主祭大人身邊……為什麼？"
  },
  AvgDialog_23854_Content_56 = {
    Text = "神母，神母……咕嗚，咕嗚……！我找到了神母！"
  },
  AvgDialog_23854_Content_57 = {
    Text = "主祭大人，主祭大人！儀式將近，<Big:儀式將近！>"
  },
  AvgDialog_23854_Content_58 = {
    Text = "蹈海者的魚類下顎張大到了極致，連接上下頜的肉膜組織被拉伸到半透明。"
  },
  AvgDialog_23854_Content_59 = {
    Text = "被恐懼、希望與信仰驅使，他迸發出了難以想像的生命力。\n蹈海者猛地撞開了你，尖嘯著向動力室外衝去。"
  },
  AvgDialog_23854_Content_6 = {
    Text = "<BigShake:墨菲！我有事要告訴你！>"
  },
  AvgDialog_23854_Content_62 = {
    Text = "銳利的尖端從灰藍色胸膛穿出，液體飛濺，蹈海者轟然倒地。"
  },
  AvgDialog_23854_Content_63 = {
    Text = "墨菲不知何時守在了動力室門邊，灰綠色的稠血靜靜從手中的匕尖滴落。"
  },
  AvgDialog_23854_Content_64 = {
    Text = "那上面掛著布料的碎屑，凹陷的雕花被血肉填滿。墨菲的身體肉眼可見顫抖著，握刀的手卻格外堅定有力。"
  },
  AvgDialog_23854_Content_65 = {
    Text = "……抱歉，不能讓你走。"
  },
  AvgDialog_23854_Content_66 = {
    Text = "墨菲沉著眼，盯著匕首看了一會兒，最後擦去了其上蹈海者的鮮血。"
  },
  AvgDialog_23854_Content_67 = {
    Text = "他的反應是想要去通風報信……"
  },
  AvgDialog_23854_Content_68 = {
    Text = "墨菲靠在門邊，側身看了一眼動力室的滿目狼藉，睫毛不安地翕動。"
  },
  AvgDialog_23854_Content_69 = {
    Text = "可<Blue:彌利亞姆>難道不是已經…為什麼還不放棄……"
  },
  AvgDialog_23854_Content_7 = {
    Text = "別叫這麼大聲！萬一真的把蹈海者引來了怎麼辦！"
  },
  AvgDialog_23854_Content_70 = {
    Text = "墨菲喃喃自語般道出的名字讓你沒由來地感到一陣眩暈，你眨了眨眼，等待噁心難受的感覺過去後，才問出了心中疑問。"
  },
  AvgDialog_23854_Content_71 = {
    Text = "彌利亞姆是？"
  },
  AvgDialog_23854_Content_72 = {
    Text = "她是蹈海者…也就是這些魚人的首領。"
  },
  AvgDialog_23854_Content_73 = {
    Text = "那所謂的「神母」……"
  },
  AvgDialog_23854_Content_74 = {
    Text = "問題甫一出口，你便緊張地進行了幾次機械性吞咽。"
  },
  AvgDialog_23854_Content_75 = {
    Text = "你的身體似乎早就知道答案，潛意識卻又害怕讓你想起這個答案。"
  },
  AvgDialog_23854_Content_77 = {
    Text = "墨菲抬頭看向你，悲傷的暗流在她眼中流動。"
  },
  AvgDialog_23854_Content_79 = {
    Text = "我是被怪物寄生的可憐蟲，是異教神明重生中命定的載體。"
  },
  AvgDialog_23854_Content_8 = {
    Text = "說吧，什麼事？"
  },
  AvgDialog_23854_Content_80 = {
    Text = "我……就是蹈海者教團的「神母」。"
  },
  AvgDialog_23854_Content_81 = {
    Text = "隨著最後一個詞從墨菲口中吐出，白光伴著劇痛在眼前炸開。"
  },
  AvgDialog_23854_Content_83 = {
    Text = "身體不受控制後仰倒下，低頻的鳴音在耳邊盤繞，少女驚呼的聲音被疼痛的洪流淹沒。"
  },
  AvgDialog_23854_Content_84 = {
    Text = "白光的盡頭，若有似無的視線正注視著你。"
  },
  AvgDialog_23854_Content_85 = {
    Text = "那未知的存在似乎正在評判你，評判你那碎裂的顱骨是否有被拼合的資格，評判抽絲的靈魂是否能夠被重新編織。"
  },
  AvgDialog_23854_Content_86 = {
    Text = "你睜大著雙眼，意識從身體抽離……"
  },
  AvgDialog_23854_Content_9 = {
    Text = "我…有點搞不清楚發生什麼了。\n為什麼我會在船上，為什麼我又會認識你……"
  },
  AvgDialog_23855_Content_1 = {
    Text = "墨菲，別跑了，我們不是壞人！"
  },
  AvgDialog_23855_Content_2 = {
    Text = "哪有壞人會說自己是壞人的！"
  },
  AvgDialog_23855_Content_3 = {
    Text = "這小子都能看出符文的作用了，你們還敢說自己和蹈海者不是一夥的！"
  },
  AvgDialog_23855_Content_4 = {
    Text = "那是由古代利莫里亞語寫作的咒文，凡通曉利莫里亞語之人，沒有無法讀出符文的道理。"
  },
  AvgDialog_23855_Content_5 = {
    Text = "你還記得嗎，利莫里亞是人類史誕生前就已失落的文明。就算在彌薩格大學裡，利莫里亞相關研究論文也隻手可數。"
  },
  AvgDialog_23855_Content_7 = {
    Text = "還不快追上她。"
  },
  AvgDialog_23856_Content_1 = {
    Text = "扭曲的現實"
  },
  AvgDialog_23856_Content_10 = {
    Text = "幹、幹什麼，幹嘛突然這麼看著我？你們倆這是什麼眼神？"
  },
  AvgDialog_23856_Content_100 = {
    Text = "戈利亞…你……"
  },
  AvgDialog_23856_Content_101 = {
    Text = "為什麼……為什麼要告訴我這些？"
  },
  AvgDialog_23856_Content_102 = {
    Text = "鬱鬱寡歡可不是什麼好事，要知道，你的狀態可決定了「神」的生長。"
  },
  AvgDialog_23856_Content_103 = {
    Text = "下一個星辰正位之時在二十五年後。我估計，彌利亞姆這兩天就要來讓你沉睡了。"
  },
  AvgDialog_23856_Content_104 = {
    Text = "做點什麼你喜歡的事吧，搞破壞，對蹈海者抽鞭子，折騰你的女僕……隨便什麼都行。"
  },
  AvgDialog_23856_Content_105 = {
    Text = "戈利亞單方面中止了這場對話，毫無溫情可言地拍了拍她的發頂。"
  },
  AvgDialog_23856_Content_106 = {
    Text = "離開時，他看了一眼被墨菲扔到牆角的木雕。少女的手藝非常差，那木質底座上端坐著的形狀肥大而詭異，讓人只看一眼就心生厭煩。"
  },
  AvgDialog_23856_Content_108 = {
    Text = "戈利亞離開後，空間變得一片寂靜，牢籠中那些待宰的祭品也沒有發出絲毫聲音。"
  },
  AvgDialog_23856_Content_109 = {
    Text = "墨菲在篝火旁坐了很久，直到光芒漸弱，篝火將熄，她才如夢初醒般拍了拍自己的臉頰。"
  },
  AvgDialog_23856_Content_11 = {
    Text = "你能夠通過腳步判斷來人是戈利亞，而再之前，你的言行中已經透露出了你對彌利亞姆的熟識。"
  },
  AvgDialog_23856_Content_110 = {
    Text = "她對著身邊的牢籠狠狠踢了一腳，回想起數月前那個破壞了儀式的女人……那個憑著堅韌毅力，從彌利亞姆手下逃脫的女人。"
  },
  AvgDialog_23856_Content_113 = {
    Text = "「對不起……」\n「我……不想死……」"
  },
  AvgDialog_23856_Content_115 = {
    Text = "我也不想……就這麼結束……"
  },
  AvgDialog_23856_Content_12 = {
    Text = "你很了解「蹈海者」這個組織，你是「蹈海者」的一份子，甚至身居高位……或者說，他們就是為你而來。"
  },
  AvgDialog_23856_Content_13 = {
    Text = "你是蹈海者口中的「神母」，孕育新神的容器……是嗎？"
  },
  AvgDialog_23856_Content_15 = {
    Text = "那要如何解釋你對戈利亞、彌利亞姆的熟悉，以及你對蹈海者的逃避？"
  },
  AvgDialog_23856_Content_16 = {
    Text = "我只是……侍女……普通的侍女，在教團駐地裡，像我這樣的女孩多得數不清。"
  },
  AvgDialog_23856_Content_17 = {
    Text = "在蹈海者的群體中，人類外表應該是非常稀有的。不然憑藉他們的戰鬥力，也不會需要與提燈教會進行合作。"
  },
  AvgDialog_23856_Content_18 = {
    Text = "如果你只是一個無關緊要的人類侍女，為什麼他們會大動干戈地追捕你？"
  },
  AvgDialog_23856_Content_19 = {
    Text = "都是、這只是……"
  },
  AvgDialog_23856_Content_20 = {
    Text = "墨菲，我需要知道發生了什麼。"
  },
  AvgDialog_23856_Content_21 = {
    Text = "只有這樣，我們才有活下來的機會，我們才能幫助你。"
  },
  AvgDialog_23856_Content_25 = {
    Text = "被折斷翅膀的雛鳥，落入了黑色水潭。"
  },
  AvgDialog_23856_Content_26 = {
    Text = "主祭的絮絮禱言飄忽而堅實，狂熱的言辭穿透黑色黏液，化為利刃剖開了雛鳥的胸腔。"
  },
  AvgDialog_23856_Content_27 = {
    Text = "鮮紅色的液體從胸口上浮，在歸於平靜的黑色水面上妖冶綻放——"
  },
  AvgDialog_23856_Content_28 = {
    Text = "她卻在不斷下沉，帶著血跡的根，沉入最深處，沉入一個柔軟而陰冷的懷抱。"
  },
  AvgDialog_23856_Content_3 = {
    Text = "不用躲了，戈利亞已經走得足夠遠了。"
  },
  AvgDialog_23856_Content_31 = {
    Text = "她看到了。\n她向上看去，「母親」垂下三對眼柄，同她對視。"
  },
  AvgDialog_23856_Content_32 = {
    Text = "那是個深紅色的龐然巨物，被血液沾染的地方呈現出了透明的白。\n「母親」發出微弱螢光，暫且照亮了一方小小天地。"
  },
  AvgDialog_23856_Content_33 = {
    Text = "借著光，她看見「母親」光滑的表皮之上，大大小小分佈著數不盡的黑色傷口。"
  },
  AvgDialog_23856_Content_34 = {
    Text = "「對不起……」"
  },
  AvgDialog_23856_Content_35 = {
    Text = "黑色黏液翻湧，攪碎了灘底的平靜。"
  },
  AvgDialog_23856_Content_36 = {
    Text = "「母親」發出了一聲尖利的哀鳴，觸肢一陣翻動，將什麼東西送入了雛鳥的胸腔。"
  },
  AvgDialog_23856_Content_37 = {
    Text = "濕滑冰冷的軟體觸肢纏繞著她，黑色的池水不再堵塞她的口鼻，反而如羊水一般，托舉起了她的生命。"
  },
  AvgDialog_23856_Content_38 = {
    Text = "「對不起……」\n「我還……不想死……」"
  },
  AvgDialog_23856_Content_39 = {
    Text = "水面維持著長久的平靜，就連極地呼嘯的風，都無法讓粘稠的池水泛起漣漪。"
  },
  AvgDialog_23856_Content_4 = {
    Text = "真、真的嗎？"
  },
  AvgDialog_23856_Content_40 = {
    Text = "彌利亞姆大人，聖女會不會已經……"
  },
  AvgDialog_23856_Content_41 = {
    Text = "她於上一個<Blue:星辰正位時刻>出生，是“看得見”的孩子。"
  },
  AvgDialog_23856_Content_42 = {
    Text = "世界上，沒有人比她更值得得到神之血脈的承認。"
  },
  AvgDialog_23856_Content_43 = {
    Text = "消瘦的女人被簇擁著，站在能夠睥睨所有人的最高處。\n薄紗模糊了她的面容，即便是近侍，也無法讀出主人心中所想。"
  },
  AvgDialog_23856_Content_45 = {
    Text = "伴隨著喃喃低語，彷彿地心的能量即將噴湧而出一般，水面陡然沸騰了起來。"
  },
  AvgDialog_23856_Content_46 = {
    Text = "厚重黏稠的黑水溢出池畔，沒過眾人腳背，流淌至女人赤裸的足邊。"
  },
  AvgDialog_23856_Content_47 = {
    Text = "穿過低聲驚呼的年輕教眾，她沉默著走上黑液鋪就的道路，將雙手深深浸入了池水中——"
  },
  AvgDialog_23856_Content_48 = {Text = "——嘩"},
  AvgDialog_23856_Content_49 = {
    Text = "少女攀附於她的雙手，從池水中躍出。\n黑液順著臉部輪廓流下，像極了兩道駭人的淚痕。"
  },
  AvgDialog_23856_Content_5 = {
    Text = "沒事了，甲板上的蹈海者也跟著他走掉了。\n來，手給我，我扶你出來。"
  },
  AvgDialog_23856_Content_50 = {
    Text = "謔，還不錯嘛。看樣子，<Blue:神明>已經承認了新的<Blue:母親>。"
  },
  AvgDialog_23856_Content_51 = {
    Text = "戈利亞冷不防地出聲，語氣嘲弄，在場卻已無人在意他的譏諷。"
  },
  AvgDialog_23856_Content_52 = {
    Text = "聖女……成功了？我們成功了！"
  },
  AvgDialog_23856_Content_53 = {
    Text = "禱言此起彼伏，最終在寒冷的洞窟中調律重合，狂熱，扭曲，震耳欲聾。"
  },
  AvgDialog_23856_Content_54 = {
    Text = "彌利亞姆，如你所願，我已經完成了你所要求的事。"
  },
  AvgDialog_23856_Content_55 = {
    Text = "「祂」……已經在這裡跳動了。"
  },
  AvgDialog_23856_Content_56 = {
    Text = "不僅是墨菲，彌利亞姆也能聽見。\n兩顆節奏相異的心臟，正在少女胸腔中鼓動著。"
  },
  AvgDialog_23856_Content_57 = {
    Text = "現在，你能回答我的問題了嗎？"
  },
  AvgDialog_23856_Content_58 = {
    Text = "知無不言。"
  },
  AvgDialog_23856_Content_59 = {
    Text = "你撫養我，從最開始就是為了今天嗎？"
  },
  AvgDialog_23856_Content_6 = {
    Text = "墨菲剛一站定，圖魯的觸手就在你的默許下緊緊捆住了她的腳踝。"
  },
  AvgDialog_23856_Content_62 = {
    Text = "你是我的「聖女」，本應作為橋樑連通神之國度……在那之後，你的靈魂抑將被迎入神國。"
  },
  AvgDialog_23856_Content_63 = {
    Text = "今日之儀，是計劃之外……但，毋須驚慌。\n神誕儀式後，我將妥善保存你的魂靈，你必不會在常夜中彷徨。"
  },
  AvgDialog_23856_Content_64 = {
    Text = "說什麼靈魂、魂靈……"
  },
  AvgDialog_23856_Content_65 = {
    Text = "我的死期，從一開始就定好在所謂「星辰正位之時」了，對嗎？"
  },
  AvgDialog_23856_Content_66 = {
    Text = "彌利亞姆雙目輕闔，她不再回答問題，轉身面向陷入狂熱的教眾。\n她雙臂高舉，黑液順著肌膚紋理滑落，頭紗瞬間被染成濃重的黑色。"
  },
  AvgDialog_23856_Content_68 = {
    Text = "祂將從@1中復甦，使@2降臨！"
  },
  AvgDialog_23856_Content_69 = {
    Text = "祂將從@1中復甦，使@2降臨！"
  },
  AvgDialog_23856_Content_7 = {
    Text = "幹、幹什麼？！我知道我扔下你們單獨面對戈利亞，是我的不對……"
  },
  AvgDialog_23856_Content_70 = {
    Text = "三個月後"
  },
  AvgDialog_23856_Content_71 = {
    Text = "你可讓那女人越來越頭疼了。前幾個月不是還很乖嗎？\n怎麼，現在不願意再聽媽媽的話了？"
  },
  AvgDialog_23856_Content_72 = {
    Text = "少女瞥了一眼戈利亞，狠狠將刻刀插進木頭上，連工具帶材料扔到了一邊。"
  },
  AvgDialog_23856_Content_73 = {
    Text = "媽、媽媽？"
  },
  AvgDialog_23856_Content_74 = {
    Text = "你……從何處習得這種說法？"
  },
  AvgDialog_23856_Content_75 = {
    Text = "字典！你看，“照顧幼兒，且有感情連接的女性成人”。"
  },
  AvgDialog_23856_Content_76 = {
    Text = "不……我不會是你的媽媽。"
  },
  AvgDialog_23856_Content_77 = {
    Text = "你是教團聖女，是尊貴的命定之人……若你願意，可以直呼我的名字。"
  },
  AvgDialog_23856_Content_78 = {
    Text = "唔……彌利……亞姆？"
  },
  AvgDialog_23856_Content_79 = {
    Text = "是的，聖女。"
  },
  AvgDialog_23856_Content_8 = {
    Text = "但、但如果他是來找我的，被他抓到我就只有死路一條！我、我……"
  },
  AvgDialog_23856_Content_80 = {
    Text = "……她不是我媽媽，從來都不是。"
  },
  AvgDialog_23856_Content_81 = {
    Text = "只有提燈教會上面的傢伙知道我的來歷，我也沒有媽媽，我只是他們送給彌利亞姆的禮物。"
  },
  AvgDialog_23856_Content_82 = {
    Text = "哦？她居然連這事都告訴你了？"
  },
  AvgDialog_23856_Content_83 = {
    Text = "對一個死期已經定下的囚犯來說，知道多少秘密都無所謂了，反正所有東西都會被我帶進墳墓裡。"
  },
  AvgDialog_23856_Content_84 = {
    Text = "這也是那女人對你的補償吧。要知道，把神明移植於你的那天，我們的主祭大人可傷心得徹夜未眠。"
  },
  AvgDialog_23856_Content_85 = {
    Text = "傷心？開什麼玩笑，她不會有這種情感。"
  },
  AvgDialog_23856_Content_86 = {
    Text = "真絕情啊，小公主。\n女孩子太冷酷，可是會惹媽媽傷心的哦。"
  },
  AvgDialog_23856_Content_87 = {
    Text = "你煩不煩！都說了她不是我媽媽了！"
  },
  AvgDialog_23856_Content_88 = {
    Text = "這可不一定，你想聽故事嗎。"
  },
  AvgDialog_23856_Content_89 = {
    Text = "<BigShake:不想聽，我也不想見到你！>\n如果是特意來譏諷我的，你可以離開了！"
  },
  AvgDialog_23856_Content_90 = {
    Text = "不，你想聽。"
  },
  AvgDialog_23856_Content_91 = {
    Text = "戈利亞的語氣陡然深沉，帶著久經戰場的威儀，墨菲體內的兩顆心臟都險些因此停跳。"
  },
  AvgDialog_23856_Content_92 = {
    Text = "她突然意識到——巨人從來就不是她可以隨意把弄的玩具。\n自己只是仗著身分得寸進尺，而對方也樂於看笑話罷了。"
  },
  AvgDialog_23856_Content_93 = {
    Text = "是……是的，請說吧。"
  },
  AvgDialog_23856_Content_94 = {
    Text = "有一個神秘教會，為了血統的絕對純淨，一切婚嫁都由教首指定。那些和外面的人成婚生子的傢伙，最後都會遭到清算。"
  },
  AvgDialog_23856_Content_95 = {
    Text = "在上一次清算中，執行者帶回了一名嬰兒——能夠看見精神存在的女嬰。"
  },
  AvgDialog_23856_Content_96 = {
    Text = "女嬰……"
  },
  AvgDialog_23856_Content_97 = {
    Text = "她在母親身體下的暗格待了太久，被教徒找到時，她險些被親生母親的血嗆死。"
  },
  AvgDialog_23856_Content_98 = {
    Text = "那個碌碌無為的普通女人，這輩子最大的成就，就是生下了一個素質優秀的女兒，並試圖不讓她被教會帶走。"
  },
  AvgDialog_23856_Content_99 = {
    Text = "——多麼美妙的母女情誼啊，我都快要為之落淚了。"
  },
  AvgDialog_23857_Content_1 = {
    Text = "命運的種子"
  },
  AvgDialog_23857_Content_10 = {
    Text = "還有多久？"
  },
  AvgDialog_23857_Content_11 = {
    Text = "什麼還有多久？"
  },
  AvgDialog_23857_Content_12 = {
    Text = "神明。距離祂誕生，還有多久？"
  },
  AvgDialog_23857_Content_13 = {
    Text = "……我不知道。不如你自己確認吧，反正從你對彌利亞姆和戈利亞的態度來看，你也早就牽扯其中了吧。"
  },
  AvgDialog_23857_Content_14 = {
    Text = "墨菲沒多忸怩，乾脆地動手解起了衣服。\n隨著前襟最後一顆紐扣的解開，你們看見了少女體內的「神」。"
  },
  AvgDialog_23857_Content_15 = {
    Text = "她前襟下的軀體赫然是透明的，透明肌理拉扯著周遭的皮膚與肌肉，讓整塊胸腹腔都呈現著灰敗衰退的白色。"
  },
  AvgDialog_23857_Content_16 = {
    Text = "透明異象讓胸腔中的器官一覽無餘，你看見了一顆薄紅色的年輕心臟，以及一顆乳色的「卵」。"
  },
  AvgDialog_23857_Content_17 = {
    Text = "數不盡的細絲從「卵」中伸出，緊密地與墨菲的血管纏繞著，相互依存。"
  },
  AvgDialog_23857_Content_18 = {
    Text = "若非其存在已經擠壓到了墨菲的心臟，祂看起來甚至與透明胸腔渾然一體，不似外物。"
  },
  AvgDialog_23857_Content_19 = {
    Text = "祂混沌而安靜，刻印其上的倒三角黑紋也一同凝固，如同一尊詭異的藝術品。"
  },
  AvgDialog_23857_Content_2 = {
    Text = "蹈海者教團、被冒險隊破壞的儀式、被融蝕的前任母體……還有你體內的「神明」……"
  },
  AvgDialog_23857_Content_20 = {
    Text = "融蝕……這個東西已經被融蝕了。"
  },
  AvgDialog_23857_Content_21 = {
    Text = "看夠了沒？"
  },
  AvgDialog_23857_Content_22 = {
    Text = "抱歉……請快把衣服整理好吧。"
  },
  AvgDialog_23857_Content_23 = {
    Text = "墨菲低著頭，一邊整理著衣服一邊看向你。"
  },
  AvgDialog_23857_Content_24 = {
    Text = "你剛剛一直提到“融蝕”，指的就是祂上面那個黑色的傷口嗎？"
  },
  AvgDialog_23857_Content_25 = {
    Text = "前任容器……也就是真正孕育了這個東西的那傢伙，身上就全是這樣的痕跡。"
  },
  AvgDialog_23857_Content_26 = {
    Text = "如果不是這“融蝕”讓前任容器日漸虛弱，我也不會被……"
  },
  AvgDialog_23857_Content_27 = {
    Text = "墨菲聲音漸漸低了下去。\n她咽下了未說完的話，抬手按著自己胸口，神色晦暗。"
  },
  AvgDialog_23857_Content_28 = {
    Text = "圖魯，你也看到了那個神明的樣子。\n距離祂生長完成，還有多久？"
  },
  AvgDialog_23857_Content_29 = {
    Text = "相當康健，甚至只差最後一步了……\n只差用群星指引祂，指引祂撕開容器的身體。"
  },
  AvgDialog_23857_Content_3 = {
    Text = "艾繼絲、梅森小姐、莉莉、麗莎……迄今為止，你遇見了不少受到身體改造的人。"
  },
  AvgDialog_23857_Content_30 = {
    Text = "余很驚訝，事到如今你居然還能自如行動。"
  },
  AvgDialog_23857_Content_31 = {
    Text = "是嗎…居然已經到了這個時候……"
  },
  AvgDialog_23857_Content_32 = {
    Text = "我之所以還沒失去意識，是因為<Blue:希萊斯特>幫了我。"
  },
  AvgDialog_23857_Content_33 = {
    Text = "希萊斯特是？"
  },
  AvgDialog_23857_Content_34 = {
    Text = "墨菲看向回轉著奇異流光的天空。\n飛鳥在光幕下盤旋，光線扭曲而柔和，隔絕了外部可能的狂風暴雨。"
  },
  AvgDialog_23857_Content_35 = {
    Text = "蹈海者教團的筆記中，反復強調著<Blue:星辰正位>的重要性，降生儀式也必須在特定的時間進行，這就是那女人讓我沉睡的原因。"
  },
  AvgDialog_23857_Content_36 = {
    Text = "船長推測，祂的成長也許與天體運轉的規則有關。\n所以希萊斯特就以船為中心，製造出了這個與世隔絕的密境。"
  },
  AvgDialog_23857_Content_37 = {
    Text = "我們猜對了，自從離開了真正的天空，祂就沉寂了下來。只要在船上躲過這一次的「星辰正位之時」，也許祂就會永遠休眠下去。"
  },
  AvgDialog_23857_Content_38 = {
    Text = "正是這位希萊斯特構築出了這個密境，也是她控制著本該沉沒的索納尼爾號航行。"
  },
  AvgDialog_23857_Content_39 = {
    Text = "聽起來，她也是一名喚醒體。\n等等……她就是你口中“能幫忙找到拉蒙娜”的人？"
  },
  AvgDialog_23857_Content_4 = {
    Text = "但將<Blue:“神明”>移植進活人的身體裡？這實在是……"
  },
  AvgDialog_23857_Content_40 = {
    Text = "沒錯，這艘船上什麼東西都逃不過她的眼睛。"
  },
  AvgDialog_23857_Content_41 = {
    Text = "她肯定帶著船長躲開了蹈海者，只要我們找到她，找到你同伴的位置就是小菜一碟。"
  },
  AvgDialog_23857_Content_42 = {
    Text = "換句話說，無論我們選擇先幫你，還是先去救拉蒙娜，這位希萊斯特都是關鍵。"
  },
  AvgDialog_23857_Content_43 = {
    Text = "圖魯不再說話，只歪過頭看著你，等待你做決定。"
  },
  AvgDialog_23857_Content_44 = {
    Text = "沒錯。不管是讓這艘船回到陸地，阻止降神儀式，還是救出拉蒙娜，現在唯一的出路都是找到「希萊斯特」。"
  },
  AvgDialog_23857_Content_45 = {
    Text = "墨菲，帶路吧。\n去找船長，去找希萊斯特。"
  },
  AvgDialog_23857_Content_5 = {
    Text = "你這是什麼表情？不相信就算了，我也沒指望你一時半會能聽懂我的話。"
  },
  AvgDialog_23857_Content_6 = {
    Text = "抱歉……只是，這一切都太讓人匪夷所思了。"
  },
  AvgDialog_23857_Content_7 = {
    Text = "墨菲，能讓我看看那個……“神明”嗎？"
  },
  AvgDialog_23857_Content_8 = {
    Text = "你還說你沒有不相信！"
  },
  AvgDialog_23858_Content_10 = {
    Text = "我們在<Blue:布里爾珀特鎮>的<Blue:第三碼頭>，與未知敵人發生了遭遇戰。"
  },
  AvgDialog_23858_Content_11 = {
    Text = "正在通知最近的外勤調查員……\n德拉普爾調查員預計將於半小時內抵達第三碼頭。"
  },
  AvgDialog_23858_Content_12 = {
    Text = "半小時太久了。道路南側敵人太多，我們會嘗試從北側突破。"
  },
  AvgDialog_23858_Content_13 = {
    Text = "已通知司機至第三碼頭北側出口接應。"
  },
  AvgDialog_23858_Content_14 = {
    Text = "未知敵人？難道不是<Yellow:提燈教會>嗎？"
  },
  AvgDialog_23858_Content_15 = {
    Text = "是否錄入新敵人情報？"
  },
  AvgDialog_23858_Content_16 = {
    Text = "拜託了艾瑞卡，不是現在。"
  },
  AvgDialog_23858_Content_17 = {
    Text = "是未曾有過目擊記錄的類人生物，回去後我會呈遞報告。"
  },
  AvgDialog_23858_Content_18 = {
    Text = "%player%，保護好自己，準備突圍。"
  },
  AvgDialog_23858_Content_2 = {
    Text = "三小時前\n港口城鎮·布里爾珀特\n第三碼頭"
  },
  AvgDialog_23858_Content_3 = {
    Text = "%player%，小心身後的敵人！"
  },
  AvgDialog_23858_Content_5 = {
    Text = "監測到無預警高頻聲波，通訊自動連接。\n再一次，晚上好，守密人，拉蒙娜。"
  },
  AvgDialog_23858_Content_6 = {
    Text = "看來有人的膽子被嚇破了。"
  },
  AvgDialog_23858_Content_7 = {
    Text = "請不要對外勤人員進行不必要的語言干擾。"
  },
  AvgDialog_23858_Content_8 = {
    Text = "好吧，好吧。\n那麼，你們需要幫助嗎？"
  },
  AvgDialog_23858_Content_9 = {
    Text = "我們需要增援！"
  },
  AvgDialog_23859_Content_1 = {
    Text = "無路可逃"
  },
  AvgDialog_23859_Content_10 = {
    Text = "果然，它們沒有跟上舷梯……"
  },
  AvgDialog_23859_Content_11 = {
    Text = "拉蒙娜壓低了聲音，悄聲說道。"
  },
  AvgDialog_23859_Content_12 = {
    Text = "這些魚人被索納尼爾號擋在了外面，但不知道出於什麼原因，我們沒有被這艘船拒絕。"
  },
  AvgDialog_23859_Content_13 = {
    Text = "我們被當做了敲門磚，一旦他們也登船了，我們就會失去利用價值。"
  },
  AvgDialog_23859_Content_14 = {
    Text = "沒錯。所以……我有個主意。"
  },
  AvgDialog_23859_Content_15 = {
    Text = "你們踏上了舷梯最後一級臺階。"
  },
  AvgDialog_23859_Content_16 = {
    Text = "如同被天空親吻的飛鳥，雙眼被輕柔和煦的風拂過，入目的世界天翻地覆。"
  },
  AvgDialog_23859_Content_17 = {
    Text = "偌大的滿月消失在了天空中，極光般的光暈攪動著包圍船體的空間，投到甲板上的光斑也泛著奇異的色澤。"
  },
  AvgDialog_23859_Content_18 = {
    Text = "拉蒙娜，不太對勁！"
  },
  AvgDialog_23859_Content_19 = {
    Text = "舷梯一陣震顫，在你們順利登上甲板後，魚人們也不再繼續觀望，手腳並用地向上攀爬。"
  },
  AvgDialog_23859_Content_2 = {
    Text = "三小時前\n港口城鎮·布里爾珀特\n第三碼頭"
  },
  AvgDialog_23859_Content_20 = {
    Text = "來不及了，他們要跟上來了。"
  },
  AvgDialog_23859_Content_21 = {
    Text = "拉蒙娜全力的一劍擊碎了固定搭扣，舷梯應聲掉落，卻沒有發出哪怕半分重物落地的聲響。"
  },
  AvgDialog_23859_Content_22 = {
    Text = "心臟劇烈鼓動，船上的異象沖刷著大腦，過了好一會兒你們才找回說話的能力。"
  },
  AvgDialog_23859_Content_23 = {
    Text = "至少它們沒法從這部舷梯登船了。"
  },
  AvgDialog_23859_Content_24 = {
    Text = "這艘船上的景象……的確符合我對“幽靈船”的刻板印象。"
  },
  AvgDialog_23859_Content_25 = {
    Text = "舷梯掉下去時沒有發出聲音——說明我們可能正身處一個獨立的空間中。很有趣，不是嗎？"
  },
  AvgDialog_23859_Content_26 = {
    Text = "這是肉眼可見的<Yellow:密境>。"
  },
  AvgDialog_23859_Content_27 = {
    Text = "保護學校的迷霧由<Yellow:銀芯科技>驅動，不知道這艘船會處於哪種力量的控制之下呢？"
  },
  AvgDialog_23859_Content_28 = {
    Text = "會是喚醒體嗎？"
  },
  AvgDialog_23859_Content_29 = {
    Text = "檔案中沒有類似記錄，但從理論上看，喚醒體創造獨立空間是可行的——你想聽聽具體理論嗎？"
  },
  AvgDialog_23859_Content_3 = {
    Text = "鋼鐵銹蝕的氣味直衝鼻腔，每走一步，舷梯都會發出搖搖欲墜的呻吟。"
  },
  AvgDialog_23859_Content_30 = {
    Text = "放過我吧……"
  },
  AvgDialog_23859_Content_31 = {
    Text = "朵爾，你們聽見了嗎？"
  },
  AvgDialog_23859_Content_32 = {
    Text = "看看場合吧！"
  },
  AvgDialog_23859_Content_33 = {
    Text = "抱歉，抱歉，原諒我的好奇心吧。"
  },
  AvgDialog_23859_Content_34 = {
    Text = "朵爾，你們聽見了嗎？"
  },
  AvgDialog_23859_Content_35 = {
    Text = "拉蒙娜點點胸針，通訊器的銀色金屬表面似有流光劃過。"
  },
  AvgDialog_23859_Content_37 = {
    Text = "拉蒙娜側過身，伸手點了點你的通訊器。\n你試圖像往常一樣集中精神，但毫不奏效。"
  },
  AvgDialog_23859_Content_38 = {
    Text = "精神力就像淚水滴入了大海，歸於寂靜。"
  },
  AvgDialog_23859_Content_39 = {
    Text = "從外觀上看，通訊器沒有受損，但無法發信。"
  },
  AvgDialog_23859_Content_4 = {
    Text = "沒有進行維護修繕的痕跡，但除了陳舊以外，船體本身相對完整。\n海水侵蝕不明顯，吃水線下也沒有藤壺、牡蠣……"
  },
  AvgDialog_23859_Content_40 = {
    Text = "<Small:怎麼有這麼多東西能阻斷通信，上次在蠟像館也是……>"
  },
  AvgDialog_23859_Content_41 = {
    Text = "銀芯催生的科技不是萬能的。\n再說了，對於銀芯本身，我們的研究也還只是皮毛。"
  },
  AvgDialog_23859_Content_42 = {
    Text = "希望那些魚人別從其他地方爬上來吧……"
  },
  AvgDialog_23859_Content_43 = {
    Text = "嗯，小心周圍環境，並祈禱這艘船不會起航吧。"
  },
  AvgDialog_23859_Content_44 = {
    Text = "<Big:嗚————>"
  },
  AvgDialog_23859_Content_45 = {
    Text = "像是百靈鳥回應歌劇演員的花腔一般，綿長的汽笛回應起了拉蒙娜的祈禱。"
  },
  AvgDialog_23859_Content_48 = {
    Text = "我知道你想說什麼，但拜託了，不是現在。"
  },
  AvgDialog_23859_Content_49 = {
    Text = "我們不能跟著索納尼爾號出海，這艘船有太多疑點了。"
  },
  AvgDialog_23859_Content_5 = {
    Text = "你和拉蒙娜並肩走上了搖搖欲墜的登船舷梯，上行的道路像是陷入了雲霧一般，讓人根本看不清盡頭。"
  },
  AvgDialog_23859_Content_50 = {
    Text = "去甲板另一頭看看！我看到那邊有固定救生船的繩索，我們試著從海面上撤離。"
  },
  AvgDialog_23859_Content_51 = {
    Text = "等等……好像有什麼聲音。"
  },
  AvgDialog_23859_Content_53 = {
    Text = "類魚面孔出現在了甲板上，將你們趕上船的始作俑者們步步緊逼。"
  },
  AvgDialog_23859_Content_6 = {
    Text = "你有什麼發現？"
  },
  AvgDialog_23859_Content_7 = {
    Text = "索納尼爾號缺少沉沒幽靈船的特徵，不符合它曾在風暴中沉沒的記錄。"
  },
  AvgDialog_23859_Content_8 = {
    Text = "我會想好好調查這艘船的來龍去脈，但現在顯然不是個好時機。"
  },
  AvgDialog_23859_Content_9 = {
    Text = "她回頭看去，將你們逼上舷梯的敵人團團圍在舷梯之下，與一雙雙無神的魚眼對上了視線。"
  },
  AvgDialog_23860_Content_10 = {
    Text = "最後，是一張熟悉又陌生的臉。"
  },
  AvgDialog_23860_Content_12 = {
    Text = "乾燥的空氣與留在氣管中的海水相結合，呼吸道受到前所未有的刺激，肌肉抽動間帶出了難以抑制的咳嗽。"
  },
  AvgDialog_23860_Content_13 = {
    Text = "綠發少年微微皺眉，觸肢在他的控制下再度纏在了你身上，然後——"
  },
  AvgDialog_23860_Content_14 = {
    Text = "觸肢用恰到好處的力道收縮了數次，喉嚨中的海水與小魚在擠壓中被盡數吐出。"
  },
  AvgDialog_23860_Content_15 = {
    Text = "咳、咳……謝謝你。"
  },
  AvgDialog_23860_Content_16 = {
    Text = "無需言謝，你的聲音太大了，會將其他蹈海者引來。"
  },
  AvgDialog_23860_Content_17 = {
    Text = "……我指的是，把我從海中救上來的事。"
  },
  AvgDialog_23860_Content_18 = {
    Text = "雖然成為喚醒體之身非余所願，但彌薩格大學畢竟結束了余的萬年長眠。\n於情於理，余不會對「守密人」見死不救。"
  },
  AvgDialog_23860_Content_19 = {
    Text = "但……你不該出現在這裡，對嗎？\n這次調查任務的出行名單中，只有我和拉蒙娜。"
  },
  AvgDialog_23860_Content_2 = {
    Text = "水無止無休地灌進你的身體。\n鼻腔、耳道、咽喉、眼角…上肢所有孔洞都被海水填滿。"
  },
  AvgDialog_23860_Content_20 = {
    Text = "未經外勤行動組組長批准，且未被調查員連結前，喚醒體不被允許離開彌薩格地界。我以為你是清楚這一點的……"
  },
  AvgDialog_23860_Content_21 = {
    Text = "喚醒體圖魯，檔案編號-6291，代號「沉睡之主」。"
  },
  AvgDialog_23860_Content_22 = {
    Text = "余相信你也清楚，彌薩格大學那些所謂的“戒律”，在余面前形同虛設。"
  },
  AvgDialog_23860_Content_23 = {
    Text = "另，別用那愚蠢的代號指代余。"
  },
  AvgDialog_23860_Content_24 = {Text = "圖魯。"},
  AvgDialog_23860_Content_25 = {
    Text = "我不是審查會那些死腦筋，喚醒體於我而言不是需要銬上腳鐐的野獸。"
  },
  AvgDialog_23860_Content_26 = {
    Text = "我擔心的是，你不在外勤任務的人員名單上，未經任何人連結。\n離開彌薩格的<Yellow:黑池>太久，你會步入失控。"
  },
  AvgDialog_23860_Content_27 = {
    Text = "無礙，余不會被所謂本能掌控。"
  },
  AvgDialog_23860_Content_28 = {
    Text = "喚醒體保持著少年的形態，一言一行卻充滿了上位者的威壓。\n僅是輕飄飄撇來一督，就足以讓人渾身汗毛直立。"
  },
  AvgDialog_23860_Content_3 = {
    Text = "你的血液與海水產生了某種反應，細胞被排出軀殼，取而代之流淌在血管裡的，似乎成了粗鹽與砂礫。"
  },
  AvgDialog_23860_Content_30 = {
    Text = "——我只想知道，你在這裡做什麼？\n你常年保持沉睡，就連<Yellow:銀鑰授予儀式>上的突變也沒能讓你醒來。"
  },
  AvgDialog_23860_Content_31 = {
    Text = "可你不惜冒著失去理智的風險出現在這裡……無論發生了什麼事，對你一定意義非凡。"
  },
  AvgDialog_23860_Content_32 = {
    Text = "這裡所發生的一切，皆因余而起。\n至於細節，與你無關。"
  },
  AvgDialog_23860_Content_33 = {
    Text = "是嗎？無關到我和拉蒙娜與那名叫彌利亞姆的女人遭遇，你都難以現身搭救嗎？"
  },
  AvgDialog_23860_Content_34 = {
    Text = "余沒有向你們解釋的義務，但如有必要，余將出手相助。"
  },
  AvgDialog_23860_Content_35 = {
    Text = "圖魯三緘其口的態度幾乎要點燃你的憤怒，但現實保留了你的理性。"
  },
  AvgDialog_23860_Content_36 = {
    Text = "雙手幾度握成拳，又再度鬆開。深呼吸幾次後，你終於看向了眼前的喚醒體少年。"
  },
  AvgDialog_23860_Content_37 = {
    Text = "拉蒙娜在蹈海者的手上。圖魯，我需要你的幫助。"
  },
  AvgDialog_23860_Content_38 = {
    Text = "圖魯抬頭久久看著你的眼睛，似乎在醞釀拒絕的話語。"
  },
  AvgDialog_23860_Content_39 = {
    Text = "就在他唇邊肌肉微動，準備吐出回復時，船艙深處傳來了少女淒厲的尖叫。"
  },
  AvgDialog_23860_Content_4 = {
    Text = "它們從內部剮蹭著軀體與靈魂，肺部被液體充盈。意識隨著身體下沉，對搭檔的擔憂也被疼痛與窒息擠出了大腦……"
  },
  AvgDialog_23860_Content_40 = {
    Text = "是拉蒙娜嗎！？我們快過去看看！"
  },
  AvgDialog_23860_Content_41 = {
    Text = "還不知道有多少蹈海者登了船，你這麼毫無準備地衝進去，著實愚鈍。"
  },
  AvgDialog_23860_Content_42 = {Text = "愚鈍？"},
  AvgDialog_23860_Content_43 = {
    Text = "如果真如你所說，你不會對「守密人」見死不救的話。"
  },
  AvgDialog_23860_Content_44 = {
    Text = "圖魯，我接下來要去送死。"
  },
  AvgDialog_23860_Content_45 = {
    Text = "圖魯扶著頭未作回答，但在你轉身衝向船艙深處前，你聽見了少年若有似無的歎息。"
  },
  AvgDialog_23860_Content_6 = {
    Text = "海面被攪動的波紋撞上了耳膜，掙扎著睜開眼，什麼東西逆著光潛入了水下。"
  },
  AvgDialog_23860_Content_7 = {
    Text = "它靈活地纏上了你的腰，就像海草……不，那不是海草，而是某種柔軟，又極具韌性的肌肉……"
  },
  AvgDialog_23860_Content_9 = {
    Text = "長條形的肌肉一路向上拖拽著你，視野中出現了密境天空粉色的光，然後是下層甲板的梁木，接著是船艙中忽明忽暗的電燈。"
  },
  AvgDialog_23861_Content_1 = {
    Text = "那些醜陋的面容，僅是直視就令人感到對進化論的褻瀆。"
  },
  AvgDialog_23861_Content_2 = {
    Text = "它們相互推搡著，手中冷兵撞在一起發出刺耳的聲響。而一片混亂的正中，它們似乎簇擁著什麼存在……"
  },
  AvgDialog_23862_Content_1 = {
    Text = "可惡的傢伙，可惡可惡可惡！"
  },
  AvgDialog_23862_Content_2 = {
    Text = "蹈海者本該被索納尼爾號這個密境擋在外面的，要不是這個小黑斗篷怪人，我本來能安安心心地逃到新大陸去……"
  },
  AvgDialog_23862_Content_3 = {
    Text = "可是…他們打趴下了那麼多蹈海者……難道那傢伙真的沒有騙我？"
  },
  AvgDialog_23863_Content_1 = {
    Text = "可是…彌利亞姆什麼時候玩起了這種伎倆。\n找人來騙我回去……這不像她的風格。"
  },
  AvgDialog_23863_Content_2 = {
    Text = "墨菲？你在這裡嗎？"
  },
  AvgDialog_23863_Content_3 = {
    Text = "嘖，也太陰魂不散了吧。"
  },
  AvgDialog_23864_Content_1 = {Text = "船員"},
  AvgDialog_23864_Content_10 = {
    Text = "你都用那精神什麼的把戲去冒犯彌利亞姆了，還說什麼“知道你還活著”……海邊的死魚都該知道你們不是一夥人了。"
  },
  AvgDialog_23864_Content_11 = {
    Text = "你所謂的安全之所，是什麼地方？"
  },
  AvgDialog_23864_Content_12 = {
    Text = "別管那麼多，小點聲跟著我走就是了。"
  },
  AvgDialog_23864_Content_13 = {
    Text = "墨菲也沒關心你和圖魯有沒有跟上她，她輕車熟路地推開又一扇閘門，輕巧地鑽進了門後。"
  },
  AvgDialog_23864_Content_14 = {
    Text = "你正準備追上去時，圖魯伸出一根觸手，攔在了你和門的中間。"
  },
  AvgDialog_23864_Content_15 = {
    Text = "守密人，不可對這女孩放下戒備。"
  },
  AvgDialog_23864_Content_16 = {
    Text = "為什麼？"
  },
  AvgDialog_23864_Content_17 = {
    Text = "圖魯沒有正面解答你的疑問，反而是反問起了你。"
  },
  AvgDialog_23864_Content_19 = {
    Text = "蹈海者？指間有蹼，尾椎骨以上的部分完全魚化，保有一定智力。"
  },
  AvgDialog_23864_Content_2 = {
    Text = "墨菲帶著你們在艙室間穿行，躡手躡腳地躲避著蹈海者的搜捕。"
  },
  AvgDialog_23864_Content_20 = {
    Text = "形體流暢自然，不像雕塑家協會的手筆，那些人總是把他們的實驗品弄得一團糟。"
  },
  AvgDialog_23864_Content_21 = {
    Text = "我原本以為，它們的外貌是受<Yellow:災厄>影響後變異的結果，但在這幾次戰鬥中，我並沒有發現它們身上存在有明顯的<Yellow:融蝕痕>。"
  },
  AvgDialog_23864_Content_22 = {
    Text = "蹈海者…更像是進化論對人類開的一個愚蠢玩笑。"
  },
  AvgDialog_23864_Content_23 = {
    Text = "他們奉彌利亞姆為主祭，與其說是族群，不如說是以信仰為紐帶聚集在一起的團體。"
  },
  AvgDialog_23864_Content_24 = {
    Text = "“對人類開的一個愚蠢玩笑”，余欣賞你的比喻。"
  },
  AvgDialog_23864_Content_25 = {
    Text = "這個少女——墨菲，我們遇到她時，蹈海者在她身邊匍匐。且以她熟識彌利亞姆一事來看，她絕非普通教眾。"
  },
  AvgDialog_23864_Content_26 = {
    Text = "告訴余，在彌利亞姆的精神世界中，是否有「墨菲」存在？"
  },
  AvgDialog_23864_Content_27 = {
    Text = "你張了張嘴，但在聲帶震動前，門後傳來了小聲驚叫與含糊不清的怪聲。"
  },
  AvgDialog_23864_Content_3 = {
    Text = "我們這是去哪？"
  },
  AvgDialog_23864_Content_4 = {
    Text = "去安全的地方，去找能幫上忙的人。"
  },
  AvgDialog_23864_Content_5 = {
    Text = "你不是還有個同伴被綁走了嗎？我知道一個人，對船上所有東西都了若指掌。"
  },
  AvgDialog_23864_Content_6 = {
    Text = "先去找她，再讓她找到你同伴的位置……這樣總比你沒頭蒼蠅似的亂跑要好吧。"
  },
  AvgDialog_23864_Content_7 = {
    Text = "說起來，你現在不覺得我們是壞人了嗎？"
  },
  AvgDialog_23864_Content_8 = {
    Text = "墨菲回頭瞪了你一眼，貓似的哼了一聲。"
  },
  AvgDialog_23864_Content_9 = {
    Text = "我又不是什麼蠢貨，你和這觸手小子說的話我全部聽見了。"
  },
  AvgDialog_23865_Content_1 = {
    Text = "夠了，不過是些無足輕重之人。"
  },
  AvgDialog_23865_Content_2 = {
    Text = "靜立於敵人後排，從最開始就沉默著的身影發話了。\n那是一名成年女性，被黑紗包裹的身體在醜陋畸形的魚人中格格不入。"
  },
  AvgDialog_23865_Content_3 = {
    Text = "正位之時將至。忠誠的蹈海之人，神國之信徒，結束這場鬧劇……迎回<Blue:神母>，迎回神明的再臨。"
  },
  AvgDialog_23865_Content_4 = {
    Text = "在她的指令下，一名與周圍魚人格格不入的少年走到人前。\n他畢恭畢敬地對女人彎下了挺拔的脊背，語氣中是難掩的忠誠與自豪。"
  },
  AvgDialog_23865_Content_5 = {
    Text = "謹遵使命，彌利亞姆大人。"
  },
  AvgDialog_23866_Content_1 = {
    Text = "快看那邊！"
  },
  AvgDialog_23866_Content_10 = {
    Text = "你們要做什麼！？就憑你們還沒資格對本小姐動手動腳！有本事讓我去見彌利亞姆！"
  },
  AvgDialog_23866_Content_11 = {
    Text = "彌利亞姆……是剛剛那個女人的名字！難道這女孩和那個首領是一夥的？可這些蹈海者又為什麼會追捕她……"
  },
  AvgDialog_23866_Content_12 = {
    Text = "未等你厘清現狀，粗壯的觸手擦過你肩膀猛地衝向了蛇形蹈海者。"
  },
  AvgDialog_23866_Content_13 = {
    Text = "後者被撞了個猝不及防，但很快反應過來，吐著蛇信與圖魯的觸手纏鬥在了一起。"
  },
  AvgDialog_23866_Content_3 = {
    Text = "數名蹈海者圍成包圍圈，團團包圍著艙室的一角。他們口中吟誦著刺耳的語調，幾乎要將少女的抽泣淹沒。"
  },
  AvgDialog_23866_Content_6 = {
    Text = "領頭的蹈海者畢恭畢敬地匍匐於少女身前，其他人則用蹼狀手掌擒住了她的手腳。"
  },
  AvgDialog_23866_Content_7 = {
    Text = "那領頭者倏地直起了身，你這才看清“她”頭紗之下竟是數條飛舞的蛇頭，格外詭異。"
  },
  AvgDialog_23866_Content_8 = {
    Text = "蛇頭人在地上畫出奇異的符文，又接過蹈海者遞上的一個行囊，那裡面散發出令人作嘔的臭味。"
  },
  AvgDialog_23866_Content_9 = {
    Text = "蛇牙在行囊上撕咬開一個口子，腐爛的臟器如沙丁魚般湧了出來，盡數掉落在符文上，腐臭頓時在艙室彌漫開來。"
  },
  AvgDialog_23867_Content_1 = {
    Text = "狂徒與巨刃"
  },
  AvgDialog_23867_Content_10 = {
    Text = "可你看看我們面前是什麼。\n只是一面封死的牆壁，甚至沒有通風管能爬。"
  },
  AvgDialog_23867_Content_11 = {
    Text = "我……我只是很少一個人下來而已，平常我都和船長他們待在一塊兒。"
  },
  AvgDialog_23867_Content_12 = {
    Text = "牆上有平面圖。"
  },
  AvgDialog_23867_Content_13 = {
    Text = "你什麼意思？是不相信我的記憶力嗎？"
  },
  AvgDialog_23867_Content_14 = {
    Text = "我說能找到就是能找到，船長他們一定在這邊！"
  },
  AvgDialog_23867_Content_15 = {
    Text = "我的搭檔還在等著我們的幫助。\n求你了，墨菲大人，看看平面圖吧。"
  },
  AvgDialog_23867_Content_17 = {
