  },
  AvgDialog_23880_Content_33 = {
    Text = "9：00PM\n<Red:密境坍塌>"
  },
  AvgDialog_23880_Content_35 = {
    Text = "整點的鐘聲不緊不慢地飄蕩著，一路沉到深淵的盡頭。"
  },
  AvgDialog_23880_Content_36 = {
    Text = "隨後你聽到密境破碎的聲音，像一顆心在無人察覺的遠方驟然破裂。"
  },
  AvgDialog_23880_Content_37 = {
    Text = "你還聽到你們骨頭一齊斷裂、血肉橫飛的聲音。"
