  AvgDialog_23880_Content_7 = {
    Text = "別碰它們，不然可能會被帶去意想不到的維度。"
  },
  AvgDialog_23880_Content_9 = {
    Text = "你似乎聽到宇宙深處傳來的急促脈搏聲，黑色的濃霧彷彿無窮無盡的潮起潮落。"
  },
  AvgDialog_23881_Content_1 = {
    Text = "咦……祂似乎又不見了？"
  },
  AvgDialog_23881_Content_10 = {
    Text = "我的計劃，已經被察覺了……唔！"
  },
  AvgDialog_23881_Content_11 = {
    Text = "索蕾爾發出一聲悶哼。一縷縷黏液從她手背刻著的字母中溢出，再緩緩攀上她的身體。"
  },
  AvgDialog_23881_Content_13 = {
    Text = "鋒利的小刀毫不猶豫地割斷荊棘，連帶著華麗的裙襬也被劃破，露出內裡傷痕累累的肌膚。"
  },
  AvgDialog_23881_Content_14 = {
    Text = "索蕾爾手持利刃，面沉如水，連眼睛都不眨一下。"
  },
  AvgDialog_23881_Content_15 = {
    Text = "這把刀不是朗貝爾先生的……？"
  },
  AvgDialog_23881_Content_16 = {
    Text = "是啊。我從一開始就知道他躲在外面，手裡拿著這把刀。"
