  AvgDialog_34972_Content_24 = {
    Text = "以戈利亞大人的名義，從愚者手中奪回神母！\n儀式，今夜必將舉行！"
  },
  AvgDialog_34972_Content_3 = {
    Text = "你是比那些眼睛朝天的傢伙機靈多了。\n這樣一來，倒讓我捨不得賜予你完全的深海之力了。"
