  AvgDialog_35988_Content_39 = {
    Text = "密境入口處，身穿白大褂的研究人員正不斷進出忙碌。"
  },
  AvgDialog_35988_Content_4 = {
    Text = "就在她的近旁，埋在雪裡的、掛在樹上的，是一具具已經風乾的「24」的屍體。"
  },
  AvgDialog_35988_Content_40 = {
    Text = "已經過去一天了，%player%都沒醒過來。要申請強制中斷密境嗎？"
