  AvgDialog_35988_Content_54 = {
    Text = "<Small:……在聽。>"
  },
  AvgDialog_35988_Content_56 = {
    Text = "別費功夫了，屍體和證物早就被清空了，你在這裡什麼也找不到。"
  },
  AvgDialog_35988_Content_57 = {
    Text = "是嗎。請問這是什麼？"
  },
  AvgDialog_35988_Content_58 = {
    Text = "威廉小心翼翼地用鑷子夾起一簇半透明的乾燥物質。"
  },
  AvgDialog_35988_Content_59 = {
    Text = "看上去像是某種蛇蛻。可它和這起案件有什麼關係？"
  },
  AvgDialog_35988_Content_6 = {
    Text = "她只知道@2在等她，就在冰雪和天光消融的盡頭。"
  },
  AvgDialog_35988_Content_60 = {
    Text = "已經是十二月了，怎麼會有蛇蛻？"
  },
  AvgDialog_35988_Content_61 = {Text = "嘩啦！"},
  AvgDialog_35988_Content_62 = {
    Text = "診所內室忽然傳來器材翻倒的聲音。"
  },
  AvgDialog_35988_Content_63 = {
    Text = "什麼聲音？！這裡不是早就被查封了……"
  },
  AvgDialog_35988_Content_64 = {Text = "出來。"},
  AvgDialog_35988_Content_65 = {
    Text = "不疾不徐的腳步聲由遠及近，一個異常蒼白的男人從內室中走了出來。"
  },
  AvgDialog_35988_Content_67 = {
    Text = "鄙人是伯納德醫生的同事，受上級所託，前來帶回他生前的研究資料……"
  },
  AvgDialog_35988_Content_68 = {
    Text = "男人雙眼半睜著，似乎有些困倦。他笑瞇瞇地呈上一張名片。"
  },
  AvgDialog_35988_Content_69 = {
    Text = "皇家醫學會註冊醫師，皮爾斯·@2……"
  },
  AvgDialog_35988_Content_7 = {
    Text = "<Red:不淨。不潔。不祥。>"
  },
  AvgDialog_35988_Content_70 = {
    Text = "不好意思，我們早就調查過伯納德醫生的社交圈。如果沒記錯的話，這位皮爾斯是個50多歲的老頭子。"
  },
  AvgDialog_35988_Content_71 = {
    Text = "說吧，你到底是誰？"
  },
  AvgDialog_35988_Content_72 = {
    Text = "呵呵……真不愧是審查會大人，過目不忘的本事令人嘆服。"
  },
  AvgDialog_35988_Content_73 = {
    Text = "他猛地睜開雙眼，鈷黃色的豎瞳在黑暗中閃著陰冷的光。"
  },
  AvgDialog_35988_Content_74 = {
    Text = "那就陪你們稍微玩會吧。"
  },
  AvgDialog_35988_Content_76 = {
    Text = "臉上傳來冰冷滑膩的觸感。"
  },
  AvgDialog_35988_Content_77 = {
    Text = "天花板上不知何時爬滿了蒼白的小蛇，牠們無聲地迅速蠕動，如雨點般紛紛墜落。"
  },
  AvgDialog_35988_Content_78 = {
    Text = "蛇……到處都是蛇！"
  },
  AvgDialog_35988_Content_79 = {
    Text = "天花板、地上、牆壁上……四周不知何時起爬滿了蛇，彷彿無數飄蕩在寂靜黑河中的蒼白水草。"
  },
  AvgDialog_35988_Content_8 = {
    Text = "一切不淨、不潔、不祥之根源……"
  },
  AvgDialog_35988_Content_80 = {
    Text = "呼叫小隊A-2，B-1，內有危險，請立刻就位。"
  },
  AvgDialog_35988_Content_81 = {
    Text = "威廉迅速掏出銀鑰匙，然而眼前的男人早已不知所蹤。"
  },
  AvgDialog_35988_Content_82 = {
    Text = "我知道你還在這裡。出來。"
  },
  AvgDialog_35988_Content_83 = {
    Text = "四周黏稠的空氣輕微抖動了片刻，隨後又愉悅地舒張開了。"
  },
  AvgDialog_35988_Content_84 = {
    Text = "耳畔傳來若有似無的“嘶嘶”聲，彷彿冰冷的氣流輕柔地摩擦過臉頰。"
  },
  AvgDialog_35988_Content_85 = {
    Text = "只是一點小小的見面禮，請調查員先生為我好好照顧牠們。"
  },
  AvgDialog_35989_Content_1 = {
    Text = "等待喜劇"
  },
  AvgDialog_35989_Content_10 = {
    Text = "我也看到了！你們手拉著手，頭髮飄啊飄，漂亮得像假人一樣！"
  },
  AvgDialog_35989_Content_11 = {
    Text = "噓！吵什麼吵，不許打攪大家看戲！"
  },
  AvgDialog_35989_Content_12 = {
    Text = "一個臨時搭建的舞台上，臉上塗著濃重油彩的小丑正在為大家表演節目。"
  },
  AvgDialog_35989_Content_13 = {
    Text = "相傳在很久很久以前，終北之地的雪山境內，古老河川的盡頭，沉睡著灰色的怪物~~~"
  },
  AvgDialog_35989_Content_14 = {
    Text = "大家好，我是那個怪物。<BigShake:嗷——>"
  },
  AvgDialog_35989_Content_15 = {
    Text = "<Shake:哇啊啊——>咦，那不是詹金嗎？"
  },
  AvgDialog_35989_Content_16 = {
    Text = "沒人知道怪物的來歷和名稱，除了牠的好胃口——每年冬季，居住在雪山腳下的居民都會將美食好酒裝進籃子……"
  },
  AvgDialog_35989_Content_17 = {
    Text = "點上一支銀色蠟燭，將籃子放在離家最近的河裡，這樣怪物就能收到人們的祭品了。"
  },
  AvgDialog_35989_Content_18 = {
    Text = "我、我有個問題！\n怪物不是住在雪山裡嗎，怎麼能收到河裡的祭品呀？"
  },
  AvgDialog_35989_Content_19 = {
    Text = "因為所有河川的盡頭都在雪山腳下，不論間隔多遠，它們終將匯聚於此。"
  },
  AvgDialog_35989_Content_2 = {
    Text = "人工密境：莉莉安濟貧院，東區"
  },
  AvgDialog_35989_Content_20 = {
    Text = "哦……然後呢？"
  },
  AvgDialog_35989_Content_21 = {
    Text = "嚼嚼嚼，俺收到大家的祭品了！俺很高興，決定報答大家！"
  },
  AvgDialog_35989_Content_22 = {
    Text = "詹金說完便低下頭，頭髮像發動機一樣狠狠晃了起來。"
  },
  AvgDialog_35989_Content_23 = {
    Text = "別晃啦，跳蚤全都掉出來了……咦，下雪了？"
  },
  AvgDialog_35989_Content_24 = {
    Text = "嗚哇，真的下雪了！"
  },
  AvgDialog_35989_Content_25 = {
    Text = "銀色紙片製成的雪花紛揚落下。艾繼絲躲在你們身後，悄悄撒著小紙片。"
  },
  AvgDialog_35989_Content_26 = {
    Text = "<Small:噓……這位大人，請假裝沒有看到艾繼絲……>"
  },
  AvgDialog_35989_Content_27 = {
    Text = "不一會兒，各色蠟燭悄然亮起，孩子們的小臉被溫暖的橘色光暈輕輕籠罩。"
  },
  AvgDialog_35989_Content_28 = {
    Text = "後來啊，每年第一場雪落下的時候，河上都會漂來銀色的蠟燭，還有裝滿禮物的籃子。"
  },
  AvgDialog_35989_Content_30 = {
    Text = "裝滿禮物的籃子來囉！！"
  },
  AvgDialog_35989_Content_31 = {
    Text = "莎拉笑瞇瞇地推著小餐車走了出來。"
  },
  AvgDialog_35989_Content_32 = {
    Text = "哇啊啊！！李子布丁、鮭魚沙拉、還有……還有烤乳豬！！"
  },
  AvgDialog_35989_Content_33 = {
    Text = "等等。開飯前應該說什麼？"
  },
  AvgDialog_35989_Content_34 = {
    Text = "孩子們相視一笑，齊刷刷回答——"
  },
  AvgDialog_35989_Content_35 = {
    Text = "<BigShake:銀霜節快樂——！！>"
  },
  AvgDialog_35989_Content_36 = {
    Text = "原來銀霜節背後還有這樣的傳說，我還是第一次聽到。"
  },
  AvgDialog_35989_Content_37 = {
    Text = "<Gray:梅森小姐的密境就像是做夢一樣，可以隨意穿梭在不同的場景，沒人會對我的出現產生任何疑問。>"
  },
  AvgDialog_35989_Content_38 = {
    Text = "<Gray:所有的場景和人物都能隨意組合，現實中這樣的景象恐怕從未出現過……>"
  },
  AvgDialog_35989_Content_39 = {
    Text = "<Gray:或許這也是梅森小姐內心深處的願望？>"
  },
  AvgDialog_35989_Content_4 = {
    Text = "實在抱歉，%player%%sirormadam%！我最近似乎胖了一些……"
  },
  AvgDialog_35989_Content_40 = {
    Text = "梅森小姐，你不去加入他們嗎？"
  },
  AvgDialog_35989_Content_41 = {
    Text = "你指了指不遠處。孩子們依舊圍在小丑周圍，聽她講那些華麗奇詭的故事。"
  },
  AvgDialog_35989_Content_42 = {
    Text = "我是個無趣的傢伙，講出來的笑話只會叫人犯睏。"
  },
  AvgDialog_35989_Content_43 = {
    Text = "嗚嗚嗚……"
  },
  AvgDialog_35989_Content_44 = {
    Text = "梅森姐姐，詹金她、她欺負我……！"
  },
  AvgDialog_35989_Content_45 = {
    Text = "哼，打不過就告狀，羞死了！誰叫你剛才說老子身上有跳蚤！"
  },
  AvgDialog_35989_Content_46 = {
    Text = "噓——麥克是勇敢的小騎士，小騎士是不可以哭的哦。"
  },
  AvgDialog_35989_Content_47 = {
    Text = "梅森輕輕拭去小麥克的眼淚鼻涕，輕聲哄著抽噎的男孩。"
  },
  AvgDialog_35989_Content_48 = {
    Text = "梅森姐姐，小熊波比的眼睛不見了……"
  },
  AvgDialog_35989_Content_49 = {
    Text = "艾繼絲攥著娃娃也走了過來。"
  },
  AvgDialog_35989_Content_5 = {
    Text = "<Shake:只有一些嗎？梅森小姐，麻煩先從我身上下、下來……>"
  },
  AvgDialog_35989_Content_50 = {
    Text = "給我看看……哎呀，好像真的丟了。晚上姐姐給你縫一個新的好不好？"
  },
  AvgDialog_35989_Content_53 = {
    Text = "哼，每次都這樣，就知道麻煩我姐姐！"
  },
  AvgDialog_35989_Content_54 = {
    Text = "可是梅森小姐也很高興呀，我可很少見她這樣。"
  },
  AvgDialog_35989_Content_55 = {
    Text = "莎拉坐在你身邊，雙手托腮，笑吟吟地看著被孩子們團團圍住的梅森。"
  },
  AvgDialog_35989_Content_56 = {
    Text = "被人需要也是一種幸福哦。"
  },
  AvgDialog_35989_Content_58 = {
    Text = "漸漸地，圍在梅森身邊的孩子越來越多，小丑反倒成了被冷落的那個。"
  },
  AvgDialog_35989_Content_59 = {
    Text = "還、還有人想聽故事嗎？在很久很久以前……"
  },
  AvgDialog_35989_Content_6 = {
    Text = "咦，這是進入新的密境了？"
  },
  AvgDialog_35989_Content_61 = {
    Text = "夜深了，孩子們悉數回到房間，濟貧院再度回歸往日的寧靜。"
  },
  AvgDialog_35989_Content_63 = {
    Text = "只留下獨自收拾殘局的小丑，以及陪伴它的孤獨倒影。"
  },
  AvgDialog_35989_Content_64 = {
    Text = "小丑搖頭晃腦地念叨著，望向一旁角落的陰影。"
  },
  AvgDialog_35989_Content_65 = {
    Text = "真叫人悲傷啊，看官您說呢？"
  },
  AvgDialog_35989_Content_67 = {
    Text = "我啊，早就聽說過你了：大名鼎鼎的「殺手24」，來去無蹤，以獵殺人格為樂。"
  },
  AvgDialog_35989_Content_68 = {
    Text = "被你盯上的人格，活不過三天——<BigShake:嗚哇！>"
  },
  AvgDialog_35989_Content_69 = {
    Text = "真叫人聞風喪膽！可眼前的小丑既不害怕也不閃躲，這是為什麼呢？"
  },
  AvgDialog_35989_Content_7 = {
    Text = "你們是天使嗎？"
  },
  AvgDialog_35989_Content_70 = {
    Text = "哼，裝神弄鬼。"
  },
  AvgDialog_35989_Content_71 = {
    Text = "小丑捧腹大笑，眼裡閃過一絲微光。"
  },
  AvgDialog_35989_Content_72 = {
    Text = "因為殺手不知道，那些劣等的、不穩定的人格連一天都活不下去。"
  },
  AvgDialog_35989_Content_73 = {
    Text = "它們從無數偶然的瞬間裡誕生，完成既定的使命後，就該永遠消失了。"
  },
  AvgDialog_35989_Content_74 = {
    Text = "「小丑24」的使命是什麼呢？當然是在銀霜節這天，把快樂帶給詹金，帶給大家。"
  },
  AvgDialog_35989_Content_75 = {
    Text = "小丑綻開一個大大的笑容，臉上的油彩化作一點點金色的星光。"
  },
  AvgDialog_35989_Content_76 = {
    Text = "現在我已經超額完成任務啦，是時候回去囉~"
  },
  AvgDialog_35989_Content_77 = {
    Text = "回去哪裡？"
  },
  AvgDialog_35989_Content_78 = {
    Text = "當然是回到我們<Yellow:誕生伊始>的地方。"
  },
  AvgDialog_35989_Content_79 = {
    Text = "告訴你一個秘密吧：每個人格都是遊蕩世間的浮萍，重歸完整是我們共同的願望。"
  },
  AvgDialog_35989_Content_8 = {
    Text = "女孩眨巴著大眼睛望著你們，指了指頭頂被你們砸穿的大洞。"
  },
  AvgDialog_35989_Content_80 = {
    Text = "一同歡笑，一同哭泣，一同感受來自詹金的愛與信任……"
  },
  AvgDialog_35989_Content_81 = {
    Text = "呵呵，你還有臉提起詹金。知道我的使命是什麼嗎？"
  },
  AvgDialog_35989_Content_82 = {
    Text = "<Red:殺了所有妄圖不勞而獲的傢伙。一個不留。>"
  },
  AvgDialog_35989_Content_84 = {
    Text = "漆黑的夜空中，群鴉四起，紛紛振翅飛離樹梢。"
  },
  AvgDialog_35989_Content_85 = {
    Text = "這是一個寧靜的冬夜。"
  },
  AvgDialog_35989_Content_9 = {
    Text = "艾繼絲都看到了，你們從天上飛下來的。"
  },
  AvgDialog_35990_Content_1 = {
    Text = "金色賦格"
  },
  AvgDialog_35990_Content_10 = {
    Text = "你們已分開太久。"
  },
  AvgDialog_35990_Content_12 = {
    Text = "這好像還是我第一次夢到以前的事。"
  },
  AvgDialog_35990_Content_13 = {
    Text = "你捂住頭，意識彷彿被無形的線牽引著，將你帶離床榻。"
  },
  AvgDialog_35990_Content_14 = {
    Text = "隨後你推開窗，見到了新年的第一場大雪。"
  },
  AvgDialog_35990_Content_15 = {
    Text = "喲呵，下雪了！！"
  },
  AvgDialog_35990_Content_16 = {
    Text = "孩童興奮的喊叫聲迴盪在寂靜的夜空中，伴隨紛亂的腳步聲，濟貧院的孩子們在樓下齊聚一堂。"
  },
  AvgDialog_35990_Content_18 = {
    Text = "艾繼絲想堆個雪人，像小熊波比那樣的。"
  },
  AvgDialog_35990_Content_19 = {
    Text = "這有什麼難的，我來——"
  },
  AvgDialog_35990_Content_2 = {
    Text = "你做了一個很長很長的夢。"
  },
  AvgDialog_35990_Content_20 = {
    Text = "噹噹噹！快看看本大爺的傑作！"
  },
  AvgDialog_35990_Content_21 = {
    Text = "唔……它好像和小熊波比長得不太一樣。它、它……"
  },
  AvgDialog_35990_Content_22 = {
    Text = "它好像一條狗啊！哈巴狗！"
  },
  AvgDialog_35990_Content_24 = {
    Text = "胡、胡說！哪裡像狗了！"
  },
  AvgDialog_35990_Content_26 = {
    Text = "孩童們嬉笑著穿梭在巷道裡。梅森不知何時早已醒來，和你並肩站著。"
  },
  AvgDialog_35990_Content_27 = {
    Text = "她伸出手，用掌心托住幾片溫柔的雪花。"
  },
  AvgDialog_35990_Content_28 = {
    Text = "雪花安靜地躺在她的手心，很快化成冰涼的雪水，閃爍著金色的星光。"
  },
  AvgDialog_35990_Content_29 = {
    Text = "咦，是上次見過的光……"
  },
  AvgDialog_35990_Content_30 = {
    Text = "無數星光從你們隔壁走廊的窗戶中飛出，在夜空中交匯成一條金色的光河。"
  },
  AvgDialog_35990_Content_31 = {
    Text = "它們輕盈地流淌著，一路延伸至遠方的月亮遠山。"
  },
  AvgDialog_35990_Content_32 = {
    Text = "是那位小丑女士的氣息。她離開我們了。"
  },
  AvgDialog_35990_Content_33 = {
    Text = "可我感覺不到悲傷……她似乎是自願離開的，就像回家一樣。"
  },
  AvgDialog_35990_Content_35 = {
    Text = "我也聽到了……它們想回家的願望。"
  },
  AvgDialog_35990_Content_36 = {
    Text = "這些願望是如此強烈，竟然讓我夢見了一些過去的事。"
  },
  AvgDialog_35990_Content_37 = {
    Text = "現在我已經不敢奢求回家了，能找回一點過去的記憶就滿足了。"
  },
  AvgDialog_35990_Content_38 = {
    Text = "你輕嘆一口氣，有些不好意思地揉了揉自己的頭髮。"
  },
  AvgDialog_35990_Content_39 = {
    Text = "不說這些喪氣話啦。講講你自己吧，梅森小姐。"
  },
  AvgDialog_35990_Content_4 = {
    Text = "夢裡，天空就像被撕開了一角的墓園，那些黑色的物質墨水般湧了進來。"
  },
  AvgDialog_35990_Content_40 = {
    Text = "聽說你很小就在倫蒂尼恩討生活了，現在還會想家嗎？"
  },
  AvgDialog_35990_Content_41 = {
    Text = "梅森望著樓下和小麥克打作一團的詹金，溫柔地笑了起來。"
  },
  AvgDialog_35990_Content_42 = {
    Text = "我的記性很差的。小時候，教會學校的嬤嬤就說我不是念書的料。"
  },
  AvgDialog_35990_Content_43 = {
    Text = "父母、家鄉……我都記不太清了，也不願回想。\n記憶是用來保存快樂的。"
  },
  AvgDialog_35990_Content_44 = {
    Text = "在我讀過的童話書裡，只有快樂、溫馨的地方才能被稱為家。\n我想成為詹金和布朗的家。"
  },
  AvgDialog_35990_Content_45 = {
    Text = "原來如此。\n梅森小姐，你遠比我想像的要堅強很多。"
  },
  AvgDialog_35990_Content_46 = {
    Text = "在蠟像館第一次見面的時候，你可不是這樣的。"
  },
  AvgDialog_35990_Content_47 = {
    Text = "<Gray:看來溫柯爾小姐的「靈啡肽超級加倍穩定療程」還是有點用處嘛。>"
  },
  AvgDialog_35990_Content_48 = {
    Text = "大家都在竭盡所能幫助我，我怎麼能一點改變都沒有呢？"
  },
  AvgDialog_35990_Content_49 = {
    Text = "我也希望能幫到大家。"
  },
  AvgDialog_35990_Content_5 = {
    Text = "你仰面倒在裂口下方，將心臟與大地貼到最近、最底了。"
  },
  AvgDialog_35990_Content_50 = {
    Text = "你伸了個懶腰，漫無目的地望著樓下寧靜祥和的居民區。"
  },
  AvgDialog_35990_Content_51 = {
    Text = "不知是否是你的錯覺，你似乎見到影子站在漆黑巷道的盡頭，與你們一同望著天上的光河。"
  },
  AvgDialog_35990_Content_53 = {
    Text = "是那時候的星光……"
  },
  AvgDialog_35990_Content_54 = {
    Text = "告訴你一個秘密吧：每個人格都是遊蕩世間的浮萍，歸於完整是我們共同的願望。"
  },
  AvgDialog_35990_Content_55 = {
    Text = "一同歡笑，一同哭泣，一同感受來自詹金的愛與信任……"
  },
  AvgDialog_35990_Content_56 = {
    Text = "……都是可悲的妄念罷了。"
  },
  AvgDialog_35990_Content_57 = {
    Text = "風輕輕吹著，雪片像溫柔的棉絮一樣在空中飛舞，沒有目的地四處飄落。"
  },
  AvgDialog_35990_Content_58 = {
    Text = "星光一點點消散，你的意識似乎也隨著它們越飄越遠。"
  },
  AvgDialog_35990_Content_59 = {
    Text = "不知道下一個等著你的密境會是什麼樣的？"
  },
  AvgDialog_35990_Content_61 = {
    Text = "<Yellow:人工密境調查日誌 III>\n\n■密境編號：M-C06\n■墜落時間：洪積315年12月24日\n■墜落地點：莉莉安濟貧院"
  },
  AvgDialog_35990_Content_62 = {
    Text = "<Yellow:■調查結果>\n\n我見到了雪，以及在雪中飛舞的金色星光。\n不知為何，它們總令我想到過去。霧氣上升、光芒墜落，笑聲相繼模糊。\n這是一個寧靜的冬夜。\n\n<Yellow:新年快樂。>\n\n另：莎拉小姐做的糖霜小蛋糕很好吃。"
  },
  AvgDialog_35990_Content_7 = {
    Text = "你閉上眼，感受著地幔深處傳來的震顫。那是一種憂鬱、古老的節奏，它令你想起自己的故鄉。"
  },
  AvgDialog_35990_Content_8 = {
    Text = "不知過了多久，你聽到模糊的笑聲，有人牽起了你的手。\n你回握住這份闊別已久的溫暖。"
  },
  AvgDialog_35990_Content_9 = {
    Text = "母親。\n你還沒來得及叫出聲，眼淚卻先流了下來。"
  },
  AvgDialog_35992_Content_1 = {Text = "止於此"},
  AvgDialog_35992_Content_10 = {
    Text = "<Red:不淨。不潔。不祥。>"
  },
  AvgDialog_35992_Content_100 = {
    Text = "傷口不斷溢出金色的星光，它們脆弱地搖曳在空氣裡，最後紛紛湧入梅森體內。"
  },
  AvgDialog_35992_Content_101 = {
    Text = "我們一起……才是真正的梅森喵……"
  },
  AvgDialog_35992_Content_103 = {
    Text = "那是所有河川的盡頭，不論間隔多遠，它們終將匯聚在此。"
  },
  AvgDialog_35992_Content_104 = {
    Text = "我聽到了……它們想回家的願望。"
  },
  AvgDialog_35992_Content_105 = {
    Text = "告訴你一個秘密吧：每個人格都是遊蕩世間的浮萍，歸於完整是我們共同的願望。"
  },
  AvgDialog_35992_Content_106 = {
    Text = "梅森輕輕閉上眼，感受著星光在體內金色的循環。"
  },
  AvgDialog_35992_Content_107 = {
    Text = "她看到她的臉和臟腑，看到小丑、學者和無數張自己的臉。"
  },
  AvgDialog_35992_Content_108 = {
    Text = "臉龐倒映在破碎的鏡中，眼睛一齊朝她看了過來，無限寧靜，無限悲哀。"
  },
  AvgDialog_35992_Content_109 = {
    Text = "那是她的影子、眼淚和裂縫，也是她流淌在大地深處的骨血與肉。"
  },
  AvgDialog_35992_Content_11 = {
    Text = "我要過去……我必須過去……"
  },
  AvgDialog_35992_Content_110 = {
    Text = "她們被迫撕開她的身體，誕生、流浪，最後拖著疲憊的身軀歸來。"
  },
  AvgDialog_35992_Content_111 = {
    Text = "<Red:止於此，止於我。>"
  },
  AvgDialog_35992_Content_12 = {
    Text = "喂，別亂跑呀。我還在給你梳毛呢。\n哎哎，怎麼還咬人了！\n\n<Gray:說真的，和彌薩格的貓比起來，你姐姐算是很聽話的了……>"
  },
  AvgDialog_35992_Content_13 = {
    Text = "模糊的笑語從遠方傳來，帶著她所熟悉眷念的繾綣與溫暖，彷彿近在咫尺。"
  },
  AvgDialog_35992_Content_15 = {
    Text = "貓咪豎直身子，努力搜尋著聲音的源頭。"
  },
  AvgDialog_35992_Content_16 = {
    Text = "<Red:歸來吧。>"
  },
  AvgDialog_35992_Content_17 = {
    Text = "唔——不，我不過去喵！"
  },
  AvgDialog_35992_Content_18 = {
    Text = "詹金，我要回到詹金身邊……回到大家身邊……"
  },
  AvgDialog_35992_Content_19 = {
    Text = "滾開……<Big:滾開喵！！>"
  },
  AvgDialog_35992_Content_2 = {
    Text = "熟睡的貓咪做了很多夢。"
  },
  AvgDialog_35992_Content_20 = {
    Text = "好好好我們不碰你了。\n怎麼突然蹦出去老高，做噩夢了嗎？"
  },
  AvgDialog_35992_Content_21 = {
    Text = "「24」警覺地環顧四周，瞳孔和鼻尖不斷顫動著。"
  },
  AvgDialog_35992_Content_22 = {
    Text = "嗅嗅……有壞人，就在附近……"
  },
  AvgDialog_35992_Content_23 = {
    Text = "她飛躍而起，撲向角落。然而——"
  },
  AvgDialog_35992_Content_25 = {
    Text = "嗚嗚……"
  },
  AvgDialog_35992_Content_26 = {
    Text = "「24」趴在地上哀哀地叫著。猙獰外翻的傷口處，暗紅的鮮血緩緩流淌。"
  },
  AvgDialog_35992_Content_27 = {
    Text = "不錯，你很警覺。可惜找錯了對手。"
  },
  AvgDialog_35992_Content_28 = {
    Text = "是你？！梅森小姐呢，從剛才起就一直不見她，難道——"
  },
  AvgDialog_35992_Content_29 = {
    Text = "影子笑了一聲，將傷痕累累的梅森丟在你們面前。"
  },
  AvgDialog_35992_Content_3 = {
    Text = "午後屋簷下緩慢浮動的光斑、咕嘟嘟冒著熱氣的白粥、舊鈴鐺、彩色的糖紙……"
  },
  AvgDialog_35992_Content_30 = {
    Text = "%player%%sirormadam%……咳咳，對不起……"
  },
  AvgDialog_35992_Content_31 = {
    Text = "影子抬起腳，在梅森的傷口處慢條斯理地碾壓著。"
  },
  AvgDialog_35992_Content_33 = {
    Text = "我說過了，我會一個一個收拾你們。"
  },
  AvgDialog_35992_Content_34 = {
    Text = "伴隨梅森痛苦的呻吟，風停了，塵埃慢下呼吸，就連陽光也被定格在永恆的瞬間。"
  },
  AvgDialog_35992_Content_35 = {
    Text = "就連你身旁的詹金也宛如雕塑般靜默。"
  },
  AvgDialog_35992_Content_36 = {
    Text = "與此同時，周遭的空間猛然抖動了幾下，天空竟開始剝落。"
  },
  AvgDialog_35992_Content_37 = {
    Text = "大片的天空從高空墜落，摔得粉碎。"
  },
  AvgDialog_35992_Content_38 = {
    Text = "密境崩塌……？不，比那個還要嚴重。這是怎麼回事？！"
  },
  AvgDialog_35992_Content_39 = {
    Text = "影子冷笑著踢了踢腳下奄奄一息的梅森。"
  },
  AvgDialog_35992_Content_40 = {
    Text = "你還不知道吧？這傢伙算是我們的<Yellow:主人格>，她如果死了，這裡就要天下大亂了。"
  },
  AvgDialog_35992_Content_41 = {
    Text = "那你這樣做無異於自殺。為什麼？"
  },
  AvgDialog_35992_Content_42 = {
    Text = "這是一個弱肉強食的世界，沒人規定主人格必須由她來做。\n我說得對嗎，梅森小姐？"
  },
  AvgDialog_35992_Content_43 = {
    Text = "別傷害%player%%sirormadam%……%heorshe%是拯救詹金的恩人……"
  },
  AvgDialog_35992_Content_44 = {
    Text = "呵呵……弱小、無能的懦夫。"
  },
  AvgDialog_35992_Content_45 = {
    Text = "那些人拙劣的謊言，你沒察覺。"
  },
  AvgDialog_35992_Content_46 = {
    Text = "手術刀切開你的身體，你不掙扎。"
  },
  AvgDialog_35992_Content_47 = {
    Text = "被逼迫著幫他們做事，你不反抗。"
  },
  AvgDialog_35992_Content_48 = {
    Text = "眼見最親愛的家人走入濟貧院，你不阻攔。"
  },
  AvgDialog_35992_Content_5 = {
    Text = "咦，這是什麼地方？"
  },
  AvgDialog_35992_Content_50 = {
    Text = "最後，你連身為“姐姐”的職責都沒做到。"
  },
  AvgDialog_35992_Content_52 = {
    Text = "記憶全部都被你像丟垃圾一樣丟給了我們。你行走於校園之中、陽光之下，放任我們在黑暗的意識裡咀嚼痛苦。"
  },
  AvgDialog_35992_Content_53 = {
    Text = "你才是讓所有人陷入痛苦的根源。\n事到如今，你想要來約束我？"
  },
  AvgDialog_35992_Content_54 = {
    Text = "<Red:你不配使用這具身體。>"
  },
  AvgDialog_35992_Content_55 = {
    Text = "配與不配，不是你說了算——唔！！"
  },
  AvgDialog_35992_Content_56 = {
    Text = "你跪倒在地，感到一陣天旋地轉。另一頭，影子呼吸平穩，朝你們緩緩走來。"
  },
  AvgDialog_35992_Content_57 = {
    Text = "不行……現在我連站穩都做不到，得先平定主人格的精神。"
  },
  AvgDialog_35992_Content_58 = {
    Text = "你爬到梅森身邊，握住她的手。"
  },
  AvgDialog_35992_Content_59 = {
    Text = "梅森小姐，別受她影響——"
  },
  AvgDialog_35992_Content_6 = {
    Text = "詹金——喵嗚——喵嗚——"
  },
  AvgDialog_35992_Content_60 = {
    Text = "是我…太軟弱了嗎……"
  },
  AvgDialog_35992_Content_61 = {
    Text = "如果我是更堅強一點的人……"
  },
  AvgDialog_35992_Content_62 = {
    Text = "如果是她的話，今天的梅森一定會有不一樣的結局……"
  },
  AvgDialog_35992_Content_63 = {
    Text = "呵呵，痛苦嗎？把你現在的痛苦再乘以十倍、百倍，就是我們的感受！"
  },
  AvgDialog_35992_Content_64 = {
    Text = "沒錯，沒錯，沒錯。"
  },
  AvgDialog_35992_Content_65 = {
    Text = "你不配使用這具身體，身體，身，身，身。"
  },
  AvgDialog_35992_Content_66 = {
    Text = "對不起，對不起對不起對不起……"
  },
  AvgDialog_35992_Content_68 = {Text = "喵嗚。"},
  AvgDialog_35992_Content_69 = {
    Text = "受傷的貓咪挪到梅森身旁，輕輕舔著她流血的傷口。"
  },
  AvgDialog_35992_Content_7 = {
    Text = "細弱的貓叫聲很快湮沒在風雪之中。\n雄偉貧瘠的山脈聳立前方，將朦朧泛藍的光線灑向大地。"
  },
  AvgDialog_35992_Content_70 = {
    Text = "隨後她又低下頭，窸窸窣窣地解著什麼。"
  },
  AvgDialog_35992_Content_71 = {
    Text = "給你，別哭喵嗚。"
  },
  AvgDialog_35992_Content_72 = {
    Text = "一片虛無之中，有什麼東西被塞進了手心。"
  },
  AvgDialog_35992_Content_73 = {
    Text = "一段柔軟、冰涼的織物，一端墜著鏽跡斑斑的鈴鐺。"
  },
  AvgDialog_35992_Content_74 = {
    Text = "沒有任何一個「24」是多餘的，因為……"
  },
  AvgDialog_35992_Content_75 = {
    Text = "你是聰明機敏的學者"
  },
  AvgDialog_35992_Content_76 = {
    Text = "羅傑斯大人。如果我贏了，您能答應我一個請求嗎？"
  },
  AvgDialog_35992_Content_77 = {
    Text = "您的蠟像群組不是還需要一個模特嗎？我可以做您的模特。"
  },
  AvgDialog_35992_Content_78 = {
    Text = "<Gray:《春》是羅傑斯計劃在博覽會上登台亮相的作品，只要能入選模特，就能增加曝光率，才能被更多人看到。>"
  },
  AvgDialog_35992_Content_80 = {
    Text = "你是大家的開心果"
  },
  AvgDialog_35992_Content_81 = {
    Text = "相傳在很久很久以前，終北之地的雪山境內，古老河川的盡頭，沉睡著灰色的怪物~~~"
  },
  AvgDialog_35992_Content_82 = {
    Text = "大家好，我是那個怪物。<Shake:嗷——>"
  },
  AvgDialog_35992_Content_84 = {
    Text = "你是招人喜愛的貓咪"
  },
  AvgDialog_35992_Content_85 = {
    Text = "困死了啊嗚……"
  },
  AvgDialog_35992_Content_86 = {
    Text = "咕嚕咕嚕……"
  },
  AvgDialog_35992_Content_87 = {
    Text = "真的發出了和貓咪一樣咕嚕聲啊……和彌薩格校園裡的那些貓一樣。"
  },
  AvgDialog_35992_Content_88 = {
    Text = "喂，你笑什麼！"
  },
  AvgDialog_35992_Content_89 = {
    Text = "她現在看起來很快樂，真的像隻無憂無慮的小貓了。"
  },
  AvgDialog_35992_Content_9 = {
    Text = "她聞到了聲音。它們混浮在空中，無字無節，如同母親溫柔的呼喚。"
  },
  AvgDialog_35992_Content_90 = {
    Text = "是啊……她們都是很好的「24」。\n相比之下，我什麼用都沒有……"
  },
  AvgDialog_35992_Content_91 = {
    Text = "你輕輕搖了搖頭。"
  },
  AvgDialog_35992_Content_92 = {
    Text = "恰恰相反，你比她們都要堅強勇敢，因為——"
  },
  AvgDialog_35992_Content_94 = {
    Text = "大人，這一切皆因我而起。"
  },
  AvgDialog_35992_Content_95 = {
    Text = "她只是個來自貧民窟的小孩罷了，什麼都不懂，不會對你們造成任何威脅……"
  },
  AvgDialog_35992_Content_96 = {
    Text = "<Shake:讓、讓她走……>"
  },
  AvgDialog_35992_Content_97 = {
    Text = "<Shake:讓她走……>"
  },
  AvgDialog_35992_Content_98 = {
    Text = "貓咪伸出毛茸茸的爪子握住梅森的手。"
  },
  AvgDialog_35992_Content_99 = {
    Text = "有勇敢的梅森，也有膽小的梅森。有聰明的梅森，也有笨笨的梅森。\n這些都沒關係的，因為——"
  },
  AvgDialog_35993_Content_1 = {
    Text = "朝聖者之歌"
  },
  AvgDialog_35993_Content_10 = {
    Text = "<Yellow:消瘦，長髮，疑似有一對以上的上肢。>"
  },
  AvgDialog_35993_Content_11 = {
    Text = "根據<Blue:《南華克街融蝕事件報告：C06》>，這裡恰好有同時符合外貌與活動範圍的生物。"
  },
  AvgDialog_35993_Content_12 = {
    Text = "將這份報告歸檔至聯合檔案庫中的，正是彌薩格大學。\n莫非，您現在想要否認它的真實性嗎？"
  },
  AvgDialog_35993_Content_13 = {
    Text = "只是稍微質疑一下目擊報告的可靠性，諸位未免有些反應過度。"
  },
  AvgDialog_35993_Content_14 = {
    Text = "有這功夫玩文字遊戲，不如來問問當事人吧。"
  },
  AvgDialog_35993_Content_15 = {
    Text = "24小姐，12月17日晚上9點15分，你在<Blue:伯納德醫生的診所>做了什麼，還記得嗎？"
  },
  AvgDialog_35993_Content_17 = {
    Text = "提醒一下：根據<Blue:伯納德醫生>的看診記錄，你是他生前最後面診的病人。"
  },
  AvgDialog_35993_Content_19 = {
    Text = "我做了什麼呢？"
  },
  AvgDialog_35993_Content_2 = {
    Text = "赤腳的朝聖者匍匐前行。"
  },
  AvgDialog_35993_Content_20 = {
    Text = "<Red:……當然是殺了他。>"
  },
  AvgDialog_35993_Content_21 = {
    Text = "24小姐？您有在聽嗎？"
  },
  AvgDialog_35993_Content_22 = {
    Text = "一下、兩下、三下……我把他那張頂好看的臉砸得粉碎，連骨頭都不剩。"
  },
  AvgDialog_35993_Content_23 = {
    Text = "血的味道留在我身上，整整一個星期都無法消散。"
  },
  AvgDialog_35993_Content_24 = {
    Text = "<Small:很遺憾，嫌疑人有迴避行為，基於《協定》中的條款，審查會有權立刻將其帶回。>"
  },
  AvgDialog_35993_Content_25 = {
    Text = "<Small:不行。24小姐和其他喚醒體不一樣，她——>"
  },
  AvgDialog_35993_Content_26 = {
    Text = "<Small:她患了歇斯底里，她是個瘋子，這點我們都清楚。可瘋子就能隨意濫殺一名備受尊敬的醫生？>"
  },
  AvgDialog_35993_Content_27 = {
    Text = "<Small:這不合理，朵兒小姐。>"
  },
  AvgDialog_35993_Content_28 = {
    Text = "<Red:我是一個殺人兇手。>"
  },
  AvgDialog_35993_Content_3 = {
    Text = "終北之地的風雪覆蓋了朝聖者的面容。她的腳趾頭早已皸裂，她的視線早已模糊，她的鮮血在雪地裡拖出長長的軌跡。"
  },
  AvgDialog_35993_Content_30 = {
    Text = "快醒醒，我針還沒扎呢！現在還不是睡覺的時候……"
  },
  AvgDialog_35993_Content_31 = {
    Text = "咦……這是……"
  },
  AvgDialog_35993_Content_32 = {
    Text = "謝天謝地，你終於醒了！"
  },
  AvgDialog_35993_Content_33 = {
    Text = "彌薩格休息室"
  },
  AvgDialog_35993_Content_34 = {
    Text = "聽說最近你的記憶混淆得厲害，我稍微解釋一下吧。"
  },
  AvgDialog_35993_Content_35 = {
    Text = "上次有關<Yellow:伯納德醫生之死>的問詢，我們和審查會鬧得很不愉快。"
  },
  AvgDialog_35993_Content_36 = {
    Text = "最後的結論是：七天。我們只有七天時間來查清楚真相。"
  },
  AvgDialog_35993_Content_37 = {
    Text = "如果我沒記錯的話，這件事發生在你被送去蠟像館之前，所以我們對此也一無所知。"
  },
  AvgDialog_35993_Content_38 = {
    Text = "檔案封存好幾個月了，天知道他們從哪裡翻出來的。再說了，在東區這樣魚龍混雜的地方調查簡直是做夢……"
  },
  AvgDialog_35993_Content_39 = {
    Text = "所以，我們決定讓%player%進入你的人工密境調查，為此需要你小小地配合我們一下……"
  },
  AvgDialog_35993_Content_4 = {
    Text = "可她依然堅定地、一往無前地向著峰頂前行。"
  },
  AvgDialog_35993_Content_40 = {
    Text = "原來如此。抱歉，我最近總是昏沉沉的……"
  },
  AvgDialog_35993_Content_41 = {
    Text = "彷彿體內正在醞釀一場可怕的狂風驟雨，身體的主人卻對此一無所知。"
  },
  AvgDialog_35993_Content_43 = {
    Text = "「我」真的是這具身體的主人嗎？"
  },
  AvgDialog_35993_Content_45 = {
    Text = "溫柯爾迅速掏出早已備好的注射器。"
  },
  AvgDialog_35993_Content_46 = {
    Text = "放心吧，我就是為此而來的。\n一針下去，你那顆混亂的腦瓜子就能清明不少……"
  },
  AvgDialog_35993_Content_47 = {
    Text = "<Shake:這樣%player%在裡面也能少受點苦畢竟誰也不知道裡面都有些什麼東西萬一遇到天災人禍可怎麼辦……>"
  },
  AvgDialog_35993_Content_48 = {
    Text = "或者像上回那樣遇到「N」這樣可怕的存在——<Big:啊！！>"
  },
  AvgDialog_35993_Content_49 = {
    Text = "溫柯爾焦慮地抓了抓頭髮，嚇得倒吸了一口氣。"
  },
  AvgDialog_35993_Content_5 = {
    Text = "是的——\n就在那片白色山脈之下，幽深的洞穴深處，棲息著一切不淨的<Red:源頭>。"
  },
  AvgDialog_35993_Content_50 = {
    Text = "<Shake:見鬼！怎麼又掉了這麼多頭髮……>"
  },
  AvgDialog_35993_Content_51 = {
    Text = "24小姐需要鎮靜，不是你的焦慮和頭髮。溫柯爾，扎完針請速速離開。"
  },
  AvgDialog_35993_Content_52 = {
    Text = "十分鐘後"
  },
  AvgDialog_35993_Content_53 = {
    Text = "現在感覺好些了嗎，24小姐？"
  },
  AvgDialog_35993_Content_54 = {
    Text = "我沒事的，只是有些頭暈……%player%呢？"
  },
  AvgDialog_35993_Content_55 = {
    Text = "已經在人工密境通道了。\n放心吧，這次我們設置的時間只有半小時，不會逗留太久。"
  },
  AvgDialog_35993_Content_56 = {
    Text = "拉蒙娜小姐呢，她沒有陪同一起調查嗎？"
  },
  AvgDialog_35993_Content_57 = {
    Text = "鑑於密境歸屬者的精神狀況不太……穩定，密境裡會出現什麼東西，我們誰也無法想像。"
  },
  AvgDialog_35993_Content_59 = {
    Text = "24沮喪地低下頭，默默攥緊了被角。"
  },
  AvgDialog_35993_Content_6 = {
    Text = "那是她的恐懼，她的夢魘。"
  },
  AvgDialog_35993_Content_60 = {
    Text = "朵兒小姐，如果我說……兇手真的是我呢？"
  },
  AvgDialog_35993_Content_61 = {
    Text = "我記得的。那天我去了診所，然後——"
  },
  AvgDialog_35993_Content_62 = {
    Text = "噓……我可不敢保證審查會沒有在這裡安插奸細哦。"
  },
  AvgDialog_35993_Content_63 = {
    Text = "朵兒回憶著茜爾維婭的模樣，努力給自己帶上一抹象徵安慰的微笑。"
  },
  AvgDialog_35993_Content_64 = {
    Text = "24小姐，你恐怕遠不如自己以為的那樣了解自己。"
  },
  AvgDialog_35993_Content_65 = {
    Text = "你看到的所謂“真相”，不一定是真的。"
  },
  AvgDialog_35993_Content_67 = {
    Text = "你來彌薩格已經好幾個月了，對於你的病症、你的經歷，我們都一無所知。"
  },
  AvgDialog_35993_Content_68 = {
    Text = "把這次密境調查當做一次重新認識你的機會吧，24小姐。"
  },
  AvgDialog_35993_Content_69 = {
    Text = "我們都想好好了解你。"
  },
  AvgDialog_35993_Content_7 = {
    Text = "也是她的歸宿。"
  },
  AvgDialog_35993_Content_8 = {
    Text = "我不認可你們所謂的“證據”。"
  },
  AvgDialog_35993_Content_9 = {
    Text = "這份所謂目擊報告，僅能證明作案的是非人生物，不能指向任何明確的個體。"
  },
  AvgDialog_35994_Content_1 = {
    Text = "影子童話"
  },
  AvgDialog_35994_Content_11 = {
    Text = "黑暗中傳來隱約的動靜，彷彿毒蛇在無人的角落吐著長信。"
  },
  AvgDialog_35994_Content_12 = {
    Text = "蛇……誰在那裡？！"
  },
  AvgDialog_35994_Content_14 = {
    Text = "匆忙的腳步聲由遠及近，長長的頭髮從你的臉上飛速掠過。"
  },
  AvgDialog_35994_Content_16 = {
    Text = "放開我……哎呀，你是誰？你和<Yellow:她>是一夥的嗎？"
  },
  AvgDialog_35994_Content_17 = {
    Text = "咦，你不認識我了嗎？"
  },
  AvgDialog_35994_Content_18 = {
    Text = "<Gray:想起來了，殺人案發生在梅森小姐進入蠟像館前，那時候我們還未相識……>"
  },
  AvgDialog_35994_Content_2 = {
    Text = "<Yellow:人工秘境調查日誌>\n\n■密境編號：M-C06\n\n■設置時間：洪積315年12月17日，9：00-9：30pm\n■設置地點：伯納德醫生的診所"
  },
  AvgDialog_35994_Content_20 = {
    Text = "不同於先前的匆忙，這次的腳步聲更加沉穩。"
  },
  AvgDialog_35994_Content_21 = {
    Text = "<Shake:來了，她來了……>"
  },
  AvgDialog_35994_Content_22 = {
    Text = "誰來了？"
  },
  AvgDialog_35994_Content_23 = {
    Text = "她……不，是“我”來了！"
  },
  AvgDialog_35994_Content_24 = {
    Text = "<Big:「我」要來殺我了！>"
  },
  AvgDialog_35994_Content_26 = {
    Text = "拳頭夾帶著風聲向你們襲來。"
  },
  AvgDialog_35994_Content_28 = {
    Text = "<Big:都給我去死！>"
  },
  AvgDialog_35994_Content_29 = {
    Text = "十分鐘後"
  },
  AvgDialog_35994_Content_3 = {
    Text = "■密境歸屬者：梅森·@2\n■密境潛入者：%player%\n■潛入目的：<Yellow:調查伯納德醫生死亡案>"
  },
  AvgDialog_35994_Content_31 = {
    Text = "請冷靜一下，這位……「24」小姐。"
  },
  AvgDialog_35994_Content_32 = {
    Text = "你站在梅森面前，勉強抵擋住影子暴烈的進攻。"
  },
  AvgDialog_35994_Content_33 = {
    Text = "再上前一步，我就不會手下留情了。"
  },
  AvgDialog_35994_Content_34 = {
    Text = "呵，看來愛哭鬼給自己找了個幫手。"
  },
  AvgDialog_35994_Content_35 = {
    Text = "昏暗的燈光勾勒出一道熟悉的纖瘦身影：長髮白裙，血一樣泛紅的虹膜。"
  },
  AvgDialog_35994_Content_36 = {
    Text = "是另一個「24」。"
  },
  AvgDialog_35994_Content_37 = {
    Text = "沒時間了……放心，我會一個一個收拾你們。"
  },
  AvgDialog_35994_Content_38 = {
    Text = "會輪到你的。"
  },
  AvgDialog_35994_Content_39 = {
    Text = "拋下一句沒頭沒尾的話，「24」乾脆俐落地離開了。"
  },
  AvgDialog_35994_Content_41 = {
    Text = "別追了，我們打不過她的……"
  },
  AvgDialog_35994_Content_42 = {
    Text = "怎麼回事，這裡怎麼會有另一個你？"
  },
  AvgDialog_35994_Content_43 = {
    Text = "我不知道……她剛才莫名其妙跑出來，說要殺了我……"
  },
  AvgDialog_35994_Content_44 = {
    Text = "那個醫生呢，也是她殺的？"
  },
  AvgDialog_35994_Content_45 = {
    Text = "原來是她殺的？！不，不僅如此……還有冬眠的蛇……"
  },
  AvgDialog_35994_Content_46 = {
    Text = "成千上萬的蛇@2殺死自己的兄弟姐妹，指頭含在嘴裡……唔……"
  },
  AvgDialog_35994_Content_47 = {
    Text = "梅森小姐？你知道自己在說什麼嗎？"
  },
  AvgDialog_35994_Content_48 = {
    Text = "說？重要的不是說了什麼，是做了什麼！這可是@2先生教我的……"
  },
  AvgDialog_35994_Content_49 = {
    Text = "梅森全然沉浸在自己的世界，嘴裡吐出一連串混亂的囈語。"
  },
  AvgDialog_35994_Content_5 = {
    Text = "黏稠的血腥氣縈繞診所，到處是散落在地的醫用器材、書籍和病例。"
  },
  AvgDialog_35994_Content_50 = {
    Text = "你……我好像在哪裡見過你……"
  },
  AvgDialog_35994_Content_53 = {
    Text = "怎麼又想起我是誰了？"
  },
  AvgDialog_35994_Content_54 = {
    Text = "你忽然覺得有些頭疼。"
  },
  AvgDialog_35994_Content_55 = {
    Text = "別急著進去，我話還沒說完呢。"
  },
  AvgDialog_35994_Content_56 = {
    Text = "24小姐的密境與拉蒙娜、索蕾爾夫人不同。她沒有穩定的人格，這一特質必然會體現在密境裡。"
  },
  AvgDialog_35994_Content_57 = {
    Text = "不同的人格之間彼此隔絕，卻又互相交融。你甚至會在裡面看到很多24。"
  },
  AvgDialog_35994_Content_58 = {
    Text = "所有的一切，人物、地點、時間……或許都不是真的。"
  },
  AvgDialog_35994_Content_59 = {
    Text = "如果都是假的，那我還有調查的必要嗎？"
  },
  AvgDialog_35994_Content_6 = {
    Text = "伯納德醫生的屍體癱倒在牆邊。他的頭部早已殘缺，再也無法辨清面容。"
  },
  AvgDialog_35994_Content_60 = {
    Text = "當然。哪怕裡面只有百分之一的真實，我們也要抓住它。"
  },
  AvgDialog_35994_Content_61 = {
    Text = "24小姐絕不是濫殺無辜的壞人，這點我們心知肚明。"
  },
  AvgDialog_35994_Content_62 = {
    Text = "都不是真的……冷靜，%player%。先明確調查目標。"
  },
  AvgDialog_35994_Content_63 = {
    Text = "你拉過梅森的手指。上面十分乾淨，沒有任何受傷或是搏鬥的痕跡。"
  },
  AvgDialog_35994_Content_64 = {
    Text = "梅森小姐，你與伯納德醫生有什麼過節嗎？"
  },
  AvgDialog_35994_Content_65 = {
    Text = "他……他給我治病，最近我總覺得身上癢癢的，很奇怪……"
  },
  AvgDialog_35994_Content_66 = {
    Text = "梅森一邊說著，若無其事地撓了撓從融蝕傷口中長出的白色眼球。"
  },
  AvgDialog_35994_Content_67 = {
    Text = "當然，她對自己的這一行為毫無自覺。"
  },
  AvgDialog_35994_Content_68 = {
    Text = "他替你治療。然後呢，你們吵起來了？"
  },
  AvgDialog_35994_Content_69 = {
    Text = "後來、後來我就什麼都想不起來了……"
  },
  AvgDialog_35994_Content_7 = {
    Text = "“30歲男性，身高6英尺，曾以優異的成績畢業於倫蒂尼恩大學醫學院……”"
  },
  AvgDialog_35994_Content_70 = {
    Text = "原來如此，我大概明白了。"
  },
  AvgDialog_35994_Content_71 = {
    Text = "<Gray:失憶是人格分裂的重要表徵。很可能是治療期間發生了什麼，導致影子人格跳出來殺死了醫生……>"
  },
  AvgDialog_35994_Content_72 = {
    Text = "<Gray:接下來只需要把下次密境時間再往回撥一個小時，看看當時都發生了什麼……>"
  },
  AvgDialog_35994_Content_73 = {
    Text = "你抬手看了看錶。"
  },
  AvgDialog_35994_Content_74 = {
    Text = "密境馬上要結束了，這次的調查先到這裡吧。"
  },
  AvgDialog_35994_Content_75 = {
    Text = "朵兒小姐恐怕多慮了，這個密境比索蕾爾夫人的簡單多了……"
  },
  AvgDialog_35994_Content_76 = {
    Text = "你伸了個懶腰，隨後蹲在梅森面前，直視著她的雙眼。"
  },
  AvgDialog_35994_Content_77 = {
    Text = "梅森小姐，你得的可不是普通的病，不是什麼拿了漂亮文憑的大夫就能醫治的。"
  },
  AvgDialog_35994_Content_78 = {
    Text = "下次記得來彌薩格找我們，明白嗎？"
  },
  AvgDialog_35994_Content_79 = {
    Text = "彌、薩、格……"
  },
  AvgDialog_35994_Content_8 = {
    Text = "“為人樂善好施，多年來一直在東區多地開展義務醫療工作……”"
  },
  AvgDialog_35994_Content_80 = {
    Text = "對，彌薩格大學。我們可是專業的。"
  },
  AvgDialog_35994_Content_83 = {
    Text = "頭頂的牆面開始一點點剝落，密境不再穩定。"
  },
  AvgDialog_35994_Content_84 = {
    Text = "再會，梅森小姐。"
  },
  AvgDialog_35994_Content_86 = {
    Text = "時間來到晚上9點30。\n冷風呼嘯而過，窗外烏鴉傳來一兩聲寂寥的鳴叫。"
  },
  AvgDialog_35994_Content_87 = {
    Text = "你依然穩穩地站在診所內，旁邊跪坐著表情懵懂的梅森。"
  },
  AvgDialog_35994_Content_88 = {
    Text = "咦……守密人%sirormadam%，您又不打算離開了嗎？"
  },
  AvgDialog_35994_Content_89 = {
    Text = "<Shake:呃，難道是設備出故障了？>"
  },
  AvgDialog_35994_Content_9 = {
    Text = "無可指摘的履歷，難怪警局和審查會如此重視。"
  },
  AvgDialog_35994_Content_90 = {
    Text = "轟隆隆——！！"
  },
  AvgDialog_35994_Content_91 = {
    Text = "下一秒，世界飛速崩塌，你墜入無底深淵。"
  },
  AvgDialog_35994_Content_93 = {
    Text = "<Yellow:人工密境調查日誌 I>\n\n■密境編號：M-C06\n■設置時間：洪積315年12月17日，9：00-9：30pm\n■設置地點：伯納德醫生的診所"
  },
  AvgDialog_35994_Content_94 = {
    Text = "<Yellow:■調查結果>\n\n——守密人失聯。"
  },
  AvgDialog_35996_Content_1 = {
    Text = "為什麼……為什麼……"
  },
  AvgDialog_35996_Content_10 = {
    Text = "為生計所困，求助無門的，是「24」。"
  },
  AvgDialog_35996_Content_11 = {
    Text = "因簡單的生活而感到幸福的，是「24」。"
  },
  AvgDialog_35996_Content_12 = {
    Text = "被雕塑家協會折磨的，也是「24」。"
  },
  AvgDialog_35996_Content_13 = {
    Text = "不…如果不是你的懦弱，我們也不會被那個醫生……"
  },
  AvgDialog_35996_Content_14 = {Text = "噓……"},
  AvgDialog_35996_Content_15 = {
    Text = "梅森輕輕捂住影子的嘴唇。她低下頭，附在影子耳邊。"
  },
  AvgDialog_35996_Content_16 = {
    Text = "告訴你一個秘密吧：<Red:那個醫生是我殺的。>"
  },
  AvgDialog_35996_Content_17 = {
    Text = "不可能。你怎麼會有這種膽量……？！"
  },
  AvgDialog_35996_Content_18 = {
    Text = "殺人不是什麼困難的事。我手邊沒有武器，所以就用手把他——"
  },
  AvgDialog_35996_Content_19 = {
    Text = "到最後我的手早已失去知覺，眼裡除了血什麼也看不到了。"
  },
  AvgDialog_35996_Content_2 = {
    Text = "影子被你們擊敗。她匍匐在地，身體向外飄出細碎的光點。"
  },
  AvgDialog_35996_Content_20 = {
    Text = "因為我必須確保他徹底死了。只要他還有一口氣在，他就一定會傷害濟貧院的孩子們，還有詹金……"
  },
  AvgDialog_35996_Content_21 = {
    Text = "他和雕塑家協會的那些人一樣，不——他比他們更加可怕……"
  },
  AvgDialog_35996_Content_22 = {
    Text = "他是一個真正的惡魔。"
  },
  AvgDialog_35996_Content_23 = {
    Text = "原來是你……竟然是你……"
  },
  AvgDialog_35996_Content_24 = {
    Text = "那時候，我又在幹什麼呢……我竟然什麼都不知道……"
  },
  AvgDialog_35996_Content_25 = {
    Text = "梅森輕輕搖了搖頭。"
  },
  AvgDialog_35996_Content_26 = {
    Text = "是你和其他「24」借給我的勇氣。"
  },
  AvgDialog_35996_Content_27 = {
    Text = "所有的「24」結合，才有了一個「梅森」。\n沒有「24」能孤立存在。"
  },
  AvgDialog_35996_Content_28 = {
    Text = "就像所有河流都將歸於一處，所有的「24」也會歸於一處……"
  },
  AvgDialog_35996_Content_29 = {
    Text = "梅森輕輕吻上影子的額頭。"
  },
  AvgDialog_35996_Content_3 = {
    Text = "如此強大的我，充滿憤怒的我……怎麼會輸給你們，輸給這個懦夫……"
  },
  AvgDialog_35996_Content_30 = {
    Text = "歸於我。"
  },
  AvgDialog_35996_Content_32 = {
    Text = "影子的身體化作點點星光。它們四散游離在梅森身邊，湧入她的肌膚。"
  },
  AvgDialog_35996_Content_33 = {
    Text = "原來如此……我明白了。"
  },
  AvgDialog_35996_Content_34 = {
    Text = "你是一切的起源，也是一切的終點……"
  },
  AvgDialog_35996_Content_35 = {
    Text = "她在溫暖的懷抱中逐漸失去了聲音。"
  },
  AvgDialog_35996_Content_36 = {
    Text = "星光似黑夜中的游螢，若隱若現，最終消失不見。"
  },
  AvgDialog_35996_Content_38 = {
    Text = "<Yellow:人工密境調查日誌 Ⅳ>\n\n■密境編號：M-C06\n■墜落時間：洪積315年12月@1日\n■墜落地點：坎伯韋爾街，東區"
  },
  AvgDialog_35996_Content_39 = {
    Text = "<Yellow:■調查結果>\n\n密境以一種平淡的方式劃上了句號。\n那以後梅森小姐的病情穩定了不少，這是令所有人都無比開心的一件事。\n\n<Yellow:我們正在逐漸接近真實的梅森小姐。>"
  },
  AvgDialog_35996_Content_4 = {
    Text = "因為……"
  },
  AvgDialog_35996_Content_40 = {
    Text = "彌薩格大學，校辦公室\n一天後"
  },
  AvgDialog_35996_Content_41 = {
    Text = "什麼，審查會撤銷控訴了？"
  },
  AvgDialog_35996_Content_42 = {
    Text = "你不在的時候，發生了很多有趣的事。他們現在忙著和市環保處的那幫人一起清理蛇患呢。"
  },
  AvgDialog_35996_Content_44 = {
    Text = "朵爾將前幾日的《倫蒂尼恩郵報》攤開舉在你面前。"
  },
  AvgDialog_35996_Content_45 = {
    Text = "“近日，已故醫生伯納德的診所忽然湧出海量不明種類的白化蛇，對當地交通住行造成了嚴重阻塞……”"
  },
  AvgDialog_35996_Content_46 = {
    Text = "“目擊證人表示，這是她此生見過最可怕的場景。若讀者您也不幸目睹了現場，歡迎致電心理醫生@2尋求幫助……”"
  },
  AvgDialog_35996_Content_47 = {
    Text = "“號碼@4……”"
  },
  AvgDialog_35996_Content_48 = {
    Text = "新聞旁還附上了照片，你似乎看到了幾個來自審查會的熟悉身影。"
  },
  AvgDialog_35996_Content_49 = {
    Text = "他們手持網兜，正在辛勤地清理著不斷湧出的小蛇們，臉上是掩飾不住的疲倦與不耐。"
  },
  AvgDialog_35996_Content_50 = {
    Text = "那個所謂的“伯納德醫生”問題很大。"
  },
  AvgDialog_35996_Content_51 = {
    Text = "我們找到了皇家醫學會的人，對方提供的照片資料和附近居民的描述完全不同。"
  },
  AvgDialog_35996_Content_52 = {
    Text = "換言之，死者盜用了這個伯納德醫生的身份。不過就目前的情況來看，這個冒牌醫生是否真的死了還猶未可知。"
  },
  AvgDialog_35996_Content_53 = {
    Text = "畢竟現場連屍體的痕跡都找不到……"
  },
  AvgDialog_35996_Content_54 = {
    Text = "12月17日，案發當日\n伯納德醫生的診所"
  },
  AvgDialog_35996_Content_55 = {
    Text = "今日的診療就到此結束了。梅森小姐，你恢復得不錯。"
  },
  AvgDialog_35996_Content_56 = {
    Text = "真的嗎？可大家都說我的病情越來越嚴重了……"
  },
  AvgDialog_35996_Content_57 = {
    Text = "我和其他人類對“嚴重”的理解恐怕不太一樣。\n給你開的幾副酊劑都按時吃了嗎？"
  },
  AvgDialog_35996_Content_58 = {
    Text = "嘩啦！！"
  },
  AvgDialog_35996_Content_59 = {
    Text = "醫生不小心碰倒了手邊的文件，泛黃的紙頁鋪灑滿地。"
  },
  AvgDialog_35996_Content_6 = {
    Text = "交給我吧。"
  },
  AvgDialog_35996_Content_60 = {
    Text = "抱歉，最近東區疫病頻發，診所內堆積的資料也越來越多——"
  },
  AvgDialog_35996_Content_61 = {
    Text = "沒關係！您可是日夜辛勞的大醫生，撿東西這點小事就交給……"
  },
  AvgDialog_35996_Content_63 = {
    Text = "手在距離文件不到2英寸的地方停住了。這是一沓身份檔案，梅森費力地從中認出了幾個還算熟悉的單詞。"
  },
  AvgDialog_35996_Content_64 = {
    Text = "實驗報告、轉運記錄……？"
  },
  AvgDialog_35996_Content_65 = {
    Text = "<Shake:這是……濟貧院失蹤的那些孩子！不，不止這些……>"
  },
  AvgDialog_35996_Content_66 = {
    Text = "就在最下方露出的一角檔案裡，詹金那張略帶倔強的面龐出現在梅森眼前。"
  },
  AvgDialog_35996_Content_67 = {
    Text = "這是你的妹妹吧？我見過她。她一直很擔心你，甚至還試圖偷溜進來。"
  },
  AvgDialog_35996_Content_68 = {
    Text = "他微微笑了笑，神色也溫柔起來。"
  },
  AvgDialog_35996_Content_69 = {
    Text = "我也曾有過許多兄弟姐妹……牠們只會害怕我、畏懼我，所以我把牠們全都吃掉了。"
  },
  AvgDialog_35996_Content_71 = {
    Text = "放心吧，梅森小姐。我沒有吃掉你的朋友，只是把他們送到了一個<Red:安全的地方>。"
  },
  AvgDialog_35996_Content_72 = {
    Text = "所以你才是這些失蹤案的罪魁禍首……"
  },
  AvgDialog_35996_Content_73 = {
    Text = "<Shake:這個笑話一點也不好笑，伯納德先生……>"
  },
  AvgDialog_35996_Content_74 = {
    Text = "伯納德先生……你是說它嗎？"
  },
  AvgDialog_35996_Content_75 = {
    Text = "男人說罷，嘴裡伸出長長的信子，上面捲著一隻血淋淋的斷指。"
  },
  AvgDialog_35996_Content_76 = {
    Text = "他的塊頭太大，我到現在都沒消化乾淨。"
  },
  AvgDialog_35996_Content_77 = {
    Text = "重新認識一下吧，我叫<Yellow:阿爾比諾>，是雕塑家協會的藥劑師。"
  },
  AvgDialog_35996_Content_79 = {
    Text = "梅森腳底一軟，重重癱倒在地。"
  },
  AvgDialog_35996_Content_8 = {
    Text = "梅森在影子身邊席地而坐，將再也無法動彈的影子抱入了懷中。"
  },
  AvgDialog_35996_Content_80 = {
    Text = "<Shake:你是壞人……你要把詹金也……>"
  },
  AvgDialog_35996_Content_81 = {
    Text = "男人扶了扶鏡框，拿出病歷唰唰地在上面記錄著。"
  },
  AvgDialog_35996_Content_82 = {
    Text = "瞳孔放大、肌體劇烈顫抖、心率加速……你現在一定害怕極了，冷嗎？"
  },
  AvgDialog_35996_Content_83 = {
    Text = "不……別過來……"
  },
  AvgDialog_35996_Content_84 = {
    Text = "很快，你就會因為腦部供血不足導致暈厥，就像其他乏味的人類一樣。"
  },
  AvgDialog_35996_Content_85 = {
    Text = "他從病歷本前抬起頭，金色的豎瞳隱約閃過一絲興奮的光。"
  },
  AvgDialog_35996_Content_86 = {
    Text = "還是說……你會有不一樣的反應？"
  },
  AvgDialog_35996_Content_87 = {
    Text = "二十分鐘後"
  },
  AvgDialog_35996_Content_88 = {
    Text = "我殺人了，我竟然殺了一個醫生……他們不會相信我的……"
  },
  AvgDialog_35996_Content_89 = {
    Text = "不對，我剛才為什麼殺了他……"
  },
  AvgDialog_35996_Content_9 = {
    Text = "因為……你沒有接受所有的「24」。"
  },
  AvgDialog_35996_Content_90 = {
    Text = "梅森如夢初醒，慌亂地離開了現場。"
  },
  AvgDialog_35996_Content_91 = {
    Text = "男人的屍體軟軟靠在牆角。他的頭早已碎裂，從中不斷滲出血水。"
  },
  AvgDialog_35996_Content_92 = {
    Text = "不知過了多久，屍體頸部忽然亮起一串黑色的咒縛。"
  },
  AvgDialog_35996_Content_93 = {
    Text = "咒縛如蛇一般緩緩轉動，碎成漿水的血肉也隨之不斷匯集、重組……"
  },
  AvgDialog_35996_Content_94 = {
    Text = "直到最後，“屍體”慢慢坐了起來。"
  },
  AvgDialog_35996_Content_95 = {
    Text = "呼……不錯，那些酊劑還算管用，她體內的潛力都爆發出來了。"
  },
  AvgDialog_35996_Content_96 = {
    Text = "阿爾比諾伸出長長的蛇信，慢條斯理地將臉上的血舔得乾乾淨淨。"
  },
  AvgDialog_35996_Content_97 = {
    Text = "獵物已經長成，是時候稟報咱們的會長大人了。"
  },
  AvgDialog_35996_Content_98 = {
    Text = "他拾起腳邊的病歷本，悠然離開。"
  },
  AvgDialog_35997_Content_1 = {
    Text = "貓知曉一切"
  },
  AvgDialog_35997_Content_10 = {
    Text = "嘖，對付你們這些雜魚，我和布朗就夠了。"
  },
  AvgDialog_35997_Content_11 = {
    Text = "你說什麼？！"
  },
  AvgDialog_35997_Content_12 = {
    Text = "小麥克擺擺手，騷亂的孩童立刻噤聲。"
  },
  AvgDialog_35997_Content_13 = {
    Text = "規矩都清楚吧？如果你輸給我們，就要交出坎伯韋爾街的統治權。"
  },
  AvgDialog_35997_Content_14 = {
    Text = "——永遠。"
  },
  AvgDialog_35997_Content_15 = {
    Text = "磨磨唧唧的，要打架趕緊上！"
  },
  AvgDialog_35997_Content_17 = {
    Text = "很好，現在我正式宣布，第13屆“坎伯韋爾爭奪戰”現在開始。\n兄弟們——"
  },
  AvgDialog_35997_Content_18 = {
    Text = "<Big:衝呀！！>"
  },
  AvgDialog_35997_Content_2 = {
    Text = "人工密境：坎伯韋爾街，東區"
  },
  AvgDialog_35997_Content_20 = {
    Text = "哎喲！痛痛痛……他們人也太多了……"
  },
  AvgDialog_35997_Content_22 = {
    Text = "哼！誰叫你平時到處惹事，現在知道我們的厲害了吧！"
  },
  AvgDialog_35997_Content_23 = {
    Text = "大家衝呀，勝利就在前方——"
  },
  AvgDialog_35997_Content_24 = {Text = "喵嗚~"},
  AvgDialog_35997_Content_25 = {
    Text = "憤怒中夾帶一絲奶氣的叫聲打斷了眼前的小小戰爭。"
  },
  AvgDialog_35997_Content_26 = {
    Text = "不許欺負詹金喵！"
  },
  AvgDialog_35997_Content_27 = {
    Text = "貓……貓人？不對，是梅森姐姐？！"
  },
  AvgDialog_35997_Content_29 = {
    Text = "尚不及反應，小麥克臉上便多了三道紅紅的劃痕。"
  },
  AvgDialog_35997_Content_3 = {
    Text = "蕭瑟的冷風吹過，捲起片片枯葉。"
  },
  AvgDialog_35997_Content_32 = {
    Text = "孩童們四散而逃。哭聲震耳欲聾，一路飄到無人注意的巷道角落。"
  },
  AvgDialog_35997_Content_33 = {
    Text = "想不到還有像貓咪一樣的24啊……梅森小姐，要出去看看嗎？"
  },
  AvgDialog_35997_Content_34 = {
    Text = "無人回應你的請求。在剛才的混戰中，梅森不知何時失去了蹤影。"
  },
  AvgDialog_35997_Content_35 = {
    Text = "梅森小姐……？怎麼離開也不打聲招呼。"
  },
  AvgDialog_35997_Content_37 = {
    Text = "臉側傳來濕漉漉的觸感。"
  },
  AvgDialog_35997_Content_38 = {
    Text = "你難以置信地扭過頭，只見「24」像個大號娃娃一樣掛在你身上，朝你露出討好的微笑。"
  },
  AvgDialog_35997_Content_39 = {
    Text = "喵、喵嗚？"
  },
  AvgDialog_35997_Content_4 = {
    Text = "小麥克和一眾孩童站在巷道盡頭。他雙手叉腰，表情十分嚴肅。"
  },
  AvgDialog_35997_Content_43 = {
    Text = "吱吱吱嗚@3！"
  },
  AvgDialog_35997_Content_44 = {
    Text = "淒厲的尖叫響徹雲霄。你們循著聲音低頭望去，「24」已將布朗銜在嘴裡。"
  },
  AvgDialog_35997_Content_46 = {
    Text = "布朗極力扭動著柔軟的身軀，鬍鬚飛速抖動。"
  },
  AvgDialog_35997_Content_48 = {
    Text = "快、快看那是什麼？"
  },
  AvgDialog_35997_Content_49 = {
    Text = "詹金熟練地從地上撿起一塊碎鏡子，照向對面的牆壁。"
  },
  AvgDialog_35997_Content_50 = {
    Text = "霎時間，石牆上出現了劇烈晃動的光斑，它們成功地吸引了「24」的注意。"
  },
  AvgDialog_35997_Content_51 = {
    Text = "亮晶晶喵嗚！"
  },
  AvgDialog_35997_Content_52 = {
    Text = "「24」嗖的一聲竄了出去，留下在原地抽噎不止的布朗。"
  },
  AvgDialog_35997_Content_53 = {
    Text = "嗚嗚吱……"
  },
  AvgDialog_35997_Content_54 = {
    Text = "唉。自從找了那個庸醫，姐姐的病情變得越來越嚴重了。"
  },
  AvgDialog_35997_Content_55 = {
    Text = "庸醫？你指的是伯納德醫生嗎？"
  },
  AvgDialog_35997_Content_56 = {
    Text = "除了他還能有誰。什麼“神醫”“東區窮人的救世主”，啊呸！"
  },
  AvgDialog_35997_Content_57 = {
    Text = "天下哪有免費的午餐，我看他一定沒安好心……"
  },
  AvgDialog_35997_Content_58 = {
    Text = "伯納德醫生是好人喵！"
  },
  AvgDialog_35997_Content_59 = {
    Text = "原本還在追逐光斑的「24」忽然從詹金背後探出頭來。"
  },
  AvgDialog_35997_Content_6 = {
    Text = "女孩踏著沉穩的步伐走了過來，風吹起她破破爛爛的斗篷。"
  },
  AvgDialog_35997_Content_60 = {
    Text = "好好好，他好得很，他是世上最厲害的醫生。"
  },
  AvgDialog_35997_Content_61 = {
    Text = "詹金熟練地捋著「24」的頭髮。\n「24」瞇了瞇眼睛，一副十分享受的模樣。"
  },
  AvgDialog_35997_Content_62 = {
    Text = "小詹金也是好人喵嗚。"
  },
  AvgDialog_35997_Content_63 = {
    Text = "梅森小姐這種……呃，奇特的症狀最早出現在什麼時候？"
  },
  AvgDialog_35997_Content_64 = {
    Text = "大概是見了那個庸醫三、四次以後吧。有一天她忽然和我說她其實是一條銀鱈魚。"
  },
  AvgDialog_35997_Content_65 = {
    Text = "後來她還制定了一個摧毀炸魚餐廳的計劃，說是要拯救自己的同伴……"
  },
  AvgDialog_35997_Content_66 = {
    Text = "<Gray:原來如此。之前太過相信審查會，忽略了醫生本人的資質問題。>"
  },
  AvgDialog_35997_Content_67 = {
    Text = "<Gray:這傢伙搞不好和米勒醫生一樣，都是雕塑家協會的走狗……>"
  },
  AvgDialog_35997_Content_68 = {
    Text = "困死了啊嗚……"
  },
  AvgDialog_35997_Content_69 = {
    Text = "「24」舒展雙臂，伸了個長長的懶腰，隨後無比自然地靠在詹金的肩上。"
  },
  AvgDialog_35997_Content_7 = {
    Text = "你還是如約來了。一個人？"
  },
  AvgDialog_35997_Content_70 = {
    Text = "咕嚕咕嚕……"
  },
  AvgDialog_35997_Content_71 = {
    Text = "她睡著了。"
  },
  AvgDialog_35997_Content_72 = {
    Text = "真的發出了和貓咪一樣咕嚕聲啊……和彌薩格校園裡的那些貓一樣。"
  },
  AvgDialog_35997_Content_74 = {
    Text = "陽光均勻地灑下，將她臉上細小的絨毛也染成了金色。"
  },
  AvgDialog_35997_Content_75 = {
    Text = "喂，你笑什麼！"
  },
  AvgDialog_35997_Content_76 = {
    Text = "她現在看起來很快樂，真的像隻無憂無慮的小貓了。"
  },
  AvgDialog_35997_Content_78 = {
    Text = "姐姐以前說過，這輩子過得太辛苦啦。如果能轉世的話，她想做一隻貓。"
  },
  AvgDialog_35997_Content_79 = {
    Text = "詹金說著，忽然從兜裡掏出一條紅色的緞帶。這是梅森常用的緞帶，尾部還墜上了一個鏽跡斑斑的鈴鐺。"
  },
  AvgDialog_35997_Content_80 = {
    Text = "放心吧。不管貓咪還是銀鱈魚，通通都是我的姐姐。"
  },
  AvgDialog_35997_Content_81 = {
    Text = "不過呢，為了防止你跑丟，我得給你繫個鈴鐺。"
  },
  AvgDialog_35997_Content_82 = {
    Text = "詹金輕輕將緞帶繫在「24」的手腕上。\n「24」猶在睡夢中，只微微皺了皺鼻子。"
  },
  AvgDialog_35997_Content_83 = {
    Text = "這是我從小麥克他們那裡搶的，你要戴穩哦。"
  },
  AvgDialog_35997_Content_84 = {
    Text = "午後的陽光如漫溢過來的時間，緩緩流經你們。詹金望著對面太陽割開的斑駁屋影，輕輕閉上眼。"
  },
  AvgDialog_35997_Content_85 = {
    Text = "姐姐很忙的。既要照顧我和布朗，還要同時打幾份工，就像一台永遠都不會故障的機器。"
  },
  AvgDialog_35997_Content_86 = {
    Text = "現在這台機器倒下了，終於輪到我來照顧啦。"
  },
  AvgDialog_35997_Content_9 = {
    Text = "不錯，竟敢獨自赴約。你是一名受人尊敬的對手。"
  },
  AvgDialog_35999_Content_1 = {Text = "苦咒縛"},
  AvgDialog_35999_Content_10 = {
    Text = "我全都記起來了……"
  },
  AvgDialog_35999_Content_2 = {
    Text = "記憶伴隨星光紛亂湧入。"
  },
  AvgDialog_35999_Content_4 = {
    Text = "那些被人為暴力製造、切碎的記憶湧入梅森的腦海，又像潮水般迅速退去。"
  },
  AvgDialog_35999_Content_5 = {
    Text = "直到最後，她來到雪山腳下，那個漆黑的洞穴入口。"
  },
  AvgDialog_35999_Content_6 = {
    Text = "沿著腳下流淌的河川一路前行，便能抵達昏睡巨獸的巢穴。"
  },
  AvgDialog_35999_Content_8 = {
    Text = "那是如老舊時鐘一般的心跳聲，屬於她和巨獸的、共同的心跳聲。"
  },
  AvgDialog_36227_Content_1 = {
    Text = "「偽神」徹底擺脫了脆弱而頑強的母體，墨菲被從高處甩下，最終重重摔在甲板上。"
  },
  AvgDialog_36227_Content_10 = {
    Text = "「銀芯」。"
  },
  AvgDialog_36227_Content_11 = {
    Text = "墨菲尚未斷氣，體內卻存在已析出的銀芯——這不符合你在課堂上所認知到的常理。"
  },
  AvgDialog_36227_Content_12 = {
    Text = "但情況不容你細想，在近乎本能的衝動下，你握住了墨菲的手。"
  },
  AvgDialog_36227_Content_13 = {
    Text = "墜在胸前的銀鑰發出震顫的鳴音，你們交握的手中迸發出耀眼到足以照亮每一個角落的銀光，將所有人都吞沒。"
  },
  AvgDialog_36227_Content_14 = {
    Text = "時間在光芒中變得無邊無際，靈魂在無盡的時間中反復被壓縮、折疊。"
  },
  AvgDialog_36227_Content_15 = {
    Text = "在這永恆的瞬間，痛苦始終伴隨著你，想讓你放下手中那塊刺穿掌心的銀芯。"
  },
  AvgDialog_36227_Content_16 = {
    Text = "——你拒絕了。任由劇烈的痛楚無情地侵襲你的意識空間，顱腔內的組織被暴亂的靈知撞碎，讓你的口、鼻、耳都湧出了帶腫塊的鮮血。"
  },
  AvgDialog_36227_Content_17 = {
    Text = "你始終緊握著墨菲的靈魂。"
  },
  AvgDialog_36227_Content_18 = {
    Text = "光芒向原點坍縮，那讓你昏沉無比的詭異笛音再次響起，強硬地挾持了你的注意力。"
  },
  AvgDialog_36227_Content_19 = {
    Text = "你感覺手中一空。"
  },
  AvgDialog_36227_Content_2 = {
    Text = "渾身的骨頭在墜落時折斷，胸腔被自己剮開了一個巨大的豁口，又被破體而生的「偽神」衝撞得支離破碎。"
  },
  AvgDialog_36227_Content_20 = {
    Text = "銀光消散後，你們面前的甲板上空無一物，徒留滿地血污。"
  },
  AvgDialog_36227_Content_22 = {
    Text = "拉蒙娜顫抖著抹去你眼角泌出的血，卻只越抹越髒，讓你滿臉都是血痕。"
  },
  AvgDialog_36227_Content_24 = {
    Text = "拉蒙娜的震驚與疑問剛含在嘴邊，不遠處的船頭便傳來了一陣低沉的響聲，彷彿是深淵之物在睡夢中的囈語，帶著一種不祥的氣息。"
  },
  AvgDialog_36227_Content_25 = {
    Text = "你們下意識雙雙轉頭看過去，只見名為「彌利亞姆」的異怪近乎狂熱地凝視著神明，她跪在船頭，向著那偽神張開自己的雙臂。"
  },
  AvgDialog_36227_Content_26 = {
    Text = "而那無數雙漆黑的手，也向她敞開了懷抱。它們輕柔地箍著她的腰，將這名虔誠的信徒高舉到嘴邊。"
  },
  AvgDialog_36227_Content_27 = {
    Text = "——<Red:哢嚓>。"
  },
  AvgDialog_36227_Content_28 = {
    Text = "下一秒，咀嚼、吞咽的聲音次第響起。"
  },
  AvgDialog_36227_Content_29 = {
    Text = "彷彿終於脫離了某種未知的恐怖邊界，新生兒發出了一種類似呼嚕的饜足聲響。彷彿正在消化「彌利亞姆」這一難得的美餐。"
  },
  AvgDialog_36227_Content_3 = {
    Text = "海浪不斷衝進甲板，沖刷著她身下一灘又一灘血跡，彷彿要將她存在的痕跡徹底抹除。"
  },
  AvgDialog_36227_Content_30 = {
    Text = "在半透明黑色繭中的“新生兒”，猶如一個巨大的、脆弱的靈長類胚胎。祂的肢體笨拙地抽搐著，似乎在尋找生長的方向——"
  },
  AvgDialog_36227_Content_31 = {
    Text = "距離正位之時\n還剩：<Red:0>分鐘"
  },
  AvgDialog_36227_Content_4 = {
    Text = "這樣的傷……我們沒有辦法處理。"
  },
  AvgDialog_36227_Content_5 = {
    Text = "墨菲下唇還在囁嚅著，眼神卻已經開始渙散。\n拉蒙娜不忍直視這幅慘狀，她咬著牙，抬頭看向那「偽神」。"
  },
  AvgDialog_36227_Content_6 = {
    Text = "要阻止祂。這麼巨大的災厄核心，如果沒能在船上結果祂，讓祂到了陸地上……後果不堪設想。"
  },
  AvgDialog_36227_Content_7 = {
    Text = "守密人，我們該行動了。就算是為了墨菲。"
  },
  AvgDialog_36227_Content_8 = {
    Text = "等一等！我或許有辦法。"
  },
  AvgDialog_36227_Content_9 = {
    Text = "你死死盯著墨菲肋骨下一塌糊塗的組織，堅信自己看見了那個東西——"
  },
  AvgDialog_36276_Content_1 = {
    Text = "外層的部分……居然不是祂的本體嗎？！"
  },
  AvgDialog_36276_Content_2 = {
    Text = "這就是彌利亞姆所追求的東西。她所渴望的，能為她帶來舊日復甦的「神明」……"
  },
  AvgDialog_36276_Content_3 = {
    Text = "接下來不能大意，一點心都不能分！"
  },
  AvgDialog_36276_Content_4 = {
    Text = "這個醜東西徹底醒了……我能感覺到。"
  },
  AvgDialog_36277_Content_2 = {
    Text = "圖魯！你終於來了。"
  },
  AvgDialog_36277_Content_3 = {
    Text = "處理埃爾頓那邊的敵人花了一些時間……<Small:等等，墨菲？>"
  },
  AvgDialog_36277_Content_4 = {
    Text = "圖魯的眼睛從「聖嬰」身上滑過，最終落在了墨菲身上。擁有了喚醒體之身的她，裙擺上的觸手正胡亂地憑空搖擺著。"
  },
  AvgDialog_36277_Content_5 = {
    Text = "……祂的力量與余同源，意味著，祂也是余的子民。雖無法直接號令祂，但余之王權曾受利莫里亞萬千臣民膜拜，絕非神明贗作可抵抗。"
  },
  AvgDialog_36277_Content_6 = {
    Text = "機會只此一次，利用余螺湮之主的權能……對祂降下天罰！"
  },
  AvgDialog_37962_Content_1 = {
    Text = "接下來測試的是：螢幕特效-持續紅色"
  },
  AvgDialog_37962_Content_10 = {
    Text = "接下來測試的是：螢幕特效-星光"
  },
  AvgDialog_37962_Content_14 = {Text = "結束"},
  AvgDialog_37962_Content_15 = {
    Text = "接下來測試的是：螢幕特效-燈光"
  },
  AvgDialog_37962_Content_19 = {Text = "結束"},
  AvgDialog_37962_Content_20 = {
    Text = "接下來測試的是：9號滾動字幕類型"
  },
  AvgDialog_37962_Content_21 = {
    Text = "春，曙為最。逐漸轉白的山頂，開始稍露光明，泛紫的細雲輕飄其上。\n夏則夜。有月的時候自不待言，無月的暗夜，也有群螢交飛。若是下場雨什麼的，那就更有情味了。\n秋則黃昏。夕陽照耀，近映山際，烏鴉返巢，三隻、四隻、兩隻的飛過，平添感傷。又有時見雁影小小，列隊飛過遠空，尤饒風情。而況，日入以後，尚有風聲蟲鳴。\n冬則晨朝。降雪時不消說，有時霜色皑皑，即使無雪亦無霜，寒氣凜冽，連忙生一盆火，搬運炭火跑過走廊，也挺合時宜；只可惜晌午時分，火盆裡頭炭木漸蒙白灰，便無甚可賞了。"
  },
  AvgDialog_37962_Content_22 = {Text = "結束"},
  AvgDialog_37962_Content_5 = {Text = "結束"},
  AvgDialog_37962_Content_6 = {
    Text = "接下來測試的是：立繪放大效果"
  },
  AvgDialog_37962_Content_7 = {
    Text = "立繪放大(1.5, 0.3)"
  },
  AvgDialog_37962_Content_8 = {
    Text = "立繪放大還原"
  },
  AvgDialog_37962_Content_9 = {
    Text = "測試結束，啾~"
  },
  AvgDialog_38725_Content_1 = {
    Text = "暗淡的藍光縈繞在你周圍，將你渾身的疲憊與疼痛都一掃而空。"
  },
  AvgDialog_38725_Content_2 = {
    Text = "父神將「賜福」降臨於你。"
  },
  AvgDialog_38725_Content_3 = {
    Text = "薩爾瓦多主教！"
  },
  AvgDialog_38725_Content_4 = {
    Text = "你是那蒼白的使者，是驅散黑暗的火焰。"
  },
  AvgDialog_38725_Content_5 = {
    Text = "你將終結這一切苦難，而我將予以你一切幫助。"
  },
  AvgDialog_38727_Content_1 = {
    Text = "血腥的符號"
  },
  AvgDialog_38727_Content_10 = {
    Text = "確實，或許……是邪教？"
  },
  AvgDialog_38727_Content_11 = {
    Text = "無數畫面在你腦海中浮現——手握匕首的少女，身穿黑紗的女人，拉伊療養院深處永遠不能開啟的房間……"
  },
  AvgDialog_38727_Content_12 = {
    Text = "這世上究竟還有多少和<Yellow:蹈海者>與<Yellow:提燈教會>一樣的組織，又有多少人要成為它們的犧牲品？"
  },
  AvgDialog_38727_Content_13 = {
    Text = "主教閣下，請問愛德華有沒有對你說過什麼？\n其他宗教也好，古老信仰也好，哪怕是民俗傳說也行。"
  },
  AvgDialog_38727_Content_14 = {
    Text = "薩爾瓦多放下手帕，他轉向你，儘管雙眼被蒙在紗布下，你仍然能感受到他的注視。"
  },
  AvgDialog_38727_Content_15 = {
    Text = "如果是的話，你們打算調查這件事嗎？"
  },
  AvgDialog_38727_Content_16 = {
    Text = "是的。我……與類似的組織有過接觸，我知道它們有多危險。\n如果可以的話，我不希望看到更多受害者出現。"
  },
  AvgDialog_38727_Content_17 = {
    Text = "你有一個明亮的靈魂，%player%，溫暖、堅強、令人欽佩。\n願父神的光照耀於你，如它照耀著所有<Yellow:彌薩格>的成員。"
  },
  AvgDialog_38727_Content_18 = {
    Text = "你怎麼知道——"
  },
  AvgDialog_38727_Content_19 = {
    Text = "前任主教是我的朋友，他掌管聖堂教區數十年，知道很多事情。"
  },
  AvgDialog_38727_Content_2 = {
    Text = "木門緩緩合上，將小販的叫賣與人群的喧囂都隔絕在外，靜謐之中，你不由得放輕了呼吸。"
  },
  AvgDialog_38727_Content_20 = {
    Text = "我會盡力幫助你們，但恐怕我了解得不比你們多多少。"
  },
  AvgDialog_38727_Content_21 = {
    Text = "事實上，愛德華並不是這個神秘宗教的第一個受害者。"
  },
  AvgDialog_38727_Content_22 = {
    Text = "半年前，聖堂區一個叫菲利普的年輕人，因為殺害他的妻子而被判死刑。"
  },
  AvgDialog_38727_Content_23 = {
    Text = "他剛被抓進去時，我應典獄長的邀前去探望過他。\n他很蒼白，非常消瘦，拒絕與任何人溝通。"
  },
  AvgDialog_38727_Content_24 = {
    Text = "我陪他坐了一天，在我走的時候，他說了那天唯一一句話。"
  },
  AvgDialog_38727_Content_25 = {
    Text = "“你看到了嗎，那黑色的<Red:血液>？”"
  },
  AvgDialog_38727_Content_26 = {
    Text = "在行刑之前，他自殺了。"
  },
  AvgDialog_38727_Content_27 = {
    Text = "整個房間都是血，地上、牆上、天花板上，光是站在那裡，就足以讓人感到窒息。在重重的血跡下，我發現了一個詭異的符號。"
  },
  AvgDialog_38727_Content_28 = {
    Text = "它很淺、很小，像是被人指甲刻出來的。如果不是血液滲入縫隙，恐怕沒有人會注意到。"
  },
  AvgDialog_38727_Content_29 = {
    Text = "在符號的旁邊，還有一個更淺的痕跡。"
  },
  AvgDialog_38727_Content_3 = {
    Text = "主教閣下，水來了。"
  },
  AvgDialog_38727_Content_30 = {
    Text = "那個痕跡歪歪扭扭，像是刻印的人已經失去力氣，或者神志不清。在父神的指引下，我看出來了——那是一個詞。"
  },
  AvgDialog_38727_Content_31 = {
    Text = "<Red:淨化>"
  },
  AvgDialog_38727_Content_32 = {
    Text = "那個教派非常謹慎，且善於隱藏自己。如果不是愛德華今天提到了“淨化”，我恐怕都不會知道他已經落入了他們的魔爪。"
  },
  AvgDialog_38727_Content_33 = {
    Text = "那個符號，你還記得它是什麼樣的嗎？或許彌薩格會有關於它們的資料。"
  },
  AvgDialog_38727_Content_34 = {
    Text = "當然，伸出手來。"
  },
  AvgDialog_38727_Content_35 = {
    Text = "他伸出一隻手指，在你手心輕輕畫下一個簡單的符號。"
  },
  AvgDialog_38727_Content_36 = {
    Text = "這……！"
  },
  AvgDialog_38727_Content_37 = {
    Text = "你從口袋裡摸出隨身攜帶的筆記本，迅速在上面複寫薩爾瓦多畫下的圖案。"
  },
  AvgDialog_38727_Content_38 = {
    Text = "主君，怎麼了？那是什麼符號？"
  },
  AvgDialog_38727_Content_39 = {
    Text = "倒三角，中間一個點——"
  },
  AvgDialog_38727_Content_4 = {
    Text = "謝謝你，奧吉爾。"
  },
  AvgDialog_38727_Content_40 = {
    Text = "這是提燈教會的符號。"
  },
  AvgDialog_38727_Content_42 = {
    Text = "聖堂的門被一下撞開，索菲亞頭髮微亂，氣喘吁吁，她站在陽光之中，扶著門衝你們大喊。"
  },
  AvgDialog_38727_Content_43 = {
    Text = "薩爾瓦多主教，不好了！外面的人——"
  },
  AvgDialog_38727_Content_44 = {
    Text = "別擋在這裡，讓我們進去！"
  },
  AvgDialog_38727_Content_45 = {
    Text = "一隻手將索菲亞粗暴地搡開，叫嚷和謾罵瞬間填滿了聖堂。"
  },
  AvgDialog_38727_Content_46 = {
    Text = "十多個市民湧了進來，有的拿著掃帚，有的拿著擀麵杖，其中一個揮舞著拳頭，上面還殘留了愛德華的牙印。"
  },
  AvgDialog_38727_Content_47 = {
    Text = "讓愛德華那敗類出來！我們要找他算帳！"
  },
  AvgDialog_38727_Content_5 = {
    Text = "薩爾瓦多從口袋裡拿出一塊潔白的手帕，在奧吉爾拿來的水桶裡沾濕後，一點點將愛德華身上沾染的塵土擦去。"
  },
  AvgDialog_38727_Content_6 = {
    Text = "微濕的布料拂過胸膛，將你的視線引向了根根分明的肋骨——他太瘦了，瘦得像是剛剛經歷了一場大饑荒。"
  },
  AvgDialog_38727_Content_7 = {
    Text = "<Small:……罪惡……的血液……淨化……>"
  },
  AvgDialog_38727_Content_8 = {
    Text = "流血、罪惡……雖然你對<Blue:生命教廷>的<Blue:《聖典》>並不熟悉，但這種頗為血腥的概念，與你對這個宗教的印象十分不符。"
  },
  AvgDialog_38727_Content_9 = {
    Text = "這個「無罪的淨土」，還有「淨化」……好像不是《聖典》裡的東西？"
  },
  AvgDialog_38729_Content_10 = {
    Text = "請消去他們的傷痛，撫平他們的心。"
  },
  AvgDialog_38729_Content_100 = {
    Text = "給予罪人寬恕，賜予他們「賜福」……這麼多年了，你還真是一點都沒變啊，薩爾瓦多主教。"
  },
  AvgDialog_38729_Content_101 = {
    Text = "火刑架無法改變你，死而復生也無法改變你。你要什麼時候才能看清現實呢？或許——"
  },
  AvgDialog_38729_Content_102 = {
    Text = "她的手遙遙在空中一點，彷彿隔空觸摸著什麼不可見的東西。"
  },
  AvgDialog_38729_Content_103 = {
    Text = "那個有著預言中蒼白而又溫暖的靈魂的<Yellow:守密人>，可以帶來更多的變量。\n你說，%heorshe%會不會願意加入我們呢？"
  },
  AvgDialog_38729_Content_104 = {
