  AvgDialog_43788_Content_37 = {
    Text = "記住，千萬不要進去。"
  },
  AvgDialog_43788_Content_38 = {
    Text = "若是冒犯到女王，我能幫上的部分可相當有限。"
  },
  AvgDialog_43788_Content_4 = {
    Text = "這片香熏，請隨時佩在你的隨身物品上，藏在領帶裡、掛在手杖上或者塞在耳朵裡都無所謂。"
  },
  AvgDialog_43788_Content_40 = {
    Text = "微風將簾幕微微掀動，帳篷內的景象在縫隙中若隱若現。"
  },
  AvgDialog_43788_Content_41 = {
    Text = "一股莫名的渴求湧上你的喉頭，令你忍不住想要一窺究竟。"
  },
  AvgDialog_43788_Content_42 = {
    Text = "不知為何，冥冥中有一個聲音告訴你，這帳篷內隱藏著你此行想要追求的一切，你必須揭開簾幕，才能得到答案。"
  },
  AvgDialog_43788_Content_43 = {
    Text = "四野無人，只有卷著砂礫的風聲呼嘯。"
  },
  AvgDialog_43788_Content_44 = {
    Text = "進入帳篷"
