  },
  AvgDialog_43803_Content_17 = {
    Text = "然而，他們在突破風暴之壁時受到了阻礙。"
  },
  AvgDialog_43803_Content_18 = {
    Text = "以上內容，都被記載在亞蘭族代代相傳的歌謠中。"
  },
  AvgDialog_43803_Content_19 = {
    Text = "拉蒙娜愈說，臉色愈是蒼白。"
  },
  AvgDialog_43803_Content_20 = {
    Text = "歌謠的內容，還是麻煩朵爾你來說明吧。"
  },
  AvgDialog_43803_Content_21 = {
    Text = "我不會念那首蠢詩的。\n在穩定記憶和複述方面，有比我更在行的專家。"
  },
  AvgDialog_43803_Content_22 = {
    Text = "艾瑞卡，為您效勞——"
  },
  AvgDialog_43803_Content_23 = {
    Text = "死亡已經迫近，消亡已經起始。"
  },
  AvgDialog_43803_Content_25 = {
    Text = "艾瑞卡似乎沒有聽見你的指令，機械地誦讀了下去。"
  },
  AvgDialog_43803_Content_26 = {
    Text = "母親的遺骸不見蹤跡，血與種漂泊於大地，被初生的野獸吞噬。"
  },
  AvgDialog_43803_Content_27 = {
    Text = "天空與眾神佈滿陰雲，直至異鄉使者降臨。"
  },
  AvgDialog_43803_Content_28 = {
    Text = "使者——降臨——嘎吱——降臨——嘎吱——嘻嘻，使者——"
  },
  AvgDialog_43803_Content_29 = {
    Text = "尖銳而冰冷的無機質聲音在帳篷內突兀地迴蕩。"
  },
  AvgDialog_43803_Content_3 = {
    Text = "於麗埃特面露猶豫之色。"
  },
  AvgDialog_43803_Content_31 = {
    Text = "機械警報聲響起，隨後是紙張翻頁聲，螺絲扭動聲，叮鈴哐啷的金屬碰撞聲。"
  },
  AvgDialog_43803_Content_32 = {
    Text = "抱歉，我剛才檢查了艾瑞卡的維護狀況，還沒有發現故障的起因。"
  },
  AvgDialog_43803_Content_33 = {
    Text = "不關鍵了，歌謠還有最後一句，由我來就好……"
  },
  AvgDialog_43803_Content_34 = {
    Text = "……母樹重誕聖河，為已逝者加冕，將血脈還於亞蘭。"
  },
  AvgDialog_43803_Content_35 = {
    Text = "從溝通效率的角度，如果你早說你聽過，我們可以省下不少時間。"
  },
  AvgDialog_43803_Content_36 = {
    Text = "你在女王營帳見到了什麼？"
  },
  AvgDialog_43803_Content_37 = {
    Text = "還沒等你開口，帳外就響起了熱情如火的呼喚。"
  },
  AvgDialog_43803_Content_38 = {
    Text = "各位貴客，晚宴已經準備好了！"
  },
  AvgDialog_43803_Content_39 = {
    Text = "你猶豫半晌，伏在拉蒙娜耳邊說出了最關鍵的資訊。"
  },
  AvgDialog_43803_Content_4 = {
    Text = "我之前提過，亞蘭族身為原始部族，有很多「獨特」的傳統，恐怕難以為外人理解。"
  },
  AvgDialog_43803_Content_40 = {
    Text = "聖樹遺骸就在女王營帳中。"
  },
  AvgDialog_43803_Content_41 = {
    Text = "您這麼英俊風趣，只怕連艾爾瓦大人都能俘獲呢！"
  },
  AvgDialog_43803_Content_42 = {
    Text = "您謬贊了，我倒是聽說，這裡最會講故事的，是那位於麗埃特小姐呢。"
  },
  AvgDialog_43803_Content_43 = {
    Text = "您說使者大人嗎？"
  },
  AvgDialog_43803_Content_44 = {
    Text = "她的故事本身，或許沒有您講述「最後一顆骰子」的故事精彩，但跟使者大人交談的感覺，實在是如沐春風。"
  },
  AvgDialog_43803_Content_45 = {
    Text = "而且，那位「倒懸的無目之瞳」，不知為何，有一種發自肺腑的強烈感召力……"
  },
  AvgDialog_43803_Content_46 = {
    Text = "哎呀，在聊我的事情嗎？"
  },
  AvgDialog_43803_Content_47 = {
    Text = "美迪奈特在盛讚你講故事的能力呢。"
  },
  AvgDialog_43803_Content_48 = {
    Text = "介意我加入嗎？"
  },
  AvgDialog_43803_Content_49 = {
    Text = "當然不會了，我的女士。"
  },
  AvgDialog_43803_Content_50 = {
    Text = "最近，努比亞的襲擊越來越頻繁，也該舉行篝火儀式了。"
  },
  AvgDialog_43803_Content_51 = {
    Text = "新客人來是好兆頭，別垂頭喪氣的！\n來吧，先喝幾杯！"
  },
  AvgDialog_43803_Content_52 = {
    Text = "客人也是，多喝點吧！\n好好享受宴會，我們會拿出最好的一切來招待貴客的！"
  },
  AvgDialog_43803_Content_53 = {Text = "乾杯！"},
  AvgDialog_43803_Content_54 = {
    Text = "我不會喝酒"
  },
  AvgDialog_43803_Content_55 = {
    Text = "你舉杯，與熱情的亞蘭人杯沿相碰。"
  },
  AvgDialog_43803_Content_56 = {
    Text = "趁他不備，你偷偷倒掉了杯中的酒液。"
  },
  AvgDialog_43803_Content_57 = {
    Text = "母樹遺骸就在離你不到百米的營帳中，現在可不是享樂的最佳契機。"
  },
  AvgDialog_43803_Content_58 = {
    Text = "那可太遺憾了！帶著酒意的儀式才是最完美的！"
  },
  AvgDialog_43803_Content_59 = {
    Text = "無論亞蘭人如何勸說，你都只是推拒。"
  },
  AvgDialog_43803_Content_6 = {
    Text = "具體細節……你們晚上自然就知道了。"
  },
  AvgDialog_43803_Content_60 = {
    Text = "母樹遺骸就在離你不到百米的營帳中，現在可不是享樂的最佳契機。"
  },
  AvgDialog_43803_Content_63 = {
    Text = "隨著亞蘭人的酒意漸濃，歡宴的氛圍也被推向高潮。"
  },
  AvgDialog_43803_Content_64 = {
    Text = "幾個亞蘭戰士以人體為轎，扛起亞蘭的女人們，在會場巡遊。"
  },
  AvgDialog_43803_Content_65 = {
    Text = "醉眼朦朧的女人們摘下一顆顆閃著晶瑩水珠的葡萄，肆笑著向人群拋灑。"
  },
  AvgDialog_43803_Content_66 = {
    Text = "咻~這邊，這邊，給我也來兩顆！"
  },
  AvgDialog_43803_Content_67 = {
    Text = "女人彷彿聽見了萊克的呼喚，指引著戰士們來到萊克身邊，然後飛撲而下，直落進萊克懷中。"
  },
  AvgDialog_43803_Content_68 = {
    Text = "別別，我這個小身板，可接不起啊……"
  },
  AvgDialog_43803_Content_69 = {
    Text = "還沒等萊克話音落地，眼前的景象突然令你們瞋目結舌。"
  },
  AvgDialog_43803_Content_7 = {
    Text = "……所以，亞蘭人的遷徙目標也是母樹遺址？"
  },
  AvgDialog_43803_Content_70 = {
    Text = "女人一把撕扯下自己的外袍，一絲不掛地向萊克壓去。"
  },
  AvgDialog_43803_Content_71 = {
    Text = "她的動作彷彿某種號令，所有亞蘭人都開始脫衣卸甲，現場化為淫靡的汪洋。"
  },
  AvgDialog_43803_Content_72 = {
    Text = "見萊克無所動作，女人毫不留戀，撲向身側的亞蘭戰士，口中發出令人面紅耳赤的呻吟。"
  },
  AvgDialog_43803_Content_74 = {
    Text = "來吧，加入我們，享受篝火晚會最極致的歡愉吧！"
  },
  AvgDialog_43803_Content_75 = {
    Text = "跑！跑！回拉蒙娜的帳篷去！"
  },
  AvgDialog_43803_Content_76 = {
    Text = "你大腦一片空白，只能依從萊克的言語，向著拉蒙娜的所在極盡所能地奔跑……不，逃跑。"
  },
  AvgDialog_43803_Content_77 = {
    Text = "帳篷外，負責照顧拉蒙娜的女人已經不見蹤影。"
  },
  AvgDialog_43803_Content_78 = {
    Text = "拉蒙娜此刻高燒不醒，以至於沒能親眼目睹儀式的瘋狂景象，不知是否是一種幸事。"
  },
  AvgDialog_43803_Content_8 = {
    Text = "是的，他們同樣無法突破風暴之壁。"
  },
  AvgDialog_43803_Content_80 = {
    Text = "篝火儀式。恐怕是的……\n亞蘭人的篝火儀式，是原始的交媾儀式。"
  },
  AvgDialog_43803_Content_81 = {
    Text = "這裡……離儀式現場有點距離，我去外面看守，防止別人靠近。"
  },
  AvgDialog_43803_Content_82 = {
    Text = "你留下照顧拉蒙娜。"
  },
  AvgDialog_43803_Content_83 = {
    Text = "這幫原始人……瘋子。"
  },
  AvgDialog_43803_Content_84 = {
    Text = "與帳篷外的喧囂相比，帳篷內安靜異常，只有拉蒙娜因高熱略顯沉重的呼吸聲。"
  },
  AvgDialog_43803_Content_85 = {
    Text = "遠方儀式的淫聲穢語隱隱約約，透過厚重的篷布侵入你的耳膜，讓你禁不住心慌意亂。"
  },
  AvgDialog_43803_Content_86 = {
    Text = "……萊克？"
  },
  AvgDialog_43803_Content_87 = {
    Text = "真可惜啊，你在期待的人不是我嗎？"
  },
  AvgDialog_43803_Content_88 = {
    Text = "亞蘭的女王——泰旖絲掀簾而入，她毫無顧忌地湊近，薄若無物的輕紗緊貼你的小臂，發出直白的邀請。"
  },
  AvgDialog_43803_Content_89 = {
    Text = "來吧，接受亞蘭的血脈，成為我們的一員吧。"
  },
  AvgDialog_43803_Content_9 = {
    Text = "守密人，你來了。我和朵爾在討論接下來的安排。"
  },
  AvgDialog_43803_Content_90 = {
    Text = "靠近我，擁抱我……給我你的血，你的種……"
  },
  AvgDialog_43803_Content_91 = {
    Text = "火光在她狂熱的瞳孔中躍動，暈紅的臉頰流露出病態的渴求。"
  },
  AvgDialog_43803_Content_92 = {
    Text = "只要一滴就好，只要我們的骨血交融，祂便會賜予我們渴望的未來……"
  },
  AvgDialog_43803_Content_93 = {
    Text = "讓我們……為族群誕下子嗣，同享永恆的……"
  },
  AvgDialog_43803_Content_94 = {
    Text = "你的理智告訴你你應當拒絕，你對亞蘭族一無所知，這瘋狂的儀式不知會將你帶往何方。"
  },
  AvgDialog_43803_Content_95 = {
    Text = "但你的手腳不聽使喚，那蠱惑的聲音支配了你的四肢和靈魂，喚醒你本能的欲求與渴望。"
  },
  AvgDialog_43803_Content_96 = {
    Text = "你滴酒未沾，卻覺得自己醉了，醉眼裡世間萬物美得朦朧，美得輕飄，唯有來自生命本源的呼喚縈繞。"
  },
  AvgDialog_43803_Content_99 = {
    Text = "<Big:將種子播撒至大地，讓<Red:血脈>湧流卡達斯！>"
  },
  AvgDialog_43804_Content_1 = {
    Text = "不必太過擔心，艾爾瓦大人雖然嚴厲，但相當通情達理。"
  },
  AvgDialog_43804_Content_2 = {
    Text = "稍後，我會邀請各位去我的營帳中詳談。\n在那之前，還是先消滅這些努比亞吧。"
  },
  AvgDialog_43804_Content_3 = {
    Text = "我見識過你們的身手，驅逐這些穢物應該不在話下吧？"
  },
  AvgDialog_43805_Content_10 = {
    Text = "外面的聲音已經停了。"
  },
  AvgDialog_43805_Content_11 = {
    Text = "去拜訪艾爾瓦族長吧。"
  },
  AvgDialog_43805_Content_12 = {
    Text = "去找於麗埃特商量一下吧。"
  },
  AvgDialog_43805_Content_13 = {
    Text = "是啊，原地打轉總不是辦法。"
  },
  AvgDialog_43805_Content_14 = {
    Text = "萊克推開門簾，身形一抖，僵在原地。"
  },
  AvgDialog_43805_Content_15 = {
    Text = "怎麼了，萊克？"
  },
  AvgDialog_43805_Content_16 = {
    Text = "萊克沒有回應，你好奇地朝著他的背後走去。"
  },
  AvgDialog_43805_Content_17 = {
    Text = "他深深地吸了一口氣，喉嚨裡擠出嘶啞的聲音。"
  },
  AvgDialog_43805_Content_18 = {
    Text = "你們先……不要過來。"
  },
  AvgDialog_43805_Content_19 = {
    Text = "這不可能，萊克，我們總不能被困在這個帳篷……"
  },
  AvgDialog_43805_Content_2 = {
    Text = "我是什麼時候……睡著的？"
  },
  AvgDialog_43805_Content_20 = {
    Text = "你的語調停滯了。"
  },
  AvgDialog_43805_Content_21 = {
    Text = "萊克說得對，你不該看到眼前的景象的。\n但慘劇釘住了你的瞳孔，讓你無法移開視線。"
  },
  AvgDialog_43805_Content_22 = {
    Text = "那是血水的地獄，是生殖的災難，是叛離人倫常理、違犯自然規律的怪誕夢魘。"
  },
  AvgDialog_43805_Content_23 = {
    Text = "最骯髒的鼠洞亦無法描繪眼前的狼藉，新生的柔軟肢體與胎盤絞纏成畸形的輪廓，赤色的漿液沒入沙漠的肌理。"
  },
  AvgDialog_43805_Content_24 = {
    Text = "空氣中彌漫的體液腥氣帶著幾分衝擊靈魂的鐵銹味，令人幾欲作嘔。"
  },
  AvgDialog_43805_Content_25 = {
    Text = "風揭起女王營帳的簾幕，泰旖絲從中緩緩步出。"
  },
  AvgDialog_43805_Content_26 = {
    Text = "她抬手指向遙遠的被沙丘分割的地平線，隨著她的動作，初升的朝陽綻出第一縷光芒。"
  },
  AvgDialog_43805_Content_27 = {
    Text = "刹那間，無數營帳中齊刷刷爆發出嬰兒的啼哭聲，交織成一片新生命的交響曲。"
  },
  AvgDialog_43805_Content_28 = {
    Text = "但你在其中絲毫感受不到新生的喜悅，只有從頭至腳徹骨的寒意。"
  },
  AvgDialog_43805_Content_29 = {
    Text = "最近，努比亞的襲擊越來越頻繁，也該舉行篝火儀式了。"
  },
  AvgDialog_43805_Content_3 = {
    Text = "帳外悄無聲息，昨夜異樣扭曲狂熱的盛筵彷彿一場業已消散的噩夢。"
  },
  AvgDialog_43805_Content_30 = {
    Text = "那並非鼓舞士氣的典儀，而是補充兵力的繁殖集會。\n他們將生命視為什麼？某種生存的工具嗎？"
  },
  AvgDialog_43805_Content_31 = {
    Text = "根據記載，欲之質體的權能與生殖和繁育相關。"
  },
  AvgDialog_43805_Content_32 = {
    Text = "豐穰母樹根植於被稱為聖河的卡拉蓋河之源，豐沃兩岸水土，也賜予亞蘭人超越常人的生殖能力。"
  },
  AvgDialog_43805_Content_33 = {
    Text = "仰賴聖河的哺育，亞蘭血脈才得以在生存環境惡劣的勒姆瓦希沙漠祖輩延續。"
  },
  AvgDialog_43805_Content_34 = {
    Text = "哺育、豐沃、延續……這些慈愛的詞彙的具現化，竟是如此污濁與殘忍。"
  },
  AvgDialog_43805_Content_35 = {
    Text = "現在，擺在我們面前的有兩條路。"
  },
  AvgDialog_43805_Content_36 = {
    Text = "繼續跟隨亞蘭人部隊前進，或者脫離隊伍，自行想辦法達成任務目標。"
  },
  AvgDialog_43805_Content_37 = {
    Text = "為了極致的繁衍速度而隨意拋棄畸形胎兒的行為，在文明社會等同於一樁集體謀殺案，我知道你很難視而不見。"
  },
  AvgDialog_43805_Content_38 = {
    Text = "何況，這場景中還有謎團——你注意到畸形胎的比例了嗎？"
  },
  AvgDialog_43805_Content_39 = {
    Text = "豐穰母樹賜予亞蘭人一夜之間懷孕分娩的超強生殖力，為何又讓正常胎兒的比例十不存一？"
  },
  AvgDialog_43805_Content_4 = {
    Text = "不知道，我醒來的時候，你已經睡過去了。"
  },
  AvgDialog_43805_Content_40 = {
    Text = "看吧，無論是從彌薩格調查員還是偵探的角度，前者都是必然的選擇。\n我們必須呆在離目標和真相最近的地方，不是嗎？"
  },
  AvgDialog_43805_Content_41 = {
    Text = "不等你做出答覆，眼前的部隊動了起來，自族長營帳開始，亞蘭人在多個營帳前奔忙呼喊，然後所有人離開營帳，開始整裝。"
  },
  AvgDialog_43805_Content_42 = {
    Text = "發生什麼事了？"
  },
  AvgDialog_43805_Content_43 = {
    Text = "努比亞，大群努比亞在襲擊營地，前方的衛兵擋不住了！"
  },
  AvgDialog_43805_Content_44 = {
    Text = "這麼巧合，宴會剛結束，努比亞就發動了進攻？"
  },
  AvgDialog_43805_Content_45 = {
    Text = "誰知道呢，總是這樣，這該死的野獸從不讓人放鬆！"
  },
  AvgDialog_43805_Content_46 = {
    Text = "你們也快跑吧，現在沒人顧得上照顧你們！"
  },
  AvgDialog_43805_Content_47 = {
    Text = "我們要見艾爾瓦，她在哪兒？"
  },
  AvgDialog_43805_Content_48 = {
    Text = "族長大人在前線指揮！"
  },
  AvgDialog_43805_Content_49 = {
    Text = "左側縱隊，聚攏！遷徙還沒完成，別放任何一隻努比亞過去！"
  },
  AvgDialog_43805_Content_5 = {
    Text = "萊克呢？"
  },
  AvgDialog_43805_Content_50 = {
    Text = "奈恩，守住你那一側！手腳發軟別硬撐，讓瓦杰特頂上！"
  },
  AvgDialog_43805_Content_51 = {
    Text = "你們來這裡做什麼？\n沒看到前線戰事正忙嗎？"
  },
  AvgDialog_43805_Content_52 = {
    Text = "亞蘭族不歡迎拒絕誕下「種子」的客人，請各位自便吧！"
  },
  AvgDialog_43805_Content_53 = {
    Text = "艾爾瓦大人，容我說幾句？"
  },
  AvgDialog_43805_Content_54 = {
    Text = "%player%闖入女王營帳是無心之失，女王大人也並未動怒，對吧？"
  },
  AvgDialog_43805_Content_55 = {
    Text = "一定要算起來，沒說清楚原則就讓%heorshe%獨自在女王營帳等待的我也有一半責任。"
  },
  AvgDialog_43805_Content_56 = {
    Text = "你怔怔地望著於麗埃特，她眸色顫動，輕微搖頭，似在提醒你切勿多言。"
  },
  AvgDialog_43805_Content_57 = {
    Text = "你不知道她為何要包庇你，但你沒有不承情的理由。"
  },
  AvgDialog_43805_Content_58 = {
    Text = "近期努比亞的襲擊越發頻繁，在對抗這些邪物上，他們或許能出一份力。"
  },
  AvgDialog_43805_Content_6 = {
    Text = "拉蒙娜向著帳篷門一指。"
  },
  AvgDialog_43805_Content_60 = {
    Text = "就讓他們跟著你吧。"
  },
  AvgDialog_43805_Content_61 = {
    Text = "看好他們，別讓我在主營帳附近看見他們。\n否則，可就不是逐出營地那麼簡單了。"
  },
  AvgDialog_43805_Content_7 = {
    Text = "萊克依靠著門口熟睡，似乎被你起身的動靜驚醒，一雙絨耳迅速地抖了抖，眼睫抖動兩下，睜開狹長的狼眼。"
  },
  AvgDialog_43805_Content_8 = {
    Text = "昨天的……儀式，那不是夢，對吧？"
  },
  AvgDialog_43805_Content_9 = {
    Text = "為保持倫蒂尼恩紳士的風度，我本不該隨意指摘他人的生活作風，但這些原始人的儀式，還是太過火了。"
  },
  AvgDialog_43806_Content_1 = {
    Text = "這樣的大傢伙要是一次多來幾隻，我這把老腰可真就撐不住了。"
  },
  AvgDialog_43806_Content_10 = {
    Text = "等等，那個是——"
  },
  AvgDialog_43806_Content_11 = {
    Text = "那是一個人捆著努比亞在沙地拖行，沙海的風吹落他黑袍的帽檐，冰冷的月光照得一頭金絲閃閃發亮。"
  },
  AvgDialog_43806_Content_12 = {
    Text = "威廉學長！"
  },
  AvgDialog_43806_Content_2 = {
    Text = "據艾爾瓦所說，這些只是小族群的首領，真正的威脅只怕遠比這只來得恐怖。"
  },
  AvgDialog_43806_Content_3 = {
    Text = "別說了，撞上之前就讓我當不知道，再瀟灑過幾天舒爽日子吧。"
  },
  AvgDialog_43806_Content_4 = {
    Text = "還不是放鬆警惕的時候！%player%，你看那邊！"
  },
  AvgDialog_43806_Content_5 = {
    Text = "你們早已看厭的怪異輪廓自暗夜的沙丘後浮現，朝你們蹣跚蠕動而來。"
  },
  AvgDialog_43806_Content_6 = {
    Text = "還有漏網之魚？"
  },
  AvgDialog_43806_Content_7 = {
    Text = "來吧，讓你們也享受一下三局連勝的喜悅！"
  },
  AvgDialog_43806_Content_8 = {
    Text = "不對，還是有哪裡不對——"
  },
  AvgDialog_43806_Content_9 = {
    Text = "定睛細看，這只努比亞的行動格外遲緩而僵硬。"
  },
  AvgDialog_43807_Content_1 = {Text = "軌跡"},
  AvgDialog_43807_Content_10 = {
    Text = "和戰鬥中一樣……"
  },
  AvgDialog_43807_Content_11 = {
    Text = "失敗了。"
  },
  AvgDialog_43807_Content_12 = {
    Text = "我想，兩位小朋友已經等不及要聽學長的解說了。"
  },
  AvgDialog_43807_Content_13 = {
    Text = "威廉推了推眼鏡，向你們點了點頭。"
  },
  AvgDialog_43807_Content_14 = {
    Text = "這是我們迄今為止採集到的唯一一隻完整的努比亞樣本。"
  },
  AvgDialog_43807_Content_15 = {
    Text = "在今年之前，努比亞幾乎沒有目擊紀錄，它出現在勒姆瓦希沙漠是近期的事情，但在極短的時間內就遍佈沙漠，侵蝕亞蘭人的生存領域。"
  },
  AvgDialog_43807_Content_16 = {
    Text = "生物變異不足以解釋其起源，人工改造更契合它出現的契機和狀況。"
  },
  AvgDialog_43807_Content_17 = {
    Text = "你的意思是，有人在製造努比亞？"
  },
  AvgDialog_43807_Content_18 = {
    Text = "威廉頷首，似是滿意你的猜想。"
  },
  AvgDialog_43807_Content_19 = {
    Text = "而且在刻意隱瞞來源。切割努比亞的任意部位，內部都會快速伸出觸手修補傷口，讓傷痕留在內部。"
  },
  AvgDialog_43807_Content_2 = {
    Text = "粗糙原始的帳篷中央、努比亞瘫軟的身體耸立成一座黑色的肉山、昏暗的燈光讓陰影也變得陰森可怖。"
  },
  AvgDialog_43807_Content_20 = {
    Text = "若是受到致命傷、則會快速汽化消失、不留下任何可供探究的痕跡。\n要知道、通常的融蝕漿並不會在這麼短時間內自然消失。"
  },
  AvgDialog_43807_Content_21 = {
    Text = "這些傢伙的「設計者」在隱瞞什麼。"
  },
  AvgDialog_43807_Content_22 = {
    Text = "相比它們的內部結構，我更關心努比亞的出沒軌跡。"
  },
  AvgDialog_43807_Content_23 = {
    Text = "這幾天，我一直在向亞蘭人打聽消息。根據他們的描述，每當他們停下腳步，紮營多日或舉辦儀式，原本靜止不動的努比亞群就會襲擊營地。"
  },
  AvgDialog_43807_Content_24 = {
    Text = "我的直覺告訴我，這些努比亞在將亞蘭人向著某個方位驅趕。"
  },
  AvgDialog_43807_Content_25 = {
    Text = "威廉掏出地圖，將努比亞密集的點位一一標注。"
  },
  AvgDialog_43807_Content_26 = {
    Text = "還要結合亞蘭人的遷移路徑。"
  },
  AvgDialog_43807_Content_27 = {
    Text = "萊克用大頭針固定紅色棉線，沿著亞蘭人告知的點位描繪出路徑。"
  },
  AvgDialog_43807_Content_28 = {
    Text = "黑色的陰翳追在紅線之後，步步緊逼，逐漸將紅線推向聖河源頭的所在。"
  },
  AvgDialog_43807_Content_29 = {
    Text = "你的直覺一向很准。"
  },
  AvgDialog_43807_Content_3 = {
    Text = "威廉從裹腿的夾層中摸出精密的手術刀具，手術刀、手術剪、細齒鑷、止血鉗排成不鏽鋼的小隊。"
  },
  AvgDialog_43807_Content_30 = {
    Text = "聖河源頭，隱匿於風暴之壁內。"
  },
  AvgDialog_43807_Content_31 = {
    Text = "有人不願意亞蘭人徘徊在風暴之壁外，他在壓縮亞蘭人的生存圈，逼迫亞蘭人進入風暴之壁。"
  },
  AvgDialog_43807_Content_32 = {
    Text = "案件的輪廓已經浮現，whydunit（動機）和howdunit（手法）已經揭露。"
  },
  AvgDialog_43807_Content_33 = {
    Text = "那麼問題就來了，whodunit（誰是兇手）？"
  },
  AvgDialog_43807_Content_34 = {
    Text = "線索太少，現在還無法判斷。\n先同步一下近期的見聞吧，線索總能輔助判斷。"
  },
  AvgDialog_43807_Content_37 = {
    Text = "我們需要更多關於努比亞的資訊。"
  },
  AvgDialog_43807_Content_38 = {
    Text = "你們的主要任務依然未變：探查女王營帳中母樹遺骸的真相，俟機破壞它。"
  },
  AvgDialog_43807_Content_39 = {
    Text = "我會繼續努比亞的研究。"
  },
  AvgDialog_43807_Content_4 = {
    Text = "沒想到學長還隨身帶著這個，是打算改行救死扶傷嗎？"
  },
  AvgDialog_43807_Content_40 = {
    Text = "我有種預感，亞蘭族與豐穰母樹的真相，就藏在這些努比亞的來源之後。"
  },
  AvgDialog_43807_Content_41 = {
    Text = "威廉說著，轉身拿起了斗篷。"
  },
  AvgDialog_43807_Content_42 = {
    Text = "威廉學長就要離開了嗎？"
  },
  AvgDialog_43807_Content_43 = {
    Text = "趕在天明之前出發。\n注意，別讓於麗埃特知道我的動向。"
  },
  AvgDialog_43807_Content_44 = {
    Text = "威廉掀簾而出，回身叮囑你們，幾乎與來人撞了個滿懷。"
  },
  AvgDialog_43807_Content_45 = {
    Text = "自與各位在聖河相遇，我似乎給諸位提供了諸多便捷，並未有危害之舉，威廉先生為何如此警惕我呀？"
  },
  AvgDialog_43807_Content_46 = {
    Text = "狹小的營帳內空氣緊繃，一時無人作答，原本燥熱的沙海之風竟顯出幾分陰冷。"
  },
  AvgDialog_43807_Content_47 = {
    Text = "數秒後，還是於麗埃特打破了沉默。"
  },
  AvgDialog_43807_Content_48 = {
    Text = "開個玩笑罷了，不必如此緊張。"
  },
  AvgDialog_43807_Content_49 = {
    Text = "於麗埃特小姐太誇張了，大家這一路相處愉快，只是威廉先生生性孤僻，不喜歡跟陌生人相處罷了……"
  },
  AvgDialog_43807_Content_5 = {
    Text = "威廉沒理會你的打趣，緊簇雙眉，謹慎地切下第一刀。"
  },
  AvgDialog_43807_Content_50 = {
    Text = "萊克滿嘴跑起了火車，你注意到躺在床褥裡的拉蒙娜忍不住翻了個白眼。"
  },
  AvgDialog_43807_Content_51 = {
    Text = "咳，所以，總之，於麗埃特小姐深夜來訪，是有什麼重要的事情要商量嗎？"
  },
  AvgDialog_43807_Content_52 = {
    Text = "說重要倒也沒多重要——來吧，到我帳篷裡再談。"
  },
  AvgDialog_43807_Content_6 = {
    Text = "手術刀切入努比亞的軀體，沒有如預想般流出黑色的黏液。"
  },
  AvgDialog_43807_Content_7 = {
    Text = "威廉神經緊繃，緩緩將刀鋒深入，然後向下劃出——"
  },
  AvgDialog_43807_Content_9 = {
    Text = "被刺穿的努比亞瞬間化為一灘黑泥，轉眼汽化，手術臺上潔淨得彷彿不曾存在過任何穢物。"
  },
  AvgDialog_43808_Content_1 = {
    Text = "這片意識空間中彙聚的聲音，是從古至今所有亞蘭人意識的集合。"
  },
  AvgDialog_43808_Content_10 = {
    Text = "於麗埃特跪在搖籃前，虔誠地哼唱著歌謠。"
  },
  AvgDialog_43808_Content_11 = {
    Text = "她的哼唱沒有歌詞，你卻知曉這支旋律。"
  },
  AvgDialog_43808_Content_12 = {
    Text = "她將襁褓捧起，沒入聖河之中。"
  },
  AvgDialog_43808_Content_13 = {
    Text = "流沙很快掩埋了剛剛逝去的生命。"
  },
  AvgDialog_43808_Content_14 = {
    Text = "死亡已經迫近，消亡已經起始。"
  },
  AvgDialog_43808_Content_15 = {
    Text = "歌聲優美而惆悵，帶著幾分悲涼，隨著聖河之水蜿蜒向遠方。"
  },
  AvgDialog_43808_Content_16 = {
    Text = "凌晨4：00 旅客營帳"
  },
  AvgDialog_43808_Content_17 = {
    Text = "我總結一下："
  },
  AvgDialog_43808_Content_18 = {
    Text = "對亞蘭人來說，豐穰母樹再不復生，整條聖河都會乾涸，勒姆瓦希將會淪為徹底的荒沙之國。"
  },
  AvgDialog_43808_Content_19 = {
    Text = "於麗埃特意圖復甦母樹，並教化亞蘭人接受和適應現代生活。"
  },
  AvgDialog_43808_Content_2 = {
    Text = "亞蘭人……在哭泣？"
  },
  AvgDialog_43808_Content_20 = {
    Text = "但達芙黛爾的消息源告訴我們，一旦豐穰母樹復生，就可能爆發全球級的融蝕。"
  },
  AvgDialog_43808_Content_21 = {
    Text = "聖樹遺骸就在女王營帳中，要是在進入風暴之壁前成功破壞聖樹遺骸，多半能以最小的代價完成任務。"
  },
  AvgDialog_43808_Content_22 = {
    Text = "所以，問題來了，在你們眼裡，那個名叫達芙黛爾的商人信譽如何？她的消息源可靠嗎？"
  },
  AvgDialog_43808_Content_23 = {
    Text = "阿利斯泰爾盡力了，只確認了的確有人蓄意傳遞這條消息，消息的準確度無法評估。"
  },
  AvgDialog_43808_Content_24 = {
    Text = "貿然燒毀聖樹遺骸，或許會斬斷亞蘭人最後的退路。"
  },
  AvgDialog_43808_Content_25 = {
    Text = "在融蝕面前，我們也沒有退路。\n不要讓無益的慈悲干擾你的判斷。"
  },
  AvgDialog_43808_Content_26 = {
    Text = "沒關係的，朵爾。就算最後要硬闖儀式現場去焚燒母樹，我也絕對奉陪。"
  },
  AvgDialog_43808_Content_27 = {
    Text = "我贊同守密人的看法，我們對亞蘭相關的一切知之甚少，現在發起進攻也有失謹慎。"
  },
  AvgDialog_43808_Content_28 = {
    Text = "我對努比亞的研究還會繼續。\n守密人、萊克，聖樹遺骸的調查就交給你們了。"
  },
  AvgDialog_43808_Content_3 = {
    Text = "是的，亞蘭人的靈魂在哀泣。\n因為生的罪惡和死的恐懼。"
  },
  AvgDialog_43808_Content_4 = {
    Text = "若我能帶領亞蘭人穿越風暴之壁，尋回豐穰母樹……\n亞蘭人就會將我視為新的領袖。"
  },
  AvgDialog_43808_Content_5 = {
    Text = "到那時候，我要結束這邪祟病態的儀式，讓亞蘭人永遠脫離這片荒蕪惡劣的沙漠。"
  },
  AvgDialog_43808_Content_6 = {
    Text = "所有人都會定居於純潔無垢的樂土，不必為生來即背負的罪惡而痛苦。"
  },
  AvgDialog_43808_Content_7 = {
    Text = "%player%，請你們助我一臂之力。"
  },
  AvgDialog_43808_Content_8 = {
    Text = "你從夢境中甦醒，於麗埃特胸口的孩子已經停止了呼吸。"
  },
  AvgDialog_43808_Content_9 = {
    Text = "讓他歸還聖河吧。"
  },
  AvgDialog_43809_Content_10 = {
    Text = "於麗埃特揉了揉少年毛絨絨的腦袋。"
  },
  AvgDialog_43809_Content_11 = {
    Text = "好的，如果有任何需要幫忙的地方……"
  },
  AvgDialog_43809_Content_12 = {
    Text = "少年警惕地打量了你們幾眼。"
  },
  AvgDialog_43809_Content_13 = {
    Text = "隨時叫醒我就好。"
  },
  AvgDialog_43809_Content_14 = {
    Text = "少年離去，於麗埃特朝著你們抱歉一笑。"
  },
  AvgDialog_43809_Content_15 = {
    Text = "抱歉，他有些照顧過頭了。"
  },
  AvgDialog_43809_Content_16 = {
    Text = "你猜得沒錯，他就是這批孩子裡面成長最快的那個。"
  },
  AvgDialog_43809_Content_17 = {
    Text = "與之相對的……"
  },
  AvgDialog_43809_Content_18 = {
    Text = "於麗埃特將你們引至一個簡陋的搖籃旁。"
  },
  AvgDialog_43809_Content_19 = {
    Text = "看看這個孩子吧。"
  },
  AvgDialog_43809_Content_2 = {
    Text = "凌晨2：00 使者營帳"
  },
  AvgDialog_43809_Content_20 = {
    Text = "那是一個還在襁褓中的嬰孩，樹狀的黑暗紋路爬滿他的全身。"
  },
  AvgDialog_43809_Content_21 = {
    Text = "表面看不出畸形，實際已經被母樹的疾病侵染。"
  },
  AvgDialog_43809_Content_22 = {
    Text = "把手搭在他的皮膚上試試。"
  },
  AvgDialog_43809_Content_23 = {
    Text = "你依言觸碰孩子體表。那並非你想像中嬰孩柔滑的肌膚，而是一種仿若粗糙乾裂樹皮的枯澀質感。"
  },
  AvgDialog_43809_Content_3 = {
    Text = "使者營帳中佈滿床褥，數個五六歲大小的孩子蜷縮在床鋪中酣睡。\n一個英氣的少年向你們迎來。"
  },
  AvgDialog_43809_Content_4 = {
    Text = "於麗埃特大人，您回來了。"
  },
  AvgDialog_43809_Content_5 = {
    Text = "涅弗魯瑞，我的乖孩子。\n大家都休息了嗎？"
  },
  AvgDialog_43809_Content_6 = {
    Text = "是的，於麗埃特大人。"
  },
  AvgDialog_43809_Content_7 = {
    Text = "這些孩子是……"
  },
  AvgDialog_43809_Content_8 = {
    Text = "今天之前，你還沒在亞蘭人隊伍中見過任何未成年人。"
  },
  AvgDialog_43809_Content_9 = {
    Text = "涅弗魯瑞，你先去休息吧。\n把大家都哄睡著很不容易，明天請艾爾瓦大人獎勵你。"
  },
  AvgDialog_43816_Content_10 = {
    Text = "油滑的男聲對準了失神的你——正窘迫地在聚光燈下胡亂打轉的你。"
  },
  AvgDialog_43816_Content_11 = {
    Text = "身邊的女孩們像天鵝一樣舒展著身體，舞步整齊劃一，展現著富有韻律的美。"
  },
  AvgDialog_43816_Content_12 = {
    Text = "某個人卻表現得像一隻誤入天鵝群的野鴨。"
  },
  AvgDialog_43816_Content_13 = {
    Text = "你幾乎立刻意識到這是一名舞者的身體——可身體的記憶尚未完全回籠，就連走路都是磕磕絆絆，更別提記起那些複雜的舞步了。"
  },
  AvgDialog_43816_Content_14 = {
    Text = "淨知道添亂，你這「首席」可真稱職。"
  },
  AvgDialog_43816_Content_16 = {
    Text = "沒有人回答你的問題，舞者們腳步不停，列隊從你身邊靈活地滑了過去——但在過程中，不知誰的手肘大力撞在了你身上。"
  },
  AvgDialog_43816_Content_17 = {
    Text = "你失去平衡地踉蹌了兩步，舞蹈隊形變換間，你已經被擠到了舞台的邊緣，但並沒能逃開觀眾毒辣的視線——"
  },
  AvgDialog_43816_Content_18 = {
    Text = "舞台之下並沒有設置排列的觀眾席，偌大的空地上，擺著一套套成對的桌椅。"
  },
  AvgDialog_43816_Content_19 = {
    Text = "桌布是點綴著流蘇的華貴綢緞，觀眾的珠寶在暗處反射著舞台的燈光，襯得那些戴著面具的臉更加陰森可怖。"
  },
  AvgDialog_43816_Content_2 = {
    Text = "一、二、三，一、二、三……很好，隊列非常整齊，非常優雅。"
  },
  AvgDialog_43816_Content_20 = {
    Text = "最前列那個孩子怎麼回事？是不是跳錯了？"
  },
  AvgDialog_43816_Content_21 = {
    Text = "哼……跳得好還是壞，她們根本不在乎。這種人的心思，你還不明白嗎？"
  },
  AvgDialog_43816_Content_22 = {
    Text = "也是。還別說，雖然跳得不怎麼樣，可她那身段實在是……"
  },
  AvgDialog_43816_Content_23 = {
    Text = "<Small:這些人好像不是普通的舞蹈觀眾……>"
  },
  AvgDialog_43816_Content_24 = {
    Text = "你還在發什麼呆！"
  },
  AvgDialog_43816_Content_25 = {
    Text = "養尊處優的肥厚手掌抓住了裸露的上臂，試圖把你拉進舞台帷幕的陰影中。"
  },
  AvgDialog_43816_Content_26 = {
    Text = "你差點毀掉了這場舞！這可是正式公演前最後一次排演了，你腦子裡究竟在想些什麼！"
  },
  AvgDialog_43816_Content_28 = {
    Text = "樂器一聲聲奏在耳膜上，眼前陣陣發黑，舞步的落點始終被困在記憶的迷霧中。男人的拖拽給了你機會，你順勢借力想要離開舞台——"
  },
  AvgDialog_43816_Content_29 = {
    Text = "不准走，我上台以後，需要人平衡隊列陣型。\n去隊列左後方填補空缺，模仿我的舞步。"
  },
  AvgDialog_43816_Content_3 = {
    Text = "弦樂與管樂在身後響起，與地板踏擊聲交織成工整又優雅的噪音，在感官上跳著格外刺激的舞。"
  },
  AvgDialog_43816_Content_30 = {
    Text = "男人的手被一把拍開，在他又驚又喜的眼神中，一隻慘白纖細的手擒住了你的腰，將你帶往燈光之下。"
  },
  AvgDialog_43816_Content_31 = {
    Text = "來人舞步輕靈，順水推舟地用舞步推開了本來已經有些潰散的隊列，強硬地把你塞進了舞者群中。"
  },
  AvgDialog_43816_Content_32 = {
    Text = "舞者們面面相覷，但沒人敢對少女的行為置喙。她們只是對你發出不屑的哼聲，復又低頭擺臂，繼續著舞蹈。"
  },
  AvgDialog_43816_Content_33 = {
    Text = "快！快把光打在她身上！伊麗莎白終於願意上台跳舞了！這是她闊別三個月的首次亮相！"
  },
  AvgDialog_43816_Content_34 = {
    Text = "伊麗莎白？"
  },
  AvgDialog_43816_Content_35 = {
    Text = "你咀嚼著這個名字，想要看向不由分說把你拽到舞台上的少女。"
  },
  AvgDialog_43816_Content_36 = {
    Text = "抬頭的瞬間，二樓燈光猛地劃出一道刺眼的軌跡，直直從你眼睛上碾過，讓你的世界不受控制地墜入一片白。"
  },
  AvgDialog_43816_Content_37 = {
    Text = "——再次睜開眼時，黑色舞裙的少女已經躍到了最前列。"
  },
  AvgDialog_43816_Content_38 = {
    Text = "所有人都為了她的登場而讓路，為她的裙擺留出搖曳的空間。\n在這方不大的舞台上，她是唯一攝人心魄的魔女，是絕對的明星。"
  },
  AvgDialog_43816_Content_39 = {
    Text = "那就是伊麗莎白，亞德里舞團的王牌舞者……天哪，她真美。"
  },
  AvgDialog_43816_Content_4 = {
    Text = "什麼動靜……"
  },
  AvgDialog_43816_Content_40 = {
    Text = "經理，不是說伊麗莎白小姐身體不適，會缺席這次公演嗎？"
  },
  AvgDialog_43816_Content_41 = {
    Text = "各位老爺夫人，這是……伊麗莎白為各位準備的驚喜！沒錯，驚喜。"
  },
  AvgDialog_43816_Content_42 = {
    Text = "雖然身體抱恙，但作為這齣新劇目的排演者，伊麗莎白不會讓任何一次舞台出現紕漏！"
  },
  AvgDialog_43816_Content_43 = {
    Text = "舞團經理驕傲地挺起了胸，目光逡巡的模樣像極了一隻索敵的鬥雞。"
  },
  AvgDialog_43816_Content_45 = {
    Text = "一雙冷淡的綠色眼眸看了過來，下一秒，你的身體就像受到威懾一般，調動起了肌肉記憶。沒兩拍的功夫，身體就帶著你融入了舞者群中。"
  },
  AvgDialog_43816_Content_46 = {
    Text = "沒錯……做得很好。"
  },
  AvgDialog_43816_Content_47 = {
    Text = "成為樹上的葉子，避開那些人的目光，不要再讓他們的眼睛看到你。"
  },
  AvgDialog_43816_Content_48 = {
    Text = "不要讓那些污穢的目光……注意到你。"
  },
  AvgDialog_43816_Content_5 = {
    Text = "從深眠中被音樂鬧醒，無力的四肢本能般舒展著，眼睛卻感覺格外沉重。"
  },
  AvgDialog_43816_Content_6 = {
    Text = "上下眼皮緊緊貼合在一起，無論怎麼努力，都沒法睜開哪怕一絲縫隙。"
  },
  AvgDialog_43816_Content_7 = {
    Text = "嗚……這感覺……是入夢……"
  },
  AvgDialog_43816_Content_8 = {
    Text = "震耳欲聾的音樂聲中，你的意識逐漸獲得了身體的掌控，就在眼睛能夠感受到燈光刺激的瞬間，四肢倏地僵硬了起來。"
  },
  AvgDialog_43816_Content_9 = {
    Text = "跳得非常不錯，我的女孩們。保持這個勢頭，對準音樂的拍子繼續——嘿！別走神！"
  },
  AvgDialog_44435_Content_1 = {Text = "苦咒縛"},
  AvgDialog_44435_Content_2 = {
    Text = "記憶伴隨星光紛亂湧入。"
  },
  AvgDialog_44435_Content_3 = {
    Text = "那些被人為暴力製造、切碎的記憶湧入梅森的腦海，又像潮水般迅速退去。"
  },
  AvgDialog_44435_Content_4 = {
    Text = "直到最後，她來到雪山腳下，那個漆黑的洞穴入口。"
  },
  AvgDialog_44435_Content_5 = {
