  },
  AvgDialog_45426_Content_104 = {
    Text = "為了讓告別不那麼悲傷，重逢彌足珍貴……你不必明白。"
  },
  AvgDialog_45426_Content_105 = {
    Text = "但你一定會和他們一起，抵達這段旅程的終點。"
  },
  AvgDialog_45426_Content_106 = {
    Text = "你一時失語。"
  },
  AvgDialog_45426_Content_107 = {
    Text = "到那時候……請你一定要記得，呼喚我的名字。"
  },
  AvgDialog_45426_Content_108 = {
    Text = "她在你的額頭輕柔一吻。"
  },
  AvgDialog_45426_Content_109 = {
    Text = "你神思一恍，她蕩出幾步，你伸出手臂，卻觸之不及。"
  },
  AvgDialog_45426_Content_11 = {
    Text = "明天就是母樹復生儀式了。\n女王大人這時候找我……有什麼事嗎？"
  },
  AvgDialog_45426_Content_110 = {
    Text = "你目送她遠去的身影越來越小，最終化為砂礫般渺小的一點，消失在皎潔的月光中。"
  },
  AvgDialog_45426_Content_12 = {
    Text = "話出口時，你就意識到自己語氣不善。"
  },
  AvgDialog_45426_Content_13 = {
    Text = "我……看見了。\n你同伴的事情……我很遺憾。"
  },
  AvgDialog_45426_Content_14 = {
    Text = "無可避免的沉默在你們之間徘徊。"
  },
  AvgDialog_45426_Content_15 = {
    Text = "這件事與亞蘭無關。"
  },
  AvgDialog_45426_Content_16 = {
    Text = "這不是泰旖絲的錯誤，你在內心叮囑自己，但脫口而出的話還是像在沙丘中警惕的刺蝟。"
  },
  AvgDialog_45426_Content_17 = {
    Text = "母樹復生儀式……你一定也有準備工作要做吧？"
  },
  AvgDialog_45426_Content_18 = {
    Text = "你試著補救，但說出口的話語仍像是冰冷的推拒。"
  },
  AvgDialog_45426_Content_19 = {
    Text = "你覺得，母樹復生之後，亞蘭族會前往何方？"
  },
  AvgDialog_45426_Content_2 = {
    Text = "在這次旅途中，你見證過很多人的離開。\n但沒有哪怕一次死亡，是如此令人窒息的輕描淡寫。"
  },
  AvgDialog_45426_Content_20 = {
    Text = "你沉默不語。"
  },
  AvgDialog_45426_Content_21 = {
    Text = "我知道彌薩格來到勒姆瓦希的目的，也知道你們為何遲遲沒有行動。"
  },
  AvgDialog_45426_Content_22 = {
    Text = "我很感謝你們，給了亞蘭一個機會。"
  },
  AvgDialog_45426_Content_23 = {
    Text = "但這個機會已經不存在了。"
  },
  AvgDialog_45426_Content_24 = {
    Text = "泰旖絲，你知道豐穰母樹已經被融蝕污染了嗎？"
  },
  AvgDialog_45426_Content_27 = {
    Text = "那麼，你就應該知道，彌薩格不會坐視融蝕的擴散。"
  },
  AvgDialog_45426_Content_28 = {
    Text = "我會阻止母樹的降生。\n泰旖絲，我們已經是敵人了。"
  },
  AvgDialog_45426_Content_29 = {
    Text = "原本清爽的沙海之風突然變得凝稠粘滯起來，呼吸間的沙塵似乎刮擦著你的嗓子，讓喉嚨隱隱發痛。"
  },
  AvgDialog_45426_Content_3 = {
    Text = "何況那是威廉——\n彌薩格的傳奇調查員，你在調查員這條道路上的引路人。"
  },
  AvgDialog_45426_Content_30 = {
    Text = "令你訝異的是，泰旖絲沒有退避，而是湊近前來，將你擁入懷中。"
  },
  AvgDialog_45426_Content_32 = {
    Text = "我無意對你們做出任何傷害，更不會做出有損亞蘭族利益之事。"
  },
  AvgDialog_45426_Content_33 = {
    Text = "但亞蘭人無路可選。許多年前，女王的神力就已經衰竭，甚至連守護母樹都再難做到。"
  },
  AvgDialog_45426_Content_34 = {
    Text = "只能借勒姆瓦希自身地脈之力，以風暴之壁掩蓋母樹的所在。"
  },
  AvgDialog_45426_Content_35 = {
    Text = "你的意思是……風暴之壁，是女王之力喚來的？"
  },
  AvgDialog_45426_Content_36 = {
    Text = "是。風暴之壁……會將虛假的使者拒之門外。"
  },
  AvgDialog_45426_Content_37 = {
    Text = "但每次舉行儀式，都有很多亞蘭人會死去！"
  },
  AvgDialog_45426_Content_38 = {
    Text = "只要繁衍之力仍在，亞蘭族就不會消亡。"
  },
  AvgDialog_45426_Content_39 = {
    Text = "所以你就任由他們進行這樣詛咒般的儀式，任由他們一次次淪陷在風暴之壁裡？"
  },
  AvgDialog_45426_Content_4 = {
    Text = "究竟什麼人，可以在近在咫尺的距離內，無聲無息地殺死一位傳奇調查員？"
  },
  AvgDialog_45426_Content_40 = {
    Text = "這是亞蘭人的命運，我們生於此，長於此。"
  },
  AvgDialog_45426_Content_41 = {
    Text = "無數人為你這病態的信仰付出了生命！"
  },
  AvgDialog_45426_Content_42 = {
    Text = "現在，不僅是你的族人，還有威廉學長……"
  },
  AvgDialog_45426_Content_43 = {
    Text = "你的尾音帶著輕微的哽咽，你幾乎無法辨出那是自己的聲音。"
  },
  AvgDialog_45426_Content_44 = {
    Text = "告訴我，泰旖絲，你不是真心這麼想的，對嗎？"
  },
  AvgDialog_45426_Content_45 = {
    Text = "泰旖絲沒有回答你的問題。"
  },
  AvgDialog_45426_Content_46 = {
    Text = "她只是將手臂又攏了攏。"
  },
  AvgDialog_45426_Content_47 = {
    Text = "我知道你很疲憊，很憤怒……"
  },
  AvgDialog_45426_Content_48 = {
    Text = "你對我有怨氣，有不理解。\n但我也有我的苦衷。"
  },
  AvgDialog_45426_Content_49 = {
    Text = "我給你講一個故事吧，一個很長很長的故事。"
  },
  AvgDialog_45426_Content_5 = {
    Text = "你虛脫無力地倒退兩步，撞上一個高大的身影。"
  },
  AvgDialog_45426_Content_50 = {
    Text = "很久很久以前，遠在洪積發生前的數千年，有一個文明，她們信仰名為豐穰母樹的神祗。"
  },
  AvgDialog_45426_Content_51 = {
    Text = "然而母樹的意志無法鞏固帝國的統治，他們便生出了一個計謀。"
  },
  AvgDialog_45426_Content_52 = {
    Text = "他們選中許多女孩，逼迫她們飲下母樹鮮紅的乳汁，在母樹的汁液中沐浴，直至女孩與樹融為一體。"
  },
  AvgDialog_45426_Content_53 = {
    Text = "從那之後，傀儡般的女孩即代表了樹的意志。"
  },
  AvgDialog_45426_Content_54 = {
    Text = "但從來沒有人聽她的聲音，服從她的話語。因為女孩沒有自己的聲音，也沒有自己的意志。她所傳達的，都是尼尼微君王勒令她背誦的話語。"
  },
  AvgDialog_45426_Content_55 = {
    Text = "出聲反抗那一年，女孩十五歲。"
  },
  AvgDialog_45426_Content_56 = {
    Text = "為什麼？為什麼要殺掉他，他可是阿梅耶特的父親！"
  },
  AvgDialog_45426_Content_57 = {
    Text = "他觸犯了禁忌，泰旖絲。他在戰場上逃跑了。"
  },
  AvgDialog_45426_Content_58 = {
    Text = "那場仗已經徹底潰敗了，只有他一個人活下來，他不可能獨自一個人對抗那麼多敵人！"
  },
  AvgDialog_45426_Content_59 = {
    Text = "戰爭的事情，你還太小，還不懂，泰旖絲。"
  },
  AvgDialog_45426_Content_6 = {
    Text = "我理解你現在的困擾，但現在不是展現脆弱的時候。"
  },
  AvgDialog_45426_Content_60 = {
    Text = "他應當一往無前地衝鋒，然後光榮地死去。"
  },
  AvgDialog_45426_Content_61 = {
    Text = "活下來一個人不好嗎？只要活下一個人……阿梅耶特就可以成為戰士，阿梅耶特的弟弟也可以成為戰士，還有阿梅耶特未來的孩子……"
  },
  AvgDialog_45426_Content_62 = {
    Text = "再說也無益了。"
  },
  AvgDialog_45426_Content_63 = {
    Text = "傳母樹的意志，罪人當受蟲噬之刑。"
  },
  AvgDialog_45426_Content_64 = {
    Text = "我沒有說！"
  },
  AvgDialog_45426_Content_65 = {
    Text = "傳母樹的意志，罪人當受蟲噬之刑。"
  },
  AvgDialog_45426_Content_66 = {
    Text = "我沒有說！"
  },
  AvgDialog_45426_Content_67 = {
    Text = "傳母樹的意志……"
  },
  AvgDialog_45426_Content_69 = {
    Text = "罪人當受蟲噬之刑。"
  },
  AvgDialog_45426_Content_7 = {
    Text = "他……把關鍵的資訊留給了我們。"
  },
  AvgDialog_45426_Content_70 = {
    Text = "女孩絕望而嘹亮的哭喊聲，沒有人聽見。"
  },
  AvgDialog_45426_Content_71 = {
    Text = "你、你是什麼人？"
  },
  AvgDialog_45426_Content_72 = {
    Text = "好孩子，小點聲，聽我的，趕緊跟我走吧。"
  },
  AvgDialog_45426_Content_73 = {
    Text = "你不是第一個被作為樹的傀儡的女孩，每當女孩反抗他們的意志，他們便將女孩獻祭給聖河。"
  },
  AvgDialog_45426_Content_74 = {
    Text = "我沐浴母樹的乳汁而生，我是不死的！"
  },
  AvgDialog_45426_Content_75 = {
    Text = "傻孩子，他們是騙你的。每個人跳進河裡都會淹死的。"
  },
  AvgDialog_45426_Content_76 = {
    Text = "我不會。"
  },
  AvgDialog_45426_Content_77 = {
    Text = "說到底，你是誰啊？我從來沒見過你。"
  },
  AvgDialog_45426_Content_78 = {
    Text = "我負責清掃你的花園，每天天亮之前就會離開，所以你從未見過我。"
  },
  AvgDialog_45426_Content_79 = {
    Text = "但你認識我的孫子……他的名字叫阿梅耶特。"
  },
  AvgDialog_45426_Content_8 = {
    Text = "努比亞的背後，是提燈教會。\n達芙黛爾所言非虛，阻止儀式怕是勢在必行了。"
  },
  AvgDialog_45426_Content_80 = {
    Text = "女孩離開了嗎？"
  },
  AvgDialog_45426_Content_81 = {Text = "沒有。"},
  AvgDialog_45426_Content_82 = {
    Text = "女孩在那個瞬間明白了很多事情。"
  },
  AvgDialog_45426_Content_83 = {
    Text = "原來弄髒的花園不會自己恢復潔淨。"
  },
  AvgDialog_45426_Content_84 = {
    Text = "原來有些東西好似存在卻從未被看見。"
  },
  AvgDialog_45426_Content_85 = {
    Text = "原來不能發出聲音……是那麼痛苦。"
  },
  AvgDialog_45426_Content_86 = {
    Text = "……獻祭儀式那天，她主動跳入了聖河。"
  },
  AvgDialog_45426_Content_87 = {
    Text = "那個瞬間，女孩和樹的意志悠遠地共鳴。"
  },
  AvgDialog_45426_Content_88 = {
    Text = "然後，樹的意志問她："
  },
  AvgDialog_45426_Content_89 = {
    Text = "你願意成為樹的載體，誕下樹的血肉與靈魂嗎？"
  },
  AvgDialog_45426_Content_9 = {
    Text = "高曠的天空中星子閃爍，沙漠夜晚的風總算讓你艱難的呼吸勉強恢復正常。"
  },
  AvgDialog_45426_Content_90 = {
    Text = "因為靈魂的奇妙共鳴，女孩能夠聽見樹的聲音。\n在那個夜晚，她得知了與<Red:黑色末日>相關的知識。"
  },
  AvgDialog_45426_Content_91 = {
    Text = "黑色末日……是指融蝕？"
  },
  AvgDialog_45426_Content_92 = {
    Text = "女孩回到了樹的身邊，卻不再執行君王的命令。\n不……因為血脈的呼喚，所有民眾只會回應樹的意志。"
  },
  AvgDialog_45426_Content_93 = {
    Text = "女孩即是樹，樹即是女孩。相較於自身的存活，她更在乎整個種群能否逃過與世界一同毀滅的結局。"
  },
  AvgDialog_45426_Content_94 = {
    Text = "帝國覆滅之時，她帶著一支隊伍藏入沙漠最深處，人跡罕至的風暴之中，隻為躲避屠殺，留存最後的血脈。"
  },
  AvgDialog_45426_Content_95 = {
    Text = "這就是……遊牧民族亞蘭？"
  },
  AvgDialog_45426_Content_96 = {
    Text = "很久很久以後，女孩再次消失了。"
  },
  AvgDialog_45426_Content_97 = {
    Text = "還是沒有人聽見她的聲音，再也沒有人傳頌她的名姓。"
  },
  AvgDialog_45426_Content_98 = {
    Text = "但所有人都在按照她的意願，為了躲過末日而拼命繁衍……"
  },
  AvgDialog_45426_Content_99 = {
    Text = "隻為了在末日降臨時刻，留存「豐穰」的種子。"
  },
  AvgDialog_45427_Content_10 = {
    Text = "孩子們會走出他們自己的路。"
  },
  AvgDialog_45427_Content_100 = {
    Text = "你順著泰旖絲的視線望去，拉蒙娜正小跑著向你奔來，萊克跟在她的身後，步伐迅疾卻穩健，不失風度與優雅。"
  },
  AvgDialog_45427_Content_101 = {
    Text = "別忘了，今夜是隻屬於我們的秘密。"
  },
  AvgDialog_45427_Content_102 = {
    Text = "再轉身看去，泰旖絲的身影消失不見，只有風呼嘯過沙漠。"
  },
  AvgDialog_45427_Content_103 = {
    Text = "在你面前的沙地上，一痕漆黑的融蝕漿滲入流沙，與大地融為一體。"
  },
  AvgDialog_45427_Content_12 = {
    Text = "你朦朧睜開雙眼，映入眼簾的是一片清亮璀璨的浩瀚星空。"
  },
  AvgDialog_45427_Content_13 = {
    Text = "我怎麼……睡著了？"
  },
  AvgDialog_45427_Content_14 = {
    Text = "沙漠中行進久了，疲倦是再正常不過的事情。"
  },
  AvgDialog_45427_Content_15 = {
    Text = "我還有很多問題……"
  },
  AvgDialog_45427_Content_16 = {
    Text = "漫長的夢境似乎將你從緊繃的旅程中抽離出來，疑問一個接一個地浮上你的腦海。"
  },
  AvgDialog_45427_Content_17 = {
    Text = "拉蒙娜水囊中的水為何會變成融蝕漿？"
  },
  AvgDialog_45427_Content_18 = {
    Text = "究竟是什麼人在散佈努比亞？"
  },
  AvgDialog_45427_Content_19 = {
    Text = "風暴之壁內部究竟藏著什麼？"
  },
  AvgDialog_45427_Content_2 = {
    Text = "▼▼處於混亂之中，沒有人知道結局。\n將要發生的事情在我的言語裡，但人們的聽覺和視覺都已經喪失，\n唯有緘默者遍佈大地。"
  },
  AvgDialog_45427_Content_20 = {
    Text = "神秘的使者於麗埃特有何目的？"
  },
  AvgDialog_45427_Content_21 = {
    Text = "亞蘭的儀式又是怎麼一回事？"
  },
  AvgDialog_45427_Content_22 = {
    Text = "而泰旖絲，眼前的泰旖絲真的值得信任嗎？"
  },
  AvgDialog_45427_Content_23 = {
    Text = "自從來到勒姆瓦希，異常事端就沒停息過，一個接一個的謎團追得你喘不過氣來。"
  },
  AvgDialog_45427_Content_24 = {
    Text = "你需要冷靜，需要思考。"
  },
  AvgDialog_45427_Content_26 = {
    Text = "回過身時，只有一輪圓月，映照在泰旖絲光潔滑膩的面龐，竟有幾分通透之感。"
  },
  AvgDialog_45427_Content_27 = {
    Text = "在風暴之壁的那一側……你的所有問題都會得到答案。"
  },
  AvgDialog_45427_Content_28 = {
    Text = "在風暴之壁的那一側。"
  },
  AvgDialog_45427_Content_29 = {
    Text = "於麗埃特也是這麼說，難道你非得順著那個幕後之人的意思抵達風暴之中嗎？"
  },
  AvgDialog_45427_Content_3 = {
    Text = "塔薇的監測資料逐漸穩定下來了。"
  },
  AvgDialog_45427_Content_30 = {
    Text = "還是冥冥之中有某種力量在驅使所有人朝聖般前赴後繼地朝著風暴的中央而去？"
  },
  AvgDialog_45427_Content_31 = {
    Text = "思緒止不住翻湧，在你的神識之海中培植懷疑和焦慮的種子。"
  },
  AvgDialog_45427_Content_32 = {
    Text = "你的心始終無法平靜嗎？"
  },
  AvgDialog_45427_Content_33 = {
    Text = "閉上眼吧。"
  },
  AvgDialog_45427_Content_34 = {
    Text = "泰旖絲與你的呼吸只有咫尺之隔。"
  },
  AvgDialog_45427_Content_35 = {
    Text = "閉上眼睛"
  },
  AvgDialog_45427_Content_36 = {
    Text = "拒絕閉眼"
  },
  AvgDialog_45427_Content_37 = {
    Text = "真是清亮的眼神啊……一點都沒有因為這一路的顛簸變得渾濁。"
  },
  AvgDialog_45427_Content_38 = {
    Text = "泰旖絲將食指抵在你的唇峰。"
  },
  AvgDialog_45427_Content_39 = {
    Text = "她的臉與你近在咫尺，月光為她的肌膚鍍上一層柔和的光暈。"
  },
  AvgDialog_45427_Content_4 = {
    Text = "你們這段時間辛苦了。"
  },
  AvgDialog_45427_Content_40 = {
    Text = "你感覺到湊近的呼吸，輕柔而溫熱的。"
  },
  AvgDialog_45427_Content_41 = {
    Text = "真是令人懷念的氣息。"
  },
  AvgDialog_45427_Content_42 = {
    Text = "我們已經多久沒有如此貼近彼此了呢？"
  },
  AvgDialog_45427_Content_43 = {
    Text = "嘴唇上傳來微涼的觸感。"
  },
  AvgDialog_45427_Content_44 = {
    Text = "你睜開眼，泰旖絲的食指抵在你的唇鋒。\n她的臉與你近在咫尺，月光為她的肌膚鍍上一層柔和的光暈。"
  },
  AvgDialog_45427_Content_45 = {
    Text = "你知道嗎？我在你的眼中看到了災厄，看到了亙古的餘燼，看到了寰宇天地的呼吸。"
  },
  AvgDialog_45427_Content_46 = {
    Text = "你經歷的旅程很漫長，已經很疲憊了吧？\n但你的目光還是那麼堅定，沒有一絲渾濁。"
  },
  AvgDialog_45427_Content_47 = {
    Text = "群星不能轉變你，沙海也未必可以。"
  },
  AvgDialog_45427_Content_49 = {
    Text = "你現在還不必明白。"
  },
  AvgDialog_45427_Content_5 = {
    Text = "接下來也不能鬆懈。\n三百多年來，黑池的異動從未如今年這般頻繁。"
  },
  AvgDialog_45427_Content_50 = {
    Text = "泰旖絲起身，向著沙丘之下漫步。"
  },
  AvgDialog_45427_Content_51 = {
    Text = "在這樣的星空下，只是枯坐著，未免太過不解風情。"
  },
  AvgDialog_45427_Content_52 = {
    Text = "風托起她潔白通透的輕紗，她飄飄搖搖地走在軟沙上。"
  },
  AvgDialog_45427_Content_53 = {
    Text = "就讓我為你獻上，這支亞蘭之舞吧。"
  },
  AvgDialog_45427_Content_54 = {
    Text = "鈴聲響了起來，她揚起單臂，搖曳出舞蹈的伊始。"
  },
  AvgDialog_45427_Content_55 = {
    Text = "她彎曲，伸展，時而奔放，時而含蓄。"
  },
  AvgDialog_45427_Content_56 = {
    Text = "我一直在等待一個人。"
  },
  AvgDialog_45427_Content_57 = {
    Text = "她的身形柔若無骨，她的舞姿宛若遊蛇。"
  },
  AvgDialog_45427_Content_58 = {
    Text = "一個能引領亞蘭走向「未來」的守望者。"
  },
  AvgDialog_45427_Content_59 = {
    Text = "她翻轉、擺動，殘影都透露出天生的優雅與不可思議的柔韌。"
  },
  AvgDialog_45427_Content_6 = {
    Text = "不必過分憂慮，這是遲早會發生的事情。\n對那位「祂」而言，無論是藏在過去還是未來，都不是長久之計。"
  },
  AvgDialog_45427_Content_60 = {
    Text = "艾爾瓦不是那個人嗎？"
  },
  AvgDialog_45427_Content_61 = {
    Text = "泰旖絲側身回首，低眉垂目，指尖的挽花拂過她歎息的唇角。"
  },
  AvgDialog_45427_Content_62 = {
    Text = "艾爾瓦是個好孩子，但她尚無法開闢出新的道路。"
  },
  AvgDialog_45427_Content_63 = {
    Text = "於麗埃特呢？她不是異鄉的使者嗎？"
  },
  AvgDialog_45427_Content_64 = {
    Text = "你剛才說，於麗埃特為亞蘭族求取的路，是脫離沙漠，對嗎？"
  },
  AvgDialog_45427_Content_65 = {
    Text = "泰旖絲伸展雙臂，遊離的目光望向指尖的月亮，像是送離不可視的飛鳥。"
  },
  AvgDialog_45427_Content_66 = {
    Text = "能夠離開的人，早就已經離開了，亞蘭從未束縛任何人。無論是眷戀故土，還是習慣沙漠的生活方式，留下的人都只能生存在這裡。"
  },
  AvgDialog_45427_Content_67 = {
    Text = "何況，那並非我所期待的答案。"
  },
  AvgDialog_45427_Content_68 = {
    Text = "你期待的答案……是怎樣的？"
  },
  AvgDialog_45427_Content_69 = {
    Text = "早就已經寫在歌謠中了。"
  },
  AvgDialog_45427_Content_7 = {
    Text = "我擔心的不是「祂」，而是那個孩子。"
  },
  AvgDialog_45427_Content_70 = {
    Text = "母樹重誕聖河，為已逝者加冕，將血脈還於亞蘭。"
  },
  AvgDialog_45427_Content_71 = {
    Text = "母樹重誕聖河很好理解，已逝者是指誰？又要怎麼將血脈還於亞蘭？"
  },
  AvgDialog_45427_Content_72 = {Text = "噓——"},
  AvgDialog_45427_Content_73 = {
    Text = "那些細節太過複雜，@1的預言無法給出所有的答案。"
  },
  AvgDialog_45427_Content_74 = {
    Text = "你唯一需要做的，就是絕對信任我。\n信任亞蘭的女王。"
  },
  AvgDialog_45427_Content_75 = {
    Text = "沙漠的花在幽暗的月夜綻放，她抬手、旋轉、邁步，在沙地上踏出複雜而古老的節奏。"
  },
  AvgDialog_45427_Content_76 = {
    Text = "只要你相信我，我就是你絕對的、唯一的、只屬於你的——秘密武器。"
  },
  AvgDialog_45427_Content_77 = {
    Text = "在月光下，她的輪廓柔和而神秘，她的雙眸流轉，傾訴無言的情愫。"
  },
  AvgDialog_45427_Content_78 = {
    Text = "若這是終將結束的夢境——\n遙遠的星辰，即為她的見證者。"
  },
  AvgDialog_45427_Content_79 = {
    Text = "等等，泰旖絲，你的腳下——"
  },
  AvgDialog_45427_Content_8 = {
    Text = "這就不是你我能夠干涉的事情了。"
  },
  AvgDialog_45427_Content_80 = {
    Text = "你焦急地呼喊出聲。"
  },
  AvgDialog_45427_Content_81 = {
    Text = "她踏上了波紋，不，是黑色的波紋自她的足尖蕩漾開去。"
  },
  AvgDialog_45427_Content_82 = {
    Text = "白紗的末梢如同擺動的荷葉般飛揚起線線水珠，黑曜石般濃郁深邃。"
  },
  AvgDialog_45427_Content_83 = {
    Text = "那是……融蝕漿……？"
  },
  AvgDialog_45427_Content_84 = {
    Text = "她在幻覺般的融蝕之池中起舞，一而再、再而三地踏上黑色的液麵。"
  },
  AvgDialog_45427_Content_87 = {
    Text = "她彷彿沒有聽見你的呼喚，循著不可知的韻律起舞。"
  },
  AvgDialog_45427_Content_88 = {
    Text = "她回身向你，身姿舒張，你親手佩上的項鍊在她的胸口熠熠閃光。"
  },
  AvgDialog_45427_Content_9 = {
    Text = "彌薩格為此付出了三百年傳承，我們鎖定的繼承者不能偏離預定的軌跡。"
  },
  AvgDialog_45427_Content_90 = {
    Text = "她拉過你的手掌，引導你的指尖碰觸那顆彷彿有著生命搏動的白玉。"
  },
  AvgDialog_45427_Content_91 = {
    Text = "遠天中流星墜落。\n她的眼睛比星辰更加璀璨。"
  },
  AvgDialog_45427_Content_93 = {
    Text = "她雙唇微啟，晚風送來她的輕聲低語。"
  },
  AvgDialog_45427_Content_94 = {
    Text = "我可以放心將他們託付給你麼？"
  },
  AvgDialog_45427_Content_95 = {
    Text = "與篝火晚宴那夜近似的牽引感捕獲了你，幾乎是不由自主地，你喃喃。"
  },
  AvgDialog_45427_Content_98 = {
    Text = "泰旖絲笑了。"
  },
  AvgDialog_45427_Content_99 = {
    Text = "你的朋友們來了。"
  },
  AvgDialog_45429_Content_1 = {
    Text = "卡茜亞的紅綢四處翻飛，帳篷內的杯盤被打了個七零八碎。"
  },
  AvgDialog_45429_Content_10 = {
    Text = "她爽快地揭開巨大的魔術帽，出現其中的是她意料之外的身影。"
  },
  AvgDialog_45429_Content_11 = {
    Text = "怎麼是你？！"
  },
  AvgDialog_45429_Content_12 = {
    Text = "哎呀，一點點小運氣。"
  },
  AvgDialog_45429_Content_13 = {
    Text = "卡茜亞急忙往窗外看去，守密人的身影已在駱駝上顛簸著遠去。"
  },
  AvgDialog_45429_Content_14 = {
    Text = "三枚骰子洞穿了幕布，擦著卡茜亞的臉頰飛過。"
  },
  AvgDialog_45429_Content_15 = {
    Text = "好啊，你這是要跟我糾纏到底了嗎？"
  },
  AvgDialog_45429_Content_16 = {
    Text = "那就讓你去異次元空洞裡面反思反思自己的錯誤吧！"
  },
  AvgDialog_45429_Content_17 = {
    Text = "幻象忽然吞沒了眼前的空間，油畫般的色彩覆蓋視野，五彩斑斕的混沌重歸秩序之時，空間已異化成魔術師的舞臺。"
  },
  AvgDialog_45429_Content_18 = {
    Text = "盡情上演吧，「奇蹟卡茜亞的魔術嘉年華！」"
  },
  AvgDialog_45429_Content_2 = {
    Text = "你和萊克對了個眼神。\n此刻最重要的，是脫身去阻止那被提燈教會操縱的亞蘭獻祭儀式。"
  },
  AvgDialog_45429_Content_3 = {
    Text = "卡茜亞的魔術帽兜頭而來，你和萊克依計分成兩路，一頂魔術帽直追你而來——"
  },
  AvgDialog_45429_Content_4 = {
    Text = "哼哼，猜猜守密人在哪頂帽子裡？"
  },
  AvgDialog_45429_Content_5 = {
    Text = "左邊也是空的，右邊也是空的~"
  },
  AvgDialog_45429_Content_6 = {
    Text = "鏘鏘~其實，哪個帽子都不在，看，%heorshe%在卡茜亞的幕布裡！"
  },
  AvgDialog_45429_Content_7 = {
    Text = "紅綢幕布自虛空裂隙中躥出，飛舞成搖曳不定的波浪，將守密人緊緊裹纏成一具鮮紅木乃伊。"
  },
  AvgDialog_45429_Content_8 = {
    Text = "怎麼樣，是不是很有亞蘭風情的演出呀？"
  },
  AvgDialog_45429_Content_9 = {
    Text = "隔空取物~嘿嘿，到我收貨的時候啦。"
  },
  AvgDialog_45430_Content_1 = {Text = "交匯點"},
  AvgDialog_45430_Content_10 = {
    Text = "母樹……不就在那裡嗎？"
  },
  AvgDialog_45430_Content_100 = {
    Text = "你們向沙丘下的營地奔去。"
  },
  AvgDialog_45430_Content_101 = {
    Text = "在指尖觸碰簾布的瞬間，巨大的恐懼攫住了你。"
  },
  AvgDialog_45430_Content_103 = {
    Text = "這種恐懼與直面獵犬、對抗聖胎時都不一樣……"
  },
  AvgDialog_45430_Content_104 = {
    Text = "那是一種深入骨髓的、無法面對也無法挽回的，難以訴說的恐怖。"
  },
  AvgDialog_45430_Content_105 = {
    Text = "那是浮遊的噩夢，是畸零的妄想，是不堪忍耐的、令人窒息的現實。"
  },
  AvgDialog_45430_Content_106 = {
    Text = "巨大而野性的怪物搖擺著黏液狀的觸肢，威廉瘦削的身軀在其中搖擺如伶仃的蘆葦。"
  },
  AvgDialog_45430_Content_108 = {
    Text = "額角的傷疤，據說是由他瘋癲的母親燙傷，此刻像是一條細淺的溝渠，汩汩流淌著猩紅的漿液。"
  },
  AvgDialog_45430_Content_109 = {
    Text = "銀鑰在胸口破碎，彌薩格標配的手套被血漬侵染，不祥的黏液以逆重力的方式自由滴落。"
  },
  AvgDialog_45430_Content_11 = {
    Text = "遙遠的地平線，與天相接之處。"
  },
  AvgDialog_45430_Content_110 = {
    Text = "在那搖擺的噩夢背後——"
  },
  AvgDialog_45430_Content_111 = {
    Text = "巨大的肉塊山張開如捕蠅草般的裂口。"
  },
  AvgDialog_45430_Content_112 = {
    Text = "兩側胎盤與畸嬰的褶皺清晰如你腦海中血色的烙印。"
  },
  AvgDialog_45430_Content_113 = {
    Text = "臃腫扭曲的肉塊中間，躺著他不斷追溯、不斷探求，獻給你們此行最後的禮物。"
  },
  AvgDialog_45430_Content_114 = {
    Text = "那即是努比亞內核的真相——"
  },
  AvgDialog_45430_Content_115 = {
    Text = "一枚小小的提燈。"
  },
  AvgDialog_45430_Content_12 = {
    Text = "高聳入雲的母樹，佇立於宛若彼岸之地。"
  },
  AvgDialog_45430_Content_13 = {
    Text = "你是說，你能看見母樹？"
  },
  AvgDialog_45430_Content_14 = {
    Text = "你抬頭望向天際，伸出手掌，描摹母樹的輪廓。"
  },
  AvgDialog_45430_Content_15 = {
    Text = "一棵衰老瘦削的樹……高聳、但孤獨……"
  },
  AvgDialog_45430_Content_16 = {
    Text = "或許……母樹是因為融蝕而消失的。"
  },
  AvgDialog_45430_Content_17 = {
    Text = "你們還記得嗎？%player%留存有因融蝕而消失之物的記憶。"
  },
  AvgDialog_45430_Content_18 = {
    Text = "你攤開詹金帶來的那份報紙，卻發現上面的墨水就像有生命一般，正在一點點消融——"
  },
  AvgDialog_45430_Content_19 = {
    Text = "直到你再也看不清那則有關《春》的報導。"
  },
  AvgDialog_45430_Content_2 = {
    Text = "然後，▼▼▼將回到她的王座上，\n混亂將被驅逐。\n看到這一切的人將會歡呼，\n為王服務的人也會歡呼。"
  },
  AvgDialog_45430_Content_20 = {
    Text = "這些損毀的水印與墨痕，像是鐵了心要將梅森的存在徹底抹消。"
  },
  AvgDialog_45430_Content_22 = {
    Text = "這、這是什麼妖術嗎？這報紙我都看過八百次了。"
  },
  AvgDialog_45430_Content_23 = {
    Text = "可現在……一個字，我連一個字都想不起來。"
  },
  AvgDialog_45430_Content_24 = {
    Text = "咦，你們什麼都不記得了？"
  },
  AvgDialog_45430_Content_25 = {
    Text = "「立體派的傑出捍衛者，波提切利的靈魂轉世正隱居於南華克街角的蠟像館內……」"
  },
  AvgDialog_45430_Content_26 = {
    Text = "你看，我甚至能複述出那則新聞的內容。"
  },
  AvgDialog_45430_Content_27 = {
    Text = "報紙被融蝕了。說明這大機率是一起融蝕導致的<Yellow:群體失憶>現象，不過……"
  },
  AvgDialog_45430_Content_28 = {
    Text = "拉蒙娜和詹金齊刷刷看向你。"
  },
  AvgDialog_45430_Content_29 = {
    Text = "對某人似乎不起作用。"
  },
  AvgDialog_45430_Content_3 = {
    Text = "那支小隊……只有包括涅弗魯瑞在內的三個人生還。"
  },
  AvgDialog_45430_Content_31 = {
    Text = "不管你們信不信，這感覺可不太舒服……"
  },
  AvgDialog_45430_Content_32 = {
    Text = "似乎在不知不覺間，過去已被篡改，故事就此偏離了既定的軌道。"
  },
  AvgDialog_45430_Content_33 = {
    Text = "而你卻成為了這些變化的唯一見證者。"
  },
  AvgDialog_45430_Content_34 = {
    Text = "身為欲之質體的載體，豐穰母樹的存在一定在星球上刻下了足夠深刻的烙印。"
  },
  AvgDialog_45430_Content_35 = {
    Text = "母樹頑強的生命力，讓母樹被融蝕侵蝕的速度比常人緩上千倍萬倍。"
  },
  AvgDialog_45430_Content_36 = {
    Text = "所以，對你而言，她還不曾完全消失。"
  },
  AvgDialog_45430_Content_37 = {
    Text = "若再過上百年千年，亞蘭人多半連母樹的存在都會遺忘。"
  },
  AvgDialog_45430_Content_38 = {
    Text = "而亞蘭的儀式，或許能捕捉到母樹殘留的那絲微弱的存在。"
  },
  AvgDialog_45430_Content_39 = {
    Text = "就像喚醒儀式？"
  },
  AvgDialog_45430_Content_4 = {
    Text = "但亞蘭人看起來還是很興奮。\n這種犧牲……對他們來說已經是家常便飯了吧。"
  },
  AvgDialog_45430_Content_40 = {
    Text = "是的，喚醒儀式本來就是借用調查員的精神力令銀芯中的精神存在重現於世，母樹的「重生」應該與之類似。"
  },
  AvgDialog_45430_Content_41 = {
    Text = "%player%，你看到的母樹是什麼樣的？"
  },
  AvgDialog_45430_Content_42 = {
    Text = "嗯……怎麼說呢，像是生長在貧瘠土壤上的光禿禿樹幹……跟豐穰這個詞毫不相干。"
  },
  AvgDialog_45430_Content_43 = {
    Text = "就像是……母樹臨終的形態。"
  },
  AvgDialog_45430_Content_44 = {
    Text = "明天就是亞蘭儀式了，你們還不休息嗎？"
  },
  AvgDialog_45430_Content_45 = {
    Text = "我的解剖就快有結果了。"
  },
  AvgDialog_45430_Content_46 = {
    Text = "都什麼時候了，還惦記著你那解剖……\n雖然我很想這麼說，不過你是對的，我們還差最後一塊拼圖。"
  },
  AvgDialog_45430_Content_47 = {
    Text = "%player%，已經是最後的機會了。"
  },
  AvgDialog_45430_Content_48 = {
    Text = "他不睡覺是為了解剖，你又是為了什麼？"
  },
  AvgDialog_45430_Content_49 = {
    Text = "我……在回憶一個夢。"
  },
  AvgDialog_45430_Content_5 = {
    Text = "你放眼望向往日沉默的人群，他們的瞳孔裡閃爍著綠洲般的光芒。"
  },
  AvgDialog_45430_Content_50 = {
    Text = "那是你時常會做的夢之一。"
  },
  AvgDialog_45430_Content_51 = {
    Text = "夢裡漆黑一片，只有潮水奔騰激蕩，衝擊河岸的洶湧澎湃之聲。"
  },
  AvgDialog_45430_Content_52 = {
    Text = "你的心臟隨著水流的節奏而跳動。無數人的心臟隨之而跳動。"
  },
  AvgDialog_45430_Content_53 = {
    Text = "無數人的心跳彙聚成漆黑的河流，那漆黑的潮水便無所顧忌地朝著入海口奔湧而去，將整片汪洋染成墨色……"
  },
  AvgDialog_45430_Content_54 = {
    Text = "我聽說你的夢裡常會包含有預言。"
  },
  AvgDialog_45430_Content_55 = {
    Text = "有時候是記憶，有時候是預言。"
  },
  AvgDialog_45430_Content_56 = {
    Text = "無論哪一種，都說明那些生命切實地被融蝕吞噬了……"
  },
  AvgDialog_45430_Content_57 = {
    Text = "別想太多。即使融蝕從未存在，人類也在不斷前進和消失的旅途當中。"
  },
  AvgDialog_45430_Content_58 = {
    Text = "談論這種話題，總覺得應該叫上威廉，再來點酒。"
  },
  AvgDialog_45430_Content_59 = {
    Text = "彌薩格最偉大的傳奇調查員，他經歷的神秘事件比我贏下的賭局還要多。"
  },
  AvgDialog_45430_Content_6 = {
    Text = "母樹在上，請您豐沃亞蘭的水土，護佑亞蘭的世代。"
  },
  AvgDialog_45430_Content_60 = {
    Text = "你點了點胸口的胸針，呼叫威廉。"
  },
  AvgDialog_45430_Content_61 = {
    Text = "我早該……早該想到的。"
  },
  AvgDialog_45430_Content_62 = {
    Text = "在帳篷的中央，努比亞屍被開膛破肚，刀口流暢而精確。\n仔細看去，還能感覺到它輕微起伏的呼吸。"
  },
  AvgDialog_45430_Content_63 = {
    Text = "那是千百遍實驗所能抵達的極限，介於生與死邊緣的搏動。"
  },
  AvgDialog_45430_Content_64 = {
    Text = "能夠操縱融蝕的進程，讓努比亞異常消失。"
  },
  AvgDialog_45430_Content_65 = {
    Text = "我們的敵人，對融蝕有著超乎尋常的理解和掌控。"
  },
  AvgDialog_45430_Content_66 = {
    Text = "他放下手術刀，深呼吸，近似血水的腐臭味一嗆，他猛烈地咳嗽起來。"
  },
  AvgDialog_45430_Content_67 = {
    Text = "還有那支歌謠……"
  },
  AvgDialog_45430_Content_68 = {
    Text = "母親的遺骸不見蹤跡，血與種漂泊於大地，被初生的野獸吞噬。"
  },
  AvgDialog_45430_Content_69 = {
    Text = "天空與眾神佈滿陰雲，直至異鄉使者降臨。"
  },
  AvgDialog_45430_Content_7 = {
    Text = "待您重生之後，亞蘭必將最甘美的水供奉於您……"
  },
  AvgDialog_45430_Content_70 = {
    Text = "野獸的降臨，要先於使者的到來。"
  },
  AvgDialog_45430_Content_71 = {
    Text = "所以於麗埃特一直在風暴之壁外徘徊，所以她那麼確定那一次一定可以突破風暴之壁。"
  },
  AvgDialog_45430_Content_72 = {
    Text = "於麗埃特，根本不是傳說中的異鄉使者……"
  },
  AvgDialog_45430_Content_73 = {
    Text = "她來自提燈教會，編造了所謂的夢境感召，博取了亞蘭人的信任。\n目的……多半是與亞蘭人同行，污染豐穰母樹和聖河。"
  },
  AvgDialog_45430_Content_74 = {
    Text = "真正的異鄉使者……\n無需猜想，毫無疑問，是守密人。"
  },
  AvgDialog_45430_Content_75 = {
    Text = "不對，還不夠。"
  },
  AvgDialog_45430_Content_76 = {
    Text = "一種異常感催促著威廉繼續演進自己的結論。"
  },
  AvgDialog_45430_Content_77 = {
    Text = "還有這些異常的接口……\n是雕塑家協會，赫伯特那傢伙的手筆。"
  },
  AvgDialog_45430_Content_78 = {
    Text = "如果你的推論能停留在上一步的話，本可以安然離開勒姆瓦希。"
  },
  AvgDialog_45430_Content_79 = {
    Text = "只能說真不愧是彌薩格的傳奇調查員啊，領先所有人一步找到了答案。"
  },
  AvgDialog_45430_Content_8 = {
    Text = "天天聽這幫亞蘭人念叨豐穰母樹，不知道實際上是怎樣壯美的景象。"
  },
  AvgDialog_45430_Content_81 = {
    Text = "別緊張，我一直都比其他人更相信你的實力。"
  },
  AvgDialog_45430_Content_82 = {
    Text = "他們也一樣，否則為什麼留你一個人在這裡，連個喚醒體都不跟著呢？"
  },
  AvgDialog_45430_Content_83 = {
    Text = "彼此彼此。\n如果我沒記錯的話，你的喚醒體在拉伊與你斷鏈了。"
  },
  AvgDialog_45430_Content_84 = {
    Text = "至於你雇傭的那名喚醒體……我相信達芙黛爾夫人不至於與彌薩格大學直接為敵。"
  },
  AvgDialog_45430_Content_85 = {
    Text = "你覺得我沒有能力在這裡殺死你。"
  },
  AvgDialog_45430_Content_86 = {
    Text = "我從不輕視自己的敵人，尤其是殺害克勞利教授的兇手。"
  },
  AvgDialog_45430_Content_87 = {
    Text = "我知道，我當然知道。"
  },
  AvgDialog_45430_Content_88 = {
    Text = "在畫室調查中，在哨兵嶺儀式上……\n那些高位意志的僕從都奈何不了你，何況區區喚醒體。"
  },
  AvgDialog_45430_Content_89 = {
    Text = "所以，當我聽說彌薩格出動了你的時候，就知道我必須做好萬全的準備了。"
  },
  AvgDialog_45430_Content_9 = {
    Text = "萊克你……在說什麼啊……"
  },
  AvgDialog_45430_Content_90 = {
    Text = "環行·拉蒙娜對吧？"
  },
  AvgDialog_45430_Content_91 = {
    Text = "通過某種手段打通與其他世界的通道，將其他世界中更貼近高位存在的精神寄宿在同源個體上。"
  },
  AvgDialog_45430_Content_92 = {
    Text = "赫伯特在肩頭怪貓的兩個頭顱上各摸了摸。"
  },
  AvgDialog_45430_Content_93 = {
    Text = "小乖乖，我愛你和愛它一樣多。"
  },
  AvgDialog_45430_Content_94 = {
    Text = "<Blue:血鏈·希洛>。"
  },
  AvgDialog_45430_Content_95 = {
    Text = "喂喂，威廉學長……"
  },
  AvgDialog_45430_Content_98 = {
    Text = "威廉就在離你百步之遙的帳篷之內，但通訊的另一側無聲無息。"
  },
  AvgDialog_45430_Content_99 = {
    Text = "不安感陡然升起，恐懼如一記記重錘砸向你的心靈。"
  },
  AvgDialog_45431_Content_1 = {Text = "遺骸"},
  AvgDialog_45431_Content_10 = {
    Text = "稍微和緩些了。威廉不在，我不放心你們兩個人。"
  },
  AvgDialog_45431_Content_11 = {
    Text = "她的臉頰還泛著微微的潮紅，你輕觸她的額頭，似乎沒有之前那麼燙了。"
  },
  AvgDialog_45431_Content_12 = {
    Text = "這裡是……？"
  },
  AvgDialog_45431_Content_13 = {
    Text = "和充滿原始氛圍的亞蘭部族不同，入目的是更貼近你所認知的人類文明的產物廢墟，一座看來廢棄已久的工廠。"
  },
  AvgDialog_45431_Content_14 = {
    Text = "洪積後，勒姆瓦希的政權曾經在此進行過工業建設，建造多個工廠和學校。"
  },
  AvgDialog_45431_Content_15 = {
    Text = "但亞蘭人民慣於遊牧，對沙漠工業化的支持有限，這些建築就隨著荒沙化加劇和政權變遷而荒廢了。"
  },
  AvgDialog_45431_Content_16 = {
    Text = "亞蘭人沒有浪費這些屋簷，他們用廢棄工廠儲藏需要通風避濕、層層防衛的物品——比如你我所知的聖樹遺骸。"
  },
  AvgDialog_45431_Content_17 = {
    Text = "等等，有什麼東西躥過來了！"
  },
  AvgDialog_45431_Content_2 = {
    Text = "一轉頭你就不見了。\n你剛才在跟誰說話？"
  },
  AvgDialog_45431_Content_4 = {
    Text = "你唯一需要做的，就是絕對信任我。\n信任亞蘭的女王。"
  },
  AvgDialog_45431_Content_5 = {
    Text = "別忘了，今夜是隻屬於我們的秘密。"
  },
  AvgDialog_45431_Content_6 = {
    Text = "你的猶豫沒有逃過偵探的眼睛。"
  },
  AvgDialog_45431_Content_7 = {
    Text = "我們的小朋友有點秘密不想說呢。\n放心吧，善解人意的大人是不會追問的。"
  },
  AvgDialog_45431_Content_8 = {
    Text = "我和拉蒙娜剛才跟隨亞蘭隊伍，確認了安置聖樹遺骸的地點。\n事不宜遲，我們趁午夜潛進去吧。"
  },
  AvgDialog_45431_Content_9 = {
    Text = "拉蒙娜，你的身體沒關係嗎？"
  },
  AvgDialog_45432_Content_1 = {
    Text = "風暴之壁"
  },
  AvgDialog_45432_Content_10 = {
    Text = "風暴之壁並非固有的牆壁，而是聖樹自我隱匿的壁障。"
  },
  AvgDialog_45432_Content_11 = {
    Text = "若非心懷面見母樹的目的，根本連風暴之壁都見不到，更別提突破它。"
  },
  AvgDialog_45432_Content_12 = {
    Text = "因此，他們需要「異鄉的使者」。"
  },
  AvgDialog_45432_Content_13 = {
    Text = "隊列有序向兩側散開，間隔五步十步，綿延成一條由人體構成的長蛇。"
  },
  AvgDialog_45432_Content_15 = {
    Text = "艾爾瓦一揚大旗，他們整齊劃一地將長矛劃過荒沙，掀起迷眼的沙塵，唱誦渺遠詭異的歌謠。"
  },
  AvgDialog_45432_Content_16 = {
    Text = "死亡已經迫近，消亡已經起始。"
  },
  AvgDialog_45432_Content_17 = {
    Text = "母親的遺骸不見蹤跡，血與種漂泊於大地，被初生的野獸吞噬。"
  },
  AvgDialog_45432_Content_18 = {
    Text = "天空與眾神佈滿陰雲，直至異鄉使者降臨。"
  },
  AvgDialog_45432_Content_19 = {
    Text = "母樹重誕聖河，為已逝者加冕，將血脈還於亞蘭。"
  },
  AvgDialog_45432_Content_2 = {
    Text = "我沒事的。\n艾爾瓦已經在清點小隊了，我們也跟上吧。"
  },
  AvgDialog_45432_Content_20 = {
    Text = "將血脈……還於亞蘭……"
  },
  AvgDialog_45432_Content_21 = {
    Text = "沙漠的豔陽不知何時失去了蹤跡，天空變得陰沉，風聲也轉了音調。"
  },
  AvgDialog_45432_Content_22 = {
    Text = "莫名的恐懼攫住了你，你刹那失神，緊接著被一聲尖叫喚醒。"
  },
  AvgDialog_45432_Content_23 = {
    Text = "它、它來了——！"
  },
  AvgDialog_45432_Content_24 = {
    Text = "視線聚焦的瞬間，你理解了何為「風暴之壁」。"
  },
  AvgDialog_45432_Content_25 = {
    Text = "那是吞天噬地的灰色幕牆，以遮蔽天空的形態滾滾而來。"
  },
  AvgDialog_45432_Content_26 = {
    Text = "它本應是潮水，又並非潮水，它龐大而死寂，它在前行卻又仿若靜止。"
  },
  AvgDialog_45432_Content_27 = {
    Text = "它的邊界如同巨獸舔舐大地，而亞蘭的隊列就那麼被吞吃進迷霧，被風暴的胃袋撕扯、消化。"
  },
  AvgDialog_45432_Content_28 = {
    Text = "繼續跳，不要停！"
  },
  AvgDialog_45432_Content_29 = {
    Text = "異鄉使者在此，女王會為我們打開前往母樹的通路！"
  },
  AvgDialog_45432_Content_3 = {
    Text = "今天，是啟程前往風暴之壁的日子。"
  },
  AvgDialog_45432_Content_30 = {
    Text = "你注意到身邊的於麗埃特露出輕笑。"
  },
  AvgDialog_45432_Content_31 = {
    Text = "族長，族長，今天的風暴太劇烈了，我們真的損失不起這麼多人了，先退吧！"
  },
  AvgDialog_45432_Content_33 = {
    Text = "她的音調威嚴，語句卻被風聲震顫。"
  },
  AvgDialog_45432_Content_34 = {
    Text = "篝火儀式的畸胎率越來越高，這樣下去，在找到母樹之前，亞蘭的血脈就會消亡在時間的長河裡。"
  },
  AvgDialog_45432_Content_35 = {
    Text = "於麗埃特雙指成環，吹響嘹亮的口哨，綿延的音韻被風暴裹挾，飄向不可知的遠方。"
  },
  AvgDialog_45432_Content_36 = {
    Text = "我是使者於麗埃特，我已經聆聽到女王的旨意，今天，我們一定可以突破風暴之壁！"
  },
  AvgDialog_45432_Content_37 = {
    Text = "所有人，只許前進，不得後退！"
  },
  AvgDialog_45432_Content_38 = {
    Text = "謹遵使者大人之命，只許前進，不得後退！"
  },
  AvgDialog_45432_Content_4 = {
    Text = "諸位勇士，已經做好準備了嗎？"
  },
  AvgDialog_45432_Content_40 = {
    Text = "等等，守密人，背後來了一大群努比亞……\n看數量……至少有……兩百頭！"
  },
  AvgDialog_45432_Content_41 = {
    Text = "看啊！這是女王的旨意！你們只能前進！"
  },
  AvgDialog_45432_Content_42 = {
    Text = "努比亞咆哮著，朝著你們狂奔而來。"
  },
  AvgDialog_45432_Content_5 = {
    Text = "你注意到跟隨艾爾瓦的兩列士兵。\n他們神情肅穆，慨然如赴死。"
  },
  AvgDialog_45432_Content_6 = {
    Text = "站在首位的青年人輪廓硬朗，身姿筆挺，看起來有些熟悉。"
  },
  AvgDialog_45432_Content_7 = {
    Text = "風暴之壁？"
  },
  AvgDialog_45432_Content_8 = {
    Text = "你放眼遠眺，碧空晴朗，視野清明，看上去並無任何沙暴跡象。"
  },
  AvgDialog_45432_Content_9 = {
    Text = "於麗埃特迎上前來。"
  },
  AvgDialog_45433_Content_1 = {Text = "尾聲"},
  AvgDialog_45433_Content_10 = {
    Text = "但至少，我們阻止了最壞的結果。"
  },
  AvgDialog_45433_Content_11 = {
    Text = "一旦豐穰母樹在提燈教會的掌控下重生，受污染的就遠不止勒姆瓦希的北部沙漠了。"
  },
  AvgDialog_45433_Content_12 = {
    Text = "只是，我們也蒙受了自建校以來，最難承受的損失。"
  },
  AvgDialog_45433_Content_13 = {
    Text = "威廉的遺體上……沒有銀芯析出。"
  },
  AvgDialog_45433_Content_14 = {
    Text = "我們永遠失去了彌薩格建校以來最優秀的調查員，甚至不具備將他的意識部分喚回的可能性。"
  },
  AvgDialog_45433_Content_15 = {
    Text = "今日，他的遺體將被安葬於此。"
  },
  AvgDialog_45433_Content_16 = {
    Text = "威廉是我認識的最具天賦的調查員，他敏銳的洞察、臨危不懼的態度和不凡的身手在人類中都出類拔萃。"
  },
  AvgDialog_45433_Content_17 = {
    Text = "阿利斯泰爾老師！"
  },
  AvgDialog_45433_Content_18 = {
    Text = "輪椅的吱呀聲中，人群為阿利斯泰爾讓出一條道路。"
  },
  AvgDialog_45433_Content_19 = {
    Text = "他的生涯雖被神秘的陰影所吞沒，但他的光輝事蹟，將如星辰長明。"
  },
  AvgDialog_45433_Content_2 = {
    Text = "鑰塚細雨霏霏，一如授鑰儀式那天。"
  },
  AvgDialog_45433_Content_20 = {
    Text = "死亡如影隨形，在融蝕面前，我們沒有太多緬懷的時間。"
  },
  AvgDialog_45433_Content_21 = {
    Text = "%player%，你跟我來。關於塔薇、關於三大質體、關於融蝕……有很多你現在必須要知道的資訊。"
  },
  AvgDialog_45433_Content_22 = {
    Text = "我沒有想到，你對同僚的冷漠程度已經達到了不去參加他的葬禮的級別。"
  },
  AvgDialog_45433_Content_23 = {
    Text = "我習慣不了那種氛圍。"
  },
  AvgDialog_45433_Content_24 = {
    Text = "何況智之質體甦醒、欲之質體沉沒、悅之質體現身……威廉不在，總該輪到我焦頭爛額了。"
  },
  AvgDialog_45433_Content_25 = {
    Text = "悅之質體現身？"
  },
  AvgDialog_45433_Content_26 = {
    Text = "威廉死亡現場的痕跡勘察可不是一無所獲啊。"
  },
  AvgDialog_45433_Content_27 = {
    Text = "一枚超維界域的銀芯，經檢驗屬於卡茜亞。"
  },
  AvgDialog_45433_Content_28 = {
    Text = "除此之外，我們還監測到悅之質體活動的痕跡——"
  },
  AvgDialog_45433_Content_29 = {
    Text = "誰讓你們這麼不珍惜我的玩具，還得我親自動小指頭把他撈回來？"
  },
  AvgDialog_45433_Content_3 = {
    Text = "眾人肅立早已銘刻姓名的墓碑之前，見證一場真正的葬禮。"
  },
  AvgDialog_45433_Content_30 = {
    Text = "還得多謝N先生出手相助了。"
  },
  AvgDialog_45433_Content_31 = {
    Text = "下次見面的時候，記得跟我說，謝謝N的胸襟開闊、心慈手軟、豁達大度、寬宏大量……"
  },
  AvgDialog_45433_Content_32 = {
    Text = "萊克撓了撓毛茸茸的後腦勺。"
  },
  AvgDialog_45433_Content_33 = {
    Text = "這麼說也不太對，我們約好了，在我贏你一局之前，你都會讓我一遍又一遍經歷失敗和死亡的痛苦的，不是嗎？"
  },
  AvgDialog_45433_Content_34 = {
