  },
  AvgDialog_45437_Content_7 = {
    Text = "跟於麗埃特受到的熱烈歡迎相比，她接受的歡呼之零星，令女王之名都顯得有些名不副實。"
  },
  AvgDialog_45437_Content_8 = {
    Text = "感謝諸位。炎陽考驗了每一個踏入沙漠的人，你們的熱情如同聖河之水，令人難忘。"
  },
  AvgDialog_45437_Content_9 = {
    Text = "想來各位都已經疲憊，請回各自的居所，享受夜晚的安寧吧。"
  },
  AvgDialog_45438_Content_1 = {
    Text = "於麗埃特……為什麼……"
  },
  AvgDialog_45438_Content_2 = {
    Text = "事已至此，也沒什麼好忌憚的了。"
  },
  AvgDialog_45438_Content_3 = {
    Text = "亞蘭人以畸形之人的淋漓鮮血為代價換取種群的繁衍，你們的存在本身就是污穢和罪惡。"
  },
  AvgDialog_45438_Content_4 = {
    Text = "身懷原罪降生的傢伙，只配成為神國奠基的薪柴。"
  },
  AvgDialog_45438_Content_5 = {
    Text = "而最珍貴的孩子，已經在我的囊中，成為去往新世界的適格者。"
  },
  AvgDialog_45438_Content_6 = {
    Text = "艾爾瓦面前，一隻人面犬匍匐於地。"
  },
  AvgDialog_45438_Content_7 = {
    Text = "真乖，不愧是我選中的孩子。"
  },
  AvgDialog_45438_Content_8 = {
    Text = "涅弗……魯瑞……"
  },
  AvgDialog_45438_Content_9 = {
    Text = "去吧，孩子，為守護母樹的重生，撕碎你的敵人。"
  },
  AvgDialog_45439_Content_1 = {
    Text = "什麼事這麼喧嘩？"
  },
  AvgDialog_45439_Content_10 = {
    Text = "你有什麼證據呢？"
  },
  AvgDialog_45439_Content_11 = {
    Text = "威廉死亡的慘狀浮現在你的面前。\n他死於某種窮兇極惡的怪物，與提燈教會息息相關。"
  },
  AvgDialog_45439_Content_12 = {
    Text = "但指控於麗埃特……你無法提出任何證據。"
  },
  AvgDialog_45439_Content_13 = {
    Text = "請你好好回憶一下，我與諸位渡過的那些日子。"
  },
  AvgDialog_45439_Content_14 = {
    Text = "你要聽信%hisorher%胡言亂語嗎？"
  },
  AvgDialog_45439_Content_15 = {
    Text = "質疑之聲此起彼伏，其中並無任何對你的信任。"
  },
  AvgDialog_45439_Content_16 = {
    Text = "%player%，我也很傷心，迄今為止，我一直信任你，忽視你在亞蘭的種種無禮，甚至代你向族長求情。"
  },
  AvgDialog_45439_Content_17 = {
    Text = "如今看來，的確是我看錯了你。"
  },
  AvgDialog_45439_Content_18 = {
    Text = "艾爾瓦大人，請您寬宥我的錯誤。"
  },
  AvgDialog_45439_Content_19 = {
    Text = "無論你和於麗埃特之間的糾紛最終如何解決，今天，儀式必須進行到底。"
  },
  AvgDialog_45439_Content_2 = {
    Text = "人群讓出一條通路。"
  },
  AvgDialog_45439_Content_20 = {
    Text = "任何阻撓母樹重生之人，都會成為母樹重現之路上的祭品！"
  },
  AvgDialog_45439_Content_3 = {
    Text = "是你們？"
  },
  AvgDialog_45439_Content_4 = {
    Text = "是的，我們有重要之事稟報。"
  },
  AvgDialog_45439_Content_5 = {
    Text = "於麗埃特……一直在欺騙你們。"
  },
  AvgDialog_45439_Content_6 = {
    Text = "她不是傳說中的使者，她也不具備讓母樹復生的神力。"
  },
  AvgDialog_45439_Content_7 = {
    Text = "她甚至得不到風暴之壁的准入，因為風暴之壁是由女王泰旖絲構建的，隔絕異心人的壁障！"
  },
  AvgDialog_45439_Content_8 = {
    Text = "你環顧四周，於麗埃特站在人群之首，你的發言似乎沒能在她的心中掀起任何波瀾。"
  },
  AvgDialog_45439_Content_9 = {
    Text = "你提出這種指控，有什麼證據嗎？"
  },
  AvgDialog_45440_Content_1 = {
    Text = "於麗埃特大人……會……獎賞我……的吧……"
  },
  AvgDialog_45440_Content_2 = {
    Text = "嗯嗯，乖孩子，你幫了很大的忙噢。"
  },
  AvgDialog_45440_Content_3 = {
    Text = "母樹……已經初具形態了。"
  },
  AvgDialog_45441_Content_1 = {Text = "對手"},
  AvgDialog_45441_Content_2 = {
    Text = "萊克一腳踢飛了佈滿銹蝕的鐵門，煙塵四起。"
  },
  AvgDialog_45441_Content_3 = {
    Text = "詭異而熟悉的嘶吼聲、骨節扭動的聲音從四方傳來。"
  },
  AvgDialog_45441_Content_4 = {
    Text = "我沒認錯吧？那些是雕塑家協會改造的實驗體？"
  },
  AvgDialog_45441_Content_6 = {
    Text = "大混戰啊。我嗅到了不好的味道。"
  },
  AvgDialog_45441_Content_7 = {
    Text = "母樹遺骸就在最裡面，靠窗的位置！"
  },
  AvgDialog_45441_Content_8 = {
    Text = "先往前看看吧，再等下去只怕他要尿褲子了。"
  },
  AvgDialog_45442_Content_1 = {Text = "夢"},
  AvgDialog_45442_Content_10 = {
    Text = "這樣可不行啊，艾爾瓦。"
  },
  AvgDialog_45442_Content_101 = {
    Text = "我聽見一聲悠悠的歎息。"
  },
  AvgDialog_45442_Content_102 = {
    Text = "終究是不夠完美的傀儡，還是需要消耗太多精力操控。"
  },
  AvgDialog_45442_Content_103 = {
    Text = "你為亞蘭而獻身的意志有多堅決，意識到真相後就會反抗得有多劇烈。"
  },
  AvgDialog_45442_Content_104 = {
    Text = "還好，我早就預料到了這種情況。"
  },
  AvgDialog_45442_Content_105 = {
    Text = "時間差不多到了，你們所有人，為你們最愛的母樹……"
  },
  AvgDialog_45442_Content_106 = {
    Text = "獻上血肉和生命吧。"
  },
  AvgDialog_45442_Content_107 = {
    Text = "我張開口，驚訝地發現自己發不出聲音。\n周遭的一切陷入了恐怖的靜止。"
  },
  AvgDialog_45442_Content_108 = {
    Text = "不，靜止的並非世界，而是我的感知，每一次輕微眨眼都彷彿過去了一個世紀。"
  },
  AvgDialog_45442_Content_109 = {
    Text = "在凝滯綿長的序列中，只有我曾經的夥伴，一個又一個的亞蘭士兵，前仆後繼地朝著聖河奔去。"
  },
  AvgDialog_45442_Content_11 = {
    Text = "不如這樣吧，剛才<Blue:哈萊曼>差人送來請帖，她準備了上好的葡萄酒，邀我過去品嘗。"
  },
  AvgDialog_45442_Content_110 = {
    Text = "嘩啦——"
  },
  AvgDialog_45442_Content_111 = {
    Text = "世界恢復了聲音和色彩。"
  },
  AvgDialog_45442_Content_112 = {
    Text = "他們一個接一個，義無反顧地躍入聖河奔湧的河水，竭力伸出雙臂，擁抱母樹枯幹的軀幹。"
  },
  AvgDialog_45442_Content_113 = {
    Text = "他們狂熱地哭喊，發出不可名狀的瘋狂嚎叫。"
  },
  AvgDialog_45442_Content_114 = {
    Text = "他們的表皮變得鬆弛，彷彿癱軟的泥漿；他們的體液抽離肉體，匯成聖河湍急的流水。"
  },
  AvgDialog_45442_Content_115 = {
    Text = "他們的骨骼像是皮肉般軟化，肢體以非人的方式扭曲、延展、纏繞，用自身的血肉，構成聖樹龐大臃腫的莖枝。"
  },
  AvgDialog_45442_Content_116 = {
    Text = "他們緩慢而痛苦地，與聖樹融為一體。"
  },
  AvgDialog_45442_Content_12 = {
    Text = "你與我同去，不醉不歸，如何？"
  },
  AvgDialog_45442_Content_13 = {
    Text = "泰旖絲大人，我恐怕……"
  },
  AvgDialog_45442_Content_14 = {
    Text = "軍人聽令行事，這可是你說的。"
  },
  AvgDialog_45442_Content_15 = {
    Text = "我的命令是——不醉不歸。"
  },
  AvgDialog_45442_Content_16 = {
    Text = "沒有鮮血和淚水的烏托邦嗎？"
  },
  AvgDialog_45442_Content_17 = {
    Text = "真沒想到啊，你看上去一板一眼的，內心裡居然做著這麼天真的夢啊。"
  },
  AvgDialog_45442_Content_18 = {
    Text = "泰旖絲大人，別笑話我……"
  },
  AvgDialog_45442_Content_19 = {
    Text = "怎麼會笑話你呢。"
  },
  AvgDialog_45442_Content_2 = {
    Text = "艾爾瓦，你被召喚出來已經挺長時間了，每天除了晨練就是勞作，卡魯涅上次請你去晚宴，你也拒絕了。"
  },
  AvgDialog_45442_Content_20 = {
    Text = "以我的骨、我的血滋養整片勒姆瓦希、讓亞蘭的血脈不息流淌。"
  },
  AvgDialog_45442_Content_21 = {
    Text = "無限繁殖血脈，期望它們中能有一個逃過那位大人的目光，在初與終的循環中延續我的意志……"
  },
  AvgDialog_45442_Content_22 = {
    Text = "我和你，難道不是一樣天真可笑嗎？"
  },
  AvgDialog_45442_Content_24 = {
    Text = "睡著了嗎？"
  },
  AvgDialog_45442_Content_25 = {
    Text = "也好。你本就並非亞蘭族裔，不應該困守在這片荒蕪的沙漠中。"
  },
  AvgDialog_45442_Content_26 = {
    Text = "等我的生命走到盡頭，你就離開勒姆瓦希，去尋找新的契約者吧。"
  },
  AvgDialog_45442_Content_28 = {
    Text = "我坐在女王營帳中，帳外葬儀上的嚎哭聲帶著刺骨的悲傷、苦痛和不舍。"
  },
  AvgDialog_45442_Content_29 = {
    Text = "能夠為信任之人哭泣，也算是一種幸運吧。\n在戰場上，我們通常沒有為已逝戰友落淚的閒暇。"
  },
  AvgDialog_45442_Content_3 = {
    Text = "你沒有想要的賞賜嗎？"
  },
  AvgDialog_45442_Content_30 = {
    Text = "對我來說，更關鍵的是失去了女王的亞蘭人應該去往何方。\n亞蘭人因悲傷而停止思考，那就由我來思考。"
  },
  AvgDialog_45442_Content_31 = {
    Text = "泰旖絲大人不信任我，我一直都知道。"
  },
  AvgDialog_45442_Content_32 = {
    Text = "亞蘭人以血脈判別親疏，在他們眼裡，流淌著異族血液的我一直都是個外人。"
  },
  AvgDialog_45442_Content_33 = {
    Text = "但亞蘭人需要領袖，無論是精神上，還是現實中。"
  },
  AvgDialog_45442_Content_34 = {
    Text = "我會擔任族長一職，守候泰旖絲大人的棺槨。"
  },
  AvgDialog_45442_Content_35 = {
    Text = "亞蘭族未來每一步，都會在<Red:泰旖絲大人>的注視下前行。"
  },
  AvgDialog_45442_Content_36 = {
    Text = "亞蘭族未來每一步，都會在<Red:女王大人>的注視下前行。"
  },
  AvgDialog_45442_Content_37 = {
    Text = "亞蘭族未來每一步，都會在<Red:@1大人>的注視下前行。"
  },
  AvgDialog_45442_Content_39 = {
    Text = "我到底是為什麼出現在這裡呢？"
  },
  AvgDialog_45442_Content_4 = {
    Text = "只要亞蘭安定繁榮，對我來說就是最好的賞賜了，泰旖絲大人。"
  },
  AvgDialog_45442_Content_40 = {
    Text = "那具棺槨裡盛放的東西……對了，好像是聖樹遺骸。"
  },
  AvgDialog_45442_Content_41 = {
    Text = "聖樹遺骸為什麼要放在女王的營帳裡？"
  },
  AvgDialog_45442_Content_42 = {
    Text = "算了，想不起來。"
  },
  AvgDialog_45442_Content_43 = {
    Text = "不過沒關係。"
  },
  AvgDialog_45442_Content_44 = {
    Text = "<Big:只要母樹重生，<Red:一切>都會好起來的。>"
  },
  AvgDialog_45442_Content_46 = {
    Text = "幾百年的生涯中，我培養過很多繼任者。"
  },
  AvgDialog_45442_Content_47 = {
    Text = "我相信會有某個英雄為亞蘭帶來曙光。"
  },
  AvgDialog_45442_Content_48 = {
    Text = "第一名繼任者死於蛇毒。"
  },
  AvgDialog_45442_Content_49 = {
    Text = "第二名繼任者死於風暴。"
  },
  AvgDialog_45442_Content_5 = {
    Text = "你根本不喜歡亞蘭對吧？你甚至不肯參加篝火晚宴。"
  },
  AvgDialog_45442_Content_50 = {
    Text = "第三名繼任者死於他人的嫉恨。"
  },
  AvgDialog_45442_Content_51 = {
    Text = "沙漠中的意外和變數太多，在沙漠中存活最久的種族，並非兇悍的高冠鷹鵰或劇毒的荒漠角蝰，而是每天只活動十分鐘的銀蟻。"
  },
  AvgDialog_45442_Content_52 = {
    Text = "將希望寄託在某個個體的身上，對亞蘭來說太過愚蠢了。"
  },
  AvgDialog_45442_Content_53 = {
    Text = "而種群削減的速度根本不等人。\n只要一次未曾預料的風暴，就能卷走幾隊人馬。"
  },
  AvgDialog_45442_Content_54 = {
    Text = "最少的時候，亞蘭隊伍收縮到不及百人。"
  },
  AvgDialog_45442_Content_55 = {
    Text = "<Red:再這麼下去，亞蘭將在我的手中滅族。>"
  },
  AvgDialog_45442_Content_56 = {
    Text = "明天晚上……重啟篝火晚會。"
  },
  AvgDialog_45442_Content_57 = {
    Text = "晚會上，他們歡歌暢飲。\n於黎明之時，誕下一夜而生的嬰孩。"
  },
  AvgDialog_45442_Content_58 = {
    Text = "捧起那呱呱墜地的胎兒時，我竟然熱淚盈眶。"
  },
  AvgDialog_45442_Content_59 = {
    Text = "母樹的權能，是上天賜予亞蘭的奇蹟，而我竟然因為自己淺薄狹隘的見識，將它斥為異端。"
  },
  AvgDialog_45442_Content_6 = {
    Text = "不用狡辯，我都看得出來。\n這裡都是縱情恣意的瘋子，和你合不來。"
  },
  AvgDialog_45442_Content_61 = {
    Text = "母樹的神力在不斷衰弱。"
  },
  AvgDialog_45442_Content_62 = {
    Text = "畸形的胎兒越來越多。"
  },
  AvgDialog_45442_Content_63 = {
    Text = "我焦頭爛額，直到某個年長的女性偶然提及——"
  },
  AvgDialog_45442_Content_64 = {
    Text = "您還記得那支歌謠嗎？"
  },
  AvgDialog_45442_Content_65 = {
    Text = "死亡已經迫近，消亡已經起始。"
  },
  AvgDialog_45442_Content_66 = {
    Text = "母親的遺骸不見蹤跡，血與種漂泊於大地，被初生的野獸吞噬。"
  },
  AvgDialog_45442_Content_67 = {
    Text = "天空與眾神佈滿陰雲，直至異鄉使者降臨。"
  },
  AvgDialog_45442_Content_68 = {
    Text = "母樹重誕聖河，為已逝者加冕，將血脈還於亞蘭。"
  },
  AvgDialog_45442_Content_69 = {
    Text = "只要找到<Yellow:異鄉使者>，或許就能見證母樹的重生了！"
  },
  AvgDialog_45442_Content_7 = {
    Text = "可是，這樣隻為責任而活的生活，你不覺得枯燥嗎？"
  },
  AvgDialog_45442_Content_70 = {
    Text = "泰旖絲，泰旖絲——！"
  },
  AvgDialog_45442_Content_71 = {
    Text = "某人，在呼喚某人的名字。"
  },
  AvgDialog_45442_Content_72 = {
    Text = "頭痛欲裂，無數銀針在腦海中肆意穿刺，尖銳刺耳的噪聲撕扯著耳膜，血管內血流湧動的聲音卻依然清晰可聞。"
  },
  AvgDialog_45442_Content_73 = {
    Text = "<Big:泰旖絲，泰旖絲——！>"
  },
  AvgDialog_45442_Content_74 = {
    Text = "泰旖絲，那是誰？"
  },
  AvgDialog_45442_Content_75 = {
    Text = "別把那些雜音放在心上，它們只會干擾你的專注。"
  },
  AvgDialog_45442_Content_76 = {
    Text = "母樹就要重臨大地了，你不為此感到喜悅嗎？"
  },
  AvgDialog_45442_Content_77 = {
    Text = "我絕對在哪裡聽過泰旖絲這個名字。"
  },
  AvgDialog_45442_Content_78 = {
    Text = "可是，那究竟是在哪兒呢？"
  },
  AvgDialog_45442_Content_79 = {
    Text = "生前瞬息萬變的戰場，戰友臨終的笑臉，指揮官冰冷無情的答覆……\n不是，都不是。"
  },
  AvgDialog_45442_Content_8 = {
    Text = "泰旖絲大人，您知道的。\n我生前是一名軍人。軍人聽令行事。"
  },
  AvgDialog_45442_Content_80 = {
    Text = "被喚醒後日復一日的勞作，組織宴會，抵抗獸群……"
  },
  AvgDialog_45442_Content_81 = {
    Text = "被喚醒後……？"
  },
  AvgDialog_45442_Content_82 = {
    Text = "是誰喚醒的我？"
  },
  AvgDialog_45442_Content_84 = {
    Text = "<Red:泰旖絲。>"
  },
  AvgDialog_45442_Content_85 = {
    Text = "為什麼會忘記她的名字呢？"
  },
  AvgDialog_45442_Content_86 = {
    Text = "我明明每一天，都在呼喚她——"
  },
  AvgDialog_45442_Content_87 = {
    Text = "沙塵之中，走出那個我日思夜想的身影。"
  },
  AvgDialog_45442_Content_88 = {
    Text = "她的每一步都重重印在風蝕的大地上，在我的胸中掀起令熱淚滾落的激浪。"
  },
  AvgDialog_45442_Content_89 = {
    Text = "泰旖絲大人……"
  },
  AvgDialog_45442_Content_9 = {
    Text = "您是我的連結者。\n維護亞蘭是您的所願，便也是我的。"
  },
  AvgDialog_45442_Content_90 = {
    Text = "我一直在等您。\n我知道您一定會回來，您從未遺忘亞蘭。"
  },
  AvgDialog_45442_Content_91 = {
    Text = "所有亞蘭族裔聽令！古老的預言已經應驗，母樹重現於世，當為已逝者加冕！"
  },
  AvgDialog_45442_Content_92 = {
    Text = "女王踏砂歸來，重臨王座！"
  },
  AvgDialog_45442_Content_93 = {
    Text = "向亞蘭唯一的女王泰旖絲大人——"
  },
  AvgDialog_45442_Content_94 = {
    Text = "獻上你們的忠誠與意志！"
  },
  AvgDialog_45442_Content_95 = {
    Text = "我終於、終於堅持到這個時刻了。"
  },
  AvgDialog_45442_Content_96 = {
    Text = "所以，現在能請您給予我一句稱讚嗎？"
  },
  AvgDialog_45442_Content_97 = {
    Text = "稱讚我數百年的隱忍，數百年的咬牙堅持，數百年終於尋覓到令豐穰母樹重生的使者——"
  },
  AvgDialog_45442_Content_98 = {
    Text = "我們一起，讓亞蘭成為沒有鮮血和淚水的理想國，純潔無瑕的烏托邦吧。"
  },
  AvgDialog_45442_Content_99 = {
    Text = "啊，泰旖絲大人，您為何在對我搖頭呢？"
  },
  AvgDialog_45443_Content_1 = {Text = "歸來"},
  AvgDialog_45443_Content_10 = {
    Text = "孤身一人的你，需要會支持你的夥伴——泰旖絲的面容在眼前浮現。"
  },
  AvgDialog_45443_Content_11 = {
    Text = "你唯一需要做的，就是絕對信任我。\n信任亞蘭的女王。"
  },
  AvgDialog_45443_Content_12 = {
    Text = "她一定也會回饋你同等的信任。"
  },
  AvgDialog_45443_Content_13 = {
    Text = "泰旖絲？誰？"
  },
  AvgDialog_45443_Content_14 = {
    Text = "還有誰？你們的女王泰旖絲！"
  },
  AvgDialog_45443_Content_15 = {
    Text = "你瘋了嗎？要想見女王大人，就拿這柄刀抹了自己的脖子！"
  },
  AvgDialog_45443_Content_16 = {
    Text = "女王……怎麼了？"
  },
  AvgDialog_45443_Content_17 = {
    Text = "還怎麼了？女王大人已經亡故幾百年了，你若再語出不敬，我就不客氣了！"
  },
  AvgDialog_45443_Content_18 = {
    Text = "看著他認真的表情，你的內心如墜冰窟。"
  },
  AvgDialog_45443_Content_2 = {
    Text = "近千名亞蘭族裔聚集於聖河之畔，低沉的頌歌迴蕩擴散，與遠方野獸的嚎叫聲交織成混沌的樂章。"
  },
  AvgDialog_45443_Content_20 = {
    Text = "你眺望遠方，儀式的中央。"
  },
  AvgDialog_45443_Content_21 = {
    Text = "棺槨靜靜躺在高大的祭壇木架上。\n理所當然的，那裡不存在你曾見過的泰旖絲的影子。"
  },
  AvgDialog_45443_Content_22 = {
    Text = "不止是那裡。\n哪裡都不存在。"
  },
  AvgDialog_45443_Content_23 = {
    Text = "帳篷的簾幕被人推開，一位三十後半、面容嚴肅的亞蘭女性大踏步邁入帳中。"
  },
  AvgDialog_45443_Content_24 = {
    Text = "泰旖絲慌亂地蹦回棺槨上，儀態端方，儼然王座上倨傲的女王。"
  },
  AvgDialog_45443_Content_25 = {
    Text = "尊敬的客人喲……"
  },
  AvgDialog_45443_Content_26 = {
    Text = "<Red:她裝腔拿調的聲音被來者乾脆地打斷>。"
  },
  AvgDialog_45443_Content_27 = {
    Text = "艾爾瓦當然不會「打斷」女王的宣言。"
  },
  AvgDialog_45443_Content_28 = {
    Text = "使者！是使者的隊伍回來了！"
  },
  AvgDialog_45443_Content_29 = {
    Text = "村民們將狹窄的街道圍得水泄不通，手中托舉著獻給於麗埃特的貢品。"
  },
  AvgDialog_45443_Content_3 = {
    Text = "一座巨大的木質祭壇屹立在人群中，雕刻著晦澀難解符號的棺槨陳列其上，周遭的目光混合著恐懼、狂熱與期待。"
  },
  AvgDialog_45443_Content_30 = {
    Text = "隊伍的最後，泰旖絲悠遊地坐在棺槨之上，由四位亞蘭戰士抬入。"
  },
  AvgDialog_45443_Content_31 = {
    Text = "跟於麗埃特受到的熱烈歡迎相比，<Red:她接受的歡呼之零星，令女王之名都顯得有些名不副實>。"
  },
  AvgDialog_45443_Content_32 = {
    Text = "所有民眾眼中，不存在端坐遺骸上的女王。"
  },
  AvgDialog_45443_Content_33 = {
    Text = "能不能把這個送給我？"
  },
  AvgDialog_45443_Content_34 = {
    Text = "你順著她的指尖望去，視線落在一枚金屬項圈上。"
  },
  AvgDialog_45443_Content_35 = {
    Text = "客人好眼光！要看看這枚項圈嗎？"
  },
  AvgDialog_45443_Content_36 = {
    Text = "這是我女兒親手打造的，尤其是中間這枚青金石，質地均勻，色澤細膩，您這麼識貨肯定看得出來！"
  },
  AvgDialog_45443_Content_39 = {
    Text = "啊？您確定不要青金石嗎？"
  },
  AvgDialog_45443_Content_4 = {
    Text = "你剛一踏入其中，就遭到了嚴厲的阻攔。"
  },
  AvgDialog_45443_Content_40 = {
    Text = "加上這枚青金石的話，彌薩格給你準備的那點兒經費可就捉襟見肘了。"
  },
  AvgDialog_45443_Content_42 = {
    Text = "好吧，給<Red:這位客人>包起來。"
  },
  AvgDialog_45443_Content_43 = {
    Text = "攤主在回應的，只是你的話語。"
  },
  AvgDialog_45443_Content_44 = {
    Text = "在不遠處的沙丘上，你見到了那個身影。"
  },
  AvgDialog_45443_Content_45 = {
    Text = "從輪廓中你認出來，那是泰旖絲。"
  },
  AvgDialog_45443_Content_46 = {
    Text = "風暴……是不是小了？"
  },
  AvgDialog_45443_Content_47 = {
    Text = "她唱誦著不知名的禱文，任獵獵狂風卷起她的紗袍，緩慢而穩健地走進黑暗的沙暴。"
  },
  AvgDialog_45443_Content_48 = {
    Text = "轟鳴聲震耳欲聾，禱文的聲音卻清晰可辨，彷彿迴響在你的顱骨內側。"
  },
  AvgDialog_45443_Content_49 = {
    Text = "吞天噬地的狂風中，她像是在和生存在沙漠中的某種生靈平靜交談。"
  },
  AvgDialog_45443_Content_5 = {
    Text = "什麼人！"
  },
  AvgDialog_45443_Content_50 = {
    Text = "是女王！女王來拯救我們，拯救亞蘭了！"
  },
  AvgDialog_45443_Content_51 = {
    Text = "原本亟待逃生的亞蘭隊伍突然停了下來。"
  },
  AvgDialog_45443_Content_52 = {
    Text = "無數亞蘭人面朝泰旖絲所在的方向，肅穆虔誠地跪拜。"
  },
  AvgDialog_45443_Content_53 = {
    Text = "但在他們跪拜方向的盡頭……\n那裡空無一物，只有你能看見泰旖絲被沙風掀起的衣角。"
  },
  AvgDialog_45443_Content_54 = {
    Text = "身為欲之質體的載體，豐穰母樹的存在一定在星球上刻下了足夠深刻的烙印。"
  },
  AvgDialog_45443_Content_55 = {
    Text = "母樹頑強的生命力，讓母樹被融蝕侵蝕的速度比常人緩上千倍萬倍。"
  },
  AvgDialog_45443_Content_56 = {
    Text = "所以，<Red:對你而言，她還不曾完全消失>。"
  },
  AvgDialog_45443_Content_57 = {
    Text = "若再過上百年千年，<Red:亞蘭人或許連母樹的存在都會遺忘>。"
  },
  AvgDialog_45443_Content_59 = {
    Text = "他們從未見過名為泰旖絲的女王，他們信仰的、跪拜的都是只是口口相傳的虛無之物。"
  },
  AvgDialog_45443_Content_6 = {
    Text = "現在是儀式的關鍵時刻，無關人等不得進入！"
  },
  AvgDialog_45443_Content_60 = {
    Text = "那名帶你遊歷、為你獻舞，坐在棺槨上裝腔作勢的泰旖絲，<Red:在他們眼中從未存在過>。"
  },
  AvgDialog_45443_Content_61 = {
    Text = "但你很肯定，異常肯定——"
  },
  AvgDialog_45443_Content_62 = {
    Text = "肯定月夜下的記憶。"
  },
  AvgDialog_45443_Content_63 = {
    Text = "肯定指尖殘留的溫度。"
  },
  AvgDialog_45443_Content_64 = {
    Text = "肯定她輕柔的絮語。"
  },
  AvgDialog_45443_Content_65 = {
    Text = "你知道嗎？我在你的眼中看到了災厄，看到了亙古的餘燼，看到了寰宇天地的呼吸。"
  },
  AvgDialog_45443_Content_66 = {
    Text = "你經歷的旅程很漫長，已經很疲憊了吧？但你的目光還是那麼堅定，沒有一絲渾濁。"
  },
  AvgDialog_45443_Content_67 = {
    Text = "群星不能轉變你，沙海也未必可以。"
  },
  AvgDialog_45443_Content_68 = {
    Text = "她的鼻息與你相聞。\n星海在她的眼底燃燒。"
  },
  AvgDialog_45443_Content_69 = {
    Text = "我要去終結亞蘭的儀式。"
  },
  AvgDialog_45443_Content_7 = {
    Text = "我要見泰旖絲！"
  },
  AvgDialog_45443_Content_70 = {
    Text = "泰旖絲……一定在那裡等我。"
  },
  AvgDialog_45443_Content_8 = {
    Text = "你不會誤讀威廉為你留下的關鍵線索——努比亞、假使者、母樹污染……這一切的背後都是提燈教會的手筆。"
  },
  AvgDialog_45443_Content_9 = {
    Text = "拉蒙娜、威廉、萊克……彌薩格的同僚們此時此刻都已經離開。"
  },
  AvgDialog_45444_Content_1 = {
    Text = "母樹之下，無力的艾爾瓦流淚跪伏。"
  },
  AvgDialog_45444_Content_10 = {
    Text = "只在狹小的縫隙之間，可以窺視另一個世界外的光明。"
  },
  AvgDialog_45444_Content_11 = {
    Text = "就在那瞬息的罅隙中，我跟著亞蘭族的隊伍四處流亡遷徙。"
  },
  AvgDialog_45444_Content_12 = {
    Text = "我見證了艾爾瓦在群龍無首時主動扛下大任的堅決。"
  },
  AvgDialog_45444_Content_13 = {
    Text = "我見證了艾爾瓦廢止篝火儀式時的決意，培養的繼承人夭折時的痛苦，重啟篝火儀式時的無奈。"
  },
  AvgDialog_45444_Content_14 = {
    Text = "見證了艾爾瓦率隊尋找飲水物資的奔忙，也見證了她為對抗努比亞主動出戰的艱辛。"
  },
  AvgDialog_45444_Content_15 = {
    Text = "艾爾瓦，你已經做得很好了。"
  },
  AvgDialog_45444_Content_16 = {
    Text = "即使是我留在這裡，也不能做得比你更好。"
  },
  AvgDialog_45444_Content_17 = {
    Text = "所以，接下來的事情，就交給我吧。"
  },
  AvgDialog_45444_Content_18 = {
    Text = "泰旖絲撫摸艾爾瓦的頭顱，然後轉身迎向萬千失神的亞蘭士卒。"
  },
  AvgDialog_45444_Content_19 = {
    Text = "我是大地的母親、欲之質體的化身。"
  },
  AvgDialog_45444_Content_2 = {
    Text = "女王大人……我……對不起……亞蘭……"
  },
  AvgDialog_45444_Content_20 = {
    Text = "我名為泰旖絲，聖名<Yellow:提芙蕾·耶索德>。"
  },
  AvgDialog_45444_Content_21 = {
    Text = "我以亞蘭唯一的女王之名，討伐你這吞噬生靈、傳播死亡的，虛偽的豐穰母樹。"
  },
  AvgDialog_45444_Content_22 = {
    Text = "我將自你體內，解救亞蘭的子民，為他們求取存續之路。"
  },
  AvgDialog_45444_Content_23 = {
    Text = "亞蘭的子民啊，若你們尚能聽見我的聲音，就請醒來吧！"
  },
  AvgDialog_45444_Content_24 = {
    Text = "世界陷入瞬息的靜止。"
  },
  AvgDialog_45444_Content_25 = {
    Text = "然而，不過數秒之後，亞蘭的隊伍又如同不知疲倦不知回頭的旅鼠般墜入聖河。"
  },
  AvgDialog_45444_Content_26 = {
    Text = "沒用的，你和豐穰母樹同根同源，都已經被那位大人的意志侵染，以你現在的力量，根本無法撼動被侵蝕的母樹意志。"
  },
  AvgDialog_45444_Content_27 = {
    Text = "我當然知道。"
  },
  AvgDialog_45444_Content_28 = {
    Text = "若非如此，又何須這數百年跋涉？"
  },
  AvgDialog_45444_Content_29 = {
    Text = "我以聖河隱藏母樹之軀，以肉身承受融蝕隱匿母樹之種，不正是為了等待此刻嗎？"
  },
  AvgDialog_45444_Content_3 = {
    Text = "不必擔心。你的心聲，我已經聽見了。"
  },
  AvgDialog_45444_Content_30 = {
    Text = "決戰之刻已至！"
  },
  AvgDialog_45444_Content_31 = {
    Text = "我以欲之質體提芙蕾·耶索德的名義，向<Yellow:塔薇>提出請求，請回應我們千年前的約定——"
  },
  AvgDialog_45444_Content_32 = {
    Text = "當異鄉的使者降臨，以你的化身為引，為我暫時驅散籠罩勒姆瓦希的陰翳。"
  },
  AvgDialog_45444_Content_33 = {
    Text = "天空中響起嘹亮的悲鳴。"
  },
  AvgDialog_45444_Content_34 = {
    Text = "泰旖絲打開棺槨，其中翻身而出的，竟是燒得滿面通紅的拉蒙娜。"
  },
  AvgDialog_45444_Content_35 = {
    Text = "終於……需要我了嗎……"
  },
  AvgDialog_45444_Content_36 = {
    Text = "藏在這裡面跟來，也真虧你想得出來，小姑娘。"
  },
  AvgDialog_45444_Content_37 = {
    Text = "也還好你跟來了，不然回去接你的每分鐘，都要消耗不知道多少生命。"
  },
  AvgDialog_45444_Content_38 = {
    Text = "腦子裡的那個聲音……她告訴我……我一定要堅持……"
  },
  AvgDialog_45444_Content_39 = {
    Text = "不過，即使她不說……\n我也是%player%唯一的助手，最危險的時刻，我必須在%heorshe%身邊。"
  },
  AvgDialog_45444_Content_4 = {
    Text = "因為，沒有人比我更懂不被聽見的痛苦。"
  },
  AvgDialog_45444_Content_40 = {
    Text = "這是我身為唯一助手的職責，對吧？"
  },
  AvgDialog_45444_Content_41 = {
    Text = "她的“唯一”兩個字咬得很重。"
  },
  AvgDialog_45444_Content_42 = {
    Text = "在這片土地上喚醒她的力量，你的身體所受的影響會更加劇烈。"
  },
  AvgDialog_45444_Content_43 = {
    Text = "如果還有其他辦法，我也不願意出此下策。"
  },
  AvgDialog_45444_Content_44 = {
    Text = "彌薩格為了阻止儀式而到此，我是彌薩格的一員，萬死而不辭！"
  },
  AvgDialog_45444_Content_45 = {
    Text = "好！拉蒙娜壓制欲之質體，%player%你和我一起，徹底擊潰母樹！"
  },
  AvgDialog_45444_Content_46 = {
    Text = "長空之中響起震耳欲聾的嘯鳴，銀色的虛影劃過大漠的高空。"
  },
  AvgDialog_45444_Content_48 = {
    Text = "你感覺身體一輕，下一秒已經落在了一團髒臭的腫瘤前。"
  },
  AvgDialog_45444_Content_49 = {
    Text = "被母樹吞吃的亞蘭人以卵形態積聚在此，半透明孔洞中，無數面龐扭曲模糊，只有紅黑色的漿液順著孔洞源源不絕湧出，匯入不再清澈的聖河中。"
  },
  AvgDialog_45444_Content_5 = {
    Text = "我跟隨亞蘭的隊伍，遷徙了數百年。"
  },
  AvgDialog_45444_Content_6 = {
    Text = "沒有人看得見我，沒有人聽得見我。"
  },
  AvgDialog_45444_Content_7 = {
    Text = "我曾是晚宴中最美的舞姬，也曾是亞蘭族最受擁戴的女王。\n但此刻，我的舞姿無人可見，我的律令無人可聞。"
  },
  AvgDialog_45444_Content_8 = {
    Text = "融蝕之內，是另一個世界。"
  },
  AvgDialog_45444_Content_9 = {
    Text = "漆黑、死寂、絕望。"
  },
  AvgDialog_46539_Content_1 = {
    Text = "經過一年的授課和近期的任務調查，你現在的資歷已經可以接觸「相位對弈」了。"
  },
  AvgDialog_46539_Content_10 = {
    Text = "當然，進行戰鬥的都是喚醒體——不過在相位過程中，某些存在會受到物理界限的<Yellow:扭曲>。"
  },
  AvgDialog_46539_Content_11 = {
    Text = "<Yellow:喚醒體的能力>，<Yellow:界域的隔閡>乃至<Yellow:戰鬥規則>都與現實中大相徑庭。"
  },
  AvgDialog_46539_Content_12 = {
    Text = "你對喚醒體們的<Yellow:養成也會失效>，不過<Yellow:對方亦然>。某種程度上而言，「相位對弈」是一場<Yellow:公平對決>。"
  },
  AvgDialog_46539_Content_13 = {
    Text = "啟動相位儀器，嘗試一次對弈吧，一切疑問都將在實戰中得到解答。願銀鑰指引前路。"
  },
  AvgDialog_46539_Content_2 = {
    Text = "說起來，你有從其他人那兒聽說過「相位對弈」嗎？"
  },
  AvgDialog_46539_Content_4 = {
    Text = "很好，不過基於學校的規章，我必須向你更全面地講解其中的風險與規則。"
  },
  AvgDialog_46539_Content_5 = {
    Text = "聞所未聞"
  },
  AvgDialog_46539_Content_6 = {
    Text = "好，那我會從頭開始向你介紹。"
  },
  AvgDialog_46539_Content_7 = {
    Text = "在對銀芯的研究中，我們發現銀芯振動時產生的振波，偶爾能夠跨越物理的界限。我們將發生振波的位置稱為<Yellow:相位>。"
  },
  AvgDialog_46539_Content_8 = {
    Text = "而「相位對弈」，正是一種利用相位，與另一個時空的自己進行<Yellow:對戰>，從而達到鍛煉精神與戰鬥意識效果的特化訓練。"
  },
  AvgDialog_46539_Content_9 = {
    Text = "另一個時空的自己……"
  },
  AvgDialog_46700_Content_1 = {
    Text = "諾斯指數89.8，潮頻762hz，還在不斷上升中……"
  },
  AvgDialog_46700_Content_2 = {
    Text = "毫無疑問，是<Yellow:融災黑潮>。各部門就位，監測組實時彙報諾斯指數，對策組預備方案，行動組展開人工密境，準備通過精神維度潛入融災禁區！"
  },
  AvgDialog_46700_Content_3 = {
    Text = "融災黑潮？"
  },
  AvgDialog_46700_Content_4 = {
    Text = "黑池內部的意識維度受潮汐影響形成的階段性湧動，若是處置不當也可能在聯通的各大<Yellow:融災禁區>引發劇烈災變。"
  },
  AvgDialog_46700_Content_5 = {
    Text = "訶勒特院長在授鑰儀式上提及的漂浮異常存在，正是融災黑潮爆發的徵兆。"
  },
  AvgDialog_46700_Content_6 = {
    Text = "未知的精神潮汐會干擾密境穩定性，內部環境瞬息萬變，<Yellow:喚醒體和敵方都可能受到黑潮影響>……"
  },
  AvgDialog_46700_Content_7 = {
    Text = "原理等到課堂上再討論吧，第一波融災已經襲來，準備應對黑潮災害！"
  },
  AvgDialog_46700_Content_8 = {
    Text = "願銀鑰指引你們。"
  },
  AvgDialog_46733_Content_1 = {
    Text = "雖然只是又一個再普通不過的外勤之夜，但離校在外的夜晚，你總是睡得不那麼安心。"
  },
  AvgDialog_46733_Content_10 = {
    Text = "奧吉爾，你哪裡不太舒服嗎？"
  },
  AvgDialog_46733_Content_11 = {
    Text = "主君，我、我…沒有……是它們……"
  },
  AvgDialog_46733_Content_12 = {
    Text = "奧吉爾吃力地抱起不受控的無形之物，原本只是像奧吉爾的力量一般盤繞身側的它們變得異常活躍——"
  },
  AvgDialog_46733_Content_14 = {
    Text = "活躍到，它們在你靠近查看時，像貓舌一般“舔”上了你的臉。"
  },
  AvgDialog_46733_Content_16 = {
    Text = "我、奧、不…故意……"
  },
  AvgDialog_46733_Content_17 = {
    Text = "你推開了像貓一樣貼上來的無形之物，手指陷進奧吉爾柔軟的金髮中，安撫性地揉弄著他的髮絲。"
  },
  AvgDialog_46733_Content_18 = {
    Text = "沒關係，慢慢說。"
  },
  AvgDialog_46733_Content_19 = {
    Text = "我……我不知道為什麼，今天非常想留在主君身邊。這種感覺強烈到，強烈到無形之物都不太聽我的使喚……"
  },
  AvgDialog_46733_Content_2 = {
    Text = "世界的聲音在黑暗中變得格外抓耳，特別是那一聲聲稚嫩而沉重的呼吸——"
  },
  AvgDialog_46733_Content_20 = {
    Text = "<Small:難道是聖河和母樹的影響嗎？>"
  },
  AvgDialog_46733_Content_21 = {
    Text = "如果打擾到主君了的話……"
  },
  AvgDialog_46733_Content_22 = {
    Text = "沒關係哦。"
  },
  AvgDialog_46733_Content_23 = {
    Text = "真、真的嗎？！"
  },
  AvgDialog_46733_Content_24 = {
    Text = "你拉著奧吉爾進了房間，強硬地把他推在了床上，自己則拉來一把椅子，坐在了床邊。"
  },
  AvgDialog_46733_Content_25 = {
    Text = "今晚就留在我這裡吧，這樣就能好好睡一覺了吧。"
  },
  AvgDialog_46733_Content_26 = {
    Text = "我怎麼能在主君的床榻上過夜，這不合禮數——"
  },
  AvgDialog_46733_Content_27 = {
    Text = "奧吉爾被你用被子裹成了一團，整個人毛毛蟲一般不安蠕動著，直到你將手按在他的額前。"
  },
  AvgDialog_46733_Content_29 = {
    Text = "你沒聽過幾首搖籃曲，現下下意識哼出的調子，也只是倫蒂尼恩諸多恐怖童謠的其中之一。"
  },
  AvgDialog_46733_Content_3 = {
    Text = "天亮後還有調查任務等著我們呢，怎麼還不睡？"
  },
  AvgDialog_46733_Content_30 = {
    Text = "但奧吉爾炯炯的雙目，居然真的逐漸暗了下去，像黎明前沉入薄霧的晚星。"
  },
  AvgDialog_46733_Content_32 = {
    Text = "你在床邊久久地看著他，直到呼吸變得綿長，窗外的星空也變得不甚明朗。你才摸摸他額角的碎髮，躡手躡腳離開了房間。"
  },
  AvgDialog_46733_Content_33 = {
    Text = "睡個好覺，好孩子。"
  },
  AvgDialog_46733_Content_4 = {
    Text = "主、主君！奧吉爾無意驚擾主君的安眠，只是、只是……"
  },
  AvgDialog_46733_Content_5 = {
    Text = "奧吉爾抱著武器，背靠過道，像騎士雕塑般守在你的門外。"
  },
  AvgDialog_46733_Content_6 = {
    Text = "他不知道在走廊上這麼傻站了多久，見你拉開門，他反射性想要向你行禮，身體卻無力地打了個踉蹌。"
  },
  AvgDialog_46733_Content_8 = {
    Text = "你穩穩扶住了險些摔倒的少年，但似乎只讓奧吉爾變得更加窘迫。"
  },
  AvgDialog_46733_Content_9 = {
    Text = "他滿臉通紅，手忙腳亂，似乎想收起不受控制流溢的無形之物，似乎又想要從你身邊逃離。"
  },
  AvgDialog_46734_Content_1 = {
    Text = "抱歉，守密人，請暫時不要看我。"
  },
  AvgDialog_46734_Content_10 = {
    Text = "女人的手抓握著你的胳膊，她的指節修長有力，即使隔著布料，也能察覺到常年使用槍械留下的薄繭。"
  },
  AvgDialog_46734_Content_11 = {
    Text = "在這漫長的歲月中，我已習慣了忍耐來自聖河的影響……沒錯，祂神聖、慈悲，令族群得以延續，然而我所追尋的，無法在祂的灼熱中獲得。"
  },
  AvgDialog_46734_Content_12 = {
    Text = "說這麼正直的台詞的時候，艾爾瓦……你的動作好像不太應該是這樣吧？！"
  },
  AvgDialog_46734_Content_13 = {
    Text = "我的意思是，我現在非常冷靜，我的舉動並非源於聖河，也並非源於任何外力。"
  },
  AvgDialog_46734_Content_14 = {
    Text = "<LightGray:（不，你看上去完全不冷靜。）>"
  },
  AvgDialog_46734_Content_15 = {
    Text = "說看或許不恰當，即使被剝奪了視力，你也知道現在的動作絕不是平時的艾爾瓦能做出來的。"
  },
  AvgDialog_46734_Content_16 = {
    Text = "……只是對方顯然並不這麼想。"
  },
  AvgDialog_46734_Content_17 = {
    Text = "因為我已經知道，要達成我所嚮往的願景，應該守護什麼，為誰所用。"
  },
  AvgDialog_46734_Content_18 = {
    Text = "所以，我在想——是否如今，我已經可以選擇遵循本能，去探尋一些我從未觸碰過的事物。"
  },
  AvgDialog_46734_Content_19 = {
    Text = "艾爾瓦的敘述極其平穩，似乎這只是對於某次訓練計畫的匯報。"
  },
  AvgDialog_46734_Content_2 = {
    Text = "艾爾瓦，你確定自己沒事嗎，你聽上去不太好。"
  },
  AvgDialog_46734_Content_20 = {
    Text = "可是心跳出賣了主人，那種鼓噪難以如同你眼前的光線一樣被輕易遮掩。"
  },
  AvgDialog_46734_Content_21 = {
    Text = "這位曾經投身於正義的殉葬者，顯然正在經歷另一場和自己的戰爭。"
  },
  AvgDialog_46734_Content_22 = {
    Text = "您可以隨時推開我，打暈我。"
  },
  AvgDialog_46734_Content_24 = {
    Text = "在這無盡追尋的前路上，我將獻給您永恆的忠誠……"
  },
  AvgDialog_46734_Content_25 = {
    Text = "我願永遠護衛在您身邊。"
  },
  AvgDialog_46734_Content_3 = {
    Text = "這名向來果決堅毅的女性，此刻的嗓音低啞而顫抖，她的額頭貼抵在你腦後，手掌將你的視線遮蔽在了一片黑暗之中。"
  },
  AvgDialog_46734_Content_4 = {
    Text = "在當期的訓練之後，艾爾瓦破天荒地闖進了你的宿舍，進行了長達三十秒的呼哧呼哧大喘氣挑戰，然後強硬地把你疑惑的目光掰向了另一個方向。"
  },
  AvgDialog_46734_Content_6 = {
    Text = "你不知道她到底在想什麼，但理智告訴你，現在除了代表疑惑的單音節，最好不要發出其他聲音。"
  },
  AvgDialog_46734_Content_7 = {
    Text = "你也這麼做了，艾爾瓦對你尷尬的僵硬報以一聲理解的大笑。"
  },
  AvgDialog_46734_Content_8 = {
    Text = "我知道聖河的影響來源於什麼，意味著什麼。"
  },
  AvgDialog_46734_Content_9 = {
    Text = "我效忠過許多存在，但我追逐的始終只有正義。即使在許多人眼中，所謂正義或許只是飄忽的泡影。"
  },
  AvgDialog_46735_Content_1 = {
    Text = "夥伴！夥伴快來！"
  },
  AvgDialog_46735_Content_10 = {
    Text = "是新朋友！奧瑞塔的腺體今天分裂了好多好多新朋友！"
  },
  AvgDialog_46735_Content_11 = {
    Text = "她興奮地笑著，將帶毒的水母一股腦塞進了你手裡。"
  },
  AvgDialog_46735_Content_12 = {
    Text = "大家說想和你在一起，所以奧瑞塔也要一起！"
  },
  AvgDialog_46735_Content_13 = {
    Text = "<Small:這麼多水母……幸好我的體質沒那麼容易過敏。>"
  },
  AvgDialog_46735_Content_14 = {
    Text = "不過，就算容易過敏，用幾針腎上腺素來換她的笑容似乎也不錯。"
  },
  AvgDialog_46735_Content_2 = {
    Text = "<Small:這聲音……莫非是……>"
  },
  AvgDialog_46735_Content_3 = {
    Text = "稍等一下，我這就來開門——"
  },
  AvgDialog_46735_Content_4 = {
    Text = "來人不由分說地撞開了宿舍門，噗通一下撞到了你身上。"
  },
  AvgDialog_46735_Content_5 = {
    Text = "你扶著女孩踉蹌了兩步，最終還是沒能抵抗住地心引力，抱著她摔在了地上，眼前一片天旋地轉。"
  },
  AvgDialog_46735_Content_6 = {
    Text = "夥伴快看！"
  },
  AvgDialog_46735_Content_7 = {
    Text = "沒等你從地上爬起來，奧瑞塔就把「雙手」伸到了你面前。"
  },
  AvgDialog_46735_Content_8 = {
    Text = "傘蓋形的雙臂合攏，捧著一把拇指大小的水母。"
  },
  AvgDialog_46735_Content_9 = {
    Text = "這些水母是？"
  },
  AvgDialog_47150_Content_1 = {
    Text = "<Italic:今夜諸多眼淚，令人流連忘返~>"
  },
  AvgDialog_47150_Content_10 = {
    Text = "您的侍女應該有準備醒酒茶吧，我去讓她端過來。"
  },
  AvgDialog_47150_Content_11 = {Text = "別——"},
  AvgDialog_47150_Content_12 = {
    Text = "索蕾爾拉了你一把，順勢與你一同滾在了軟榻上。模樣狼狽，手中酒杯倒還端得穩穩當當。"
  },
  AvgDialog_47150_Content_13 = {
    Text = "莊園所有燈都熄著，只有她杯中金色的酒液折射著月光，為你們之間染著曖昧的光暈。"
  },
  AvgDialog_47150_Content_14 = {
    Text = "我沒有醉，不需要什麼醒酒茶。"
  },
  AvgDialog_47150_Content_15 = {
    Text = "我的沙龍……從來沒有如此安靜，卻又讓我感覺如此平靜過。"
  },
  AvgDialog_47150_Content_16 = {
    Text = "在過去的每一場盛會上，我都會在心中清點沙龍的客人。應了我邀約的、買了邀請函的、偷溜進來的……我會記住每個人的臉。"
  },
  AvgDialog_47150_Content_17 = {
    Text = "若有人應了邀約卻未露面，我也會記著……那些人手裡，一定還握著我不曾掌握的秘辛。"
  },
  AvgDialog_47150_Content_18 = {
    Text = "我沒有辦法不為這些潛藏的危險而感到煩躁，不為不能掌控的未來而感到焦慮……"
  },
  AvgDialog_47150_Content_19 = {
    Text = "說著，她單手挑起了你的下巴，阻止了你的眼神向別處游移。"
  },
  AvgDialog_47150_Content_2 = {
    Text = "索蕾爾夫人？珈倫傳信說，您想要見我一面？"
  },
  AvgDialog_47150_Content_20 = {
    Text = "但在「你」這個未知上，我只感覺到了好奇。"
  },
  AvgDialog_47150_Content_21 = {
    Text = "或許……你與我，能共同培育出最嬌豔強韌的蓓蕾。"
  },
  AvgDialog_47150_Content_22 = {
    Text = "我們，會一起站在無人可及的……"
  },
  AvgDialog_47150_Content_24 = {
    Text = "索蕾爾的話尚未說完，她便身體一軟，整個人的重量都壓在了你身上。"
  },
  AvgDialog_47150_Content_25 = {
    Text = "酒杯滾落在大理石地面上，酒液迅速滲進石片的接縫間。帶著酒氣的吐息，也悄然飄入了你近乎融化的大腦。"
  },
  AvgDialog_47150_Content_3 = {
    Text = "呀……小守密人，你來了。"
  },
  AvgDialog_47150_Content_5 = {
    Text = "沒等你做出更多反應，索蕾爾就將一杯酒送到了你的嘴邊。"
  },
  AvgDialog_47150_Content_6 = {
    Text = "她靠近時，濃烈的酒氣自髮梢與裙襬綻放而出。酒精與花果的香氣互相交融，由她溫熱的鼻息襲向你的手腕。"
  },
  AvgDialog_47150_Content_7 = {
    Text = "索蕾爾夫人，你又喝醉了。"
  },
  AvgDialog_47150_Content_8 = {
    Text = "醉？可能哦，我大概的確是醉了。"
  },
  AvgDialog_47150_Content_9 = {
    Text = "索蕾爾見你滴酒不進，佯裝惱怒地搖了搖頭，收回酒杯自己抿了幾口。"
  },
  AvgDialog_47164_Content_1 = {
    Text = "聆聽吧，群星"
  },
  AvgDialog_47164_Content_10 = {
    Text = "我在，黛博拉。我在這裡。"
  },
  AvgDialog_47164_Content_100 = {
    Text = "……外面的親兵呢？"
  },
  AvgDialog_47164_Content_101 = {
    Text = "你們推杯換盞的時候，那些親兵，就已經被我們幹掉了。"
  },
  AvgDialog_47164_Content_102 = {
    Text = "至於城外的軍隊……也不用再想著聯絡他們了。"
  },
  AvgDialog_47164_Content_103 = {
    Text = "鮮血染紅了大廳的每一個角落，慘叫聲瘋狂地在牆壁上撞擊、迴盪，如同來自地獄的交響。"
  },
  AvgDialog_47164_Content_104 = {
    Text = "那些沒有飲下毒酒、保持著正常的人們身體顫抖著，身體甚至抽不出拔劍或逃跑的力氣。"
  },
  AvgDialog_47164_Content_105 = {
    Text = "戈利亞欣賞著大廳中這幅血腥的繪卷，看著貴族們恐懼的神情，享受地嘆了一口氣，提起那把巨大的刀刃。"
  },
  AvgDialog_47164_Content_106 = {
    Text = "喝下毒酒變成魚人，或者死在這裡。選一個吧。"
  },
  AvgDialog_47164_Content_109 = {
    Text = "淒厲的慘叫聲撞上石板，發出沉悶的迴響。"
  },
  AvgDialog_47164_Content_11 = {
    Text = "彌利亞姆？你這是……在做什麼？"
  },
  AvgDialog_47164_Content_110 = {
    Text = "她想掙扎、逃走，但身體被彌利亞姆控制著，不能移動分毫。"
  },
  AvgDialog_47164_Content_111 = {
    Text = "她想暈過去，但她的大腦無比清醒，迎接著疼痛與恐懼。"
  },
  AvgDialog_47164_Content_112 = {
    Text = "跟我說，“凡虔誠的，吾主將眷顧……”"
  },
  AvgDialog_47164_Content_113 = {
    Text = "黛博拉的鮮血濺滿了彌利亞姆的身子。她想起很多年前，在神殿的祭祀台上，她也是這樣，送別了自己的父親。"
  },
  AvgDialog_47164_Content_114 = {
    Text = "送別，是為了更好的相聚，對吧，吾主？"
  },
  AvgDialog_47164_Content_115 = {
    Text = "她深情地望著黛博拉的腹部，匕首劃動著，完成了這幅繪圖的最後一筆。"
  },
  AvgDialog_47164_Content_116 = {
    Text = "來吧，黛博拉。跟我說。凡期願的……"
  },
  AvgDialog_47164_Content_117 = {
    Text = "彌利亞姆的手探入黛博拉的肚子，攪動，撕扯。"
  },
  AvgDialog_47164_Content_118 = {
    Text = "黛博拉喑啞的嗓子痛苦地嘶吼著，猩紅的雙眼瘋狂地睜開，直直地注視著自己的腹腔。"
  },
  AvgDialog_47164_Content_119 = {
    Text = "……“凡期願的，吾主將應許。”"
  },
  AvgDialog_47164_Content_12 = {
    Text = "這個玩笑一點都不好笑，彌利亞姆……快把我放下來……"
  },
  AvgDialog_47164_Content_120 = {
    Text = "彌利亞姆扯斷了什麼東西，或許應該很痛，但黛博拉已經感受不到了。"
  },
  AvgDialog_47164_Content_121 = {
    Text = "她的大腦已經變得麻木，情緒與感知都已離她遠去。"
  },
  AvgDialog_47164_Content_122 = {
    Text = "她模糊地看見，彌利亞姆從她的腹腔中抱出一個血淋淋的肉球。"
  },
  AvgDialog_47164_Content_123 = {
    Text = "薩……薩……"
  },
  AvgDialog_47164_Content_124 = {
    Text = "薩拉。彌利亞姆曾和她講過，這是她妹妹的名字。"
  },
  AvgDialog_47164_Content_125 = {
    Text = "她和諾德商量過了，他們會以這個名字，為自己的女兒命名。但她還沒有來得及告訴彌利亞姆。"
  },
  AvgDialog_47164_Content_126 = {
    Text = "叫她薩拉。黛博拉囁嚅著，可她已經無法再發出任何聲音。"
  },
  AvgDialog_47164_Content_127 = {
    Text = "“吾主，願我們的歌聲穿越深海，與您一同，前往無盡的安寧與極樂之境。”"
  },
  AvgDialog_47164_Content_128 = {
    Text = "彌利亞姆深情地親吻她的教女，嬰兒身上的血染紅她的唇。鮮血順著唇角滴落，她輕輕蓋上黛博拉的眼。"
  },
  AvgDialog_47164_Content_13 = {
    Text = "不，黛博拉，這不是玩笑。這世上沒有比這更莊嚴的事了。"
  },
  AvgDialog_47164_Content_130 = {
    Text = "噠，噠，噠……"
  },
  AvgDialog_47164_Content_131 = {
    Text = "輕微的腳步聲從屋內響起。"
  },
  AvgDialog_47164_Content_132 = {
    Text = "這間由幽暗的石板搭建的簡陋棚屋，樣式和彌利亞姆曾經生活的家一模一樣。"
  },
  AvgDialog_47164_Content_133 = {
    Text = "在這個屋子裡，她告別了母親，父親，妹妹，好友。"
  },
  AvgDialog_47164_Content_134 = {
    Text = "在這個屋子裡，她將與他們重逢。"
  },
  AvgDialog_47164_Content_135 = {
    Text = "腳步聲停在屋門口。"
  },
  AvgDialog_47164_Content_136 = {
    Text = "讚頌主祭大人！"
  },
  AvgDialog_47164_Content_137 = {
    Text = "讚頌主祭大人！"
  },
  AvgDialog_47164_Content_138 = {
    Text = "戈利亞跪了下來。在他身後，無數的魚人喊出的同一句話，整齊地跪倒在地。"
  },
  AvgDialog_47164_Content_139 = {
    Text = "牠們圍在棚屋四周，如同綿延不盡的浪濤，正等待著深海的指令。"
  },
  AvgDialog_47164_Content_14 = {
    Text = "你想做什麼？彌利亞姆……你不是說我是你最好的朋友嗎？"
  },
  AvgDialog_47164_Content_140 = {
    Text = "彌利亞姆懷抱著血淋淋的嬰孩，向人群走去。魚人們自覺地讓出一條道路。"
  },
  AvgDialog_47164_Content_141 = {
    Text = "群星已至正位。王的聖胎，已經植入了聖嬰體內。很快，王便將重現於世。"
  },
  AvgDialog_47164_Content_142 = {
    Text = "王，將庇護祂良善的子民，帶來神國！"
  },
  AvgDialog_47164_Content_143 = {
    Text = "神國！神國！"
  },
  AvgDialog_47164_Content_144 = {
    Text = "魚人們癲狂地歡呼、舞蹈。彌利亞姆來到人群的中央。星光落下，照亮她滿是鮮血與眼淚的臉。"
  },
  AvgDialog_47164_Content_145 = {
    Text = "王的教義將傳遍世界。主祭大人，給這個教派一個名字吧。"
  },
  AvgDialog_47164_Content_146 = {
    Text = "一雙冰冷又熾熱的眼睛緩緩轉動。彌利亞姆環顧著她的士兵，她的臣民。她向牠們露出主祭的微笑。"
  },
  AvgDialog_47164_Content_147 = {
    Text = "我們蹈海而去，追尋王的足跡。\n我們蹈海而來，帶來王的國度……"
  },
  AvgDialog_47164_Content_148 = {
    Text = "世人將稱我們，蹈海者。"
  },
  AvgDialog_47164_Content_15 = {
    Text = "你……你以前也有一個朋友，也叫黛博拉……我們不是很有緣分嗎，彌利亞姆？請……請不要傷害我……"
  },
  AvgDialog_47164_Content_150 = {
    Text = "在魚人們震耳欲聾的和鳴中，彌利亞姆伸出雙手，將懷中的嬰兒高高舉起。"
  },
  AvgDialog_47164_Content_151 = {
    Text = "在她原本的心臟處，聖胎在群星之下，散發著潔淨的白色光芒。"
  },
  AvgDialog_47164_Content_152 = {
    Text = "嗚哇——"
  },
  AvgDialog_47164_Content_153 = {
    Text = "一切都安靜了下來。被鮮血包裹的嬰兒扭動身體，古老的廢墟中，響起她遲來的第一聲啼哭。"
  },
  AvgDialog_47164_Content_154 = {
    Text = "漫天的星辰沉默著，聆聽這神諭般的哭聲。一顆星星隕落下來，在夜空中劃出一道淒厲的註腳。"
  },
  AvgDialog_47164_Content_155 = {
    Text = "——關於群星的另一段故事，便要開始了。"
  },
  AvgDialog_47164_Content_16 = {
    Text = "怎麼會呢，黛博拉？我怎麼會忍心傷害你？你是我最好的朋友，你是我唯一的朋友……"
  },
  AvgDialog_47164_Content_17 = {
    Text = "她撫摸著黛博拉的臉，拂去她恐懼的淚水。冰冷滑膩的觸感，讓黛博拉忍不住戰慄。"
  },
  AvgDialog_47164_Content_18 = {
    Text = "我永遠、永遠也不會傷害你的，黛博拉。我只是要贈予你一件禮物。"
  },
  AvgDialog_47164_Content_19 = {
    Text = "禮、禮物？"
  },
  AvgDialog_47164_Content_2 = {
    Text = "奧恩家族領地，祭祀台。"
  },
  AvgDialog_47164_Content_20 = {
    Text = "我是多麼希望自己成為那個孕育聖胎的人。可你看到過我植入聖胎的樣子，我沒有那個資格。"
  },
  AvgDialog_47164_Content_21 = {
    Text = "這份榮耀，不是誰都有資格獲得的。無法享受這份榮耀，這是我的遺憾……"
  },
  AvgDialog_47164_Content_22 = {
    Text = "黛博拉，我是你女兒的教母。我將把這份無上的榮耀，送給我的教女，也送給你，我唯一的摯友。"
  },
  AvgDialog_47164_Content_23 = {
    Text = "彌利亞姆，我願意……我願意讓女兒成為容器，享受這份榮耀……"
  },
  AvgDialog_47164_Content_24 = {
    Text = "可是，她還有三個月才出生……我也沒辦法……"
  },
  AvgDialog_47164_Content_25 = {
    Text = "來不及了，黛博拉。來不及了。"
  },
  AvgDialog_47164_Content_26 = {
    Text = "彌利亞姆愛憐地注視著黛博拉，語氣變得更加溫柔。"
  },
  AvgDialog_47164_Content_27 = {
    Text = "她是最合適的人選。她必須，出生在今天。"
  },
  AvgDialog_47164_Content_29 = {
    Text = "艾德蒙家族領地，宴會大廳。"
  },
  AvgDialog_47164_Content_3 = {
    Text = "滴答——"
  },
  AvgDialog_47164_Content_30 = {
    Text = "現在，讓我們歡迎這場宴會的主人——來自奧恩的戈利亞！"
  },
  AvgDialog_47164_Content_31 = {
    Text = "空曠的大廳內響起熱烈的歡呼。戈利亞走上台，緩慢地掃視了一圈。"
  },
  AvgDialog_47164_Content_32 = {
    Text = "艾德蒙、帕帕斯、埃諾姆……各個大家族的人們都集結在了這裡。"
  },
  AvgDialog_47164_Content_33 = {
    Text = "他們華麗的服飾上書寫著殺戮的歷史，他們歡笑的眼睛裡閃爍著貪婪的流光。"
  },
  AvgDialog_47164_Content_34 = {
    Text = "他們是土地與歷史的主人。他們是權力與慾望的奴隸。"
  },
  AvgDialog_47164_Content_35 = {
    Text = "戈利亞向他們微笑。"
  },
  AvgDialog_47164_Content_36 = {
    Text = "諸位，在今天，七大家族的聯盟便正式成立了，詳細的協定，會在稍後告知給大家。"
  },
  AvgDialog_47164_Content_37 = {
    Text = "現在，讓我們享用這場美妙的歡宴，為土地，為金錢，為權力，乾杯！"
  },
  AvgDialog_47164_Content_38 = {
    Text = "眾人歡呼著舉起手中的酒杯。精緻豐盛的菜品被一道道端上餐桌。"
  },
  AvgDialog_47164_Content_39 = {
    Text = "宴會開始了，貴族們為即將分到的利益舉杯歡慶，喧囂的聲音，掩蓋了門外的所有動靜。"
  },
  AvgDialog_47164_Content_4 = {
    Text = "水滴落下的聲音清晰地傳進黛博拉的耳朵。她緩緩睜開眼。"
  },
  AvgDialog_47164_Content_40 = {Text = "門外。"},
  AvgDialog_47164_Content_42 = {
    Text = "你們是……嗚！……"
  },
  AvgDialog_47164_Content_43 = {
    Text = "阿比夏抽出插入衛兵體內的刀。"
  },
  AvgDialog_47164_Content_44 = {
    Text = "呼……要是聽不懂這些魚人的話就好了，這樣也不會讓我來做這種活……"
  },
  AvgDialog_47164_Content_45 = {
    Text = "他看了一眼身邊的魚人士兵，哀嘆了一聲。"
  },
  AvgDialog_47164_Content_46 = {
    Text = "所有其他出口都拿下來了嗎？那些家族帶來的親衛隊，都殺死了麼？"
  },
  AvgDialog_47164_Content_47 = {
    Text = "那就好……你們把這座城堡內的所有出口都守好，安排一隊士兵跟我一起在宴會廳旁邊，等候戈利亞大人的下一步命令。"
  },
  AvgDialog_47164_Content_48 = {
    Text = "他們的大部隊恐怕要等一兩個小時才能知道這裡面發生的異變，祈禱戈利亞大人能在那之前解決問題吧……"
  },
  AvgDialog_47164_Content_5 = {
    Text = "一個由幽暗石板圍成的房間，星光從頭頂的洞口落下，照在她的肚子上。"
  },
  AvgDialog_47164_Content_50 = {
    Text = "不……彌利亞姆……不要！"
  },
  AvgDialog_47164_Content_51 = {
    Text = "求求你……求求你……看在我們的情分上……饒過我……"
  },
  AvgDialog_47164_Content_52 = {
    Text = "我將最高的榮耀贈予你，你是在侮辱這份友誼，黛博拉。"
  },
  AvgDialog_47164_Content_53 = {
    Text = "不過沒關係，吾主能理解你的恐懼。我們的友誼，不會因為這些侮辱而改變的。"
  },
  AvgDialog_47164_Content_54 = {
    Text = "她虔誠地將圖魯的雕像放在祭祀台邊上，向它行禮。"
  },
  AvgDialog_47164_Content_55 = {
    Text = "讚頌吾主……利莫里亞，偉大的王……今夜，我將迎接您回歸。"
  },
  AvgDialog_47164_Content_56 = {
    Text = "請您耐心等待。星辰正位之刻，就要到來……"
  },
  AvgDialog_47164_Content_57 = {
    Text = "她站起身，溫柔地走向黛博拉。蒼白的手中，造型怪異的祭祀匕首閃動著幽暗的光。"
  },
  AvgDialog_47164_Content_58 = {
    Text = "不！彌利亞姆！！求求你……求求你……不要做這麼殘忍的事……"
  },
  AvgDialog_47164_Content_59 = {
    Text = "看著我，黛博拉。看著我……"
  },
  AvgDialog_47164_Content_6 = {
    Text = "她的身體一絲不掛，肚子高高隆起，上面的血管在星光下清晰可見。"
  },
  AvgDialog_47164_Content_60 = {
    Text = "我知道，你很害怕。我見過很多的信徒，面對此生的終結，他們都會害怕。"
  },
  AvgDialog_47164_Content_61 = {
    Text = "但是，不要擔心。你是神國至高的子民，你所遭受的一切，都會在神國得到補償。"
  },
  AvgDialog_47164_Content_62 = {
    Text = "來，和我一起禱告吧，黛博拉。"
  },
  AvgDialog_47164_Content_63 = {
    Text = "不……彌利亞姆……我求你……"
  },
  AvgDialog_47164_Content_64 = {
    Text = "跟我說：“凡苦難的，吾主將償還。”"
  },
  AvgDialog_47164_Content_65 = {
    Text = "凡……凡苦難的……不，彌利亞姆……"
  },
  AvgDialog_47164_Content_66 = {
    Text = "跟我說。“凡罪孽的，吾主將責罰。”"
  },
  AvgDialog_47164_Content_67 = {
    Text = "彌利亞姆頌念著禱詞，來到她的身旁。"
  },
  AvgDialog_47164_Content_68 = {
    Text = "讓我和諾德說一句話！彌利亞姆……就讓我和他說一句……"
  },
  AvgDialog_47164_Content_7 = {
    Text = "這是……怎麼回事……彌利亞姆？！"
  },
  AvgDialog_47164_Content_70 = {
    Text = "劇烈的疼痛從腹部傳來。她抬起頭，看到彌利亞姆蒼白如蛇的手帶著那只匕首，插入了自己的腹腔，在她的腹腔畫出一道殷紅的軌跡。"
  },
  AvgDialog_47164_Content_71 = {
    Text = "彌利亞姆聽不見黛博拉淒厲的慘叫，看不見她因恐懼與劇痛而扭曲的面龐。"
  },
  AvgDialog_47164_Content_72 = {
    Text = "匕首穩定地劃動，溫熱的鮮血噴灑在彌利亞姆的臉上。她虔誠地頌念，踏上通往神國的階梯。"
  },
  AvgDialog_47164_Content_74 = {
    Text = "殺了彌利亞姆！瓜分奧恩家族！我們的聯盟繁榮昌盛！乾杯！！"
  },
  AvgDialog_47164_Content_75 = {
    Text = "酒杯碰撞，毫不掩飾的貪婪隨著酒肉的香味瀰漫。"
  },
  AvgDialog_47164_Content_76 = {
    Text = "戈利亞舔舐著嘴唇，享受著這種令他陶醉的味道。"
  },
  AvgDialog_47164_Content_77 = {
    Text = "來，繼續啊，你這是怎麼了？"
  },
  AvgDialog_47164_Content_78 = {
    Text = "你……你的臉……"
  },
  AvgDialog_47164_Content_79 = {
    Text = "我的臉？"
  },
  AvgDialog_47164_Content_8 = {
    Text = "她想要起身，發現自己的身體與手腳都被綁在石質的祭台上，動彈不得。"
  },
  AvgDialog_47164_Content_80 = {
    Text = "他望向身旁光滑如鏡的瓷磚，看到一張像是魚一般的臉。"
  },
  AvgDialog_47164_Content_82 = {
    Text = "一道道傷口出現在他的胸膛，如同被無形的匕首劃過。耳朵與眉毛正在消失，眼球極速地膨脹，向兩邊生長著。"
  },
  AvgDialog_47164_Content_83 = {
    Text = "劇烈的疼痛突破酒精與腎上腺素來到他的大腦。他倒在地上，發出後知後覺的痛苦哀嚎，雙手胡亂地撕扯著自己的臉。"
  },
  AvgDialog_47164_Content_84 = {
    Text = "這是？啊！！——"
  },
  AvgDialog_47164_Content_85 = {
    Text = "一個，兩個，三個……豪華的宴會大廳裡，貴族們一個接一個倒在地上。"
  },
  AvgDialog_47164_Content_86 = {
    Text = "殷紅的創口在他們身上接連出現，血與肉在他們的身體上繪製成一幅古老的圖案。"
  },
  AvgDialog_47164_Content_87 = {
    Text = "痛苦的哀嚎匯成恢弘的樂曲，鮮血噴灑，斟滿每一個酒杯。"
  },
  AvgDialog_47164_Content_88 = {
    Text = "這是……這是……魚人儀式！"
  },
  AvgDialog_47164_Content_89 = {
    Text = "沒錯，魚人儀式。奧恩家族的慘狀，你們應該都聽說過了。"
  },
  AvgDialog_47164_Content_9 = {
    Text = "一雙手伸過來，握住了她的手。那雙手冰冷、滑膩，就像一條蒼白的蛇。"
  },
  AvgDialog_47164_Content_90 = {
    Text = "為什麼……戈利亞？"
  },
  AvgDialog_47164_Content_91 = {
    Text = "為什麼？"
  },
  AvgDialog_47164_Content_92 = {
    Text = "戈利亞似乎聽到了一個好笑的笑話。他從主座上站起來，拿起了自己的刀。"
  },
  AvgDialog_47164_Content_93 = {
    Text = "跟你們合作，我能得到奧恩家族的一小塊領地。"
  },
  AvgDialog_47164_Content_94 = {
    Text = "跟彌利亞姆合作，我能得到你們無法想像的強大力量，能將你們這些家族都變成魚人的一員，掌控你們的所有財富……"
  },
  AvgDialog_47164_Content_95 = {
    Text = "告訴我，艾德蒙先生，你是我的話，你會怎麼選呢？"
  },
  AvgDialog_47164_Content_96 = {
    Text = "我……我們不會束手就擒的！"
  },
  AvgDialog_47164_Content_97 = {
    Text = "沒錯！戈利亞，以埃諾姆家族的榮耀，我們會……啊——"
  },
  AvgDialog_47164_Content_98 = {
    Text = "巨大的鋒刃豎著落下，年輕的貴族分成兩塊向兩邊倒去，失去了證明榮耀的能力。"
  },
  AvgDialog_47164_Content_99 = {
    Text = "四周的門打開，無數的魚人如同潮水般湧入大廳。"
  },
  AvgDialog_47165_Content_1 = {Text = "摯友"},
  AvgDialog_47165_Content_10 = {
    Text = "不用緊張，艾德蒙先生。彌利亞姆剝奪了我的自由，我和你們，有著共同的敵人。"
  },
  AvgDialog_47165_Content_100 = {
    Text = "彌利亞姆，也不用太擔心了，我們還可以一起想想別的辦法……"
  },
  AvgDialog_47165_Content_101 = {
    Text = "沒有別的辦法了，黛博拉。只剩下一個……"
  },
  AvgDialog_47165_Content_102 = {
    Text = "她抬起頭，擦乾了自己的淚水，撫摸著黛博拉的臉。"
  },
  AvgDialog_47165_Content_103 = {
    Text = "她想起了一些很久遠的問題。那些問題被歲月塵封，如今忽然出現，帶著漫天灰塵的氣息，瀰漫在她的腦海。"
  },
  AvgDialog_47165_Content_104 = {
    Text = "黛博拉，你信仰王嗎？"
  },
  AvgDialog_47165_Content_105 = {
    Text = "當然了……"
  },
  AvgDialog_47165_Content_106 = {
    Text = "黛博拉，你知道，什麼是信仰嗎？"
  },
  AvgDialog_47165_Content_107 = {
    Text = "我的老師曾告訴我，信仰，是一切責任與意義，是除此之外，別無他想。"
  },
  AvgDialog_47165_Content_108 = {
    Text = "嗯……你說得好複雜……"
  },
  AvgDialog_47165_Content_109 = {
    Text = "其實很簡單的。黛博拉，你是我唯一的摯友，從很早之前就是……"
  },
  AvgDialog_47165_Content_11 = {
    Text = "彌利亞姆擁有強大的力量，你們有很多英勇的戰士，但想要消滅她，也要付出極為慘痛的代價。"
  },
  AvgDialog_47165_Content_110 = {
    Text = "我答應過你，要讓你享有無上的殊榮，要讓你成為神國的第一位子民。我要讓你的家，成為神國中最幸福的家庭。"
  },
  AvgDialog_47165_Content_111 = {
    Text = "我會做到的，黛博拉。我會記住你對未來的希冀。現在，我就會將這份殊榮賜予你。"
  },
  AvgDialog_47165_Content_112 = {
    Text = "神國必定會降臨，通往神國的階梯，將會以你的名字命名。所有的信徒，所有的神國子民，都會記住你……"
  },
  AvgDialog_47165_Content_114 = {
    Text = "等等，彌利亞姆，我……"
  },
  AvgDialog_47165_Content_115 = {
    Text = "黛博拉還沒有來得及感到恐懼。她的話尚未說完，蛇形的黑霧便鑽進她的身體。她感到一陣暈眩，趴在彌利亞姆肩頭。"
  },
  AvgDialog_47165_Content_116 = {
    Text = "你不能這樣做……"
  },
  AvgDialog_47165_Content_117 = {
    Text = "我必須這樣做。"
  },
  AvgDialog_47165_Content_118 = {
    Text = "父親和王，不會想看到你這個樣子的！"
  },
  AvgDialog_47165_Content_119 = {
    Text = "你只是一個九歲的孩子，彌利亞姆。你不明白。"
  },
  AvgDialog_47165_Content_12 = {
    Text = "我願意和你們合作。這些，是我的誠意。"
  },
  AvgDialog_47165_Content_120 = {
    Text = "父親和王，想要看到神國的降臨。"
  },
  AvgDialog_47165_Content_121 = {
    Text = "我正在完成他們的願望，不是嗎？"
  },
  AvgDialog_47165_Content_122 = {
    Text = "可是……這是錯的……"
  },
  AvgDialog_47165_Content_123 = {
    Text = "只有神國，才是正確的。"
  },
  AvgDialog_47165_Content_124 = {
    Text = "彌利亞姆的聲音很平靜，像是在講述一個所有人都應該明白的常識。"
  },
  AvgDialog_47165_Content_125 = {
    Text = "小彌利亞姆望著多年後的自己。她自信，堅定，強大。她是利莫里亞無可置疑的主祭，是神國孤獨的使臣。"
  },
  AvgDialog_47165_Content_126 = {
    Text = "那個在廢墟下顫抖、呼喚著父親的女兒，已經與她再沒有任何關係。"
  },
  AvgDialog_47165_Content_127 = {
    Text = "我明白了……我想，我該走了。"
  },
  AvgDialog_47165_Content_128 = {
    Text = "她悲哀地望著她。"
  },
  AvgDialog_47165_Content_129 = {
    Text = "祝你能夠找到自己的神國，彌利亞姆。"
  },
  AvgDialog_47165_Content_13 = {
    Text = "衛兵們抬著幾個箱子進到會客廳。箱子打開，璀璨的金光照耀在老艾德蒙臉上，讓他的精神有一刻恍惚。"
  },
  AvgDialog_47165_Content_130 = {
    Text = "我會的。"
  },
  AvgDialog_47165_Content_131 = {
    Text = "她知道，那是最後的祝願與告別。幼小的彌利亞姆離開了，彷彿從未存在過。彌利亞姆沒有向她消失的地方看上一眼。"
  },
  AvgDialog_47165_Content_132 = {
    Text = "她擁抱著黛博拉，微笑著拍打她的後背，嘴裡輕聲哼著一首利莫里亞的童謠，彷彿是在哄一個孩子入睡。"
  },
  AvgDialog_47165_Content_133 = {
    Text = "窗外，夕陽落了下去，群星開始踏入各自的軌跡。"
  },
  AvgDialog_47165_Content_14 = {
    Text = "你的誠意我感受到了，戈利亞先生……你的計劃是什麼？"
  },
  AvgDialog_47165_Content_15 = {
    Text = "帕帕斯、埃諾姆、還有其他幾個大家族的人，我已經依次去拜訪了。"
  },
  AvgDialog_47165_Content_16 = {
    Text = "各個家族的軍隊已經開始集結，在軍隊開始行動之前，我想，我們需要進行一次會談。"
  },
  AvgDialog_47165_Content_17 = {
    Text = "我會告訴你們關於奧恩家族的一切，並且向你們提供我的建議。"
  },
  AvgDialog_47165_Content_18 = {
    Text = "我會讓你們以最小的代價，殺死彌利亞姆。並且……"
  },
  AvgDialog_47165_Content_19 = {
    Text = "他湊到老艾德蒙耳邊。"
  },
  AvgDialog_47165_Content_2 = {
    Text = "請坐，奧恩家族的戈利亞。"
  },
  AvgDialog_47165_Content_20 = {
    Text = "不瞞你說，艾德蒙先生，我正在尋找合適的人進行深度合作。"
  },
  AvgDialog_47165_Content_21 = {
    Text = "說句不太禮貌的話，艾德蒙家族的實力，在各大家族裡並不算強。這正是我願意和你合作的原因。"
  },
  AvgDialog_47165_Content_22 = {
    Text = "奧恩家族的財富與土地，甚至彌利亞姆的力量，我都可以將一部分獻予你。"
  },
  AvgDialog_47165_Content_23 = {
    Text = "我所要的，是深度的同盟關係。畢竟，我們所謀求的，可不只是打敗彌利亞姆和奧恩家族而已，對嗎？"
  },
  AvgDialog_47165_Content_24 = {
    Text = "老人望著戈利亞，露出心照不宣的笑容。"
  },
  AvgDialog_47165_Content_25 = {
    Text = "呵呵呵，你這個充滿野心的小鬼……"
  },
  AvgDialog_47165_Content_26 = {
    Text = "你的目光很長遠，戈利亞先生。沒錯，奧恩家族的消亡，只是一個序幕。"
  },
  AvgDialog_47165_Content_27 = {
    Text = "我們的同盟，一定會讓這片土地，開啟一個嶄新的王朝……"
  },
  AvgDialog_47165_Content_29 = {
    Text = "妹妹……父親……啊！……"
  },
  AvgDialog_47165_Content_3 = {
    Text = "老人的措辭仍保有基本的貴族涵養，但語氣中的不屑卻沒有做任何的掩藏。"
  },
  AvgDialog_47165_Content_30 = {
    Text = "彌利亞姆？彌利亞姆，你沒事吧？"
  },
  AvgDialog_47165_Content_31 = {
    Text = "彌利亞姆從床上驚醒，汗水打濕了她的後背。"
  },
  AvgDialog_47165_Content_32 = {
    Text = "父親與妹妹的身影從她面前消失，眼前是黛博拉關切的臉。"
  },
  AvgDialog_47165_Content_33 = {
    Text = "夢到你的家人了嗎？"
  },
  AvgDialog_47165_Content_34 = {
    Text = "我看到了父親和妹妹，他們都長著魚人的臉……父親說，他們已經這樣活了上萬年……"
  },
  AvgDialog_47165_Content_35 = {
    Text = "他問我，還要讓他等多久……"
  },
  AvgDialog_47165_Content_36 = {
    Text = "黛博拉，我已經……記不清父親的樣子了……"
  },
  AvgDialog_47165_Content_37 = {
    Text = "彌利亞姆無法再說下去。她虛弱地靠在床欄上。"
  },
  AvgDialog_47165_Content_38 = {
    Text = "黛博拉拿手帕敷在彌利亞姆額頭，輕輕拍打著彌利亞姆的後背。"
  },
  AvgDialog_47165_Content_39 = {
    Text = "你這段時間老是做噩夢……傷還沒有完全好，別老是想這些。"
  },
  AvgDialog_47165_Content_4 = {
    Text = "艾德蒙先生，我十分理解你們對奧恩家族的敵意。"
  },
  AvgDialog_47165_Content_40 = {
    Text = "沒事沒事。等你養好身體，帶來了神國之後，很快就能和你的家人相見了。"
  },
  AvgDialog_47165_Content_41 = {
    Text = "抱歉，黛博拉……不管是在利莫里亞，還是在現在，你都幫了我很多……"
  },
  AvgDialog_47165_Content_42 = {
    Text = "又在說些我聽不懂的話了……這有什麼好道歉的？"
  },
  AvgDialog_47165_Content_43 = {
    Text = "彌利亞姆搖了搖頭，沒有再解釋。她神情複雜地望著黛博拉隆起的肚子。"
  },
  AvgDialog_47165_Content_44 = {
    Text = "我的傷已經好得差不多了，你是快要做母親的人了，還是先照顧好自己吧。"
  },
  AvgDialog_47165_Content_45 = {
    Text = "我跟她一樣，都健康得很呢……"
  },
  AvgDialog_47165_Content_46 = {
    Text = "啊！彌利亞姆！彌利亞姆你快聽……她正在踢我！"
  },
  AvgDialog_47165_Content_47 = {
    Text = "真的嗎？我聽聽看呢……"
  },
  AvgDialog_47165_Content_48 = {
    Text = "彌利亞姆俯下身，湊到黛博拉的肚子上。"
  },
  AvgDialog_47165_Content_49 = {
    Text = "啊，是真的……我聽到了……"
  },
  AvgDialog_47165_Content_5 = {
    Text = "如今，奧恩家族走上了一條不太尋常的路……"
  },
  AvgDialog_47165_Content_50 = {
    Text = "孩子你快看，這個是你的教母，我們的主祭，彌利亞姆。是她感知到了你，我們才能早早地知道你是個女兒，給你準備出生的禮物。"
  },
  AvgDialog_47165_Content_51 = {
    Text = "以後，她還會帶著我們一家人一起，去到傳說中的神國！"
  },
  AvgDialog_47165_Content_52 = {
    Text = "到那時候，你的父親會繼續做主祭的車夫，我還要繼續做主祭的侍女……"
  },
  AvgDialog_47165_Content_53 = {
    Text = "神國裡可不需要什麼車夫和侍女。"
  },
  AvgDialog_47165_Content_54 = {
    Text = "那不行，那樣可沒有跟你待在一起有意思。"
  },
  AvgDialog_47165_Content_55 = {
    Text = "彌利亞姆凝視著黛博拉的肚子，露出一個複雜的笑容。"
  },
  AvgDialog_47165_Content_57 = {
    Text = "報告主祭大人，戈利亞大人正在門口等待。"
  },
  AvgDialog_47165_Content_58 = {
    Text = "……讓他進來吧。"
  },
  AvgDialog_47165_Content_59 = {
    Text = "看來，這個驚喜我要晚一點才能聽到了~"
  },
  AvgDialog_47165_Content_6 = {
    Text = "不太尋常的路？你們這些異種怪胎……對於這片大陸上所有的人來說，你們的存在都是一種褻瀆。"
  },
  AvgDialog_47165_Content_60 = {
    Text = "黛博拉向彌利亞姆做了個鬼臉，退到了隔壁。戈利亞推門進來，看著黛博拉的身影，若有所思。"
  },
  AvgDialog_47165_Content_61 = {
    Text = "與其他家族的聯絡，做得怎麼樣了？"
  },
  AvgDialog_47165_Content_62 = {
    Text = "陸地上的人的確比非利士人要更聰明，但只要是人，想要的東西就不會差太多。"
  },
  AvgDialog_47165_Content_63 = {
    Text = "我跟每個家族都說，要和他們成為最親近的盟友。我們會一起殺了你，消滅奧恩家族，然後，我會將這裡的土地、財富、力量分給他們。"
  },
  AvgDialog_47165_Content_64 = {
    Text = "這個承諾漏洞百出，但那些傢伙都是些相信自己能站上世界之巔的自大狂，覺得這些都是他們的天命，沒有任何懷疑。"
  },
  AvgDialog_47165_Content_65 = {
    Text = "他們的軍隊已經在集結。星辰正位之日只剩下幾天了，到時候我們會舉辦一場宴會。"
  },
  AvgDialog_47165_Content_66 = {
    Text = "那一定會是場十分美妙的盛宴。"
  },
  AvgDialog_47165_Content_67 = {
    Text = "戈利亞惡劣地笑著，露出鯊魚般尖利的牙。"
  },
  AvgDialog_47165_Content_69 = {
    Text = "你這邊呢？尋找聖嬰的事，準備得怎麼樣了？"
  },
  AvgDialog_47165_Content_7 = {
    Text = "請相信我，艾德蒙先生，這只是一種意外。是那個巫女，彌利亞姆，造成了這一切。"
  },
  AvgDialog_47165_Content_70 = {
    Text = "奧恩家族範圍內，所有的人我都已經找遍了。"
  },
  AvgDialog_47165_Content_71 = {
    Text = "我找到了一些即將出生在星辰正位之刻的嬰兒，但他們的家人，並不信仰神國。"
  },
  AvgDialog_47165_Content_72 = {
    Text = "這樣的人，是不配作為孕育王的容器的。"
  },
  AvgDialog_47165_Content_73 = {
    Text = "既要正好出生在那個時刻，又要家人能夠信仰你的神國，這的確不好辦。"
  },
  AvgDialog_47165_Content_74 = {
    Text = "現在奧恩家族的勢力範圍很狹窄，你的信仰還沒有來得及傳播開，我們能找到的人也很少……"
  },
  AvgDialog_47165_Content_75 = {
    Text = "可惜黛博拉的孩子還有三個月才出世。要不然，她肯定會是一個完美的人選。"
  },
  AvgDialog_47165_Content_76 = {
    Text = "那現在怎麼辦？要不就讓那些出生在星辰正位之刻的嬰兒試一試？"
  },
  AvgDialog_47165_Content_77 = {
    Text = "如果再次植入失敗，聖胎有可能會損壞……我不能讓王冒這樣的風險。"
  },
  AvgDialog_47165_Content_78 = {
    Text = "那可就難辦了……我想不到還有什麼能幫你的法子。"
  },
  AvgDialog_47165_Content_79 = {
    Text = "戈利亞向後靠在椅背上。看到彌利亞姆所望的方向，和她的眼神，戈利亞猛然坐直了身體。"
  },
  AvgDialog_47165_Content_8 = {
    Text = "我知道，你和其他幾個家族，正在秘密商討要圍剿奧恩家族的事情……"
  },
  AvgDialog_47165_Content_80 = {
    Text = "等等……你不會是想……"
  },
  AvgDialog_47165_Content_81 = {
    Text = "彌利亞姆輕輕轉過頭，望向戈利亞。那雙眼睛，讓戈利亞感到一陣從脊柱竄上腦門的寒意。"
  },
  AvgDialog_47165_Content_82 = {
    Text = "不愧是你啊，彌利亞姆。你可真@2是個瘋子。"
  },
  AvgDialog_47165_Content_83 = {
    Text = "不過放心好了，我並不介意這一點。我的選擇沒有錯，只有和你這樣的瘋子合作，才能做到一般人做不到的事。"
  },
  AvgDialog_47165_Content_84 = {
    Text = "去準備吧……我也要，開始準備我的儀式了。"
  },
  AvgDialog_47165_Content_85 = {
    Text = "呵呵……星辰正位之刻，一定會是一個精彩的夜晚。到時候見，主祭大人。"
  },
  AvgDialog_47165_Content_87 = {
    Text = "門被推開，溫和的夕陽照在黛博拉身上。"
  },
  AvgDialog_47165_Content_88 = {
    Text = "她一邊哼著當地的小曲子，一邊撫摸著自己隆起的肚子，腦子裡或許想著要為孩子準備些什麼東西，或許在想著要給孩子取個什麼名字。"
  },
  AvgDialog_47165_Content_89 = {
    Text = "看到彌利亞姆進來，她衝她招了招手。"
  },
  AvgDialog_47165_Content_9 = {
    Text = "老艾德蒙身體驟然緊繃，微微坐直。戈利亞將這一切看在眼裡，對著他笑了笑。"
  },
  AvgDialog_47165_Content_90 = {
    Text = "彌利亞姆，你們聊完了？怎麼樣？！"
  },
  AvgDialog_47165_Content_91 = {
    Text = "很順利，戈利亞準備得很好。"
  },
  AvgDialog_47165_Content_92 = {
    Text = "太好了！那是不是，我們很快就可以迎來神國了！"
  },
  AvgDialog_47165_Content_93 = {
    Text = "彌利亞姆對著她笑了笑。黛博拉與她相處了太久，彌利亞姆笑容裡的疲憊，被她輕易地捕捉到。"
  },
  AvgDialog_47165_Content_94 = {
    Text = "彌利亞姆，我感覺你精神好像不太好。"
  },
  AvgDialog_47165_Content_95 = {
    Text = "你說戈利亞那邊很順利……那我們這邊呢？是出現了什麼問題嗎？"
  },
  AvgDialog_47165_Content_96 = {
    Text = "我找不到合適的人，黛博拉……我們的信仰尚未傳播，沒有符合條件的聖嬰……"
  },
  AvgDialog_47165_Content_97 = {
    Text = "我想等等，等到下一個星辰正位之刻。可父親在催促，王在催促……我沒辦法再等下去了，黛博拉……"
  },
  AvgDialog_47165_Content_98 = {
    Text = "她擁抱著黛博拉，將臉埋在黛博拉的肚子上。淚水落下，打濕了黛博拉的衣服。"
  },
  AvgDialog_47165_Content_99 = {
    Text = "哎，要是我的孩子出生得再早兩三個月就好了，那樣就能幫上你……"
  },
  AvgDialog_47166_Content_1 = {
    Text = "舊日泡影"
  },
  AvgDialog_47166_Content_10 = {
    Text = "本來打算後面有空了再來看看，還沒來得及，就碰上了以格倫叛亂這一堆爛事。"
  },
  AvgDialog_47166_Content_100 = {
    Text = "呵，小不點，你倒是越來越了解我了。"
  },
  AvgDialog_47166_Content_101 = {
    Text = "戈利亞大人，您不殺彌利亞姆，是為什麼呢？"
  },
  AvgDialog_47166_Content_102 = {
    Text = "殺了她，我的確能自由。不過，自由有什麼用呢？"
  },
  AvgDialog_47166_Content_103 = {
    Text = "戈利亞看著海面上的鳥群，舒適地閉上眼。"
  },
  AvgDialog_47166_Content_104 = {
    Text = "我可以去找那些曾經擊敗過非利士人的部族算帳，可以繼續帶著族人在海岸劫掠。不過，也就僅此而已了。"
  },
  AvgDialog_47166_Content_105 = {
    Text = "彌利亞姆給了我力量，可這些力量還不夠。遠遠不夠。"
  },
  AvgDialog_47166_Content_106 = {
    Text = "一身蠻力而已，遇上那些王國的強大正規軍，我們依然只能被追殺，繼續在這片海域像野狗一樣逃竄。"
  },
  AvgDialog_47166_Content_107 = {
    Text = "我想要的，是比彌利亞姆給我的更為強大的力量。"
  },
  AvgDialog_47166_Content_108 = {
    Text = "——它叫做權力，阿比夏。跟權力比起來，自由不值一提。"
  },
  AvgDialog_47166_Content_109 = {
    Text = "猩紅的光芒在他眼中微微閃動，他舔舐著自己的嘴唇，愉悅地笑著。"
  },
  AvgDialog_47166_Content_11 = {
    Text = "這裡就是你的故鄉，對嗎？"
  },
  AvgDialog_47166_Content_110 = {
    Text = "彌利亞姆現在控制著奧恩家族。我可以利用她，把這個權力擴大到無數倍。"
  },
  AvgDialog_47166_Content_111 = {
    Text = "在那時候，我再從她的手裡拿過這些權力。"
  },
  AvgDialog_47166_Content_112 = {
    Text = "可是，彌利亞姆那麼厲害，這個風險太大了……"
  },
  AvgDialog_47166_Content_113 = {
    Text = "阿比夏，我是非利士人的領袖，還記得嗎？我們一直在失敗，逃竄。我要帶非利士人贏一次。"
  },
  AvgDialog_47166_Content_114 = {
    Text = "至於風險……你覺得，我還有什麼可失去的呢？"
  },
  AvgDialog_47166_Content_115 = {
    Text = "巨人輕輕拍了拍阿比夏的肩膀，起身向彌利亞姆的病床走去。"
  },
  AvgDialog_47166_Content_117 = {
    Text = "王……吾主……您拋棄我了……為什麼……"
  },
  AvgDialog_47166_Content_118 = {
    Text = "胸口的繃帶中滲出鮮血，彌利亞姆渾然不覺。她虛弱地躺在床上，茫然地注視著無際的海面。"
  },
  AvgDialog_47166_Content_119 = {
    Text = "你醒以後，念這句話念了一路了。就不能換點別的詞嗎？"
  },
  AvgDialog_47166_Content_12 = {
    Text = "島的外貌變化很大。或許是利莫里亞，或許是些別的什麼，我不確定。"
  },
  AvgDialog_47166_Content_120 = {
    Text = "你現在的樣子，就像一條被吊起來的死魚。"
  },
  AvgDialog_47166_Content_121 = {
    Text = "那個聖胎，一定是可以用身體供養的，我很清楚地感覺到了……我的方法沒有錯！"
  },
  AvgDialog_47166_Content_122 = {
    Text = "可是王拒絕了我……王拒絕了我！"
  },
  AvgDialog_47166_Content_123 = {
    Text = "戈利亞清晰地看到彌利亞姆的痛苦與迷茫。它們一閃而過。"
  },
  AvgDialog_47166_Content_124 = {
    Text = "王曾告訴我，在星辰正位之刻，祂將重現於世，利莫里亞將重現於世……"
  },
  AvgDialog_47166_Content_125 = {
    Text = "星辰，星辰……難道和星辰有關……"
  },
  AvgDialog_47166_Content_126 = {
    Text = "我明白了，我明白了！王的力量來自群星，或許，在星辰正位之刻出生的人，才能供養王的聖胎……"
  },
  AvgDialog_47166_Content_127 = {
    Text = "下一個星辰正位之刻很快就會到來，我可以找一個剛剛出世的……咳咳……"
  },
  AvgDialog_47166_Content_128 = {
    Text = "彌利亞姆的眼裡迸發出興奮的光芒，她猛然起身，牽動身上的傷口，猛烈地咳嗽起來。"
  },
  AvgDialog_47166_Content_129 = {
    Text = "先好好養傷吧。你要是死在這裡，你的王也活不了了。"
  },
  AvgDialog_47166_Content_13 = {
    Text = "上萬年的時間，能改變的東西很多……"
  },
  AvgDialog_47166_Content_130 = {
    Text = "尋找聖嬰也好，培養聖胎也好，召集信徒也好……你接下來要做的所有事情，都需要大量的金錢、力量、人手、權力。"
  },
  AvgDialog_47166_Content_131 = {
    Text = "我沒時間去關心這些……"
  },
  AvgDialog_47166_Content_132 = {
    Text = "這正是我們合作的意義。我有時間。很多。"
  },
  AvgDialog_47166_Content_133 = {
    Text = "接下來要做的事情，只有奧恩家族的力量是遠遠不夠的。我們需要獲得這片大陸上更多家族的支持。"
  },
  AvgDialog_47166_Content_134 = {
    Text = "奧恩家族的所有力量，你都有權調用。這些事情你來辦吧。"
  },
  AvgDialog_47166_Content_135 = {
    Text = "在下一個星辰正位之刻來臨之前，我會為王的聖胎，尋找一個合適的容器。"
  },
  AvgDialog_47166_Content_136 = {
    Text = "彌利亞姆微微側過頭，瞥了一眼戈利亞。"
  },
  AvgDialog_47166_Content_137 = {
    Text = "力量，權力，財富，尊嚴……我知道你想做什麼，非利士人。我不在乎。"
  },
  AvgDialog_47166_Content_138 = {
    Text = "留著你的命，是因為你足夠聰明。不要做蠢事。"
  },
  AvgDialog_47166_Content_139 = {
    Text = "戈利亞露出一個惡劣的微笑。"
  },
  AvgDialog_47166_Content_14 = {
    Text = "彌利亞姆仔細摩挲著海岸邊的細沙。她回憶起故鄉的滅亡，回憶自己站在那群魚人之中，絕望地望著海洋吞噬利莫里亞的一切。"
  },
  AvgDialog_47166_Content_141 = {
    Text = "彌利亞姆，我們到家了！"
  },
  AvgDialog_47166_Content_142 = {
    Text = "奧恩家族領地蜿蜒的海岸線上，那些怪異的魚人們受到感召，密密麻麻排在岸邊，迎接著牠們的主人。"
  },
  AvgDialog_47166_Content_143 = {
    Text = "戈利亞滿意地看著牠們怪異的身姿，手中的利刃，以及忠誠又愚蠢的眼神。"
  },
  AvgDialog_47166_Content_144 = {
    Text = "他望向魚人身後無盡的肥美土地，如同鯊魚望向將死的鯨。"
  },
  AvgDialog_47166_Content_15 = {
    Text = "如今，她再次出現在了這裡。很快，她就會將利莫里亞重新帶回這片海域。"
  },
  AvgDialog_47166_Content_16 = {
    Text = "你找到雕像的地方在哪裡，帶我過去。"
  },
  AvgDialog_47166_Content_17 = {
    Text = "跟我來吧。"
  },
  AvgDialog_47166_Content_18 = {
    Text = "你之前說，你要找的是什麼東西？王的聖髑？那玩意兒能用來做什麼？"
  },
  AvgDialog_47166_Content_19 = {
    Text = "喚醒王，需要找到王死後留下的銀色物質，這是儀式的必需品。"
  },
  AvgDialog_47166_Content_2 = {
    Text = "船底摩擦著細沙，停靠在海岸邊。彌利亞姆走下船隻，望著眼前這座孤島。"
  },
  AvgDialog_47166_Content_20 = {
    Text = "那個儀式具體是怎麼樣的？跟你把我們魚人化的儀式差不多嗎？"
  },
  AvgDialog_47166_Content_21 = {
    Text = "那你豈不是要把你的王拿出來鞭屍？他死了上萬年，那屍體估計一碰就散架了吧……"
  },
  AvgDialog_47166_Content_23 = {
    Text = "脖子上的紫光閃爍，鑽心的疼痛讓戈利亞倒吸了一口涼氣。"
  },
  AvgDialog_47166_Content_24 = {
    Text = "再敢對王不敬，懲罰就不會這麼輕了。好好帶路。"
  },
  AvgDialog_47166_Content_26 = {
    Text = "雜草與密林被黑霧撥開，一個小型海灣出現在眾人面前。"
  },
  AvgDialog_47166_Content_27 = {
    Text = "咦，剛才從另一個方向往這裡看，好像沒看到這個海灣？這個海灣的樣子也好奇怪……"
  },
  AvgDialog_47166_Content_28 = {
    Text = "沒錯，從不同的方向觀察，它的模樣會發生變化，甚至消失。所以我想，大概是某種巫術之類的東西……"
  },
  AvgDialog_47166_Content_29 = {
    Text = "是夢境。是王為了保護利莫里亞，為入侵者構建出的夢境！"
  },
  AvgDialog_47166_Content_3 = {
    Text = "島嶼面積極小，如同一塊崎嶇的礁石。古老而複雜的植被覆蓋在礁石上，講述著漫長時光裡的孤獨故事。"
  },
  AvgDialog_47166_Content_30 = {
    Text = "彌利亞姆的目光開始變得興奮起來。"
  },
  AvgDialog_47166_Content_31 = {
    Text = "“夢境”？"
  },
  AvgDialog_47166_Content_32 = {
    Text = "那個雕像，是在哪裡找到的？"
  },
  AvgDialog_47166_Content_33 = {
    Text = "就在那裡。"
  },
  AvgDialog_47166_Content_34 = {
    Text = "戈利亞指著不遠處一個祭台。祭台被雜草覆蓋，幾乎看不出原本的模樣。"
  },
  AvgDialog_47166_Content_35 = {
    Text = "黛博拉拿出圖魯的雕像，放在了祭台上。底座與祭台完全吻合。"
  },
  AvgDialog_47166_Content_36 = {
    Text = "好像……也沒什麼變化啊……是不是我放錯了？"
  },
  AvgDialog_47166_Content_37 = {
    Text = "要是放上去就有變化，我早就已經進去，把所有值錢的東西都拿走了。"
  },
  AvgDialog_47166_Content_38 = {
    Text = "他用詢問的目光望向彌利亞姆。她走到祭台邊，拿出匕首，割破了自己的手指。"
  },
  AvgDialog_47166_Content_39 = {
    Text = "順著潔白的指尖，一滴殷紅的鮮血落下，滴在雕像上。"
  },
  AvgDialog_47166_Content_4 = {
    Text = "失落的利莫里亞文明，這是一個流傳在非利士部族的古老傳說。"
  },
  AvgDialog_47166_Content_40 = {Text = "嘩——"},
  AvgDialog_47166_Content_41 = {
    Text = "似乎有一陣漣漪從空氣中散播開，眾人腳下的孤島開始震動起來。"
  },
  AvgDialog_47166_Content_42 = {
    Text = "這是？……"
  },
  AvgDialog_47166_Content_43 = {
    Text = "海灣的形狀開始模糊起來，海水旋轉、直立，形成一個巨大的漩渦，如同一道巨大的門，向眾人發出邀請。"
  },
  AvgDialog_47166_Content_44 = {
    Text = "王，這就是您為自己準備的墳墓……您為利莫里亞留下的火種就在裡面，對嗎？"
  },
  AvgDialog_47166_Content_46 = {
    Text = "彌利亞姆興奮地向漩渦的中心走去，沒有理會戈利亞的呼喊。戈利亞咒罵了一句，跟上前去。"
  },
  AvgDialog_47166_Content_47 = {
    Text = "這裡是……水裡？"
  },
  AvgDialog_47166_Content_48 = {
    Text = "這裡可以呼吸，還能說話……真是神蹟！"
  },
  AvgDialog_47166_Content_49 = {
    Text = "一道狹窄的石階出現在眾人面前，通向深不可見的海底。眾人隨著彌利亞姆一同向下走去。"
  },
  AvgDialog_47166_Content_5 = {
    Text = "在一次沿岸劫掠結束之後，我的船隊遇上了風暴，偶然來到了這個地方。"
  },
  AvgDialog_47166_Content_50 = {
    Text = "前面的東西……那是什麼？"
  },
  AvgDialog_47166_Content_51 = {
    Text = "沿著石階不知道走了多久，出現在眾人面前的，是一處宏偉的殘墟。"
  },
  AvgDialog_47166_Content_52 = {
    Text = "幽暗的石柱如同被斬首的衛兵，莊嚴地持戟分列兩側。"
  },
  AvgDialog_47166_Content_53 = {
    Text = "巨大石塊做成的牆面與道路碎裂、腐壞，骯髒的藻類爬滿它們的殘軀，訴說著過往的榮光與這萬年間孤寂的命運。"
  },
  AvgDialog_47166_Content_54 = {
    Text = "一行人踩踏著海水與碎石緩緩前行，登上斷裂的台階。"
  },
  AvgDialog_47166_Content_55 = {
    Text = "這個就是……利莫里亞的王座？"
  },
  AvgDialog_47166_Content_56 = {
    Text = "一個殘破的石質王座矗立在道路盡頭，王座之上，一個早已枯死的骸骨撐著自己的下頜，疲憊地望著舊日的殘夢。"
  },
  AvgDialog_47166_Content_57 = {
    Text = "是您，吾主……是您的聖髑！我找到您了！"
  },
  AvgDialog_47166_Content_58 = {
    Text = "上萬年，上萬年了，我終於又見到了您……"
  },
  AvgDialog_47166_Content_59 = {
    Text = "彌利亞姆虔誠地俯下身，向骸骨跪拜。"
  },
  AvgDialog_47166_Content_6 = {
    Text = "那個雕像，就是在這裡找到的。"
  },
  AvgDialog_47166_Content_60 = {
    Text = "她站起身，雙手探入骸骨污穢的軀體。她將手拿出來的時候，微弱的銀光出現在黯淡的遺跡之中。"
  },
  AvgDialog_47166_Content_61 = {
    Text = "一個銀色的光球躺在彌利亞姆手中，流光在它表面浮動，在海底折射出幻夢般的光彩。彌利亞姆湊近它，傾聽著它的呼吸。"
  },
  AvgDialog_47166_Content_62 = {
    Text = "這就是你說的……銀色物質？"
  },
  AvgDialog_47166_Content_63 = {
    Text = "和塔利斯所說的不一樣……但這一定是我想要找的東西！"
  },
  AvgDialog_47166_Content_64 = {
    Text = "你確定嗎……這玩意看著可不像什麼好東西……"
  },
  AvgDialog_47166_Content_65 = {
    Text = "再對王出言不遜，我將賜你最痛苦的死亡。"
  },
  AvgDialog_47166_Content_66 = {
    Text = "開個玩笑，何必這麼嚴肅……"
  },
  AvgDialog_47166_Content_67 = {
    Text = "你說塔利斯描述的東西跟它不一樣，那他的方法大概也用不了。接下來呢，你打算怎麼辦？"
  },
  AvgDialog_47166_Content_68 = {
    Text = "我在它上面聽到了心跳……這是王的心跳……"
  },
  AvgDialog_47166_Content_69 = {
    Text = "它的生命在消散，我感覺到了……為它供給生命，便能讓王重生！一定是這樣，一定是這樣！"
  },
  AvgDialog_47166_Content_7 = {
    Text = "還有其他東西嗎？"
  },
  AvgDialog_47166_Content_71 = {
    Text = "彌利亞姆！你要做什麼？"
  },
  AvgDialog_47166_Content_72 = {
    Text = "用自己的生命為王供養，孕育王的重生……這是多麼至高無上的榮耀……這就是我的使命！"
  },
  AvgDialog_47166_Content_73 = {
    Text = "為我祝福吧，黛博拉……"
  },
  AvgDialog_47166_Content_75 = {
    Text = "祭祀匕首插入彌利亞姆的胸膛。匕首轉動，剜出一個血淋淋的空洞。"
  },
  AvgDialog_47166_Content_76 = {
    Text = "無數的鮮血噴濺，混入海水，縈繞在破敗的王座周圍。枯骨沐浴著熱血，冷漠地望著眼前的這一幕。"
  },
  AvgDialog_47166_Content_77 = {
    Text = "彌利亞姆似乎一點也不覺得疼痛，她的笑容變得愈發狂熱。"
  },
  AvgDialog_47166_Content_78 = {
    Text = "她捧著那團銀色的融動著的光球，將它塞入自己胸膛的空洞之中。"
  },
  AvgDialog_47166_Content_8 = {
    Text = "零零散散有一些，大部分剛才都給你看過了。"
  },
  AvgDialog_47166_Content_80 = {
    Text = "進入彌利亞姆體內的一瞬間，光球迸發出強烈的光亮，瘋狂地蠕動。它在抗拒。"
  },
  AvgDialog_47166_Content_81 = {
    Text = "彌利亞姆的生命在向它流動，被它吸食，然後被它唾棄。"
  },
  AvgDialog_47166_Content_82 = {
    Text = "烈焰在炙烤著自己的每一寸肌膚，利刃在剝削著自己的每一塊血肉。無盡的痛苦襲向彌利亞姆，她拼命支撐著自己扭曲的笑容。"
  },
  AvgDialog_47166_Content_83 = {
    Text = "吾主……請……請接納……我……"
  },
  AvgDialog_47166_Content_85 = {
    Text = "彌利亞姆！"
  },
  AvgDialog_47166_Content_86 = {
    Text = "彌利亞姆再也無法支撐，暈死過去。"
  },
  AvgDialog_47166_Content_87 = {
    Text = "把那個不祥的玩意從她體內取出來，把她送到船上。"
  },
  AvgDialog_47166_Content_88 = {
    Text = "可彌利亞姆說……"
  },
  AvgDialog_47166_Content_89 = {
    Text = "想讓她活，就趕緊照做。"
  },
  AvgDialog_47166_Content_9 = {
    Text = "我搜遍了整座島，沒有找到什麼遺跡，只帶走了這些小玩意。"
  },
  AvgDialog_47166_Content_91 = {
    Text = "霧氣與風浪都已消散，島嶼在遠處縮成了一個孤獨的墨點。"
  },
  AvgDialog_47166_Content_92 = {
    Text = "戈利亞靠在船舷上，享受著船隻平靜的搖晃。"
  },
  AvgDialog_47166_Content_93 = {
    Text = "戈利亞大人，看來您的心情不錯。這個太陽，也讓您想起了非利士故鄉的海岸了吧？"
  },
  AvgDialog_47166_Content_94 = {
    Text = "故鄉的海岸？哈。我只是在想，要是我現在殺了彌利亞姆，就可以想去哪就去哪了。"
  },
  AvgDialog_47166_Content_95 = {
    Text = "啊？大人，這……不太好吧……"
  },
  AvgDialog_47166_Content_96 = {
    Text = "彌利亞姆的力量遠比我強大。她現在身受重傷，錯過了今天，恐怕很難再有什麼機會了。"
  },
  AvgDialog_47166_Content_97 = {
    Text = "您不會做這樣的事情的。"
  },
  AvgDialog_47166_Content_98 = {
    Text = "怎麼，我在你心裡是個什麼軟心腸的東西嗎？"
  },
  AvgDialog_47166_Content_99 = {
    Text = "那倒也不是……只是，要是您真的想殺了她，早就已經動手了，不會跟我在這裡閒聊的。"
  },
  AvgDialog_47167_Content_1 = {Text = "霧中人"},
  AvgDialog_47167_Content_10 = {
    Text = "廢物。巨人看著身邊將死的追隨者，咧開一個惡劣的笑容，閉上了眼。"
  },
  AvgDialog_47167_Content_100 = {
    Text = "你已經有控制我的手段了，我的效命，對你來說應該更加的穩固才對。"
  },
  AvgDialog_47167_Content_101 = {
    Text = "我們的合作依然有效。沒有比我更合適的合作對象了，收下我的效命，讓我們的合作繼續下去。"
  },
  AvgDialog_47167_Content_102 = {
    Text = "如你所知，我並不是一個忠誠的人，但你需要的也並不是我的忠誠，而是我的能力，不是嗎？"
  },
  AvgDialog_47167_Content_103 = {
    Text = "彌利亞姆有些吃驚地望著戈利亞，片刻後，她笑了笑。"
  },
  AvgDialog_47167_Content_104 = {
    Text = "你的伎倆和卑劣讓我感到驚訝……你說得對，戈利亞，你這樣的人，能做到許多我做不到的事。"
  },
  AvgDialog_47167_Content_105 = {
    Text = "那我們，合作繼續？"
  },
  AvgDialog_47167_Content_106 = {
    Text = "戈利亞笑著伸出手，彌利亞姆沒有理會，轉身向船篷走去。"
  },
  AvgDialog_47167_Content_107 = {
    Text = "以後，稱我為主祭。"
  },
  AvgDialog_47167_Content_108 = {
    Text = "戈利亞收回手，摸了摸脖子上的印記。他微笑著眺望大海，新生的尖牙，在陽光下閃耀出銳利的光。"
  },
  AvgDialog_47167_Content_11 = {
    Text = "為我們的光，我們的希望嘆息。"
  },
  AvgDialog_47167_Content_12 = {
    Text = "因被放逐海洋的命運，我們哭號、哀嘆、流盡眼淚……"
  },
  AvgDialog_47167_Content_13 = {
    Text = "是臨死前的幻覺吧，巨人這樣想著。"
  },
  AvgDialog_47167_Content_14 = {
    Text = "古老詭譎的歌謠傳進他的耳朵。黏稠的霧氣中，女人的身影出現在他模糊的視線裡。"
  },
  AvgDialog_47167_Content_15 = {
    Text = "啊，彌利亞姆，就是他，那個非利士巨人！海岸上有好多關於他的傳說……"
  },
  AvgDialog_47167_Content_16 = {
    Text = "不過他好像要死了？"
  },
  AvgDialog_47167_Content_17 = {
    Text = "他不會死。"
  },
  AvgDialog_47167_Content_18 = {
    Text = "黑蛇纏繞的脖頸處傳來柔軟冰涼的觸感，巨人已經渾濁發黑的雙眼，變得逐漸清晰起來。"
  },
  AvgDialog_47167_Content_19 = {
    Text = "女巫、是那個女巫！"
  },
  AvgDialog_47167_Content_20 = {
    Text = "發生在奧恩家族領地的事情傳遍整片海域，她從傳說的迷霧中走來，站在凡人面前。"
  },
  AvgDialog_47167_Content_21 = {
    Text = "非利士的鬣狗們反應了過來。他們開始逃命，或者撲向這只小船，進行最後的殊死搏鬥。"
  },
  AvgDialog_47167_Content_22 = {
    Text = "彌利亞姆望著呆愣的巨人，微笑著，伸手指向遠方。她拍了拍黛博拉，調轉船頭。"
  },
  AvgDialog_47167_Content_23 = {
    Text = "對於鬣狗的奔跑與掙扎，她沒有絲毫興趣。"
  },
  AvgDialog_47167_Content_24 = {
    Text = "黑蛇游走，捕獵，撕咬，吞食。海面的濃霧中，殘破的屍身越來越多地浮現。"
  },
  AvgDialog_47167_Content_25 = {
    Text = "寂靜的屠殺很快結束，留下被鮮血染紅的海域，和巨人茫然出神的臉。"
  },
  AvgDialog_47167_Content_27 = {
    Text = "彌利亞姆，既然都找到他了，為什麼要走呢？"
  },
  AvgDialog_47167_Content_28 = {
    Text = "尋找吾主，是一件神聖的事情。祂不會希望我在那種骯髒的地方談論這種事的。"
  },
  AvgDialog_47167_Content_29 = {
    Text = "可是你什麼都沒跟那個大塊頭說哎……他會過來找你嗎？"
  },
  AvgDialog_47167_Content_3 = {
    Text = "巨人悶哼一聲，拔出了肩膀上的利箭。"
  },
  AvgDialog_47167_Content_30 = {
    Text = "二位，請等一等！"
  },
  AvgDialog_47167_Content_31 = {
    Text = "聲音穿透濃霧傳來。黛博拉向彌利亞姆吐了吐舌頭，緩緩將船停下。"
  },
  AvgDialog_47167_Content_32 = {
    Text = "很快，一只殘破的木舟停在了她們的船隻前。"
  },
  AvgDialog_47167_Content_33 = {
    Text = "你的毒素還沒有完全清理乾淨。以非利士人的行船速度，你可以休息一段時間再來找我。"
  },
  AvgDialog_47167_Content_34 = {
    Text = "跟一場至關重要的交易比起來，這點小傷算得了什麼。"
  },
  AvgDialog_47167_Content_35 = {
    Text = "我從未說過，要和你做什麼交易。"
  },
  AvgDialog_47167_Content_36 = {
    Text = "我不希望浪費您的時間，女巫大人。\n我知道利莫里亞的消息，我想，這也是您找到我的原因。"
  },
  AvgDialog_47167_Content_37 = {
    Text = "你知道我想要什麼？"
  },
  AvgDialog_47167_Content_38 = {
    Text = "您在奧恩莊園對非利士人做的事情，傳遍了整片海域。說實話，在這之前，我向來不相信這些傳說。"
  },
  AvgDialog_47167_Content_39 = {
    Text = "但如今，您主動找到了我。您這樣做，總歸是有原因的。"
  },
  AvgDialog_47167_Content_4 = {
    Text = "帶毒的鮮血從他肩膀上濺在甲板上，在陽光下呈現出骯髒的黑色。"
  },
  AvgDialog_47167_Content_40 = {
    Text = "傳聞中，您對那些黑色的雕像很感興趣。那些雕像是我找到的，我知道它們代表著什麼。"
  },
  AvgDialog_47167_Content_41 = {
    Text = "把你知道的事情告訴我。"
  },
  AvgDialog_47167_Content_42 = {
    Text = "在此之前，女巫大人，或許我們可以達成一個合作。"
  },
  AvgDialog_47167_Content_43 = {
    Text = "我見證了您的偉大力量……我想，您應該有辦法可以將這力量賜予我？"
  },
  AvgDialog_47167_Content_44 = {
    Text = "我有很多辦法可以讓你開口，非利士人。你覺得，你有提出交易的資格？"
  },
  AvgDialog_47167_Content_45 = {
    Text = "您誤會了，女巫大人……您救了我的性命，即使您不願意與我交易，那些資訊我也會毫無保留地獻給您。"
  },
  AvgDialog_47167_Content_46 = {
    Text = "我想要與您交易的，並非是這些資訊。"
  },
  AvgDialog_47167_Content_47 = {
    Text = "除了這些，你還能提供什麼？"
  },
  AvgDialog_47167_Content_48 = {
    Text = "我的忠誠。"
  },
  AvgDialog_47167_Content_49 = {
    Text = "我對你的忠誠不感興趣，歌利亞。"
  },
  AvgDialog_47167_Content_5 = {
    Text = "真有你的啊，以格倫……非利士人……現在也用上這些帶毒的玩意兒了……"
  },
  AvgDialog_47167_Content_50 = {
    Text = "是嗎？我聽說了您控制奧恩家族的事蹟，非常精彩……女巫大人，您在完成某個偉業，需要人手，對嗎？"
  },
  AvgDialog_47167_Content_51 = {
    Text = "您煞費苦心這麼久，有多少人能夠供您驅使呢？在您尋找自己想要之物的過程裡，又有誰能幫助您進行管轄呢？"
  },
  AvgDialog_47167_Content_52 = {
    Text = "恕我直言，女巫大人，您是一位強大的人，但人心、權力、和真正意義上的殺戮，並非您的專長。"
  },
  AvgDialog_47167_Content_53 = {
    Text = "我並不知道您的偉業究竟是什麼。但您一定會需要我的幫助。"
  },
  AvgDialog_47167_Content_54 = {
    Text = "請收下我的忠誠！這對您有益無害。"
  },
  AvgDialog_47167_Content_55 = {
    Text = "彌利亞姆沉默著望著他，片刻後，她點了點頭。"
  },
  AvgDialog_47167_Content_56 = {
    Text = "你的遊說打動了我，歌利亞。你證明了自己的能力。"
  },
  AvgDialog_47167_Content_57 = {
    Text = "現在，將你的刀投入深海。"
  },
  AvgDialog_47167_Content_59 = {
    Text = "戈利亞看了一眼那把跟隨他多年的巨刃，咬了咬牙，將它棄入海中。"
  },
  AvgDialog_47167_Content_6 = {
    Text = "巨人的視線變得模糊，大腦開始暈眩。他再也支撐不住，轟然倒下。"
  },
  AvgDialog_47167_Content_60 = {
    Text = "船身一陣搖晃，似乎有什麼東西正在攪動他們身下的大海。"
  },
  AvgDialog_47167_Content_61 = {
    Text = "彌利亞姆伸出手。那柄巨刃從海中重新躍起，散發出一陣之前未曾見過的幽暗光澤。"
  },
  AvgDialog_47167_Content_62 = {
    Text = "巨大的刀身落入彌利亞姆手中，如同一片羽毛般，被纖細的手輕輕握住。"
  },
  AvgDialog_47167_Content_63 = {
    Text = "你畏懼疼痛嗎？"
  },
  AvgDialog_47167_Content_65 = {
    Text = "戈利亞微笑著，半跪在彌利亞姆面前。"
  },
  AvgDialog_47167_Content_66 = {
    Text = "彌利亞姆拿著巨刃，放在戈利亞的脖頸上。"
  },
  AvgDialog_47167_Content_67 = {
    Text = "戈利亞大人！"
  },
  AvgDialog_47167_Content_69 = {
    Text = "巨刃砍入戈利亞的脖頸，輕易地將脖子斬成兩截，鮮血猛然噴濺而出。"
  },
  AvgDialog_47167_Content_7 = {
    Text = "戈利亞……巨人戈利亞，終於倒下了！"
  },
  AvgDialog_47167_Content_70 = {
    Text = "沒等旁邊的人反應過來，在戈利亞脖子的傷口處，一道紫黑的光芒微微閃爍。"
  },
  AvgDialog_47167_Content_71 = {
    Text = "它游走著，在黝黑的皮膚上劃出一道古老繁複的紋案。"
  },
  AvgDialog_47167_Content_73 = {
    Text = "劇烈的疼痛襲向戈利亞。那疼痛並非只來自傷口處，而是從全身各處洶湧而至。"
  },
  AvgDialog_47167_Content_74 = {
    Text = "汗珠從巨人額頭滾落，他咬著牙，全身顫抖著，與疼痛對抗。"
  },
  AvgDialog_47167_Content_75 = {
    Text = "在這劇烈的疼痛中，戈利亞的雙耳伸展出魚鰭狀的利刃，他的牙齒變得層層疊疊、尖銳無比，他的雙眼變得猩紅。"
  },
  AvgDialog_47167_Content_76 = {
    Text = "戈利亞大人……您……您現在……"
  },
  AvgDialog_47167_Content_77 = {
    Text = "這是一個無比漫長的過程，戈利亞感覺自己似乎經歷了一整年的劇痛。在這漫長的時光裡，他死於疼痛，又於疼痛中重生。"
  },
  AvgDialog_47167_Content_78 = {
    Text = "當戈利亞的意識重新變得清晰，他發現儀式早已經結束，他正俯身趴在船上，因疼痛而落下的汗水打濕了甲板。"
  },
  AvgDialog_47167_Content_79 = {
    Text = "他看著海面上映照的自己的面容。魚人的特徵在巨人的身軀上清晰地出現。一隻兇悍的鯊魚，展露在眾人面前。"
  },
  AvgDialog_47167_Content_8 = {
    Text = "他的首級歸我了，誰也別和我搶！！！"
  },
  AvgDialog_47167_Content_80 = {
    Text = "魚人化的效果，由你自己的潛力決定。你很有天賦，戈利亞。"
  },
  AvgDialog_47167_Content_82 = {
    Text = "從未擁有過的澎湃的力量，出現在戈利亞的體內。他輕鬆拿起手邊的巨刃，揮擊向水面。"
  },
  AvgDialog_47167_Content_83 = {Text = "轟——"},
  AvgDialog_47167_Content_84 = {
    Text = "平靜的海面掀起巨大的浪濤，兩片小船被波濤捲起，劇烈地搖晃著。"
  },
  AvgDialog_47167_Content_86 = {
    Text = "在著劇烈的搖晃中，戈利亞縱聲大笑著。他轉身望著彌利亞姆，眼中紅光猛然閃動。"
  },
  AvgDialog_47167_Content_87 = {
    Text = "多謝你，女巫大人，我將無比享受你賜予我的力量。"
  },
  AvgDialog_47167_Content_88 = {
    Text = "不過很抱歉，我沒有時間去向你獻上忠誠了，非利士的叛徒和敵人，還在等著我去宰了他們。"
  },
  AvgDialog_47167_Content_89 = {
    Text = "不要怪我，怪你自己沒有防備之心吧。以後，我會用敵人的鮮血為你祭奠的！"
  },
  AvgDialog_47167_Content_9 = {
    Text = "那些原本畏懼著戈利亞的非利士人，此刻向他瘋狂地圍了上來，像是一群見到了獅子屍體的英勇鬣狗。"
  },
  AvgDialog_47167_Content_90 = {
    Text = "戈利亞猛然將刀揮向彌利亞姆。而那把剛猛無儔的利刃在即將到達彌利亞姆身前時，忽然像是被定格了一般，失去了所有的力量。"
  },
  AvgDialog_47167_Content_92 = {
    Text = "戈利亞脖子上的傷痕紫光如同蛇信般閃爍。他痛苦地倒在地上，剛才所經歷的那種鑽心剜骨般的疼痛再次向他襲來，體內那股力量也在這一刻消失不見。"
  },
  AvgDialog_47167_Content_93 = {
    Text = "你……做了……什麼……"
  },
  AvgDialog_47167_Content_94 = {
    Text = "我是利莫里亞的主祭。我的確不擅長你說的那些事，但我清楚什麼是人性，非利士人。"
  },
  AvgDialog_47167_Content_95 = {
    Text = "疼痛與力量，是我一同賜予你的。無論你在哪裡，無論你強大到何種地步，只要我想，就能剝奪你的力量，重現你的疼痛。"
  },
  AvgDialog_47167_Content_96 = {
    Text = "你享受它，不是嗎？"
  },
  AvgDialog_47167_Content_97 = {
    Text = "厲害啊……女巫大人……"
  },
  AvgDialog_47167_Content_98 = {
    Text = "告訴我你知道的資訊，在這之後，我將賜予你一個輕鬆的死亡。"
  },
  AvgDialog_47167_Content_99 = {
    Text = "只是一個小小的插曲罷了……何必呢，女巫大人？"
  },
  AvgDialog_47168_Content_10 = {
    Text = "沒關係，沒關係，一次家庭聚會而已。身體沒問題吧？"
  },
  AvgDialog_47168_Content_100 = {
    Text = "哈哈哈，哪有那麼簡單？"
  },
  AvgDialog_47168_Content_101 = {
    Text = "咒語，軀體，還有……"
  },
  AvgDialog_47168_Content_102 = {
    Text = "他朦朧的醉眼猛地睜開，突然狠厲地念出一串無聲的咒語。"
  },
  AvgDialog_47168_Content_104 = {
    Text = "彌利亞姆跪倒在地。如針刺般的疼痛襲向她的精神，巨大的痛苦讓她難以站立。"
  },
  AvgDialog_47168_Content_105 = {
    Text = "@2，你以為我不知道你在想什麼？"
  },
  AvgDialog_47168_Content_106 = {
    Text = "叫我父親，幫我做事……你想要的是別的東西，對吧？"
  },
  AvgDialog_47168_Content_107 = {
    Text = "彌利亞姆，我不知道你的老家是什麼樣子，但很顯然，你們根本不懂什麼叫鬥爭。"
  },
  AvgDialog_47168_Content_108 = {
    Text = "如果我是一個蠢貨，在我六歲那年，就被人淹死在馬棚裡了，根本就走不到今天。"
  },
  AvgDialog_47168_Content_109 = {
    Text = "如同一條無形的繩子越拉越緊，彌利亞姆精神上的痛楚越發強烈。"
  },
  AvgDialog_47168_Content_11 = {
    Text = "已經好得差不多了。啊，大哥也到了？"
  },
  AvgDialog_47168_Content_110 = {
    Text = "你很強大，可那又怎麼樣？你只是一條獵犬，我讓你做什麼，你就得做什麼！"
  },
  AvgDialog_47168_Content_111 = {
    Text = "現在，我的目的已經完成，暫時用不上你了。要重新喚醒你會是一件很麻煩的事情，但是留著一個有自己想法的武器，會更麻煩。"
  },
  AvgDialog_47168_Content_112 = {
    Text = "所以，你就再死一次吧。放心，在我以後有需要時，我會再讓你看到太陽的……"
  },
  AvgDialog_47168_Content_113 = {
    Text = "塔利斯惡狠狠地盯著彌利亞姆，念出一串咒語。那條無形的繩索猛然收緊，成為一個絞索，套在了彌利亞姆的脖頸上。"
  },
  AvgDialog_47168_Content_114 = {
    Text = "塔利斯控制絞索的手猛然收緊……"
  },
  AvgDialog_47168_Content_115 = {
    Text = "？？！這是……怎麼回事？！"
  },
  AvgDialog_47168_Content_116 = {
    Text = "絞索仍然還在，但塔利斯感受不到自己對繩索的控制。無論他如何施咒，那條繩索都躺在那裡，一動不動。"
  },
  AvgDialog_47168_Content_117 = {Text = "嘩——"},
  AvgDialog_47168_Content_119 = {
    Text = "強烈的痛楚從塔利斯身體上傳來。他的胸膛上出現了一條又長又直的新鮮傷口，就像是被人用匕首虔誠地劃過一般。"
  },
  AvgDialog_47168_Content_12 = {
    Text = "塔利斯笑著向他行了個禮。"
  },
  AvgDialog_47168_Content_120 = {
    Text = "大廳內的賓客們迅速安靜下來，呆立在原地，衛兵們持槍圍了上來，但不敢再繼續向彌利亞姆靠近。"
  },
  AvgDialog_47168_Content_121 = {
    Text = "這……這是……？"
  },
  AvgDialog_47168_Content_122 = {
    Text = "在我的故鄉，它被稱為魚人儀式。"
  },
  AvgDialog_47168_Content_123 = {
    Text = "以前想要完成它，需要我用匕首將人的身體劃開，再將神血灌入對方的身體。但現在不需要了。"
  },
  AvgDialog_47168_Content_124 = {
    Text = "只需要飲下我的血，再加上我的力量進行催化，這個儀式就能完成。"
  },
  AvgDialog_47168_Content_126 = {
    Text = "酒裡，沒錯。在這場宴會裡，你們已經享用了它。"
  },
  AvgDialog_47168_Content_127 = {
    Text = "彌利亞姆站起身，清理掉身上的塵土。"
  },
  AvgDialog_47168_Content_129 = {
    Text = "這個世界的人變化了。信仰，親情，尊嚴……在你們眼裡，這一切一文不值。我很清楚，塔利斯。"
  },
  AvgDialog_47168_Content_13 = {
    Text = "我也剛剛才到，正準備為父親獻上禮物。"
  },
  AvgDialog_47168_Content_130 = {
    Text = "不過沒關係，我會帶來一個更好的世界。幫助你成為族長，就能讓奧恩家族成為我的助力，與我一同參與這神聖偉大的事業。"
  },
  AvgDialog_47168_Content_131 = {
    Text = "你們有著卑賤的心，本不配做神國的子民。但你們完成了讓我重生的使命，這，是我送還給你們的禮物。"
  },
  AvgDialog_47168_Content_132 = {
    Text = "你可以……可以和我交易……你不用這樣……"
  },
  AvgDialog_47168_Content_133 = {
    Text = "獵犬沒有交易的資格。所以，我只能成為你的主人。現在，我想我有這個資格了。"
  },
  AvgDialog_47168_Content_134 = {
    Text = "我要復活一個人。告訴我，我應該怎麼做。"
  },
  AvgDialog_47168_Content_135 = {
    Text = "說了，你能讓我活？"
  },
  AvgDialog_47168_Content_137 = {
    Text = "彌利亞姆沒有說話。塔利斯身上多出了一道極深的創口，鮮血從創口上汩汩流出。"
  },
  AvgDialog_47168_Content_138 = {
    Text = "我說！我說！"
  },
  AvgDialog_47168_Content_139 = {
    Text = "在我的書房……書桌裡面……有一本書，記載著我的所有研究結果。"
  },
  AvgDialog_47168_Content_14 = {
    Text = "好了，現在，你們兄弟幾人都到齊了。"
  },
  AvgDialog_47168_Content_140 = {
    Text = "關於魔像的內容，全都寫在裡面！"
  },
  AvgDialog_47168_Content_141 = {
    Text = "彌利亞姆看了他一眼，點了點頭。"
  },
  AvgDialog_47168_Content_142 = {
    Text = "我知道，你說的是真話。"
  },
  AvgDialog_47168_Content_143 = {
    Text = "你說得對，利莫里亞人沒有這樣的鬥爭。"
  },
  AvgDialog_47168_Content_144 = {
    Text = "不過，在人有了一定要完成的神聖使命以後，學會這些，便不是一件難事。"
  },
  AvgDialog_47168_Content_145 = {
    Text = "沒錯，沒錯……所以現在能放我走了嗎？"
  },
  AvgDialog_47168_Content_147 = {
    Text = "傷口在他身上繼續出現。鮮血與骨肉的線條交織，匯成一幅來自遠古文明的圖案。"
  },
  AvgDialog_47168_Content_148 = {
    Text = "與此同時，這些線條出現在大部分的賓客與衛兵身上。慘叫聲混同鮮血，噴濺在這個禮堂的每一個角落。"
  },
  AvgDialog_47168_Content_149 = {
    Text = "貴氣的禮堂，變成了鮮血與骨肉的地獄，滿是奧恩家族的哀嚎聲。"
  },
  AvgDialog_47168_Content_15 = {
    Text = "宴席正在準備。在此之前，有些重要的事情，我需要跟你們說。是關於我的後事。"
  },
  AvgDialog_47168_Content_150 = {
    Text = "塔利斯的面龐開始變形，魚鱗出現在他的皮膚上。那些慘烈的叫聲，逐漸變得喑啞、模糊不清，帶著深海的腥氣。"
  },
  AvgDialog_47168_Content_151 = {
    Text = "這片土地已經腐朽……我會讓他們看到，一個完美的神國。"
  },
  AvgDialog_47168_Content_152 = {
    Text = "王說的都是真的。神國就要降臨了……我已經知道要去哪裡找到祂。再等一等，很快，我們就能相聚了。"
  },
  AvgDialog_47168_Content_153 = {
    Text = "塔利斯的痛苦嘶鳴幾乎已經消失。在彌利亞姆強大力量的催化下，他的魚人化比曾經的利莫里亞人更加徹底。"
  },
  AvgDialog_47168_Content_154 = {
    Text = "她俯下身，撫摸著塔利斯變形的面部與佈滿鱗片的臂膀。在滿屋的血腥氣與哭嚎之中，她哭泣著，她微笑著。"
  },
  AvgDialog_47168_Content_155 = {
    Text = "好久不見，父親。"
  },
  AvgDialog_47168_Content_156 = {
    Text = "她向那隻痛苦抽搐著的魚人，致以最深情的問候。"
  },
  AvgDialog_47168_Content_16 = {
    Text = "父親！請別這樣說……"
  },
  AvgDialog_47168_Content_17 = {
    Text = "次子向前走了兩步，扶住老人的臂膀。老人輕輕拍了拍他的手背。"
  },
  AvgDialog_47168_Content_18 = {
    Text = "聽我說完。我的身體狀況，我自己很清楚。有些事情需要提前安排，奧恩家族，才能繁榮昌盛。"
  },
  AvgDialog_47168_Content_19 = {
    Text = "今天的晚宴結束，我就會將奧恩家族族長的位置傳給老二。我自己準備享受幾年清閒的生活。"
  },
  AvgDialog_47168_Content_2 = {
    Text = "向您致意，父親，奧恩家族永遠的領袖。"
  },
  AvgDialog_47168_Content_20 = {
    Text = "父親，可是……這太突然了，我還沒做好準備……"
  },
  AvgDialog_47168_Content_21 = {
    Text = "你是奧恩家族最優秀的繼承者，擁有最高貴的血統，最優良的教養。這本是我答應過你母親的事情，我一定會做到。"
  },
  AvgDialog_47168_Content_22 = {
    Text = "放心吧，我已經提前和家族的老朋友們打好了招呼，你的兄弟們，也會幫助你的。"
  },
  AvgDialog_47168_Content_23 = {
    Text = "他掃視著另外的幾個兒子。"
  },
  AvgDialog_47168_Content_24 = {
    Text = "你們的領地沒有什麼變化，我知道你們和老二的感情。所謂的族長只是一個名頭，大家都是一家人，要團結起來。"
  },
  AvgDialog_47168_Content_25 = {
    Text = "至於你……"
  },
  AvgDialog_47168_Content_26 = {
    Text = "他抬起頭，盯著塔利斯。"
  },
  AvgDialog_47168_Content_27 = {
    Text = "你的領地也不會變化。不過，你最近操心的事情實在是太多了。"
  },
  AvgDialog_47168_Content_28 = {
    Text = "你也上了年紀了，把你的軍隊指揮權交給你弟弟吧。我想，你也應該和我一樣，過點輕鬆的日子。"
  },
  AvgDialog_47168_Content_3 = {
    Text = "塔利斯屈身行禮，彌利亞姆站在他的身後，向主座上的老人微微頷首。"
  },
  AvgDialog_47168_Content_30 = {
    Text = "這是一個無法拒絕的命令，是嗎？"
  },
  AvgDialog_47168_Content_31 = {
    Text = "老人似乎對這個回答早有準備，向後靠在椅背上。"
  },
  AvgDialog_47168_Content_32 = {
    Text = "三天以前，我派出了軍隊向你的駐地進發。"
  },
  AvgDialog_47168_Content_33 = {
    Text = "你的野心我一直都清楚，但你終究是我的兒子，我會給你一個選擇的機會。"
  },
  AvgDialog_47168_Content_34 = {
    Text = "這是我為奧恩家族長遠考慮而做出的決定，希望你不要怪我。"
  },
  AvgDialog_47168_Content_35 = {
    Text = "……怎麼會呢，父親？我得感謝你。"
  },
  AvgDialog_47168_Content_36 = {
    Text = "塔利斯露出一個如釋重負的笑容。"
  },
  AvgDialog_47168_Content_37 = {
    Text = "來這裡的路上，一想到我將要做的事情，你不知道我有多麼煎熬……"
  },
  AvgDialog_47168_Content_38 = {
    Text = "感謝你，也感謝你們，我的兄弟們。現在，我沒有任何的負擔了。"
  },
  AvgDialog_47168_Content_39 = {
    Text = "老人敲了敲座椅，一大隊衛兵從幕布後跑出來，圍住了塔利斯與彌利亞姆。"
  },
  AvgDialog_47168_Content_4 = {
    Text = "老人不耐煩地揮了揮手。"
  },
  AvgDialog_47168_Content_40 = {
    Text = "在他身旁，次子瞪大了眼睛，聲音因緊張而變得有些嘶啞。"
  },
  AvgDialog_47168_Content_41 = {
    Text = "「父親？你這是……」"
  },
  AvgDialog_47168_Content_42 = {
    Text = "準備得真是周全啊，父親。讓我把親兵安頓在城外，又收繳了我的武器，讓我沒有一丁點的機會。"
  },
  AvgDialog_47168_Content_43 = {
    Text = "一個侍女生下的野種，不學無術，成天研究你那可笑的煉金術，還有你那可笑的野心……你對家人沒有任何感情，你想要的只是權力。"
  },
  AvgDialog_47168_Content_44 = {
    Text = "容忍你到現在，我也算是盡到了義務了。"
  },
  AvgDialog_47168_Content_45 = {
    Text = "士兵抽出了刀，向他們走來。塔利斯揮了揮手，彌利亞姆上前一步，黑色的霧氣，在她身後凝聚。"
  },
  AvgDialog_47168_Content_46 = {
    Text = "這個侍女？……"
  },
  AvgDialog_47168_Content_47 = {
    Text = "我同意，父親。你容忍我，容忍得有點太多了。"
  },
  AvgDialog_47168_Content_48 = {
    Text = "我可笑的煉金術的成果，好好欣賞吧，父親！"
  },
  AvgDialog_47168_Content_49 = {
    Text = "士兵察覺到了危險，猛然撲向二人。"
  },
  AvgDialog_47168_Content_5 = {
    Text = "「你這個當哥哥的，要給其他人做好表率。連個下人的禮儀都教不會嗎？」"
  },
  AvgDialog_47168_Content_51 = {
    Text = "一道蛇形的霧氣掠過他的面龐。下一刻，一個無頭的身子癱軟著倒在了地上。"
  },
  AvgDialog_47168_Content_52 = {
    Text = "這、這是……"
  },
  AvgDialog_47168_Content_53 = {
    Text = "其餘的士兵尚未反應過來，蛇形的黑霧便出現在每個人身邊。"
  },
  AvgDialog_47168_Content_54 = {
    Text = "黑霧纏繞著他們的身體，吐著蛇信，欣賞著他們。"
  },
  AvgDialog_47168_Content_56 = {
    Text = "空中留下幾縷黑煙。黑蛇們的嘴咬向牠們的獵物，房間內發出此起彼伏的慘叫聲。"
  },
  AvgDialog_47168_Content_57 = {
    Text = "很快，慘叫聲平息。奧恩家族的人們癱倒在地，坐在屍塊與血跡中間，喉嚨中除了低聲的慘叫以外發不出任何的聲音。"
  },
  AvgDialog_47168_Content_58 = {
    Text = "睜大你的眼睛，好好看看吧，我的煉金術的成果……我的“女兒”。"
  },
  AvgDialog_47168_Content_59 = {
    Text = "這幾個月，我用盡一切手段，隱瞞她的存在，就是為了這一天。"
  },
  AvgDialog_47168_Content_6 = {
    Text = "哎……算了，這些東西你可能也不懂。"
  },
  AvgDialog_47168_Content_60 = {
    Text = "這是我為你準備的厚禮，喜歡嗎，老東西？"
  },
  AvgDialog_47168_Content_61 = {
    Text = "塔利斯看著顫抖到無法言語的老人，露出快意的笑容。"
  },
  AvgDialog_47168_Content_62 = {
    Text = "你說的很對，只有提前安排，才能讓奧恩家族繁榮昌盛。"
  },
  AvgDialog_47168_Content_63 = {
    Text = "放心吧，父親。我可是一直深愛著奧恩家族，也愛著我的家人們……"
  },
  AvgDialog_47168_Content_64 = {
    Text = "把奧恩家族交給我，我會讓它，繁榮昌盛——"
  },
  AvgDialog_47168_Content_66 = {
    Text = "鋒利的刀子送進老人枯瘦的胸膛。他最後一眼看到的，是私生子臉上快意的笑容。"
  },
  AvgDialog_47168_Content_68 = {Text = "諸位。"},
  AvgDialog_47168_Content_7 = {
    Text = "……父親教訓的是。"
  },
  AvgDialog_47168_Content_70 = {
    Text = "銀製的湯匙敲擊在雕刻著繁複花紋的高腳玻璃杯上，發出清脆的聲響。"
  },
  AvgDialog_47168_Content_71 = {
    Text = "嘈雜的宴會大廳安靜下來。所有的人都望向主座。"
  },
  AvgDialog_47168_Content_72 = {
    Text = "座位上的血跡還沒有完全乾涸，塔利斯嗅著縈繞身旁的血腥氣，滿意地看著那些望向自己的目光。"
  },
  AvgDialog_47168_Content_73 = {
    Text = "我知道我知道，你們本來是要參加我父親的壽宴的。但我還是非常感謝大家的到來。"
  },
  AvgDialog_47168_Content_74 = {
    Text = "一場精彩的大戲，要是沒有觀眾，那就太無趣了。"
  },
  AvgDialog_47168_Content_75 = {
    Text = "非常感謝你們到這裡。如今，奧恩家族齊聚一堂，來見證我人生最重要的時刻。"
  },
  AvgDialog_47168_Content_76 = {
    Text = "尤其是我至親的兄弟們……"
  },
  AvgDialog_47168_Content_77 = {
    Text = "他站起身，舉起酒杯沖著角落晃了晃。"
  },
  AvgDialog_47168_Content_78 = {
    Text = "在一隊全副武裝的士兵的看守下，塔利斯的弟弟們坐在一張桌子上，恐懼著，沉默著。"
  },
  AvgDialog_47168_Content_79 = {
    Text = "在他們的幫助下，今天，你們將見證一個偉大的時刻。"
  },
  AvgDialog_47168_Content_8 = {
    Text = "門外響起一陣急促的腳步聲。一個長得和塔利斯有幾分相似的年輕人出現在大廳裡。"
  },
  AvgDialog_47168_Content_80 = {
    Text = "奧恩家族的歷史，在今天，將會徹底地改變。"
  },
  AvgDialog_47168_Content_81 = {
    Text = "他抽出佩刀，將它插在木桌上。"
  },
  AvgDialog_47168_Content_82 = {
    Text = "我，塔利斯，一個野種，一個私生子。從今天開始，我就是奧恩家族的獨裁者！"
  },
  AvgDialog_47168_Content_83 = {
    Text = "在座的各位，你們將是我塔利斯的新朋友。我們將組建一個強大的同盟，所有的敵人，都將被這個同盟碾碎！"
  },
  AvgDialog_47168_Content_84 = {
    Text = "賓客們或許曾是前任族長的朋友，但現在他們不再是了。他們的朋友，只有勝者。"
  },
  AvgDialog_47168_Content_85 = {
    Text = "在塔利斯慷慨的致辭中，賓客們舉起酒杯。"
  },
  AvgDialog_47168_Content_87 = {
    Text = "哈哈哈哈……敬你們，我的朋友們！敬我們偉大的同盟！敬奧恩家族光明的未來！"
  },
  AvgDialog_47168_Content_88 = {Text = "乾杯！"},
  AvgDialog_47168_Content_9 = {
    Text = "父親！抱歉，昨天生了病，剛剛才起來……"
  },
  AvgDialog_47168_Content_90 = {
    Text = "杯盞碰撞，人聲喧嘩。人們真情實意或逢場作戲地融入這場宴會，成為宴會的一部分。"
  },
  AvgDialog_47168_Content_91 = {
    Text = "彌利亞姆微笑著站在一旁，望著這些賓客，望著這新時代的法則。"
  },
  AvgDialog_47168_Content_92 = {
    Text = "塔利斯滿是醉意地坐回了主座。他與每個人碰杯，痛飲，享受著這人生中無比快意的一刻。"
  },
  AvgDialog_47168_Content_93 = {
    Text = "彌利亞姆，也敬你……你是我的驕傲！"
  },
  AvgDialog_47168_Content_94 = {
    Text = "你不知道，為了找到你，為了喚醒你，我做了多少的事情……"
  },
  AvgDialog_47168_Content_95 = {
    Text = "您之前提到的，那些“銀色物質”……"
  },
  AvgDialog_47168_Content_96 = {
    Text = "對，沒錯，就是那些銀色物質……黃金？寶石？哈哈哈，那些都是垃圾！"
  },
  AvgDialog_47168_Content_97 = {
    Text = "銀色物質是什麼，煉金術是什麼？是力量！在力量面前，財富算什麼？那不過只是力量的附贈品而已。"
  },
  AvgDialog_47168_Content_98 = {
    Text = "煉金術就是力量……彌利亞姆，你就是力量！來，乾杯！"
  },
  AvgDialog_47168_Content_99 = {
    Text = "想要復活一個人，只需要那些銀色的物質就行了嗎？"
  },
  AvgDialog_47169_Content_10 = {
    Text = "塔利斯將我重新復活，他一定知道些什麼。我會從他那裡找到復活您的辦法！"
  },
  AvgDialog_47169_Content_100 = {
    Text = "他會為他的猶豫付出代價的。"
  },
  AvgDialog_47169_Content_101 = {
    Text = "我們的糧食和水，只能維持兩三天……"
  },
  AvgDialog_47169_Content_102 = {
    Text = "雖然你個子很小，但等到實在活不下去的時候，我不會介意吃掉你的。"
  },
  AvgDialog_47169_Content_103 = {
    Text = "放心，為了感謝你的追隨，我會在你做夢的時候給你一個痛快。"
  },
  AvgDialog_47169_Content_104 = {
    Text = "戈利亞大人，我是您的追隨者，您可別嚇唬我……"
  },
  AvgDialog_47169_Content_105 = {
    Text = "不過大人，我們也不要那麼悲觀。以格倫讓我們去尋找那個殺死了族人的女巫，要是找到的話，說不定咱們還能活下去！"
  },
  AvgDialog_47169_Content_106 = {
    Text = "天真的小不點，以格倫可不是那麼仁慈的人。哪有什麼女巫，一句用來騙族人的鬼話罷了。"
  },
  AvgDialog_47169_Content_107 = {
    Text = "不過事已至此，我倒希望，這個傳說是真的……"
  },
  AvgDialog_47169_Content_108 = {
    Text = "巨人睜開眼，望著一望無際的海面。"
  },
  AvgDialog_47169_Content_109 = {
    Text = "如果有這樣一個人存在，或許，我真的能做到一些什麼。"
  },
  AvgDialog_47169_Content_11 = {
    Text = "“星辰正位之刻，利莫里亞將重現於世。”"
  },
  AvgDialog_47169_Content_12 = {
    Text = "我將帶回您，帶回利莫里亞……這是您告訴我的話。請您放心，我一定會完成我的使命！"
  },
  AvgDialog_47169_Content_13 = {
    Text = "她熱切地看著那個影子。"
  },
  AvgDialog_47169_Content_14 = {
    Text = "影子沒有說話。光線與觸鬚遮擋住他的臉，看不清他的表情。他低下頭，輕輕嘆了一口氣。"
  },
  AvgDialog_47169_Content_15 = {
    Text = "輕微的嘆氣聲如同驚雷在虛無的空間中炸響，光線開始四散逃逸。"
  },
  AvgDialog_47169_Content_18 = {
    Text = "光線晃得彌利亞姆的眼睛有些刺痛。"
  },
  AvgDialog_47169_Content_19 = {
    Text = "模糊到清晰的視線裡，雕像正安穩地擺放在窗台上。"
  },
  AvgDialog_47169_Content_2 = {
    Text = "絕對的寂靜。絕對的黑暗。"
  },
  AvgDialog_47169_Content_20 = {
    Text = "幽暗的石質材料被雕刻得十分細緻，王撐著下頜，斜坐在觸鬚蔓延的王座之上，靜靜地看著彌利亞姆。"
  },
  AvgDialog_47169_Content_21 = {
    Text = "陽光從他背後升起，映出一個模糊的輪廓。"
  },
  AvgDialog_47169_Content_22 = {
    Text = "彌利亞姆微笑著，向雕像虔誠地行了一禮。"
  },
  AvgDialog_47169_Content_23 = {
    Text = "請耐心等待吧，吾主。"
  },
  AvgDialog_47169_Content_24 = {
    Text = "彌利亞姆，我剛剛又聽到你說夢話了……沒事吧？"
  },
  AvgDialog_47169_Content_25 = {
    Text = "嗯……我沒事，黛博拉。"
  },
  AvgDialog_47169_Content_26 = {
    Text = "你怎麼老是說夢話，我都聽到好多次了。"
  },
  AvgDialog_47169_Content_27 = {
    Text = "侍女走上前來，關切地摸著她的額頭。彌利亞姆怔怔地看著她。"
  },
  AvgDialog_47169_Content_28 = {
    Text = "看我幹什麼？"
  },
  AvgDialog_47169_Content_29 = {
    Text = "我在想，黛博拉這個名字，真是好聽。"
  },
  AvgDialog_47169_Content_3 = {
    Text = "她置身於黑暗之中，不論從哪個方向望去，都只能望見永恆的虛無。"
  },
  AvgDialog_47169_Content_30 = {
    Text = "嘿嘿，是吧？奴隸的孩子，本來是不應該有名字的，不過以前老夫人喜歡我，給我取了這個名字。我也好喜歡！"
  },
  AvgDialog_47169_Content_31 = {
    Text = "記憶中那位朋友的臉和侍女的臉重合在一起。"
  },
  AvgDialog_47169_Content_32 = {
    Text = "祭司黛博拉曾幫助彌利亞姆成為主祭，侍女黛博拉，或許也將幫助彌利亞姆迎來神國。"
  },
  AvgDialog_47169_Content_33 = {
    Text = "多麼美妙的巧合。多麼神聖的命運。彌利亞姆看著她，不自覺地微笑著。"
  },
  AvgDialog_47169_Content_34 = {
    Text = "頭也不燙啊？怎麼感覺人變得呆呆的……"
  },
  AvgDialog_47169_Content_35 = {
    Text = "你要是出什麼問題，塔利斯老爺可饒不了我。"
  },
  AvgDialog_47169_Content_36 = {
    Text = "雖然名義上都是侍女，但你這侍女可比我們金貴多了！"
  },
  AvgDialog_47169_Content_37 = {
    Text = "我們沒什麼不一樣。這世上的所有人，都只是偉大存在的僕從。"
  },
  AvgDialog_47169_Content_38 = {
    Text = "哎，你又開始胡言亂語了……"
  },
  AvgDialog_47169_Content_39 = {
    Text = "黛博拉，這段時間，你和我聊了很多東西。這裡對我來說很陌生，我很感激有人能和我說話。"
  },
  AvgDialog_47169_Content_4 = {
    Text = "彌利亞姆感覺自己變成了一顆無光的星星，身上的能量，正在向某處匯集——這是一種讓她無比熟悉懷念的感覺。"
  },
  AvgDialog_47169_Content_42 = {
    Text = "走吧，塔利斯老爺應該已經在等著我們了。"
  },
  AvgDialog_47169_Content_44 = {
    Text = "我再跟你講個事，你可千萬別跟別人說啊！"
  },
  AvgDialog_47169_Content_45 = {
    Text = "放心，不會說的。"
  },
  AvgDialog_47169_Content_46 = {
    Text = "不過你不用在說每個秘密之前都加這句話的，這是你今天第五次講了。"
  },
  AvgDialog_47169_Content_47 = {
    Text = "何況，我覺得你剛才說你有喜歡的人這件事也算不得秘密，莊園裡的人應該都清楚是誰了。"
  },
  AvgDialog_47169_Content_48 = {
    Text = "怎麼可能！我裝得可好了……你別想騙我說出來！"
  },
  AvgDialog_47169_Content_49 = {
    Text = "哎呀，總之，這也是一件大事……我覺得塔利斯老爺在謀劃些什麼不得了的勾當。"
  },
  AvgDialog_47169_Content_5 = {
    Text = "她向那處望去。光線奔湧，在彼處匯成一個模糊的輪廓。"
  },
  AvgDialog_47169_Content_50 = {
    Text = "那位老爺是個很陰險的人，你可要小心一點！"
  },
  AvgDialog_47169_Content_51 = {Text = "是嗎？"},
  AvgDialog_47169_Content_52 = {
    Text = "彌利亞姆這樣說著，臉上的微笑卻絲毫未改，沒有任何驚訝的神情。"
  },
  AvgDialog_47169_Content_53 = {
    Text = "沒錯！你看他，最近讓你殺了不少的人。那些人都是奧恩家族的朋友，和塔利斯老爺的父親關係可好了……"
  },
  AvgDialog_47169_Content_54 = {
    Text = "每次他表面上都跟這些人相處得特別好，就像是很好的朋友，結果，一回頭就讓你把他們都殺掉了。"
  },
  AvgDialog_47169_Content_55 = {
    Text = "我知道你肯定是不願意做這種事的，可是沒辦法，你要聽塔利斯老爺的話嘛。"
  },
  AvgDialog_47169_Content_56 = {
    Text = "這個世界沒有天災，可這個世界的人心，比天災更可怕。"
  },
  AvgDialog_47169_Content_57 = {
    Text = "在這樣一個不完美的世界，殺戮總是會存在的。這是我們無法避免的東西。"
  },
  AvgDialog_47169_Content_58 = {
    Text = "哎，不明白……各個王國，各個家族，為什麼非要這樣老是爭來爭去的，明明還有那麼多人連生活都過不好。"
  },
  AvgDialog_47169_Content_59 = {
    Text = "我就希望以後能找到一個平靜的小地方，修一座房子，和諾德一起……"
  },
  AvgDialog_47169_Content_6 = {
    Text = "吾主……是您嗎？"
  },
  AvgDialog_47169_Content_61 = {
    Text = "意識到自己說漏嘴了，黛博拉的臉一下子紅了起來，緊緊捂住自己的嘴。"
  },
  AvgDialog_47169_Content_62 = {
    Text = "沒關係的，所有人都知道你喜歡那位年輕的馬車夫，塔利斯老爺都曾和我聊過。"
  },
  AvgDialog_47169_Content_63 = {
    Text = "她微笑著拍了拍黛博拉紅透的臉。"
  },
  AvgDialog_47169_Content_64 = {
    Text = "你放心，黛博拉，以後，會有一個完美的世界的。"
  },
  AvgDialog_47169_Content_65 = {
    Text = "真的嗎？你怎麼知道？"
  },
  AvgDialog_47169_Content_66 = {
    Text = "是真的，黛博拉。有一些事，我會慢慢告訴你。我會讓你成為這個新時代的第一個信奉者，成為神國的第一個子民。"
  },
  AvgDialog_47169_Content_67 = {
    Text = "我會讓一個完美的神國降臨……這是我的使命。"
  },
  AvgDialog_47169_Content_68 = {
    Text = "讓我在這裡等著，你帶著彌利亞姆在路上聊天，很開心，是嗎？"
  },
  AvgDialog_47169_Content_69 = {
    Text = "塔利斯陰沉的聲音打斷了兩人的談話。"
  },
  AvgDialog_47169_Content_7 = {
    Text = "光線匯集的人影斜坐於王座之上，一手撐著下頜，沉默地望著彌利亞姆。"
  },
  AvgDialog_47169_Content_70 = {
    Text = "我讓你去請彌利亞姆小姐，你就是這麼做事的？"
  },
  AvgDialog_47169_Content_71 = {
    Text = "直呼其名，並肩而行……士兵，給我把這個沒規矩的東西拖出去，處理了。"
  },
  AvgDialog_47169_Content_72 = {
    Text = "塔利斯老爺！請饒命……我……我只是……"
  },
  AvgDialog_47169_Content_73 = {
    Text = "是我的過錯，與黛博拉無關。還請“父親”寬恕她。"
  },
  AvgDialog_47169_Content_74 = {
    Text = "塔利斯瞥了一眼黛博拉，不耐煩地揮揮手。"
  },
  AvgDialog_47169_Content_75 = {
    Text = "既然彌利亞姆替你求情，這次就算了。再有下次，誰求情都沒用。滾吧。"
  },
  AvgDialog_47169_Content_76 = {
    Text = "我的女兒，來，來這邊……"
  },
  AvgDialog_47169_Content_77 = {
    Text = "黛博拉向他行了一禮，悄悄向彌利亞姆眨了眨眼，識趣地去到屋外，將門關上。"
  },
  AvgDialog_47169_Content_78 = {
    Text = "和彌利亞姆開始說話之後，塔利斯的聲音立刻變得熱情起來。"
  },
  AvgDialog_47169_Content_79 = {
    Text = "這幾個月你做得很好，非常好。"
  },
  AvgDialog_47169_Content_8 = {
    Text = "吾主……我是帶著對您的質疑死去的。這是我的罪孽……"
  },
  AvgDialog_47169_Content_80 = {
    Text = "以前鑽研煉金術，父親總說我不務正業。不過我這種侍女生下的孩子，不管做什麼，他也不會喜歡……侍女，哼。"
  },
  AvgDialog_47169_Content_81 = {
    Text = "他緊握著刀柄的手上青筋暴起，然後慢慢放鬆下來。"
  },
  AvgDialog_47169_Content_82 = {
    Text = "現在不一樣了，彌利亞姆。有了你，我就有了一支軍隊……不，比軍隊更加強大！"
  },
  AvgDialog_47169_Content_83 = {
    Text = "我們還能夠製造更多像我一樣的魔像。這種儀式需要消耗大量的精神力量，我可以幫助你。"
  },
  AvgDialog_47169_Content_84 = {
    Text = "我也一直在想這件事。不過，那些銀色物質可不是哪裡都能找到的。"
  },
  AvgDialog_47169_Content_85 = {
    Text = "“銀色物質”……"
  },
  AvgDialog_47169_Content_86 = {
    Text = "等以後有時間，我會跟你解釋的。現在這個事情先不用著急，有你在，就足夠做到我想做的事情了。"
  },
  AvgDialog_47169_Content_87 = {
    Text = "他深呼吸一口，握著手裡的刀，望向窗外的海洋。"
  },
  AvgDialog_47169_Content_88 = {
    Text = "再過不久，就是我父親七十歲的壽辰。我將帶著禮物，前往奧恩家族領地的主城，為他祝壽。"
  },
  AvgDialog_47169_Content_89 = {
    Text = "我們的準備工作，已經做得差不多了。到時候，我們會為他送上一個貴重的禮物。對吧，彌利亞姆？"
  },
  AvgDialog_47169_Content_9 = {
    Text = "我不奢求您的原諒……我會承擔我的罪孽！在那之前，我會完成我應該完成的事！"
  },
  AvgDialog_47169_Content_90 = {
    Text = "沒錯，“父親”。對整個奧恩家族，這都將是一個無比貴重的禮物。"
  },
  AvgDialog_47169_Content_92 = {
    Text = "數日後。"
  },
  AvgDialog_47169_Content_93 = {
    Text = "海面上，一艘木船正獨自飄蕩著。"
  },
  AvgDialog_47169_Content_94 = {
    Text = "戈利亞大人，族人們的船已經看不見了。"
  },
  AvgDialog_47169_Content_96 = {
    Text = "巨人扔下自己的刀，靠在桅杆上，閉目養神。"
  },
  AvgDialog_47169_Content_97 = {
    Text = "與敵人戰鬥時所受的傷，受傷後族人的算計與背叛……是自己大意了，怪不得別人。"
  },
  AvgDialog_47169_Content_98 = {
    Text = "可即便是他，也感到有些疲憊。"
  },
  AvgDialog_47169_Content_99 = {
    Text = "呵，以格倫這個懦夫。想殺了我，又怕影響到自己的名聲。用尋找女巫的名義將我趕出族群，真是麻煩的手段。"
  },
  AvgDialog_47170_Content_10 = {
    Text = "「醒來吧，回到家人的懷抱……」"
  },
  AvgDialog_47170_Content_100 = {
    Text = "很快，屋子裡的人再也聽不見任何非利士人的聲音。"
  },
  AvgDialog_47170_Content_101 = {
    Text = "彌利亞姆似乎看不見身旁發生的一切，她走向屋內那灘殘軀，虔誠地拿起了那個幽暗的雕像仔細檢查著。"
  },
  AvgDialog_47170_Content_102 = {
    Text = "「是利莫里亞的雕像……沒錯，是利莫里亞的雕像……」"
  },
  AvgDialog_47170_Content_103 = {
    Text = "「這就是魔像……這就是魔像的力量！！」"
  },
  AvgDialog_47170_Content_105 = {
    Text = "塔利斯站起身，臉上因為興奮而產生紅暈。他頌念出一道咒語，揮了揮手。"
  },
  AvgDialog_47170_Content_106 = {
    Text = "彌利亞姆感受到，從鏈接的另一頭傳來一股強大的力量。那力量在對她造成實質的傷害之前便倏然消失。"
  },
  AvgDialog_47170_Content_107 = {
    Text = "「魔像，我是你的鏈接者，是我給了你生命，從現在起，我便是你的父親。」"
  },
  AvgDialog_47170_Content_108 = {
    Text = "「你的能力很強大，但只要我想，隨時都能讓你重新變回一具屍體。」"
  },
  AvgDialog_47170_Content_109 = {
    Text = "「你的命運已經與我綁定在了一起，如果我死了，你也無法繼續存在。」"
  },
  AvgDialog_47170_Content_11 = {
    Text = "「父親！……」"
  },
  AvgDialog_47170_Content_110 = {
    Text = "「所以，不要有什麼不應該有的念頭。盡心輔佐我，成為奧恩家族的族長。」"
  },
  AvgDialog_47170_Content_111 = {
    Text = "「『父親』？『父親』……王說的沒有錯，我是那個承擔起命運的人！我知道該怎麼做了。我能做到很多很多的事……」"
  },
  AvgDialog_47170_Content_112 = {
    Text = "「請放心，父親。彌利亞姆一定，會和你一起迎回神國！」"
  },
  AvgDialog_47170_Content_113 = {
    Text = "彌利亞姆熱切地望著塔利斯。那是一種奇怪的眼神，明明在看著塔利斯，眼睛卻像是穿過了他，看著更遠處的某種他所不理解的東西。"
  },
  AvgDialog_47170_Content_114 = {
    Text = "它像太陽一樣熾熱，又像深海一樣幽暗冰冷。"
  },
  AvgDialog_47170_Content_115 = {
    Text = "「什麼神國，你是想說奧恩家族的土地？奇怪的習慣。不過不是什麼重要的事情，隨你便吧。」"
  },
  AvgDialog_47170_Content_116 = {
    Text = "「那些非利士人還在我的城堡與莊園裡享樂。彌利亞姆，殺了他們。讓我看看，你能做到些什麼。」"
  },
  AvgDialog_47170_Content_117 = {
    Text = "「如你所願，『父親』。」"
  },
  AvgDialog_47170_Content_118 = {
    Text = "彌利亞姆向塔利斯行了一禮，向外走去。"
  },
  AvgDialog_47170_Content_119 = {
    Text = "鮮血從幽暗的雕像上滴落。彌利亞姆身後，黑蛇如同羽翼般伸展，露出尖銳的牙。"
  },
  AvgDialog_47170_Content_12 = {
    Text = "她猛然睜開眼，躍出海面。"
  },
  AvgDialog_47170_Content_13 = {
    Text = "「醒了！塔利斯老爺，她醒了！」"
  },
  AvgDialog_47170_Content_14 = {
    Text = "「這裡是？……」"
  },
  AvgDialog_47170_Content_15 = {
    Text = "彌利亞姆身處一個寬闊豪華的大廳之中，跪在地上一圈儀式法陣中央。"
  },
  AvgDialog_47170_Content_16 = {
    Text = "周圍的人長著她從未見過的臉，穿著她從未見過的服飾，激動地大喊大叫。"
  },
  AvgDialog_47170_Content_17 = {
    Text = "一個中年男人站在法陣外，疲憊又興奮地望著她。"
  },
  AvgDialog_47170_Content_18 = {
    Text = "「成功了……我召喚出了魔像！我研究了一輩子……終於成功了！！」"
  },
  AvgDialog_47170_Content_19 = {
    Text = "「王……王去了哪？這裡不是利莫里亞？」"
  },
  AvgDialog_47170_Content_2 = {
    Text = "「以@3之名，呼喚你，我的孩子……」"
  },
  AvgDialog_47170_Content_20 = {
    Text = "那個看上去有些面熟的侍女疑惑地盯著她。"
  },
  AvgDialog_47170_Content_21 = {
    Text = "「利莫里亞？那是什麼？」"
  },
  AvgDialog_47170_Content_22 = {
    Text = "「大概是個什麼古老的文明之類的……誰知道呢？」"
  },
  AvgDialog_47170_Content_23 = {
    Text = "「看她的裝束，一定是個很重要的人……我的努力，一定沒有白費！」"
  },
  AvgDialog_47170_Content_24 = {
    Text = "他看著彌利亞姆的目光變得越來越熾熱。他走向彌利亞姆，伸出手放在她的額頭前。"
  },
  AvgDialog_47170_Content_25 = {
    Text = "「我是你的鏈接者……現在，睜開眼，好好看著這一切吧……」"
  },
  AvgDialog_47170_Content_26 = {
    Text = "現實短暫地消失了。無數的資訊灌入彌利亞姆的腦海，像是一片海洋將她淹沒。"
  },
  AvgDialog_47170_Content_27 = {
    Text = "她看見了故鄉的沉沒，看見了海面的變化，看見孤島與大陸相連。"
  },
  AvgDialog_47170_Content_28 = {
    Text = "她看見，新的文明誕生，新的國度建立，新的信徒頌念新的禱詞，新的王登上新的王座。"
  },
  AvgDialog_47170_Content_29 = {
    Text = "她看見，漫長的時光在無數個日夜交替中快速流逝，利莫里亞消失在這個世界的記憶裡，沒有留有任何的痕跡。"
  },
  AvgDialog_47170_Content_3 = {
    Text = "「讓家人的擁抱撫慰疲憊的身軀，讓故鄉的氣息治癒你漂泊的靈魂。」"
  },
  AvgDialog_47170_Content_30 = {
    Text = "「我沉睡了……上萬年？」"
  },
  AvgDialog_47170_Content_31 = {
    Text = "「沉睡？哈哈哈……不，不是的。你死了，死過一次。」"
  },
  AvgDialog_47170_Content_32 = {
    Text = "「是我，是我把你喚醒，讓你重新有了生命！」"
  },
  AvgDialog_47170_Content_33 = {
    Text = "「快，和我講講，你有什麼能力，能幫我做什麼？」"
  },
  AvgDialog_47170_Content_34 = {
    Text = "「利莫里亞……消失了，什麼也沒有留下……」"
  },
  AvgDialog_47170_Content_35 = {
    Text = "沒有理會塔利斯急切地詢問，彌利亞姆還沉浸在茫然的情緒之中。"
  },
  AvgDialog_47170_Content_36 = {
    Text = "世界的變化，故土的消逝，萬年的時光，這一切讓她剛剛甦醒的大腦還無法進行思考。"
  },
  AvgDialog_47170_Content_37 = {
    Text = "侍女拍了拍自己的額頭，嘆了口氣。"
  },
  AvgDialog_47170_Content_38 = {
    Text = "「完了，塔利斯老爺……她的腦袋好像不是很聰明的樣子？」"
  },
  AvgDialog_47170_Content_39 = {
    Text = "「不過沒關係，等我好好照顧她一段時間，她說不定就……」"
  },
  AvgDialog_47170_Content_4 = {
    Text = "「父親？……」"
  },
  AvgDialog_47170_Content_41 = {
    Text = "嘈雜聲從屋外遠遠傳來。"
  },
  AvgDialog_47170_Content_42 = {
    Text = "「什麼聲音？」"
  },
  AvgDialog_47170_Content_43 = {
    Text = "「非利士人……非利士人入侵！士兵都在防備喚醒儀式，海岸防線被突破！」"
  },
  AvgDialog_47170_Content_45 = {
    Text = "一個衛兵一邊奔跑一邊呼喊著。沒等他的話說完，一柄巨大的魚叉從遠處飛來，穿透他的心臟。"
  },
  AvgDialog_47170_Content_46 = {
    Text = "一群皮膚黝黑、全身不著鎧甲的異族戰士，嘴裡喊著怪異的戰吼，從四面圍困上來。"
  },
  AvgDialog_47170_Content_47 = {
    Text = "「快……魔像！快幫我殺了他們！」"
  },
  AvgDialog_47170_Content_49 = {
    Text = "彌利亞姆癱坐在地板上，茫然地低下頭，沒有回話。"
  },
  AvgDialog_47170_Content_5 = {
    Text = "意識和感知逐漸回到了彌利亞姆身上。半夢半醒之間，她感到自己正被溫暖的海水包裹。"
  },
  AvgDialog_47170_Content_50 = {
    Text = "「@2！沒想到喚醒了一個廢物……」"
  },
  AvgDialog_47170_Content_51 = {
    Text = "「奧恩家族的城堡裡面，原來是長這樣子。真是豪華。」"
  },
  AvgDialog_47170_Content_52 = {
    Text = "「你們這些野蠻人，這裡是奧恩家族的領地，要是不想被奧恩家族的軍隊血洗，就早點滾出去！」"
  },
  AvgDialog_47170_Content_55 = {
    Text = "魚叉刺穿他的肩膀，他慘叫一聲，痛苦地捂住傷口。"
  },
  AvgDialog_47170_Content_56 = {
    Text = "「再狗叫一聲，下一次，它刺穿的就是你的眼珠，然後是你的喉嚨。」"
  },
  AvgDialog_47170_Content_57 = {
    Text = "房間內的人都被控制，房間外的衛兵都死在了魚叉之下。非利士人在房間內踱著步，貪婪地看著這一切。"
  },
  AvgDialog_47170_Content_58 = {
    Text = "「戈利亞以前常常說，不要打奧恩家族城堡的主意，這是一件非常危險的事情。可現在怎麼樣？我們就站在奧恩家的城堡裡。」"
  },
  AvgDialog_47170_Content_59 = {
    Text = "「這裡的一切，馬上就是我們的了！」"
  },
  AvgDialog_47170_Content_6 = {
    Text = "聲音朦朦朧朧地響著，太陽的輪廓穿透海水，影影綽綽地在上方浮現。"
  },
  AvgDialog_47170_Content_60 = {
    Text = "在他身旁，另一個非利士戰士迫不及待地高舉起自己的魚叉。"
  },
  AvgDialog_47170_Content_61 = {
    Text = "「沒錯，戈利亞這個懦夫！我們就該聽以格倫的才對。他應該取代戈利亞，做我們的族長！」"
  },
  AvgDialog_47170_Content_62 = {
    Text = "「老大，這次你拿下奧恩家的城堡，回去以後，以格倫一定會賞識你的！」"
  },
  AvgDialog_47170_Content_63 = {
    Text = "「要不是我正在進行喚醒儀式，也不會被你們偷襲得逞……你們這群卑鄙的野蠻人！」"
  },
  AvgDialog_47170_Content_64 = {
    Text = "「魔像！是我救了你！要是我死了，你也活不了！快……快清醒一點，幫幫我！……」"
  },
  AvgDialog_47170_Content_65 = {
    Text = "「她？你把希望寄託於一個女人嗎？哈哈哈哈……」"
  },
  AvgDialog_47170_Content_66 = {
    Text = "非利士人的嘲笑在房間中迴盪。非利士隊長搖了搖頭，揪住塔利斯的頭髮，拿出手中的匕首。"
  },
  AvgDialog_47170_Content_67 = {
    Text = "他側身對著彌利亞姆。在他的腰間，一個小雕像晃盪著。她猛然瞪大了眼睛。"
  },
  AvgDialog_47170_Content_68 = {
    Text = "「那個雕像……是哪來的？」"
  },
  AvgDialog_47170_Content_69 = {
    Text = "「喲……原來你會說話啊，還以為是個傻子。」"
  },
  AvgDialog_47170_Content_7 = {
    Text = "這是一場無夢的長眠。彌利亞姆不知道自己睡了多久，或許一整天？或是一個星期？"
  },
  AvgDialog_47170_Content_70 = {
    Text = "「雕像，哪裡來的？」"
  },
  AvgDialog_47170_Content_71 = {
    Text = "非利士隊長放下刀。低頭看著腰間那個雕像。"
  },
  AvgDialog_47170_Content_72 = {
    Text = "雕像使用的是一種看上去非常古老黯淡的石質材料，刻畫著一個坐在王座上的身影。一些怪異的觸手胡亂伸開，擋住了他的臉。"
  },
  AvgDialog_47170_Content_73 = {
    Text = "「呵……這個？戈利亞找到的。因為我的英勇，賞給了我。」"
  },
  AvgDialog_47170_Content_74 = {
    Text = "「我為他出生入死，他就賞給我這種東西。不知道是哪個蠢貨文明留下來的，一個沒用的廢物。」"
  },
  AvgDialog_47170_Content_76 = {
    Text = "非利士隊長還在說著話，突然發現面前的女人站了起來。"
  },
  AvgDialog_47170_Content_77 = {
    Text = "他饒有興致地打量著她奇異的服飾，以及身上那些看上去詭異而昂貴的飾品。"
  },
  AvgDialog_47170_Content_78 = {
    Text = "「你剛才，說這個雕像，是什麼？」"
  },
  AvgDialog_47170_Content_79 = {
    Text = "「我說，沒用的廢物，跟你一樣。怎麼，你的耳朵和嘴巴一樣，都不太好使？」"
  },
  AvgDialog_47170_Content_8 = {
    Text = "意識逐漸地清晰起來，和她的身體整合在一起。隱約中，一群人從海面上向她伸出手。"
  },
  AvgDialog_47170_Content_80 = {
    Text = "「隊長，別跟她廢話，一刀……啊！！！！……」"
  },
  AvgDialog_47170_Content_81 = {
    Text = "黑色的霧氣，幾乎是在一瞬間出現的。"
  },
  AvgDialog_47170_Content_82 = {
    Text = "黑霧凝聚成數條巨蛇，飢餓地撲向那名非利士戰士。"
  },
  AvgDialog_47170_Content_83 = {
    Text = "他的刀離開了彌利亞姆的脖頸，拿刀的手被黑蛇一口咬掉，鮮血噴濺，打濕了彌利亞姆的衣服。"
  },
  AvgDialog_47170_Content_84 = {
    Text = "黑蛇湧向非利士人，在他來不及發出更多的慘叫時，便被吞噬殆盡。"
  },
  AvgDialog_47170_Content_85 = {
    Text = "地上只剩下幾塊殘軀，一灘血跡。"
  },
  AvgDialog_47170_Content_86 = {
    Text = "「這……這是……」"
  },
  AvgDialog_47170_Content_87 = {
    Text = "房間裡的所有人都被這突然的一幕驚住，開始懷疑自己的視覺。"
  },
  AvgDialog_47170_Content_88 = {
    Text = "彌利亞姆低頭審視著自己的雙手。一抹越來越燦爛的笑容，浮現在她的臉上。"
  },
  AvgDialog_47170_Content_89 = {
    Text = "她看向非利士隊長的方向，但並沒有看他，而是在凝視著他腰間那個雕像。\n淚水浸滿她的雙眼。"
  },
  AvgDialog_47170_Content_9 = {
    Text = "父親，母親，妹妹，老主祭，王，黛博拉……他們一起伸出手，向她發出了邀請。"
  },
  AvgDialog_47170_Content_90 = {
    Text = "「王，我又見到您了……原來，您說的都是真的……」"
  },
  AvgDialog_47170_Content_91 = {
    Text = "「我真的重生了！我擁有了比曾經更強大的力量！」"
  },
  AvgDialog_47170_Content_92 = {
    Text = "「吾主……我為我的懷疑向您致歉……您真的沒有騙我……」"
  },
  AvgDialog_47170_Content_94 = {
    Text = "這個可怖的女巫正沉浸在複雜的情緒裡。從小燒殺劫掠的生活讓非利士人對危險具有天生的直覺，他知道，這是他唯一的機會。"
  },
  AvgDialog_47170_Content_95 = {
    Text = "他怒吼著，拿著刀，用他最快的速度衝向彌利亞姆。"
  },
  AvgDialog_47170_Content_97 = {
    Text = "黑蛇以他無法理解的形式憑空出現，穿透他的身體。"
  },
  AvgDialog_47170_Content_98 = {
    Text = "屋內屋外，非利士人有的拿著武器衝上前來，有的四散逃跑，有的跪地求饒。"
  },
  AvgDialog_47170_Content_99 = {
    Text = "彌利亞姆不在意他們勇敢或卑劣的抉擇。黑蛇憑空出現又消失，玩弄、撕咬、獵殺著這些低賤的生命。"
  },
  AvgDialog_47171_Content_1 = {
    Text = "謊言的美德"
  },
  AvgDialog_47171_Content_10 = {
    Text = "看到黛博拉的神情，信徒們心領神會地點了點頭。"
  },
  AvgDialog_47171_Content_100 = {
    Text = "老師說的那些……那些都是假的，對嗎？"
  },
  AvgDialog_47171_Content_101 = {
    Text = "這些年，所有的天災都消失了，利莫里亞離神國已經越來越近……只差一步，我們只差一步……"
  },
  AvgDialog_47171_Content_102 = {
    Text = "您一定會帶來神國的，吾主！我是您忠實的僕從，我永遠會……"
  },
  AvgDialog_47171_Content_103 = {
    Text = "余尋找了許久……余的夢境中，已經沒有了神的身影。"
  },
  AvgDialog_47171_Content_104 = {
    Text = "圖魯將眼神從彌利亞姆臉上挪開。"
  },
  AvgDialog_47171_Content_105 = {
    Text = "我們的文明，終將覆滅，無可避免……這是祂告知余的最後一句話。"
  },
  AvgDialog_47171_Content_106 = {
    Text = "風調雨順，四海昇平，這是利莫里亞最後的余暉。"
  },
  AvgDialog_47171_Content_107 = {
    Text = "迎接這場浩劫，這是王與主祭，將要承擔的刑罰。"
  },
  AvgDialog_47171_Content_108 = {
    Text = "所以……所以您的意思是……利莫里亞人，他們的所有祈禱和期待，都是一場騙局……"
  },
  AvgDialog_47171_Content_109 = {
    Text = "所有的人，從出生到死亡，都生活在一場騙局裡，是嗎，吾主？"
  },
  AvgDialog_47171_Content_11 = {
    Text = "他們緊閉著嘴，跪倒在彌利亞姆身前。崇敬、期待的眼神，一動不動地盯著她。"
  },
  AvgDialog_47171_Content_110 = {
    Text = "你的老師，已經告知過你。"
  },
  AvgDialog_47171_Content_111 = {
    Text = "我想聽您親口說，吾主……"
  },
  AvgDialog_47171_Content_112 = {
    Text = "請親口告訴我，我們的祈禱毫無意義。這些先行者，犧牲了一切，智識、情感、尊嚴，擠在這個水池裡，等待的只是一個遙遠的謊言……"
  },
  AvgDialog_47171_Content_113 = {
    Text = "請親口告訴我，神國……永遠也不會降臨……"
  },
  AvgDialog_47171_Content_114 = {
    Text = "這是一場寂靜的坍塌。彌利亞姆沒有哭泣、沒有陷入癲狂。她看著圖魯，虛弱地問出了所有的話。"
  },
  AvgDialog_47171_Content_115 = {
    Text = "她的眼睛一眨不眨，就像是身邊的那些魚人，不再思考，不帶情緒，只是那樣靜靜地、認真地看著圖魯。"
  },
  AvgDialog_47171_Content_116 = {
    Text = "像是即將熄滅的焰火，期待著遙遠的黎明。"
  },
  AvgDialog_47171_Content_117 = {
    Text = "圖魯閉著眼，深深呼吸著。在這個瞬間，那些目光讓他想起了很多。"
  },
  AvgDialog_47171_Content_118 = {
    Text = "或許，他想起了那些世代生活在謊言裡的人們。"
  },
  AvgDialog_47171_Content_119 = {
    Text = "或許，他想起了那些獻出智識、情感與尊嚴的信徒，想起了那些被異化扭曲的靈魂。"
  },
  AvgDialog_47171_Content_12 = {
    Text = "吾主忠誠的信徒，吾主將永遠為你祝福。"
  },
  AvgDialog_47171_Content_120 = {
    Text = "或許，他只是想起了，在這場關於沉睡的騙局之前，他也曾像利莫里亞的子民們一樣，相信自己能為這片土地帶來新的黎明。"
  },
  AvgDialog_47171_Content_121 = {
    Text = "給子民以希冀，這是為王者的職責，是這場騙局唯一的意義。既然如此，就讓騙局繼續下去吧。"
  },
  AvgDialog_47171_Content_122 = {
    Text = "圖魯睜開了眼，來到彌利亞姆面前。"
  },
  AvgDialog_47171_Content_123 = {
    Text = "余已很久未曾見到神明……但我知道，祂仍然在那裡，在夢境的深處。"
  },
  AvgDialog_47171_Content_124 = {
    Text = "神國，依舊存在。"
  },
  AvgDialog_47171_Content_125 = {
    Text = "彌利亞姆猛然抬起頭。"
  },
  AvgDialog_47171_Content_126 = {
    Text = "可……可老師說……"
  },
  AvgDialog_47171_Content_127 = {
    Text = "直到利莫里亞覆滅，神國仍舊不會降臨。所有人，都將死於這場浩劫。"
  },
  AvgDialog_47171_Content_129 = {
    Text = "……但，群星曾昭示余，利莫里亞將會重生。"
  },
  AvgDialog_47171_Content_13 = {
    Text = "黑蛇在彌利亞姆身後舞動。她的手輕輕點在每一個信徒的額頭。"
  },
  AvgDialog_47171_Content_130 = {
    Text = "他沒有看彌利亞姆，轉身向王座走去。"
  },
  AvgDialog_47171_Content_131 = {
    Text = "星辰正位之刻，利莫里亞將重現於世。"
  },
  AvgDialog_47171_Content_132 = {
    Text = "拯救利莫里亞之人，並非余。拯救利莫里亞之人，是你。"
  },
  AvgDialog_47171_Content_134 = {
    Text = "彌利亞姆，利莫里亞的主祭。你將重生於世。你將帶回余，帶回利莫里亞。"
  },
  AvgDialog_47171_Content_135 = {
    Text = "屆時，余將讓神國，於利莫里亞永存。"
  },
  AvgDialog_47171_Content_136 = {
    Text = "圖魯坐到了王座之上。他撐著自己的下頜，疲憊地斜靠著。"
  },
  AvgDialog_47171_Content_137 = {
    Text = "他沒有去看彌利亞姆臉上震驚與掙扎的神情。他知道，彌利亞姆並未完全相信這句話。沒有任何人能夠真的相信這句話。"
  },
  AvgDialog_47171_Content_138 = {
    Text = "謊言與真相，哪個更加殘忍？他思考了許久，仍然得不到答案。"
  },
  AvgDialog_47171_Content_139 = {
    Text = "如果自己的選擇是錯誤的，那就以錯誤作為結束吧。"
  },
  AvgDialog_47171_Content_14 = {
    Text = "讚頌吾主……讚頌主祭大人！"
  },
  AvgDialog_47171_Content_140 = {
    Text = "可……吾主，我……我應該怎麼做？"
  },
  AvgDialog_47171_Content_141 = {
    Text = "等待。在那以前，和利莫里亞，一同走向終點。"
  },
  AvgDialog_47171_Content_142 = {
    Text = "利莫里亞，還有……"
  },
  AvgDialog_47171_Content_143 = {
    Text = "三日。三日之後，利莫里亞，將會迎來終結。"
  },
  AvgDialog_47171_Content_144 = {
    Text = "您打算怎麼做……吾主？"
  },
  AvgDialog_47171_Content_145 = {
    Text = "一場盛大的祭祀，讓信徒們繼續祈禱……呼喚余的名字，余將讓利莫里亞的所有人，陷入沉睡。"
  },
  AvgDialog_47171_Content_146 = {
    Text = "余會給他們，最美好的夢境。"
  },
  AvgDialog_47171_Content_147 = {
    Text = "老主祭說，他不願意入睡，他要親眼看著利莫里亞沉入深海。"
  },
  AvgDialog_47171_Content_15 = {
    Text = "在幾個侍衛的督促下，受到了主祭祝福的信徒們無比欣喜地離開了。"
  },
  AvgDialog_47171_Content_150 = {
    Text = "……我願意清醒地迎接終結，吾主。"
  },
  AvgDialog_47171_Content_151 = {
    Text = "彌利亞姆離開了。圖魯疲憊地靠在王座上，看著空曠的房間，看著那些雜亂的魚人，看著彌利亞姆彷徨的背影。"
  },
  AvgDialog_47171_Content_152 = {
    Text = "利莫里亞的王與主祭的談話結束了。\n在未來上萬年的漫長日夜裡，這將是他們唯一的一次會面。"
  },
  AvgDialog_47171_Content_16 = {
    Text = "看著他們的背影，黛博拉愉悅地嘆了口氣。"
  },
  AvgDialog_47171_Content_17 = {
    Text = "自從你當上主祭以後，利莫里亞已經很久沒有出現過天災了。"
  },
  AvgDialog_47171_Content_18 = {
    Text = "你把這個地方治理得很好，你看這些信徒，可敬仰你了！"
  },
  AvgDialog_47171_Content_19 = {
    Text = "我只是吾主的傳達者。利莫里亞人應該敬仰的，唯有吾主。"
  },
  AvgDialog_47171_Content_2 = {
    Text = "數年後。"
  },
  AvgDialog_47171_Content_20 = {
    Text = "在吾主即位以前，我從未見過這樣的利莫里亞。我從未想像過，真的會有這樣的利莫里亞……"
  },
  AvgDialog_47171_Content_21 = {
    Text = "彌利亞姆和黛博拉一起站在海岸邊的礁石上，眺望生機勃勃的田野、愈發壯麗的城市，眺望那座古老宏偉的、她們熟悉無比的神殿。"
  },
  AvgDialog_47171_Content_22 = {
    Text = "她的聲音柔和平靜，但她的眼睛，閃爍著遠比信徒更加狂熱的色彩。"
  },
  AvgDialog_47171_Content_23 = {
    Text = "為我們的王禱告吧，黛博拉……我們離神國，越來越近了。"
  },
  AvgDialog_47171_Content_25 = {
    Text = "“在遙遠的黯淡深淵，古老的偉大靈魂沉眠……”"
  },
  AvgDialog_47171_Content_26 = {
    Text = "“……祂的意志如星辰之網交織，祂在永恆的虛無中候汝入夢……”"
  },
  AvgDialog_47171_Content_27 = {
    Text = "離雕像最近的位置，彌利亞姆獨自一人虔誠地跪拜。禱文順暢地從她口中響起，如同清泉從山澗湧出。"
  },
  AvgDialog_47171_Content_28 = {
    Text = "泉水在這個房間中旋轉、流淌，成為一道黑幕，將她淹沒。"
  },
  AvgDialog_47171_Content_29 = {
    Text = "精神維度永恆的虛無降臨在她的身邊。她沒有任何不適，只覺得無比溫暖。"
  },
  AvgDialog_47171_Content_3 = {
    Text = "剛剛下過一場細雨，天空很快變得晴朗起來。陽光溫柔地灑下，照在海岸邊幾個正在嬉戲的利莫里亞小孩身上。"
  },
  AvgDialog_47171_Content_30 = {
    Text = "星星點點的光亮在黑暗中亮起，若隱若現的絲線從光點中抽離。"
  },
  AvgDialog_47171_Content_31 = {
    Text = "光線匯集之處，一個巨大的明亮輪廓像是夜空中的月亮，在這虛無的空間中照出一片亙古的白夜。"
  },
  AvgDialog_47171_Content_32 = {
    Text = "吾主，利莫里亞沉眠的王……請原諒我，闖入您偉大的夢境。"
  },
  AvgDialog_47171_Content_33 = {
    Text = "您的神諭拯救了子民，一切天災都為您退避。我替利莫里亞的子民們，上達對您的崇敬……"
  },
  AvgDialog_47171_Content_34 = {
    Text = "您是神明的代行者，利莫里亞的救世主。我們願獻上一切，幫助您得到神諭，迎來神國。"
  },
  AvgDialog_47171_Content_35 = {
    Text = "請給我指引。請回應您最忠實的信徒……"
  },
  AvgDialog_47171_Content_36 = {
    Text = "她的意識飄向前方，來到那座由星光匯成的塑像面前。她伸出手，虔誠地觸碰那些光束……"
  },
  AvgDialog_47171_Content_37 = {
    Text = "轟！——"
  },
  AvgDialog_47171_Content_38 = {
    Text = "在她尚未觸碰到光束時，雕塑便轟然碎裂開。那些光束碰撞回轉、四散飛濺。"
  },
  AvgDialog_47171_Content_39 = {
    Text = "彌利亞姆被一陣強大的氣流向後推去，摔倒在地。"
  },
  AvgDialog_47171_Content_4 = {
    Text = "幾個城鎮的居民，坐在岸邊的石階上，吟唱著一首古老歡快的頌歌。"
  },
  AvgDialog_47171_Content_40 = {
    Text = "黑暗消失不見。彌利亞姆茫然地站起身。煙塵之中，一塊巨石從不知何處落下，穿透神殿的牆壁，重重砸在王的雕像上。"
  },
  AvgDialog_47171_Content_41 = {
    Text = "不！吾主！這、這是……"
  },
  AvgDialog_47171_Content_42 = {
    Text = "觸鬚與頭顱碎裂一地，只剩下半個身子仍端坐王座之上。外面的雨點透過牆壁上的空洞飄落進來，落在這滿地廢墟上。"
  },
  AvgDialog_47171_Content_43 = {
    Text = "彌利亞姆驚慌失措，跪在殘存的雕像前。"
  },
  AvgDialog_47171_Content_44 = {
    Text = "是、是我做錯了什麼嗎？請您告訴我……"
  },
  AvgDialog_47171_Content_46 = {
    Text = "老人的咳嗽聲出現在禱告室。幾年時間對於一位老人來說已足夠漫長。他吃力地揮手驅趕著那些嗆人的煙塵，緩慢向前挪動著。"
  },
  AvgDialog_47171_Content_47 = {
    Text = "老師？您怎麼一個人過來……"
  },
  AvgDialog_47171_Content_48 = {
    Text = "想一個人走走。很久沒有出來散過步了。"
  },
  AvgDialog_47171_Content_49 = {
    Text = "他走到已成殘墟的雕像面前，緩慢而恭敬地行禮。"
  },
  AvgDialog_47171_Content_5 = {
    Text = "歌聲伴隨著海鷗的鳴叫，傳入彌利亞姆耳中。"
  },
  AvgDialog_47171_Content_50 = {
    Text = "彌利亞姆看見了他的眼睛，那雙眼睛依然銳利，但裡面卻有一些她無法理解的情緒。"
  },
  AvgDialog_47171_Content_51 = {
    Text = "那是一種極其複雜的情緒，像是一個新生兒第一次面對這個陌生的世界，像是一個叛徒面對他深愛的故鄉。"
  },
  AvgDialog_47171_Content_52 = {
    Text = "老師……這是怎麼回事？這種不祥的徵兆……我們要不要進行一場盛大的祭祀儀式？"
  },
  AvgDialog_47171_Content_53 = {
    Text = "彌利亞姆，向王行禮，聆聽王的諭旨。"
  },
  AvgDialog_47171_Content_55 = {
    Text = "她恭敬地俯下身。向雕像行禮完畢，她熱切地注視著自己的老師，期待著。"
  },
  AvgDialog_47171_Content_56 = {
    Text = "“王的夢境中，神明已無蹤跡。利莫里亞，已被神明拋棄。”"
  },
  AvgDialog_47171_Content_57 = {
    Text = "“最後的時刻即將來臨。國度將沉入深海，利莫里亞的文明，將消逝於此。”"
  },
  AvgDialog_47171_Content_58 = {
    Text = "“神國，永不會降臨。”"
  },
  AvgDialog_47171_Content_59 = {
    Text = "老師……您、您在說什麼？這些話……這些褻瀆的話……"
  },
  AvgDialog_47171_Content_6 = {
    Text = "那個是……是主祭大人？"
  },
  AvgDialog_47171_Content_60 = {
    Text = "這是考驗，對嗎？請您放心，我無比信仰王！我會幫助王，我們會帶來神國……"
  },
  AvgDialog_47171_Content_61 = {
    Text = "這些話，是王親口所說。"
  },
  AvgDialog_47171_Content_62 = {
    Text = "在祂即位之前，祂便在夢中察覺，並告知於我……祂於夢中尋覓，直到現在，祂終於看清了未來。"
  },
  AvgDialog_47171_Content_63 = {
    Text = "王，拯救不了利莫里亞。"
  },
  AvgDialog_47171_Content_64 = {
    Text = "他轉過身，認真地望著彌利亞姆。"
  },
  AvgDialog_47171_Content_65 = {
    Text = "他看著光亮從她的眼中黯淡下去。他看著她愣在原地，那雙已習慣了行禮的雙手無處安放。"
  },
  AvgDialog_47171_Content_66 = {
    Text = "手足無措的樣子，和第一次知道這些的自己一模一樣。"
  },
  AvgDialog_47171_Content_67 = {
    Text = "彌利亞姆，你知道，利莫里亞的主祭，最重要的責任是什麼嗎？"
  },
  AvgDialog_47171_Content_68 = {
    Text = "聆聽王帶來的神諭，幫助王帶來神國，組織信徒進行儀式……這些都不是。"
  },
  AvgDialog_47171_Content_69 = {
    Text = "主祭最重要的職責，是欺騙。"
  },
  AvgDialog_47171_Content_70 = {
    Text = "欺騙利莫里亞的信徒，給他們一道光亮，讓他們能夠不那樣痛苦地活到利莫里亞覆滅的那一刻……"
  },
  AvgDialog_47171_Content_71 = {
    Text = "我們與王共享同一個秘密。我們是王的代言者，也是王的共犯。我們是利莫里亞地位崇高的罪人……"
  },
  AvgDialog_47171_Content_72 = {
    Text = "現在，你也是我們的一員了。"
  },
  AvgDialog_47171_Content_73 = {
    Text = "老師……您是說……呵，不……我……"
  },
  AvgDialog_47171_Content_74 = {
    Text = "彌利亞姆本能地笑了笑。"
  },
  AvgDialog_47171_Content_75 = {
    Text = "是個笑話嗎？或者是某種考驗吧？一定是這樣的。"
  },
  AvgDialog_47171_Content_76 = {
    Text = "是因為自己平時對王不夠虔誠，所以王故意這樣來考驗自己。"
  },
  AvgDialog_47171_Content_77 = {
    Text = "只要再做好一點就好，再虔誠一點就好……"
  },
  AvgDialog_47171_Content_78 = {
    Text = "彌利亞姆這樣想著。她的手用力地抓著雕像的底座，像是在抓著一根救命的稻草。"
  },
  AvgDialog_47171_Content_79 = {
    Text = "雕像鋒利的斷口割破她的手掌，鮮血滴落，她渾然不覺。"
  },
  AvgDialog_47171_Content_8 = {
    Text = "看到那個紫色的長袍，幾名利莫里亞的居民向彌利亞姆圍了過來。"
  },
  AvgDialog_47171_Content_80 = {
    Text = "老人緩緩搖著頭，眼神穿過碎裂的雕像與厚重的石板，望向遙遠的天穹。"
  },
  AvgDialog_47171_Content_81 = {
    Text = "群星告訴我，要將利莫里亞的命運交到你手上。這本是我該承擔的職責。可現在，這個重擔卻交給了你……"
  },
  AvgDialog_47171_Content_82 = {
    Text = "這對你不公平，孩子。很不公平。可是，群星、命運、神明……在祂們面前，公平二字，不值一提。"
  },
  AvgDialog_47171_Content_83 = {
    Text = "我無法帶給你公平，也無法再教給你更多的東西。"
  },
  AvgDialog_47171_Content_84 = {
    Text = "所以，你想做什麼，就去做吧。作為不公的受害者，作為利莫里亞的罪人，你有這個權利。"
  },
  AvgDialog_47171_Content_85 = {
    Text = "老主祭的眼神裡不再有銳利與威嚴，只剩下疲憊與茫然。他佝僂著向外走去。"
  },
  AvgDialog_47171_Content_86 = {
    Text = "王已經甦醒，祂正等著你。"
  },
  AvgDialog_47171_Content_87 = {
    Text = "我想，你會想要見一見祂。"
  },
  AvgDialog_47171_Content_89 = {
    Text = "他凝視著池水。"
  },
  AvgDialog_47171_Content_9 = {
    Text = "噓！不要讓其他人發現了！"
  },
  AvgDialog_47171_Content_90 = {
    Text = "一顆顆光滑的頭顱浮出水面，又落下去，此起彼伏，在池水中激起一道道骯髒的漣漪。"
  },
  AvgDialog_47171_Content_91 = {
    Text = "巨大的眼球往魚人頭顱的兩側生長，茫然地翻動，注視著他，嘴唇一開一合，吐露著意義不明的含糊音節，似乎在向他詢問什麼。"
  },
  AvgDialog_47171_Content_92 = {
    Text = "身後，石板門劃開。"
  },
  AvgDialog_47171_Content_93 = {
    Text = "讚頌吾主……利莫里亞，偉大的王……"
  },
  AvgDialog_47171_Content_94 = {
    Text = "與你們的每次會面，余都會聽到這句諷刺。"
  },
  AvgDialog_47171_Content_95 = {
    Text = "利莫里亞的巨大王冠反射著房間中不知何處出現的幽暗光澤，與少年的身體比例極不協調。"
  },
  AvgDialog_47171_Content_96 = {
    Text = "但王冠戴在他的頭上，卻沒有任何違和，似乎天生就是他身體的一部分。"
  },
  AvgDialog_47171_Content_97 = {
    Text = "惺忪的睡眼望向彌利亞姆，像是微微呼吸著的深海。稚氣未脫的臉上，見不到任何屬於少年的情緒。"
  },
  AvgDialog_47171_Content_98 = {
    Text = "余曾猜想，你會哭泣，會癲狂，或是試圖殺死余。"
  },
  AvgDialog_47171_Content_99 = {
    Text = "你很冷靜。余不清楚，這種冷靜是一種祝福，還是一種詛咒。"
  },
  AvgDialog_47172_Content_10 = {
    Text = "「你呀，還是先想想自己怎麼辦吧，這樣下去可不是辦法！」"
  },
  AvgDialog_47172_Content_100 = {
    Text = "「王保護了我們。我是個沒用的廢人，王還是保護了我……」"
  },
  AvgDialog_47172_Content_101 = {
    Text = "「你跟爸爸不一樣，彌利亞姆。你是能夠成為祭司的人，我們的驕傲。你是有意義的……」"
  },
  AvgDialog_47172_Content_102 = {
    Text = "「你能幫助王，拯救利莫里亞，迎接……神國……」"
  },
  AvgDialog_47172_Content_103 = {
    Text = "「父親……父親！！！」"
  },
  AvgDialog_47172_Content_104 = {
    Text = "創口中的鮮血幾乎已經流乾，雨水混著血絲，染紅了彌利亞姆的長裙。"
  },
  AvgDialog_47172_Content_105 = {
    Text = "伊諾斯的身軀依然佝僂著，替死去的女兒阻擋著那些無法阻擋的風雨。"
  },
  AvgDialog_47172_Content_106 = {
    Text = "他俯下身去，似乎只是抱著女兒，告別辛勞的白天，進入了夜晚甜美的酣睡。"
  },
  AvgDialog_47172_Content_107 = {
    Text = "「父親……我……對不起……我失敗了……」"
  },
  AvgDialog_47172_Content_108 = {
    Text = "懊悔和痛苦像是無盡的沉悶黑霧，堵在彌利亞姆心頭，讓她幾乎無法呼吸。她用力抱住父親和妹妹的身軀。"
  },
  AvgDialog_47172_Content_109 = {
    Text = "雨似乎變小了一些。她抬起頭，看到頭上遮蔽住天空的黑傘。"
  },
  AvgDialog_47172_Content_11 = {
    Text = "「今天幸好只是練習，沒有祭司在這裡盯著，要不然你又要挨罵了……」"
  },
  AvgDialog_47172_Content_110 = {
    Text = "彌利亞姆回過頭，看到身後的一排侍衛，以及站在中間的那位身穿神袍的老人。"
  },
  AvgDialog_47172_Content_111 = {
    Text = "似乎看到一根救命的浮木，她跪著向老人挪去。"
  },
  AvgDialog_47172_Content_112 = {
    Text = "「主祭大人！主祭大人，請救救我父親！」"
  },
  AvgDialog_47172_Content_113 = {
    Text = "「衛兵，帶她走。」"
  },
  AvgDialog_47172_Content_114 = {
    Text = "「我的罪我會承擔的！但我的父親，他一直是王最忠實的信徒……請救救他！」"
  },
  AvgDialog_47172_Content_115 = {
    Text = "「你沒有明白，彌利亞姆。」"
  },
  AvgDialog_47172_Content_116 = {
    Text = "「利莫里亞不在乎一個信徒的生死，也不在乎你的罪。」"
  },
  AvgDialog_47172_Content_117 = {
    Text = "「利莫里亞在乎的，只有夢境中的未來——那成為神國的未來。」"
  },
  AvgDialog_47172_Content_118 = {
    Text = "「你或許是未來的一部分，但……這取決於你自己的選擇。」"
  },
  AvgDialog_47172_Content_119 = {
    Text = "老主祭抬起頭，看了一眼天空。銳利的雙眼，似乎在與天空進行一段彌利亞姆無法理解的對話。"
  },
  AvgDialog_47172_Content_12 = {
    Text = "「挨罵都是小事了。我要是祭司，可能都會把我自己從祭司學徒裡除名了。」"
  },
  AvgDialog_47172_Content_120 = {
    Text = "「彌利亞姆，你信仰王嗎？」"
  },
  AvgDialog_47172_Content_121 = {
    Text = "「我信仰王，主祭大人，我信仰王！我是王的信徒……我什麼都願意做！」"
  },
  AvgDialog_47172_Content_122 = {
    Text = "「那麼，你會為了王，殺死你的父親嗎？」"
  },
  AvgDialog_47172_Content_123 = {
    Text = "「這……我……」"
  },
  AvgDialog_47172_Content_124 = {
    Text = "「彌利亞姆，你，信仰王嗎？！」"
  },
  AvgDialog_47172_Content_125 = {
    Text = "主祭突然逼近她，雙眼猛然盯著她，如同一柄鋒利的刀。"
  },
  AvgDialog_47172_Content_126 = {
    Text = "彌利亞姆愣在原地。主祭的質問讓她幾乎連為父親求救也忘了。"
  },
  AvgDialog_47172_Content_127 = {
    Text = "「有一個辦法，可以讓你父親活下去。」"
  },
  AvgDialog_47172_Content_129 = {
    Text = "「現在，回答我。什麼是信仰。」"
  },
  AvgDialog_47172_Content_13 = {
    Text = "「你也知道啊？虧你還笑得出來！這都快半年時間了，你每次做魚人儀式都做不了，這樣下去可是很危險的！」"
  },
  AvgDialog_47172_Content_131 = {
    Text = "「信仰，是一切責任與意義。是除此之外，別無他想。」"
  },
  AvgDialog_47172_Content_132 = {
    Text = "「只有對王的信仰，才能拯救你的父親。\n想要擁有這份信仰，就必須先殺死你的父親。」"
  },
  AvgDialog_47172_Content_134 = {
    Text = "主祭緩慢地走向彌利亞姆，他緊盯著彌利亞姆的雙眼，捕捉著裡面任何一道細微的漣漪。"
  },
  AvgDialog_47172_Content_135 = {
    Text = "「把你的父親，變成魚人，才能保住他的命。」"
  },
  AvgDialog_47172_Content_136 = {
    Text = "「忘記你的父親。忘記你的家庭。全心信仰利莫里亞的王，頌念祂，歸依祂。像一個祭司那樣，按照王的指引，完成轉化儀式。」"
  },
  AvgDialog_47172_Content_137 = {
    Text = "「想要救你父親，想要贖你的罪，這是唯一的路。」"
  },
  AvgDialog_47172_Content_138 = {
    Text = "他看著彌利亞姆癱坐在地上的單薄身影，就像看著一道關於毀滅與重生、關於深淵與希望的預言。"
  },
  AvgDialog_47172_Content_139 = {
    Text = "「那麼，彌利亞姆，你準備好，殺死你的父親了嗎？」"
  },
  AvgDialog_47172_Content_14 = {
    Text = "「你說你，那些複雜的什麼草藥理論課，你學得比誰都快，怎麼一到這個儀式就不行了呢……」"
  },
  AvgDialog_47172_Content_15 = {
    Text = "「抱歉，我……我想到要在他們身上做那麼殘忍的事，我實在沒辦法……我做不到……」"
  },
  AvgDialog_47172_Content_16 = {
    Text = "「你的天賦這麼厲害，怎麼會做不到！就像主祭大人說的那樣，你只需要全心全意地去為王禱告，忘記別的那些東西，一定可以的！」"
  },
  AvgDialog_47172_Content_17 = {
    Text = "「黛博拉，我真的……每次我看到那些禱詞，還有那些魚一樣的生物，就會想到我的家人。」"
  },
  AvgDialog_47172_Content_18 = {
    Text = "「出現在我身邊保護我的，一直都是我的家人，不是王……」"
  },
  AvgDialog_47172_Content_19 = {
    Text = "「噓！你在說什麼胡話呢？！」"
  },
  AvgDialog_47172_Content_2 = {
    Text = "數月後。"
  },
  AvgDialog_47172_Content_20 = {
    Text = "「吾主，請原諒彌利亞姆，她的腦子被魚人嚇得不清醒了……請原諒請原諒……」"
  },
  AvgDialog_47172_Content_21 = {
    Text = "黛博拉向著禱告室雕像的方向恭敬地行完禮，然後狠狠地瞪了彌利亞姆一眼。"
  },
  AvgDialog_47172_Content_22 = {
    Text = "「你說話可得小心一點！被王聽見了，可是會懲罰你的！」"
  },
  AvgDialog_47172_Content_23 = {
    Text = "「抱歉……我不該說這些的……」"
  },
  AvgDialog_47172_Content_24 = {
    Text = "「你就不該這麼想！哎，算了算了，這種事也急不得。我們慢慢來。」"
  },
  AvgDialog_47172_Content_25 = {
    Text = "「利莫里亞人大都更在意王，可你好像更在意自己家裡人。不過，好像從來沒聽你講過他們？」"
  },
  AvgDialog_47172_Content_26 = {
    Text = "「都半年沒見到他們了，一定很想他們吧……想和我講講嗎？」"
  },
  AvgDialog_47172_Content_27 = {
    Text = "「可以嗎？那可能要講很久，而且都是些雜亂的小事……」"
  },
  AvgDialog_47172_Content_28 = {
    Text = "「反正沒什麼事，你慢慢講，我慢慢聽嘛。」"
  },
  AvgDialog_47172_Content_29 = {
    Text = "「我想想從哪裡開始……嗯，以前，我家裡有我父親母親，還有一個妹妹。」"
  },
  AvgDialog_47172_Content_3 = {
    Text = "她拿著一把祭祀用的匕首，看著石案上那個半人半魚的生物。"
  },
  AvgDialog_47172_Content_30 = {
    Text = "「在我小的時候，我母親因為天災過世了，父親一個人把我們養大。他是一個很偉大的人，一直在保護著這個家。」"
  },
  AvgDialog_47172_Content_31 = {
    Text = "「我的妹妹也很可愛，雖然性格有些大大咧咧，但是很聰明，很善解人意……」"
  },
  AvgDialog_47172_Content_32 = {
    Text = "「說起來，你們性格還挺像呢。要不，我今天再多收一個妹妹吧？」"
  },
  AvgDialog_47172_Content_33 = {
    Text = "「好你個彌利亞姆，還挺會佔我便宜！」"
  },
  AvgDialog_47172_Content_34 = {
    Text = "彌利亞姆很少和人講述這些，一開始的時候還不太習慣，說話斷斷續續。但很快，她的話語變得流暢、輕快起來。"
  },
  AvgDialog_47172_Content_35 = {
    Text = "她向黛博拉細緻地講述著關於家人的一件件瑣碎記憶，臉上不自覺地帶上微笑，像是在展示自己秘密的珍寶。"
  },
  AvgDialog_47172_Content_36 = {
    Text = "隱隱的雷雨聲中，她們沿著漫長安寧的走廊，一邊打鬧著一邊向前走去。"
  },
  AvgDialog_47172_Content_37 = {
    Text = "「……來神殿的前一天，他給我做了一桌魚。我假裝很喜歡，把那一盤魚都吃下去了。他當時表情可開心了。」"
  },
  AvgDialog_47172_Content_38 = {
    Text = "「哈哈哈……要是你爸爸知道真相，一定會被你給氣死！」"
  },
  AvgDialog_47172_Content_39 = {
    Text = "「我跟妹妹約好了，這件事永遠都不會讓他知道。等我回去，還得再吃他做的魚……哎，想起來就頭疼。」"
  },
  AvgDialog_47172_Content_4 = {
    Text = "風雨聲和隱隱的雷鳴穿過厚重的石牆，沉悶地傳進神殿內部。"
  },
  AvgDialog_47172_Content_40 = {
    Text = "「頭疼？我看你倒是笑得挺開心的。你是又痛苦又享受，自討苦吃，活該~」"
  },
  AvgDialog_47172_Content_42 = {
    Text = "武器碰撞的聲音伴著急促的腳步聲，在內殿中迴盪，打斷了她們的談話。"
  },
  AvgDialog_47172_Content_44 = {
    Text = "「緊急情況！……天災……南部谷地……死傷……收屍隊……避免瘟疫……」"
  },
  AvgDialog_47172_Content_45 = {
    Text = "幾個詞遠遠傳進彌利亞姆的耳中，侍衛們緊急往內殿深處走去。她猛然頓住。"
  },
  AvgDialog_47172_Content_46 = {
    Text = "「南部谷地……彌利亞姆，你剛才說，你家好像就在……」"
  },
  AvgDialog_47172_Content_48 = {
    Text = "彌利亞姆快速地點點頭，焦急地四下張望著，似乎在尋找著什麼。"
  },
  AvgDialog_47172_Content_49 = {
    Text = "「你瘋了？祭司學徒從神殿私自逃走，可是重罪！」"
  },
  AvgDialog_47172_Content_5 = {
    Text = "「\"吾主之信徒，請、請敞開你的心懷，接納……接納吾主的……\"」"
  },
  AvgDialog_47172_Content_50 = {
    Text = "「別擔心，彌利亞姆……你的家人一定不會有事的……」"
  },
  AvgDialog_47172_Content_51 = {
    Text = "「不，黛博拉……南谷的地形很容易……母親以前就是這樣……」"
  },
  AvgDialog_47172_Content_52 = {
    Text = "「我有預感……我必須回去看看！」"
  },
  AvgDialog_47172_Content_53 = {
    Text = "「可是……馬上就要召開全體學徒的集會了，我想不到什麼辦法幫……」"
  },
  AvgDialog_47172_Content_54 = {
    Text = "「啊！彌利亞姆……你……」"
  },
  AvgDialog_47172_Content_55 = {
    Text = "強烈的困意湧上她的大腦。那是種用於祭祀儀式的催眠草藥，祭司們會在身上隨身攜帶。"
  },
  AvgDialog_47172_Content_56 = {
    Text = "它幫助信徒們尋找安寧，也幫助祭司們減輕罪孽。"
  },
  AvgDialog_47172_Content_57 = {
    Text = "在所有學徒裡，彌利亞姆是最擅長這些課程的，黛博拉一直都知道。"
  },
  AvgDialog_47172_Content_58 = {
    Text = "「我不想把你牽連進來。好好睡一覺吧。」"
  },
  AvgDialog_47172_Content_59 = {
    Text = "「我必須要回去……抱歉，黛博拉。」"
  },
  AvgDialog_47172_Content_6 = {
    Text = "「對不起……唔——」"
  },
  AvgDialog_47172_Content_60 = {
    Text = "她將黛博拉輕輕放在無人注意到的角落中，趁著守衛們還沒有歸位，轉身向神殿外部跑去。"
  },
  AvgDialog_47172_Content_62 = {
    Text = "「聆聽吾主。歸依吾主。」"
  },
  AvgDialog_47172_Content_63 = {
    Text = "暴雨。狂風。雷鳴。"
  },
  AvgDialog_47172_Content_64 = {
    Text = "「凡虔誠的，吾主將眷顧。」"
  },
  AvgDialog_47172_Content_65 = {
    Text = "倒塌的房屋。哭泣的人群。碎石如同凌亂的積木，從兩側的山體上落下。"
  },
  AvgDialog_47172_Content_66 = {
    Text = "「凡期願的，吾主將應許。」"
  },
  AvgDialog_47172_Content_67 = {
    Text = "世界在她眼中變成了另一種顏色，像是蒙上了一層染血的濾鏡。"
  },
  AvgDialog_47172_Content_68 = {
    Text = "在雨中奔跑了數個小時，她不確定自己所來到的是否是自己的故鄉。"
  },
  AvgDialog_47172_Content_69 = {
    Text = "那些熟悉的街道和建築，為什麼全都消失了？"
  },
  AvgDialog_47172_Content_7 = {
    Text = "她捂著嘴跑到一邊，胃部的痙攣讓她扶著牆才能勉強站穩。"
  },
  AvgDialog_47172_Content_70 = {
    Text = "那些熟悉的鄰居，為什麼很多都不見了？"
  },
  AvgDialog_47172_Content_71 = {
    Text = "她一路奔波來到這裡，現在她只想離開這個地方。但雙腿還是拖著她，將她帶回了自己的家。"
  },
  AvgDialog_47172_Content_72 = {
    Text = "——承載著她無數歡笑與眼淚的家。在無數次天災中飽經摧殘，被一次次重新建起的家。"
  },
  AvgDialog_47172_Content_73 = {
    Text = "如今只剩一地殘墟的家。"
  },
  AvgDialog_47172_Content_74 = {
    Text = "「凡苦難的，吾主將償還。」"
  },
  AvgDialog_47172_Content_75 = {
    Text = "男人佝僂著跪在廢墟之中，絲毫不在意那些鋒利的石塊與木屑。"
  },
  AvgDialog_47172_Content_76 = {
    Text = "暴雨猛烈地拍打在他的後背。他背脊盡力地彎曲，想將自己的身軀彎成一道可以勉強遮住風雨的屋簷。"
  },
  AvgDialog_47172_Content_77 = {
    Text = "可那屋簷遮不住任何的東西。無論他怎樣努力地遮擋，暴雨都穿透他渺小的身體，落在他懷中小女孩的屍體上。"
  },
  AvgDialog_47172_Content_78 = {
    Text = "他只能一遍遍地撫摸著她的臉，用那雙粗糙的手，將雨水從她逐漸變涼、變白的臉上擦去。"
  },
  AvgDialog_47172_Content_79 = {
    Text = "「薩……薩拉……不……」"
  },
  AvgDialog_47172_Content_8 = {
    Text = "「彌利亞姆，沒事吧？」"
  },
  AvgDialog_47172_Content_80 = {
    Text = "彌利亞姆聲帶幾乎沒有震動，聲音微不可聞。她向前走，摔倒，麻木地爬到妹妹的屍體旁邊，用顫抖的手撫摸她。"
  },
  AvgDialog_47172_Content_81 = {
    Text = "「她那時候正在睡覺。你知道的，薩拉睡覺的時候，一直都睡得很沉。什麼都吵不醒她。」"
  },
  AvgDialog_47172_Content_82 = {
    Text = "「她走得很平靜……沒有恐懼，沒有痛苦，沒有眷戀，什麼都沒有。」"
  },
  AvgDialog_47172_Content_83 = {
    Text = "「那時候，你媽媽死的時候，我也這樣和自己說。」"
  },
  AvgDialog_47172_Content_84 = {
    Text = "「我只能這樣安慰自己，彌利亞姆……我沒辦法保護她們，我只能這樣安慰自己……」"
  },
  AvgDialog_47172_Content_85 = {
    Text = "男人以為自己的淚水早已流乾，但幾句話一出口，淚水便重新混入雨水中。他囁嚅著，因為寒冷和疲倦而發白的嘴唇上下翕動。"
  },
  AvgDialog_47172_Content_86 = {
    Text = "伊諾斯痛苦地咳了兩聲。彌利亞姆此時才注意到，他的腿上和腹部，兩個巨大的傷口正往外滲著體內最後的血。"
  },
  AvgDialog_47172_Content_87 = {
    Text = "「父親！你……你受傷了？……」"
  },
  AvgDialog_47172_Content_88 = {
    Text = "她慌亂地拿出不知道是什麼的草藥，貼在父親的創口上，然後四下胡亂張望，想要尋找一些什麼能用上的東西。"
  },
  AvgDialog_47172_Content_89 = {
    Text = "「彌利亞姆，沒有意義的。」"
  },
  AvgDialog_47172_Content_9 = {
    Text = "「我沒事……對不起，黛博拉，耽誤你了……」"
  },
  AvgDialog_47172_Content_90 = {
    Text = "「我能救下你……我能救下你的，父親！」"
  },
  AvgDialog_47172_Content_91 = {
    Text = "「我做到了我能做的全部了，彌利亞姆。可是沒有意義……她們還是死了。你的母親，你的妹妹……」"
  },
  AvgDialog_47172_Content_92 = {
    Text = "「在利莫里亞，我這樣的人，做什麼都沒有意義……」"
  },
  AvgDialog_47172_Content_93 = {
    Text = "他努力地抬起頭，看著那些崩壞的山巒，看著滿目的廢墟，看著將災難隨意落在這座島嶼、沒有任何情感的天空。"
  },
  AvgDialog_47172_Content_94 = {
    Text = "順著他目光的方向，彌利亞姆看向兩側的山體。"
  },
  AvgDialog_47172_Content_95 = {
    Text = "「父親，那是……」"
  },
  AvgDialog_47172_Content_96 = {
    Text = "巨大的石塊從山上滾落，本應將整個鎮子完全淹沒。"
  },
  AvgDialog_47172_Content_97 = {
    Text = "幾根巨大的觸手從地底伸展出來，將大部分可怖的石塊擋了下來。"
  },
  AvgDialog_47172_Content_98 = {
    Text = "伊諾斯低下頭，望著身邊的女兒，望著他僅剩的希望與驕傲。"
  },
  AvgDialog_47172_Content_99 = {
    Text = "「是王的神蹟……」"
  },
  AvgDialog_47173_Content_1 = {
    Text = "王的獻禮"
  },
  AvgDialog_47173_Content_10 = {
    Text = "記得的，父親，所有的這些事，我都記得的……"
  },
  AvgDialog_47173_Content_100 = {
    Text = "如果無法與王的夢境相連，你將痛苦地死去。"
  },
  AvgDialog_47173_Content_101 = {
    Text = "如果活下來，就換上這套衣服。我將指引你，成為一名真正的利莫里亞祭司。"
  },
  AvgDialog_47173_Content_102 = {
    Text = "似乎完成了一個艱鉅的任務，或是犯下了一樁惡毒的罪行。老人深深吐出一口濁氣，佝僂著身體，離開了禱告室。"
  },
  AvgDialog_47173_Content_103 = {
    Text = "彌利亞姆機械地走向雕像，端起酒杯。"
  },
  AvgDialog_47173_Content_104 = {
    Text = "你殺死了父親。"
  },
  AvgDialog_47173_Content_105 = {
    Text = "那是一張彌利亞姆無比熟悉，又無比陌生的臉。"
  },
  AvgDialog_47173_Content_106 = {
    Text = "十八歲的彌利亞姆向旁邊望去，看見九歲的自己坐在身旁，望著眼前的雕像。"
  },
  AvgDialog_47173_Content_107 = {
    Text = "不，我救了父親……他曾保護過我們很多很多次。現在，輪到我們來保護他了。"
  },
  AvgDialog_47173_Content_108 = {
    Text = "可是，父親不會想看到你現在的樣子……"
  },
  AvgDialog_47173_Content_109 = {
    Text = "他會的。父親會痛苦，會難過，但他會支持我的。"
  },
  AvgDialog_47173_Content_11 = {
    Text = "這條路，真像是回家的那條。"
  },
  AvgDialog_47173_Content_110 = {
    Text = "只有這樣，我才能真正幫助利莫里亞，為他帶來神國……"
  },
  AvgDialog_47173_Content_111 = {
    Text = "這麼多的蛇血，很少有人能夠承受。你在求死，對嗎？"
  },
  AvgDialog_47173_Content_112 = {
    Text = "彌利亞姆……你相信神國嗎？"
  },
  AvgDialog_47173_Content_113 = {
    Text = "她盯著她的眼睛，如同盯著一個幼稚的神明。九歲的眼裡，盛滿了比十八歲的彌利亞姆更加深沉的悲哀。"
  },
  AvgDialog_47173_Content_114 = {
    Text = "……我還能相信什麼呢？"
  },
  AvgDialog_47173_Content_115 = {
    Text = "彌利亞姆衝她笑了笑，舉起酒杯，虔誠地望向眼前的雕像。"
  },
  AvgDialog_47173_Content_116 = {
    Text = "我將一切獻予您。回應我的期許吧，吾主。"
  },
  AvgDialog_47173_Content_117 = {
    Text = "父親的鮮血從她臉上滴落，與杯中的蛇血混在一起。"
  },
  AvgDialog_47173_Content_118 = {
    Text = "沒有任何猶豫，她仰起頭，將泛著濃烈腥氣的液體一飲而盡。"
  },
  AvgDialog_47173_Content_12 = {
    Text = "現在女兒長大啦。爸爸累的時候，也終於有人，可以依靠一下。"
  },
  AvgDialog_47173_Content_13 = {
    Text = "彌利亞姆看著父親。那個曾經像天神一樣出現在自己面前，保護自己、支撐起整個家的父親，此刻變得無比的蒼老、虛弱。"
  },
  AvgDialog_47173_Content_14 = {
    Text = "像是虛假的頑石，當堅硬的外殼破碎，才發現裡面包裹著的是一顆脆弱的心。"
  },
  AvgDialog_47173_Content_15 = {
    Text = "到了，下車吧。"
  },
  AvgDialog_47173_Content_16 = {
    Text = "馱車停了下來。黯淡的儀式間裡燃著油燈，燈台緩慢旋轉著，上面刻畫著的那些觸鬚與眼睛來回盯著忙碌的人們。"
  },
  AvgDialog_47173_Content_17 = {
    Text = "用古老符號描繪出的血色法陣中央，一個孤獨的石床正在等待著。"
  },
  AvgDialog_47173_Content_18 = {
    Text = "彌利亞姆攙扶著父親，將他放在石床之上。"
  },
  AvgDialog_47173_Content_19 = {
    Text = "短短幾步，似乎耗盡了伊諾斯的全部力氣。他痛苦地咳嗽著，幾乎快要昏迷過去。"
  },
  AvgDialog_47173_Content_2 = {
    Text = "神殿的裡面，原來是長這樣……"
  },
  AvgDialog_47173_Content_20 = {
    Text = "沒事的，父親，沒事的……你很快就會好起來了……"
  },
  AvgDialog_47173_Content_21 = {
    Text = "就是在這個房間，你的儀式失敗了。失敗了很多次。"
  },
  AvgDialog_47173_Content_22 = {
    Text = "我……記得的，主祭大人。"
  },
  AvgDialog_47173_Content_23 = {
    Text = "如果不能全心全意地信奉王的諭旨，無法得到王的認同，你的儀式依舊會失敗。"
  },
  AvgDialog_47173_Content_24 = {
    Text = "你可以選擇放棄。我會讓他死得沒有痛苦。"
  },
  AvgDialog_47173_Content_26 = {
    Text = "這是你的命運。想清楚，然後做決定吧。"
  },
  AvgDialog_47173_Content_27 = {
    Text = "身邊的侍衛將儀式所需要的工具與材料放在一邊，跟隨著主祭一同離開了房間。"
  },
  AvgDialog_47173_Content_28 = {
    Text = "陰冷的燭火，照亮了房間裡僅剩的兩個人。"
  },
  AvgDialog_47173_Content_29 = {
    Text = "彌利亞姆跪在石床邊，將頭埋在父親的胸膛。"
  },
  AvgDialog_47173_Content_3 = {
    Text = "薩拉前幾天還在說，她想姐姐了，想來看看，姐姐生活的地方是什麼樣子。"
  },
  AvgDialog_47173_Content_30 = {
    Text = "我該怎麼做……父親……"
  },
  AvgDialog_47173_Content_31 = {
    Text = "你哭了，孩子……是什麼事讓我們的小彌利亞姆這麼難過？"
  },
  AvgDialog_47173_Content_32 = {
    Text = "一雙手放在彌利亞姆頭上，輕輕撫摸著，就像從小到大，她每次難過時那樣。"
  },
  AvgDialog_47173_Content_33 = {
    Text = "彌利亞姆再也止不住淚水。她全身聳動著，淚水滴落在伊諾斯濕冷的身軀上。"
  },
  AvgDialog_47173_Content_34 = {
    Text = "她緊緊抓住父親的手，似乎只要她抓得足夠緊，父親就能夠繼續陪伴著她。"
  },
  AvgDialog_47173_Content_35 = {
    Text = "彌利亞姆，你聽到了嗎？是你媽媽的聲音……她在叫我們回家吃飯呢。還有薩拉，她正在朝我們招手……"
  },
  AvgDialog_47173_Content_36 = {
    Text = "我看見了……父親，我看見了……"
  },
  AvgDialog_47173_Content_37 = {
    Text = "我和你媽媽說了，今天給你做魚吃。爸爸知道，你最喜歡吃魚了。"
  },
  AvgDialog_47173_Content_38 = {
    Text = "你媽媽還不知道，咱們的彌利亞姆，已經當上祭司學徒了。待會告訴她，保準會嚇她一大跳的。"
  },
  AvgDialog_47173_Content_39 = {
    Text = "很快，你就會成為祭司了吧？"
  },
  AvgDialog_47173_Content_4 = {
    Text = "伊諾斯輕輕撫摸小女兒的臉。"
  },
  AvgDialog_47173_Content_40 = {
    Text = "……是的，父親，很快，我就會成為祭司……"
  },
  AvgDialog_47173_Content_42 = {
    Text = "利莫里亞的人們，活得太辛苦了。我從來都不喜歡利莫里亞，孩子，可我離不開它……因為你們在這裡，我的家在這裡。"
  },
  AvgDialog_47173_Content_43 = {
    Text = "我會做很多事，搭建房子、打魚賺錢、給你們做飯……可我改變不了什麼。"
  },
  AvgDialog_47173_Content_44 = {
    Text = "你不一樣，彌利亞姆。你會成為王最信任的追隨者，你會幫助王，讓利莫里亞，成為傳說中的神國……"
  },
  AvgDialog_47173_Content_45 = {
    Text = "神國裡，有著數不盡的食物和美酒，每天都風調雨順，晴空萬里。再也沒有人因為災難死去。"
  },
  AvgDialog_47173_Content_46 = {
    Text = "我們會有一棟堅固的石頭房子……伊諾斯，帕婭，彌利亞姆，薩拉，在那棟房子裡，我們一家人，會快樂地生活在一起……"
  },
  AvgDialog_47173_Content_47 = {
    Text = "沒錯，父親……我們會在神國再見的！我們一家人，會在神國生活在一起……"
  },
  AvgDialog_47173_Content_48 = {
    Text = "她擦去臉上的淚水，緩緩站起身，拿起了身旁的匕首。"
  },
  AvgDialog_47173_Content_49 = {
    Text = "匕首以一種奇特的弧度彎曲，上面刻畫著和禱文同樣的複雜象形符號。"
  },
  AvgDialog_47173_Content_5 = {
    Text = "昂貴的草藥暫時保住了他的命。這位虔誠的信徒第一次進入到這個神聖的殿堂，來到離王如此之近的地方。"
  },
  AvgDialog_47173_Content_50 = {
    Text = "在匕首旁邊的石盆中，與神明同源的鮮血微微泛起漣漪，燭火映照，反射出幽暗詭異的光澤。"
  },
  AvgDialog_47173_Content_51 = {
    Text = "嚴重的譫妄，讓伊諾斯失去了絕大部分的意識。他睜著眼，好奇地看著彌利亞姆，就像一個剛出世的嬰兒，看著眼前新奇的世界。"
  },
  AvgDialog_47173_Content_52 = {
    Text = "彌利亞姆，你現在是祭司了……你有問過王嗎？王有沒有告訴你，神國什麼時候能在利莫里亞降臨呢？"
  },
  AvgDialog_47173_Content_53 = {
    Text = "我問過了，父親……王說，很快，很快……"
  },
  AvgDialog_47173_Content_54 = {
    Text = "淚水之間，出現了一抹慘淡的笑容。她來到伊諾斯身邊，俯下身，撫摸他的臉。"
  },
  AvgDialog_47173_Content_55 = {
    Text = "我不會讓您失望的，父親。"
  },
  AvgDialog_47173_Content_56 = {
    Text = "神國就要降臨了，父親。很快，我們一家人，就會重逢……"
  },
  AvgDialog_47173_Content_58 = {
    Text = "匕首狠狠插入伊諾斯的胸膛，伊諾斯發出痛苦的嚎叫。鮮血噴濺，染紅了彌利亞姆的右半臉。"
  },
  AvgDialog_47173_Content_59 = {
    Text = "彌利亞姆睜大雙眼，認真地看著匕首與肉體之間的切口，就像在看著一幅曠世的畫作。"
  },
  AvgDialog_47173_Content_6 = {
    Text = "對天災的憎恨，失去女兒的悲痛，對死亡的恐懼，以及朝聖的喜悅……複雜的情緒在他平凡的身軀裡撕扯著。他靠在彌利亞姆肩頭。"
  },
  AvgDialog_47173_Content_60 = {
    Text = "匕首游走，滑動，切開皮膚與骨肉。伊諾斯痛苦地哭嚎，像是一頭正在被肢解的野獸。"
  },
  AvgDialog_47173_Content_61 = {
    Text = "嘶吼與鮮血在儀式間內奔湧，像密密麻麻的尖刺，穿透彌利亞姆的面孔與肌膚，刺入她的心臟肺腑。"
  },
  AvgDialog_47173_Content_63 = {
    Text = "“吾主之信徒，敞開你的心懷，接納吾主……”"
  },
  AvgDialog_47173_Content_64 = {
    Text = "血與淚沖刷著彌利亞姆猙獰扭曲的面容。她念誦著禱文，手上的動作越來越快、越來越快。"
  },
  AvgDialog_47173_Content_65 = {
    Text = "匕首停下。伊諾斯的身體上，以他自己的骨肉與鮮血，描繪出那些象徵著幸福與希冀的符號。"
  },
  AvgDialog_47173_Content_66 = {
    Text = "“凡虔誠的，吾主將眷顧……”"
  },
  AvgDialog_47173_Content_67 = {
    Text = "<Big:「凡期願的，吾主將應許……」>"
  },
  AvgDialog_47173_Content_68 = {
    Text = "她捧起神血，灌入伊諾斯身上那些符號般的傷口。"
  },
  AvgDialog_47173_Content_69 = {
    Text = "神血接觸到那些符號的那一刻，如同感知到獵物熱源的蛇，變得鮮活、興奮起來。"
  },
  AvgDialog_47173_Content_7 = {
    Text = "小時候你跟著我出海打魚，玩累了，回家的時候，就是像這樣，靠在我身上休息。"
  },
  AvgDialog_47173_Content_70 = {
    Text = "不需要彌利亞姆的指引，它們遵循著熱源的指引，從那些傷口鑽入伊諾斯體內。"
  },
  AvgDialog_47173_Content_71 = {
    Text = "隨著神血的匯入，伊諾斯的慘叫聲愈發劇烈。他身上的傷口，以肉眼可見的速度癒合著。"
  },
  AvgDialog_47173_Content_72 = {
    Text = "與此同時，他的五官開始退化，雙眼變得巨大而外翻，嘴唇變得黏膩，頭顱的形狀也變得扁而狹長。"
  },
  AvgDialog_47173_Content_73 = {
    Text = "一道鰓狀的器官出現在他的脖頸上，鱗片取代了毛髮，從他身體的各處生長出來。"
  },
  AvgDialog_47173_Content_74 = {
    Text = "他仍然發出痛苦的聲音，從人類成年男性的嚎叫，逐漸變成帶著深海潮濕污穢氣息的嘶鳴……"
  },
  AvgDialog_47173_Content_75 = {
    Text = "我成功了，父親……我沒有讓您失望，對嗎？"
  },
  AvgDialog_47173_Content_76 = {
    Text = "嘶鳴聲停止了。智識消失，那隻半魚半人的怪物瞪著那雙巨大泛白的眼睛，茫然地打量著她。"
  },
  AvgDialog_47173_Content_77 = {
    Text = "彌利亞姆走到石案旁邊，撫摸著那隻怪物，感知著空氣中濃烈的魚腥味，以及手上傳來的黏膩觸感。"
  },
  AvgDialog_47173_Content_78 = {
    Text = "這腥味與觸感曾經讓她覺得噁心，但現在，她覺得它們無比溫暖。"
  },
  AvgDialog_47173_Content_79 = {
    Text = "我很喜歡魚，等我們在神國重逢，我每天都會吃你做的魚……"
  },
  AvgDialog_47173_Content_8 = {
    Text = "等你睡醒，我們就到了家。你母親那時正懷著你妹妹，走很遠的路，來接我們。"
  },
  AvgDialog_47173_Content_80 = {
    Text = "請等著我吧，父親。"
  },
  AvgDialog_47173_Content_81 = {
    Text = "她俯下身，親吻它滑膩潮濕的臉。"
  },
  AvgDialog_47173_Content_83 = {
    Text = "石板門劃開。侍衛們自覺地讓開了一條路。"
  },
  AvgDialog_47173_Content_84 = {
    Text = "平靜緩慢的腳步聲來到禱告室，停留在主祭身後。"
  },
  AvgDialog_47173_Content_85 = {
    Text = "如果你想成為魚人，和父親生活在一起，我可以幫助你。"
  },
  AvgDialog_47173_Content_86 = {
    Text = "彌利亞姆輕輕搖了搖頭。"
  },
  AvgDialog_47173_Content_87 = {
    Text = "對你來說，有理智地活著，應該會比失去理智要痛苦得多。"
  },
  AvgDialog_47173_Content_88 = {
    Text = "的確如此，主祭大人。但我不怕痛苦……"
  },
  AvgDialog_47173_Content_9 = {
    Text = "我每次都跟她說，在家好好休息，她就是不聽……還記得嗎，彌利亞姆？"
  },
  AvgDialog_47173_Content_90 = {
    Text = "請您再給我一次機會……我會向您證明，我能夠成為利莫里亞最好的祭司。"
  },
  AvgDialog_47173_Content_91 = {
    Text = "我會和您一起，幫助王，為利莫里亞帶來神國！"
  },
  AvgDialog_47173_Content_92 = {
    Text = "那麼，你會為了王，殺死你的父親嗎？"
  },
  AvgDialog_47173_Content_93 = {
    Text = "是的，主祭大人。我願意。我願意為了王，做任何事。"
  },
  AvgDialog_47173_Content_94 = {
    Text = "這是唯一能拯救我的家、拯救父親的方式。"
  },
  AvgDialog_47173_Content_95 = {
    Text = "王即是父親，王即是我的家……在利莫里亞，這是唯一的真理。"
  },
  AvgDialog_47173_Content_96 = {
    Text = "彌利亞姆的半邊臉被父親的鮮血染紅，像是一張穠麗的面具。"
  },
  AvgDialog_47173_Content_97 = {
    Text = "主祭望著她，銳利的眼神終於變得緩和了一刻。"
  },
  AvgDialog_47173_Content_98 = {
    Text = "他指了指身旁。桌子上，早已準備好了一個酒杯與一套衣服。"
  },
  AvgDialog_47173_Content_99 = {
    Text = "飲下蛇怪的血液，頌念禱文，向王祈禱。"
  },
  AvgDialog_47174_Content_1 = {
    Text = "祭司之儀"
  },
  AvgDialog_47174_Content_10 = {
    Text = "每個地方的教堂都流傳著她的故事。聽說她還是祭司學徒的時候，第一次禱告就見到了王的影子。"
  },
  AvgDialog_47174_Content_11 = {
    Text = "其他祭司喝下蛇血之後，至少都會一個星期下不了床，可她一點事都沒有。"
  },
  AvgDialog_47174_Content_12 = {
    Text = "這麼年輕，就能站在離王那麼近的地方，為利莫里亞做這麼多的事。真是羨慕啊。"
  },
  AvgDialog_47174_Content_13 = {
    Text = "要是能和她交換，讓我犧牲什麼我都願意……"
  },
  AvgDialog_47174_Content_14 = {
    Text = "啊！快看快看，副主祭大人出來了！"
  },
  AvgDialog_47174_Content_15 = {
    Text = "房間內的燭火隨著風搖曳。一群侍衛魚貫而出，分列在祭祀台兩側。"
  },
  AvgDialog_47174_Content_16 = {
    Text = "王座的幻夢中，王聆聽神明的啟示："
  },
  AvgDialog_47174_Content_17 = {
    Text = "利莫里亞的風暴將平息。利莫里亞的深淵將消逝。"
  },
  AvgDialog_47174_Content_18 = {
    Text = "王將庇護祂良善的子民，帶來神的國度。"
  },
  AvgDialog_47174_Content_19 = {
    Text = "讚頌吾主。"
  },
  AvgDialog_47174_Content_2 = {
    Text = "看這個天氣，很快又要下暴雨了……天氣真是越來越差。"
  },
  AvgDialog_47174_Content_20 = {
    Text = "讚頌吾主！"
  },
  AvgDialog_47174_Content_21 = {
    Text = "聲音似乎是從遙遠的地方傳來，柔和卻清晰無比。"
  },
  AvgDialog_47174_Content_22 = {
    Text = "在祭司學徒們的注視下，一道紫色的身影緩緩從神殿內部走出。"
  },
  AvgDialog_47174_Content_23 = {
    Text = "她站在祭祀台上，雙眼透過淡紫色的面紗，平靜地掃視眾人。兩道黑色的霧氣，如同未成型的蛇，盤踞在她的身後。"
  },
  AvgDialog_47174_Content_24 = {
    Text = "那道平靜的目光之下似乎帶著某種強大的力量，讓眾人的呼吸都變得遲緩了下來。"
  },
  AvgDialog_47174_Content_25 = {
    Text = "主祭大人近期身體不適。魚人化的儀式，將由我來為大家進行教學。"
  },
  AvgDialog_47174_Content_26 = {
    Text = "帶上先行者。"
  },
  AvgDialog_47174_Content_27 = {
    Text = "在侍衛的押送下，一對父女被帶入房間內。"
  },
  AvgDialog_47174_Content_28 = {
    Text = "潮濕的燭台，陰冷的燭光。一切似乎都和三年前一樣。"
  },
  AvgDialog_47174_Content_29 = {
    Text = "意識不清的父親被放上石桌，他十來歲的女兒在侍衛的扣押下不停地掙扎哭喊著。"
  },
  AvgDialog_47174_Content_3 = {
    Text = "這幾年大大小小的天災比以前頻繁了不少。尤其是三年之前那場南谷的天災，可是死了不少人……"
  },
  AvgDialog_47174_Content_30 = {
    Text = "祭司大人！求求你，求求你高抬貴手……"
  },
  AvgDialog_47174_Content_31 = {
    Text = "我的父親只偷了很少的一點東西……我母親死在天災裡面，父親拿不出錢，才會去偷東西……"
  },
  AvgDialog_47174_Content_32 = {
    Text = "我什麼都願意做，求求你放過我父親……"
  },
  AvgDialog_47174_Content_33 = {
    Text = "什麼都願意做……那麼，你願意為了王，殺死你的父親嗎？"
  },
  AvgDialog_47174_Content_35 = {
    Text = "女孩臉上的茫然讓彌利亞姆覺得很熟悉。每個人都會經歷這樣的階段，沒有人比彌利亞姆更明白。"
  },
  AvgDialog_47174_Content_36 = {
    Text = "她走上前，溫柔地拍了拍女孩的頭。"
  },
  AvgDialog_47174_Content_37 = {
    Text = "別害怕，吾主的信徒。"
  },
  AvgDialog_47174_Content_38 = {
    Text = "來，來這邊。"
  },
  AvgDialog_47174_Content_39 = {
    Text = "她握著女孩的手，帶著她，撫摸著自己父親的臉頰。"
  },
  AvgDialog_47174_Content_4 = {
    Text = "的確……不過這位新的副主祭授職以後，還是做了不少事。信徒的房屋改建，大規模的祭司選拔和祭祀活動，都是她在操辦。"
  },
  AvgDialog_47174_Content_40 = {
    Text = "告訴我，你和你的父親，你們嚮往神國嗎？"
  },
  AvgDialog_47174_Content_41 = {
    Text = "我們……我們嚮往神國……"
  },
  AvgDialog_47174_Content_42 = {
    Text = "沒錯，利莫里亞人，應該嚮往神國。"
  },
  AvgDialog_47174_Content_43 = {
    Text = "那裡有你們想要的一切。沒有災難，沒有病痛……神國，才應該是我們唯一追尋的東西。"
  },
  AvgDialog_47174_Content_44 = {
    Text = "她將祭祀匕首放在了女孩手上。那雙手顫抖不止，彌利亞姆將它輕輕握住。"
  },
  AvgDialog_47174_Content_45 = {
    Text = "你們不是罪犯。你們深愛著對方，這種愛是值得讚頌的，不應被稱之為罪。"
  },
  AvgDialog_47174_Content_46 = {
    Text = "正因如此，你們才有資格來到這裡。才有資格，為神國的降臨，貢獻你們自己的力量。"
  },
  AvgDialog_47174_Content_47 = {
    Text = "不……祭司大人，既然不是罪，請您不要懲罰我們……求求你，求求你不要……"
  },
  AvgDialog_47174_Content_48 = {
    Text = "懲罰？不，吾主的信徒，這不是懲罰。這是王，對你們的恩賜——"
  },
  AvgDialog_47174_Content_5 = {
    Text = "還有像今天這種公開的魚人化儀式，都是以前從來沒有見過的。"
  },
  AvgDialog_47174_Content_51 = {
    Text = "彌利亞姆帶著女孩的手狠狠落下。祭祀匕首的鋒刃，完全沒入了男人的胸膛。"
  },
  AvgDialog_47174_Content_52 = {
    Text = "鮮血濺出，塗滿了女孩的臉。父親痛苦的嘶吼和女兒尖銳的哭喊，在房間中迴盪著。"
  },
  AvgDialog_47174_Content_53 = {
    Text = "放心，忠誠的信徒，你父親的儀式結束，便會輪到你。"
  },
  AvgDialog_47174_Content_54 = {
    Text = "你還能夠和父親生活在一起。那些清醒的代價，我會去替你們承擔的。"
  },
  AvgDialog_47174_Content_55 = {
    Text = "她一邊說著，一邊帶領著那只匕首在男人身上遊走著。這幾年裡，這樣的儀式她已經做了無數次。"
  },
  AvgDialog_47174_Content_56 = {
    Text = "一種巨大的幸福感縈繞著她。那些飛濺的鮮血和扭曲的面孔，是通往神國的階梯。利莫里亞人，理應幸福地接受它。"
  },
  AvgDialog_47174_Content_57 = {
    Text = "和我一樣，堅信王。和我一樣，耐心地等待。很快，你和你的家人們，便會在神國重逢。"
  },
  AvgDialog_47174_Content_6 = {
    Text = "我聽說，那位副主祭就是南谷的人？"
  },
  AvgDialog_47174_Content_60 = {
    Text = "對祭司學徒們來說，儀式或許有些漫長。但對彌利亞姆來說，這場儀式很快便結束了。"
  },
  AvgDialog_47174_Content_61 = {
    Text = "兩隻半人半魚的怪物被扔進了池子。彌利亞姆站在水池邊，俯下身來，溫柔地撫摸著牠們滑膩的肌膚。"
  },
  AvgDialog_47174_Content_62 = {
    Text = "濃重的腥味鑽進她的肺腑，污穢的池水打濕她的衣裙，她對此毫不在意。"
  },
  AvgDialog_47174_Content_63 = {
    Text = "這些魚人的變化比以前更加徹底了。您的技藝越來越嫻熟了呢，副主祭大人。"
  },
  AvgDialog_47174_Content_64 = {
    Text = "黛博拉，我都跟你說了好多次了，不要叫我副主祭。"
  },
  AvgDialog_47174_Content_65 = {
    Text = "她轉過身，親切地對這位唯一的朋友笑了笑。"
  },
  AvgDialog_47174_Content_66 = {
    Text = "時間過得真快，我現在都還記得你當時被這些先行者嚇到的樣子。現在搖身一變，都已經是利莫里亞的大人物了~"
  },
  AvgDialog_47174_Content_67 = {
    Text = "老主祭身體不太好，等新王即位的時候，你很可能就是我們的主祭了呢！"
  },
  AvgDialog_47174_Content_68 = {
    Text = "都一樣的，黛博拉。老師會帶著我們一起，將一切奉獻給王。很快，神國就會降臨。"
  },
  AvgDialog_47174_Content_69 = {
    Text = "新王即位的時間就要到了，我們還需要仔細地準備。我先去禱告室……"
  },
  AvgDialog_47174_Content_7 = {
    Text = "沒錯！三年以前還是個祭司學徒，結果不到一年時間，就成為了利莫里亞最年輕的副主祭……"
  },
  AvgDialog_47174_Content_70 = {
    Text = "彌利亞姆……"
  },
  AvgDialog_47174_Content_71 = {
    Text = "她指了指彌利亞姆的身上。彌利亞姆低頭一看，才注意到自己滿身的血污。"
  },
  AvgDialog_47174_Content_72 = {
    Text = "啊，抱歉……剛做完儀式，都忘了這事……"
  },
  AvgDialog_47174_Content_73 = {
    Text = "彌利亞姆，你還好嗎？"
  },
  AvgDialog_47174_Content_74 = {
    Text = "我？我很好啊……為什麼這麼問？"
  },
  AvgDialog_47174_Content_75 = {
    Text = "我也不知道。只是那件事以後，感覺你和以前像是變了一個人……"
  },
  AvgDialog_47174_Content_76 = {
    Text = "我沒有變，只是成長了。人總是要成長的。"
  },
  AvgDialog_47174_Content_77 = {
    Text = "黛博拉，還記得我們的願望嗎？以前你和我說，我們要一起成為祭司，幫助王，為利莫里亞帶來神國。"
  },
  AvgDialog_47174_Content_78 = {
    Text = "當然記得。那時候，你還是個連禱告都做不好的學徒呢~"
  },
  AvgDialog_47174_Content_79 = {
    Text = "你看，以前的約定，我都做到了。你應該為我高興才對，不是嗎？"
  },
  AvgDialog_47174_Content_8 = {
    Text = "如今主祭大人身體越來越差，大部分事情都交給她去做了。說不定，她很快就能成為利莫里亞最年輕的主祭。"
  },
  AvgDialog_47174_Content_80 = {
    Text = "我可是每天都在為你開心的！只是有些時候看你的樣子，感覺你好像很累。我有些擔心……"
  },
  AvgDialog_47174_Content_81 = {
    Text = "放心吧，黛博拉，我很好。從小到大，這麼多年，我從來沒有這麼好過。"
  },
  AvgDialog_47174_Content_82 = {
    Text = "她拍了拍黛博拉的肩膀，對她笑了笑，向住處走去。"
  },
  AvgDialog_47174_Content_83 = {
    Text = "新王的即位儀式，需要準備的東西很多，接下來將會是一段忙碌的時間。"
  },
  AvgDialog_47174_Content_84 = {
    Text = "路上，她望向那個自己沒有資格進入的新王的寢宮。"
  },
  AvgDialog_47174_Content_85 = {
    Text = "關於新王的傳說，利莫里亞的人們都或多或少有所耳聞。"
  },
  AvgDialog_47174_Content_86 = {
    Text = "新王即位，利莫里亞成為神國的時刻便又近了。她微笑著，隨手將擦拭鮮血的綢絹遞給了侍衛。"
  },
  AvgDialog_47174_Content_9 = {
    Text = "她現在才二十來歲，真是了不得……"
  },
  AvgDialog_47175_Content_11 = {
    Text = "利莫里亞神殿外。"
  },
  AvgDialog_47175_Content_13 = {
    Text = "讚頌吾主！迎接神國！"
  },
  AvgDialog_47175_Content_14 = {
    Text = "宏偉的利莫里亞神殿高高聳立，如山峰般屹立在廣闊的海岸邊。"
  },
  AvgDialog_47175_Content_15 = {
    Text = "信徒們蜂擁而至，擁擠在神殿外的廣場上，望著那個閃爍著幽暗光芒、氣勢恢宏的神壇。"
  },
  AvgDialog_47175_Content_16 = {
    Text = "人們踮起腳尖，越過人海與成群的侍衛，拼命地向神壇內部張望，想要一窺新王的身影。"
  },
  AvgDialog_47175_Content_17 = {
    Text = "神壇後方，神殿宏偉的石板門難得地在信眾面前敞開。帶著深海幽邃氣息的風從神殿內吹來，半透明的帷幕在風中微微漂浮。"
  },
  AvgDialog_47175_Content_18 = {
    Text = "彌利亞姆站在神壇外的祭司隊伍前方，雙手緊緊握住，一動不動地望著帷幕的後方。"
  },
  AvgDialog_47175_Content_19 = {
    Text = "一道看不真切的身影，斜靠在帷幕後方的御座之上，似乎正在沉睡。那獨一無二的象徵著王的冠冕，讓彌利亞姆的呼吸不自覺地紊亂起來。"
  },
  AvgDialog_47175_Content_20 = {Text = "轟——"},
  AvgDialog_47175_Content_22 = {
    Text = "猛然響起的雷鳴，讓信徒們停了下來。對天災的恐懼在他們血脈中流淌，他們慌張地抬起頭。"
  },
  AvgDialog_47175_Content_23 = {
    Text = "原本被雲層遮蔽的天空變得愈發黑暗起來。電閃雷鳴，海洋呼號著，湧起那些象徵著災難與死亡的波濤。"
  },
  AvgDialog_47175_Content_24 = {
    Text = "天災……是天災！天災就要來了！"
  },
  AvgDialog_47175_Content_25 = {
    Text = "要是神殿遭了天災，那我們……"
  },
  AvgDialog_47175_Content_26 = {
    Text = "怎麼會是在這時候……在新王即位的日子……"
  },
  AvgDialog_47175_Content_27 = {
    Text = "難道……這位新王……"
  },
  AvgDialog_47175_Content_28 = {
    Text = "不祥的預兆下，擁擠在神殿周圍的信徒們變得躁動起來。不安在人群中擴散。"
  },
  AvgDialog_47175_Content_29 = {
    Text = "帷幕後方，響起一聲輕微的嘆息。一個幼小的身影，從御座之上站起身。"
  },
  AvgDialog_47175_Content_3 = {
    Text = "低沉悠長的鐘聲，如同神聖的諭旨，自利莫里亞的神殿響起。"
  },
  AvgDialog_47175_Content_30 = {
    Text = "天災不會降臨。"
  },
  AvgDialog_47175_Content_31 = {
    Text = "於夢境之中，余得聞神諭："
  },
  AvgDialog_47175_Content_32 = {
    Text = "即日，利莫里亞將迎來新王。"
  },
  AvgDialog_47175_Content_33 = {
    Text = "即日，一切天災將為余退避。"
  },
  AvgDialog_47175_Content_34 = {
    Text = "那道年幼的聲音很平靜，卻像洪鐘一般，無比清晰地傳進每個人的耳中。"
  },
  AvgDialog_47175_Content_35 = {
    Text = "那是……新王？是新王的聲音！"
  },
  AvgDialog_47175_Content_37 = {
    Text = "幾乎就在圖魯的話出口的那一刻，天上的烏雲開始以肉眼可見的速度消散。"
  },
  AvgDialog_47175_Content_38 = {
    Text = "海洋的呼號開始平息，晴朗的陽光灑下，照耀在每一位信徒臉上。"
  },
  AvgDialog_47175_Content_39 = {
    Text = "神蹟……這是神蹟！"
  },
  AvgDialog_47175_Content_4 = {
    Text = "鐘聲傳向海岸，傳向山脈，傳向城市與村野。"
  },
  AvgDialog_47175_Content_40 = {
    Text = "神壇後的帷幕上，被陽光照耀，映出一個清晰的輪廓。"
  },
  AvgDialog_47175_Content_41 = {
    Text = "一個年幼的身軀，來到帷幕邊上，輕輕抬起手臂。"
  },
  AvgDialog_47175_Content_42 = {Text = "轟……"},
  AvgDialog_47175_Content_43 = {
    Text = "隨著他的動作，數根巨大的觸手穿透海洋、平地與山體，出現在眾人面前。"
  },
  AvgDialog_47175_Content_44 = {
    Text = "若有若無的光線，自觸手上散發。光線逐漸連成一片，在所有的信徒面前，交織成一幅盛大的畫卷。"
  },
  AvgDialog_47175_Content_45 = {
    Text = "這……這個是……"
  },
  AvgDialog_47175_Content_46 = {
    Text = "彌利亞姆睜大眼睛，看著眼前的這一切。"
  },
  AvgDialog_47175_Content_47 = {
    Text = "她眼中的世界變了。山體不再破敗，海洋不再洶湧。她看到陽光落下，照在一個安寧祥和的國度。"
  },
  AvgDialog_47175_Content_49 = {
    Text = "聲音傳進彌利亞姆的耳中。她猛然抬頭，看見自己前方那個熟悉的身影。"
  },
  AvgDialog_47175_Content_5 = {
    Text = "利莫里亞的新王……新王就要即位了！！"
  },
  AvgDialog_47175_Content_50 = {
    Text = "薩……薩拉？你怎麼會……"
  },
  AvgDialog_47175_Content_51 = {
    Text = "姐姐，過了這麼久了，你怎麼一點都沒變？你看我，我長高了！"
  },
  AvgDialog_47175_Content_52 = {
    Text = "彌利亞姆……你在神殿裡，過得還好嗎？"
  },
  AvgDialog_47175_Content_53 = {
    Text = "好久都沒見到你……媽媽想你了。"
  },
  AvgDialog_47175_Content_54 = {
    Text = "母親……母親……您……"
  },
  AvgDialog_47175_Content_55 = {
    Text = "彌利亞姆愣愣地看著向自己走來的兩人。身後響起腳步聲。她緩緩轉過身去。"
  },
  AvgDialog_47175_Content_56 = {
    Text = "啊，我家的祭司大人回來了！"
  },
  AvgDialog_47175_Content_58 = {
    Text = "淚水模糊了她的視線。她喉嚨沙啞，說不出話。"
  },
  AvgDialog_47175_Content_59 = {
    Text = "一隻手放在她的頭上，輕輕撫摸著。"
  },
  AvgDialog_47175_Content_6 = {
    Text = "呼喊聲伴隨著鐘鳴，傳進這個龐大王國每一個子民的耳中。"
  },
  AvgDialog_47175_Content_60 = {
    Text = "別傷心，彌利亞姆。你做到了……你幫助王，帶來了神國！"
  },
  AvgDialog_47175_Content_61 = {
    Text = "現在，我們什麼也不用害怕了。我們一家人，會好好在神國生活在一起。永遠永遠……"
  },
  AvgDialog_47175_Content_63 = {
    Text = "妹妹跑到她身邊，擁抱著她。母親來到她身邊，擁抱著她。父親來到她身邊，擁抱著她。"
  },
  AvgDialog_47175_Content_64 = {
    Text = "擁抱。身體相觸的擁抱。帶著體溫的擁抱。只為相聚不為分別的擁抱。無人缺席的擁抱。"
  },
  AvgDialog_47175_Content_65 = {
    Text = "擁抱，那是她所追尋的一切。"
  },
  AvgDialog_47175_Content_66 = {
    Text = "淚水奪眶而出，從彌利亞姆臉上滑落，她抬起頭。"
  },
  AvgDialog_47175_Content_67 = {
    Text = "擁抱消失了。光彩變化，她回到了神殿之前。她的面前，是無數同樣流著淚的信徒。"
  },
  AvgDialog_47175_Content_68 = {
    Text = "神國的盛景，每個人內心最深的渴望，無比真切地展現在信徒們面前。"
  },
  AvgDialog_47175_Content_7 = {
    Text = "數百萬的利莫里亞人湧上街頭，佔滿每一處街道與廣場，狂熱地喊叫、期盼著。"
  },
  AvgDialog_47175_Content_70 = {
    Text = "這就是神國……這就是您將帶給我們的神國！"
  },
  AvgDialog_47175_Content_72 = {
    Text = "彌利亞姆呢喃著這些重複的話語，向著帷幕內的新王跪拜下去。"
  },
  AvgDialog_47175_Content_73 = {
    Text = "不需要任何人組織，在她身後，無數的信眾跟著跪下，行禮。"
  },
  AvgDialog_47175_Content_74 = {
    Text = "透過婆娑的淚眼，無數雙眼睛熱切地盯著神壇，盯著帷幕後方，那位新王幼小的輪廓。"
  },
  AvgDialog_47175_Content_75 = {
    Text = "此乃神國之盛景。此乃吾主之威儀。"
  },
  AvgDialog_47175_Content_76 = {
    Text = "我已年邁。依吾主之命，彌利亞姆，將接任主祭之位，輔佐利莫里亞的新王。"
  },
  AvgDialog_47175_Content_78 = {
    Text = "主祭讓到一邊，壓低了聲音。"
  },
  AvgDialog_47175_Content_79 = {
    Text = "吾主，利莫里亞已經見證了您的威儀。請繼續說下去吧。請把希望，帶給利莫里亞。"
  },
  AvgDialog_47175_Content_8 = {
    Text = "老國王或許是退位了，或許是死去了。利莫里亞人無從知曉，也並不關心。"
  },
  AvgDialog_47175_Content_80 = {
    Text = "他做了一個邀請的手勢，向圖魯躬身行禮。"
  },
  AvgDialog_47175_Content_82 = {
    Text = "余，神明的代行者，利莫里亞的王。"
  },
  AvgDialog_47175_Content_83 = {
    Text = "余……將為利莫里亞，帶來神國。"
  },
  AvgDialog_47175_Content_84 = {
    Text = "神明……神明庇佑利莫里亞！"
  },
  AvgDialog_47175_Content_85 = {
    Text = "吾主！讚頌吾主！"
  },
  AvgDialog_47175_Content_86 = {
    Text = "讚頌吾主！！"
  },
  AvgDialog_47175_Content_87 = {
    Text = "萬千信眾跪拜於地，山呼海嘯般的歡呼聲，響徹王國的每一個角落。"
  },
  AvgDialog_47175_Content_88 = {
    Text = "圖魯疲憊地轉過身。"
  },
  AvgDialog_47175_Content_89 = {
    Text = "利莫里亞期盼余說的話，余已經說完。"
  },
  AvgDialog_47175_Content_9 = {
    Text = "在與天災抗爭的漫長歲月裡，他們已學會不為昨日哀悼。他們的眼裡，只有新王所帶來的，閃耀著神國光輝的明天。"
  },
  AvgDialog_47175_Content_90 = {
    Text = "余乏了。不必相隨。"
  },
  AvgDialog_47175_Content_91 = {
    Text = "他揮揮手，阻止了想要跟上來的侍衛與主祭，"
  },
  AvgDialog_47175_Content_92 = {
    Text = "在信徒們狂熱的呼喊中，年幼的新王沉默著，獨自向空無一人的神殿內走去。"
  },
  AvgDialog_47176_Content_1 = {Text = "預言"},
  AvgDialog_47176_Content_10 = {
    Text = "房屋幾乎徹底倒塌，碎石將她堵在了這個狹窄的角落中。暴雨透過石塊之間的縫隙，澆打在她身上。"
  },
  AvgDialog_47176_Content_100 = {
    Text = "「可是、可是我父親是虔誠的信徒，王愛護他的子民，不會讓我……」"
  },
  AvgDialog_47176_Content_101 = {
    Text = "「你不應該做祭司。你不應該生在利莫里亞。你應該被流放，或是處死。」"
  },
  AvgDialog_47176_Content_102 = {
    Text = "「彌利亞姆，主祭大人不是那個意思……」"
  },
  AvgDialog_47176_Content_103 = {
    Text = "「主祭大人！請原諒彌利亞姆，她只是不太會表達……我們願意為王獻出一切！……」"
  },
  AvgDialog_47176_Content_104 = {
    Text = "「神明指引我來到這裡。這就是群星昭示的命運吧……命運，呵。」"
  },
  AvgDialog_47176_Content_105 = {
    Text = "主祭沒有理會伊諾斯和彌利亞姆的話，他深深嘆了口氣，走回了神殿深處。"
  },
  AvgDialog_47176_Content_106 = {
    Text = "很快，一個祭司跑了過來，腳步聲在安靜的大廳中迴盪。"
  },
  AvgDialog_47176_Content_107 = {
    Text = "她停在彌利亞姆面前，向她微笑著，遞給她一塊徽章。"
  },
  AvgDialog_47176_Content_108 = {
    Text = "「七天之後，帶著它來神殿，參加訓練。」"
  },
  AvgDialog_47176_Content_109 = {
    Text = "「祝賀你，彌利亞姆。你是利莫里亞的祭司學徒了。」"
  },
  AvgDialog_47176_Content_11 = {
    Text = "數塊巨大的碎石懸在她的頭頂，被一根滿是裂痕的細石柱勉強支撐著，在暴雨中顫抖。"
  },
  AvgDialog_47176_Content_111 = {
    Text = "「姐姐選上了！姐姐選上了！」"
  },
  AvgDialog_47176_Content_112 = {
    Text = "薩拉興奮地跳了起來，伊諾斯向著雕像的方向，緊握的雙手在身前微微顫抖。"
  },
  AvgDialog_47176_Content_113 = {
    Text = "「謝謝您，祭司大人，謝謝您！」"
  },
  AvgDialog_47176_Content_114 = {
    Text = "「吾主聽見了我們的聲音……感恩吾主……感恩……」"
  },
  AvgDialog_47176_Content_115 = {
    Text = "「帕婭，你聽見了嗎？我們的孩子成為祭司學徒了！」"
  },
  AvgDialog_47176_Content_116 = {
    Text = "「你要是能看到，一定會很開心吧，帕婭……」"
  },
  AvgDialog_47176_Content_117 = {
    Text = "彌利亞姆愣在原地，還沒有明白發生了什麼。"
  },
  AvgDialog_47176_Content_118 = {
    Text = "妹妹肆無忌憚地歡呼，父親偷偷擦去眼淚，周圍的人群傳來真誠或嫉妒的賀喜聲。"
  },
  AvgDialog_47176_Content_119 = {
    Text = "一個刻著觸鬚與風暴的暗色徽章靜靜地躺在她的手心，對周圍的一切景象與聲音無動於衷，像一個淡漠的預言。"
  },
  AvgDialog_47176_Content_12 = {
    Text = "「敬、敬愛的王……」"
  },
  AvgDialog_47176_Content_120 = {
    Text = "「你喜歡吃魚，回去以後，我要好好給你做一桌你最喜歡的菜！」"
  },
  AvgDialog_47176_Content_121 = {
    Text = "「我要去通知所有的人，告訴他們這個好消息！」"
  },
  AvgDialog_47176_Content_122 = {
    Text = "「我家彌利亞姆，就要成為利莫里亞的祭司了！」"
  },
  AvgDialog_47176_Content_123 = {
    Text = "「還只是學徒呢……」"
  },
  AvgDialog_47176_Content_124 = {
    Text = "「主祭大人都特別關照過你了，說明咱們彌利亞姆的天賦可是了不得的！一定不會有問題的！」"
  },
  AvgDialog_47176_Content_125 = {
    Text = "彌利亞姆不明白主祭的意思，也不明白自己為什麼會獲得這個資格。她看著父親與妹妹。她很久沒有在他們臉上見過如此幸福的神情了。"
  },
  AvgDialog_47176_Content_126 = {
    Text = "彌利亞姆撫摸著徽章，微笑浮現在她的臉上。"
  },
  AvgDialog_47176_Content_127 = {
    Text = "自己終於也像父親一樣，為家人們帶來了笑容。那就讓這笑容，繼續持續下去吧。她想。"
  },
  AvgDialog_47176_Content_13 = {
    Text = "「請……拯救您忠誠的信徒……」"
  },
  AvgDialog_47176_Content_14 = {
    Text = "她看著頭上搖搖欲墜的碎石，將自己的身體盡量往角落裡縮了縮，兩隻手十指交叉，合在胸前禱告著。"
  },
  AvgDialog_47176_Content_15 = {
    Text = "暴雨。驚雷。地震。海嘯。"
  },
  AvgDialog_47176_Content_16 = {
    Text = "利莫里亞的人們與天災同眠，祈禱是他們學會的第一件事。"
  },
  AvgDialog_47176_Content_17 = {
    Text = "「您是神明的代行者，是利莫里亞子民的信仰……我將為您獻上我的一切……」"
  },
  AvgDialog_47176_Content_18 = {
    Text = "「請幫助我……救救我……」"
  },
  AvgDialog_47176_Content_19 = {
    Text = "父親說，神明與王會拯救利莫里亞的子民。她不知道什麼是神，什麼是王。她一遍一遍地呼喚著。"
  },
  AvgDialog_47176_Content_2 = {
    Text = "「王座的幻夢中，王聆聽神明的啟示：」"
  },
  AvgDialog_47176_Content_20 = {
    Text = "神明仍未出現，神明從未在她面前出現過。可除了禱告，她什麼也做不了。"
  },
  AvgDialog_47176_Content_21 = {
    Text = "石柱的裂隙越來越明顯。它已無法再支撐上方碎石的重量了。"
  },
  AvgDialog_47176_Content_22 = {
    Text = "「吾主……請救救我……」"
  },
  AvgDialog_47176_Content_23 = {
    Text = "彌利亞姆想起母親被從廢墟下挖出來時，那個骯髒、破爛的身體。"
  },
  AvgDialog_47176_Content_24 = {
    Text = "在她最後的那個時刻，是不是也像現在的自己一樣，寒冷，恐懼，絕望呢？"
  },
  AvgDialog_47176_Content_25 = {
    Text = "淚水無助地混在雨水裡。聲音越來越弱，和身體一同顫抖著……"
  },
  AvgDialog_47176_Content_26 = {Text = "轟——"},
  AvgDialog_47176_Content_28 = {
    Text = "「彌利亞姆！」"
  },
  AvgDialog_47176_Content_29 = {
    Text = "石柱斷裂開。在巨大的石塊即將砸下來之前，一個熟悉的身影衝了過來，將彌利亞姆拉到自己懷裡。"
  },
  AvgDialog_47176_Content_3 = {
    Text = "「利莫里亞的風暴將平息。利莫里亞的深淵將消逝。」"
  },
  AvgDialog_47176_Content_30 = {
    Text = "「父……父親！……」"
  },
  AvgDialog_47176_Content_31 = {
    Text = "彌利亞姆緩緩移開下意識遮擋在眼前的手臂。"
  },
  AvgDialog_47176_Content_32 = {
    Text = "「嗚哇……」"
  },
  AvgDialog_47176_Content_33 = {
    Text = "她一把抱住這個熟悉的身影。"
  },
  AvgDialog_47176_Content_34 = {
    Text = "「別怕，彌利亞姆。別怕。我在這。」"
  },
  AvgDialog_47176_Content_35 = {
    Text = "「嘶啊……小心點，孩子……別碰肩膀……」"
  },
  AvgDialog_47176_Content_37 = {
    Text = "石塊墜落，碎石飛濺，男人擋在石塊與女孩之間，常年風吹日曬而顯得黝黑的皮膚上，滿是碎石與瓦片留下的傷痕。"
  },
  AvgDialog_47176_Content_38 = {
    Text = "瘋狂地刨去石塊與泥土，即使是那雙粗糙的手也血肉模糊。"
  },
  AvgDialog_47176_Content_39 = {
    Text = "雨水沖刷著男人的身體，帶著新鮮的血液，將地上的廢墟染得殷紅。"
  },
  AvgDialog_47176_Content_4 = {
    Text = "「王將庇護他良善的子民，帶來神的國度。\n溫柔的水，潤澤每一寸草木……」"
  },
  AvgDialog_47176_Content_40 = {
    Text = "「父親……我……是我讓您受傷了……」"
  },
  AvgDialog_47176_Content_41 = {
    Text = "一隻粗糙、寬厚的手放在了她的頭上，輕輕撫摸著。"
  },
  AvgDialog_47176_Content_42 = {
    Text = "「傻孩子，說什麼呢。只要你沒事，再多的傷也算不了什麼的。」"
  },
  AvgDialog_47176_Content_43 = {
    Text = "「還好，還好……總算趕上了……」"
  },
  AvgDialog_47176_Content_44 = {
    Text = "「感謝吾主！保護了我的家人……」"
  },
  AvgDialog_47176_Content_45 = {
    Text = "「保護我的，明明是父親……」"
  },
  AvgDialog_47176_Content_46 = {
    Text = "「利莫里亞的人能活下來，都是因為王的幫助。只有虔誠地信奉王，才能保護好自己的家人。你現在還小，等你長大以後，你會明白的。」"
  },
  AvgDialog_47176_Content_47 = {
    Text = "伊諾斯笑著，拍了拍她的腦袋。他帶著彌利亞姆一起，對著神殿的方向，虔誠地行禮。"
  },
  AvgDialog_47176_Content_48 = {
    Text = "「來，和我一起念。\n凡迷失的，吾主將指引……」"
  },
  AvgDialog_47176_Content_5 = {Text = "轟——"},
  AvgDialog_47176_Content_50 = {
    Text = "……凡期願的，吾主將應許……"
  },
  AvgDialog_47176_Content_51 = {
    Text = "「彌利亞姆？」"
  },
  AvgDialog_47176_Content_52 = {
    Text = "……凡虔誠的，吾主將眷顧……"
  },
  AvgDialog_47176_Content_53 = {
    Text = "「彌利亞姆？睡著了嗎？」"
  },
  AvgDialog_47176_Content_54 = {
    Text = "「啊，父親！抱歉……我剛剛在想一些以前的事情……」"
  },
  AvgDialog_47176_Content_55 = {
    Text = "「彌利亞姆，你確定你想當祭司學徒嗎？」"
  },
  AvgDialog_47176_Content_56 = {
    Text = "「是的，父親。」"
  },
  AvgDialog_47176_Content_57 = {
    Text = "「那就好，那就好。我看你心不在焉的樣子，平時也不太喜歡聊這些，還以為你不喜歡呢……」"
  },
  AvgDialog_47176_Content_58 = {
    Text = "「你那天主動說想來競選祭司學徒，爸爸真是太高興了。咱女兒長大了……」"
  },
  AvgDialog_47176_Content_59 = {
    Text = "「既然來了，咱們就好好聽祭司講話。王是最接近神明的人，祂什麼都看得見。不虔誠的人，是沒辦法得到王的眷顧的。」"
  },
  AvgDialog_47176_Content_60 = {
    Text = "「嗯……我知道了，父親。」"
  },
  AvgDialog_47176_Content_61 = {
    Text = "眷顧自己的從來都不是王。彌利亞姆這樣想著，沒有說出口。"
  },
  AvgDialog_47176_Content_62 = {
    Text = "「爸爸，姐姐能選上嗎？」"
  },
  AvgDialog_47176_Content_63 = {
    Text = "「當然可以了！城裡的祭司都說了，你姐姐的精神力天賦，可是比祭司本人都要強。」"
  },
  AvgDialog_47176_Content_64 = {
    Text = "「她不僅能夠成為祭司，說不定，以後還能成為主祭呢！」"
  },
  AvgDialog_47176_Content_65 = {
    Text = "「那是無上的榮耀……要真是那樣，你們母親在另外那個世界，也會為你們感到高興的！」"
  },
  AvgDialog_47176_Content_66 = {
    Text = "「啊！祭司大人過來了！」"
  },
  AvgDialog_47176_Content_67 = {
    Text = "薩拉興奮的叫喊中，眾人望向前方。"
  },
  AvgDialog_47176_Content_68 = {
    Text = "頭戴紫紗的祭司一邊誦念著禱詞，一邊行走。她從前面參選的孩子面前一個個走過，來到了彌利亞姆一家面前。"
  },
  AvgDialog_47176_Content_69 = {
    Text = "「吾主，請聆聽我虔誠的心聲，請接納我的女兒，彌利亞姆……」"
  },
  AvgDialog_47176_Content_7 = {
    Text = "雷聲在島嶼上空炸響。幼小的身軀在廢墟下戰慄。"
  },
  AvgDialog_47176_Content_70 = {
    Text = "父親的低聲禱告與祭司的威儀讓彌利亞姆沒有再說話。"
  },
  AvgDialog_47176_Content_71 = {
    Text = "她低下頭等待著。祭司抬起的手放在她的前額之上。"
  },
  AvgDialog_47176_Content_72 = {
    Text = "「祭司大人，請問我的孩子……」"
  },
  AvgDialog_47176_Content_73 = {
    Text = "父親卑微地望著祭司。祭司沒有回話，也沒有任何的表情。她已經見過太多這樣的故事，對於動物的低鳴，已經沒有了任何的興趣。"
  },
  AvgDialog_47176_Content_74 = {
    Text = "那雙保養得當的手連一刻也沒有停留。祭司帶著侍從，轉身離開，回到了祭禮台。"
  },
  AvgDialog_47176_Content_75 = {
    Text = "「落選了嗎……」"
  },
  AvgDialog_47176_Content_76 = {
    Text = "「父親，對不起，我還是沒有幫上家裡什麼……」"
  },
  AvgDialog_47176_Content_77 = {
    Text = "「說什麼呢，傻孩子。群星已經定好了每個人的命運，爸爸自己不是也沒有做成祭司嗎？」"
  },
  AvgDialog_47176_Content_78 = {
    Text = "「只要你們能健康快樂地生活下去，爸爸就心滿意足了。就算做不了祭司，你也是爸爸的好孩子。」"
  },
  AvgDialog_47176_Content_8 = {
    Text = "海洋在離她不遠的地方憤怒地咆哮，幾乎連雷聲也要吞沒。宏大的利莫里亞島如同一片無依的枯葉，在漫無邊際的海洋中顫抖。"
  },
  AvgDialog_47176_Content_80 = {
    Text = "「哈哈哈，你們都是好孩子！」"
  },
  AvgDialog_47176_Content_81 = {
    Text = "彌利亞姆看得出來，父親的表情有些失落。但那隻粗糙、寬厚的手，依然溫柔地放在自己的頭上。"
  },
  AvgDialog_47176_Content_82 = {
    Text = "從小到大，在她恐懼的時候，在她失落的時候，在她悲傷的時候，這隻手總是會出現，像這樣撫摸著自己的頭，讓自己安下心來。"
  },
  AvgDialog_47176_Content_83 = {
    Text = "可從小到大，那隻手的主人，承受了些什麼？自己又做了什麼，去幫助他呢？"
  },
  AvgDialog_47176_Content_84 = {
    Text = "彌利亞姆低下頭去，藏起發紅的眼圈。"
  },
  AvgDialog_47176_Content_85 = {
    Text = "「咦，姐姐你看，有個老爺爺走到台上來了！」"
  },
  AvgDialog_47176_Content_86 = {
    Text = "「那個衣服！……紫色的長袍！……」"
  },
  AvgDialog_47176_Content_87 = {
    Text = "一個信徒激動地擠到伊諾斯身旁，踮起腳張望著。"
  },
  AvgDialog_47176_Content_88 = {
    Text = "「是主祭大人？主祭大人竟然從神殿裡出來了？！也沒有人通知過這件事啊……」"
  },
  AvgDialog_47176_Content_89 = {
    Text = "一個老者從後方的房間中走了出來。他的面容蒼老，但步履依舊穩定，身上的服飾打理得一絲不苟，連一個皺紋都沒有。"
  },
  AvgDialog_47176_Content_9 = {
    Text = "強烈的海島地震已經平息，但她依然感覺到暈眩。"
  },
  AvgDialog_47176_Content_90 = {
    Text = "主祭，唯一能面見王的人。在整個利莫里亞，除了能與神明溝通的王以外，他的地位至高無上。"
  },
  AvgDialog_47176_Content_91 = {
    Text = "老人嚴峻的目光掃視著全場。他什麼話也沒有說，但在那道目光之下，原本喧囂的神殿立刻安靜了下來。"
  },
  AvgDialog_47176_Content_92 = {
    Text = "很快，那道目光望向了彌利亞姆的方向。跟隨著祭司的指引，老人來到彌利亞姆面前，佈滿皺紋的手放在她的前額之上。"
  },
  AvgDialog_47176_Content_93 = {
    Text = "那些高傲的祭司此刻躬身停留在老人身前。神殿內的一切似乎因為老人的出現而凝滯了，她沒有辦法呼吸，也感覺不到時間的流逝。"
  },
  AvgDialog_47176_Content_94 = {
    Text = "「你會為了王，殺死你的父親嗎？」"
  },
  AvgDialog_47176_Content_95 = {
    Text = "冰冷的聲音從主祭口中傳來，像驚雷一樣炸開了凝滯的時間。"
  },
  AvgDialog_47176_Content_96 = {
    Text = "彌利亞姆猛然抬起頭，看到主祭那張蒼老威嚴的臉。"
  },
  AvgDialog_47176_Content_97 = {
    Text = "「您……您說什麼？」"
  },
  AvgDialog_47176_Content_98 = {
    Text = "「告訴我，什麼是信仰。」"
  },
  AvgDialog_47176_Content_99 = {
    Text = "「信仰是……是為王獻出一切……」"
  },
  AvgDialog_47177_Content_1 = {Text = "魚肉"},
  AvgDialog_47177_Content_10 = {
    Text = "姐姐，魚那麼好吃，為什麼你不喜歡吃呢？"
  },
  AvgDialog_47177_Content_11 = {
    Text = "可能是因為小時候吃得太多，可能是因為魚的味道太腥，也可能……"
  },
  AvgDialog_47177_Content_12 = {
    Text = "薩拉，我還沒有和你講過媽媽去世時候的事情，對吧？"
  },
  AvgDialog_47177_Content_13 = {
    Text = "薩拉搖了搖頭，安靜地窩在彌利亞姆懷裡聽著。"
  },
  AvgDialog_47177_Content_14 = {
    Text = "那時候你剛出生不久，媽媽臥病在床。山上的石頭滾下來的時候，她沒有來得及跑開。"
  },
  AvgDialog_47177_Content_15 = {
    Text = "那天刮著很大的風，那些魚從天上落下來，落在媽媽的身上。"
  },
  AvgDialog_47177_Content_16 = {
    Text = "她的眼睛圓圓地睜著，就像那些魚一樣……"
  },
  AvgDialog_47177_Content_17 = {
    Text = "彌利亞姆沒有再說下去，薩拉也沒有再問。妹妹緊緊地靠在姐姐懷裡，拍了拍她的後背。"
  },
  AvgDialog_47177_Content_18 = {
    Text = "那你都不喜歡了，為什麼不跟爸爸說呢？"
  },
  AvgDialog_47177_Content_19 = {
    Text = "我要是不喜歡什麼，我就會直接和你們說的。"
  },
  AvgDialog_47177_Content_20 = {
    Text = "媽媽去世以後，爸爸一個人養活我們一家人。他活得很辛苦。"
  },
  AvgDialog_47177_Content_21 = {
    Text = "在利莫里亞，魚是最便宜的食物。"
  },
  AvgDialog_47177_Content_22 = {
    Text = "我沒什麼本事，幫不了家裡什麼。唯一能做的，就是少給他添麻煩……"
  },
  AvgDialog_47177_Content_23 = {
    Text = "薩拉，你也要記得，等你長大了，也要好好幫助爸爸，好嗎？"
  },
  AvgDialog_47177_Content_24 = {
    Text = "嗯！誒，那姐姐，你說你喜歡當祭司，也和你說喜歡吃魚一樣嗎？"
  },
  AvgDialog_47177_Content_25 = {
    Text = "來！兩個小公主，最後一道菜做好了！"
  },
  AvgDialog_47177_Content_26 = {
    Text = "父親的聲音從廚房傳來，打斷了薩拉的問題。彌利亞姆笑了笑，轉開了話頭。"
  },
  AvgDialog_47177_Content_27 = {
    Text = "薩拉，我的這些事，可不能跟其他人講哦？"
  },
  AvgDialog_47177_Content_28 = {
    Text = "知道！薩拉也不給姐姐和爸爸添麻煩~"
  },
  AvgDialog_47177_Content_29 = {
    Text = "彌利亞姆笑著拍了拍妹妹的頭，帶著她向廚房走去，迎接父親為自己準備的盛宴。"
  },
  AvgDialog_47177_Content_3 = {
    Text = "新鮮的魚肉放進鍋裡，美妙的聲音與香味一同從簡陋的廚房中飄出。"
  },
  AvgDialog_47177_Content_30 = {
    Text = "很快，各種魚製菜品便擺滿了家裡那個不大的桌子。"
  },
  AvgDialog_47177_Content_31 = {
    Text = "你們去買菜的時候，我和鎮子上的人們講了，住得很遠的那些親戚，我也寫了信，幾天以後他們也會知道。"
  },
  AvgDialog_47177_Content_32 = {
    Text = "附近那些從小看著你長大的叔叔阿姨，都為你高興，送了好多吃的喝的過來。"
  },
  AvgDialog_47177_Content_33 = {
    Text = "啊對，還有城裡那個祭司，聽說你是被主祭挑選出來的，過來主動找我說話，態度可好了！"
  },
  AvgDialog_47177_Content_34 = {
    Text = "只是個小事情……沒必要告訴這麼多人吧……"
  },
  AvgDialog_47177_Content_35 = {
    Text = "才不是小事！姐姐要是當了祭司，就能賺好多好多錢，還可以找人來幫我掃地……"
  },
  AvgDialog_47177_Content_36 = {
    Text = "可別瞎說，薩拉。祭司是個神聖的職業，當祭司可不是為了這些。"
  },
  AvgDialog_47177_Content_37 = {
    Text = "那祭司是幹嘛的？"
  },
  AvgDialog_47177_Content_38 = {
    Text = "祭司的使命……這就要從很早之前說起了。這是每個利莫里亞人，都應該熟知的故事，"
  },
  AvgDialog_47177_Content_39 = {
    Text = "伊諾斯抱起薩拉，把她放在自己腿上，撫摸著她的頭。"
  },
  AvgDialog_47177_Content_4 = {
    Text = "這些都是女兒們最愛的菜。伊諾斯做這些菜已經十幾年，閉上眼睛也能精確地控制好每一種香料的用量。"
  },
  AvgDialog_47177_Content_40 = {
    Text = "利莫里亞，有著輝煌的歷史與璀璨的文明。神明的力量庇佑著這個國家，賜予我們無盡的幸福與安寧。"
  },
  AvgDialog_47177_Content_41 = {
    Text = "這裡沒有天災，沒有病痛，每個人都有享之不盡的食物與美酒。即使是逝去的人，在神明的幫助下，也能與生者團聚。"
  },
  AvgDialog_47177_Content_42 = {
    Text = "可不知道從什麼時候開始，這裡的人們便不再能聽到神明的聲音。天災變得越來越頻繁……"
  },
  AvgDialog_47177_Content_43 = {
    Text = "我們的國家被漫無邊際的海水包圍著，從來沒有人能夠從這裡走出去。只有神明，才能改變這一切。"
  },
  AvgDialog_47177_Content_44 = {
    Text = "而我們的王，是唯一能夠與神溝通的人。王會聆聽神諭，重新為我們帶來神的恩澤。"
  },
  AvgDialog_47177_Content_45 = {
    Text = "到那個時候，所有天災都會消失，死去的親人重獲新生，我們會永遠在這片土地上安居……利莫里亞，將重新成為完美的神國！"
  },
  AvgDialog_47177_Content_46 = {
    Text = "他的喉結滾動著，從神殿的方向收回滿懷希冀的目光。"
  },
  AvgDialog_47177_Content_47 = {
    Text = "不過，王的力量有限，需要子民們的幫助。只有那些精神力足夠強大的人，才有能力成為祭司，去傳達王的旨意，去幫助王。"
  },
  AvgDialog_47177_Content_48 = {
    Text = "像我這樣的普通人，沒有這個天分，做不了什麼，只能眼睜睜看著你們的母親……"
  },
  AvgDialog_47177_Content_49 = {
    Text = "算了算了，今天是好日子，我們不說這些。"
  },
  AvgDialog_47177_Content_50 = {
    Text = "他擦了擦眼角，笑著拍了拍兩個女兒的頭。"
  },
  AvgDialog_47177_Content_51 = {
    Text = "成為祭司，幫助王，拯救利莫里亞，這是至高無上的榮耀。"
  },
  AvgDialog_47177_Content_52 = {
    Text = "感謝王，給了我們這個平凡的家這樣的機會……"
  },
  AvgDialog_47177_Content_53 = {
    Text = "伊諾斯舉起杯子。混濁的液體在杯中搖晃著，散發出劣質酒精的刺鼻氣味。"
  },
  AvgDialog_47177_Content_54 = {
    Text = "利莫里亞的窮人們喜歡這種酒，便宜，濃烈，以低廉的代價帶給他們短暫的慰藉。"
  },
  AvgDialog_47177_Content_55 = {
    Text = "酒精中的雜質會讓他們在第二天醒來時頭痛無比。而對他們而言，宿醉與疼痛是一種可貴的恩賜。"
  },
  AvgDialog_47177_Content_56 = {
    Text = "他一飲而盡。"
  },
  AvgDialog_47177_Content_57 = {
    Text = "薩拉，你的父親沒什麼用，但你的姐姐，是我們整個家族的驕傲！"
  },
  AvgDialog_47177_Content_58 = {
    Text = "來，彌利亞姆，這是你最喜歡吃的煎魚片。老奧納今天剛剛撈上來的！我專門囑咐了他，讓他給我留著。"
  },
  AvgDialog_47177_Content_59 = {
    Text = "爸爸不想給你太多壓力，放手去做就好了，我知道你一定能把事情做好的！"
  },
  AvgDialog_47177_Content_6 = {
    Text = "姐姐，你胃又不舒服了……每次聞到魚的味道都會反胃，唉。"
  },
  AvgDialog_47177_Content_60 = {
    Text = "爸爸只希望，你以後能照顧好自己。如果有什麼不開心的事，就寫信告訴我。"
  },
  AvgDialog_47177_Content_61 = {
    Text = "明天離開了家，下次再吃爸爸做的魚，就不知道是什麼時候啦……"
  },
  AvgDialog_47177_Content_62 = {
    Text = "堆滿魚的盤子放在彌利亞姆的面前。金黃的色澤，濃郁的香味。"
  },
  AvgDialog_47177_Content_63 = {
    Text = "妹妹在微笑。父親在微笑，眼裡泛著淚光。母親似乎也坐在旁邊，向自己微笑。"
  },
  AvgDialog_47177_Content_64 = {
    Text = "她衣衫襤褸，身體殘缺，那雙眼睛圓圓地睜著，和盤子裡的魚一模一樣。"
  },
  AvgDialog_47177_Content_65 = {
    Text = "我會成為祭司……我一定不會讓你失望的，父親。"
  },
  AvgDialog_47177_Content_66 = {
    Text = "彌利亞姆將魚放進嘴裡。她咀嚼，吞嚥。她向家人報以微笑。"
  },
  AvgDialog_47177_Content_7 = {
    Text = "妹妹一邊拍著彌利亞姆的背，一邊搖著頭唉聲嘆氣。"
  },
  AvgDialog_47177_Content_8 = {
    Text = "老婦人般的神情出現在這個十歲的小孩子臉上，逗得彌利亞姆失笑。"
  },
  AvgDialog_47177_Content_9 = {
    Text = "我沒事的，薩拉。"
  },
  AvgDialog_47178_Content_1 = {
    Text = "於深海禱告"
  },
  AvgDialog_47178_Content_100 = {
    Text = "若隱若現的眼睛，似乎越過了這個屋子裡的跟隨者，越過那些巨大的石板門，注視著利莫里亞的芸芸眾生。"
  },
  AvgDialog_47178_Content_101 = {
    Text = "那雙眼裡刻下的，不知是信念，是悲憫，還是倦怠。"
  },
  AvgDialog_47178_Content_12 = {
    Text = "一個濕漉漉的生物從水中竄起，人類的毛髮稀疏地從頭上灑下，覆蓋在那張魚類的臉上。"
  },
  AvgDialog_47178_Content_13 = {
    Text = "它的魚鰓微微張開，滑膩的嘴唇翕動著，異變的聲帶微微震動，發出意義不明的混沌音節。"
  },
  AvgDialog_47178_Content_14 = {
    Text = "人類的四肢上滿是雜亂的鱗片，反射出污穢的光澤，在水面上胡亂拍打著。"
  },
  AvgDialog_47178_Content_16 = {
    Text = "兩塊巨大的水池中，無數長著同樣臉孔的魚臉生物從水中探出身子，瘋狂地拍打著水面，發出怪異的叫聲。"
  },
  AvgDialog_47178_Content_17 = {
    Text = "它們擁擠地堆積在水中，無數雙魚眼圓圓地睜著，毫無情緒地望著彌利亞姆。"
  },
  AvgDialog_47178_Content_19 = {
    Text = "彌利亞姆用盡全力，控制自己沒有吐出來。"
  },
  AvgDialog_47178_Content_2 = {
    Text = "低沉的嗡鳴，像是從遠古響起的呼喚。"
  },
  AvgDialog_47178_Content_20 = {
    Text = "這些就是……"
  },
  AvgDialog_47178_Content_21 = {
    Text = "沒錯，它們就是那些偉大的先行者！我也是第一次見到，原來它們長這樣！"
  },
  AvgDialog_47178_Content_22 = {
    Text = "名為黛博拉的祭司學徒站在彌利亞姆身邊，興奮地拍打著她，絲毫不避諱這是兩人第一次見面。"
  },
  AvgDialog_47178_Content_23 = {
    Text = "傳說，王得到神諭，在利莫里亞化為神國之前，要用神血對子民進行改造，讓子民能夠擁有應對天災的能力。"
  },
  AvgDialog_47178_Content_24 = {
    Text = "這些先行者，為了利莫里亞人的未來，勇敢地提前走出了這一步。"
  },
  AvgDialog_47178_Content_25 = {
    Text = "在我們成為祭司以後，魚人化的儀式，便會由我們來執行了。到時候我肯定會興奮得睡不著覺！"
  },
  AvgDialog_47178_Content_26 = {
    Text = "黛博拉滿心歡喜地向這些魚人們行禮，親切地撫摸著牠們光滑的臉。"
  },
  AvgDialog_47178_Content_27 = {
    Text = "身旁的其他學徒也一樣俯下身，向這些先賢們致敬。彌利亞姆站在原地，看著這一幕。"
  },
  AvgDialog_47178_Content_28 = {
    Text = "“偉大的先行者”……不知道他們的家裡人看到這個樣子，會不會這麼想……"
  },
  AvgDialog_47178_Content_29 = {
    Text = "禱告室就在前方。各位，隨我來。"
  },
  AvgDialog_47178_Content_3 = {
    Text = "刻著浮雕的巨大石板門被某種不知名的力量驅使，向兩邊滑開。外面的光線，無法向門內滲入一丁點。"
  },
  AvgDialog_47178_Content_31 = {
    Text = "石板門無聲關上，隔絕了魚人們的嘶吼以及外部的嘈雜。"
  },
  AvgDialog_47178_Content_32 = {
    Text = "學徒們各自跪在禱告席上，望向前方的祭台，以及祭台後方那尊由人體、王座與觸鬚構成的巨大雕像。"
  },
  AvgDialog_47178_Content_33 = {
    Text = "雕像上的人臉有些模糊，人類的身軀居於巨大的御座與觸鬚之間，形成了強烈的反差。"
  },
  AvgDialog_47178_Content_34 = {
    Text = "這是象徵著王的雕像。"
  },
  AvgDialog_47178_Content_35 = {
    Text = "老人從雕像房間右側走出，擺擺手，阻止了那些想要起身行禮的學徒們。"
  },
  AvgDialog_47178_Content_36 = {
    Text = "禱詞擺在你們面前。閱讀它，頌念它。最重要的是，相信它。"
  },
  AvgDialog_47178_Content_37 = {
    Text = "主祭大人，做到這些，我們就能為王提供幫助了嗎？"
  },
  AvgDialog_47178_Content_39 = {
    Text = "王會告訴你們。禱告吧。"
  },
  AvgDialog_47178_Content_4 = {
    Text = "濃烈、純粹的黑暗，從門內向眾人發出邀請。"
  },
  AvgDialog_47178_Content_40 = {
    Text = "老人離開了房間，內部只剩一位祭司和幾名侍衛。"
  },
  AvgDialog_47178_Content_41 = {
    Text = "禱告室內的光線變得昏暗，前方的雕像閃爍著神秘的暗淡光澤。"
  },
  AvgDialog_47178_Content_42 = {
    Text = "彌利亞姆拿起身前的禱文。"
  },
  AvgDialog_47178_Content_44 = {
    Text = "紙上寫著的並不是利莫里亞的通用語，那是一種複雜的象形符號，擁有比現實空間更多的維度。"
  },
  AvgDialog_47178_Content_45 = {
    Text = "那符號來自遠古、甚或是來自另一個世界，彌利亞姆從未見過。但閱讀這符號時，其間的含義卻自動進入了她腦海。"
  },
  AvgDialog_47178_Content_46 = {
    Text = "每個文字都包含著巨大的資訊量，無數的經文竄進彌利亞姆的大腦，讓那個脆弱的人類頭顱難堪重負。"
  },
  AvgDialog_47178_Content_47 = {
    Text = "<Shake:頭……頭好痛……>"
  },
  AvgDialog_47178_Content_48 = {
    Text = "身邊不時有人倒下。彌利亞姆強忍著疼痛，念出了紙上的禱文。"
  },
  AvgDialog_47178_Content_49 = {
    Text = "“在遙遠的黯淡深淵，古老的偉大靈魂沉眠……”"
  },
  AvgDialog_47178_Content_5 = {
    Text = "神殿外部可供普通信徒朝拜，而只有具備成為祭司資質的子民，能來到這裡。"
  },
  AvgDialog_47178_Content_50 = {
    Text = "彌利亞姆以普通的利莫里亞語念出了這些話，但話從她口中說出，卻變成了另一種語言。"
  },
  AvgDialog_47178_Content_51 = {
    Text = "同一個時刻，她的聲音重疊交織，繁複地響起。就如同文字一樣，她的聲音也變成了一種高維度結構，如同從某個人類無從想像的時空中響起。"
  },
  AvgDialog_47178_Content_52 = {
    Text = "“……祂的意志如星辰之網交織，祂在永恆的虛無中候汝入夢……”"
  },
  AvgDialog_47178_Content_53 = {
    Text = "彌利亞姆繼續頌念著。"
  },
  AvgDialog_47178_Content_54 = {
    Text = "不知道什麼時候開始，眼前的世界消失了。"
  },
  AvgDialog_47178_Content_55 = {
    Text = "她置身於深海，不論從哪個方向望去，都只能望見虛無的海水。"
  },
  AvgDialog_47178_Content_56 = {
    Text = "在深海之中，點點亮光如同寰宇星辰散落開。"
  },
  AvgDialog_47178_Content_57 = {
    Text = "彌利亞姆感覺自己也變成了一顆星星，而自己身上的亮光，正在向某處匯集。她向那處望去。"
  },
  AvgDialog_47178_Content_58 = {
    Text = "無數的光線奔湧匯集，在彼處匯成一個模糊的輪廓。那是一個由人體、王座與觸鬚所構成的輪廓。"
  },
  AvgDialog_47178_Content_59 = {
    Text = "那是……王嗎？"
  },
  AvgDialog_47178_Content_6 = {
    Text = "諸位，歡迎來到內殿。歡迎來到王的居所。"
  },
  AvgDialog_47178_Content_61 = {
    Text = "似乎被某個聲音驚擾，他從石座上醒來。隨著他的驚醒，整個虛無的空間似乎都黯淡了一刻。"
  },
  AvgDialog_47178_Content_62 = {
    Text = "在他身後，一個老人的模糊輪廓顯現出來。"
  },
  AvgDialog_47178_Content_63 = {
    Text = "您聽見她的聲音了，吾主。"
  },
  AvgDialog_47178_Content_64 = {
    Text = "利莫里亞的王尚在王座，余隻是繼任者。你不應該這樣稱呼。"
  },
  AvgDialog_47178_Content_65 = {
    Text = "利莫里亞的王，從不由誰坐在王座之上決定。誰距離神明最近，誰即是吾主。"
  },
  AvgDialog_47178_Content_66 = {
    Text = "余不喜歡這個稱謂。"
  },
  AvgDialog_47178_Content_67 = {
    Text = "老國王這一生，曾聆聽過一次神諭。這一句神諭，讓他端坐王座，成為子民的信仰。"
  },
  AvgDialog_47178_Content_68 = {
    Text = "您所聆聽到的神諭，已經超過了利莫里亞無數的先王。而您……尚為孩童。"
  },
  AvgDialog_47178_Content_69 = {
    Text = "您是利莫里亞希望所繫。老國王時日無多，他早已授意。很快，您便將登上王座。您需要習慣這個稱呼，吾主。"
  },
  AvgDialog_47178_Content_7 = {
    Text = "一陣風從封閉著的內殿中吹來，帶著濃烈的深海的腥氣。"
  },
  AvgDialog_47178_Content_70 = {
    Text = "年幼的男孩疲憊地靠在椅背之上，不再與老人爭論。"
  },
  AvgDialog_47178_Content_71 = {
    Text = "第一次禱告，便能與余相連，目睹余的身影。群星所昭示之人，便是她嗎？"
  },
  AvgDialog_47178_Content_72 = {
    Text = "是她，我已經查驗過。若群星所示沒有錯，她……便是利莫里亞的未來。"
  },
  AvgDialog_47178_Content_73 = {
    Text = "你並不這樣想。"
  },
  AvgDialog_47178_Content_74 = {
    Text = "有天賦，但有雜念。她無法為您提供幫助，吾主。"
  },
  AvgDialog_47178_Content_75 = {
    Text = "她並不相信禱文，不相信您，也不相信利莫里亞的未來。她只相信她的家人。"
  },
  AvgDialog_47178_Content_76 = {
    Text = "彌利亞姆是一個活在真實中的人。這樣的人，是無法承擔利莫里亞的命運的。"
  },
  AvgDialog_47178_Content_77 = {
    Text = "生活在真實而非虛妄裡，這正是余的希冀。"
  },
  AvgDialog_47178_Content_78 = {
    Text = "利莫里亞的命運……沒有人應該去承擔。"
  },
  AvgDialog_47178_Content_79 = {
    Text = "美好的願望，吾主。可生於利莫里亞，我們都有自己應去承擔的職責。"
  },
  AvgDialog_47178_Content_8 = {
    Text = "跟隨著祭司的腳步進入內殿，黑暗奇異地消失，不知道是何處而來的光線，照亮了那條長得似乎永無盡頭的鵝卵石路。"
  },
  AvgDialog_47178_Content_80 = {
    Text = "我們無從選擇。無論是她，是我，還是您，都一樣。"
  },
  AvgDialog_47178_Content_81 = {
    Text = "……無聊。余要休息了。"
  },
  AvgDialog_47178_Content_82 = {
    Text = "他揮了揮手。老人向他躬身行禮，消失在了無邊的虛無中。"
  },
  AvgDialog_47178_Content_83 = {
    Text = "入睡之前，他望了一眼那些將光亮獻予他的人們。一聲無人聽聞的嘆息，消失在無垠的虛空裡。"
  },
  AvgDialog_47178_Content_85 = {
    Text = "緊接著一陣令人心悸的墜落感的，是一道強烈的刺痛。"
  },
  AvgDialog_47178_Content_86 = {
    Text = "痛楚並沒有持續很久。彌利亞姆離開了那個虛無的空間，環視著身邊。"
  },
  AvgDialog_47178_Content_87 = {
    Text = "一些無法閱讀或頌唸禱文的人已經被請出了禱告室，剩下一小半的人，一些痛苦地倒在地上，另外還有一些正閉眼禱唸著，臉上露出幸福的笑容。"
  },
  AvgDialog_47178_Content_88 = {
    Text = "黛博拉坐在她旁邊，面帶微笑緩緩睜開眼。看到彌利亞姆的樣子，她露出關切的神情。"
  },
  AvgDialog_47178_Content_89 = {
    Text = "喂，彌利亞姆？你還好嗎？"
  },
  AvgDialog_47178_Content_9 = {
    Text = "路的兩頭，是兩方巨大的水池。彌利亞姆靠近水池，向裡微微探頭。"
  },
  AvgDialog_47178_Content_90 = {
    Text = "頭好痛……剛才明明好好的，為什麼我會突然離開了呢？是哪裡出了問題嗎……"
  },
  AvgDialog_47178_Content_91 = {
    Text = "你好像……失敗了。王的夢境拒絕了你。"
  },
  AvgDialog_47178_Content_92 = {
    Text = "可是為什麼……我明明看見了一個輪廓，怎麼突然……"
  },
  AvgDialog_47178_Content_93 = {
    Text = "祭司透過禱文進入王的夢境，為王提供幫助，按理說，能看到王的輪廓可是一件很了不起的事情，只有最有天賦的祭司才能做到呢！"
  },
  AvgDialog_47178_Content_94 = {
    Text = "我也不清楚問題究竟出在哪裡……不過這才是第一次嘛！可能只是還不習慣，以後就好了！"
  },
  AvgDialog_47178_Content_95 = {
    Text = "謝謝你……"
  },
  AvgDialog_47178_Content_96 = {
    Text = "客氣什麼~好好加油！這個禱文是每個祭司都需要掌握的，以後不管是禱告還是魚人化儀式，都需要用這個禱文和王建立連接。"
  },
  AvgDialog_47178_Content_97 = {
    Text = "以後我們一起留在神殿，成為王的祭司，讓利莫里亞重新變成神國！"
  },
  AvgDialog_47178_Content_98 = {
    Text = "朋友的善意沖淡了彌利亞姆的虛弱感。準備起身離開的時候，她再次望了一眼前方的雕像。精神維度中見到的光影與雕像重疊起來。"
  },
  AvgDialog_47178_Content_99 = {
    Text = "模糊的身姿斜坐於王座之上，面部被那些象徵著偉力的觸鬚所遮擋。"
  },
  AvgDialog_47232_Content_1 = {
    Text = "前方管制區域，無關人等不得擅入。請出示身分證明。"
  },
  AvgDialog_47232_Content_10 = {
    Text = "願銀鑰指引我們。"
  },
  AvgDialog_47232_Content_2 = {
    Text = "彌薩格大學調查員威廉·德拉普爾，銀鑰ID I-2083。"
  },
  AvgDialog_47232_Content_5 = {
    Text = "他的眼神，好像在看什麼赴死之人……"
  },
  AvgDialog_47232_Content_6 = {
    Text = "融災禁區內的精神維度混沌異常，我們往往需要<Yellow:同步面對複數個精神戰場>，對精神的傷害遠大於肉體。"
  },
  AvgDialog_47232_Content_7 = {
    Text = "為壓制融災禁區而精神失常的調查員不在少數，你們也要注意平衡各分戰場的資源分配，避免最壞的結果。"
  },
  AvgDialog_47232_Content_8 = {
    Text = "後視鏡中，值守的警衛向你們脫帽致意。"
  },
  AvgDialog_47232_Content_9 = {
    Text = "願銀鑰指引前路。"
  },
  AvgDialog_47798_Content_1 = {
    Text = "我們這麼偷溜進來真的可以嗎？茜爾維婭女士……這可是她的辦公室。"
  },
  AvgDialog_47798_Content_10 = {
    Text = "嚐嚐看？"
  },
  AvgDialog_47798_Content_11 = {
    Text = "墨菲捻起一塊牛奶巧克力，低著頭沉默不語。心理諮詢室陷入了一種恐怖的死寂，讓你忍不住打了個寒顫。"
  },
  AvgDialog_47798_Content_12 = {
    Text = "難、難道你不愛吃巧克力嗎？還是說你對可可豆過敏？"
  },
  AvgDialog_47798_Content_13 = {
    Text = "我們去學校咖啡廳再找點其他東西吧！雖然這個時間廚師已經休息了，但我們可以自己試著做點什麼——唔！"
  },
  AvgDialog_47798_Content_14 = {
    Text = "沒等你反應過來，一顆牛奶巧克力被塞進了嘴裡。"
  },
  AvgDialog_47798_Content_15 = {
    Text = "她抽身而去時，冰涼的指腹從你的舌尖擦過。下一秒，醇厚濃郁的可可香在口腔爆發，滑進了肚子裡。"
  },
  AvgDialog_47798_Content_16 = {
    Text = "我可沒說不要吃——"
  },
  AvgDialog_47798_Content_17 = {
    Text = "墨菲說著，從禮盒裡挑出了顏色最深的一顆巧克力。純度極高，看上去沒有額外添加任何糖——"
  },
  AvgDialog_47798_Content_19 = {
    Text = "見她整張臉都扭曲了起來，你連忙又拿了一塊牛奶巧克力給她。"
  },
  AvgDialog_47798_Content_2 = {
    Text = "沒關係。茜爾維婭小姐說過，心理諮詢室裡的甜食我隨時都可以取用。"
  },
  AvgDialog_47798_Content_20 = {
    Text = "謝、謝謝啦……"
  },
  AvgDialog_47798_Content_21 = {
    Text = "心理諮詢室有全套茶具，你們泡了一壺淡淡的紅茶，有一搭沒一搭地聊著天。"
  },
  AvgDialog_47798_Content_22 = {
    Text = "直到墨菲吃掉最後一塊牛奶巧克力，意猶未盡地舔起了手指，你才看向牆上的掛鐘。"
  },
  AvgDialog_47798_Content_23 = {
    Text = "我待會要去執行任務了，半夜吃了甜食，躺下休息前記得刷牙。"
  },
  AvgDialog_47798_Content_24 = {
    Text = "執行任務？這麼晚？"
  },
  AvgDialog_47798_Content_25 = {
    Text = "還是因為勒姆瓦希異變的影響，整個彌薩格大學都忙得團團轉。\n走吧，我先送你回房間。"
  },
  AvgDialog_47798_Content_26 = {
    Text = "你先往外走了一步，下一秒，你猝不及防地被絆倒在了地上。"
  },
  AvgDialog_47798_Content_27 = {
    Text = "啊？！對、對不起。"
  },
  AvgDialog_47798_Content_28 = {
    Text = "墨菲手忙腳亂地扶起了你，你低頭向下看，才發現一根暗紅色的觸肢正緊緊勾著你的腿。"
  },
  AvgDialog_47798_Content_29 = {
    Text = "那是墨菲裙裝的一部分，或者說是她「身體」的一部分。"
  },
  AvgDialog_47798_Content_3 = {
    Text = "要真是這樣的話，我們也不用翻窗進來了吧？"
  },
  AvgDialog_47798_Content_30 = {
    Text = "你……現在一定要走嗎？"
  },
  AvgDialog_47798_Content_31 = {
    Text = "因為勒姆瓦希聖河的影響，世界各地的密境都出現了異常。"
  },
  AvgDialog_47798_Content_32 = {
    Text = "二年級調查員小隊一整夜都在巡邏，我和他們約好了早上八點去接手東區的密境巡查。"
  },
  AvgDialog_47798_Content_33 = {
    Text = "異常……"
  },
  AvgDialog_47798_Content_34 = {
    Text = "我、我感覺……我也……有點異常……"
  },
  AvgDialog_47798_Content_35 = {
    Text = "不舒服嗎？是不是有發熱？"
  },
  AvgDialog_47798_Content_36 = {
    Text = "說著你摘下手套，伸手去探她的額頭。墨菲卻猛地撤了一步，躲開了你的手——但觸肢卻始終繞在你的腿上。"
  },
  AvgDialog_47798_Content_37 = {
    Text = "我記得讓司機送你去東區只要半個小時，沒有必要這麼早出發。"
  },
  AvgDialog_47798_Content_38 = {
    Text = "作為……的回報，本小姐白天會陪你一起巡邏……"
  },
  AvgDialog_47798_Content_39 = {
    Text = "總、總之……陪我到天亮就好……"
  },
  AvgDialog_47798_Content_4 = {
    Text = "……沒關係，反正茜爾維婭小姐不在學校。為了平息勒姆瓦希事件帶來的影響，她和其他調查員一起組隊去了倫蒂尼恩市區。"
  },
  AvgDialog_47798_Content_6 = {
    Text = "從心理諮詢室的甜品櫃裡，你拿出了一個精緻的禮盒——"
  },
  AvgDialog_47798_Content_7 = {
    Text = "這個牌子的巧克力……"
  },
  AvgDialog_47798_Content_8 = {
    Text = "燙金包裝紙平整妥帖，連裝飾綢帶上都繡了一圈銀線，足以證明這份巧克力禮盒的價值不菲。"
  },
  AvgDialog_47798_Content_9 = {
    Text = "可可的苦香，在綢帶解開的瞬間就迫不及待溢了出來。"
  },
  AvgDialog_47803_Content_1 = {
    Text = "呵…彌薩格的小守密人，居然真的賞臉光臨寒舍了。\n我這間小小的工作室，因您的到來而蓬蓽生輝。"
  },
  AvgDialog_47803_Content_11 = {
    Text = "噓，噓……安靜地讓我看看。"
  },
  AvgDialog_47803_Content_12 = {
    Text = "她停下了揮舞刻刀，用尖端抵在你的臉上來回摩挲、"
  },
  AvgDialog_47803_Content_13 = {
    Text = "你知道嗎，每個藝術家都有獨一無二的繆斯。"
  },
  AvgDialog_47803_Content_14 = {
    Text = "卡圖盧斯有他的萊斯比亞，彼特拉克有深愛的勞拉……"
  },
  AvgDialog_47803_Content_15 = {
    Text = "那雙深不可測的眼睛裡沒有半分兇惡暴戾，反而填滿了一些你難以形容的情感——"
  },
  AvgDialog_47803_Content_16 = {
    Text = "而我現在，也有我的<Blue:卡米耶>。你說對嗎？守密人閣下。"
  },
  AvgDialog_47803_Content_2 = {
    Text = "你推開堆在門邊的雕塑材料，艱難地擠進了珊位於彌薩格側翼西樓的工作室。"
  },
  AvgDialog_47803_Content_3 = {
    Text = "雕塑藝術家坐在珊瑚底座上，刻刀在她指間翻飛，看得人心驚肉跳——那刻刀太鋒利了，足夠削掉她的手指。"
  },
  AvgDialog_47803_Content_4 = {
    Text = "不是你和看守的調查員說，想要見我一面的麼？"
  },
  AvgDialog_47803_Content_5 = {
    Text = "喚醒體們在校內享有規則限度內的絕對自由，但珊是個例外——基於她在濟貧院所犯下的罪行，她不被允許獨自行動。"
  },
  AvgDialog_47803_Content_6 = {
    Text = "啊……確實如此。您看，都是靈感的缺失，讓我的腦子也塞滿了珊瑚。"
  },
  AvgDialog_47803_Content_7 = {
    Text = "請您再靠近我一些，讓我再看清一次你的眼睛……讓我這無法離開房間的可憐人，透過你的眼睛看看世界。"
  },
  AvgDialog_47803_Content_8 = {
    Text = "理由如此冠冕堂皇，你一時間無法找出拒絕她的理由，只好向她靠近——"
  },
  AvgDialog_47803_Content_9 = {
    Text = "珊猛地扯住了校服披風，讓你的臉猛地湊到了她跟前。"
  },
  AvgDialog_47807_Content_1 = {
    Text = "不散的濃霧籠罩著睡夢中的感官，綿延的黑暗看似風平浪靜，黑色巨浪實際已經翻湧著衝撞上了精神的壁壘。"
  },
  AvgDialog_47807_Content_10 = {
    Text = "希萊斯特揮動羅盤，將你按在了床上。"
  },
  AvgDialog_47807_Content_11 = {
    Text = "她指了指窗外高懸的滿月，又指了指你——"
  },
  AvgDialog_47807_Content_12 = {
    Text = "……噩夢。"
  },
  AvgDialog_47807_Content_13 = {
    Text = "我在，就不會有噩夢。"
  },
  AvgDialog_47807_Content_14 = {
    Text = "你的呼吸和她撫弄被褥的輕柔節奏逐漸合拍，每次呼吸都像與風的合奏。意識再度開始下沉，沉入又一個夢境。"
  },
  AvgDialog_47807_Content_15 = {
    Text = "又一個溫柔、輕柔的，能駛向寧靜黎明的夢境。"
  },
  AvgDialog_47807_Content_2 = {
    Text = "時至今日，聖河與巨樹的影響仍纏繞著你。"
  },
  AvgDialog_47807_Content_3 = {
    Text = "過往的記憶在夢中凝結成一個個易碎的泡泡，你的每一次輾轉反側，都讓它們如水月鏡花般觸之即散。"
  },
  AvgDialog_47807_Content_4 = {
    Text = "無秩序的黑暗拽著你沉入意識的最深處，就在你感覺墜落得粉身碎骨的前一刻，微弱的輕風吹進了你的夢。"
  },
  AvgDialog_47807_Content_5 = {
    Text = "風似乎有顏色，既讓人無法忽視，卻也不張揚。它像一位虛弱的守護者，用它的存在證明著你不會在夢中迷失——"
  },
  AvgDialog_47807_Content_6 = {
    Text = "睜開眼的瞬間，你與「守夢人」對上了視線。"
  },
  AvgDialog_47807_Content_7 = {
    Text = "希萊斯特……你怎麼在這兒？"
  },
  AvgDialog_47807_Content_8 = {
    Text = "緘默的喚醒體點了點頭，坐在了你的床沿上，柔軟的床墊因重量而微微下陷。"
  },
  AvgDialog_47807_Content_9 = {
    Text = "是任務出現意外情況了嗎？我馬上——"
  },
  AvgDialog_47808_Content_1 = {
    Text = "法洛思，你在看什麼？"
  },
  AvgDialog_47808_Content_10 = {
    Text = "法洛思的光芒閃爍了幾下。"
  },
  AvgDialog_47808_Content_11 = {
    Text = "未曾，等我長到足夠參加聚會的年紀時，利莫里亞已經陷入天災的包圍中了。"
  },
  AvgDialog_47808_Content_13 = {
    Text = "守密人，你願意今晚留在這裡陪我嗎？"
  },
  AvgDialog_47808_Content_14 = {
    Text = "就當是……聽一個瘋子講故事。一夜，只要一夜就好……"
  },
  AvgDialog_47808_Content_2 = {
    Text = "你遠遠就看見了法洛思，她在夜晚實在過於“亮眼”。在萬籟俱寂的沙海中，更是唯一不同於天體的光芒。"
  },
  AvgDialog_47808_Content_4 = {
    Text = "在她的幫助下，你爬上了沙丘。沙漠夜晚寒冷而乾燥的風迎面而來，猶如刀片滾在臉上。"
  },
  AvgDialog_47808_Content_5 = {
    Text = "身為深海界域的喚醒體，法洛思身上的衣裙往往透著一股濕意。可現在，就連她的觸肢都因乾燥而顯得無精打采。"
  },
  AvgDialog_47808_Content_6 = {
    Text = "我在看……這條河流。"
  },
  AvgDialog_47808_Content_7 = {
    Text = "它讓我想起了利莫里亞。我的故國也曾被這樣一條偉大的河流哺育著。"
  },
  AvgDialog_47808_Content_8 = {
    Text = "在一切災難發生前，青年們每年夏夜都會聚在河岸邊……為了結識一生的伴侶，為了組建新的家庭。"
  },
  AvgDialog_47808_Content_9 = {
    Text = "聽起來會很熱鬧。法洛思呢？你也參加過夏夜聚會嗎？"
  },
  AvgDialog_47977_Content_10 = {
    Text = "好了，言歸正傳。這次行動是為了觀察掃描「24」顱內的意識活動，為後續治療提供參考。"
  },
  AvgDialog_47977_Content_11 = {
    Text = "別去不該去的地方，除非你想永遠被困在別人的腦子裡。"
  },
  AvgDialog_47977_Content_12 = {
    Text = "千萬別偷懶，也不要睡著！"
  },
  AvgDialog_47977_Content_13 = {
    Text = "<Shake:我有好幾個同伴就是這樣消失的幾千年過去了我現在都不知道它們是死是活……>"
  },
  AvgDialog_47977_Content_14 = {
    Text = "……我會注意的。"
  },
  AvgDialog_47977_Content_15 = {
    Text = "別擔心，我們會密切關注你的狀態感受。一旦情況有變，行動立刻中止。"
  },
  AvgDialog_47977_Content_16 = {
    Text = "準備好了嗎，%player%？"
  },
  AvgDialog_47977_Content_17 = {
    Text = "你望向眼前縱橫交錯的腔室。它們規律地膨脹、收縮，隆起的部位隨呼吸緩緩起伏，令人想起無邊無際的海洋。"
  },
  AvgDialog_47977_Content_18 = {
    Text = "而你，則是孑然獨立在甲板上的航海者。"
  },
  AvgDialog_47977_Content_19 = {
    Text = "準備好了"
  },
  AvgDialog_47977_Content_2 = {
    Text = "醒了？注意跟隨指示：直走100微米然後右拐再左拐，向上跳躍最後進入第三腦室……"
  },
  AvgDialog_47977_Content_20 = {
    Text = "那就出發吧，我們和「24」小姐都很期待你的成果。"
  },
  AvgDialog_47977_Content_3 = {
    Text = "等等，什麼第三腦室——<ShakeBig:嗚哇，我的手？！>"
  },
  AvgDialog_47977_Content_4 = {
    Text = "你本想揉揉眼睛，卻發現自己的四肢變成了柔軟的突觸，緩緩飄動在溫暖的紅色海洋中。"
  },
  AvgDialog_47977_Content_5 = {
    Text = "別害怕，溫柯爾在<Yellow:意識潛遊>的基礎上做了一些小小的迭代。你的意識現在遊離在「24」的腦子裡，感知到的一切都將被傳回遠端終端。"
  },
  AvgDialog_47977_Content_6 = {
    Text = "身體變成圓錐了，頭頂甚至還長了觸角！"
  },
  AvgDialog_47977_Content_7 = {
    Text = "別亂碰！這些觸角是幫助你感知環境的重要器官。在我的母星，它們可是身分的象徵，觸角越長地位越高……"
  },
  AvgDialog_47977_Content_8 = {
    Text = "明白。所以溫柯爾小姐的觸角也很長嗎？"
  },
  AvgDialog_48091_Content_11 = {
    Text = "歇息了不多時，你注意到莉莉仍不斷小心翼翼地瞥著你的胸口，滿臉欲言又止。"
  },
  AvgDialog_48091_Content_12 = {
    Text = "不知為何，那枚銀光閃閃的鑰匙似乎對這個孩子有著異常的吸引力。"
  },
  AvgDialog_48091_Content_13 = {
    Text = "<Gray:在學校裡應該沒關係吧……>"
  },
  AvgDialog_48091_Content_14 = {
    Text = "你猶豫了片刻，還是將銀鑰摘下，塞進她嬌小柔弱的手心。"
  },
  AvgDialog_48091_Content_15 = {
    Text = "好涼……"
  },
  AvgDialog_48091_Content_16 = {
    Text = "會太冰了嗎？"
  },
  AvgDialog_48091_Content_17 = {
    Text = "不……涼涼的，很舒服……"
  },
  AvgDialog_48091_Content_18 = {
    Text = "很久以前，莉莉生病的時候，媽媽會抱著莉莉，給莉莉講睡前故事……"
  },
  AvgDialog_48091_Content_19 = {
    Text = "我來給你講吧。"
  },
  AvgDialog_48091_Content_2 = {
    Text = "莉莉伏在你的胸口上，就像你初次在達芙黛爾的小店中迎來清晨那日一樣。"
  },
  AvgDialog_48091_Content_20 = {
    Text = "很久很久以前，在遙遠的高塔上，有一個頭髮很長很長的公主……"
  },
  AvgDialog_48091_Content_21 = {
    Text = "你輕輕地拍著她的背，看著她一點點陷入安恬的睡眠。"
  },
  AvgDialog_48091_Content_22 = {
    Text = "媽媽……"
  },
  AvgDialog_48091_Content_23 = {
    Text = "莉莉趴在你的懷中，安靜地睡著了，呼吸均勻而輕柔。你輕輕扯過薄薄的睡毯，將她和小小的膿皰一起蓋上。"
  },
  AvgDialog_48091_Content_24 = {
    Text = "<Gray:我也，有點困了呢……>"
  },
  AvgDialog_48091_Content_25 = {
    Text = "但現在更重要的，是守護好面前這個小小女孩的幸福時刻。"
  },
  AvgDialog_48091_Content_3 = {
    Text = "與那天不同的是，小小的身軀蜷縮著，臉蛋紅撲撲的。"
  },
  AvgDialog_48091_Content_4 = {
    Text = "主人，莉莉好像發燒了。"
  },
  AvgDialog_48091_Content_5 = {
    Text = "我送你去醫務室。"
  },
  AvgDialog_48091_Content_6 = {
    Text = "莉莉堅決地搖頭，幾個膿皰跟她一起，搖晃得像遊樂園小販手中碰碰撞撞的氣球。"
  },
  AvgDialog_48091_Content_7 = {
    Text = "莉莉不要打針。"
  },
  AvgDialog_48091_Content_8 = {
    Text = "那，要躺下來休息嗎？"
  },
  AvgDialog_48091_Content_9 = {
    Text = "你側過身，在床榻旁為她讓出小小的空間。"
  },
  AvgDialog_48092_Content_1 = {
    Text = "停一下，守密人，我有關鍵的事情要和你商量。"
  },
  AvgDialog_48092_Content_10 = {
    Text = "朵爾徑直拉過你的手，搭在她的腰間。"
  },
  AvgDialog_48092_Content_11 = {
    Text = "還不夠，必須催化慾望的烈度，我才能對入侵思想進行即時定位和追蹤。\n換句話說，在我產生感覺之前，都不要停下來。"
  },
  AvgDialog_48092_Content_12 = {
    Text = "這……不太合適吧……？"
  },
  AvgDialog_48092_Content_13 = {
    Text = "沒有比讓異常思想停留在我腦海中更不合適的事情了。\n對你來說，這也是難得的體驗吧？"
  },
  AvgDialog_48092_Content_14 = {
    Text = "她的雙眼直勾勾地看著你，你感覺自己像被獵豹盯上的無處可逃的可憐兔子。"
  },
  AvgDialog_48092_Content_15 = {
    Text = "只是任務，只是任務……"
  },
  AvgDialog_48092_Content_16 = {
    Text = "說服著自己，你將嘴唇湊了上去。\n腦缸冰冷的觸感讓你的呼吸一窒。"
  },
  AvgDialog_48092_Content_17 = {
    Text = "朵爾的瞳孔中閃爍著點點火光，你能感覺她的身體在喜悅中顫抖。"
  },
  AvgDialog_48092_Content_19 = {
    Text = "接下來，該執行清除工序了。"
  },
  AvgDialog_48092_Content_20 = {
    Text = "在流程完成之前，不要鬆手。"
  },
  AvgDialog_48092_Content_4 = {
    Text = "阿列麥瑟斯文明早已捨棄了肉體和生殖慾望，這類腐朽落後的思想只要出現在我的腦海中，就一定是源於外界的入侵。"
  },
  AvgDialog_48092_Content_5 = {
    Text = "需要我為你做些什麼嗎？"
  },
  AvgDialog_48092_Content_6 = {
    Text = "過來，擁抱我。"
  },
  AvgDialog_48092_Content_8 = {
    Text = "儘管有些不適應，你還是依言抱住了朵爾嬌小的身軀，柔軟蜷曲的髮絲拂過你的鼻尖，有些難耐的微癢。"
  },
  AvgDialog_48092_Content_9 = {
    Text = "連這點小事都做不好嗎？\n再近一點。"
  },
  AvgDialog_48093_Content_10 = {
    Text = "她小腹中的蠟燭燃燒得異常旺盛，似乎要連她眼底的火光也一同引燃，油亮皮鞭啪啪地將空氣抽出風聲。"
  },
  AvgDialog_48093_Content_11 = {
    Text = "可以的吧，守密人。你跟人家已經親密到了這個地步，人家感受到了你那麼多那麼多——那麼多的愛意~"
  },
  AvgDialog_48093_Content_12 = {
    Text = "唔唔！潘…狄婭！噗呸，冷靜！"
  },
  AvgDialog_48093_Content_13 = {
    Text = "瀕臨狂暴的掙扎給你爭取來了一線生機，你嘴忙口亂把布條吐了出來，下意識地閉上眼準備躲過想像中的抽打……"
  },
  AvgDialog_48093_Content_14 = {
    Text = "但鞭子只是輕輕地停在了你的鼻尖上。"
  },
  AvgDialog_48093_Content_15 = {
    Text = "潘狄婭的眼睛因疑惑而散亂失焦，煩躁又惱怒地抓撓著自己的臉。"
  },
  AvgDialog_48093_Content_16 = {
    Text = "不對，不對，人家想要的感覺不是這個~！"
  },
  AvgDialog_48093_Content_17 = {
    Text = "是要抽守密人的臉嗎，還是用腳狠狠地踩守密人的@2呢，不對不對不對，全都不、對、啦！"
  },
  AvgDialog_48093_Content_18 = {
    Text = "失敗的綁架者惱羞成怒，聖河的影響讓她躁動地胡亂甩著鞭子。"
  },
  AvgDialog_48093_Content_19 = {
    Text = "為什麼想像對守密人@2和@2的時候，人家完~全沒有感受到那股灼熱滾燙的甜美呢？"
  },
  AvgDialog_48093_Content_20 = {
    Text = "和繩子的搏鬥沒能取得勝利，你的大腦已經完全停止運轉，開始自動往外倒出麻木的冷笑話。"
  },
  AvgDialog_48093_Content_21 = {
    Text = "如果你打我感覺不對，要不我打你怎麼樣？"
  },
  AvgDialog_48093_Content_22 = {
    Text = "你還沒來得及為這句話把舌頭嚥下去，潘狄婭的瞳孔驟然放大。"
  },
  AvgDialog_48093_Content_23 = {
    Text = "對啊！我怎麼沒想到呢，人家真正~真正，真正渴望的……！"
  },
  AvgDialog_48093_Content_24 = {
    Text = "她的身體因為極度興奮，開始微微顫抖。"
  },
  AvgDialog_48093_Content_25 = {
    Text = "除了依然在她體內熊熊燃燒的蠟燭以外，屋內所有的亮光都熄滅了。"
  },
  AvgDialog_48093_Content_26 = {
    Text = "月光下，少女掉轉鞭柄，叼住了她的皮鞭，聲音變得黏稠而含混，像亟待品嚐的糖霜…或某種沉重潮濕的陰冷黑暗。"
  },
  AvgDialog_48093_Content_27 = {
    Text = "一聲悶響，束縛你手臂的繩子落下了。"
  },
  AvgDialog_48093_Content_28 = {
    Text = "責罰我吧，鞭笞我吧，蹂躪我吧……"
  },
  AvgDialog_48093_Content_29 = {
    Text = "就像人家贈予其他人一樣，把甜蜜的疼痛也贈予人家~！"
  },
  AvgDialog_48093_Content_3 = {
    Text = "人家好孤獨~好寂寞~身體裡的小火苗一直在燒~"
  },
  AvgDialog_48093_Content_4 = {
    Text = "簡直快要把人家渾身都燃盡了~！你怎麼都不願意回應人家~"
  },
  AvgDialog_48093_Content_5 = {
    Text = "（有沒有可能是因為你堵住了我的嘴啊！）"
  },
  AvgDialog_48093_Content_6 = {
    Text = "彌薩格的教育體系中，沒有任何一堂課教過，要怎麼在這種情況下應對物理意義上「熱情燃燒」的喚醒體。"
  },
  AvgDialog_48093_Content_7 = {
    Text = "而且她已經快要把觸感如蠟油般滑膩的大腿，完全壓坐到你胸口上了。"
  },
  AvgDialog_48093_Content_8 = {
    Text = "（潘狄婭，如果你再不起來，我會在因為你的熱情窒息之前，先因為你的體重窒息。）"
  },
  AvgDialog_48093_Content_9 = {
