  },
  AvgDialog_48238_Content_16 = {
    Text = "那隻手領著你搭在腰間的那一刻，勻稱的身體顫動了一下。"
  },
  AvgDialog_48238_Content_17 = {
    Text = "指腹傳來綢緞冰涼的觸感。綢緞之下，柔軟、緊緻的腰腹隨著呼吸微微起伏著。"
  },
  AvgDialog_48238_Content_18 = {
    Text = "我完全沒有接觸過芭蕾……這樣真的可以嗎？"
  },
  AvgDialog_48238_Content_19 = {
    Text = "跟著音樂，做你想做的事，就好了。"
  },
  AvgDialog_48238_Content_2 = {
    Text = "空無一人的劇院裡，少女搖了搖頭。你聽見她紊亂的呼吸，看見她在暗淡光線下微微發紅的臉頰。"
  },
  AvgDialog_48238_Content_20 = {
    Text = "請記住，芭蕾的秘密，是旋轉。"
  },
  AvgDialog_48238_Content_21 = {
    Text = "從雙手到腰腹，從腰腹到雙腿。舞者帶領著你，完成每一個優雅的動作，感受她身體每一個部位細微的變化。"
  },
  AvgDialog_48238_Content_22 = {
    Text = "踢腿。下腰。跳躍。"
  },
  AvgDialog_48238_Content_23 = {
    Text = "輕靈的音樂在空無一人的劇院迴盪，一道清冷光束追隨著舞台上的你們。"
  },
  AvgDialog_48238_Content_24 = {
    Text = "你們一同旋轉著。莉茲臉色愈發緋紅，綠色的雙眸帶著羞怯望著你。"
  },
  AvgDialog_48238_Content_25 = {
    Text = "我跳得怎麼樣？"
  },
  AvgDialog_48238_Content_26 = {
    Text = "一無是處。但這會是我最喜歡的舞蹈表演，守密人。"
  },
  AvgDialog_48238_Content_27 = {
    Text = "我們要不要轉慢一點？我覺得有點……"
  },
  AvgDialog_48238_Content_28 = {
    Text = "綠色的眼眸輕輕合上，冰冷的雙唇吻住了你。"
  },
  AvgDialog_48238_Content_29 = {
    Text = "旋轉。旋轉。"
  },
  AvgDialog_48238_Content_3 = {
    Text = "本來以為，劇院能讓你心情平靜下來，消除掉聖河的影響。"
  },
  AvgDialog_48238_Content_30 = {
    Text = "白色的髮絲隨風飄揚，翠綠的火焰包裹住你們，沒有任何溫度，隨著音樂一同躍動。黑綠相間的舞蹈服，在空中劃出天鵝般的弧線。"
  },
  AvgDialog_48238_Content_31 = {
    Text = "暈眩。你想說暈眩。"
  },
  AvgDialog_48238_Content_32 = {
    Text = "莉茲越來越沉重的呼吸拍打在你的臉上，你下意識雙臂用力，環住她的腰，沉重的力度讓她微微皺起眉。你們旋轉著。"
  },
  AvgDialog_48238_Content_33 = {
    Text = "請記住，守密人。芭蕾的秘密，是旋轉……"
  },
  AvgDialog_48238_Content_34 = {
    Text = "今夜，劇院的流光下，一對舞者迷失在旋轉裡。"
  },
  AvgDialog_48238_Content_4 = {
    Text = "或許可以做點別的什麼來轉移一下注意力。我想想……"
  },
  AvgDialog_48238_Content_5 = {
    Text = "綠色的眼眸閃動，黑色的裙襬在你面前劃出一道弧線，少女熟練地登上了舞台。"
  },
  AvgDialog_48238_Content_6 = {
    Text = "我以為，你現在對跳舞這件事仍有心結……"
  },
  AvgDialog_48238_Content_7 = {
    Text = "我可沒說要跳。"
  },
  AvgDialog_48238_Content_9 = {
    Text = "我來教你跳舞吧，守密人。"
  },
  AvgDialog_48555_Content_1 = {
    Text = "走過教學樓的又一個轉角，從今早就縈繞著你的低氣壓變得更加嚴重，擠壓得你幾乎無法呼吸。"
  },
  AvgDialog_48555_Content_10 = {
    Text = "球囊在你的掌心發散著微弱的螢光，湧動著磅礴的生命力。"
  },
  AvgDialog_48555_Content_11 = {
    Text = "半透明的囊壁中，形似蟬翼的枝條雙雙合攏，它無規律地不時振翅，彷彿正處於一場綿長的夢境中。"
  },
  AvgDialog_48555_Content_12 = {
    Text = "這是……？"
  },
  AvgDialog_48555_Content_13 = {
    Text = "菲茵特見你沒有拒絕她的禮物，這才長舒一口氣，露出了滿足的笑。"
  },
  AvgDialog_48555_Content_14 = {
    Text = "是我們@2一族的新生種，只要是成熟的我們，都會結出這樣的果實。"
  },
  AvgDialog_48555_Content_15 = {
    Text = "在過去那麼久那麼久的時間裡，我從來沒有發過芽……我原本以為，我永遠都不會成為完整的@2。"
  },
  AvgDialog_48555_Content_16 = {
    Text = "<Small:異常發育……又是勒姆瓦希那邊帶來的影響。>"
  },
  AvgDialog_48555_Content_17 = {
    Text = "菲茵特現在感覺如何呢？發芽以後，身體有沒有其他異常？"
  },
  AvgDialog_48555_Content_18 = {
    Text = "菲茵特搖了搖頭，稚嫩的臉上寫滿欣喜。"
  },
  AvgDialog_48555_Content_19 = {
    Text = "很熱……腦袋、四肢都感覺很熱。或許這就是汀克特說過的，成為大人的感覺？"
  },
  AvgDialog_48555_Content_2 = {
    Text = "你扶牆蹲下，動作之間目光捕捉到了一個熟悉的影子一閃而過。"
  },
  AvgDialog_48555_Content_3 = {
    Text = "……菲茵特？是你嗎？"
  },
  AvgDialog_48555_Content_4 = {
    Text = "白色影子停頓了片刻，最終不再隱藏自己的存在。白色框架載著它的主人飄浮到了你身前。"
  },
  AvgDialog_48555_Content_6 = {
    Text = "她向你伸出手，似乎想要爬出「搖籃」——但離開「搖籃」這個限制器，只會讓她的本能更加肆無忌憚。"
  },
  AvgDialog_48555_Content_7 = {
    Text = "菲茵特很快意識到了自己的異常，於是最終只抿著嘴，擰掉了「搖籃」上最靠近她身體的球囊。"
  },
  AvgDialog_48555_Content_8 = {
    Text = "請收下……收下這個。"
  },
  AvgDialog_48555_Content_9 = {
    Text = "你伸出手，取球囊時指尖觸到了她柔軟的掌心。菲茵特立刻渾身一顫，蜷縮著躲進了搖籃的更深處。"
  },
  AvgDialog_48556_Content_1 = {
    Text = "守密人，如果方便的話，您是否現在能為我稍加駐足？"
  },
  AvgDialog_48556_Content_10 = {
    Text = "那絕非卡達斯應有的旋律，貫入顳橫回的聲音一如寰宇般幽魅，又閃亮著點點晨星的溫柔。"
  },
  AvgDialog_48556_Content_11 = {
    Text = "意識成為了一艘無舵的船，在汀克特歌聲的牽引下，漂泊向慾望的彼岸。"
  },
  AvgDialog_48556_Content_12 = {
    Text = "唇角印下了冰冷濕潤的觸感，咽喉中竄起無名的暗火。"
  },
  AvgDialog_48556_Content_13 = {
    Text = "再次睜眼，汀克特也正在抬頭，她的嘴唇看起來格外濕潤飽滿。"
  },
  AvgDialog_48556_Content_14 = {
    Text = "一個難以置信的答案在你的嘴邊呼之欲出，但理智很快被再次落在唇邊的吟誦捲走。"
  },
  AvgDialog_48556_Content_15 = {
    Text = "歌聲玩弄著內心深處的不堪慾望，現實與幻想的界限再次模糊，無力抗拒，也無力逃脫。"
  },
  AvgDialog_48556_Content_16 = {
    Text = "噓……只此夜，請成為我歌聲的俘虜……"
  },
  AvgDialog_48556_Content_2 = {
    Text = "當然，最近在學校裡遇上什麼不開心的事情了嗎？"
