  },
  AvgDialog_4883_Content_4 = {
    Text = "他們一定很擔心奧瑞塔，所以奧瑞塔要帶很多很多朋友一起回去！\n要帶小狗、貓咪、烏鴉、守密人……還有奧瑞塔最喜歡的水母！"
  },
  AvgDialog_4883_Content_5 = {
    Text = "這樣他們就知道，奧瑞塔在陸地上的生活也很開心！"
  },
  AvgDialog_4883_Content_6 = {
    Text = "感覺有很多是不適合帶進海裡的生物呢……"
  },
  AvgDialog_4883_Content_7 = {
    Text = "我也是要被帶進海裡的一員嗎"
  },
  AvgDialog_4883_Content_8 = {
    Text = "嗯！嗯嗯！守密人是奧瑞塔的夥伴！莉莉也要來！"
  },
  AvgDialog_4884_Content_1 = {
    Text = "在卡茜亞的帶領下，你們停在了倫蒂尼恩最大百貨公司的門口，被熙熙攘攘的顧客包圍。"
  },
  AvgDialog_4884_Content_10 = {
    Text = "差點忘記了，是兩個悶罐子。"
  },
  AvgDialog_4884_Content_11 = {
    Text = "卡茜亞退到眾人身後，把一直沉默著的莉莉推到了人前。"
  },
  AvgDialog_4884_Content_12 = {
    Text = "達芙黛爾夫人，早上好。"
  },
  AvgDialog_4884_Content_13 = {
    Text = "早上好，我的小客人。讓我猜猜這一次，你們是為何而來……"
  },
  AvgDialog_4884_Content_14 = {
    Text = "「能記錄喚醒體影像的膠片」……我的確能為客人們找到這樣的物件。"
  },
  AvgDialog_4884_Content_15 = {
    Text = "你怎麼知道？不會又派了什麼人跟蹤我們吧？！"
  },
  AvgDialog_4884_Content_16 = {
    Text = "我怎麼能預知各位會不慎弄壞珍貴的膠片呢？"
  },
  AvgDialog_4884_Content_17 = {
    Text = "達芙黛爾噙著一抹神秘莫測的笑，將你們想要的東西擺上了櫃檯。"
  },
  AvgDialog_4884_Content_18 = {
    Text = "經高純度銀芯源液處理，能夠正常留影喚醒體樣貌的膠片，非常珍貴。小店目前僅此一份哦。"
  },
  AvgDialog_4884_Content_19 = {
    Text = "不是說特殊膠片是<Yellow:朵爾的新研究>嗎，你又是從哪搞來的？"
  },
  AvgDialog_4884_Content_2 = {
    Text = "這也太熱鬧了吧，那女人怎麼把店停在這種地方？"
  },
  AvgDialog_4884_Content_20 = {
    Text = "穿行維度的商人，自有特殊的渠道。\n別用這種懷疑的眼神看著我，我可是會傷心的哦。"
  },
  AvgDialog_4884_Content_21 = {
    Text = "如何？不需要的話我就收起來了。"
  },
  AvgDialog_4884_Content_22 = {
    Text = "好，我們要了。"
  },
  AvgDialog_4884_Content_23 = {
    Text = "莉莉捏了捏你的手，眼裡寫著幾分不安。"
  },
  AvgDialog_4884_Content_24 = {
    Text = "交換商店……要給夫人報酬。"
  },
  AvgDialog_4884_Content_25 = {
    Text = "呀，莉莉還記得我這兒的規矩。"
  },
  AvgDialog_4884_Content_26 = {
    Text = "放心，這次我要的不多——我想要看“故事”。"
  },
  AvgDialog_4884_Content_27 = {
    Text = "一個精彩的、圓滿的、不留遺憾的故事。\n這就是我想要交換的東西。"
  },
  AvgDialog_4884_Content_3 = {
    Text = "“想要藏好一張方塊6，就把它洗進一副牌裡”。"
  },
  AvgDialog_4884_Content_4 = {
    Text = "卡茜亞將你們領到了百貨公司旁，帶頭推開了店門。\n一陣紫煙把眾人拉了進來。"
  },
  AvgDialog_4884_Content_5 = {
    Text = "歡迎再次光臨我的“交換商店”，我尊貴的客人們，還有……"
  },
  AvgDialog_4884_Content_6 = {
    Text = "還有我可愛的“員工”。\n彌薩格的生活如何，你有學習到真實的情感嗎？"
  },
  AvgDialog_4884_Content_7 = {
    Text = "多謝夫人的慷慨，但從嘰嘰喳喳的小老鼠、什麼都不懂的單細胞生物、自大暴力狂和悶罐子身上，確實沒什麼好學習的。"
  },
  AvgDialog_4884_Content_8 = {
    Text = "誰嘰嘰喳喳了？！"
  },
  AvgDialog_4884_Content_9 = {
    Text = "悶罐子……是在說我嗎？"
  },
  AvgDialog_4885_Content_2 = {
    Text = "住手！放開那個女孩！"
  },
  AvgDialog_4885_Content_3 = {
    Text = "哦？莫非您就是大名鼎鼎的……<Blue:倫蒂尼恩警局花園分局的探長G>。"
  },
  AvgDialog_4885_Content_4 = {
    Text = "沒、沒錯。我就是<Blue:倫蒂尼恩警局花局長…唔！>"
  },
  AvgDialog_4885_Content_5 = {
    Text = "過於拗口的稱號讓探長咬到了舌頭，但這並不會影響他拯救無辜市民的決心。"
  },
  AvgDialog_4885_Content_6 = {
    Text = "我會將她從你邪惡的計劃中拯救出來！接受制裁吧！邪術師霍迪妮！"
  },
  AvgDialog_4886_Content_2 = {
    Text = "<Small:壞掉了……>"
  },
  AvgDialog_4886_Content_3 = {
    Text = "再來再來！卡茜亞也玩得很開心吧！"
  },
  AvgDialog_4886_Content_4 = {
    Text = "沒禮貌的傢伙！我要撕碎你！讓你在電影世界再無立足之地！"
  },
  AvgDialog_4886_Content_5 = {
    Text = "噓，噓！別再刺激卡茜亞小姐了。"
  },
  AvgDialog_4886_Content_6 = {
    Text = "注意力全被混亂的戰鬥所吸引，小聲的驚呼並沒有引起關注。"
  },
  AvgDialog_4886_Content_7 = {
    Text = "莉莉深吸了一口氣，用盡全力大喊出聲。"
  },
  AvgDialog_4886_Content_8 = {
    Text = "壞掉了……<BigShake:機器壞掉了！>"
  },
  AvgDialog_4887_Content_1 = {
    Text = "護工熟稔地按倒發狂的病人，三兩下就用皮扣束住了病人的手腳。\n完事後才想起還有外人在，有些不好意思地撓了撓頭。"
  },
  AvgDialog_4887_Content_10 = {
    Text = "那裡存在著常人不可見的大片融蝕漿——或許，這正是瘋狂的源頭。"
  },
  AvgDialog_4887_Content_2 = {
    Text = "你們小心點，今天病人瘋得特別厲害，別被他們傷到了。"
  },
  AvgDialog_4887_Content_3 = {
    Text = "集體發瘋？這種事經常出現嗎？"
  },
  AvgDialog_4887_Content_4 = {
    Text = "會被拋棄到療養院的人，精神脆弱得像曬過七天七夜的紙，風一吹就碎了。突然的集體瘋狂在這兒並不稀奇。"
  },
  AvgDialog_4887_Content_5 = {
    Text = "走吧，負責人應該就在這層。"
  },
  AvgDialog_4887_Content_6 = {
    Text = "誒！小心！"
  },
  AvgDialog_4887_Content_7 = {
    Text = "你猛地推了一把護工，後者踉蹌了兩步，滿臉疑惑地看向你。"
  },
  AvgDialog_4887_Content_8 = {
    Text = "那有點水漬，咱們靠著走廊的邊走過去吧。"
  },
  AvgDialog_4887_Content_9 = {
    Text = "護工沒多問什麼，繞開了你指出的方向。只有你暗自鬆了一口氣。"
  },
  AvgDialog_4888_Content_1 = {
    Text = "保安隊，你們協助艾莉女士把院子裡的病人帶回病房。\n黛西，你去準備病人的安撫用品和洗漱用具。"
  },
  AvgDialog_4888_Content_10 = {
    Text = "多謝您把遠道而來的故人帶到我的面前。"
  },
  AvgDialog_4888_Content_11 = {
    Text = "說“謝謝”就太客套了，那我們先去處理病區的事故了。"
  },
  AvgDialog_4888_Content_12 = {
    Text = "醫護們紛紛向寧菲亞示意，得到她的首肯後才一一離開了辦公室。"
  },
  AvgDialog_4888_Content_13 = {
    Text = "看來在地獄犬事件後，你在這裡過得不錯。"
  },
  AvgDialog_4888_Content_14 = {
    Text = "託您和拉蒙娜小姐的福，療養院才能平穩順利地運行下來。"
  },
  AvgDialog_4888_Content_15 = {
    Text = "深夜前來拜訪，是發生什麼事了嗎？"
  },
  AvgDialog_4888_Content_16 = {
    Text = "你向面容蒼白的少女解釋了一番，有關拍攝，有關劇本，有關莉莉……"
  },
  AvgDialog_4888_Content_17 = {
    Text = "原來如此…想要創作故事嗎？\n我不會寫詩，也不會寫劇本，但我看過足夠多的故事。"
  },
  AvgDialog_4888_Content_18 = {
    Text = "寧菲亞閉上了眼，吟誦一般娓娓道來。"
  },
  AvgDialog_4888_Content_19 = {
    Text = "最重要的，莫過於<Yellow:傾聽>吧？\n傾聽內心的聲音，跟隨情感的水流……它們會帶你找到答案。"
  },
  AvgDialog_4888_Content_2 = {
    Text = "傑克遜先生，你……去幫忙把馬鈴薯切進咖哩裡吧，不要浪費了。"
  },
  AvgDialog_4888_Content_20 = {
    Text = "莉莉似懂非懂地傾聽、思考著，試圖理解寧菲亞的話。"
  },
  AvgDialog_4888_Content_21 = {
    Text = "談話之間，含糊不清的哀嚎從樓下傳來。本來在認真思考的莉莉也被嚇了一跳，猛地撞上了寧菲亞的腿。"
  },
  AvgDialog_4888_Content_22 = {
    Text = "他聽起來好像很痛苦……"
  },
  AvgDialog_4888_Content_23 = {
    Text = "這裡的病人，病情會不規律地突然惡化，通常半天後就會恢復正常……\n讓你們見笑了。"
  },
  AvgDialog_4888_Content_24 = {
    Text = "您可以聯繫彌薩格大學，請求協助調查原因。德克斯特勳爵應該有留下聯繫方式。"
  },
  AvgDialog_4888_Content_25 = {
    Text = "我知道異變發生的原因，恐怕，這是連彌薩格也無法解決的難題。"
  },
  AvgDialog_4888_Content_26 = {
    Text = "我也要去幫忙“清理”了，您想要和我一起來嗎？"
  },
  AvgDialog_4888_Content_3 = {
    Text = "有人看見羅伯特先生了嗎？有人去找他了嗎，我記得他今晚負責第二病區的看護……"
  },
  AvgDialog_4888_Content_4 = {
    Text = "我在這兒，寧菲亞小姐。"
  },
  AvgDialog_4888_Content_5 = {
    Text = "有條不紊安排著醫護工作的，正是與你有過一面之緣的寧菲亞。\n看見你出現在療養院，她的臉上也出現了驚訝的表情。"
  },
  AvgDialog_4888_Content_6 = {
    Text = "是你……還有莉莉。"
  },
  AvgDialog_4888_Content_7 = {
    Text = "寧菲亞姐姐。"
  },
  AvgDialog_4888_Content_8 = {
    Text = "你們倆既然認識波洛涅斯小姐怎麼不早說，我還以為是哪裡來的騙子呢。"
  },
  AvgDialog_4888_Content_9 = {
    Text = "寧菲亞低低笑了，牽起了莉莉的手。"
  },
  AvgDialog_4889_Content_1 = {
    Text = "最圓滿的結局"
  },
  AvgDialog_4889_Content_10 = {
    Text = "她看過了畫展、去過了動物園、坐過了地鐵與火車，她們甚至乘船順伊希斯河而下，一路衝進了浩蕩的南洋！"
  },
  AvgDialog_4889_Content_11 = {
    Text = "在經歷過種種冒險後，兩人過起了安寧平靜的生活……但女孩仍保有對未知的好奇和嚮往。"
  },
  AvgDialog_4889_Content_12 = {
    Text = "好奇…是件壞事嗎？"
  },
  AvgDialog_4889_Content_13 = {
    Text = "不不不，絕對是好事。好奇心是驅使文明前進的永恆動力——"
  },
  AvgDialog_4889_Content_14 = {
    Text = "只可惜這一次，女孩對一處神秘的工坊產生了好奇……"
  },
  AvgDialog_4889_Content_15 = {
    Text = "眼神示意卡茜亞"
  },
  AvgDialog_4889_Content_16 = {
    Text = "你對著卡茜亞擠眉弄眼，自被你搶走揚聲器後就一直呆滯著的魔術師這才回過神來。"
  },
  AvgDialog_4889_Content_17 = {
    Text = "怎麼這大魔王又是我來當呢？"
  },
  AvgDialog_4889_Content_18 = {
    Text = "出於對你工作的支持——或者乾脆只是想要惡作劇，雖然嘴上不滿地嘟囔著，但她仍十分配合地再次升起了魔術幻景。"
  },
  AvgDialog_4889_Content_19 = {
    Text = "魔術工坊中亮起了陰森暗詭的光，詭異的光線奪走了屬於生者世界的生機，讓人感覺置身幽冥。"
  },
  AvgDialog_4889_Content_20 = {
    Text = "我是來自死者世界的魔術大師霍迪妮，美麗的小女孩是我最中意的魔術道具——勇敢的冒險者們啊，你們是否有挑戰我的膽量！"
  },
  AvgDialog_4889_Content_21 = {
    Text = "卡、卡茜亞小姐……？"
  },
  AvgDialog_4889_Content_22 = {
    Text = "霍迪妮！魔術大師霍迪妮！你應該被我嚇得嚎啕大哭，失去理智！"
  },
  AvgDialog_4889_Content_23 = {
    Text = "在你和卡茜亞期盼的眼神中，莉莉機械地進行了幾次吞嚥——"
  },
  AvgDialog_4889_Content_24 = {
    Text = "來、來……"
  },
  AvgDialog_4889_Content_25 = {
    Text = "大聲點！哭出來！讓我聽見來自靈魂深處的恐懼！"
  },
  AvgDialog_4889_Content_26 = {
    Text = "<BigShake:來、來人啊！！幫幫我——母親！>"
  },
  AvgDialog_4889_Content_3 = {
    Text = "什麼動靜？！"
  },
  AvgDialog_4889_Content_4 = {
    Text = "蘿坦反射性把小喚醒體們攔在身後，雙手充滿警惕地握緊了劍柄。"
  },
  AvgDialog_4889_Content_5 = {
    Text = "抱歉，我第一次用這個揚聲器。"
  },
  AvgDialog_4889_Content_6 = {
    Text = "還想玩一會兒？"
  },
  AvgDialog_4889_Content_7 = {
    Text = "你搖了搖頭，再次按下了揚聲器的開關，同時也將照明燈再次對準了佈景中央。"
  },
  AvgDialog_4889_Content_8 = {
    Text = "勇敢的女孩和冒險家女士回到了城鎮。冒險家對女孩視如己出，帶她體驗了生活中無數的點點滴滴——"
  },
  AvgDialog_4889_Content_9 = {
    Text = "莉莉的眼睛倏地亮了起來，她睜大了眼，露出難以置信的表情。"
  },
  AvgDialog_4890_Content_1 = {
    Text = "<Change>我不想…離開…家…"
  },
  AvgDialog_4890_Content_3 = {
    Text = "沉重的情緒抓著你的腳踝，將你拖向不可見的深淵，就連呼吸都感到急促。"
  },
  AvgDialog_4890_Content_4 = {
    Text = "胸口好重，莉莉感覺好難受……"
  },
  AvgDialog_4890_Content_5 = {
    Text = "抱歉，讓你感覺不舒服了。"
  },
  AvgDialog_4890_Content_6 = {
    Text = "守密人，請您幫我擊敗她吧。"
  },
  AvgDialog_4891_Content_1 = {
    Text = "年輕的詩人搖了搖頭，語氣憂愁而落寞。她不知何時縮回了信紙之下，流露出絲縷的悲傷。"
  },
  AvgDialog_4891_Content_2 = {
    Text = "被悲傷的陰影所籠罩，我的詩文和靈感…對守密人和莉莉而言，恐怕起不到什麼作用。"
  },
  AvgDialog_4891_Content_3 = {
    Text = "悲傷的……陰影？"
  },
  AvgDialog_4891_Content_4 = {
    Text = "面對莉莉疑惑的表情，奧爾拉微不可聞地嘆了口氣。"
  },
  AvgDialog_4891_Content_5 = {
    Text = "如果可以的話，讓我為你們展示吧……"
  },
  AvgDialog_4891_Content_6 = {
    Text = "奧爾拉推開了房間的門，世界不再被隔絕在外，濃稠凝滯的空氣猛地灌進了房間。"
  },
  AvgDialog_4891_Content_7 = {
    Text = "何為“悲傷的陰影”。"
