  AvgDialog_4893_Content_5 = {
    Text = "不…可能是幻覺吧。"
  },
  AvgDialog_4894_Content_1 = {
    Text = "沒用的傢伙！無能！你們把卡茜亞的群演都打跑了！"
  },
  AvgDialog_4894_Content_10 = {
    Text = "千鈞一髮之際，奧吉爾揮動長槍，將橫衝直撞的兔子打散回了一片虛影。"
  },
  AvgDialog_4894_Content_11 = {
    Text = "討厭！討厭！不配合的傢伙沒有留在卡茜亞導演片場的資格！"
  },
  AvgDialog_4894_Content_12 = {
    Text = "看樣子，不把她打一頓，她是不會停止「情緒模仿」了。\n這回你可沒資格說我什麼「戰鬥狂」了吧？"
  },
  AvgDialog_4894_Content_13 = {
    Text = "以後可得少讓她再看亂七八糟的雜誌了……"
