  AvgDialog_49091_Content_24 = {
    Text = "這種時候，語言太過蒼白。"
  },
  AvgDialog_49091_Content_25 = {
    Text = "就用你的身體……來回答我吧。"
  },
  AvgDialog_49091_Content_3 = {
    Text = "她的目光迷離動亂，將你從髮絲到腳趾尖依次舔舐。"
  },
  AvgDialog_49091_Content_4 = {
    Text = "與你扣合的十指又緊了緊，彷彿擔心你逃跑似的，將你圈在那片充斥情慾溫熱的深域中。"
  },
  AvgDialog_49091_Content_5 = {
    Text = "眼前浩瀚的白色沙海與滿眼璀璨星光交相輝映，令人目眩神迷。"
  },
  AvgDialog_49091_Content_6 = {
    Text = "這片星海會讓你想起什麼？"
  },
  AvgDialog_49091_Content_7 = {
    Text = "你什麼也回憶不起來，玻璃碎片般的記憶之海裡，只有泰旖絲瞳孔中倒映的熠熠星光。"
  },
  AvgDialog_49091_Content_8 = {
    Text = "我會想起亞蘭。"
  },
  AvgDialog_49091_Content_9 = {
    Text = "想起生命的種子匯成大河，再浩浩湯湯地奔赴沙漠的每根毛細血管。"
  },
  AvgDialog_49092_Content_1 = {
    Text = "一塊黑布從你頭上拿開。你揉了揉眼睛。"
  },
  AvgDialog_49092_Content_10 = {
    Text = "下面，請欣賞卡茜亞為您帶來的魔術，《守密人無法忘記的夜晚》……"
  },
  AvgDialog_49092_Content_11 = {
    Text = "一雙調皮的眼睛在你面前忽閃忽閃。似乎有那麼一刻，你看到這位沒心沒肺的大魔術師，臉第一次變紅了。"
  },
  AvgDialog_49092_Content_13 = {
    Text = "沒等你反應過來，一塊黑布重新遮住了你們。暗淡的星光下，一個溫軟的身體靠在了你懷裡。"
