  AvgDialog_49400_Content_19 = {
    Text = "泰旖絲……泰旖絲！"
  },
  AvgDialog_49400_Content_2 = {
    Text = "你和艾爾瓦僵持不下之際，於麗埃特出聲阻攔。"
  },
  AvgDialog_49400_Content_20 = {
    Text = "如果她能出現，如果她能以她的神力，向艾爾瓦昭示亞蘭族的未來。"
  },
  AvgDialog_49400_Content_21 = {
    Text = "哪怕只是出聲辯解，你便不必在此，與艾爾瓦兵刃相向。"
  },
  AvgDialog_49400_Content_22 = {
    Text = "泰旖絲……泰旖絲——！"
  },
  AvgDialog_49400_Content_23 = {
    Text = "無論如何呼喊都無濟於事，你和她最後的對話，停留在對她的指責上。"
  },
  AvgDialog_49400_Content_24 = {
    Text = "已經被融蝕消亡的存在，沒有銀芯的接觸殘留，你根本不可能觸及她的存在分毫。"
  },
  AvgDialog_49400_Content_26 = {
    Text = "怎麼，過去的旅途讓你太過驕傲了嗎？"
  },
  AvgDialog_49400_Content_27 = {
    Text = "還是離開了我就成了哭哭啼啼的沒用的傢伙呢？"
  },
  AvgDialog_49400_Content_28 = {
    Text = "沙漠的寧靜被一陣急促的風聲所打破，天際迅速變得暗沉，彷彿一切亮色都被即將到來的怒濤吞噬。"
  },
  AvgDialog_49400_Content_29 = {
    Text = "沙塵暴如被驚怒的巨獸，呼嘯著席捲而來，卷起千萬噸的細沙，遮天蔽日，將烈日和藍天同歸於盡。"
  },
  AvgDialog_49400_Content_3 = {
    Text = "既然你執意如此。"
  },
  AvgDialog_49400_Content_30 = {
    Text = "在這肆虐的自然之力中，有一個龐大的身影若隱若現，不定地在沙塵中閃爍。"
  },
  AvgDialog_49400_Content_31 = {
    Text = "風暴之壁……"
  },
  AvgDialog_49400_Content_32 = {
    Text = "風暴之壁，本就是憑藉我的權能呼喚而來之物。"
  },
  AvgDialog_49400_Content_33 = {
    Text = "你是……泰旖絲……？"
  },
  AvgDialog_49400_Content_34 = {
    Text = "它似乎擁有著無盡的力量，隨著沙塵的狂舞，那影子也跳躍、扭曲，彷彿是一頭古老的沙漠怪獸，在塵暴中覓找著獵物。"
  },
  AvgDialog_49400_Content_35 = {
    Text = "其形體巨大而恐怖，碩大盤繞的頭顱、尖銳的爪牙和笨重的四蹄，都在飛揚的沙塵中隱約可見。"
  },
  AvgDialog_49400_Content_36 = {
    Text = "這麼稱呼，也算不上錯誤。"
  },
  AvgDialog_49400_Content_37 = {
    Text = "但是，我並非你所期待的那位女王。"
  },
  AvgDialog_49400_Content_38 = {
    Text = "若是想要借用我的力量，就高聲念誦我的聖名吧——"
  },
  AvgDialog_49400_Content_39 = {
    Text = "那龐大古怪的影子逐漸淡去，你思之不得的身影從呼嘯的沙暴中走出。"
  },
  AvgDialog_49400_Content_4 = {
    Text = "衛兵，別讓他們傷到使者大人一根毫毛。"
  },
  AvgDialog_49400_Content_40 = {
    Text = "砂礫在她的周身無情地呼嘯狂舞，卻絲毫未能撼動她的步伐。"
  },
  AvgDialog_49400_Content_42 = {
    Text = "女王！是女王歸來了！"
  },
  AvgDialog_49400_Content_43 = {
    Text = "女王，女王的目光一直注視著我們！"
  },
  AvgDialog_49400_Content_44 = {
    Text = "她的目光一直注視著亞蘭，注視著奔湧在血脈中的過去與未來。"
  },
  AvgDialog_49400_Content_45 = {
    Text = "泰旖絲……大人……"
  },
  AvgDialog_49400_Content_46 = {
    Text = "所有亞蘭族裔聽令！古老的預言已經應驗，母樹重現於世，當為已逝者加冕！"
  },
  AvgDialog_49400_Content_47 = {
    Text = "女王踏砂歸來，重臨王座！"
  },
  AvgDialog_49400_Content_48 = {
    Text = "向亞蘭唯一的女王泰旖絲大人——"
  },
  AvgDialog_49400_Content_49 = {
    Text = "獻上你們的忠誠與意志！"
  },
  AvgDialog_49400_Content_6 = {
    Text = "於麗埃特湊近前來，與你一臂之隔向你低語。"
  },
  AvgDialog_49400_Content_7 = {
    Text = "回歸聖河是亞蘭人的宿命，我不過是幫他們加速了些許。"
  },
  AvgDialog_49400_Content_8 = {
    Text = "等到祂的目光遍及整片卡達斯，他們就會和聖河一起融入嶄新的世界。"
  },
  AvgDialog_49400_Content_9 = {
    Text = "這本就是你的意志，不是嗎？"
  },
  AvgDialog_49401_Content_1 = {
    Text = "母樹的枝條彷彿有了自己的意志，爭先恐後四向延伸，人類軀體的輪廓在其中若隱若現，動作笨拙而痛苦。"
