  AvgDialog_51254_Content_4 = {
    Text = "願銀鑰指引我們。"
  },
  AvgDialog_51998_Content_1 = {
    Text = "非利士人的嘲笑在房間中迴盪。非利士隊長搖了搖頭，揪住塔利斯的頭髮，拿出手中的匕首。"
  },
  AvgDialog_51998_Content_10 = {
    Text = "「你倒是提醒了我，我應該把戈利亞的東西都扔掉，免得以葛籣起疑。」"
