  AvgDialog_51998_Content_11 = {
    Text = "「衝這個，我可以讓你死得沒那麼痛苦……哦？」"
  },
  AvgDialog_51998_Content_2 = {
    Text = "他側身對著彌利亞姆。在他的腰間，一個小雕像晃盪著。她猛然瞪大了眼睛。"
  },
  AvgDialog_51998_Content_3 = {
    Text = "「那個雕像……是哪來的？」"
  },
  AvgDialog_51998_Content_4 = {
    Text = "「喲……原來你會說話啊，還以為是個傻子。」"
  },
  AvgDialog_51998_Content_5 = {
    Text = "「雕像，哪裡來的？」"
  },
  AvgDialog_51998_Content_6 = {
    Text = "非利士隊長放下刀。低頭看著腰間那個雕像。"
  },
  AvgDialog_51998_Content_7 = {
    Text = "雕像使用的是一種看上去非常古老的黯淡石質材料，刻畫著一個少年坐在王座上的模樣。一些怪異的觸手胡亂伸開，擋住了少年的臉。"
  },
  AvgDialog_51998_Content_8 = {
    Text = "「呵……這個？以前的族長戈利亞找到的。因為我的英勇，賞給了我。」"
  },
  AvgDialog_51998_Content_9 = {
    Text = "「我為他出生入死，他就賞給我這種東西。不知道是哪個蠢貨文明留下來的，一個沒用的廢物。」"
  },
  AvgDialog_51999_Content_1 = {Text = "轟——"},
  AvgDialog_51999_Content_10 = {
    Text = "「你也在被更高的意志所追逐，獵殺。你與余一樣，都是無主的孤魂。」"
  },
  AvgDialog_51999_Content_11 = {
    Text = "「利莫里亞人，信仰著無情的神明，和弱小的王。神國……呵，實在無聊。」"
  },
  AvgDialog_51999_Content_2 = {
    Text = "沉悶的聲響，穿透無數道厚重的石牆，在神殿的寢宮中迴盪。"
  },
  AvgDialog_51999_Content_3 = {
    Text = "圖魯一隻手撐著自己的下頜，疲憊地坐在王座之上。"
  },
  AvgDialog_51999_Content_4 = {
    Text = "利莫里亞的子民們陷入了沉眠。他用盡自己全部的力量，贈予他們一場美麗的夢境。"
  },
  AvgDialog_51999_Content_5 = {
    Text = "「“利莫里亞的風暴將平息。利莫里亞的深淵將消逝。”」"
  },
  AvgDialog_51999_Content_6 = {
    Text = "「“王將庇護他良善的子民，帶來神的國度……”」"
  },
  AvgDialog_51999_Content_7 = {
    Text = "「真會諷刺。是你傳達的意志嗎，“利莫里亞的神”？」"
  },
  AvgDialog_51999_Content_8 = {
    Text = "他抬起頭，目光穿過頭頂的石板，穿過暴雨與烏雲，直到深沉的星空，直到比星空更深沉的夢境。"
  },
  AvgDialog_51999_Content_9 = {
    Text = "「你早已死去。你從未在意利莫里亞。」"
  },
  AvgDialog_52000_Content_1 = {
    Text = "謊言的美德"
  },
  AvgDialog_52000_Content_10 = {
    Text = "這位被利莫里亞人頌念了無數次的王，第一次站在彌利亞姆面前。"
  },
  AvgDialog_52000_Content_11 = {
    Text = "走入此門後，有人會哭泣，有人會癲狂，也有人曾經試圖殺死余。"
  },
  AvgDialog_52000_Content_2 = {
    Text = "他凝視著池水。"
  },
  AvgDialog_52000_Content_3 = {
    Text = "一顆顆光滑的頭顱浮出水面，又落下去，此起彼伏，在池水中激起一道道骯髒的漣漪。"
  },
  AvgDialog_52000_Content_4 = {
    Text = "巨大的眼球往魚人頭顱的兩側生長，茫然地翻動，注視著他，嘴唇一開一合，吐露著意義不明的含糊音節，似乎在向他詢問什麼。"
  },
  AvgDialog_52000_Content_5 = {
    Text = "身後，石板門劃開。"
  },
  AvgDialog_52000_Content_6 = {
    Text = "讚頌吾主……利莫里亞，偉大的王……"
  },
  AvgDialog_52000_Content_7 = {
    Text = "與每個主祭的第一次見面，余都會聽到這句諷刺。"
  },
  AvgDialog_52000_Content_8 = {
    Text = "利莫里亞的巨大王冠反射著房間中不知何處出現的幽暗光澤，與少年的身體比例極不協調，戴在他的頭上卻沒有任何違和，似乎天生就是他身體的一部分。"
  },
  AvgDialog_52000_Content_9 = {
    Text = "惺忪的睡眼望向彌利亞姆，像是微微呼吸著的深海。稚氣未脫的臉上，見不到任何屬於少年的情緒。"
  },
  AvgDialog_52001_Content_1 = {
    Text = "可是沒關係，吾主能理解你的恐懼。我們的友誼，不會因為這些侮辱而改變的。"
  },
  AvgDialog_52001_Content_10 = {
    Text = "來，和我一起禱告吧，黛博拉。"
  },
  AvgDialog_52001_Content_11 = {
    Text = "不……彌利亞姆……我求你……"
  },
  AvgDialog_52001_Content_12 = {
    Text = "跟我說：“凡苦難的，吾主將償還。”"
  },
  AvgDialog_52001_Content_13 = {
    Text = "凡……凡苦難的……不，彌利亞姆……"
  },
  AvgDialog_52001_Content_14 = {
    Text = "跟我說。“凡罪孽的，吾主將責罰。”"
  },
  AvgDialog_52001_Content_15 = {
    Text = "彌利亞姆頌念著禱詞，來到她的身旁。"
  },
  AvgDialog_52001_Content_16 = {
    Text = "讓我和諾德說一句話！彌利亞姆……就讓我和他說一句……"
  },
  AvgDialog_52001_Content_18 = {
    Text = "劇烈的疼痛從腹部傳來。她抬起頭，看到彌利亞姆蒼白如蛇的手帶著那只匕首，插入了自己的腹腔，在她的腹腔畫出一道殷紅的軌跡。"
  },
  AvgDialog_52001_Content_19 = {
    Text = "彌利亞姆聽不見黛博拉淒厲的慘叫，看不見她因恐懼與劇痛而扭曲的面龐。"
  },
  AvgDialog_52001_Content_2 = {
    Text = "她虔誠地將圖魯的雕像放在祭祀台邊上，向它行禮。"
  },
  AvgDialog_52001_Content_20 = {
    Text = "匕首穩定地劃動，溫熱的鮮血噴灑在彌利亞姆的臉上。她虔誠地頌念，踏上通往神國的階梯。"
  },
  AvgDialog_52001_Content_22 = {
    Text = "殺了彌利亞姆！瓜分奧恩家族！我們的聯盟繁榮昌盛！乾杯！！"
  },
  AvgDialog_52001_Content_23 = {
    Text = "酒杯碰撞，毫不掩飾的貪婪隨著酒肉的香味瀰漫。"
  },
  AvgDialog_52001_Content_24 = {
    Text = "戈利亞舔舐著嘴唇，享受著這種令他陶醉的味道。"
  },
  AvgDialog_52001_Content_25 = {
    Text = "來，繼續啊，你這是怎麼了？"
  },
  AvgDialog_52001_Content_26 = {
    Text = "你……你的臉……"
  },
  AvgDialog_52001_Content_27 = {
    Text = "我的臉？"
  },
  AvgDialog_52001_Content_28 = {
    Text = "他望向身旁光滑如鏡的瓷磚，看到一張像是魚一般的臉。"
  },
  AvgDialog_52001_Content_3 = {
    Text = "讚頌吾主……利莫里亞，偉大的王……今夜，我將迎接您回歸。"
  },
  AvgDialog_52001_Content_30 = {
    Text = "一道道傷口出現在他的胸膛，如同被無形的匕首劃過。耳朵與眉毛正在消失，眼球極速地膨脹，向兩邊生長著。"
  },
  AvgDialog_52001_Content_31 = {
    Text = "劇烈的疼痛突破酒精與腎上腺素來到他的大腦。他倒在地上，發出後知後覺的痛苦哀嚎，雙手胡亂地撕扯著自己的臉。"
  },
  AvgDialog_52001_Content_32 = {
    Text = "這是？啊！！——"
  },
  AvgDialog_52001_Content_33 = {
    Text = "一個，兩個，三個……豪華的宴會大廳裡，貴族們一個接一個倒在地上。"
  },
  AvgDialog_52001_Content_34 = {
    Text = "殷紅的創口在他們身上接連出現，血與肉在他們的身體上繪製成一幅古老的圖案。"
  },
  AvgDialog_52001_Content_35 = {
    Text = "痛苦的哀嚎匯成恢弘的樂曲，鮮血噴灑，斟滿每一個酒杯。"
  },
  AvgDialog_52001_Content_36 = {
    Text = "這是……這是……魚人儀式！"
  },
  AvgDialog_52001_Content_37 = {
    Text = "沒錯，魚人儀式。奧恩家族的慘狀，你們應該都知道了。"
  },
  AvgDialog_52001_Content_38 = {
    Text = "為什麼……戈利亞？"
  },
  AvgDialog_52001_Content_39 = {
    Text = "為什麼？"
  },
  AvgDialog_52001_Content_4 = {
    Text = "請您耐心等待。星辰正位之刻，就要到來……"
  },
  AvgDialog_52001_Content_40 = {
    Text = "戈利亞似乎聽到了一個好笑的笑話。他從主座上站起來，拿起了自己的刀。"
  },
  AvgDialog_52001_Content_41 = {
    Text = "跟你們合作，我能得到奧恩家族的一小塊領地。"
  },
  AvgDialog_52001_Content_42 = {
    Text = "跟彌利亞姆合作，我能得到你們無法想像的強大力量，能將你們這些家族都變成魚人的一員，掌控你們的所有財富……"
  },
  AvgDialog_52001_Content_43 = {
    Text = "告訴我，艾德蒙先生，你是我的話，你會怎麼選呢？"
  },
  AvgDialog_52001_Content_44 = {
    Text = "我……我們不會束手就擒的！"
  },
  AvgDialog_52001_Content_45 = {
    Text = "沒錯！戈利亞，以埃諾姆家族的榮耀，我們會……啊——"
  },
  AvgDialog_52001_Content_46 = {
    Text = "巨大的鋒刃豎著落下，年輕的貴族分成兩塊向兩邊倒去，失去了證明榮耀的能力。"
  },
  AvgDialog_52001_Content_47 = {
    Text = "四周的門打開，無數的魚人如同潮水般湧入大廳。"
  },
  AvgDialog_52001_Content_48 = {
    Text = "……外面的親兵呢？"
  },
  AvgDialog_52001_Content_49 = {
    Text = "你們推杯換盞的時候，那些親兵，就已經被我們幹掉了。"
  },
  AvgDialog_52001_Content_5 = {
    Text = "她站起身，溫柔地走向黛博拉。蒼白的手中，造型怪異的祭祀匕首閃動著幽暗的光。"
  },
  AvgDialog_52001_Content_50 = {
    Text = "至於城外的軍隊……也不用再想著聯絡他們了。"
  },
  AvgDialog_52001_Content_51 = {
    Text = "鮮血染紅了大廳的每一個角落，慘叫聲瘋狂地在牆壁上撞擊、迴盪，如同來自地獄的交響。"
  },
  AvgDialog_52001_Content_52 = {
    Text = "那些沒有飲下毒酒、保持著正常的人們身體顫抖著，身體甚至抽不出拔劍或逃跑的力氣。"
  },
  AvgDialog_52001_Content_53 = {
    Text = "戈利亞欣賞著大廳中這幅血腥的繪卷，看著貴族們恐懼的神情，享受地嘆了一口氣，提起那把巨大的刀刃。"
  },
  AvgDialog_52001_Content_54 = {
    Text = "喝下毒酒變成魚人，或者死在這裡。選一個吧。"
  },
  AvgDialog_52001_Content_57 = {
    Text = "淒厲的慘叫聲撞上石板，發出沉悶的迴響。"
  },
  AvgDialog_52001_Content_58 = {
    Text = "她想掙扎、逃走，但身體被彌利亞姆控制著，不能移動分毫。"
  },
  AvgDialog_52001_Content_59 = {
    Text = "她想暈過去，但她的大腦無比清醒，迎接著疼痛與恐懼。"
  },
  AvgDialog_52001_Content_6 = {
    Text = "不！彌利亞姆！！求求你……求求你……不要做這麼殘忍的事……"
  },
  AvgDialog_52001_Content_60 = {
    Text = "跟我說，“凡虔誠的，吾主將眷顧……”"
  },
  AvgDialog_52001_Content_61 = {
    Text = "黛博拉的鮮血濺滿了彌利亞姆的身子。她想起很多年前，在神殿的祭祀台上，她也是這樣，送別了自己的父親。"
  },
  AvgDialog_52001_Content_62 = {
    Text = "送別，是為了更好的相聚，對吧，吾主？"
  },
  AvgDialog_52001_Content_63 = {
    Text = "她深情地望著黛博拉的腹部，匕首劃動著，完成了這幅繪圖的最後一筆。"
  },
  AvgDialog_52001_Content_64 = {
    Text = "來吧，黛博拉。跟我說。凡期願的……"
  },
  AvgDialog_52001_Content_65 = {
    Text = "彌利亞姆的手探入彌利亞姆的肚子，攪動，撕扯。"
  },
  AvgDialog_52001_Content_66 = {
    Text = "黛博拉喑啞的嗓子痛苦地嘶吼著，猩紅的雙眼瘋狂地睜開，直直地注視著自己的腹腔。"
  },
  AvgDialog_52001_Content_67 = {
    Text = "……“凡期願的，吾主將應許。”"
  },
  AvgDialog_52001_Content_68 = {
    Text = "彌利亞姆扯斷了什麼東西，或許應該很痛，但黛博拉已經感受不到了。"
  },
  AvgDialog_52001_Content_69 = {
    Text = "她的大腦已經變得麻木，情緒與感知都已離她遠去。"
  },
  AvgDialog_52001_Content_7 = {
    Text = "看著我，黛博拉。看著我……"
  },
  AvgDialog_52001_Content_70 = {
    Text = "她模糊地看見，彌利亞姆從她的腹腔中抱出一個血淋淋的肉球。"
  },
  AvgDialog_52001_Content_71 = {
    Text = "薩……薩……"
  },
  AvgDialog_52001_Content_72 = {
    Text = "薩拉。彌利亞姆曾和她講過，這是她妹妹的名字。"
  },
  AvgDialog_52001_Content_73 = {
    Text = "她和諾德商量過了，他們會以這個名字，為自己的女兒命名。但她還沒有來得及告訴彌利亞姆。"
  },
  AvgDialog_52001_Content_74 = {
    Text = "叫她薩拉。黛博拉囁嚅著，可她已經無法再發出任何聲音。"
  },
  AvgDialog_52001_Content_75 = {
    Text = "“吾主，願我們的歌聲穿越深海，與您一同，前往無盡的安寧與極樂之境。”"
  },
  AvgDialog_52001_Content_76 = {
    Text = "彌利亞姆深情地親吻她的教女，嬰兒身上的血染紅她的唇。鮮血順著唇角滴落，她輕輕蓋上黛博拉的眼。"
  },
  AvgDialog_52001_Content_8 = {
    Text = "我知道，你很害怕。我見過很多的信徒，面對此生的終結，他們都會害怕。"
  },
  AvgDialog_52001_Content_9 = {
    Text = "但是，不要擔心。你是神國至高的子民，你所遭受的一切，都會在神國得到補償。"
  },
  AvgDialog_52002_Content_1 = {
    Text = "群星已至正位。王的聖胎，已經植入了聖嬰體內。很快，王便將重現於世。"
  },
  AvgDialog_52002_Content_10 = {
    Text = "在魚人們震耳欲聾的和鳴中，彌利亞姆伸出雙手，將懷中的嬰兒高高舉起。"
  },
  AvgDialog_52002_Content_11 = {
    Text = "在她原本的心臟處，聖胎在群星之下，散發著潔淨的白色光芒。"
  },
  AvgDialog_52002_Content_12 = {
    Text = "嗚哇——"
  },
  AvgDialog_52002_Content_13 = {
    Text = "一切都安靜了下來。被鮮血包裹的嬰兒扭動身體，古老的廢墟中，響起她遲來的第一聲啼哭。"
  },
  AvgDialog_52002_Content_14 = {
    Text = "漫天的星辰沉默著，聆聽這神諭般的哭聲。一顆星星隕落下來，在夜空中劃出一道淒厲的註腳。"
  },
  AvgDialog_52002_Content_15 = {
    Text = "——關於群星的另一段故事，便要開始了。"
  },
  AvgDialog_52002_Content_2 = {
    Text = "王，將庇護祂良善的子民，帶來神國！"
  },
  AvgDialog_52002_Content_3 = {
    Text = "神國！神國！"
  },
  AvgDialog_52002_Content_4 = {
    Text = "魚人們癲狂地歡呼、舞蹈。彌利亞姆來到人群的中央。星光落下，照亮她滿是鮮血與眼淚的臉。"
  },
  AvgDialog_52002_Content_5 = {
    Text = "王的教義將傳遍世界。主祭大人，給這個教派一個名字吧。"
  },
  AvgDialog_52002_Content_6 = {
    Text = "一雙冰冷又熾熱的眼睛緩緩轉動。彌利亞姆環顧著她的士兵，她的臣民。她向牠們露出主祭的微笑。"
  },
  AvgDialog_52002_Content_7 = {
    Text = "我們蹈海而去，追尋王的足跡。我們蹈海而來，帶來王的國度……"
  },
  AvgDialog_52002_Content_8 = {
    Text = "世人將稱我們，蹈海者。"
  },
  AvgDialog_52003_Content_1 = {
    Text = "王會告訴你們。禱告吧。"
  },
  AvgDialog_52003_Content_10 = {
    Text = "身邊不時有人倒下。彌利亞姆強忍著疼痛，念出了紙上的禱文。"
  },
  AvgDialog_52003_Content_11 = {
    Text = "“在遙遠的黯淡深淵，古老的偉大靈魂沉眠……”"
  },
  AvgDialog_52003_Content_12 = {
    Text = "彌利亞姆以普通的利莫里亞語念出了這些話，但話從她口中說出，卻變成了另一種語言。"
  },
  AvgDialog_52003_Content_13 = {
    Text = "同一個時刻，她的聲音重疊交織，繁複地響起。就如同文字一樣，她的聲音也變成了一種高維度結構，如同從某個人類無從想像的時空中響起。"
  },
  AvgDialog_52003_Content_14 = {
    Text = "“……祂的意志如星辰之網交織，祂在永恆的虛無中候汝入夢……”"
  },
  AvgDialog_52003_Content_15 = {
    Text = "彌利亞姆繼續頌念著。"
  },
  AvgDialog_52003_Content_16 = {
    Text = "不知道什麼時候開始，眼前的世界消失了。"
  },
  AvgDialog_52003_Content_17 = {
    Text = "她置身於深海，不論從哪個方向望去，都只能望見虛無的海水。"
  },
  AvgDialog_52003_Content_18 = {
    Text = "在深海之中，點點亮光如同寰宇星辰散落開。"
  },
  AvgDialog_52003_Content_19 = {
    Text = "彌利亞姆感覺自己也變成了一顆星星，而自己身上的亮光，正在向某處匯集。她向那處望去。"
  },
  AvgDialog_52003_Content_2 = {
    Text = "老人離開了房間，內部只剩一位祭司和幾名侍衛。"
  },
  AvgDialog_52003_Content_20 = {
    Text = "無數的光線奔湧匯集，在彼處匯成一個模糊的輪廓。那是一個由人體、王座與觸鬚所構成的輪廓。"
  },
  AvgDialog_52003_Content_21 = {
    Text = "那是……王嗎？"
  },
  AvgDialog_52003_Content_23 = {
    Text = "似乎被某個聲音驚擾，他從王座上醒來。隨著他的驚醒，整個虛無的空間似乎都暗淡了一刻。"
  },
  AvgDialog_52003_Content_24 = {
    Text = "在他身後，一個老人的模糊輪廓顯現出來。"
  },
  AvgDialog_52003_Content_25 = {
    Text = "您聽見她的聲音了，吾主。"
  },
  AvgDialog_52003_Content_26 = {
    Text = "群星所昭示之人，便是她嗎？"
  },
  AvgDialog_52003_Content_27 = {
    Text = "是她，我已經查驗過。若群星所示沒有錯，她……便是利莫里亞的未來。"
  },
  AvgDialog_52003_Content_28 = {
    Text = "你並不這樣想。"
  },
  AvgDialog_52003_Content_29 = {
    Text = "有天賦，但有雜念。她無法為您提供幫助，吾主。"
  },
  AvgDialog_52003_Content_3 = {
    Text = "禱告室內的光線變得昏暗，前方的雕像閃爍著神秘的暗淡光澤。"
  },
  AvgDialog_52003_Content_30 = {
    Text = "她並不相信禱文，不相信您，也不相信利莫里亞的未來。她只相信她的家人。"
  },
  AvgDialog_52003_Content_31 = {
    Text = "彌利亞姆是一個活在真實中的人。這樣的人，是無法承擔利莫里亞的命運的。"
  },
  AvgDialog_52003_Content_32 = {
    Text = "生活在真實而非虛妄裡，這正是余的希冀。"
  },
  AvgDialog_52003_Content_33 = {
    Text = "美好的願望，吾主。可生於利莫里亞，我們都有自己應去承擔的職責。"
  },
  AvgDialog_52003_Content_34 = {
    Text = "我們無從選擇。無論是她，是我，還是您，都一樣。"
  },
  AvgDialog_52003_Content_35 = {
    Text = "……無聊。余要休息了。"
  },
  AvgDialog_52003_Content_36 = {
    Text = "他揮了揮手。老人向他躬身行禮，消失在了無邊的虛無中。"
  },
  AvgDialog_52003_Content_37 = {
    Text = "入睡之前，他望了一眼那些將光亮獻予他的人們。一聲無人聽聞的嘆息，消失在無垠的虛空裡。"
  },
  AvgDialog_52003_Content_39 = {
    Text = "緊接著一陣令人心悸的墜落感的，是一道強烈的刺痛。"
  },
  AvgDialog_52003_Content_4 = {
    Text = "彌利亞姆拿起身前的禱文。"
  },
  AvgDialog_52003_Content_40 = {
    Text = "痛楚並沒有持續很久。彌利亞姆離開了那個虛無的空間，環視著身邊。"
  },
  AvgDialog_52003_Content_41 = {
    Text = "一些無法閱讀或頌唸禱文的人已經被請出了禱告室，剩下一小半的人，一些痛苦地倒在地上，另外還有一些正閉眼禱唸著，臉上露出幸福的笑容。"
  },
  AvgDialog_52003_Content_42 = {
    Text = "黛博拉坐在她旁邊，面帶微笑緩緩睜開眼。看到彌利亞姆的樣子，她露出關切的神情。"
  },
  AvgDialog_52003_Content_6 = {
    Text = "紙上寫著的並不是利莫里亞的通用語，那是一種複雜的象形符號，擁有比現實空間更多的維度。"
  },
  AvgDialog_52003_Content_7 = {
    Text = "那符號來自遠古、甚或是來自另一個世界，彌利亞姆從未見過。但閱讀這符號時，其間的含義卻自動進入了她腦海。"
  },
  AvgDialog_52003_Content_8 = {
    Text = "每個文字都包含著巨大的資訊量，無數的經文竄進彌利亞姆的大腦，讓那個脆弱的人類頭顱難堪重負。"
  },
  AvgDialog_52003_Content_9 = {
    Text = "<Shake:頭……頭好痛……>"
  },
  AvgDialog_52004_Content_1 = {
    Text = "只要信仰王，王便會回應你的信仰……"
  },
  AvgDialog_52004_Content_10 = {
    Text = "願您的慧眼洞察災禍，\n願您的智慧引領子民。"
  },
  AvgDialog_52004_Content_11 = {
    Text = "“願您的慧眼洞察災禍，\n願您的智慧引領子民。！”"
  },
  AvgDialog_52004_Content_12 = {
    Text = "風暴靜伏，水波不興；\n地震平息，大地安寧。"
  },
  AvgDialog_52004_Content_13 = {
    Text = "災禍在您的寧靜夢境中化為虛無。\n在您的庇護中，我們迎來神的國度。"
  },
  AvgDialog_52004_Content_14 = {
    Text = "“災禍在您的寧靜夢境中化為虛無！”"
  },
  AvgDialog_52004_Content_15 = {
    Text = "“在您的庇護中，\n我們迎來神的國度……”"
  },
  AvgDialog_52004_Content_16 = {Text = "轟……"},
  AvgDialog_52004_Content_17 = {
    Text = "轟鳴聲中，數根巨大的觸手從神殿下方破土而出。"
  },
  AvgDialog_52004_Content_18 = {
    Text = "是王！王的神蹟現身了！！！"
  },
  AvgDialog_52004_Content_19 = {
    Text = "信徒們張開雙臂，瘋狂地歡呼著。"
  },
  AvgDialog_52004_Content_2 = {
    Text = "所以，告訴我，你信仰王嗎？你願意將你的一切，獻予王嗎？"
  },
  AvgDialog_52004_Content_20 = {
    Text = "觸手在風雨中微微擺動著，利莫里亞的所有人都毫不懷疑，這些利莫里亞的偉大神祇，擁有能夠抵禦一切災厄的力量。"
  },
  AvgDialog_52004_Content_21 = {
    Text = "吾主，圖魯——"
  },
  AvgDialog_52004_Content_22 = {
    Text = "吾主，圖魯！！圖魯！！！"
  },
  AvgDialog_52004_Content_23 = {
    Text = "她轉過身，望著神殿內部的方向，跪倒在地。"
  },
  AvgDialog_52004_Content_24 = {
    Text = "在無人能看到的眼裡，沒有任何主祭的期冀與威嚴，只剩下迷茫。"
  },
  AvgDialog_52004_Content_25 = {
    Text = "請聆聽您信徒的呼喚。請為我們，帶來神國。"
  },
  AvgDialog_52004_Content_26 = {
    Text = "請為我們，帶來神國！"
  },
  AvgDialog_52004_Content_27 = {
    Text = "吾主！神國！哈哈哈……神國就要降臨了！"
  },
  AvgDialog_52004_Content_28 = {
    Text = "伴隨著瘋狂的呼喊聲，觸手開始舞動。深海的靜謐氣息從觸手上傳來，傳入每個利莫里亞人的感官裡。"
  },
  AvgDialog_52004_Content_29 = {Text = "轟——"},
  AvgDialog_52004_Content_3 = {
    Text = "我信仰王，主祭大人！我願意將一切都獻予王！"
  },
  AvgDialog_52004_Content_30 = {
    Text = "滾滾雷聲裡，歡呼聲平息。閃電從天空亮起，照耀著利莫里亞孤單的土地。"
  },
  AvgDialog_52004_Content_31 = {
    Text = "在這狂歡的一刻，信徒們的動作停了下來，停在對王至高的頌念與信仰裡，停在對未來無限的暢想與希冀中。"
  },
  AvgDialog_52004_Content_32 = {
    Text = "暴雨之下，利莫里亞的子民們酣然入夢。"
  },
  AvgDialog_52004_Content_4 = {
    Text = "我是王最忠實的追隨者！"
  },
  AvgDialog_52004_Content_5 = {
    Text = "我願意！主祭大人，我願意！"
  },
  AvgDialog_52004_Content_6 = {
    Text = "那麼現在，和我一起頌念王的名字——"
  },
  AvgDialog_52004_Content_7 = {
    Text = "她環視著廣場上的每個人。"
  },
  AvgDialog_52004_Content_8 = {
    Text = "狂風暴雨裡，所有人都跪了下去，張開雙臂，望向神殿裡王座的方向。"
  },
  AvgDialog_52004_Content_9 = {
    Text = "在星輝蒼穹之下，深海孤島之上，為吾主虔誠禱告："
  },
  AvgDialog_52005_Content_1 = {
    Text = "沒錯，父親……我們會在神國再見的！我們一家人，會在神國生活在一起……"
  },
  AvgDialog_52005_Content_10 = {
    Text = "神國就要降臨了，父親。很快，我們一家人，就會重逢……"
  },
  AvgDialog_52005_Content_12 = {
    Text = "匕首狠狠插入伊諾斯的胸膛，伊諾斯發出痛苦的嚎叫。鮮血噴濺，染紅了彌利亞姆的右半臉。"
  },
  AvgDialog_52005_Content_13 = {
    Text = "彌利亞姆睜大雙眼，認真地看著匕首與肉體之間的切口，就像在看著一幅曠世的畫作。"
  },
  AvgDialog_52005_Content_14 = {
    Text = "匕首游走，滑動，切開皮膚與骨肉。伊諾斯痛苦地哭嚎，像是一頭正在被肢解的野獸。"
  },
  AvgDialog_52005_Content_15 = {
    Text = "嘶吼與鮮血在儀式間內奔湧，像密密麻麻的尖刺，穿透彌利亞姆的面孔與肌膚，刺入她的心臟肺腑。"
  },
  AvgDialog_52005_Content_17 = {
    Text = "“吾主之信徒，敞開你的心懷，接納吾主……”"
  },
  AvgDialog_52005_Content_18 = {
    Text = "血與淚沖刷著彌利亞姆猙獰扭曲的面容。她念誦著禱文，手上的動作越來越快、越來越快。"
  },
  AvgDialog_52005_Content_19 = {
    Text = "匕首停下。伊諾斯的身體上，以他自己的骨肉與鮮血，描繪出那些象徵著幸福與希冀的符號。"
  },
  AvgDialog_52005_Content_2 = {
    Text = "她擦去臉上的淚水，緩緩站起身，拿起了身旁的匕首。"
  },
  AvgDialog_52005_Content_20 = {
    Text = "“凡虔誠的，吾主將眷顧……”"
  },
  AvgDialog_52005_Content_21 = {
    Text = "<Big:「凡期願的，吾主將應許……」>"
  },
  AvgDialog_52005_Content_22 = {
    Text = "她捧起神血，灌入伊諾斯身上那些符號般的傷口。"
  },
  AvgDialog_52005_Content_23 = {
    Text = "神血接觸到那些符號的那一刻，如同感知到獵物熱源的蛇，變得鮮活、興奮起來。"
  },
  AvgDialog_52005_Content_24 = {
    Text = "不需要彌利亞姆的指引，它們遵循著熱源的指引，從那些傷口鑽入伊諾斯體內。"
  },
  AvgDialog_52005_Content_25 = {
    Text = "隨著神血的匯入，伊諾斯的慘叫聲愈發劇烈。他身上的傷口，以肉眼可見的速度癒合著。"
  },
  AvgDialog_52005_Content_26 = {
    Text = "與此同時，他的五官開始退化，雙眼變得巨大而外翻，嘴唇變得黏膩，頭顱的形狀也變得扁而狹長。"
  },
  AvgDialog_52005_Content_27 = {
    Text = "一道鰓狀的器官出現在他的脖頸上，鱗片取代了毛髮，從他身體的各處生長出來。"
  },
  AvgDialog_52005_Content_28 = {
    Text = "他仍然發出痛苦的聲音，從人類成年男性的嚎叫，逐漸變成帶著深海潮濕污穢氣息的嘶鳴……"
  },
  AvgDialog_52005_Content_29 = {
    Text = "我成功了，父親……我沒有讓您失望，對嗎？"
  },
  AvgDialog_52005_Content_3 = {
    Text = "匕首以一種奇特的弧度彎曲，上面刻畫著和禱文同樣的複雜象形符號。"
  },
  AvgDialog_52005_Content_30 = {
    Text = "嘶鳴聲停止了。智識消失，那隻半魚半人的怪物瞪著那雙巨大泛白的眼睛，茫然地打量著她。"
  },
  AvgDialog_52005_Content_31 = {
    Text = "彌利亞姆走到石案旁邊，撫摸著那隻怪物，感知著空氣中濃烈的魚腥味，以及手上傳來的黏膩觸感。"
  },
  AvgDialog_52005_Content_32 = {
    Text = "這腥味與觸感曾經讓她覺得噁心，但現在，她覺得它們無比溫暖。"
  },
  AvgDialog_52005_Content_33 = {
    Text = "我很喜歡魚，等我們在神國重逢，我每天都會吃你做的魚……"
  },
  AvgDialog_52005_Content_34 = {
    Text = "請等著我吧，父親。"
  },
  AvgDialog_52005_Content_35 = {
    Text = "她俯下身，親吻它滑膩潮濕的臉。"
  },
  AvgDialog_52005_Content_4 = {
    Text = "在匕首旁邊的石盆中，與神明同源的鮮血微微泛起漣漪，燭火映照，反射出詭異的紅綠色光澤。"
  },
  AvgDialog_52005_Content_5 = {
    Text = "嚴重的譫妄，讓伊諾斯失去了絕大部分的意識。他睜著眼，好奇地看著彌利亞姆，就像一個剛出世的嬰兒，看著眼前新奇的世界。"
  },
  AvgDialog_52005_Content_6 = {
    Text = "彌利亞姆，你現在是祭司了……你有問過王嗎？王有沒有告訴你，神國什麼時候能在利莫里亞降臨呢？"
  },
  AvgDialog_52005_Content_7 = {
    Text = "我問過了，父親……王說，很快，很快……"
  },
  AvgDialog_52005_Content_8 = {
    Text = "淚水之間，出現了一抹慘淡的笑容。她來到伊諾斯身邊，俯下身，撫摸他的臉。"
  },
  AvgDialog_52005_Content_9 = {
    Text = "我不會讓您失望的，父親。"
  },
  AvgDialog_54067_Content_1 = {
    Text = "夢歸利莫里亞"
  },
  AvgDialog_54067_Content_10 = {
    Text = "嘈雜是這海裡的魚群，圍繞著她游動，在她與魚群之間，一片虛無的海水沉默地湧動，她自己的聲音，在其間清晰地浮現。"
  },
  AvgDialog_54067_Content_100 = {
    Text = "暴雨擊打在他乾枯的軀體上，狂風幾乎要將他吹倒。在利莫里亞的最高點，老人眺望著這個龐大的島嶼。"
  },
  AvgDialog_54067_Content_101 = {
    Text = "眼裡的銳利和蒼老都消失不見，它們清澈，痛快，好奇，像是一個剛出生的嬰孩，興致勃勃地盯著這個瘡痍的土地。"
  },
  AvgDialog_54067_Content_102 = {
    Text = "「呵呵呵……利莫里亞，多美的地方啊。」"
  },
  AvgDialog_54067_Content_103 = {
    Text = "「您現在在想什麼呢，吾主？」"
  },
  AvgDialog_54067_Content_104 = {
    Text = "「您總是說，您對拯救利莫里亞沒有興趣，您只感到困倦。可為了利莫里亞，您把自己困在了王座上，困在自己的夢境裡。」"
  },
  AvgDialog_54067_Content_105 = {
    Text = "「神明已消失，可您仍在追尋……我只是一個騙子，您才是利莫里亞最偉大的守護者。」"
  },
  AvgDialog_54067_Content_106 = {
    Text = "「再看一眼吧，吾主。再看最後一眼。利莫里亞，我們的故鄉……」"
  },
  AvgDialog_54067_Content_107 = {
    Text = "老人抬起頭，目光從島嶼上那些陷入沉睡的子民，移到天邊沸騰的海洋，移到天空無情的驚雷與暴雨。"
  },
  AvgDialog_54067_Content_108 = {
    Text = "他顫巍巍地站起來，溫情融化在深邃的眸中。鬚髮與長袍在風中飄搖，重新變得銳利的雙眼，如利刃般直直刺向天空。"
  },
  AvgDialog_54067_Content_109 = {
    Text = "「繁雜的騙局，無聊的使命，莊嚴的承諾，讓這些東西都統統見鬼去吧。」"
  },
  AvgDialog_54067_Content_11 = {
    Text = "“……以圖魯，吾主之名宣誓：”"
  },
  AvgDialog_54067_Content_110 = {
    Text = "他扔掉拐杖，張開雙臂，迎接著風暴。他嘶吼著。"
  },
  AvgDialog_54067_Content_111 = {
    Text = "「來吧，災厄！來吧，卑劣的神明！」"
  },
  AvgDialog_54067_Content_112 = {
    Text = "「我是你們的共犯。讓我們一起，為利莫里亞送葬！」"
  },
  AvgDialog_54067_Content_114 = {Text = "轟——"},
  AvgDialog_54067_Content_115 = {
    Text = "沉悶的聲響，穿透無數道厚重的石牆，在神殿的寢宮中迴盪。"
  },
  AvgDialog_54067_Content_116 = {
    Text = "圖魯一隻手撐著自己的下頜，疲憊地坐在王座之上。"
  },
  AvgDialog_54067_Content_117 = {
    Text = "利莫里亞的子民們陷入了沉眠。他用盡自己全部的力量，贈予他們一場美麗的夢境。"
  },
  AvgDialog_54067_Content_118 = {
    Text = "「“利莫里亞的風暴將平息。利莫里亞的深淵將消逝。”」"
  },
  AvgDialog_54067_Content_119 = {
    Text = "「“王將庇護他良善的子民，帶來神的國度……”」"
  },
  AvgDialog_54067_Content_12 = {
    Text = "“我是利莫里亞的僕從。我是王的近侍。”"
  },
  AvgDialog_54067_Content_120 = {
    Text = "「真會諷刺。是你傳達的意志嗎，“利莫里亞的神”？」"
  },
  AvgDialog_54067_Content_121 = {
    Text = "他抬起頭，目光穿過頭頂的石板，穿過暴雨與烏雲，直到深沉的星空，直到比星空更深沉的夢境。"
  },
  AvgDialog_54067_Content_122 = {
    Text = "「你早已離去……你從未在意利莫里亞。對嗎？」"
  },
  AvgDialog_54067_Content_123 = {
    Text = "「你也在被更高的意志所追逐，獵殺，遺棄。你與余一樣，都是無主的孤魂。」"
  },
  AvgDialog_54067_Content_124 = {
    Text = "「利莫里亞人，信仰著無情的神明，和弱小的王。神國……呵，實在無聊。」"
  },
  AvgDialog_54067_Content_125 = {
    Text = "「很抱歉。不過這次，余真的乏了。」"
  },
  AvgDialog_54067_Content_126 = {
    Text = "他斜坐在王座之上，一隻手撐在下頜，沉沉睡去。"
  },
  AvgDialog_54067_Content_127 = {
    Text = "他與子民們進入了同一個夢境。在那裡，利莫里亞陽光燦爛，歡聲笑語。"
  },
  AvgDialog_54067_Content_128 = {
    Text = "他為利莫里亞帶來了夢寐以求的神國。他為利莫里亞帶來了夢寐以求的謊言。"
  },
  AvgDialog_54067_Content_129 = {
    Text = "以謊言為故鄉送別，這是他身為利莫里亞的王，最後的權力與慈悲。"
  },
  AvgDialog_54067_Content_13 = {
    Text = "“我將引領利莫里亞的子民。我將聆聽吾主之音，奉行吾主之命。”"
  },
  AvgDialog_54067_Content_132 = {
    Text = "碎石從雕像上掉落下來。那座巨大的沉默雕像，如今已經殘破不堪。"
  },
  AvgDialog_54067_Content_133 = {
    Text = "「父親，你看……那是王的眼淚。吾主，正在為利莫里亞哀悼。」"
  },
  AvgDialog_54067_Content_134 = {
    Text = "在她的懷裡，一隻魚人翻動著巨大的眼睛，茫然地四處張望著。"
  },
  AvgDialog_54067_Content_135 = {
    Text = "她找不到伊諾斯，於是每隻魚人便都是伊諾斯。"
  },
  AvgDialog_54067_Content_136 = {
    Text = "暴雨的聲音穿透牆壁，越發強烈，魚人們濃重的腥味瀰漫在房間裡。她輕輕撫摸著牠。"
  },
  AvgDialog_54067_Content_137 = {
    Text = "「老師，王……他們似乎都放棄了。」"
  },
  AvgDialog_54067_Content_138 = {
    Text = "「我……不會放棄的……我能拯救利莫里亞，我能將利莫里亞帶回來。這是王親口告訴我的。」"
  },
  AvgDialog_54067_Content_139 = {
    Text = "「母親死了，妹妹死了，父親……也死了。」"
  },
  AvgDialog_54067_Content_14 = {
    Text = "“我將與一切信徒一起，迎接神國。”"
  },
  AvgDialog_54067_Content_140 = {
    Text = "「我很害怕，彌利亞姆。我怕我們做的這些，都沒有意義……」"
  },
  AvgDialog_54067_Content_141 = {
    Text = "「那麼多的災難，父親只是一個普通的人，可他都從來沒有害怕過，也沒有放棄過。」"
  },
  AvgDialog_54067_Content_142 = {
    Text = "「我們是利莫里亞的主祭，我們也絕不會放棄……這是父親教會我的。」"
  },
  AvgDialog_54067_Content_143 = {
    Text = "她微笑著，輕聲安慰著。淚水奔湧，混合著這些她也不知道是真是假的話，滴落在魚人的鱗片上，折射出幽暗的光。"
  },
  AvgDialog_54067_Content_144 = {
    Text = "轟轟轟——"
  },
  AvgDialog_54067_Content_145 = {
    Text = "腳下的土地猛然震動起來。神殿堅固的石柱苦苦支撐著，頭頂的石板逐漸支離、瓦解，碎落在地。"
  },
  AvgDialog_54067_Content_146 = {
    Text = "在這劇烈的震動中，雕像殘餘的部分分崩離析。風暴與地震的聲音像鼓點般敲動著彌利亞姆的耳膜。"
  },
  AvgDialog_54067_Content_147 = {
    Text = "她閉上眼，跪在殘缺的雕像面前，挽起小彌利亞姆的手。"
  },
  AvgDialog_54067_Content_148 = {
    Text = "「聆聽吾主，歸依吾主，讚頌吾主……」"
  },
  AvgDialog_54067_Content_149 = {
    Text = "「凡苦難的，吾主將償還。\n凡罪孽的，吾主將責罰……」"
  },
  AvgDialog_54067_Content_15 = {Text = "轟——"},
  AvgDialog_54067_Content_150 = {
    Text = "震動沒有停止，光線似乎變得暗淡下去。遠方的海洋中，升起一面直達天穹的深藍色牆壁——"
  },
  AvgDialog_54067_Content_151 = {
    Text = "海洋站立起來，像是一個甦醒的巨人，邁向利莫里亞。"
  },
  AvgDialog_54067_Content_152 = {
    Text = "在海洋面前，這個輝煌的國度如枯葉般渺小，如枯葉般脆弱。"
  },
  AvgDialog_54067_Content_153 = {
    Text = "「凡虔誠的，吾主將眷顧。」"
  },
  AvgDialog_54067_Content_154 = {
    Text = "「凡期願的，吾主將應許……將應許……」"
  },
  AvgDialog_54067_Content_155 = {
    Text = "暴怒的颶風襲向脆弱的神殿，掀開了沉重的石板與堅固的地基。"
  },
  AvgDialog_54067_Content_156 = {
    Text = "僅剩的光線幾乎被直立的海洋完全遮擋。晦暗殘破的廢墟中，她緊緊抱著懷裡的魚人。"
  },
  AvgDialog_54067_Content_157 = {
    Text = "來自海洋深處的死亡的氣息包圍著她。淚水浸滿她的雙眼。"
  },
  AvgDialog_54067_Content_159 = {
    Text = "「吾主……我的信念與您同在，直到星辰的盡頭……」"
  },
  AvgDialog_54067_Content_16 = {
    Text = "一道驚雷在利莫里亞上空炸響。"
  },
  AvgDialog_54067_Content_160 = {
    Text = "「您沒有騙我，神國會降臨的，對嗎，吾主？」"
  },
  AvgDialog_54067_Content_161 = {
    Text = "最後一次，她抬起頭，絕望地凝視王的雕像曾經矗立的地方。"
  },
  AvgDialog_54067_Content_162 = {
    Text = "那裡沒有雕像，也沒有王。"
  },
  AvgDialog_54067_Content_164 = {
    Text = "<Big:轟————>"
  },
  AvgDialog_54067_Content_165 = {
    Text = "海洋來到了枯葉身前。"
  },
  AvgDialog_54067_Content_167 = {
    Text = "舊日曆@3年，利莫里亞沉入深海，無人生還。"
  },
  AvgDialog_54067_Content_17 = {
    Text = "巨大的聲響，讓人群開始變得安靜下來。"
  },
  AvgDialog_54067_Content_18 = {
    Text = "天災……天災又開始了？"
  },
  AvgDialog_54067_Content_19 = {
    Text = "主祭大人……這是……天災快來了嗎？"
  },
  AvgDialog_54067_Content_2 = {
    Text = "呼嘯的狂風捲動暴雨，潑灑在廣場的人們身上。"
  },
  AvgDialog_54067_Content_20 = {
    Text = "天災從未消失。利莫里亞與天災同眠。"
  },
  AvgDialog_54067_Content_21 = {
    Text = "但利莫里亞也一直存在著，不是嗎？"
  },
  AvgDialog_54067_Content_22 = {
    Text = "沒錯……沒錯……"
  },
  AvgDialog_54067_Content_23 = {
    Text = "主祭大人，神國……神國什麼時候能來到呢？"
  },
  AvgDialog_54067_Content_27 = {
    Text = "彌利亞姆離開了侍衛的保護，來到祭祀台邊。"
  },
  AvgDialog_54067_Content_28 = {
    Text = "無數雙手伸出來，信徒們向她的方向洶湧地擠動著，想要獲得利莫里亞主祭的祝福。"
  },
  AvgDialog_54067_Content_29 = {
    Text = "她掃視了一眼，眼神平靜，帶著微笑，但那道目光，讓信徒們的嘈雜迅速平息了下來。"
  },
  AvgDialog_54067_Content_3 = {
    Text = "人們已經許久未曾見過這樣的暴雨，但他們的呼喊聲，依然蓋過了海島的怒號。"
  },
  AvgDialog_54067_Content_30 = {
    Text = "風雨的喧囂中，她伸出手，觸碰那位信徒的額頭。"
  },
  AvgDialog_54067_Content_31 = {
    Text = "信徒雙手抱在胸前，跪在了地上。"
  },
  AvgDialog_54067_Content_32 = {
    Text = "只要信仰王，王便會回應你的信仰……"
  },
  AvgDialog_54067_Content_33 = {
    Text = "所以，告訴我，你信仰王嗎？你願意將你的一切，獻予王嗎？"
  },
  AvgDialog_54067_Content_34 = {
    Text = "我信仰王，主祭大人！我願意將一切都獻予王！"
  },
  AvgDialog_54067_Content_35 = {
    Text = "我是王最忠實的追隨者！"
  },
  AvgDialog_54067_Content_36 = {
    Text = "我願意！主祭大人，我願意！"
  },
  AvgDialog_54067_Content_37 = {
    Text = "那麼現在，和我一起頌念王的名字——"
  },
  AvgDialog_54067_Content_38 = {
    Text = "她環視著廣場上的每個人。"
  },
  AvgDialog_54067_Content_39 = {
    Text = "狂風暴雨裡，所有人都跪了下去，張開雙臂，望向神殿裡王座的方向。"
  },
  AvgDialog_54067_Content_4 = {
    Text = "主祭大人！主祭大人為我們帶來王的神諭了！"
  },
  AvgDialog_54067_Content_40 = {
    Text = "在星輝蒼穹之下，深海古國之上，為吾主虔誠禱告："
  },
  AvgDialog_54067_Content_41 = {
    Text = "願您的慧眼洞察災禍，\n願您的智慧引領子民。"
  },
  AvgDialog_54067_Content_42 = {
    Text = "“願您的慧眼洞察災禍，\n願您的智慧引領子民！”"
  },
  AvgDialog_54067_Content_43 = {
    Text = "風暴靜伏，水波不興；\n震盪平息，大地安寧。"
  },
  AvgDialog_54067_Content_44 = {
    Text = "災禍在您的寧靜夢境中化為虛無。\n在您的庇護中，我們迎來神的國度。"
  },
  AvgDialog_54067_Content_45 = {
    Text = "“災禍在您的寧靜夢境中化為虛無！”"
  },
  AvgDialog_54067_Content_46 = {
    Text = "“在您的庇護中，\n我們迎來神的國度……”"
  },
  AvgDialog_54067_Content_47 = {Text = "轟……"},
  AvgDialog_54067_Content_48 = {
    Text = "轟鳴聲中，數根巨大的觸手從神殿下方破土而出。"
  },
  AvgDialog_54067_Content_49 = {
    Text = "是王！王的神蹟現身了！！！"
  },
  AvgDialog_54067_Content_5 = {
    Text = "讚頌吾主！讚頌主祭大人！"
  },
  AvgDialog_54067_Content_50 = {
    Text = "信徒們張開雙臂，瘋狂地歡呼著。"
  },
  AvgDialog_54067_Content_51 = {
    Text = "觸手在風雨中微微擺動著，利莫里亞的所有人都毫不懷疑，這些利莫里亞的偉大神祇，擁有能夠抵禦一切災厄的力量。"
  },
  AvgDialog_54067_Content_52 = {
    Text = "吾主，圖魯——"
  },
  AvgDialog_54067_Content_53 = {
    Text = "吾主，圖魯！！圖魯！！！"
  },
  AvgDialog_54067_Content_54 = {
    Text = "她轉過身，望著神殿內部的方向，跪倒在地。"
  },
  AvgDialog_54067_Content_55 = {
    Text = "在無人能看到的眼裡，沒有任何主祭的期冀與威嚴，只剩下迷茫。"
  },
  AvgDialog_54067_Content_56 = {
    Text = "請聆聽您信徒的呼喚。請為我們，帶來神國。"
  },
  AvgDialog_54067_Content_57 = {
    Text = "請為我們，帶來神國！"
  },
  AvgDialog_54067_Content_58 = {
    Text = "吾主！神國！哈哈哈……神國就要降臨了！"
  },
  AvgDialog_54067_Content_59 = {
    Text = "伴隨著瘋狂的呼喊聲，觸手開始舞動。深海的靜謐氣息從觸手上傳來，從神殿傳往利莫里亞的每一寸土地，傳入每個利莫里亞人的感官裡。"
  },
  AvgDialog_54067_Content_6 = {
    Text = "主祭大人會帶我們見到神國的！"
  },
  AvgDialog_54067_Content_60 = {Text = "轟——"},
  AvgDialog_54067_Content_61 = {
    Text = "滾滾雷聲裡，歡呼聲平息。閃電從天空亮起，照耀著利莫里亞孤單的土地。"
  },
  AvgDialog_54067_Content_62 = {
    Text = "在這狂歡的一刻，信徒們的動作停了下來，停在對王至高的頌念與信仰裡，停在對未來無限的暢想與希冀中。"
  },
  AvgDialog_54067_Content_63 = {
    Text = "暴雨之下，利莫里亞的子民們酣然入夢。"
  },
  AvgDialog_54067_Content_65 = {
    Text = "石板門關上的聲音變得漫長沉重。"
  },
  AvgDialog_54067_Content_66 = {
    Text = "強烈的魚腥味塞滿整個房間。原本空曠的禱告室，在此時變得無比擁擠。"
  },
  AvgDialog_54067_Content_67 = {
    Text = "所有的魚人都被從水池中撈起，擺放在禱告室的地板上。"
  },
  AvgDialog_54067_Content_68 = {
    Text = "侍衛們並不知道這位新任主祭想要做什麼，他們也沒有機會再知道了。"
  },
  AvgDialog_54067_Content_69 = {
    Text = "彌利亞姆來到房間的角落，蹲下身，撫摸離自己最近的那隻魚人。"
  },
  AvgDialog_54067_Content_7 = {
    Text = "狂熱的歡呼聲像是海浪，向祭祀台湧來。"
  },
  AvgDialog_54067_Content_70 = {
    Text = "「父親……是你嗎？」"
  },
  AvgDialog_54067_Content_71 = {
    Text = "「我是彌利亞姆，你的女兒。」"
  },
  AvgDialog_54067_Content_72 = {
    Text = "「如果你能聽到的話，回應我，好嗎？父親……」"
  },
  AvgDialog_54067_Content_73 = {
    Text = "「……嗚……嗚……」"
  },
  AvgDialog_54067_Content_74 = {
    Text = "魚人的鰓一開一合，嘴唇上下翕動，發出意義不明的嗚咽，和平日裡的聲音沒有任何區別。"
  },
  AvgDialog_54067_Content_75 = {
    Text = "彌利亞姆走向第二隻，蹲下身，撫摸牠。"
  },
  AvgDialog_54067_Content_76 = {
    Text = "「父親，我成為利莫里亞的主祭了，我比你曾經所夢想的做得還要更好……」"
  },
  AvgDialog_54067_Content_77 = {
    Text = "「我沒有讓你失望，父親……睜開眼看看我吧……」"
  },
  AvgDialog_54067_Content_78 = {
    Text = "魚人巨大的眼睛胡亂地望著這個陌生的地方，對它面前這個主祭沒有半點興趣。"
  },
  AvgDialog_54067_Content_79 = {
    Text = "她走向第三隻。"
  },
  AvgDialog_54067_Content_8 = {
    Text = "人群湧動著，讓彌利亞姆想起池子裡那些瞪著眼睛的魚。"
  },
  AvgDialog_54067_Content_80 = {
    Text = "「我見到了王，我們信奉的王……可王告訴我，利莫里亞就要覆滅了。」"
  },
  AvgDialog_54067_Content_81 = {
    Text = "「王說，我能拯救利莫里亞，我能將利莫里亞帶回來……」"
  },
  AvgDialog_54067_Content_82 = {
    Text = "「我沒辦法相信王的話，可是那樣，我就只能相信我們一直生活在謊言裡，我們做的一切，我對你做的那些……那些事，都沒有任何意義。」"
  },
  AvgDialog_54067_Content_83 = {
    Text = "「我不知道，我不知道……父親，我該怎麼做？」"
  },
  AvgDialog_54067_Content_84 = {
    Text = "「睜開眼看看我吧，父親……和我說說話，再摸一下我的頭，就一下……」"
  },
  AvgDialog_54067_Content_85 = {
    Text = "魚人盯著它。茫然的眼神，就像在盯著一株晃動著的紫色水草。"
  },
  AvgDialog_54067_Content_86 = {
    Text = "彌利亞姆走向下一隻，再下一隻……她蹲下身，一隻隻地撫摸牠們，親吻牠們。"
  },
  AvgDialog_54067_Content_87 = {
    Text = "老師帶給她職責，王帶給她希望。而那個能夠傾聽她的迷茫與痛苦的人，那個能夠撫摸著她的頭安慰她的人，早已經不在了。"
  },
  AvgDialog_54067_Content_88 = {
    Text = "她一隻隻地湊到牠們耳邊，向牠們傾訴，在牠們之中尋覓著。"
  },
  AvgDialog_54067_Content_89 = {
    Text = "父親還活著嗎？活下來的那隻魚人，還能算自己的父親嗎？"
  },
  AvgDialog_54067_Content_9 = {
    Text = "如同沉入深海，海水灌滿她的感官。圖像變得模糊，聲音變得混沌。"
  },
  AvgDialog_54067_Content_90 = {
    Text = "她不知道。她不關心。"
  },
  AvgDialog_54067_Content_91 = {
    Text = "暴雨聲穿透牆壁傳了進來。偌大的禱告室裡，無數的魚人在躺在地上，擺動著牠們的肢體與尾鰭。"
  },
  AvgDialog_54067_Content_92 = {
    Text = "一個紫色的身影，在這些魚人之間穿行，尋覓，訴說。"
  },
  AvgDialog_54067_Content_93 = {
    Text = "半截破損的雕像，端坐在殘缺的王座之上，靜靜地望著她。"
  },
