  },
  AvgDialog_58289_Content_89 = {
    Text = "你嚇得抓住萊克的衣領。匍匐弓背的偵探敏捷地越過大大小小的房簷，穿梭在倫蒂尼恩鱗次櫛比的建築中。"
  },
  AvgDialog_58289_Content_90 = {
    Text = "一人一狼奔襲在安靜的月下。"
  },
  AvgDialog_58289_Content_91 = {
    Text = "耳畔只聽見乾淨的風聲，你低下身子，將自己靠向身下柔軟的絨毛中。"
  },
  AvgDialog_58289_Content_92 = {
    Text = "怎麼樣，好玩嗎？"
  },
  AvgDialog_58289_Content_93 = {
    Text = "想不到你還有這種本事……<Big:減速，申請減速！>"
  },
  AvgDialog_58289_Content_94 = {
    Text = "萊克哈哈大笑，胸腔不斷震顫，彷彿全身上下每一個細胞都在歡呼雀躍。"
  },
  AvgDialog_58289_Content_95 = {
    Text = "這才是一匹狼該幹的事！我只是做回了老本行，明白嗎？"
  },
  AvgDialog_58289_Content_96 = {
    Text = "我說了，<BigShake:減速！！>"
  },
  AvgDialog_58289_Content_97 = {
    Text = "輕點，別亂抓我的毛！"
  },
  AvgDialog_58290_Content_1 = {
    Text = "幽靈之家"
  },
  AvgDialog_58290_Content_10 = {
    Text = "牌桌上戰局正酣，無人理會你的小小疑問。"
  },
  AvgDialog_58290_Content_11 = {
    Text = "<BigShake:打擾各位雅興！>"
  },
  AvgDialog_58290_Content_12 = {
    Text = "請問誰還記得我們是被困在一個該死的瘋癲神祇的密境裡？"
  },
  AvgDialog_58290_Content_13 = {
    Text = "糾正一下，瘋癲且健忘的神祇。現在我們要做的就是保存體力，等祂什麼時候想起來再告訴我們題目，不是嗎？"
  },
  AvgDialog_58290_Content_14 = {
    Text = "同花順，漂亮！"
  },
  AvgDialog_58290_Content_16 = {
    Text = "算了，我去附近調查一下。"
  },
  AvgDialog_58290_Content_17 = {
    Text = "法蘭德宅邸\n一樓書房"
  },
  AvgDialog_58290_Content_18 = {
    Text = "唔……這傢伙的書果然全是從沒翻過的豪華精裝版，真不知道他是怎麼當上彌薩格教授的。"
  },
  AvgDialog_58290_Content_19 = {
    Text = "咦，這是什麼？"
  },
  AvgDialog_58290_Content_2 = {
    Text = "法蘭德宅邸\n兩小時後"
  },
  AvgDialog_58290_Content_20 = {
    Text = "無人注意的角落裡，一口黑色的棺材吸引了你的注意。"
  },
  AvgDialog_58290_Content_21 = {
    Text = "棺材兩側以金色的染料繪製著繁複的圖案與符號，從中間的縫隙中隱約湧出黑色的濃霧。"
  },
  AvgDialog_58290_Content_22 = {
    Text = "唔——完全推不開。"
  },
  AvgDialog_58290_Content_23 = {
    Text = "看上去有點像古勒姆瓦希的風格，德克斯特從哪裡搞來的？"
  },
  AvgDialog_58290_Content_24 = {
    Text = "你好奇地伸出手，輕輕撫上棺木外側鎏金的花紋，然而——"
  },
  AvgDialog_58290_Content_25 = {
    Text = "阿波菲斯，這個黑色法老就是卡納克。\n你供奉他，他活著，他活著，他活著。"
  },
  AvgDialog_58290_Content_26 = {
    Text = "阿波菲斯，他沒死，他沒死，阿波菲斯。"
  },
  AvgDialog_58290_Content_28 = {
    Text = "怎麼了，勳爵大人？臉色怎麼這麼蒼白？"
  },
  AvgDialog_58290_Content_29 = {
    Text = "抱歉，有點急事，我先失陪一下。"
  },
  AvgDialog_58290_Content_3 = {
    Text = "看來好運女神今夜並未眷顧你，萊克先生。"
  },
  AvgDialog_58290_Content_30 = {
    Text = "又跑了一個，本大爺眼看就要回本了……機器人助理和魔術師呢？"
  },
  AvgDialog_58290_Content_31 = {
    Text = "唔，剛才我看到艾瑞卡小姐往樓上去了。至於卡茜亞小姐嘛，回來後就沒人見過她了。"
  },
  AvgDialog_58290_Content_32 = {
    Text = "我也有些累了，想出去透透氣。"
  },
  AvgDialog_58290_Content_33 = {
    Text = "可外面下著很大的雪，您會著涼的，索蕾爾夫人！"
  },
  AvgDialog_58290_Content_34 = {
    Text = "這裡並非真實的世界，不必拘泥常規。退一步來說，偶爾欣賞欣賞雪景也不錯，不是嗎？"
  },
  AvgDialog_58290_Content_35 = {
    Text = "索蕾爾搖曳著優雅的步伐離開了，原本熱鬧的大廳瞬間冷清下來。"
  },
  AvgDialog_58290_Content_36 = {
    Text = "<SmallShake:老大，咱們打牌只是個幌子吧？我知道你一定早有計劃！>"
  },
  AvgDialog_58290_Content_38 = {
    Text = "對了！剛才德克斯特先生的反應很奇怪。走，我們去他的臥室看看。"
  },
  AvgDialog_58290_Content_39 = {
    Text = "哇哦收到！偵探遊戲終於開始了！"
  },
  AvgDialog_58290_Content_4 = {
    Text = "底池已經超過一萬雷歐坊了，還要繼續加注嗎？"
  },
  AvgDialog_58290_Content_40 = {
    Text = "法蘭德宅邸\n樓梯口"
  },
  AvgDialog_58290_Content_41 = {
    Text = "老大，你確定德克斯特先生在臥室裡嗎？我怎麼覺得他剛才往書房的方向去了。"
  },
  AvgDialog_58290_Content_42 = {
    Text = "唔……我很難告訴你我的推導過程。你可以將它理解為一種奇怪的直覺。"
  },
  AvgDialog_58290_Content_43 = {
    Text = "我明白了！這就是傳說中的，名偵探的直覺！！"
  },
  AvgDialog_58290_Content_44 = {
    Text = "放心吧老大，我不會質疑您一個字。"
  },
  AvgDialog_58290_Content_45 = {
    Text = "漢娜拍拍胸脯，又掏出隨身攜帶的放大鏡四處查看。"
  },
  AvgDialog_58290_Content_46 = {
    Text = "第215次調查行動，正式開始！首先是眼前由黑桃木雕刻而成的樓梯，低調、奢華，與世無爭……"
  },
  AvgDialog_58290_Content_47 = {
    Text = "考慮轉行嗎，漢娜小姐？我忽然覺得你很適合去<Blue:亨氏公司>做廣告銷售。"
  },
  AvgDialog_58290_Content_48 = {
    Text = "請不要打斷別人的偵查工作！最後呢，是樓梯口的雕花窗戶——"
  },
  AvgDialog_58290_Content_5 = {
    Text = "……當然。"
  },
  AvgDialog_58290_Content_50 = {
    Text = "透鏡正對著的不遠處，影影綽綽的黑影從窗外一晃而過。"
  },
  AvgDialog_58290_Content_51 = {
    Text = "啊啊啊啊啊！幽、幽靈！！"
  },
  AvgDialog_58290_Content_52 = {
    Text = "麻煩說點我能聽懂的話，漢娜小姐。"
  },
  AvgDialog_58290_Content_53 = {
    Text = "<Shake:德克斯特先生的幽靈！就在樓梯口！往天上飛、飛走了！>"
  },
  AvgDialog_58290_Content_54 = {
    Text = "萊克上前兩步打開窗。風呼呼吹著，雪花在空中紛亂飛舞，漫無目的地四處飄落。"
  },
  AvgDialog_58290_Content_55 = {
    Text = "他抬起頭，二樓室內溫暖的燈光為雪花鍍上了一層淺淺的橙色。"
  },
  AvgDialog_58290_Content_56 = {
    Text = "有意思，不止一個房間開著燈……上去看看吧。"
  },
  AvgDialog_58290_Content_57 = {
    Text = "法蘭德宅邸\n二樓走廊"
  },
  AvgDialog_58290_Content_58 = {
    Text = "咦，門鎖住了。"
  },
  AvgDialog_58290_Content_59 = {
    Text = "德克斯特先生，您在裡面嗎？現在感覺好些了嗎？"
  },
  AvgDialog_58290_Content_6 = {
    Text = "聽到您這麼說我就放心了，萊克先生。等出了密境我會拜託管家把帳單都寄給你的。"
  },
  AvgDialog_58290_Content_60 = {
    Text = "屋內死一般的寂靜。不知過了多久，從裡面傳來德克斯特模糊的聲音。"
  },
  AvgDialog_58290_Content_61 = {
    Text = "抱歉，我現在感覺不太舒服。能讓我稍微休息一會嗎？"
  },
  AvgDialog_58290_Content_62 = {
    Text = "被你猜中了，他真的在裡面。現在怎麼辦？"
  },
  AvgDialog_58290_Content_63 = {
    Text = "先撤吧。這可是貴族老爺的宅邸，基本的禮節咱們還是要講的。"
  },
  AvgDialog_58290_Content_64 = {
    Text = "萊克一邊說著，向後倒退了幾步。"
  },
  AvgDialog_58290_Content_65 = {
    Text = "隨後他猛地加速躍起，一腳踹向房門——"
  },
  AvgDialog_58290_Content_66 = {
    Text = "嘩啦！！"
  },
  AvgDialog_58290_Content_67 = {
    Text = "堅實的橡木門瞬間被踹出了一個大洞。萊克將手伸進洞裡，輕鬆摸到門把手，從容地將門打開。"
  },
  AvgDialog_58290_Content_68 = {
    Text = "女士優先，請——"
  },
  AvgDialog_58290_Content_7 = {
    Text = "麻煩連我們的帳單一起寄給他，嘻嘻嘻~"
  },
  AvgDialog_58290_Content_70 = {
    Text = "<Shake:說好的禮、禮節呢？>"
  },
  AvgDialog_58290_Content_71 = {
    Text = "很抱歉，我那點不多的教養禮節僅針對人類。睜大眼看看，那是什麼？"
  },
  AvgDialog_58290_Content_72 = {
    Text = "漢娜順著萊克的眼神向前望去。只見書桌旁放著一架立式黑膠唱機，漆黑的唱片正緩緩旋轉。"
  },
  AvgDialog_58290_Content_73 = {
    Text = "抱歉，我現在感覺不太舒服。能讓我稍微休息一會嗎？"
  },
  AvgDialog_58290_Content_76 = {
    Text = "請各位儘早離開，勿要打擾德克斯特先生休息。"
  },
  AvgDialog_58290_Content_77 = {
    Text = "<Shake:嗚哇！！你是什麼時候……>"
  },
  AvgDialog_58290_Content_78 = {
    Text = "艾瑞卡小姐，雖然你已經被那傢伙變成白痴了，但我還是要提醒一下……"
  },
  AvgDialog_58290_Content_79 = {
    Text = "這裡連德克斯特的一根毛都沒有。"
  },
  AvgDialog_58290_Content_8 = {
    Text = "真見鬼！N那傢伙，一定對我動了什麼手腳……"
  },
  AvgDialog_58290_Content_80 = {
    Text = "請各位儘早離開，勿要……"
  },
  AvgDialog_58290_Content_81 = {
    Text = "算了，先別管她了。這個黑膠唱機究竟是怎麼回事？"
  },
  AvgDialog_58290_Content_82 = {
    Text = "很簡單。有人在製造不在場證明，可惜被我第一時間識破了。"
  },
  AvgDialog_58290_Content_83 = {
    Text = "原來如此。我明白了！在偵探小說裡，有不在場證明的地方就有兇——"
  },
  AvgDialog_58290_Content_85 = {
    Text = "一聲突兀的槍響劃破了寂靜的夜。"
  },
  AvgDialog_58290_Content_86 = {
    Text = "<Shake:那是……樓、樓下傳出來的……>"
  },
  AvgDialog_58290_Content_87 = {
    Text = "過去看看。遊戲恐怕……已經開始了。"
  },
  AvgDialog_58290_Content_9 = {
    Text = "打擾一下……"
  },
  AvgDialog_58291_Content_1 = {
    Text = "無人生還"
  },
  AvgDialog_58291_Content_10 = {
    Text = "法蘭德宅邸\n11：45 PM"
  },
  AvgDialog_58291_Content_100 = {
    Text = "行行行，都聽你們的——"
  },
  AvgDialog_58291_Content_101 = {
    Text = "很好，接下來的時間就由艾瑞卡帶各位玩耍吧，還有1124個生物等著和我簽訂惡魔契約呢。"
  },
  AvgDialog_58291_Content_102 = {
    Text = "記住……"
  },
  AvgDialog_58291_Content_103 = {
    Text = "<Red:壞人就潛藏在大家中間哦，千萬不要相信任何人。>"
  },
  AvgDialog_58291_Content_106 = {
    Text = "看什麼看，人家還什麼都沒來得及做呢！"
  },
  AvgDialog_58291_Content_107 = {
    Text = "哦？不妨說說看，你原本計劃做什麼？"
  },
  AvgDialog_58291_Content_108 = {
    Text = "非常棒，請大家繼續發揚這股吵架的勁頭，不要因為我的在場而影響發揮！"
  },
  AvgDialog_58291_Content_109 = {
    Text = "我們的行為準則第一條，混亂！第二條，混亂！第三條……"
  },
  AvgDialog_58291_Content_11 = {
    Text = "沉重木門被一把推開。萊克張開雙臂，帶著一股略顯浮誇的熱情走進大廳。"
  },
  AvgDialog_58291_Content_110 = {
    Text = "讓我猜猜看，還是混亂？"
  },
  AvgDialog_58291_Content_111 = {
    Text = "錯！是<Red:無盡的混亂>！"
  },
  AvgDialog_58291_Content_113 = {
    Text = "那麼，祝大家玩得開心~"
  },
  AvgDialog_58291_Content_114 = {
    Text = "N說罷便化為濃黑的霧氣消失了，留下面面相覷的眾人。"
  },
  AvgDialog_58291_Content_115 = {
    Text = "%player%，這傢伙究竟是哪裡來的討厭鬼？你們似乎和祂是老相識？"
  },
  AvgDialog_58291_Content_116 = {
    Text = "你沉吟著，猶豫要不要將知道的一切告訴漢娜。但很快你便意識到自己多慮了。"
  },
  AvgDialog_58291_Content_117 = {
    Text = "對於N，你也同樣一無所知。"
  },
  AvgDialog_58291_Content_118 = {
    Text = "抱歉，我也不知道這傢伙的底細。祂變了副模樣後，性格也更……"
  },
  AvgDialog_58291_Content_119 = {
    Text = "你本想說“活潑”，話到嘴邊又生生嚥下。"
  },
  AvgDialog_58291_Content_12 = {
    Text = "德克斯特，我的老夥計！才幾天沒見，這就等不及約我們來你的宅邸再續前緣？"
  },
  AvgDialog_58291_Content_120 = {
    Text = "更討人厭了。"
  },
  AvgDialog_58291_Content_121 = {
    Text = "如果我沒理解錯的話，我們是要解開謎題，找到<Yellow:最後的真相>吧？"
  },
  AvgDialog_58291_Content_122 = {
    Text = "唔……是這樣沒錯。"
  },
  AvgDialog_58291_Content_123 = {
    Text = "有個小小的問題。這傢伙似乎忘記說題目了。"
  },
  AvgDialog_58291_Content_124 = {
    Text = "確實是無盡的混亂。"
  },
  AvgDialog_58291_Content_125 = {
    Text = "你望向前方早已被破壞殆盡的斷橋。漆黑的山谷彷彿不見底的深淵，將你們與遠處的島嶼徹底隔開。"
  },
  AvgDialog_58291_Content_126 = {
    Text = "德克斯特先生，你確定這是唯一一條通往外界的路嗎？"
  },
  AvgDialog_58291_Content_127 = {
    Text = "德克斯特無奈地聳聳肩。"
  },
  AvgDialog_58291_Content_128 = {
    Text = "當初看上這裡是因為它足夠偏僻，能替我擋掉許多無意義的社交與關注。"
  },
  AvgDialog_58291_Content_129 = {
    Text = "沒想到弄巧成拙了。"
  },
  AvgDialog_58291_Content_13 = {
    Text = "當然，我不得不提醒你，這種邀請方式未免有些小小的極端。"
  },
  AvgDialog_58291_Content_130 = {
    Text = "雪紛紛揚揚地下著，很快便將損毀的木橋覆蓋。"
  },
  AvgDialog_58291_Content_131 = {
    Text = "哈啾！暴雪、偏僻的山莊、還有莫名其妙湊到一塊的人……"
  },
  AvgDialog_58291_Content_132 = {
    Text = "我有種不太好的預感。"
  },
  AvgDialog_58291_Content_14 = {
    Text = "<Small:喂，說好的埋伏呢！>"
  },
  AvgDialog_58291_Content_15 = {
    Text = "我知道你們在暗示什麼——不是我做的。"
  },
  AvgDialog_58291_Content_16 = {
    Text = "德克斯特端坐長桌盡頭，有些不耐煩地抓了抓凌亂的頭髮。"
  },
  AvgDialog_58291_Content_17 = {
    Text = "<Gray:拉蒙娜似乎說過，德克斯特先生被打斷睡眠的時候，脾氣會變得很暴躁……>"
  },
  AvgDialog_58291_Content_18 = {
    Text = "原本我在家裡好好睡著覺，突然冒出一群人敲門，僕人還全都消失了。"
  },
  AvgDialog_58291_Content_19 = {
    Text = "我到現在也不明白發生了什麼。"
  },
  AvgDialog_58291_Content_2 = {
    Text = "法蘭德宅邸\n11：30 PM"
  },
  AvgDialog_58291_Content_22 = {
    Text = "眼前白光閃爍了一瞬，室內旋即恢復了原本的靜寂。"
  },
  AvgDialog_58291_Content_23 = {
    Text = "唔，還是什麼都拍不到。這裡果然不正常……"
  },
  AvgDialog_58291_Content_24 = {
    Text = "漢娜？！你怎麼在這裡？"
  },
  AvgDialog_58291_Content_25 = {
    Text = "哼哼，推理協會副會長的頭銜可不是白來的！找路我最擅長了。"
  },
  AvgDialog_58291_Content_28 = {
    Text = "老大……？想不到你倆居然認識。"
  },
  AvgDialog_58291_Content_29 = {
    Text = "萊克先生可是東區有名的偵探，我倆聯手配合無間，壞人見了我們都要繞路走！"
  },
  AvgDialog_58291_Content_3 = {
    Text = "喲嚯！速降成功~"
  },
  AvgDialog_58291_Content_30 = {
    Text = "咳咳，請收斂一下你的職業習慣，現在可不是在寫新聞稿。"
  },
  AvgDialog_58291_Content_31 = {
    Text = "萊克朝你無奈地攤了攤手。"
  },
  AvgDialog_58291_Content_32 = {
    Text = "我有些案子會拜託她替我跑個腿，作為回報，這傢伙從我這套了不少情報，算是互惠互利吧。"
  },
  AvgDialog_58291_Content_33 = {
    Text = "說起互惠互利，另一位聽說也和彌薩格關係匪淺？"
  },
  AvgDialog_58291_Content_34 = {
    Text = "你順著萊克的視線望去，只見角落陰影裡，衣著華貴的女子手持紅酒杯，朝你微笑致意。"
  },
  AvgDialog_58291_Content_35 = {
    Text = "又見面了，守密人%sirormadam%。"
  },
  AvgDialog_58291_Content_36 = {
    Text = "索蕾爾夫人？！你，你怎麼也……"
  },
  AvgDialog_58291_Content_37 = {
    Text = "很遺憾，我原本期待我們能在更加正式的場合再會的。"
  },
  AvgDialog_58291_Content_38 = {
    Text = "可惜這裡只有偏遠的宅邸和手裡的空酒杯，又該做點什麼打發時間呢？"
  },
  AvgDialog_58291_Content_39 = {
    Text = "當然是把酒斟滿，徹夜暢飲囉~！"
  },
  AvgDialog_58291_Content_4 = {
    Text = "你確定德克斯特住在這種鬼地方嗎？他該不會破產了吧。"
  },
  AvgDialog_58291_Content_40 = {
    Text = "伴隨輕快愉悅的女聲，索蕾爾杯中的紅酒奇蹟般回滿了。"
  },
  AvgDialog_58291_Content_41 = {
    Text = "真令人吃驚，是霞多麗紅酒的味道……這是怎麼辦到的？"
  },
  AvgDialog_58291_Content_42 = {
    Text = "嘻嘻，這算什麼，看這個——"
  },
  AvgDialog_58291_Content_43 = {
    Text = "卡茜亞用手杖在杯沿輕輕敲了一下，紅酒又瞬間綻放出朵朵鮮紅的薔薇，在燈光映射下輕輕顫動。"
  },
  AvgDialog_58291_Content_44 = {
    Text = "她摘下其中最嬌豔的一朵，輕輕別在了索蕾爾耳後。"
  },
  AvgDialog_58291_Content_45 = {
    Text = "最嬌豔的薔薇，送給倫蒂尼恩最嬌豔的美人。"
  },
  AvgDialog_58291_Content_46 = {
    Text = "非常精彩，魔術師小姐！請問你對宮廷職位感興趣嗎，我一定要向女王陛下引薦你。"
  },
  AvgDialog_58291_Content_47 = {
    Text = "價錢到位的話，什麼都好說……"
  },
  AvgDialog_58291_Content_48 = {
    Text = "咦，這不是咱們的守密人%sirormadam%和偵探先生嗎？"
  },
  AvgDialog_58291_Content_49 = {
    Text = "卡茜亞一臉驚訝的模樣，彷彿才剛剛看到你們。"
  },
  AvgDialog_58291_Content_5 = {
    Text = "不好意思，這是他名下五十餘處房產中最不起眼的一個。"
  },
  AvgDialog_58291_Content_50 = {
    Text = "自亞蘭一別，我可是每天都在思念你們呢。"
  },
  AvgDialog_58291_Content_53 = {
    Text = "等一等！威廉不是我殺的，卡茜亞只是個可憐的打工仔罷了。你們也不想在這位紳士家裡大開殺戒吧？"
  },
  AvgDialog_58291_Content_54 = {
    Text = "沒關係，我不介意咱們出去好好交流一下。"
  },
  AvgDialog_58291_Content_55 = {
    Text = "嘶……事先聲明，我對這裡的地形早就摸得一清二楚了。"
  },
  AvgDialog_58291_Content_56 = {
    Text = "打不過也能跑……"
  },
  AvgDialog_58291_Content_58 = {
    Text = "巨大的時鐘忽然高懸眾人頭頂，錶盤上的時間來到午夜十二點整。"
  },
  AvgDialog_58291_Content_59 = {
    Text = "女士們，先生們，晚上好！歡迎來到我的樂園！"
  },
  AvgDialog_58291_Content_6 = {
    Text = "嘶…我忽然想到一個絕妙的點子——"
  },
  AvgDialog_58291_Content_60 = {
    Text = "唔啊啊！這小孩怎麼沒有臉！"
  },
  AvgDialog_58291_Content_61 = {
    Text = "這熟悉的打扮和感覺，難道是……"
  },
  AvgDialog_58291_Content_62 = {
    Text = "恭喜大家憑藉各自的聰明才智與合作精神，成功通過了我設置的第一個難題。"
  },
  AvgDialog_58291_Content_63 = {
    Text = "暖場時間已經結束，接下來請聽正題——"
  },
  AvgDialog_58291_Content_65 = {
    Text = "子彈精準從神秘小人的面龐穿過，在中間留下了一個大大的空洞。"
  },
  AvgDialog_58291_Content_66 = {
    Text = "不好意思，手槍不小心走火了。過家家遊戲好玩嗎，N？"
  },
  AvgDialog_58291_Content_68 = {
    Text = "N面部殘餘的黑霧不斷扭曲、延展，迅速填滿了空洞。"
  },
  AvgDialog_58291_Content_69 = {
    Text = "真沒意思，這麼快就被大家認出來了。"
  },
  AvgDialog_58291_Content_7 = {
    Text = "話說在前面，別打德克斯特先生的歪主意。他對任何形式的賭博、不明投資以及風險創業都毫無興趣。"
  },
  AvgDialog_58291_Content_70 = {
    Text = "萊克先生在月下奔襲的時候，可是開心得很呢。喜歡我為你量身定制的過家家遊戲嗎？"
  },
  AvgDialog_58291_Content_71 = {
    Text = "呵……挺一般的。這是你的密境？"
  },
  AvgDialog_58291_Content_72 = {
    Text = "當然。想出去的話，就給我留在這棟房子裡，乖乖解開我設置的難題。"
  },
  AvgDialog_58291_Content_73 = {
    Text = "喂，這可是我的房子，沒人徵詢一下我的意見嗎？"
  },
  AvgDialog_58291_Content_75 = {
    Text = "轟隆隆！！"
  },
  AvgDialog_58291_Content_76 = {
    Text = "很好，我的小助理已經把通向外界唯一的橋梁給鋸斷了。"
  },
  AvgDialog_58291_Content_77 = {
    Text = "這下你們哪裡都去不了啦！"
  },
  AvgDialog_58291_Content_78 = {
    Text = "什麼？！快出去看看——"
  },
  AvgDialog_58291_Content_79 = {
    Text = "四下一片寂靜，你們站在懸崖邊的斷橋面前，沉默不語。"
  },
  AvgDialog_58291_Content_8 = {
    Text = "被無情打斷的偵探悻悻縮回手，只倔強地抬起下巴點了點不遠處的宅邸。"
  },
  AvgDialog_58291_Content_80 = {
    Text = "天邊不知何時下起了大雪，紛紛揚揚地飄在空中。"
  },
  AvgDialog_58291_Content_81 = {
    Text = "你握緊了胸前的暗淡的銀鑰匙。從踏入這片土地的瞬間起，你和它就徹底斷開了聯結。"
  },
  AvgDialog_58291_Content_82 = {
    Text = "沒用的哦，我已經隔絕了你們和@2的聯結，現在你們沒有任何超出常人的特殊能力。"
  },
  AvgDialog_58291_Content_83 = {
    Text = "果然是你幹的……"
  },
  AvgDialog_58291_Content_84 = {
    Text = "放心吧，就算把眼珠子瞪出來也沒用哦。"
  },
  AvgDialog_58291_Content_85 = {
    Text = "真正的勇者就該像普通人一樣解決問題。我說得對嗎，艾瑞卡？"
  },
  AvgDialog_58291_Content_87 = {
    Text = "機械的腳步聲自角落響起。"
  },
  AvgDialog_58291_Content_88 = {
    Text = "艾瑞卡手持一個巨大的電鋸，猛地伸長手臂，連接義肢的伸縮繩被拉伸到一個極遠的距離，竟然將對面的橋也鋸斷了。"
  },
  AvgDialog_58291_Content_9 = {
    Text = "咳咳，你想到哪裡去了？我的意思是咱們最好早點進去，然後埋伏起來打探情報……"
  },
  AvgDialog_58291_Content_90 = {
    Text = "這傢伙的機械臂可真有意思。得想個辦法搞到手……"
  },
  AvgDialog_58291_Content_91 = {
    Text = "艾瑞卡關閉電鋸開關，走到N的身後，甚至還恭謹地彎下了腰。"
  },
  AvgDialog_58291_Content_92 = {
    Text = "稟報主人，法蘭德通向外界的唯一通道已被損毀，共計耗時5分40秒，耗電……"
  },
  AvgDialog_58291_Content_93 = {
    Text = "你這傢伙……你對艾瑞卡小姐做了什麼？！"
  },
  AvgDialog_58291_Content_94 = {
    Text = "N輕巧地跳到艾瑞卡的肩上，悠閒地翹起了二郎腿。"
  },
  AvgDialog_58291_Content_95 = {
    Text = "放心吧，只是稍微用我的人格魅力影響了一下她的意識。介紹一下，這是我的新助理，艾瑞卡。"
  },
  AvgDialog_58291_Content_96 = {
    Text = "艾瑞卡，快和大家說晚上好。"
  },
  AvgDialog_58291_Content_97 = {
    Text = "晚上好，接下來的時間艾瑞卡將負責監督照顧各位，請大家隨我回到宅邸。"
  },
  AvgDialog_58291_Content_98 = {
    Text = "事先聲明一下，如果有人膽敢違抗我新招的小助理……"
  },
  AvgDialog_58291_Content_99 = {
    Text = "N輕輕摁下艾瑞卡手中的電鋸開關，震耳欲聾的噪音使所有人第一時間摀住了耳朵。"
  },
  AvgDialog_58292_Content_1 = {
    Text = "初次會晤"
  },
  AvgDialog_58292_Content_10 = {
    Text = "可、可我和萊克先生一直在一起，對吧老大？"
  },
  AvgDialog_58292_Content_11 = {
    Text = "無人回應漢娜略帶心虛的呼喚。"
  },
  AvgDialog_58292_Content_12 = {
    Text = "就在房屋的另一頭，偵探先生和他的臨時助理已經開啟了現場調查。"
  },
  AvgDialog_58292_Content_13 = {
    Text = "兩隻鞋子都不見了。頸部的勒痕也有兩道，真奇怪。"
  },
  AvgDialog_58292_Content_14 = {
    Text = "你用放大鏡細細觀察德克斯特先生脖頸上的兩條勒痕。它們的走向幾乎一致，只不過有些許傾斜角度的差異。"
  },
  AvgDialog_58292_Content_15 = {
    Text = "兩道勒痕的紋路也不一致。裡面是很規整的菱形結構，外面的更加粗糙……"
  },
  AvgDialog_58292_Content_16 = {
    Text = "或許是中途繩子斷了，或許是沾上了血跡，於是兇手又更換了一條繩子。"
  },
  AvgDialog_58292_Content_17 = {
    Text = "不論如何，兩道勒痕都從頸部前面經過下顎，再蔓延至耳部後側，朝著後頭頂逐漸消失……"
  },
  AvgDialog_58292_Content_18 = {
    Text = "這是上吊自殺才會出現的勒痕。"
  },
  AvgDialog_58292_Content_19 = {
    Text = "不，不對……勒痕附近有抓傷痕跡，說明死者經歷過劇烈的掙扎。"
  },
  AvgDialog_58292_Content_2 = {
    Text = "法蘭德宅邸 一樓書房\n距離案情結束還剩 <Red:90> 分鐘"
  },
  AvgDialog_58292_Content_20 = {
    Text = "也可能是上吊後又開始後悔了？我聽說過類似的案例。"
  },
  AvgDialog_58292_Content_21 = {
    Text = "如果沒有那盤黑膠唱片的話，十個警察有九個到這裡就要按照自殺結案了。"
  },
  AvgDialog_58292_Content_22 = {
    Text = "而我就是那僅存的、目光如炬的十分之一！"
  },
  AvgDialog_58292_Content_23 = {
    Text = "黑膠唱片？"
  },
  AvgDialog_58292_Content_24 = {
    Text = "守密人%sirormadam%當時不在現場吧！有一盤黑膠唱片不斷循環播放德克斯特先生的聲音，像幽靈一樣……"
  },
  AvgDialog_58292_Content_25 = {
    Text = "突然擠入你們中間的漢娜繪聲繪色地描述著，又忍不住打了個寒顫。"
  },
  AvgDialog_58292_Content_26 = {
    Text = "老大，剛才我們找了一圈都沒看到索蕾爾夫人的蹤影。難道她已經……"
  },
  AvgDialog_58292_Content_27 = {
    Text = "萊克自信地擺了擺手。"
  },
  AvgDialog_58292_Content_28 = {
    Text = "很快你們就會知道她在哪裡了。這案子和我當年偵辦過的第一起兇殺案幾乎一模一樣。"
  },
  AvgDialog_58292_Content_29 = {
    Text = "這就是老大剛才所謂“直覺”的由來麼……"
  },
  AvgDialog_58292_Content_3 = {
    Text = "人家當時在屋外閒逛，尋找有沒有離開這裡的路。"
  },
  AvgDialog_58292_Content_30 = {
    Text = "咳咳，真不好意思。的確如此。"
  },
  AvgDialog_58292_Content_31 = {
    Text = "黑膠唱片、荒蕪宅邸、神秘上吊的男主人……漢娜也想起來了！"
  },
  AvgDialog_58292_Content_32 = {
    Text = "《神秘狗頭男子破獲豪門驚情》，我到現在都還能記得當年的新聞頭條！"
  },
  AvgDialog_58292_Content_33 = {
    Text = "狗頭？這是你自己胡謅的標題吧，在外我一直都以翩翩君子的形象示人。"
  },
  AvgDialog_58292_Content_34 = {
    Text = "一提及萊克的過去，你立刻來了興趣，將漢娜拽了過來。"
  },
  AvgDialog_58292_Content_35 = {
    Text = "<Small:說起來，我一直覺得這傢伙的偵探身份很可疑。>"
  },
  AvgDialog_58292_Content_36 = {
    Text = "<Small:要知道在倫蒂尼恩，破獲一起案件能獲得的酬勞遠不如待在賭桌上十分鐘的收益。>"
  },
  AvgDialog_58292_Content_37 = {
    Text = "<Small:或許所謂的偵探身份只是個幌子……>"
  },
  AvgDialog_58292_Content_38 = {
    Text = "請收回你對我的人身攻擊，守密人%player%。賭徒也是可以有自己的愛好和事業的。"
  },
  AvgDialog_58292_Content_39 = {
    Text = "咦，這裡怎麼還放了個棺材？德克斯特的品味可真不敢恭維。"
  },
  AvgDialog_58292_Content_4 = {
    Text = "也就是說，沒有不在場證明。記下記下……後來你找到路了嗎，卡茜亞小姐？"
  },
  AvgDialog_58292_Content_41 = {
    Text = "別碰它！"
  },
  AvgDialog_58292_Content_42 = {
    Text = "話音未落，偵探已經漫不經心地朝棺材踢了兩腳。回應他的，是死一般的寂靜。"
  },
  AvgDialog_58292_Content_43 = {
    Text = "奇怪……它對你的觸碰似乎毫無反應？"
  },
  AvgDialog_58292_Content_44 = {
    Text = "哦？那你倒是說說看，它應該有什麼樣的反應呢？"
  },
  AvgDialog_58292_Content_45 = {
    Text = "你將先前遭遇的種種告訴了萊克。"
  },
  AvgDialog_58292_Content_46 = {
    Text = "原來如此……我明白了！"
  },
  AvgDialog_58292_Content_47 = {
    Text = "這裡面一定裝著一具神秘的、魔法高強的至尊木乃伊！"
  },
  AvgDialog_58292_Content_48 = {
    Text = "萊克忽然蹲下身子，嘴裡說著你完全聽不懂的“外語”。"
  },
  AvgDialog_58292_Content_49 = {
    Text = "泥蒿！珩篙緈 見稲泥@3！"
  },
  AvgDialog_58292_Content_5 = {
    Text = "動動你的小腦瓜，偵探小姐。如果我找到了，現在還會站在你們面前嗎？"
  },
  AvgDialog_58292_Content_50 = {
    Text = "……你在說什麼？"
  },
  AvgDialog_58292_Content_51 = {
    Text = "勒姆瓦西語啊。蝸晈萊殼，泥晈森嚒閔緇？"
  },
  AvgDialog_58292_Content_52 = {
    Text = "面對外界友善卻稍顯難懂的問候，黑棺依舊肅穆，不發一語。"
  },
  AvgDialog_58292_Content_53 = {
    Text = "好了，別玩了。我聽過亞蘭的古語，發音和你沒有一丁點相似之處。"
  },
  AvgDialog_58292_Content_54 = {
    Text = "嘖，真沒意思。接著幹正事吧。"
  },
  AvgDialog_58292_Content_55 = {
    Text = "萊克起身悠閒地伸了個懶腰，朝空中打了兩個響指。"
  },
  AvgDialog_58292_Content_56 = {
    Text = "好了各位，我已經知道兇手是誰了。為了節約時間，我就省略推理過程，直接帶你們抓人吧。"
  },
  AvgDialog_58292_Content_58 = {
    Text = "噗嗤。要是有小說家敢像萊克先生這樣推動劇情，恐怕早就被憤怒的讀者懸吊在路燈下了。"
  },
  AvgDialog_58292_Content_59 = {
    Text = "連一點小小的提示也不願意分享嗎？"
  },
  AvgDialog_58292_Content_60 = {
    Text = "萊克有些煩躁地抓了抓頭髮。"
  },
  AvgDialog_58292_Content_61 = {
    Text = "黑膠唱片。它的存在很可能是兇手想製造不在場證據，將案發時間延後。"
  },
  AvgDialog_58292_Content_62 = {
    Text = "也就是說，就在黑膠唱片播放死者聲音的同時，兇手事實上正在案發現場。"
  },
  AvgDialog_58292_Content_63 = {
    Text = "巧妙的詭計，但很不幸，我並未按照兇手設想的套路行動。聽到聲音後，我沒有選擇離開，而是把門踹開了。"
  },
  AvgDialog_58292_Content_64 = {
    Text = "合格的偵探拆解罪犯的不在場證明，卓越的偵探從根源上掐斷罪犯的不在場證明！"
  },
  AvgDialog_58292_Content_65 = {
    Text = "記下這句至理名言了嗎，漢娜？"
  },
  AvgDialog_58292_Content_66 = {
    Text = "啊？記、記下了，老大！"
  },
  AvgDialog_58292_Content_67 = {
    Text = "不過老大，你剛才說兇手就在案發現場……那……"
  },
  AvgDialog_58292_Content_68 = {
    Text = "萊克掏出手槍，邁著悠閒的步伐向前走去。"
  },
  AvgDialog_58292_Content_69 = {
    Text = "接下來請出我們從案發到現在都未曾出現，只能慌亂地縮在暗處的兇手小姐。"
  },
  AvgDialog_58292_Content_7 = {
    Text = "一樓廚房。主人吩咐為大家準備食物。"
  },
  AvgDialog_58292_Content_70 = {
    Text = "偵探在衣櫃前停下腳步，在門上輕輕敲了兩聲。"
  },
  AvgDialog_58292_Content_71 = {
    Text = "還想躲到最後一刻嗎？那我可就不客氣了——"
  },
  AvgDialog_58292_Content_72 = {
    Text = "偵探有些苦惱地用槍管在太陽穴蹭了蹭，隨後一把拉開衣櫃門。"
  },
  AvgDialog_58292_Content_73 = {
    Text = "索蕾爾……"
  },
  AvgDialog_58292_Content_75 = {
    Text = "索蕾爾夫人！！！"
  },
  AvgDialog_58292_Content_76 = {
    Text = "沒有拙劣的辯解，沒有狼狽的躲藏，也沒有痛哭流涕的懺悔。"
  },
  AvgDialog_58292_Content_77 = {
    Text = "只有索蕾爾的屍體安靜地靠在角落，眉心的彈孔顯得分外刺眼，彷彿在嘲笑偵探那自以為是的賣弄。"
  },
  AvgDialog_58292_Content_78 = {
    Text = "不……這不可能……"
  },
  AvgDialog_58292_Content_79 = {
    Text = "鏘鏘鏘！"
  },
  AvgDialog_58292_Content_8 = {
    Text = "期間沒人去過廚房，也就是說，艾瑞卡小姐同樣沒有不在場證明……"
  },
  AvgDialog_58292_Content_80 = {
    Text = "我好像聽到有人給出了錯誤推理哦！"
  },
  AvgDialog_58292_Content_81 = {
    Text = "誣陷一個清白無辜的人類可是無法被饒恕的重罪，接下來就是懲罰時間了！"
  },
  AvgDialog_58292_Content_82 = {
    Text = "N有些苦惱地托著圓圓的下巴。每當祂思索的時候，面部霧氣湧動的速度也會慢下來。"
  },
  AvgDialog_58292_Content_83 = {
    Text = "懲罰，懲罰……該殺掉誰好呢？"
  },
  AvgDialog_58292_Content_9 = {
    Text = "很遺憾，偵探小姐。站在我們的角度來看，你、守密人以及萊克先生也很可疑哦~"
  },
  AvgDialog_58293_Content_1 = {Text = "棺中牆"},
  AvgDialog_58293_Content_10 = {
    Text = "這應該是最後一次見面了，但你的心沒有一絲起伏。"
  },
  AvgDialog_58293_Content_12 = {
    Text = "卡納克，我的名字叫卡納克。"
  },
  AvgDialog_58293_Content_14 = {
    Text = "唔……好奇怪的夢。我怎麼在走廊裡……自從碰了那具棺材，腦子裡一直亂亂的。"
  },
  AvgDialog_58293_Content_16 = {
    Text = "伴隨一陣急促的腳步聲，你和一團黑影迎面撞上。"
  },
  AvgDialog_58293_Content_17 = {
    Text = "哎喲！別擋路……咦，竟然是守密人%sirormadam%！"
  },
  AvgDialog_58293_Content_18 = {
    Text = "呼……幸好你沒事。我還以為……"
  },
  AvgDialog_58293_Content_19 = {
    Text = "你們兩個怎麼在這裡？發生什麼事了嗎？"
  },
  AvgDialog_58293_Content_20 = {
    Text = "悄悄告訴你們，獵殺遊戲已經開始了哦~"
  },
  AvgDialog_58293_Content_21 = {
    Text = "纖瘦的身體自黑暗中劃過，卡茜亞如同變魔術一般輕盈地落在你們面前。"
  },
  AvgDialog_58293_Content_22 = {
    Text = "我知道槍聲是從哪裡傳出來的，要和我一起去看看嗎？人家一個人有點害怕呢。"
  },
  AvgDialog_58293_Content_23 = {
    Text = "你從哪裡冒出來的……"
  },
  AvgDialog_58293_Content_24 = {
    Text = "卡茜亞剛才一直躺在天花板的吊燈上睡覺呢。俗話說，站得高看得遠……"
  },
  AvgDialog_58293_Content_25 = {
    Text = "人家可什麼都看見了哦~"
  },
  AvgDialog_58293_Content_26 = {
    Text = "卡茜亞說罷，笑嘻嘻地朝你拋了個媚眼。"
  },
  AvgDialog_58293_Content_28 = {
    Text = "都愣著做什麼？不想第一時間見證案發現場嗎？"
  },
  AvgDialog_58293_Content_29 = {
    Text = "法蘭德宅邸\n一樓書房"
  },
  AvgDialog_58293_Content_3 = {
    Text = "就到這裡吧，接下來咱倆就要分道揚鑣了。你還要找那個什麼<Yellow:真理之牆>嗎？"
  },
  AvgDialog_58293_Content_30 = {
    Text = "你們一把推開書房門。"
  },
  AvgDialog_58293_Content_31 = {
    Text = "這、這是……"
  },
  AvgDialog_58293_Content_33 = {
    Text = "男人被繩索懸吊在房梁下，彷彿風中飄零的落葉。他臉上被青紫色的陰霾籠罩，雙眼幾欲瞪出眼眶。"
  },
  AvgDialog_58293_Content_34 = {
    Text = "請大家稍安勿躁，以免破壞犯罪現場。"
  },
  AvgDialog_58293_Content_35 = {
    Text = "犯罪……現場？"
  },
  AvgDialog_58293_Content_36 = {
    Text = "別看啦，這傢伙死得透透的。讓我猜猜看，這就是留給我們的謎題吧？"
  },
  AvgDialog_58293_Content_37 = {
    Text = "某種偵探推理遊戲？"
  },
  AvgDialog_58293_Content_38 = {
    Text = "賓果！答對了~！"
  },
  AvgDialog_58293_Content_39 = {
    Text = "那麼究竟是誰，在這樣一個大雪紛飛的夜裡，殘忍地殺害了一位風度翩翩的貴族紳士呢？"
  },
  AvgDialog_58293_Content_4 = {
    Text = "“你”點了點頭。"
  },
  AvgDialog_58293_Content_40 = {
    Text = "請試著找出真相吧，各位名偵探。"
  },
  AvgDialog_58293_Content_41 = {
    Text = "真奇怪，嫌疑最大的難道不是您嗎，親愛的N先生？"
  },
  AvgDialog_58293_Content_42 = {
    Text = "咳咳，容我更精確一些——請找出由我的分身假扮的兇手吧！"
  },
  AvgDialog_58293_Content_43 = {
    Text = "就在諸位中間哦！"
  },
  AvgDialog_58293_Content_44 = {
    Text = "死一般的寂靜。"
  },
  AvgDialog_58293_Content_45 = {
    Text = "疑懼與不安在人群中悄然蔓延。眼神似不經意掃過其他人，默默咀嚼N話語中的真實性。"
  },
  AvgDialog_58293_Content_46 = {
    Text = "如果我們拒絕這個遊戲呢？"
  },
  AvgDialog_58293_Content_47 = {
    Text = "你們知道對於像我這樣充滿理想與熱情的遊戲設計師，最重要的是什麼嗎？"
  },
  AvgDialog_58293_Content_48 = {
    Text = "當然是玩家的參與度！如果大家都不感興趣，那我只能遺憾宣布遊戲結束囉！"
  },
  AvgDialog_58293_Content_49 = {
    Text = "無人回應。大家都在等待後面的“但是”——"
  },
  AvgDialog_58293_Content_5 = {
    Text = "那我就不勸你了。說實話我一直搞不懂你……你這傢伙看著年輕，卻又像活了幾千年。"
  },
  AvgDialog_58293_Content_51 = {
    Text = "可憐的德克斯特先生與艾爾莎小姐，只能永遠和你們說再見了。"
  },
  AvgDialog_58293_Content_52 = {
    Text = "彌薩格醫務室\n與此同時……"
  },
  AvgDialog_58293_Content_53 = {
    Text = "情況怎麼樣了？"
  },
  AvgDialog_58293_Content_54 = {
    Text = "很不樂觀。艾爾莎顱內出血嚴重，腦脊液壓力持續攀升，體溫一直維持在100華氏度以上。"
  },
  AvgDialog_58293_Content_55 = {
    Text = "守密人和漢娜則陷入了某種譫妄狀態。雖然一直昏睡不醒，但身體各項指徵都正常。"
  },
  AvgDialog_58293_Content_57 = {
    Text = "少女並未指代姓名，但在場所有人都知道她在說誰。"
  },
  AvgDialog_58293_Content_58 = {
    Text = "德克斯特先生……初步診斷為壓迫神經引起反射性心跳停止，像是經歷了某種機械性窒息。"
  },
  AvgDialog_58293_Content_6 = {
    Text = "不管怎麼說，謝了。我已經拿到了解開封印的方法，接下來就該去羅馬，把那頭野獸放出來……"
  },
  AvgDialog_58293_Content_60 = {
    Text = "溫柯爾點點頭。"
  },
  AvgDialog_58293_Content_61 = {
    Text = "搶救無效，五分鐘前已經停止呼吸了。從理論上來講……"
  },
  AvgDialog_58293_Content_62 = {
    Text = "他已經死了。"
  },
  AvgDialog_58293_Content_63 = {
    Text = "法蘭德宅邸\n一樓書房"
  },
  AvgDialog_58293_Content_64 = {
    Text = "也就是說，如果我們不按你的規矩來，這裡死去的人在現實世界裡也無法醒來？"
  },
  AvgDialog_58293_Content_65 = {
    Text = "N滿意地點點頭。"
  },
  AvgDialog_58293_Content_66 = {
    Text = "不愧是最了解我的那一個！"
  },
  AvgDialog_58293_Content_67 = {
    Text = "……呵，我一點也不為此感到自豪。"
  },
  AvgDialog_58293_Content_68 = {
    Text = "萬一這只不過是唬人的把戲呢？你要如何證明自己沒有撒謊？"
  },
  AvgDialog_58293_Content_69 = {
    Text = "我當然可以證明——但我不想，嘻嘻。"
  },
  AvgDialog_58293_Content_7 = {
    Text = "巫師費力地打包好行李，剛走了幾步又回過頭來。"
  },
  AvgDialog_58293_Content_70 = {
    Text = "或者你們也可以賭一把試試看？立刻結束遊戲，回到你們可愛的小世界，一切都沒有改變。"
  },
  AvgDialog_58293_Content_71 = {
    Text = "被窩永遠溫暖，考試繼續進行，大家都健康地活著。"
  },
  AvgDialog_58293_Content_72 = {
    Text = "N望向萊克，激情洋溢地張開小小的雙臂。"
  },
  AvgDialog_58293_Content_73 = {
    Text = "怎麼樣，來賭一把嗎？這可是你最擅長的事。"
  },
  AvgDialog_58293_Content_74 = {
    Text = "不好意思，我從不拿別人的命來賭。"
  },
  AvgDialog_58293_Content_75 = {
    Text = "遊戲才剛剛開始呢，這麼快結束未免太沒意思了！"
  },
  AvgDialog_58293_Content_76 = {
    Text = "卡茜亞直起身，“蹭”地舉起右手。"
  },
  AvgDialog_58293_Content_77 = {
    Text = "嗶嗶！我贊成繼續遊戲~！"
  },
  AvgDialog_58293_Content_78 = {
    Text = "一番討論後，出於不同的理由，大家這次出奇地達成了一致。"
  },
  AvgDialog_58293_Content_79 = {
    Text = "真令人感動！感謝大家無條件尊重我的設計成果！"
  },
  AvgDialog_58293_Content_8 = {
    Text = "喂，你還沒告訴我你的名字呢。"
  },
  AvgDialog_58293_Content_80 = {
    Text = "那麼我在此宣布：<Red:第二輪考驗正式開始！>"
  },
  AvgDialog_58293_Content_81 = {
    Text = "諸位足足有兩個小時的時間解開謎題哦~"
  },
  AvgDialog_58293_Content_82 = {
    Text = "才兩個小時，這怎麼夠……"
  },
  AvgDialog_58293_Content_83 = {
    Text = "哦呵呵，就在某些人質疑尊貴的N大人的時候，時間又過去了整整十秒。"
  },
  AvgDialog_58293_Content_84 = {
    Text = "那麼，祝各位玩得開心~"
  },
  AvgDialog_58293_Content_85 = {
    Text = "N說罷化作漆黑的煙霧，悄無聲息地消失了。"
  },
  AvgDialog_58293_Content_87 = {
    Text = "萊克沉吟著，忽然伸手掐了一把你的臉。"
  },
  AvgDialog_58293_Content_88 = {
    Text = "痛…喂，你這是做什麼？！"
  },
  AvgDialog_58293_Content_89 = {
    Text = "放輕鬆。確認一下你是不是冒牌貨。"
  },
  AvgDialog_58293_Content_9 = {
    Text = "風帶起一陣陣金色的細沙。衣衫襤褸的巫師背靠藍天，紅撲撲的臉上難得透出一份善意。"
  },
  AvgDialog_58293_Content_90 = {
    Text = "唔，適度的謹慎是必要的。那麼——"
  },
  AvgDialog_58293_Content_91 = {
    Text = "你一把揪住萊克臉上蓬鬆的毛髮，狠狠拔下來幾根。"
