  AvgDialog_60327_Content_28 = {
    Text = "你戰勝了我們……你拯救了我們。"
  },
  AvgDialog_60327_Content_3 = {
    Text = "你飛身躍出，在坍塌的神像中，接住了那個虛弱的身影。"
  },
  AvgDialog_60327_Content_30 = {
    Text = "你順著拉蒙娜的目光望去。"
  },
  AvgDialog_60327_Content_31 = {
    Text = "在石像身後，那兩扇巨大的石質門扉停止了移動，內部那無數幻景變得平靜下來。"
  },
  AvgDialog_60327_Content_32 = {
    Text = "繁複的色彩在門內緩緩流動，如同一場永遠不會醒來的夢。"
  },
  AvgDialog_60327_Content_5 = {
    Text = "拉蒙娜看著你。你有些分不清她是存在於哪個維度，也分不清她究竟是拉蒙娜、是塔薇，還是誰。"
  },
  AvgDialog_60327_Content_6 = {
    Text = "但這些不重要。重要的是，她回到了你的身邊，如同過往的無數次。"
  },
  AvgDialog_60327_Content_7 = {
    Text = "你拉住她的手，就像第一天成為守密人時那樣。"
  },
  AvgDialog_60327_Content_8 = {
    Text = "源源不斷的精神力，如同汪洋般匯入銀鑰匙中，傳入拉蒙娜的體內。"
  },
  AvgDialog_60327_Content_9 = {
    Text = "嗚啊啊——"
  },
  AvgDialog_60340_Content_10 = {
