  },
  AvgDialog_60344_Content_10 = {
    Text = "拉蒙娜，給你們添麻煩了。要是沒有受傷，我或許還能幫你分擔一些……"
  },
  AvgDialog_60344_Content_100 = {
    Text = "他站起身，微笑著摸了摸肩上的無毛貓。"
  },
  AvgDialog_60344_Content_101 = {
    Text = "貓抬起頭，百無聊賴的眼睛掃視了一圈周圍的人類，以此作答。"
  },
  AvgDialog_60344_Content_11 = {
    Text = "不用說這種話，院長。\n彌薩格人從不把傷患視為累贅。"
  },
  AvgDialog_60344_Content_12 = {
    Text = "等把你們放到生命科學院的大樓裡，我們就可以……"
  },
  AvgDialog_60344_Content_13 = {
    Text = "需要我送你們一程嗎，拉蒙娜小姐？"
  },
  AvgDialog_60344_Content_16 = {
    Text = "拉蒙娜舉起劍橫在自己身前。"
  },
  AvgDialog_60344_Content_17 = {
    Text = "在她身後，茜爾維婭皺緊眉頭，護著虛弱的訶勒特。"
  },
  AvgDialog_60344_Content_18 = {
    Text = "一陣急促的腳步聲響起，似乎已在這裡埋伏了多時。"
  },
  AvgDialog_60344_Content_19 = {
    Text = "狹窄的甬道兩頭，身穿審查會制服的探員密密麻麻地堵住了他們的去路。"
  },
  AvgDialog_60344_Content_2 = {
    Text = "狹長的走廊中看不見任何的人影。一陣沉重的呼吸與腳步聲響起，在走廊中迴蕩著。"
  },
  AvgDialog_60344_Content_20 = {
    Text = "獨眼男人一邊走到人群之前，一邊溫柔地逗弄著肩膀上那只被縫上了兩顆頭顱的無毛貓。"
  },
  AvgDialog_60344_Content_22 = {
    Text = "看到出現在面前的這張臉，訶勒特的身子一下子緊繃起來。"
  },
  AvgDialog_60344_Content_23 = {
    Text = "赫伯特……你這個混帳……"
  },
  AvgDialog_60344_Content_24 = {
    Text = "克勞利老師像對自己的孩子一樣對你，你卻殺了他，篡奪了他的學術成果……事到如今，你居然還有臉回來……"
  },
  AvgDialog_60344_Content_25 = {
    Text = "噓，訶勒特同學……啊不，應該叫你，訶勒特院長。"
  },
  AvgDialog_60344_Content_26 = {
    Text = "在我離開之後，院長的位置，當然非你莫屬。"
  },
  AvgDialog_60344_Content_27 = {
    Text = "我很想和你一起追憶曾經美好的求學時光，不過今天我來這裡，還有其他正事要做。"
  },
  AvgDialog_60344_Content_29 = {
    Text = "許久不見，真是讓人想念啊，拉蒙娜小姐。"
  },
  AvgDialog_60344_Content_3 = {
    Text = "呼……訶勒特院長，請再堅持一下，我們就快到了。"
  },
  AvgDialog_60344_Content_30 = {
    Text = "不過是在這段時間裡見過幾面，不用說得這麼熟悉。"
  },
  AvgDialog_60344_Content_31 = {
    Text = "這段時間？不，不。"
  },
  AvgDialog_60344_Content_32 = {
    Text = "赫伯特抬眼，他的目光越過訶勒特，越過拉蒙娜，最終落入黑暗的虛空之中，彷彿望著遙遠得觸不可及的某處。"
  },
  AvgDialog_60344_Content_33 = {
    Text = "我還記得第一次見到你的時候，似乎就是在這個通道裡。"
  },
  AvgDialog_60344_Content_34 = {
    Text = "那時候你才……這麼大……"
  },
  AvgDialog_60344_Content_35 = {
    Text = "赫伯特伸出雙手，比出一隻無毛貓的長度。"
  },
  AvgDialog_60344_Content_36 = {
    Text = "你是……什麼意思？"
  },
  AvgDialog_60344_Content_38 = {
    Text = "希洛是失敗的產物，那對孱弱的異星雙子也無力承擔偉大的使命。\n在我和提燈教會的合作裡，你是最完美的結晶。"
  },
  AvgDialog_60344_Content_4 = {
    Text = "拉蒙娜同學，請小心傷口……"
  },
  AvgDialog_60344_Content_40 = {
    Text = "你還不明白嗎，拉蒙娜？"
  },
  AvgDialog_60344_Content_41 = {
    Text = "那些你在意的人們，受到驚嚇，受到傷害，面臨失控和死亡的威脅……彌薩格遭受的這一切災難，都是因為你啊。"
  },
  AvgDialog_60344_Content_42 = {
    Text = "你……說什麼？"
  },
  AvgDialog_60344_Content_43 = {
    Text = "看著拉蒙娜手中嗡鳴顫抖的劍，赫伯特微笑著向前走了兩步。"
  },
  AvgDialog_60344_Content_44 = {
    Text = "很多年前，德克斯特這個小偷把你從我們手裡偷走了。"
  },
  AvgDialog_60344_Content_45 = {
    Text = "這一天晚了很久，不過沒有關係——它來的正是時候。"
  },
  AvgDialog_60344_Content_46 = {
    Text = "你是珍貴的雙子，是提燈的完美造物。"
  },
  AvgDialog_60344_Content_47 = {
    Text = "我們此次前來，就是為了重新找回你。"
  },
  AvgDialog_60344_Content_49 = {
    Text = "我向你保證，只要你安靜跟我離開，彌薩格所受的驚擾便會全部停止。"
  },
  AvgDialog_60344_Content_5 = {
    Text = "她拿出手巾，細心擦拭乾淨拉蒙娜手臂上的血跡。"
  },
  AvgDialog_60344_Content_51 = {
    Text = "我在你眼裡是這麼愚蠢的人嗎，赫伯特？"
  },
  AvgDialog_60344_Content_52 = {
    Text = "這裡是彌薩格。無論你們的目的是什麼，我們都不會讓它得逞的。"
  },
  AvgDialog_60344_Content_53 = {
    Text = "看到拉蒙娜抬起的細劍，赫伯特輕輕搖動手指。"
  },
  AvgDialog_60344_Content_54 = {
    Text = "你當然是個聰明人，拉蒙娜。"
  },
  AvgDialog_60344_Content_55 = {
    Text = "你需要護送兩位缺乏自保能力的女士，所以選擇了這條鮮有人知的道路。"
  },
  AvgDialog_60344_Content_56 = {
    Text = "我完全相信你的突圍能力，若是獨身來此，我沒有把握攔住你。"
  },
  AvgDialog_60344_Content_57 = {
    Text = "不過，回頭看看那二位你敬愛的師長，訶勒特院長和茜爾維婭老師吧，拉蒙娜同學。"
  },
  AvgDialog_60344_Content_58 = {
    Text = "拉蒙娜環視著身邊虎視眈眈的審查會探員，手中的劍在胸前一動不動。"
  },
  AvgDialog_60344_Content_59 = {
    Text = "彌薩格的安危高於一切。做正確的事情，拉蒙娜。"
  },
  AvgDialog_60344_Content_60 = {
    Text = "訶勒特的話語悄聲傳入拉蒙娜耳中。她停頓了一下，沒有點頭。"
  },
  AvgDialog_60344_Content_61 = {
    Text = "片刻後，她抬起頭，望向赫伯特。"
