  AvgDialog_60344_Content_82 = {
    Text = "（我會帶其他喚醒體來救出你們。很快！）"
  },
  AvgDialog_60344_Content_83 = {
    Text = "拉蒙娜沒有時間將這些話說出口。這是唯一的機會，從這突然出現的豁口中，她奪路而出。"
  },
  AvgDialog_60344_Content_84 = {
    Text = "零星幾個探員們勉強反應了過來，但他們完全無法擋住拉蒙娜的劍。訶勒特和茜爾維婭對視一眼，臉上出現欣慰的神色。"
  },
  AvgDialog_60344_Content_85 = {
    Text = "赫伯特的餘光看到她們臉上的神情，笑著舉起手，輕輕揮了揮。"
  },
  AvgDialog_60344_Content_86 = {
    Text = "我們在此恭候您，無上的意志……"
  },
  AvgDialog_60344_Content_87 = {
    Text = "為了您的降誕，請賜福於我們，懲罰那不敬之人……"
  },
  AvgDialog_60344_Content_88 = {
    Text = "一陣古怪的音節從人群中飄出，落入拉蒙娜耳中那一刻，她的內臟猛地一緊，似乎被無形的繩索緊緊攥住，被奪取了全部的力氣。"
  },
  AvgDialog_60344_Content_89 = {
    Text = "她毫無防備，猛的墜倒在地，手中的細劍滾落一旁，在細小的金屬滑動聲後停在不遠處。\n拉蒙娜抬手，卻觸之不及。"
  },
  AvgDialog_60344_Content_90 = {
    Text = "這……這是……"
  },
  AvgDialog_60344_Content_91 = {
    Text = "即使是再廉價的提燈造物，體內都會留有提燈的印記。更何況是你。"
  },
  AvgDialog_60344_Content_92 = {
    Text = "你要找機會逃離，我也在等待提燈教會的人催動你體內的法印，這需要時間。"
  },
  AvgDialog_60344_Content_93 = {
    Text = "如果使用暴力手段，傷到了你，或是被你逃走，那就不太好了。"
