  AvgDialog_60351_Content_56 = {
    Text = "（德克斯特教授……父親？）"
  },
  AvgDialog_60351_Content_57 = {
    Text = "赫伯特不知道這個男人是怎麼突然出現在他身邊的。"
  },
  AvgDialog_60351_Content_58 = {
    Text = "他身邊，克萊門汀與審查會的成員將德克斯特團團圍住。"
  },
  AvgDialog_60351_Content_59 = {
    Text = "德克斯特似乎看不見那些對著他的刀槍，徑直走到拉蒙娜身邊，打量了一番。"
  },
  AvgDialog_60351_Content_6 = {
    Text = "甦醒吧。我的承載者。我的碎片。"
  },
  AvgDialog_60351_Content_60 = {
    Text = "當年就是你這個小偷將她奪走……今天，你和她都別想離開！"
