  AvgDialog_60351_Content_62 = {
    Text = "當然，也不用擔心我會做什麼。看到我女兒安然無恙我就放心了。你們把她照顧得這麼好，我可不舍得帶她走。"
  },
  AvgDialog_60351_Content_63 = {
    Text = "赫伯特皺著眉頭，認真地盯著德克斯特的眼睛，想要看清他在想什麼。"
  },
  AvgDialog_60351_Content_64 = {
