  },
  AvgDialog_60886_Content_19 = {
    Text = "德克斯特教授？誰是德克斯特教授？"
  },
  AvgDialog_60886_Content_2 = {
    Text = "可要是真的把她救出來了，這個故事豈不是就少了一出大戲可看？"
  },
  AvgDialog_60886_Content_20 = {
    Text = "守密人，你和拉蒙娜……你們真的認識德克斯特嗎？"
  },
  AvgDialog_60886_Content_21 = {
    Text = "你是什麼意思……我們怎麼可能……難道？！"
  },
  AvgDialog_60886_Content_22 = {
    Text = "你想起N的話。十九年來，他一直在扮演同一個角色……"
  },
  AvgDialog_60886_Content_23 = {
    Text = "瞳孔劇烈地收縮。你猛然抬起頭，望向N那張沒有五官的臉。"
  },
  AvgDialog_60886_Content_24 = {
    Text = "很棒，守密人。就是這個表情！"
  },
  AvgDialog_60886_Content_25 = {
    Text = "別動，保持。對，沒錯……讓我好好記住你現在的樣子……"
  },
  AvgDialog_60886_Content_26 = {
    Text = "可惜了，拉蒙娜知道這件事的時候，還沒有醒過來，我沒辦法看到她的表情。"
  },
  AvgDialog_60886_Content_27 = {
    Text = "我想，她的神情，大概和你的一樣精彩。"
  },
  AvgDialog_60886_Content_28 = {
    Text = "N的身體微微顫抖，似乎正在忍耐著強烈的笑意。"
  },
  AvgDialog_60886_Content_29 = {
    Text = "他俯下身，湊到你面前，仔細端詳著。"
  },
  AvgDialog_60886_Content_3 = {
    Text = "關心，懷念，悲切……一切情緒都從德克斯特臉上消失了。"
  },
  AvgDialog_60886_Content_30 = {
    Text = "你……為什麼要控制德克斯特教授？"
  },
  AvgDialog_60886_Content_31 = {
    Text = "控制？啊，不。控制是一種低劣的娛樂。"
  },
  AvgDialog_60886_Content_32 = {
    Text = "一個優秀的演員，要扮演，要成為。"
  },
  AvgDialog_60886_Content_33 = {
    Text = "他湊到你的耳邊，對你悄悄的耳語，彷彿要和你分享一個天大的秘密——"
  },
  AvgDialog_60886_Content_35 = {
    Text = "這些年，你和拉蒙娜，跟我相處得一定很愉快吧？"
  },
  AvgDialog_60886_Content_36 = {
    Text = "他的臉對著你。在那張空無的臉上，你似乎清晰地看到了那跋扈的五官。"
  },
  AvgDialog_60886_Content_37 = {
    Text = "他俯下身，湊在你面前，仔細端詳著，像是要記下你的每一個表情，每一個無法自控的顫抖。"
  },
  AvgDialog_60886_Content_38 = {
    Text = "一個風流的花花公子，一個深情的父親，我對這樣的角色本來沒有太多興趣。"
  },
  AvgDialog_60886_Content_39 = {
    Text = "我有興趣的，只是她……我的“女兒”。塔薇的雙子造物，拉蒙娜。"
  },
  AvgDialog_60886_Content_4 = {
    Text = "你看到，他向你露出一個完美的、沒有任何溫度的微笑。"
  },
  AvgDialog_60886_Content_40 = {
    Text = "N笑著望向黑池中央，塔薇所在的方向。"
  },
  AvgDialog_60886_Content_41 = {
    Text = "你……你為什麼要害死他……"
  },
  AvgDialog_60886_Content_42 = {
    Text = "你的誤會是多麼令人難過啊，守密人。"
  },
  AvgDialog_60886_Content_43 = {
    Text = "提燈的雙子計劃，豈是一個手無縛雞之力的花花公子能夠輕易抗衡的。可他竟然能夠把那個女嬰給偷出來。"
  },
  AvgDialog_60886_Content_44 = {
    Text = "看到我的時候，他的眼神就像是看到了救世主……哈。"
  },
  AvgDialog_60886_Content_45 = {
    Text = "N想起那段故事，愉悅地笑了笑。"
  },
  AvgDialog_60886_Content_46 = {
    Text = "他跟我做了個交易。你敢相信嗎？一個快死的普通人，跟我做交易……"
  },
  AvgDialog_60886_Content_47 = {
    Text = "他把一切都給了我。他的財產，他的地位，他的女兒……"
  },
  AvgDialog_60886_Content_48 = {
    Text = "他讓我扮演他，扮演他女兒的父親。"
  },
  AvgDialog_60886_Content_49 = {
    Text = "他是抱著那個女嬰死去的。臨死的時候，一直絮絮叨叨什麼父親會好好保護她之類的話……"
  },
  AvgDialog_60886_Content_5 = {
    Text = "德克斯特教授絕不會說出這樣的話……你到底是誰？！"
  },
  AvgDialog_60886_Content_50 = {
    Text = "彌薩格的那個內鬼……是你？"
  },
  AvgDialog_60886_Content_51 = {
    Text = "看著你疑惑、憤怒的眼睛，N無所謂地聳聳肩。"
  },
  AvgDialog_60886_Content_52 = {
    Text = "是我，不是我，有什麼要緊呢？很難相信，到現在你還有心情考慮這些。"
  },
  AvgDialog_60886_Content_53 = {
    Text = "扮演德克斯特，能夠近距離地待在彌薩格，還是提供了不錯的便利。"
  },
  AvgDialog_60886_Content_54 = {
    Text = "這個地方，簡直就是世界上最有趣的遊樂場。"
  },
  AvgDialog_60886_Content_55 = {
    Text = "看你們知道被我矇騙時的神情。看塔薇的計劃失敗時，那崩潰的姿態。"
  },
  AvgDialog_60886_Content_56 = {
    Text = "當然，還有你。"
  },
  AvgDialog_60886_Content_57 = {
    Text = "他望著你，舔舐著嘴唇，就像一個無邪的孩童，在望著一個即將被摧毀的玩具。"
  },
  AvgDialog_60886_Content_58 = {
    Text = "泰旖絲將她的種子贈予了你，她竟然相信你能帶她活下去……哈，這個瘋女人。"
  },
  AvgDialog_60886_Content_59 = {
    Text = "很可惜，她信錯了人。繁育的權柄，我就收下了。"
  },
  AvgDialog_60886_Content_6 = {
    Text = "他來到你面前，那雙熟悉的眼睛帶著陌生的笑意望向你。"
  },
  AvgDialog_60886_Content_60 = {
    Text = "讓我看看，當燃起的希望被奪走，你的臉上，會出現什麼樣的神情？"
  },
  AvgDialog_60886_Content_7 = {
    Text = "一道黑色的煙霧，從他身上氤氳升起，將他緩緩包裹。"
  },
  AvgDialog_60886_Content_8 = {
    Text = "對啊，我是誰呢……"
  },
  AvgDialog_60886_Content_9 = {
    Text = "揮霍無度的股東。愛女心切的父親。聲名遠播的花花公子。頗受歡迎的彌薩格教授。"
  },
  AvgDialog_60887_Content_1 = {
    Text = "只有這一個辦法了……"
  },
  AvgDialog_60887_Content_10 = {
    Text = "在這道聲音之後，恢弘的音樂從你們意識深處響起。"
  },
  AvgDialog_60887_Content_13 = {
    Text = "這……這是……"
  },
  AvgDialog_60887_Content_14 = {
    Text = "收起你的銀鑰匙。現在催動它，你會死。"
  },
  AvgDialog_60887_Content_15 = {
    Text = "節拍。旋律。絃樂柔和的泛音充盈你們的腦海。"
  },
  AvgDialog_60887_Content_16 = {
    Text = "那是一種神秘的頻段。審查會的人們在這道樂聲中痛苦地倒在地上，而你感到自己正被溫暖的泉水包裹、沖洗。"
  },
  AvgDialog_60887_Content_17 = {
    Text = "你明確感知到，自己和喚醒體們的連結重新恢復了過來。來自黑池的震盪，似乎也在這樂聲中消散殆盡。"
  },
  AvgDialog_60887_Content_18 = {
    Text = "克萊門汀訝異地望向這道聲音的主人。"
  },
  AvgDialog_60887_Content_19 = {
    Text = "是你！為什麼……"
  },
  AvgDialog_60887_Content_20 = {
    Text = "打擊樂，停止。"
  },
  AvgDialog_60887_Content_21 = {
    Text = "男子輕輕揮動指揮棒。一聲短促有力的命令式頓音，帶來了瞬間的寂靜。"
  },
  AvgDialog_60887_Content_22 = {
    Text = "克萊門汀再也支撐不住，倒在了地上。"
  },
  AvgDialog_60887_Content_24 = {
    Text = "其他的人很快就會趕到，我的樂聲撐不了多久。"
  },
  AvgDialog_60887_Content_25 = {
    Text = "我會帶你去一個安全的地方。"
  },
  AvgDialog_60887_Content_26 = {
    Text = "他轉過身，向你微微頷首，臉上的表情如古井般平靜。"
  },
  AvgDialog_60887_Content_27 = {
    Text = "指揮家哈姆林，為你效勞。"
  },
  AvgDialog_60887_Content_3 = {
    Text = "你舉起手。"
  },
  AvgDialog_60887_Content_4 = {
    Text = "我不會讓你們……"
  },
  AvgDialog_60887_Content_5 = {
    Text = "第二樂章，起。"
  },
  AvgDialog_60887_Content_8 = {
    Text = "沒等你手中的銀鑰匙發出刺傷你與敵人的耀眼光芒，一道清冷的聲音從你身後傳來。"
  },
  AvgDialog_60887_Content_9 = {
    Text = "那聲音是指揮家劃下的軌跡，是音符所構建的世界中不可忤逆的律令。"
  },
  AvgDialog_60888_Content_10 = {
    Text = "一分十五秒，觀眾的掌聲將如同雷鳴，經久不息，再逐漸消散。"
  },
  AvgDialog_60888_Content_11 = {
    Text = "二十五分，樂團與觀眾將完成離場。"
  },
  AvgDialog_60888_Content_12 = {
    Text = "時間與預想中分毫不差，如同第二場精准的演出。"
  },
  AvgDialog_60888_Content_13 = {
    Text = "指揮家滿意地點點頭，對著空空蕩蕩的觀眾席，鞠躬致意。"
  },
  AvgDialog_60888_Content_15 = {
    Text = "觀眾席側面不起眼的角落中，一道輕微的掌聲再次響起。"
  },
  AvgDialog_60888_Content_16 = {
    Text = "一場偉大的演出，哈姆林先生。"
  },
  AvgDialog_60888_Content_17 = {
    Text = "或許算得上完整，但遠遠還稱不上偉大。真正偉大的演出，在劇院之外。"
  },
  AvgDialog_60888_Content_18 = {
    Text = "指揮家收起指揮棒，皺著眉頭望向觀眾席側臺的女士。"
  },
  AvgDialog_60888_Content_19 = {
    Text = "我們有言在先，你不應該出現在劇院內，於麗埃特女士。"
  },
  AvgDialog_60888_Content_2 = {
    Text = "得趕緊告訴大家……還有守密人！"
  },
  AvgDialog_60888_Content_20 = {
    Text = "我們的合作與演出無關，我不希望我的演出受到任何打擾。我以為你清楚這一點。"
  },
  AvgDialog_60888_Content_21 = {
    Text = "另外，以你的身分出現在這裡，會帶來不必要的麻煩。"
  },
  AvgDialog_60888_Content_22 = {
    Text = "當然，哈姆林先生。只是，如果不來現場聽聽你的演出，我會非常遺憾的。"
  },
  AvgDialog_60888_Content_23 = {
    Text = "於麗埃特微笑著頷首致意，輕輕整理了一下衣襬上的皺褶。"
  },
  AvgDialog_60888_Content_24 = {
    Text = "對於哈姆林的表達方式，她早已習慣，並不在意。"
  },
  AvgDialog_60888_Content_25 = {
    Text = "另外，我也有重要的事情，需要向你當面告知。"
  },
  AvgDialog_60888_Content_26 = {
    Text = "行動開始了？"
  },
  AvgDialog_60888_Content_27 = {
    Text = "不錯。克萊門汀很順利地處理掉了彌薩格的巡邏者，我們比預想中爭取到了更多的時間。"
  },
  AvgDialog_60888_Content_28 = {
    Text = "你的計劃很成功。"
  },
  AvgDialog_60888_Content_29 = {
    Text = "只是一段並不複雜的前奏而已，現在說成功，為時尚早。"
  },
  AvgDialog_60888_Content_30 = {
    Text = "我相信你的智慧，指揮家先生。"
  },
  AvgDialog_60888_Content_31 = {
    Text = "這一天，我們等了多久了？"
  },
  AvgDialog_60888_Content_33 = {
    Text = "沒錯，十九年。一段漫長的時光。"
  },
  AvgDialog_60888_Content_34 = {
    Text = "雕塑家協會和蹈海者的遊戲，替我們吸引了足夠多的注意力，我們的身影隱藏得很好。"
  },
  AvgDialog_60888_Content_35 = {
    Text = "勒姆瓦希的計劃失敗，很遺憾，但也無關緊要。"
  },
  AvgDialog_60888_Content_36 = {
    Text = "真正重要的，只有今天——十九年後的今天。"
  },
  AvgDialog_60888_Content_37 = {
    Text = "能和你這樣的合作者一同見證這重要的時刻，是一件讓人愉悅的事情。"
  },
  AvgDialog_60888_Content_38 = {
    Text = "我們的目的一致。這場演出，並非是獻給你我。"
  },
  AvgDialog_60888_Content_39 = {
    Text = "為了再次聽到那位偉大存在所帶來的樂聲，所有的付出，都微不足道。"
  },
  AvgDialog_60888_Content_4 = {
    Text = "指揮家的指揮棒在空中劃過一道悠揚的弧線。樂章來到收尾的階段。"
  },
  AvgDialog_60888_Content_40 = {
    Text = "轉身，立定。年輕的指揮家抬起雙手，向空蕩蕩的劇院、向劇院外無人知曉的星河深處致禮。"
  },
  AvgDialog_60888_Content_41 = {
    Text = "一切都已就緒，準備動身吧，於麗埃特女士。"
  },
  AvgDialog_60888_Content_42 = {
    Text = "真正的演出，就要開始了。"
  },
  AvgDialog_60888_Content_5 = {
    Text = "強烈的和絃與複雜的多聲部所編織出的驚心動魄的音景平息下來。"
  },
  AvgDialog_60888_Content_6 = {
    Text = "長笛和豎琴的琶音緩緩飄出，如同黃昏正映照雲朵。"
  },
  AvgDialog_60888_Content_7 = {
    Text = "和諧綿長的和絃緩緩消散在空氣中，最後一記絃樂的休止記號將音符帶入尾聲。"
  },
  AvgDialog_60888_Content_8 = {
    Text = "在這悠遠的一刻，指揮家收起了指揮棒。他沉默地計算著。"
  },
  AvgDialog_60888_Content_9 = {
    Text = "十秒，觀眾陶醉於樂聲，劇院將陷入拂曉般的寂靜。"
  },
  AvgDialog_60889_Content_1 = {
    Text = "狹長的走廊中看不見任何的人影。一陣沉重的呼吸與腳步聲響起，在走廊中迴蕩著。"
  },
  AvgDialog_60889_Content_10 = {
    Text = "不用說這種話，院長。"
  },
  AvgDialog_60889_Content_11 = {
    Text = "等把你們放到生命科學院的大樓裡，我們就可以……"
  },
  AvgDialog_60889_Content_12 = {
    Text = "需要我送你們一程嗎，拉蒙娜小姐？"
  },
  AvgDialog_60889_Content_15 = {
    Text = "拉蒙娜舉起劍橫在自己身前。"
  },
  AvgDialog_60889_Content_16 = {
    Text = "在她身後，茜爾維婭皺緊眉頭，護著虛弱的訶勒特。"
  },
  AvgDialog_60889_Content_17 = {
    Text = "一陣急促的腳步聲響起，似乎已在這裡埋伏了多時。"
  },
  AvgDialog_60889_Content_18 = {
    Text = "狹窄的甬道兩頭，身穿審查會制服的探員密密麻麻地堵住了他們的去路。"
  },
  AvgDialog_60889_Content_19 = {
    Text = "獨眼男人一邊走到人群之前，一邊溫柔地逗弄著肩膀上那只被縫上了兩顆頭顱的無毛貓。"
  },
  AvgDialog_60889_Content_2 = {
    Text = "呼……訶勒特院長，請再堅持一下，我們就快到了。"
  },
  AvgDialog_60889_Content_21 = {
    Text = "看到出現在面前的這張臉，訶勒特的身子一下子緊繃起來。"
  },
  AvgDialog_60889_Content_22 = {
    Text = "赫伯特……你這個混帳……"
  },
  AvgDialog_60889_Content_23 = {
    Text = "克勞利老師像對自己的孩子一樣對你，你竟然對他做出那樣的事。還有臉回來……"
  },
  AvgDialog_60889_Content_24 = {
    Text = "噓，訶勒特同學……啊不，應該叫你，訶勒特院長。"
  },
  AvgDialog_60889_Content_25 = {
    Text = "在我離開之後，院長的位置，當然非你莫屬。"
  },
  AvgDialog_60889_Content_26 = {
    Text = "我很想和你一起追憶曾經美好的求學時光，不過今天我來這裡，還有其他正事要做。"
  },
  AvgDialog_60889_Content_28 = {
    Text = "很久不見，甚是想念，拉蒙娜小姐。"
  },
  AvgDialog_60889_Content_29 = {
    Text = "不過是在這段時間裡見過幾面，不用說得這麼熟悉。"
  },
  AvgDialog_60889_Content_3 = {
    Text = "拉蒙娜，你的傷口……"
  },
  AvgDialog_60889_Content_30 = {
    Text = "這段時間？不，不。"
  },
  AvgDialog_60889_Content_31 = {
    Text = "我還記得第一次見到你的時候，似乎就是在這個通道裡。"
  },
  AvgDialog_60889_Content_32 = {
    Text = "那時候你才……這麼大……"
  },
  AvgDialog_60889_Content_33 = {
    Text = "赫伯特伸出雙手，比出一隻無毛貓的長度。"
  },
  AvgDialog_60889_Content_34 = {
    Text = "你是……什麼意思？"
  },
  AvgDialog_60889_Content_36 = {
    Text = "希洛是失敗的產物。在我和提燈教會的合作裡，你是最完美的結晶。"
  },
  AvgDialog_60889_Content_38 = {
    Text = "你還不明白嗎，拉蒙娜？"
  },
  AvgDialog_60889_Content_39 = {
    Text = "那些你在意的人們，受到驚嚇，受到傷害，面臨失控和死亡的威脅……彌薩格遭受的這一切災難，都是因為你啊。"
  },
  AvgDialog_60889_Content_4 = {
    Text = "她拿出手巾，擦乾淨了拉蒙娜手臂上的血跡。"
  },
  AvgDialog_60889_Content_40 = {
    Text = "你……說什麼？"
  },
  AvgDialog_60889_Content_41 = {
    Text = "看著拉蒙娜手中顫抖的劍，赫伯特微笑著向前走了兩步。"
  },
  AvgDialog_60889_Content_42 = {
    Text = "很多年前，德克斯特這個小偷把你從我們手裡偷走了。"
  },
  AvgDialog_60889_Content_43 = {
    Text = "這一天晚了很久，不過沒有關係——它來的正是時候。"
  },
  AvgDialog_60889_Content_44 = {
    Text = "你是珍貴的雙子，是提燈的完美造物。"
  },
  AvgDialog_60889_Content_6 = {
    Text = "剛才和那幾個審查會的人戰鬥的時候，一時間失了神……"
  },
  AvgDialog_60889_Content_7 = {
    Text = "黑池的動盪，還是對你造成了影響，是麼？"
  },
  AvgDialog_60889_Content_9 = {
    Text = "拉蒙娜，給你們添麻煩了。要是沒有受傷，我或許還能幫你分擔一些……"
  },
  AvgDialog_60890_Content_1 = {
    Text = "你身處風暴。"
  },
  AvgDialog_60890_Content_10 = {
    Text = "尖銳的嘶鳴響徹黑池。體內那代表智識的權柄，隨著嘶鳴震顫。"
  },
  AvgDialog_60890_Content_11 = {
    Text = "無數個白色的虛影，從不同的維度與時空中被捕捉，匯入那座黑白雕像之中。"
  },
  AvgDialog_60890_Content_12 = {
    Text = "很快，那些嘶鳴與震顫盡皆消失。"
  },
  AvgDialog_60890_Content_13 = {
    Text = "沒有人能躲避祂，塔薇。"
  },
  AvgDialog_60890_Content_14 = {
    Text = "來吧，讓我們一起，迎接祂的降生！"
  },
  AvgDialog_60890_Content_15 = {
    Text = "隨著於麗埃特的動作停止，那巨大的提燈雙子像開始向中間靠攏，如同尋找靈魂的軀殼，急迫地想要與中央那座黑白雕像融為一體。"
  },
  AvgDialog_60890_Content_17 = {
    Text = "一道強烈的光芒突然綻放開。在巨大的雙子造物身後，出現了一道縫隙。"
  },
  AvgDialog_60890_Content_18 = {
    Text = "你緩緩挪開遮擋著眼睛的雙手。"
  },
  AvgDialog_60890_Content_19 = {
    Text = "那是……門？"
  },
  AvgDialog_60890_Content_2 = {
    Text = "強烈的震動，讓黑池的水劇烈地震盪，激起巨大的水浪，拍打在你的身上。"
  },
  AvgDialog_60890_Content_20 = {
    Text = "塔薇身後那座虛幻的門，在這一刻擁有了實體。"
  },
  AvgDialog_60890_Content_21 = {
    Text = "光芒從逐漸擴大的門縫中透出，冷漠如同宇宙，純淨如同真理。"
  },
  AvgDialog_60890_Content_22 = {
    Text = "你癡癡地望向那片光，兩道淚水在強光下滑落，你毫無覺察。你再也無法挪開雙眼。"
  },
  AvgDialog_60890_Content_23 = {
    Text = "門……承載萬物之門……神明的居所……"
  },
  AvgDialog_60890_Content_24 = {
    Text = "終於，終於等到了這一天！"
  },
  AvgDialog_60890_Content_25 = {
    Text = "不，不能讓門打開……"
  },
  AvgDialog_60890_Content_26 = {
    Text = "你想要做些什麼。你努力催動銀鑰匙，但你的精神力此時被死死壓制，銀鑰匙沒有半點反應。"
  },
  AvgDialog_60890_Content_28 = {
    Text = "你絕望地看著那道門從模糊到清晰，打開一道縫隙。"
  },
  AvgDialog_60890_Content_29 = {
    Text = "那強大的力量，如同將要淹沒世界的洪水，從門內湧向提燈雙子像。"
  },
  AvgDialog_60890_Content_3 = {
    Text = "黑池在搖晃。穹頂在搖晃。似乎整個彌薩格、整個大陸，都在於麗埃特的吟誦中顫抖。"
  },
  AvgDialog_60890_Content_30 = {
    Text = "於麗埃特瞪大雙眼望著門與神像，臉上的笑容變得愈發猙獰起來。"
  },
  AvgDialog_60890_Content_31 = {
    Text = "力量，是門內的力量……雙子神像，就要完成融合。"
  },
  AvgDialog_60890_Content_32 = {
    Text = "彌薩格……守密人……和這個罪惡的世界一起，迎接最終的淨化吧！"
  },
  AvgDialog_60890_Content_34 = {
    Text = "第四樂章，起。"
  },
  AvgDialog_60890_Content_36 = {
    Text = "如同數萬個樂手同時奏響樂器，絃樂，管樂，打擊樂，不同的樂聲交織彙集，成為一道恢弘的河流。"
  },
  AvgDialog_60890_Content_37 = {
    Text = "河流奔湧著，猛然衝向門與雙子神像之間的薄弱連結。"
  },
  AvgDialog_60890_Content_38 = {
    Text = "門內力量的反噬，讓雙子像轟然震動。神像上傳來的危險氣息明顯變得淡薄了起來。"
  },
  AvgDialog_60890_Content_39 = {
    Text = "向中央靠攏的石像，停下了它的動作。"
  },
  AvgDialog_60890_Content_4 = {
    Text = "在這劇烈的晃動中，你抬起頭，看著眼前那個越來越恢弘的造物。"
  },
  AvgDialog_60890_Content_40 = {
    Text = "那個熟悉的面孔，從陰影中走出，重新出現在你的視野裡。"
  },
  AvgDialog_60890_Content_41 = {
    Text = "時機已至。最後的演出，即將開始。"
  },
  AvgDialog_60890_Content_42 = {
    Text = "他輕輕揮動指揮棒。一道輕柔的樂聲傳入你的精神世界。"
  },
  AvgDialog_60890_Content_43 = {
    Text = "那些沉重的枷鎖與痛苦忽然消失不見，你重新沐浴在溫泉之中，腦中重新充盈著比之前更加磅礴的精神力量。"
  },
  AvgDialog_60890_Content_44 = {
    Text = "你……你沒有破壞我的精神連結……"
  },
  AvgDialog_60890_Content_45 = {
    Text = "之前暫時切斷了你的連結能力。一個用來迷惑於麗埃特的手段。"
  },
  AvgDialog_60890_Content_46 = {
    Text = "你的限制解除了。現在，門已開啟，所有的準備，均已就緒。"
  },
  AvgDialog_60890_Content_47 = {
    Text = "他站在你的面前，冷靜的眼睛裡，燃燒著狂熱的火焰。"
  },
  AvgDialog_60890_Content_48 = {
    Text = "他將指揮棒背在身後，向你躬身行禮。"
  },
  AvgDialog_60890_Content_49 = {
    Text = "無目之瞳，無上意志的代行者。我將協助你，拿回屬於你的權柄。"
  },
  AvgDialog_60890_Content_5 = {
    Text = "雙子……神像……"
  },
  AvgDialog_60890_Content_50 = {
    Text = "你……說什麼？"
  },
  AvgDialog_60890_Content_51 = {
    Text = "無上意志的降臨不可避免，唯有你可以與之對抗。"
  },
  AvgDialog_60890_Content_52 = {
    Text = "讓雙子現世，門扉開啟，你才能重新獲得與祂對抗的能力。"
  },
  AvgDialog_60890_Content_53 = {
    Text = "事急從權，請原諒我先前的失禮。"
  },
  AvgDialog_60890_Content_54 = {
    Text = "哈姆林！你……你這是在做什麼？！！"
  },
  AvgDialog_60890_Content_55 = {
    Text = "做我應該做的事。"
  },
  AvgDialog_60890_Content_56 = {
    Text = "他只是一塊碎片！只有用我的方式，才能讓真正的無上意志甦醒……"
  },
  AvgDialog_60890_Content_57 = {
    Text = "你不是想要從無上意志那裡聆聽到至高的樂聲嗎？哈姆林，你背叛了你所信奉之物！"
  },
  AvgDialog_60890_Content_58 = {
    Text = "神明不一定比其碎片更偉大。這也不是我所在意的事，於麗埃特女士。"
  },
  AvgDialog_60890_Content_59 = {
    Text = "我曾經也以為，無上意志的安魂曲是這宇宙中最偉大的樂聲，後來我終於明白了。真正至高的藝術，將超越其本身。"
  },
  AvgDialog_60890_Content_6 = {
    Text = "兩塊白色的人形石像，從黑池之下緩緩現出身形，讓整個黑池為之顫慄。"
  },
  AvgDialog_60890_Content_60 = {
    Text = "他抬起頭，那雙燃燒著兇猛火焰的雙眼，靜靜地望向於麗埃特。"
  },
  AvgDialog_60890_Content_61 = {
    Text = "它將於抗爭中鳴響——人類與神明的對抗。碎片與原初的對抗。"
  },
  AvgDialog_60890_Content_62 = {
    Text = "與無上意志對抗，與無上意志合奏……這將是比無上意志的安魂曲，更加崇高的樂聲！"
  },
  AvgDialog_60890_Content_63 = {
    Text = "你是從什麼時候……"
  },
  AvgDialog_60890_Content_64 = {
    Text = "阿庫特之春，我們目睹了那場爆炸。"
  },
  AvgDialog_60890_Content_65 = {
    Text = "那一天，我聽見了它……我所追尋的，比那安魂曲更為永恆的，於抗爭中鳴響的樂聲。"
  },
  AvgDialog_60890_Content_66 = {
    Text = "那時候，我只聽到了它的前奏。今天，它將完整地響徹這個世界。"
  },
  AvgDialog_60890_Content_67 = {
    Text = "哈姆林冷靜的聲音不可抑制地顫抖著。"
  },
  AvgDialog_60890_Content_68 = {
    Text = "所以，你從那一天開始，就在計劃著背叛……"
  },
  AvgDialog_60890_Content_69 = {
    Text = "神明已經將祂的音樂遺忘了。祂只是一個無意識的混沌體，一場宏大的災難。"
  },
  AvgDialog_60890_Content_7 = {
    Text = "在石像中央的空隙裡，拉蒙娜的身體被塔薇的軀殼所纏繞、包裹。"
  },
  AvgDialog_60890_Content_71 = {
    Text = "我忠於音樂，我從未背叛過，於麗埃特。"
  },
  AvgDialog_60890_Content_72 = {
    Text = "他平靜地望著於麗埃特、巨像，以及巨像身後的門。"
  },
  AvgDialog_60890_Content_74 = {
    Text = "為什麼……如果你從一開始就幫我，拉蒙娜就不會……"
  },
  AvgDialog_60890_Content_75 = {
    Text = "守密人%player%，無上意志的降臨無法阻止。讓於麗埃特召喚出門，讓你順利回收權柄，是唯一的路。"
  },
  AvgDialog_60890_Content_76 = {
    Text = "你我所追尋之物不同，但無論是至高的樂聲，還是世界的存續，機會都只有這一次。"
  },
  AvgDialog_60890_Content_77 = {
    Text = "在這場演出裡，你，我，拉蒙娜小姐，這裡的所有人，都只是樂手。"
  },
  AvgDialog_60890_Content_78 = {
    Text = "拉蒙娜小姐會理解的。"
  },
  AvgDialog_60890_Content_79 = {
    Text = "你知道，哈姆林說的沒錯。拉蒙娜一定會理解。為了世界的存續，她從不介意犧牲自己。"
  },
  AvgDialog_60890_Content_8 = {
    Text = "兩具無主的軀殼不斷變化、交融，變為一尊黑白兩色的巨大雕塑，懸浮在巨大的半身石像之間。"
  },
  AvgDialog_60890_Content_80 = {
    Text = "德克斯特已經消失，但這世上，總還是有人會介意的。"
  },
  AvgDialog_60890_Content_81 = {
    Text = "——至少，她現在還活著。"
  },
  AvgDialog_60890_Content_82 = {
    Text = "感受著體內越發洶湧的精神力量，你抬起頭，望向那個黑白的雕塑。"
  },
  AvgDialog_60890_Content_83 = {
    Text = "走吧，守密人%player%。去擊碎那道石像，救出你的同伴。"
  },
  AvgDialog_60890_Content_84 = {
    Text = "去向這個世界展現你的權柄……去重新想起，關於無上意志的一切。"
  },
  AvgDialog_60897_Content_1 = {
    Text = "守密人……我們成功了！"
  },
  AvgDialog_60897_Content_10 = {
    Text = "她回過頭，望向你正望著的方向——"
  },
  AvgDialog_60897_Content_11 = {
    Text = "在那敞開的門扉之後，無數泡沫同時破裂。時光、空間與知識，碎裂成一個個碎片，如同凌亂的油污，將這片維度染上繁複骯髒的色彩。"
  },
  AvgDialog_60897_Content_12 = {
    Text = "在那些象徵著萬物的碎片之後，一隻眼睛緩緩睜開，如同剛剛出世的嬰兒，好奇地打量著這個世界。"
  },
  AvgDialog_60897_Content_13 = {
    Text = "目光所到之處，無數原本存在於世的物體，盡皆化為融蝕液，匯入黑池之中。"
  },
  AvgDialog_60897_Content_14 = {
    Text = "那目光移動著，最後，鎖定在了你的身上。"
  },
  AvgDialog_60897_Content_15 = {
    Text = "甦醒……@3……甦醒！……"
  },
  AvgDialog_60897_Content_16 = {
    Text = "祂的瞳孔猛地放大，整個宇宙似乎都隨著祂而震動了一瞬。"
  },
  AvgDialog_60897_Content_17 = {
    Text = "你與祂對視。這種對視無疑是一種褻瀆。世間的一切，從你的意識中消失。"
  },
  AvgDialog_60897_Content_18 = {
    Text = "恐懼。最原初、最純粹的恐懼，無從想像、無從違逆的恐懼，灌滿了你的全身。"
  },
  AvgDialog_60897_Content_2 = {
    Text = "拉蒙娜的臉上，綻放出笑容。"
  },
  AvgDialog_60897_Content_21 = {
    Text = "我沒看錯你，%player%。我沒看錯你！"
  },
  AvgDialog_60897_Content_22 = {
    Text = "N的聲音從黑池的陰影處傳來。眼前的畫面讓祂完全忘記了維持自己的優雅。祂瘋狂地笑著，狂熱地望向門內。"
  },
  AvgDialog_60897_Content_24 = {
    Text = "那麼，%player%，碎片，冒牌貨……"
  },
  AvgDialog_60897_Content_25 = {
    Text = "祂回過頭來，邪惡的嘴高高咧開，那張沒有眼睛、純黑色的臉，玩味地望向你。"
  },
  AvgDialog_60897_Content_26 = {
    Text = "告訴我……現在，你能做到什麼呢？"
  },
  AvgDialog_60897_Content_3 = {
    Text = "守密人，我們現在可以……"
  },
  AvgDialog_60897_Content_6 = {
    Text = "拉蒙娜疑惑地看著你。"
  },
  AvgDialog_60897_Content_7 = {
    Text = "在這喜悅的時刻，她看到了從未在你臉上看到過的表情——"
  },
  AvgDialog_60897_Content_8 = {
    Text = "那是一個人在面對宏偉宇宙的崩塌時……"
  },
  AvgDialog_60897_Content_9 = {
    Text = "所展露出的寒冷、恐懼、絕望、孱弱。"
  },
  AvgDialog_61921_Content_1 = {
    Text = "你被不定形的噩夢纏繞，古怪的情思攫住你的意識，令夢境變得顛倒而渾濁。"
  },
  AvgDialog_61921_Content_10 = {
    Text = "她回眸，目光平靜淡漠，但你卻無法抗拒她的言語。"
  },
  AvgDialog_61921_Content_12 = {
    Text = "她倚靠在你的胸膛，你感覺到自己的呼吸變得急促。"
  },
  AvgDialog_61921_Content_13 = {
    Text = "塔薇拉住你的手，輕觸黑池的水面。一圈圈漣漪向外盪開去。"
  },
  AvgDialog_61921_Content_14 = {
    Text = "你聽見了嗎？這是你心跳的鼓動。"
  },
  AvgDialog_61921_Content_15 = {
    Text = "無論我在什麼時代、哪個空間……你的呼吸和心跳都會通過這片池水傳遞給我。"
  },
  AvgDialog_61921_Content_16 = {
    Text = "這還是第一次，我這樣聆聽你的心跳。\n和我日日夜夜聽聞的同頻共振，震耳欲聾。"
  },
  AvgDialog_61921_Content_17 = {
    Text = "她抬眸望向你，灰綠色的瞳孔中瀰散不明的思緒。"
  },
  AvgDialog_61921_Content_18 = {
    Text = "你覺得四周好像又下雨了。\n黑池也會有雨嗎？"
  },
  AvgDialog_61921_Content_19 = {
    Text = "銀色的雨絲，將你們二人細細密密地裹纏起來。\n這是只屬於你和她的時間與空間。"
  },
  AvgDialog_61921_Content_2 = {
    Text = "一滴清涼的液體如輕柔的吻落在你的額角，隨之而來的是漫天銀雨。\n你被雨絲喚醒。"
  },
  AvgDialog_61921_Content_20 = {
    Text = "你知道嗎？她會後悔散佈這樣的慾念的……"
  },
  AvgDialog_61921_Content_21 = {
    Text = "你我之間的鏈接，遠比她試圖侵染你的，更深，更遠……"
  },
  AvgDialog_61921_Content_4 = {
    Text = "宿舍的夜晚像是籠罩著一層紗幔，朦朧的聲音在你的耳畔迴盪。"
  },
  AvgDialog_61921_Content_7 = {
    Text = "潔白的輕紗掩住她的側臉，縈繞黑池的水氣彷彿她的延伸，將你攏入幻覺般的夢境。"
  },
  AvgDialog_61921_Content_8 = {
    Text = "在萬千夢境之中，她站在窮極之扉前，詢問你無聲的問題。"
  },
  AvgDialog_61921_Content_9 = {
    Text = "來，到我身邊來。"
  },
  AvgDialog_62163_Content_2 = {
    Text = "是「遺忘之理」的力量……我的意識已經受到了影響，無法再為你提供完整的樂聲。接下來的戰鬥，會無比困難……"
  },
  AvgDialog_62163_Content_3 = {
    Text = "祂和我們一樣，也已經到達了極限……我絕不會……倒在這裡！"
  },
  AvgDialog_62164_Content_2 = {
    Text = "是「遺忘之理」的力量……我的意識已經受到了影響，無法再為你提供完整的樂聲。"
  },
  AvgDialog_62164_Content_3 = {
    Text = "在被吞噬以前，拉蒙娜的意識也讓祂受到了重創。她仍和你站在一起，守密人。"
  },
  AvgDialog_62164_Content_4 = {
    Text = "腦中的一根弦微微顫動，你聽見一道微弱的聲音。"
  },
  AvgDialog_62164_Content_5 = {
    Text = "銘記過去……不能……遺忘……"
  },
  AvgDialog_62164_Content_6 = {
    Text = "讓我和你……站在一起……"
  },
  AvgDialog_62165_Content_2 = {
    Text = "拉蒙娜？！你……恢復意識了？！"
  },
  AvgDialog_62165_Content_3 = {
    Text = "很抱歉，這次沒有再和你並肩作戰……但現在我不會再食言了。"
  },
  AvgDialog_62165_Content_4 = {
    Text = "從最初的連結開始，那些屬於我們的記憶，我們不會讓任何人將它奪走。\n對嗎，守密人？"
  },
  AvgDialog_62165_Content_5 = {
    Text = "隨著拉蒙娜的話音在你腦海中落下，神像發出一陣強烈的嘶鳴，似乎有一支利刃刺入祂的神經。"
  },
  AvgDialog_62165_Content_6 = {
    Text = "一道光芒從它頭頂的銀色花朵中綻放，落在你身上。"
  },
  AvgDialog_62165_Content_7 = {
    Text = "你知道，她從未遺忘。她已來到你身邊——就像曾經無數次那樣。"
  },
  AvgDialog_62166_Content_1 = {
    Text = "只靠我們無法阻止神像……我會用樂聲幫助你與拉蒙娜進行連結。閉上眼，用你的意識呼喚她！"
  },
  AvgDialog_62166_Content_10 = {
    Text = "拉蒙娜抬起頭，望向聲音的來處。"
  },
  AvgDialog_62166_Content_11 = {
    Text = "我答應過%heorshe%。無論在什麼時候，無論面對什麼……我都會和%heorshe%站在一起。"
  },
  AvgDialog_62166_Content_12 = {
    Text = "在哈姆林的樂聲與你的呼喚中，神像的融合突然停了下來。\n一朵殘缺的、流光溢彩的銀色花朵，飄然離開了黑白雕像的身軀。"
  },
  AvgDialog_62166_Content_13 = {
    Text = "拉蒙娜，等著我！"
  },
  AvgDialog_62166_Content_14 = {
    Text = "我一定會救你出去！……拉蒙娜，等著我！！"
  },
  AvgDialog_62166_Content_15 = {
    Text = "你衝著那朵純銀之花大喊。透過虛無的精神世界，那道銀色的殘影向你微笑著。"
  },
  AvgDialog_62166_Content_17 = {
    Text = "……我會等你。"
  },
  AvgDialog_62166_Content_3 = {
    Text = "有聲音……很熟悉，是……"
  },
  AvgDialog_62166_Content_4 = {
    Text = "神像正在吞噬我們的意識。我們的記憶快消失了，拉蒙娜。從這個世界的每一個維度，每一個時空中消失，從未存在過。"
  },
  AvgDialog_62166_Content_5 = {
    Text = "父親，力量，自由，生命……你即將失去更多，拉蒙娜。"
  },
  AvgDialog_62166_Content_6 = {
    Text = "不，塔薇……有些東西，我不能失去。至少現在，我還擁有%heorshe%……"
  },
  AvgDialog_62166_Content_7 = {
    Text = "神像的禁錮無法被擊破，強行掙脫，你將承受莫大的痛苦，為%heorshe%提供的幫助也極為有限。"
  },
  AvgDialog_62166_Content_8 = {
    Text = "即使這樣，你也願意嗎？"
  },
  AvgDialog_62166_Content_9 = {
    Text = "如果不這樣，我們便只能任由神像成型。是嗎？"
  },
  AvgDialog_62167_Content_1 = {
    Text = "遊戲到此為止了，守密人%sirormadam%。"
  },
  AvgDialog_62167_Content_10 = {
    Text = "她再也顧不上自己的儀態，俯下身乾嘔起來。"
  },
  AvgDialog_62167_Content_11 = {
    Text = "不，不可能……您是無上的意志……您是為這個世界帶來淨化的……"
  },
  AvgDialog_62167_Content_12 = {
    Text = "夢境……毀滅……不……不！"
  },
  AvgDialog_62167_Content_13 = {
    Text = "她癱軟在門前，環抱住自己的臂膀，身體止不住地顫抖。"
  },
  AvgDialog_62167_Content_14 = {
    Text = "於麗埃特？你看到了什麼？！"
  },
  AvgDialog_62167_Content_15 = {
    Text = "真相……原來……這就是真相……"
  },
  AvgDialog_62167_Content_16 = {
    Text = "於麗埃特沒有理會你的呼喊。在看到門扉那一瞬間之後，這世間的一切似乎都與她再也沒有關係。"
  },
  AvgDialog_62167_Content_18 = {
    Text = "你抬起頭——"
  },
  AvgDialog_62167_Content_19 = {
    Text = "從門扉之後溢出的氣息被盡皆吸收，原本被你們阻擋而停下的石像，猛然合併在一起。"
  },
  AvgDialog_62167_Content_2 = {
    Text = "在於麗埃特身前，門開啟了一個足夠人通過的縫隙。"
  },
  AvgDialog_62167_Content_20 = {
    Text = "那尊巨大的石像如同活物，威嚴地佇立在你面前。"
  },
  AvgDialog_62167_Content_21 = {
    Text = "於麗埃特虛弱地抬起頭，望著眼前再也無法掌控的龐然造物，用盡最後的餘力，淒慘地牽動嘴角。"
  },
  AvgDialog_62167_Content_22 = {
    Text = "錯誤的開始，錯誤的結束。終結，亦是淨化……就讓這一切，在這裡結束吧。"
  },
  AvgDialog_62167_Content_23 = {
    Text = "於麗埃特緩緩倒下。倒在門扉的真相之前。"
  },
  AvgDialog_62167_Content_24 = {
    Text = "在她的身體之前，帶著深淵般氣息的巨大石像，在你面前緩緩起身——"
  },
  AvgDialog_62167_Content_3 = {
    Text = "你們的意志力讓人敬佩，可惜，方向錯誤的意志毫無用處。"
  },
  AvgDialog_62167_Content_4 = {
    Text = "一切知識與力量，都藏在這道門後。門會幫助我，完成雙子神像的融合。"
