  AvgDialog_62208_Content_18 = {
    Text = "我想，我需要向你說聲謝謝。"
  },
  AvgDialog_62208_Content_19 = {
    Text = "只有庸俗的指揮家會在意觀眾的目光。"
  },
  AvgDialog_62208_Content_2 = {
    Text = "事情……結束了？……"
  },
  AvgDialog_62208_Content_20 = {
    Text = "我只是為了完成自己的目的。合作者之間，不必言謝。"
  },
  AvgDialog_62208_Content_21 = {
    Text = "哈姆林閉眼深吸一口氣，準備收起自己的指揮棒。"
  },
  AvgDialog_62208_Content_22 = {
    Text = "長久的謀劃，似乎讓這位指揮家也感到了些許的疲憊。\n在這場沒有掌聲的演出裡，他以此完成自己的謝幕。"
  },
  AvgDialog_62208_Content_23 = {
    Text = "而在他的指揮棒收到一半時，一道隱約的笛聲，忽然從門扉中傳來。"
  },
  AvgDialog_62208_Content_27 = {
    Text = "跟隨他的目光望向門扉的瞬間，你同他一樣，無法再做出任何一個動作，說出任何一個字。"
  },
  AvgDialog_62208_Content_29 = {
    Text = "拉蒙娜疑惑地看著你。"
  },
  AvgDialog_62208_Content_3 = {
    Text = "你感到一陣暈眩。連續的戰鬥下，積壓的疲憊如同山巒般壓向你。"
  },
  AvgDialog_62208_Content_30 = {
    Text = "在這喜悅的時刻，她看到了從未在你臉上看到過的表情——"
  },
  AvgDialog_62208_Content_31 = {
    Text = "那是一個人在面對宏偉宇宙的崩塌時……"
  },
  AvgDialog_62208_Content_32 = {
    Text = "所展露出的寒冷、恐懼、絕望、孱弱。"
  },
  AvgDialog_62208_Content_33 = {
    Text = "她回過頭，望向你正望著的方向——"
  },
  AvgDialog_62208_Content_34 = {
    Text = "在那本應平靜下來的門扉之後，靜止的光彩突然破裂。時光、空間與知識，碎裂成一個個碎片，如同凌亂的油污，將這片維度染上繁複骯髒的色彩。"
  },
  AvgDialog_62208_Content_35 = {
    Text = "低沉的笛聲傳入你們的耳中，混沌、古老的旋律在人群中穿行迴蕩，交織成一個恐懼的繭，將所有人層層包裹。"
  },
  AvgDialog_62208_Content_36 = {
    Text = "在那笛聲之中，在那包羅萬象的色彩之後，一隻眼睛緩緩睜開，如同剛剛出世的嬰兒，好奇地打量著這個世界。"
  },
  AvgDialog_62208_Content_37 = {
    Text = "目光所到之處，無數原本存在於世的物體，盡皆化為融蝕液，匯入黑池之中。"
  },
  AvgDialog_62208_Content_38 = {
    Text = "那目光移動著，最後，鎖定在了你的身上。"
  },
  AvgDialog_62208_Content_4 = {
    Text = "在你快要摔倒在地時，一道輕柔的樂聲拖住了你。"
  },
  AvgDialog_62208_Content_40 = {
    Text = "祂的瞳孔猛地放大。黑池轟鳴，整個宇宙似乎都隨之震顫。"
  },
  AvgDialog_62208_Content_41 = {
    Text = "你與祂對視。這種對視無疑是一種褻瀆。世間的一切，從你的意識中消失。"
  },
  AvgDialog_62208_Content_42 = {
    Text = "恐懼。最原初、最純粹的恐懼，無從想像、無從違逆的恐懼，灌滿了你的全身。"
  },
  AvgDialog_62208_Content_45 = {
    Text = "希望，歡樂，團聚，然後，砰——死亡。"
  },
  AvgDialog_62208_Content_46 = {
    Text = "彌薩格的內鬼朋友，這個舞臺上第二優雅的配角，我都忍不住為你喝彩！"
  },
  AvgDialog_62208_Content_47 = {
    Text = "我沒看錯你，%player%。我沒看錯你們！"
  },
