  AvgDialog_64035_Content_2 = {
    Text = "她會盡全力蠱惑、拉攏你，你需要有自己的判斷。"
  },
  AvgDialog_64035_Content_20 = {
    Text = "她沒有任何反應，溫馴如真正的人偶。"
  },
  AvgDialog_64035_Content_21 = {
    Text = "只有那雙眼睛始終注視著你，彷彿會穿透一切，一直跟隨你的靈魂。"
