  AvgDialog_65470_Content_31 = {
    Text = "你站起身來，迎上面前這個龐然大物的目光。"
  },
  AvgDialog_65470_Content_32 = {
    Text = "看吶，我們的冒牌貨朋友，又要開始%heorshe%不知死活的戲碼了。"
  },
  AvgDialog_65470_Content_33 = {
    Text = "N，你說的沒錯。一個碎片，根本做不到什麼。"
