  AvgDialog_65470_Content_34 = {
    Text = "可這個崩塌的造物主掉落的碎片，不只一個……"
  },
  AvgDialog_65470_Content_35 = {
    Text = "你掃視著門內的這片空間。無數的眼睛，正從無數個維度中向你望來。"
