  AvgDialog_65470_Content_56 = {
    Text = "虛幻的空間，熟悉的場景隨著目光出現。無數即將破滅的維度裡，無數銀色的光點同時燃起。"
  },
  AvgDialog_65470_Content_57 = {
    Text = "銀光照耀倫蒂尼恩的蠟像館，拉伊的療養院，布里爾珀特的海面，勒姆瓦希的沙丘。銀光照耀你的過往，你所有的劫難與成長。"
  },
  AvgDialog_65470_Content_58 = {
    Text = "那些脆弱、渺小的碎片們，將鋒刃對準了自己的造物主。"
  },
  AvgDialog_65470_Content_59 = {
    Text = "一隻眼睛，一道傷口，一個劃痕，甚至什麼都留不下……這些都沒關係。"
  },
  AvgDialog_65470_Content_6 = {
    Text = "這裡是……"
  },
  AvgDialog_65470_Content_60 = {
    Text = "看著吧，托乎瓦波。我們是你的碎片，我們是彌薩格的守密人……"
  },
  AvgDialog_65470_Content_61 = {
    Text = "無論付出怎樣的代價，我們都會將你留在這裡！"
  },
  AvgDialog_65470_Content_7 = {
    Text = "智之質體短暫地回溯了時間，我們仍在門扉之內。"
