  AvgDialog_65471_Content_20 = {
    Text = "迎接這一刻吧——"
  },
  AvgDialog_65471_Content_22 = {
    Text = "似乎受到了某種召喚，混沌的聲音從門扉之內響起。"
  },
  AvgDialog_65471_Content_23 = {
    Text = "那是嬰兒的啼哭，是古老的咒語，是純粹的惡意。癡愚的聲音彷彿從它的血脈中流出，帶著毀滅的氣息，從門扉內湧現。"
  },
  AvgDialog_65471_Content_25 = {
    Text = "塔薇擋在眾人的前方，巨大的羽翼張開，但那象徵著多重維度的色彩越來越暗淡。"
  },
  AvgDialog_65471_Content_26 = {
    Text = "裂隙無可控制地擴大，吞噬著祂最後的理智。"
  },
  AvgDialog_65471_Content_27 = {
    Text = "拉蒙娜，你能感知到%heorshe%嗎？"
