  AvgDialog_65471_Content_70 = {
    Text = "你笑了笑。一切的解釋，都已不再有必要了。"
  },
  AvgDialog_65471_Content_71 = {
    Text = "你的世界所剩下的，唯有前方那個屬於造物主的宏偉的眼瞳。\n你的身邊，已空無一人。"
