  AvgDialog_65472_Content_8 = {
    Text = "祂看到了你的過去，祂正從你所走過的每一個地方睜開眼。倫蒂尼恩，拉伊，勒姆瓦希……"
  },
  AvgDialog_65472_Content_9 = {
    Text = "祂的目光，仍在追逐我們。"
  },
  AvgDialog_65473_Content_1 = {
    Text = "在我的預設裡，我沒有想到你能走得這樣遠。"
  },
  AvgDialog_65473_Content_2 = {
    Text = "放棄自己所擁有的東西，這並不是一件容易的事。"
  },
  AvgDialog_65473_Content_3 = {
    Text = "你在猶豫。猶豫是正常的。猶豫是人性中最腐朽與光輝的部分。"
  },
  AvgDialog_65473_Content_4 = {
    Text = "但你已走到了這裡。你已經沒有了猶豫的資格，%player%。"
  },
  AvgDialog_65473_Content_5 = {
    Text = "能夠阻擋神明的，只能是神明。所有的人性，將與你無關。"
  },
  AvgDialog_65473_Content_6 = {
    Text = "告訴我，你準備好了嗎？"
  },
  AvgDialog_65473_Content_7 = {
    Text = "我準備好了，朵爾教授。"
  },
  AvgDialog_65473_Content_8 = {
    Text = "在這條道路的盡頭，她在等待你。"
  },
  AvgDialog_65473_Content_9 = {
    Text = "斬斷與我的連結，然後勇敢地面對她吧。"
  },
  AvgDialog_65474_Content_1 = {
    Text = "主君，您真的……要拋棄我們了嗎？"
  },
  AvgDialog_65474_Content_2 = {
    Text = "抱歉，主君……我不該這樣說。"
  },
  AvgDialog_65474_Content_3 = {
    Text = "我明白，您是為了保護我們，才不得已這樣做……但我曾經立下誓言，要永遠擋在主君身前。"
  },
  AvgDialog_65474_Content_4 = {
    Text = "主君，若您已下定決心……請宣佈解除我的效忠吧。"
  },
  AvgDialog_65474_Content_5 = {
    Text = "我……已下定決心，奧吉爾。"
  },
  AvgDialog_65474_Content_6 = {
    Text = "主君，和我一樣，您也有想要守護的東西。"
  },
  AvgDialog_65474_Content_7 = {
    Text = "在您親手解除這份誓言之後，我會在背後看著您的背影。"
  },
  AvgDialog_65474_Content_8 = {
    Text = "我會看著您，向神明宣告您的騎士之道！"
  },
  AvgDialog_65475_Content_1 = {
    Text = "斬斷一切，需要鋒利的劍刃，需要強大的力量，更需要一顆一往無前的心。"
  },
  AvgDialog_65475_Content_2 = {
    Text = "這些，你都準備好了嗎？"
  },
  AvgDialog_65475_Content_3 = {
    Text = "我……準備好了……"
  },
  AvgDialog_65475_Content_4 = {
    Text = "放棄並不是一件容易的事。我欣賞你的答案。"
  },
  AvgDialog_65475_Content_5 = {
    Text = "拔劍吧，%player%。"
  },
  AvgDialog_65475_Content_6 = {
    Text = "最後一堂劍術課，現在開始——"
  },
  AvgDialog_65476_Content_10 = {
    Text = "她望向門內，眉頭緊緊皺起。"
  },
  AvgDialog_65476_Content_11 = {
    Text = "守密人！離開那裡！！"
  },
  AvgDialog_65476_Content_12 = {
    Text = "門外的聲音渾濁地傳入你耳中。你捂住胸口，抬起頭。"
  },
  AvgDialog_65476_Content_13 = {
    Text = "眼睛。無數的眼睛。在你費盡全力將一隻眼睛擊破之後，萬千眼睛惺忪睜開，從門內的世界、從宇宙的每一個維度向你望來。"
  },
  AvgDialog_65476_Content_14 = {
    Text = "那道強烈的震盪攪碎了你的意識，讓你的記憶開始變得混亂起來。\n在混亂的大腦中，N的話躍動著漂浮在你面前。你自嘲地牽動嘴角。"
  },
  AvgDialog_65476_Content_15 = {
    Text = "你說的沒錯，N……我根本不知道，我所要面對的究竟是什麼……"
  },
  AvgDialog_65476_Content_16 = {
    Text = "只是一個碎片而已……我根本，沒有和祂對視的資格……"
  },
  AvgDialog_65476_Content_17 = {
    Text = "你強撐起身體，望著那無數個癡愚的眼瞳。"
  },
  AvgDialog_65476_Content_18 = {
    Text = "憤怒和悲哀的情緒在你心底彌漫翻湧。但你明白，你什麼也改變不了。"
  },
  AvgDialog_65476_Content_2 = {
    Text = "一切的攻擊都落入虛空，一切的防禦都不堪一擊。"
  },
  AvgDialog_65476_Content_20 = {
    Text = "無數的目光聚焦在你身上。融蝕如潮水般在你身上湧現。\n體內的權柄消弭著融蝕，但遠遠趕不上融蝕出現的速度。"
  },
  AvgDialog_65476_Content_21 = {
    Text = "劇烈的痛苦讓你渾身顫抖。記憶在融蝕中消解，大腦逐漸變得空白。\n你機械性地握住銀鑰匙，向那令人戰慄的目光舉起——"
  },
  AvgDialog_65476_Content_23 = {Text = "轟——"},
  AvgDialog_65476_Content_24 = {Text = "轟——"},
  AvgDialog_65476_Content_3 = {
    Text = "強烈的震盪在門扉世界中炸開，你跪倒在地，痛苦地捂住自己劇烈跳動的心臟。"
  },
  AvgDialog_65476_Content_4 = {
    Text = "這是……怎麼回事！%heorshe%明明已經贏了……"
  },
  AvgDialog_65476_Content_5 = {
    Text = "%heorshe%沒有贏，拉蒙娜。"
  },
  AvgDialog_65476_Content_6 = {
    Text = "%heorshe%所擊敗的，只是託乎瓦波的一道目光。"
  },
  AvgDialog_65476_Content_8 = {
    Text = "託乎瓦波存在於無數的維度。當祂睜開眼時，祂的目光，將在無數的維度之中逡巡。"
  },
  AvgDialog_65476_Content_9 = {
    Text = "這道被阻擋的目光，吸引了託乎瓦波的注意。其他的目光，那些真正強大的目光……"
  },
  AvgDialog_65477_Content_1 = {
    Text = "她站在道路的盡頭，凝望著你。"
  },
  AvgDialog_65477_Content_10 = {
    Text = "你說，我不能輕易倒下。我是唯一的守密人，我將負責調查和記錄所有被融蝕抹消的歷史……"
  },
  AvgDialog_65477_Content_11 = {
    Text = "你做到了。你已經做到的、你將要做到的事，遠超於此。"
  },
  AvgDialog_65477_Content_14 = {
    Text = "我是你的助手和搭檔。我一直在你身邊，與你經歷每一件事，見證你與每一個敵人戰鬥，聽你說每一句話……"
  },
  AvgDialog_65477_Content_15 = {
    Text = "我知道，這一路上，你很累，尤其是在今天、現在……"
  },
  AvgDialog_65477_Content_16 = {
    Text = "晶瑩的淚滴從她眼中落下。她微笑著，凝視著你的眼。"
  },
  AvgDialog_65477_Content_17 = {
    Text = "這是最後一次選擇了。很簡單，就和我教你的那些題一樣，就和我們第一次連結時一樣……"
  },
  AvgDialog_65477_Content_18 = {
    Text = "斷開和我的連結吧，守密人。"
  },
  AvgDialog_65477_Content_2 = {
    Text = "你想起阿庫特之春第一次睜開眼時，她臉上凌亂的髮絲。"
  },
  AvgDialog_65477_Content_20 = {
    Text = "斷開和拉蒙娜的連結"
  },
  AvgDialog_65477_Content_21 = {
    Text = "你以前也說，微積分很簡單。你騙了我兩次，拉蒙娜。"
  },
  AvgDialog_65477_Content_22 = {
    Text = "這道題目，比微積分難多了。"
  },
  AvgDialog_65477_Content_23 = {
    Text = "很抱歉，這次沒有答案讓你抄了……\n這是屬於你一個人的題目，我相信，你一定能解開它。"
  },
  AvgDialog_65477_Content_24 = {
    Text = "……再見了，守密人。"
  },
  AvgDialog_65477_Content_3 = {
    Text = "你想起彌薩格求學的時光裡，她時常皺起的眉頭。"
  },
  AvgDialog_65477_Content_4 = {
    Text = "你想起第一次握住她的手時，那道隱秘流淌的電流。"
  },
  AvgDialog_65477_Content_5 = {
    Text = "電流穿透手套、指尖、神經，在你的精神深處，彙聚成第一個清晰的影子。\n你想起與那道影子一起，走過的漫長艱難的道路。"
  },
  AvgDialog_65477_Content_6 = {
    Text = "如今，你再次站在影子面前，手中握著那把不存在的、名為割棄的刀刃。"
  },
  AvgDialog_65477_Content_7 = {
    Text = "還記得鑰塚儀式上第一次連結時，我對你說了什麼嗎，守密人？"
  },
  AvgDialog_65477_Content_8 = {
    Text = "我記得。每一個字。"
  },
  AvgDialog_65477_Content_9 = {
    Text = "你說，從一年前開始，你就在期待那一天。我們的精神連結非常穩定，精神與生命力從未如今天一般強韌。"
  },
  AvgDialog_65478_Content_1 = {
    Text = "你的信標已經被毀掉，「朵爾」！"
  },
  AvgDialog_65478_Content_11 = {
    Text = "這是……不！……"
  },
  AvgDialog_65478_Content_12 = {
    Text = "這是……不！……"
  },
  AvgDialog_65478_Content_13 = {
    Text = "空洞，液化，粉末，消失。融蝕發展的流程你爛熟於心。"
  },
  AvgDialog_65478_Content_14 = {
    Text = "但在這道目光下，你對於融蝕的一切認知已完全失效。"
  },
  AvgDialog_65478_Content_15 = {
    Text = "牆壁在消失。臺階在消失。甚至黑池本身也在消失。"
  },
  AvgDialog_65478_Content_16 = {
    Text = "你忘記了牆壁的顏色。你忘記了臺階的位置。那道目光之下，萬事萬物化作永恆的虛無，連空白的概念都不曾遺留。"
  },
  AvgDialog_65478_Content_17 = {
    Text = "那道目光逡巡著，最終定格在你的身上。"
  },
  AvgDialog_65478_Content_2 = {
    Text = "於麗埃特已經看到了真相，那不是你們想要的未來……"
  },
  AvgDialog_65478_Content_20 = {
    Text = "睜開眼，守密人。"
  },
  AvgDialog_65478_Content_21 = {
    Text = "那光芒一點也不讓你覺得刺眼，只讓你感到溫和，如同堆滿你眼中的銀白羽毛。"
  },
  AvgDialog_65478_Content_22 = {
    Text = "在你面前的，是塔薇的臉。\n一如初見那日，神聖，溫和，不可侵犯。"
  },
  AvgDialog_65478_Content_23 = {
    Text = "祂的六翼舒展開來，擋在你與那道毀滅一切的目光之間。超越常理的聖潔光芒在背後閃爍。每一次翕動，都是一次維度的變化，將那毀滅一切的目光轉移向那不存在的奇點。"
  },
  AvgDialog_65478_Content_24 = {
    Text = "融蝕的黑液沿著她的羽翼滑落，覬覦著每一寸不可褻瀆的聖體。每一個瞬間，祂的身軀無數次化為枯骨，祂的面容無數次被融蝕殆盡，又無數次恢復如初。"
  },
  AvgDialog_65478_Content_25 = {
    Text = "——祂以維度對抗那道目光，對抗那毀滅一切、無可違逆的意志。"
  },
  AvgDialog_65478_Content_26 = {
    Text = "在這場純淨與污穢的戰爭裡，祂們在每個瞬間進行著無數次交鋒。每一次交鋒，都讓塔薇的臉色變得虛弱一分。"
  },
  AvgDialog_65478_Content_27 = {
    Text = "祂的目光，將暫時停留在我藏身的維度。你還有時間，守密人。"
  },
  AvgDialog_65478_Content_29 = {
    Text = "聽我說，守密人。"
  },
  AvgDialog_65478_Content_3 = {
    Text = "未來？我和於麗埃特那個單純的傢伙不一樣。我想要的，從來就不是什麼未來。"
  },
  AvgDialog_65478_Content_30 = {
    Text = "跨入門扉。去找到答案。去想起，關於你自己的一切。"
  },
  AvgDialog_65478_Content_31 = {
    Text = "她望著你。那張溫和聖潔的臉上，有著不可違逆的威嚴。"
  },
  AvgDialog_65478_Content_32 = {
    Text = "你打敗了我們。你做到了。"
  },
  AvgDialog_65478_Content_33 = {
    Text = "現在，去拯救他們。"
  },
  AvgDialog_65478_Content_34 = {
    Text = "你還會再做到一次的。對嗎，守密人？"
  },
  AvgDialog_65478_Content_4 = {
    Text = "零件與渾濁的液體鋪滿她的腳下，鮮血與渾濁的融蝕液灑滿她的全身，她渾然不覺，爆發出一陣與纖瘦身軀極不相符的狂妄興奮的大笑。"
  },
  AvgDialog_65478_Content_5 = {
    Text = "來不及了，愚鈍的人類。"
  },
  AvgDialog_65478_Content_6 = {
    Text = "戰鬥的勝負，已經無關緊要……\n最終的贏家是我，守密人。"
  },
  AvgDialog_65478_Content_8 = {
    Text = "「朵爾」臉上帶著滿足的笑意，雙手微微張開，如同一朵虔誠腐敗的花束。"
  },
  AvgDialog_65478_Content_9 = {
    Text = "她緩緩跪倒在地，在她身後，那扇巨大的門扉，已完全打開。"
  },
  AvgDialog_65479_Content_10 = {
    Text = "甦醒吧。"
  },
  AvgDialog_65479_Content_12 = {
    Text = "雙子神像明明已經被破壞……為什麼……"
  },
  AvgDialog_65479_Content_13 = {
    Text = "無數道漣漪在你的精神維度中泛起。從世界各地傳來的震盪，清晰地映入你的腦海。"
  },
  AvgDialog_65479_Content_14 = {
    Text = "這是……融蝕裂隙！……"
  },
  AvgDialog_65479_Content_15 = {
    Text = "你曾見過蠟像館粘稠的煉獄，見過拉伊猙獰的深淵，也剛剛經歷黑池恐怖的震盪。"
  },
  AvgDialog_65479_Content_16 = {
    Text = "你了解所有人類已知的關於融蝕的知識，但從未有任何記錄告訴你，融蝕裂隙會如邪惡的黑色花朵，在同一時間綻放於世界的每一個角落。"
  },
  AvgDialog_65479_Content_17 = {
    Text = "無數個世紀，無數個文明，人類前赴後繼地探索，犧牲生命與熱情。\n但在真正的混沌面前，人類換來的只有脆弱與無知。"
  },
  AvgDialog_65479_Content_18 = {
    Text = "嘖嘖嘖，真是壯觀吶……\n祂就快要甦醒。再這樣愣著就來不及了，守密人。"
  },
  AvgDialog_65479_Content_2 = {
    Text = "祂做了一場漫長的夢。"
  },
  AvgDialog_65479_Content_21 = {
    Text = "N深深嗅了一口手裡的玫瑰，發出一聲滿足的歎息。"
  },
  AvgDialog_65479_Content_22 = {
    Text = "自己下場，哪有看樂子有趣。"
  },
  AvgDialog_65479_Content_23 = {
    Text = "彌薩格的內鬼另有其人……"
  },
  AvgDialog_65479_Content_24 = {
    Text = "沒錯……雙子神像已經被擊敗，一定是那個內鬼在喚醒祂。\n朵爾在查這件事，需要儘快找到她！"
  },
  AvgDialog_65479_Content_25 = {
    Text = "你快速地按上了校徽的通訊鍵。"
