  },
  AvgDialog_6773_Content_11 = {
    Text = "嚮導的聲音在顫抖。面對此生從未經歷過的恐懼，這個普通人拿出畢生的勇氣，站在莉莉的身前。"
  },
  AvgDialog_6773_Content_110 = {
    Text = "她的臉上，湧現出癲狂的笑意。"
