  AvgDialog_6811_Content_37 = {
    Text = "有位病人家裡是開酒廠的，家屬為了表達感謝，送了兩瓶上好的自釀葡萄酒過來。"
  },
  AvgDialog_6811_Content_38 = {
    Text = "一個人品嚐實在是太冷清了。怎麼樣，要一起嚐嚐嗎？"
  },
  AvgDialog_6811_Content_39 = {
    Text = "看著他遞過來的高腳杯，你無奈地嘆了口氣。"
  },
  AvgDialog_6811_Content_4 = {
    Text = "沒錯。歡迎回家，希洛。"
  },
  AvgDialog_6811_Content_40 = {
    Text = "教授，我最近很忙的……如果沒什麼事的話，我就先走了。"
  },
  AvgDialog_6811_Content_41 = {
    Text = "不懂得享受的人生是沒有樂趣的。"
  },
  AvgDialog_6811_Content_42 = {
    Text = "啊，還有另外一件事，雖然跟品酒比起來微不足道，但我想你可能會感興趣。"
  },
  AvgDialog_6811_Content_43 = {Text = "什麼？"},
  AvgDialog_6811_Content_44 = {
    Text = "那位送酒的朋友告訴我，一位病人出現了異樣。精神病院裡整天整夜迴盪著她的呻吟和嚎叫，而她越來越差的精神和體質也都讓醫生們束手無策。"
  },
  AvgDialog_6811_Content_45 = {
    Text = "的確很糟糕，但我在精神病症領域實在沒有什麼建樹……"
  },
  AvgDialog_6811_Content_46 = {
    Text = "和醫學領域無關——或許你還沒有忘記，一位小喚醒體女士，正鏈接在弗朗西斯精神病院的病人身上。"
  },
  AvgDialog_6811_Content_48 = {
    Text = "把她……交給我！"
  },
  AvgDialog_6811_Content_49 = {
    Text = "真是可憐啊，僅僅只是失去銀芯鏈接，就衰退成如此形貌。"
  },
  AvgDialog_6811_Content_5 = {
    Text = "你想要去的山，你想要見的人，都在這裡。"
  },
  AvgDialog_6811_Content_50 = {
    Text = "弗朗西斯已經鏈接了莉莉，那希洛的鏈接者……"
  },
  AvgDialog_6811_Content_51 = {
    Text = "朵爾在《喚醒體製作與鏈接基礎》課程上曾經講過，排除無法指揮和控制的副作用，喚醒體的最佳鏈接對象，就是這座療養院的病患們了。"
  },
  AvgDialog_6811_Content_52 = {
    Text = "療養院的病患……？\n因為本來精神就不穩，所以不害怕失控嗎？"
  },
  AvgDialog_6811_Content_53 = {
    Text = "希洛孑立碼頭，長髮隨風獵獵舞動。"
  },
  AvgDialog_6811_Content_54 = {
    Text = "船要開了，要登船嗎？"
  },
  AvgDialog_6811_Content_55 = {
    Text = "希洛揮了揮手，示意渡船不必等待自己。\n她還沒有想好下一站的地點。"
  },
  AvgDialog_6811_Content_56 = {
    Text = "希洛……從療養院離開以後，她就失蹤了。是出了什麼事嗎？"
  },
  AvgDialog_6811_Content_57 = {
    Text = "看看這個。"
  },
  AvgDialog_6811_Content_58 = {
    Text = "一張散發著新印油墨味的報紙被推到你的面前。"
  },
  AvgDialog_6811_Content_59 = {
    Text = "“位於極地的雪原艾爾沃斯，於@2年@2月@2日發生特大雪崩，經測定為目前已知的最大規模，原因不明……”"
  },
  AvgDialog_6811_Content_6 = {
    Text = "赫伯特伸出手，指向前方風雪覆蓋的群山。"
  },
  AvgDialog_6811_Content_60 = {
    Text = "艾爾……沃斯？"
  },
  AvgDialog_6811_Content_61 = {
    Text = "精神病人受到喚醒體希洛的影響，口中所呼喊著的，正是前不久剛發生過雪崩的高山雪原——艾爾沃斯。"
  },
  AvgDialog_6811_Content_62 = {
    Text = "還有之前你在夢中見到的那些景象。讓人印象深刻，不是嗎？"
  },
  AvgDialog_6811_Content_63 = {
    Text = "夢境中的景象，希洛的動向，還有這場異常的雪崩，都指向那裡……"
  },
  AvgDialog_6811_Content_64 = {
    Text = "夢境裡出現的是提燈教會的符號，他們要做的事情，或許和希洛有關係。"
  },
  AvgDialog_6811_Content_65 = {
    Text = "沒錯。這世上總有些不解風情的傢伙，熱衷於打擾別人的生活。"
  },
  AvgDialog_6811_Content_66 = {
    Text = "我會查清楚艾爾沃斯發生的事"
  },
  AvgDialog_6811_Content_67 = {
    Text = "我會找到希洛"
  },
  AvgDialog_6811_Content_68 = {
    Text = "明白了。時間緊急，我這就準備動身，前往艾爾沃斯。"
  },
  AvgDialog_6811_Content_69 = {
    Text = "我不是這個意思……喂？"
  },
  AvgDialog_6811_Content_7 = {
    Text = "你確定，她會出現？"
  },
  AvgDialog_6811_Content_70 = {
    Text = "真不明白，為什麼每個人都這樣急匆匆的。好歹，也把這杯酒喝了吧……"
  },
  AvgDialog_6811_Content_71 = {
    Text = "面前的酒被一飲而盡，他拿著空杯子，衝著門輕輕晃了晃。"
  },
  AvgDialog_6811_Content_72 = {
    Text = "願銀鑰指引前路，守密人。"
  },
  AvgDialog_6811_Content_73 = {
    Text = "守密人，目前情況如何？"
  },
  AvgDialog_6811_Content_74 = {
    Text = "已抵達艾爾沃斯冰原，情況穩定。"
  },
  AvgDialog_6811_Content_75 = {
    Text = "和你的推測一致，莉莉能模糊地察覺到同源力量的波動，找到正確的方向。"
  },
  AvgDialog_6811_Content_76 = {
    Text = "旅程裡有發生什麼異狀嗎？"
  },
  AvgDialog_6811_Content_77 = {
    Text = "異狀倒沒有，無非就是行進在碎冰遍布的海上，每天祈禱咆哮的風不要把船弄翻……也不知道提燈教會跟希洛為什麼都盯上了這種地方。"
  },
  AvgDialog_6811_Content_78 = {
    Text = "不過，附近的當地人似乎對我們的到來不太歡迎，經常叫嚷著山神、怪物之類不清不楚的話。"
  },
  AvgDialog_6811_Content_79 = {
    Text = "有件事情需要通知你。你這次行程的審批十分匆忙，之前沒有來得及做詳細的前置調查。"
  },
  AvgDialog_6811_Content_8 = {
    Text = "就像你會出現在這裡一樣。這是命運的召喚。\n沒有人能夠拒絕命運，不是嗎？"
  },
  AvgDialog_6811_Content_80 = {
    Text = "我這幾天一直在檔案室，找到了一份關於艾爾沃斯的資料，上面提到……"
  },
  AvgDialog_6811_Content_81 = {
    Text = "你正和朵爾說著話，看到莉莉走到一個窟窿面前。"
  },
  AvgDialog_6811_Content_82 = {
    Text = "莉莉，小心一些，不要掉進去了。"
  },
  AvgDialog_6811_Content_83 = {
    Text = "莉莉朝遠處走了幾步，好奇地蹲了下來。"
  },
  AvgDialog_6811_Content_84 = {
    Text = "有……聲音……"
  },
  AvgDialog_6811_Content_85 = {
    Text = "你走近了幾步。海水不知道被什麼東西攪動，透過半透明的冰層發出沉悶的聲響。"
  },
  AvgDialog_6811_Content_86 = {
    Text = "一團模糊的黑影猛然出現在冰層之下，正以極快的速度越變越大……"
  },
  AvgDialog_6811_Content_87 = {Text = "危險！"},
  AvgDialog_6811_Content_88 = {
    Text = "你迅速將少女從深淵的邊緣拽回。冰面在她腳下應聲破裂，數個龐大到近乎怪異的極地生物衝破冰層，扭動著不成比例的身軀攀爬而出。"
  },
  AvgDialog_6811_Content_89 = {
    Text = "詭異的黑色膿皰從牠們的皮毛下面湧出，膿皰內部似乎被什麼東西攪動著，散發出腐朽的味道。"
  },
  AvgDialog_6811_Content_9 = {
    Text = "聽見這話，少女咧嘴一笑，露出兩顆尖利的牙。"
  },
  AvgDialog_6811_Content_90 = {
    Text = "嘶啞、刺耳的尖嘯聲響起。那些怪物睜著被膿皰腐蝕的眼睛望著你們，滿含著原始的敵意。"
  },
  AvgDialog_6811_Content_91 = {
    Text = "是融蝕引發的變異……莉莉小心！"
  },
  AvgDialog_6811_Content_92 = {
    Text = "手中的銀鑰散發出溫和的光芒，黑色的球體擋在莉莉面前，碾碎了那些來歷不明的怪物。"
  },
  AvgDialog_6811_Content_93 = {
    Text = "躲開了怪物臨死前的危險攻擊，你呼出一口濁氣。"
  },
  AvgDialog_6811_Content_94 = {
    Text = "敵人已清剿完成……朵爾，那些未知怪物是什麼？"
  },
  AvgDialog_6811_Content_95 = {
    Text = "我也是剛剛調取檔案後才得知，彌薩格曾派出一隊科學家和調查員，前往艾爾沃斯進行秘密考察，他們也遭遇並記載了這種變異生物。"
  },
  AvgDialog_6811_Content_96 = {
    Text = "考察隊傳回的記檔中，有沒有提及“山神”？我總懷疑，這和希洛有些關係。"
  },
  AvgDialog_6811_Content_97 = {
    Text = "很遺憾，秘密考察的存檔和某些人的大腦一樣乾淨。"
  },
  AvgDialog_6811_Content_98 = {
    Text = "他們沒能考察出任何成果？我有一些問題想問問他們，能和他們直接通話嗎？"
  },
  AvgDialog_6811_Content_99 = {
    Text = "通訊的那一頭沉默了片刻。"
  },
  AvgDialog_6812_Content_10 = {
    Text = "一些不夠幸運的登山者。"
  },
  AvgDialog_6812_Content_100 = {
    Text = "轟隆——"
  },
  AvgDialog_6812_Content_101 = {
    Text = "煙塵夾雜著雪粒，在你眼前逸散開。"
  },
  AvgDialog_6812_Content_102 = {
    Text = "漆黑的甬道被硬生生劈開了一道裂口，雪亮的白光灑落肩頭。"
  },
  AvgDialog_6812_Content_103 = {
    Text = "抓緊點，我帶你們出去。"
  },
  AvgDialog_6812_Content_104 = {
    Text = "她將洞窟的岩塊劈碎，將你們從亂石堆裡拽了出來。"
  },
  AvgDialog_6812_Content_105 = {
    Text = "欠你的人情，現在還清……"
  },
  AvgDialog_6812_Content_108 = {
    Text = "話音未落，她突然一腳踩空。"
  },
  AvgDialog_6812_Content_109 = {
    Text = "——記憶中原本是山坡的地面憑空消失，在頃刻間，化成了萬丈深淵。"
  },
  AvgDialog_6812_Content_11 = {
    Text = "這些屍體為什麼在牆壁裡面？牆……會吃人嗎？"
  },
  AvgDialog_6812_Content_12 = {
    Text = "現在需要我們操心的事情已經夠多了。繼續趕路吧。"
  },
  AvgDialog_6812_Content_14 = {
    Text = "……這裡的味道有點奇怪，和我們之前聞到的惡臭很類似，不過要強烈許多。也許跟火山活動有關。"
  },
  AvgDialog_6812_Content_15 = {
    Text = "我們可能正在接近火山口。"
  },
  AvgDialog_6812_Content_16 = {
    Text = "這個味道，有些熟悉……"
  },
  AvgDialog_6812_Content_17 = {
    Text = "牆壁在冒熱氣，這洞窟不太尋常。"
  },
  AvgDialog_6812_Content_18 = {
    Text = "是這樣嗎？我摸摸看。"
  },
  AvgDialog_6812_Content_19 = {
    Text = "嗯？希洛，你從我身上拿了什麼？"
  },
  AvgDialog_6812_Content_2 = {
    Text = "你們循著幾乎無處落腳的冰川石壁攀爬而上，依據希洛對莉莉的模糊感應，鑽進了這道岩縫之中。"
  },
  AvgDialog_6812_Content_20 = {
    Text = "一些掉在你身上的髒東西。"
  },
  AvgDialog_6812_Content_22 = {
    Text = "她將手上的小型黑色膿皰甩到牆上，一劍刺穿。"
  },
  AvgDialog_6812_Content_25 = {
    Text = "越往裡面，惡臭的氣味越濃……哦，抱歉，擠到你了。"
  },
  AvgDialog_6812_Content_26 = {
    Text = "再靠近的話，後果自負，人類。"
  },
  AvgDialog_6812_Content_27 = {
    Text = "真的不能怪我，是路越變越窄了……這個牆好像會動……"
  },
  AvgDialog_6812_Content_28 = {
    Text = "下次可以找個好點的理由。"
  },
  AvgDialog_6812_Content_29 = {
    Text = "<Small:呃……啊啊啊啊……求你放過我們……>"
  },
  AvgDialog_6812_Content_3 = {
    Text = "冰川內部的岩縫本該擠滿冰雪，這裡氣溫卻並不低，甚至在內壁上掛著令人不安的蘚。"
  },
  AvgDialog_6812_Content_30 = {
    Text = "微弱的聲音從洞穴深處傳來。"
  },
  AvgDialog_6812_Content_31 = {
    Text = "裡面有人！終於找到他們了！"
  },
  AvgDialog_6812_Content_32 = {
    Text = "你正想要往內深入，一隻手拽住了你的手臂，希洛面色凝重地衝你搖了搖頭。"
  },
  AvgDialog_6812_Content_33 = {
    Text = "你說的沒錯……牆壁正在變窄。再往裡深入，就出不去了。"
  },
  AvgDialog_6812_Content_34 = {
    Text = "牆壁像是在回應她的話，開始緩慢地蠕動。"
  },
  AvgDialog_6812_Content_35 = {
    Text = "一隻腐化的手掌從牆裡緩緩翻出，緊接著是大腿、頭顱……"
  },
  AvgDialog_6812_Content_36 = {
    Text = "數不清的屍塊從牆壁上湧出，有的已是森森白骨，有的還帶著腐爛的肉塊。"
  },
  AvgDialog_6812_Content_37 = {
    Text = "來自不同的登山者的斑駁碎肢，如同一朵腐敗殘忍的花，在你面前緩緩盛開。"
  },
  AvgDialog_6812_Content_38 = {
    Text = "這是？！……"
  },
  AvgDialog_6812_Content_39 = {
    Text = "原來……這就是惡臭的來源……"
  },
  AvgDialog_6812_Content_4 = {
    Text = "把她留在那裡，真的好嗎？"
  },
  AvgDialog_6812_Content_40 = {
    Text = "如果我們兩個一起進去，很可能會出不來。希洛，你在外面等著我！"
  },
  AvgDialog_6812_Content_42 = {
    Text = "沒等她說完，你掙開她的手，一頭衝進了散發著惡臭的幽深甬道。"
  },
  AvgDialog_6812_Content_44 = {
    Text = "莉莉！艾維斯教授！嚮導！你們在哪裡？"
  },
  AvgDialog_6812_Content_45 = {
    Text = "向偉大的@3……祭奠……"
  },
  AvgDialog_6812_Content_46 = {
    Text = "你循聲邁入洞穴的盡頭，無數岩塊與尖刺圍擁的所在，拱衛著一座漆黑的祭壇。"
  },
  AvgDialog_6812_Content_47 = {
    Text = "祭壇上有幾個暗紅色人體，瑟縮地跪拜在地，已經沒了聲息。"
  },
  AvgDialog_6812_Content_48 = {
    Text = "還是來遲了一步……"
  },
  AvgDialog_6812_Content_49 = {
    Text = "你從通道的陰影中伸出了頭，看向人們頂禮膜拜的上空。"
  },
  AvgDialog_6812_Content_5 = {
    Text = "這是她自己的選擇。"
  },
  AvgDialog_6812_Content_50 = {
    Text = "穹頂之上有一塊不自然的破損，岩石的空洞裡，懸浮著那隻曾有過一面之緣、刻畫著提燈教會印記的熒藍色怪物。"
  },
  AvgDialog_6812_Content_51 = {
    Text = "那是無比恐怖和龐大的生物，這也是你第一次得以仔細打量它的外表。"
  },
  AvgDialog_6812_Content_52 = {
    Text = "近似於節肢動物的骨骼外露，體表覆著一層冰霜，肢體中心跳動著一簇極為特殊的藍色火焰，噴薄出令人窒息的寒意。"
  },
  AvgDialog_6812_Content_54 = {
    Text = "又是這些膿皰，這下麻煩了……"
  },
  AvgDialog_6812_Content_55 = {
    Text = "不許傷害大%brotherorsister1%！"
  },
  AvgDialog_6812_Content_57 = {
    Text = "黑色的球體出現在你面前，將那些襲向你的膿皰碾成一灘灘骯髒的液體。"
  },
  AvgDialog_6812_Content_58 = {
    Text = "莉莉？！你沒事吧？"
  },
  AvgDialog_6812_Content_59 = {
    Text = "莉莉沒事。那個壞東西，是兇手。"
  },
  AvgDialog_6812_Content_6 = {
    Text = "她在那裡，也算是為我們爭取了時間，我們得加緊……啊！"
  },
  AvgDialog_6812_Content_60 = {
    Text = "莉莉從一處孔隙中鑽出來，小手拖著一根長長的登山繩，另一頭則綴著兩個被裹得嚴實、動彈不得的成年人。"
  },
  AvgDialog_6812_Content_61 = {
    Text = "他們都被這個壞東西凍僵了，但還沒有死掉。莉莉記得大%brotherorsister1%的話，莉莉——要保護他們。"
  },
  AvgDialog_6812_Content_62 = {
    Text = "但是莉莉不記得路，走錯了，才走到了這裡……"
  },
  AvgDialog_6812_Content_63 = {
    Text = "莉莉，你知道這裡是什麼地方嗎？"
  },
  AvgDialog_6812_Content_64 = {
    Text = "莉莉抬起頭，天真地看著頭頂蜷起身體的怪物。"
  },
  AvgDialog_6812_Content_65 = {
    Text = "這裡是……嗯，怪物睡覺的地方。"
  },
  AvgDialog_6812_Content_66 = {
    Text = "祭壇上的逝者身上沾滿了血漬，仔細一看，都是考察隊之前失蹤的熟面孔。"
  },
  AvgDialog_6812_Content_67 = {
    Text = "你帶著莉莉從甬道裡溜出，穿梭在碎石堆裡。在尚未驚動怪物的情況下，成功接近了祭壇。"
  },
  AvgDialog_6812_Content_68 = {
    Text = "這傢伙，恐怕是在籌劃生人活祭。"
  },
  AvgDialog_6812_Content_69 = {
    Text = "是……什麼？"
  },
  AvgDialog_6812_Content_7 = {
    Text = "你被地上一截突出的白骨絆了一跤，被希洛眼疾手快地抓住，拽了回來。"
  },
  AvgDialog_6812_Content_70 = {
    Text = "透過獻祭活人的方式，喚醒某位存在。這怪物被提燈教會控制，他們想讓不該存在於世的傢伙再度歸來。"
  },
  AvgDialog_6812_Content_71 = {
    Text = "那個傢伙……是什麼東西呢？"
  },
  AvgDialog_6812_Content_72 = {
    Text = "不清楚，上課的時候只提到過這種活祭儀式……"
  },
  AvgDialog_6812_Content_73 = {
    Text = "看來怪物供奉的那位，對祭品很挑剔，所以這裡才只有幾個人。"
  },
  AvgDialog_6812_Content_74 = {
    Text = "之前那些被殺害的考察隊員，體表多處傷口和全身粉碎性骨折，都只是……不想要的祭品，所以能隨意處置。"
  },
  AvgDialog_6812_Content_75 = {
    Text = "面對輕而易舉碾死的生物，牠們連一點可悲的仁慈都欠奉。"
  },
  AvgDialog_6812_Content_76 = {
    Text = "你咬緊了牙，試圖不讓憤怒和悲哀影響自己。莉莉察覺到了你的情緒，貼得更近了一些，試圖給你一點安慰。"
  },
  AvgDialog_6812_Content_77 = {
    Text = "沉默了片刻，你摸了摸莉莉的頭，皮膚上傳來溫熱的觸感——那是如此鮮活的生命。"
  },
  AvgDialog_6812_Content_78 = {
    Text = "莉莉，現在，我們要帶活著的人回家。"
  },
  AvgDialog_6812_Content_79 = {
    Text = "把他們拖走，對，就是這樣……等等，小心！"
  },
  AvgDialog_6812_Content_8 = {
    Text = "絆倒你的，是一根嵌進牆壁內的完整人類腿骨，如同被岩石牆壁吞吃入內後，留下的殘渣。"
  },
  AvgDialog_6812_Content_80 = {
    Text = "莉莉拖動屍體的力氣太大，冰雕般的人體與碎石狠狠相撞，你們背後猝然亮起螢藍的火焰。"
  },
  AvgDialog_6812_Content_81 = {
    Text = "不好，牠看見我們了！"
  },
  AvgDialog_6812_Content_82 = {
    Text = "寒風如同利刃般割過臉頰。怪物噴吐著冰霧，轉而盯住了陰影中的你們，伸展著骨骼朝你們逼近。"
  },
  AvgDialog_6812_Content_83 = {
    Text = "……走開！"
  },
  AvgDialog_6812_Content_85 = {
