  AvgDialog_6813_Content_41 = {
    Text = "山要見我，我便來見祂。"
  },
  AvgDialog_6813_Content_42 = {
    Text = "我是你的未來，“希洛”。等你有勇氣向命運舉起手裡的劍的時候，你便會成為我。"
  },
  AvgDialog_6813_Content_43 = {
    Text = "所以你想要向背叛者復仇，想保護搭救你的弗朗西斯。\n但戰鬥不是這樣的東西。"
  },
  AvgDialog_6813_Content_44 = {
    Text = "不是為了守護，不是為了復仇，不是為了求證。\n戰鬥就只是戰鬥而已。"
  },
  AvgDialog_6813_Content_45 = {
    Text = "你的世界太狹小了，所以總像燈蛾一樣在意他人點亮的星點微光。"
