  AvgDialog_71793_Content_83 = {
    Text = "蠕動的深綠觸肢匯聚著深淵的磅礴力量，自圖魯的身側攀出，如同有自身意志一般擴張，彷彿要化作王者身下宏偉的青金石王座。"
  },
  AvgDialog_71793_Content_84 = {
    Text = "可怖的巨獸像是受到無法違抗的命令而發出不甘的嗚咽，在那對峙中退縮地後退了一步。"
  },
  AvgDialog_71793_Content_85 = {
    Text = "那山脈一般的脊背漸漸沒入水中，最終隨著回退的浪潮緩緩回歸深海。"
  },
  AvgDialog_71793_Content_86 = {
    Text = "安然無恙。"
  },
  AvgDialog_71793_Content_87 = {
    Text = "天光透過雲層，重新灑在利莫里亞的大地上。"
  },
  AvgDialog_71793_Content_88 = {
    Text = "被海浪追趕吞噬的人群漸漸停下腳步，被淹沒的建築與土地重新出現，所有驚惶茫然的面龐上露出劫後餘生的狂喜。"
  },
  AvgDialog_71793_Content_89 = {
    Text = "是主！主來救我們了！"
  },
  AvgDialog_71793_Content_90 = {
    Text = "那是王儲，王儲們喚醒了吾主！"
  },
  AvgDialog_71793_Content_91 = {
    Text = "從看到孩子們走向王冠開始便沉默著默許的主祭，此時向祭台最高處的圖魯深深地彎下腰去——那是祭司臣服於王的禮儀。"
  },
  AvgDialog_71793_Content_92 = {
    Text = "而後他轉身顫抖著舉起權杖，用最莊嚴的聲音宣判。"
  },
  AvgDialog_71793_Content_93 = {
    Text = "吾主拯救了利莫里亞，祂已經做出了最後的選擇，讓我們向新的王儲——圖魯殿下行禮！"
  },
  AvgDialog_71793_Content_94 = {
    Text = "山呼的讚頌聲從人群中爆發，人們向著未來的新王彎下腰，有虔誠者甚至跪伏在地、親吻著這片土地喜極而泣。"
  },
  AvgDialog_71793_Content_95 = {
    Text = "在一旁愣住的諾亞此時也終於反應過來，衝上來熊抱住了圖魯，險些將圖魯撲倒在地。"
  },
  AvgDialog_71793_Content_97 = {
    Text = "諾亞激動得淚流滿面，那兩行血淚被淚水沖掉，化成一團髒污蹭在了圖魯身上。"
  },
  AvgDialog_71793_Content_98 = {
    Text = "你的臉……"
  },
  AvgDialog_71793_Content_99 = {
    Text = "諾亞這才意識到了什麼一般鬆開了手，尷尬又訕訕地退後了一步，他的脊背微微躬起，似乎在是否要行禮之間猶豫。"
  },
  AvgDialog_71794_Content_10 = {
    Text = "你努力睜開眼，視野中豁然出現的是兩行巨獸齒列一般佇立的廊柱、佈滿細密石刻的穹頂，以及向下長長綿延的石階——這是一座巍峨莊嚴的神殿。"
  },
  AvgDialog_71794_Content_100 = {
    Text = "明明寫字最慢，還要逞強裝英雄，這點東西就被收買了，真是沒出息。"
  },
  AvgDialog_71794_Content_101 = {
    Text = "朋友的事，怎麼能叫收買呢，那是，那是……我可是比你大幾歲，作為大哥照顧你是應該的，哎喲——"
  },
  AvgDialog_71794_Content_102 = {
    Text = "諾亞威武地挺起腰桿，卻一不小心扭到了痠澀的脖子，齜牙咧嘴地叫喚起來。"
  },
  AvgDialog_71794_Content_104 = {
    Text = "在逐漸沉悶的抄寫聲中，你看到圖魯的頭開始一沉一沉，雙眼也逐漸閉合，手中筆尖上的墨水滴答落在紙上，暈開一大團墨跡。"
  },
  AvgDialog_71794_Content_105 = {
    Text = "圖魯，醒醒！再堅持一下！"
  },
  AvgDialog_71794_Content_107 = {
    Text = "來聊聊天，說會兒話就不睏了，哎……馬上就是選儲儀式了，你覺得最後誰能戴上王冠？"
  },
  AvgDialog_71794_Content_108 = {
    Text = "圖魯的眼睛勉強睜開些許，乾脆把筆丟下，專心打起盹來。"
  },
  AvgDialog_71794_Content_109 = {
    Text = "你有抄這麼多遍禱告詞的熱情，想必再冰冷的神明都會被你打動的。"
  },
  AvgDialog_71794_Content_11 = {
    Text = "近乎三百六十度的怪異視角令你的感官一時陷入眩暈，但比起其他狀況，這顯然不是最要命的問題。"
  },
  AvgDialog_71794_Content_110 = {
    Text = "好啊，你又笑話我，我的精神力水平在大家之間甚至排不進前三呢，唉……"
  },
  AvgDialog_71794_Content_111 = {
    Text = "諾亞滿臉惆悵，像是也被無聊壞了，滔滔不絕地念叨起來。"
  },
  AvgDialog_71794_Content_112 = {
    Text = "阿莫斯對王冠的感應一直很強，塞繆爾的精神力幾乎是我們之中最好的……"
  },
  AvgDialog_71794_Content_113 = {
    Text = "哦不對，雖然你每天都在睡大覺，但我覺得你才是我們之中最厲害的。"
  },
  AvgDialog_71794_Content_114 = {
    Text = "你對我的信心和你對修行的熱情一樣莫名其妙。"
  },
  AvgDialog_71794_Content_115 = {
    Text = "我當然相信你啊，你平時做的那些夢，肯定不是普通的夢，萬一那就是主給你的啟示呢？"
  },
  AvgDialog_71794_Content_116 = {
    Text = "……主給我那麼多莫名其妙的啟示幹什麼，我這樣的凡人又什麼都改變不了。"
  },
  AvgDialog_71794_Content_117 = {
    Text = "話不是這麼說，萬一呢？世世代代的凡人努力下去，總有能改變的事，不然我們為什麼還要選神王嘛。"
  },
  AvgDialog_71794_Content_118 = {
    Text = "圖魯側過頭看了諾亞一眼，隨後那雙眼睛破天荒地轉向了你。"
  },
  AvgDialog_71794_Content_119 = {
    Text = "我覺得你能戴上。"
  },
  AvgDialog_71794_Content_12 = {
    Text = "（<Gray:怎麼……怎麼動不了，身體好奇怪，難道這次附身的對象不是人？>）"
  },
  AvgDialog_71794_Content_121 = {
    Text = "你這樣的濫好人，一定能當個好國王的。"
  },
  AvgDialog_71794_Content_122 = {
    Text = "嘶，你這是誇我還是罵我……難道你就一點也不好奇當上神王的生活嗎？"
  },
  AvgDialog_71794_Content_123 = {
    Text = "諾亞的罵罵咧咧聲裡，你與那雙橙黃色的眼眸對視，你感到一股莫名的衝動從內心湧出。"
  },
  AvgDialog_71794_Content_124 = {
    Text = "那是一種強烈的慾望，讓你迫不及待地想要將那個幼小的身影召喚至身旁，以緊緊攥住那個明亮如星辰的靈魂，使你們合二為一。"
  },
  AvgDialog_71794_Content_125 = {
    Text = "就像是感應到了你的所思所想，圖魯的眉頭微微皺起，露出了洞悉一切的複雜目光。"
  },
  AvgDialog_71794_Content_126 = {
    Text = "（<Gray:神的認同，只是一個囚籠……>）"
  },
  AvgDialog_71794_Content_127 = {
    Text = "你看見了圖魯眼中的倒影，在那淡漠而困倦的瞳孔中映出的，並不是一頂金色的皇冠。"
  },
  AvgDialog_71794_Content_128 = {
    Text = "而是一團扭曲虯結的、觸肢狀的幻影，正在召喚他似的舒展著濃綠的觸腕。"
  },
  AvgDialog_71794_Content_13 = {
    Text = "突兀的咔啦一聲，門軸艱澀轉動的聲音響起，神殿沉重的大門被輕輕推開一道縫隙。"
  },
  AvgDialog_71794_Content_14 = {
    Text = "幾個小蘿蔔頭似的孩子探頭探腦、鬼鬼祟祟鑽進了神殿。"
  },
  AvgDialog_71794_Content_15 = {
    Text = "在驚訝中，你看到在那一串孩童的最後出現了一個熟悉的身影。"
  },
  AvgDialog_71794_Content_17 = {
    Text = "醒醒，圖魯！我們的偉大計劃已經成功第一步了，可不能在這時候掉鏈子！"
  },
  AvgDialog_71794_Content_18 = {
    Text = "年長一些的少年悄聲搖晃著困頓得神遊天外的圖魯。"
  },
  AvgDialog_71794_Content_19 = {
    Text = "別搖了諾亞，都說了不要帶著我……"
  },
  AvgDialog_71794_Content_2 = {
    Text = "夢境是有邊緣的。"
  },
  AvgDialog_71794_Content_20 = {
    Text = "諾亞立刻捂住了圖魯的嘴。"
  },
  AvgDialog_71794_Content_21 = {
    Text = "噓，小點聲，這麼有意義的大事我怎麼會丟下你，第一批觸摸王冠的王儲候選人……我們說不定可以名留青史！"
  },
  AvgDialog_71794_Content_22 = {
    Text = "……能不能名留青史不知道，萬一被主祭發現，你的屁股肯定是要開花。"
  },
  AvgDialog_71794_Content_23 = {
    Text = "哎呀，不試試怎麼知道？有機會的時候沒去試一試可是會後悔的。"
  },
  AvgDialog_71794_Content_24 = {
    Text = "難道你就不想知道，為什麼王冠是吾主最直接的賜福，主祭卻一直不讓我們靠近王冠嗎？"
  },
  AvgDialog_71794_Content_26 = {
    Text = "一陣踢踢踏踏的腳步聲響過，孩子們很快來到了高高的供台旁，他們圍成一圈，透過晶瑩的琉璃塵罩向內看去。"
  },
  AvgDialog_71794_Content_27 = {
    Text = "一張張有些折射變形的稚嫩小臉擠滿了你三百六十度的視野，你從孩子們好奇的瞳孔中看到了自己的倒影，甚至還能聽到兩個孩子激動的鼻息。"
  },
  AvgDialog_71794_Content_28 = {
    Text = "（<Gray:可以了，小朋友，再近就不禮貌了。>）"
  },
  AvgDialog_71794_Content_29 = {
    Text = "哇……這是我們第一次離得這麼近看王冠吧。"
  },
  AvgDialog_71794_Content_3 = {
    Text = "對凡俗之人來說，夢是顛倒神秘、不可捉摸的泡沫幻影。"
  },
  AvgDialog_71794_Content_30 = {
    Text = "王冠上的寶石好漂亮……"
  },
  AvgDialog_71794_Content_31 = {
    Text = "這麼大的王冠，我們真的戴得上嗎？"
  },
  AvgDialog_71794_Content_32 = {
    Text = "（<Gray:如果我是王冠……看來這是在圖魯成為王儲之前的時候了。>）"
  },
  AvgDialog_71794_Content_33 = {
    Text = "在你的視角中，人類的情緒與慾望就像調色盤一樣清晰，不停變幻的顏色在每個人的腦海中湧動。"
  },
  AvgDialog_71794_Content_34 = {
    Text = "紅色、綠色、紫色、黃色，那是激動、緊張、渴求、喜悅……而在圖魯的身上，只有穩定而冷淡的灰色。"
  },
  AvgDialog_71794_Content_35 = {
    Text = "（<Gray:圖魯，圖魯？>）"
  },
  AvgDialog_71794_Content_36 = {
    Text = "圖魯始終半合著眼，顯得興致缺缺。在你不抱希望的呼喚聲中，你卻恍惚看到一雙漠然的橙黃眼眸。"
  },
  AvgDialog_71794_Content_37 = {
    Text = "那雙眼穿過彷彿睡著了的軀體，穿過現實沉重的藩籬，在某種虛幻的夢境之中與你靜靜對視。"
  },
  AvgDialog_71794_Content_38 = {
    Text = "你們有什麼感應嗎？"
