  AvgDialog_71794_Content_43 = {
    Text = "（<Gray:可能是因為裡面多了個人。>）"
  },
  AvgDialog_71794_Content_44 = {
    Text = "無人聽見你的積極應答，圍在你周圍努力冥想感悟的孩子們等待半晌，可惜並未有任何事發生。"
  },
  AvgDialog_71794_Content_45 = {
    Text = "來都來了，要不……摸摸看？"
  },
  AvgDialog_71794_Content_46 = {
    Text = "想要探究王冠的奧秘，看來必須要實際接觸一下了，動手吧。"
  },
  AvgDialog_71794_Content_47 = {
    Text = "孩子們緊張地互相看了看，彼此加油似的一起點了點頭。"
  },
  AvgDialog_71794_Content_48 = {
    Text = "諾亞也嚥了一口口水，把手在衣服上仔細擦了擦，這才伸手慢慢拿起王冠外的琉璃罩來。"
  },
  AvgDialog_71794_Content_49 = {
    Text = "隨著王冠漸漸暴露在空氣中，似乎真的有奇異的能量從光澤流轉的王冠上逸散出來。"
  },
  AvgDialog_71794_Content_5 = {
    Text = "當你的靈魂穿越那層薄膜，越出羊水般包裹著你的混濁夢境。"
  },
  AvgDialog_71794_Content_50 = {
    Text = "所有孩子不自覺屏住呼吸，注視著諾亞徹底移開琉璃罩，一個個下定決心一般都將手伸了出來，向王冠越探越近。"
  },
  AvgDialog_71794_Content_51 = {
    Text = "就在他們即將觸碰到王冠、你已經在構思許願神燈開場白的那一刻，一聲威嚴的怒吼滾雷一樣從神殿門口傳來，嚇得諾亞的手狠狠一哆嗦，差點將琉璃罩扔了出去。"
  },
  AvgDialog_71794_Content_52 = {
    Text = "你們在幹什麼？"
  },
  AvgDialog_71794_Content_53 = {
    Text = "所有人立刻僵在了原地，諾亞迅速將琉璃罩扣了回去，一把拽起圖魯的胳膊，衝著其他人焦急地擠眉弄眼。"
  },
  AvgDialog_71794_Content_55 = {
    Text = "一群孩子像熱鍋螞蟻一樣慌張地亂竄，圖魯被拽得向前走了兩步，又回過頭看向大步走來的主祭。"
  },
  AvgDialog_71794_Content_56 = {
    Text = "沒用的……"
  },
  AvgDialog_71794_Content_57 = {
    Text = "就像早就看穿了這次胡鬧的結局一樣，圖魯沒什麼反抗就被主祭拎起了衣領——當然倒霉的也包括諾亞。"
  },
  AvgDialog_71794_Content_58 = {
    Text = "阿莫斯、賽繆爾、格雷琴，現在立刻過來，不要讓我說第二遍。"
  },
  AvgDialog_71794_Content_59 = {
    Text = "沒跑出去幾步的孩子們見被點出了大名，只好垂頭耷腦地磨蹭了回來。"
  },
  AvgDialog_71794_Content_6 = {
    Text = "在那無數渺小泡沫之外的，是混亂而瘋狂的、古老者無垠的長夢。"
  },
  AvgDialog_71794_Content_60 = {
    Text = "主祭冷笑一聲，看著在面前一排站好的小犯人們。"
  },
  AvgDialog_71794_Content_61 = {
    Text = "說說吧，你們是來做什麼的？我教導了這麼久的王儲候選，難道教出了一群偷偷摸摸的小賊嗎？"
  },
  AvgDialog_71794_Content_62 = {
    Text = "我，我們……"
  },
  AvgDialog_71794_Content_63 = {
    Text = "悄悄擋在圖魯身前的諾亞此時攥了攥拳頭，主動站了出來。"
  },
  AvgDialog_71794_Content_64 = {
    Text = "因為選儲儀式馬上到了，我們想在儀式之前接觸一下王冠，增進一些感悟，並沒有不敬的意思……"
  },
  AvgDialog_71794_Content_65 = {
    Text = "增進感悟，那麼我還要誇獎你們勤奮了？"
  },
  AvgDialog_71794_Content_66 = {
    Text = "抱歉，主祭閣下，這件事是我們做的不對。"
  },
  AvgDialog_71794_Content_67 = {
    Text = "只是我們為了溝通吾主修行了這麼久，卻始終不能靠近主賜予的王冠，我們都對它太好奇了。"
  },
  AvgDialog_71794_Content_68 = {
    Text = "主祭看了看一派理性的男孩，意外地沒有出言斥責。"
  },
  AvgDialog_71794_Content_69 = {
    Text = "賽繆爾，你是大家之中精神力量較好的孩子，你覺得我為什麼一直不讓你們觸碰王冠？"
  },
  AvgDialog_71794_Content_70 = {
    Text = "因為我們還駕馭不了王冠的力量，王冠大概不會給我們回應。"
  },
  AvgDialog_71794_Content_71 = {
    Text = "阿莫斯，格雷琴，你們說呢？"
  },
  AvgDialog_71794_Content_72 = {
    Text = "因為王冠神聖又尊貴，代表著神王的權柄與責任，我們還沒有觸碰的資格？"
  },
  AvgDialog_71794_Content_73 = {
    Text = "因為我們的靈魂並不一定符合主的喜好，擅自觸碰王冠可能是一種褻瀆？"
  },
  AvgDialog_71794_Content_74 = {
    Text = "這位侍奉了神明一生的老人表情嚴肅地搖了搖頭。"
  },
  AvgDialog_71794_Content_75 = {
    Text = "你們說的都對，也都不對。這只是因為一個最簡單的道理：不是每個人都能戴上王冠。"
  },
  AvgDialog_71794_Content_76 = {
    Text = "那麼，主祭閣下，到底怎樣的人才能戴上王冠呢？"
  },
  AvgDialog_71794_Content_77 = {
    Text = "你們每天修行，錘煉精神，的確是為了更好地承接主的旨意。但成為主的代行者，更多是一種既定的宿命。"
  },
  AvgDialog_71794_Content_78 = {
    Text = "因此你們最後要做的，只是靜靜地等待主的選擇。無需悲傷，無需強求。至於不允許你們觸碰的原因……"
  },
  AvgDialog_71794_Content_79 = {
    Text = "主祭一向不苟言笑的神情在這一刻變得意外緩和起來，但那並不是慈愛，而是帶著一絲悲憫的意味。"
  },
  AvgDialog_71794_Content_8 = {
    Text = "潮濕。\n似乎永遠潮濕的空氣湧入你的夢境，送來淡淡的腥鹹氣息。"
  },
  AvgDialog_71794_Content_80 = {
    Text = "注定不能承接神諭的人如果強行戴上王冠，只會因無法承受神的力量而走向死亡。"
  },
  AvgDialog_71794_Content_81 = {
    Text = "寂靜的神殿中，孩子們陷入了長久的沉默，主祭的臉上也慢慢恢復了往日的嚴厲。"
  },
  AvgDialog_71794_Content_82 = {
    Text = "鑑於你們冒著死亡的風險也要來膜拜王冠的熱情，這份虔誠的精神十分可嘉。"
  },
  AvgDialog_71794_Content_83 = {
    Text = "為了向吾主彰顯你們的虔誠，所有人在王冠面前抄寫禱告詞一百遍，什麼時候抄完，什麼時候離開。"
  },
  AvgDialog_71794_Content_84 = {
    Text = "孩子們發出長長的抱怨聲，又在主祭的目光中閉上了嘴，只好紛紛垂頭喪氣地認命。"
  },
  AvgDialog_71794_Content_85 = {
    Text = "在那些看向你的種種不甘、畏懼、憧憬、崇拜的眼神之中，唯有圖魯始終未曾投來哪怕一瞥。"
  },
  AvgDialog_71794_Content_86 = {
    Text = "主祭意味深長地注視著從始至終無動於衷的圖魯，最終不發一言地離開了。"
  },
  AvgDialog_71794_Content_87 = {
    Text = "二人擦肩而過的那一瞬間，你聆聽到了未來的王者的心聲。"
  },
  AvgDialog_71794_Content_88 = {
    Text = "（<Gray:沒有用的，即便戴上王冠，又能改變什麼呢？>）"
  },
  AvgDialog_71794_Content_9 = {
    Text = "（<Gray:海風的味道……又入夢了？>）"
  },
  AvgDialog_71794_Content_90 = {
    Text = "很快，你端坐在高高的供台上，視線順著石階俯視而下，看到孩童們一個個歪七扭八地趴跪在坐墊上抄寫禱告詞。"
  },
  AvgDialog_71794_Content_91 = {
    Text = "聆聽吾主。歸依吾主。凡罪孽的，吾主將責罰。凡迷失的，吾主將指引……"
  },
  AvgDialog_71794_Content_92 = {
    Text = "喃喃的背誦聲伴隨著偶爾紙張翻動的嘩啦聲迴盪在神殿中，時不時還夾雜著一些疲累的嘆氣聲。"
  },
  AvgDialog_71794_Content_93 = {
    Text = "凡苦難的，吾主將償還。凡虔誠的，吾主將眷顧。凡祈求的，吾主將恩賜。凡期願的，吾主將應許……"
  },
  AvgDialog_71794_Content_94 = {
    Text = "諾亞苦哈哈的臉旁邊是比其他人高上一摞的紙張，只要向一旁圖魯身前薄薄一層的紙張看去就可以發現緣由——那是他拍著胸脯從圖魯手中搶去的。"
  },
  AvgDialog_71794_Content_95 = {
    Text = "你是被我硬拉來的，於情於理，我都得替你分擔。"
  },
  AvgDialog_71794_Content_96 = {
    Text = "沒搶過他的圖魯只好沉默著從身上掏出了幾塊堅果糖酥似的零食，冷淡地塞進了諾亞的手裡。"
  },
  AvgDialog_71794_Content_97 = {
    Text = "這兩天分餐時攢下來的，我不愛吃。"
  },
  AvgDialog_71794_Content_98 = {
    Text = "阿瑪蘭特酥？！胡魯，你中吼……"
  },
  AvgDialog_71794_Content_99 = {
    Text = "諾亞鼓著腮幫，眼淚汪汪地搖晃著圖魯的手。"
  },
  AvgDialog_71986_Content_1 = {
    Text = "寧靜。彷彿永恆不滅的黑暗與寧靜。"
  },
  AvgDialog_71986_Content_10 = {
    Text = "流光的幻景在眼前破碎，映入眼簾的少女緊抿雙唇，雙眼被眼罩牢牢遮覆。"
  },
  AvgDialog_71986_Content_12 = {
    Text = "在最後的時刻，她將身體交給了我。"
  },
  AvgDialog_71986_Content_13 = {
    Text = "面對毀滅的回溯，我已經不知道經歷了多少次……"
  },
  AvgDialog_71986_Content_14 = {
    Text = "她走上前來，用纖細的雙手蒙上你的眼。"
  },
  AvgDialog_71986_Content_15 = {
    Text = "將你的一縷意識交給我。"
  },
  AvgDialog_71986_Content_16 = {
    Text = "就像夜幕落下，萬物墜入黑暗……"
  },
  AvgDialog_71986_Content_17 = {
    Text = "然後太陽昇起，一切恢復到最初的原點。"
  },
  AvgDialog_71986_Content_18 = {
    Text = "這裡是你的意識，他們的一切都源於你。"
  },
  AvgDialog_71986_Content_19 = {
    Text = "他們的記憶中不會留存這段毀滅的記錄，但我知道你不會遺忘。"
  },
  AvgDialog_71986_Content_2 = {
    Text = "在那無限的寧靜之中，一枚小小的白色光點悄然凝聚，在眼前遊移漂浮。"
  },
  AvgDialog_71986_Content_20 = {
    Text = "珍惜這點滴的時光吧。"
  },
  AvgDialog_71986_Content_21 = {
    Text = "在註定降臨的毀滅再次到來之前。"
  },
  AvgDialog_71986_Content_3 = {
    Text = "很遺憾，在本次對抗融蝕的旅途中……我們付出瞭如此慘痛的代價。"
  },
  AvgDialog_71986_Content_4 = {
    Text = "以你為代價……"
  },
  AvgDialog_71986_Content_5 = {
    Text = "但我無法忍受，目睹你陷入那門扉之內，永世的孤獨。"
  },
  AvgDialog_71986_Content_6 = {
    Text = "清冷的女聲。足夠熟悉，但又有些不一樣。"
  },
  AvgDialog_71986_Content_7 = {
    Text = "睜開眼吧。"
  },
  AvgDialog_71986_Content_8 = {
    Text = "我會還給你……一個世界。"
  },
  AvgDialog_71987_Content_1 = {
    Text = "人間食糧"
  },
  AvgDialog_71987_Content_11 = {
    Text = "誰在那邊？"
  },
  AvgDialog_71987_Content_13 = {
    Text = "通常來說，我會負責教堂入夜前最後一輪巡查。看到二位不在床位上，我就四處看看，不是故意要偷聽你們聊天的……"
  },
  AvgDialog_71987_Content_14 = {
    Text = "沒關係的，奧吉爾，你也過來吧。"
  },
  AvgDialog_71987_Content_16 = {
    Text = "奧吉爾笨拙地沿著木階登上平臺，小心地不讓腳下發出聲響，以免驚擾眾人的睡眠。"
  },
  AvgDialog_71987_Content_17 = {
    Text = "回到剛才的問題。"
  },
  AvgDialog_71987_Content_18 = {
    Text = "我認真思考過這個問題：我們當前目睹的一切慘劇是否源自我的手筆？"
  },
  AvgDialog_71987_Content_2 = {
    Text = "他們幾個已經睡下了嗎？"
  },
  AvgDialog_71987_Content_20 = {
    Text = "乾脆、簡潔，以俐落的死亡為目的，相當符合我的審美。"
  },
  AvgDialog_71987_Content_21 = {
    Text = "但異樣之處同樣存在——我不喜歡延時類裝置，那種等待與折磨是我所不能容納的酷刑。"
  },
  AvgDialog_71987_Content_22 = {
    Text = "既然這段時間內我都在與各位共同行動，那便無暇去發射名為死亡通知的按鈕。"
  },
  AvgDialog_71987_Content_24 = {
    Text = "為什麼？"
  },
  AvgDialog_71987_Content_25 = {
    Text = "剛才聽到你們的聊天的時候，我一直在擔心朵爾小姐是這一切的主使者。"
  },
  AvgDialog_71987_Content_26 = {
    Text = "那樣的話，我就不得不挺身而出，也就不得不和朵爾小姐成為敵人了。"
  },
  AvgDialog_71987_Content_27 = {
    Text = "現在，知道幕後黑手另有其人，我就不用提心吊膽，可以把朵爾小姐當成夥伴了！"
  },
  AvgDialog_71987_Content_28 = {
    Text = "奧吉爾收起了剛才悄悄背在身後的長槍，笑容真摯而燦爛。"
  },
  AvgDialog_71987_Content_3 = {
    Text = "嗯，他們應該好好休息。"
  },
  AvgDialog_71987_Content_30 = {
    Text = "哼，我也不在乎什麼夥伴不夥伴的。"
  },
  AvgDialog_71987_Content_31 = {
    Text = "不會的，朵爾。"
  },
  AvgDialog_71987_Content_32 = {
    Text = "雖然我對這個世界中本源化的你一無所知，但我對身為教授的朵爾……可太熟悉了。"
  },
  AvgDialog_71987_Content_33 = {
    Text = "不如請你告訴我，你所認識的那個「朵爾」，是個怎樣的人？"
  },
  AvgDialog_71987_Content_35 = {
    Text = "在界域教學課堂上第一次見到的冷面的教授。"
  },
  AvgDialog_71987_Content_36 = {
    Text = "在授鑰儀式上，將銀鑰匙鄭重交付在你手中的朵爾。"
  },
  AvgDialog_71987_Content_37 = {
    Text = "總是毒舌你的論文和大腦，但最後會為你解決好一切後顧之憂的朵爾。"
  },
  AvgDialog_71987_Content_38 = {
    Text = "在拉伊療養院時獨自面對赫伯特，為你們開闢出一條生路的朵爾。"
  },
  AvgDialog_71987_Content_39 = {
    Text = "……還有最後，毅然斬斷和你的連結的朵爾。"
  },
  AvgDialog_71987_Content_4 = {
    Text = "你白天從融蝕的夢境中窺探到的……"
  },
  AvgDialog_71987_Content_40 = {
    Text = "往事一一浮現，原來在不知不覺中，你們已經陪伴在彼此身邊，經歷了那麼、那麼多故事。"
  },
  AvgDialog_71987_Content_41 = {
    Text = "你將你所知道的關於朵爾的一切向她傾囊而出。"
  },
  AvgDialog_71987_Content_44 = {
    Text = "雖然嘴上說得不好聽，但你內心還挺尊重她的，對吧？"
  },
  AvgDialog_71987_Content_45 = {
    Text = "讓我猜猜，這就是你至今仍然沒有對我動手的原因，是不是？"
  },
  AvgDialog_71987_Content_46 = {
    Text = "我失去了記憶，但你可沒有。\n你有很多機會，在我還沒有意識到你的身分的時候攻我不備，但你什麼都沒做。"
  },
  AvgDialog_71987_Content_47 = {
    Text = "看來你的導師還是沒有告訴你，應該如何對待可能的敵人。"
  },
  AvgDialog_71987_Content_48 = {
    Text = "在恰當的時機，或許我會出手。"
  },
  AvgDialog_71987_Content_49 = {
    Text = "但不是現在。"
  },
  AvgDialog_71987_Content_5 = {
    Text = "是這個行將就木的世界。"
  },
  AvgDialog_71987_Content_50 = {
    Text = "愚蠢的小狗……遲早有一天，你要為你的心軟付出代價。"
  },
  AvgDialog_71987_Content_53 = {
    Text = "一聲淒厲的尖叫劃破夜空。"
  },
  AvgDialog_71987_Content_54 = {
    Text = "怎麼了？！"
  },
  AvgDialog_71987_Content_55 = {
    Text = "視線的盡頭，梅森的身影狼狽地奔來。她扭曲的手臂焦躁不安地撕扯著亂髮，語無倫次地對你們發出渾濁的呼喊。"
  },
  AvgDialog_71987_Content_56 = {
    Text = "莎拉……快去看看莎拉女士……\n她的頭……她的頭！！"
  },
  AvgDialog_71987_Content_6 = {
    Text = "因為死亡將要來臨了，所有生靈用本能相互依偎、相互擁抱、相互融合。"
  },
  AvgDialog_71987_Content_7 = {
    Text = "朵爾……在我的世界裡，你引發了洪水、山崩、融蝕擴散等種種災難。"
  },
  AvgDialog_71987_Content_8 = {
    Text = "這裡的一切，是你造成的嗎？"
  },
  AvgDialog_71989_Content_1 = {
    Text = "有毒的蘋果"
  },
  AvgDialog_71989_Content_11 = {
    Text = "長久的沉默在你們之間久久迴蕩。你感覺自己喉嚨發梗，不知如何接話。"
  },
  AvgDialog_71989_Content_13 = {
    Text = "與「彌薩格大學」最接近的，是另一所高等學府，同樣以異種生物為主要研究對象。"
  },
  AvgDialog_71989_Content_14 = {
    Text = "只是他們的研究更加古樸和正統，調查員的工作內容以考古研究、實地勘察和神秘學文書編撰為主，戰鬥人員規模遠不如彌薩格大學。"
  },
  AvgDialog_71989_Content_15 = {
    Text = "這所高等學府……名為「密斯卡託尼克大學」。"
  },
  AvgDialog_71989_Content_16 = {
    Text = "沒有守密人，沒有銀芯，這個世界的「密斯卡託尼克大學」自然不具備招募朵爾的基礎。"
  },
  AvgDialog_71989_Content_17 = {
    Text = "可惜，我並不記得詹金所說那次湮滅，只怕在那之後的全部記憶，都因為爆炸而遺失了。"
  },
  AvgDialog_71989_Content_18 = {
    Text = "至於你想要回到原本的世界……我倒是有些想法。"
  },
  AvgDialog_71989_Content_19 = {
    Text = "達芙黛爾夫人曾經告訴你，這裡並非託乎瓦波的夢境，那麼知曉當前世界的真相多半有助於建構與其他維度世界的聯繫。"
  },
  AvgDialog_71989_Content_2 = {
    Text = "你獨自在天台呼吸著新鮮的夜間空氣。"
  },
  AvgDialog_71989_Content_20 = {
    Text = "這是一條更漫長的路，並且多半有效——畢竟失憶前的我曾經順利轉移至多個維度，而我和我的思路應當能保持一致。"
  },
  AvgDialog_71989_Content_21 = {
    Text = "至於捷徑，等我想想清楚再告訴你吧……"
  },
  AvgDialog_71989_Content_22 = {
    Text = "不過，還有一件事是你能需要考慮清楚的。"
  },
  AvgDialog_71989_Content_23 = {
    Text = "搜查濟貧院這件事，與你返回原世界毫無關聯。"
  },
  AvgDialog_71989_Content_24 = {
    Text = "現在的你，將精力投在這些無關緊要的事情上。等到那一天，你當真能放下這裡的一切，心無旁騖地回到過去的生活中嗎？"
  },
  AvgDialog_71989_Content_25 = {
    Text = "你可以慢慢思考這個問題。現在，有更關鍵的事情需要面對。\n你看那邊——"
  },
  AvgDialog_71989_Content_26 = {
    Text = "黑暗中冒出星點移動的光，細細簌簌地掠過夜色。"
  },
  AvgDialog_71989_Content_27 = {
    Text = "是融蝕異構體！"
  },
  AvgDialog_71989_Content_28 = {
    Text = "白日裡被你驅逐的融蝕異構體，成群結隊地蜂擁而來，他們焦躁不安地亂擠亂竄，竟至於相互攀扯和撕咬。"
  },
  AvgDialog_71989_Content_29 = {
    Text = "他們的目標……非常明確，就是鐘樓。"
  },
  AvgDialog_71989_Content_3 = {
    Text = "儘管荒蕪的城市被煙塵籠罩，高處天台上卻依然能夠看到閃爍的清亮星星，為你帶來短暫的慰藉。"
  },
  AvgDialog_71989_Content_30 = {
    Text = "他們是衝我們來的。"
  },
  AvgDialog_71989_Content_31 = {Text = "迎戰！"},
  AvgDialog_71989_Content_4 = {
    Text = "熔燬·朵爾……這個世界的你，為什麼沒有選擇加入彌薩格大學？"
  },
  AvgDialog_71989_Content_5 = {
    Text = "你對這個世界存在誤解，愚蠢的小東西。"
  },
  AvgDialog_71989_Content_6 = {
    Text = "星光落在朵爾的球形關節上，反射出非人型的金屬異色。"
  },
  AvgDialog_71989_Content_7 = {
    Text = "你以為不同維度之間的差別僅在於融蝕的表徵和個體的經歷嗎？那可就大錯特錯了。"
  },
  AvgDialog_71989_Content_8 = {
    Text = "就我所知，這個維度中，根本不存在所謂的「彌薩格大學」。"
  },
  AvgDialog_71990_Content_10 = {
    Text = "醒醒，醒醒，兩個懶鬼。"
  },
  AvgDialog_71990_Content_11 = {
    Text = "姐姐讓我叫你們去莎拉阿姨那裡。"
  },
  AvgDialog_71990_Content_12 = {
    Text = "你們踏入教堂後的隔間，梅森在病床前正照料著安靜熟睡的莎拉，昏黃的壁爐火光為她的臉頰鍍上一層暖意。"
  },
  AvgDialog_71990_Content_13 = {
    Text = "薩爾瓦多主祭站在窗旁，靜靜眺望著窗外的景色，彷彿一座沉默的雕像。"
  },
  AvgDialog_71990_Content_14 = {
    Text = "夢境中的莎拉發出痛楚的囈語，你們正要走近，梅森將手指抵在唇邊輕輕地說了句「噓」，然後拿起一塊白布手帕擦拭。"
  },
  AvgDialog_71990_Content_15 = {
    Text = "請各位跟我來吧。"
  },
  AvgDialog_71990_Content_16 = {
    Text = "那位莎拉女士的病，比我想像中更為複雜。"
  },
  AvgDialog_71990_Content_17 = {
    Text = "找不出原因嗎？"
  },
  AvgDialog_71990_Content_18 = {
    Text = "不，恰恰相反，我已經有些眉目。\n只是……"
  },
  AvgDialog_71990_Content_19 = {
    Text = "我相信你們對「喚醒體」形成的原理都很熟悉，所以我就不詳細講解了。"
  },
  AvgDialog_71990_Content_2 = {
    Text = "海在呼喚你。"
  },
  AvgDialog_71990_Content_20 = {
    Text = "這位莎拉女士體內的高位意志能量，與維持她靈魂的高位意志處於激烈的衝突之中。"
  },
  AvgDialog_71990_Content_21 = {
    Text = "如果剝離莎拉女士頭部植入的銀芯，她的意識會隨之消亡；如果不憑依來自夢境的力量，她的身體會和其他人一樣化作灰燼。"
  },
  AvgDialog_71990_Content_22 = {
    Text = "不幸的是，我確實無法以父神的力量治癒她。\n無論哪份高位意志最終勝出......莎拉女士的生命都很難維持。"
  },
  AvgDialog_71990_Content_23 = {
    Text = "我聽懂了，她必死無疑。"
  },
  AvgDialog_71990_Content_24 = {
    Text = "要麼放棄生命，要麼在痛苦中活下去……沒有第三種選擇嗎？"
  },
  AvgDialog_71990_Content_25 = {
    Text = "薩爾瓦多搖頭，略顯凌亂的白髮擦過主教袍，發出簌簌聲響。"
  },
  AvgDialog_71990_Content_26 = {
    Text = "熔燬·朵爾望向你，眼底透露出不合時宜的勝利笑意，彷彿在耀武揚威地說“你看，我說的對吧？”"
  },
  AvgDialog_71990_Content_28 = {
    Text = "猛烈的咳嗽聲自幽暗處傳來，莎拉飽受苦痛折磨的臉上，銀白色裂痕又猙獰了幾分。"
  },
  AvgDialog_71990_Content_29 = {
    Text = "我聽見了……是%player%……%heorshe%在這裡嗎？"
  },
  AvgDialog_71990_Content_3 = {
    Text = "那是暗色的大海，在群星的照耀下交錯反射著幽暗的黃綠色光芒。"
  },
  AvgDialog_71990_Content_30 = {
    Text = "她是……在叫我嗎？"
  },
  AvgDialog_71990_Content_31 = {
    Text = "還能是誰？我們這裡還有別人叫%player%嗎？"
  },
  AvgDialog_71990_Content_32 = {
    Text = "你湊近莎拉的床前，梅森將莎拉扶坐起。\n莎拉大口大口喘著粗氣，許久才勉強穩住身體，抬頭向你露出一個勉強的微笑。"
  },
  AvgDialog_71990_Content_33 = {
    Text = "這位好心人……能拜託你一件事情嗎？"
  },
  AvgDialog_71990_Content_34 = {
    Text = "您請說。"
  },
  AvgDialog_71990_Content_35 = {
    Text = "我能聽出來，你是一個見多識廣的人。"
  },
  AvgDialog_71990_Content_36 = {
    Text = "既然如此，能請你將這些首飾想辦法交給羅傑斯先生，用來充抵小艾繼絲獨立前的生活費用嗎？"
  },
  AvgDialog_71990_Content_37 = {
    Text = "我知道，我自己多半是見不到她長大的一天了……羅傑斯先生慷慨大方，或許也不缺這一星半點。"
  },
  AvgDialog_71990_Content_38 = {
    Text = "但有了這些首飾，她至少不算是完全的寄人籬下……那孩子從小被她的母親拋棄，我想讓她知道，莎拉姐姐沒有拋棄她……"
  },
  AvgDialog_71990_Content_39 = {
    Text = "然後，再告訴她，等她長大了，每年記得給提尤格和小威利的墳墓前送一束花……那些孩子還那麼小，一定會很怕寂寞的。"
  },
  AvgDialog_71990_Content_4 = {
    Text = "那是深眠者黯淡無光的長夢，黑星高懸的黑暗與寂靜。"
  },
  AvgDialog_71990_Content_41 = {
    Text = "放心吧，我不會輕易放棄的。在那天到來之前，我都會掙扎著活下去。\n哪怕還有一線希望……我還想再見那些孩子一面。"
  },
  AvgDialog_71990_Content_42 = {
    Text = "在荒無人煙的倫敦街頭，你長長出了一口氣。\n即使遍佈煙塵的道路，也不及盤旋在莎拉身邊的空氣陰沉。"
  },
  AvgDialog_71990_Content_43 = {
    Text = "熔燬·朵爾走在你的身側，保持著和你相距半步的距離。"
  },
  AvgDialog_71990_Content_44 = {
    Text = "朵爾。今天的我，可以回答你的問題了。"
  },
  AvgDialog_71990_Content_45 = {
    Text = "讓我聽聽你的詭辯吧。"
  },
  AvgDialog_71990_Content_46 = {
    Text = "你知道嗎？在你的眼中，莎拉已經是將死之人了。她對這個世界的留戀本應毫無意義。"
  },
  AvgDialog_71990_Content_47 = {
    Text = "但是事實並非如此。她仍舊惦記著那些被帶走的孩子。"
  },
  AvgDialog_71990_Content_48 = {
    Text = "這就是平凡的人類，和平凡的人類的牽掛。"
  },
  AvgDialog_71990_Content_49 = {
    Text = "你所催化的終結和死亡，不過是剝奪他們最後一絲希望罷了。"
  },
  AvgDialog_71990_Content_5 = {
    Text = "絞纏、衝突、扭曲、撕扯、掙扎，觸肢與觸肢彼此纏繞和鬥爭。"
  },
  AvgDialog_71990_Content_50 = {
    Text = "但希望只是飄渺的幻象，當下的苦痛才是真實的。"
  },
  AvgDialog_71990_Content_51 = {
    Text = "哪怕是在幻象中活下去，很多人還是願意為了希望忍受眼下的痛苦。"
  },
  AvgDialog_71990_Content_52 = {
    Text = "這便是人類的韌性。"
  },
  AvgDialog_71990_Content_53 = {
    Text = "你說你不明白薩爾瓦多行動的宗旨，我卻能夠理解。"
  },
  AvgDialog_71990_Content_54 = {
    Text = "薩爾瓦多的所作所為僅僅遵循一條原則，那就是平等地讓每個人「活下去」。"
  },
  AvgDialog_71990_Content_55 = {
    Text = "在他的眼中，生命並非權衡，也不是數字，他眼裡看見的是一個又一個的渴求生存的人。"
  },
  AvgDialog_71990_Content_56 = {
    Text = "只要「活下去」，就有未來，就有可能性。"
  },
  AvgDialog_71990_Content_57 = {
    Text = "「可能性」嗎？……"
  },
  AvgDialog_71990_Content_58 = {
    Text = "熔燬·朵爾沉思片刻，隨後彷彿想起什麼似的，發出一聲冷哼。"
  },
  AvgDialog_71990_Content_6 = {
    Text = "一方嘯叫著：我必將吞噬那美味的容器，靈感與智性的源泉，洞察與思維的載體，想像與妄念的器官。"
  },
  AvgDialog_71990_Content_60 = {
    Text = "去哪兒？"
  },
  AvgDialog_71990_Content_61 = {
    Text = "去親眼目睹……去確認一個答案。"
  },
  AvgDialog_71990_Content_62 = {
    Text = "記得叫上那只小老鼠一起，我們有讓她派上用場的時候。"
  },
  AvgDialog_71990_Content_7 = {
    Text = "另一方回應：腐朽的貪婪自當溺亡於深不見星辰的湖底。"
  },
  AvgDialog_71991_Content_10 = {
    Text = "朵爾飛起一腳，將襲來的融蝕異變體輕鬆擊飛。"
  },
  AvgDialog_71991_Content_11 = {
    Text = "少廢話，讓我無聊的話，就把你當這些東西一起消滅！"
  },
  AvgDialog_71991_Content_13 = {
    Text = "你將與熔燬·朵爾初次相遇後的遭遇一一道來，從雪崩事故後對她的回收，到她利用朵爾的義體逃離拘束，直至將你維度轉移到當前世界……"
  },
  AvgDialog_71991_Content_14 = {
    Text = "我聽懂了，所以你炸了我的實驗室，還讓我在這裡給你打白工。"
  },
  AvgDialog_71991_Content_15 = {
    Text = "不要斷章取義，在那之前是你先毀滅了我的維度，還把我囚禁在腦缸裡。"
  },
  AvgDialog_71991_Content_17 = {
    Text = "一隻頭顱開裂面孔猙獰的半融蝕異變體咕嚕一聲，噴吐出濃黑的漿液，發出令人戰慄的嘶嘶聲響。"
  },
  AvgDialog_71991_Content_18 = {
    Text = "但你所說的毀滅世界……"
  },
  AvgDialog_71991_Content_19 = {
    Text = "螯足刺穿感染融蝕的巨型野鼠的頭顱，吱呀一聲腦漿崩濺，而朵爾毫不在意地抖抖螯足將它甩下。"
  },
  AvgDialog_71991_Content_2 = {
    Text = "去找那幫西區佬嗎？別算上我。我和那些傢伙合不來的。"
  },
  AvgDialog_71991_Content_20 = {
    Text = "在我的記憶中，我毫無疑問不存在尋求世界毀滅的動機。"
  },
  AvgDialog_71991_Content_21 = {
    Text = "與之相反，我一直在探求使世界免受融蝕危機侵害的方法，並因此忙得焦頭爛額。"
  },
  AvgDialog_71991_Content_22 = {
    Text = "你覺得我在騙你？"
  },
  AvgDialog_71991_Content_23 = {
    Text = "不，我並非要否認你的說法。從你的眼神中，我能讀出你的誠實。"
  },
  AvgDialog_71991_Content_24 = {
    Text = "這當中一定存在我做出選擇的原因，只是我目前仍對此一無所知。"
  },
  AvgDialog_71991_Content_25 = {
    Text = "她的目光中透露出一絲幾不可察的茫然。"
  },
  AvgDialog_71991_Content_26 = {
    Text = "自詡天才的我，對真實偏執到放棄「米-戈」文明一切的我……"
  },
  AvgDialog_71991_Content_27 = {
    Text = "又為何會輕易倒戈向毀滅的陣營？"
  },
  AvgDialog_71991_Content_28 = {
    Text = "你敏銳地捕捉到一個獨特的關鍵字。"
  },
  AvgDialog_71991_Content_3 = {
    Text = "再說了，我得留下來保護姐姐。"
  },
  AvgDialog_71991_Content_30 = {
    Text = "在彌薩格的記錄中，你來源的文明，名為阿列麥瑟斯……"
  },
  AvgDialog_71991_Content_31 = {
    Text = "阿列麥瑟斯，飛翔的真菌……這個代稱倒也不錯。"
  },
  AvgDialog_71991_Content_32 = {
    Text = "不過，在並非卡達斯的世界中，我們無需避諱與祂的目光相連的一切。"
  },
  AvgDialog_71991_Content_33 = {
    Text = "並非卡達斯的世界……"
  },
  AvgDialog_71991_Content_34 = {
    Text = "或許你還有很多疑問，不過閒話就到此為止吧。再囉嗦下去，天黑前也到不了教堂了。"
  },
  AvgDialog_71991_Content_4 = {
    Text = "有那個粉色大腦袋保護你就足夠了吧？"
  },
  AvgDialog_71991_Content_6 = {
    Text = "總之，最後只有我們兩個人負責突圍任務了。"
  },
  AvgDialog_71991_Content_7 = {
    Text = "目標是清除鐘樓下的融蝕異變體，前往西區的濟世大聖堂，請求薩爾瓦多的支援。"
  },
  AvgDialog_71991_Content_8 = {
    Text = "趁此機會，把我失憶之前所有你知道的事情，一五一十地告訴我。"
  },
  AvgDialog_71991_Content_9 = {
    Text = "你把這個環境叫「趁此機會」，是不是有點太輕描淡寫了？！"
  },
  AvgDialog_71992_Content_10 = {
    Text = "她也不會將實驗資料交給我。"
  },
  AvgDialog_71992_Content_100 = {
    Text = "你點按胸針，一聲輕響，傳來通訊接通的聲音。"
  },
  AvgDialog_71992_Content_101 = {
    Text = "喂喂，連結穩定嗎？"
  },
  AvgDialog_71992_Content_102 = {
    Text = "熔燬·朵爾，你……"
  },
  AvgDialog_71992_Content_104 = {
    Text = "為了讓你這可憐的淋雨小狗不至於太過孤單，之後的旅程裡需要支持的時候，你可以通過這個通訊器聯絡我。"
  },
  AvgDialog_71992_Content_106 = {
    Text = "這一次……毀滅是你的夥伴。"
  },
  AvgDialog_71992_Content_12 = {
    Text = "你記不記得，我在最初的時候，並沒有提供這條返回實驗室的「捷徑」給你？"
  },
  AvgDialog_71992_Content_13 = {
    Text = "因為選擇捷徑，就必須付出選擇捷徑的代價。"
  },
  AvgDialog_71992_Content_14 = {
    Text = "只要確認了這條「捷徑」，我就必然踏上應循的道路，不得不變回追求毀滅的自己。"
  },
  AvgDialog_71992_Content_15 = {
    Text = "和「自己」的對抗……如今聽來依然很愚蠢，愚蠢得根本不符合孤注一擲的「天才」的名號。"
  },
  AvgDialog_71992_Content_16 = {
    Text = "但如果，我先讀過了這份報告，或許就不能那麼堅定地站在你的身邊了。"
  },
  AvgDialog_71992_Content_17 = {
    Text = "總之，這份手稿交給你。"
  },
  AvgDialog_71992_Content_18 = {
    Text = "評估好自己的精神狀態再進行閱讀吧。"
  },
  AvgDialog_71992_Content_19 = {
    Text = "你鎮定心神，展開那份邊緣泛黃的手稿。"
  },
  AvgDialog_71992_Content_20 = {
    Text = "《託乎瓦波的目光協同性運動研究》"
  },
  AvgDialog_71992_Content_21 = {
    Text = "實驗目的：\n通過定量和定性的方式，觀察和記錄託乎瓦波對視野中高靈性目標的反應，驗證它們的目光追蹤移動的高靈性目標的規律。\n本實驗旨在揭示託乎瓦波的視覺特徵及其對特定靈性目標的反應機制。"
  },
  AvgDialog_71992_Content_22 = {
    Text = "實驗背景：\n根據歷史文獻及往期實驗記錄（見《融蝕現象的成因探究》）託乎瓦波的目光能夠造成融蝕現象，但託乎瓦波捕捉目標的原理尚未解明。\n研究託乎瓦波的目光協同性運動原理，可以幫助我們更好地尋求當前世界的存續方式。"
  },
  AvgDialog_71992_Content_23 = {
    Text = "實驗材料：\n1.7種強度的靈性材料各1份；\n2.維度穿越器材及燃料9份；\n3.實驗資料記錄表"
  },
  AvgDialog_71992_Content_24 = {
    Text = "實驗方法：\n1、設定實驗環境：篩選靈性數值波動相對穩定且接近的維度；\n2、實驗程序：\n①輪流向各維度投放不同靈性數值的實驗材料。\n②潛入當地融蝕對抗組織，通常為彌薩格大學，獲取各維度的融蝕爆發頻率資料。\n③以低靈性銀芯為載體將資料傳輸至279號義體。\n④整理資料並進行分析。"
  },
  AvgDialog_71992_Content_26 = {
    Text = "第二份報告中，輪流向各維度投放的實驗材料變成了啟動七個人工義體同時進行投放。"
  },
  AvgDialog_71992_Content_27 = {
    Text = "第三份報告中，攜帶的靈性材料數值設定發生了變化。"
  },
  AvgDialog_71992_Content_29 = {
    Text = "最後的手稿，字跡變得異常凌亂。"
  },
  AvgDialog_71992_Content_3 = {
    Text = "我檢索了目前所有留存的筆記，很遺憾地告訴你兩件事。\n首先，B-68所說的那塊石板已經不知所蹤了。"
  },
  AvgDialog_71992_Content_30 = {
    Text = "沒有意義。\n我在探究的是毫無意義的結果。\n靈性生物本身就是祂的捕捉目標，諾斯指數大於21的生物就會招致祂的注視，並波及周遭的其他存在。\n這份報告的流出最終只會導致更恐怖的結局：諾斯指數的測定、篩選、誘捕和追殺。"
  },
  AvgDialog_71992_Content_31 = {
    Text = "更可怕的是，能夠檢測出諾斯指數的並非只有人類——諸多海洋生物整個種群的諾斯指數都高於21。\n除非核平全部海域……但那同樣是無人生還的結局。"
  },
  AvgDialog_71992_Content_32 = {
    Text = "一切解法都是虛妄，祂的目光永恆誕臨。"
  },
  AvgDialog_71992_Content_33 = {
    Text = "沒有人能夠得到拯救。"
  },
  AvgDialog_71992_Content_34 = {
    Text = "你們短暫的存續既非你個人犧牲的結果，也不是他一時的開恩，僅僅只是因為他對自己的碎片產生了一絲可有可無的好奇罷了。"
  },
  AvgDialog_71992_Content_35 = {
    Text = "他屏息凝神，去看一眼自己的碎片，在那個刹那忘記了呼吸……"
  },
  AvgDialog_71992_Content_36 = {
    Text = "你們就以為危機結束了，故事完結了，王子和公主過上幸福的生活了。"
  },
  AvgDialog_71992_Content_38 = {
    Text = "你根本不明白我知道了什麼！這一切都是——"
  },
  AvgDialog_71992_Content_39 = {
    Text = "你從實驗報告的閱讀中驚醒，發覺自己已經冷汗涔涔。"
  },
  AvgDialog_71992_Content_4 = {
    Text = "其次，雖然我發現了當時的我跳躍至你的維度所用的方法，但它並不能通用於你。"
  },
  AvgDialog_71992_Content_40 = {
    Text = "在你面前狂妄不可一世的熔燬·朵爾，曾經也只是彌薩格一名謹小慎微的研究員。"
  },
  AvgDialog_71992_Content_41 = {
    Text = "只是她比你所在的世界更早窺視到融蝕的秘密，以及無解的殘酷真相。"
  },
  AvgDialog_71992_Content_42 = {
    Text = "你壯烈的犧牲並不能換來世界的長治久安。"
  },
  AvgDialog_71992_Content_43 = {
    Text = "你們的戰鬥還沒有結束，必須讓彌薩格、讓拉蒙娜知曉這一事實——"
  },
  AvgDialog_71992_Content_44 = {
    Text = "你必須回去。"
  },
  AvgDialog_71992_Content_45 = {
    Text = "送別日，霏霏細雨。"
  },
  AvgDialog_71992_Content_46 = {
    Text = "你人生的關鍵時刻似乎總是有如絲雨幕作陪。"
  },
  AvgDialog_71992_Content_47 = {
    Text = "在阿庫特睜開眼睛的那天也好，授鑰儀式那天也好，決意成為門扉的守護者那天也好……"
  },
  AvgDialog_71992_Content_48 = {
    Text = "每個風平浪靜的雨夜，你都會擔憂你的人生是否會突如其來地迎來新的轉折點。"
  },
  AvgDialog_71992_Content_49 = {
    Text = "你回憶起與熔燬·朵爾的告別。"
  },
  AvgDialog_71992_Content_5 = {
    Text = "簡單來說，義體之間的高度相似性讓意識的轉移得以成為可能，但在那個世界已經不存在足夠契合你的軀體。"
  },
  AvgDialog_71992_Content_50 = {
    Text = "我會留在實驗室中。停下不會是答案，或許有一天我會重複同樣的瘋狂。"
  },
  AvgDialog_71992_Content_51 = {
    Text = "但，在抵達絕對的真理之前，即便毗鄰毀滅的污染，我也必須孤注一擲地繼續我的研究。"
  },
  AvgDialog_71992_Content_52 = {
    Text = "這才像是我認識的朵爾……\n不，還是有些不一樣的。"
  },
  AvgDialog_71992_Content_53 = {
    Text = "你們擁有著表面截然不同，內核卻完全一致的偏執。"
  },
  AvgDialog_71992_Content_54 = {
    Text = "但至少，現在的她，不會像之前那麼狂躁和恐怖了。"
  },
  AvgDialog_71992_Content_55 = {
    Text = "這枚胸針，她讓我交給你。我給你別上吧。"
  },
  AvgDialog_71992_Content_56 = {
    Text = "溫柯爾將一枚胸針扣在你的胸口。"
  },
  AvgDialog_71992_Content_57 = {
    Text = "溫柯爾……這一路而來，你幫助了我很多。而我甚至還沒來得及跟你說一聲謝謝。"
  },
  AvgDialog_71992_Content_58 = {
    Text = "謝謝你，溫柯爾。謝謝你成為我在這裡的第一個朋友。"
  },
  AvgDialog_71992_Content_59 = {
    Text = "不用這麼客氣，我已經從朵爾口中聽說了很多有關你的事情。在我無法與你對話的時候，你也已經認識另一個我了，不是嗎？"
  },
  AvgDialog_71992_Content_6 = {
    Text = "還有一種方式是通過腦缸和再造軀體，但這需要你的意識的頻譜資料，相應實驗報告已經遺失了。"
  },
  AvgDialog_71992_Content_60 = {
    Text = "雖然我還是很恐懼……\n但冥冥中有個聲音告訴我，你會給我、給這個世界帶來光的。"
  },
  AvgDialog_71992_Content_61 = {
    Text = "看那邊，送行的隊伍來了。"
  },
  AvgDialog_71992_Content_63 = {
    Text = "不去，我不去感謝那傢伙！\n那傢伙是我從碎石堆裡挖出來的，我救了%heorshe%的命才對！"
  },
  AvgDialog_71992_Content_64 = {
    Text = "聽話，詹金。"
  },
  AvgDialog_71992_Content_65 = {
    Text = "謝謝您幫助我的妹妹……抱歉的是，我和詹金沒有多少“所有物”。\n這條緞帶，就由我轉贈您作為紀念吧。"
  },
  AvgDialog_71992_Content_66 = {
    Text = "她將一枚殷紅的絲綢緞帶系在你的手腕上。"
  },
  AvgDialog_71992_Content_69 = {
    Text = "不必推辭，我知道您和朵爾女士為聖堂提供了大量銀芯資源，足夠讓薩爾瓦多主教再支撐很長很長時間。"
  },
  AvgDialog_71992_Content_7 = {
    Text = "還有辦法找回嗎？"
  },
  AvgDialog_71992_Content_70 = {
    Text = "我能看見你靈魂的光輝，如同蒼白的搖焰，雖然尚不穩固，但明亮而溫暖。"
  },
  AvgDialog_71992_Content_71 = {
    Text = "薩爾瓦多主祭……如果我找到能解決危機的方式，一定會第一時間趕來聖堂。"
  },
  AvgDialog_71992_Content_72 = {
    Text = "我相信你，蒼白的使者。有朝一日，你必將為聖堂中遭受苦難之人帶來救贖與希望。"
  },
  AvgDialog_71992_Content_74 = {
    Text = "辭別眾人，你深深呼吸了一口清涼的雨絲。\n街巷的一角，余光中陡然閃現的身影攫住了你的注意。"
  },
  AvgDialog_71992_Content_76 = {
    Text = "那邊那位先生，請等一下！"
  },
  AvgDialog_71992_Content_77 = {
    Text = "那衣袍一抖，金髮男人彷彿在躲避你的追隨，竟加快了腳步。"
  },
  AvgDialog_71992_Content_78 = {
    Text = "……威廉，是你嗎……威廉！"
  },
  AvgDialog_71992_Content_79 = {
    Text = "你來不及多想，腳步從快走加速至疾奔，一個又一個街區的側影接連從眼前掠過。"
  },
  AvgDialog_71992_Content_8 = {
    Text = "有，但同樣有著不可接受的風險——我必須冒險將自己的思維與完整版本的熔燬·朵爾同調。"
  },
  AvgDialog_71992_Content_83 = {
    Text = "稀薄的氧氣不足以供給肺部缺氧的需求，你大口喘息著，血流的湧動讓大腦恢復了些許思考能力。"
  },
  AvgDialog_71992_Content_84 = {
    Text = "……天什麼時候黑了下去？"
  },
  AvgDialog_71992_Content_85 = {
    Text = "南華克大街……44號……"
  },
  AvgDialog_71992_Content_86 = {
    Text = "上一次，在這個時刻，你身邊是你最重要的搭檔。"
  },
  AvgDialog_71992_Content_87 = {
    Text = "南華克大街就在西區。\n看來這次，我們可以親眼見證名牌調查員威廉的風采了。"
  },
  AvgDialog_71992_Content_88 = {
    Text = "他都出動了嗎……"
  },
  AvgDialog_71992_Content_89 = {
    Text = "但如今，你身側空無一人。"
  },
  AvgDialog_71992_Content_9 = {
    Text = "換句話說，我會變成那個與你為敵的本源存在。"
  },
  AvgDialog_71992_Content_90 = {
    Text = "這就是與融蝕對抗的旅程。"
  },
  AvgDialog_71992_Content_92 = {
    Text = "我們要去拯救，去改變。\n但，即使最終什麼也沒能實現……"
  },
  AvgDialog_71992_Content_93 = {
    Text = "在那個萬物都被遺忘的深夜來臨之前，也請你用你的雙眼去見證、去記憶發生過的一切。"
  },
  AvgDialog_71992_Content_94 = {
    Text = "我會做到的。\n拉蒙娜，等我回去。"
  },
  AvgDialog_71992_Content_95 = {
    Text = "從回憶中汲取了支撐內心的力量後，你已經準備好直面這一路孤身一人的旅途。"
  },
  AvgDialog_71992_Content_96 = {
    Text = "前進吧。"
  },
  AvgDialog_71992_Content_97 = {
    Text = "願銀鑰指引前路。"
  },
  AvgDialog_71992_Content_99 = {
    Text = "熔燬·朵爾製作、溫柯爾為你在胸口別上的胸針突然鳴響起來。"
  },
  AvgDialog_71993_Content_10 = {
    Text = "……父神，請賜予那些罹難者安寧與解脫，撫慰他們受苦的靈魂。"
  },
  AvgDialog_71993_Content_11 = {
    Text = "願您的醫治之手降臨在受苦者身上，願您存在的光芒驅散抓住我們靈魂的恐懼黑暗。"
  },
  AvgDialog_71993_Content_13 = {
    Text = "你的身體都快透明了。"
  },
  AvgDialog_71993_Content_14 = {
    Text = "於麗埃特……父神會包容所有人的罪惡，但在你為執行異端儀式顯露哪怕半分悔悟之心之前，在聖堂現身恐怕並非恰當之舉。"
  },
  AvgDialog_71993_Content_15 = {
    Text = "終究沒能看清現實嗎？無論是「賜福」還是「庇佑」，你所做的一切只不過是在燃燒自己。"
  },
  AvgDialog_71993_Content_16 = {
    Text = "你的父神既不能讓你的雙眼重見光明，也不能治癒你身上的頑疾。"
  },
  AvgDialog_71993_Content_17 = {
    Text = "再堅持下去，你會比現在教堂裡看似虛弱的那些人先倒下。"
  },
  AvgDialog_71993_Content_18 = {
    Text = "跟我一起離開這裡吧，我會找到治癒你的方法。"
  },
  AvgDialog_71993_Content_19 = {
    Text = "若我離開聖堂，這裡的所有病人都會被吞噬。神不會忍心見它的子民遭此劫難。"
  },
  AvgDialog_71993_Content_2 = {
    Text = "濟世大聖堂前"
  },
  AvgDialog_71993_Content_20 = {
    Text = "即便再苟延殘喘十天半月，在你靈性不支後，他們同樣只能自尋出路。"
  },
  AvgDialog_71993_Content_21 = {
    Text = "而其中大半……恕我直言，連他們的房間都走不出去。"
  },
  AvgDialog_71993_Content_22 = {
    Text = "於麗埃特狂熱的瞳孔凝視著薩爾瓦多，見他手撫教袍沉默不語，她露出因過分燦爛而顯得虛假的笑意。"
  },
  AvgDialog_71993_Content_23 = {
    Text = "索性將這裡定為新的亂葬崗也不錯，葬身於神的懷抱中，未嘗不是一種虔誠的回歸呢？"
  },
  AvgDialog_71993_Content_24 = {
    Text = "睜開眼看看吧，整座城市已經傾覆，你的所作所為不過是杯水車薪罷了。"
  },
  AvgDialog_71993_Content_25 = {
    Text = "父神給予每一個人平等的機會，他們每多活一天，就存在更大的等到施救者的可能性。"
  },
  AvgDialog_71993_Content_26 = {
    Text = "蒼白的使者仍未降臨於世，那世間的救贖就尚存在轉機。"
  },
  AvgDialog_71993_Content_27 = {
    Text = "別開玩笑了，尊敬的主教大人！<Yellow:《聖典》>書寫的不過是荒誕的謊言罷了！"
  },
  AvgDialog_71993_Content_28 = {
    Text = "終焉已經降臨，沒有人能拯救這個世界！"
  },
  AvgDialog_71993_Content_29 = {
    Text = "若你依然執迷不悟，我就不得不採取強硬手段了。"
  },
  AvgDialog_71993_Content_3 = {
    Text = "你確信這裡就是你要找的避難所？"
  },
  AvgDialog_71993_Content_30 = {
    Text = "自教堂的花窗，自長椅之下，自門扉之後，悄然浮現數個高大的提燈教眾的身姿。"
  },
  AvgDialog_71993_Content_31 = {
    Text = "薩爾瓦多主教！！"
  },
  AvgDialog_71993_Content_32 = {
    Text = "少年的身影闖入聖堂的大門，身後跟隨著兩個被日光拉長的身影，正緩慢觀察著環境行進。"
  },
  AvgDialog_71993_Content_33 = {
    Text = "在那對峙之中，你的目光穿過提燈教眾，對上薩爾瓦多。\n門扉的光將他的面龐鍍上一層柔和神聖的光，你感覺他繃帶下的目光正與你觸碰。"
  },
  AvgDialog_71993_Content_34 = {
    Text = "他低頭，唇角揚起微不可查的弧度，抬手觸碰心臟的位置，低沉的祈禱聲帶著一絲慈悲與溫暖。"
  },
  AvgDialog_71993_Content_35 = {
    Text = "“將有無邊的黑暗降臨世界，那個靈魂蒼白溫暖的即為希望的使者，%heorshe%將燃起白色的火焰，照亮前進的方向。”"
  },
  AvgDialog_71993_Content_36 = {
    Text = "我已感知到你靈魂的溫度……蒼白的使者。"
  },
  AvgDialog_71993_Content_38 = {
    Text = "我還以為我們是來尋求幫助的。不會是讓我路見不平拔刀相助吧？"
  },
  AvgDialog_71993_Content_39 = {
    Text = "於麗埃特……"
  },
  AvgDialog_71993_Content_4 = {
    Text = "這裡的境況，與濟貧院鐘樓，不說一模一樣，至少是非常相似……"
  },
  AvgDialog_71993_Content_40 = {
    Text = "哦？你認識我？"
  },
  AvgDialog_71993_Content_41 = {
    Text = "我沒見過你的臉。但看起來，這裡沒有讓我們坐下來互相自我介紹的餘裕了。"
  },
  AvgDialog_71993_Content_42 = {
    Text = "不……她不是可以交涉的對象……準備作戰吧。"
  },
  AvgDialog_71993_Content_43 = {
    Text = "看來你還很了解我的作風。既然如此，我倒是有興趣探問一下你的資訊的來源了。"
  },
  AvgDialog_71993_Content_5 = {
    Text = "大量的融蝕異變體包圍了整座教堂……"
  },
  AvgDialog_71993_Content_6 = {
    Text = "等等，前面那個是……"
  },
  AvgDialog_71993_Content_7 = {
    Text = "讓開！不得阻擋騎士的道路！"
  },
  AvgDialog_71993_Content_8 = {
    Text = "小小的身影張開黑色的護盾，朝你們而來。"
  },
  AvgDialog_71993_Content_9 = {
    Text = "你們！是倖存者嗎？快跟我進來！"
  },
  AvgDialog_71994_Content_1 = {
    Text = "意識空間徹底潰散了，幻象的煙塵簌簌而落，浮現在你們面前的仍是最初的實驗室。"
  },
  AvgDialog_71994_Content_2 = {
    Text = "為什麼不願意接納呢？能夠葬身在維度的罅隙之中，永遠不必承受「祂」的目光的洗禮。"
  },
  AvgDialog_71994_Content_3 = {
    Text = "這是怎樣的榮幸，怎樣的恩賜啊！"
  },
  AvgDialog_71994_Content_4 = {
    Text = "可惜，可惜，現在只能由我親自動手……讓這業已湮滅的冰冷城市……"
  },
  AvgDialog_71994_Content_5 = {
    Text = "成為你們的葬身之所！"
  },
  AvgDialog_71995_Content_1 = {
    Text = "混沌的空間伴隨扭曲的輪廓，霎時間吞噬了整座實驗室。"
  },
  AvgDialog_71995_Content_2 = {
    Text = "失控的光影在你們面前展開，被黑色淹沒而不可辨識的獸群將你們二人包圍。"
  },
  AvgDialog_71995_Content_3 = {
    Text = "歡迎來到我的實驗田，我的屠宰場。"
  },
  AvgDialog_71995_Content_4 = {
    Text = "上吧，親愛的孩子們。給這些不知好歹的傢伙們一個教訓。"
  },
  AvgDialog_71996_Content_10 = {
    Text = "毫無疑問，是我的實驗室。"
  },
  AvgDialog_71996_Content_11 = {
    Text = "還記得嗎？我曾經告訴你，我們可以走「捷徑」。"
  },
  AvgDialog_71996_Content_12 = {
    Text = "那條捷徑，便是「竊取」。"
  },
  AvgDialog_71996_Content_13 = {Text = "竊取？"},
  AvgDialog_71996_Content_14 = {
    Text = "竊取。\n竊取「我」的研究成果。"
  },
  AvgDialog_71996_Content_15 = {
    Text = "我不知道你引發的那場爆炸究竟是什麼規模，但我有慎重儲存關鍵研究成果的習慣。"
  },
  AvgDialog_71996_Content_16 = {
    Text = "只要這只小老鼠鑽牆翻找的能力達到攻無不克的境地，就能從廢墟中挖掘出記錄，從而大幅縮短我的後續研究週期。"
  },
  AvgDialog_71996_Content_17 = {
    Text = "好了，少廢話，掃清前往實驗室廢墟的障礙吧。"
  },
  AvgDialog_71996_Content_2 = {
    Text = "喂，西區佬，一大早的把我從美夢中拖出來，你們這是要把我帶到哪兒去？"
  },
  AvgDialog_71996_Content_3 = {
    Text = "我可睡得正香呢，夢見自己變成了一隻小老鼠，走在獨木橋上，周圍都是油脂甜甜的香氣，很快鼻尖就要碰到最美味的芝士了——"
  },
  AvgDialog_71996_Content_4 = {
    Text = "哐啷一聲，被你這傢伙用枕頭砸醒了。"
  },
  AvgDialog_71996_Content_5 = {
    Text = "幸虧把你叫醒了。你夢到的那個是最常見的高效捕鼠陷阱之一。"
  },
  AvgDialog_71996_Content_6 = {
    Text = "獨木橋的下方是高度超過一米的水箱，你聞到的香氣是塗抹在透明的容器和腳下的獨木橋上的。"
  },
  AvgDialog_71996_Content_7 = {
    Text = "只要你一踩上，就會腳底打滑墜入萬劫不復的深淵。"
  },
  AvgDialog_71996_Content_8 = {
    Text = "要想做只自由自在的老鼠，你還得再聰明點。"
  },
  AvgDialog_71996_Content_9 = {
    Text = "朵爾，我們此行的目的地是……？"
  },
  AvgDialog_71997_Content_1 = {
    Text = "融蝕異變體悲鳴著消失的瞬間，剛才與你並肩作戰的四人回眸向你微笑。"
  },
  AvgDialog_71997_Content_10 = {
    Text = "可以是可以，但跨越維度的聯繫足夠壓垮你這具軀體。\n非必要時刻，我不建議你這麼做。"
  },
  AvgDialog_71997_Content_11 = {
    Text = "你嘗試再去聚焦回想，腦海中尚未凝聚出輪廓，思維的齒輪就已經故障停滯。"
  },
  AvgDialog_71997_Content_12 = {
    Text = "你的眼皮沉重如鉛塊，窒息感如厚重的霧霾籠罩在心頭。"
  },
  AvgDialog_71997_Content_13 = {
    Text = "跟我回實驗室去吧，治治你身上的傷。\n要是朵爾發現了，我就說都是我幹的。"
  },
  AvgDialog_71997_Content_14 = {
    Text = "朵爾她、雖然，但我能感覺到，她本質上是個純粹的人，轉移技術也很精湛……比這個星球上大部分的人厲害多了。"
  },
  AvgDialog_71997_Content_15 = {
    Text = "你回憶了在原本世界中熔燬·朵爾的所作所為，很難表示贊同。"
  },
  AvgDialog_71997_Content_16 = {
    Text = "但和溫柯爾爭辯熔燬·朵爾的對錯當前並無意義，更關鍵的事情是了解這個世界究竟發生了什麼，以及如何返回原本的世界。"
  },
  AvgDialog_71997_Content_17 = {
    Text = "我們……回去吧？外面真的很不安全……"
  },
  AvgDialog_71997_Content_18 = {
    Text = "她拽著你的衣角的手正悄悄用力。"
  },
  AvgDialog_71997_Content_19 = {
    Text = "你看了看遠方天空中昏黑的太陽，在煙塵中勉強暈出環狀輪廓，如同裸露的枯槁眼瞳。"
  },
  AvgDialog_71997_Content_2 = {
    Text = "然後身影逐漸淡去。"
  },
  AvgDialog_71997_Content_20 = {
    Text = "我跟你回去。我有問題要問問朵爾。"
  },
  AvgDialog_71997_Content_3 = {
    Text = "下個瞬間，湊在你面前的是溫柯爾焦急的臉。"
  },
  AvgDialog_71997_Content_5 = {
    Text = "不，不要到處亂跑……外面、很危險的。"
  },
  AvgDialog_71997_Content_6 = {
    Text = "你環顧四周，確認身影已經徹底消失不見，而戰鬥的疲勞度與之前相比更甚。"
  },
  AvgDialog_71997_Content_7 = {
    Text = "他們……"
  },
  AvgDialog_71997_Content_8 = {
    Text = "是來自你的意識空間的投影。不過據朵爾所說，你的意識空間裡本就包含了所有維度世界。"
  },
  AvgDialog_71997_Content_9 = {
    Text = "還能再見到他們嗎？"
  },
  AvgDialog_71998_Content_2 = {
    Text = "天搖地動，手邊的實驗台上接連滾落玻璃燒瓶和試管，在地面上蒸騰起迷幻色彩的煙霧。"
  },
  AvgDialog_71998_Content_3 = {
    Text = "隨後實驗臺與試劑架接連倒塌，連掛在牆面上的鐘擺和飾物也搖搖欲墜。"
  },
  AvgDialog_71998_Content_5 = {
    Text = "這個據點也撐不住了嗎？"
  },
  AvgDialog_71998_Content_6 = {
    Text = "看來我要和彌薩格的小狗一起被埋在這裡了。高興嗎，把尾巴搖起來吧，這可是你難得尊享的殊榮。"
  },
  AvgDialog_71998_Content_7 = {
    Text = "在你回應之前，世界陷入一片坍塌的漆黑。"
  },
  AvgDialog_71999_Content_1 = {
    Text = "未選擇的路"
  },
  AvgDialog_71999_Content_10 = {
    Text = "取決於你這段時間在做些什麼了。"
  },
  AvgDialog_71999_Content_11 = {
    Text = "在做些什麼？當然是繼續你的偉業，我們的偉業，催化終結的偉業！"
  },
  AvgDialog_71999_Content_12 = {
    Text = "來吧，親愛的，與我分享喜悅吧！\n在你離開期間，我已經為整整六個維度的卡達斯送去了終焉！"
  },
  AvgDialog_71999_Content_13 = {
    Text = "你和身邊的朵爾對望一眼。"
  },
  AvgDialog_71999_Content_14 = {
    Text = "看來我們是做不了朋友了。"
  },
  AvgDialog_71999_Content_15 = {
    Text = "遺憾，遺憾啊！連我自己都無法再理解自我的願望！"
  },
  AvgDialog_71999_Content_16 = {
    Text = "剛才仍在歌劇舞臺忘情演出的她猝然停步，灼熱的目光似要刺穿你和身側的熔燬·朵爾。"
  },
  AvgDialog_71999_Content_17 = {
    Text = "想必，你已經忘記石板上的一切了吧？"
  },
  AvgDialog_71999_Content_18 = {
    Text = "你們的無言正是對狂妄之人提問的作答。"
  },
  AvgDialog_71999_Content_19 = {
    Text = "果然，果然！那便正好，就當作是一次預演，為終將揭幕的熔燬末路！"
  },
  AvgDialog_71999_Content_2 = {
    Text = "「我」的義體的重啟模式是，一旦任何一枚義體與中央大腦失去聯繫超過24小時，就會自動啟動下一具備用義體。"
  },
  AvgDialog_71999_Content_20 = {
    Text = "你知道嗎？我的內心燃燒著一種渴望。"
  },
  AvgDialog_71999_Content_21 = {
    Text = "我渴望將石板傳授於我的一切告知世人，我渴望讓他們知曉自己所求所追逐的荒誕。"
  },
  AvgDialog_71999_Content_22 = {
    Text = "無人知曉自己因何得到一切，也無人關注世界註定的命運。"
  },
  AvgDialog_71999_Content_23 = {
    Text = "世界的毀滅近在咫尺，每個人的生命都可能在明天終結，他們的存在將被漆黑吞噬，而庸碌之人居然視而不見聽而不聞！"
  },
  AvgDialog_71999_Content_24 = {
    Text = "而我看見了！我看見了！"
  },
  AvgDialog_71999_Content_25 = {
    Text = "她的神色愈發癲狂，粗壯的螯足砸在地面上，擊穿木製地板的瘮人踩踏聲令人毛骨悚然。"
  },
  AvgDialog_71999_Content_26 = {
    Text = "所以，以死亡的形式，我將同等的荒誕賜予麻木的庸人，賜予他們醒覺的特權。"
  },
  AvgDialog_71999_Content_27 = {
    Text = "我授予他們足以抵抗火焰和電力的裝甲，然後用尖銳鋒利的螯足將他們胸膛刺穿；"
  },
  AvgDialog_71999_Content_28 = {
    Text = "我將數以千計的地震採礦機隨意贈予路人，貪婪之人爭奪開採領域，共振誘發的地震竟比我親手引爆的更多。"
  },
  AvgDialog_71999_Content_29 = {
    Text = "我將你們這些吠叫的傢伙裝入大腦收容筒，讓你們只能枯坐著目睹噩夢的降臨。"
  },
  AvgDialog_71999_Content_3 = {
    Text = "因此，在實驗室事故後，我陷入昏迷，新的義體B-68已經啟動。\n而這具損失了部分記憶的軀體，是一枚本應投入垃圾站的廢棄品。"
  },
  AvgDialog_71999_Content_30 = {
    Text = "這便是「我」的選擇嗎？"
  },
  AvgDialog_71999_Content_31 = {
    Text = "真是孱弱啊。本以為連結本源的存在能夠通曉更多智慧，沒想到科學的陷阱竟將你引向了荒誕的末路。"
  },
  AvgDialog_71999_Content_32 = {
    Text = "你知道生物裝甲的價值嗎？無論是火焰還是電力都無法擊穿，穿著它足夠我們邁入岩漿層探索地底的奧秘。"
  },
  AvgDialog_71999_Content_33 = {
    Text = "地震採礦機……可以深入地層，並通過高速震盪挖掘和分離銀芯。"
  },
  AvgDialog_71999_Content_34 = {
    Text = "至於大腦收容筒……那是用來保存一些無價的大腦與其中容納的知識和思考的，並非任性妄為隨意收容渣滓的產物。"
  },
  AvgDialog_71999_Content_35 = {
    Text = "將他們僅作樂趣之用，簡直和那個叫N的傢伙一樣，無知且暴殄天物。"
  },
  AvgDialog_71999_Content_36 = {
    Text = "你陷在另一種瘋狂裡太久了，另一個「我」。"
  },
  AvgDialog_71999_Content_37 = {
    Text = "人類本就在求索中開闢通往未來的道路，你卻武斷地斬斷了所有可能性和希望。"
  },
  AvgDialog_71999_Content_39 = {
    Text = "所有答案都被永恆的黑色淹沒，所有相似或不同的維度只會走向唯一的結局！"
  },
  AvgDialog_71999_Content_4 = {
    Text = "換句話說，我們面前的「熔燬·朵爾」才是更完整的「我」。"
  },
  AvgDialog_71999_Content_40 = {
    Text = "%player%。希望只會是讓人更加痛苦的毒藥。只有在徹底、迅速的毀滅中，所有人才能獲得真正的解脫。"
  },
  AvgDialog_71999_Content_41 = {
    Text = "閃著寒光的螯足高高舉起，下一秒就要刺穿你的頭顱。"
  },
  AvgDialog_71999_Content_42 = {
    Text = "既然你不願意放棄那粗陋的希望……"
  },
  AvgDialog_71999_Content_43 = {
    Text = "那就準備迎接我賜予你們的完美高效的死亡吧！"
  },
  AvgDialog_71999_Content_5 = {
    Text = "你很聰明，不愧是「我」，B-67號。"
  },
  AvgDialog_71999_Content_6 = {
    Text = "已經報廢的贗品帶著這只逃跑的小狗一同回到這具實驗室，總不會是來找我敘舊的吧？"
  },
  AvgDialog_71999_Content_7 = {
    Text = "如果我說我的編號在你之前，所以這座實驗室應該歸我所有，你肯定不會承認。"
  },
  AvgDialog_71999_Content_8 = {
    Text = "但我們之間未必不能達成和談。"
  },
  AvgDialog_71999_Content_9 = {
    Text = "那麼，你要來加入我嗎？"
  },
  AvgDialog_72000_Content_1 = {
    Text = "你這傢伙果然有問題，怎麼一言不合就動手啊！"
  },
  AvgDialog_72000_Content_10 = {
    Text = "她和姐姐一樣，被那個帶著古怪人偶的有錢少爺帶去治病了。"
  },
  AvgDialog_72000_Content_11 = {
    Text = "我也告訴克萊門汀小姐了，但克萊門汀小姐說，少爺把她送去什麼高端療養了，暫時還回不來。"
  },
  AvgDialog_72000_Content_12 = {
    Text = "那麼……莎拉小姐，還有戴安娜呢？"
  },
  AvgDialog_72000_Content_13 = {
    Text = "不知道。濟貧院裡全是怪物，沒人敢靠近。"
  },
  AvgDialog_72000_Content_14 = {
    Text = "是的，我從西區被克萊門汀小姐帶回來的時候發現，東區的怪物比西區要多上許多……"
  },
  AvgDialog_72000_Content_15 = {
    Text = "濟貧院內更是。"
  },
  AvgDialog_72000_Content_16 = {
    Text = "你的眼前浮現出那二人的身影。佝僂著腰，帶著殷勤的笑意的莎拉；膽怯的，不敢吐露心聲的艾繼絲。"
  },
  AvgDialog_72000_Content_17 = {
    Text = "明天一早，我去搜查濟貧院。"
  },
  AvgDialog_72000_Content_2 = {
    Text = "梅森能感覺到，二位都是好人……能不要互相為難了嗎？"
  },
  AvgDialog_72000_Content_3 = {
    Text = "不，看來這二位是不能容我在這裡安身了……"
  },
  AvgDialog_72000_Content_4 = {
    Text = "既然如此，我還是先出去避避風頭吧。"
  },
  AvgDialog_72000_Content_5 = {
    Text = "她嘴上說著離去，卻倏然湊到你的近前，呢喃耳語。"
  },
  AvgDialog_72000_Content_6 = {
    Text = "還會再見的，無目之瞳。"
  },
  AvgDialog_72000_Content_7 = {
    Text = "（既然雕塑家協會和羅傑斯的情況與之前一致，那麼……）"
  },
  AvgDialog_72000_Content_8 = {
    Text = "詹金，你知道艾繼絲在哪兒嗎？"
  },
  AvgDialog_72000_Content_9 = {
    Text = "你還認識艾繼絲？"
  },
  AvgDialog_72001_Content_11 = {
    Text = "你推開了門。"
  },
  AvgDialog_72001_Content_12 = {
    Text = "出現在你面前的是熟悉的地下室，但沒有糖人，沒有雕塑家，也沒有實驗臺。"
  },
  AvgDialog_72001_Content_13 = {
    Text = "有的只是一個蓬頭垢面、骨瘦如柴的女人。"
  },
  AvgDialog_72001_Content_14 = {
    Text = "……誰……"
  },
  AvgDialog_72001_Content_15 = {
    Text = "沙啞的、虛弱的聲音，像是忍受著劇烈的疼痛。\n枯瘦的手指在地面竭力攀行，拖拽著無力的身軀向你們湊近。"
  },
  AvgDialog_72001_Content_16 = {
    Text = "是……人類嗎……"
  },
  AvgDialog_72001_Content_18 = {
    Text = "慢些喝，水還有很多，沒關係的。"
  },
  AvgDialog_72001_Content_2 = {
    Text = "你把那些怪物全部幹掉了？"
  },
  AvgDialog_72001_Content_21 = {
    Text = "算不清了……無論如何，應該超過二十天。"
  },
  AvgDialog_72001_Content_22 = {
    Text = "有時候，我會聽到一種古怪的囈語聲，頭會疼痛得無法忍受，甚至感覺它要從內部裂開來……"
  },
  AvgDialog_72001_Content_23 = {
    Text = "醒來的時候，已經不知道昏迷了多久……"
  },
  AvgDialog_72001_Content_24 = {
    Text = "沒有食物，也沒有水……我總覺得自己馬上就要死去了。\n但是，一想到孩子們還在等著我……"
  },
  AvgDialog_72001_Content_25 = {
    Text = "超過二十天不吃不喝還能活下來，你不會覺得自己是靠著對孩子們的愛活下來的吧？"
  },
  AvgDialog_72001_Content_26 = {
    Text = "你在陰陽怪氣些什麼！"
  },
  AvgDialog_72001_Content_27 = {
    Text = "恕我直言，朋友們，你們應該意識到……"
  },
  AvgDialog_72001_Content_28 = {
    Text = "你們眼前的這位莎拉女士，早就已經不是普通的人類了……她是個半成品喚醒體。"
  },
  AvgDialog_72001_Content_29 = {
    Text = "是的，她的諾斯指數反復震盪，不能維持在21以上。\n原理尚不明確，但顯然並非穩定的喚醒體。"
  },
  AvgDialog_72001_Content_3 = {
    Text = "從今往後，你在濟貧院裡就可以行動自如了。"
  },
  AvgDialog_72001_Content_30 = {
    Text = "並且，顯而易見的，她的身體很快就要扛不住內側銀芯的震盪了。"
  },
  AvgDialog_72001_Content_31 = {
    Text = "很遺憾，但她恐怕見不到她的孩子們了。"
  },
  AvgDialog_72001_Content_32 = {
    Text = "熔燬·朵爾的笑意像一塊沉重的巨石，牢牢地壓在了你們的胸口。\n沒有人接話，沉默在濟貧院的空氣中抽出一塊綿長的空洞。"
  },
  AvgDialog_72001_Content_4 = {
    Text = "如果在外面發現了受傷的人，就讓他們在這裡休息吧。"
  },
  AvgDialog_72001_Content_5 = {
    Text = "我去地下室看看。\n你先別過來。"
  },
  AvgDialog_72001_Content_6 = {
    Text = "你站在地下室的門前，深吸了一口氣。"
  },
  AvgDialog_72001_Content_7 = {
    Text = "往昔的回憶在你的眼前膠片軸般滾動閃現。"
  },
  AvgDialog_72002_Content_1 = {
    Text = "壓住她！"
  },
  AvgDialog_72002_Content_10 = {
    Text = "她給予的建議是發自肺腑、真誠可靠的。"
  },
  AvgDialog_72002_Content_11 = {
    Text = "於麗埃特小姐是真的擔心您的身體，您也真的不能再使用「賜福」了！"
  },
  AvgDialog_72002_Content_12 = {
    Text = "人群的中央，莎拉抱著頭蜷縮在地，身體因強行忍耐劇烈的痛楚而止不住顫抖，指節已經勒到泛白。"
  },
  AvgDialog_72002_Content_13 = {
    Text = "索菲亞挺身攔在微微佝僂的薩爾瓦多之前，用虛弱的身軀將他和莎拉強行隔絕開來。"
  },
  AvgDialog_72002_Content_14 = {
    Text = "索菲亞，請讓開道路吧。"
  },
  AvgDialog_72002_Content_15 = {
    Text = "她既然來到此處請求我的幫助，那父神的輝光便會為她驅散苦難的陰翳。"
  },
  AvgDialog_72002_Content_16 = {
    Text = "消瘦的身影伏於莎拉的病榻前，淡藍色的紋路逐漸將嚎哭的女人擁入懷抱，女人漸漸停止了痛苦，在藍光的籠罩中嬰孩般安然睡去。"
  },
  AvgDialog_72002_Content_17 = {
    Text = "薩爾瓦多猛烈咳嗽，嘴角滑落一絲殷紅的血痕。他不動聲色地將它擦去。"
  },
  AvgDialog_72002_Content_18 = {
    Text = "您看看您！我現在就扶您去休息！"
  },
  AvgDialog_72002_Content_19 = {
    Text = "目送著二人遠去的背影，熔燬·朵爾嗆出一聲冷笑。"
  },
  AvgDialog_72002_Content_2 = {
    Text = "莎拉頭部的銀芯逐漸黯淡下去，但仍爆發著超乎常人的巨力，猛烈掙扎著，眼中透露出瘋狂的光芒。"
  },
  AvgDialog_72002_Content_20 = {
    Text = "朵爾你……在笑什麼？"
  },
  AvgDialog_72002_Content_21 = {
    Text = "笑那位神父，當然。"
  },
  AvgDialog_72002_Content_22 = {
    Text = "他的邏輯難道不可笑麼？\n他早該放棄這個爛攤子了。"
  },
  AvgDialog_72002_Content_23 = {
    Text = "若保下他一人，往後能救的人或許更多。"
  },
  AvgDialog_72002_Content_24 = {
    Text = "但他寧可讓自己燈枯油盡，也要維繫這座教堂內部不受侵蝕，保護那些孱弱無力的待宰羔羊。"
  },
  AvgDialog_72002_Content_25 = {
    Text = "非要用「人多大於人少」的理論來支持他的想法，如今他的所作所為卻又背離了曾經的決策。"
  },
  AvgDialog_72002_Content_26 = {
    Text = "救治一人，卻減損教堂內所有人的生存機會，人類「聖人」的思考邏輯，實在缺乏理性的根基。"
  },
  AvgDialog_72002_Content_27 = {
    Text = "如果是你，你會怎麼處理，朵爾？"
  },
  AvgDialog_72002_Content_28 = {
    Text = "在不被接納的世界中苟延殘喘，等待或許永遠不會降臨的解脫之日。"
  },
  AvgDialog_72002_Content_29 = {
    Text = "我會終結他們的痛苦，終結所有人的痛苦。"
  },
  AvgDialog_72002_Content_3 = {
    Text = "幾名身材高大的護工模樣的人左右逼近，將她強行用麻繩捆縛在床邊。"
  },
  AvgDialog_72002_Content_4 = {
    Text = "請各位不必如此，將一切交給我吧。父神會治癒她因苦痛而迷惘的靈魂。"
  },
  AvgDialog_72002_Content_5 = {
    Text = "薩爾瓦多拉起臂上的衣袍，深淺不一、觸目驚心的疤痕大大小小地佈滿了他那堅韌而蒼老的手臂。"
  },
  AvgDialog_72002_Content_6 = {
    Text = "他劃開自己的手腕，滴滴鮮血淌在教堂地面，逐漸蜿蜒成法陣樣式的紋路。"
  },
  AvgDialog_72002_Content_7 = {
    Text = "薩爾瓦多閣下！！"
  },
  AvgDialog_72002_Content_8 = {
    Text = "一名少女從人群中衝出，用白色繃帶束上了薩爾瓦多腕上的傷口。"
  },
  AvgDialog_72002_Content_9 = {
    Text = "主教閣下，我不知道您眼中的於麗埃特小姐是怎樣惡貫滿盈之人，但我能看得清人真實的欲望。"
  },
  AvgDialog_72003_Content_1 = {
    Text = "不行，數量太多了，這麼下去，憑我們幾個根本攔不住，鐘樓要被攻陷了！"
  },
  AvgDialog_72003_Content_10 = {
    Text = "那個女人。"
  },
  AvgDialog_72003_Content_11 = {
    Text = "怪物是衝著那個女人來的！"
  },
  AvgDialog_72003_Content_12 = {
    Text = "你聽見苦悶的哭嚎聲自鐘樓內傳來，嘶啞的、破碎的、飽經摧殘的，在嚎叫聲灌入耳道的瞬間你彷彿置身駭異的絕境，足以令人神經錯亂。"
  },
  AvgDialog_72003_Content_13 = {
    Text = "當時，莎拉因愧疚而頭部爆裂之前，也曾爆發出這樣的吼聲——"
  },
  AvgDialog_72003_Content_15 = {
    Text = "你闖入室內，修女的身影蜷縮在陰影之中。"
  },
  AvgDialog_72003_Content_16 = {
    Text = "她跪伏於地，驚恐地緊抱住自己的肩膀，自顱頂到下頜綻開一條細長的血線，血線中不斷滴落的殷紅讓她整個人分外猙獰可怖。"
  },
  AvgDialog_72003_Content_17 = {
    Text = "你猶豫了。"
  },
  AvgDialog_72003_Content_18 = {
    Text = "眼前即將失控的人還是莎拉嗎？你該以對待怪物還是對待人類的方式應對她呢？"
  },
  AvgDialog_72003_Content_19 = {
    Text = "連這點銀芯的力量都不能容納，感到痛苦也是理所應當的。"
  },
  AvgDialog_72003_Content_2 = {
    Text = "一個嬌小的身影飛快地向你們躥來，額角的髮絲凌亂，顯然是剛從睡夢中驚醒。"
  },
  AvgDialog_72003_Content_20 = {
    Text = "熔燬·朵爾毫無芥蒂地來到莎拉面前，伸手輕撫莎拉額角的閃光，隨後掏出一小瓶製劑，塗抹在皮膚開裂處隱隱露出的白骨上。"
  },
  AvgDialog_72003_Content_21 = {
    Text = "那枚銀芯的光澤逐漸黯淡下去。"
  },
  AvgDialog_72003_Content_22 = {
    Text = "只能暫時壓制，無論任由病程發展還是強行拔出銀芯，她的軀體都無法承受。"
  },
  AvgDialog_72003_Content_23 = {
    Text = "你們或許認識什麼擅長淨化的存在嗎？"
  },
  AvgDialog_72003_Content_27 = {
    Text = "遙遠的過去，喧囂的人潮中。\n薩爾瓦多抬起手，血液從他身上、從他四周源源不斷地流向石板。"
  },
  AvgDialog_72003_Content_28 = {
    Text = "藍光再次沿著紋路流轉，一明一暗，宛如呼吸。"
  },
  AvgDialog_72003_Content_29 = {
    Text = "創生的父神，仁慈的造主，請聆聽我的祈求。"
  },
  AvgDialog_72003_Content_3 = {
    Text = "%player%！這到底是怎麼回事？！過去從來沒有這麼多怪物！"
  },
  AvgDialog_72003_Content_30 = {
    Text = "溫潤的藍以石板為中心向四周深處密匝的鬚根，它們穿過人群，清涼的風驅散了殘存的血腥味，留下淡淡的熏香氣息。"
  },
  AvgDialog_72003_Content_31 = {
    Text = "站著的人們緩緩坐下。"
  },
  AvgDialog_72003_Content_32 = {
    Text = "坐著的那些人張著嘴，呆呆地看著面前堪稱神蹟的一幕。"
  },
  AvgDialog_72003_Content_33 = {
    Text = "那些失去意識、甚至停止呼吸的，都在微風中緩緩睜開了眼。"
  },
  AvgDialog_72003_Content_34 = {
    Text = "請消去他們的傷痛，撫平他們的心。"
  },
  AvgDialog_72003_Content_35 = {
    Text = "人們的目光變得空茫，身體愈發放鬆。慌亂與恐懼一掃而空，取而代之的是一種舒緩和寧靜。"
  },
  AvgDialog_72003_Content_36 = {
    Text = "讓他們不再受苦難折磨，並給予他們賜福。"
  },
  AvgDialog_72003_Content_37 = {
    Text = "潮汐般的光向四周湧去，所有人都閉上了眼，像是沉浸在寧靜之中。"
  },
  AvgDialog_72003_Content_39 = {
    Text = "薩爾瓦多的治癒如此沉靜，如此沉穩，足以在激蕩的現實中構建出令人絕對安心的一隅。"
  },
  AvgDialog_72003_Content_4 = {
    Text = "你們看怪物的動作！"
  },
  AvgDialog_72003_Content_40 = {
    Text = "我不確定這個世界中是否仍存在與我所知世界一致的事物……但我希望他們存在。"
  },
  AvgDialog_72003_Content_41 = {
    Text = "濟世大聖堂的主教，薩爾瓦多。"
  },
  AvgDialog_72003_Content_42 = {
    Text = "明天一早，我們啟程突圍。"
  },
  AvgDialog_72003_Content_5 = {
    Text = "他們無神的眼瞳齊齊仰望著鐘樓，彷彿野外的狼群長嘯向血色的滿月。"
  },
  AvgDialog_72003_Content_6 = {
    Text = "鐘樓上有什麼東西吸引著他們。"
  },
  AvgDialog_72003_Content_7 = {
    Text = "你回憶起地下室走廊門口徘徊的融蝕異變體，他們同樣在渴求著什麼，因此在那裡聚集。"
  },
  AvgDialog_72003_Content_9 = {
    Text = "今天來到鐘樓的……"
  },
  AvgDialog_72004_Content_10 = {
    Text = "外面的世界好玩嗎，我的小狗？"
  },
  AvgDialog_72004_Content_11 = {
    Text = "你想要回復她的挑釁，但困倦的感覺像潮水般湧來，席卷走你所有的意志。\n被疲憊裹挾的你，在她說出下一句話之前就昏了過去。"
  },
  AvgDialog_72004_Content_12 = {
    Text = "滴滴的微弱電流聲，某人安靜的呼吸聲。"
  },
  AvgDialog_72004_Content_13 = {
    Text = "你睜開眼，只見自己躺在一張小折疊床上，溫柯爾守在你的床邊安靜地睡著了。"
  },
  AvgDialog_72004_Content_16 = {
    Text = "你還得再好好休息一會兒，注射的多比妥等鎮定類藥物會讓你的身體陷入異常疲勞。"
  },
  AvgDialog_72004_Content_17 = {
    Text = "你抬了抬胳膊，果然感覺大臂酸脹無力。"
  },
  AvgDialog_72004_Content_18 = {
    Text = "等你病養好了，我們再慢慢和朵爾商量，讓你出去轉轉好嗎？病人總是需要新鮮空氣的。"
  },
  AvgDialog_72004_Content_19 = {
    Text = "再說了，你一直沒有進食，就算補充了營養液，消化系統也需要攝入來維持健康運轉……"
  },
  AvgDialog_72004_Content_2 = {
    Text = "噠噠，噠噠。\n朵爾的螯足敲打著實驗臺的桌面。"
  },
  AvgDialog_72004_Content_21 = {
    Text = "雖然時間於你而言早已失去了意義，但你有必要掌握自己的身體狀況。"
  },
  AvgDialog_72004_Content_22 = {
    Text = "我看看……46小時15分鐘……"
  },
  AvgDialog_72004_Content_23 = {
    Text = "僅僅兩天，還在可以承受的範圍內。"
  },
  AvgDialog_72004_Content_24 = {
    Text = "想要離開嗎？很遺憾，我可不能容許。"
  },
  AvgDialog_72004_Content_25 = {
    Text = "走出這間實驗室，有太多壞人對你虎視眈眈了，小綿羊。"
  },
  AvgDialog_72004_Content_26 = {
    Text = "朵爾說得對……留在這裡……是對你的保護……"
  },
  AvgDialog_72004_Content_27 = {
    Text = "我不需要任何人的保護。"
  },
  AvgDialog_72004_Content_28 = {
    Text = "既然如此，那就讓我看看吧。"
  },
  AvgDialog_72004_Content_29 = {
    Text = "彌薩格的小狗，離開了「祂」的支持，還能有幾分本事！"
  },
  AvgDialog_72004_Content_3 = {
    Text = "說實話，我不喜歡你的提議。"
  },
  AvgDialog_72004_Content_4 = {
    Text = "正如我不喜歡你手裡的那盤黑膠——音樂不錯，但將個人作品聯合署名簡直是對創作者的侮辱，就好像把作品當成生日蛋糕來瓜分。"
  },
  AvgDialog_72004_Content_5 = {
    Text = "我承諾代你潛入彌薩格並引爆黑池，僅此而已。"
  },
  AvgDialog_72004_Content_6 = {
    Text = "%player%的意識是我從那個維度中喚醒並植入缸中之腦的，換句話說，他是我私人馴養的小狗。"
  },
  AvgDialog_72004_Content_7 = {
    Text = "現在你要分一杯羹，讓我交出祂的腦缸或共用研究成果，我只能說，我們的協議中不包含這個部分。"
  },
  AvgDialog_72004_Content_8 = {
    Text = "我要表述的內容到此為止，除非你搗毀這座實驗室並承受我必將施加於你的怒火，否則我對你的提議的回復永遠只會是「癡心妄想」。"
  },
  AvgDialog_72004_Content_9 = {
    Text = "熔燬·朵爾似乎結束了通訊，轉頭向被溫柯爾攙扶的重傷的你。"
  },
  AvgDialog_72005_Content_1 = {
    Text = "經你提醒我才意識到，這裡的某些融蝕怪物，和我所在的維度中的，似乎有所不同。"
  },
  AvgDialog_72005_Content_10 = {
    Text = "他們呼喊：\n擁抱我。"
  },
  AvgDialog_72005_Content_11 = {
    Text = "他們呼喊：\n殺死我。"
  },
  AvgDialog_72005_Content_12 = {
    Text = "他們呼喊：\n讓我成為你，讓你成為我。"
  },
  AvgDialog_72005_Content_13 = {
    Text = "讓我們微末的靈性湧作萬古的幽暗海潮，以禁忌而癲狂的姿態融合糾葛，並永不分離。"
  },
  AvgDialog_72005_Content_15 = {
    Text = "你咆哮著跪伏在地，不由自主地向前探出手。"
  },
  AvgDialog_72005_Content_16 = {Text = "誰——"},
  AvgDialog_72005_Content_17 = {
    Text = "誰來——"
  },
  AvgDialog_72005_Content_18 = {
    Text = "聽見了嗎？"
  },
  AvgDialog_72005_Content_19 = {
    Text = "必須……交融……"
  },
  AvgDialog_72005_Content_2 = {
    Text = "嗯，他們是那次毀滅來臨後才出現的。"
  },
  AvgDialog_72005_Content_20 = {
    Text = "你聽見了，和那些異變體聽見的一樣的聲音。"
  },
  AvgDialog_72005_Content_21 = {
    Text = "朵爾的聲音中唯有無機質的冰冷，與她相比，那些呼喚反而彌散著名為痛苦的溫度。"
  },
  AvgDialog_72005_Content_22 = {
    Text = "你靜下心，去捕捉它。那些銀芯中的靈性太過微弱，儀器無法檢測其波動。這是只有你能做到的事情。"
  },
  AvgDialog_72005_Content_23 = {
    Text = "來自遙遠不明之地模糊不清的手鼓聲，眼前浮現不見天日的密徑。"
  },
  AvgDialog_72005_Content_24 = {
    Text = "污穢淤泥與雕花岩石在偏光的迷瘴中變化莫測，歪曲的投影仿若不可知的鬼魅。"
  },
  AvgDialog_72005_Content_26 = {
    Text = "手鼓聲愈發急促，你低頭看去，烏黑的水面已經浸透你的腳踝，催促著你踏上前往黑暗夢境旅途。"
  },
  AvgDialog_72005_Content_27 = {
    Text = "你深呼吸，清空暈眩的頭腦，勉強維繫肢體的平衡，在黏稠的深水中輕輕抬起腳步，慢慢向前踱去……"
  },
  AvgDialog_72005_Content_28 = {
    Text = "你的口舌乾澀，似被灰燼填滿。"
  },
  AvgDialog_72005_Content_29 = {
    Text = "他們誕生於灰燼之中，相互擁抱和融合……"
  },
  AvgDialog_72005_Content_3 = {
    Text = "我曾經大量採樣並進行檢測，起初毫無頭緒，經過複雜的流程改良才得出結論。"
  },
  AvgDialog_72005_Content_30 = {
    Text = "呼吸之間，永無止境的煙塵將你深深掩埋，你竭力睜眼，和萬千生靈一道抬頭望穿這無盡的塵霾。"
  },
  AvgDialog_72005_Content_31 = {
    Text = "他們嚮往著……"
  },
  AvgDialog_72005_Content_32 = {
    Text = "遠方蒼白的天空中，高懸著一輪模糊的太陽。"
  },
  AvgDialog_72005_Content_33 = {
    Text = "懸垂於天際的黑色日輪，像一顆被遺忘的古老的瞳孔，沉默地凝視著這片盤旋噩夢、被灰霧掩埋的大地。"
  },
  AvgDialog_72005_Content_34 = {
    Text = "光線無法穿透它，反而被它吞噬。輪廓泛著的遊離波紋彷彿編織著永恆的儀式，宣告不可逆轉不可言說的終結。"
  },
  AvgDialog_72005_Content_35 = {
    Text = "已然降臨的終結。"
  },
  AvgDialog_72005_Content_4 = {
    Text = "結論是？"
  },
  AvgDialog_72005_Content_5 = {
    Text = "這些融蝕異變體中，含有來自不止一位生命體的銀芯。"
  },
  AvgDialog_72005_Content_6 = {
    Text = "通常的銀芯提煉流程不會刻意區分銀芯來歷，低靈性的銀芯作為燃料精煉時就更是如此。"
  },
  AvgDialog_72005_Content_7 = {
    Text = "你觸摸那枚銀芯，紛擾的夢境如冰冷的潮水淹溺了你。"
  },
  AvgDialog_72005_Content_8 = {
    Text = "兩隻手臂的殘肢，相互融合，絞纏。\n他們曾經如此相愛，因此將彼此交託給彼此。"
  },
  AvgDialog_72005_Content_9 = {
    Text = "交託骨血，靈肉，撕扯亂髮。\n忠於欲望，忠於渴求，忠於對分離的恐慌和痛苦。"
  },
  AvgDialog_72006_Content_1 = {
    Text = "缸中之夢"
  },
  AvgDialog_72006_Content_10 = {
    Text = "歡迎來到我的秘密基地，來自317號世界的旅行者，那位「無上意志」的一縷靈識……一只可憐的落水小狗。"
  },
  AvgDialog_72006_Content_11 = {
    Text = "告訴我，你的世界已經毀滅了嗎？"
  },
  AvgDialog_72006_Content_13 = {
    Text = "真不愧是「我」的所作所為啊。"
  },
  AvgDialog_72006_Content_14 = {
    Text = "正如你所想，你所在的世界的「我」是由這個「我」通過維度旅行能力送到你的時空中的。"
  },
  AvgDialog_72006_Content_15 = {
    Text = "作為回報，她為我送來了有趣的禮物……你的「意識」。"
  },
  AvgDialog_72006_Content_17 = {
    Text = "想見見現在的自己嗎？"
  },
  AvgDialog_72006_Content_18 = {
    Text = "她的笑意旺盛，像一盞肆意綻放的黑色大麗花。"
  },
  AvgDialog_72006_Content_19 = {
    Text = "溫柯爾，搬一面落地鏡來。"
  },
  AvgDialog_72006_Content_2 = {
    Text = "把留聲機啟動起來。書架左起第三張黑色封面的唱片。"
  },
  AvgDialog_72006_Content_20 = {
    Text = "讓我們的「客人」，好好看看自己現在的模樣……"
  },
  AvgDialog_72006_Content_21 = {
    Text = "無需眼球，用光電訊號模擬視覺神經。"
  },
  AvgDialog_72006_Content_22 = {
    Text = "無需聲帶，用機械震動和液態介質替代發聲和接收器官。"
  },
  AvgDialog_72006_Content_23 = {
    Text = "完美的思考者，缸中之腦……"
  },
  AvgDialog_72006_Content_24 = {
    Text = "這就是你啊，偉大的「無上意志」！"
  },
  AvgDialog_72006_Content_25 = {
    Text = "落地鏡中倒映出「你」的影子，彷彿剛被剝離而出的大腦透露出令人難以直視的粉紅，表面的皺褶與溝壑像極了扭曲的山脈。"
  },
  AvgDialog_72006_Content_26 = {
    Text = "營養液中細小的氣泡發出微微的湧動聲，似乎在低語著什麼不可名狀的秘密，令你本就混沌的「頭腦」陷入異常的緊繃。"
  },
  AvgDialog_72006_Content_27 = {
    Text = "熔燬·朵爾縱聲狂笑。\n溫柯爾在她的身後，緊張地咬著指甲。"
  },
  AvgDialog_72006_Content_28 = {
    Text = "我、我能離開了嗎？"
  },
  AvgDialog_72006_Content_29 = {
    Text = "不……幫我繼續實驗步驟。這是手冊。"
  },
  AvgDialog_72006_Content_3 = {
    Text = "反應爐裡再補充21mg精純銀芯。用二次提煉的，靈性磨滅得越徹底越好。"
  },
  AvgDialog_72006_Content_30 = {
    Text = "熔燬·朵爾撥停了留聲機，揚長而去，空曠的實驗室內只留溫柯爾和你面面相覷。"
  },
  AvgDialog_72006_Content_31 = {
    Text = "實驗步驟，實驗步驟……"
  },
  AvgDialog_72006_Content_32 = {
    Text = "她彷彿才反應過來朵爾的叮囑，轉過身去嘩啦啦地亂翻著朵爾留下的手記，那情狀與其說一目十行不如說半個字也沒看進去。"
  },
  AvgDialog_72006_Content_33 = {
    Text = "喂，喂。你能聽見我說話嗎？"
  },
  AvgDialog_72006_Content_34 = {
    Text = "聽不見，聽不見，我什麼也沒聽見……"
  },
  AvgDialog_72006_Content_35 = {
    Text = "你是……溫柯爾吧？"
  },
  AvgDialog_72006_Content_36 = {
    Text = "你、你怎麼會知道……"
  },
  AvgDialog_72006_Content_37 = {
    Text = "不必害怕，溫柯爾，我們曾經是共同作戰的夥伴。"
  },
  AvgDialog_72006_Content_38 = {
    Text = "你試著安撫她的情緒。神經質狀態下的溫柯爾是無法進行任何有效交流的，你內心清楚。"
  },
  AvgDialog_72006_Content_4 = {
    Text = "今天的實驗產物……就要完成了。"
  },
  AvgDialog_72006_Content_40 = {
    Text = "她咬著指甲，眼神時左時右飄忽不定，像一隻被逼退在角落裡、充滿恐懼的幼獸。"
  },
  AvgDialog_72006_Content_41 = {
    Text = "冷靜一點。能請你告訴我，我為什麼會來到這裡嗎？"
  },
  AvgDialog_72006_Content_42 = {
    Text = "這、這……"
  },
  AvgDialog_72006_Content_43 = {
    Text = "你耐心地等候著她的情緒走向平靜。\n半晌，她好像終於下定了決心。"
  },
  AvgDialog_72006_Content_44 = {
    Text = "那天，朵爾突然發來通訊……"
  },
  AvgDialog_72006_Content_45 = {
    Text = "溫柯爾，準備好接收器和備用腦缸。"
  },
  AvgDialog_72006_Content_46 = {
    Text = "我捕捉到一縷異常電信號，頻段顯示和託乎瓦波的意識接近。"
  },
  AvgDialog_72006_Content_47 = {
    Text = "那傢伙理論上已經自鎖於「門」內了，不知道這縷信號是如何保留下來的。"
  },
  AvgDialog_72006_Content_48 = {
    Text = "總之，立刻準備好接收工作！"
  },
  AvgDialog_72006_Content_49 = {
    Text = "總之，你的意識被投射到這個腦缸中，倖存了下來。"
  },
  AvgDialog_72006_Content_5 = {
    Text = "能感知到我的存在嗎？"
  },
  AvgDialog_72006_Content_50 = {
    Text = "具體的來源，或許只有朵爾知道了。"
  },
  AvgDialog_72006_Content_51 = {
    Text = "說實話，啟動你的意識讓我們不眠不休了整整一個月，朵爾估計是睡覺去了，即使是人工義體，精神也撐不住更久了。"
  },
  AvgDialog_72006_Content_52 = {
    Text = "這麼聽起來，在我轉移之前，你已經在幫朵爾完成實驗了。"
  },
  AvgDialog_72006_Content_53 = {
    Text = "你知道她在做的事情嗎？"
  },
  AvgDialog_72006_Content_54 = {
    Text = "溫柯爾緊張地一哆嗦。"
  },
  AvgDialog_72006_Content_55 = {
    Text = "我，我只是在做一些……尖端的科學研究……"
  },
  AvgDialog_72006_Content_56 = {
    Text = "關於時空跳躍、意識轉移……有助於我早日返回母星……"
  },
  AvgDialog_72006_Content_57 = {
    Text = "你歎了口氣，雖然你也不清楚歎氣的聲音能否傳達到她的耳朵裡。"
  },
  AvgDialog_72006_Content_58 = {
    Text = "辯解就已經說明你知道自己在做什麼了，溫柯爾。"
  },
  AvgDialog_72006_Content_59 = {
    Text = "溫柯爾，為了你，為了我，為了可能會被熔燬·朵爾傷害的許許多多的人。"
  },
  AvgDialog_72006_Content_60 = {
    Text = "能請你答應我一個請求嗎？"
  },
  AvgDialog_72006_Content_61 = {
    Text = "我、我可以聽聽看。"
  },
  AvgDialog_72006_Content_62 = {
    Text = "你知道怎麼讓我恢復正常行動能力嗎？"
  },
  AvgDialog_72006_Content_63 = {
    Text = "溫柯爾用力搖了搖頭。"
  },
  AvgDialog_72006_Content_64 = {
    Text = "人偶的操作技術不是我的專精，而且所有義體都被朵爾植入了封層，只有她才能操縱。"
  },
  AvgDialog_72006_Content_65 = {
    Text = "你必須另尋他法。\n或許與其他喚醒體取得聯繫，向他們求助……？"
  },
  AvgDialog_72006_Content_66 = {
    Text = "如果我沒認錯的話，你背後的那排，是熔燬·朵爾的銀芯庫吧？"
  },
  AvgDialog_72006_Content_67 = {
    Text = "裝罐、標籤、各類儀表整齊排列，與朵爾的工作習慣完全一致。"
  },
  AvgDialog_72006_Content_68 = {
    Text = "從銀芯庫中，取一枚……"
  },
  AvgDialog_72006_Content_69 = {
    Text = "你的腦海中接連浮現拉蒙娜、朵爾、奧吉爾和蘿坦的影像。"
  },
  AvgDialog_72006_Content_7 = {
    Text = "不要猶豫。用你正常的方式去「說話」就好。儀器會捕捉你發射的模擬信號，再將它轉化成聲波信號。"
  },
  AvgDialog_72006_Content_70 = {
    Text = "達芙黛爾夫人的銀芯給我。"
  },
  AvgDialog_72006_Content_71 = {
    Text = "見溫柯爾猶豫不定，你果斷增加了砝碼。"
  },
  AvgDialog_72006_Content_72 = {
    Text = "溫柯爾，現在，我連通的腦缸是這個房間裡唯一的光源。如果你連這一個小小的要求都不答應我，我會立刻熄滅自身。"
  },
  AvgDialog_72006_Content_73 = {
    Text = "你走到開關處啟動照明至少需要3秒時間，好好想想你要怎麼熬過這艱難的3秒吧。"
  },
  AvgDialog_72006_Content_74 = {
    Text = "我倒數3個數——"
  },
  AvgDialog_72006_Content_76 = {
    Text = "你試著操縱缸中的螢光液閃爍。"
  },
  AvgDialog_72006_Content_77 = {
    Text = "黑暗降臨的第一個瞬間，溫柯爾厲聲尖叫起來。"
  },
  AvgDialog_72006_Content_78 = {
    Text = "不要——我答應你，我現在就拿給你！！"
  },
  AvgDialog_72006_Content_79 = {
    Text = "她轉身在實驗臺旁的藥櫃裡東翻西找起來。數秒後，一枚纏繞著曖昧紫煙的銀芯被她盛在掌心，小心翼翼地托舉到你面前。"
  },
  AvgDialog_72006_Content_8 = {
    Text = "你嘗試著按照她的囑咐發聲。感覺不到喉舌的震動回饋，但她若有所思地露出一抹詭譎微笑。"
  },
  AvgDialog_72006_Content_81 = {
    Text = "你凝視著那枚銀色的金屬，嘗試著與之感應共鳴。\n你不確定身為缸中之腦的你能否實現……但你別無選擇，只能一試。"
  },
  AvgDialog_72006_Content_82 = {
    Text = "紫霧翻騰。"
  },
  AvgDialog_72006_Content_83 = {
    Text = "明碼標價，童叟無欺……達芙黛爾的小店能為你做些什麼呢？"
  },
  AvgDialog_72006_Content_9 = {
    Text = "你問我這是哪兒？"
  },
  AvgDialog_72007_Content_2 = {
    Text = "算啦，有超出預期的發展，我還是下次再來吧。"
  },
  AvgDialog_72007_Content_3 = {
    Text = "不過，薩爾瓦多主教，我注意到了……在剛才的戰鬥中，你一次都沒有出手，對吧？"
  },
  AvgDialog_72007_Content_4 = {
    Text = "燈燭已經搖搖欲墜，呼，微風一吹，就要熄滅了。"
  },
  AvgDialog_72007_Content_5 = {
    Text = "一條巨犬疾奔而來，扭曲的頭顱乖覺地垂下，對於麗埃特言聽計從的模樣。"
  },
  AvgDialog_72007_Content_6 = {
    Text = "於麗埃特輕盈地翻身而上，倚靠在巨犬的肩頭。"
  },
  AvgDialog_72007_Content_7 = {
    Text = "走吧，親愛的。\n保重了，薩爾瓦多主教。"
  },
  AvgDialog_72007_Content_8 = {
    Text = "那陣風……很快就要來了。"
  },
  AvgDialog_72008_Content_1 = {
    Text = "喂，教堂的老頭子，我們把病人帶來了！"
  },
  AvgDialog_72008_Content_10 = {
    Text = "當她的大腦被蠶食殆盡的時候……"
  },
  AvgDialog_72008_Content_11 = {
    Text = "薩爾瓦多神父低下頭，在胸口劃下祈禱的符文。"
  },
  AvgDialog_72008_Content_12 = {
    Text = "明天，我會嘗試剝離她體內的這股力量。"
  },
  AvgDialog_72008_Content_13 = {
    Text = "莎拉，你能不能跟我們講講，你頭上的這道疤痕是怎麼來的？"
  },
  AvgDialog_72008_Content_15 = {
    Text = "小女孩推開了單薄的床鋪，繞過身邊熟睡的孩子們，冬夜裡光著腳，搖搖晃晃地朝昏暗的庭院走去。"
  },
  AvgDialog_72008_Content_16 = {
    Text = "艾繼絲，艾繼絲……？"
  },
  AvgDialog_72008_Content_17 = {
    Text = "我追了上去，想要提醒她穿上鞋。\n但她絲毫沒有理會我。"
  },
  AvgDialog_72008_Content_18 = {
    Text = "我跟著她一直跑，一直跑，終於在濟貧院門口追上了她。"
  },
  AvgDialog_72008_Content_19 = {
    Text = "我按住她的肩膀，將她的身體扭轉過來，面對著我……"
  },
  AvgDialog_72008_Content_2 = {
    Text = "詹金搶在所有人之前衝進了濟世大聖堂。"
  },
  AvgDialog_72008_Content_20 = {
    Text = "我只看見……"
  },
  AvgDialog_72008_Content_21 = {
    Text = "一雙失神的眼睛。"
  },
  AvgDialog_72008_Content_23 = {
    Text = "就在那個時候，有誰的手輕輕地搭上了我的右肩膀。"
  },
  AvgDialog_72008_Content_24 = {
    Text = "我戰戰兢兢地回頭……"
  },
  AvgDialog_72008_Content_25 = {
    Text = "那是一個石色的、握著小刀的女人。"
  },
  AvgDialog_72008_Content_26 = {
    Text = "她的食指輕抵同樣蒼白如石膏的唇峰，悄然叮囑。"
  },
  AvgDialog_72008_Content_27 = {
    Text = "噓，不要驚擾「祂」的兒女。"
  },
  AvgDialog_72008_Content_29 = {
    Text = "在那之後的事情，我就記不清楚了。"
  },
  AvgDialog_72008_Content_3 = {
    Text = "請各位保持肅靜，聖堂之中還寄宿著許多病人，他們恐怕無力承受過分的吵鬧。"
  },
  AvgDialog_72008_Content_30 = {
    Text = "我額頭上的疤痕，本來是羅傑斯先生找醫生幫我治病時留下的。"
  },
  AvgDialog_72008_Content_31 = {
    Text = "在那天之後，就開始泛起一種銀色的金屬光澤……不過不疼也不癢，對生活也沒有影響。"
  },
  AvgDialog_72008_Content_32 = {
    Text = "難怪你能躲過那場毀滅的融災。"
  },
  AvgDialog_72008_Content_33 = {
    Text = "有人在你的體內植入了高活性的銀芯，強行將你的諾斯指數拔高至標準線以上。"
  },
  AvgDialog_72008_Content_34 = {
    Text = "和24類似，在人類體內植入或凝聚銀芯的實驗……"
  },
  AvgDialog_72008_Content_35 = {
    Text = "可惜，一切饋贈皆有代價。你如今承受的痛苦，多半也與這強行延續的壽命有關。"
  },
  AvgDialog_72008_Content_36 = {
    Text = "那位清高的聖父能不能救你於水火之中……就讓我們拭目以待了。"
  },
  AvgDialog_72008_Content_4 = {
    Text = "那個手到病除的醫生就是你嗎？\n嗯，看起來跟濟貧院那些穿白大褂的倒是不一樣。"
  },
  AvgDialog_72008_Content_5 = {
    Text = "我並非醫師，僅是「賜福者」。\n請將病人安置在事務員的房間內吧，勞煩各位跟我來。"
  },
  AvgDialog_72008_Content_6 = {
    Text = "溫和的藍光在莎拉周身流轉泛起，帶著溫暖的光澤與對生命的深切關懷。"
  },
  AvgDialog_72008_Content_7 = {
    Text = "時間一分一秒過去，薩爾瓦多掌心的微光不減，只是微微蹙眉，臉上流露出一絲不易察覺的無奈和沉重。"
  },
  AvgDialog_72008_Content_8 = {
    Text = "在這之前，我從未見過這樣的病徵。\n簡單來說，她的體內存在著一種異常的力量。"
  },
  AvgDialog_72008_Content_9 = {
    Text = "那種力量對進食大腦有著異常的欲求……她憑一己之力剋制著這種欲望，那種力量便開始以她自身的大腦為食。"
  },
  AvgDialog_72009_Content_1 = {Text = "逃脫"},
  AvgDialog_72009_Content_10 = {
    Text = "代價呢？"
  },
  AvgDialog_72009_Content_11 = {
    Text = "守密人在新世界的第一個要求，只能當成一份隆重的禮物贈送，怎麼會要求代價呢？"
  },
  AvgDialog_72009_Content_12 = {
    Text = "只不過……如果你想表示感激的話……"
  },
  AvgDialog_72009_Content_13 = {
    Text = "就將那個人的頭顱取來送給我吧。"
  },
  AvgDialog_72009_Content_14 = {
    Text = "你的意識陷入一片混沌之中。再睜開眼時，身邊是顫抖不止的溫柯爾。"
  },
  AvgDialog_72009_Content_15 = {
    Text = "你……你……突然從空洞中落下來一具身體……"
  },
  AvgDialog_72009_Content_16 = {
    Text = "怎麼離開這裡？"
  },
  AvgDialog_72009_Content_17 = {
    Text = "無視了她顫抖的碎語，你徑直髮問。"
  },
  AvgDialog_72009_Content_18 = {
    Text = "不，你不能走……如果，如果你逃走的話……朵爾她絕對、絕對會……"
  },
  AvgDialog_72009_Content_19 = {
    Text = "她的瞳孔被恐懼支配而放大，祈求的音色因絕望而顫抖。"
  },
  AvgDialog_72009_Content_2 = {
    Text = "很遺憾，我也想為你找到重新轉移回原維度的方法，但你所在的維度似乎並未與卡達斯的底層相連……"
  },
  AvgDialog_72009_Content_22 = {
    Text = "你無視了她的哀求，敲了敲朵爾離開時的鐵門，門上沒有把手或鎖鑰。"
  },
  AvgDialog_72009_Content_23 = {
    Text = "怎麼開這個門？"
  },
  AvgDialog_72009_Content_24 = {
    Text = "溫柯爾倒退幾步，緊緊貼著實驗臺。"
  },
  AvgDialog_72009_Content_26 = {
    Text = "我真的只是出去看看。朵爾那邊，交給我來處理。"
  },
  AvgDialog_72009_Content_27 = {
    Text = "開門的鑰匙或者機關就在你背後的實驗台上吧？你的遮擋動作已經暴露了這點。"
  },
  AvgDialog_72009_Content_29 = {
    Text = "朵爾無法預測你的逃脫，對缸中之腦的防範無需過度，這個出入口想必不會太隱秘。"
  },
  AvgDialog_72009_Content_3 = {
    Text = "換句話說，那裡並非託乎瓦波的萬千夢境之一。"
  },
  AvgDialog_72009_Content_30 = {
    Text = "你掃視實驗臺，目光掠過一個個令人頭疼的論文標題。"
  },
  AvgDialog_72009_Content_31 = {
    Text = "《勒姆瓦希地區融蝕現象的傳播模型》、《銀芯與融蝕擴散的遏制》、"
  },
  AvgDialog_72009_Content_32 = {
    Text = "《託乎瓦波的目光協同性運動研究》、《意識穩定方法在維度轉移中的應用》……"
  },
  AvgDialog_72009_Content_33 = {
    Text = "在實驗臺一角，你發現了一個紅色握把的簡易開關。你輕輕拉動，就傳來齒輪運轉的聲音。"
  },
  AvgDialog_72009_Content_34 = {
    Text = "哢鐺哢鐺哢鐺，銹蝕的鐵門在機械裝置的牽引下自動開啟。"
  },
  AvgDialog_72009_Content_36 = {
    Text = "你無視了她的呼喚，大步邁出鐵門——"
  },
  AvgDialog_72009_Content_37 = {
    Text = "巨大的鉛灰色霧霾，如同無形的巨獸將整座城市隱沒在內。"
  },
  AvgDialog_72009_Content_38 = {
    Text = "無數的起伏不定的樓層，如同覆蓋著堅硬皮革的尖銳手足般從霧團中露出一角。"
  },
  AvgDialog_72009_Content_4 = {
    Text = "即便是我，也不能輕易在兩個世界間進行維度穿越。"
  },
  AvgDialog_72009_Content_40 = {
    Text = "沒有人。目光所及之處一個人影也沒有。"
  },
  AvgDialog_72009_Content_41 = {
    Text = "你在街道上艱難前進。"
  },
  AvgDialog_72009_Content_42 = {
    Text = "轉過三個街區，才偶然見到濃霧中透露出的人形輪廓。"
  },
  AvgDialog_72009_Content_44 = {
    Text = "輪廓向你轉過身來，然後猝不及防地逼近，巨大扭曲的黑影猛然緊貼上你的面龐。\n腎上腺素驟然飆升，心跳響如擂鼓。"
  },
  AvgDialog_72009_Content_45 = {Text = "嘩——"},
  AvgDialog_72009_Content_46 = {
    Text = "你手無寸鐵，拉蒙娜也不在身邊，更別提那些夥伴。"
  },
  AvgDialog_72009_Content_47 = {
    Text = "異變體噴吐出一團黑泥，黏稠的漿液覆蓋上你的額頭，潮濕惡臭順著太陽穴一路下滑。"
  },
  AvgDialog_72009_Content_48 = {
    Text = "隨之而來的是一記重擊。"
  },
  AvgDialog_72009_Content_5 = {
    Text = "既然如此……我至少需要一副能夠在這裡自由行動的軀體。"
  },
  AvgDialog_72009_Content_51 = {
    Text = "你感覺身體騰空，眼冒金星，隨後側面飛來的一擊旋踢扭轉了方向，帶來萬箭穿心般的痛苦。"
  },
  AvgDialog_72009_Content_52 = {
    Text = "你狠狠砸在硬質的牆壁上，劇烈的疼痛讓你感覺自己的肋骨或許都斷了幾根。"
  },
  AvgDialog_72009_Content_53 = {
    Text = "（有沒有人能……救救我……）"
  },
  AvgDialog_72009_Content_55 = {
    Text = "煙塵之中，溫柯爾踉踉蹌蹌地從你身後的街角追來。"
  },
  AvgDialog_72009_Content_56 = {
    Text = "拿好這個，再、再走！"
  },
  AvgDialog_72009_Content_57 = {
    Text = "銀色的弧線劃過被粉塵污染的天空，穿過包圍你的怪物群，落在你的手邊。"
  },
  AvgDialog_72009_Content_58 = {
    Text = "一把銀鑰匙。沒有編號。"
  },
  AvgDialog_72009_Content_59 = {
    Text = "你伸手去觸摸，但生理性的淚水讓你眼前一片模糊，渾身上下的疼痛感令指尖不由自主地顫抖。"
  },
  AvgDialog_72009_Content_6 = {
    Text = "你無法在兩個世界間進行穿越……但利用這個世界內側的資源是可行的，對吧？"
  },
  AvgDialog_72009_Content_60 = {
    Text = "還差……一點……"
  },
  AvgDialog_72009_Content_61 = {
    Text = "哢擦——"
  },
  AvgDialog_72009_Content_62 = {
    Text = "怪物的觸肢狠狠踩上你的後背，已然開裂的傷口霎時間血花四濺。"
  },
  AvgDialog_72009_Content_63 = {
    Text = "但也就在這個瞬間，你的指尖碰觸到了那抹輝光。"
  },
  AvgDialog_72009_Content_65 = {
    Text = "朵爾說，你的神識包含了整個世界，只要回想，銀鑰匙就能激發出回憶的力量！"
  },
  AvgDialog_72009_Content_66 = {
    Text = "溫柔的白光漸漸籠罩了你的視野，熟悉的四個背影，幻覺般出現在你眼前。"
  },
  AvgDialog_72009_Content_67 = {
    Text = "守密人！真的是你嗎？"
  },
  AvgDialog_72009_Content_68 = {
    Text = "幾天不見就被融蝕體揍成這樣，彌薩格的體術課程還是欠缺獨立精神啊。"
  },
  AvgDialog_72009_Content_69 = {
    Text = "看起來，現在可不是適合敘舊的時候。"
  },
  AvgDialog_72009_Content_7 = {
    Text = "不愧是彌薩格最後的守密人，提出的要求還是這麼刁難人。"
  },
  AvgDialog_72009_Content_70 = {
    Text = "奧吉爾，為守護主公而戰！"
  },
  AvgDialog_72009_Content_71 = {
    Text = "戰鬥吧。"
  },
  AvgDialog_72009_Content_72 = {
    Text = "為了再次向前。"
  },
  AvgDialog_72009_Content_8 = {
    Text = "辦不到嗎？"
  },
  AvgDialog_72009_Content_9 = {
    Text = "當然不會。達芙黛爾的小店必將實現你的心願。"
  },
  AvgDialog_72010_Content_1 = {
    Text = "喂，西區佬，我是不是眼花了？"
  },
  AvgDialog_72010_Content_10 = {
    Text = "第一，能夠在短時間內完成建築的設計和建造，搭建者工程能力可見一斑。"
  },
  AvgDialog_72010_Content_11 = {
    Text = "第二，搭建者必然熟知整體實驗室的結構和設計細節，曾經長居於實驗室內……"
  },
  AvgDialog_72010_Content_12 = {
    Text = "如此推斷，這個人應當是——"
  },
  AvgDialog_72010_Content_13 = {
    Text = "咦、咦，%player%，你怎麼回來了，快，趁她還沒發現……"
  },
  AvgDialog_72010_Content_14 = {
    Text = "從轉角而來的溫柯爾手中擺弄著算力儀器，面露驚愕之色地向你打招呼。"
  },
  AvgDialog_72010_Content_15 = {
    Text = "隨後她的目光落在了你身後的陰影中。"
  },
  AvgDialog_72010_Content_16 = {
    Text = "她的瞳孔急劇收縮，神色轉為驚恐，手中的儀器哐當掉落在地，金屬零件四散飛濺，發出致人耳鳴的餘響。"
  },
  AvgDialog_72010_Content_17 = {
    Text = "對不起對不起對不起對不起！！朵爾，我不知道你在，我沒有想……對不起對不起對不起！"
  },
  AvgDialog_72010_Content_18 = {
    Text = "還有一件必須提醒你的事情——"
  },
  AvgDialog_72010_Content_19 = {
    Text = "這名搭建者掌握著我的實驗室中為數巨大的全部毀滅性裝置。"
  },
  AvgDialog_72010_Content_2 = {
    Text = "不……沒有。"
  },
  AvgDialog_72010_Content_20 = {
    Text = "並且擁有和我對等的權限——"
  },
  AvgDialog_72010_Content_21 = {
    Text = "你說對吧？"
  },
  AvgDialog_72010_Content_22 = {
    Text = "走廊的盡頭，緩緩步出一個一模一樣的身影。\n兩人隔著整個實驗室對望著，彷彿望向巨大玻璃鏡面裡的自己的倒影。"
  },
  AvgDialog_72010_Content_23 = {
    Text = "「另一個」熔燬·朵爾。"
  },
  AvgDialog_72010_Content_3 = {
    Text = "曾經坍塌為石堆的實驗室保持著原本的形態出現在街道的轉角，你反復揉了揉眼睛，確認這並非自身的幻覺。"
  },
  AvgDialog_72010_Content_4 = {
    Text = "我有一個猜想。小老鼠，你留在外面。"
  },
  AvgDialog_72010_Content_5 = {
    Text = "用得著我的時候就把我從床上拽起來，用不著我了就攆我走，哪有這種好事！"
  },
  AvgDialog_72010_Content_6 = {
    Text = "詹金，乖。你還要好好照顧梅森姐姐呢，我們過一會兒就出來。"
  },
  AvgDialog_72010_Content_7 = {
    Text = "可沒有說得那麼簡單。\n總之，我們小心點潛入進去吧。"
  },
  AvgDialog_72010_Content_8 = {
    Text = "距離你在這座實驗室甦醒已過半月，但眼前的景象竟與你甦醒時別無二致。"
  },
  AvgDialog_72010_Content_9 = {
    Text = "能夠將徹底損毀的建築完全還原，說明搭建者有兩項關鍵能力。"
  },
  AvgDialog_72011_Content_1 = {
    Text = "我們已經失去"
  },
  AvgDialog_72011_Content_11 = {
    Text = "小老鼠搖頭晃腦，似在否認詹金的問詢。"
  },
  AvgDialog_72011_Content_13 = {
    Text = "你激動得一把抱住詹金。"
  },
  AvgDialog_72011_Content_14 = {
    Text = "她瘦弱的身軀被你緊緊壓在懷中，那麼小，只有一丁點，卻是溫熱的，帶著生命的熱度，透過薄薄的肋骨傳來令人安心的心跳。"
  },
  AvgDialog_72011_Content_15 = {
    Text = "幹什麼啊！！瘋了嗎？！放開我！"
  },
  AvgDialog_72011_Content_16 = {
    Text = "還不等你和詹金解釋，身邊傳來模糊的嚶嚀聲。"
  },
  AvgDialog_72011_Content_18 = {
    Text = "我睡著了嗎……不能貪睡……還有20個燒瓶要刷，溶媒製劑還要儲備120升……"
  },
  AvgDialog_72011_Content_19 = {
    Text = "這是哪兒？！\n你們是？！"
  },
  AvgDialog_72011_Content_22 = {
    Text = "所以，詹金，你確實沒見到第三個人嗎？一個紅色短髮，一驚一乍的研究員……"
  },
  AvgDialog_72011_Content_23 = {
    Text = "我看恐怕是兇多吉少了，那句話怎麼說來著，節哀順變，願她的靈魂安息？"
  },
  AvgDialog_72011_Content_24 = {
    Text = "戴著兜帽的小老鼠聳了聳肩。"
  },
  AvgDialog_72011_Content_25 = {
    Text = "把你們兩個西區佬刨出來的地方，與其說是廢墟，不如說是石塊兒的小山。"
  },
  AvgDialog_72011_Content_26 = {
    Text = "要不是布朗非扯著我說裡面有東西，我才懶得去翻撿呢。"
  },
  AvgDialog_72011_Content_27 = {
    Text = "然後……朵爾你已經完全不記得你的邪惡實驗了？"
  },
  AvgDialog_72011_Content_28 = {
    Text = "雖然我覺得你的指控是純粹的無稽之談，但我不得不提醒你的是，以人類的善惡觀衡量我的行動準則不具備絲毫恰當性。"
  },
  AvgDialog_72011_Content_29 = {
    Text = "我不知道你們之間有什麼恩怨，不過，喏，這裡有麵包。"
  },
  AvgDialog_72011_Content_3 = {
    Text = "喂，這傢伙好像醒了。"
  },
  AvgDialog_72011_Content_30 = {
    Text = "口渴的話那邊有水，嗯，還有些紅茶，和我認不出來的一堆高檔玩意兒。"
  },
  AvgDialog_72011_Content_31 = {
    Text = "你……發家致富了？"
  },
  AvgDialog_72011_Content_32 = {
    Text = "什麼亂七八糟的！你不知道嗎？"
  },
  AvgDialog_72011_Content_33 = {
    Text = "那個做了一大堆怪夢的晚上過後，大部分人都不見了，外面全是怪物。"
  },
  AvgDialog_72011_Content_34 = {
    Text = "好在因為人都不見了，所以到處都是免費麵包。"
  },
  AvgDialog_72011_Content_35 = {
    Text = "你……怎麼會來這裡？"
  },
  AvgDialog_72011_Content_36 = {
    Text = "你環顧四周，小小的鐘樓空間擺了五六個臥鋪。"
  },
  AvgDialog_72011_Content_37 = {
    Text = "我才不想來，小老鼠在街頭活得好得很。就是晚上的時候，那些鬧哄哄的傢伙太煩人了。"
  },
  AvgDialog_72011_Content_38 = {
    Text = "我往高處躲的時候，就找到了這裡，要爬個梯子，怪物上不來。"
  },
  AvgDialog_72011_Content_39 = {
    Text = "可惜我發現得晚，已經被人佔啦，大多數都是傷病員，或者瘋瘋癲癲的。"
  },
  AvgDialog_72011_Content_4 = {
    Text = "一個小腦袋鑽進你的視野。"
  },
  AvgDialog_72011_Content_40 = {
    Text = "有個善心的大姐姐給我也準備了一張床鋪，那句話怎麼說來著，“何樂而不為”？"
  },
  AvgDialog_72011_Content_41 = {
    Text = "詹金，有客人來嗎？"
  },
  AvgDialog_72011_Content_42 = {
    Text = "你的呼吸一滯。"
  },
  AvgDialog_72011_Content_43 = {
    Text = "啊，不好意思，招待不周，我這就去給你們端茶來。"
  },
  AvgDialog_72011_Content_44 = {
    Text = "姐姐！他們有手有腳的，不需要你照顧。"
  },
  AvgDialog_72011_Content_45 = {
    Text = "對了，這是我姐姐，梅森，她現在看起來有點怪，但你們要是敢把她當成怪物的話，我不會讓你們有好果子吃！"
  },
  AvgDialog_72011_Content_47 = {
    Text = "你怎麼回事？感天動地的姐弟情深，你第一次見？"
  },
  AvgDialog_72011_Content_48 = {
    Text = "什麼姐弟，你眼睛是不是有問題啊！？我是女的，女的！"
  },
  AvgDialog_72011_Content_49 = {
    Text = "一切都回來了，正如你第一次與她相見的時候。\n你拭了拭眼角。"
  },
  AvgDialog_72011_Content_5 = {
    Text = "醒了的話就去洗個澡吧，倫敦的老鼠都看不下去你一身的髒灰了。"
  },
  AvgDialog_72011_Content_50 = {
    Text = "抱歉，我失態了，只是沒想到會再見到你們……"
  },
  AvgDialog_72011_Content_51 = {
    Text = "再？這位%sirormadam%，我們以前認識嗎？很抱歉接受治療後我有很多記憶都混亂了……"
  },
  AvgDialog_72011_Content_52 = {
    Text = "不，這不重要……知道你們還活著，就好了……"
  },
  AvgDialog_72011_Content_55 = {
    Text = "我不知道大姐姐用什麼方法，總之我跟她說了說姐姐的事情，她就幫我把姐姐帶了回來。"
  },
  AvgDialog_72011_Content_56 = {
    Text = "姐姐……雖然有時候會顯得有點不安和崩潰，但她在好的狀態下依然很溫柔善良，對我和其他人都特別好……"
  },
  AvgDialog_72011_Content_57 = {
    Text = "你說的那個大姐姐……她叫什麼名字？"
  },
  AvgDialog_72011_Content_58 = {
    Text = "咦，我剛才沒說嗎？"
  },
  AvgDialog_72011_Content_59 = {
    Text = "克萊門汀，她叫克萊門汀。"
  },
  AvgDialog_72011_Content_62 = {
    Text = "所以，如果她和羅傑斯的關係如我的預期一般……是克萊門汀將梅森從雕塑家協會處搭救回來的嗎？"
  },
  AvgDialog_72011_Content_63 = {
    Text = "雕塑家協會，那些苟且偷生的臭蟲嗎？\n和那些傢伙混在一起的，就算不是床蝨、蜱蟲，也得是螞蟥、牛虻一樣的髒東西。"
  },
  AvgDialog_72011_Content_64 = {
    Text = "您貿然做出如此發言，可就不太禮貌了，親愛的小小姐。"
  },
  AvgDialog_72011_Content_65 = {
    Text = "白衣的女人無聲無息地飄然出現在你身後。"
  },
  AvgDialog_72011_Content_66 = {
    Text = "一陣嗡鳴聲鑽入你的腦海，眼前的景象扭曲起來。"
  },
  AvgDialog_72011_Content_67 = {
    Text = "你們二位還是我親自從一片狼藉的廢墟中翻出來，又辛辛苦苦扛到這鐘樓之上，生怕你們一不小心就被那些冒著黑泥的怪物生吞活剝了……"
  },
  AvgDialog_72011_Content_68 = {
    Text = "恩將仇報可不好啊，你們說對不對？"
  },
  AvgDialog_72011_Content_69 = {
    Text = "你的內心警鈴大作，旋身與她對峙，高揚的銀鑰閃爍召喚的銀光。\n在你出手之前，小小的身影突然躥出，擋在白衣女人身前。"
  },
  AvgDialog_72011_Content_70 = {
    Text = "克萊門汀小姐是我和姐姐的恩人，不准你們傷害她！"
  },
  AvgDialog_72011_Content_9 = {
    Text = "你這傢伙，從哪裡認識的我？我臉上寫了名字嗎，布朗？"
  },
  AvgDialog_72012_Content_1 = {Text = "深夢"},
  AvgDialog_72012_Content_10 = {
    Text = "你又開始說那些聽不懂的怪話了。"
  },
  AvgDialog_72012_Content_11 = {
    Text = "聽不懂也沒關係，這些本就不是孩子應該背負的東西。"
  },
  AvgDialog_72012_Content_12 = {
    Text = "姐姐，我還有一件事要請教你。"
  },
  AvgDialog_72012_Content_13 = {
    Text = "莎拉阿姨的病，是治不好的，對嗎？"
  },
  AvgDialog_72012_Content_14 = {
    Text = "克萊門汀撫摸著詹金的後腦勺。"
  },
  AvgDialog_72012_Content_15 = {
    Text = "若是%player%問起，你就回答%heorshe%。"
  },
  AvgDialog_72012_Content_16 = {
    Text = "「在深夢之底，不願入夢之人會給你答案。」"
  },
  AvgDialog_72012_Content_18 = {
    Text = "她輕靈地躍下鐘樓的階梯，一雙透明的泛光蟲翼在她背後逐漸展開。"
  },
  AvgDialog_72012_Content_19 = {
    Text = "願這陣風托舉我們，抵達永恆的深夢。"
  },
  AvgDialog_72012_Content_2 = {
    Text = "誰在那邊……？！"
  },
  AvgDialog_72012_Content_21 = {
    Text = "莎拉小姐，我們要準備出發前往濟世大聖堂了。"
  },
  AvgDialog_72012_Content_22 = {
    Text = "可以不離開這裡嗎？我怕孩子們回來的時候找不到我……"
  },
  AvgDialog_72012_Content_23 = {
    Text = "好吧……但在那之前，能帶我再去一次院長辦公室嗎？"
  },
  AvgDialog_72012_Content_24 = {
    Text = "我有些東西，想要取上……"
  },
  AvgDialog_72012_Content_25 = {
    Text = "有沒有搞錯，你的辦公室附近可被那些大傢伙堆滿了！"
  },
  AvgDialog_72012_Content_26 = {
    Text = "雖然我很想否定各位在這個世界中追求物質的愚蠢意義，不過歸根結底，各位去哪兒對我來說沒有區別。"
  },
  AvgDialog_72012_Content_28 = {
    Text = "走吧，去看看再說。"
  },
  AvgDialog_72012_Content_29 = {
    Text = "莎拉強撐著身體，搖搖晃晃地向辦公桌走去。她的身體趔趄了一下，歪倒在桌旁，強撐著喘氣。"
  },
  AvgDialog_72012_Content_3 = {
    Text = "別擔心，詹金，是我。"
  },
  AvgDialog_72012_Content_30 = {Text = "這兒。"},
  AvgDialog_72012_Content_31 = {
    Text = "唰啦一聲木製抽屜被倉促拉開，陳舊的金銀手鐲、胸針、戒指……混亂地甩了一地。"
  },
  AvgDialog_72012_Content_32 = {
    Text = "莎拉鋪在地上，試圖將它們一一聚攏起來。"
  },
  AvgDialog_72012_Content_33 = {
    Text = "都什麼時候了，收集這些玩意還有什麼意義，外面的人都已經……嗚嗚嗚！"
  },
  AvgDialog_72012_Content_34 = {
    Text = "熔燬·朵爾一把拉過詹金，將一個古怪的小腦缸塞進了她的嘴裡。"
  },
  AvgDialog_72012_Content_35 = {
    Text = "不該你說話的時候，少插嘴。"
  },
  AvgDialog_72012_Content_37 = {
    Text = "她掙扎著將異物掏出，大口喘著氣。"
  },
  AvgDialog_72012_Content_38 = {
    Text = "喂，就算要讓我閉嘴，最起碼你也拿個味道好點的東西吧！這玩意嘗起來像黏糊糊的蛞蝓，好惡心！"
  },
  AvgDialog_72012_Content_39 = {
    Text = "抱歉，忘記你不具備關閉嗅覺和味覺傳感器的功能了。"
  },
  AvgDialog_72012_Content_4 = {
    Text = "克萊門汀姐姐！"
  },
  AvgDialog_72012_Content_40 = {
    Text = "好了，我不喜歡總是停留在原地。"
  },
  AvgDialog_72012_Content_41 = {
    Text = "東西都拿上了吧？拿上了我們就去教堂吧。"
  },
  AvgDialog_72012_Content_42 = {
    Text = "擅長戰鬥的，開路。"
  },
  AvgDialog_72012_Content_5 = {
    Text = "少女歡暢地撲了上去。"
  },
  AvgDialog_72012_Content_6 = {
    Text = "小詹金，姐姐是來跟你告別的。"
  },
  AvgDialog_72012_Content_7 = {
    Text = "為什麼？為什麼要走？如果是因為那個西區佬，我讓布朗把%heorshe%趕開！"
  },
  AvgDialog_72012_Content_8 = {
    Text = "反正%heorshe%看起來完全能自己料理那些怪物。"
  },
  AvgDialog_72012_Content_9 = {
    Text = "不，當然不是……只是，我聽見了夢境中的風聲。"
  },
  AvgDialog_72013_Content_1 = {
    Text = "親切的與勇敢的"
  },
  AvgDialog_72013_Content_10 = {
    Text = "布朗回過身來，蹦上你的肩頭，用尖尖的鼻子貼近你的臉頰輕嗅著。"
  },
  AvgDialog_72013_Content_12 = {
    Text = "摸摸它的頭"
  },
  AvgDialog_72013_Content_13 = {
    Text = "你輕輕摸了摸它的小腦袋，它則仰著頭回應你。"
  },
  AvgDialog_72013_Content_14 = {
    Text = "記憶裡這是你們第一次如此親近。"
  },
  AvgDialog_72013_Content_15 = {
    Text = "與它對視"
  },
  AvgDialog_72013_Content_16 = {
    Text = "它吱吱一聲別過臉去，噠噠地鑽到詹金的兜帽裡，探出半個腦袋小心翼翼地與你對視。"
  },
  AvgDialog_72013_Content_17 = {
    Text = "通過前面的走廊，就是地下室的位置了。"
  },
  AvgDialog_72013_Content_18 = {
    Text = "詹金和布朗竊竊私語。"
  },
  AvgDialog_72013_Content_2 = {
    Text = "這裡的煙塵一直沒到腳踝。\n布朗在其中蹦來跳去，落下一個又一個小小的陷坑。"
  },
  AvgDialog_72013_Content_20 = {
    Text = "它說什麼了？"
  },
  AvgDialog_72013_Content_21 = {
    Text = "哼。我問它為什麼這麼親近你，布朗說你是個無害的傢伙。"
  },
  AvgDialog_72013_Content_22 = {
    Text = "動物的直覺總是很准的。"
  },
  AvgDialog_72013_Content_23 = {
    Text = "少貧嘴，誰知道你這傢伙用了什麼手段。"
  },
  AvgDialog_72013_Content_24 = {
    Text = "詹金彆扭地撇了撇嘴，下個瞬間卻突然瞪圓了眼。"
  },
  AvgDialog_72013_Content_26 = {
    Text = "詹金一把拉過你，噴射的漿液從你臉頰劃過，落在走廊的牆壁上，腐蝕的臭味蒸汽般彌漫在空間裡，讓人幾乎將胃液嘔出來。"
  },
  AvgDialog_72013_Content_27 = {
    Text = "徘徊的融蝕體聚集而來，在你們面前的道路上發出聲聲悲鳴。"
  },
  AvgDialog_72013_Content_28 = {
    Text = "嘁，你帶的這條路太窄了，沒法繞過去啊。"
  },
  AvgDialog_72013_Content_29 = {
    Text = "這段時間，你就是這麼生存下來的？"
  },
  AvgDialog_72013_Content_3 = {
    Text = "真的要在這裡搜索什麼……幸村者嗎？"
  },
  AvgDialog_72013_Content_30 = {
    Text = "那當然。"
  },
  AvgDialog_72013_Content_31 = {
    Text = "這裡施展不開……我們將這些異變體引到庭院裡吧。"
  },
  AvgDialog_72013_Content_4 = {
    Text = "是倖存者。"
  },
  AvgDialog_72013_Content_5 = {
    Text = "濟貧院我都搜索過了，這裡可沒什麼正常人。"
  },
  AvgDialog_72013_Content_6 = {
    Text = "不……還有一個地方。"
  },
  AvgDialog_72013_Content_7 = {
    Text = "你的眼前浮現出地下室的畫面。"
  },
  AvgDialog_72013_Content_8 = {
    Text = "那個安靜的雕塑者，珊，她還會在那裡進行悖亂常理的雕刻嗎？"
  },
  AvgDialog_73775_Content_10 = {
    Text = "同族？抱歉，我還不想改變自己的種族。"
  },
  AvgDialog_73775_Content_11 = {
    Text = "就像剛才的測試結果，我保留著人性，且自認為是人類。"
  },
  AvgDialog_73775_Content_12 = {
    Text = "……這樣啊，真是可惜。我本來不想做到這個地步的。"
  },
  AvgDialog_73775_Content_13 = {
    Text = "但為了向你展示人類的脆弱性，為了幫助你脫離人類這種低級的生命狀態，我不得不替你治療——"
  },
  AvgDialog_73775_Content_14 = {
    Text = "頭痛讓你聽不清克萊門汀的聲音，只能看到嘴唇的張合。\n她說的似乎並不是人言，而是囈語，無數人臨死前的囈語。"
  },
  AvgDialog_73775_Content_16 = {
    Text = "<Red:殺了我！>"
  },
  AvgDialog_73775_Content_17 = {
    Text = "瞧，人類的內心是多麼軟弱，一點點催眠和暗示，就能帶來無法逆轉的影響。"
  },
  AvgDialog_73775_Content_18 = {
    Text = "<Red:來陪我，快來陪我吧……>"
  },
  AvgDialog_73775_Content_19 = {
    Text = "<Red:讓我們……共入天堂。>"
  },
  AvgDialog_73775_Content_2 = {
    Text = "最終，你的攻擊無形化解，只是深深地給了「拉蒙娜」一個擁抱。"
  },
  AvgDialog_73775_Content_20 = {
    Text = "感受到了嗎？%player%。那都是你靈魂深處的聲音，是你這具身體真正的本能和意願。"
  },
  AvgDialog_73775_Content_21 = {
    Text = "<RedShake:殺了我！殺了我！殺了我！殺了我！殺了我！殺了我！>"
  },
  AvgDialog_73775_Content_22 = {
    Text = "<RedBig:殺了「我」>"
  },
  AvgDialog_73775_Content_23 = {
    Text = "不知什麼時候，克萊門汀來到你的面前，向你遞出一柄尖刀。你不受控制地接過它，放到自己的心口。"
  },
  AvgDialog_73775_Content_24 = {
    Text = "來，行動吧。這之後，你將會獲得真正的解脫與新生。"
  },
  AvgDialog_73775_Content_26 = {
    Text = "你用盡最後力氣，將那柄尖刀插向克萊門汀——但預想中的情況並沒有發生。"
  },
  AvgDialog_73775_Content_28 = {
    Text = "哈哈哈，你為什麼總是能給我這麼多的驚喜？%player%，這簡直、簡直讓我……"
  },
  AvgDialog_73775_Content_29 = {
    Text = "興奮得無以復加。"
  },
  AvgDialog_73775_Content_3 = {
    Text = "天花板和地板憑空出現類似蟲足的尖刺，穿透你的臂膀、雙腿，你卻仍是緊緊擁抱著那道無法再見的身影。"
  },
  AvgDialog_73775_Content_30 = {
    Text = "克萊門汀笑著，而你終於看清了：你手中的尖刀，變成了一隻蟲蛹標本。"
  },
  AvgDialog_73775_Content_31 = {
    Text = "多麼天真可愛的孩子，竟然認為眼中所見的一切都是真實的。"
  },
  AvgDialog_73775_Content_32 = {
    Text = "這裡，是心靈的空間，我的心靈空間。這裡，只貫徹著我的意願，只展示著我想要展露的真實。"
  },
  AvgDialog_73775_Content_34 = {
    Text = "沉默是因為心理崩潰了嗎？沒關係，%player%，我們可以嘗試崩潰療法。"
  },
  AvgDialog_73775_Content_35 = {
    Text = "那是真正的折磨，能夠讓所有患者老老實實將他們的痛苦從靈魂裡榨取出來。"
  },
  AvgDialog_73775_Content_36 = {
    Text = "這樣的治療方法，我還有很多、很多，多到足以擊潰你身為人類的認知和理智，逐漸轉化成真正的蟲子。"
  },
  AvgDialog_73775_Content_37 = {
    Text = "你將忘記身為人類的一切，甚至忘記「人類」這個詞彙的意義。"
  },
  AvgDialog_73775_Content_38 = {
    Text = "等到那時，我會給你痊癒的證明，帶領你以@2蟲族的身分，獲得新生。"
  },
  AvgDialog_73775_Content_39 = {
    Text = "恐怕你等不到那個時候了。"
  },
  AvgDialog_73775_Content_4 = {
    Text = "我會回去的，一定會想盡辦法回去的。等著我……"
  },
  AvgDialog_73775_Content_40 = {
    Text = "低頭，看看胸口。"
  },
  AvgDialog_73775_Content_41 = {
    Text = "克萊門汀聞言低下頭，見到一個充滿棱角的東西抵在她的胸膛。"
  },
  AvgDialog_73775_Content_42 = {
    Text = "銀鑰匙？"
  },
  AvgDialog_73775_Content_43 = {
    Text = "是的，銀鑰匙。在觀察和推理後，我認為，你才是這間療養院的核心。"
  },
  AvgDialog_73775_Content_44 = {
    Text = "你想強行連結我？作為守密人，你應該明白其中的危險性……"
  },
  AvgDialog_73775_Content_46 = {
    Text = "說著，你忍不住笑起來。如果在那個世界，朵爾教授肯定會斥責你胡亂操作，拉蒙娜也會勸說你，和你共同尋找更好的選擇。"
  },
  AvgDialog_73775_Content_47 = {
    Text = "但這裡，只有我一個人。"
  },
  AvgDialog_73775_Content_48 = {
    Text = "威廉……我沒有食言，我會拯救這間療養院的所有人。"
  },
  AvgDialog_73775_Content_49 = {
    Text = "銀鑰的震動裡，劇烈的白光從克萊門汀的白銀之心上爆發開來，溢滿整個房間——"
  },
  AvgDialog_73775_Content_5 = {
    Text = "幻影沉默著虛化、最終消失——克萊門汀收回了投影。"
  },
  AvgDialog_73775_Content_50 = {
    Text = "隨後，銀鑰匙掉落，你和克萊門汀雙雙倒地。"
  },
  AvgDialog_73775_Content_51 = {
    Text = "想通過強行連結我而破解療養院？真是瘋狂的想法，但是，我喜歡。"
  },
  AvgDialog_73775_Content_52 = {
    Text = "可惜這裡是我的心靈空間，%player%，看來你註定要成為我的同族了。"
  },
  AvgDialog_73775_Content_53 = {
    Text = "接下來，是我為你特殊訂製的深度治療時刻。\n當然，為了確保療效，我隱藏了你的小道具。"
  },
  AvgDialog_73775_Content_54 = {
    Text = "盡情向我展示你的痛苦，你的掙扎，即將蛻變的小蟲子——"
  },
  AvgDialog_73775_Content_6 = {
    Text = "感性麼……很有趣的選擇。只是這個選擇——值得嗎？"
  },
  AvgDialog_73775_Content_7 = {
    Text = "直面過祂的你有更好的選擇——成為我的同族，成為屬於宇宙的偉大存在。"
  },
  AvgDialog_73775_Content_8 = {
    Text = "我見過許多人類，但從沒有一個人，能讓我產生這樣的渴望——"
  },
  AvgDialog_73775_Content_9 = {
    Text = "你註定成為我的同族，你必須成為我的同族。"
  },
  AvgDialog_73776_Content_1 = {
    Text = "孤獨的勇者"
  },
  AvgDialog_73776_Content_10 = {
    Text = "請坐——"
  },
  AvgDialog_73776_Content_11 = {
    Text = "一個椅子憑空出現在你身後，載著你滑到克萊門汀的對面。"
  },
  AvgDialog_73776_Content_12 = {
    Text = "你趁機快速掃視四周——沙發、辦公桌、昆蟲乾製標本。"
  },
  AvgDialog_73776_Content_13 = {
    Text = "沙發、辦公桌，都太常見了，不太可能。心靈空間的核心必然會更特殊一點。那就只剩下……"
  },
  AvgDialog_73776_Content_14 = {
    Text = "你的餘光在偷瞄什麼？嗯，昆蟲標本。難道說，你也對昆蟲感興趣？"
  },
  AvgDialog_73776_Content_16 = {
    Text = "不想回答也沒關係。我說過，我是個充滿博愛精神的心理醫生，能夠包容患者的小缺點。"
  },
  AvgDialog_73776_Content_17 = {
    Text = "當然，也不介意給患者一些貼心的提示，比如，你想找的東西並不在那些標本里。"
  },
  AvgDialog_73776_Content_18 = {
    Text = "你將目光從昆蟲標本上移開，正視克萊門汀。"
  },
  AvgDialog_73776_Content_19 = {
    Text = "克萊門汀，你建造這間療養院的目的是什麼？那個需要許多祭品的重要實驗，又是什麼？"
  },
  AvgDialog_73776_Content_20 = {
    Text = "這裡，死了那麼多人，造成了那麼多的慘劇，你卻說這裡不是屠宰場，而是心靈的療養院。那麼它療養的對象究竟是誰？"
  },
  AvgDialog_73776_Content_21 = {
    Text = "這個問題很重要嗎？我還以為直面過那偉大存在的你，不會關注這些小問題呢。"
  },
  AvgDialog_73776_Content_22 = {
    Text = "這不是什麼小問題。只要涉及到人命，就從來都不會是小問題！"
  },
  AvgDialog_73776_Content_23 = {
    Text = "很顯然，在這裡獲得救贖的不是患者，因為他們只是祭品。而排除掉錯誤的答案，剩下的就是正解。"
  },
  AvgDialog_73776_Content_24 = {
    Text = "這間療養院真正療癒的，是你，克萊門汀，這間療養院的主人。"
  },
  AvgDialog_73776_Content_25 = {
    Text = "告訴我，什麼樣的心理創傷需要用這麼多的人命去填補？"
  },
  AvgDialog_73776_Content_26 = {
    Text = "克萊門汀露出疑惑的表情。她不明白也不理解你的憤怒從何而來，但很快，她就笑起來。"
  },
  AvgDialog_73776_Content_27 = {
    Text = "如果這是你的請求，那麼我同意了。直面過那偉大存在的你，有資格成為我的同類。"
  },
  AvgDialog_73776_Content_28 = {
    Text = "你在說什麼……"
  },
  AvgDialog_73776_Content_29 = {
    Text = "只是，我們需要先來進行一個小測試。"
  },
  AvgDialog_73776_Content_3 = {
    Text = "又一聲爆炸，足以吸引療養院的所有生物，為你前往克萊門汀的房間鋪平道路。"
  },
  AvgDialog_73776_Content_30 = {
    Text = "別擔心，真的只是一個小測試而已，目的只是為了測評一下你的自我認知和人性存留。"
  },
  AvgDialog_73776_Content_31 = {
    Text = "隨著克萊門汀的話語，一個熟悉卻無法再次相見的身影緩緩出現在你面前。"
  },
  AvgDialog_73776_Content_33 = {
    Text = "你的記憶裡都是這個女孩的身影，所以我想，你應該很想見見她——"
  },
  AvgDialog_73776_Content_34 = {
    Text = "不用謝我，請盡情享受這重聚時刻。"
  },
  AvgDialog_73776_Content_4 = {
    Text = "威廉……我不會辜負你的犧牲。"
  },
  AvgDialog_73776_Content_5 = {
    Text = "我一定會找到療養院的核心，摧毀它。"
  },
  AvgDialog_73776_Content_6 = {
    Text = "終於，你走到那扇門前——深呼一口氣，你做好了面對療養院幕後掌控者的準備。"
  },
  AvgDialog_73776_Content_7 = {
    Text = "推開克萊門汀的房門"
  },
  AvgDialog_73776_Content_8 = {
    Text = "熟悉的心理諮詢用沙發，辦公桌，具有怪異美感的昆蟲乾製標本，以及帶著微笑的克萊門汀。"
  },
  AvgDialog_73776_Content_9 = {
    Text = "歡迎來到我的諮詢室，%player%，我等你很久了。"
  },
  AvgDialog_73777_Content_1 = {
    Text = "燃燒的世界，再見"
  },
  AvgDialog_73777_Content_10 = {
    Text = "只是克萊門汀的精神狀態不太穩定，只是擔心虛空會侵蝕克萊門汀的銀芯，還是擔心醒來的克萊門汀出現什麼問題？"
  },
  AvgDialog_73777_Content_11 = {
    Text = "你還不明白嗎？當我們捕捉到克萊門汀意識碎片的時候，就已經代表了她的選擇和意志。"
  },
  AvgDialog_73777_Content_12 = {
    Text = "是的，我的意志和我的選擇，都是你，%player%。"
  },
  AvgDialog_73777_Content_13 = {
    Text = "克萊門汀！"
  },
  AvgDialog_73777_Content_14 = {
    Text = "感覺如何，是否需要我幫忙調試身軀？"
  },
  AvgDialog_73777_Content_15 = {
    Text = "我想暫時還不需要。我現在很好，或許從來都沒有這麼好過。"
