  AvgDialog_73786_Content_34 = {
    Text = "那東西……銀芯，可以讓他超脫嗎？"
  },
  AvgDialog_73786_Content_35 = {
    Text = "很遺憾，那是你的東西，是你的生命、你的意志所析出的奇蹟。"
  },
  AvgDialog_73786_Content_37 = {
    Text = "為什麼告訴我這些？為什麼現在才告訴我這些？！就是為了讓我和你們融合，成為一個怪物？"
  },
  AvgDialog_73786_Content_38 = {
    Text = "作為高維生命，俯視、操縱、玩弄我們這些人類，這些低維生物，究竟對你們有什麼好處！"
  },
  AvgDialog_73786_Content_39 = {
