  AvgDialog_73794_Content_16 = {Text = "誰？"},
  AvgDialog_73794_Content_17 = {
    Text = "槍聲代替了父親的回答，一同出現的，還有慘叫，族人的慘叫。"
  },
  AvgDialog_73794_Content_18 = {
