  },
  AvgDialog_80279_Content_70 = {
    Text = "她也是珈倫的家人之一！"
  },
  AvgDialog_80279_Content_71 = {
    Text = "（跟濃霧以及珈倫生前的宴會有關……）"
  },
  AvgDialog_80279_Content_72 = {
    Text = "（回去再調查一下吧，該不會是……）"
  },
  AvgDialog_80279_Content_73 = {
    Text = "呀！時間要不夠了！"
  },
  AvgDialog_80279_Content_74 = {
    Text = "什麼時間？"
  },
  AvgDialog_80279_Content_75 = {
    Text = "派對呀，主人！慶祝你成為清理大師的派對！"
  },
  AvgDialog_80279_Content_76 = {
    Text = "對哦！當時想著正好藉機在假期裡聚一下。"
  },
  AvgDialog_80279_Content_77 = {
    Text = "怎麼辦珈倫！還來得及嗎！"
  },
  AvgDialog_80279_Content_78 = {
    Text = "沒問題，交給珈倫吧！"
  },
  AvgDialog_80279_Content_79 = {
    Text = "在準備派對方面，珈倫也是專業的！"
  },
  AvgDialog_80279_Content_80 = {
    Text = "主人！派對的準備要加速了！衝呀！"
  },
  AvgDialog_80279_Content_81 = {
    Text = "跑太快了珈倫！等等我！"
  },
  AvgDialog_80279_Content_82 = {
    Text = "掃除奇旅\n- Fin -"
  },
  AvgDialog_80279_Content_9 = {
    Text = "醒來……"
  },
  AvgDialog_80280_Content_1 = {
    Text = "掃除完成！"
  },
  AvgDialog_80280_Content_10 = {
    Text = "主人不要逃！這次肯定沒問題的！"
  },
  AvgDialog_80280_Content_2 = {
    Text = "掃除完成！"
  },
  AvgDialog_80280_Content_3 = {
    Text = "主人好厲害，居然這麼快就領悟了掃除的奧義。"
  },
  AvgDialog_80280_Content_4 = {
    Text = "都是珈倫老師教得好。"
  },
  AvgDialog_80280_Content_5 = {
    Text = "為了紀念主人出師，我要給主人一個禮物！"
  },
  AvgDialog_80280_Content_6 = {
    Text = "什麼禮物？"
  },
  AvgDialog_80280_Content_7 = {
    Text = "珈倫的美食宴！主人想吃什麼？珈倫給你做！"
  },
  AvgDialog_80280_Content_8 = {
    Text = "什麼！額，珈倫，我想起來拉蒙娜找我有點事。"
  },
  AvgDialog_80280_Content_9 = {
    Text = "我先去她那邊了！飯不用給我留！"
  },
  AvgDialog_80319_Content_1 = {
    Text = "守密人，彌薩格已同意你的輔助戰鬥申請，點擊指令儀的<Blue:左下角>，開啟自動戰鬥權限。"
  },
  AvgDialog_80319_Content_2 = {
    Text = "注意，此技術仍處於研發階段，因此<Blue:面對強敵與特殊場景時無法生效>。"
  },
  AvgDialog_80319_Content_3 = {
    Text = "現在，繼續戰鬥吧。輔助戰鬥功能會持續到本次調查結束，你可以隨時開啟與關閉。"
  },
  AvgDialog_80448_Content_1 = {
    Text = "這不是拉蒙娜。拉蒙娜不會……"
  },
  AvgDialog_80448_Content_2 = {
    Text = "拉蒙娜絕對不會傷害我。"
  },
  AvgDialog_80448_Content_3 = {
    Text = "當然不是。這只是我剛才翻閱你的記憶後幻化出來的投影。"
  },
  AvgDialog_80448_Content_4 = {
    Text = "她的本質，我已經告訴你了，接下來，就看你如何選擇——"
  },
  AvgDialog_80448_Content_5 = {
    Text = "理性，還是感性，%player%，告訴我你的答案。"
  },
  AvgDialog_80449_Content_1 = {
    Text = "廣播通知，西區出現外來人員，請巡邏隊及時清理。"
  },
  AvgDialog_80449_Content_2 = {
    Text = "重複一遍，西區出現外來人員，請巡邏隊及時清理。"
  },
  AvgDialog_80449_Content_3 = {
    Text = "廣播聲音好耳熟，但一時想不起來……算了，不想了。"
  },
  AvgDialog_80449_Content_4 = {
    Text = "或許威廉就是廣播裡的外來人員，得想個辦法到西區去。"
  },
  AvgDialog_80977_Content_1 = {
    Text = "好孩子，能夠堅持到這裡，已經很棒了，接下來，你可以休息了。"
  },
  AvgDialog_80977_Content_11 = {
    Text = "我聽到了你的呼喚，所以我來了。"
  },
  AvgDialog_80977_Content_12 = {
    Text = "呼喚？啊，我明白了，我擴散了銀芯的牽引，或許這點微光對於宇宙毫無意義。"
  },
  AvgDialog_80977_Content_13 = {
    Text = "對於一直搜尋%player%氣息的你來說，確是渴求已久的太陽。"
  },
  AvgDialog_80977_Content_14 = {
    Text = "但是，或許%player%最想見到的並不是你，或者說，這個形態的你？"
  },
  AvgDialog_80977_Content_15 = {
    Text = "環行·拉蒙娜，你不要聽她胡說，我……"
  },
  AvgDialog_80977_Content_16 = {
    Text = "我明白。我不是她，也永遠不可能成為她，但畢竟，她也算是我對嗎？"
  },
  AvgDialog_80977_Content_17 = {
    Text = "我和她最底層的色彩，對於%player%你的執著，是一樣的。"
  },
  AvgDialog_80977_Content_19 = {
    Text = "不知為何，你看向了克萊門汀。"
  },
  AvgDialog_80977_Content_2 = {
    Text = "是的，你感到很疲憊，想要休息、休息……"
  },
  AvgDialog_80977_Content_20 = {
    Text = "死去的她，活著的她，兩個克萊門汀互不相同，互不理解，但她們終歸是一個人。"
  },
  AvgDialog_80977_Content_21 = {
    Text = "所以，她才會說不是她回應了我，而是「克萊門汀」回應了我。"
  },
  AvgDialog_80977_Content_22 = {
    Text = "可憐的%player%已經開始說胡話了。"
  },
  AvgDialog_80977_Content_23 = {
    Text = "記住，不要將獲得新生的我與那個渺小脆弱的人類相提並論，不然我會生氣的。"
  },
  AvgDialog_80977_Content_24 = {
    Text = "你沒有接話，而是看向環行·拉蒙娜。\n此刻，你的心中已經有了破局的辦法。"
  },
  AvgDialog_80977_Content_25 = {
    Text = "環行·拉蒙娜，你還能堅持多久？"
  },
  AvgDialog_80977_Content_26 = {
    Text = "理論上來說，我只能堅持幾分鐘。但是，只要沒有死亡，我就會無數次撕裂維度來到這裡。"
  },
  AvgDialog_80977_Content_27 = {
    Text = "無論需要重複多少次，我都會陪著你，戰鬥到最後。"
  },
  AvgDialog_80977_Content_28 = {
    Text = "……我明白了，搭檔。那就讓我們，戰鬥至獲得勝利。"
  },
  AvgDialog_80977_Content_29 = {
    Text = "因為無論是這個世界，還是另一個世界，都有人在等我。"
  },
  AvgDialog_80977_Content_3 = {
    Text = "你咬緊牙關，想要保持理智，然而克萊門汀充滿催眠感的聲音，卻讓力竭的你越發疲憊、困頓。"
  },
  AvgDialog_80977_Content_5 = {
    Text = "我還沒……"
  },
  AvgDialog_80977_Content_7 = {
    Text = "你猛然睜開眼睛，見到彌薩格標誌性的手套。"
  },
  AvgDialog_80977_Content_9 = {
    Text = "只一眼，你就知道對方是誰。\n因為在腦海中，你無數次勾勒過她的形貌。"
  },
  AvgDialog_80978_Content_1 = {
    Text = "為什麼……為什麼你總能做出這些出人意料的事情？"
  },
  AvgDialog_80978_Content_10 = {
    Text = "那閃耀著宇宙輝光的存在用目光鎖定住你，輕輕抖動羽翼，迎接著蛻變的時刻。"
  },
  AvgDialog_80978_Content_11 = {
    Text = "你本能地感到恐懼，但再多的恐懼，也無法讓你退後哪怕一步。"
  },
  AvgDialog_80978_Content_12 = {
    Text = "……拉蒙娜、威廉還有「克萊門汀」，請看著我，戰鬥吧！"
  },
  AvgDialog_80978_Content_2 = {
    Text = "真的好想剖開你的大腦，仔仔細細窺視每一個褶皺，每一條神經纖維，那裡一定、一定潛藏著最美味的痛苦吧……"
  },
  AvgDialog_80978_Content_3 = {
    Text = "你沒有機會知道。一切就要結束了。"
  },
  AvgDialog_80978_Content_4 = {
    Text = "結束？怎麼會呢，這只是……一個測試而已。"
  },
  AvgDialog_80978_Content_5 = {
    Text = "彌薩格的銀鑰匙，還有你，果然很神奇，竟然能夠穿透這間療養院，連結虛空。"
  },
  AvgDialog_80978_Content_6 = {
    Text = "但別忘了，這裡終歸受我掌控——你，也是受我掌控的人之一。"
  },
  AvgDialog_80978_Content_7 = {
    Text = "你又篡改了我的認知？"
  },
  AvgDialog_80978_Content_8 = {
    Text = "別擔心，只有一點點而已。現在來見見真正的@2吧。"
  },
  AvgDialog_80978_Content_9 = {
    Text = "畢竟，沒有你和銀鑰匙，我也無法召喚出這種程度的它。"
  },
  AvgDialog_81044_Content_1 = {
    Text = "療養院裡持續播放著警鈴聲。\n這刺耳的聲音是一種警示，一種恐嚇，一種精神污染。"
  },
  AvgDialog_81044_Content_10 = {
    Text = "不用提醒，你就已經拉著小威廉在廊道裡狂奔。你們身後是數不清的克萊門汀，人數多到開始堵住療養院的走廊。"
  },
  AvgDialog_81044_Content_2 = {
    Text = "無數扇心靈房間的大門空洞洞地打開，走出一個又一個克萊門汀。"
  },
  AvgDialog_81044_Content_3 = {
    Text = "讓我看看你的記憶——"
  },
  AvgDialog_81044_Content_4 = {
    Text = "她們說著一模一樣的話。"
  },
  AvgDialog_81044_Content_5 = {
    Text = "究竟是什麼樣的過去——"
  },
  AvgDialog_81044_Content_6 = {
    Text = "她們邁著整齊劃一的動作。"
  },
  AvgDialog_81044_Content_7 = {
    Text = "塑造了現在的你——"
  },
  AvgDialog_81044_Content_8 = {
    Text = "她們從四面八方，向你而來。"
  },
  AvgDialog_81045_Content_1 = {
    Text = "人類？還是蟲族？"
  },
  AvgDialog_81045_Content_3 = {
    Text = "這是一滴遲來的淚。\n這是一滴在心底醞釀許久的淚，久到它的主人，已經忘記了它的存在。"
  },
  AvgDialog_81046_Content_2 = {
    Text = "最終，你的攻擊無形化解，只是深深地給了「拉蒙娜」一個擁抱。"
  },
  AvgDialog_81046_Content_3 = {
    Text = "天花板和地板憑空出現類似蟲足的尖刺，穿透你的臂膀、雙腿，你卻仍是緊緊擁抱著那道無法再見的身影。"
  },
  AvgDialog_81046_Content_4 = {
    Text = "我會回去的，一定會想盡辦法回去的。等著我……"
  },
  AvgDialog_81046_Content_5 = {
    Text = "幻影沉默著虛化、最終消失——克萊門汀收回了投影。"
  },
  AvgDialog_81046_Content_6 = {
    Text = "感性麼……很有趣的選擇。只是這個選擇——值得嗎？"
  },
  AvgDialog_81046_Content_7 = {
    Text = "直面過祂的你有更好的選擇——成為我的同族，成為屬於宇宙的偉大存在。"
  },
  AvgDialog_81047_Content_1 = {
    Text = "因為人類太過渺小與脆弱。"
  },
  AvgDialog_81047_Content_2 = {
    Text = "忽然，一隻血肉組成的手撫上了克萊門汀的額頭。是父親。"
  },
  AvgDialog_81047_Content_3 = {
    Text = "隨後，父親擁抱了她，用力地擁抱了她。"
  },
  AvgDialog_81047_Content_4 = {
    Text = "@2門汀……對不起……為我所做的一切……"
  },
  AvgDialog_81047_Content_5 = {
    Text = "為什麼突然道歉，難道說……"
  },
  AvgDialog_81048_Content_1 = {
    Text = "一隻光蝶從怪物先生的胸膛裡飛了出現。"
  },
  AvgDialog_81048_Content_10 = {
    Text = "但那只蝴蝶不肯放棄，持續盤旋在你的手邊——你似乎，聽到了歎息。"
  },
  AvgDialog_81048_Content_2 = {
    Text = "記憶如水波蕩漾，徹底消散，化為數不清的飛舞之蝶。"
  },
  AvgDialog_81048_Content_3 = {
    Text = "%player%，你能聽到我的聲音嗎？"
  },
  AvgDialog_81048_Content_4 = {
    Text = "克萊門汀？你還活著？！"
  },
  AvgDialog_81048_Content_5 = {
    Text = "……抱歉，我的時間不多了。"
  },
  AvgDialog_81048_Content_6 = {
    Text = "在消失前，我必須要做一件事情。"
  },
  AvgDialog_81048_Content_7 = {
    Text = "一隻蝴蝶飛舞於你的手畔，溢出的微光如指引，但你拒絕了。"
  },
  AvgDialog_81048_Content_8 = {
    Text = "……如果我的逃生，需要以你的死亡為代價，克萊門汀，請容我拒絕。"
  },
  AvgDialog_81048_Content_9 = {
    Text = "別人為我犧牲這種事情，一次就夠了。"
  },
  AvgDialog_81049_Content_1 = {Text = "轟——"},
  AvgDialog_81049_Content_2 = {
    Text = "經受刺激的銀芯自主做出了選擇，而在那磅礴的死意面前，心靈空間做出了退步，徹底崩解。"
  },
  AvgDialog_81049_Content_3 = {
    Text = "一道道裂隙出現，而數不清的、被困在這裡的魂靈，借著它們奔向自由。"
  },
  AvgDialog_81049_Content_4 = {
    Text = "在那歡湧的無數靈魂下，是靜靜凝望你的克萊門汀。\n她的身體，也在崩潰。"
  },
  AvgDialog_81049_Content_5 = {
    Text = "……對不起。"
  },
  AvgDialog_81276_Content_1 = {
    Text = "於夜晚的酣眠中，你感到一股奇怪的癢意，就像有人在用羽毛輕輕撓著你的肌膚。"
  },
  AvgDialog_81276_Content_10 = {
    Text = "我，不知道為什麼睡不著，身上很熱，翅膀也很癢。"
  },
  AvgDialog_81276_Content_11 = {
    Text = "我本想請恩人幫我梳理羽毛，但這樣於禮不合，況且夜色已深……"
  },
  AvgDialog_81276_Content_12 = {
    Text = "現在貿然前來，更是十分冒昧，我知道的……"
  },
  AvgDialog_81276_Content_13 = {
    Text = "出於禮教的羞愧讓卡斯托爾的臉更紅了，他的眼神微微錯開，聲音越來越輕。"
  },
  AvgDialog_81276_Content_14 = {
    Text = "但，能否請恩人允許我在這裡稍坐一會兒，一會兒就好……"
  },
  AvgDialog_81276_Content_15 = {
    Text = "卡斯托爾。"
  },
  AvgDialog_81276_Content_17 = {
    Text = "隨著你的呼喚，卡斯托爾慢半拍地轉過了頭，那變得濕漉漉的眼中露出了一絲迷茫，但直到此時依舊充滿了對你的信任。"
  },
  AvgDialog_81276_Content_18 = {
    Text = "你不用那麼客氣的，過來吧，我幫你梳一梳翅膀。"
  },
  AvgDialog_81276_Content_19 = {
    Text = "卡斯托爾在糾結中短暫地停頓了一下，似乎在和內心的某種原則打架。"
  },
  AvgDialog_81276_Content_2 = {
    Text = "又有蚊子了嗎……嗯？！"
  },
  AvgDialog_81276_Content_20 = {
    Text = "最終他沉默著點了點頭，馴服地低伏下身體，輕輕趴在了你的腿上，向你露出後背。"
  },
  AvgDialog_81276_Content_21 = {
    Text = "月光透過窗簾的縫隙灑落，與那對放鬆展開的黑色羽翼一同鋪滿了你的床鋪。"
  },
  AvgDialog_81276_Content_22 = {
    Text = "是哪裡不舒服？"
  },
  AvgDialog_81276_Content_23 = {
    Text = "你的手輕柔地撫過，從翅膀的根部梳到長長的飛羽，像安撫一個無法入睡的孩童。"
  },
  AvgDialog_81276_Content_24 = {
    Text = "這裡嗎？還是這裡？"
  },
  AvgDialog_81276_Content_25 = {
    Text = "於是一隻鳥兒便在你的手下輕輕顫抖。"
  },
  AvgDialog_81276_Content_26 = {
    Text = "你不舒服嗎？我該用多大力氣？"
  },
  AvgDialog_81276_Content_27 = {
    Text = "不要問。"
  },
  AvgDialog_81276_Content_28 = {
    Text = "卡斯托爾忽然回頭，發出一聲嘆息似的責怪。"
  },
  AvgDialog_81276_Content_29 = {
    Text = "請隨您心意地梳理吧，只要是您……"
  },
  AvgDialog_81276_Content_3 = {
    Text = "睜開眼後，眼前竟然仍是一片模糊的黑暗，似乎有某種黑色的東西緊緊包裹著你。"
  },
  AvgDialog_81276_Content_30 = {
    Text = "你看到他的耳尖後知後覺地紅了起來，卡斯托爾重新將頭埋入了被子，發出悶悶的尾音。"
  },
  AvgDialog_81276_Content_4 = {
    Text = "轉頭間，你從那奇怪的黑暗中看到了一雙凝望的眼，正在面前與你默默相對。"
  },
  AvgDialog_81276_Content_6 = {
    Text = "啊！對不起！我吵到恩人了嗎……"
  },
  AvgDialog_81276_Content_7 = {
    Text = "那牢牢擁抱著你的黑暗忽然撤去了，卡斯托爾赧然地收起圈攏住你的雙翼，規規矩矩地端坐在了床邊。"
  },
  AvgDialog_81276_Content_8 = {
    Text = "卡斯托爾？！你在這裡做什麼？"
  },
  AvgDialog_81276_Content_9 = {
    Text = "你翻身坐起，與手足無措的卡斯托爾大眼瞪小眼。"
  },
  AvgDialog_81522_Content_1 = {Text = "一滴淚"},
  AvgDialog_81522_Content_10 = {
    Text = "“我在這裡。”"
  },
  AvgDialog_81522_Content_100 = {
    Text = "（可是弟弟啊，如果你真心如此，又為什麼要哭呢？）"
  },
  AvgDialog_81522_Content_11 = {
    Text = "波呂克斯抬起頭，看向視野中那雙讓他不屑又令他嫉妒的純黑羽翼。"
  },
  AvgDialog_81522_Content_13 = {
    Text = "波呂克斯發出一聲低低的笑，他又匆忙地低下頭去，遮擋住自己的表情。那是在笑卡斯托爾還是在笑自己，連他自己也不清楚。"
  },
  AvgDialog_81522_Content_14 = {
    Text = "那陣風驅逐了燈衛，卻溫柔地繞開了波呂克斯。一雙手將他從地上扶起。"
  },
  AvgDialog_81522_Content_15 = {
    Text = "波呂克斯！你怎麼樣？"
  },
  AvgDialog_81522_Content_16 = {
    Text = "……帶我走吧。"
  },
  AvgDialog_81522_Content_17 = {
    Text = "波呂克斯看向那些依然想要攻擊的燈衛，輕輕地呢喃。"
  },
  AvgDialog_81522_Content_18 = {
    Text = "沒有嘲弄，沒有驚訝，彷彿一直等待著這句話一般，卡斯托爾點了點頭。"
  },
  AvgDialog_81522_Content_2 = {
    Text = "你們怎敢……如此不敬……"
  },
  AvgDialog_81522_Content_20 = {
    Text = "於是那陣風又將波呂克斯包裹，將他帶離了那些冷漠得令他刺痛的眼神。"
  },
  AvgDialog_81522_Content_22 = {
    Text = "黃昏瑰麗的緋色籠罩了這座城，曾經美麗如沙漠寶石的水源之地，此刻只剩下一層虛幻的表象，恐怖的帷幕即將照常拉起。"
  },
  AvgDialog_81522_Content_23 = {
    Text = "天要黑了，這座城中會充滿怪物，喝下它能夠保證你的安全。"
  },
  AvgDialog_81522_Content_24 = {
    Text = "波呂克斯沉默而順從地飲下了泰旖絲捧來的樹汁，安靜地縮在角落。"
  },
  AvgDialog_81522_Content_25 = {
    Text = "我已經知道了那顆種子在哪裡，今夜我會去毀掉它，讓這裡的痛苦終結。"
  },
  AvgDialog_81522_Content_27 = {
    Text = "沒關係的，那也曾是我的孩子。"
  },
  AvgDialog_81522_Content_28 = {
    Text = "教會的人已經包圍了這裡，我和波呂克斯也會盡快想辦法離開，一路以來……謝謝。"
  },
  AvgDialog_81522_Content_29 = {
    Text = "卡斯托爾欲言又止，無法將那句告別真正說出口。他剛剛不甚熟練地經歷了相遇，便立刻要面對突然的離別。"
  },
  AvgDialog_81522_Content_3 = {
    Text = "像是要證明什麼似的，波呂克斯顫抖著劇痛的身體，不斷想要從地上支撐爬起。"
  },
  AvgDialog_81522_Content_30 = {
    Text = "泰旖絲笑著搖了搖頭，沒有多說什麼。"
  },
  AvgDialog_81522_Content_31 = {
    Text = "到了該分別的時候了，小傢伙。祝你們好運。"
  },
  AvgDialog_81522_Content_33 = {
    Text = "落日最後的餘溫中，卡斯托爾與波呂克斯在一條條街道上穿梭。"
  },
  AvgDialog_81522_Content_34 = {
    Text = "他們有意地露出一道影子、半片衣角，吸引著一隊隊巡邏的提燈燈衛。"
  },
  AvgDialog_81522_Content_35 = {
    Text = "發現聖子的消息很快使剩餘的燈衛也聚攏過來，一道道紫色的影子從四面八方無聲湧來。"
  },
  AvgDialog_81522_Content_36 = {
    Text = "卡斯托爾回頭看了看殷紅如血的夕陽，翻身進入了一家滿是住客的旅館。"
  },
  AvgDialog_81522_Content_37 = {
    Text = "我們的聖子終於不再逃跑了嗎？"
  },
  AvgDialog_81522_Content_38 = {
    Text = "巨犬的涎水隨著興奮的吐息滴落在地，在密密麻麻低頭致敬的身影中，于麗埃特從巨犬身上輕盈跳下。"
  },
  AvgDialog_81522_Content_39 = {
    Text = "一間旅館……怎麼，這裡有你們新結交的朋友嗎？"
  },
  AvgDialog_81522_Content_4 = {
    Text = "那樣不可置信的神情慢慢變作憤怒在他的眼中燃燒，掩蓋著瞳孔深處埋藏的恐懼。"
  },
  AvgDialog_81522_Content_40 = {
    Text = "詭異的寂靜瀰漫在空氣中，偌大的庭院中，甚至沒有一個出面詢問的店員。"
  },
  AvgDialog_81522_Content_41 = {
    Text = "巨犬抬起頭，耳朵向四周迷惑地轉動，發現整座城市中忽然沒有了任何一點響聲。"
  },
  AvgDialog_81522_Content_43 = {
    Text = "隨著于麗埃特揮了揮手，幾個燈衛小心地拉開了旅館的大門。"
  },
  AvgDialog_81522_Content_45 = {
    Text = "門軸的響聲於絕對的安靜中突兀而刺耳，巨犬不安地向前踏了一步，牠聽到有某種細微的蠕動聲從各處傳來。"
  },
  AvgDialog_81522_Content_46 = {
    Text = "旅館內彷彿時間凍結的標本，所有人維持著僵硬的姿勢，靜靜佇立在原地。"
  },
  AvgDialog_81522_Content_47 = {
    Text = "幾個燈衛試探著觸碰那些居民，便看到他們像昏睡一樣倒在了地上。"
  },
  AvgDialog_81522_Content_48 = {
    Text = "貌似還活著，應該沒有危……"
  },
  AvgDialog_81522_Content_49 = {
    Text = "噗嗤——"
  },
  AvgDialog_81522_Content_5 = {
    Text = "他無力地想要推開那條鎖鏈，以求保住自己岌岌可危的尊嚴。"
  },
  AvgDialog_81522_Content_50 = {
    Text = "話音未落，一根扭動著的漆黑枝條便從燈衛的胸口貫穿而出，轉瞬蔓延到他的全身。"
  },
  AvgDialog_81522_Content_51 = {
    Text = "來不及叫喊，孱弱的血肉之軀便被植物的意志佔據，四肢、內臟、七竅……黑色的線條湧動生長。"
  },
  AvgDialog_81522_Content_52 = {
    Text = "燈衛怪異地扭動了幾下，便欣然加入了樹的狂歡，他咧開嘴，新的枝條便從他的口中生長，滴下猩紅黏稠的血滴。"
  },
  AvgDialog_81522_Content_54 = {
    Text = "旅館的店主從燈衛身後站起，所有睡去的人們一同站起，它們的頭顱一齊旋轉，看向庭院內一具具新鮮的軀體，它們已嗅到了獵物的香味。"
  },
  AvgDialog_81522_Content_55 = {
    Text = "旅館外，深夜來臨，在濃稠的黑暗中，整座城市重新醒來。"
  },
  AvgDialog_81522_Content_56 = {
    Text = "有什麼沉重的東西突然從旅館樓頂砸落，隨著一聲巨響，旅館內外無數笨拙的腳步聲被吸引，踢踢踏踏靠攏而來。"
  },
  AvgDialog_81522_Content_57 = {
    Text = "天台上，收回手的卡斯托爾將身影藏在圍牆之後，靜靜望著樓下的一切。"
  },
  AvgDialog_81522_Content_59 = {
    Text = "一旁的波呂克斯瞪大了雙眼，他看向冷靜的卡斯托爾，一時說不出話。"
  },
  AvgDialog_81522_Content_6 = {
    Text = "他想要辯解，呼喊，求救，但他能向誰求救呢？"
  },
  AvgDialog_81522_Content_60 = {
    Text = "于麗埃特那永恆不變的笑容微微冷卻，她看向隔著無數房間的天台，又看向周圍艱難抵抗怪物的燈衛，幾乎要忍不住為卡斯托爾的成長鼓起掌來。"
  },
  AvgDialog_81522_Content_61 = {
    Text = "於是她站在一片血腥之中，旁若無人地輕輕鼓起了掌。"
  },
  AvgDialog_81522_Content_62 = {
    Text = "很不錯的計劃，很勇敢的決斷，不愧是教會培養多年的孩子。"
  },
  AvgDialog_81522_Content_63 = {
    Text = "卡斯托爾望向她依然從容的樣子，神情凝重。"
  },
  AvgDialog_81522_Content_64 = {
    Text = "作為你們的老師，我可以給你們優異的評價，但現在，該和老師回去了。"
  },
  AvgDialog_81522_Content_65 = {
    Text = "于麗埃特不知從何處拿出了那面暗淡的鏡子，她笑著吟誦晦澀的咒文，皎潔而冰冷的月光反射在鏡子上，竟逐漸變得晦暗猩紅。"
  },
  AvgDialog_81522_Content_66 = {
    Text = "一層血色的薄膜籠罩了月亮，刺眼的紅光下，所有枝條都失去了生命一般靜止下來。"
  },
  AvgDialog_81522_Content_67 = {
    Text = "下一瞬，那些枝條開始發狂地舞動，彷彿在痛苦哀嚎一般，那些枝條寄宿的血肉也一起鼓脹、變形，翻滾著互相糾纏在一處。"
  },
  AvgDialog_81522_Content_69 = {
    Text = "齊聲的誦念聲從所有教眾口中嗡鳴擴散，凡念誦咒文的，都免去了那瘋狂的折磨，開始向著天台靠近。"
  },
  AvgDialog_81522_Content_70 = {
    Text = "怪物刺耳的嚎叫聲中，于麗埃特望向天台伸出手掌，像是一位呼喚孩子歸家的母親。"
  },
  AvgDialog_81522_Content_72 = {
    Text = "頭……好痛！！卡斯托爾……"
  },
  AvgDialog_81522_Content_73 = {
    Text = "卡斯托爾咬牙擊暈翻滾叫喊的波呂克斯，顫抖著打開從卡納克手中得到的那只盒子，將最後的藥丸送入自己口中。"
  },
  AvgDialog_81522_Content_74 = {
    Text = "巨大的血月之下，那雙純黑的羽翼剎那展開，甘泉般的熒光流淌在每一片羽毛上，所有的傷口都一瞬消弭於無形。"
  },
  AvgDialog_81522_Content_75 = {
    Text = "該走了。"
  },
  AvgDialog_81522_Content_76 = {
    Text = "感受著磅礴的力量在體內湧動，卡斯托爾的雙眼閃過綠光，他抱起波呂克斯，從天台一躍而下。"
  },
  AvgDialog_81522_Content_78 = {
    Text = "恐怖嘯叫著的颶風將無數燈衛與怪物都高高捲起，撕碎成淋漓的血雨，灑落在他的身後。"
  },
  AvgDialog_81522_Content_79 = {
    Text = "風將卡斯托爾推動成一道箭似的黑影，他的手中醞釀著風刃，直直擊向于麗埃特手中的儀式鏡。"
  },
  AvgDialog_81522_Content_8 = {
    Text = "波呂克斯張了張嘴，只呼出一口虛弱的氣聲。"
  },
  AvgDialog_81522_Content_80 = {
    Text = "（只要毀去那面鏡子，他們就不可能再追上來了……）"
  },
  AvgDialog_81522_Content_81 = {
    Text = "于麗埃特的面龐在卡斯托爾眼中極速拉近，卡斯托爾甚至能夠看見她因驚訝而微微縮小的瞳孔。"
  },
  AvgDialog_81522_Content_82 = {
    Text = "但在她的面龐上，那令他厭惡的笑意不僅沒有消失，反而越發濃厚起來。"
  },
  AvgDialog_81522_Content_83 = {
    Text = "（為什麼？她還有更多的手段阻攔我？她究竟要做什麼……）"
  },
  AvgDialog_81522_Content_84 = {
    Text = "不安的預感讓卡斯托爾的心臟緊張地跳動，他下意識緊了緊抱住波呂克斯的那隻手，做好了一場苦戰的準備。"
  },
  AvgDialog_81522_Content_85 = {
    Text = "就在他的手快要碰到于麗埃特的那一刻，一聲微弱的悶響從耳邊呼嘯的風聲之中，清晰地傳進了卡斯托爾的耳朵。"
  },
  AvgDialog_81522_Content_86 = {
    Text = "卡斯托爾低下頭，他看到一片漸漸洇開的血暈從自己的胸口擴散。"
  },
  AvgDialog_81522_Content_87 = {
    Text = "隨著血花輕盈地飛濺，一隻蒼白的手腕從那片殷紅之中輕輕拔出。"
  },
  AvgDialog_81522_Content_88 = {
    Text = "卡斯托爾難以置信地睜著眼，慢慢看向了懷中面無表情的波呂克斯。"
  },
  AvgDialog_81522_Content_9 = {
    Text = "率先回應他的不是偉大的持燈者，也不是始終教導他的教主大人，而是一陣猛烈而熟悉的颶風。"
  },
  AvgDialog_81522_Content_90 = {
    Text = "那隻翱翔的黑色飛鳥，狠狠墜落在地。"
  },
  AvgDialog_81522_Content_92 = {
    Text = "在卡斯托爾逐漸發黑的視線裡，他看到波呂克斯一步步走向于麗埃特，乖順地低下頭行禮。"
  },
  AvgDialog_81522_Content_93 = {
    Text = "教主大人，請您見證我對持燈者的虔誠。"
  },
  AvgDialog_81522_Content_94 = {
    Text = "毫髮未損的于麗埃特笑著摸了摸波呂克斯的頭，而後分給了卡斯托爾一瞬憐憫的目光。"
  },
  AvgDialog_81522_Content_95 = {
    Text = "四周的燈衛圍攏過來，將沉重的鎖鏈捆上卡斯托爾的翅膀與身體。"
  },
  AvgDialog_81522_Content_96 = {
    Text = "一切肉與骨的疼痛都離卡斯托爾遠去了，卡斯托爾的胸口像是生長出了一個巨大的空洞，將他一點點拖入了孤獨而空虛的黑暗。"
  },
  AvgDialog_81522_Content_97 = {
    Text = "一切肉與骨的疼痛都離卡斯托爾遠去了，卡斯托爾的胸口像是生長出了一個巨大的空洞，將他一點點拖入了孤獨而空虛的黑暗。"
  },
  AvgDialog_81522_Content_98 = {
    Text = "在陷入昏迷前的最後一刻，卡斯托爾於黑暗中茫然地回想著。"
  },
  AvgDialog_81522_Content_99 = {
    Text = "他回想起波呂克斯將手洞穿自己胸口的那一刻，他看到那張冰冷的面龐上滑落了一滴晶瑩的淚珠。"
  },
  AvgDialog_81523_Content_1 = {Text = "標本"},
  AvgDialog_81523_Content_10 = {
    Text = "他們大概五六人，最多十來人，運著五口一人長、半人寬的大箱子。"
  },
  AvgDialog_81523_Content_100 = {
    Text = "可是，為什麼白天時城裡的居民都毫無異樣？"
  },
  AvgDialog_81523_Content_101 = {
    Text = "小鳥兒，你聽說過會長出陷阱、捕捉昆蟲的植物嗎？"
  },
  AvgDialog_81523_Content_102 = {
    Text = "這座城仍然在吸引新的獵物進入，這些被寄生的人依舊渴望著繁衍，渴望著新鮮的血肉、新的同伴。"
  },
  AvgDialog_81523_Content_103 = {
    Text = "就像它們還是人類時，渴望更多的來客進入這座貿易之城。"
  },
  AvgDialog_81523_Content_104 = {
    Text = "他們跟隨日光的節律生活、沉眠，當那殘留的意識徹底睡去，枝條就會接管那些軀體。"
  },
  AvgDialog_81523_Content_105 = {
    Text = "這就是為什麼我說那支商隊一定還在城裡。他們無法離開，它會吞噬一切。"
  },
  AvgDialog_81523_Content_107 = {
    Text = "萬千怪物循著簡單的本能行動，不可驚醒、不可擾動。"
  },
  AvgDialog_81523_Content_108 = {
    Text = "他們像兩個誤入了亡靈世界的生人，在怪物叢中順流而下又逆流而上，徹夜巡梭。"
  },
  AvgDialog_81523_Content_109 = {
    Text = "卡斯托爾屏住呼吸，繃緊精神搜尋著、漫步著，並時刻害怕會突然聽到波呂克斯的慘叫。"
  },
  AvgDialog_81523_Content_11 = {
    Text = "正在介紹一顆綠松石的攤主抬起頭看了卡斯托爾一眼，又回過頭與泰旖絲對視了一眼。"
  },
  AvgDialog_81523_Content_110 = {
    Text = "終於，在路過第五十一個街口時，他從一扇旅館後門的縫隙中看到了那幾口熟悉的貨箱。"
  },
  AvgDialog_81523_Content_112 = {
    Text = "卡斯托爾與泰旖絲對視一眼，率先鑽入了庭院，院中遊蕩的怪物只是稍微停頓，就對這兩個不速之客失去了興趣。"
  },
  AvgDialog_81523_Content_113 = {
    Text = "（蘇摩利·波利斯。）"
  },
  AvgDialog_81523_Content_114 = {
    Text = "卡斯托爾掀開蓋布摩挲著箱子上金屬刻印的標籤，雙手顫抖著打開一口口箱子上的鎖。"
  },
  AvgDialog_81523_Content_115 = {
    Text = "（不是這一個，也不是這一個……）"
  },
  AvgDialog_81523_Content_116 = {
    Text = "泰旖絲眺望著已經泛白的天際線，回頭輕聲催促。"
  },
  AvgDialog_81523_Content_117 = {
    Text = "快一些，要來不及了。"
  },
  AvgDialog_81523_Content_118 = {
    Text = "卡斯托爾微微一愣，尚未反應過來。就在他將要打開最後的貨箱時，院中突然傳來了一陣枝條與血肉摩擦攪動的聲音。"
  },
  AvgDialog_81523_Content_119 = {
    Text = "陽光灑落，世界甦醒，光暗倒轉。一聲中氣十足的大喝陡然驚醒了整個旅館。"
  },
  AvgDialog_81523_Content_12 = {
    Text = "怎麼？您到底有沒有……"
  },
  AvgDialog_81523_Content_121 = {
    Text = "運送貨物的商隊也發現了他們，與幾個店員打扮的人一起跑來。"
  },
  AvgDialog_81523_Content_122 = {
    Text = "卡斯托爾猛然回頭看向初升的朝陽，終於明白過來，他看向最後的尚未打開的貨箱，又看向來勢洶洶的眾人。"
  },
  AvgDialog_81523_Content_123 = {
    Text = "（既然無法帶著箱子逃脫這些人的追捕，那麼乾脆……）"
  },
  AvgDialog_81523_Content_124 = {
    Text = "那雙羽翼在背後簌簌地抖動，就在他野獸般低伏下脊背，準備再次開啟殺戮之時，泰旖絲拉住了他搖了搖頭。"
  },
  AvgDialog_81523_Content_125 = {
    Text = "不行，他們已經被那顆最初的種子連接在了一起，所有人都是從同一處蔓延的枝椏。"
  },
  AvgDialog_81523_Content_126 = {
    Text = "我無法一次安撫這麼多心臟，貿然動手只會驚醒更多“它”的觸角。"
  },
  AvgDialog_81523_Content_127 = {
    Text = "我們先離開，找到機會再回來，至少白天不會有太多危險。"
  },
  AvgDialog_81523_Content_128 = {
    Text = "卡斯托爾看向近在咫尺的貨箱，最終在追兵的叫喊聲中，跟隨泰旖絲離開了旅館。"
  },
  AvgDialog_81523_Content_13 = {
    Text = "卡斯托爾焦急的神色中透出一絲迷茫，攤主掩著嘴，發出一連串清脆的笑聲，連泰旖絲都忍不住無奈地笑了。"
  },
  AvgDialog_81523_Content_130 = {
    Text = "當一個人死而復生是什麼感覺？"
  },
  AvgDialog_81523_Content_131 = {
    Text = "波呂克斯從未想過自己會體驗這些滋味，他在睡夢中陷入了一片黑暗的混沌，陷入了彷彿母親子宮般包裹著他的狹小空間。"
  },
  AvgDialog_81523_Content_132 = {
    Text = "無法動彈、無法甦醒，但不知為何，他卻在懶洋洋的安心中繼續朦朧地睡去，就像發自內心接受了甘美的死亡。"
  },
  AvgDialog_81523_Content_133 = {
    Text = "難道是神明要自己就這樣結束，就這樣回歸潔淨的極樂之土？\n那麼他會感激跪伏著，承接這道溫柔的旨意。"
  },
  AvgDialog_81523_Content_134 = {
    Text = "但，偉大的純銀塑身者啊，為何這樣的永恆寧靜之地會有如此喧囂的噪音，難道那是自己未贖清的罪孽？"
  },
  AvgDialog_81523_Content_135 = {
    Text = "波呂克斯睜開眼睛，看到的卻不是想像中的無垢淨土，而是頭頂幾張飽經風沙摧殘的面龐。"
  },
  AvgDialog_81523_Content_136 = {
    Text = "剛剛檢查完其他箱子的商隊成員睜著幾雙充滿困惑的眼睛，直直對上了箱子裡波呂克斯同樣茫然的雙眼。"
  },
  AvgDialog_81523_Content_14 = {
    Text = "這位客人，你看看周圍，你都看見了什麼？"
  },
  AvgDialog_81523_Content_15 = {
    Text = "看見了……繁榮的貿易？"
  },
  AvgDialog_81523_Content_16 = {
    Text = "對呀，這地方，最不缺的就是商人，每天來來往往的商隊那麼多，你的商隊早就像一粒沙子掉進沙漠裡——"
  },
  AvgDialog_81523_Content_17 = {
    Text = "唰！不見囉！"
  },
  AvgDialog_81523_Content_18 = {
    Text = "攤主攤開手掌，表情誇張地吹掉了浮塵，卡斯托爾卻沒有被她的玩笑逗笑。"
  },
  AvgDialog_81523_Content_19 = {
    Text = "那無法掌控一切的焦慮又從心中湧出，他不死心，又沿路挨個攤子問了過去。"
  },
  AvgDialog_81523_Content_2 = {
    Text = "金子般的晨光灑在街道，這座城和它的居民已經醒來，數不清的攤販陸陸續續支起了五顏六色的篷布。"
  },
  AvgDialog_81523_Content_20 = {
    Text = "沒有，沒見過。"
  },
  AvgDialog_81523_Content_21 = {
    Text = "好像有這麼一夥人吧，又好像不是……"
  },
  AvgDialog_81523_Content_22 = {
    Text = "哦！應該是路過過這裡。去哪了？那我哪知道，我又沒跟蹤人家！"
  },
  AvgDialog_81523_Content_23 = {
    Text = "直到他再也得不到半點有用的消息，一直跟在他身後的泰旖絲才平靜開口。"
  },
  AvgDialog_81523_Content_24 = {
    Text = "別擔心，放鬆點，那支商隊一定還在這裡。"
  },
  AvgDialog_81523_Content_25 = {
    Text = "可如果在我找到他們之前，他們就要離開了呢？這座城市太大了……"
  },
  AvgDialog_81523_Content_26 = {
    Text = "卡斯托爾無力地望向一座座色彩斑斕的帳篷，一棟棟沙石堆砌的小樓。"
  },
  AvgDialog_81523_Content_27 = {
    Text = "（這裡比教會的據點大上幾十倍，然而我們逃出小小的教會就已經用了許多年……）"
  },
  AvgDialog_81523_Content_28 = {
    Text = "一個很簡單的道理：即使是夜行的銀蜥，在白日裡也會安靜地匍匐在沙堆之下。"
  },
  AvgDialog_81523_Content_29 = {
    Text = "既然你說那是一支肩負重任的商隊，那他們一定會選擇更加昂貴、安靜、私密的旅館休息。"
  },
  AvgDialog_81523_Content_3 = {
    Text = "城市豐沛的水源吸引了許多部落聚集在周圍，沒有客商到來的日子，這裡的市集依舊熱鬧非凡。"
  },
  AvgDialog_81523_Content_30 = {
    Text = "這樣的旅館，在柯雷尼也不會超過十家。"
  },
  AvgDialog_81523_Content_31 = {
    Text = "卡斯托爾閉上眼睛，默默計算著搜尋的計劃。"
  },
  AvgDialog_81523_Content_32 = {
    Text = "你說得對，是我太心急了。"
  },
  AvgDialog_81523_Content_33 = {
    Text = "（耐心，卡斯托爾，再耐心一點。）"
  },
  AvgDialog_81523_Content_34 = {
    Text = "他攥緊拳頭，不住勸告自己。"
  },
  AvgDialog_81523_Content_36 = {
    Text = "然而幸運之神並沒有輕易眷顧於他，一直到夕陽西下，他們仍舊沒有找到那支商隊的蹤影。"
  },
  AvgDialog_81523_Content_37 = {
    Text = "如果我知道更多商隊的資訊……"
  },
  AvgDialog_81523_Content_38 = {
    Text = "卡斯托爾一拳捶上了路邊沙土砌成的牆面。"
  },
  AvgDialog_81523_Content_39 = {
    Text = "噓，雖然是哥哥，但你與你弟弟是差不多一起出生的吧？"
  },
  AvgDialog_81523_Content_4 = {
    Text = "珍珠，珍珠，天上少有，地下難尋的深海大珍珠！"
  },
  AvgDialog_81523_Content_40 = {
    Text = "一個人把所有東西都背在身上，只會被疲憊壓垮哦。"
  },
  AvgDialog_81523_Content_41 = {
    Text = "或許是泰旖絲那無限包容的神情讓他感到了某種陌生的安心，卡斯托爾再次平靜下來，他抬起頭，露出了某種倔強如石頭般的眼神。"
  },
  AvgDialog_81523_Content_42 = {
    Text = "……不會的，在他獲得自由以前，我都不會倒下的。"
  },
  AvgDialog_81523_Content_43 = {
    Text = "那麼，這位堅強的哥哥，該找個地方稍微休息一下了。"
  },
  AvgDialog_81523_Content_44 = {
    Text = "泰旖絲安撫地摸了摸卡斯托爾的頭，看向隨著天光暗淡而逐漸冷清下來的城市。"
  },
  AvgDialog_81523_Content_46 = {
    Text = "二人挨著未排查過的城南找了一家旅館，即將踏進店門的時候，夜幕剛好降臨。"
  },
  AvgDialog_81523_Content_47 = {
    Text = "白天的熱鬧市集已經散場，滿街的喧鬧聲不再，取而代之的是一種徹底的寂靜。"
  },
  AvgDialog_81523_Content_48 = {
    Text = "卡斯托爾有些狐疑地看了看門外，終於走近了旅館已點上燭火的櫃檯。"
  },
  AvgDialog_81523_Content_49 = {
    Text = "您好，我們要兩個房間。"
  },
  AvgDialog_81523_Content_5 = {
    Text = "烤餅，烤肉，嫩嫩的烤羊羔嘞！"
  },
  AvgDialog_81523_Content_50 = {
    Text = "低垂著頭似乎正在打盹的店老闆無動於衷，彷彿靜止在了香甜的夢中。"
  },
  AvgDialog_81523_Content_51 = {
    Text = "貌似沒有住客的旅館同樣籠罩在絕對的安靜中，只有燭火嗶啵燃燒的聲響靜悄悄持續。"
  },
  AvgDialog_81523_Content_52 = {
    Text = "卡斯托爾回頭看了一眼泰旖絲，在對方“小心”的眼神中點了點頭，一步步走向櫃檯後的店老闆。"
  },
  AvgDialog_81523_Content_54 = {
    Text = "卡斯托爾伸出一隻手，緩緩靠近了熟睡中的男人的鼻子。"
  },
  AvgDialog_81523_Content_55 = {
    Text = "他的手指離那只隆起駝峰的鼻子越來越近、越來越近。"
  },
  AvgDialog_81523_Content_56 = {
    Text = "終於，他感到一股細微的氣流輕輕打在了他的手上。"
  },
  AvgDialog_81523_Content_57 = {
    Text = "他還活著。"
  },
  AvgDialog_81523_Content_58 = {
    Text = "卡斯托爾略鬆了一口氣回過頭去，卻看到泰旖絲驟然縮小的瞳孔。"
  },
  AvgDialog_81523_Content_59 = {Text = "退後！"},
  AvgDialog_81523_Content_6 = {
    Text = "人流如梭，從日常的吃穿用度，到稀罕的香料、飾品、手工織就的毛毯披肩，這裡包羅萬象、應有盡有。"
  },
  AvgDialog_81523_Content_60 = {
    Text = "一陣令人作嘔的吞嚥嘔吐聲從背後響起，卡斯托爾堪堪回過頭去。幾根沾染著血肉的漆黑枝條，正從男人的七竅中蔓延而出。"
  },
  AvgDialog_81523_Content_62 = {
    Text = "堪堪避開狂亂舞動的枝條，在泰旖絲的指示下，卡斯托爾一擊將怪物的心臟險險挖出。"
  },
  AvgDialog_81523_Content_63 = {
    Text = "他驚魂未定地盯著那具血肉模糊的屍體，反覆確認終結了這個詭異的生物。"
  },
  AvgDialog_81523_Content_65 = {
    Text = "卡斯托爾注視著泰旖絲從那顆心臟中剖出的，彷彿根莖一樣密密麻麻盤虯的枝條，艱難地忍下想要嘔吐的衝動。"
  },
  AvgDialog_81523_Content_66 = {
    Text = "他已經習慣了提燈教會血腥的儀式，但這是他第一次親自動手殺人。"
  },
  AvgDialog_81523_Content_67 = {
    Text = "（可是……那種存在真的還算是人類嗎？）"
  },
  AvgDialog_81523_Content_68 = {
    Text = "泰旖絲沾滿鮮血的手輕輕拂過屍體的臉，將那雙渾濁的眼睛閉上。"
  },
  AvgDialog_81523_Content_69 = {
    Text = "現在，所有的一切，你該給我一個解釋了吧。"
  },
  AvgDialog_81523_Content_7 = {
    Text = "卡斯托爾跟著泰旖絲走過了十幾家攤子，一直到對方已經開始挑看寶石的時候，卡斯托爾才從眼花繚亂中反應過來，急忙擠上前詢問攤主。"
  },
  AvgDialog_81523_Content_70 = {
    Text = "我會的，別著急。你想知道的一切，我都會告訴你。"
  },
  AvgDialog_81523_Content_71 = {
    Text = "泰旖絲捧起那團仍然在扭動著、似乎在尋找新的宿主的根莖，輕柔地一下下安撫著它。"
  },
  AvgDialog_81523_Content_72 = {
    Text = "彷彿哭鬧的孩童找到了母親的懷抱，那張牙舞爪的根莖漸漸靜止下來，又時光倒流一般縮小，回歸成了一小節漆黑的樹枝。"
  },
  AvgDialog_81523_Content_73 = {
    Text = "這是母樹的枝條。"
  },
  AvgDialog_81523_Content_74 = {
    Text = "這座城裡的人身上，大概都已遍佈了這樣的枝條。"
  },
  AvgDialog_81523_Content_75 = {
    Text = "泰旖絲近乎悲憫地閉上眼睛，雙手泛起奇異的輝光。"
  },
  AvgDialog_81523_Content_76 = {
    Text = "那漆黑的枝條慢慢褪去顏色，變得透明、柔軟，彷彿一塊無色的胚胎，又慢慢地融化成了一小汪清澈的水。"
  },
  AvgDialog_81523_Content_77 = {
    Text = "此時旅館外原本寂靜的街道上傳來一群群拖沓的腳步聲，無數吞嚥嘔吐著枝條的聲音漸次響起，彷彿鬼怪扭曲的嚎叫，正逐漸向旅館靠近。"
  },
  AvgDialog_81523_Content_78 = {
    Text = "昏暗的燭光下，泰旖絲面無表情地舉起那一捧小小的水，伸向卡斯托爾面前。"
  },
  AvgDialog_81523_Content_8 = {
    Text = "請問，最近您有見到一個外來的商隊嗎？"
  },
  AvgDialog_81523_Content_81 = {
    Text = "所以，它們來自一枚你曾經散播出去的種子，現在那枚種子失控了，因此你來到了這裡……"
  },
  AvgDialog_81523_Content_82 = {
    Text = "卡斯托爾坐在旅館的蒲團上，試圖用理性的思考壓住喝下那團不明液體的噁心感，但他蒼白的臉色顯示這並不怎麼奏效。"
  },
  AvgDialog_81523_Content_83 = {
    Text = "自從母樹被侵蝕後，我的存在和力量就一直在衰弱，許多曾經為了繁育而散播之物，也隨母樹一起失控、墮落了。"
  },
  AvgDialog_81523_Content_84 = {
    Text = "母樹回歸聖河之後，我在沉睡中聽到了它們痛苦的呼喚，所以我再次醒來，來帶走它們，讓它們也一同回歸母體、回歸聖河。"
  },
  AvgDialog_81523_Content_85 = {
    Text = "卡斯托爾頓了頓，沒有繼續追問所謂的“母體”與泰旖絲的關係。"
  },
  AvgDialog_81523_Content_86 = {
    Text = "所以你要用剛剛的方式，去……處理整個城市的居民？"
  },
  AvgDialog_81523_Content_87 = {
    Text = "不，剛剛那只是為了賜予你母樹的氣息，讓它們將你當作同伴。"
  },
  AvgDialog_81523_Content_88 = {
    Text = "泰旖絲靜靜走到旅館的門邊，看著外面因失去活人氣息而繼續盲目徘徊的寄生怪物們。"
  },
  AvgDialog_81523_Content_89 = {
    Text = "我當時在此地種下的種子只有一顆，剩下的，都是它繁衍出的枝條。"
  },
  AvgDialog_81523_Content_9 = {
    Text = "卡斯托爾伸出手，有些笨拙地比劃著。"
  },
  AvgDialog_81523_Content_90 = {
    Text = "我要找到那顆種子，就像你要找到你的弟弟。那是我們的使命。"
  },
  AvgDialog_81523_Content_91 = {
    Text = "剛剛你說……氣息？如果它們感受到了活人的氣息會怎麼樣？"
  },
  AvgDialog_81523_Content_92 = {
    Text = "它們始終活在飢渴之中，夜晚就是它們獵食的時間。或者吞噬、融合，或者，將人變成它們的同伴。"
  },
  AvgDialog_81523_Content_93 = {
    Text = "卡斯托爾騰地站了起來。"
  },
  AvgDialog_81523_Content_94 = {
    Text = "必須現在就去找波呂克斯。那顆藥的效用已經快要消散了，他隨時有可能醒過來！"
  },
  AvgDialog_81523_Content_96 = {
    Text = "二人沉默著在夢遊般遊蕩的怪物中間穿行。"
  },
  AvgDialog_81523_Content_97 = {
    Text = "卡斯托爾小心地不發出聲響，避開怪物身上一條條蠕動著滴落不明液體的漆黑樹枝。"
  },
  AvgDialog_81523_Content_98 = {
    Text = "他看到一張張白天似乎見過的熟悉的面孔，他們中的許多還曾與卡斯托爾說過話。"
  },
  AvgDialog_81523_Content_99 = {
    Text = "此刻他們卻佝僂著背，眼白亂翻，嘴巴張到人類不可能的極限，發出陣陣無意識的詭異低吼。"
  },
  AvgDialog_81524_Content_10 = {
    Text = "終於，他聽到那道輕輕起伏的呼吸聲，慢慢地消失了。"
  },
  AvgDialog_81524_Content_101 = {
    Text = "一道咒術爆炸的聲響響徹狹窄的山洞，一串血花與純黑的羽毛從那揚起的翅膀上淋漓地飛散。"
  },
  AvgDialog_81524_Content_103 = {
    Text = "卡斯托爾向前撲倒，劇痛從骨肉模糊的血洞中席捲全身，那雙翅膀控制不住地痙攣蜷縮起來。"
  },
  AvgDialog_81524_Content_104 = {
    Text = "不要再掙扎了，聖子大人，您永遠也無法離開的！"
  },
  AvgDialog_81524_Content_105 = {
    Text = "在身後燈衛得意的呼喊中，卡斯托爾顫抖著爬起，繼續向前邁動了一步。"
  },
  AvgDialog_81524_Content_106 = {
    Text = "……不，沒有什麼永遠。"
  },
  AvgDialog_81524_Content_107 = {
    Text = "鮮血流過他所行的路，他抬起低垂的頭，看向那團近在咫尺的白色光暈，從一貫沉默的喉嚨中扯出一聲極憤怒的嘶吼。"
  },
  AvgDialog_81524_Content_108 = {
    Text = "（自由的光……洞口，就在這裡了——）"
  },
  AvgDialog_81524_Content_109 = {
    Text = "卡斯托爾怒吼著，拼命向前縱身一躍。在身後眾人的驚呼聲中，他直直墜下山崖。"
  },
  AvgDialog_81524_Content_110 = {
    Text = "世界如從破碎的魚缸之外忽然浮現，萬物在陽光的映照下豁然清晰，盡數倒映在他寂寞已久的瞳孔。\n彷彿多年以前，他和過去的波呂克斯第一次躍上天空的那一刻。"
  },
  AvgDialog_81524_Content_111 = {
    Text = "（森林、雪山、天空與雲層，還有風……）"
  },
  AvgDialog_81524_Content_113 = {
    Text = "在高空凜冽的寒風中，一對黑色的羽翼再次張開，一隻鳥兒迎著風，歪歪扭扭地撲扇著，向遠方飛去。"
  },
  AvgDialog_81524_Content_12 = {
    Text = "卡斯托爾走過了一個個轉角與岔路，避過了一個個暗中的哨崗，他的腳步時行時停，卻沒有任何遲疑。"
  },
  AvgDialog_81524_Content_13 = {
    Text = "為了這一天，他已經準備了太久太久。"
  },
  AvgDialog_81524_Content_14 = {
    Text = "聖子大人……你們這是？"
  },
  AvgDialog_81524_Content_15 = {
    Text = "卡斯托爾扶著低垂著頭的波呂克斯，十分鎮靜地看了巡邏的燈衛一眼。"
  },
  AvgDialog_81524_Content_16 = {
    Text = "我弟弟腹中不適，要去一下盥洗室。明天你去查一下負責準備今天菜餚的人，看看是什麼地方出了問題。"
  },
  AvgDialog_81524_Content_18 = {
    Text = "一步、兩步，卡斯托爾的步伐沒有一絲慌亂，呼吸亦沒有一絲顫抖。"
  },
  AvgDialog_81524_Content_19 = {
    Text = "他穩穩地走向了長廊的盡頭，走向了他心中從不曾熄滅的那個願望。"
  },
  AvgDialog_81524_Content_2 = {
    Text = "夜晚的寢宮落針可聞，所有的侍從都已離開，這裡已沒有了那遍布的一雙雙眼睛。"
  },
  AvgDialog_81524_Content_21 = {
    Text = "提燈教會\n地下貨倉"
  },
  AvgDialog_81524_Content_22 = {
    Text = "提燈教會如今雖然隱藏在不為人知的暗面，但憑藉亞塔納西奧斯家族取之不竭的財富與勢力，提燈的觸手依然蔓延向了世界各地。"
  },
  AvgDialog_81524_Content_23 = {
    Text = "他們隱藏在一個又一個企業與基金會後面，資助合作著一個又一個“降神”的試驗對象。"
  },
  AvgDialog_81524_Content_24 = {
    Text = "這些即將發送給各個合作夥伴的貨箱之中，有的是俗氣的金銀現金，有的是禁忌詭異的實驗材料，而有的甚至裝有不明的活物。"
  },
  AvgDialog_81524_Content_26 = {
    Text = "卡斯托爾路過一個個氣味莫名的箱子，忽略了角落之中偶爾傳來的詭異聲響。"
  },
  AvgDialog_81524_Content_27 = {
    Text = "終於，他的腳步在一排貨箱前停了下來，那些厚重的箱子上貼有一個小小的標籤，上面寫著——"
  },
  AvgDialog_81524_Content_28 = {
    Text = "蘇摩利·波利斯……"
  },
  AvgDialog_81524_Content_29 = {
    Text = "在他看過的為數不多的書籍中，關於沙漠的描述只有寥寥幾筆，那裡有無盡的金色沙礫，有酷熱的烈陽與長滿尖刺的植物。"
  },
  AvgDialog_81524_Content_3 = {
    Text = "這一直是雙子最為自由、最為快樂的秘密時間，至少曾經是。"
  },
  AvgDialog_81524_Content_30 = {
    Text = "那裡荒無人煙，原本不是適宜生存之地，但在那罕有的綠洲之中，卻奇蹟般聚集著璀璨的文明與城池。"
  },
  AvgDialog_81524_Content_31 = {
    Text = "只有這裡，只有這裡能暫時逃脫他們的視線，只有這樣，才能讓現在的波呂克斯跟我離開……"
  },
  AvgDialog_81524_Content_32 = {
    Text = "他呢喃著，輕柔地將身體冰冷的波呂克斯放入了其中一個貨箱之中。"
  },
  AvgDialog_81524_Content_33 = {
    Text = "會隨著風遷徙的蓬草，背上隆起山峰的駱駝，傳說中庇佑生靈的母樹，流滿了清澈甘泉的綠洲……"
  },
  AvgDialog_81524_Content_34 = {
    Text = "那麼多我們沒有見過的東西……你一定會喜歡的，對嗎？"
  },
  AvgDialog_81524_Content_36 = {
    Text = "無聲的腳步一步步走向寢宮，在明日一早貨物發出之前，卡斯托爾必須拖住教眾，確保波呂克斯被成功送出。"
  },
  AvgDialog_81524_Content_37 = {
    Text = "一旦在此之前暴露，弟弟被從貨箱中搜出只會是時間問題。"
  },
  AvgDialog_81524_Content_38 = {
    Text = "（這是最後的機會，絕對不能出錯。）"
  },
  AvgDialog_81524_Content_39 = {
    Text = "啊呀，卡斯托爾……大人，如此深夜之中，您在這裡幹什麼呢？"
  },
  AvgDialog_81524_Content_40 = {
    Text = "未曾預料過的人突然出現在了轉角之後，一雙細細的蛇瞳探究地盯住了卡斯托爾。"
  },
  AvgDialog_81524_Content_41 = {
    Text = "……波呂克斯有些睡不著，讓我出來為他找些熱牛奶喝。"
  },
  AvgDialog_81524_Content_42 = {
    Text = "原來如此，在睡夢時刻還要指使您，那位大人還真是一如既往的任性啊。"
  },
  AvgDialog_81524_Content_43 = {
    Text = "只是為弟弟做些事而已，沒有什麼任不任性的，如果沒有什麼事，我就告辭了，阿爾比諾大人。"
  },
  AvgDialog_81524_Content_44 = {
    Text = "卡斯托爾平靜地點了點頭，與阿爾比諾擦肩而過。"
  },
  AvgDialog_81524_Content_45 = {
    Text = "若有所思的蛇人望著他的背影，而後轉身看向了卡斯托爾來時的方向，頗有些愉悅地吐了吐猩紅的蛇信。"
  },
  AvgDialog_81524_Content_46 = {
    Text = "那個方向麼，呵呵……"
  },
  AvgDialog_81524_Content_49 = {
    Text = "二位聖子大人，該起床梳洗了。"
  },
  AvgDialog_81524_Content_5 = {
    Text = "熟睡的波呂克斯翻了個身，在他悠長輕緩的呼吸聲中，一道黑影靜靜出現在他的床頭，在他的臉上投下一片陰影。"
  },
  AvgDialog_81524_Content_50 = {
    Text = "精準如鬧鐘的侍女準時出現在了寢宮之中，向著二人的床榻走來。"
  },
  AvgDialog_81524_Content_51 = {
    Text = "噓……不要說話。"
  },
  AvgDialog_81524_Content_52 = {
    Text = "卡斯托爾坐在波呂克斯的床邊，回頭瞪視著侍女，發出嚴肅的氣聲。"
  },
  AvgDialog_81524_Content_53 = {
    Text = "……卡斯托爾大人？"
  },
  AvgDialog_81524_Content_54 = {
    Text = "波呂克斯昨晚腹痛一夜，我剛剛把他哄睡著，不要吵到他。"
  },
  AvgDialog_81524_Content_55 = {
    Text = "腹痛？怎麼會，昨日一整天都還好好的……"
  },
  AvgDialog_81524_Content_56 = {
    Text = "侍女看向了床榻上隆起的輪廓，那被角外露出了一片波呂克斯的衣袍，她猶疑一瞬，還要繼續上前。"
  },
  AvgDialog_81524_Content_57 = {
    Text = "退下，無禮之人，我尚且沒有追究你們的問題。"
  },
  AvgDialog_81524_Content_58 = {
    Text = "卡斯托爾的眉頭嚴厲地皺起，那一向沉默木訥的臉竟破天荒顯得冷酷起來。"
  },
  AvgDialog_81524_Content_59 = {
    Text = "若是你們之中有人包藏禍心，想要謀害聖子，你們每個人都有包庇兇手的可能。"
  },
  AvgDialog_81524_Content_60 = {
    Text = "如果波呂克斯真的出了什麼事……你們恐怕也不會想要體驗凌遲剖心的刑罰。"
  },
  AvgDialog_81524_Content_61 = {Text = "這……"},
  AvgDialog_81524_Content_62 = {
    Text = "我昨晚已經吩咐一個燈衛去排查此事，去，找到他，一定要查清昨日的飲食有什麼問題。"
  },
  AvgDialog_81524_Content_63 = {
    Text = "侍女被卡斯托爾教訓得愣在原地，她的額角冒出冷汗，終於馴服地低下頭顱。"
  },
  AvgDialog_81524_Content_64 = {
    Text = "遵從您的吩咐，但二位大人今天的安排……"
  },
  AvgDialog_81524_Content_65 = {
    Text = "將上午的修行先取消，我會親自去找阿爾比諾大人說明，一切以波呂克斯的身體為先。"
  },
  AvgDialog_81524_Content_66 = {
    Text = "你去找到教會的醫生，讓他兩個小時之後準時來給波呂克斯看病，早一分、晚一分都不行。"
  },
  AvgDialog_81524_Content_67 = {
    Text = "至於現在，你們都暫時退下吧，波呂克斯需要休息。"
  },
  AvgDialog_81524_Content_69 = {
    Text = "沒有鐘錶，就用默數，在無數枯燥的日夜中，計時已經成為雙子的某種本能。"
  },
  AvgDialog_81524_Content_7 = {
    Text = "（他如今雖然脾氣驕縱，但睡著的時候，還是和以前的樣子沒什麼區別。）"
  },
  AvgDialog_81524_Content_70 = {
    Text = "在說服侍從離開後，卡斯托爾獲得了寶貴的喘息時間，但這一切只是暫時的。"
  },
  AvgDialog_81524_Content_71 = {
    Text = "此刻他一副關切的模樣坐在波呂克斯的床邊，時不時整理被角，安撫著熟睡的“弟弟”。"
  },
  AvgDialog_81524_Content_72 = {
    Text = "十分鐘，二十分鐘，半個小時。"
  },
  AvgDialog_81524_Content_73 = {
    Text = "（拖得越久，教會中有人起疑的可能便越大。）"
  },
  AvgDialog_81524_Content_74 = {
    Text = "那所謂的兩個小時休息時間，同樣只是一個掩人耳目的幌子。"
  },
  AvgDialog_81524_Content_75 = {
    Text = "（按照慣例，此刻貨物已經離開教會有一段距離了。）"
  },
  AvgDialog_81524_Content_76 = {
    Text = "卡斯托爾不再猶豫，他立刻起身，避開耳目離開了寢宮。"
  },
  AvgDialog_81524_Content_77 = {
    Text = "在腦海中演練過無數遍的路線此刻變成了現實。"
  },
  AvgDialog_81524_Content_78 = {Text = "迴廊。"},
  AvgDialog_81524_Content_79 = {Text = "祭壇。"},
  AvgDialog_81524_Content_8 = {
    Text = "卡斯托爾緩緩打開了從卡納克手中得到的盒子，他拿出了那一顆黑色的藥丸，將它放入了波呂克斯的口中。"
  },
  AvgDialog_81524_Content_80 = {
    Text = "甚至山體中的水道。"
  },
  AvgDialog_81524_Content_82 = {
    Text = "精準、乾脆，如同機械的行動，極力穩定卻越發激烈的脈搏。"
  },
  AvgDialog_81524_Content_83 = {
    Text = "在快速的奔跑中，卡斯托爾的血液在燃燒，他的心臟好像就要從喉嚨裡跳出來。"
  },
  AvgDialog_81524_Content_85 = {
    Text = "他大口喘著氣，似乎已經從空氣中品味出了一絲屬於自由的香甜。"
  },
  AvgDialog_81524_Content_87 = {
    Text = "一陣難以抵抗的眩暈令卡斯托爾踉蹌了一下，遠處傳來模糊的呢喃，這是提燈用以攻擊精神的咒文，他們追來了。"
  },
  AvgDialog_81524_Content_88 = {
    Text = "沒關係，他們還沒有追上，只要在那之前……"
  },
  AvgDialog_81524_Content_89 = {
    Text = "他離道路盡頭的出口已經很近了，只要再鑽過一個窄洞、轉過一個彎，再爬上一個陡坡。"
  },
  AvgDialog_81524_Content_9 = {
    Text = "只一瞬間，那小小的藥丸便如同一縷煙一樣融化消失。他如同一位耐心的獵手一樣，繼續安靜地等待、等待著。"
  },
  AvgDialog_81524_Content_91 = {
    Text = "卡斯托爾像一隻瀕死的鳥，費力扇動的翅膀不停撞擊著牆壁。"
  },
  AvgDialog_81524_Content_92 = {
    Text = "眼睛看不清了就用耳朵聽，耳朵聽不見了就用四肢去觸摸。"
  },
  AvgDialog_81524_Content_93 = {
    Text = "他手腳並用，跌跌撞撞地拼命向前奔去、爬去。"
  },
  AvgDialog_81524_Content_94 = {
    Text = "那不遠處的山洞出口在他眼中已經融化成了一團虛幻的白光，吸引著他不斷向前。"
  },
  AvgDialog_81524_Content_97 = {
    Text = "在那裡！"
  },
  AvgDialog_81524_Content_98 = {
    Text = "身後傳來了燈衛的聲音，他全然不顧，繼續向前奔跑著。"
  },
  AvgDialog_81524_Content_99 = {
    Text = "那光芒的終點就要到了，十米、五米……卡斯托爾的翅膀已經張開，他已做好了飛翔的準備。"
  },
  AvgDialog_81525_Content_1 = {
    Text = "飛鳥之心"
  },
  AvgDialog_81525_Content_10 = {
    Text = "得到吩咐的侍女低頭將餐盤撤下離去，卡斯托爾張了張嘴，還是沒有說什麼。"
  },
  AvgDialog_81525_Content_100 = {
    Text = "卡斯托爾望向卡納克逆著月光的面龐，有些分辨不清那張面孔上的神情。"
  },
  AvgDialog_81525_Content_101 = {
    Text = "只有一層淡淡的月光鍍在那身影的輪廓之外，如同神祇降臨。"
  },
  AvgDialog_81525_Content_102 = {
    Text = "現在，你可以開始向你們的純銀神明許願了，聖子殿下，祝你好運。"
  },
  AvgDialog_81525_Content_104 = {
    Text = "怎麼這麼慢才回來，你是去廚房釀酒了嗎？"
  },
  AvgDialog_81525_Content_105 = {
    Text = "卡斯托爾將懷中抱著的酒壺擱在桌面，對橫眉豎眼的弟弟報以歉意的笑。"
  },
  AvgDialog_81525_Content_106 = {
    Text = "抱歉，教主大人一直在與貴客商談，我沒有敢去打擾，不過我為你取來了你愛喝的甜白葡萄酒。"
  },
  AvgDialog_81525_Content_107 = {
    Text = "我就知道，還以為你這塊朽木疙瘩突然發芽了，實際上你還是這麼沒用。"
  },
  AvgDialog_81525_Content_108 = {
    Text = "對不起……"
  },
  AvgDialog_81525_Content_109 = {
    Text = "波呂克斯不滿地哼了一聲，卻也十分識大體地沒有多說什麼，在侍女的侍奉下慢慢喝起酒來。"
  },
  AvgDialog_81525_Content_11 = {
    Text = "（……那其實是我喜歡的。）"
  },
  AvgDialog_81525_Content_110 = {
    Text = "卡斯托爾似是羞赧地低著頭坐在一邊，藏在袖子中的手卻輕輕摩挲著那只繪著精細雕飾的小盒。"
  },
  AvgDialog_81525_Content_111 = {
    Text = "那雕飾繪製著一位羽翼豐滿的天使，正從天國之中悠悠降下，飛往地上的人間。"
  },
  AvgDialog_81525_Content_12 = {
    Text = "弟弟如今已經不記得從前的事，他知道的。"
  },
  AvgDialog_81525_Content_13 = {
    Text = "（都是教會將他變成了現在這樣……無論還要等待多久，我都一定要帶他再次逃出去。）"
  },
  AvgDialog_81525_Content_14 = {
    Text = "他默念著移開了眼，看向寢宮門口捧著禮袍與禮器魚貫而入的侍女。"
  },
  AvgDialog_81525_Content_15 = {
    Text = "（那是出席燃芯儀式時才有的穿著……）"
  },
  AvgDialog_81525_Content_16 = {
    Text = "而從那一次出逃以後，自己與弟弟就再沒有被允許出席任何儀式。"
  },
  AvgDialog_81525_Content_17 = {
    Text = "一旁的波呂克斯放下刀叉，十分矜持地擦了擦嘴，向他投來了鄙夷的目光。"
  },
  AvgDialog_81525_Content_18 = {
    Text = "收起你那呆愣愣的樣子，卡斯托爾，今天教會可是有貴客來訪，不要丟了聖子的臉面。"
  },
  AvgDialog_81525_Content_2 = {
    Text = "雙生的聖子將承接祂的意志，\n讓正義的持燈者降臨人間。"
  },
  AvgDialog_81525_Content_20 = {
    Text = "隨著侍從的指引，卡斯托爾與波呂克斯一路行過無數低頭行禮的教眾，走向了祭壇的最高處。"
  },
  AvgDialog_81525_Content_21 = {
    Text = "鮮少露面的提燈正與來訪的貴賓相談甚歡，露出了愉悅的笑容。"
  },
  AvgDialog_81525_Content_22 = {
    Text = "有了閣下的才華與見地，提燈一定會在您的幫助下與祂更加接近。"
  },
  AvgDialog_81525_Content_23 = {
    Text = "來到他們面前時，一路昂著頭的波呂克斯立刻俯下身去，行了標準的問候禮儀。"
  },
  AvgDialog_81525_Content_24 = {
    Text = "聖子波呂克斯、卡斯托爾，向教主大人與貴客問好。"
  },
  AvgDialog_81525_Content_25 = {
    Text = "慢了半拍的卡斯托爾愣愣地看著那個站在於麗埃特身旁的男人，終於在波呂克斯刀子般的眼神中一起微微俯身。"
  },
  AvgDialog_81525_Content_26 = {
    Text = "卡納克閣下，這就是提燈教會傾盡多年心血的傑作，我們的<Yellow:雙生聖子>。"
  },
  AvgDialog_81525_Content_27 = {
    Text = "哦？真是一樣有趣的……發明啊。"
  },
  AvgDialog_81525_Content_28 = {
    Text = "禮畢，卡斯托爾抬起頭，雙眼與那位衣著氣度異常華貴張揚的男人對視了一瞬。"
  },
  AvgDialog_81525_Content_29 = {
    Text = "在那副充滿玩味的笑容中，卡斯托爾沉默地退至於麗埃特身後，心中卻湧起一種難以抑制的預感。"
  },
  AvgDialog_81525_Content_3 = {
    Text = "那純銀塑身者將帶來無罪的淨土，\n使所有的義人都前往永無苦難的極樂之地。"
  },
  AvgDialog_81525_Content_30 = {
    Text = "請諸位大人入座，<Yellow:燃芯儀式>即將開始。"
  },
  AvgDialog_81525_Content_31 = {
    Text = "那陣鼓噪的衝動緊攥著他的心臟，卡斯托爾卻只得溫順地低垂下頭，安靜旁觀著儀式的進行。"
  },
  AvgDialog_81525_Content_32 = {
    Text = "卡納克與聖子一同坐在高台上，與端坐的兩人不同，男人的姿態慵懶隨意，如一位帝王俯視著台下，也俯視著走入儀式中央的於麗埃特。"
  },
  AvgDialog_81525_Content_33 = {
    Text = "（或許他就是一位帝王呢？）"
  },
  AvgDialog_81525_Content_34 = {
    Text = "今天，又有一位受持燈者感召的<Yellow:燈芯>要回歸無罪無苦的淨土。"
  },
  AvgDialog_81525_Content_35 = {
    Text = "我們齊聚在這裡，共同幫助她完成最後的淨化，將她的靈魂從污濁的塵世中解脫。"
  },
  AvgDialog_81525_Content_36 = {
    Text = "儀式開始，罪人燈滅。"
  },
  AvgDialog_81525_Content_37 = {
    Text = "無數教眾圍成巨大的倒三角，手中的提燈一盞盞熄滅，只留下中央的於麗埃特的提燈亮著，如一隻三角巨眼的瞳孔。"
  },
  AvgDialog_81525_Content_38 = {
    Text = "眾人在於麗埃特的帶領下吟誦著晦澀的神言，而後目送站在三角形最下方的燈芯莊重步入碩大的<Yellow:聖燈>。"
  },
  AvgDialog_81525_Content_39 = {
    Text = "那虔誠的燈芯隨著懺悔毫不猶豫地割開了她的皮肉，淅瀝瀝流下她罪孽的血液。"
  },
  AvgDialog_81525_Content_4 = {
    Text = "AF31@1年\n勒姆瓦希行動後"
  },
  AvgDialog_81525_Content_40 = {
    Text = "我將為你祈福，即將踏上無苦淨土之人。"
  },
  AvgDialog_81525_Content_41 = {
    Text = "令人眩暈的吟誦絮語中，於麗埃特走向聖燈，用手中的提燈點燃了其中混合著點點融蝕漿的血液。"
  },
  AvgDialog_81525_Content_43 = {
    Text = "爆燃的火焰一瞬間照亮了周圍一片黑暗，淒厲的哀嚎從燈芯的疼痛本能中爆發，那燃燒的人形不停在聖燈中翻滾，發出咚咚的撞擊聲。"
  },
  AvgDialog_81525_Content_44 = {
    Text = "光明已至，燃己的燈芯必定得到救贖。"
  },
  AvgDialog_81525_Content_45 = {
    Text = "無數沉默的人影在火光的映照下黑洞洞地搖曳，注視著聖燈之中的人真如燒盡的燈芯一般縮小、蜷曲起來。"
  },
  AvgDialog_81525_Content_46 = {
    Text = "卡納克挑了挑眉毛，忽然轉向了坐在旁邊的卡斯托爾與波呂克斯。"
  },
  AvgDialog_81525_Content_47 = {
    Text = "看起來真疼，如果她這時候後悔了，還能從那裡面出來嗎？"
  },
  AvgDialog_81525_Content_48 = {
    Text = "卡斯托爾愣了一下，波呂克斯像被冒犯到一般略有慍色，但看著卡納克一本正經的表情，也只好勉強扯出一個笑容。"
  },
  AvgDialog_81525_Content_49 = {
    Text = "燈芯皆是得到持燈者感召之人，能夠徹底淨化罪孽是他們求之不得的榮幸。"
  },
  AvgDialog_81525_Content_5 = {
    Text = "一行行身量、步伐別無二致的侍女籠著輕紗，在聖子的寢宮中如梭般安靜穿行。"
  },
  AvgDialog_81525_Content_50 = {
    Text = "很快，在所有人豔羨的目光中，一顆指甲大的銀芯被從殘餘的灰燼中撈起、展示，彷彿一個充滿榮光的好兆頭。"
  },
  AvgDialog_81525_Content_51 = {
    Text = "純銀塑身者已賜下<Yellow:聖軀>，代償了此人的罪孽，此人的靈魂必將進入無罪的淨土，讓我們感激祂的慈悲，願提燈長明。"
  },
  AvgDialog_81525_Content_52 = {
    Text = "願提燈長明！"
  },
  AvgDialog_81525_Content_53 = {
    Text = "卡斯托爾注視著所有人習以為常的一切，那慣有的悲哀此刻卻仍被混亂的思緒牢牢蓋過。"
  },
  AvgDialog_81525_Content_54 = {
    Text = "在教眾們蟲鳴般的狂熱祈禱聲中，他偷偷瞥向那個似笑非笑、甚至顯得有些無聊的男人，心中那宿命般的強烈預感不停叫囂著。"
  },
  AvgDialog_81525_Content_55 = {
    Text = "（這個男人一定能夠改變很多事，或許，他也能改變我和波呂克斯的命運。）"
  },
  AvgDialog_81525_Content_57 = {
    Text = "儀式結束，那位尊貴的客人被于麗埃特邀請，一同前去共進晚餐。"
  },
  AvgDialog_81525_Content_58 = {
    Text = "怎麼，二位聖子不與我們一起嗎？"
  },
  AvgDialog_81525_Content_59 = {
    Text = "聖子們日常隱居清修，他們並不參與教會內的宴會，今天來這裡只是為了瞻仰閣下。"
  },
  AvgDialog_81525_Content_6 = {
    Text = "起居、洗漱、更衣、用飯，聖子的一切都由她們侍奉。"
  },
  AvgDialog_81525_Content_60 = {
    Text = "是了，卡斯托爾和波呂克斯並不會，或者說並不被允許在外面露面太久。"
  },
  AvgDialog_81525_Content_61 = {
    Text = "走在回去寢宮的路上，波呂克斯始終興奮的樣子終於平靜下來，甚至露出了一絲意猶未盡的寂寞。"
  },
  AvgDialog_81525_Content_62 = {
    Text = "晚宴應該很熱鬧吧，真想也去嚐一嚐招待貴賓用的甘酒啊……"
  },
  AvgDialog_81525_Content_63 = {
    Text = "原本這只是一句微不可聞的嘟囔，一路沉默跟在後面的卡斯托爾卻忽然停住了腳步。"
  },
  AvgDialog_81525_Content_64 = {
    Text = "那，我去為你求一些酒來，想必教主大人會通融的。"
  },
  AvgDialog_81525_Content_65 = {
    Text = "幾乎是話音剛落，卡斯托爾就轉頭向著晚宴的方向走了出去，只留下波呂克斯愣在原地，發出小聲的咕噥。"
  },
  AvgDialog_81525_Content_66 = {
    Text = "我就是隨口一說，今天他怎麼這麼殷勤……"
  },
  AvgDialog_81525_Content_68 = {
    Text = "雖然平日裡卡斯托爾非常順從波呂克斯的要求，幾乎到了百依百順的境地，但這一次，他並不是為了他而來的。"
  },
  AvgDialog_81525_Content_69 = {
    Text = "（必須要再見一見那位貴客。）"
  },
  AvgDialog_81525_Content_7 = {
    Text = "無言、遮面、無欲、無求，她們已是最親近聖子的人，卻也同樣是最疏遠聖子的人。"
  },
  AvgDialog_81525_Content_70 = {
    Text = "卡斯托爾止步於宴會大廳之外的角落，此刻他才意識到剛剛那股惑人的衝動多少有些魯莽。"
  },
  AvgDialog_81525_Content_71 = {
    Text = "不能直接闖進宴會，那太突兀了，但等待宴會結束時，教主大人肯定也會一同出現……"
  },
  AvgDialog_81525_Content_72 = {
    Text = "或許應該先打聽一下貴客的行程，再想辦法製造一些偶遇……"
  },
  AvgDialog_81525_Content_73 = {
    Text = "卡斯托爾胡思亂想地喃喃自語著，甚至他自己也說不清為什麼這麼在意那個男人。"
  },
  AvgDialog_81525_Content_74 = {
    Text = "正當他將拳頭攥了又鬆，準備轉身離開的時候，他的身後忽然傳來了那醇厚又飽含笑意的嗓音。"
  },
  AvgDialog_81525_Content_75 = {
    Text = "你是在找我嗎？"
  },
  AvgDialog_81525_Content_76 = {
    Text = "卡斯托爾驚訝地扭過頭去，那位剛剛還縈繞在他腦子裡的貴客就這樣幻覺一樣站在他面前。"
  },
  AvgDialog_81525_Content_77 = {
    Text = "不是幻覺哦。"
  },
  AvgDialog_81525_Content_79 = {
    Text = "彷彿是洞察了卡斯托爾心中那一絲慌張與擔憂，名為卡納克的男人隨手打了一個響指。"
  },
  AvgDialog_81525_Content_8 = {
    Text = "只因尚有罪孽之人，不得污染將呼喚神降臨的靈魂。"
  },
  AvgDialog_81525_Content_81 = {
    Text = "燈火通明、金碧輝煌的廳廊忽然暗淡下來，一層朦朧的輕紗似的光暈籠罩四周，如同二人一齊跌入了夢境的空間。"
  },
  AvgDialog_81525_Content_82 = {
    Text = "放心，沒有人會知道我們的談話的。"
  },
  AvgDialog_81525_Content_83 = {
    Text = "卡斯托爾四下張望了一下，又很快鎮定下來，不知為何他此刻格外相信著這個男人的力量。"
  },
  AvgDialog_81525_Content_84 = {
    Text = "那麼，這場秘密會談可以開始了，這位……尊貴的聖子，你來找我是想做些什麼呢？"
  },
  AvgDialog_81525_Content_86 = {
    Text = "噓，讓我猜猜，你心中有某種強烈的願望，強烈到日日把你焚燒，但又無法找到機會實現……"
  },
  AvgDialog_81525_Content_87 = {
    Text = "卡斯托爾竭力克制著心中的緊張與震撼，不讓自己表露出一絲一毫。"
  },
  AvgDialog_81525_Content_88 = {
    Text = "也許那位客人真的可以洞察人心，但他並沒有說出任何具體的事實，而自己也不會承認任何的猜測。"
  },
  AvgDialog_81525_Content_89 = {
    Text = "我不知道您在說什麼。"
  },
  AvgDialog_81525_Content_9 = {
    Text = "這道菜為什麼與前天的一樣？拿下去，不要再有這樣低級的失誤了。"
  },
  AvgDialog_81525_Content_90 = {
    Text = "男人哼笑了一聲，隨意地聳了聳肩，便緩緩踱步到了廳廊巨大的玻璃窗旁，仰頭欣賞起了月色。"
  },
  AvgDialog_81525_Content_91 = {
    Text = "你誤會了，我無心窺探他人的隱私，畢竟我是一個很尊重他人意願的人。"
  },
  AvgDialog_81525_Content_92 = {
    Text = "你的心告訴我，你早已準備好了一切，雖然你有些許……不善言辭，不過我恰巧也懶得聽一些彎彎繞繞的廢話。"
  },
  AvgDialog_81525_Content_94 = {
    Text = "像在自己的宮殿中閒庭散步一樣的男人回過頭來，向卡斯托爾遞來一個小小的盒子。"
  },
  AvgDialog_81525_Content_95 = {
    Text = "如果你需要的話，我這裡有一些神奇的小玩意兒，或許能夠幫上你的忙，讓你們成為……真正的自己。"
  },
  AvgDialog_81525_Content_96 = {
    Text = "卡斯托爾打開盒子，看到盒中躺著一黑一白兩顆藥丸，如同命運給出的兩個選擇。"
  },
  AvgDialog_81525_Content_97 = {
    Text = "卡納克體貼地向卡斯托爾介紹了藥丸的功用，如此順利、如此善解人意到不可思議，那盒子中的到底是帶來希望的金蘋果，還是魔鬼的蠱惑？"
  },
  AvgDialog_81525_Content_98 = {
    Text = "感激不盡，但……服用如此神奇的寶物，是否有其他的代價呢？"
  },
  AvgDialog_81525_Content_99 = {
    Text = "那就要由你自己判斷了。"
  },
  AvgDialog_81526_Content_1 = {Text = "圍獵"},
  AvgDialog_81526_Content_10 = {
    Text = "他不是本身就在我們的貨箱裡嗎？"
  },
  AvgDialog_81526_Content_100 = {
    Text = "他覺得自己像一隻離巢的鳥，從種種怪物的口中逃離，正全力撲向家的懷抱。"
  },
  AvgDialog_81526_Content_101 = {
    Text = "或許是仁慈的持燈者已聽到了他的祈禱，正在互相搜尋的雙方很快就遙遙看見了對方的身影。"
  },
  AvgDialog_81526_Content_102 = {
    Text = "波呂克斯向那一隊燈衛飛快地跑去，他竭力維持著儀態，不讓自己臉上的欣喜太過誇張。"
  },
  AvgDialog_81526_Content_103 = {
    Text = "我是被迫的，請傳告教主大人，我將剖陳我的忠誠！"
  },
  AvgDialog_81526_Content_104 = {
    Text = "同樣發現了他的燈衛舉起了手中的提燈，似乎正要對他行禮。"
  },
  AvgDialog_81526_Content_105 = {
    Text = "熟悉的地位、尊敬、那些虔誠純粹的信仰，一切他所賴以生存的東西都重新對他敞開了懷抱。"
  },
  AvgDialog_81526_Content_108 = {
    Text = "一道毫不留情的咒術擊中了他，猛烈的劇痛、痙攣讓他像一條擱淺的魚一樣摔倒在地。"
  },
  AvgDialog_81526_Content_11 = {
    Text = "抓住了，我們就多一樣貨物，沒抓住，就說我們不知道這件事，只要我們把東西安全送到……"
  },
  AvgDialog_81526_Content_110 = {
    Text = "波呂克斯艱難地抬起頭，在他難以置信的目光中，那些平日裡從來不可直視他、整日低著頭的燈衛正冷漠地俯視著他。"
  },
  AvgDialog_81526_Content_112 = {
    Text = "他們一步步向他走來，用卑微的雙手舉起了關鎖囚犯與祭品的鎖鏈。"
  },
  AvgDialog_81526_Content_113 = {
    Text = "為什麼……你們不能……我沒有背叛教會！"
  },
  AvgDialog_81526_Content_114 = {
    Text = "他昂著頭，極力辯解，然而那些鎖鏈絲毫沒有停頓，它們帶著冰冷的氣息，伸向了他高貴而脆弱的脖頸。"
  },
  AvgDialog_81526_Content_12 = {
    Text = "……送到哪裡？領隊有些記不清了，總之，只要把貨安全送到，他們的任務就可以結束了。"
  },
  AvgDialog_81526_Content_15 = {
    Text = "波呂克斯緊緊貼在一道陰暗狹窄的小巷之中，盡力收斂狂奔後的呼吸。"
  },
  AvgDialog_81526_Content_16 = {
    Text = "該死的不信者……"
  },
  AvgDialog_81526_Content_17 = {
    Text = "他悄悄探出半隻眼睛，用餘光瞥著那些愚蠢的力夫跑遠，終於長長吐出一口氣。"
  },
  AvgDialog_81526_Content_18 = {
    Text = "我明明好好地在寢宮睡覺，為什麼醒來會……"
  },
  AvgDialog_81526_Content_19 = {
    Text = "他思索著死而復生前後的記憶，仍然不知道自己是如何來到現在的境地的。但關於這一切的始作俑者，對他來說卻並不難猜測。"
  },
  AvgDialog_81526_Content_2 = {
    Text = "波呂克斯猛地從貨箱中坐起，彈射一般翻出了箱子。"
  },
  AvgDialog_81526_Content_20 = {
    Text = "除了我那冥頑不靈的兄弟，還有誰有必要將我千里迢迢地帶到這種鬼地方。"
  },
  AvgDialog_81526_Content_21 = {
    Text = "波呂克斯瞇起眼，露出一個譏諷的笑容，沒等他的嘴角完全舒展，久未進食的腹中便傳來一陣雷鳴般的轟鳴。"
  },
  AvgDialog_81526_Content_23 = {
    Text = "算了，比起揣摩他的木頭腦子，現在還有更要緊的事。"
  },
  AvgDialog_81526_Content_24 = {
    Text = "他直起身，施施然撣了撣衣服上的褶皺，仔細整理好了跑亂的鬢髮，這才昂著下巴走出了小巷。"
  },
  AvgDialog_81526_Content_25 = {
    Text = "波呂克斯邁著每一步都精確到同樣距離的步伐，他的神情倨傲而冷淡，緩緩行走在街道中央。"
  },
  AvgDialog_81526_Content_26 = {
    Text = "在幾乎沒有變化的表情中，那雙一直忍不住向兩側攤子上瞄去的眼睛就顯得格外突兀起來。"
  },
  AvgDialog_81526_Content_27 = {
    Text = "（為何此地的衣飾花紋如此混亂鮮豔，簡直令人眼暈，難道是某種迷惑精神的咒紋？）"
  },
  AvgDialog_81526_Content_28 = {
    Text = "（這些粗糙滑稽的土罐……裝著水，居然是此地的杯盞嗎？！）"
  },
  AvgDialog_81526_Content_29 = {
    Text = "（哦？那些湖水一樣的晶石倒是……不不，波呂克斯，不要被這些未開化之地的玩物所矇蔽，找些正經的食物來撫慰你可憐的肚子！）"
  },
  AvgDialog_81526_Content_3 = {
    Text = "什麼人？竟敢對聖子不敬，你們可知綁架聖子是什麼樣的罪孽！"
  },
  AvgDialog_81526_Content_30 = {
    Text = "（這些皺巴巴的果子是何物……那些巨大的肉塊又是何物，難道是怪物血肉……竟然用手抓著食用！真是粗鄙不堪。）"
  },
  AvgDialog_81526_Content_31 = {
    Text = "波呂克斯心中經歷了無數次挑挑揀揀，終於，這貴族一般的步伐停在了一處最“正常”的烤餅攤前。"
  },
  AvgDialog_81526_Content_32 = {
    Text = "卑微之人，我現在賜予你服侍神之使者的機會。"
  },
  AvgDialog_81526_Content_33 = {
    Text = "攤主與波呂克斯面面相覷了半晌，終於操著還算流利的通用語開口。"
  },
  AvgDialog_81526_Content_34 = {
    Text = "買餅？要買幾個？"
  },
  AvgDialog_81526_Content_35 = {
    Text = "（什麼是買……想必是此地特有的語言。）"
  },
  AvgDialog_81526_Content_36 = {
    Text = "波呂克斯垂下眼皮，矜持地看了看攤子上熱氣騰騰的烤餅，伸出手指輕輕一點。"
  },
  AvgDialog_81526_Content_37 = {
    Text = "將此物切作小塊，盛於銀盤之中，附上刀叉供奉於我。"
  },
  AvgDialog_81526_Content_39 = {
    Text = "在攤主怪異的眼神中，一張用紙皮包好的烤餅被粗暴地遞到了波呂克斯手中。"
  },
  AvgDialog_81526_Content_4 = {
    Text = "波呂克斯控制住剛剛恢復知覺的虛弱手腳，便立刻挺直了背，暴怒的貓一樣大聲呵斥起來。"
  },
  AvgDialog_81526_Content_40 = {
    Text = "……真是粗魯！算了，畢竟此地未曾經過提燈的教化。"
  },
  AvgDialog_81526_Content_41 = {
    Text = "過度飢餓使波呂克斯顧不上太多禮儀，他一口將餅咬下一塊，意外地被新鮮麵食與沙漠香料的香氣驚得微微睜大了眼。"
  },
  AvgDialog_81526_Content_42 = {
    Text = "這粗劣的食物竟然……別有一番風味，好吧，看來愚昧之人也能帶來些驚喜。"
  },
  AvgDialog_81526_Content_43 = {
    Text = "波呂克斯狼吞虎嚥地吃了幾口，這才慢條斯理地擦了擦翹起的嘴角，頗為愉悅地拈起一個祈禱的手勢。"
  },
  AvgDialog_81526_Content_44 = {
    Text = "做得不錯，凡俗之人，我將以聖子之名，為你祈求持燈者的賜福，祈求那銀色的聖恩將你庇佑，除淨你身上黑夜般深重的罪孽……"
  },
  AvgDialog_81526_Content_45 = {
    Text = "預想中如教會中人一樣激動的神情並沒有出現，攤主在短暫的愣神後伸出了兩隻手，分別豎著一根手指和五根手指。"
  },
  AvgDialog_81526_Content_46 = {
    Text = "一張餅，十五緬。"
  },
  AvgDialog_81526_Content_47 = {
    Text = "什麼？什麼緬？"
  },
  AvgDialog_81526_Content_48 = {
    Text = "在發覺波呂克斯並沒有打算掏出任何一枚銀色或銅色的錢幣之後，攤主終於反應過來，開始憤怒地大吼。"
  },
  AvgDialog_81526_Content_49 = {
    Text = "怎麼回事？我剛剛唸的分明是祝福的咒文……"
  },
  AvgDialog_81526_Content_5 = {
    Text = "原來是聖子……"
  },
  AvgDialog_81526_Content_50 = {
    Text = "不明所以的波呂克斯嚇了一跳，他雖然聽不懂那些嘰哩咕嚕的沙漠方言，但隨著店主跨出攤子向他抓來，他顯然明白了那一定不是感激的意思。"
  },
  AvgDialog_81526_Content_51 = {
    Text = "這是忽然瘋了嗎？野蠻的不信者！簡直不可理喻！"
  },
  AvgDialog_81526_Content_52 = {
    Text = "禍不單行，在波呂克斯的叫喊聲中，不知從何處出現的商隊成員又發現了他，從遠處一起追了過來。"
  },
  AvgDialog_81526_Content_53 = {
    Text = "虛弱的波呂克斯猶豫了一瞬，咬牙放棄了與這一群人戰鬥的打算，再度開啟了逃亡。"
  },
  AvgDialog_81526_Content_54 = {
    Text = "謹遵持燈者的教誨，應持慈愛之心，引領無知的世人，助他們洗脫他們的罪……"
  },
  AvgDialog_81526_Content_55 = {
    Text = "他緊緊攥著那半張滾燙的烤餅，在一條條陌生的街道中一邊祈禱、一邊咒罵、一邊狂奔著。"
  },
  AvgDialog_81526_Content_57 = {
    Text = "與此同時，當卡斯托爾與泰旖絲再次潛行到旅館的後院時，他們只看到了那口空空如也的箱子。"
  },
  AvgDialog_81526_Content_58 = {
    Text = "波呂克斯！他一定是醒來了，要趕在提燈找到這裡之前……"
  },
  AvgDialog_81526_Content_59 = {
    Text = "就在他們要踏出大門的時候，卡斯托爾卻迅速地退了回來，與泰旖絲一起毫無聲響地藏在了門後。"
  },
  AvgDialog_81526_Content_6 = {
    Text = "你們……不知道我是聖子？"
  },
  AvgDialog_81526_Content_60 = {
    Text = "一隊提燈燈衛訓練有素地從一旁的街道穿行而過，目光仔細將街上的角落搜尋了個徹底。"
  },
  AvgDialog_81526_Content_61 = {
    Text = "卡斯托爾回過頭，對泰旖絲苦澀一笑。"
  },
  AvgDialog_81526_Content_62 = {
    Text = "他們已經來了。"
  },
  AvgDialog_81526_Content_64 = {
    Text = "上氣不接下氣的波呂克斯精疲力竭地停了下來，他向街口回頭張望，終於再看不見那幾張惱人的面孔。"
  },
  AvgDialog_81526_Content_65 = {
    Text = "可惡的賤民，持燈者一定會懲罰他們的罪……"
  },
  AvgDialog_81526_Content_66 = {
    Text = "他看向手中沾染了他滿手油污的烤餅，氣憤地將餅狠狠摔在了地上。"
  },
  AvgDialog_81526_Content_67 = {
    Text = "一定是卡斯托爾那個蠢貨，這一切都是他害的……唔！"
  },
  AvgDialog_81526_Content_68 = {
    Text = "就在他想繼續大罵下去的時候，一隻手突然從一旁陰暗的小巷伸出，捂住了他的嘴，將他一把拖了進去。"
  },
  AvgDialog_81526_Content_69 = {
    Text = "卑賤的東西，你們……卡斯托爾？！"
  },
  AvgDialog_81526_Content_7 = {
    Text = "在商隊成員由困惑轉向陰沉的眼神中，反應過來的波呂克斯退後半步，緩緩向外挪動著。"
  },
  AvgDialog_81526_Content_70 = {
    Text = "噓，小心被他們發現。"
  },
  AvgDialog_81526_Content_71 = {
    Text = "即使二人腦中擔憂的追兵並不相同，波呂克斯還是勉為其難地壓低了聲音。"
  },
  AvgDialog_81526_Content_72 = {
    Text = "呵，我剛剛還在想，你這個沒用的傢伙跑去了哪裡，居然讓我一個人面對那些危險的瘋子。"
  },
  AvgDialog_81526_Content_73 = {
    Text = "波呂克斯剛剛所有的驚惶此刻消失一空，只要在卡斯托爾面前，他就還是那個高高在上的提燈聖子。"
  },
  AvgDialog_81526_Content_74 = {
    Text = "至於為什麼絕不想在卡斯托爾面前露出任何脆弱的樣子，他卻從不肯仔細去想。"
  },
  AvgDialog_81526_Content_75 = {
    Text = "他挑起眉毛，從抱怨中板起臉質問。"
  },
  AvgDialog_81526_Content_76 = {
    Text = "現在我倒想知道，將我弄到這裡的人究竟是不是你？"
  },
  AvgDialog_81526_Content_78 = {
    Text = "那麼，你與我來到這裡，是否是教主大人的旨意？"
  },
  AvgDialog_81526_Content_79 = {
    Text = "黑暗中卡斯托爾的眼神閃爍著，波呂克斯冷笑一聲，臉上的表情變得更加漠然。"
  },
  AvgDialog_81526_Content_8 = {
    Text = "領隊輕輕一揮手，幾個高大的身影便在波呂克斯“放肆”、“大膽”的叫喊聲中追趕著他出了門。"
  },
  AvgDialog_81526_Content_80 = {
    Text = "看來答案很明顯了，接下來你不會又要和我說一次，你那追尋自由的偉大計劃吧？"
  },
  AvgDialog_81526_Content_81 = {
    Text = "看到波呂克斯轉身欲走，卡斯托爾心急如焚地抓住了他的手腕。"
  },
  AvgDialog_81526_Content_82 = {
    Text = "這是我們最後的機會了，只要我們走出去，到外面去，你一定會慢慢想起一切的！"
  },
  AvgDialog_81526_Content_83 = {
    Text = "那些教眾的尊重只是他們控制我們、欺騙我們的手段，所謂聖子只不過是教會犧牲的工具罷了！"
  },
  AvgDialog_81526_Content_84 = {
    Text = "跟我走吧，我們是唯一的兄弟不是嗎，波呂克斯？"
  },
  AvgDialog_81526_Content_85 = {
    Text = "像是被某個詞語猛然激怒了，波呂克斯狠狠甩開了卡斯托爾的手，面無表情地盯住了他的雙眼。"
  },
  AvgDialog_81526_Content_87 = {
    Text = "醒醒吧，卡斯托爾，你我不過是同為侍奉持燈者的聖子。我們平日須和睦友愛，不代表我能容忍你的一切罪行！"
  },
  AvgDialog_81526_Content_88 = {
    Text = "背棄教會、違背教主大人的教導，你自己犯下這樣恐怖的罪孽，還要自作主張將我捲進來！"
  },
  AvgDialog_81526_Content_89 = {
    Text = "如若持燈者現在就對你降下責罰，我也不會為你祈禱半分的。"
  },
  AvgDialog_81526_Content_9 = {
    Text = "這……領隊，這個聖子我們要怎麼處理？"
  },
  AvgDialog_81526_Content_90 = {
    Text = "卡斯托爾看著弟弟臉上越來越陌生的表情，呆滯地愣在原地。"
  },
  AvgDialog_81526_Content_91 = {
    Text = "波呂克斯不屑地哼了一聲，卻似乎反應過來什麼似的思索起來。"
  },
  AvgDialog_81526_Content_92 = {
    Text = "不過……剛剛你似乎沒有看見追逐我的人，現在你又為什麼如此著急呢？"
  },
  AvgDialog_81526_Content_93 = {
    Text = "該不會，是教主大人已經找來了吧？"
  },
  AvgDialog_81526_Content_94 = {
    Text = "波呂克斯的眼神刀似的銳利起來，卡斯托爾囁嚅著，半晌說不出話。"
  },
  AvgDialog_81526_Content_96 = {
    Text = "那就再見吧，我的好哥哥。"
  },
  AvgDialog_81526_Content_97 = {
    Text = "波呂克斯用力甩脫了還想阻攔的卡斯托爾，一閃身融入了街上的人群之中。"
  },
  AvgDialog_81526_Content_99 = {
    Text = "自從離開了教會，波呂克斯就總是在奔跑。"
  },
  AvgDialog_81527_Content_1 = {Text = "沙與蜜"},
  AvgDialog_81527_Content_10 = {
    Text = "跋涉，無盡的跋涉。"
  },
  AvgDialog_81527_Content_100 = {
    Text = "這點不堪一擊的小威脅就讓你放棄你們的計劃了嗎？"
  },
  AvgDialog_81527_Content_101 = {
    Text = "泰旖絲……"
  },
  AvgDialog_81527_Content_102 = {
    Text = "唉，還要逃麼，真是狠心的哥哥啊，看來只有等我在波呂克斯身上略施一些懲罰，你才願意考慮回來了。"
  },
  AvgDialog_81527_Content_103 = {
    Text = "（不，不能在這裡束手就擒，但如果波呂克斯再次被傷害……）"
  },
  AvgDialog_81527_Content_104 = {
    Text = "相信我，在這片沙漠中，沒有什麼謊言能逃過我的耳目，她不過是在虛張聲勢罷了。"
  },
  AvgDialog_81527_Content_105 = {
    Text = "泰旖絲回過頭，輕輕瞇起眼睛。"
  },
  AvgDialog_81527_Content_106 = {
    Text = "于麗埃特……我認得她，她沒有那麼了解沙漠。"
  },
  AvgDialog_81527_Content_108 = {
    Text = "卡斯托爾看著眼前越發神秘的泰旖絲，最終重重點了點頭。"
  },
  AvgDialog_81527_Content_109 = {
    Text = "巨犬的咆哮聲越靠越近，沙漠的月亮已經能清晰照見犬類猩紅的瞳孔，於麗埃特手中的儀式鏡高舉過頂，鏡面折射的血月紅光直指兩人所在。"
  },
  AvgDialog_81527_Content_11 = {
    Text = "很快地圖就成了擺設，卡斯托爾無法辨清自己行走的方向有沒有偏移，只能盲目地跟著太陽與月亮升落的方向前進。"
  },
  AvgDialog_81527_Content_110 = {
    Text = "泰旖絲的神情變得冷峻起來，她的雙手如舞蹈般輕盈一揮，兩人的身影倏地化為了兩捧黃沙，窸窸窣窣消失在了無盡的沙丘中。"
  },
  AvgDialog_81527_Content_111 = {
    Text = "丟失目標的巨犬茫然地停下了腳步，煩躁不安地從鼻子中噴著氣。"
  },
  AvgDialog_81527_Content_112 = {
    Text = "……嘖。"
  },
  AvgDialog_81527_Content_114 = {
    Text = "晨光熹微之時，不遠處繁榮的小城終於出現在了星夜兼程的兩人面前。"
  },
  AvgDialog_81527_Content_115 = {
    Text = "你……還好嗎？"
  },
  AvgDialog_81527_Content_116 = {
    Text = "面對卡斯托爾擔憂的目光，臉色蒼白的泰旖絲輕輕搖了搖頭，看向了眼前傳來人聲的城門。"
  },
  AvgDialog_81527_Content_117 = {
    Text = "我們到了，這就是沙漠中的明珠，清泉之城——柯雷尼。"
  },
  AvgDialog_81527_Content_12 = {
    Text = "他燥熱、乾渴、茫然無措，水壺早已在昨日喝空。"
  },
  AvgDialog_81527_Content_13 = {
    Text = "太熱了……如果今天不能找到水源，恐怕就要永遠留在這裡了……"
  },
  AvgDialog_81527_Content_14 = {
    Text = "起碼波呂克斯過幾天醒來後，或許還有機會逃走。"
  },
  AvgDialog_81527_Content_15 = {
    Text = "卡斯托爾苦笑一聲，雙腳機械地移動著。"
  },
  AvgDialog_81527_Content_16 = {
    Text = "仙人掌、駱駝、紮著帳篷的部落，那些手抄本上所描繪的東西都不見蹤影，這裡荒無人煙，除了沙礫一無所有。"
  },
  AvgDialog_81527_Content_17 = {
    Text = "流淌著甘泉的綠洲，那恐怕只是旅人瀕死的幻覺吧……"
  },
  AvgDialog_81527_Content_18 = {
    Text = "就只能到這裡了嗎……令人充滿希望地死去，真是美好的傳說啊……"
  },
  AvgDialog_81527_Content_19 = {
    Text = "絕望的自我寬慰中，他的眼前開始發暈，從提燈教會逃出時強撐的一口氣到這裡已經精疲力盡。"
  },
  AvgDialog_81527_Content_2 = {Text = "數日後"},
  AvgDialog_81527_Content_20 = {
    Text = "如果死在這裡，大概很快就會被黃沙掩埋，乾乾淨淨誰也找不到，這樣也不錯……"
  },
  AvgDialog_81527_Content_21 = {
    Text = "就在他搖晃著走上又一個沙丘，終於力竭跪倒在地，想要這樣睡去的時候，一抹奇蹟般的綠色忽然在他的視線盡頭出現。"
  },
  AvgDialog_81527_Content_22 = {
    Text = "清澈的河流，星星點點的低矮灌木，還有停駐在此飲水的幾隻沙狐。"
  },
  AvgDialog_81527_Content_24 = {Text = "綠洲。"},
  AvgDialog_81527_Content_25 = {
    Text = "卡斯托爾情不自禁地嚥了嚥乾涸的口水，那雙灌了鉛似的腿也重新獲得了力量，他猛地爬了起來，向著水源走去。"
  },
  AvgDialog_81527_Content_27 = {
    Text = "大口大口的水流過喉嚨，卡斯托爾吐出長長一口氣，重獲新生一般跌坐在了水邊的沙地上。"
  },
  AvgDialog_81527_Content_28 = {
    Text = "他望著不遠處在低空盤旋的紅腳隼，心中的喜悅很快被更大的擔憂沖淡了，一種完全未知的恐懼時刻折磨著他。"
  },
  AvgDialog_81527_Content_29 = {
    Text = "我現在或許走在正確的方向上，或許已經徹底迷失了……"
  },
  AvgDialog_81527_Content_3 = {
    Text = "一個風塵僕僕的身影踏上了滾燙的沙丘。"
  },
  AvgDialog_81527_Content_30 = {
    Text = "即使我還能勉強堅持，但從這片綠洲走出後，下一次就未必有這樣的好運了。"
  },
  AvgDialog_81527_Content_32 = {
    Text = "卡斯托爾站了起來，緊鎖的眉頭忽然驚訝地鬆開了些許，他看見不遠處水流的分叉之中，的確有一道奇怪的影子。"
  },
  AvgDialog_81527_Content_33 = {
    Text = "他慢慢走近，終於看清了那順著河水漂流而下的，是一位緊閉著雙眼、肌膚如蜜的美人。"
  },
  AvgDialog_81527_Content_35 = {
    Text = "費力將泰旖絲從水中拖出的卡斯托爾手足無措地呆在原地，沒有任何急救知識的他只好輕輕推著泰旖絲的肩膀。"
  },
  AvgDialog_81527_Content_37 = {
    Text = "那雙緩緩睜開的眼睛迷茫了一瞬，很快看向了杵在面前、一身狼狽的卡斯托爾。"
  },
  AvgDialog_81527_Content_38 = {
    Text = "啊呀，感謝你叫醒了我，要不是遇到你，我可就要昏昏沉沉不知道睡到什麼時候去了呢，這位落單的小哥。"
  },
  AvgDialog_81527_Content_39 = {
    Text = "僅僅是站起了身，二人主動與被動的關係就好像完全轉變了。"
  },
  AvgDialog_81527_Content_4 = {
    Text = "蘇摩利·波利斯……"
  },
  AvgDialog_81527_Content_40 = {
    Text = "看你這副樣子……是遇到什麼麻煩了嗎？"
  },
  AvgDialog_81527_Content_41 = {
    Text = "卡斯托爾看著泰旖絲蒼白卻從容的面龐，雖然她十分柔和地笑著，僅僅是隨意地打量著他，但卡斯托爾莫名想起了那個名為卡納克的男人。"
  },
  AvgDialog_81527_Content_42 = {
    Text = "是的，那是一種強烈的、被俯視的感受。"
  },
  AvgDialog_81527_Content_43 = {
    Text = "（她了解沙漠，她很危險，但……她也很強大、沒有惡意，她能夠幫助我。）"
  },
  AvgDialog_81527_Content_44 = {
    Text = "卡斯托爾僅僅猶豫了一瞬，便憑藉著某種野獸般的直覺做下了決定。"
  },
  AvgDialog_81527_Content_45 = {
    Text = "我叫卡斯托爾，我在找一支去波利斯的商隊，蘇摩利的波利斯。"
  },
  AvgDialog_81527_Content_47 = {
    Text = "卡斯托爾預料中的笑聲並沒有出現，泰旖絲仍舊微微笑著，甚至是有些憐愛地注視著他。"
  },
  AvgDialog_81527_Content_48 = {
    Text = "可憐的孩子，那可是很遠的一座城，你就憑這雙腳來橫穿整座沙漠嗎？"
  },
  AvgDialog_81527_Content_49 = {
    Text = "唉，你說的那支商隊，是什麼時候進入沙漠的呢？"
  },
  AvgDialog_81527_Content_5 = {
    Text = "卡斯托爾受傷的黑色翅膀可憐地縮在一邊，傷口在過度使用中癒合又崩裂，乾涸的血痂黏住了一大片羽毛。"
  },
  AvgDialog_81527_Content_50 = {
    Text = "我追得很緊，他們還帶著貨物，應該與我差不了多久。"
  },
  AvgDialog_81527_Content_51 = {
    Text = "泰旖絲點了點頭，彎下腰去掬起一捧河水。"
  },
  AvgDialog_81527_Content_52 = {
    Text = "你應該已經發現了，沒有了水，任何生命都會輕易被黃沙吞沒。"
  },
  AvgDialog_81527_Content_53 = {
    Text = "在沙漠之中唯一能夠生存的道路，就是沿著水流的道路。"
  },
  AvgDialog_81527_Content_54 = {
    Text = "水滴順著泰旖絲的指尖流下，她的手指劃過柔軟的沙地，畫出了一幅蜿蜒的地圖。"
  },
  AvgDialog_81527_Content_55 = {
    Text = "想要到達沙漠彼端的那座城，就必須先經過中央這座水源旁的小城，柯雷尼。"
  },
  AvgDialog_81527_Content_56 = {
    Text = "那裡是著名的貿易中轉之地，你說的商隊一定會先去往這裡歇息補給，這是熟悉沙漠的人必須的常識。"
  },
  AvgDialog_81527_Content_57 = {
    Text = "說著說著，泰旖絲的聲音變得有些含糊。"
  },
  AvgDialog_81527_Content_58 = {
    Text = "<Small:不過現在，那裡已經不是個落腳的好選擇了……>"
  },
  AvgDialog_81527_Content_59 = {Text = "什麼？"},
  AvgDialog_81527_Content_6 = {
    Text = "嘶……所幸在沙漠裡翅膀太吸熱，並不適合長途飛行。"
  },
  AvgDialog_81527_Content_60 = {
    Text = "沒什麼，正巧的是，我也需要去一趟柯雷尼，我們豈不是能做個旅伴，在這漫漫黃沙之中給彼此一些安慰？"
  },
  AvgDialog_81527_Content_61 = {
    Text = "就讓我來當你的嚮導，而你麼，就負責保護我吧。"
  },
  AvgDialog_81527_Content_63 = {
    Text = "卡斯托爾沒有理由拒絕這樣一根救命稻草。"
  },
  AvgDialog_81527_Content_64 = {
    Text = "（保護她嗎……）"
  },
  AvgDialog_81527_Content_65 = {
    Text = "雖然他對泰旖絲口中含糊的解釋一概不信，但他也能看出，泰旖絲的身體確實十分虛弱。"
  },
  AvgDialog_81527_Content_66 = {
    Text = "即便有著無盡的疑問，此刻也不是猜忌的時候，只因有一個對沙漠瞭如指掌的嚮導，實在過於令人安心了。"
  },
  AvgDialog_81527_Content_67 = {
    Text = "那是沙蠍，去除毒囊之後可以烤著吃，味道出人意料的好呢。"
  },
  AvgDialog_81527_Content_68 = {
    Text = "為什麼找不到仙人掌？靠人的感官的確難以尋找，但，跟隨動物的腳步，你就很容易發現驚喜。"
  },
  AvgDialog_81527_Content_69 = {
    Text = "會換著腳站立的蜥蜴，扭動斜行的沙蛇，能高高跳起的小鼠，還有迅猛兇狠的紅鷹……"
  },
  AvgDialog_81527_Content_7 = {
    Text = "卡斯托爾忍著疼痛，小心地將斗篷披在身上，遮住陽光與風沙。"
  },
  AvgDialog_81527_Content_70 = {
    Text = "卡斯托爾一路都睜大著眼睛，聽泰旖絲娓娓道來著沙漠中奇特的生靈、多變的氣候，以及種種生存的技巧。"
  },
  AvgDialog_81527_Content_71 = {
    Text = "小傢伙，我發現你不是不了解沙漠的外鄉人。"
  },
  AvgDialog_81527_Content_72 = {
    Text = "泰旖絲拄著下巴，看卡斯托爾笨拙地串起沙蠍，又將乾枯的樹枝直接伸進了篝火中，最後手忙腳亂地把燒起的樹枝直接丟進了火堆。"
  },
  AvgDialog_81527_Content_73 = {
    Text = "你是根本不了解任何生存的常識，就像一個剛剛學會走路的幼兒。"
  },
  AvgDialog_81527_Content_74 = {
    Text = "卡斯托爾沉默著，半晌才忽然回話。"
  },
  AvgDialog_81527_Content_75 = {
    Text = "也可以這麼說。"
  },
  AvgDialog_81527_Content_76 = {
    Text = "泰旖絲看了看抱著膝蓋垂頭喪氣的卡斯托爾，熟練地重新串好一串沙蠍，悠然靠近了火上翻烤。"
  },
  AvgDialog_81527_Content_77 = {
    Text = "你好像一直很憂心？"
  },
  AvgDialog_81527_Content_78 = {
    Text = "……我在找我的弟弟，我的孿生弟弟。"
  },
  AvgDialog_81527_Content_79 = {
    Text = "卡斯托爾抬起頭，有些茫然地望向沙漠中明亮而浩瀚的星空。"
  },
  AvgDialog_81527_Content_8 = {
    Text = "環顧四周，漫漫黃沙充斥著他的視野，他握緊了手中的包裹與地圖，義無反顧地向沙漠深處走去。"
  },
  AvgDialog_81527_Content_80 = {
    Text = "如果這次我找不到他，那我們或許……就再也無法見面了。"
  },
  AvgDialog_81527_Content_81 = {
    Text = "這樣啊，我覺得你不用太擔心。"
  },
  AvgDialog_81527_Content_82 = {
    Text = "泰旖絲一派輕鬆地轉動著沙蠍，卡斯托爾盯著那隻可怖的黑乎乎的生物，卻似乎聞到了一股若隱若現的香味。"
  },
  AvgDialog_81527_Content_83 = {
    Text = "為什麼？"
  },
  AvgDialog_81527_Content_84 = {
    Text = "亞蘭盛行以繁衍為核心的種族文化，我們相信同日而生的孩子們享有共通的命運。至於相互依偎著誕生的雙生子……更是註定一生命運糾纏。"
  },
  AvgDialog_81527_Content_85 = {
    Text = "所以，在下一片生命的綠洲，你們一定會重新相聚的。"
  },
  AvgDialog_81527_Content_86 = {
    Text = "又是傳說麼……"
  },
  AvgDialog_81527_Content_87 = {
    Text = "卡斯托爾搖了搖頭，轉念他又浮起一絲希冀。"
  },
  AvgDialog_81527_Content_88 = {
    Text = "（如果綠洲、部落、璀璨的沙漠文明都是真的，那我是不是也可以再相信一次這個傳說呢……）"
  },
  AvgDialog_81527_Content_89 = {
    Text = "出神之中，卡斯托爾臉上淡淡的笑容剛剛浮現，便很快冷卻成了一片凝重。"
  },
  AvgDialog_81527_Content_90 = {
    Text = "泰旖絲同樣看向了遠方，寂靜的夜空陡然被一聲悠長的嚎叫劃破，那叫聲不屬於沙漠的任何一種生物。"
  },
  AvgDialog_81527_Content_91 = {
    Text = "快走，追捕我們的人來了。"
  },
  AvgDialog_81527_Content_93 = {
    Text = "剛剛烤熟的沙蠍掉落在地，卡斯托爾匆匆熄滅篝火，帶著泰旖絲不斷奔跑著。"
  },
  AvgDialog_81527_Content_94 = {
    Text = "巨犬的身影在夜色中若隱若現，于麗埃特的聲音從後方遠遠傳來。"
  },
  AvgDialog_81527_Content_95 = {
    Text = "卡斯托爾，我已經知道你將波呂克斯裝進了貨箱，教會已經鎖定了商隊的位置，不出多時就會將波呂克斯帶回來。"
  },
  AvgDialog_81527_Content_96 = {
    Text = "如果你心中還有你親愛的弟弟，就乖乖跟我回去，你也不希望這場可歌可泣的逃亡故事，變成你的獨角戲吧。"
  },
  AvgDialog_81527_Content_98 = {
    Text = "自己計劃的核心已被發現，提燈教會的貨物交易雖然隱秘，但未必沒有追蹤定位的手段，如果于麗埃特說的是真的……"
  },
  AvgDialog_81527_Content_99 = {
    Text = "卡斯托爾心中動搖了一瞬，腳步也跟著慢了下來。"
  },
  AvgDialog_81620_Content_1 = {
    Text = "好難纏的敵人……別害怕，守密人，彌薩格早就為這種危機狀況準備好了對策。"
  },
  AvgDialog_81620_Content_2 = {
    Text = "點擊啟動手中的應急靈知體吧，裡面珍貴的精神力量會瞬間激發喚醒體的潛力，讓大家恢復最佳狀態。"
  },
  AvgDialog_81620_Content_3 = {
    Text = "在戰鬥的關鍵時刻使用應急靈知體，是可以讓局面反敗為勝的最終手段，請謹慎選擇使用吧，你的安危始終是最重要的。"
  },
  AvgDialog_8224_Content_1 = {
    Text = "為嫉妒殺戮"
  },
  AvgDialog_8224_Content_10 = {
    Text = "那，你能把他們圍起來嗎？"
  },
  AvgDialog_8224_Content_11 = {
    Text = "圍起來？是……像這樣嗎？"
  },
  AvgDialog_8224_Content_12 = {
    Text = "漆黑的屏障閃爍了一下，然後迅速延展，將人群包圍在其中。"
  },
  AvgDialog_8224_Content_13 = {
    Text = "真厲害，不愧是我們的小騎士。"
  },
  AvgDialog_8224_Content_14 = {
    Text = "這、這沒什麼的，主君。"
  },
  AvgDialog_8224_Content_15 = {
    Text = "看不到屏障的人徒勞地擊打著空氣，並因為自己被困而愈發激憤。"
  },
  AvgDialog_8224_Content_16 = {
    Text = "巫術，巫術！主教快看啊，他們使用巫術！"
  },
  AvgDialog_8224_Content_17 = {
    Text = "還說不是同夥，當初愛德華肯定是你們用巫術救回來的！\n<Big:殺了他們，殺了他們！>"
  },
  AvgDialog_8224_Content_18 = {
    Text = "這不是巫術！這——"
  },
  AvgDialog_8224_Content_19 = {
    Text = "算了，他們聽不進去的。\n你在這裡看著他們吧，我去找根繩子。"
  },
  AvgDialog_8224_Content_2 = {
    Text = "門軸轉動之際，一道與陽光截然不同的光線刺痛了你的眼睛。"
  },
  AvgDialog_8224_Content_20 = {
    Text = "好了，這樣他就跑不掉了。"
  },
  AvgDialog_8224_Content_21 = {
    Text = "被你結實捆在長凳一角的愛德華不住掙扎，宛如被拴了鐵鏈的惡犬，眼神裡透露出一種絕望的瘋狂。"
  },
  AvgDialog_8224_Content_22 = {
    Text = "另一邊，被奧吉爾無形屏障困住的人們仍在叫罵著，你不免有些頭疼。"
  },
  AvgDialog_8224_Content_23 = {
    Text = "他這到底是做了什麼啊。"
  },
  AvgDialog_8224_Content_24 = {
    Text = "該死的敗類，我那天就該確保你死了！"
  },
  AvgDialog_8224_Content_25 = {
    Text = "一個人擠到人群前來，他雙目赤紅，面容因仇恨和憤怒而扭曲。\n在你腳邊，愛德華明顯地瑟縮了一下。"
  },
  AvgDialog_8224_Content_26 = {
    Text = "你騙了<Blue:米莉>的感情，騙走了她的花店。你把她從她自己的家裡趕了出去，轉頭用她的錢尋歡作樂。"
  },
  AvgDialog_8224_Content_27 = {
    Text = "她跳伊希斯河的時候甚至懷了你的孩子，你這個冷血的惡魔，你還有哪怕一點良知嗎！"
  },
  AvgDialog_8224_Content_28 = {
    Text = "我不知道上次你是怎麼撿回一條狗命的，但我發誓，這次我要割下你的頭，讓你為米莉償命！"
  },
  AvgDialog_8224_Content_29 = {
    Text = "湯普森。"
  },
  AvgDialog_8224_Content_3 = {
    Text = "殘留在眼底的光斑牢牢佔據著你的視線中心。你用力眨眼，甚至揉了揉，卻遲遲無法將它驅散，隨之而來的，是一種遲來的戰慄。"
  },
  AvgDialog_8224_Content_30 = {
    Text = "薩爾瓦多站在了叫喊者與愛德華之間，用身體隔絕了雙方的視線，安撫地抬起一隻手。"
  },
  AvgDialog_8224_Content_31 = {
    Text = "父神的愛降於所有，祂的旨意是叫你們彼此為善。\n殺戮的暴行是不應當的，你們都應該知曉。"
  },
  AvgDialog_8224_Content_32 = {
    Text = "他殺了米莉！"
  },
  AvgDialog_8224_Content_33 = {
    Text = "而他應當為此懺悔，但已死之人是無法做到這點的。\n讓他活著吧，這樣他才能真正贖罪。"
  },
  AvgDialog_8224_Content_34 = {
    Text = "我讓他活著了，我沒有在發現他沒死的時候立刻再殺了他！結果呢？\n他轉頭就盯上了<Yellow:索菲亞>家，盯上了<Yellow:她的姐姐>。"
  },
  AvgDialog_8224_Content_35 = {
    Text = "他不會悔改，他沒資格！他要為他所做的一切付出代價！"
  },
  AvgDialog_8224_Content_36 = {
    Text = "<Big:沒錯！>"
  },
  AvgDialog_8224_Content_37 = {
    Text = "<BigShake:殺了他，讓他償命！>"
  },
  AvgDialog_8224_Content_38 = {
    Text = "薩爾瓦多嘆了口氣。"
  },
  AvgDialog_8224_Content_39 = {
    Text = "憤怒蒙蔽了你們的雙眼，我的孩子，勿要再被它牽引了。\n看看他，難道他此刻不是表現出了悔改之意嗎？"
  },
  AvgDialog_8224_Content_4 = {
    Text = "莫名出現的危機感像緩慢浸潤的冰水，從看不見的地方侵入了你的日常。你皺眉：奧吉爾已經控制住形勢了，為什麼……"
  },
  AvgDialog_8224_Content_40 = {
    Text = "愛德華瑟縮在長椅邊，低垂的頭歪斜地靠在扶手上，嘴裡不住念叨著贖罪的話語。"
  },
  AvgDialog_8224_Content_41 = {
    Text = "靈魂的迷途不應是他永受黑暗之苦的原因，再給他一次機會吧，父神期望的道路永遠歡迎改過自新者。"
  },
  AvgDialog_8224_Content_43 = {
    Text = "敲門聲打斷了你們的交談，一個陌生的聲音透過門板隱隱傳來。"
  },
  AvgDialog_8224_Content_44 = {
    Text = "主教閣下，你在嗎？薩爾瓦多主教？"
  },
  AvgDialog_8224_Content_45 = {
    Text = "主教停了停，略帶歉意地轉向你。"
  },
  AvgDialog_8224_Content_46 = {
    Text = "恐怕我又需要你的幫助了，%player%%sirormadam%，能煩請你照看一下愛德華嗎？"
  },
  AvgDialog_8224_Content_47 = {
    Text = "他綁在這裡也出不了什麼事。\n我和你一起去吧，興許是索菲亞把警察帶來了。"
  },
  AvgDialog_8224_Content_48 = {
    Text = "你和薩爾瓦多一同朝門口走去。而隨著你們的靠近，模糊的人聲也愈發清晰。"
  },
  AvgDialog_8224_Content_49 = {
    Text = "薩爾瓦多握住門把，向內一拉——"
  },
  AvgDialog_8224_Content_5 = {
    Text = "把那瘋子交出來！"
  },
  AvgDialog_8224_Content_50 = {
    Text = "主教閣下，你終於開門了！"
  },
  AvgDialog_8224_Content_51 = {
    Text = "門被外力推開，比先前更加鼎沸的人聲隨著陽光一同湧了進來。一群人擠在門前，將這唯一的通道堵得嚴嚴實實。"
  },
  AvgDialog_8224_Content_52 = {
    Text = "諸位這是？"
  },
  AvgDialog_8224_Content_53 = {
    Text = "是這樣的主教閣下，我突然很想進去，呃……向父神禱告！對，我突然很想進去禱告，但這幫混帳東西不讓！您幫幫忙，讓我進去——"
  },
  AvgDialog_8224_Content_54 = {
    Text = "那人說著就往裡邁步，卻被一旁的人猛地拉住。"
  },
  AvgDialog_8224_Content_55 = {
    Text = "憑什麼是你先？我在這裡站好久了，怎麼也得是我吧！"
  },
  AvgDialog_8224_Content_56 = {
    Text = "胡扯什麼，大家不是都一塊兒來的，要我說門還是我敲的呢？"
  },
  AvgDialog_8224_Content_57 = {
    Text = "諸位，請冷靜——"
  },
  AvgDialog_8224_Content_58 = {
    Text = "薩爾瓦多的聲音很快被又一個聲音蓋過。"
  },
  AvgDialog_8224_Content_59 = {
    Text = "為什麼非得是你倆啊，我們也等了很久了！"
  },
  AvgDialog_8224_Content_6 = {
    Text = "暴民的聲音打斷了你的思路，你嘆了口氣。"
  },
  AvgDialog_8224_Content_60 = {
    Text = "就非要跟我搶是吧？找打！"
  },
  AvgDialog_8224_Content_61 = {
    Text = "打就打，忍你很久了！憑什麼你就要站第一個，那位子本來就該是我的！"
  },
  AvgDialog_8224_Content_62 = {
    Text = "<Big:打！打贏的就能第一個進去！>"
  },
  AvgDialog_8224_Content_63 = {
    Text = "人們彼此推搡起來，甚至動起了手。你正要出聲阻止，卻聽到身後傳來幾聲悶響，伴隨著一句低語。"
  },
  AvgDialog_8224_Content_64 = {
    Text = "我應當懺悔。"
  },
  AvgDialog_8224_Content_65 = {
    Text = "愛德華先生！"
  },
  AvgDialog_8224_Content_66 = {
    Text = "我應當流出黑色的血液。"
  },
  AvgDialog_8224_Content_67 = {
    Text = "薩爾瓦多轉身，快速朝聖堂內跑去。"
  },
  AvgDialog_8224_Content_68 = {
    Text = "我應當淨化——"
  },
  AvgDialog_8224_Content_69 = {
    Text = "有什麼東西破了，濕潤的聲音並不很響，此刻卻震耳欲聾。"
  },
  AvgDialog_8224_Content_7 = {
    Text = "這些人怎麼突然那麼生氣，剛才在廣場上看還好好的啊。"
  },
  AvgDialog_8224_Content_70 = {
    Text = "愛德華弓著腰俯身在長凳的扶手上，扶手凸起的銳角深深嵌入了他的前額，鮮紅的血液順著深色的木料流下，迅速在地面擴散。"
  },
  AvgDialog_8224_Content_71 = {
    Text = "粉色的碎骨和深色的組織從豁口內透出，即使相隔甚遠，你仍能聞到那濃重的血腥味。"
  },
  AvgDialog_8224_Content_73 = {
    Text = "薩爾瓦多很快跪到了愛德華身前，他用手捂著年輕人的額頭，像是希望幫他止血。"
  },
  AvgDialog_8224_Content_74 = {
    Text = "哈哈！好，活該！死得好！"
  },
  AvgDialog_8224_Content_75 = {
    Text = "被奧吉爾困住的人們歡呼起來，他們互相拍著肩膀，彷彿自己目睹了一件盛大的好事。"
  },
  AvgDialog_8224_Content_76 = {
    Text = "與此同時，你身邊的人爆發出了與裡面的人完全不同的反應。"
  },
  AvgDialog_8224_Content_77 = {
    Text = "該死的，讓他搶先了！"
  },
  AvgDialog_8224_Content_78 = {
    Text = "我才有資格死在聖堂裡，我！"
  },
  AvgDialog_8224_Content_79 = {
    Text = "強大的推力將你逼得連連後退，你不得不側身閃入長凳間的狹窄過道中，避免被人群推倒踩踏的危險。"
  },
  AvgDialog_8224_Content_8 = {
    Text = "誰知道呢，可能天氣太熱，脾氣也燥起來了吧……\n你現在還控制得住嗎，奧吉爾？"
  },
  AvgDialog_8224_Content_80 = {
    Text = "失去你這個唯一的阻礙後，場面徹底失控。"
  },
  AvgDialog_8224_Content_82 = {
    Text = "一道血印出現在聖堂粗壯的石柱上，撞到牆上的年輕人軟倒在地，手指抽搐了兩下，便不再動彈。"
  },
  AvgDialog_8224_Content_83 = {
    Text = "可惡，被他搶先了！那我是第一個撞門死——"
  },
  AvgDialog_8224_Content_85 = {
    Text = "哈、哈哈哈哈，讓你搶在我前面！現在我是第一個殺人的了！"
  },
  AvgDialog_8224_Content_87 = {
    Text = "我才是第一個，我！"
  },
  AvgDialog_8224_Content_89 = {
    Text = "……這……到底……"
  },
  AvgDialog_8224_Content_9 = {
    Text = "不用擔心，主君，這個可比任務輕鬆多了。"
  },
  AvgDialog_8224_Content_90 = {
    Text = "這到底是怎麼回事……"
  },
  AvgDialog_8228_Content_1 = {
    Text = "向倦怠妥協"
  },
  AvgDialog_8228_Content_10 = {
    Text = "那平民怎麼辦？"
  },
  AvgDialog_8228_Content_11 = {
    Text = "我們這裡除了自殘的，還有一批有嚴重暴力傾向的，走不開啊。"
  },
  AvgDialog_8228_Content_12 = {
    Text = "……盡力而為，一切以發現事件源頭並將其徹底解決為重。\n只有盡快停止異象，他們才能真正安全。"
  },
  AvgDialog_8228_Content_13 = {
    Text = "倫蒂尼恩怎麼那麼危險啊——"
  },
  AvgDialog_8228_Content_14 = {
    Text = "……這大概就是大城市的代價吧。"
  },
  AvgDialog_8228_Content_15 = {
    Text = "總之，只有盡快停止異象，他們才能真正安全。"
  },
  AvgDialog_8228_Content_16 = {
    Text = "抓緊時間，守密人。\n務必在情況進一步惡化前解決此事。"
  },
  AvgDialog_8228_Content_17 = {
    Text = "我知道了。\n奧吉爾，先撤下屏障，我們去和審查會的探員匯合。"
  },
  AvgDialog_8228_Content_18 = {
    Text = "可，這些人該怎麼辦呢？\n撤下屏障的話，他們肯定會暴動的。"
  },
  AvgDialog_8228_Content_19 = {
    Text = "你遲疑了一會。"
  },
  AvgDialog_8228_Content_2 = {
    Text = "這絕不可能是普通事件，必須趕緊聯繫——"
  },
  AvgDialog_8228_Content_20 = {
    Text = "我知道，我也很擔心。但……但威廉說得沒錯，只有盡快停止異象，大家才能真正安全。"
  },
  AvgDialog_8228_Content_21 = {
    Text = "……我知道了，主君。一切聽你安排。"
  },
  AvgDialog_8228_Content_22 = {
    Text = "薩爾瓦多主教，這裡危險，還請你先和我們一起行動，等與審查會合警方匯合後，我們會再派人手將你送到安全的地方去。"
  },
  AvgDialog_8228_Content_23 = {
    Text = "莫要擔心，一切以你們的工作為重。"
  },
  AvgDialog_8228_Content_24 = {
    Text = "那麼，出發。"
  },
  AvgDialog_8228_Content_25 = {
    Text = "原本熱鬧的廣場此刻一片混亂，四處奔逃的、追逐的、尖叫的、自殘的……每個人都陷入了不同程度、不同症狀的瘋狂。"
  },
  AvgDialog_8228_Content_26 = {
    Text = "你跟在奧吉爾身後，用盡可能快的速度往廣場的東南角趕去，卻無可避免地被人群沖散。"
  },
  AvgDialog_8228_Content_27 = {
    Text = "正在你思考是否要折返時，聽到一個熟悉的聲音。"
  },
  AvgDialog_8228_Content_29 = {
    Text = "索菲亞驚慌的面容出現在你身前，她身後跟著幾個人：其中兩個穿著審查會的制服，剩下兩個則是做警察打扮。"
  },
  AvgDialog_8228_Content_3 = {
    Text = "%player%，你現在在哪？"
  },
  AvgDialog_8228_Content_31 = {
    Text = "你有些驚訝地看向一旁的探員。"
  },
  AvgDialog_8228_Content_32 = {
    Text = "你認識我？"
  },
  AvgDialog_8228_Content_33 = {
    Text = "我們都看過你的照片，守密人%sirormadam%。\n<Blue:MTC區域維護與管理第一響應隊>阿爾法小組，向你報告。"
  },
  AvgDialog_8228_Content_34 = {
    Text = "怎麼就你們幾個，增援呢？"
