  },
  AvgDialog_89878_Content_23 = {
    Text = "戈利亞沒有回答，和凱刻斯消失在你的視線裡。"
  },
  AvgDialog_89878_Content_24 = {
    Text = "看來一切都結束了。你找回了奧瑞塔，摧毀了邪惡儀式，「拯救」了世界。"
  },
  AvgDialog_89878_Content_25 = {
    Text = "真是「有趣」的經歷，令我充滿了靈感。"
  },
  AvgDialog_89878_Content_26 = {
    Text = "珊微笑地注視著你，彷彿這世界的所有都已經消失，只剩下你。"
  },
  AvgDialog_89878_Content_27 = {
    Text = "別看我，我絕不會成為你的雕塑材料。"
  },
  AvgDialog_89878_Content_28 = {
    Text = "不過，如果你跟我走，我會承包你的原料。這也是守護世界的一種方式。"
  },
  AvgDialog_89878_Content_29 = {
    Text = "有意思。可以，我會跟你走，但若是你出現了什麼事情……"
  },
  AvgDialog_89878_Content_3 = {
    Text = "你證明了自己的力量，所以……我願意放你一馬。"
  },
  AvgDialog_89878_Content_30 = {
    Text = "我很樂意將你獨特的美，雕琢成永恆。"
  },
  AvgDialog_89878_Content_32 = {
    Text = "還有奧瑞塔！"
  },
  AvgDialog_89878_Content_33 = {
    Text = "奧瑞塔要和你走，奧瑞塔要守護朋友！"
  },
  AvgDialog_89878_Content_34 = {
    Text = "薩爾瓦多，你呢？還是回到教堂？"
  },
  AvgDialog_89878_Content_35 = {
    Text = "是的，但在此之前，我想……好好安葬這裡的兄弟姐妹，安撫他們最後的苦痛。"
  },
  AvgDialog_89878_Content_36 = {
    Text = "你點點頭，知道他的心情遠比此刻展現的更加痛苦，因此輕輕拍了拍他的肩膀。"
  },
  AvgDialog_89878_Content_37 = {
    Text = "那麼薩爾瓦多，再見。"
  },
  AvgDialog_89878_Content_38 = {
    Text = "蒼白的使者，再見。"
  },
  AvgDialog_89878_Content_39 = {
    Text = "就這樣，你和薩爾瓦多告別，帶著珊、奧瑞塔與熔毀·朵爾離開。"
  },
  AvgDialog_89878_Content_4 = {
    Text = "嘖，嘴硬的小狗，真是——讓人看不順眼。"
  },
  AvgDialog_89878_Content_40 = {
    Text = "遠處，你看不見的地方，兩個身影靜靜佇立，看著你和薩爾瓦多分別。\n其中一人赫然是彌利亞姆。"
  },
  AvgDialog_89878_Content_41 = {
    Text = "許久之後，另一個未知的人影把玩著造成無數慘劇的象牙雕像，開了口，態度高傲而驕矜。"
  },
  AvgDialog_89878_Content_42 = {
    Text = "%heorshe%就是破壞儀式之人？"
  },
  AvgDialog_89878_Content_43 = {
    Text = "是的，@2大人。抱歉，神國誕臨之際將至，我卻……"
  },
  AvgDialog_89878_Content_44 = {
    Text = "不必擔憂，你我所求的永恆不會在此中止。"
  },
  AvgDialog_89878_Content_45 = {
    Text = "您的意思是，我的失敗不會影響神國降臨的進程？"
  },
  AvgDialog_89878_Content_46 = {
    Text = "少女發出一聲含義不明的悶哼。"
  },
  AvgDialog_89878_Content_47 = {
    Text = "是啊，神國必會誕臨，畢竟神王已經……"
  },
  AvgDialog_89878_Content_48 = {
    Text = "少女曖昧的聲音融入陰影之中，彌利亞姆聽此深吸口氣，緩緩閉上了眼睛。"
  },
  AvgDialog_89878_Content_49 = {
    Text = "再次睜眼時，彌利亞姆的眼中滿是狂熱，身體都因為激動而顫抖。"
  },
  AvgDialog_89878_Content_5 = {
    Text = "怎麼，還要再來嗎？當然，我可以繼續戰鬥，戰鬥到死。"
  },
  AvgDialog_89878_Content_50 = {
    Text = "是的，<Yellow:神國必會誕臨>。"
  },
  AvgDialog_89878_Content_7 = {
    Text = "冷靜！你們兩個都冷靜一下。"
  },
  AvgDialog_89878_Content_8 = {
    Text = "熔毀·朵爾，我們來這裡只是為了找到奧瑞塔，現在奧瑞塔已經找到了，我們該回去了。"
  },
  AvgDialog_89878_Content_9 = {
    Text = "至於戈利亞，你或許不記得，但是我們曾經——"
  },
  AvgDialog_89879_Content_10 = {
    Text = "你不和我們一起？"
  },
  AvgDialog_89879_Content_11 = {
    Text = "很抱歉，我還有些事情要做。但我想，我們能以精神鏈接的方式保持聯繫。"
  },
  AvgDialog_89879_Content_12 = {
    Text = "請放心，%player%，儘管遠在千里之外，我也會……注視著你。"
  },
  AvgDialog_89879_Content_13 = {
    Text = "就這樣，我們來到了塞勒菲斯"
  },
  AvgDialog_89879_Content_14 = {
    Text = "這裡就是塞勒菲斯？"
  },
  AvgDialog_89879_Content_15 = {
    Text = "我看著面前的景象——"
  },
  AvgDialog_89879_Content_16 = {
    Text = "如果不算遠處的驢叫，那麼海浪、碼頭和熔毀·朵爾，就是視線中的全部。"
  },
  AvgDialog_89879_Content_17 = {
    Text = "奇怪，這裡怎麼一個人都沒有……"
  },
  AvgDialog_89879_Content_18 = {
    Text = "嘗試自己探索四周"
  },
  AvgDialog_89879_Content_19 = {
    Text = "我勸你不要輕舉妄動。這裡……太安靜了。"
  },
  AvgDialog_89879_Content_2 = {
    Text = "克萊門汀，你找到了失蹤的<Yellow:奧瑞塔>！？"
  },
  AvgDialog_89879_Content_20 = {
    Text = "向熔毀·朵爾尋求建議"
  },
  AvgDialog_89879_Content_21 = {
    Text = "你看著我做什麼？難道我會突然精通動物語言，從驢口中問出事情的經過？"
  },
  AvgDialog_89879_Content_23 = {
    Text = "這時，遠處突然傳來淒慘的驢叫。\n這下不用問，你們也知道該如何行動了。"
  },
  AvgDialog_89879_Content_24 = {
    Text = "當你和熔毀·朵爾趕到時，那頭被困在欄裡、不斷慘叫的驢已經瀕死，悲切地嗚咽。"
  },
  AvgDialog_89879_Content_25 = {
    Text = "一個人影跪在牠身邊，無視驢身不停湧動的融蝕，給予最後的關懷。"
  },
  AvgDialog_89879_Content_26 = {
    Text = "雖然你並非我的姐妹弟兄，父神的兒女，但生命本身便是寶貴的。"
  },
  AvgDialog_89879_Content_27 = {
    Text = "身為父神的代行者，我願免去你的病痛，將你從苦中解脫。"
  },
  AvgDialog_89879_Content_28 = {
    Text = "薩爾瓦多？你怎麼會在這裡？"
  },
  AvgDialog_89879_Content_29 = {
    Text = "蒼白的使者？請原諒我的失禮，我有更加重要的使命……"
  },
  AvgDialog_89879_Content_3 = {
    Text = "冷靜，%player%，她的原話是「有著水母特徵、穿著白色洋裙的小女孩出現在塞勒菲斯漁村」。"
  },
  AvgDialog_89879_Content_30 = {
    Text = "薩爾瓦多的手中閃現光芒。\n他在試圖挽救那不斷哀叫、瀕死的驢。"
  },
  AvgDialog_89879_Content_4 = {
    Text = "是的，作為「情報人員」我只是將自己知道的告訴了你們。"
  },
  AvgDialog_89879_Content_5 = {
    Text = "至於確認那孩子是否真的是奧瑞塔，那是%player%你的工作。"
  },
  AvgDialog_89879_Content_6 = {
    Text = "我明白了，抱歉，剛才是我太過激動。"
  },
  AvgDialog_89879_Content_7 = {
    Text = "塞勒菲斯，我似乎聽過這個名字……是那座「時光凝固的村莊」？"
  },
  AvgDialog_89879_Content_8 = {
    Text = "就是那座以懸崖、鯡魚、茅草屋還有驢運場景為特色，在旅者間聲名大噪的漁村。"
  },
  AvgDialog_89879_Content_9 = {
    Text = "哪怕最後沒有找到奧瑞塔，我想你們也會不虛一行。"
  },
  AvgDialog_89880_Content_1 = {
    Text = "奧瑞塔需要朋友，如此需要，就像她賴以生存的呼吸和水一樣。"
  },
  AvgDialog_89880_Content_10 = {
    Text = "直到包括塞勒菲斯在內的許多地方變為死亡之地，恐怖之地，「時光凝固之地」。"
  },
  AvgDialog_89880_Content_11 = {
    Text = "直到這時，她愚蠢的腦子才開始明白自己究竟做了什麼事情。可是，可是……她已經回不去了。"
  },
  AvgDialog_89880_Content_12 = {
    Text = "<Red:她親手殺死了自己的朋友。所有朋友>"
  },
  AvgDialog_89880_Content_14 = {
    Text = "乾脆就消失吧，反正，她永遠不會擁有真正的朋友"
  },
  AvgDialog_89880_Content_15 = {
    Text = "心碎的奧瑞塔閉上眼睛。她覺得疲憊，如此渴望著沉睡，<Yellow:永久的沉睡>。"
  },
  AvgDialog_89880_Content_16 = {
    Text = "但是某個聲音傳了進來——"
  },
  AvgDialog_89880_Content_17 = {
    Text = "奧瑞塔！奧瑞塔！能聽到我說話嗎？我在嘗試連結你，你能聽到我說話嗎？"
  },
  AvgDialog_89880_Content_18 = {
    Text = "奧瑞塔沒有回應，她太累了，身心疲憊，只想沉溺於永恆的睡眠，遠離所有痛苦。"
  },
  AvgDialog_89880_Content_19 = {
    Text = "奧瑞塔，回答我。請你回答我。"
  },
  AvgDialog_89880_Content_2 = {
    Text = "然而她總是在失去朋友。\n她不理解原因，只能後知後覺感到一個個朋友在「消失」。"
  },
  AvgDialog_89880_Content_20 = {
    Text = "渴望、罪惡、內疚、還有絕望讓奧瑞塔無法回應。"
  },
  AvgDialog_89880_Content_21 = {
    Text = "這些複雜的情緒已經超出了她簡單大腦可以理解的範圍，讓她無法呼吸。"
  },
  AvgDialog_89880_Content_22 = {
    Text = "……奧瑞塔，我知道你能聽到我的話。"
  },
  AvgDialog_89880_Content_23 = {
    Text = "奧瑞塔仍舊沉默，或者說，她已經無法回應。深沉的黑暗已經開始侵襲她罪惡的靈魂。"
  },
  AvgDialog_89880_Content_25 = {
    Text = "無論如何，奧瑞塔，我永遠是你的朋友。每個喚醒體，都是。"
  },
  AvgDialog_89880_Content_26 = {
    Text = "……你、你仍願意和我做朋友？"
  },
  AvgDialog_89880_Content_27 = {
    Text = "哪怕、哪怕我做了那樣可怕的事情？"
  },
  AvgDialog_89880_Content_28 = {
    Text = "這就是我存在的意義，這就是守密人的責任。鏈接你們，克制你們，和你們，守護這個世界。"
  },
  AvgDialog_89880_Content_29 = {
    Text = "因此，我們是朋友，是戰友，是同志，哪怕性格不同，最終都會為了同一個理想而燃燒。"
  },
  AvgDialog_89880_Content_3 = {
    Text = "那麼，你是否希望他們永恆陪伴你？"
  },
  AvgDialog_89880_Content_30 = {
    Text = "奧瑞塔不明白。奧瑞塔……沒有那麼聰明。"
  },
  AvgDialog_89880_Content_31 = {
    Text = "那麼，你只需要相信我。我會帶領你們，在銀鑰的指引下找到方向。"
  },
  AvgDialog_89880_Content_33 = {
    Text = "……奧瑞塔，願意相信你。朋友。"
  },
  AvgDialog_89880_Content_34 = {
    Text = "奧瑞塔終於睜開了眼睛，與此同時，銀鑰的輝光乍然閃爍，驅散所有她靈魂中的痛苦與黑暗。"
  },
  AvgDialog_89880_Content_36 = {
    Text = "奧瑞塔會守護朋友。奧瑞塔會讓朋友幸福！"
  },
  AvgDialog_89880_Content_37 = {
    Text = "奧瑞塔的精神主動而欣喜地回應著你，鏈接著你。\n在銀鑰的輝光與奧瑞塔精神的支持中，你漸漸回神。"
  },
  AvgDialog_89880_Content_38 = {
    Text = "此刻，你的身邊是薩爾瓦多、熔毀·朵爾、珊、因為鏈接恢復戰鬥能力的奧瑞塔，和遠在千里之外卻會通過鏈接輔助戰鬥的克萊門汀。"
  },
  AvgDialog_89880_Content_39 = {
    Text = "愚蠢的無信者。你破壞了吾主的重要儀式，必須為此付出代價。"
  },
  AvgDialog_89880_Content_4 = {
    Text = "希望！奧瑞塔希望朋友們永遠陪著奧瑞塔！"
  },
  AvgDialog_89880_Content_40 = {
    Text = "非利士人，他們交給你了。"
  },
  AvgDialog_89880_Content_41 = {
    Text = "嘖，你還是真會使喚人，彌利亞姆。"
  },
  AvgDialog_89880_Content_42 = {
    Text = "這是為了彰顯吾主的權威必須降下的懲罰。我很想親自施行，但是，我另有使命。"
  },
  AvgDialog_89880_Content_43 = {
    Text = "彌利亞姆瞪視戈利亞，直到後者拿起巨劍才滿意地點點頭，優雅地向你道別。"
  },
  AvgDialog_89880_Content_44 = {
    Text = "無信者，希望我們再也不會見面。"
  },
  AvgDialog_89880_Content_45 = {
    Text = "隨後，彌利亞姆離開，只剩下戈利亞。就在這時，另一人靠近戰場。"
  },
  AvgDialog_89880_Content_46 = {
    Text = "來得正好，凱刻斯，和我一起把這些人撕碎。"
  },
  AvgDialog_89880_Content_47 = {
    Text = "凱刻斯沒有說話，他靜靜走到你身邊，沉默卻又堅定。"
  },
  AvgDialog_89880_Content_48 = {
    Text = "哈哈哈，很好，又一個背叛者。這場戲還真是精彩萬分。"
  },
  AvgDialog_89880_Content_49 = {
    Text = "但是沒關係，我的巨刃會讓你們明白，力量，才是這世間的真理。"
  },
  AvgDialog_89880_Content_5 = {
    Text = "那麼，接受此物吧。"
  },
  AvgDialog_89880_Content_6 = {
    Text = "只要你將此物送給朋友，他們將會沐浴於吾主的輝光下，於神國永恆陪伴著你。"
  },
  AvgDialog_89880_Content_7 = {
    Text = "神秘優雅的祭祀說著，將許多象牙雕像放到了奧瑞塔的懷裡。\n而奧瑞塔，開心地接過，高興地蹦了起來。"
  },
  AvgDialog_89880_Content_8 = {
    Text = "好哦，奧瑞塔要給每個朋友都送這個禮物，奧瑞塔要讓每個朋友都永永遠遠地陪著奧瑞塔！"
  },
  AvgDialog_89880_Content_9 = {
    Text = "第一個「禮物」就這樣送出，然後是第二個、第三個、第四個……第無數個。"
  },
  AvgDialog_89881_Content_1 = {
    Text = "由於海怪數量太多，這場戰鬥注定會被拖得很久。\n但你不能這樣。你要盡快找到奧瑞塔。"
  },
  AvgDialog_89881_Content_10 = {
    Text = "說著，你再次沉入意識的世界，在紛亂的光影裡搜尋凱刻斯的精神光斑。"
  },
  AvgDialog_89881_Content_11 = {
    Text = "我找到凱刻斯了。克萊門汀！"
  },
  AvgDialog_89881_Content_12 = {
    Text = "一瞬間，無數的回憶紛至沓來，在克萊門汀的操控下一一播放。"
  },
  AvgDialog_89881_Content_13 = {
    Text = "孕育著神明的心臟。"
  },
  AvgDialog_89881_Content_14 = {
    Text = "猙獰的群蛇。"
  },
  AvgDialog_89881_Content_15 = {
    Text = "以及「另一個世界」的凱刻斯，堅定站在你面前，為了守護你而與戈利亞戰鬥的身影。"
  },
  AvgDialog_89881_Content_16 = {
    Text = "這些記憶快速翻湧在意識世界，令凱刻斯差異萬分。\n他震驚得甚至沒有拒絕你的連結。"
  },
  AvgDialog_89881_Content_17 = {
    Text = "這些、這些到底是什麼？幻覺？！"
  },
  AvgDialog_89881_Content_18 = {
    Text = "不，這不是幻覺，而是「另一個世界」裡的事實。"
  },
  AvgDialog_89881_Content_19 = {
    Text = "「另一個世界」……你到底是什麼意思？"
  },
  AvgDialog_89881_Content_2 = {
    Text = "為此，你握住了胸口的銀鑰匙。"
  },
  AvgDialog_89881_Content_20 = {
    Text = "我的意思是，我們曾經是朋友，並肩作戰，互相信任，互相依靠。"
  },
  AvgDialog_89881_Content_21 = {
    Text = "朋友？不可能，我這樣高貴的血統傳承者怎麼會和你這樣孱弱的人類——"
  },
  AvgDialog_89881_Content_22 = {
    Text = "你打斷凱刻斯的話。"
  },
  AvgDialog_89881_Content_23 = {
    Text = "首先，我並不孱弱。其次，凱刻斯，你不必這樣，不必像個刺蝟武裝自己，掩飾自卑與渴求認同。"
  },
  AvgDialog_89881_Content_24 = {
    Text = "因為我們是朋友，我會接受你本來的樣子。"
  },
  AvgDialog_89881_Content_25 = {
    Text = "你走向凱刻斯。精神鏈接和巨大衝擊下，他暫時無心傷害你，因此不停後退。"
  },
  AvgDialog_89881_Content_26 = {
    Text = "你、你幹什麼，別過——"
  },
  AvgDialog_89881_Content_27 = {
    Text = "凱刻斯的聲音戛然而止。他瞪大眼睛看著你，看著你擁抱他。"
  },
  AvgDialog_89881_Content_28 = {
    Text = "無論如何，凱刻斯，我永遠是你的朋友。哪怕跨越維度，穿越世界。"
  },
  AvgDialog_89881_Content_3 = {
    Text = "熟悉的暈眩感裡，克萊門汀出現。"
  },
  AvgDialog_89881_Content_30 = {
    Text = "這個世界即將毀滅，我不會強求你和我拯救它，但請不要阻止我。"
  },
  AvgDialog_89881_Content_31 = {
    Text = "我的朋友，凱刻斯。"
  },
  AvgDialog_89881_Content_33 = {
    Text = "呵，不愧是彌薩格的守密人。總是會給我驚喜，用最小的代價解決問題。"
  },
  AvgDialog_89881_Content_34 = {
    Text = "隨著一聲輕笑，克萊門汀中斷了鏈接。"
  },
  AvgDialog_89881_Content_35 = {
    Text = "眩暈感再次來臨，那是重返現實世界的徵兆。"
  },
  AvgDialog_89881_Content_36 = {
    Text = "短暫的頭暈後，你睜開了眼睛，見到了凱刻斯。"
  },
  AvgDialog_89881_Content_37 = {
    Text = "他仍舊愣在原地，沉默一會後揮退了所有海怪。"
  },
  AvgDialog_89881_Content_38 = {
    Text = "你確定要知道奧瑞塔的位置？"
  },
  AvgDialog_89881_Content_4 = {
    Text = "哎呀，這麼快就需要我的幫助了嗎？我還以為你能再撐一會。"
  },
  AvgDialog_89881_Content_40 = {
    Text = "哪怕會遭遇危險？"
  },
  AvgDialog_89881_Content_41 = {
    Text = "你點點頭。\n凱刻斯沉默著，無聲指了個方向。"
  },
  AvgDialog_89881_Content_42 = {
    Text = "隨後，你和薩爾瓦多、珊、熔毀·朵爾離開。"
  },
  AvgDialog_89881_Content_43 = {
    Text = "凱刻斯站在原地，直到你消失在視線中，才輕輕地嘆了口氣。"
  },
  AvgDialog_89881_Content_44 = {
    Text = "祝你好運……我永遠的朋友，%player%。"
  },
  AvgDialog_89881_Content_5 = {
    Text = "沒有時間了，我怕奧瑞塔有危險。"
  },
  AvgDialog_89881_Content_6 = {
    Text = "所以，需要我做什麼呢？"
  },
  AvgDialog_89881_Content_7 = {
    Text = "我會強行連結凱刻斯，到時候，麻煩克萊門汀你播放一下我的記憶。"
  },
  AvgDialog_89881_Content_8 = {
    Text = "播放你的記憶？"
  },
  AvgDialog_89881_Content_9 = {
    Text = "是的，「那個世界」中關於凱刻斯的記憶。"
  },
  AvgDialog_89882_Content_1 = {
    Text = "你數不清自己「狩獵」了多少海怪的頭顱，但當某個東西從倒下的海怪屍體中掉出時，你猛然停下動作。"
  },
  AvgDialog_89882_Content_10 = {
    Text = "……這就是我必須找到奧瑞塔的原因。"
  },
  AvgDialog_89882_Content_11 = {
    Text = "她是個沉浸於自己世界裡的孩子，不會知道也無法理解自己的行為……會造成多麼恐怖的後果。"
  },
  AvgDialog_89882_Content_12 = {
    Text = "我明白了，蒼白的使者。你在嘗試拯救那個孩子，免除她無意間施加於他人的痛苦。"
  },
  AvgDialog_89882_Content_13 = {
    Text = "這亦是善舉。我願秉承父神的旨意，竭盡全力相助。"
  },
  AvgDialog_89882_Content_14 = {
    Text = "我當然也願意。除了被我雕塑完成，卓越的材料不應該以其他方式浪費。"
  },
  AvgDialog_89882_Content_15 = {Text = "嘖……"},
  AvgDialog_89882_Content_16 = {
    Text = "碰觸象牙雕像"
  },
  AvgDialog_89882_Content_17 = {
    Text = "你確定要接觸這個古怪的祭祀雕像？我們對它一無所知。"
  },
  AvgDialog_89882_Content_18 = {
    Text = "所以我才要這麼做。碰觸真相，接近真相，揭開真相。"
  },
  AvgDialog_89882_Content_19 = {
    Text = "看向熔毀·朵爾"
  },
  AvgDialog_89882_Content_2 = {
    Text = "那就是「交易」的結果。\n你的內心隱隱察覺出了這點。"
  },
  AvgDialog_89882_Content_20 = {
    Text = "好吧。不過是捲入麻煩裡而已。過去我們已經無數次這麼做過了。"
  },
  AvgDialog_89882_Content_21 = {
    Text = "去吧，我的小狗。我就在這裡，保證你的安全。"
  },
  AvgDialog_89882_Content_22 = {
    Text = "你深呼吸，然後伸手，碰觸那完整的象牙頭雕。"
  },
  AvgDialog_89882_Content_23 = {
    Text = "一瞬間，強烈的衝擊自你的靈魂深處擴散，你看到無數的光與影。"
  },
  AvgDialog_89882_Content_24 = {
    Text = "這些光影穿梭著，融化著，緩慢構築起一個畫面"
  },
  AvgDialog_89882_Content_25 = {
    Text = "利莫里亞"
  },
  AvgDialog_89882_Content_26 = {
    Text = "@4，今天在這裡玩嗎？"
  },
  AvgDialog_89882_Content_27 = {
    Text = "夥伴們，加入奧瑞塔吧。"
  },
  AvgDialog_89882_Content_28 = {
    Text = "奧瑞塔想和朋友們一起玩！"
  },
  AvgDialog_89882_Content_29 = {
    Text = "在那無盡的深紅中，女孩天真地笑著，歡樂地跳著，而她的每一次歡笑，每一次躍動，都伴隨著死亡。"
  },
  AvgDialog_89882_Content_3 = {
    Text = "這是……象牙雕像？"
  },
  AvgDialog_89882_Content_30 = {
    Text = "奧瑞塔……"
  },
  AvgDialog_89882_Content_31 = {
    Text = "你的心漸漸沉下去，無法呼吸。那是太過強烈的精神鏈接導致的眩惑。"
  },
  AvgDialog_89882_Content_32 = {
    Text = "深呼吸……冷靜……冷靜。"
  },
  AvgDialog_89882_Content_33 = {
    Text = "隨著你不停呼吸，令人迷失的暈眩感終於開始褪去，你即將回到現實——"
  },
  AvgDialog_89882_Content_34 = {
    Text = "巨浪拍擊的海灘邊，薩爾瓦多、熔毀·朵爾和珊將你護在身後，與某一道身影對峙。"
  },
  AvgDialog_89882_Content_35 = {
    Text = "凱刻斯？"
  },
  AvgDialog_89882_Content_36 = {
    Text = "孱弱的人類，你沒有資格稱呼我的名字。這是對我褻瀆！"
  },
  AvgDialog_89882_Content_37 = {
    Text = "凱刻斯，奧瑞塔在哪裡？"
  },
  AvgDialog_89882_Content_38 = {
    Text = "奧瑞塔？那和你無關。你再次直呼我的名字，是瞧不起我嗎？"
  },
  AvgDialog_89882_Content_39 = {
    Text = "你會後悔的，任何輕視我血脈之人，都會付出代價。"
  },
  AvgDialog_89882_Content_40 = {
    Text = "來吧，流著高貴血脈之族裔，讓他們見識見識深海的力量。"
  },
  AvgDialog_89882_Content_41 = {
    Text = "凱刻斯閉上眼睛呼喚，而隨著他的呼喚，巨浪翻湧，數不清的海怪自深海浮現。"
  },
  AvgDialog_89882_Content_5 = {
    Text = "不是很像，是一模一樣。只是這個，是完整的。"
  },
  AvgDialog_89882_Content_6 = {
    Text = "看來那個可愛的女孩不只交了我一個「朋友」。"
  },
  AvgDialog_89882_Content_7 = {
    Text = "交朋友？呵，恐怕是<Yellow:被利用，成為了邪惡祭祀的一部分>吧。"
  },
  AvgDialog_89882_Content_8 = {
    Text = "一瞬間，你的心情沉重萬分。"
  },
  AvgDialog_89882_Content_9 = {
    Text = "無論如何，奧瑞塔都造成了無法挽回的傷害。"
  },
  AvgDialog_90536_Content_1 = {Text = "窄門外"},
  AvgDialog_90536_Content_10 = {
    Text = "（每當這時候，波呂克斯就會又變得像從前一樣了，真好。）"
  },
  AvgDialog_90536_Content_11 = {
    Text = "兩人用盡一切可能的機會，將這片從小生活的地方仔細地摸索清楚，又耐心謹慎地等待著，直到一個完美的時機出現。"
  },
  AvgDialog_90536_Content_12 = {
    Text = "趁著於麗埃特離開教會、而所有教眾都在為一場盛大的儀式忙碌時，兩人終於沿著那些曲折的小路，悄無聲息地離開了關鎖他們的牢籠。"
  },
  AvgDialog_90536_Content_13 = {
    Text = "快，快點，馬上就到了。"
  },
  AvgDialog_90536_Content_14 = {
    Text = "這邊的出口太高了，我還，我還不太會飛呢！"
  },
  AvgDialog_90536_Content_15 = {
    Text = "沒時間換一條路了，害怕的話就抓緊我，我不會讓你掉下去的，準備好——跳！"
  },
  AvgDialog_90536_Content_16 = {
    Text = "兩對稚嫩的翅膀一瞬衝進了寧靜的夜空，激烈鼓動的心跳淹沒在耳畔呼嘯的風中。"
  },
  AvgDialog_90536_Content_17 = {
    Text = "圓月如盤，星河如洗，這個晴朗夏夜無數細微的風景都照進了兩個少年的眼中。"
  },
  AvgDialog_90536_Content_18 = {
    Text = "原來從天上看，世界是這樣的……"
  },
  AvgDialog_90536_Content_19 = {
    Text = "兩個人睜大了眼，就這樣呆呆地、不知疲倦地一直飛啊飛啊。"
  },
  AvgDialog_90536_Content_2 = {
    Text = "一場隱秘的冒險在兩個少年的心中慢慢籌劃、發芽。"
  },
  AvgDialog_90536_Content_20 = {
    Text = "啊……我們到哪裡了？我們之後要去哪呢？"
  },
  AvgDialog_90536_Content_21 = {
    Text = "地圖……就到這裡了，不過我們可以再畫一份新的！重要的是我們成功了，我們自由了！卡斯托爾！"
  },
  AvgDialog_90536_Content_22 = {
    Text = "自由……我們以後再也不用背經文，你也不用再去進行改造儀式了！"
  },
  AvgDialog_90536_Content_23 = {
    Text = "對，我們還可以去任何想去的地方，做任何想做的事，沒有人可以再來控制我們了！"
  },
  AvgDialog_90536_Content_24 = {
    Text = "波呂克斯開懷地大笑，他拉起卡斯托爾的胳膊，帶著他在空中劃過一個又一個華麗的圈。"
  },
  AvgDialog_90536_Content_25 = {
    Text = "卡斯托爾在失重的眩暈中驚恐地叫喊，卻也在旋轉中感到一種如釋重負的快樂。"
  },
  AvgDialog_90536_Content_26 = {
    Text = "呸呸……手抄本上說這種草可以食用，沒說過有這麼難吃啊！"
  },
  AvgDialog_90536_Content_27 = {
    Text = "也可能是我們的吃法不對，畢竟現在沒有廚房和廚師替我們準備三餐了。"
  },
  AvgDialog_90536_Content_28 = {
    Text = "沒關係，手抄本上還寫了那麼多種植物，總有一種會好吃的！"
  },
  AvgDialog_90536_Content_29 = {
    Text = "<Small:你上次吃到酸果子的時候也是這麼說的。>"
  },
  AvgDialog_90536_Content_3 = {
    Text = "即便看了那麼多遍騎士的冒險故事，卡斯托爾還是沒能習慣這樣出格的行為。"
  },
  AvgDialog_90536_Content_30 = {
    Text = "卡斯托爾歎了一口氣，認命地和波呂克斯一起打開了手抄本，從這本指引著他們的神聖之書上找尋生存的秘訣。"
  },
  AvgDialog_90536_Content_31 = {
    Text = "於是兩個小騎士展開了他們全新的冒險。"
  },
  AvgDialog_90536_Content_32 = {
    Text = "他們在森林裡辨別無毒的蘑菇，和松鼠爭搶樹果，從樹洞中與枝椏上偷走新鮮的鳥蛋。"
  },
  AvgDialog_90536_Content_33 = {
    Text = "他們走啊，走啊，穿過森林，翻過山丘。"
  },
  AvgDialog_90536_Content_34 = {
    Text = "他們與好奇的野鹿互相凝望，他們跟隨狼群的腳印找到水源。"
  },
  AvgDialog_90536_Content_35 = {
    Text = "在夜裡，他們擊敗偷襲的野獸，並學會了如何點燃枯枝、製作篝火。"
  },
  AvgDialog_90536_Content_36 = {
    Text = "他們在山丘頂上欣賞遠方的原野與草浪，然後睡在月亮與星星下面。"
  },
  AvgDialog_90536_Content_37 = {
    Text = "饑餓與疲憊令他們的肚子常常叫喚，但兩個小騎士並不害怕，他們互相攙扶著，興奮而勇敢地探索著無邊的世界。"
  },
  AvgDialog_90536_Content_38 = {
    Text = "他們漫無目的，任何方向都充滿新鮮的境遇，唯一指引他們的只有好奇與自由的心靈。"
  },
  AvgDialog_90536_Content_39 = {
    Text = "他們還想去很多地方，去看書上說的大海、沙漠和牛羊遍地的牧場。"
  },
  AvgDialog_90536_Content_4 = {
    Text = "他小心、笨拙地跟隨著波呂克斯的指示，一同在深夜中偷偷探索，充實著兩人自由的地圖。"
  },
  AvgDialog_90536_Content_40 = {
    Text = "但，剛剛學會飛行的鳥兒不會想到，老練的獵人早已將槍口對準了它們的翅膀。"
  },
  AvgDialog_90536_Content_41 = {
    Text = "刹那間，殘酷的烈焰焚毀了冒險的森林，濃煙與火光充滿了他們逃亡的道路。"
  },
  AvgDialog_90536_Content_42 = {
    Text = "松鼠從樹上跌落，麻雀無力飛起，小鹿倒在灌木之間。"
  },
  AvgDialog_90536_Content_43 = {
    Text = "他們無暇為剛剛結識的朋友悲傷，在四面的追趕中，他們只能絕望地奔逃。"
  },
  AvgDialog_90536_Content_44 = {
    Text = "終於，饑餓與盲目吞噬了他們，精疲力盡的兩個少年被重新追上，一場奮力的抵抗最後在獵人的怒火中以悲鳴告終。"
  },
  AvgDialog_90536_Content_45 = {
    Text = "鳥兒們被重新關回了籠中。"
  },
  AvgDialog_90536_Content_46 = {
    Text = "兩個少年被燈衛按著，跪伏在教會寂靜的祭壇下。"
  },
  AvgDialog_90536_Content_47 = {
    Text = "私自潛逃、抗拒追捕、殺戮燈衛，這就是我們的聖子回報給教會的，說說吧，這些都是誰的計劃？"
  },
  AvgDialog_90536_Content_49 = {
    Text = "卡斯托爾不甚熟練地想要撒謊，卻被快速開口的波呂克斯打斷。"
  },
  AvgDialog_90536_Content_5 = {
    Text = "把今天晚上發現的這條水道也畫在地圖上吧，那地方偏得完全沒有人去，但我們可以從那裡遊過去！"
  },
  AvgDialog_90536_Content_50 = {
    Text = "是我。您應該知道，卡斯托爾那樣木訥的傢伙是不會有這些想法的。"
  },
  AvgDialog_90536_Content_51 = {
    Text = "於麗埃特的雙眼眯起，不變的笑容中流露出一絲難以壓抑的怒火。"
  },
  AvgDialog_90536_Content_52 = {
    Text = "好，很好，嚮往天空的飛鳥，多麼感人的故事，既然這對沒用的東西如此礙事，不如乾脆拔了吧。"
  },
  AvgDialog_90536_Content_53 = {
    Text = "她隨意地揮了揮手，幾個燈衛應聲上前，狠狠抓住了波呂克斯的翅膀。"
  },
  AvgDialog_90536_Content_54 = {
    Text = "什……等等！教主大人！請您再考慮一下！波呂克斯他只是想看看外面的世界，他只是在改造儀式中太痛苦了……"
  },
  AvgDialog_90536_Content_55 = {
    Text = "在卡斯托爾驚恐的掙扎中，波呂克斯靜靜地回過頭，他的口型無聲開合，向自己的兄長露出安撫的笑容。"
  },
  AvgDialog_90536_Content_56 = {
    Text = "不要低頭，哥哥。"
  },
  AvgDialog_90536_Content_57 = {
    Text = "<Shake:是我，是我攻擊了燈衛，要懲罰的話就請懲罰我吧！不……不！>"
  },
  AvgDialog_90536_Content_58 = {
    Text = "虛弱的卡斯托爾無法在燈衛的控制下挪動半分，他只能眼睜睜看著那雙纖長優美的翅膀被幾雙手粗暴地抓緊、繃直，發出骨骼瀕臨斷裂的脆弱聲響。"
  },
  AvgDialog_90536_Content_59 = {
    Text = "<Small:<Shake:堅持下去，為了自由。>>"
  },
  AvgDialog_90536_Content_6 = {
    Text = "好，不過……能不走還是不走這裡吧，翅膀泡在水里的感覺好不舒服。"
  },
  AvgDialog_90536_Content_60 = {
    Text = "隨著一聲恐怖的撕裂聲響起，一簇溫熱的鮮血迸濺在卡斯托爾目眥欲裂的面龐。"
  },
  AvgDialog_90536_Content_62 = {
    Text = "波呂克斯！！！噗咳……"
  },
  AvgDialog_90536_Content_63 = {
    Text = "劇烈的情緒波動沖垮了卡斯托爾在逃亡中傷重的身體，他不受控制地倒向地面，慢慢陷入昏迷。"
  },
  AvgDialog_90536_Content_64 = {
    Text = "哦，差點忘記我們的卡斯托爾聖子剛剛受了這麼重的傷呢。"
  },
  AvgDialog_90536_Content_65 = {
    Text = "於麗埃特冰冷的目光俯視著鮮血淋漓的兩個少年，一旁的教眾上前低聲詢問了什麼，卻只換來於麗埃特漫不經心地搖頭。"
  },
  AvgDialog_90536_Content_66 = {
    Text = "治療？不需要，將卡斯托爾丟到<Yellow:罪潭>中吧，神血會洗淨他的罪惡，等什麼時候罪惡流乾，什麼時候再讓他出來。"
  },
  AvgDialog_90536_Content_67 = {
    Text = "卡斯托爾渙散的視線看向波呂克斯那雙凋落在地的、被用提燈的火焰燒毀的翅膀。"
  },
  AvgDialog_90536_Content_68 = {
    Text = "懷中所珍藏的那片落羽彷彿在灼燒他的靈魂，那是在他們冒險的途中，他無心之下為波呂克斯收起的。"
  },
  AvgDialog_90536_Content_69 = {
    Text = "（那怎麼會是，他最後的一片羽毛呢……）"
  },
  AvgDialog_90536_Content_7 = {
    Text = "忍一忍就過去了！只有一小段而已，這可是關乎我們自由的大事！"
  },
  AvgDialog_90536_Content_71 = {
    Text = "貴為聖子，卡斯托爾從來不知道教會的地下還有這樣一塊純黑色的水潭。"
  },
  AvgDialog_90536_Content_72 = {
    Text = "他被關鎖在其中，那潭水粘稠如漿，將他浸泡。\n恐怖的黏液侵蝕著他的傷口，卻並沒有想像之中的劇痛。"
  },
  AvgDialog_90536_Content_73 = {
    Text = "一種難以言明的虛無感籠罩了他，彷彿有一部分的靈魂正在被緩慢抽出。"
  },
  AvgDialog_90536_Content_74 = {
    Text = "過去多久了……傷口好像乾涸了，又好像，只是感覺不到那一塊血肉了……"
  },
  AvgDialog_90536_Content_75 = {
    Text = "絕對的寂靜就是最恐怖的懲罰。\n他動彈不得，只能在這片漆黑的地獄中默數著逐漸混亂的時間。"
  },
  AvgDialog_90536_Content_76 = {
    Text = "等到終於被帶出罪潭時，卡斯托爾的翅膀已經被融蝕侵蝕得面目全非，但他仍然迫不及待地品味著胸腔中久違的激烈跳動。"
  },
  AvgDialog_90536_Content_77 = {
    Text = "他的牽掛，他的支撐，他唯一的親人，終於可以與他重逢。"
  },
  AvgDialog_90536_Content_78 = {
    Text = "（馬上就能和波呂克斯見面了，那群侍女身後的好像就是……波呂克斯！）"
  },
  AvgDialog_90536_Content_79 = {
    Text = "（他長高了，好像瘦了一些，好在沒有更多傷疤，只是那對漂亮的翅膀……）"
  },
  AvgDialog_90536_Content_8 = {
    Text = "好吧，你說得對，騎士是不會害怕冒險的艱辛的。"
  },
  AvgDialog_90536_Content_80 = {
    Text = "穿著聖子華服的波呂克斯這才注意到了遠處卡斯托爾的目光，施施然地走了過來。"
  },
  AvgDialog_90536_Content_81 = {
    Text = "你就是要與我共事的另一個聖子嗎？真是有些……寒酸，希望之後主持賜福的時候，你不要丟了持燈者的臉面。"
  },
  AvgDialog_90536_Content_82 = {
    Text = "他只是輕蔑地打量著近鄉情怯、束手束腳的卡斯托爾，彷彿從不曾見過這個人。"
  },
  AvgDialog_90536_Content_83 = {
    Text = "……你在說什麼？是我啊，波呂克斯，是哥哥啊……"
  },
  AvgDialog_90536_Content_84 = {
    Text = "卡斯托爾有些惶急地低頭看了看身上經歷融蝕的種種痕跡，害怕是自己也在漫長的折磨中變了樣子。"
  },
  AvgDialog_90536_Content_85 = {
    Text = "（等等，會不會他只是要在侍從面前做戲？）"
  },
  AvgDialog_90536_Content_86 = {
    Text = "卡斯托爾看著眉頭嫌棄皺起的波呂克斯，試探性地打了一個手勢，那是兒時兩人共同發明的密語。"
  },
  AvgDialog_90536_Content_87 = {
    Text = "——“你感覺如何？”"
  },
  AvgDialog_90536_Content_89 = {
    Text = "<Small:你說的自由，我一直都記得。>"
  },
  AvgDialog_90536_Content_9 = {
    Text = "卡斯托爾有些不好意思地縮了縮翅膀，又點點頭給兩人打起氣來。"
  },
  AvgDialog_90536_Content_90 = {
    Text = "波呂克斯無動於衷地看著反復試探的卡斯托爾，那雙一貫充滿笑意的眼睛刻薄而慍怒地垂著。"
  },
  AvgDialog_90536_Content_91 = {
    Text = "什麼自由？你在說什麼瘋話，如果大病初癒腦袋不清醒，可以多去祭壇祈禱幾次。"
  },
  AvgDialog_90536_Content_92 = {
    Text = "你……你不記得我們一起逃出教會的事了嗎？"
  },
  AvgDialog_90536_Content_93 = {
    Text = "你在說什麼不敬之語？我是教會的聖子，什麼時候做過這樣荒謬的蠢事？"
  },
  AvgDialog_90536_Content_94 = {
    Text = "那張冷漠的臉上終於有了變化，波呂克斯震驚地彈開，頗為惱怒地對著滿目委屈的卡斯托爾大聲呵斥。"
  },
  AvgDialog_90536_Content_95 = {
    Text = "收起你那噁心的眼神。"
  },
  AvgDialog_90536_Content_96 = {
    Text = "另外奉勸你一句，卡斯托爾閣下，你我不過是共同侍奉持燈者的聖子，人後無事之時，就不必太過親昵了，令人徒增厭煩。"
  },
  AvgDialog_90536_Content_97 = {
    Text = "卡斯托爾張大著眼，這才不得不緩慢地明白過來一件事實——"
  },
  AvgDialog_90536_Content_98 = {
    Text = "<Red:在那別無二致的軀殼裡的，已不是他過去熟悉的弟弟了>"
  },
  AvgDialog_90537_Content_1 = {
    Text = "失序命運"
  },
  AvgDialog_90537_Content_10 = {
    Text = "但，我知道你並不害怕它，你比我要勇敢很多，小鳥兒。"
  },
  AvgDialog_90537_Content_11 = {
    Text = "如果你想要摘下那柄利劍作為武器，我會幫你，但我希望你不要有用到它的那一天。"
  },
  AvgDialog_90537_Content_12 = {
    Text = "那一截你曾吞下的枝條只是在我的力量下沉睡了，當它再次生長時，它會把你的生命當做養分。"
  },
  AvgDialog_90537_Content_13 = {
    Text = "我會教給你主動催發它的方法，你要想清楚，枝條一旦生長就無法再逆轉了，你沒有後悔的機會。"
  },
  AvgDialog_90537_Content_14 = {
    Text = "保重了，小鳥兒。"
  },
  AvgDialog_90537_Content_16 = {
    Text = "我不會後悔的。"
  },
  AvgDialog_90537_Content_17 = {
    Text = "卡斯托爾喃喃著跪倒，他感到身體在提燈的儀式的作用下慢慢融化。"
  },
  AvgDialog_90537_Content_18 = {
    Text = "此時他的體內出現了一個漩渦，正飛快吞食著他的生命，帶他走向消散的終結。"
  },
  AvgDialog_90537_Content_19 = {
    Text = "不知為何那截枝條並沒有從他的腹中穿透生長，只是單純的吞噬著，讓他的一寸寸羽毛、皮膚的邊界都詭異地虛化起來。"
  },
  AvgDialog_90537_Content_2 = {
    Text = "想好要怎麼對付那個難纏的女人了嗎，小鳥兒，萬一你們失敗了，我恐怕沒有多餘的力量來救你。"
  },
  AvgDialog_90537_Content_20 = {
    Text = "這一次他完全敞開了一切，他不再不甘痛苦，他要用這份解脫，親手換取弟弟的自由。"
  },
  AvgDialog_90537_Content_22 = {
    Text = "不遠處的於麗埃特發現了卡斯托爾的異樣，她的身影剛剛一動，便被一條憑空抽來的樹枝阻攔在原地。"
  },
  AvgDialog_90537_Content_23 = {
    Text = "那棵原本已經枯死的小樹此刻忽然煥發了新的生機，其中沉睡的泰旖絲一同睜開了眼，正微笑注視著她。"
  },
  AvgDialog_90537_Content_24 = {
    Text = "想過去嗎？可沒有那麼容易哦，你的對手是我。"
  },
  AvgDialog_90537_Content_25 = {Text = "嘖。"},
  AvgDialog_90537_Content_26 = {
    Text = "……卡斯托爾？你怎麼了？！"
  },
  AvgDialog_90537_Content_27 = {
    Text = "痛苦搖晃的波呂克斯回過頭，這才發現卡斯托爾迅速衰敗下去的異樣，驚惶地奔向自己此時唯一的戰友。"
  },
  AvgDialog_90537_Content_28 = {
    Text = "用那把匕首……殺了我，快……"
  },
  AvgDialog_90537_Content_29 = {
    Text = "我為什麼要殺你！你不准死，卡斯托爾你這個懦夫！"
  },
  AvgDialog_90537_Content_3 = {
    Text = "所以，我不會失敗的，我不會允許那樣的結局再次出現了……我想請求你，給予我絕對能夠死去的辦法。"
  },
  AvgDialog_90537_Content_30 = {
    Text = "波呂克斯伸出手想要查看卡斯托爾的狀況，卻對著那滿身自己剛剛刻下的、鮮血淋漓的傷口無所適從。"
  },
  AvgDialog_90537_Content_31 = {
    Text = "只要我死了，你就能活下來。"
  },
  AvgDialog_90537_Content_33 = {
    Text = "卡斯托爾握住了波呂克斯那只抓著匕首的手，輕柔地將它引向自己的胸膛，卻被波呂克斯狠狠打開。"
  },
  AvgDialog_90537_Content_34 = {
    Text = "誰要你自作主張？誰允許你替我決定？你想丟下我一個人嗎！"
  },
  AvgDialog_90537_Content_35 = {
    Text = "總是莫名其妙地逞英雄，讓我厭惡你，又讓我虧欠你……"
  },
  AvgDialog_90537_Content_36 = {
    Text = "我不會感謝你的，我恨你！你聽見了嗎！我恨你！"
  },
  AvgDialog_90537_Content_37 = {
    Text = "恨嗎……呵呵，沒關係，這一切很快就會結束了……"
  },
  AvgDialog_90537_Content_38 = {
    Text = "卡斯托爾看向猛地丟開匕首的波呂克斯，從那彆扭的大吼中感到了一絲不舍。"
  },
  AvgDialog_90537_Content_39 = {
    Text = "他欣慰地笑了笑，慢慢蜷縮起衰弱的身體，就像要回歸誕生時的姿勢一樣。"
  },
  AvgDialog_90537_Content_4 = {
    Text = "……你真的這樣決定了嗎？"
  },
  AvgDialog_90537_Content_40 = {
    Text = "一會兒你要拼命地跑，跑得越遠越好……"
  },
  AvgDialog_90537_Content_41 = {
    Text = "你要去看一看雪山的花，去看看大海的顏色，去嘗一嘗，自由是什麼味道……"
  },
  AvgDialog_90537_Content_43 = {
    Text = "在斷斷續續的呢喃中，在波呂克斯慌亂的呼喊中，卡斯托爾的氣息漸漸消失了。"
  },
  AvgDialog_90537_Content_44 = {
    Text = "他的身體倏然沙一般坍塌，化作了點點螢光，飄散在了空中。"
  },
  AvgDialog_90537_Content_45 = {
    Text = "在模糊視線的淚水中，波呂克斯徒勞地抓握著，擁抱著那些光點，感到有什麼生命中最重要的東西在那一瞬間失去了。"
  },
  AvgDialog_90537_Content_46 = {
    Text = "地上越來越亮的法陣仍然徒勞地運作著，卻只是將那些螢光融入了波呂克斯的身體。"
  },
  AvgDialog_90537_Content_48 = {
    Text = "洶湧的記憶一刹那淹沒了波呂克斯，像是命運的閘門豁然打開，兩個源於一體的靈魂就此重逢。"
  },
  AvgDialog_90537_Content_49 = {
    Text = "那些整日頤指氣使的生活像是虛假的泡沫一般倒退、消散了。"
  },
  AvgDialog_90537_Content_5 = {
    Text = "是，我相信你一定有那樣的力量，不管於麗埃特想要利用聖子做什麼，她都一定需要兩個聖子同時存在。"
  },
  AvgDialog_90537_Content_50 = {
    Text = "他回憶起了他們寂寞的童年，回憶起了那本轉折命運的手抄本，回憶起了他們出逃與失敗。"
  },
  AvgDialog_90537_Content_51 = {
    Text = "在那源自靈魂的糾纏中，他甚至從命運罅隙的幻影裡一瞬窺到了他們的誕生——"
  },
  AvgDialog_90537_Content_52 = {
    Text = "嘖，又不是雙生麼？唉，直接處理掉吧，不要讓他來到這污濁的世界上受苦了。"
  },
  AvgDialog_90537_Content_53 = {
    Text = "像是預知到了死亡的命運，那個原本即將被拋棄的失敗實驗品突然開始掙扎扭動著。"
  },
  AvgDialog_90537_Content_54 = {
    Text = "隨著一聲細弱、陰鬱的啼哭響起，原本孤單的血肉向外膨脹撕扯著，生長出了另一個生命。"
  },
  AvgDialog_90537_Content_55 = {
    Text = "他也回憶起瞭如何在教會的手段下，在那日復一日重複的神學課中，逐漸將卡斯托爾忘記的過去。"
  },
  AvgDialog_90537_Content_56 = {
    Text = "卡斯托爾進入罪潭的第7天"
  },
  AvgDialog_90537_Content_57 = {
    Text = "兩人被分開後，波呂克斯並沒有遭受同樣的酷刑，在翅膀斷裂的傷口癒合後，他便在於麗埃特親自的教導下開始學習提燈的神學。"
  },
  AvgDialog_90537_Content_58 = {
    Text = "再一次夢到卡斯托爾後，波呂克斯於深夜中悚然驚醒。"
  },
  AvgDialog_90537_Content_59 = {
    Text = "唔……可惡，頭好痛……什麼體悟經文，那個女人一定給我動了什麼手腳，腦海中哥哥的面容，為什麼有些模糊了……"
  },
  AvgDialog_90537_Content_6 = {
    Text = "如果最終我們仍然不能逃離所謂的宿命，那麼，就徹底毀掉它吧。"
  },
  AvgDialog_90537_Content_60 = {
    Text = "記下來，要記下來……不，不能用紙，會被發現……"
  },
  AvgDialog_90537_Content_61 = {
    Text = "對，刻下來，刻在一個隱蔽的地方……就刻在床下！他們不會找到這裡的……"
  },
  AvgDialog_90537_Content_62 = {
    Text = "把我們從出生起的所有，還有逃走的計劃，那些一點點探索的路線，通通刻下來！想要奪走我的意志，你休想得逞！"
  },
  AvgDialog_90537_Content_63 = {
    Text = "等著我，哥哥，我一定會找到機會，再次帶你逃走的……"
  },
  AvgDialog_90537_Content_64 = {
    Text = "卡斯托爾進入罪潭的第@1天"
  },
  AvgDialog_90537_Content_65 = {
    Text = "日復一日不斷重複的麻木修行中，波呂克斯已經習慣了在每天晚上準時醒來。"
  },
  AvgDialog_90537_Content_66 = {
    Text = "這隱秘而執著的雕刻時間，是他在這樣暗無天日的生活中唯一支撐下去的希望。"
  },
  AvgDialog_90537_Content_67 = {
    Text = "他又一次在混亂的夢境中猛地坐起，急迫地要繼續那未竟的事業。"
  },
  AvgDialog_90537_Content_68 = {
    Text = "哈……快起來，要繼續刻，刻下我們的記憶……"
  },
  AvgDialog_90537_Content_69 = {
    Text = "刻到哪裡了，刻到我們第一次偷偷學飛，然後飛去了……"
  },
  AvgDialog_90537_Content_7 = {
    Text = "哪怕犧牲你所有的未來？"
  },
  AvgDialog_90537_Content_70 = {
    Text = "……然後飛去了哪裡？"
  },
  AvgDialog_90537_Content_71 = {
    Text = "巨大的恐慌攫取了他的心臟，波呂克斯神經質地捶打著自己的腦袋，幾乎要被洪水般的無力感淹沒。"
  },
  AvgDialog_90537_Content_72 = {
    Text = "波呂克斯！沒用的腦子，想起來，快點想起來，你不能忘！你絕對不能……"
  },
  AvgDialog_90537_Content_73 = {
    Text = "卡斯托爾進入罪潭的第@2天"
  },
  AvgDialog_90537_Content_75 = {
    Text = "我要做什麼事……對，我要起來，我要記些東西……"
  },
  AvgDialog_90537_Content_76 = {
    Text = "波呂克斯幽魂一樣起身，恍惚地在屋內遊蕩著。"
  },
  AvgDialog_90537_Content_77 = {
    Text = "原本是記在哪裡的？不是這裡，不是這裡……對，對，在床下……"
  },
  AvgDialog_90537_Content_78 = {
    Text = "他彎下腰去，摸索著看向床底密密麻麻的刻痕。"
  },
  AvgDialog_90537_Content_79 = {
    Text = "好多的字，我有寫過這麼多東西嗎？"
  },
  AvgDialog_90537_Content_8 = {
    Text = "哪怕犧牲我所有的未來。"
  },
  AvgDialog_90537_Content_80 = {
    Text = "這是……什麼，卡斯托爾……是誰？"
  },
  AvgDialog_90537_Content_81 = {
    Text = "波呂克斯呆坐在原地，費力地辨認著那些已被融蝕模糊的字跡。"
  },
  AvgDialog_90537_Content_82 = {
    Text = "這些字，怎麼看不清了……"
  },
  AvgDialog_90537_Content_83 = {
    Text = "好難過，為什麼突然這麼想流淚呢……"
  },
  AvgDialog_90537_Content_9 = {
    Text = "……一直以來，我都喜愛生命，厭惡死亡，我恐懼著那柄高懸在頭頂的利劍，所以想盡辦法逃離它。"
  },
  AvgDialog_90538_Content_1 = {
    Text = "純黑羽翼"
  },
  AvgDialog_90538_Content_10 = {
    Text = "我會的，那些書裡的景色，我會帶你一起去看……"
  },
  AvgDialog_90538_Content_100 = {
    Text = "像是曾經誕生之時的光景，一道新生的人影蜷縮著，從波呂克斯的背後緩緩成型、脫出，完成了又一次生命的輪回。"
  },
  AvgDialog_90538_Content_101 = {
    Text = "那雙虛幻的翅膀也隨著那個靈魂的脫離一同脫離了波呂克斯的身體，回歸到了它真正的主人身上。"
  },
  AvgDialog_90538_Content_102 = {
    Text = "……波呂克斯？我不是已經……難道你也？"
  },
  AvgDialog_90538_Content_103 = {
    Text = "在波呂克斯怔愣的、流下淚水的雙眼中，倒映著卡斯托爾迷茫而焦急的面龐。"
  },
  AvgDialog_90538_Content_104 = {
    Text = "泰旖絲也在？所以這裡不是淨土……"
  },
  AvgDialog_90538_Content_105 = {
    Text = "卡斯托爾在混亂的思緒中左顧右盼著，試圖理清這些生死的奧秘，他的臉上混雜著迷惑、欣喜、擔憂，唯獨沒有一絲怨恨。"
  },
  AvgDialog_90538_Content_106 = {
    Text = "在波呂克斯忍俊不禁的笑容中，卡斯托爾也後知後覺地露出一個重逢的笑。"
  },
  AvgDialog_90538_Content_107 = {
    Text = "遠處高曠而晴朗的天空上，一群白色的飛鳥啼叫著飛過，遼遠的大地上，兩個久別重逢的靈魂相對而望。"
  },
  AvgDialog_90538_Content_108 = {
    Text = "他們是兄弟、是雙生的鳥、是唯一的摯友、是一同被命運審判的囚徒。"
  },
  AvgDialog_90538_Content_109 = {
    Text = "至少這一次，再也沒有什麼能讓他們分開。"
  },
  AvgDialog_90538_Content_11 = {
    Text = "像是失去了最重要的原料一般，地面密密麻麻混雜著鮮血的咒文黯淡了下去，空氣中那種令萬物靜止的威壓也突然鬆動了。"
  },
  AvgDialog_90538_Content_12 = {
    Text = "四周吟誦的教眾迷茫地張望著，那些跟隨於麗埃特一同與泰旖絲戰鬥的燈衛也惶惑地看向了自己的教主。"
  },
  AvgDialog_90538_Content_13 = {
    Text = "控制住他，重新啟動儀式！"
  },
  AvgDialog_90538_Content_14 = {
    Text = "於麗埃特陰沉著臉，身旁的巨犬群更加瘋狂地撕咬、閃避，與舞動的枝條殘影不斷碰撞在一起。"
  },
  AvgDialog_90538_Content_15 = {
    Text = "一群燈衛蝗蟲一樣撲來，消耗著泰旖絲本就虛弱的力量，更多教眾靠近了儀式陣中央，舉起了一盞盞搖晃的提燈。"
  },
  AvgDialog_90538_Content_16 = {
    Text = "願您注視，願您垂憐……"
  },
  AvgDialog_90538_Content_17 = {
    Text = "一道道法咒催動的光芒亮起，那些凌遲一般的疼痛如懲戒的鞭笞，曾將恐懼刻在雙子的骨血。"
  },
  AvgDialog_90538_Content_18 = {
    Text = "閉上嘴……你們這些骯髒蛆蟲……"
  },
  AvgDialog_90538_Content_19 = {
    Text = "立於法陣中央的波呂克斯安靜地閉目，只有胸口那一顆聖心流轉著更加明亮的光芒。"
  },
  AvgDialog_90538_Content_2 = {
    Text = "一幕幕記憶在波呂克斯腦海中閃回，他呆呆地跪坐在地，淚流滿面地注視著空空如也的懷中。"
  },
  AvgDialog_90538_Content_20 = {
    Text = "他將那根羽毛妥帖地收起，而後抬頭看向了昔日尊他敬他，如今卻將他困於囚籠的人們。"
  },
  AvgDialog_90538_Content_21 = {
    Text = "給我……<Shake:<Big:滾開！！>>"
  },
  AvgDialog_90538_Content_22 = {
    Text = "所有複雜難言的情緒此刻都化作滔天的仇恨與怒火，一陣耀目的光暈從那顆顫抖的聖心中震盪爆發。"
  },
  AvgDialog_90538_Content_23 = {
    Text = "昏暗的天空霎時亮成一片白夜，原本溫和的賜福此刻如教眾們祈禱的那樣，將所有人的罪徹底淨化。"
  },
  AvgDialog_90538_Content_24 = {
    Text = "那些衣袍下隱藏的融蝕傷口豁然擴大、潰爛，蒸騰出黑色的霧，一道道身影來不及哀嚎便倒下。"
  },
  AvgDialog_90538_Content_25 = {
    Text = "波呂克斯走過那些扭曲異化的屍體，他信手將剛剛困住他的法杖猛地拔出丟棄。"
  },
  AvgDialog_90538_Content_26 = {
    Text = "下一瞬，那只蒼白的手便出現在了泰旖絲面前，輕輕按上一隻巨犬的頭顱。"
  },
  AvgDialog_90538_Content_27 = {
    Text = "隨著一聲變調的哀嚎，巨犬倒飛而出，狠狠摔落在了於麗埃特腳邊。"
  },
  AvgDialog_90538_Content_28 = {
    Text = "原本快要力竭的泰旖絲看向對峙而立的兩人，默默將戰場留給了真正需要它的人。"
  },
  AvgDialog_90538_Content_29 = {
    Text = "啊，我最聽話的乖孩子，好久沒有看到你這樣的眼神了，這是想起自己做過的一切了嗎？"
  },
  AvgDialog_90538_Content_3 = {
    Text = "原來，我把你忘記了這麼久……"
  },
  AvgDialog_90538_Content_30 = {
    Text = "<Big:<Shake:於、麗、埃、特!!!>>"
  },
  AvgDialog_90538_Content_31 = {
    Text = "你過去加之於我們身上的一切悲痛和苦難……"
  },
  AvgDialog_90538_Content_32 = {
    Text = "我要你今日……<Big:<Red:<Shake:全數奉還！>>>"
  },
  AvgDialog_90538_Content_33 = {
    Text = "滔天的仇恨與怒火點燃了那顆聖心，波呂克斯雙手翻覆，一雙漆黑的巨手裹挾著融蝕的黏液狠狠砸向於麗埃特。"
  },
  AvgDialog_90538_Content_34 = {
    Text = "哎呀，享受了這麼多年聖子的殊榮與禮遇後，要把所有過錯都推到我頭上嗎？"
  },
  AvgDialog_90538_Content_35 = {
    Text = "說不定忘掉過去之後，暴露出來的才是你的本心。那些傷害你哥哥的事，可是你自己親手做下的哦？"
  },
  AvgDialog_90538_Content_36 = {
    Text = "你以為事到如今，我還會被你迷惑麼？"
  },
  AvgDialog_90538_Content_37 = {
    Text = "於麗埃特，你還是一如既往的……傲慢且愚蠢。"
  },
  AvgDialog_90538_Content_38 = {
    Text = "唉，我可是一直包容著你們，屢次原諒了你們的不敬，將你們的性命好好照顧到今天呢。"
  },
  AvgDialog_90538_Content_39 = {
    Text = "性命？我們的性命，乃至命運不過都是你利用的工具。"
  },
  AvgDialog_90538_Content_4 = {
    Text = "那些傷害、誤解、背叛，後悔、愧疚、痛苦，一切話語都無法再傳達到虧欠之人的耳畔。"
  },
  AvgDialog_90538_Content_40 = {
    Text = "混淆黑白、扭曲人心、褻瀆生命……你所做的哪樣事情，其下沒有深埋枉死者的靈魂？"
  },
  AvgDialog_90538_Content_41 = {
    Text = "你那為「淨化世界」所生的雙手，卻沾滿著世上最污穢、最無法洗脫的罪孽。"
  },
  AvgDialog_90538_Content_42 = {
    Text = "我將代表所有，因你扭曲的欲望走向慘痛悲劇的生靈，讓你於此，<Big:<Red:血債血償！！！>>"
  },
  AvgDialog_90538_Content_43 = {
    Text = "兩人的力量盛大地轟鳴，融蝕與鮮血淋漓地飛散，這樣痛快的復仇波呂克斯已經等待了太久太久。"
  },
  AvgDialog_90538_Content_44 = {
    Text = "無能的怒火最是可憐，以弱小無知之身試圖掌握命運，本就註定是一場悲劇。"
  },
  AvgDialog_90538_Content_45 = {
    Text = "或許背叛才是你最擅長的事，當初你背叛了教會，後來你背叛了你的哥哥，現在你又一次選擇了背叛我。"
  },
  AvgDialog_90538_Content_46 = {
    Text = "但不要忘了，你的本領、知識，乃至你的生命，你的一切都是我所賦予，你又拿什麼來背叛我呢？"
  },
  AvgDialog_90538_Content_47 = {
    Text = "更何況，你真的覺得自己已經得到自由了嗎？"
  },
  AvgDialog_90538_Content_48 = {
    Text = "於麗埃特那雙紫色眼睛中的笑意更加濃郁，她的口型輕輕開合，將某種咒語無聲吐出。"
  },
  AvgDialog_90538_Content_5 = {
    Text = "原來親手傷害對方時所流下的眼淚並不是兔死狐悲的不忍，而是來自真心的痛哭。"
  },
  AvgDialog_90538_Content_51 = {
    Text = "一條埋藏於血肉之下多年的繩索突然浮現，惡毒地絞緊了那顆人造的心臟。"
  },
  AvgDialog_90538_Content_52 = {
    Text = "紫色的咒文閃爍間，那盛大如白夜的光輝忽然消散了，波呂克斯五官痛苦地皺起，猛地跪倒下去。"
  },
  AvgDialog_90538_Content_53 = {
    Text = "於麗埃特……"
  },
  AvgDialog_90538_Content_54 = {
    Text = "<Shake:於麗埃特！！！>"
  },
  AvgDialog_90538_Content_55 = {
    Text = "不出意料的冷笑中，波呂克斯如頂起巨石一般直起了脊背，他將那片黑色的羽毛從懷中取出，而後將手狠狠插向了自己的胸膛。"
  },
  AvgDialog_90538_Content_56 = {
    Text = "無論付出什麼代價，我一定要殺了你……一顆心而已，還給你就是！"
  },
  AvgDialog_90538_Content_57 = {
    Text = "在他的手指觸碰到那顆黑色的心臟那一刻，一陣推力輕輕把他抗拒在外。"
  },
  AvgDialog_90538_Content_59 = {
    Text = "剛剛被儀式融入身體的那部分力量彷彿長出了靈魂，在荊棘般的咒文中，那顆黑色的心臟泛起潮水一樣的波紋。"
  },
  AvgDialog_90538_Content_6 = {
    Text = "對不起，哥哥。"
  },
  AvgDialog_90538_Content_60 = {
    Text = "白色與黑色的光輝噴薄交織，隨著咒文寸寸崩裂，一雙巨大的黑色羽翼在波呂克斯背後驟然展開。"
  },
  AvgDialog_90538_Content_61 = {
    Text = "兄長……"
  },
  AvgDialog_90538_Content_62 = {
    Text = "踏著耀眼的輝光，身負雙翼的天使懸於半空，如經文中神聖威嚴的使者，替神明降下審判。"
  },
  AvgDialog_90538_Content_63 = {
    Text = "哦？這倒是我從未想過的融合，我現在更加好奇，你的靈魂是否還能吸引持燈者的降臨了。"
  },
  AvgDialog_90538_Content_64 = {
    Text = "既然你如此虔誠，為何不將自己獻給持燈者？反而要靠我們這些你口中「低賤的靈魂」？"
  },
  AvgDialog_90538_Content_65 = {
    Text = "莫非是你的靈魂過於骯髒，無法獲得持燈者無私的救贖？"
  },
  AvgDialog_90538_Content_66 = {
    Text = "牙尖嘴利的孩子，洗淨罪孽之前，每個人都有自己的使命，老師教給你的，難道都忘了嗎？"
  },
  AvgDialog_90538_Content_67 = {
    Text = "大言不慚，不可理喻！"
  },
  AvgDialog_90538_Content_68 = {
    Text = "神聖的背叛者與虔誠的褻瀆者全力對撞在一起，那些漆黑湧動的巨手、猩紅的犬目與森白的犬牙互相撕裂又重組。"
  },
  AvgDialog_90538_Content_69 = {
    Text = "漸漸的，於麗埃特的巨犬們已開始左支右絀。流淌著「神血」的巨手高高舉起，將獵犬的頭顱拍碎在地。"
  },
  AvgDialog_90538_Content_7 = {
    Text = "我來晚了。"
  },
  AvgDialog_90538_Content_70 = {Text = "嘖……"},
  AvgDialog_90538_Content_71 = {
    Text = "給我回歸你的無罪淨土吧！！！"
  },
  AvgDialog_90538_Content_72 = {
    Text = "颶風席捲著融蝕，暴漲成黑色的龍捲，將越來越吃力的於麗埃特狠狠卷向高空，又摔向地面。"
  },
  AvgDialog_90538_Content_74 = {
    Text = "呼……呼……準備受死……"
  },
  AvgDialog_90538_Content_75 = {
    Text = "呵呵，這樣偉大的力量，也都來自我的創造……"
  },
  AvgDialog_90538_Content_76 = {
    Text = "你當然可以打敗我，可是，你真的有力量對抗整個教會嗎？"
  },
  AvgDialog_90538_Content_77 = {
    Text = "沒有了於麗埃特掣肘的泰旖絲此刻將全心回收著那顆樹種。"
  },
  AvgDialog_90538_Content_78 = {
    Text = "在她臉色變得更加蒼白後，那顆扭曲的、如孩童般嚎哭的小樹回歸了最初的樣子，變成了一顆漆黑的種子，安靜地消散在了黃沙與河流之中。"
  },
  AvgDialog_90538_Content_79 = {
    Text = "燈衛與教眾圍繞在四周，紛亂的咒術如雨落下，泰旖絲抵擋的力量也明顯變得枯竭起來。"
  },
  AvgDialog_90538_Content_8 = {
    Text = "一根熟悉的羽毛從卡斯托爾消散的地方緩緩飄落，那是卡斯托爾平日最珍惜的、連自己也不准觸碰的寶物。"
  },
  AvgDialog_90538_Content_80 = {
    Text = "更多教眾蚊蠅一般悍不畏死地湧來，毫不猶豫地用生命當做阻攔他們的薪柴。"
  },
  AvgDialog_90538_Content_81 = {
    Text = "……你的性命，總有一天我會親自來取。"
  },
  AvgDialog_90538_Content_82 = {
    Text = "那雙疲憊的翅膀猶豫一瞬，終於轉身將虛弱的泰旖絲從包圍中救出，振翅飛向了高空。"
  },
  AvgDialog_90538_Content_83 = {
    Text = "所有燈衛，找到他的蹤跡，背叛教會的，必須受到應有的審判。"
  },
  AvgDialog_90538_Content_84 = {
    Text = "哎呀哎呀，何必要趕盡殺絕呢，於麗埃特小姐，一個孤單的聖子已經沒有什麼用處了吧。"
  },
  AvgDialog_90538_Content_85 = {
    Text = "這場戲已經落幕了，如果不甘心，就為下一次好戲開場好好準備吧。"
  },
  AvgDialog_90538_Content_86 = {
    Text = "烈日下金色的沙海隨風緩緩流動著，那無盡的沙丘似乎永恆不變，只是如今踏上這裡的，已不是昨日的旅人。"
  },
  AvgDialog_90538_Content_87 = {
    Text = "在戰鬥中力竭的波呂克斯歪歪扭扭栽落在沙丘上，他面無表情地撫摸著那對重新長出的翅膀，用翅膀環攏住了自己身軀，疲憊地縮成一個繭。"
  },
  AvgDialog_90538_Content_88 = {
    Text = "雖然不知道你的來歷，想必卡斯托爾一路走來也少不了你的幫助，謝謝。"
  },
  AvgDialog_90538_Content_89 = {
    Text = "我的力量只夠將你送到這裡了，提燈教會或許還會一直追捕我，如果沒有其他需要我幫忙的事，我們就在這裡分開吧。"
  },
  AvgDialog_90538_Content_9 = {
    Text = "波呂克斯終於明白了這片羽毛真正的歸屬，他俯下身將它拾起，輕輕貼在了自己胸口。"
  },
  AvgDialog_90538_Content_90 = {
    Text = "過於乾脆的逐客令並沒有惹惱泰旖絲，她微笑著，緩緩踏著黃沙繞到了波呂克斯面前。"
  },
  AvgDialog_90538_Content_91 = {
    Text = "我要做的事已經做完了，的確沒有需要麻煩你的地方了，不過……"
  },
  AvgDialog_90538_Content_92 = {
    Text = "泰旖絲的手指輕柔地撥開封閉住波呂克斯的羽毛，在波呂克斯驚訝的眼神中點上了他的心臟。"
  },
  AvgDialog_90538_Content_93 = {
    Text = "我倒是還有一件能幫到你的事。"
  },
  AvgDialog_90538_Content_94 = {
    Text = "一點柔和的光輝從泰旖絲的指尖流轉到了那顆心臟之上。"
  },
  AvgDialog_90538_Content_95 = {
    Text = "彷彿另一個生命被由此喚醒，波呂克斯體內無數銀色的碎屑漸漸聚攏，凝成一顆六角的、銀白的晶石。"
  },
  AvgDialog_90538_Content_96 = {
    Text = "不要哭喪著臉呀，小鳥兒，我說過，你們的命運早就牢牢綁在一起了，在生命的綠洲裡，你們一定會再次重逢的。"
  },
  AvgDialog_90538_Content_97 = {
    Text = "隨著那抹銀光呼吸般閃爍，波呂克斯不可置信地將手撫上胸口，一道熟悉的聲音忽然從那顆黑色的心臟中響起。"
  },
  AvgDialog_90538_Content_99 = {
    Text = "刹那間，波呂克斯背後那雙翅膀簌簌抖動著，如新生的蝴蝶在破繭時震動的雙翼。"
  },
  AvgDialog_90539_Content_1 = {
    Text = "傾倒的天平"
  },
  AvgDialog_90539_Content_10 = {
    Text = "於麗埃特那一向對他充滿包容度的眼中充滿了陌生的寒意，波呂克斯知道，他沒有拒絕的餘地。"
  },
  AvgDialog_90539_Content_100 = {
    Text = "<Big:<Shake:願提燈長明！願提燈長明！>>"
  },
  AvgDialog_90539_Content_101 = {
    Text = "在震響的呐喊中，卡斯托爾昂起頭，直面著於麗埃特俯瞰般的目光，露出了一個從未屈服的笑容。"
  },
  AvgDialog_90539_Content_102 = {
    Text = "所有人的力量都已經連接在這裡了吧，是時候了……"
  },
  AvgDialog_90539_Content_103 = {
    Text = "下一刻，他將手撫上自己流淌著鮮血的腹部，用所有的力量催動了體內那截沉睡的、等待發芽的枝條。"
  },
  AvgDialog_90539_Content_104 = {
    Text = "我許諾過，我一定會讓你，走向那個自由的未來……"
  },
  AvgDialog_90539_Content_12 = {
    Text = "很好，那麼去吧，執行這場淨化，去審判他的罪惡，一切都是為了持燈者的降臨，願提燈長明。"
  },
  AvgDialog_90539_Content_13 = {
    Text = "<Shake:願提燈……長明。>"
  },
  AvgDialog_90539_Content_14 = {
    Text = "四周教徒靜默而沉重的目光都聚焦在波呂克斯身上，他勉強挺直脊背，緩慢到有些拖沓地走到卡斯托爾面前。"
  },
  AvgDialog_90539_Content_15 = {
    Text = "已被鎖鏈牽扯住四肢、固定在地上的卡斯托爾抬起頭，露出了並不意外的平靜神情。"
  },
  AvgDialog_90539_Content_16 = {
    Text = "一柄匕首……她要你執行對叛徒的刑罰，對麼？"
  },
  AvgDialog_90539_Content_17 = {
    Text = "虔誠、愧疚、還有一股沒來由的恐懼，互相矛盾的心情讓波呂克斯不知道該擺出怎樣的神情。"
  },
  AvgDialog_90539_Content_18 = {
    Text = "他深深呼吸了一口氣，在一旁侍從捧來的銀盆中將手洗淨，對卡斯托爾悄悄地低語。"
  },
  AvgDialog_90539_Content_19 = {
    Text = "這也是為了你好，如果能淨化你的靈魂，你就還是……"
  },
  AvgDialog_90539_Content_2 = {
    Text = "波呂克斯怔愣地盯著那柄通體亮銀的匕首。"
  },
  AvgDialog_90539_Content_20 = {
    Text = "呵……不用說了，動手吧，波呂克斯。"
  },
  AvgDialog_90539_Content_21 = {
    Text = "在你曾經歷那些痛苦時，我就一直愧疚於沒能代替你分擔，或許這就是命運讓我可以補償曾虧欠你的……"
  },
  AvgDialog_90539_Content_22 = {
    Text = "又來了，你又在胡言亂語什麼？！"
  },
  AvgDialog_90539_Content_23 = {
    Text = "真是……愚不可及。果然，教主大人說的沒錯，你是應該被好好淨化……"
  },
  AvgDialog_90539_Content_24 = {
    Text = "波呂克斯有些神經質地說服著自己，他將那柄閃耀著冰冷光芒的匕首高高舉起，朗聲念誦著祈禱之語。"
  },
  AvgDialog_90539_Content_25 = {
    Text = "我以聖子之名，祈求持燈者的憐憫、祈求您的注視、祈求您用神血洗滌此人的罪惡。"
  },
  AvgDialog_90539_Content_26 = {
    Text = "我將把您的聖行刻於罪人的四肢，以求您矯正他走上歧途的腳步。\n「祂持著不滅的燭火，行走於黑暗的大地……」"
  },
  AvgDialog_90539_Content_27 = {
    Text = "在無數教徒的複誦聲中，波呂克斯鄭重地站定在卡斯托爾面前，兩雙相似的眼瞳互相凝望，所有未竟之語都消弭於血光閃爍的那一刻。"
  },
  AvgDialog_90539_Content_29 = {
    Text = "刀尖切開皮膚，留下一道蜿蜒的血痕，從卡斯托爾的肩膀開始遊走、鐫刻，引起一陣陣疼痛的顫慄。"
  },
  AvgDialog_90539_Content_3 = {
    Text = "它細瘦而優雅，雕刻著繁複的經文，如一件聖潔的禮器，被輕飄飄地交到波呂克斯僵硬的雙手之中。"
  },
  AvgDialog_90539_Content_30 = {
    Text = "「祂注視著滿目的罪惡，流下悲傷的淚水，於是祂割開血肉，流出黑色的血液……」"
  },
  AvgDialog_90539_Content_31 = {
    Text = "「祂的鮮血帶走了罪惡，使世間眾人的罪得以從靈魂中解脫……」"
  },
  AvgDialog_90539_Content_32 = {
    Text = "繃直的鎖鏈嘩啦作響，波呂克斯握刀的手也微不可查地顫抖著。"
  },
  AvgDialog_90539_Content_33 = {
    Text = "借著動作的一瞬遮掩，他湊近卡斯托爾耳邊，怒其不爭地勸說著。"
  },
  AvgDialog_90539_Content_34 = {
    Text = "懺悔吧，只要你真心地懺悔，證明你的虔誠，教主大人會原諒你的！"
  },
  AvgDialog_90539_Content_35 = {
    Text = "不……你不懂那個女人，也不懂她想要什麼，她是不會停手的，繼續吧……"
  },
  AvgDialog_90539_Content_36 = {
    Text = "你！冥頑不靈的瘋子！這一切都是你自找的，既然如此，不要怪我……"
  },
  AvgDialog_90539_Content_37 = {
    Text = "仁慈的持燈者啊，我將把您的慈悲，刻於罪人的脊樑，以求您將他骨中的惡盡數洗淨。"
  },
  AvgDialog_90539_Content_38 = {
    Text = "波呂克斯的銘刻越來越快，他已來到卡斯托爾的背後，避開了那雙令他嫉妒過、安心過的翅膀，從脖頸自上而下刻下咒文。"
  },
  AvgDialog_90539_Content_39 = {
    Text = "「但世界仍籠罩於無盡的黑暗，於是祂用那燈火，點燃了自己的身軀……」"
  },
  AvgDialog_90539_Content_4 = {
    Text = "教主大人……這是？"
  },
  AvgDialog_90539_Content_40 = {
    Text = "「盛大的光明從祂的軀體中迸發，祂的肉與骨於火中凝成純銀的塑身，祂又將銀色的肉與骨取下，恩賜給那些世上的義人，以償還他們的罪孽。」"
  },
  AvgDialog_90539_Content_41 = {
    Text = "波呂克斯看著卡斯托爾微微彎起的背，聽見他越來越痛苦的喘息，從沒有像現在這樣痛恨他的頑固。"
  },
  AvgDialog_90539_Content_42 = {
    Text = "（明明這一切都是他自找的，但為何我還會如此混亂，如此糾結？）"
  },
  AvgDialog_90539_Content_43 = {
    Text = "波呂克斯甚至有些不敢走回卡斯托爾的面前，不敢去看他現在的表情。"
  },
  AvgDialog_90539_Content_44 = {
    Text = "……現在，滿身罪孽的人啊，我將為你祈求持燈者的憐憫，我將把祂的注視引導向你的心靈。"
  },
  AvgDialog_90539_Content_45 = {
    Text = "然而當他再次來到卡斯托爾面前時，他看到的只是一雙毫無怨恨的、哀傷的眼睛。"
  },
  AvgDialog_90539_Content_46 = {
    Text = "……別這樣看我。"
  },
  AvgDialog_90539_Content_47 = {
    Text = "一股莫名的怒火立刻吞噬了波呂克斯，所有感同身受一般的痛苦、惱恨、無力都讓他無法理解，無法回應。"
  },
  AvgDialog_90539_Content_48 = {
    Text = "然而在那哀傷的眼神下，卡斯托爾竟還努力露出了一個微笑。"
  },
  AvgDialog_90539_Content_49 = {
    Text = "別害怕，波呂克斯……"
  },
  AvgDialog_90539_Content_5 = {
    Text = "這是為了這場淨化儀式特別準備的器具。"
  },
  AvgDialog_90539_Content_50 = {
    Text = "閉嘴，閉嘴！我說過，我最討厭你這樣看著我！"
  },
  AvgDialog_90539_Content_51 = {
    Text = "波呂克斯泛白的指節緊緊握著匕首，那銀白的刀尖猛地狠狠切入肌理。"
  },
  AvgDialog_90539_Content_52 = {
    Text = "滾燙的血珠迸濺到波呂克斯憤怒的臉上，沾染在眼角，彷彿一枚豔紅的血淚。"
  },
  AvgDialog_90539_Content_54 = {
    Text = "為什麼你總是這樣？為什麼要做這些蠢事？現在你又為什麼……不恨我？"
  },
  AvgDialog_90539_Content_55 = {
    Text = "這就是我們的命運，波呂克斯，如果這些痛苦是你帶來的，也好……"
  },
  AvgDialog_90539_Content_56 = {
    Text = "夠了，你這個罪人，去向持燈者完全地懺悔吧！"
  },
  AvgDialog_90539_Content_57 = {
    Text = "「祂的靈魂從此回歸了無罪的淨土，但祂的目光仍慈愛地注視這個世間，將血、肉、骨贈予世人，以待接引那些無罪的靈魂來到淨土，與祂共用純潔的天國。」"
  },
  AvgDialog_90539_Content_58 = {
    Text = "你須直面你最深切的罪惡，明析你的痛苦與悔恨，我將代祂為你降下賜福……與審判。"
  },
  AvgDialog_90539_Content_59 = {
    Text = "在胸膛上最後的咒文落下時，一陣難以抵抗的眩暈感模糊了卡斯托爾因劇痛發黑的視線。"
  },
  AvgDialog_90539_Content_6 = {
    Text = "你要用它將聖行的咒文銘刻於卡斯托爾的血肉之上，祈求持燈者的注視與寬恕，讓他的罪惡從靈魂深處釋放。"
  },
  AvgDialog_90539_Content_60 = {
    Text = "（終於要結束了麼，這是……儀式帶來的幻境嗎？直面罪惡……我的罪惡嗎……）"
  },
  AvgDialog_90539_Content_61 = {
    Text = "改造儀式的效果很好，我們的方向沒有問題，從今天開始，給波呂克斯聖子每週都進行一次改造儀式，爭取早日完成「聖心」。"
  },
  AvgDialog_90539_Content_63 = {
    Text = "波呂克斯！你怎麼樣……我該怎麼辦，你流了好多血，好多，為什麼止不住……"
  },
  AvgDialog_90539_Content_64 = {
    Text = "好，很好，嚮往天空的飛鳥，多麼感人的故事，既然這對沒用的東西如此礙事，不如乾脆拔了吧。"
  },
  AvgDialog_90539_Content_65 = {
    Text = "什……等等！教主大人！請您再考慮一下！波呂克斯他只是想看看外面的世界，他只是太痛苦了……"
  },
  AvgDialog_90539_Content_66 = {
    Text = "是我，是我攻擊了燈衛，要懲罰的話就請懲罰我吧！不……不！"
  },
  AvgDialog_90539_Content_67 = {
    Text = "暗無天日的囚籠、散落的羽毛、無盡的血色，還有弟弟眼中濃郁不可消解的痛苦。"
  },
  AvgDialog_90539_Content_68 = {
    Text = "無數個日夜裡，那些無能為力的悔恨都像尖刀一樣刺痛著卡斯托爾的靈魂，那是他前行的力量，也是他懦弱的罪孽。"
  },
  AvgDialog_90539_Content_69 = {
    Text = "你已清楚地看到你心中的罪惡，向持燈者懺悔以求祂的寬恕吧。"
  },
  AvgDialog_90539_Content_7 = {
    Text = "銘刻？可這和賜福儀式的流程不一樣……"
  },
  AvgDialog_90539_Content_70 = {
    Text = "好疼，好疼啊，哥哥，為什麼不救我……"
  },
  AvgDialog_90539_Content_71 = {
    Text = "<Shake:不……不……波呂克斯……>"
  },
  AvgDialog_90539_Content_73 = {
    Text = "你為什麼什麼都沒做？為什麼不救我？！"
  },
  AvgDialog_90539_Content_74 = {
    Text = "<Shake:是哥哥太弱小，太沒用了……我……>"
  },
  AvgDialog_90539_Content_75 = {
    Text = "不，不要低頭，哥哥，堅持下去，為了自由。"
  },
  AvgDialog_90539_Content_76 = {
    Text = "好，我會的，我會的……"
  },
  AvgDialog_90539_Content_77 = {
    Text = "你的願望，我們的願望，我會……堅持到底的。"
  },
  AvgDialog_90539_Content_78 = {
    Text = "波呂克斯複雜地看著神情逐漸釋然而安寧的卡斯托爾，按壓下對剛剛那聲呼喚的好奇，轉身恭敬地向於麗埃特稟報。"
  },
  AvgDialog_90539_Content_79 = {
    Text = "教主大人，儀式已成，我先將卡斯托爾帶下去包紮……"
  },
  AvgDialog_90539_Content_8 = {
    Text = "這當然不是賜福儀式，難道你認為我們對不忠的叛徒需要那麼仁慈嗎？"
  },
  AvgDialog_90539_Content_80 = {
    Text = "不必了，接下來，才是儀式真正的開始，你就和卡斯托爾一起待在這裡，完成聖子最終的使命，為持燈者奉獻一切吧。"
  },
  AvgDialog_90539_Content_81 = {
    Text = "於麗埃特仍然保持著她永恆不變的微笑，彷彿丟下一片無關緊要的落葉一般，不再理會波呂克斯震驚的目光。"
  },
  AvgDialog_90539_Content_82 = {
    Text = "周圍的燈衛立刻上前，將一根根纖長的提燈插在兩個聖子的周圍，構成了一圈散發光輝的三角形牢籠。"
  },
  AvgDialog_90539_Content_83 = {
    Text = "……什麼？我？教主大人，我的靈魂絕對一片虔誠！不需要進行淨化儀式！"
  },
  AvgDialog_90539_Content_84 = {
    Text = "波呂克斯團團轉著，卻無法突破那法陣的邊界。"
  },
  AvgDialog_90539_Content_85 = {
    Text = "呵呵……這從來都不是什麼淨化儀式啊。"
  },
  AvgDialog_90539_Content_86 = {
    Text = "原本昏倒在血泊中的卡斯托爾不知什麼時候醒來，正掙扎著爬起，搖晃著挺直了脊樑。"
  },
  AvgDialog_90539_Content_87 = {
    Text = "波呂克斯，我親愛的弟弟，不要害怕……"
  },
  AvgDialog_90539_Content_88 = {
    Text = "你在說什麼，你已經徹底瘋了嗎？"
  },
  AvgDialog_90539_Content_89 = {
    Text = "波呂克斯倉皇地環顧，卻只看到四周那些狂熱而漠然的教眾，露出了一道道熟悉的冰冷的眼神。"
  },
  AvgDialog_90539_Content_9 = {
    Text = "還是說……你狠不下心，無法履行你聖子的職責？"
  },
  AvgDialog_90539_Content_90 = {
    Text = "在再次響起的念誦聲中，一道道刀刃劃破皮膚，無數教眾將鮮血滴入腳下。"
  },
  AvgDialog_90539_Content_91 = {
    Text = "一座早已埋藏於地下的法陣亮起微光，處於陣法中央的巨樹與怪物們一同被黑色的霧氣吞噬。"
  },
  AvgDialog_90539_Content_92 = {
    Text = "那些血肉與枝條都像蠟塊一樣融化、滴落，一點點聚集成一片融蝕的沼澤。"
  },
  AvgDialog_90539_Content_93 = {
    Text = "請收下這些供奉吧，偉大的持燈者，我們將淨化這些罪人，歸還您的神血，祈求您降臨於此處人間！"
  },
  AvgDialog_90539_Content_94 = {
    Text = "法陣如同一張呼吸的巨口，閃爍著越來越強的光芒。"
  },
  AvgDialog_90539_Content_95 = {
    Text = "呃……怎麼回事，胸口好燙……"
  },
  AvgDialog_90539_Content_96 = {
    Text = "唔……原來咒文是用在這裡……"
  },
  AvgDialog_90539_Content_97 = {
    Text = "卡斯托爾身上剛剛刻下的咒文、連同波呂克斯那顆經歷改造的聖心都呼應著地上的銘文一同亮起。"
  },
  AvgDialog_90539_Content_98 = {
    Text = "隨著無數獻祭不可挽回地消逝，某種宏偉而可怖的、令人靈魂顫抖的氣息漸漸濃郁。"
  },
  AvgDialog_90539_Content_99 = {
    Text = "日光、雲層、微風都凝固一般靜止——真正的降神儀式已經開始。龐大的儀式貪婪地攫取著兩個祭品的靈魂，要將他們的靈魂扭曲、融合。"
  },
  AvgDialog_90540_Content_1 = {Text = "雙生鳥"},
  AvgDialog_90540_Content_10 = {
    Text = "波呂克斯！"
  },
  AvgDialog_90540_Content_11 = {
    Text = "焦急的哥哥向前一步，努力伸著雙手試圖準確地接住他，然而少年低估了墜落的衝擊，也高估了自己的臂力。"
  },
  AvgDialog_90540_Content_12 = {
    Text = "砰的一聲，兩個少年以亂七八糟的姿勢一起砸倒在地，濺起倉庫中薄薄的灰塵。"
  },
  AvgDialog_90540_Content_13 = {
    Text = "哎喲，痛痛痛……那本書呢？有沒有摔壞？"
  },
  AvgDialog_90540_Content_14 = {
    Text = "波呂克斯捂著屁股，齜牙咧嘴地爬起來，立刻撲到了摔落一旁的書籍邊仔細查看——還好，這是一本包裝精美、質量過硬的好書。"
  },
  AvgDialog_90540_Content_15 = {
    Text = "你怎麼都不關心一下我有沒有被你砸壞。"
  },
  AvgDialog_90540_Content_16 = {
    Text = "眼神稚嫩的卡斯托爾扁著嘴，頗有些幽怨地湊了過來，兩個孩子的腦袋聚在一起，完全被這本大書那用金絲勾勒著華麗紋路的封皮所吸引。"
  },
  AvgDialog_90540_Content_17 = {
    Text = "我知道你肯定最厲害啦，我的哥哥怎麼會被這點小問題打倒呢……"
  },
  AvgDialog_90540_Content_18 = {
    Text = "波呂克斯嘿嘿一笑，由於眼睛仍在一轉不轉地盯著書皮，往日誠懇的安慰也顯得敷衍起來，但卡斯托爾此刻顯然也顧不上在意這些。"
  },
  AvgDialog_90540_Content_19 = {
    Text = "好美的花紋，這是用金子畫的嗎？這本書一定很珍貴吧。"
  },
  AvgDialog_90540_Content_20 = {
    Text = "那個信徒獻上供奉的時候說這個叫……手抄本？波呂克斯，你知道什麼是手抄本嗎？"
  },
  AvgDialog_90540_Content_21 = {
    Text = "我們兩個每天都在一起，我怎麼會知道你不知道的東西！不過，打開看看不就知道了。"
  },
  AvgDialog_90540_Content_22 = {
    Text = "也是，教會規定我們只能看持燈者書庫裡的書，翻來覆去就是那些東西，每一本的內容都差不多……"
  },
  AvgDialog_90540_Content_23 = {
    Text = "對於兩個從未走出過提燈教會的孩子來說，這本外來的藏書只是靜靜躺在這裡，就彷彿是孩童幻想中最神奇的魔法書一般，不斷吸引著他們的心。"
  },
  AvgDialog_90540_Content_26 = {
    Text = "星空、田野、大海、沙漠，雪原上也有盛開的花；國王、弄臣、騎士與公主，邪惡的怪物都會倒在正義之人的劍下……"
  },
  AvgDialog_90540_Content_27 = {
    Text = "這是一本包攬了中世紀種種記錄與故事的百科全書，無數貴重顏料繪製的圖畫萬花筒一般倒映在兩人眼中，介紹著他們從未得知的世界樣貌。"
  },
  AvgDialog_90540_Content_29 = {
    Text = "在驚訝的餘韻中，兩個少年久久沒有說話。"
  },
  AvgDialog_90540_Content_3 = {
    Text = "好累，身體好沉……這是……夢？"
  },
  AvgDialog_90540_Content_30 = {
    Text = "卡斯托爾張了張嘴，他有太多問題想要問，但又無從問起，他彷彿一下子變成了一個牙牙學語的嬰兒，充滿了對世界的無知與茫然。"
  },
  AvgDialog_90540_Content_31 = {
    Text = "走，我們回去，這本書一定要藏好，這樣厚的書，我們每天晚上看一些……用不了一個月就能看完了！"
  },
  AvgDialog_90540_Content_32 = {
    Text = "厚重的書在依依不舍的視線中被啪地合上，兄弟兩人對視一眼，都發覺了對方眼裡興奮的光芒。"
  },
  AvgDialog_90540_Content_33 = {
    Text = "下面，把經卷翻到第二十六頁，今天我將教二位聖子學習如何發現罪孽、審判罪孽。"
  },
  AvgDialog_90540_Content_34 = {
    Text = "安靜的教室中，阿爾比諾在黑板上書寫經文釋義的聲音沙沙迴響著。"
  },
  AvgDialog_90540_Content_35 = {
    Text = "表面乖順稱是的波呂克斯在阿爾比諾一轉過頭去時，就擠眉弄眼地側過頭，向卡斯托爾比劃著兩人秘密發明的暗語手勢。"
  },
  AvgDialog_90540_Content_36 = {
    Text = "（今天還看騎士和公主的那篇故事怎麼樣，這次我演騎士，你來演怪物。）"
  },
  AvgDialog_90540_Content_37 = {
    Text = "（啊，可是那篇故事都看過十二次了。）"
  },
  AvgDialog_90540_Content_38 = {
    Text = "（那你說看哪篇？哪一頁我們不是最少看了八九遍，那一篇已經是最好看的了！）"
  },
  AvgDialog_90540_Content_39 = {
    Text = "（你說的也是……但我不想演怪物。）"
  },
  AvgDialog_90540_Content_4 = {
    Text = "哥哥！卡斯托爾聖子閣下！又在發什麼呆呢？快幫我把梯子往左挪一挪！"
  },
  AvgDialog_90540_Content_40 = {
    Text = "（賴皮哥哥！算了，我也有點看膩了，不然……我們自己編一個故事怎麼樣？）"
  },
  AvgDialog_90540_Content_41 = {
    Text = "（怎麼編故事啊？我想不出來……）"
  },
  AvgDialog_90540_Content_42 = {
    Text = "（笨，看了那麼多騎士故事，我們模仿著寫一次新的騎士冒險不就好了！）"
  },
  AvgDialog_90540_Content_43 = {
    Text = "悄無聲息的溝通於兩人快速翻飛的手指間進行著，直到一片陰影忽然投到了沒能及時收回手的卡斯托爾面前。"
  },
  AvgDialog_90540_Content_44 = {
    Text = "在幹什麼呢？兩位聖子，好像沒有在認真聽講呀？真是讓這麼認真上課的我有些傷心呢。"
  },
  AvgDialog_90540_Content_45 = {
    Text = "阿爾比諾先生，我……"
  },
  AvgDialog_90540_Content_46 = {
    Text = "對不起先生，卡斯托爾的手好像扭到了，我正想幫他看看呢，我們錯了，我們會好好聽講的。"
  },
  AvgDialog_90540_Content_47 = {
    Text = "……原來是這樣啊，那確實情有可原呢。"
  },
  AvgDialog_90540_Content_48 = {
    Text = "那道飽含笑意的目光在兩人的面孔上輕飄飄掃過，便隨意地放下了此事，好像剛剛那雙蛇瞳中冰冷的影子都只是一瞬的玩笑。"
  },
  AvgDialog_90540_Content_49 = {
    Text = "對了，聖子們，有一件事教主大人要我轉告給你們，最近教會有了新的發現，需要你們在下課後去祭壇一趟。"
  },
  AvgDialog_90540_Content_5 = {
    Text = "哦，好，這邊嗎？"
  },
  AvgDialog_90540_Content_51 = {
    Text = "劇痛，無法想像的劇痛，連靈魂都要被撕裂的劇痛。"
  },
  AvgDialog_90540_Content_52 = {
    Text = "波呂克斯在被教主大人鄭重地選中，作為“聖心”的承載者時，還以為這是某種特殊的榮耀。"
  },
  AvgDialog_90540_Content_53 = {
    Text = "然而當他被固定在祭壇上，眼睜睜看著自己的胸膛被剖開的時候，一旁教主大人那無動於衷又頗為滿意的微笑，讓他立刻明白了——"
  },
  AvgDialog_90540_Content_54 = {
    Text = "所謂的聖子，也不過只是隨時可以用來祭祀給神的羔羊。"
  },
  AvgDialog_90540_Content_56 = {
    Text = "波呂克斯！你的胸口……怎麼會……"
  },
  AvgDialog_90540_Content_57 = {
    Text = "渾身在疼痛中顫抖的波呂克斯狠狠抓緊了卡斯托爾攙扶的胳膊，他抬起頭，露出了一個十足悲哀的慘笑。"
  },
  AvgDialog_90540_Content_58 = {
    Text = "<Shake:這就是教主大人說的改造儀式……這就是，我們的命運。>"
  },
  AvgDialog_90540_Content_6 = {
    Text = "多了多了！再往回一點，我已經看到那本書了！嘿——"
  },
  AvgDialog_90540_Content_60 = {
    Text = "就送到這吧，哥哥，以後的改造儀式，我自己來就可以了……你來等我，也只是站在這裡難過。"
  },
  AvgDialog_90540_Content_61 = {
    Text = "我……我去問過教主大人，她說我的體質不如你更有靈性，不能代替你進行改造。"
  },
  AvgDialog_90540_Content_62 = {
    Text = "我該怎麼辦呢，波呂克斯，我除了在這裡等著你，什麼都做不到了……"
  },
  AvgDialog_90540_Content_63 = {
    Text = "回應卡斯托爾幾乎要哭出來的目光的，只有長久的沉默。"
  },
  AvgDialog_90540_Content_64 = {
    Text = "這樣也好，哥哥，起碼我們不用承受兩份的痛苦。"
  },
  AvgDialog_90540_Content_65 = {
    Text = "別難過，小時候我偷吃東西，偷偷在書上畫畫的時候，一直都是哥哥替我的任性頂罪受罰，這一次，就換我代替哥哥吧。"
  },
  AvgDialog_90540_Content_67 = {
    Text = "卡斯托爾已經有些記不清在祭壇門口進行了多少次漫長的等待，每週的改造儀式讓那個總是想盡辦法給兩個人找樂子的弟弟也變得越來越沉默。"
  },
  AvgDialog_90540_Content_69 = {
    Text = "波呂克斯蹣跚的腳步聲剛剛出現的時候，卡斯托爾就立刻迎了過去。"
  },
  AvgDialog_90540_Content_7 = {
    Text = "年少的波呂克斯站在倉庫的木架之上，他踮著腳，尚且稚嫩的翅膀在背後不斷撲騰著，終於用力一跳，將一本厚厚的硬殼書從架子上拽了下來。"
  },
  AvgDialog_90540_Content_70 = {
    Text = "你怎麼樣？很疼吧？我扶你回去。——這些沒有意義的話最終被咽回了喉嚨，只有沉默而凝固的空氣包圍著兩人。"
  },
  AvgDialog_90540_Content_71 = {
    Text = "（我真是太沒用了……連話都不會說……）"
  },
  AvgDialog_90540_Content_72 = {
    Text = "卡斯托爾感到有某種異常沉重的東西將兩人壓得越來越死，讓他們已經喘不過氣來。"
  },
  AvgDialog_90540_Content_73 = {
    Text = "（不能再這樣了，再這樣下去……波呂克斯他一定會……）"
  },
  AvgDialog_90540_Content_74 = {
    Text = "波呂克斯靜靜坐在寢宮的床上，看著一旁欲言又止，彷彿比自己還要焦灼痛苦的哥哥。"
  },
  AvgDialog_90540_Content_75 = {
    Text = "坐一會吧，哥哥。"
  },
  AvgDialog_90540_Content_76 = {
    Text = "我明天再去求一求教主大人，讓我代替你進行改造吧。"
  },
  AvgDialog_90540_Content_77 = {
    Text = "那又有什麼區別？何況你已經求了她三次，上一次還被她狠狠罰過了，到現在你的後背還留著鞭刑的疤痕吧。"
  },
  AvgDialog_90540_Content_8 = {
    Text = "拿到了！我就說肯定在這裡……哎哎——"
  },
  AvgDialog_90540_Content_80 = {
    Text = "波呂克斯制止了卡斯托爾繼續說下去，他那空洞的目光悠悠地落在了床角中，落在了兩人珍藏的那本手抄本上。"
  },
  AvgDialog_90540_Content_81 = {
    Text = "你想要自由嗎？"
  },
  AvgDialog_90540_Content_82 = {
    Text = "什麼是……自由？"
  },
  AvgDialog_90540_Content_83 = {
    Text = "你想去……看看外面的世界嗎？就像手抄本上說的那樣。"
  },
  AvgDialog_90540_Content_84 = {
    Text = "波呂克斯拿起手抄本，輕輕摩挲著老舊的書脊，他的目光彷彿注視著卡斯托爾，又彷彿凝望著極為遙遠的地方。"
  },
  AvgDialog_90540_Content_85 = {
    Text = "卡斯托爾愣在原地，一瞬間明白了弟弟想說的全部。那是木訥、呆板、怯懦的自己永遠無法想像的、驚世駭俗的狂言。"
  },
  AvgDialog_90540_Content_86 = {
    Text = "他要背叛供養兩人的教會，從他們誕生、成長的這片罪惡的溫床中將血肉撕下，掙脫兩人從小習以為常的一切。"
  },
  AvgDialog_90540_Content_87 = {
    Text = "卡斯托爾吞咽了一下口水，堅定地握緊了拳頭。"
  },
  AvgDialog_90540_Content_88 = {
    Text = "如果那能讓你不再痛苦……我想。"
  },
  AvgDialog_90540_Content_9 = {
    Text = "波呂克斯臉上得意的笑容還沒有停留過兩秒，就因失去了平衡從梯子上向後翻倒下來。"
  },
  AvgDialog_90541_Content_10 = {
    Text = "還在那座沙漠的小城，教主大人說要在此舉行儀式，淨化你靈魂中的罪孽。"
  },
  AvgDialog_90541_Content_11 = {
    Text = "儀式？在這裡？為什麼？"
  },
  AvgDialog_90541_Content_12 = {
    Text = "我怎麼知道？這是教主大人的決定，這座城裡有那麼多噁心的怪物，到處都流淌著神血，是該替持燈者好好淨化一下這裡了。"
  },
  AvgDialog_90541_Content_13 = {
    Text = "<Small:不，不對，這一定不是什麼淨化儀式……>"
  },
  AvgDialog_90541_Content_14 = {
    Text = "你又在嘟囔什麼？不過教主大人他們好像還在城鎮裡抓到了那個女人，據說她昏倒在一棵怪樹下，幾乎和樹融為了一體，真是詭異。"
  },
  AvgDialog_90541_Content_15 = {
    Text = "泰旖絲？"
  },
  AvgDialog_90541_Content_16 = {
    Text = "卡斯托爾立刻意識到了事情的嚴重性，如果連泰旖絲的力量也被牽扯其中，這絕不是懲罰罪人這麼簡單的事。"
  },
  AvgDialog_90541_Content_17 = {
    Text = "你聽我說，波呂克斯，我知道你無法相信我說的一切，就當是我的恐懼，就當是我懇求你……"
  },
  AvgDialog_90541_Content_18 = {
    Text = "卡斯托爾踉蹌著伸出被縛的手，急切地抓住了波呂克斯的袖子。"
  },
  AvgDialog_90541_Content_19 = {
    Text = "離開這裡！哪怕只有你一個人也好！"
  },
  AvgDialog_90541_Content_2 = {
    Text = "當卡斯托爾重新睜開眼時，他以為自己會再次回到教會幽深的罪潭中，沒想到目光所及仍是一片沙漠居所的陳設。"
  },
  AvgDialog_90541_Content_20 = {
    Text = "這不是什麼聖子的榮耀！他們只會再一次傷害你，就像當初剖開你的胸口，拔掉你的翅膀一樣……"
  },
  AvgDialog_90541_Content_21 = {
    Text = "夠了！我真的不明白，你為什麼要一直詆譭教會，我的聖心與翅膀生來就是如此，哪裡有什麼人傷害過我？"
  },
  AvgDialog_90541_Content_22 = {
    Text = "至於你，你確實是怯懦，我能夠理解你因為聖子的生活過於枯燥而孤獨，不想承擔這份偉大的職責。"
  },
  AvgDialog_90541_Content_23 = {
    Text = "但你最不應該的就是動搖一個虔誠之人的信仰。"
  },
  AvgDialog_90541_Content_24 = {
    Text = "波呂克斯這一次沒有甩開卡斯托爾，他緊緊攥著卡斯托爾的衣領，那雙憤怒的眼睛裡竟流動著幾分如有實質的痛苦。"
  },
  AvgDialog_90541_Content_25 = {
    Text = "不要再冥頑不靈地對抗教主大人了，就讓我們回到從前那樣平靜的生活不好嗎？"
  },
  AvgDialog_90541_Content_26 = {
    Text = "<Small:從前的生活……>"
  },
  AvgDialog_90541_Content_27 = {
    Text = "卡斯托爾慘然而笑，他頹然垂首，終於意識到這種遺忘之刑的可怕，也終於意識到，自己和弟弟已經無法再擺脫這樣可悲的宿命了。"
  },
  AvgDialog_90541_Content_29 = {
    Text = "波呂克斯看著忽然沉默下來的卡斯托爾，還想再說些什麼，門口忽然傳來了燈衛們的腳步聲。"
  },
  AvgDialog_90541_Content_3 = {
    Text = "彷彿剛剛經歷的背叛都是一場幻夢一樣，他怔愣地想要起身，卻被身上鐵鍊傳來的嘩啦聲扯回現實，胸口的傷口也開始疼痛起來。"
  },
  AvgDialog_90541_Content_30 = {
    Text = "教主大人下令，儀式已準備完畢，將罪人帶到儀式現場。"
  },
  AvgDialog_90541_Content_31 = {
    Text = "隨著泰旖絲與那顆種子的沉睡，一夜之間柯雷尼之中所有虛假的偽裝都如幻影般消散了，廢墟之中只有寂靜。"
  },
  AvgDialog_90541_Content_32 = {
    Text = "巨大高聳的樹木張牙舞爪地立在城鎮中央，滿城只剩下枝條發狂損毀的痕跡。"
  },
  AvgDialog_90541_Content_33 = {
    Text = "一片不祥的黑雲籠罩了這裡，籠罩著這座城市已死去許久的屍體。"
  },
  AvgDialog_90541_Content_35 = {
    Text = "不知道經歷了怎樣的戰鬥與清剿，無數怪物化的居民擠擠挨挨地困在了巨大而詭異的陣法之中，待宰的牲畜一般伸展著佈滿融蝕的雙手。"
  },
  AvgDialog_90541_Content_36 = {
    Text = "在教眾包圍的中央，那棵枯萎的巨樹之中，正是被樹幹包裹的、沉睡的泰旖絲。"
  },
  AvgDialog_90541_Content_38 = {
    Text = "隨著於麗埃特的出現，一道道狂熱而安靜的視線立刻集中了過來。"
  },
  AvgDialog_90541_Content_39 = {
    Text = "終於，我們多年的努力馬上要迎來最終的時刻。"
  },
  AvgDialog_90541_Content_4 = {
    Text = "醒了？別亂動，祭司剛剛為你治療過傷口。"
  },
  AvgDialog_90541_Content_40 = {
    Text = "原本我們只是為了追捕罪人而來，但持燈者一直引導著祂的信徒，這座罪惡之城就是祂賜予我們的機會。"
  },
  AvgDialog_90541_Content_41 = {
    Text = "祂的鮮血在此處流淌，祂的目光也必將注視著此處，等待著我們將罪孽淨化，呼喚祂的降臨。"
  },
  AvgDialog_90541_Content_42 = {
    Text = "持燈者的僕從們、義人們，光明的追隨者們，準備好向偉大的持燈者獻上你的虔誠！迎接無罪的淨土！"
  },
  AvgDialog_90541_Content_43 = {
    Text = "現在，將我們的聖子請上來吧。"
  },
  AvgDialog_90541_Content_45 = {
    Text = "卡斯托爾被燈衛粗暴地拖拽著，波呂克斯微微皺起了眉，卻只得目不斜視地跟在一旁，尊敬地行禮。"
  },
  AvgDialog_90541_Content_47 = {
    Text = "做得很好，波呂克斯，你沒有愧對聖子的榮耀。接下來，是時候淨化這個對持燈者不敬的靈魂了。"
  },
  AvgDialog_90541_Content_48 = {
    Text = "……是，但卡斯托爾目前傷勢有些嚴重，恐怕無法執行儀式，是否讓我……"
  },
  AvgDialog_90541_Content_49 = {
    Text = "沒關係，沒關係，淨化罪惡不正是你最熟悉的使命嗎？來，拿上這個。"
  },
  AvgDialog_90541_Content_5 = {
    Text = "卡斯托爾看到了坐在不遠處的波呂克斯，偌大的屋子內只有他一個人守在這裡，波呂克斯欲言又止地投來一瞥，又很快收回了相交的目光。"
  },
  AvgDialog_90541_Content_50 = {
    Text = "於麗埃特仍然憐愛地微笑著，她轉過身，從一旁的侍從手中取來一柄光潔而鋒銳的匕首，遞到了波呂克斯面前。"
  },
  AvgDialog_90541_Content_6 = {
    Text = "我們這是在……哪裡？"
  },
  AvgDialog_90541_Content_7 = {
    Text = "除卻沙啞的嗓音，卡斯托爾驚訝地發現胸口的傷已完全不再流血，呈現出一種僵硬的閉合狀態。"
  },
  AvgDialog_90541_Content_8 = {
    Text = "他回憶起在罪潭中度過的暗無天日的“治療時間”，不禁苦笑。"
  },
  AvgDialog_90541_Content_9 = {
    Text = "（原來教會如此精通治癒的手段……）"
  },
  AvgDialog_91726_Content_1 = {
    Text = "奴隸與奴隸主"
  },
  AvgDialog_91726_Content_10 = {
    Text = "去死吧，去死吧，什麼作業，什麼大學都去死吧！"
  },
  AvgDialog_91726_Content_11 = {
    Text = "然而無能的啃咬並不能讓未完成的作業減少半分，甚至還讓被關在宿舍許久的她感到了一絲飢餓。"
  },
  AvgDialog_91726_Content_12 = {
    Text = "因為又一次將宿舍的生活用品都用壞了，阿格里帕於昨日對艾繼絲進行了入室搶劫，並與聞聲趕來的詹金大打出手。"
  },
  AvgDialog_91726_Content_13 = {
    Text = "最終榮獲了罰抄翻倍和禁足三天的懲罰。"
  },
  AvgDialog_91726_Content_14 = {
    Text = "烤肉、雞翅、薯條、羅宋湯，還有脆脆的黃油麵包……"
  },
  AvgDialog_91726_Content_15 = {
    Text = "阿格里帕回想起這所學校裡唯一令她喜愛的部分——那些餐廳裡任取任吃的美味菜餚，終於甩了甩頭，一拍桌子站了起來。"
  },
  AvgDialog_91726_Content_16 = {
    Text = "去他的禁閉，憑什麼關著我，老娘想去哪就去哪！"
  },
  AvgDialog_91726_Content_17 = {
    Text = "趁著夜深人靜，她鬼鬼祟祟地撬開了房門，發覺四下無人後，氣勢洶洶地向廚房潛行而去。"
  },
  AvgDialog_91726_Content_18 = {
    Text = "也不知道這個時候廚房還能剩下什麼東西……嗯？怎麼有人？小氣的彌薩格，連後廚也要安排守衛嗎？"
  },
  AvgDialog_91726_Content_19 = {
    Text = "嘟嘟囔囔靠近後廚大門的阿格里帕一瞬間縮回了拐角後，她探出半個腦袋，小心地望向黑暗裡門口的那個人影。"
  },
  AvgDialog_91726_Content_2 = {
    Text = "由於銀芯的物理特性，調查員在使用銀芯製品時應注意……以下幾個……"
  },
  AvgDialog_91726_Content_20 = {
    Text = "那是……好熟悉的背影，這個拖把一樣的頭髮……尤烏哈希？！"
  },
  AvgDialog_91726_Content_21 = {
    Text = "原本要被發現的緊張感一掃而空，阿格里帕叉著腰跳出拐角，先聲奪人地大聲指責起來。"
  },
  AvgDialog_91726_Content_22 = {
    Text = "哈，我當是誰，原來是我的奴隸！"
  },
  AvgDialog_91726_Content_23 = {
    Text = "怎麼，半夜在這裡鬼鬼祟祟的是想來偷吃嗎？果然是改不掉奴隸低賤的本性啊！"
  },
  AvgDialog_91726_Content_25 = {
    Text = "早就發現了她的尤烏哈希頭也不抬，繼續蹲在門口專心鼓搗著什麼。"
  },
  AvgDialog_91726_Content_26 = {
    Text = "難道你半夜來這裡，是被餐廳僱來上班的嗎？"
  },
  AvgDialog_91726_Content_27 = {
    Text = "你！誰允許你這樣和主人說話的！"
  },
  AvgDialog_91726_Content_28 = {
    Text = "不要以為你當初殺死了我，就能從此騎在我的頭上，那是出於我自己高貴的意志……"
  },
  AvgDialog_91726_Content_29 = {
    Text = "喂！看著我，你在幹什麼，為什麼不理……"
  },
  AvgDialog_91726_Content_3 = {
    Text = "及格……幾……"
  },
  AvgDialog_91726_Content_30 = {Text = "閉嘴！"},
  AvgDialog_91726_Content_31 = {
    Text = "尤烏哈希煩躁地大吼一聲，將湊近的阿格里帕嚇了一跳。"
  },
  AvgDialog_91726_Content_32 = {
    Text = "吼什麼？！你瘋了……嗯？門上怎麼掛了這麼多鎖頭？"
  },
  AvgDialog_91726_Content_33 = {
    Text = "那扇後廚不起眼的小門上，竟然層層疊疊掛著一大串的鎖頭，就像是廚房的主人惱羞成怒地在防範什麼慣犯一樣。"
  },
  AvgDialog_91726_Content_34 = {
    Text = "我說你怎麼一直蹲在門口，原來是進不去哈哈哈哈哈！！該不會是你天天來偷吃，被人家發現了吧！"
  },
  AvgDialog_91726_Content_35 = {
    Text = "沒有天天，一般也就兩天來一次。"
  },
  AvgDialog_91726_Content_36 = {
    Text = "這和天天有什麼區別！你的臉皮還真夠厚的，真應該讓朵爾也狠狠罰你的禁閉！"
  },
  AvgDialog_91726_Content_37 = {
    Text = "發覺又開始和鎖頭搏鬥的尤烏哈希已經完全無視了她，自討沒趣的阿格里帕跺了跺腳，想要轉身離開。"
  },
  AvgDialog_91726_Content_38 = {
    Text = "然而那腹中空虛的感受又一次湧了上來。"
  },
  AvgDialog_91726_Content_39 = {
    Text = "她想到要回去面對那些無盡的抄寫，還是決定繼續跟這個令她討厭的奴隸待在一起更好一些。"
  },
  AvgDialog_91726_Content_4 = {
    Text = "砰的一聲，阿格里帕一點一點的腦袋一下砸到了宿舍的書桌上，撞出了一塊清晰的紅印。"
  },
  AvgDialog_91726_Content_40 = {
    Text = "笨死了，讓開！不就是一些鎖頭，要從裡面打開，扯是扯不……"
  },
  AvgDialog_91726_Content_41 = {
    Text = "沒等阿格里帕用那些纖細的節肢捅開鎖頭，尤烏哈希忽然怒喝一聲，猛地將那一串門鎖、連同整個門把手都一把扯了下來。"
  },
  AvgDialog_91726_Content_42 = {
    Text = "……斷的。"
  },
  AvgDialog_91726_Content_43 = {
    Text = "尤烏哈希將手伸進了門上的大洞，從裡面輕鬆地打開了門鎖，一腳踹開門板，大步流星地走進了廚房。"
  },
  AvgDialog_91726_Content_44 = {
    Text = "粗魯的奴隸……喂，等等我！"
  },
  AvgDialog_91726_Content_45 = {
    Text = "哇，沒想到這裡存了這麼多吃的，怪不得你天天都要來偷吃。"
  },
  AvgDialog_91726_Content_46 = {
    Text = "兩輩子從未進過廚房的阿格里帕睜大著眼，在後廚一個個存儲食材、蔬果的大筐旁興奮地亂竄。"
  },
  AvgDialog_91726_Content_47 = {
    Text = "我認得，這個是聖女果，這個是胡蘿蔔，餐廳總是把它們混進肉菜的盤子裡，想不要都不行。"
  },
  AvgDialog_91726_Content_48 = {
    Text = "這個巨大的綠瓜是什麼？居然比我的腦袋還大，算了……一看就不好吃。"
  },
  AvgDialog_91726_Content_49 = {
    Text = "怎麼都是些沒意思的素菜，他們把那些烤肉藏到哪裡去了……尤烏哈希？你又在鼓搗什麼？"
  },
  AvgDialog_91726_Content_5 = {
    Text = "好痛！@2，我為什麼要在這裡抄這些愚蠢的爛書！"
  },
  AvgDialog_91726_Content_51 = {
    Text = "又一次突破後廚封鎖的尤烏哈希心情大好，他輕車熟路地打開了制冷箱上孱弱的小鎖頭，向阿格里帕招了招手。"
  },
  AvgDialog_91726_Content_52 = {
    Text = "當兩顆腦袋都湊在制冷箱前時，如同展示新世界的大門一般，尤烏哈希得意地將制冷箱門嘩地拉開。"
  },
  AvgDialog_91726_Content_53 = {
    Text = "這是……火山烤肉排！！"
  },
  AvgDialog_91726_Content_54 = {
    Text = "不見蹤影的肉類整齊地碼在制冷箱的角落，在冷藏區居然還有一整盤做好的肉排靜靜躺在中央，散發著誘人的香料氣息。"
  },
  AvgDialog_91726_Content_55 = {
    Text = "<Small:嗯？今天居然有這麼多剩菜，之前都只有生肉……>"
  },
  AvgDialog_91726_Content_56 = {
    Text = "看到滿滿一盤肉的尤烏哈希也愣了一下，還沒等他思考什麼，兩眼放光的阿格里帕就立刻端起了裝肉的餐盤。"
  },
  AvgDialog_91726_Content_57 = {
    Text = "還等什麼，奴隸，快生一堆火把它們熱一熱！"
  },
  AvgDialog_91726_Content_58 = {
    Text = "尤烏哈希剛想不屑地展示自己關於烤箱的知識，他的餘光就瞥見原本放置餐盤的地方有一枚突兀的按鈕緩緩亮起。"
  },
  AvgDialog_91726_Content_6 = {
    Text = "阿格里帕捂著額頭驚醒，齜牙咧嘴地瞪著本子上自己歪七扭八的錯字。"
  },
  AvgDialog_91726_Content_60 = {
    Text = "轉瞬之間，制冷箱前兩人站立的地板猛地向下分開，露出下方一個黑黝黝的大洞。"
  },
  AvgDialog_91726_Content_62 = {
    Text = "那盤美味的烤肉還沒來得及被拿穩，就從阿格里帕的手中滑落了。"
  },
  AvgDialog_91726_Content_63 = {
    Text = "兩人一屁股掉在坑底，只聽砰的一聲，頭頂的地板又飛快地合上了。\n只剩下兩雙瞪大的眼睛在黑暗中沉默地對視。"
  },
  AvgDialog_91726_Content_7 = {
    Text = "那寫錯的及格兩個字又讓她想起了朵爾輕蔑的眼神和這些可惡的罰抄作業——沒錯，她又一次在考試中取得了個位數的好成績。"
  },
  AvgDialog_91726_Content_8 = {
    Text = "及格，及格，又是及格，不及格能怎麼樣？老娘不伺候了！"
  },
  AvgDialog_91726_Content_9 = {
    Text = "阿格里帕惱怒地抓起本子想要撕掉，一想起朵爾那些折磨人的手段，最終又悻悻地停下了手，憤恨地將書角塞進了嘴裡狠狠咬著。"
  },
  AvgDialog_91727_Content_1 = {
    Text = "羅馬的力量"
  },
  AvgDialog_91727_Content_10 = {
    Text = "我的榮譽，我的尊嚴，一切都毀了！說不定我還要被罰更久的禁閉和更多的抄寫……"
  },
  AvgDialog_91727_Content_11 = {
    Text = "可我還什麼都沒有吃！連一片菜葉都沒有吃到！！"
  },
  AvgDialog_91727_Content_12 = {
    Text = "在阿格里帕喋喋不休的抱怨中，尤烏哈希嘗試了各種攻擊的手段。"
  },
  AvgDialog_91727_Content_13 = {
    Text = "然而剛剛合上的那兩塊地板就像是被重新澆築過，連一道縫隙都找不到了。"
  },
  AvgDialog_91727_Content_14 = {
    Text = "阿格里帕回想起自己來到彌薩格以來的種種生活，想起那些天書一樣的課本，寫滿了她不明白的知識。"
  },
  AvgDialog_91727_Content_15 = {
    Text = "還有那些完全變了樣的建築、習俗、發明用品，消失的奴隸制和被迫獨立的生活。"
  },
  AvgDialog_91727_Content_16 = {
    Text = "從前理所應當的生活變成了闖禍、被罰、再次闖禍的輪迴，期間充滿了其他人的嘆息、嫌棄，甚至敵意。"
  },
  AvgDialog_91727_Content_17 = {
    Text = "世界的法則一夕顛覆，她勉強維持著身為奴隸主的尊嚴，卻只感到一次又一次的不適應。"
  },
  AvgDialog_91727_Content_18 = {
    Text = "就像一條擱淺在過去的沙灘上，無法追趕上新的浪潮的魚。"
  },
  AvgDialog_91727_Content_19 = {
    Text = "此刻，許久未曾進食的、那種虛幻的飢餓感再次籠罩了她。"
  },
  AvgDialog_91727_Content_2 = {
    Text = "在尤烏哈希的全力一擊下，兩人頭頂的地板居然紋絲不動，甚至優雅地亮起了一片銀色的紋路。"
  },
  AvgDialog_91727_Content_20 = {
    Text = "那種空虛帶給她的並不是出於生存必需的痛苦，而是失去了一切的、莫大的委屈。"
  },
  AvgDialog_91727_Content_21 = {
    Text = "我只是想吃一塊肉……"
  },
  AvgDialog_91727_Content_22 = {
    Text = "放出去探索的子嗣也無功而返，阿格里帕崩潰地抱住膝蓋，絕望地蜷縮成了一團。"
  },
  AvgDialog_91727_Content_23 = {
    Text = "羅馬完蛋了，我的人生也完蛋了。我們的世界連一粒灰都沒有剩下，一切都被這個該死的新時代吞沒了。"
  },
  AvgDialog_91727_Content_24 = {
    Text = "我受夠了！我受夠了這樣的生活，受夠了這個鬼地方，這裡不屬於我，也不屬於你。"
  },
  AvgDialog_91727_Content_25 = {
    Text = "尤烏哈希！我們再也回不去羅馬了！那個金色的，充滿火焰、鮮花和歡呼的地方，再也回不去了！"
  },
  AvgDialog_91727_Content_26 = {
    Text = "尤烏哈希原本已經無所謂地坐在角落裡，準備就這樣等到天亮，卻被阿格里帕吵得耳朵生疼。"
  },
  AvgDialog_91727_Content_27 = {
    Text = "他用力地挖了挖耳朵，皺著眉打斷了阿格里帕。"
  },
  AvgDialog_91727_Content_28 = {
    Text = "吵死了，那又怎樣？"
  },
  AvgDialog_91727_Content_29 = {
    Text = "……什麼？"
  },
  AvgDialog_91727_Content_3 = {
    Text = "……嘖。"
  },
  AvgDialog_91727_Content_30 = {
    Text = "回不去那又怎樣？"
  },
  AvgDialog_91727_Content_31 = {
    Text = "阿格里帕不可置信地抬起頭，衝尤烏哈希破口大罵起來。"
  },
  AvgDialog_91727_Content_32 = {
    Text = "虧我還一直以為你是個戰士，尤烏哈希，你的血性呢？你那殺戮的誓言呢？"
  },
  AvgDialog_91727_Content_33 = {
    Text = "你竟然已經愛上這樣每天被人管教的生活，徹底變成一個懦夫了嗎！"
  },
  AvgDialog_91727_Content_35 = {
    Text = "你笑什麼？你承認了，說不出話了麼！"
  },
  AvgDialog_91727_Content_36 = {
    Text = "不，我依然喜歡殺戮，但我已經明白了這裡最大的好處，羅馬也不能帶給我的好處。"
  },
  AvgDialog_91727_Content_38 = {
    Text = "阿格里帕瞪著眼睛，用一種看叛徒的眼神怒視著他。"
  },
  AvgDialog_91727_Content_39 = {
    Text = "在羅馬，人們總是放縱自己，聽從慾望，無論是你、我、國王甚至奴隸。"
  },
  AvgDialog_91727_Content_4 = {
    Text = "什麼？發生什麼事了？這裡怎麼會有一個大坑？"
  },
  AvgDialog_91727_Content_40 = {
    Text = "我可以為貪婪的國王一夜殺光所有敵人，但那之後，我被關在了地下一千年。"
  },
  AvgDialog_91727_Content_41 = {
    Text = "整整一千年後，我又迎來了新的盛宴，而後我死去，同樣因為那放縱的飢渴。"
  },
  AvgDialog_91727_Content_42 = {
    Text = "這裡的人不一樣，他們崇拜那種叫理性的東西，他們糾結、克制、缺乏男子氣概。"
  },
  AvgDialog_91727_Content_43 = {
    Text = "我和你一樣討厭那些亂七八糟的規矩——我都不知道他們為什麼要自己給自己定下那麼多條條框框？"
  },
  AvgDialog_91727_Content_44 = {
    Text = "要知道他們根本控制不了我，只要我想，我隨時可以出去大鬧一場，殺個痛快。"
  },
  AvgDialog_91727_Content_45 = {
    Text = "彌薩格……這些傢伙給我的，是源源不斷的血、永遠不缺敵手的殺戮……"
  },
  AvgDialog_91727_Content_46 = {
    Text = "就算我們現在被關在這裡，等到明天清晨第一縷陽光照進那幫貪睡鬼的宿舍的時候，他們就會發現我不見了。"
  },
  AvgDialog_91727_Content_47 = {
    Text = "然後他們會大驚失色，像熱鍋上的螞蟻一樣團團轉圈，直到乖乖地把這破門打開。"
  },
  AvgDialog_91727_Content_48 = {
    Text = "這所謂的新時代奈何不了我們，不是嗎？"
  },
  AvgDialog_91727_Content_49 = {
    Text = "阿格里帕原本憤怒的表情漸漸愣住，她看著叉著腿放鬆地靠在角落的尤烏哈希，突然明白了這裡為她帶來的、那寶貴的「安心」。"
  },
  AvgDialog_91727_Content_5 = {
    Text = "我明白了……陷阱！是卑鄙的陷阱！是那盤肉！尤烏哈希！那肯定是用來針對你的！！"
  },
  AvgDialog_91727_Content_50 = {
    Text = "她想起每當夜晚到來時，她早就可以安心地閉上眼睛，不必再擔心任何背叛。"
  },
  AvgDialog_91727_Content_51 = {
    Text = "那曾在迷宮中將她牢牢困住的、噩夢般的過去，她已經很久很久沒有再想起了。"
  },
  AvgDialog_91727_Content_52 = {
    Text = "然而看著那個奴隸狂妄又自以為是的樣子，她還是感到一陣牙根癢癢。"
  },
  AvgDialog_91727_Content_53 = {
    Text = "什麼嘰哩呱啦的，不就是你背叛了羅馬，愛上了給新主子當奴隸的生活嗎？"
  },
  AvgDialog_91727_Content_54 = {
    Text = "奴隸，武器……誰在乎？他們給我血，給我取之不盡用之不竭的血！"
  },
  AvgDialog_91727_Content_55 = {
    Text = "至於你的規矩……早就已經和羅馬一樣，埋了很多年了。"
  },
  AvgDialog_91727_Content_56 = {
    Text = "哪怕現在回到羅馬，像你這樣的怪物也會立刻被征討，這樣一看，你還要感謝這個地方啊。"
  },
  AvgDialog_91727_Content_57 = {
    Text = "你！我聽明白了，你的的確確是變成了一個懦夫！"
  },
  AvgDialog_91727_Content_58 = {
    Text = "你就是害怕了被人隨用隨丟的生活，想要當一條被人呵護的寵物狗罷了！"
  },
  AvgDialog_91727_Content_59 = {
    Text = "害怕？我從來沒有害怕，更沒有後悔。"
  },
  AvgDialog_91727_Content_6 = {
    Text = "阿格里帕後知後覺地吵鬧起來，看到尤烏哈希的攻擊完全無效後，她更是大叫著怒罵起來。"
  },
  AvgDialog_91727_Content_60 = {
    Text = "我只是不像某個蠢貨，非要維護自己那可憐的破布一樣的尊嚴、拼命埋著頭抗拒新生活罷了。"
  },
  AvgDialog_91727_Content_61 = {
    Text = "你說誰是蠢貨？！"
  },
  AvgDialog_91727_Content_62 = {
    Text = "阿格里帕氣到髮絲炸起，一團又一團蒼白的肉卵鑽出身體，那些節肢瘋狂地跺著地面，最終忍無可忍地向尤烏哈希撲去。"
  },
  AvgDialog_91727_Content_63 = {
    Text = "下賤的奴隸，你要為你的無禮付出代價！"
  },
  AvgDialog_91727_Content_64 = {
    Text = "怎麼，你想再一次被我吸乾鮮血嗎？"
  },
  AvgDialog_91727_Content_65 = {
    Text = "尤烏哈希！！！"
  },
  AvgDialog_91727_Content_66 = {
    Text = "狹小的空間裡，毒汁與血刺飛舞，節肢與雙手碰撞，兩個人毫無形象地扭打成一團，誰也不願意服輸。"
  },
  AvgDialog_91727_Content_67 = {
    Text = "就在他們大動干戈的時候，不知道是哪道攻擊起了作用，頭頂那扇亮著微弱銀光的門板忽然閃爍了一下。"
  },
  AvgDialog_91727_Content_68 = {
    Text = "等等……剛剛這個門板是不是閃了一下？"
  },
  AvgDialog_91727_Content_69 = {
    Text = "阿格里帕忽然停了手抬頭看去，來不及剎住的尤烏哈希一頭撞了出去，咚地撞上了仍然巋然不動的門板。"
  },
  AvgDialog_91727_Content_7 = {
    Text = "臭奴隸！沒用的東西！都怪你！現在好了，連我都要被你連累一起倒霉！"
  },
  AvgDialog_91727_Content_71 = {
    Text = "阿格里帕推開礙事的尤烏哈希，扒在門板上仔細研究著，忽然從那流淌著銀光的紋路中看到了某些熟悉的東西。"
  },
  AvgDialog_91727_Content_72 = {
    Text = "這些紋路……好像是我剛剛抄過的銀芯驅動機關迴路？"
  },
  AvgDialog_91727_Content_73 = {
    Text = "什麼雞什麼鹿？"
  },
  AvgDialog_91727_Content_74 = {
    Text = "剛剛罰抄的內容一下子湧入腦袋，在更差的差生面前，阿格里帕那貧瘠的知識終於有了炫耀的機會。"
  },
  AvgDialog_91727_Content_75 = {
    Text = "說了你也聽不懂，總之這種機關以銀芯為核心，因為銀芯的……什麼什麼特性，它的核心通常都離機關的位置不遠。"
  },
  AvgDialog_91727_Content_76 = {
    Text = "而且這些核心構造十分精密，剛剛一定是恰巧打中了核心所在的位置，這破門才會有反應。"
  },
  AvgDialog_91727_Content_77 = {
    Text = "只要我們針對核心的位置造成足夠的震盪，就能夠破壞掉門上的機關！"
  },
  AvgDialog_91727_Content_78 = {
    Text = "聽不懂，總之就是要狠狠打那個什麼東西吧，它在哪？"
  },
  AvgDialog_91727_Content_79 = {
    Text = "我看看……按照這個機關的功能，這裡迴路的走向應該是這邊……不對不對，這邊？"
  },
  AvgDialog_91727_Content_8 = {
    Text = "明天一早就會有人打開這個該死的陷阱，說：「瞧瞧我們抓住了什麼，兩個蠢蛋！就是你們一直在偷吃後廚的東西。」"
  },
  AvgDialog_91727_Content_80 = {
    Text = "呃……應該藏在這面牆的這裡？"
  },
  AvgDialog_91727_Content_81 = {
    Text = "算了，這些考試我從來就沒有及格過，這次一定又錯了。"
  },
  AvgDialog_91727_Content_82 = {
    Text = "阿格里帕頹然地垂下腦袋，讓她意外的是，眼前的奴隸竟然沒有趁機嘲笑她，只是認真地點了點頭。"
  },
  AvgDialog_91727_Content_83 = {
    Text = "看來你也在這裡改變了很多啊。"
  },
  AvgDialog_91727_Content_84 = {
    Text = "尤烏哈希回過頭，像是面對最強大的對手一般凝視著牆上那個虛幻的點。"
  },
  AvgDialog_91727_Content_85 = {
    Text = "如同昔日戰場上的殺神歸來，一根又一根鮮血凝聚的長矛拱衛在他的身旁，在黑暗中散發著猩紅的光。"
  },
  AvgDialog_91727_Content_86 = {
    Text = "那就讓這間廚房的人看一看，羅馬最強大的戰士的力量吧！"
  },
  AvgDialog_91727_Content_87 = {
    Text = "伴隨著張狂的笑聲，灌注了戰士全力的一擊精準轟上了那一點，在一聲微弱的咔噠聲中，頭頂那扇堅不可摧的門板終於黯淡了下來。"
  },
  AvgDialog_91727_Content_88 = {
    Text = "淡淡的銀光閃爍消失，阿格里帕驚訝地抬起頭，開懷地笑了起來。"
  },
  AvgDialog_91727_Content_89 = {
    Text = "成功了！什麼銀芯科技，區區廚房，還不是被老娘征服了！"
  },
  AvgDialog_91727_Content_9 = {
    Text = "然後我們的名字就會被掛在公告板上，被整個彌薩格嘲笑，笑話我們是兩隻愚蠢的老鼠。"
  },
  AvgDialog_91727_Content_90 = {
    Text = "她與尤烏哈希對視一眼，不約而同地哼了一聲，一起轟然捶飛了失效的門板。"
  },
  AvgDialog_91727_Content_91 = {
    Text = "不知感恩的奴隸，這裡的食物應該由我先享用！"
  },
  AvgDialog_91727_Content_92 = {
    Text = "沒有我你打得開那個門嗎？當然是誰先搶到算誰的。"
  },
  AvgDialog_91727_Content_93 = {
    Text = "在爭搶和撕打中，憋悶已久的兩人風捲殘雲地清空了廚房的肉食，而後大搖大擺地揚長而去。"
  },
  AvgDialog_91727_Content_94 = {
    Text = "他們的名字最終還是沒有出現在校園的通告板上，屬於羅馬的榮耀在這個夜晚得以保全。"
  },
  AvgDialog_91727_Content_95 = {
    Text = "可喜可賀，此地又一次被羅馬的力量成功征服。"
  },
  AvgDialog_91727_Content_96 = {
    Text = "只有廚師長在第二天信心滿滿地走進後廚後，發出了一聲響徹校園的怒吼。"
  },
  AvgDialog_94610_Content_1 = {
    Text = "退下吧，凱刻斯。"
  },
  AvgDialog_94610_Content_2 = {
    Text = "異鄉人，拿出你的真本事。讓我看看，你到底還藏著些什麼秘密！"
  },
  AvgDialog_94611_Content_1 = {
    Text = "守密人閣下，我只是想與你共舞一曲而已，為何如此過激呢？"
  },
  AvgDialog_94611_Content_2 = {
    Text = "我不知道你了解些什麼，也不想知道……"
  },
  AvgDialog_94611_Content_3 = {
    Text = "就算死在這裡……威廉學長的仇，我也一定會報！"
  },
  AvgDialog_94641_Content_1 = {
    Text = "經計算，當前手牌未處於最優區間。建議指令：釋放<Yellow:「湮滅」>協議，獲取靈感。"
  },
  AvgDialog_94642_Content_1 = {
    Text = "唔唔，還有<Yellow:怒濤姿態>，可以讓觸腕打人變得超級疼，並且所有主動攻擊都會再給觸腕附加一次額外傷害噢。快使用怒濤姿態，把壞蛋都趕跑！"
  },
  AvgDialog_94643_Content_1 = {
    Text = "點擊我們上方的界域標識，就可以切換觸腕的<Yellow:姿態>。這個敵人好兇，切換到擅長防守的<Yellow:靜海姿態>，保護好大家！"
  },
  AvgDialog_94644_Content_1 = {
    Text = "看到那個圓圓的標識了嗎？這是<Yellow:猩紅熔爐>，只要輕輕點一下它，積攢的能量就會全部轉化成生命值哦。"
  },
  AvgDialog_94644_Content_2 = {
    Text = "現在……請用這份小小的助力，去抵擋那些可怕的攻擊吧。"
  },
  AvgDialog_94645_Content_1 = {
    Text = "<Yellow:觸腕>就和奧瑞塔的夥伴一樣，會不斷增多哦。在不切換姿態的情況下，回合結束時會自動生成1條新的觸腕，很厲害吧~"
  },
  AvgDialog_94646_Content_1 = {
    Text = "啟動條件確認完畢！即刻進入<Yellow:超維回合>，<Yellow:超維空間>內的卡牌將被重新取回。據演算，此為發動連續攻勢的最佳節點。"
  },
  AvgDialog_94653_Content_1 = {
    Text = "深夜，一陣狂亂焦急的敲門聲忽然把你驚醒。"
  },
  AvgDialog_94653_Content_10 = {
    Text = "你連忙伸手去扶，但滑膩的汗濕讓那隻滾燙的胳膊從你的手中滑落了，波呂克斯踉蹌著跌倒在地，無力地伏在床沿。"
  },
  AvgDialog_94653_Content_11 = {
    Text = "真是失禮，讓您看到了這樣難看的樣子……"
  },
  AvgDialog_94653_Content_12 = {
    Text = "你的臉色……<Small:好紅，不會錯了，這一定是……>"
  },
  AvgDialog_94653_Content_13 = {
    Text = "恩人，我弟弟到底怎麼了？從今晚開始，他的胸口好像越來越燙了。"
  },
  AvgDialog_94653_Content_14 = {
    Text = "波呂克斯也從地上抬起眼，於痛苦之中等待著自己的審判。"
  },
  AvgDialog_94653_Content_15 = {
    Text = "兩雙信賴的眼睛把你盯住，讓你一時間不知道如何措辭解釋。"
  },
  AvgDialog_94653_Content_16 = {
    Text = "他，嗯……可以說是生病了，可能由於聖心的特殊體質，病得比較嚴重。"
  },
  AvgDialog_94653_Content_17 = {
    Text = "是不是我犯下的罪孽已迎來了懲罰？我的靈魂已經無可救藥……"
  },
  AvgDialog_94653_Content_18 = {
    Text = "波呂克斯自嘲地笑了一聲，他的胸膛起伏，汗水將他的髮絲黏在皮膚上，難耐的發熱似乎讓他陷入了脆弱與悲觀之中。"
  },
  AvgDialog_94653_Content_19 = {
    Text = "不不不，這個其實是……呃，總之不是你的問題，是外力的影響，只要過一陣就會好了！真的！"
  },
  AvgDialog_94653_Content_2 = {
    Text = "你想起了一些不太美好的回憶，沒有立刻開門，而是小心地靠近門板。"
  },
  AvgDialog_94653_Content_20 = {
    Text = "你信誓旦旦地保證，俯下身想要把波呂克斯從地上攙起。"
  },
  AvgDialog_94653_Content_21 = {
    Text = "如此仁慈的寬慰，您的靈魂還是那樣耀眼，甚至有一絲……香甜？讓人想要……"
  },
  AvgDialog_94653_Content_22 = {
    Text = "肢體接觸間，波呂克斯湊近的鼻息撲灑在你的皮膚，他張著嘴，彷彿想要舔舐你滾動的喉頭。"
  },
  AvgDialog_94653_Content_23 = {
    Text = "不，我怎麼會有這樣不敬的想法……只是在您身邊，我的痛苦好像也減輕了些許……"
  },
  AvgDialog_94653_Content_24 = {
    Text = "波呂克斯一瞬間克制地錯開了臉，他蹙著眉喃喃著，似乎意識到了什麼。"
  },
  AvgDialog_94653_Content_25 = {
    Text = "恩人，真的沒有辦法能治好他嗎？"
  },
  AvgDialog_94653_Content_26 = {
    Text = "我……算了，可以是可以，不過這期間房間不能有人，卡斯托爾你今晚就去我的房間休息吧。"
  },
  AvgDialog_94653_Content_27 = {
    Text = "我明白了，那就拜託恩人了。"
  },
  AvgDialog_94653_Content_28 = {
    Text = "在波呂克斯輕輕的點頭中，卡斯托爾終於擔憂地關上了房門。"
  },
  AvgDialog_94653_Content_29 = {
    Text = "讓卡斯托爾離開，是有什麼殘酷的治療方法嗎，請您放心地動手吧，我可以忍耐任何疼痛。"
  },
  AvgDialog_94653_Content_3 = {Text = "誰？"},
  AvgDialog_94653_Content_30 = {
    Text = "不，我又不是于麗埃特，你不必再經受痛苦了，這只是會……有些羞恥。"
  },
  AvgDialog_94653_Content_31 = {
    Text = "那麼，我該怎麼做？"
  },
  AvgDialog_94653_Content_32 = {
    Text = "在你的回答中，波呂克斯已經找到了自己想要的答案，他明白了自己心中的慾望已被你知曉、應允。"
  },
  AvgDialog_94653_Content_33 = {
    Text = "他將你的手執起，貼在了自己的臉頰，在你的默許中，又慢慢地湊近，將滾燙的額頭貼上你的額頭。"
  },
  AvgDialog_94653_Content_34 = {
    Text = "那雙失神的眼凝望著你，如虔誠的信徒望向他的主。"
  },
  AvgDialog_94653_Content_35 = {
    Text = "請指引我吧，我的明燈……"
  },
  AvgDialog_94653_Content_5 = {
    Text = "波呂克斯？他怎麼了？"
  },
  AvgDialog_94653_Content_6 = {
    Text = "你快速跟隨卡斯托爾來到了房間，那兩張床鋪的其中一張上蜷縮著一個呻吟的人影，床單與被子都在漫長的折磨中被揉滿了凌亂的褶皺。"
  },
  AvgDialog_94653_Content_7 = {
    Text = "聽到你們開門的響聲，波呂克斯從昏沉中驚醒，從床上艱難地掙扎站起。"
  },
  AvgDialog_94653_Content_8 = {
    Text = "哈……是您來了……"
  },
  AvgDialog_94653_Content_9 = {
    Text = "如此簡單的動作也令波呂克斯吃力地喘著氣，他的身形搖晃著將要栽倒。"
  },
  AvgDialog_95381_Content_1 = {
    Text = "夜幕已深，你躺在床上，看著時鐘滴答滴答地走過，無所事事地發著呆。"
  },
  AvgDialog_95381_Content_11 = {
    Text = "來了來了……凱，凱蒂古拉？！"
  },
  AvgDialog_95381_Content_12 = {
    Text = "出現在你面前的是滿身酒氣的凱蒂古拉，她一把推開你半掩的房門，隨後反手擰上了鎖。"
  },
  AvgDialog_95381_Content_13 = {
    Text = "凱，凱蒂古拉？你還好嗎？"
  },
  AvgDialog_95381_Content_14 = {
    Text = "凱蒂古拉的狀況似乎有些不對，她全身散發著某種被稱為生物最原始衝動的慾望。"
  },
  AvgDialog_95381_Content_15 = {
    Text = "彷彿被強大的獸類牢牢盯住，你心中產生了強烈的危機感，警告你趕快離開這裡。"
  },
  AvgDialog_95381_Content_16 = {
    Text = "我嗎？我當然很好，沒有任何問題。"
  },
  AvgDialog_95381_Content_17 = {
    Text = "凱蒂古拉一邊鬆了鬆腦後的髮繩，一邊邁開長靴緩緩向你靠近。你只得不斷後退，嘗試保持一個安全距離。"
  },
  AvgDialog_95381_Content_18 = {
    Text = "呃，我去給你拿些醒酒藥？"
  },
  AvgDialog_95381_Content_19 = {
    Text = "你本想藉此理由從這裡脫身，卻不料凱蒂古拉迅速將你的右手抓在手裡，猖獗、蠻橫且無禮。"
  },
  AvgDialog_95381_Content_2 = {
    Text = "若是平日，這個時間你早已脫下佈滿風塵的衣物，把疲憊的身體送入夢鄉。"
  },
  AvgDialog_95381_Content_20 = {
    Text = "不用，小傢伙，有些事情啊，太清醒了反而無聊，不是嗎？"
  },
  AvgDialog_95381_Content_21 = {
    Text = "不得已，你只得繼續向後退去，但留給你的空間似乎不多了。"
  },
  AvgDialog_95381_Content_22 = {
    Text = "知道嗎，小傢伙，我一直有個遺憾，就是上次沒喝到你的酒。"
  },
  AvgDialog_95381_Content_23 = {
    Text = "但是這次嘛……就不會了。"
  },
  AvgDialog_95381_Content_24 = {
    Text = "誒？你怎麼記得那時……"
  },
  AvgDialog_95381_Content_25 = {
    Text = "記憶雖然模糊，但它依舊存在。"
  },
  AvgDialog_95381_Content_26 = {
    Text = "別忘了我可是永不遺忘的凱蒂古拉，嗯，至少在需要時是永不遺忘的。"
  },
  AvgDialog_95381_Content_27 = {
    Text = "凱蒂古拉將你逼至床邊，隨手脫下外衣，順勢俯身撐在你身上，垂下的髮絲搖晃著劃過你的皮膚。"
  },
  AvgDialog_95381_Content_28 = {
    Text = "你睜著眼睛，不知所措地躺在床上，任由她那摻雜著甜美酒香的鼻息拂過臉頰。"
  },
  AvgDialog_95381_Content_29 = {
    Text = "凱蒂古拉的目光中透著戲謔，面龐與你離得越來越近。"
  },
  AvgDialog_95381_Content_3 = {
    Text = "但託慶典的福，繁忙和勞累並沒有在這一天打擾你。"
  },
  AvgDialog_95381_Content_30 = {
    Text = "她的鼻尖觸碰著你的鼻尖輕輕嗅聞，彷彿在品味你呼吸中香醇的餘韻。"
  },
  AvgDialog_95381_Content_31 = {
    Text = "那雙溫熱的嘴唇湊到你嘴唇之上，懸停在毫釐之間，發出一聲輕輕的笑。於是她在這微小的縫隙中摩擦著你的雙唇開口。"
  },
  AvgDialog_95381_Content_32 = {
    Text = "這次就讓我，品嚐一下獨屬於你的味道吧……"
  },
  AvgDialog_95381_Content_33 = {
    Text = "可愛的小傢伙。"
  },
  AvgDialog_95381_Content_4 = {
    Text = "因此你仍有精力拿起放在床頭許久未碰的小說，「調研」一下當下的文學風潮。"
  },
  AvgDialog_95381_Content_6 = {
    Text = "突然，一陣急促的敲門聲打斷了你的閱讀計劃。"
  },
  AvgDialog_95381_Content_7 = {
    Text = "來了！稍等！"
  },
  AvgDialog_95381_Content_8 = {
    Text = "你放下書籤都還未取出的《火槍與蜜酒》，離開了舒適溫暖的床鋪，向門口走去。"
  },
  AvgDialog_95381_Content_9 = {
    Text = "（這麼晚了，會是誰呢？）"
  },
  AvgDialog_95473_Content_1 = {
    Text = "幕後禍首"
  },
  AvgDialog_95473_Content_10 = {
    Text = "砍起來比之前那些玩意過癮多了。"
  },
  AvgDialog_95473_Content_11 = {
    Text = "減少二分之一了，下個地方……就選這裡吧。"
  },
  AvgDialog_95473_Content_12 = {
    Text = "……第8次誘導，敵人減少至1/14"
  },
  AvgDialog_95473_Content_13 = {
    Text = "……第13次誘導，敵人減少至1/25"
  },
  AvgDialog_95473_Content_14 = {
    Text = "……第27次誘導，敵人減少至1/138"
  },
  AvgDialog_95473_Content_15 = {
    Text = "最後的了嗎。"
  },
  AvgDialog_95473_Content_16 = {
    Text = "凱蒂古拉停下腳步，清點起剩下的敵人。"
  },
  AvgDialog_95473_Content_17 = {
    Text = "一，二，三……還剩五隻。"
  },
  AvgDialog_95473_Content_18 = {
    Text = "來吧，傑拉德，逃了這麼久……"
  },
  AvgDialog_95473_Content_19 = {
    Text = "也該發洩一下了！！"
  },
  AvgDialog_95473_Content_20 = {
    Text = "<Shake:<Big:去死吧！骯髒的怪物！>>"
  },
  AvgDialog_95473_Content_24 = {
    Text = "鏘——鏘——"
  },
  AvgDialog_95473_Content_28 = {Text = "撲通。"},
  AvgDialog_95473_Content_29 = {
    Text = "叫得真難聽，傑拉德，你那邊呢？"
  },
  AvgDialog_95473_Content_30 = {
    Text = "呼……呼……解決了。"
  },
  AvgDialog_95473_Content_31 = {
    Text = "很好，接下來跟他們會合前，我們先去一個地方。"
  },
  AvgDialog_95473_Content_32 = {Text = "哪裡？"},
  AvgDialog_95473_Content_33 = {
    Text = "那個神殿，儀式的中心，如果我沒猜錯的話。"
  },
  AvgDialog_95473_Content_34 = {
    Text = "有人在等我們。"
  },
  AvgDialog_95473_Content_35 = {
    Text = "神殿內部，血液和屍體已經消失不見，彷彿什麼都從未發生過。"
  },
  AvgDialog_95473_Content_36 = {
    Text = "哎呀，居然回來了，就這樣乖乖地離開不好麼？"
  },
  AvgDialog_95473_Content_37 = {
    Text = "那樣我就可以讓你們在即將看見光明的時候……"
  },
  AvgDialog_95473_Content_38 = {
    Text = "體驗那墜入煉獄的絕景了。"
  },
  AvgDialog_95473_Content_4 = {
    Text = "不錯，甩掉一些，跟計劃一樣。"
  },
  AvgDialog_95473_Content_40 = {
    Text = "一個再熟悉不過的人影出現在面前，標誌性的禮服，虛假的笑容以及手中盛開的紅色薔薇。"
  },
  AvgDialog_95473_Content_41 = {
    Text = "（為什麼會在這裡……見到他……）"
  },
  AvgDialog_95473_Content_42 = {
    Text = "多日不見，請允許我向凱蒂古拉女士做個正式的自我介紹。"
  },
  AvgDialog_95473_Content_45 = {
    Text = "不知道這個結局，有沒有讓凱蒂古拉女士滿意呢？"
  },
  AvgDialog_95473_Content_46 = {
    Text = "我來評價麼？"
  },
  AvgDialog_95473_Content_47 = {
    Text = "凱蒂古拉笑了，輕蔑中夾雜著三分不屑。"
  },
  AvgDialog_95473_Content_48 = {
    Text = "這個故事太老套了，既不精彩，也不有趣。"
  },
  AvgDialog_95473_Content_49 = {
    Text = "就像跟不上時代的迂腐老頭，只會不斷模仿自己曾經的作品，然後沾沾自喜，大肆鼓吹這早就被用爛的玩意。"
  },
  AvgDialog_95473_Content_5 = {
    Text = "來啊，怪物們，你們的對手在這裡！"
  },
  AvgDialog_95473_Content_50 = {
    Text = "其實啊，他早就失去了靈感和創意，只能如同喪家之犬般，沉浸在自己的幻想裡了。"
  },
  AvgDialog_95473_Content_51 = {
    Text = "有趣，我還是第一次被人說成喪家之犬。"
  },
  AvgDialog_95473_Content_52 = {
    Text = "N倒也不惱怒，反倒向凱蒂古拉請教起來。"
  },
  AvgDialog_95473_Content_53 = {
    Text = "來說說，這場戲哪裡露出了破綻？"
  },
  AvgDialog_95473_Content_54 = {
    Text = "凱蒂古拉轉著手中的槍，目光在四周逡巡一圈，最終落在N的身上。"
  },
  AvgDialog_95473_Content_55 = {
    Text = "太過精準了，明白麼。"
  },
  AvgDialog_95473_Content_56 = {
    Text = "暗道、門戶……就連走廊的深度也分毫不差。我進入大廳掃視的第一個瞬間，就明白了這一事實。"
  },
  AvgDialog_95473_Content_57 = {
    Text = "這是一場自導自演的鬧劇，僅此而已。"
  },
  AvgDialog_95473_Content_58 = {
    Text = "原來如此！我明白了！放心，下次我會用更真實的劇本招待您。"
  },
  AvgDialog_95473_Content_59 = {
    Text = "啊！差點忘了！"
  },
  AvgDialog_95473_Content_60 = {
    Text = "N誇張地拍了下腦袋，表演著自己突然想起了什麼。"
  },
  AvgDialog_95473_Content_61 = {
    Text = "您已經——沒有下次了。"
  },
  AvgDialog_95473_Content_62 = {
    Text = "凱蒂古拉冷笑著，無視了對方那充滿惡意的話語，抬手將槍口指向了N。"
  },
  AvgDialog_95473_Content_63 = {
    Text = "我有個問題，你為什麼要自導自演這一齣。"
  },
  AvgDialog_95473_Content_64 = {
    Text = "我從你的行為上看不到任何邏輯，你到底想從我這裡拿到什麼？"
  },
  AvgDialog_95473_Content_65 = {
    Text = "您的問題很奇怪，凱蒂古拉女士。"
  },
  AvgDialog_95473_Content_66 = {
    Text = "為什麼我一定要……拿到什麼呢？"
  },
  AvgDialog_95473_Content_67 = {
    Text = "就不能是單純想看看，人類在這種情況下的表情麼？"
  },
  AvgDialog_95473_Content_68 = {
    Text = "哦當然，不要誤會，我只是舉個例子，其實我連這種想法都沒有。"
  },
  AvgDialog_95473_Content_69 = {
    Text = "……你是說，你單純覺得這樣做很有趣？"
