  AvgDialog_95474_Content_12 = {
    Text = "作為陪我玩這麼久的獎勵，我來告訴你一個好消息吧。"
  },
  AvgDialog_95474_Content_120 = {
    Text = "所有人都捂著腦袋，強忍著精神被撕碎般的痛苦。"
