  AvgDialog_95474_Content_13 = {
    Text = "還記得那些只能在陰溝裡逃竄的老鼠們嗎？"
  },
  AvgDialog_95474_Content_130 = {
    Text = "到時候……我們再把這新仇舊怨……好好地清算乾淨。"
  },
  AvgDialog_95474_Content_14 = {
    Text = "如果他們運氣不錯的話，現在應該已經逃出去了。"
  },
  AvgDialog_95474_Content_15 = {
    Text = "當然，這都歸功於我們的凱蒂古拉女士，不惜讓自身變得破破爛爛也要攔住我。"
  },
  AvgDialog_95474_Content_16 = {
    Text = "N低沉的腳步聲逐漸逼近，彷彿一塊巨石緩緩壓上心頭。"
  },
  AvgDialog_95474_Content_17 = {
    Text = "怎麼樣，開心嗎？現在有沒有「自己的努力沒有白費」的心情？"
  },
  AvgDialog_95474_Content_18 = {
    Text = "不過不要放鬆，凱蒂古拉女士，從現在開始，你要爆發出更強的意志，開始更努力地掙扎。"
