  AvgDialog_95474_Content_33 = {Text = "什麼？"},
  AvgDialog_95474_Content_35 = {
    Text = "N看著腹部出現的缺口，那是被大口徑子彈直擊的痕跡。其中露出的是真正的人體組織，而不是漆黑的氣體。"
  },
  AvgDialog_95474_Content_36 = {
    Text = "這進一步證實了你的猜想，此刻對方的身體只是一個稍強一些的人類。"
  },
  AvgDialog_95474_Content_37 = {
    Text = "沒想到你們居然回來了，這可真是……有趣。"
