  AvgDialog_95476_Content_70 = {
    Text = "我知道你想說什麼，把話收回去吧，傑拉德。"
  },
  AvgDialog_95476_Content_71 = {
    Text = "我明白這樣做的風險，但……我有必須這樣做的理由。"
