  AvgDialog_98108_Content_44 = {
    Text = "只是泰旖絲，不要再摸余的觸手了，你是在挑釁余嗎？"
  },
  AvgDialog_98108_Content_45 = {
    Text = "害羞了嗎？難得能碰到你，我當然要好好品味一下深海之主的觸感。"
